Set @ObsNf1 = ''
Set @mg_FlgInfCpl = 1
Set @mg_FlgobsCont = 0
Set @mg_FlginfAdFisco = 0
Set @mg_FlgobsFisco = 0

Delete From @TabObs

Set @ObsNf1 = 'RECUPERAÇÃO DE ICMS PAGO NA FONTE.'
if @PTipNot = 'S'
  begin
    if Exists(Select 1
                From FS_PARAM 
               Where Cod_Estabe = @PCodEstabe
                 And Cod_Param = 'NFE_CFG_DNF_ICMPGFN'
                 And Val_Param ='1') and
       Exists(Select 1
                From NFSCB cb
                     inner join ESTAB es on cb.Cod_Estabe = es.Cod_Estabe
               Where cb.Cod_Estabe = @PCodEstabe
                 And cb.Ser_Nota = @PSerNot
                 And cb.Num_Nota = @PNumNot
                 And cb.Estado = es.Des_Estado
                 And IsNull(cb.Vlr_SubsTrib,0) > 0)
      begin
        Select @ObsNf1 = 'RECUPERAÇÃO DE ICMS PAGO NA FONTE.'
--               dbo.FN_FormataValor(Vlr_SubsTrib, '.', ',')
          From NFSCB
         Where Cod_Estabe = @PCodEstabe
           And Ser_Nota = @PSerNot
           And Num_Nota = @PNumNot
           And IsNull(Vlr_SubsTrib,0) > 0
    
    if IsNull(@ObsNf1,'') <> '' 
      Set @PObserv = @ObsNf1

    if not Exists(Select 1 From @TabObs Where Tip_Not = @PTipNot And Des_Observ = @PObserv)
      Insert Into @TabObs (Tip_Not, Des_Observ, Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
             Values (@PTipNot, @PObserv, 1, 0, 0, 0)
      end 
  end  -- if @PTipNot = 'S'
else
  begin
    if Exists(Select 1
                From FS_PARAM 
               Where Cod_Estabe = @PCodEstabe
                 And Cod_Param = 'NFE_CFG_DNF_ICMPGFN'
                 And Val_Param ='1') and
       Exists(Select 1
                From NFECB cb
                     inner join ESTAB es on cb.Cod_Estabe = es.Cod_Estabe
               Where cb.Cod_Estabe = @PCodEstabe
                 And cb.Protocolo = @PNumNot
                 And cb.Cod_UFOrigem = es.Des_Estado
                 And IsNull(cb.Vlr_IstFon,0) > 0)
      begin
        Select @ObsNf1 = 'RECUPERAÇÃO DE ICMS PAGO NA FONTE.'
--               dbo.FN_FormataValor(Vlr_IstFon, '.', ',')
          From NFECB
         Where Cod_Estabe = @PCodEstabe
           And Protocolo = @PNumNot
           And IsNull(Vlr_IstFon,0) > 0
    if IsNull(@ObsNf1,'') <> '' 
      Set @PObserv = @ObsNf1

    if not Exists(Select 1 From @TabObs Where Tip_Not = @PTipNot And Des_Observ = @PObserv)
      Insert Into @TabObs (Tip_Not, Des_Observ, Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
             Values (@PTipNot, @PObserv, 1, 0, 0, 0)
      end   
  end  -- else if @PTipNot = 'S'
  

Set @ObsNf1 = 'ICMS PARA EFEITO DE CREDITO DO ADQUIRENTE.'
if @PTipNot = 'S'
  begin
    if Exists(Select 1
                From FS_PARAM 
               Where Cod_Estabe = @PCodEstabe
                 And Cod_Param = 'NFE_CFG_DNF_OBCRAD'
                 And Val_Param ='1') and
       Exists(Select 1
                From NFSCB
               Where Cod_Estabe = @PCodEstabe
                 And Ser_Nota = @PSerNot
                 And Num_Nota = @PNumNot
                 And IsNull(Vlr_IcmsTri,0) = 0
                 And IsNull(Vlr_SubsTrib,0) = 0
