CREATE VIEW [dbo].[V_NFSCB_Rent] AS

Select cb.Cod_Estabe, cb.Ser_Nota, cb.Num_Nota, cb.Dat_Emissao, cb.Status, cb.Tip_Saida, cb.Esp_Nota,
       cb.Cod_Vendedor, cb.Cod_VendTlmkt, cb.Cod_Cliente, cb.Estado,
     Nome_Cliente = cl.Razao_Social,
     Total_Itens = cb.VlrBruItens,
     Tip_Cfo = Case When cb.Cod_Cfo1 > 0 then 'FAT' else 'ORC' End,
       Per_FreTra = Case 
                      When IsNull(tx.Cod_Transp,0) > 0 then tx.Per_Frete 
                      When IsNull(tr.Per_Frete,0)  > 0 then tr.Per_Frete 
                      When IsNull(pm.Per_DesFre,0) > 0 then pm.Per_DesFre 
                      Else ISNull(pa.PerDesFre,0) 
                    End, 
       Per_Irpj = Case 
                    When (cb.Cod_Cfo1 > 0) and (IsNull(pm.Mes_Ref,0) > 0)  then IsNull(pm.Per_DesIrpj,0) 
                    When (cb.Cod_Cfo1 > 0) then IsNull(pa.PerDesIrpj,0) 
                    Else 0 
                  End, 

       Per_ConSoc = Case 
                    When (cb.Cod_Cfo1 > 0) and (IsNull(pm.Mes_Ref,0) > 0)  then IsNull(pm.Per_DesConSoc,0) 
                    When (cb.Cod_Cfo1 > 0) then IsNull(pa.PerDesConSoc,0) 
                      Else 0 
                    End,

       Per_DesOpe = Case 
                      When IsNull(pm.Mes_Ref,0) > 0  then IsNull(pm.Per_DesOpe,0) 
                      Else IsNull(pa.PerDesOpe,0) 
                    End, 

       Per_IrpjOpe = Case 
                       When IsNull(pm.Mes_Ref,0) > 0  then IsNull(pm.Per_DesIrpj,0) 
                       Else IsNull(pa.PerDesIrpj,0) 
                     End, 
       Per_ConSocOpe = Case 
                         When IsNull(pm.Mes_Ref,0) > 0  then IsNull(pm.Per_DesConSoc,0) 
                         Else IsNull(pa.PerDesConSoc,0) 
                       End, 
       Per_FreOpe = Case 
                      When IsNull(pm.Mes_Ref,0) > 0 then pm.Per_DesFre 
                      Else ISNull(pa.PerDesFre,0) 
                    End, 
       Per_PisOpe = Case 
                      When (IsNull(pm.Mes_Ref,0) > 0) and (es.Cod_TipLucro = 'LR') then pm.Per_DesPisLucRea 
                      When (IsNull(pm.Mes_Ref,0) > 0) and (es.Cod_TipLucro = 'LP') then pm.Per_DesPisLucPre 
                      When (IsNull(pm.Mes_Ref,0) = 0) and (es.Cod_TipLucro = 'LR') then pa.PerDesPisLucRea 
                      Else IsNull(pa.PerDesPisLucPre,0) 
                    End, 
       Per_CofOpe = Case 
                      When (IsNull(pm.Mes_Ref,0) > 0) and (es.Cod_TipLucro = 'LR') then pm.Per_DesCofLucRea 
                      When (IsNull(pm.Mes_Ref,0) > 0) and (es.Cod_TipLucro = 'LP') then pm.Per_DesCofLucPre 
                      When (IsNull(pm.Mes_Ref,0) = 0) and (es.Cod_TipLucro = 'LR') then pa.PerDesCofLucRea 
                      Else IsNull(pa.PerDesCofLucPre,0) 
                    End

  From NFSCB cb
       Inner Join ESTAB es on cb.Cod_Estabe = es.Cod_Estabe 
       inner Join PARAM pa on pa.Cod_Estabe = cb.Cod_Estabe 
       Left  Join PMMES pm on pm.Cod_Estabe = cb.Cod_Estabe and pm.Ano_Ref = Year(cb.Dat_Emissao) and pm.Mes_Ref = Month(cb.Dat_Emissao) 
       Left  Join CLIEN cl on cb.Cod_Cliente = cl.Codigo 
       Left  Join TRANS tr on cb.Cod_Transportadora = tr.Codigo 
       Left  Join TRXUF tx on cb.Cod_Transportadora = tx.Cod_Transp and tx.Cod_UF COLLATE DATABASE_DEFAULT = cl.Cod_Estado COLLATE DATABASE_DEFAULT and cb.cod_estabe = tx.Cod_Estabe 

GO

