GO

CREATE VIEW [dbo].[V_NFSIT_Rent] AS


Select it.Cod_Estabe, it.Ser_Nota, it.Num_Nota, 
       it.Cod_Produto, it.Id_PolCom, it.Per_ComTra, it.Vlr_CusIte,
     Valor_Unit = it.Prc_Unitario,
     Valor_Total =it.Vlr_TotItem,
     Unid = pr.Unidade_Venda,
     Peso_Liquido = it.Qtd_PesVolImpFat,
     Peso_Bruto = it.Qtd_PesVolImpFat,
     Descricao_Item_1 = pr.Descricao,
     Descricao_Item_2 = pr.Descri,
     Linha = cl1.Descricao,
       Sublinha = cl2.Descricao,
     QtdPrd = sum(it.Qtd_Produto+it.Qtd_Bonificacao),
     ValBru    = sum(IsNull(it.Vlr_BruItem,0)),
       ValDescon = Sum(IsNull(it.Vlr_BruItem,0) - IsNull(it.Vlr_TotItem,0) + IsNull(it.Vlr_DescRateado,0) + IsNull(it.Vlr_DscBonRat,0)),
     ValLiqVen = sum(IsNull(it.Vlr_LiqVenIte,0)),

       ValPis = sum(Case When cb.Tip_Cfo = 'FAT' then IsNull(it.Vlr_Pis,0) Else 0 End), 
       ValCof = sum(Case When cb.Tip_Cfo = 'FAT' then IsNull(it.Vlr_Cofins,0) Else 0 End), 
       ValIpi = sum(Case When cb.Tip_Cfo = 'FAT' then IsNull(it.Vlr_Ipi,0) Else 0 End), 
       ValIcm = sum(Case 
                      When (cb.Tip_Cfo = 'FAT') and (IsNull(pa.FlgBlqIcmTriCalRntPrdSbtFnt,0) = 1) and (IsNull(it.Vlr_SubsTrib,0) > 0) then 
                        Case 
                          When IsNull(pa.FlgBlqDifalCalRnt,0) = 1 then 0 
                          Else 0 + IsNull(it.Vlr_IcmParDes,0) 
                        End 
                      When (cb.Tip_Cfo = 'FAT') and (IsNull(it.Flg_UsaDebPresum,0) = 0) then 
                        Case 
                          When IsNull(pa.FlgBlqDifalCalRnt,0) = 1 then IsNull(it.Vlr_IcmsTri,0) 
                          Else IsNull(it.Vlr_IcmsTri,0) + IsNull(it.Vlr_IcmParDes,0) 
                        End 
                      When (cb.Tip_Cfo = 'FAT') and (IsNull(it.Flg_UsaDebPresum,0) = 1) then 
                        Case 
                          When IsNull(pa.FlgBlqDifalCalRnt,0) = 1 then 
                               (IsNull(it.Vlr_BasTri,0)*IsNull(it.Alq_IcmPresum,0)/100) 
                          Else (IsNull(it.Vlr_BasTri,0)*IsNull(it.Alq_IcmPresum,0)/100) + IsNull(it.Vlr_IcmParDes,0) 
                        End 
                      Else 0 
                    End), 
     ValSbt    = sum(IsNull(it.Vlr_SubsTrib,0)), 
     ValRes    = sum(IsNull(it.Vlr_SbtRes,0)), 
     ValIcmPar = sum(IsNull(it.Vlr_IcmParDes,0)),
     ValIcmTri = sum(IsNull(it.Vlr_IcmsTri,0)), 
       ValComiss = sum(IsNull(it.Vlr_Comissao,0)+IsNull(it.Vlr_ComTlmkt,0)+IsNull(it.Vlr_ComSup,0)+IsNull(it.Vlr_ComGer,0)+IsNull(it.Vlr_ComSupOpe,0)+IsNull(it.Vlr_ComGerOpe,0)),

       ValVrbPar = sum(IsNull(it.Vlr_VrbPar,0)), 
     ValVrbBon = sum(IsNull(it.Vlr_VrbBon,0)), 

     ValDspRat = sum(IsNull(it.Vlr_DespRateada,0)), 
     ValDspExt = sum(IsNull(it.Vlr_DspExt,0)),

     -- cb.Per_Irpj/cb.Per_ConSoc: conforme Cod_Cfo1 em V_NFSCB
       ValIrpj   = Round(sum((IsNull(it.Vlr_LiqVenIte,0)+IsNull(it.Vlr_SbtRes,0)+IsNull(it.Vlr_DespRateada,0)+IsNull(it.Vlr_DspExt,0)) * cb.Per_Irpj/100),4),
       ValConSoc = Round(sum((IsNull(it.Vlr_LiqVenIte,0)+IsNull(it.Vlr_SbtRes,0)+IsNull(it.Vlr_DespRateada,0)+IsNull(it.Vlr_DspExt,0)) * cb.Per_ConSoc/100),4),
       ValDspOpe = Round(sum(IsNull(it.Vlr_LiqVenIte,0) * cb.Per_DesOpe/100),4),
       ValFrete  = Round(sum( IsNull(it.Vlr_LiqVenIte,0) * (Case 
                                                        When IsNull(it.Per_ComTra,0) > 0 then it.Per_ComTra 
                                                        Else cb.Per_FreTra 
                                                      End/100) ),4),

       ValVenDsc = Round(sum(it.Vlr_LiqVenIte*(1-IsNull(it.Per_DescontoFin,0)/100)),4), 
       ValVenTab = sum((it.Qtd_Produto+it.Qtd_Bonificacao)*it.Prc_Tabela) 

  From dbo.NFSIT it
       inner join dbo.V_NFSCB_Rent cb on it.Cod_Estabe = cb.Cod_Estabe and it.Ser_Nota = cb.Ser_Nota and it.Num_Nota = cb.Num_Nota
       inner Join dbo.PARAM pa on pa.Cod_Estabe = cb.Cod_Estabe 
     inner Join dbo.PRODU pr on it.Cod_Produto = pr.Codigo
     Left Join CLASS cl1 ON cl1.Codigo = SUBSTRING(pr.Cod_Classif, 1, 2)
       Left Join CLASS cl2 ON cl2.Codigo = SUBSTRING(pr.Cod_Classif, 1, 4)

 Group by it.Cod_Estabe, it.Ser_Nota, it.Num_Nota, 
          it.Cod_Produto, it.Id_PolCom, it.Per_ComTra, it.Vlr_CusIte, 
      it.Prc_Unitario,
      it.Vlr_TotItem,       
        it.Des_UnvImpFat,
        it.Qtd_PesVolImpFat,
        it.Qtd_PesVolImpFat,
        pr.Descricao,
        pr.Descri,
      pr.Cod_Classif,
      pr.Unidade_Venda,
      cl1.Descricao, 
      cl2.Descricao

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[FN_SaldoCreditoCliente]
(
@PCodEstabe int,
@PCodCli int
)
RETURNS numeric(18,4)

AS

BEGIN

Declare @PVlrSld numeric(18,4),
        @CodCliPag int,
    @SldLimCre numeric(18,4),
    @VlrTotPen  numeric(18,4)

Set @PVlrSld = 0
 
Set @CodCliPag = (Select Cod_CliPag From CLIEN Where Codigo = @PCodCli)

Set @SldLimCre = 0
Select @SldLimCre = IsNull(Round(Sum(IsNull(cl.Limite_Credito,0)-IsNull(cl.Total_Debito,0)),2),0)
From CLIEN cl 
Where cl.Cod_CliPag = @CodCliPag

Set @VlrTotPen = 0
Select @VlrTotPen = IsNull(Sum(dbo.FN_ValPdv(cb.Cod_Estabe,cb.Numero)),0)
From PDVCB cb 
     Inner Join CLIEN cl on cb.Cod_Cliente = cl.Codigo 
/*Where cb.Cod_Estabe = @PCodEstabe DMD-8030 */ 
Where cb.Status1 = 'P'
And cb.Status2 = 'F'
And cb.Tip_Pedido <> 'C'
And cb.Cod_Cliente = cl.Codigo 
And cl.Cod_CliPag = @CodCliPag

Set @PVlrSld = IsNull(@SldLimCre,0) - IsNull(@VlrTotPen,0)
        
-- Retorna o resultado da function
RETURN @PVlrSld

END
GO


SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[PR_IncluiHSPRC]
@PCodEstabe int,
@PCodProdut int,
@PDatAlt smalldatetime,
@PNumSeqAlt int output    -- se = 0 : cria novo pedido

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd

Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now  = GetDate()
Set @Date = cast(GetDate() as date)

Begin Transaction

Declare @PNumSeqAnt int

Set @PNumSeqAlt = 0
Set @PNumSeqAnt = 0

if not Exists(Select 1 From HSPRC Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodProdut and Dat_Alteracao = @PDatAlt)
  begin

    Insert Into HSPRC (Cod_Estabe, Cod_Produto, Dat_Alteracao, Usuario, Transacao)
      Values (@PCodEstabe, @PCodProdut, @PDatAlt, Substring(dbo.FN_UsuarioInfarma(),1,15), @Now)

    Set @PNumSeqAlt = (Select max(Seq_Alteracao) From HSPRC 
                       Where Cod_Estabe = @PCodEstabe And Cod_Produto = @PCodProdut and Dat_Alteracao = @PDatAlt)

    Set @PNumSeqAnt = (Select top 1 Seq_ALteracao From HSPRC 
                       Where Cod_Estabe = @PCodEstabe And Cod_Produto = @PCodProdut 
                       /*And ( (Dat_Alteracao = @Date) and (Seq_Alteracao < @PNumSeqAlt) or (Dat_Alteracao < @Date) ) */
					   And ( (Dat_Alteracao = @Date) and (Seq_Alteracao < @PNumSeqAlt) or (Dat_Alteracao < @PDatAlt) ) /* DMD7878 */
                       Order by Cod_Estabe, Cod_Produto, Dat_Alteracao desc, Seq_ALteracao desc)

    Update h1
      Set h1.Vlr_PrcVen = IsNull(h2.Vlr_PrcVen,0),
          h1.Vlr_PrcFab = IsNull(h2.Vlr_PrcFab,0),
          h1.Vlr_PrcMaxCon = IsNull(h2.Vlr_PrcMaxCon,0),
          h1.Vlr_RefFpb = IsNull(h2.Vlr_RefFpb,0),
          h1.Vlr_CusLiqPra = IsNull(h2.Vlr_CusLiqPra,0),
          h1.Vlr_CusLiqDep = IsNull(h2.Vlr_CusLiqDep,0),
          h1.Vlr_CusMed = IsNull(h2.Vlr_CusMed,0),
          h1.Vlr_CusMedPra = IsNull(h2.Vlr_CusMedPra,0),
          h1.Vlr_CusMedDep = IsNull(h2.Vlr_CusMedDep,0),
          h1.Vlr_CusMedCom = IsNull(h2.Vlr_CusMedCom,0),
          h1.Vlr_PrcUltEntLiq = IsNull(h2.Vlr_PrcUltEntLiq,0),
          h1.Vlr_PrcUltEntLiqIpi = IsNull(h2.Vlr_PrcUltEntLiqIpi,0),
          h1.Vlr_BasCalSubTriEntMed = IsNull(h2.Vlr_BasCalSubTriEntMed,0),
          h1.Vlr_PrcFab12 = IsNull(h2.Vlr_PrcFab12,0),
          h1.Vlr_PrcFab17 = IsNull(h2.Vlr_PrcFab17,0),
          h1.Vlr_PrcFab175 = IsNull(h2.Vlr_PrcFab175,0),
          h1.Vlr_PrcFab18 = IsNull(h2.Vlr_PrcFab18,0),
          h1.Vlr_PrcFab19 = IsNull(h2.Vlr_PrcFab19,0),
          h1.Vlr_PrcFab20 = IsNull(h2.Vlr_PrcFab20,0),
          h1.Vlr_PrcMaxCon12 = IsNull(h2.Vlr_PrcMaxCon12,0),
          h1.Vlr_PrcMaxCon17 = IsNull(h2.Vlr_PrcMaxCon17,0),
          h1.Vlr_PrcMaxCon175 = IsNull(h2.Vlr_PrcMaxCon175,0),
          h1.Vlr_PrcMaxCon18 = IsNull(h2.Vlr_PrcMaxCon18,0),
          h1.Vlr_PrcMaxCon19 = IsNull(h2.Vlr_PrcMaxCon19,0),
          h1.Vlr_PrcMaxCon20 = IsNull(h2.Vlr_PrcMaxCon20,0)

    From HSPRC h1
         Inner Join HSPRC h2 on (h2.Cod_Estabe = h1.Cod_Estabe And h2.Cod_Produto = h1.Cod_Produto And h2.Seq_Alteracao = @PNumSeqAnt)
    Where h1.Cod_Estabe  = @PCodEstabe
    And h1.Cod_Produto   = @PCodProdut
    And h1.Dat_Alteracao = @PDatAlt
    And h1.Seq_Alteracao = @PNumSeqAlt

   end
else
  Set @PNumSeqAlt = (Select max(Seq_Alteracao) From HSPRC 
                     Where Cod_Estabe = @PCodEstabe And Cod_Produto = @PCodProdut and Dat_Alteracao = @PDatAlt)

Commit Transaction
GO





SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-----------------------------------------------------------------------------------------------------------
----  Rotina para reprocessar custos custos em (PRXES, HSPRC, NFEIT, NFSIT)  de                        ----
----  NF Entradas a partir da data base definida                                                       ----
----  PRXES: Prc_CusLiqEnt, Prc_CusLiqEntDep, Prc_CusMed, Prc_CusMedCom, Prc_CusMedPra, Prc_CusMedDep  ----
----  HSPRC: Vlr_CusLiqPra, Vlr_CusLiqDep,    Vlr_CusMed, Vlr_CusMedCom, Vlr_CusMedPra, Vlr_CusMedDep  ----
----  NFEIT: Prc_CusMedAnt, Prc_CustoMedio                                                             ----  
----  NFSIT: Vlr_CusIte                                                                                ----
-----------------------------------------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[PR_ReprocessaCustosEntrada]
@PCodEstabe int,
@PMesMov smallint,        -- mes inicial
@PAnoMov smallint,        -- ano inicial
@PCodPrd int,             -- 0 = todos os produtos
@PFlgBlqAltUltPrcCMC Bit  -- 1 = Bloqueia alteração do ultimo custo comercial do produto

AS

SET NOCOUNT ON

SET DATEFORMAT ymd

BEGIN

  Declare @DatRef smalldatetime,  -- data inicial
          @DatBas smalldatetime,
          @CodPrdIni int,
          @CodPrdFin int,
          @CodPrd int,
          @NumSeq int,
          @DatMov smalldatetime,
          @DatMovAnt smalldatetime,
          @DatUltEnt smalldatetime,
          @DatUltEntPra smalldatetime,
          @DatUltEntDep smalldatetime,
          @QtdSldPraAnt int,
          @QtdSldDepAnt int,
          @QtdSldDiaAnt int,
          @NumPrt int, 
          @PrcVenPrd numeric (18,4),
          @VlrPrcVenHis numeric (18,4),
          @QtdEnt int,
          @VlrBasCalSubTriUni numeric(18,4),
          @CusLiqPraAnt numeric (18,4), 
          @CusLiqDepAnt numeric (18,4), 
          @CusMedGerAnt numeric (18,4),
          @CusMedComAnt numeric (18,4),
          @CusMedPraAnt numeric (18,4),
          @CusMedDepAnt numeric (18,4),
          @VlrBasCalSubTriEntMedAnt numeric(18,4),
          @CusLiqPraNew numeric (18,4), 
          @CusLiqDepNew numeric (18,4), 
          @CusMedGerNew numeric (18,4),
          @CusMedComNew numeric (18,4),
          @CusMedPraNew numeric (18,4),
          @CusMedDepNew numeric (18,4),
          @VlrBasCalSubTriEntMedNew numeric(18,4),
          @CodCfoCab int, 
          @CodCfoIte int, 
          @CusLiqUni numeric (18,4),
          @CusLiqComUni numeric (18,4),
          @PrcUniMed numeric (18,4),
          @DscUniMed numeric (8,4)

  -- CFOp bonificacao
  Declare @KCfoBonEntInt int = 1910,
          @KCfoBonEntExt int = 2910		         

  Set @DatRef = Cast(Cast(@PAnoMov as varchar)+'-'+Cast(@PMesMov as varchar)+'-01 00:00:00' as smalldatetime)

  BEGIN TRY
    BEGIN TRANSACTION

    -- desabilita triggers de PRODU que atualiza historico de precos
    ALTER TABLE PRODU DISABLE TRIGGER ALL
    ALTER TABLE PRXES DISABLE TRIGGER ALL

    -----------------------------------------------------------------------
    -- seleciona itens de nota de entrada a partir da data de movimento  --
    -----------------------------------------------------------------------
    Set @CodPrdIni = 0
    Set @CodPrdFin = 999999999
	if @PCodPrd > 0
      begin
        Set @CodPrdIni = @PCodPrd
        Set @CodPrdFin = @PCodPrd
      end


    Declare HSPRC_Cr Cursor Local For 
    
      Select distinct it.Cod_Produto, pr.Dat_UltCompra, pr.Dat_UltEntDep, pr.Prc_Venda
        From NFECB cb 
             Inner Join NFEIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Protocolo = it.Protocolo
             Inner Join PRXES pr on it.Cod_Estabe = pr.Cod_Estabe and it.Cod_Produto = pr.Cod_Produt
       Where cb.Cod_Estabe = @PCodEstabe
         and cb.Status = 'F'
         and cb.Flg_MovEst = 1 
         and cb.Flg_AtuPrcCus = 1 
         and IsNull(cb.Dat_Movimento,0) > 0
         and cb.Dat_Movimento >= @DatRef
         and it.Cod_Produto between @CodPrdIni and @CodPrdFin
       Order by it.Cod_Produto
    
    Open HSPRC_Cr
    Fetch Next From HSPRC_Cr Into @CodPrd, @DatUltEntPra, @DatUltEntDep, @PrcVenPrd
    While @@FETCH_STATUS = 0
      begin
        Set @DatMov = null

        -- Normaliza registros em NFEIT
        Update it
           Set it.Dat_Movimento = cb.Dat_Movimento
          From NFECB cb 
               Inner Join NFEIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Protocolo = it.Protocolo
         Where cb.Cod_Estabe = @PCodEstabe     
           and cb.Status = 'F'
           and cb.Flg_MovEst = 1 
           and cb.Flg_AtuPrcCus = 1 
           and cb.Dat_Movimento >= @DatRef
           and it.Cod_Produto = @CodPrd
           and IsNull(it.Dat_Movimento,0) <> cb.Dat_Movimento

        -- ultima entrada do produto
        Select top 1 @DatMov = it.Dat_Movimento,
                     @CodCfoCab = cb.Cod_Cfo
          From NFECB cb 
               Inner Join NFEIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Protocolo = it.Protocolo
         Where cb.Cod_Estabe = @PCodEstabe     
           and cb.Status = 'F'
           and cb.Flg_MovEst = 1 
           and cb.Flg_AtuPrcCus = 1 
           and it.Cod_Produto = @CodPrd
         Order by cb.Dat_Movimento desc

        -- normaliza registros em NFEIT        
        if @DatMov is not null
          begin
            if @CodCfoCab > 0 
              Set @DatUltEnt = @DatUltEntPra 
            else
              Set @DatUltEnt = @DatUltEntDep
    
            -- verifica data minima inicial processamento
            if @DatMov > @DatRef
              begin
                Select top 1 @DatMov = it.Dat_Movimento
                  From NFECB cb 
                       Inner Join NFEIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Protocolo = it.Protocolo
                 Where cb.Cod_Estabe = @PCodEstabe     
                   and cb.Status = 'F'
                   and cb.Flg_MovEst = 1 
                   and cb.Flg_AtuPrcCus = 1 
                   and cb.Dat_Movimento >= @DatRef
                   and it.Cod_Produto = @CodPrd
                 Order by it.Dat_Movimento
              end
              
            Set @DatBas = @DatMov   

            -- seleciona itens de nota de entrada a partir da data base ordenadaos pela data
            Declare TABLE_Cr Cursor Local For 
           
              Select cb.Cod_Cfo, it.Dat_Movimento, it.Protocolo, it.Cod_Cfo,
                     sum(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0)),
                     sum(it.Cus_LiqUni*it.Qtd_Pedido)/sum(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0)),
                     case 
                       When IsNull(it.Vlr_DscIte2,0) > 0 then sum(it.Cus_LiqUni*it.Qtd_Pedido+it.Vlr_DscIte2)/sum(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0))
                       Else sum(it.Cus_LiqUni*it.Qtd_Pedido)/sum(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0))
                     end,
                     sum(it.Prc_Unitario*(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0)))/sum(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0)),
                     sum(it.Per_DescItem*it.Prc_Unitario*(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0)))/sum(it.Prc_Unitario*(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0))),
                     case
                       When ((cb.Tip_NF = 'C') or (cb.Tip_NF = 'T') or (cb.Cod_Cfo = @KCfoBonEntExt) or (cb.Cod_Cfo = @KCfoBonEntInt)) 
                         then sum(it.Vlr_BasSubsTrib)/sum(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0))
                       Else 0
                     end
                From NFEIT it 
                     Inner Join NFECB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Protocolo = cb.Protocolo
               Where cb.Cod_Estabe = @PCodEstabe     
                 and cb.Status = 'F'
                 and cb.Flg_MovEst = 1 
                 and cb.Flg_AtuPrcCus = 1 
                 and cb.Dat_Movimento >= @DatBas
                 and it.Cod_Produto = @CodPrd
               Group by cb.Cod_Cfo, it.Dat_Movimento, it.Protocolo, it.Cod_Cfo, cb.Tip_NF, it.Vlr_DscIte2
               Order by it.Dat_Movimento, it.Protocolo
           
            Open TABLE_Cr
            Fetch Next From TABLE_Cr Into @CodCfoCab, @DatMov, @NumPrt, @CodCfoIte, 
                                          @QtdEnt, @CusLiqUni, @CusLiqComUni, @PrcUniMed, @DscUniMed, @VlrBasCalSubTriUni
            While @@FETCH_STATUS = 0
              begin
           
                Set @DatMovAnt = @DatMov

                -- saldos anteriores mais proximos à data da entrada
                Set @QtdSldPraAnt = 0 
                Set @QtdSldDepAnt = 0
                Set @QtdSldDiaAnt = 0

                if Exists(Select 1 
                            From PRSLD
                           Where Cod_Estabe = @PCodEstabe 
                             And Cod_Produt = @CodPrd
                             And Dat_Movime < @DatMov)
                  Select Top 1 @QtdSldPraAnt = IsNull(Qtd_SldPra,0), 
                               @QtdSldDepAnt = IsNull(Qtd_SldDep,0), 
                               @QtdSldDiaAnt = IsNull(Qtd_SldAtu,0)
                    From PRSLD
                   Where Cod_Estabe = @PCodEstabe 
                     And Cod_Produt = @CodPrd
                     And Dat_Movime < @DatMov
                   Order by Dat_Movime desc
           
                if @QtdSldPraAnt < 0 Set @QtdSldPraAnt = 0
                if @QtdSldDepAnt < 0 Set @QtdSldDepAnt = 0
                if @QtdSldDiaAnt < 0 Set @QtdSldDiaAnt = 0

                -- inclui HSPRC
                if not Exists(Select 1 From HSPRC Where Cod_Estabe = @PCodEstabe and Cod_Produto = @CodPrd and Dat_Alteracao = @DatMov)
                  Exec PR_IncluiHSPRC @PCodEstabe, @CodPrd, @DatMov, @NumSeq output   

                -- custos medios imediatamente anteriores a data do movimennto
                Set @CusLiqPraAnt = 0
                Set @CusLiqDepAnt = 0
                Set @CusMedGerAnt = 0
                Set @CusMedComAnt = 0
                Set @CusMedPraAnt = 0
                Set @CusMedDepAnt = 0
                Set @VlrBasCalSubTriEntMedAnt = 0

                if Exists(Select 1
                            From HSPRC
                           Where Cod_Estabe = @PCodEstabe     
                             And Cod_Produto = @CodPrd
                             And Dat_Alteracao < @DatMov)
                  Select Top 1 @CusLiqPraAnt = IsNull(Vlr_CusLiqPra,0), 
                               @CusLiqDepAnt = IsNull(Vlr_CusLiqDep,0), 
                               @CusMedGerAnt = IsNull(Vlr_CusMed,0),
                               @CusMedComAnt = IsNull(Vlr_CusMedCom,0),
                               @CusMedPraAnt = IsNull(Vlr_CusMedPra,0), 
                               @CusMedDepAnt = IsNull(Vlr_CusMedDep,0),
                               @VlrBasCalSubTriEntMedAnt = IsNull(Vlr_BasCalSubTriEntMed,0)
                    From HSPRC
                   Where Cod_Estabe = @PCodEstabe     
                     And Cod_Produto = @CodPrd
                     And Dat_Alteracao < @DatMov
                   Order by Dat_Alteracao desc, Seq_Alteracao desc
           
                if @CusLiqPraAnt < 0 Set @CusLiqPraAnt = 0
                if @CusLiqDepAnt < 0 Set @CusLiqDepAnt = 0
                if @CusMedGerAnt < 0 Set @CusMedGerAnt = 0
                if @CusMedComAnt < 0 Set @CusMedComAnt = 0
                if @CusMedPraAnt < 0 Set @CusMedPraAnt = 0
                if @CusMedDepAnt < 0 Set @CusMedDepAnt = 0
                if @VlrBasCalSubTriEntMedAnt < 0 Set @VlrBasCalSubTriEntMedAnt = 0
           
                While (@DatMovAnt = @DatMov) and (@@FETCH_STATUS = 0)
                  begin
                    if @CodCfoCab > 0
                      Update pr
                         Set pr.Prc_CusLiqEnt = @CusLiqUni,
                             pr.Prc_EntAnt    = pr.Prc_UltEnt,
                             pr.Per_DscEntAnt = pr.Per_DscUltEnt,
                             pr.Qtd_EntAnt    = pr.Qtd_UltEnt,
                             pr.Dat_EntAnt    = pr.Dat_UltCompra,
                             pr.Prc_UltEnt    = @PrcUniMed,
                             pr.Per_DscUltEnt = @DscUniMed,
                             pr.Qtd_UltEnt    = @QtdEnt,
                             pr.Dat_UltCompra = @DatMov
                        From PRXES pr
                       Where pr.Cod_Estabe = @PCodEstabe And pr.Cod_Produt = @CodPrd
                    else
                      Update pr
                         Set pr.Prc_CusLiqEntDep = @CusLiqUni,
                             pr.Prc_EntAntDep    = pr.Prc_UltEntDep,
                             pr.Per_DscEntAntDep = pr.Per_DscUltEntDep,
                             pr.Qtd_EntAntDep    = pr.Qtd_UltEntDep,
                             pr.Dat_EntAntDep    = pr.Dat_UltEntDep,
                             pr.Prc_UltEntDep    = @PrcUniMed,
                             pr.Per_DscUltEntDep = @DscUniMed,
                             pr.Qtd_UltEntDep    = @QtdEnt,
                             pr.Dat_UltEntDep    = @DatMov
                        From PRXES pr
                       Where pr.Cod_Estabe = @PCodEstabe And pr.Cod_Produt = @CodPrd

                    -- atualiza registro de entrada
                    Update NFEIT
                       Set Qtd_FisAnt = @QtdSldDiaAnt,
--                           Vlr_BasCalSubTriEntMedAnt = @VlrBasCalSubTriEntMedAnt,
                           Prc_CusMedAnt = @CusMedGerAnt
                     Where Cod_Estabe = @PCodEstabe
                       And Protocolo = @NumPrt
                       And Cod_Produto = @CodPrd
                       And ((Qtd_FisAnt <> @QtdSldDiaAnt) or (Prc_CusMedAnt <> @CusMedGerAnt))
                
                    Update HSPRC
                       Set Vlr_CusLiqPra = @CusLiqPraAnt,
                           Vlr_CusLiqDep = @CusLiqDepAnt,
                           Vlr_CusMed    = @CusMedGerAnt,
                           Vlr_CusMedCom = Case 
                                             When @PFlgBlqAltUltPrcCMC = 0 then @CusMedComAnt 
                                             Else Vlr_CusMedCom 
                                           End,
                           Vlr_CusMedPra = @CusMedPraAnt,
                           Vlr_CusMedDep = @CusMedDepAnt
--                           Vlr_BasCalSubTriEntMed = @VlrBasCalSubTriEntMedAnt
                     Where Cod_Estabe = @PCodEstabe
                       and Cod_Produto = @CodPrd 
                       and Dat_Alteracao >= @DatMov
                       And ((Vlr_CusMed <> @CusMedGerAnt) or (Vlr_CusMedCom <> @CusMedComAnt) or 
                            (Vlr_CusMedPra <> @CusMedPraAnt) or (Vlr_CusMedDep <> @CusMedDepAnt))

                
                     -- zera saldo se o custo anterior estiver zerado
                    if @CusMedGerAnt = 0
                      Set @QtdSldDiaAnt = 0
                    if @CusMedPraAnt = 0
                      Set @QtdSldPraAnt = 0
                    if @CusMedDepAnt = 0
                      Set @QtdSldDepAnt = 0
                
                    -- custos a calcular
                    Set @CusLiqPraNew = 0
                    Set @CusLiqDepNew = 0
                    Set @CusMedGerNew = 0
                    Set @CusMedComNew = 0
                    Set @CusMedPraNew = 0
                    Set @CusMedDepNew = 0
                
/*               
                    Set @VlrBasCalSubTriEntMedNew = 0

                   -- base de calculo media ST
                    if @VlrBasCalSubTriUni > 0
                      begin
                        Set @VlrBasCalSubTriEntMedNew = (@VlrBasCalSubTriEntMedAnt*@QtdSldDiaAnt + @VlrBasCalSubTriUni*@QtdEnt)/(@QtdSldDiaAnt+@QtdEnt)

                        Update PRXES
                          Set Vlr_BasCalSubTriEntMed = @VlrBasCalSubTriEntMedNew
                        Where Cod_Estabe = @PCodEstabe
                        And Cod_Produt = @CodPrd
                        And @VlrBasCalSubTriEntMedNew > 0
                        And Vlr_BasCalSubTriEntMed <> @VlrBasCalSubTriEntMedNew

                        Update HSPRC
                          Set Vlr_BasCalSubTriEntMed = @VlrBasCalSubTriEntMedNew
                        Where Cod_Estabe = @PCodEstabe
                        And Cod_Produto = @CodPrd 
                        And Dat_Alteracao >= @DatMov
                        And @VlrBasCalSubTriEntMedNew > 0
                        And Vlr_BasCalSubTriEntMed <> @VlrBasCalSubTriEntMedNew
                      end 
*/

                    -- custo medio gerencial
                    -- verifica tipo de bonificacao
                    if ((@CodCfoCab <> @KCfoBonEntInt) and (@CodCfoCab <> @KCfoBonEntExt)) and  -- nao eh nf de bonificacao
                       ((@CodCfoIte = @KCfoBonEntInt) or (@CodCfoIte = @KCfoBonEntExt)) 
                      begin
                        Set @CusMedGerNew = (@CusMedGerAnt*@QtdSldDiaAnt)/(@QtdSldDiaAnt+@QtdEnt)
                        Set @CusMedComNew = (@CusMedComAnt*@QtdSldDiaAnt)/(@QtdSldDiaAnt+@QtdEnt)
                      end
                    else
                      begin
                        Set @CusMedGerNew = (@CusMedGerAnt*@QtdSldDiaAnt+@CusLiqUni*@QtdEnt)/(@QtdSldDiaAnt+@QtdEnt)
                        Set @CusMedComNew = (@CusMedComAnt*@QtdSldDiaAnt+@CusLiqComUni*@QtdEnt)/(@QtdSldDiaAnt+@QtdEnt)
                      end

                    Update PRXES
                       Set Prc_CusMed = @CusMedGerNew
                     Where Cod_Estabe = @PCodEstabe
                       And Cod_Produt = @CodPrd
                       And @CusMedGerNew > 0
                       And Prc_CusMed <> @CusMedGerNew
                
                    
		            if @PFlgBlqAltUltPrcCMC = 0
                      Update PRXES
                         Set Prc_CusMedCom = @CusMedComNew
                       Where Cod_Estabe = @PCodEstabe
                         And Cod_Produt = @CodPrd
                         And @CusMedComNew > 0
                         And Prc_CusMedCom <> @CusMedComNew

                    Update it
                       Set it.Vlr_CusIte = @CusMedGerNew
                      From NFSIT it 
                           Inner Join NFSCB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Ser_Nota = cb.Ser_Nota and it.Num_Nota = cb.Num_Nota
                     Where it.Cod_Estabe = @PCodEstabe
                       And it.Cod_Produto = @CodPrd
                       And cb.Dat_Emissao >= @DatMov
                       And it.Vlr_CusIte <> @CusMedGerNew
                
                    Update HSPRC
                       Set Vlr_CusMed = @CusMedGerNew
                     Where Cod_Estabe = @PCodEstabe
                       And Cod_Produto = @CodPrd 
                       And Dat_Alteracao >= @DatMov
                       And @CusMedGerNew > 0
                       And Vlr_CusMed <> @CusMedGerNew

		            if @PFlgBlqAltUltPrcCMC = 0
                      Update HSPRC
                         Set Vlr_CusMedCom = @CusMedComNew 
                       Where Cod_Estabe = @PCodEstabe
                         And Cod_Produto = @CodPrd 
                         And Dat_Alteracao >= @DatMov
                         And @CusMedComNew > 0
                         And Vlr_CusMedCom <> @CusMedComNew
                
                    -- custo medio 1
                    if @CodCfoCab > 0
                      begin
                        Update PRXES
                           Set Prc_CusLiqEnt = @CusLiqUni,
                               Dat_UltCompra = @DatMov,
                               Qtd_UltEnt = @QtdEnt
                         Where Cod_Estabe = @PCodEstabe
                           And Cod_Produt = @CodPrd
                
                        -- verifica tipo de bonificacao
                        if ((@CodCfoCab <> @KCfoBonEntInt) and (@CodCfoCab <> @KCfoBonEntExt)) and  -- nao eh nf de bonificacao
                           ((@CodCfoIte = @KCfoBonEntInt) or (@CodCfoIte = @KCfoBonEntExt)) 
                          begin
                            Set @CusLiqPraNew = (@CusLiqPraAnt*@QtdSldPraAnt)/(@QtdSldPraAnt+@QtdEnt)
                            Set @CusMedPraNew = (@CusMedPraAnt*@QtdSldPraAnt)/(@QtdSldPraAnt+@QtdEnt)
                          end
                        else
                          begin
                            Set @CusLiqPraNew = (@CusLiqPraAnt*@QtdSldPraAnt+@CusLiqUni*@QtdEnt)/(@QtdSldPraAnt+@QtdEnt)
                            Set @CusMedPraNew = (@CusMedPraAnt*@QtdSldPraAnt+@CusLiqUni*@QtdEnt)/(@QtdSldPraAnt+@QtdEnt)
                          end
                
                        Update PRXES
                           Set Prc_CusMedPra = @CusMedPraNew
                         Where Cod_Estabe = @PCodEstabe
                           And Cod_Produt = @CodPrd
                           And @CusMedPraNew > 0
                           And Prc_CusMedPra <> @CusMedPraNew
                
                        Update HSPRC
                           Set Vlr_CusMedPra = @CusMedPraNew,
                               Vlr_CusLiqPra = @CusLiqUni
                         Where Cod_Estabe = @PCodEstabe
                           And Cod_Produto = @CodPrd 
                           And Dat_Alteracao >= @DatMov
                           And @CusMedPraNew > 0
                           And ((Vlr_CusMedPra <> @CusMedPraNew) or (Vlr_CusLiqPra <> @CusLiqUni))
                      end

                    else              
                    -- custo medio 2
                      begin
                        Update PRXES
                           Set Prc_CusLiqEntDep = @CusLiqUni,
                               Dat_UltEntDep = @DatMov,
                               Qtd_UltEntDep = @QtdEnt
                         Where Cod_Estabe = @PCodEstabe
                           And Cod_Produt = @CodPrd
                        
                        Set @CusLiqDepNew = (@CusLiqDepAnt*@QtdSldDepAnt+@CusLiqUni*@QtdEnt)/(@QtdSldDepAnt+@QtdEnt)
                        Set @CusMedDepNew = (@CusMedDepAnt*@QtdSldDepAnt+@CusLiqUni*@QtdEnt)/(@QtdSldDepAnt+@QtdEnt)

                        Update PRXES
                           Set Prc_CusMedDep = @CusMedDepNew
                         Where Cod_Estabe = @PCodEstabe
                           And Cod_Produt = @CodPrd
                           And @CusMedDepNew > 0
                           And Prc_CusMedDep <> @CusMedDepNew
          
                        Update HSPRC
                           Set Vlr_CusMedDep = @CusMedDepNew,
                               Vlr_CusLiqDep = @CusLiqUni
                         Where Cod_Estabe = @PCodEstabe
                           And Cod_Produto = @CodPrd 
                           And Dat_Alteracao >= @DatMov
                           And @CusMedDepNew > 0
                           And ((Vlr_CusMedDep <> @CusMedDepNew) or (Vlr_CusLiqDep <> @CusLiqUni))
                      end

                    -- atualiza itens da nota   
                    Update it
                       Set it.Prc_CustoMedio = pr.Prc_CusMed
                      From NFEIT it 
                           Inner Join PRXES pr on it.Cod_Estabe = pr.Cod_Estabe and it.Cod_Produto = pr.Cod_Produt
                     Where it.Cod_Estabe = @PCodEstabe 
                       and it.Protocolo = @NumPrt
                       And it.Cod_Produto = @CodPrd

                    -- acumula p/ proxima entrada do dia
                    Set @QtdSldDiaAnt = @QtdSldDiaAnt + @QtdEnt 
                    if @CodCfoCab > 0
                      Set @QtdSldPraAnt = @QtdSldPraAnt + @QtdEnt
                    else
                      Set @QtdSldDepAnt = @QtdSldDepAnt + @QtdEnt   

                    Set @CusLiqPraAnt = @CusLiqPraNew
                    Set @CusLiqDepAnt = @CusLiqDepNew
                    Set @CusMedGerAnt = @CusMedGerNew
                    Set @CusMedComAnt = @CusMedComNew
                    Set @CusMedPraAnt = @CusMedPraNew
                    Set @CusMedDepAnt = @CusMedDepNew

                    Fetch Next From TABLE_Cr Into @CodCfoCab, @DatMov, @NumPrt, @CodCfoIte, 
                                                  @QtdEnt, @CusLiqUni, @CusLiqComUni, @PrcUniMed, @DscUniMed, @VlrBasCalSubTriUni

                  end  -- While (@DatMovAnt = @DatMov) and (@@FETCH_STATUS = 0)

              end -- While @@FETCH_STATUS = 0  
            Close TABLE_Cr
            Deallocate TABLE_Cr

          end  -- if @DatMov is not null
/*
        else
          begin
            Set @VlrPrcVenHis = null
            Select Top 1 @VlrPrcVenHis = Vlr_PrcVen
              From HSPRC
              Where Cod_Estabe = @PCodEstabe     
              And Cod_Produto = @CodPrd
              Order by Dat_Alteracao desc
            
            if IsNull(@VlrPrcVenHis,0) <> IsNull(@PrcVenPrd,0)
              begin
                PRINT '!!!!!!!!!!!!!!!!!!  D E L E T A R  !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!'
              end    
          end  
*/
        Fetch Next From HSPRC_Cr Into @CodPrd, @DatUltEntPra, @DatUltEntDep, @PrcVenPrd
      end
    
    Close HSPRC_Cr
    Deallocate HSPRC_Cr

    -- habilita triggers
    ALTER TABLE PRODU ENABLE TRIGGER ALL
    ALTER TABLE PRXES ENABLE TRIGGER ALL

    if @@trancount > 0
      COMMIT TRANSACTION
  END TRY
  BEGIN CATCH
    if @@trancount > 0
      ROLLBACK TRANSACTION
    -- habilita triggers
    ALTER TABLE PRODU ENABLE TRIGGER ALL
    ALTER TABLE PRXES ENABLE TRIGGER ALL
  END CATCH

END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CriticaCadastrosVolumesWMS]
@PCodEstabe int,
@PNumPdv int,
@PFlgErr bit output,
@PMsgErr varchar(100) output
       
AS

SET NOCOUNT ON 

BEGIN
  -- Pegar a data atual com a hora zerada 
  Set DateFormat ymd
  Declare @Now smalldatetime,
          @Date smalldatetime
  Set @Now = GetDate()
  Set @Date = cast(GetDate() as date)


  Set @PFlgErr = 0
  Set @PMsgErr = ''


  Declare @CodPrd int = 0,
          @StrPrd varchar(100),
          @pm_FlgUndMin bit = 0

  Select @pm_FlgUndMin = IsNull(FlgAltUnvItePdv,0) 
    From PARAM Where Cod_Estabe = @PCodEstabe


  -- se trabalha com unidade minima verifica apresentações padrão
  if Exists(Select 1
            From PDVIT it
                 Left Outer Join PRXAP ap on it.Cod_Produto = ap.Cod_Produt and IsNull(ap.Flg_Padrao,0) = 1
            Where it.Cod_Estabe = @PCodEstabe And it.Cod_Pedido = @PNumPdv
            And it.Qtd_Pedido > 0
            And @pm_FlgUndMin = 1
            And ap.Cod_Produt is null)
    begin
      Set @StrPrd = ''
      Set @CodPrd = 0

      while Exists(Select 1
                   From PDVIT it
                        Left Outer Join PRXAP ap on it.Cod_Produto = ap.Cod_Produt and IsNull(ap.Flg_Padrao,0) = 1
                    Where it.Cod_Estabe = @PCodEstabe And it.Cod_Pedido = @PNumPdv
                    And it.Qtd_Pedido > 0
                    And ap.Cod_Produt is null
                    And @pm_FlgUndMin = 1
                    And it.Cod_Produto > @CodPrd)
        begin
          Set @CodPrd = (Select top 1 it.Cod_Produto
                         From PDVIT it
                              Left Outer Join PRXAP ap on it.Cod_Produto = ap.Cod_Produt and IsNull(ap.Flg_Padrao,0) = 1
                         Where it.Cod_Estabe = @PCodEstabe And it.Cod_Pedido = @PNumPdv
                         And it.Qtd_Pedido > 0
                         And ap.Cod_Produt is null
                         And @pm_FlgUndMin = 1
                         And it.Cod_Produto > @CodPrd
                         Order by it.Cod_Produto)
          if LEN(@StrPrd) + LEN(cast(@CodPrd as varchar)+';') < 101               
            Set @StrPrd = @StrPrd + cast(@CodPrd as varchar)+';'                 
        end 
                
      Set @PFlgErr = 1
      Set @PMsgErr = 'Pedido ('+CAST(@PNumPdv as varchar)+') com produtos sem Apresentação Padrão: '+@StrPrd
    end

  -- se trabalha com unidade minima verifica produtos com mais de 1 apresentação padrão
  if (@PFlgErr = 0) and
     Exists(Select 1
            From PRXAP ap
            Where ap.Flg_Padrao = 1
            And @pm_FlgUndMin = 1
            And Exists(Select 1 From PDVIT it Where it.Cod_Estabe = @PCodEstabe and it.Cod_Pedido = @PNumPdv And it.Cod_Produto = ap.Cod_Produt And it.Qtd_Pedido > 0 )
            Group by ap.Cod_Produt
            Having count(*) > 1)
    begin
      Set @StrPrd = ''
      Set @CodPrd = 0

      while Exists(Select 1
                   From PRXAP ap
                   Where ap.Flg_Padrao = 1
                   And @pm_FlgUndMin = 1
                   And ap.Cod_Produt > @CodPrd
                   And Exists(Select 1 From PDVIT it Where it.Cod_Estabe = @PCodEstabe and it.Cod_Pedido = @PNumPdv And it.Cod_Produto = ap.Cod_Produt And it.Qtd_Pedido > 0 )
                   Group by ap.Cod_Produt
                   Having count(*) > 1)
        begin
          Set @CodPrd = (Select top 1 ap.Cod_Produt
                         From PRXAP ap
                         Where ap.Flg_Padrao = 1
                         And @pm_FlgUndMin = 1
                         And ap.Cod_Produt > @CodPrd
                         And Exists(Select 1 From PDVIT it Where it.Cod_Estabe = @PCodEstabe and it.Cod_Pedido = @PNumPdv And it.Cod_Produto = ap.Cod_Produt And it.Qtd_Pedido > 0 )
                         Group by ap.Cod_Produt
                         Having count(*) > 1
                         Order by ap.Cod_Produt)
                               
          if LEN(@StrPrd) + LEN(cast(@CodPrd as varchar)+';') < 101               
            Set @StrPrd = @StrPrd + cast(@CodPrd as varchar)+';'                 
        end 

      Set @PFlgErr = 1
      Set @PMsgErr = 'Pedido ('+CAST(@PNumPdv as varchar)+') com produtos com mais de 1 Apresentação Padrão: '+@StrPrd
    end

    -- se trabalha com unidade minima verifica produtos sem medidas da embalagem padrao
  if (@PFlgErr = 0) and
     Exists(Select 1
            From PDVIT it
                 Left Join PRXAP ap on it.Cod_Produto = ap.Cod_Produt and ap.Flg_Padrao = 1
            Where it.Cod_Estabe = @PCodEstabe 
            And it.Cod_Pedido = @PNumPdv 
            And it.Qtd_Pedido > 0
			And ((IsNull(ap.Fat_CnvApr,0) = 0) or (IsNull(ap.Vol_Emb,0) = 0))
            And @pm_FlgUndMin = 1)
    begin
      Set @StrPrd = ''
      Set @CodPrd = 0

      while Exists(Select 1
                   From PDVIT it
                        Left Join PRXAP ap on it.Cod_Produto = ap.Cod_Produt and ap.Flg_Padrao = 1
                   Where it.Cod_Estabe = @PCodEstabe 
                   And it.Cod_Pedido = @PNumPdv 
                   And it.Qtd_Pedido > 0
                   And ((IsNull(ap.Fat_CnvApr,0) = 0) or (IsNull(ap.Vol_Emb,0) = 0))
                   And @pm_FlgUndMin = 1
                   And it.Cod_Produto > @CodPrd)
        begin
          Set @CodPrd = (Select top 1 it.Cod_Produto
                         From PDVIT it
                              Left Join PRXAP ap on it.Cod_Produto = ap.Cod_Produt and ap.Flg_Padrao = 1
                         Where it.Cod_Estabe = @PCodEstabe 
                         And it.Cod_Pedido = @PNumPdv 
                         And it.Qtd_Pedido > 0
                         And ((IsNull(ap.Fat_CnvApr,0) = 0) or (IsNull(ap.Vol_Emb,0) = 0))
                         And @pm_FlgUndMin = 1
                         And it.Cod_Produto > @CodPrd
                         Order by it.Cod_Produto)
                               
          if LEN(@StrPrd) + LEN(cast(@CodPrd as varchar)+';') < 101               
            Set @StrPrd = @StrPrd + cast(@CodPrd as varchar)+';'                 
        end 

      Set @PFlgErr = 1
      Set @PMsgErr = 'Pedido ('+CAST(@PNumPdv as varchar)+') com produtos com Cadastro da Apresentação Padrão Incompleto: '+@StrPrd
    end

  -- se nao trabalha com unidade minima verifica produtos sem medidas da embalagem padrao
  if (@PFlgErr = 0) and
     Exists(Select 1
            From PDVIT it
                 Left Join PRODU pr on it.Cod_Produto = pr.Codigo
            Where it.Cod_Estabe = @PCodEstabe 
            And it.Cod_Pedido = @PNumPdv 
            And it.Qtd_Pedido > 0
			And IsNull(pr.Vol_Emb,0) = 0
            And @pm_FlgUndMin = 0)
    begin
      Set @StrPrd = ''
      Set @CodPrd = 0

      while Exists(Select 1
                   From PDVIT it
                        Left Join PRODU pr on it.Cod_Produto = pr.Codigo
                   Where it.Cod_Estabe = @PCodEstabe 
                   And it.Cod_Pedido = @PNumPdv 
                   And it.Qtd_Pedido > 0
			       And IsNull(pr.Vol_Emb,0) = 0
                   And @pm_FlgUndMin = 0
                   And it.Cod_Produto > @CodPrd)
        begin
          Set @CodPrd = (Select top 1 it.Cod_Produto
                         From PDVIT it
                              Left Join PRODU pr on it.Cod_Produto = pr.Codigo
                         Where it.Cod_Estabe = @PCodEstabe 
                         And it.Cod_Pedido = @PNumPdv 
                         And it.Qtd_Pedido > 0
			             And IsNull(pr.Vol_Emb,0) = 0
                         And @pm_FlgUndMin = 0
                         And it.Cod_Produto > @CodPrd
                         Order by it.Cod_Produto)
                               
          if LEN(@StrPrd) + LEN(cast(@CodPrd as varchar)+';') < 101               
            Set @StrPrd = @StrPrd + cast(@CodPrd as varchar)+';'                 
        end 

      Set @PFlgErr = 1
      Set @PMsgErr = 'Pedido ('+CAST(@PNumPdv as varchar)+') com produtos com Cadastro da Embalagem Padrão Incompleto: '+@StrPrd
    end

  if (@PFlgErr = 0) and
     not Exists(Select 1
                From CXPAD
                Where Cod_Estabe = @PCodEstabe
                And IsNull(Flg_Bloqueado,0) = 0 
                And Vol_UtlCxaPad > 0)
    begin
      Set @PFlgErr = 1
      Set @PMsgErr = 'Não existe caixa para embalagem cadastrada no estabelecimento'
    end

END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_SolicitaLotesPDV]
@CodEstabe int,
@CodPed int,       -- num. do pedido
@QtdMesVctMin int,  -- qtd meses vencimento minimo de lotes DESCARTAR  
@FlgErr bit output

AS

SET NOCOUNT ON 

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

Declare @StrMsg varchar(400)

Set @FlgErr = 0
Set @StrMsg = ''

if Exists(Select 1
           From PDVCB
          Where Cod_Estabe = @CodEstabe
            And Numero = @CodPed
            And IsNull(Sta_SepLot,'') <> '')
  begin
    Set @FlgErr = 1
    Return
  end

Set @StrMsg = IsNull((Select MsgErr = Case
                                        When CharIndex(Status2,';N;D;') > 0 then 'Pedido já faturado'
                                        When (Status1 <> 'P') or (Status2 <> 'F') then 'Pedido não está pendente/fechado'
                                        When IsNull(Bloqueio,'') <> '' then 'Pedido está bloqueado'
                                        When IsNull(Flg_Wms,0) = 0 then 'Pedido não permite solicitar lotes'
                                        Else ''
                                      End
                        From PDVCB
                       Where Cod_Estabe = @CodEstabe
                         And Numero = @CodPed),'')
if @StrMsg <> ''
  Set @FlgErr = 1


/*
-- retirar esta critica quando o sistema permitir solicitação de lote específico parcial
if (@FlgErr = 0) and
   Exists(Select 1 From PDVLT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed)
  begin
    Set @FlgErr = 1
    Set @StrMsg = 'Pedido já solicitou lotes'
  end
*/

-- verifica se existe quantidades em PDVLT inválidas
if (@FlgErr = 0) and
   Exists(Select lt.Cod_Produt, lt.QtdLot, it.QtdIte 
             From (Select Cod_Produt, QtdLot = SUM(IsNull(Qtd_Lote,0)) 
                     From PDVLT 
                   Where Cod_Estabe = @CodEstabe
                     And Cod_Pedido = @CodPed
                     And IsNull(Qtd_Lote,0) > 0 
                   Group by Cod_Produt) lt 
                 Inner Join (Select Cod_Produto, QtdIte = SUM(IsNull(Qtd_Pedido,0)+Isnull(Qtd_Bonificacao,0)) 
                               From PDVIT 
                              Where Cod_Estabe = @CodEstabe
                                And Cod_Pedido = @CodPed
                                And (IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) > 0 
                              Group by Cod_Produto) it on it.Cod_Produto = lt.Cod_Produt 

           Where IsNull(lt.QtdLot,0) > IsNull(it.QtdIte,0))
  begin
    Set @FlgErr = 1
    Set @StrMsg = 'Existem itens em PDVLT com quantidades superiores de PDVIT '
  end

if (@FlgErr = 0) and
   Exists(Select Cod_Produto, Tip_Sai, count(*) From PDVIT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed Group By Cod_Produto, Tip_Sai Having count(*) > 1)
  begin
    Set @FlgErr = 1
    Set @StrMsg = 'Existem produtos com mais de um lote'
  end

if (@FlgErr = 0) and
   Exists(Select z1.Cod_Zon, z2.Cod_Zon 
            From TBZON z1, TBZON z2
           Where z1.Cod_Estabe = z2.Cod_Estabe
             And z1.Cod_Dep = z2.Cod_Dep
             And z1.Cod_Estabe = @CodEstabe
             And z1.Cod_Zon > 0
             And z1.Cod_Zon <> z2.Cod_Zon 
             And ((z1.Num_RuaIni between z2.Num_RuaIni and z2.Num_RuaFim) or
                  (z1.Num_RuaFim between z2.Num_RuaIni and z2.Num_RuaFim)))
  begin
    Set @FlgErr = 1
    Select top 1 
           @StrMsg = 'Endereços conflitantes entre as Zonas '+CAST(z1.Cod_Zon as varchar)+' e '+CAST(z2.Cod_Zon as varchar)
      From TBZON z1, TBZON z2
     Where z1.Cod_Estabe = z2.Cod_Estabe
       And z1.Cod_Dep = z2.Cod_Dep
       And z1.Cod_Estabe = @CodEstabe
       And z1.Cod_Zon > 0
       And z1.Cod_Zon <> z2.Cod_Zon 
       And ((z1.Num_RuaIni between z2.Num_RuaIni and z2.Num_RuaFim) or
            (z1.Num_RuaFim between z2.Num_RuaIni and z2.Num_RuaFim))    
  end

-- critica cadastros, inconsistencias, embalagem padrao, apresentacao padrao, etc...
if @FlgErr = 0
  Exec PR_CriticaCadastrosVolumesWMS @CodEstabe, @CodPed, @FlgErr output, @StrMsg output

-- verifica reabastecimento do picking
if @FlgErr = 0
  Exec PR_VerificaAbastecimentoPedido @CodEstabe, @CodPed, @StrMsg output, @FlgErr output  


if @FlgErr = 1
  begin
    RAISERROR(@StrMsg,16,1)
    Return
  end
else
BEGIN
  Begin Transaction

--    Declare @DesLoc varchar(80) = '(ANTES) PR_SolicitaLotesPDV pedido: '+cast(@CodPed as varchar)
--    Exec PR_Verifica_Divergencia_PRXESxPRLOT_PRLTL @DesLoc, @CodEstabe, 0

    Declare @CodPrd int,
            @TipSai varchar(1),
            @IdPolLot int,
            @QtdPdv int,
            @QtdLot int,
            @QtdSld int,
            @QtdMov int,
            @FlgMov bit = 0,
            @CodLotTip varchar(20),
            @QtdTotTip int,
            @QtdPraTip int,
            @QtdDepTip int,
            @QtdFra int,
            @QtdEmbFec int,
            @QtdEmbFecCal int,
            @QtdCxaFec int,
            @QtdUndLot int,
            @QtdSldFiscal int,
            @QtdSolPulmao int,
            @cl_CodCliPag int,
            @cl_CodGrpCli int,
            @cl_QtdMesMinPrzVctLot int,
            @cl_FlgBlqLotVarPdv bit,
            @StrPrd varchar(100),
            @FlgIntWms bit = 0,
            @BlqEstFisNeg bit = 0,
            @FlgUndMin bit = 0,
            @StaIntWms varchar(1),
            @FlgTipVenFat bit = 0,
            @FlgPodeFechar bit = 0,
		    @Usuario varchar(15)

    Set @Usuario = dbo.FN_UsuarioInfarma()

    Select @FlgIntWms = IsNull(FlgIntegrWmsExt,0),
           @BlqEstFisNeg = IsNull(BlqEstFisNeg,0)   -- nao permite negativar estoque fiscal
      From PMEST 
     Where Cod_Estabe = @CodEstabe

    Select @FlgUndMin = IsNull(FlgAltUnvItePdv,0) 
      From PARAM 
     Where Cod_Estabe = @CodEstabe

    Select @StaIntWms = IsNull(cb.Sta_IntWms,''),
           @FlgTipVenFat = Case When ISNull(op.Cod_CfoNorInt,0) > 0 then 1 ELse 0 End
      From PDVCB cb
           Left Join TPOPE op on cb.Tip_Faturamento = op.Cod_Ope 
     Where cb.Cod_Estabe = @CodEstabe and cb.Numero = @CodPed

    Set @FlgPodeFechar = 0
    if @FlgIntWms = 0
      begin
        -- atualiza status PDVCB: 'X"- em processamento
        Update PDVCB
           Set Sta_SepLot = 'X'
         Where Cod_Estabe = @CodEstabe
           And Numero = @CodPed
           And IsNull(Sta_SepLot,'') = ''

        if Exists(Select 1
                    From PDVCB
                   Where Cod_Estabe = @CodEstabe
                     And Numero = @CodPed
                     And IsNull(Sta_SepLot,'') = 'X')
          Set @FlgPodeFechar = 1
      end
    else
      begin
        if @StaIntWms = ''
          Exec PR_WMSGerarXMLSaida @CodEstabe, @CodPed

        Update PDVCB
           Set Sta_IntWMS = '0'
         Where Cod_Estabe = @CodEstabe 
           And Numero = @CodPed
           And IsNull(Sta_IntWMS,'') = ''
      end


    Set @FlgErr = 0
    Set @StrMsg = ''

    if @FlgPodeFechar = 1
      begin 

        IF OBJECT_ID('tempdb..#ARQ_PDVIT') IS NOT NULL
          DROP TABLE #ARQ_PDVIT
        
        CREATE TABLE #ARQ_PDVIT
        (
            Chave int identity,
        	Cod_Produt int,
            Id_PolLot int,
            Qtd_Pdv int
        ) 

        IF OBJECT_ID('tempdb..#ARQ_PRLTL') IS NOT NULL
          DROP TABLE #ARQ_PRLTL
        
        CREATE TABLE #ARQ_PRLTL
        (
            Chave int identity,
        	Cod_Estabe smallint,
            Cod_Dep smallint,
            Num_Rua smallint, 
        	Num_Col smallint, 
        	Num_Niv smallint, 
        	Num_Apt smallint,
        	Tip_LocEnd varchar(1),
            Cod_Produt int,
        	Cod_Lote varchar(20),
            Cod_Fabricante int,
            Dat_Vencim smalldatetime,
            Dat_Entrada smalldatetime,
            Qtd_EmbFec int,
            C_QtdEmbFec int,
            Qtd_Saldo int,
            Qtd_SldPra int,
            Qtd_SldDep int
        ) 
        
        CREATE UNIQUE CLUSTERED INDEX IX_CL_ARQ_PRLTL ON #ARQ_PRLTL (Chave);
        CREATE NONCLUSTERED INDEX IX_CL_ARQ_PRLTL_Cod_Dep_Cod_Produto_Dat_Vencim ON #ARQ_PRLTL (Cod_Estabe, Cod_Produt, Dat_Vencim);


        -- popula #ARQ_PDVIT --------------------------------------------------
        Insert into #ARQ_PDVIT
          Select it.Cod_Produto, 
                 IdPolLot = Case
                              When Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = it.Cod_Estabe and pl.Id_PolCom = it.Id_PolCom and pl.Cod_Produt = it.Cod_Produto) then it.Id_PolCom
                              Else 0
                            End,
                 sum(IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)) as QtdPdv
            From PDVIT it 
           Where it.Cod_Estabe = @CodEstabe 
             And it.Cod_Pedido = @CodPed
             And IsNull(it.Qtd_Pedido,0) > 0
           Group by it.Cod_Estabe, it.Cod_Produto, it.Id_PolCom

        -- desconta PDVLT já solicitado ---131370
		Declare @cr_CodPrd int,
                @cr_IdPolLot int,
                @cr_QtdLot int

        -- lotes já solicitados
        Declare PDVLT_Cr Cursor Local Fast_Forward For 

          Select Cod_Produt, Id_PolCOm
               , Qtd_Lote = sum(Qtd_Lote)
            From PDVLT
           Where Cod_Estabe = @CodEstabe
             And Cod_Pedido = @CodPed
           Group by Cod_Produt, Id_PolCom
           Order by Cod_Produt, Id_PolCom Desc

        Open PDVLT_Cr  
        Fetch Next From PDVLT_Cr Into @cr_CodPrd, @cr_IdPolLot, @QtdSld
        While @@FETCH_STATUS = 0
          begin
            Set @CodPrd = @cr_CodPrd

            While (@CodPrd = @cr_CodPrd) and (@@FETCH_STATUS = 0)  
              begin

                -- desconta lote diferenciado se houver
                if Exists(Select 1 From #ARQ_PDVIT Where Cod_Produt = @CodPrd 
                             And Id_PolLot = @cr_IdPolLot 
                             And @cr_IdPolLot > 0 And Qtd_Pdv > 0)
                  begin
                    Select @cr_QtdLot = Qtd_Pdv 
                      From #ARQ_PDVIT 
                     Where Cod_Produt = @CodPrd
                       And Id_PolLot = @cr_IdPolLot
                       And Qtd_Pdv > 0

                    Set @QtdMov = Case 
                                    When @cr_QtdLot > @QtdSld then @QtdSld
                                    Else @cr_QtdLot
                                  End

                    Update #ARQ_PDVIT 
                       Set Qtd_Pdv = Qtd_Pdv - @QtdMov
                     Where Cod_Produt = @CodPrd
                       And Id_PolLot = @cr_IdPolLot
                       And @QtdMov >= Qtd_Pdv
                    if @@rowcount > 0
                      Set @QtdSld = @QtdSld - @QtdMov
                  end

                -- desconta restante
                if @QtdSld > 0
                  Set @FlgMov = 1
				   
                while (@QtdSld > 0) and (@FlgMov = 1) and
                      Exists(Select 1 From #ARQ_PDVIT Where Cod_Produt = @CodPrd And Qtd_Pdv > 0)
                  begin
                    Set @FlgMov = 0

                    Select top 1 
                           @cr_IdPolLot = Id_PolLot
                         , @cr_QtdLot = Qtd_Pdv 
                      From #ARQ_PDVIT 
                     Where Cod_Produt = @CodPrd
                       And Qtd_Pdv > 0
                     Order by Id_PolLot desc

                    Set @QtdMov = Case 
                                    When @cr_QtdLot > @QtdSld then @QtdSld
                                    Else @cr_QtdLot
                                  End

                    Update #ARQ_PDVIT 
                       Set Qtd_Pdv = Qtd_Pdv - @QtdMov
                     Where Cod_Produt = @CodPrd
                       And Id_PolLot = @cr_IdPolLot
                       And @QtdMov <= Qtd_Pdv
                    if @@rowcount > 0
                      begin
                        Set @FlgMov = 1
                        Set @QtdSld = @QtdSld - @QtdMov
                      end

                  end -- while (@QtdSld > 0) and (@FlgMov = 1) and

                Fetch Next From PDVLT_Cr Into @cr_CodPrd, @cr_IdPolLot, @QtdSld

              end  -- While (@CodPrd = @cr_CodPrd) and (@@FETCH_STATUS = 0)

            Delete From #ARQ_PDVIT 
             Where Cod_Produt = @CodPrd
               And Qtd_Pdv = 0

          end  -- While @@FETCH_STATUS = 0
          
        Close PDVLT_Cr
        Deallocate PDVLT_Cr
        -- fim popula #ARQ_PRLTL -------------------------------------------------------

        -- popula #ARQ_PRLTL descontando abastecimentos pendentes
        Insert into #ARQ_PRLTL
          Select lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua, lt.Num_Col, lt.Num_Niv, lt.Num_Apt,
                 dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua),
                 lt.Cod_Produt, lt.Cod_Lote, pr.Cod_Fabricante, lt.Dat_Vencim, lt.Dat_Entrada,
                 Qtd_EmbFec  = IsNull(lt.Qtd_EmbFec,0),
                 C_QtdEmbFec = IsNull(lt.C_QtdEmbFec,0),
                 Qtd_Saldo   = IsNull(lt.Qtd_Saldo,0)  - IsNull(ab.C_QtdMov,0),
                 Qtd_SldPra  = IsNull(lt.Qtd_SldPra,0) - IsNull(ab.C_QtdMov,0),
                 Qtd_SldDep  = IsNull(lt.Qtd_SldDep,0)
            From PRLTL lt Inner Join
                 PRODU pr on lt.Cod_Produt = pr.Codigo Left Join
                 ( Select it.Cod_Produt, it.Cod_Lote, it.Cod_Dep, it.Num_Rua, it.Num_Col, it.Num_Niv, it.Num_Apt,
                          C_QtdMov = sum(QTd_Mov)
                     From ABAIT it
                          Inner Join ABACB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Cod_Abaste = cb.Cod_Abaste
                    Where cb.Cod_Estabe = @CodEstabe
                      And cb.Cod_STa = 'A'
                    Group by it.Cod_Produt, it.Cod_Lote, it.Cod_Dep, it.Num_Rua, it.Num_Col, it.Num_Niv, it.Num_Apt
                 ) ab on lt.Cod_Produt = ab.Cod_Produt and lt.Cod_Lote = ab.Cod_Lote and
                         lt.Cod_Dep = ab.Cod_Dep and lt.Num_Rua = ab.Num_Rua and lt.Num_Col = ab.Num_Col and lt.Num_Niv = ab.Num_Niv and lt.Num_Apt = ab.Num_Apt
           Where lt.Cod_Estabe = @CodEstabe
             And (IsNull(lt.Qtd_Saldo,0) - IsNull(ab.C_QtdMov,0)) > 0
             And IsNull(lt.Qtd_EmbFec,0) > 0

        -- normaliza #ARQ_PRLTL
        Update #ARQ_PRLTL
           Set Qtd_SldDep = Qtd_SldDep + Abs(Qtd_SldPra),
               Qtd_SldPra = 0
         Where Qtd_SldPra < 0
        
		-- TBZON
        Update TBZON
           Set Num_Esteira = 1
         Where Cod_Estabe = @CodEstabe
           And ISNULL(Num_Esteira,0) = 0

        Declare @NumVol int,
                @to_CodCfoNorInt int,
                @to_TipOpe varchar(1),
                @pm_FlgBlqCnfTrf bit, 
                @pm_CodOpeWmsDef int,
                @DatVct smalldatetime,
                @DatEnt smalldatetime,
                @CodLot varchar(20),
                @CodLotEsp varchar(20),  -- lote especifico
				@QtdLotSel int,
                @LocEst varchar(1),
                @OrdDep varchar(1),
				@FlgPrePck bit,
                @CodDep int, 
                @CodDepAnt int, 
                @NumEst smallint,
                @NumEstAnt smallint,
                @NumRua int, 
                @NumCol int, 
                @NumNiv int, 
                @NumApt int, 
                @SldLot int,
                @FatCnvAprEmbPad int,
                @QtdPraLot int,
                @QtdDepLot int,
                @QtdDif int,
                @FlgDesord bit,
                @dx_CodLocFis varchar(15),
                @pr_VolUniMin numeric(18,8),  -- @pr_VolEmb
                @cx_CodCxaPad int,
                @cx_VolCxaPad numeric(18,4),
                @cx_NewCodCxaPad int,
                @VolMaxCxa numeric(18,4),
                @VolTotIte numeric(18,4),
                @VolAcu numeric(18,4),
                @QtdAteAcu int,
                @QtdAte int,
                @Per numeric(18,8)

        Select @cl_CodCliPag = Case 
                                 When IsNull(cl.Cod_CliPag,0) > 0 then cl.Cod_CliPag
                                 Else cl.Codigo
                               End,
               @cl_QtdMesMinPrzVctLot = IsNull(cl.Qtd_MesMinPrzVctLot,0),
               @cl_CodGrpCli = cl.Cod_GrpCli,
			   @cl_FlgBlqLotVarPdv = IsNull(Flg_BlqLotVarPdv,0)
          From CLIEN cl Inner Join PDVCB cb on (cb.Cod_Cliente = cl.Codigo)
         Where cb.Cod_Estabe = @CodEstabe 
           And cb.Numero = @CodPed
          
        if @cl_CodCliPag is null Set @cl_CodCliPag = 0
        if @cl_QtdMesMinPrzVctLot is null Set @cl_QtdMesMinPrzVctLot = 0
        if @cl_CodGrpCli is null Set @cl_CodGrpCli = 0
                     
        Select @to_CodCfoNorInt = IsNull(t.Cod_CfoNorInt,0),
               @to_TipOpe = IsNull(t.Tip_Ope,'')
          From TPOPE t Inner Join PDVCB p on (t.Cod_Ope = p.Tip_Faturamento)
         Where p.Cod_Estabe = @CodEstabe 
           And p.Numero = @CodPed

        Select @pm_FlgBlqCnfTrf = IsNull(FlgBlqCnfTrf,0), 
               @pm_CodOpeWmsDef = IsNull(CodOpeWmsDef,0) 
          From PMEST
         Where Cod_Estabe = @CodEstabe  

        -- pega o último volume de caixa fechada, se já existir
        Set @NumVol = IsNull((Select max(Num_Vol)
                                From PDVLT 
                               Where Cod_Estabe = @CodEstabe 
                                 And Cod_Pedido = @CodPed
                                 And ((Cod_LocFis = 'PRLTL') And (Qtd_CxaFec > 0))),0)	

        -- negativa volumes fracionados pré-existentes
        Update PDVLT
           Set Num_Vol = -1
         Where Cod_Estabe = @CodEstabe 
           And Cod_Pedido = @CodPed
           And ((Cod_LocFis <> 'PRLTL') or (Qtd_CxaFec > 0))


        -- elimina registro de conferencia existentes
        Delete from CPVIT Where Cod_Estabe = @CodEstabe And Num_PedCnf = @CodPed

        Delete from CPVCB Where Cod_Estabe = @CodEstabe And Num_PedCnf = @CodPed
          
        -- **************************************************  solicita lotes (CAIXA FECHADA) por vencimento do DEPOSITO FECHADO  ******************************************************************
        Declare PDVIT_Cr Cursor Local Fast_Forward For 

          Select Cod_Produt, Id_PolLot, Qtd_Pdv
            From #ARQ_PDVIT

        Open PDVIT_Cr  
        Fetch Next From PDVIT_Cr Into @CodPrd, @IdPolLot, @QtdPdv
        While @@FETCH_STATUS = 0  
          begin
            -- nao permite negativar estoque fiscal
            if (@BlqEstFisNeg = 1) and (@FlgTipVenFat = 1)
              begin
                Set @QtdSldFiscal = dbo.FN_SldFiscalDisponPrd(@CodEstabe,@CodPrd)
                if @QtdPdv > @QtdSldFiscal 
                  Set @QtdPdv = @QtdSldFiscal
              end

            if @FlgUndMin = 0
              begin
                Select @pr_VolUniMin = IsNull(Vol_Emb,0)
                  From PRODU
                 Where Codigo = @CodPrd
              end
            else
            -- volume da embalagem Unidade minima
              begin
                Select @pr_VolUniMin = IsNull(Vol_Emb/Fat_CnvApr,0)
                  From PRXAP
                 Where Cod_Produt = @CodPrd
				   And Flg_Padrao = 1
              end

            -- verifica atendimento lote especifico
			Set @QtdLotSel = 0

            Set @QtdFra = @QtdPdv  
            -------------------------------------------------------------------------------------------------------------------------------------------------------
            if @to_CodCfoNorInt > 0
              begin
                -- venda FAT estoque compartilhado
                Declare PRLTL_Cr Cursor Local Fast_Forward For 

                  Select '1' as CodLocEst, lt.OrdDep, lt.Dat_Vencim, lt.Flg_PrePck, lt.Dat_Entrada, lt.Cod_Lote, lt.Qtd_EmbFec, lt.Qtd_EmbFecCal, 
                         lt.Cod_Dep, lt.Num_Rua, lt.Num_Col, lt.Num_Niv, lt.Num_Apt, lt.Qtd_SldPra
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Produt, l1.Cod_Fabricante, l1.Dat_Vencim, Flg_PrePck=IsNull(e1.Flg_PrePck,0), l1.Dat_Entrada, l1.Cod_Lote, Qtd_EmbFec=IsNull(l1.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l1.C_QtdEmbFec,0),
                                 l1.Cod_Dep, l1.Num_Rua, l1.Num_Col, l1.Num_Niv, l1.Num_Apt, Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldPra=IsNull(l1.Qtd_SldPra,0) 
                            From #ARQ_PRLTL l1 Inner Join 
                                 DPXGC de on (l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli) Left Join
							     ENDDP e1 on (l1.Cod_Estabe = e1.Cod_Estabe and l1.Cod_Dep = e1.Cod_Dep and l1.Num_Rua = e1.Num_Rua and
								              l1.Num_Col = e1.Num_Col and l1.Num_Niv = e1.Num_Niv and l1.Num_Apt = e1.Num_Apt)
                           Where l1.Cod_Estabe = @CodEstabe 
                             And IsNull(l1.Qtd_SldPra,0) >= IsNull(l1.C_QtdEmbFec,0)
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Produt, l2.Cod_Fabricante, l2.Dat_Vencim, Flg_PrePck=IsNull(e2.Flg_PrePck,0), l2.Dat_Entrada, l2.Cod_Lote, Qtd_EmbFec=IsNull(l2.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l2.C_QtdEmbFec,0), 
                                 l2.Cod_Dep, l2.Num_Rua, l2.Num_Col, l2.Num_Niv, l2.Num_Apt, Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldPra=IsNull(l2.Qtd_SldPra,0) 
                            From #ARQ_PRLTL l2 Left Join
							     ENDDP e2 on (l2.Cod_Estabe = e2.Cod_Estabe and l2.Cod_Dep = e2.Cod_Dep and l2.Num_Rua = e2.Num_Rua and
								              l2.Num_Col = e2.Num_Col and l2.Num_Niv = e2.Num_Niv and l2.Num_Apt = e2.Num_Apt)
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_SldPra,0) >= IsNull(l2.C_QtdEmbFec,0)
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Left Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = lt.Cod_Produt Left Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = lt.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd
                     And IsNull(lt.Qtd_EmbFecCal,0) > 0 
                     And IsNull(lt.Qtd_Saldo,0) >= IsNull(lt.Qtd_EmbFecCal,0) 
                     And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'D'
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     and IsNull(lt.Qtd_SldPra,0) > 0
                     and @QtdPdv >= IsNull(lt.Qtd_EmbFecCal,0) 
                  UNION ALL
                  Select '2' as CodLocEst, lt.OrdDep, lt.Dat_Vencim, lt.Flg_PrePck, lt.Dat_Entrada, lt.Cod_Lote, lt.Qtd_EmbFec, lt.Qtd_EmbFecCal,
                         lt.Cod_Dep, lt.Num_Rua, lt.Num_Col, lt.Num_Niv, lt.Num_Apt, IsNull(lt.Qtd_SldDep,0) 
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Produt, l1.Cod_Fabricante, l1.Dat_Vencim, Flg_PrePck=IsNull(e1.Flg_PrePck,0), l1.Dat_Entrada, l1.Cod_Lote, Qtd_EmbFec=IsNull(l1.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l1.C_QtdEmbFec,0),
                                 l1.Cod_Dep, l1.Num_Rua, l1.Num_Col, l1.Num_Niv, l1.Num_Apt, Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldDep=IsNull(l1.Qtd_SldDep,0) 
                            From #ARQ_PRLTL l1 Inner Join 
                                 DPXGC de on (l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli) Left Join
							     ENDDP e1 on (l1.Cod_Estabe = e1.Cod_Estabe and l1.Cod_Dep = e1.Cod_Dep and l1.Num_Rua = e1.Num_Rua and
								              l1.Num_Col = e1.Num_Col and l1.Num_Niv = e1.Num_Niv and l1.Num_Apt = e1.Num_Apt)
                           Where l1.Cod_Estabe = @CodEstabe 
                             And IsNull(l1.Qtd_SldDep,0) >= IsNull(l1.C_QtdEmbFec,0) 
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Produt, l2.Cod_Fabricante, l2.Dat_Vencim, Flg_PrePck=IsNull(e2.Flg_PrePck,0), l2.Dat_Entrada, l2.Cod_Lote, Qtd_EmbFec=IsNull(l2.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l2.C_QtdEmbFec,0), 
                                 l2.Cod_Dep, l2.Num_Rua, l2.Num_Col, l2.Num_Niv, l2.Num_Apt, Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldDep=IsNull(l2.Qtd_SldDep,0) 
                            From #ARQ_PRLTL l2 Left Join
							     ENDDP e2 on (l2.Cod_Estabe = e2.Cod_Estabe and l2.Cod_Dep = e2.Cod_Dep and l2.Num_Rua = e2.Num_Rua and
								              l2.Num_Col = e2.Num_Col and l2.Num_Niv = e2.Num_Niv and l2.Num_Apt = e2.Num_Apt)
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_SldDep,0) >= IsNull(l2.C_QtdEmbFec,0)  
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Left Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = lt.Cod_Produt Left Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = lt.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd  
                     And IsNull(lt.Qtd_EmbFecCal,0) > 0 
                     And IsNull(lt.Qtd_Saldo,0) >= IsNull(lt.Qtd_EmbFecCal,0) 
                     And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'D'
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     And IsNull(lt.Qtd_SldDep,0) > 0
                     And @QtdPdv >= IsNull(lt.Qtd_EmbFecCal,0) 
                   Order by OrdDep, CodLocEst, Dat_Vencim, Flg_PrePck desc, Num_Rua, Num_Niv, Num_Apt, Num_Col, Cod_Lote, Dat_Entrada
              end
            else
              begin
                -- venda ORC estoque compartilhado
                Declare PRLTL_Cr Cursor Local Fast_Forward For 
                  Select '2' as CodLocEst, lt.OrdDep, lt.Dat_Vencim, lt.Flg_PrePck, lt.Dat_Entrada, lt.Cod_Lote, lt.Qtd_EmbFec, lt.Qtd_EmbFecCal,
                         lt.Cod_Dep, lt.Num_Rua, lt.Num_Col, lt.Num_Niv, lt.Num_Apt, lt.Qtd_SldDep
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Produt, l1.Cod_Fabricante, l1.Dat_Vencim, Flg_PrePck=IsNull(e1.Flg_PrePck,0), l1.Dat_Entrada, l1.Cod_Lote, Qtd_EmbFec=IsNull(l1.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l1.C_QtdEmbFec,0), 
                                 l1.Cod_Dep, l1.Num_Rua, l1.Num_Col, l1.Num_Niv, l1.Num_Apt, Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldDep=IsNull(l1.Qtd_SldDep,0) 
                            From #ARQ_PRLTL l1 Inner Join 
                                 DPXGC de on (l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli) Left Join
							     ENDDP e1 on (l1.Cod_Estabe = e1.Cod_Estabe and l1.Cod_Dep = e1.Cod_Dep and l1.Num_Rua = e1.Num_Rua and
								              l1.Num_Col = e1.Num_Col and l1.Num_Niv = e1.Num_Niv and l1.Num_Apt = e1.Num_Apt)
                           Where l1.Cod_Estabe = @CodEstabe 
                             And IsNull(l1.Qtd_SldDep,0) >= IsNull(l1.C_QtdEmbFec,0)
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Produt, l2.Cod_Fabricante, l2.Dat_Vencim, Flg_PrePck=IsNull(e2.Flg_PrePck,0), l2.Dat_Entrada, l2.Cod_Lote, Qtd_EmbFec=IsNull(l2.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l2.C_QtdEmbFec,0),
                                 l2.Cod_Dep, l2.Num_Rua, l2.Num_Col, l2.Num_Niv, l2.Num_Apt, Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldDep=IsNull(l2.Qtd_SldDep,0) 
                            From #ARQ_PRLTL l2 Left Join
							     ENDDP e2 on (l2.Cod_Estabe = e2.Cod_Estabe and l2.Cod_Dep = e2.Cod_Dep and l2.Num_Rua = e2.Num_Rua and
								              l2.Num_Col = e2.Num_Col and l2.Num_Niv = e2.Num_Niv and l2.Num_Apt = e2.Num_Apt)
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_SldDep,0) >= IsNull(l2.C_QtdEmbFec,0)
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Left Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = lt.Cod_Produt Left Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = lt.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd
                     And IsNull(lt.Qtd_EmbFecCal,0) > 0 
                     And IsNull(lt.Qtd_Saldo,0) >= IsNull(lt.Qtd_EmbFecCal,0) 
                     And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'D'
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     And IsNull(lt.Qtd_SldDep,0) > 0
                     And @QtdPdv >= IsNull(lt.Qtd_EmbFecCal,0) 
                  UNION ALL
                  Select '1' as CodLocEst, lt.OrdDep, lt.Dat_Vencim, lt.Flg_PrePck, lt.Dat_Entrada, lt.Cod_Lote, lt.Qtd_EmbFec, lt.Qtd_EmbFecCal,
                         lt.Cod_Dep, lt.Num_Rua, lt.Num_Col, lt.Num_Niv, lt.Num_Apt, lt.Qtd_SldPra
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Produt, l1.Cod_Fabricante, l1.Dat_Vencim, Flg_PrePck=IsNull(e1.Flg_PrePck,0), l1.Dat_Entrada, l1.Cod_Lote, Qtd_EmbFec=IsNull(l1.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l1.C_QtdEmbFec,0), 
                                 l1.Cod_Dep, l1.Num_Rua, l1.Num_Col, l1.Num_Niv, l1.Num_Apt, Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldPra=IsNull(l1.Qtd_SldPra,0) 
                            From #ARQ_PRLTL l1 Inner Join 
                                 DPXGC de on (l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli) Left Join
							     ENDDP e1 on (l1.Cod_Estabe = e1.Cod_Estabe and l1.Cod_Dep = e1.Cod_Dep and l1.Num_Rua = e1.Num_Rua and
								              l1.Num_Col = e1.Num_Col and l1.Num_Niv = e1.Num_Niv and l1.Num_Apt = e1.Num_Apt)
                           Where l1.Cod_Estabe = @CodEstabe 
                            And IsNull(l1.Qtd_SldPra,0) >= IsNull(l1.C_QtdEmbFec,0)
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Produt, l2.Cod_Fabricante, l2.Dat_Vencim, Flg_PrePck=IsNull(e2.Flg_PrePck,0), l2.Dat_Entrada, l2.Cod_Lote, Qtd_EmbFec=IsNull(l2.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l2.C_QtdEmbFec,0),
                                 l2.Cod_Dep, l2.Num_Rua, l2.Num_Col, l2.Num_Niv, l2.Num_Apt, Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldPra=IsNull(l2.Qtd_SldPra,0) 
                            From #ARQ_PRLTL l2 Left Join
							     ENDDP e2 on (l2.Cod_Estabe = e2.Cod_Estabe and l2.Cod_Dep = e2.Cod_Dep and l2.Num_Rua = e2.Num_Rua and
								              l2.Num_Col = e2.Num_Col and l2.Num_Niv = e2.Num_Niv and l2.Num_Apt = e2.Num_Apt)
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_SldPra,0) >= IsNull(l2.C_QtdEmbFec,0)
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Left Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = lt.Cod_Produt Left Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = lt.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd
                     And IsNull(lt.Qtd_EmbFecCal,0) > 0 
                     And IsNull(lt.Qtd_Saldo,0) >= IsNull(lt.Qtd_EmbFecCal,0) 
                     And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'D'
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     And IsNull(lt.Qtd_SldPra,0) > 0
                     And @QtdPdv >= IsNull(lt.Qtd_EmbFecCal,0) 
                   Order by OrdDep, CodLocEst desc, Dat_Vencim, Flg_PrePck desc, Num_Rua, Num_Niv, Num_Apt, Num_Col, Cod_Lote, Dat_Entrada
              end
            -------------------------------------------------------------------------------------------------------------------------------------------------------
            Open PRLTL_Cr
            Fetch Next From PRLTL_Cr Into @LocEst, @OrdDep, @DatVct, @FlgPrePck, @DatEnt, @CodLot, @QtdEmbFec, @QtdEmbFecCal,
                                          @CodDep, @NumRua, @NumCol, @NumNiv,@NumApt, @SldLot 
            While @@FETCH_STATUS = 0
              begin
                -- verifica lote unico
                Set @QtdLotSel = @QtdLotSel + 1
                if (@cl_FlgBlqLotVarPdv = 1) and (@QtdLotSel > 1)
                  Break

                if (@QtdFra > 0) and (@QtdFra >= @QtdEmbFecCal) and (@SldLot >= @QtdEmbFecCal) 
                  begin
                    Set @QtdCxaFec = Case 
                                       When @SldLot < @QtdFra Then @SldLot / @QtdEmbFecCal
                                       Else @QtdFra / @QtdEmbFecCal
                                     End

                    Set @QtdUndLot = @QtdCxaFec * @QtdEmbFecCal

                    -- decrementa saldo em PRLTL
                    Set @QtdPraLot = 0
                    Set @QtdDepLot = 0
                    if @LocEst = '1'
                      Set @QtdPraLot = @QtdUndLot
                    else
                      Set @QtdDepLot = @QtdUndLot

                    Update PRLTL
                       Set Qtd_SolPra = IsNull(Qtd_SolPra,0) + @QtdPraLot,
                           Qtd_SolDep = IsNull(Qtd_SolDep,0) + @QtdDepLot
                     Where Cod_Estabe = @CodEstabe 
                       And Cod_Produt = @CodPrd
                       And Cod_Lote = @CodLot
                       And Qtd_EmbFec = @QtdEmbFec 
                       And Cod_Dep =  @CodDep
                       And Num_Rua = @NumRua
                       And Num_Col = @NumCol
                       And Num_Niv = @NumNiv
                       And Num_Apt = @NumApt

                    Set @QtdFra = @QtdFra - @QtdUndLot
                    Set @SldLot = @SldLot - @QtdUndLot

                    -- grava registro em PDVLT 
                    Set @VolTotIte = @QtdUndLot*@pr_VolUniMin
                    Set @FlgDesord = 0

					if (@QtdPraLot+@QtdDepLot) > 0
                      begin
					    --Set @NumEst = IsNull((Select z.Num_Esteira From TBZON z Where z.Cod_Estabe = @CodEstabe and @NumRua between z.Num_RuaIni and z.Num_RuaFim),0)
						Set @NumEst = IsNull((Select z.Num_Esteira From TBZON z Where z.Cod_Estabe = @CodEstabe and Cod_Dep = @CodDep and @NumRua between z.Num_RuaIni and z.Num_RuaFim),0)

                        -- caixa fechada: sempre um novo volume
                        Set @NumVol = @NumVol + 1
                        if @NumVol = 0 Set @NumVol = 1

                        if Exists(Select 1 From PDVLT 
                                   Where Cod_Estabe = @CodEstabe 
                                     And Cod_Pedido = @CodPed And Num_Vol = @NumVol) 
                          Set @NumVol = @NumVol + 1

                        -- caixa fechada: PDVLT.Cod_LocFis = 'PRLTL',  PDVLT.Qtd_CxaFec > 0
                        Insert Into PDVLT (Cod_Estabe, Cod_Pedido, Num_Vol, Cod_Produt, Cod_Lote
                                        ,  Qtd_EmbFec, Fat_CnvAprEmbPad, Qtd_Lote, Qtd_CxaFec
                                        ,  Cod_Dep, Num_Esteira, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_LocFis
                                        ,  Qtd_LotePra, Qtd_LoteDep, Vol_TotIte, Id_PolCom, Flg_Desord, Flg_Manual
                                        ,  Cod_FunSep, Transacao)
                                   Values (@CodEstabe, @CodPed, @NumVol, @CodPrd, @CodLot
                                        ,  @QtdEmbFec, @QtdEmbFecCal, @QtdUndLot, @QtdCxaFec
                                        ,  @CodDep, @NumEst, @NumRua, @NumCol, @NumNiv, @NumApt, 'PRLTL'
                                        ,  @QtdPraLot, @QtdDepLot, @VolTotIte, @IdPolLot, @FlgDesord, 0
                                        ,  0, @Now )
                        if @@error <> 0
                          begin
                            Rollback Transaction
                            Return
                          end
                      end

                  end -- if (@QtdFra > 0) and (@QtdFra >= @QtdEmbFec) and (@SldLot >= @QtdEmbFec) 

                Fetch Next From PRLTL_Cr Into @LocEst, @OrdDep, @DatVct, @FlgPrePck, @DatEnt, @CodLot, @QtdEmbFec, @QtdEmbFecCal,
                                              @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @SldLot 
              end    -- While @@FETCH_STATUS = 0
              
            Close PRLTL_Cr
            Deallocate PRLTL_Cr

            Fetch Next From PDVIT_Cr Into @CodPrd, @IdPolLot, @QtdPdv
          end  -- While @@FETCH_STATUS = 0
          
        Close PDVIT_Cr
        Deallocate PDVIT_Cr
        
--------  FIM SOLICITA CAIXA FECHADA PULMAO --------------------------------------------------------------------------------------------------------------


        -- **************************************************  solicita lotes fracionados por vencimento do PICKING  ******************************************************************
        -- unico volume para fracionados
        Set @NumVol = @NumVol + 1

        -- ajusta volumes fracionados pré-existentes negativados
        Update PDVLT
           Set Num_Vol = @NumVol
         Where Cod_Estabe = @CodEstabe 
           And Cod_Pedido = @CodPed
           And Num_Vol < 0

        if @FlgUndMin = 0
          begin
            Declare PDVIT_Cr Cursor Local Fast_Forward For 
              Select x.Cod_Produt, x.IdPolLot, pr.Qtd_Embalagem, IsNull(pr.Vol_Emb,0), x.QtdFra
                
				From (Select it.Cod_Produt, it.IdPolLot, (it.QtdPdv-IsNull(d.QtdLot,0)) as QtdFra
                        From (Select a.Cod_Produt, 
                                     IdPolLot = Case
                                                  When Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = @CodEstabe and pl.Id_PolCom = a.Id_PolLot and pl.Cod_Produt = a.Cod_Produt) then a.Id_PolLot
                                                  Else 0
                                                End,
                                     sum(IsNull(a.Qtd_Pdv,0)) as QtdPdv
                                From #ARQ_PDVIT a
                               Where IsNull(a.Qtd_Pdv,0) > 0
                               Group by a.Cod_Produt, a.Id_PolLot) it Left Outer Join

                             (Select b.Cod_Produt, 
                                     IdPolLot = Case
                                                  When Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = b.Cod_Estabe and pl.Id_PolCom = b.Id_PolCom and pl.Cod_Produt = b.Cod_Produt) then b.Id_PolCom
                                                  Else 0
                                                End,
                                     sum(IsNull(b.Qtd_Lote,0)) as QtdLot
                                From PDVLT b
                               Where b.Cod_Estabe = @CodEstabe
                                 And b.Cod_Pedido = @CodPed
                                 And IsNull(b.Qtd_Lote,0) > 0 
                                 And IsNull(b.Qtd_CxaFec,0) > 0   
                               Group by b.Cod_Estabe, b.Cod_Produt, b.Id_PolCom) d on (it.Cod_Produt = d.Cod_Produt and it.IdPolLot = d.IdPolLot)
                            
                       Where (it.QtdPdv-IsNull(d.QtdLot,0)) > 0) x  

                     Inner Join PRODU pr on x.Cod_Produt = pr.Codigo
          end
        else
          begin
            -- trabalha com unidade minima
            Declare PDVIT_Cr Cursor Local Fast_Forward For 
              Select x.Cod_Produt, x.IdPolLot, pr.Qtd_Embalagem, IsNull(ap.Vol_Emb/ap.Fat_CnvApr,0), x.QtdFra

                From (Select it.Cod_Produt, it.IdPolLot, (it.QtdPdv-IsNull(d.QtdLot,0)) as QtdFra  -- it.Cod_Estabe, 
                        From (Select a.Cod_Produt, 
                                     IdPolLot = Case
                                                  When Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = @CodEstabe and pl.Id_PolCom = a.Id_PolLot and pl.Cod_Produt = a.Cod_Produt) then a.Id_PolLot
                                                  Else 0
                                                End,
                                     sum(IsNull(a.Qtd_Pdv,0)) as QtdPdv
                                From #ARQ_PDVIT a
                               Where IsNull(a.Qtd_Pdv,0) > 0
                               Group by a.Cod_Produt, a.Id_PolLot) it Left Outer Join
                 
                             (Select b.Cod_Produt,
                                     IdPolLot = Case
                                                  When Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = b.Cod_Estabe and pl.Id_PolCom = b.Id_PolCom and pl.Cod_Produt = b.Cod_Produt) then b.Id_PolCom
                                                  Else 0
                                                End,
                                     sum(IsNull(b.Qtd_Lote,0)) as QtdLot
                                From PDVLT b
                               Where b.Cod_Estabe = @CodEstabe
                                 And b.Cod_Pedido = @CodPed
                                 And IsNull(b.Qtd_Lote,0) > 0 
                                 And IsNull(b.Qtd_CxaFec,0) > 0   
                               Group by b.Cod_Estabe, b.Cod_Produt, b.Id_PolCom) d on (it.Cod_Produt = d.Cod_Produt and it.IdPolLot = d.IdPolLot)

                       Where (it.QtdPdv-IsNull(d.QtdLot,0)) > 0) x  

                     Inner Join PRODU pr on x.Cod_Produt = pr.Codigo
					 Inner Join PRXAP ap on pr.Codigo = ap.Cod_Produt and ap.Flg_Padrao = 1
          end
                 
        Open PDVIT_Cr
        Fetch Next From PDVIT_Cr Into @CodPrd, @IdPolLot, @QtdEmbFec, @pr_VolUniMin, @QtdFra
                           
        While @@FETCH_STATUS = 0
          begin
            -- nao permite negativar estoque fiscal
            if (@BlqEstFisNeg = 1) and (@FlgTipVenFat = 1)
              begin
                -- qtd solicitada anteriormente (cx fexhada)
                Set @QtdSolPulmao = IsNull((Select sum(Qtd_Lote) From PDVLT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed 
                                               And Cod_Produt = @CodPrd And Cod_LocFis = 'PRLTL'),0)
                Set @QtdSldFiscal = dbo.FN_SldFiscalDisponPrd(@CodEstabe,@CodPrd) - @QtdSolPulmao
                if @QtdSldFiscal < 0 Set @QtdSldFiscal = 0
                if @QtdFra > @QtdSldFiscal 
                  Set @QtdFra = @QtdSldFiscal
              end
 
            Set @QtdAteAcu = 0    -- acumulador por produto
           
            -- verifica atendimento lote unico
            Set @CodLotEsp = ''
            Set @QtdLotSel = 0
			if (@cl_FlgBlqLotVarPdv = 1) and 
               Exists(Select 1 From PDVLT WHere Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Cod_Produt = @CodPrd) 
              Set @CodLotEsp = (Select top 1 Cod_Lote From PDVLT WHere Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Cod_Produt = @CodPrd)

            -- fracionados solicita somente pelo vencimento --
            if @to_CodCfoNorInt > 0
              begin
                Declare PRLOT_Cr Cursor Local Fast_Forward For   
                  Select '1' as CodLocEst, lt.OrdDep, lt.Cod_Dep, lt.Dat_Vencim, lt.Cod_Lote, lt.Qtd_SldPra, lt.Fat_CnvAprEmbPad
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldPra=IsNull(l1.Qtd_SldPra,0), Fat_CnvAprEmbPad=IsNull(l1.Fat_CnvAprEmbPad,0) 
                            From PRLOT l1 Inner Join
                                 DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli
                           Where l1.Cod_Estabe = @CodEstabe 
                             And IsNull(l1.Qtd_Saldo,0) > 0 
                             and IsNull(l1.Qtd_SldPra,0) > 0
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Dep, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldPra=IsNull(l2.Qtd_SldPra,0), Fat_CnvAprEmbPad=IsNull(l2.Fat_CnvAprEmbPad,0)
                            From PRLOT l2 
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_Saldo,0) > 0 
                             And IsNull(l2.Qtd_SldPra,0) > 0
                          --And Cod_Dep not in (Select distinct Cod_Dep From DPXGC Where Cod_Estabe = @CodEstabe)) lt Inner Join 
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Inner Join 
                         PRODU pr on lt.Cod_Produt = pr.Codigo Left Outer Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd
					 And ((@CodLotEsp = '') or 
                          ((@CodLotEsp <> '') and (lt.Cod_Lote = @CodLotEsp)))
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     And IsNull(lt.Qtd_Saldo,0) > 0 
                     And IsNull(lt.Qtd_SldPra,0) > 0
                  UNION ALL
                  Select '2' as CodLocEst, lt.OrdDep, lt.Cod_Dep, lt.Dat_Vencim, lt.Cod_Lote, lt.Qtd_SldDep, lt.Fat_CnvAprEmbPad
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldDep=IsNull(l1.Qtd_SldDep,0), Fat_CnvAprEmbPad=IsNull(l1.Fat_CnvAprEmbPad,0) 
                            From PRLOT l1 Inner Join
                                 DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli
                           Where l1.Cod_Estabe = @CodEstabe 
                             And IsNull(l1.Qtd_Saldo,0) > 0 
                             And IsNull(l1.Qtd_SldDep,0) > 0
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Dep, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldDep=IsNull(l2.Qtd_SldDep,0), Fat_CnvAprEmbPad=IsNull(l2.Fat_CnvAprEmbPad,0)
                            From PRLOT l2 
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_Saldo,0) > 0 
                             And IsNull(l2.Qtd_SldDep,0) > 0
                          --And Cod_Dep not in (Select distinct Cod_Dep From DPXGC Where Cod_Estabe = @CodEstabe)) lt Inner Join 
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Inner Join 
                         PRODU pr on lt.Cod_Produt = pr.Codigo Left Outer Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd
					 And ((@CodLotEsp = '') or 
                          ((@CodLotEsp <> '') and (lt.Cod_Lote = @CodLotEsp)))
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     And IsNull(lt.Qtd_Saldo,0) > 0 
                     And IsNull(lt.Qtd_SldDep,0) > 0
                   Order by OrdDep, Dat_Vencim, CodLocEst
              end
            else
              begin
                Declare PRLOT_Cr Cursor Local Fast_Forward For 
                  Select '1' as CodLocEst, lt.OrdDep, lt.Cod_Dep, lt.Dat_Vencim, lt.Cod_Lote, lt.Qtd_SldPra, lt.Fat_CnvAprEmbPad
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldPra=IsNull(l1.Qtd_SldPra,0), Fat_CnvAprEmbPad=IsNull(l1.Fat_CnvAprEmbPad,0) 
                            From PRLOT l1 Inner Join
                                 DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli
                           Where l1.Cod_Estabe = @CodEstabe 
                             And IsNull(l1.Qtd_Saldo,0) > 0 
                             And IsNull(l1.Qtd_SldPra,0) > 0
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Dep, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldPra=IsNull(l2.Qtd_SldPra,0), Fat_CnvAprEmbPad=IsNull(l2.Fat_CnvAprEmbPad,0) 
                            From PRLOT l2 
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_Saldo,0) > 0 
                             And IsNull(l2.Qtd_SldPra,0) > 0
                          --And Cod_Dep not in (Select distinct Cod_Dep From DPXGC Where Cod_Estabe = @CodEstabe)) lt Inner Join 
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Inner Join 
                         PRODU pr on lt.Cod_Produt = pr.Codigo Left Outer Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd
					 And ((@CodLotEsp = '') or 
                          ((@CodLotEsp <> '') and (lt.Cod_Lote = @CodLotEsp)))
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     And IsNull(lt.Qtd_Saldo,0) > 0 
                     And IsNull(lt.Qtd_SldPra,0) > 0
                  UNION ALL
                  Select '2' as CodLocEst, lt.OrdDep, lt.Cod_Dep, lt.Dat_Vencim, lt.Cod_Lote, lt.Qtd_SldDep, lt.Fat_CnvAprEmbPad
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldDep=IsNull(l1.Qtd_SldDep,0), Fat_CnvAprEmbPad=IsNull(l1.Fat_CnvAprEmbPad,0)
                            From PRLOT l1 Inner Join
                                 DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli
                           Where l1.Cod_Estabe = @CodEstabe 
                             And IsNull(l1.Qtd_Saldo,0) > 0 
                             And IsNull(l1.Qtd_SldDep,0) > 0
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Dep, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldDep=IsNull(l2.Qtd_SldDep,0), Fat_CnvAprEmbPad=IsNull(l2.Fat_CnvAprEmbPad,0)
                            From PRLOT l2
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_Saldo,0) > 0 
                             And IsNull(l2.Qtd_SldDep,0) > 0
                             --And Cod_Dep not in (Select distinct Cod_Dep From DPXGC Where Cod_Estabe = @CodEstabe)) lt Inner Join 
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Inner Join 
                         PRODU pr on lt.Cod_Produt = pr.Codigo Left Outer Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd
					 And ((@CodLotEsp = '') or 
                          ((@CodLotEsp <> '') and (lt.Cod_Lote = @CodLotEsp)))
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     And IsNull(lt.Qtd_Saldo,0) > 0 
                     And IsNull(lt.Qtd_SldDep,0) > 0
                   Order by OrdDep, Dat_Vencim, CodLocEst desc
              end
            -------------------------------------------------------------------------------------------------------------------------------------------------------
            Open PRLOT_Cr
            Fetch Next From PRLOT_Cr Into @LocEst, @OrdDep, @CodDep, @DatVct, @CodLot, @SldLot, @FatCnvAprEmbPad

            Set @QtdAteAcu = 0
            
            While (@QtdAteAcu < @QtdFra) and (@@FETCH_STATUS = 0)
              begin
                -- verifica lote unico
                Set @QtdLotSel = @QtdLotSel + 1
                if (@cl_FlgBlqLotVarPdv = 1) and (@QtdLotSel > 1)
                  Break

                Set @QtdAte = @QtdFra - @QtdAteAcu
                -- se o saldo do lote nao atender a qtd.solicitada refazer a solicitacao proporcionalmente
                if @QtdAte > @SldLot
                  begin
                    Set @QtdAte = @SldLot
                  end
                 -- Atualiza saldo do lote
                Set @QtdPraLot = 0
                Set @QtdDepLot = 0
                if @LocEst = '1'
                  Set @QtdPraLot = @QtdAte
                else
                  Set @QtdDepLot = @QtdAte

                Update PRLOT
                   Set Qtd_SolPra = Qtd_SolPra + @QtdPraLot,
                       Qtd_SolDep = Qtd_SolDep + @QtdDepLot
                 Where Cod_Estabe = @CodEstabe 
                   And Cod_Dep = @CodDep
                   And Cod_Produt = @CodPrd
                   And Cod_Lote = @CodLot
 
                Set @QtdAteAcu = @QtdAteAcu + @QtdAte

                -- verifica se lote foi solicitado fora de ordem
                Set @FlgDesord = 0
                if (@DatVct is not Null) and (@cl_QtdMesMinPrzVctLot > 0) and 
                   (Exists(Select Cod_Lote From PRLOT Where Cod_Estabe = @CodEstabe And Cod_Dep = @CodDep And Cod_Produt = @CodPrd And Qtd_Saldo > 0 And Dat_Vencim < @DatVct))
                  Set @FlgDesord = 1
                           
                -- pega endereço de picking do produto
                Select @NumRua = dx.Num_Rua,
                       @NumCol = dx.Num_Col,   
                       @NumNiv = dx.Num_Niv,   
                       @NumApt = dx.Num_Apt,
                       @dx_CodLocFis = dx.Cod_LocFis,
                       @NumEst = ISNULL(z.Num_Esteira,0)   
                  From DPXPR dx Left Outer Join
                       TBZON z on (dx.Cod_Estabe = z.Cod_Estabe and dx.Num_Rua between z.Num_RuaIni and z.Num_RuaFim)
                 Where dx.Cod_Estabe = @CodEstabe
                   And dx.Cod_Dep = @CodDep
                   And dx.Cod_Produt = @CodPrd
                       
                -- grava/regrava registro em PDVLT 
                Set @VolTotIte = (@QtdPraLot+@QtdDepLot)*@pr_VolUniMin

                 -- aqui ??? Id_PolCOm ????
                if not Exists(Select 1 From PDVLT 
                               Where Cod_Estabe = @CodEstabe 
                                 And Cod_Pedido = @CodPed And Num_Vol = @NumVol 
                                 And Cod_Produt = @CodPrd And Cod_Lote = @CodLot)
                  Insert Into PDVLT (Cod_Estabe, Cod_Pedido, Num_Vol, Cod_Produt, Cod_Lote
                                  ,  Qtd_EmbFec, Fat_CnvAprEmbPad, Qtd_Lote, Qtd_CxaFec
                                  ,  Cod_Dep, Num_Esteira, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_LocFis
                                  ,  Qtd_LotePra, Qtd_LoteDep, Vol_TotIte, Id_PolCom, Flg_Desord, Flg_Manual
                                  ,  Cod_FunSep, Transacao)
                             Values (@CodEstabe, @CodPed,    @NumVol, @CodPrd,    @CodLot
                                  ,  @QtdEmbFec, @FatCnvAprEmbPad, 0,        0
                                  ,  @CodDep, @NumEst,     @NumRua, @NumCol, @NumNiv, @NumApt, @dx_CodLocFis
                                  , 0,           0,           0,          0,         @FlgDesord,  0
                                  , 0,          @Now)
                                          
                Update PDVLT
                   Set Qtd_Lote    = IsNull(Qtd_Lote,0)    + @QtdAte,
                       Vol_TotIte  = IsNull(Vol_TotIte,0)  + @VolTotIte,
                       Qtd_LotePra = IsNull(Qtd_LotePra,0) + @QtdPraLot,
                       Qtd_LoteDep = IsNull(Qtd_LoteDep,0) + @QtdDepLot
                 Where Cod_Estabe = @CodEstabe 
                   And Cod_Pedido = @CodPed 
                   And Num_Vol = @NumVol 
                   And Cod_Produt = @CodPrd 
                   And Cod_Lote = @CodLot

                Fetch Next From PRLOT_Cr Into @LocEst, @OrdDep, @CodDep, @DatVct, @CodLot, @SldLot, @FatCnvAprEmbPad

              end  -- While (@QtdAteAcu < @QtdFra) and (@@FETCH_STATUS = 0)
              
            Close PRLOT_Cr
            Deallocate PRLOT_Cr

            Fetch Next From PDVIT_Cr Into @CodPrd, @IdPolLot, @QtdEmbFec, @pr_VolUniMin, @QtdFra
          end    -- While @@FETCH_STATUS = 0
          
        Close PDVIT_Cr
        Deallocate PDVIT_Cr

        -- verifica se necessita conferencia de caixas fechadas em transferencias

        -- verifica se necessita corrigir quantidades do pedido em PDVIT
        Exec PR_Corrige_PDVITxPDVLT @CodEstabe, @CodPed
        if @@error <> 0
          begin
            Rollback Transaction
            Return
          end

        -- normaliza quantidades 1 e 2 entre PDVLT e PDVIT
        if @FlgErr = 0
          Exec PR_NormalizaPDVITxPDVLT @CodEstabe, @CodPed

        -- verifica resultado 
        if @FlgErr = 0
          Exec PR_DivergenciasPDVITxPDVLT @CodEstabe, @CodPed, @FlgErr output, @StrMsg output

        -- reorganiza volumes
        if @FlgErr = 0
          Exec PR_ReorganizaVolumesPDV @CodEstabe, @CodPed


        -- atualiza status PDVCB
        if @FlgErr = 0
          Update PDVCB
             Set Sta_SepLot = 'F'
           Where Cod_Estabe = @CodEstabe
             And Numero = @CodPed

        IF OBJECT_ID('tempdb..#ARQ_PRLTL') IS NOT NULL
          DROP TABLE #ARQ_PRLTL

        IF OBJECT_ID('tempdb..#ARQ_PDVIT') IS NOT NULL
          DROP TABLE #ARQ_PDVIT

      end  -- if @FlgPodeFechar = 1

    if @FlgErr = 1
      begin
        Update PDVCB
           Set Sta_SepLot = null
         Where Cod_Estabe = @CodEstabe
           And Numero = @CodPEd
        RAISERROR(@StrMsg,16,1)
        Rollback Transaction
        Return
      end
    else
      begin
--        Set @DesLoc = '(DEPOIS) PR_SolicitaLotesPDV pedido: '+cast(@CodPed as varchar)
--        Exec PR_Verifica_Divergencia_PRXESxPRLOT_PRLTL @DesLoc, @CodEstabe, 0

        Commit Transaction
      end
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CalcTributItemSaidaECF]
@PCodEstab smallint,
@PSerNot varchar(3),
@PNumNot int,
@PCodPrd int,
@PCodLot varchar(20),
@PNumSeqIte smallint,
@PTipNot varchar(1),
@PDatEmi smalldatetime,
@PCodRegTri int,
@PTipLuc varchar(2),   
@PPerDst numeric(18,4),
@PCodOpe varchar(3),
@PPerDescontoCom numeric(18,8),
@PTipRetImp char(1),
@PFlgCalIcmSbt bit,
@PFlgCalIcmNor bit,
@PFlgCalRepIcm bit,
@PPrcUnitario numeric(18,4),
@PPrcVen numeric(18,4),
@PPrcFab numeric(18,4),
@PPrcMax numeric(18,4),
@PPrcRefFpb numeric(18,4),       -- Pr.Ref.Farmacia Popular
@PPrcUltEnt numeric(18,4),       -- Pr.Ult. Entrada 
@PQtdProduto int,
@PPerDesconto numeric(18,8),
@PVlrDscBonRat numeric(18,4),  -- deconto bonificado
@PVlrDspRat numeric(18,4),
@PVlrIpi numeric(18,4),
@PVlrDscRat numeric(18,4)

AS

SET NOCOUNT ON 

Begin Transaction

Declare @PPrcPon numeric(18,4) = 0

-- variaveis que serão gravadas na NFSIT
Declare @PVlrBasTri numeric(18,4),
        @PCodSt varchar(2),
        @PCodCsosn varchar(3),
        @PClaTri varchar(4),
        @PCodModBasCalIcm char(1),
        @PAlqIcm numeric(18,4),
        @PPerRedBasCalIcm numeric(7,4),
        @PBasIcmNor numeric(18,4),
        @PIcmNor numeric(18,4),
        @PBasRep numeric(18,4),
        @PPerRep numeric(7,4),
        @PVlrRep numeric(18,4),
        @PVlrPrdSub numeric(18,4),
        @PCodModBasCalIcmSbt char(1),
        @PAlqIcmSbt numeric(18,4),
        @PAlqAgrSbt numeric(18,4),
        @PPerRedBasCalIcmSbt numeric(7,4),
        @PBasSub numeric(18,4),
        @PVlrSub numeric(18,4),
        @PBasRes numeric(18,4),
        @PVlrRes numeric(18,4),
        @PVlrDst numeric(18,4),      -- desconto de tributacao (Pernambuco)
        @PBasRecSbt numeric(18,4),
        @PVlrRecSbt numeric(18,4),
        @PBasIcm numeric(18,4),      -- icms tributavel
        @PVlrIcm numeric(18,4),      -- icms tributavel
        @PVlrIse numeric(18,4),
        @PVlrOut numeric(18,4),
        @PBasIpi numeric(18,4),
        @PCstPis varchar(2),
        @PVlrBasPis numeric(18,4),
        @PAlqPis numeric(18,4),
        @PVlrPis numeric(18,4),
        @PCstCof varchar(2),
        @PVlrBasCof numeric(18,4),
        @PAlqCof numeric(18,4),
        @PVlrCof numeric(18,4),
        @PFlgBlqDsc bit,
        @PTipAux varchar(1),
        @PCodCfo smallint,
        @PVlrBasCalSubTriEntMed numeric(18,4),
        @PFlgUsaDebPresum bit,
        @PAlqDebPresum numeric(18,4),
        @PObsNf varchar(200)

-- variaveis de trabalho
Declare @WQtdLoop tinyint, 
        @WClaTriExt varchar(4),
        @WVlrTotIte numeric(18,4),  
        @WVlrRepBru numeric(18,4),
        @WVlrRepBruTab numeric(18,4),
        @WPerRepIcm numeric(7,4),
        @WVlrBasPrdSub numeric(18,4),
        @WVlrMinIcmSbtSaiRedDeb numeric(18,4),
        @WPerRedBasCalIcmExt numeric(7,4),
        @WAlqIcmExt numeric(18,4),
        @WCtrBasCalDeb varchar(1),
        @WCtrBasCalCre varchar(1),
        @WTipPrcBasDebSbt varchar(1),
        @WTipPrcBasCreSbt varchar(1),
        @WTipAgrDebSbt varchar(1),
        @WAlqAgrDeb numeric(18,4),
        @WPerRedBasCalDeb numeric(7,4),
        @WPerLimMinIcmSbtSaiRedDeb numeric(7,4),
        @WTipPrcLimMinBasCalIcmSbtSai varchar(1),
        @WAlqAgrLimMinBasCalIcmSbtSai numeric(18,4),
        @WTipCreSbt varchar(1),
        @WAlqDebSbt numeric(18,4),
        @WFlgImpSbtFnt bit,
        @WPerRedBasCalIcmInt numeric(7,4),
        @WAlqIcmInt numeric(18,4),
        @WLiq numeric(18,4),
        @WCre numeric(18,4),
        @WDebSbt numeric(18,4),
        @WBru numeric(18,4),
        @WBruTab numeric(18,4),
        @WCodCfoNor smallint,
        @WCodCfoSbt smallint,
        @WFlgCalPisCof bit,
		@WCreSbt numeric(18,4),
        @WVlrBasPisCof numeric(18,4),
        @WVlrBasCalMinSubTri numeric(18,4),
        @WFlgUsaDebPresum bit,
        @WAlqDebPresum numeric(18,4),
        @WUfDestin varchar(2)

Declare @pm_FlgIncIpiCalPis bit,
        @pm_FlgExcIcmCalPis bit,
		@em_FlgContriSubstituido bit,
        @em_DesEstado varchar(2)

Declare @pr_Ctrl_Origem varchar(1),
        @pr_Ctrl_Preco varchar(1),
        @pr_Desconto bit,
        @pr_FlgBlqInfPar bit,
        @pr_TipLisPis varchar(1),
        @pr_CodClaFis varchar(8),
        @pr_PrcFab numeric(18,4),
        @pr_PrcVen numeric(18,4),
        @pr_PrcMax numeric(18,4),
        @pr_PrcRefFpb numeric(18,4),
        @pr_PrcUltEnt numeric(18,4),
        @pr_PerDscUltEnt numeric(7,4),
        @pr_VlrBasCalSubTriEntMed numeric(18,4)
        
-- coloca campos de RTXCT na memoria
Declare @rt_ClaTriExt varchar(4),
        @rt_Tip_PrcBasDebSbt char(1),
        @rt_Ctrl_BasCalDebSai char(1),
        @rt_Alq_AgrDebSai numeric(18,4),
        @rt_Per_RedBasCalDebSai numeric(7,4),
        @rt_Per_LimMinIcmSbtSaiRedDeb numeric(7,4),        
        @rt_Tip_CreSbtSai char(1),
        @rt_Tip_PrcLimMinBasCalIcmSbtSai varchar(1),
        @rt_Alq_AgrLimMinBasCalIcmSbtSai numeric(18,4),        
        @rt_Alq_DebSbtSai numeric(18,4),
        @rt_Alq_IcmIntReg numeric(18,4),
        @rt_Per_RedBasCalIntReg numeric(7,4),
        @rt_Tip_PrcBasCreSbtSai char(1),
        @rt_Ctrl_BasCalCreSai char(1),
        @rt_Alq_IcmExtLoc numeric(18,4),
        @rt_Per_RedBasCalExtLoc numeric(7,4),
        @rt_C_PerRepIcmLoc numeric(7,4),
        
        @rt_Tip_PrcBasSbtEnt varchar(1),
        @rt_Ctrl_BasCalDebEnt varchar(1),
        @rt_Alq_AgrDebEnt numeric(18,4),
        @rt_Per_RedBasCalDebEnt numeric(7,4),
        @rt_Tip_CreSbtEnt varchar(1),
        @rt_Alq_DebSbtEnt numeric(18,4),
        @rt_Flg_ImpSbtFntEnt bit, 
        @rt_Alq_IcmIntLoc numeric(18,4),
        @rt_Per_RedBasCalIntLoc numeric(7,4),
        @rt_Tip_PrcBasCreSbtEnt varchar(1),
        @rt_Ctrl_BasCalCreEnt varchar(1),
        @rt_Alq_IcmExtReg numeric(18,4),
        @rt_Per_RedBasCalExtReg numeric(7,4),
        @rt_C_PerRepIcmReg numeric(7,4),
		@rt_Alq_DebPresum numeric(18,4),
        @rg_Flg_UsaDebPresum bit


-- coloca campos de tabelas na memoria
-- ESTAB
Select @em_FlgContriSubstituido = IsNull(Flg_ContriSubstituido,0),
       @em_DesEstado = Des_Estado
  From ESTAB
Where Cod_Estabe = @PCodEstab

-- PARAM
Select @pm_FlgIncIpiCalPis = IsNull(FlgIncIpiCalPis,0),
       @pm_FlgExcIcmCalPis = IsNull(FlgExcIcmCalPis,0)
  From PARAM
Where Cod_Estabe = @PCodEstab

Set @WUfDestin = IsNull((Select Estado 
                           From NFSCB
                          Where Cod_Estabe = @PCodEstab 
                            And Ser_Nota = @PSerNot 
                            And Num_Nota = @PNumNot),'')
if @WUfDestin = ''
  Set @WUfDestin = @em_DesEstado

Set @WQtdLoop = 1
Set @PClaTri = (Select Cod_ClaTri From PRXES Where Cod_Estabe = @PCodEstab And Cod_Produt = @PCodPrd)

LOOP_INICIO:

Set @PVlrBasTri = 0
Set @PCodSt = ''
Set @PCodCsosn = ''
Set @PCodModBasCalIcm = ''
Set @PAlqIcm = 0
Set @PPerRedBasCalIcm = 0
Set @PBasIcmNor = 0
Set @PIcmNor = 0
Set @PPerRep = 0
Set @PBasRep = 0
Set @PVlrRep = 0
Set @PVlrPrdSub = 0
Set @PCodModBasCalIcmSbt = ''
Set @PAlqIcmSbt = 0
Set @PAlqAgrSbt = 0
Set @PPerRedBasCalIcmSbt = 0
Set @PBasSub = 0
Set @PVlrSub = 0
Set @PBasRes = 0
Set @PVlrRes = 0
Set @PVlrDst = 0
Set @PBasRecSbt = 0
Set @PVlrRecSbt = 0
Set @PBasIcm = 0
Set @PVlrIcm = 0
Set @PVlrIse = 0
Set @PVlrOut = 0
Set @PBasIpi = 0
Set @PCstPis = ''
Set @PVlrBasPis = 0
Set @PAlqPis = 0
Set @PVlrPis = 0
Set @PCstCof = ''
Set @PVlrBasCof = 0
Set @PAlqCof = 0
Set @PVlrCof = 0
Set @PFlgUsaDebPresum = 0
Set @PAlqDebPresum = 0
Set @PObsNf = ''

Set @PFlgBlqDsc = 0
Set @PTipAux = null
Set @WVlrRepBru = 0
Set @WVlrRepBruTab = 0
Set @WVlrBasPrdSub = 0



Select @PCodSt = IsNull(rx.Cod_ImpNotSai,''),
       @PCodCsosn = IsNull(rx.Cod_CSOSNSai,''),
       @rt_ClaTriExt = IsNull(rx.Cod_ClaTriExt,''),
       @rt_Tip_PrcBasDebSbt = IsNull(rx.Tip_PrcBasDebSbt,''),
       @rt_Ctrl_BasCalDebSai = IsNull(rx.Ctrl_BasCalDebSai,''),
       @rt_Alq_AgrDebSai = Isnull(rx.Alq_AgrDebSai,0),
       @rt_Per_RedBasCalDebSai = Isnull(rx.Per_RedBasCalDebSai,0),
       @rt_Per_LimMinIcmSbtSaiRedDeb = IsNull(rx.Per_LimMinIcmSbtSaiRedDeb,0),
	   @rt_Tip_PrcLimMinBasCalIcmSbtSai = IsNull(Tip_PrcLimMinBasCalIcmSbtSai,''),
	   @rt_Alq_AgrLimMinBasCalIcmSbtSai = IsNull(Alq_AgrLimMinBasCalIcmSbtSai,0),
       @rt_Tip_CreSbtSai = Isnull(rx.Tip_CreSbtSai,''),
       @rt_Alq_DebSbtSai = Isnull(rx.Alq_DebSbtSai,0),
       @rt_Alq_IcmIntReg = Isnull(rx.Alq_IcmIntReg,0),
       @rt_Per_RedBasCalIntReg = Isnull(rx.Per_RedBasCalIntReg,0),
       @rt_Tip_PrcBasCreSbtSai = IsNull(rx.Tip_PrcBasCreSbtSai,''),
       @rt_Ctrl_BasCalCreSai = IsNull(rx.Ctrl_BasCalCreSai,''),
       @rt_Alq_IcmExtLoc = Isnull(rx.Alq_IcmExtLoc,0),
       @rt_Per_RedBasCalExtLoc = Isnull(rx.Per_RedBasCalExtLoc,0),
       @rt_C_PerRepIcmLoc = Isnull(rx.C_PerRepIcmLoc,0),
       
       @rt_Tip_PrcBasSbtEnt = IsNull(rx.Tip_PrcBasSbtEnt,''),
       @rt_Ctrl_BasCalDebEnt  = IsNull(rx.Ctrl_BasCalDebEnt,''),
       @rt_Alq_AgrDebEnt = Isnull(rx.Alq_AgrDebEnt,0),
       @rt_Per_RedBasCalDebEnt = Isnull(rx.Per_RedBasCalDebEnt,0),
       @rt_Tip_CreSbtEnt = IsNull(rx.Tip_CreSbtEnt,''),
       @rt_Alq_DebSbtEnt = Isnull(rx.Alq_DebSbtEnt,0),
       @rt_Flg_ImpSbtFntEnt = IsNull(rx.Flg_ImpSbtFntEnt,0),
       @rt_Alq_IcmIntLoc = Isnull(rx.Alq_IcmIntLoc,0),
       @rt_Per_RedBasCalIntLoc = Isnull(rx.Per_RedBasCalIntLoc,0),
       @rt_Tip_PrcBasCreSbtEnt = IsNull(rx.Tip_PrcBasCreSbtEnt,''),
       @rt_Ctrl_BasCalCreEnt = IsNull(rx.Ctrl_BasCalCreEnt,''),
       @rt_Alq_IcmExtReg = Isnull(rx.Alq_IcmExtReg,0),
       @rt_Per_RedBasCalExtReg = Isnull(rx.Per_RedBasCalExtReg,0),
       @rt_C_PerRepIcmReg = Isnull(rx.C_PerRepIcmReg,0),
       @rg_Flg_UsaDebPresum = IsNull(rg.Flg_UsaDebPresum,0),
       @rt_Alq_DebPresum = Case 
	                         When IsNull(rg.Flg_UsaDebPresum,0) = 1 then IsNull(rx.Alq_IcmPresumLoc,0) 
							 Else 0 
                           End    
  From RTXCT rx
       Inner Join RGTRI rg on rx.Cod_RegTri = rg.Cod_RegTri
Where rx.Cod_RegTri = @PCodRegTri
and  rx.Cod_ClaTri = @PClaTri

-- CFOP
Select @WCodCfoNor = Isnull(Cod_CfoNorInt,0),       
       @WCodCfoSbt = IsNull(Cod_CfoSbtInt,0),
       @WFlgCalPisCof = IsNull(Flg_CalPisCof,0)
  From TPOPE
Where Cod_Ope = @PCodOpe

-- tipo da nota diferente de devolucao
if @PTipNot <> 'D'
  begin
    -- vendas, outras saidas
	Set @WClaTriExt = @rt_ClaTriExt
    Set @WTipPrcBasDebSbt = @rt_Tip_PrcBasDebSbt
    Set @WCtrBasCalDeb = @rt_Ctrl_BasCalDebSai
    Set @WAlqAgrDeb = @rt_Alq_AgrDebSai
    Set @WPerRedBasCalDeb = @rt_Per_RedBasCalDebSai
    Set @WPerLimMinIcmSbtSaiRedDeb = @rt_Per_LimMinIcmSbtSaiRedDeb
    Set @WTipPrcLimMinBasCalIcmSbtSai = @rt_Tip_PrcLimMinBasCalIcmSbtSai
    Set @WAlqAgrLimMinBasCalIcmSbtSai = @rt_Alq_AgrLimMinBasCalIcmSbtSai     
    Set @WTipCreSbt = @rt_Tip_CreSbtSai
    Set @WAlqDebSbt = @rt_Alq_DebSbtSai
    Set @WFlgImpSbtFnt = 1
    Set @WAlqIcmInt = @rt_Alq_IcmIntReg
    Set @WPerRedBasCalIcmInt = @rt_Per_RedBasCalIntReg
    Set @WTipPrcBasCreSbt = @rt_Tip_PrcBasCreSbtSai
    Set @WCtrBasCalCre = @rt_Ctrl_BasCalCreSai
    Set @WAlqIcmExt = @rt_Alq_IcmExtLoc
    Set @WPerRedBasCalIcmExt = @rt_Per_RedBasCalExtLoc
    Set @WPerRepIcm = @rt_C_PerRepIcmLoc
    Set @WFlgUsaDebPresum = @rg_Flg_UsaDebPresum
    Set @WAlqDebPresum = @rt_Alq_DebPresum
  end
else
  begin
    -- devolucao
	Set @WClaTriExt = ''
    Set @WTipPrcBasDebSbt = @rt_Tip_PrcBasSbtEnt
    Set @WCtrBasCalDeb = @rt_Ctrl_BasCalDebEnt
    Set @WAlqAgrDeb = @rt_Alq_AgrDebEnt
    Set @WPerRedBasCalDeb = @rt_Per_RedBasCalDebEnt
    Set @WPerLimMinIcmSbtSaiRedDeb = 0
    Set @WTipPrcLimMinBasCalIcmSbtSai = ''
    Set @WAlqAgrLimMinBasCalIcmSbtSai = 0
    Set @WTipCreSbt = @rt_Tip_CreSbtEnt
    Set @WAlqDebSbt = @rt_Alq_DebSbtEnt
    Set @WFlgImpSbtFnt = @rt_Flg_ImpSbtFntEnt
    Set @WAlqIcmInt = @rt_Alq_IcmIntLoc
    Set @WPerRedBasCalIcmInt = @rt_Per_RedBasCalIntLoc
    Set @WTipPrcBasCreSbt = @rt_Tip_PrcBasCreSbtEnt
    Set @WCtrBasCalCre = @rt_Ctrl_BasCalCreEnt
    Set @WAlqIcmExt = @rt_Alq_IcmExtReg
    Set @WPerRedBasCalIcmExt = @rt_Per_RedBasCalExtReg
    Set @WPerRepIcm = @rt_C_PerRepIcmReg
    Set @WFlgUsaDebPresum = 0
    Set @WAlqDebPresum = 0
  end

-- coloca campo de PRODU na memoria
Select @pr_Ctrl_Origem = IsNull(p.Cod_OriMer,'0'),
       @pr_Ctrl_Preco = pr.Ctrl_Preco,
       @pr_Desconto = Isnull(p.Flg_BlqDsc,0),
       @pr_FlgBlqInfPar = Isnull(p.Flg_BlqInfPar,0),
       @pr_TipLisPis = pr.Tip_LisPis,
       @pr_CodClaFis = Substring(Ltrim(Rtrim(pr.Cod_ClaFis)),1,8),
       @pr_PrcVen = Isnull(p.Prc_Venda,0),
       @pr_PrcRefFpb = Isnull(pr.Prc_RefFpb,0),
       @pr_PrcUltEnt = Isnull(p.Prc_UltEnt,0),
       @pr_PerDscUltEnt = Isnull(p.Per_DscUltEnt,0),
	   @pr_VlrBasCalSubTriEntMed = IsNull(p.Vlr_BasCalSubTriEntMed,0),
       @pr_PrcFab = Case
                      When (Round(@WAlqIcmInt,2) = 12.00) and (IsNull(pr.Prc_Fabric12,0)  > 0) Then IsNull(pr.Prc_Fabric12,0)
                      When (Round(@WAlqIcmInt,2) = 17.00) and (IsNull(pr.Prc_Fabric17,0)  > 0) Then IsNull(pr.Prc_Fabric17,0)
                      When (Round(@WAlqIcmInt,2) = 17.50) and (IsNull(pr.Prc_Fabric175,0) > 0) Then IsNull(pr.Prc_Fabric175,0)
                      When (Round(@WAlqIcmInt,2) = 18.00) and (IsNull(pr.Prc_Fabric18,0)  > 0) Then IsNull(pr.Prc_Fabric18,0)
                      When (Round(@WAlqIcmInt,2) = 19.00) and (IsNull(pr.Prc_Fabric19,0)  > 0) Then IsNull(pr.Prc_Fabric19,0)
                      When (Round(@WAlqIcmInt,2) = 20.00) and (IsNull(pr.Prc_Fabric20,0)  > 0) Then IsNull(pr.Prc_Fabric20,0)
                      When (Round(@WAlqIcmInt,2) = 21.00) and (IsNull(pr.Prc_Fabric21,0)  > 0) Then IsNull(pr.Prc_Fabric21,0)
                      When (Round(@WAlqIcmInt,2) = 22.00) and (IsNull(pr.Prc_Fabric22,0)  > 0) Then IsNull(pr.Prc_Fabric22,0)
                      Else Isnull(p.Prc_Fabric,0)
                    End,
       @pr_PrcMax = Case
                      When (Round(@WAlqIcmInt,2) = 12.00) and (IsNull(pr.Prc_MaxCon12,0)  > 0) Then IsNull(pr.Prc_MaxCon12,0)
                      When (Round(@WAlqIcmInt,2) = 17.00) and (IsNull(pr.Prc_MaxCon17,0)  > 0) Then IsNull(pr.Prc_MaxCon17,0)
                      When (Round(@WAlqIcmInt,2) = 17.50) and (IsNull(pr.Prc_MaxCon175,0) > 0) Then IsNull(pr.Prc_MaxCon175,0)
                      When (Round(@WAlqIcmInt,2) = 18.00) and (IsNull(pr.Prc_MaxCon18,0)  > 0) Then IsNull(pr.Prc_MaxCon18,0)
                      When (Round(@WAlqIcmInt,2) = 19.00) and (IsNull(pr.Prc_MaxCon19,0)  > 0) Then IsNull(pr.Prc_MaxCon19,0)
                      When (Round(@WAlqIcmInt,2) = 20.00) and (IsNull(pr.Prc_MaxCon20,0)  > 0) Then IsNull(pr.Prc_MaxCon20,0)
                      When (Round(@WAlqIcmInt,2) = 21.00) and (IsNull(pr.Prc_MaxCon21,0)  > 0) Then IsNull(pr.Prc_MaxCon21,0)
                      When (Round(@WAlqIcmInt,2) = 22.00) and (IsNull(pr.Prc_MaxCon22,0)  > 0) Then IsNull(pr.Prc_MaxCon22,0)
                      Else Isnull(p.Prc_MaxCon,0)
                    End
  From PRXES p Inner Join PRODU pr on p.Cod_Produt = pr.Codigo
Where p.Cod_Estabe = @PCodEstab
And p.Cod_Produt = @PCodPrd

if @PPrcVen = 0
  Set @PPrcVen = @pr_PrcVen
if @PPrcRefFpb = 0
  Set @PPrcRefFpb = @pr_PrcRefFpb
if @PPrcFab = 0
  Set @PPrcFab = @pr_PrcFab
if @PPrcMax = 0
  Set @PPrcMax = @pr_PrcMax
  
if @PPrcFab <> @pr_PrcFab 
  Set @PPrcFab = @pr_PrcFab
if @PPrcMax <> @pr_PrcMax  
  Set @PPrcMax = @pr_PrcMax
  
Set @PVlrBasCalSubTriEntMed = @pr_VlrBasCalSubTriEntMed

if @PPrcPon = 0
  Set @PPrcPon = (Select dbo.FN_PrcMedPonFin (@WUfDestin,@PCodPrd,@PDatEmi))

-- verifica se utiliza classificação tributária extra (uma unica vez)
if (@PFlgCalIcmSbt = 1) and 
   (((@WTipPrcBasDebSbt = 'D') and (@PPrcPon = 0)) or
    ((@WTipPrcBasDebSbt = 'M') and (@PPrcMax = 0))) and
   (@WClaTriExt <> '') and
   (@PClaTri <> @WClaTriExt) and
   (@WQtdLoop = 1)
  begin
    Set @WQtdLoop = @WQtdLoop + 1
    Set @PClaTri = @WClaTriExt
    GOTO LOOP_INICIO
  end


-- calcula repasse para futuros calculos
-- repasse de ICMS se houver diferenca de aliquotas
-- e somente cipados ou liberados c/ repasse
Set @WVlrTotIte = Round(@PPrcUnitario * @PQtdProduto * (1-@PPerDesconto/100),2)

Set @PPerRep = @WPerRepIcm
 
if (@PFlgCalIcmNor = 1) or (@PFlgCalIcmSbt = 1)
  if (@PFlgCalRepIcm = 1) and (@PPerRep <> 0) and (@pr_Ctrl_Preco <> 'L')
    begin
      -- repasse liquido
      Set @PBasRep = @WVlrTotIte + @PVlrDspRat
      Set @PVlrRep = @PBasRep * @PPerRep / 100
      -- repasse bruto
      Set @WVlrRepBru = Round(@PPrcUnitario * @PQtdProduto * @PPerRep / 100,2)
      Set @WVlrRepBruTab = Round(@PPrcVen * @PQtdProduto * @PPerRep / 100,2)
      if @PVlrRep = 0
        Set @PBasRep = 0
    end

-- valor liquido do item
Set @WLiq = @WVlrTotIte - @PVlrRep
                        
-- desconto cabecalho
Set @PFlgBlqDsc = @pr_Desconto
                        
Set @WLiq =  @WLiq - @PVlrDscRat - @PVlrDscBonRat 
                        
-- o calculo abaixo devera ser excluido com a despesa estiver realmente rateada no item
Set @WLiq = Round(@WLiq + @PVlrDspRat,2)

if @PVlrIpi > 0
  Set @PBasIpi = @WLiq

-- registra icms proprio, icms tributavel da operacao se DEB/CRE ou SUB.TRIB.
Set @WCre = 0
Set @PPerRedBasCalIcm = @WPerRedBasCalIcmExt
Set @PBasIcmNor = Round(@WLiq * (1 - @PPerRedBasCalIcm/100),2)
Set @PAlqIcm = @WAlqIcmExt
Set @PIcmNor = @WLiq * (1 - @PPerRedBasCalIcm/100) * @PAlqIcm / 100
if @PIcmNor = 0
  Set @PBasIcmNor = 0
  
if (@PFlgCalIcmNor = 1) or (@PFlgCalIcmSbt = 1)
  begin
    -- credito com reducao da base de calculo
    Set @WCre = @PIcmNor
    if @WCre > 0
      Set @PCodModBasCalIcm = '3'  -- ICMS sobre Valor da operação
  end

-- calcula icms tributavel (debito/credito)
if (@PFlgCalIcmNor = 1) and (@WTipPrcBasDebSbt = 'X')   -- nao eh subst.tributaria
  begin
    Set @PBasIcm = @PBasIcmNor
    Set @PVlrIcm = @PIcmNor
    Set @PFlgUsaDebPresum = @WFlgUsaDebPresum
    Set @PAlqDebPresum = @WAlqDebPresum
  end

-- ver se eh ST sem retencao
if @WTipPrcBasDebSbt = 'O'
  begin
    Set @PVlrPrdSub = 0
    Set @PAlqIcmSbt = 0
    Set @PAlqAgrSbt = 0
    Set @PPerRedBasCalIcmSbt = 0
    Set @PBasSub = 0
    Set @PVlrSub = 0
--    Set @PBasIcmNor = 0
--    Set @PIcmNor = 0 
    Set @PBasIcm = 0
    Set @PVlrIcm = 0 
    Set @PVlrIse = 0
    Set @PVlrOut = @WLiq
    Set @PCodModBasCalIcm = ''
    Set @PCodModBasCalIcmSbt = ''
    Set @PFlgUsaDebPresum = @WFlgUsaDebPresum
    Set @PAlqDebPresum = @WAlqDebPresum
end
  
-- Calcula Substituicao Tributaria
if (@PFlgCalIcmSbt = 1) and (@WTipPrcBasDebSbt <> 'X') and (@WTipPrcBasDebSbt <> 'O')
  begin
    -- debito presumido p/ uso no calculo de rentabilidade
    Set @PFlgUsaDebPresum = 0
    Set @PAlqDebPresum = 0

    -- valor bruto do item
    Set @WBru = Round(@PPrcUnitario * @PQtdProduto - @WVlrRepBru + @PVlrDspRat,2)
    
    if @WCtrBasCalDeb = 'B'  -- pelo vlr. bruto
      begin
        if @WTipPrcBasDebSbt = 'D'           -- utiliza PMMF do cadastro
          Set @WVlrBasPrdSub = @PPrcPon * @PQtdProduto
        else
        if @WTipPrcBasDebSbt = 'M'           -- utiliza P.M.C. do cadastro
          Set @WVlrBasPrdSub = @PPrcMax * @PQtdProduto
        else
        if @WTipPrcBasDebSbt = 'F'            -- utiliza preco fabrica do cadastro
          Set @WVlrBasPrdSub = @PPrcFab * @PQtdProduto
        else
        if @WTipPrcBasDebSbt = 'P'            -- utiliza preco ref fcia popular
          Set @WVlrBasPrdSub = @PPrcRefFpb * @PQtdProduto
        else
        if @WTipPrcBasDebSbt = 'V'            -- utiliza preco venda do cadastro
          Set @WVlrBasPrdSub = @PPrcVen * @PQtdProduto - @WVlrRepBruTab
        else
        if @WTipPrcBasDebSbt = 'C'            -- utiliza preco compra do cadastro
          Set @WVlrBasPrdSub = @PPrcUltEnt * @PQtdProduto
        else
          Set @WVlrBasPrdSub = @WBru   --/ transacao
      end
    else
      Set @WVlrBasPrdSub = @WLiq
          
    -- Valor base da ST: agregacao, reducao e aliquota 
    Set @PAlqAgrSbt = @WAlqAgrDeb
    Set @PPerRedBasCalIcmSbt = @WPerRedBasCalDeb

    Set @PVlrPrdSub = @WVlrBasPrdSub * (1 - @PPerRedBasCalIcmSbt/100)
    Set @PBasSub = @PVlrPrdSub * (1 + @PAlqAgrSbt/100)

    -- verifica limitador B.C.ST
    Set @WVlrBasCalMinSubTri = 0
    if @WTipPrcLimMinBasCalIcmSbtSai = 'E'
      begin
        -- média da B.C. de Entrada + Agreg.
        Set @WVlrBasCalMinSubTri = Round(@PVlrBasCalSubTriEntMed * @PQtdProduto * (1 + @WAlqAgrLimMinBasCalIcmSbtSai/100),2)
      end
    if @PBasSub < @WVlrBasCalMinSubTri
      Set @PBasSub = @WVlrBasCalMinSubTri

    -- ver se utiliza no calculo da ST % fixo sobre preco do produto
    if @WTipCreSbt = 'F'
      begin
        Set @PAlqIcmSbt = @WAlqDebSbt
        Set @PVlrSub = @PBasSub * @PAlqIcmSbt / 100
        if @PAlqAgrSbt = 0
          Set @PCodModBasCalIcmSbt = '0'  -- preco tabela ou maximo sugerido
        else
          Set @PCodModBasCalIcmSbt = '4'
      end
    else
      -- calcula subst.tributaria com agregacao      
      begin
        -- debito com red. base de calculo icms
        Set @PAlqIcmSbt = @WAlqIcmInt
        Set @WDebSbt = @PBasSub * @PAlqIcmSbt / 100   

        -- desconto comercial concedido por subst.trib.
        if @PPerDst > 0
          begin
            Set @PVlrDst = @PVlrPrdSub * @PPerDst / 100
            Set @WLiq = Round(@WLiq - @PVlrDst,2)
            Set @WCre = @WLiq * (1 - @PPerRedBasCalIcm/100) * @PAlqIcm / 100
            Set @PBasIcmNor = Round(@WLiq * (1 - @PPerRedBasCalIcm/100),2)
            Set @PIcmNor = @WCre
            if @PIcmNor  = 0
              Set @PBasIcmNor = 0
            else
              Set @PCodModBasCalIcm = '3'  -- ICMS sobre Valor da operação
          end

        -- credito
        if @WCtrBasCalCre = 'B'         -- credito pelo vlr.bruto
          begin
            if @WTipPrcBasCreSbt = 'F'      -- utiliza preco fabrica do cadastro
              Set @WCreSbt = @PPrcFab * @PQtdProduto
            else
            if @WTipPrcBasCreSbt = 'V'     -- utiliza preco venda do cadastro
              Set @WCreSbt = @PPrcVen * @PQtdProduto - @WVlrRepBruTab
            else
              Set @WCreSbt = @WBru              -- transacao
                -- credito com red.base de calculo
             Set @WCreSbt = @WCreSbt * (1 - @PPerRedBasCalIcm/100) * @PAlqIcm / 100
          end
        else
          Set @WCreSbt = @WCre

        -- calcula icm subst.
        Set @PVlrSub = @WDebSbt - @WCreSbt

--        if (@WTipPrcBasDebSbt = 'M') or (@WTipPrcBasDebSbt = 'P')
        if @PAlqAgrSbt = 0
          Set @PCodModBasCalIcmSbt = '0'  -- preco tabela ou maximo sugerido
        else
          Set @PCodModBasCalIcmSbt = '4'  -- Margem Valor Agregado (%)
            
      end  -- calcula subst.tributaria com agregacao
          
    -- verifica limitador ST
    Set @WVlrMinIcmSbtSaiRedDeb = 0
    if (@PPerRedBasCalIcmSbt > 0) and (@WPerLimMinIcmSbtSaiRedDeb > 0) 
      Set @WVlrMinIcmSbtSaiRedDeb = @PBasSub*@WPerLimMinIcmSbtSaiRedDeb/100

    if (@PVlrSub > 0) and (@PVlrSub < @WVlrMinIcmSbtSaiRedDeb)
      begin
        -- desconsidera reducao na base de calculo
        Set @PPerRedBasCalIcmSbt = 0
        Set @PVlrPrdSub = @WVlrBasPrdSub
        Set @PBasSub = @PVlrPrdSub * (1 + @PAlqAgrSbt/100)
        Set @WDebSbt = @PBasSub * @PAlqIcmSbt / 100   
        Set @PVlrSub = @WDebSbt - @WCreSbt
      end
            
    if Round(@PVlrSub,2) <= 0
      begin
--        Set @PAlqIcmSbt = 0
--        Set @PAlqAgrSbt = 0
--        Set @PPerRedBasCalIcmSbt = 0
--        Set @PBasSub = 0
        Set @PVlrSub = 0
--        Set @PVlrPrdSub = 0
--        Set @PBasIcm = 0
--        Set @PVlrIcm = 0
--        Set @PVlrIse = 0
--        Set @PVlrOut = 0
--        Set @PCodModBasCalIcmSbt = ''

        -- CST sujeitas a ST 10;30;70;
        if Charindex(@PCodSt,';10;70;') > 0 
          begin
            Set @PBasIcm = @PBasIcmNor
            Set @PVlrIcm = @PIcmNor 
--            if @PCodSt = '70'
--              Set @PCodSt = '20' 
--            else
--              Set @PCodSt = '00' 
          end
        else
          begin
            Set @PVlrOut = @PBasIcmNor
--            if @PCodSt = '30'
--              Set @PCodSt = '40' 
          end
      end  -- if @PVlrSub <= 0
          
  end  -- fim Calculo Substituicao Tributaria
  
-- se a ST nao for retida na fonte
if (@WFlgImpSbtFnt = 0) and (@PVlrSub > 0)
  begin
    Set @PAlqIcmSbt = 0
    Set @PAlqAgrSbt = 0
    Set @PPerRedBasCalIcmSbt = 0
    Set @PBasSub = 0
    Set @PVlrSub = 0
    Set @PVlrPrdSub = 0

    if @PPerRedBasCalIcm > 0 
      Set @PCodSt = '20' 
    else
      Set @PCodSt = '00' 
    Set @PBasIcm = @PBasIcmNor
    Set @PVlrIcm = @PIcmNor 
  end

-- nao houve tributacao qualquer
-- if (@PFlgCalIcmNor = 0) and (@PFlgCalIcmSbt = 0)
--   begin
--     Set @PVlrOut = @PBasIcmNor
--     Set @PCodSt = '41'
--    end Albani Comentou: Para obedecer o que está na tributação do produto
  
-- CST sujeitas a ST 10;30;70;
if (@PVlrSub = 0) and (Charindex(@PCodSt,';10;30;70;') > 0) 
  if Charindex(@PCodSt,';10;70;') > 0 
    begin
      Set @PBasIcm = @PBasIcmNor
      Set @PVlrIcm = @PIcmNor 
      if @PBasSub = 0
        if @PCodSt = '70'
          Set @PCodSt = '20' 
        else
          Set @PCodSt = '00' 
    end
  else
    begin
      Set @PVlrOut = @PBasIcmNor
      if @PBasSub = 0
        if @PCodSt = '30'
          Set @PCodSt = '40' 
    end

--ajusta ressarcimento ST
if (@PCodSt = '60') and (@PVlrSub > 0)
  begin
    Set @PBasRes = @PBasSub
    Set @PVlrRes = @PVlrSub
    Set @PBasSub = 0 
    Set @PVlrSub = 0 
  end

-- exige tributacao icm
if Charindex(@PCodSt,';00;10;20;51;70;90;') > 0  -- if Charindex(@PCodSt,';00;10;20;70;90;') > 0 
  begin
    Set @PBasIcm = @PBasIcmNor
    Set @PVlrIcm = @PIcmNor 
  end
  
-- nao exige tributacao icm
if Charindex(@PCodSt,';30;40;41;50;60;') > 0   -- if Charindex(@PCodSt,';30;40;41;50;51;60;') > 0 
  begin
    Set @PBasIcm = 0
    Set @PVlrIcm = 0
  end
  
if (@PVlrIse = 0) and (@PVlrSub = 0) and (@PVlrRes = 0) and (@PVlrIcm = 0) and (@PVlrOut = 0)
  if (@PFlgCalIcmNor = 1) or (@PFlgCalIcmSbt = 1)
    Set @PVlrIse = @WLiq
  else
    Set @PVlrOut = @WLiq

if Round(@PVlrIse,2) > 0
  if @PAlqIcm = 0
    begin
      Set @PBasIcmNor = 0
      Set @PIcmNor = 0
      Set @PBasIcm = 0
      Set @PVlrIcm = 0 
      Set @PVlrOut = 0
      Set @PCodSt = '40'
    end

-- ICM presumido
if (@PVlrIcm > 0) and (@PFlgUsaDebPresum = 0)
  begin
    Set @PFlgUsaDebPresum = @WFlgUsaDebPresum
    Set @PAlqDebPresum = @WAlqDebPresum
  end

Set @PVlrOut = Round(@WLiq - @PVlrIse - @PBasIcm,2)
if @PVlrOut < 0
  Set @PVlrOut = 0
if @PVlrOut > @WLiq
  Set @PVlrOut = @WLiq 

-- ajusta Cod.Modalidade base de calculo icm sbt
if @PVlrSub > 0
  if @PAlqAgrSbt = 0
    Set @PCodModBasCalIcmSbt = '0'  -- preco tabela ou maximo sugerido
  else
    Set @PCodModBasCalIcmSbt = '4'
else
  Set @PCodModBasCalIcmSbt = ''

if Charindex(@PCodSt,';30;40;41;50;60;') > 0 
  Set @PCodModBasCalIcm = ''
if Charindex(@PCodSt,';00;20;40;41;50;51;60;') > 0 
  Set @PCodModBasCalIcmSbt = ''
  
Set @PVlrBasTri = @WLiq

if Charindex(@PCodSt,';00;40;41;') > 0
  Set @PCodCfo = @WCodCfoNor
else if Charindex(@PCodSt,';60;') > 0
  Set @PCodCfo = @WCodCfoSbt
else
  Set @PCodCfo = @WCodCfoNor
  
-- pis/cofins
Set @WVlrBasPisCof = @WLiq

-- ressarcimento
if @PVlrRes > 0
  Set @WVlrBasPisCof = Round(@WLiq+@PVlrRes,2)

-- ipi
if @pm_FlgIncIpiCalPis = 1  
  Set @WVlrBasPisCof = @WVlrBasPisCof + @PVlrIpi
  
-- exclui icm destacado
if @pm_FlgExcIcmCalPis = 1
  Set @WVlrBasPisCof = @WVlrBasPisCof - @PVlrIcm

Exec PR_CalculaPisCofins @PCodEstab, @WFlgCalPisCof, 'S', @PTipLuc, @PDatEmi, @PCodCfo, 0, @pr_CodClaFis, @pr_TipLisPis, @WVlrBasPisCof, 
                         @PCstPis output, @PVlrBasPis output, @PAlqPis output, @PVlrPis output,
                         @PCstCof output, @PVlrBasCof output, @PAlqCof output, @PVlrCof output, @PObsNf output

-- grava valores em NFSIT
Set @pr_FlgBlqInfPar = 0
Update NFSIT
   Set Tip_Aux = @pr_TipLisPis,
       Flg_BlqDsc = @PFlgBlqDsc,
       Flg_BlqInfPar = @pr_FlgBlqInfPar,
       Cod_Cfo = @PCodCfo,
       Ctrl_Tributacao = @PCodSt,
       Cod_CSOSN = @PCodCsosn,
       Cod_Tribut = @pr_Ctrl_Origem+@PCodSt,
       Cod_ClaTri = @PClaTri,

       Prc_TabBru = @PPrcVen,
       Prc_Fabric = @PPrcFab,
       Prc_PonFin = @PPrcPon,
       Prc_MaxCon = @PPrcMax,
       Prc_RefFpb = @PPrcRefFpb,
       Prc_LiqUltEnt = @PPrcUltEnt,
       Vlr_BasCalSubTriEntMed = @PVlrBasCalSubTriEntMed, 

       Vlr_BasTri = @PVlrBasTri,
       Cod_ModBasCalIcm = @PCodModBasCalIcm,

       Alq_Icms = @PAlqIcm,
       Per_RedBasCalIcm = @PPerRedBasCalIcm,
       Vlr_BasIcmsNor = Round(@PBasIcmNor,2),
       Vlr_IcmsNor = @PIcmNor,
       Flg_UsaDebPresum = @PFlgUsaDebPresum,
       Alq_IcmPresum = @PAlqDebPresum,

       Vlr_BasRepIcms = Round(@PBasRep,2),
       Per_RepIcms = @PPerRep,
       Vlr_RepIcms = @PVlrRep,

       Vlr_PrdSubTri = Round(@PVlrPrdSub,2),
       Cod_ModBasCalIcmSbt = @PCodModBasCalIcmSbt,
       Alq_IcmSbt = @PAlqIcmSbt,
       Alq_AgrSbt = @PAlqAgrSbt,
       Per_RedBasCalIcmSbt = @PPerRedBasCalIcmSbt,
       Vlr_BasSubsTrib = Round(@PBasSub,2),
       Vlr_SubsTrib = @PVlrSub,
       Vlr_BasSbtRes = Round(@PBasRes,2),
       Vlr_SbtRes = @PVlrRes,
       Vlr_DscTri = @PVlrDst,
       Vlr_BasRecSbt = Round(@PBasRecSbt,2),
       Vlr_RecSbt = @PVlrRecSbt,
       Vlr_BasIcmsTri = Round(@PBasIcm,2),
       Vlr_IcmsTri = @PVlrIcm,
       Vlr_Isento = Round(@PVlrIse,2),
       Vlr_Outros = Round(@PVlrOut,2),
       Vlr_BasIpi = Round(@PBasIpi,2),

       CST_Pis = @PCstPis, 
       Vlr_BasPis = @PVlrBasPis, 
       Alq_Pis = @PAlqPis, 
       Vlr_Pis = @PVlrPis, 
       CST_Cofins = @PCstCof, 
       Vlr_BasCofins = @PVlrBasCof, 
       Alq_Cofins = @PAlqCof, 
       Vlr_Cofins = @PVlrCof,
       Obs_Nf = @PObsNf

 Where Cod_Estabe = @PCodEstab 
   And Ser_Nota = @PSerNot 
   And Num_Nota = @PNumNot And Cod_Produto = @PCodPrd 
   And Cod_Lote = @PCodLot And Num_SeqIte = @PNumSeqIte

Update NFSIT
   Set Vlr_LiqVenIte = Round(Qtd_Produto * Prc_Unitario*(1-Per_Desconto/100),2) -- IsNull(Vlr_TotItem,0) 
                     - IsNull(Vlr_RepIcms,0) - Isnull(Vlr_DescRateado,0) - IsNull(Vlr_DscBonRat,0) - IsNull(Vlr_DscTri,0),

       Vlr_LiqItem = Round(Qtd_Produto * Prc_Unitario*(1-Per_Desconto/100),2) --IsNull(Vlr_TotItem,0) 
                   - IsNull(Vlr_RepIcms,0) - Isnull(Vlr_DescRateado,0) - IsNull(Vlr_DscBonRat,0) - IsNull(Vlr_DscTri,0)
                   + IsNull(Vlr_SubsTrib,0) + IsNull(Vlr_SbtRes,0) + IsNull(Vlr_RecSbt,0) + IsNull(Vlr_Ipi,0) + Isnull(Vlr_DespRateada,0)  + Isnull(Vlr_DspExt,0)
 Where Cod_Estabe = @PCodEstab 
   And Ser_Nota = @PSerNot 
   And Num_Nota = @PNumNot And Cod_Produto = @PCodPrd 
   And Cod_Lote = @PCodLot And Num_SeqIte = @PNumSeqIte

if (@PTipRetImp = 'R') and (@PVlrSub > 0)
  begin
    if Charindex(@PCodSt,';10;30;70;') > 0
      begin
        if @PVlrIcm > 0
          if @PPerRedBasCalIcm > 0
            Set @PCodSt = '20'    -- tributacao com reducao
          else
            Set @PCodSt = '00'    -- tributacao integral
        else
          Set @PCodSt = '41'    -- nao tributada
      end
    Set @PCodCfo = @WCodCfoNor
    Set @PBasRecSbt = @PBasSub
    Set @PVlrRecSbt = @PVlrSub - @PVlrDst
    Set @PBasSub = 0 
    Set @PVlrSub = 0
    Set @PVlrDst = 0

    Update NFSIT
       Set Cod_Cfo = Case 
                       When (Cod_Cfo = 5910) or (Cod_Cfo = 6910) Then Cod_Cfo
                       Else @PCodCfo
                     End,
           Vlr_BasSubsTrib = Round(@PBasSub,2),
           Vlr_SubsTrib = @PVlrSub,
           Vlr_BasSbtRes = Round(@PBasRes,2),
           Vlr_SbtRes = @PVlrRes,
           Vlr_DscTri = @PVlrDst,
           Vlr_BasRecSbt = Round(@PBasRecSbt,2),
           Vlr_RecSbt = @PVlrRecSbt
     Where Cod_Estabe = @PCodEstab 
       And Ser_Nota = @PSerNot 
       And Num_Nota = @PNumNot And Cod_Produto = @PCodPrd 
       And Cod_Lote = @PCodLot And Num_SeqIte = @PNumSeqIte
  end

Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CalcTributSTRetAntNFECB]
@PCodEstabe int,
@PNumPrt int

AS

SET NOCOUNT ON

--if (Select Status from NFSCB Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumPrt) <> 'A'
--  RAISERROR('Nota não está em "Aberto"',16,1)
--else
BEGIN
  Begin Transaction

    -- zera valores 
	Update NFEIT
	  Set Xml_vBCSTRet = 0,
          Xml_pST = 0,
          Xml_vICMSSubstituto = 0,
          Xml_vICMSSTRet = 0,
          Xml_vBCFCPSTRet = 0,
          Xml_pFCPSTRet = 0,
          Xml_vFCPSTRet = 0,
          Xml_pRedBCEfet = 0,
          Xml_vBCEfet = 0,
          Xml_pICMSEfet = 0,
          Xml_vICMSEfet = 0
      Where Cod_Estabe = @PCodEstabe 
	  And Protocolo = @PNumPrt

    Declare @cb_DatMov datetime,
            @it_CodPrd int,
            @it_CodLot varchar(20),
            @it_NumSeqIte int,
            @it_QtdEnt int,
            @it_PerRedBasCalIcm numeric(9,4), 
            @it_VlrBasIcmPro numeric(18,4),
            @it_VlrIcmPro numeric(18,4),
            @it_AlqIcmPro numeric(9,4),
			@WFator numeric(18,8),
            @ns_SerNot varchar(3),
            @ns_NumNot int,
            @ns_CodLot varchar(20),
            @ns_NumSeqIte int,
            @ns_VlrBasSbtRet numeric(18,4),
            --@ns_AlqIcmPro numeric(9,4),
            @ns_VlrIcmPro numeric(18,4),
            @ns_AlqIcmDeb numeric(18,4), 
            @ns_VlrSbtRet numeric(18,4),
            @ns_VlrBasFCPSbtRet numeric(18,4),
            @ns_AlqFCPSbtRet numeric(9,4),
            @ns_VlrFCPSbtRet numeric(18,4)

    Set @cb_DatMov = (Select Dat_Movimento From NFECB Where Cod_Estabe = @PCodEstabe and Protocolo = @PNumPrt)

    Declare NFEIT_Cr Cursor Local Fast_Forward For 

      Select Cod_Produto, Cod_Lote, Num_SeqIte, QtdSai=IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0),
             IsNull(Per_RedBasCalIcm,0), IsNull(Vlr_BasIcmsNor,0), IsNull(Vlr_IcmsNor,0), IsNull(Alq_Icms,0)
        From NFEIT
      Where Cod_Estabe = @PCodEstabe 
      and Protocolo = @PNumPrt
      and ((Ctrl_Tributacao = '60') or (Cod_CSOSN = '500'))

    Open NFEIT_Cr
    Fetch Next From NFEIT_Cr Into @it_CodPrd, @it_CodLot, @it_NumSeqIte, @it_QtdEnt,
                                  @it_PerRedBasCalIcm, @it_VlrBasIcmPro, @it_VlrIcmPro, @it_AlqIcmPro
    While @@FETCH_STATUS = 0
      begin
        Set @ns_SerNot = ''
        Set @ns_NumNot = 0
        Set @ns_CodLot = ''

        if Exists(Select 1
                  From NFSCB cb
                       Inner Join NFSIT it on (cb.Cod_Estabe = it.Cod_Estabe) and (cb.Ser_Nota = it.Ser_Nota)  and (cb.Num_Nota = it.Num_Nota)
                  Where cb.Cod_Estabe = @PCodEstabe
                  And cb.Status = 'F'
                  And cb.Tip_Saida <> 'D'
                  And it.Cod_Produto = @it_CodPrd
                  And it.Cod_Lote = @it_CodLot
                  And cb.Dat_Emissao <= @cb_DatMov
                  And (IsNull(cb.Vlr_SubsTrib,0)+Isnull(cb.Vlr_RecSbt,0)+IsNull(cb.Vlr_SbtRes,0)+IsNull(it.vICMSSTRet,0)) > 0) 
          Select top 1 @ns_SerNot = cb.Ser_Nota, @ns_NumNot = cb.Num_Nota, @ns_CodLot = it.Cod_Lote, @ns_NumSeqIte = it.Num_SeqIte
          From NFSCB cb
               Inner Join NFSIT it on (cb.Cod_Estabe = it.Cod_Estabe) and (cb.Ser_Nota = it.Ser_Nota)  and (cb.Num_Nota = it.Num_Nota)
          Where cb.Cod_Estabe = @PCodEstabe
          And cb.Status = 'F'
          And cb.Tip_Saida <> 'D'
          And it.Cod_Produto = @it_CodPrd
          And it.Cod_Lote = @it_CodLot
          And cb.Dat_Emissao <= @cb_DatMov
          And (IsNull(cb.Vlr_SubsTrib,0)+Isnull(cb.Vlr_RecSbt,0)+IsNull(cb.Vlr_SbtRes,0)+IsNull(it.vICMSSTRet,0)) > 0 
		  Order by cb.Dat_Emissao desc, it.Qtd_Produto desc
        else
        if Exists(Select 1
                  From NFSCB cb
                       Inner Join NFSIT it on (cb.Cod_Estabe = it.Cod_Estabe) and (cb.Ser_Nota = it.Ser_Nota)  and (cb.Num_Nota = it.Num_Nota)
                  Where cb.Cod_Estabe = @PCodEstabe
                  And cb.Status = 'F'
                  And cb.Tip_Saida <> 'D'
                  And it.Cod_Produto = @it_CodPrd
                  And cb.Dat_Emissao <= @cb_DatMov
                  And (IsNull(cb.Vlr_SubsTrib,0)+Isnull(cb.Vlr_RecSbt,0)+IsNull(cb.Vlr_SbtRes,0)+IsNull(it.vICMSSTRet,0)) > 0) 
          Select top 1 @ns_SerNot = cb.Ser_Nota, @ns_NumNot = cb.Num_Nota, @ns_CodLot = it.Cod_Lote, @ns_NumSeqIte = it.Num_SeqIte
          From NFSCB cb
               Inner Join NFSIT it on (cb.Cod_Estabe = it.Cod_Estabe) and (cb.Ser_Nota = it.Ser_Nota)  and (cb.Num_Nota = it.Num_Nota)
          Where cb.Cod_Estabe = @PCodEstabe
          And cb.Status = 'F'
          And cb.Tip_Saida <> 'D'
          And it.Cod_Produto = @it_CodPrd
          And cb.Dat_Emissao <= @cb_DatMov
          And (IsNull(cb.Vlr_SubsTrib,0)+Isnull(cb.Vlr_RecSbt,0)+IsNull(cb.Vlr_SbtRes,0)+IsNull(it.vICMSSTRet,0)) > 0 
		  Order by cb.Dat_Emissao desc, it.Qtd_Produto desc

        if IsNull(@ns_NumNot,0) > 0
          begin
            Select @WFator = @it_QtdEnt*1.0/(IsNull(Qtd_Produto,0)+IsNull(Qtd_Bonificacao,0)),

                   @ns_VlrBasSbtRet = Case 
                                        When IsNull(vICMSSTRet,0) > 0 then IsNull(vBCSTRet,0)
                                        When IsNull(Vlr_SubsTrib,0) > 0 then IsNull(Vlr_BasSubsTrib,0) 
                                        When IsNull(Vlr_SbtRes,0) > 0 then IsNull(Vlr_BasSbtRes,0) 
                                        Else IsNull(Vlr_BasRecSbt,0) 
                                      End,
                   --@ns_AlqIcmPro = IsNull(Alq_Icms,0),
                   @ns_VlrIcmPro = Case 
                                     When IsNull(vICMSSTRet,0) > 0 then IsNull(vICMSSubstituto,0)
                                     When (IsNull(Vlr_SubsTrib,0)+IsNull(Vlr_SbtRes,0)+IsNull(Vlr_RecSbt,0)) > 0 then IsNull(Vlr_IcmsNor,0)
                                     Else 0
                                   End,
                   @ns_AlqIcmDeb = Case 
                                     When IsNull(vICMSSTRet,0) > 0 then IsNull(pST,0)
									 Else IsNull(Alq_IcmSbt,0)  
                                   End,
                   @ns_VlrSbtRet = Case 
                                     When IsNull(vICMSSTRet,0) > 0 then IsNull(vICMSSTRet,0)
                                     When IsNull(Vlr_SubsTrib,0) > 0 then IsNull(Vlr_SubsTrib,0) 
                                     When IsNull(Vlr_SbtRes,0) > 0 then IsNull(Vlr_SbtRes,0) 
                                     Else IsNull(Vlr_RecSbt,0) 
                                   End,
                   @ns_VlrBasFCPSbtRet = Case 
                                           When IsNull(vICMSSTRet,0) > 0 then IsNull(vBCFCPSTRet,0)
                                           When IsNull(Alq_FcpSbt,0) > 0 then  
				                             Case 
                                               When IsNull(Vlr_SubsTrib,0) > 0 then IsNull(Vlr_BasSubsTrib,0)
                                               When IsNull(Vlr_SbtRes,0) > 0 then IsNull(Vlr_BasSbtRes,0) 												 
                                               Else IsNull(Vlr_BasRecSbt,0)
                                             End
                                           Else 0
                                         End,
                   @ns_AlqFCPSbtRet = Case 
                                        When IsNull(vICMSSTRet,0) > 0 then IsNull(pFCPSTRet,0)
                                        When (IsNull(Vlr_SubsTrib,0)+IsNull(Vlr_SbtRes,0)+IsNull(Vlr_RecSbt,0)) > 0 then IsNull(Alq_FcpSbt,0) 
                                        Else 0
                                      End,
                   @ns_VlrFCPSbtRet = Case 
                                        When IsNull(vICMSSTRet,0) > 0 then IsNull(vFCPSTRet,0) 
                                        When (IsNull(Vlr_SubsTrib,0)+IsNull(Vlr_SbtRes,0)+IsNull(Vlr_RecSbt,0)) > 0 then IsNull(Vlr_FcpSbt,0)
                                        Else 0
                                      End

            From NFSIT 
            Where Cod_Estabe = @PCodEstabe
            And Ser_Nota = @ns_SerNot
            And Num_Nota = @ns_NumNot
            And Cod_Produto = @it_CodPrd
            And Cod_Lote = @ns_CodLot
            And Num_SeqIte = @ns_NumSeqIte

            Set @ns_VlrBasSbtRet    = IsNull(Round(@ns_VlrBasSbtRet*@WFator,2),0)
            Set @ns_VlrIcmPro       = IsNull(Round(@ns_VlrIcmPro*@WFator,4),0)
            Set @ns_VlrSbtRet       = IsNull(Round(@ns_VlrSbtRet*@WFator,4),0)
            Set @ns_VlrBasFCPSbtRet = IsNull(Round(@ns_VlrBasFCPSbtRet*@WFator,2),0)
            Set @ns_VlrFCPSbtRet    = IsNull(Round(@ns_VlrFCPSbtRet*@WFator,4),0)

            -- atualiza valores em NFEIT
            Update NFEIT
              Set Xml_vBCSTRet = @ns_VlrBasSbtRet,
                  Xml_pST = @ns_AlqIcmDeb, 
                  Xml_vICMSSubstituto = @ns_VlrIcmPro,
                  Xml_vICMSSTRet = @ns_VlrSbtRet,
                  Xml_vBCFCPSTRet = @ns_VlrBasFCPSbtRet,
                  Xml_pFCPSTRet = @ns_AlqFCPSbtRet,
                  Xml_vFCPSTRet = @ns_VlrFCPSbtRet,
                  Xml_pRedBCEfet = @it_PerRedBasCalIcm,
                  Xml_vBCEfet = @it_VlrBasIcmPro, 
                  Xml_pICMSEfet = @it_AlqIcmPro,
                  Xml_vICMSEfet = @it_VlrIcmPro
            Where Cod_Estabe = @PCodEstabe 
	        And Protocolo = @PNumPrt
            And Cod_Produto = @it_CodPrd
            And Cod_Lote = @it_CodLot
            And Num_SeqIte = @it_NumSeqIte
          end

        Fetch Next From NFEIT_Cr Into @it_CodPrd, @it_CodLot, @it_NumSeqIte, @it_QtdEnt,
                                      @it_PerRedBasCalIcm, @it_VlrBasIcmPro, @it_VlrIcmPro, @it_AlqIcmPro
      end
    Close NFEIT_Cr
    Deallocate NFEIT_Cr

  Commit Transaction
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CalcTributSTRetAntNFSCB]
@PCodEstabe int,
@PSerNot varchar(3),
@PNumNot int

AS

SET NOCOUNT ON

--if (Select Status from NFSCB Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot) <> 'A'
--  RAISERROR('Nota não está em "Aberto"',16,1)
--else
BEGIN
  Begin Transaction

    -- zera valores 
	Update NFSIT
	  Set vBCSTRet = 0,
          pST = 0,
          vICMSSubstituto = 0,
          vICMSSTRet = 0,
          vBCFCPSTRet = 0,
          pFCPSTRet = 0,
          vFCPSTRet = 0,
          pRedBCEfet = 0,
          vBCEfet = 0,
          pICMSEfet = 0,
          vICMSEfet = 0
      Where Cod_Estabe = @PCodEstabe 
	  And Ser_Nota = @PSerNot 
	  And Num_Nota = @PNumNot

    Declare @cb_DatEmi datetime,
            @it_CodPrd int,
            @it_CodLot varchar(20),
            @it_NumSeqIte int,
            @it_QtdSai int,
            @it_PerRedBasCalIcm numeric(9,4), 
            @it_VlrBasIcmPro numeric(18,4),
            @it_VlrIcmPro numeric(18,4),
            @it_AlqIcmPro numeric(9,4),
			@WFator numeric(18,8),
            @ne_NumPrt int,
            @ne_CodLot varchar(20),
            @ne_NumSeqIte int,
            @ne_VlrBasSbtRet numeric(18,4),
            --@ne_AlqIcmPro numeric(9,4),
            @ne_VlrIcmPro numeric(18,4),
            @ne_AlqIcmDeb numeric(18,4), 
            @ne_VlrSbtRet numeric(18,4),
            @ne_VlrBasFCPSbtRet numeric(18,4),
            @ne_AlqFCPSbtRet numeric(9,4),
            @ne_VlrFCPSbtRet numeric(18,4)

    Set @cb_DatEmi = (Select Dat_Emissao From NFSCB Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot)

    Declare NFSIT_Cr Cursor Local Fast_Forward For 

      Select Cod_Produto, Cod_Lote, Num_SeqIte, QtdSai=IsNull(Qtd_Produto,0)+IsNull(Qtd_Bonificacao,0),
             IsNull(Per_RedBasCalIcm,0), IsNull(Vlr_BasIcmsNor,0), IsNull(Vlr_IcmsNor,0), IsNull(Alq_Icms,0)
        From NFSIT 
      Where Cod_Estabe = @PCodEstabe 
      and Ser_Nota = @PSerNot 
      and Num_Nota = @PNumNot
      and ((Ctrl_Tributacao = '60') or (Cod_CSOSN = '500'))

    Open NFSIT_Cr
    Fetch Next From NFSIT_Cr Into @it_CodPrd, @it_CodLot, @it_NumSeqIte, @it_QtdSai,
                                  @it_PerRedBasCalIcm, @it_VlrBasIcmPro, @it_VlrIcmPro, @it_AlqIcmPro
    While @@FETCH_STATUS = 0
      begin
        Set @ne_NumPrt = 0
        Set @ne_CodLot= ''

        if Exists(Select 1
                  From NFECB cb
                       Inner Join NFEIT it on (cb.Cod_Estabe = it.Cod_Estabe) and (cb.Protocolo = it.Protocolo) 
                  Where cb.Cod_Estabe = @PCodEstabe
                  And cb.Status = 'F'
                  And cb.Tip_NF <> 'D'
                  And it.Cod_Produto = @it_CodPrd
                  And it.Cod_Lote = @it_CodLot
                  And cb.Dat_Movimento <= @cb_DatEmi
                  And (IsNull(cb.Vlr_IstFon,0)+Isnull(cb.Vlr_DifTri,0)+IsNull(cb.Vlr_SbtRes,0)+IsNull(it.Xml_vICMSSTRet,0)) > 0) 
          Select top 1 @ne_NumPrt = cb.Protocolo, @ne_CodLot = it.Cod_Lote, @ne_NumSeqIte = it.Num_SeqIte
          From NFECB cb
               Inner Join NFEIT it on (cb.Cod_Estabe = it.Cod_Estabe) and (cb.Protocolo = it.Protocolo) 
          Where cb.Cod_Estabe = @PCodEstabe
          And cb.Status = 'F'
          And cb.Tip_NF <> 'D'
          And it.Cod_Produto = @it_CodPrd
          And it.Cod_Lote = @it_CodLot
          And cb.Dat_Movimento <= @cb_DatEmi
          And (IsNull(cb.Vlr_IstFon,0)+Isnull(cb.Vlr_DifTri,0)+IsNull(cb.Vlr_SbtRes,0)+IsNull(it.Xml_vICMSSTRet,0)) > 0 
		  Order by cb.Dat_Movimento desc, it.Qtd_Pedido desc
        else
        if Exists(Select 1
                  From NFECB cb
                       Inner Join NFEIT it on (cb.Cod_Estabe = it.Cod_Estabe) and (cb.Protocolo = it.Protocolo) 
                  Where cb.Cod_Estabe = @PCodEstabe
                  And cb.Status = 'F'
                  And cb.Tip_NF <> 'D'
                  And it.Cod_Produto = @it_CodPrd
                  And cb.Dat_Movimento <= @cb_DatEmi
                  And (IsNull(cb.Vlr_IstFon,0)+Isnull(cb.Vlr_DifTri,0)+IsNull(cb.Vlr_SbtRes,0)+IsNull(it.Xml_vICMSSTRet,0)) > 0) 
          Select top 1 @ne_NumPrt = cb.Protocolo, @ne_CodLot = it.Cod_Lote, @ne_NumSeqIte = it.Num_SeqIte
          From NFECB cb
               Inner Join NFEIT it on (cb.Cod_Estabe = it.Cod_Estabe) and (cb.Protocolo = it.Protocolo) 
          Where cb.Cod_Estabe = @PCodEstabe
          And cb.Status = 'F'
          And cb.Tip_NF <> 'D'
          And it.Cod_Produto = @it_CodPrd
          And cb.Dat_Movimento <= @cb_DatEmi
          And (IsNull(cb.Vlr_IstFon,0)+Isnull(cb.Vlr_DifTri,0)+IsNull(cb.Vlr_SbtRes,0)+IsNull(it.Xml_vICMSSTRet,0)) > 0 
		  Order by cb.Dat_Movimento desc, it.Qtd_Pedido desc

        if IsNull(@ne_NumPrt,0) > 0
          begin
            Select @WFator = @it_QtdSai*1.0/(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)),

                   @ne_VlrBasSbtRet = Case 
                                        When IsNull(Xml_vICMSSTRet,0) > 0 then IsNull(Xml_vBCSTRet,0)
                                        When IsNull(Vlr_SubsTrib,0) > 0 then IsNull(Vlr_BasSubsTrib,0) 
                                        When IsNull(Vlr_SbtRes,0) > 0 then IsNull(Vlr_BasSbtRes,0) 
                                        Else IsNull(Vlr_BasDifTri,0) 
                                      End,
                   --@ne_AlqIcmPro = IsNull(Alq_Icms,0),
                   @ne_VlrIcmPro = Case 
                                     When IsNull(Xml_vICMSSTRet,0) > 0 then IsNull(Xml_vICMSSubstituto,0)
                                     When (IsNull(Vlr_SubsTrib,0)+IsNull(Vlr_SbtRes,0)+IsNull(Vlr_DifTri,0)) > 0 then IsNull(Vlr_IcmsNor,0)
                                     Else 0
                                   End,
                   @ne_AlqIcmDeb = Case 
                                     When IsNull(Xml_vICMSSTRet,0) > 0 then IsNull(Xml_pST,0)
									 Else IsNull(Alq_IcmDeb,0)
                                   End,
                   @ne_VlrSbtRet = Case 
                                     When IsNull(Xml_vICMSSTRet,0) > 0 then IsNull(Xml_vICMSSTRet,0)
                                     When IsNull(Vlr_SubsTrib,0) > 0 then IsNull(Vlr_SubsTrib,0) 
                                     When IsNull(Vlr_SbtRes,0) > 0 then IsNull(Vlr_SbtRes,0) 
                                     Else IsNull(Vlr_DifTri,0) 
                                   End,
                   @ne_VlrBasFCPSbtRet = Case 
                                           When IsNull(Xml_vICMSSTRet,0) > 0 then IsNull(Xml_vBCFCPSTRet,0)
                                           When IsNull(Alq_FcpSbt,0) > 0 then  
				                             Case 
                                               When IsNull(Vlr_SubsTrib,0) > 0 then IsNull(Vlr_BasSubsTrib,0)
                                               When IsNull(Vlr_SbtRes,0) > 0 then IsNull(Vlr_BasSbtRes,0) 												 
                                               Else IsNull(Vlr_BasDifTri,0)
                                             End
                                           Else 0
                                         End,
                   @ne_AlqFCPSbtRet = Case 
                                        When IsNull(Xml_vICMSSTRet,0) > 0 then IsNull(Xml_pFCPSTRet,0)
                                        When (IsNull(Vlr_SubsTrib,0)+IsNull(Vlr_SbtRes,0)+IsNull(Vlr_DifTri,0)) > 0 then IsNull(Alq_FcpSbt,0) 
                                        Else 0
                                      End,
                   @ne_VlrFCPSbtRet = Case 
                                        When IsNull(Xml_vICMSSTRet,0) > 0 then IsNull(Xml_vFCPSTRet,0) 
                                        When (IsNull(Vlr_SubsTrib,0)+IsNull(Vlr_SbtRes,0)+IsNull(Vlr_DifTri,0)) > 0 then IsNull(Vlr_FcpSbt,0)
                                        Else 0
                                      End

            From NFEIT 
            Where Cod_Estabe = @PCodEstabe
            And Protocolo = @ne_NumPrt
            And Cod_Produto = @it_CodPrd
            And Cod_Lote = @ne_CodLot
            And Num_SeqIte = @ne_NumSeqIte

            Set @ne_VlrBasSbtRet    = IsNull(Round(@ne_VlrBasSbtRet*@WFator,2),0)
            Set @ne_VlrIcmPro       = IsNull(Round(@ne_VlrIcmPro*@WFator,4),0)
            Set @ne_VlrSbtRet       = IsNull(Round(@ne_VlrSbtRet*@WFator,4),0)
            Set @ne_VlrBasFCPSbtRet = IsNull(Round(@ne_VlrBasFCPSbtRet*@WFator,2),0)
            Set @ne_VlrFCPSbtRet    = IsNull(Round(@ne_VlrFCPSbtRet*@WFator,4),0)

            -- atualiza valores em NFSIT
            Update NFSIT
              Set vBCSTRet = @ne_VlrBasSbtRet,
                  pST = @ne_AlqIcmDeb, 
                  vICMSSubstituto = @ne_VlrIcmPro,
                  vICMSSTRet = @ne_VlrSbtRet,
                  vBCFCPSTRet = @ne_VlrBasFCPSbtRet,
                  pFCPSTRet = @ne_AlqFCPSbtRet,
                  vFCPSTRet = @ne_VlrFCPSbtRet,
                  pRedBCEfet = @it_PerRedBasCalIcm,
                  vBCEfet = @it_VlrBasIcmPro, 
                  pICMSEfet = @it_AlqIcmPro,
                  vICMSEfet = @it_VlrIcmPro
            Where Cod_Estabe = @PCodEstabe 
	        And Ser_Nota = @PSerNot 
	        And Num_Nota = @PNumNot
            And Cod_Produto = @it_CodPrd
            And Cod_Lote = @it_CodLot
            And Num_SeqIte = @it_NumSeqIte
          end

        Fetch Next From NFSIT_Cr Into @it_CodPrd, @it_CodLot, @it_NumSeqIte, @it_QtdSai,
                                      @it_PerRedBasCalIcm, @it_VlrBasIcmPro, @it_VlrIcmPro, @it_AlqIcmPro
      end
    Close NFSIT_Cr
    Deallocate NFSIT_Cr

  Commit Transaction
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_RecalculaPisCofins] 
@PCodEstabe int,
@PNumNot int,
@PSerNot varchar(3),   -- se for entrada: ignorado
@PTipEntSai char(1)    --(S)aida, (E)ntrada

AS

SET NOCOUNT ON

Begin Transaction

  -- variaveis a gravar em NFSIT
  Declare @P_CstPis varchar(2),
          @P_VlrBasPis numeric(18,4),
          @P_AlqPis numeric(18,4),
          @P_VlrPis numeric(18,4),
          @P_CstCof varchar(2),
          @P_VlrBasCof numeric(18,4),
          @P_AlqCof numeric(18,4),
          @P_VlrCof numeric(18,4),
          @P_ObsNf varchar(200)

-- coloca campos de tabelas na memoria
  Declare @cb_CodCfo int,
          @cb_DatMov smalldatetime,
          @cb_TipNot varchar(1),
          @em_CodTipLuc varchar(2),
          @pm_FlgIncIpiCalPis bit,
          @pm_FlgExcIcmCalPis bit,
          @cl_CodRamAtv int,
          @op_FlgCalPisCof bit,
          @pr_CodNcm varchar(8),
          @it_CodPrd int,
          @it_CodLot varchar(20),
          @it_NumSeqIte int,
          @it_TipLis varchar(1),
          @it_VlrBasTri numeric(18,4),
		  @it_VlrSbtRes  numeric(18,4),
          @it_VlrIpi numeric(18,4),
          @it_VlrIcmNor numeric(18,4),
          @it_VlrIcmTri numeric(18,4),
		  @WVlrBasPisCof numeric(18,4)

  -- ESTAB / PARAM
  Select @em_CodTipLuc = IsNull(Cod_TipLucro,'')
    From ESTAB
  Where Cod_Estabe = @PCodEstabe  

  Select @pm_FlgIncIpiCalPis = IsNull(FlgIncIpiCalPis,0),
         @pm_FlgExcIcmCalPis = IsNull(FlgExcIcmCalPis,0)
    From PARAM
  Where Cod_Estabe = @PCodEstabe


  if (@PTipEntSai = 'S') and Exists(Select 1 From NFSCB Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot)
    begin
      -- indica se reduz aliq. PIS/COFINS
      Set @cl_CodRamAtv = 0
  
      Select @cb_CodCfo = IsNull(cb.Cod_Cfo1,0),
             @cb_DatMov = Dat_Emissao,
             @cb_TipNot = Tip_Saida,
             @cl_CodRamAtv = IsNull(cl.Cod_RamoAtividade,0),
             @op_FlgCalPisCof = IsNull(op.Flg_CalPisCof,0)
        From NFSCB cb   
             Left Join TPOPE op on cb.Cod_Ope = op.Cod_Ope 
             Left Join CLIEN cl on cb.Cod_Cliente = cl.Codigo 
             Left Join RMATV ra on cl.Cod_RamoAtividade = ra.Codigo
      Where cb.Cod_Estabe = @PCodEstabe 
      and cb.Ser_Nota = @PSerNot 
      and cb.Num_Nota = @PNumNot

      Update NFSCB
        Set Vlr_Pis = 0,
            Vlr_Cofins = 0
      Where Cod_Estabe = @PCodEstabe 
      and Ser_Nota = @PSerNot 
      and Num_Nota = @PNumNot

      Declare NFSIT_Cr Cursor Local Fast_Forward For 
        Select it.Cod_Produto, it.Cod_Lote, it.Num_SeqIte, it.Vlr_BasTri, IsNull(it.Vlr_SbtRes,0), 
               IsNull(it.Vlr_Ipi,0), IsNull(it.Vlr_IcmsNor,0), IsNull(it.Vlr_IcmsTri,0),
               IsNull(it.Tip_Aux,pr.Tip_LisPis), Substring(Ltrim(Rtrim(pr.Cod_ClaFis)),1,8)
          From NFSIT it 
               Inner Join PRODU pr on it.Cod_Produto = pr.Codigo
        Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
        And (Qtd_Produto+Qtd_Bonificacao) > 0
      Open NFSIT_Cr
      Fetch Next From NFSIT_Cr Into @it_CodPrd, @it_CodLot, @it_NumSeqIte, @it_VlrBasTri, @it_VlrSbtRes, 
                                    @it_VlrIpi, @it_VlrIcmNor, @it_VlrIcmTri, 
                                    @it_TipLis, @pr_CodNcm
      While @@FETCH_STATUS = 0
        begin
          -- ressarcimento
          Set @WVlrBasPisCof = Round(@it_VlrBasTri+@it_VlrSbtRes,2)

          -- ipi
          if @pm_FlgIncIpiCalPis = 1
            Set @WVlrBasPisCof = @WVlrBasPisCof + @it_VlrIpi

          -- exclui icms destacado  
          if @pm_FlgExcIcmCalPis = 1
            Set @WVlrBasPisCof = @WVlrBasPisCof - @it_VlrIcmTri

          Exec PR_CalculaPisCofins @PCodEstabe, @op_FlgCalPisCof, @PTipEntSai, @em_CodTipLuc, @cb_DatMov, @cb_CodCfo, @cl_CodRamAtv, @pr_CodNcm, @it_TipLis, @WVlrBasPisCof, 
                                   @P_CstPis output, @P_VlrBasPis output, @P_AlqPis output, @P_VlrPis output,
                                   @P_CstCof output, @P_VlrBasCof output, @P_AlqCof output, @P_VlrCof output, @P_ObsNf output
          if @@error <> 0
            begin
              Rollback Transaction
              Return
            end

          Update NFSIT
            Set Cod_Ncm = @pr_CodNcm,  
                Vlr_BasPis = @P_VlrBasPis,
                Vlr_Pis = @P_VlrPis,
                Alq_Pis = @P_AlqPis,
                Cst_Pis = @P_CstPis,
                Vlr_BasCofins = @P_VlrBasCof,
                Vlr_Cofins = @P_VlrCof,
                Alq_Cofins = @P_AlqCof,
                Cst_Cofins = @P_CstCof,
                Obs_Nf = @P_ObsNf
          From NFSIT
          Where Cod_Estabe = @PCodEstabe
          And Ser_Nota = @PSerNot
          And Num_Nota = @PNumNot
          And Cod_Produto = @it_CodPrd
          And Cod_Lote = @it_CodLot
          And Num_SeqIte = @it_NumSeqIte

          -- ajusta pis/Cofins
          Update it
            Set it.Vlr_Pis = 0.01
          From NFSIT it
          Where it.Cod_Estabe = @PCodEstabe
          And it.Ser_Nota = @PSerNot
          And it.Num_Nota = @PNumNot
          And it.Cod_Produto = @it_CodPrd
          And it.Cod_Lote = @it_CodLot
          And it.Num_SeqIte = @it_NumSeqIte
          And (it.Vlr_BasPis > 0) and (it.Alq_Pis > 0) and (it.Vlr_Pis = 0)
    
          Update it
            Set it.Vlr_Cofins = 0.01
          From NFSIT it
          Where it.Cod_Estabe = @PCodEstabe
          And it.Ser_Nota = @PSerNot
          And it.Num_Nota = @PNumNot
          And it.Cod_Produto = @it_CodPrd
          And it.Cod_Lote = @it_CodLot
          And it.Num_SeqIte = @it_NumSeqIte
          And (it.Vlr_BasCofins > 0) and (it.Alq_Cofins > 0) and (it.Vlr_Cofins = 0)
    
          Fetch Next From NFSIT_Cr Into @it_CodPrd, @it_CodLot, @it_NumSeqIte, @it_VlrBasTri, @it_VlrSbtRes, 
                                        @it_VlrIpi, @it_VlrIcmNor, @it_VlrIcmTri, 
                                        @it_TipLis, @pr_CodNcm
        end
      Close NFSIT_Cr
      Deallocate NFSIT_Cr

      Update NFSCB
        Set Cod_RamAtv = @cl_CodRamAtv,
	        Vlr_Pis = (Select Round(Sum(IsNull(Vlr_Pis,0)),2) From NFSIT Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot),
            Vlr_Cofins = (Select Round(Sum(IsNull(Vlr_Cofins,0)),2) From NFSIT Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot)
      Where Cod_Estabe = @PCodEstabe 
      and Ser_Nota = @PSerNot 
      and Num_Nota = @PNumNot

	end  -- if (@PTipEntSai = 'S')

  else
  if (@PTipEntSai = 'E') and Exists(Select 1 From NFECB Where Cod_Estabe = @PCodEstabe and Protocolo = @PNumNot)
    begin
      -- indica se reduz aliq. PIS/COFINS
      Set @cl_CodRamAtv = 0
  
      Select @cb_CodCfo = IsNull(cb.Cod_Cfo,0),
             @cb_DatMov = Dat_Movimento,
             @cb_TipNot = Tip_NF,
             @cl_CodRamAtv = IsNull(cl.Cod_RamoAtividade,0),
             @op_FlgCalPisCof = IsNull(op.Flg_CalPisCof,0)
      From NFECB cb   
           Left Join TPOPE op on cb.Cod_Ope = op.Cod_Ope 
           Left Outer Join CLIEN cl on cb.Cod_EmiCliente = cl.Codigo 
           Left Outer Join RMATV ra on cl.Cod_RamoAtividade = ra.Codigo
      Where cb.Cod_Estabe = @PCodEstabe 
      and cb.Protocolo = @PNumNot

      -- atualiza cabecalho
      Update NFECB
        Set Vlr_Pis = 0,
            Vlr_Cofins = 0
      Where Cod_Estabe = @PCodEstabe
      And Protocolo = @PNumNot
     
      DECLARE NFEIT_Cr Cursor Local Fast_Forward For
        Select it.Cod_Produto, it.Cod_Lote, it.Num_SeqIte, it.Vlr_BasTri, IsNull(it.Vlr_SbtRes,0), 
               IsNull(it.Vlr_Ipi,0), IsNull(it.Vlr_IcmsNor,0), IsNull(it.Vlr_IcmsTrib,0),
               IsNull(it.Tip_LisPis,pr.Tip_LisPis), Substring(Ltrim(Rtrim(pr.Cod_ClaFis)),1,8)
          From NFEIT it 
               Inner Join PRODU pr on it.Cod_Produto = pr.Codigo
        Where Cod_Estabe = @PCodEstabe and Protocolo = @PNumNot
        And (Qtd_Pedido+Qtd_Bonificacao) > 0
      OPEN NFEIT_Cr
      Fetch Next From NFEIT_Cr Into @it_CodPrd, @it_CodLot, @it_NumSeqIte, @it_VlrBasTri, @it_VlrSbtRes, 
                                    @it_VlrIpi, @it_VlrIcmNor, @it_VlrIcmTri, 
                                    @it_TipLis, @pr_CodNcm
     
      WHILE @@FETCH_STATUS = 0
        BEGIN
          -- ressarcimento
          Set @WVlrBasPisCof = Round(@it_VlrBasTri+@it_VlrSbtRes,2)

          -- ipi
          if @pm_FlgIncIpiCalPis = 1
            Set @WVlrBasPisCof = @WVlrBasPisCof + @it_VlrIpi

          -- exclui icm destacado na devolução de venda
          if @pm_FlgExcIcmCalPis = 1
            begin
              if @cb_TipNot = 'D'
                Set @WVlrBasPisCof = @WVlrBasPisCof - @it_VlrIcmTri
              else
                Set @WVlrBasPisCof = @WVlrBasPisCof - @it_VlrIcmNor
            end

          Exec PR_CalculaPisCofins @PCodEstabe, @op_FlgCalPisCof, @PTipEntSai, @em_CodTipLuc, @cb_DatMov, @cb_CodCfo, @cl_CodRamAtv, @pr_CodNcm, @it_TipLis, @WVlrBasPisCof, 
                                   @P_CstPis output, @P_VlrBasPis output, @P_AlqPis output, @P_VlrPis output,
                                   @P_CstCof output, @P_VlrBasCof output, @P_AlqCof output, @P_VlrCof output, @P_ObsNf output
          if @@error <> 0
            begin
              Rollback Transaction
              Return
            end

          -- atualiza item
          Update NFEIT
            Set Cod_Ncm = @pr_CodNcm,  
                Vlr_BasPis = @P_VlrBasPis,
                Vlr_Pis = @P_VlrPis,
                Alq_Pis = @P_AlqPis,
                Cst_Pis = @P_CstPis,
                Vlr_BasCofins = @P_VlrBasCof,
                Vlr_Cofins = @P_VlrCof,
                Alq_Cofins = @P_AlqCof,
                Cst_Cofins = @P_CstCof
          From NFEIT
          Where Cod_Estabe = @PCodEstabe
          And Protocolo = @PNumNot
          And Cod_Produto = @it_CodPrd
          And Cod_Lote = @it_CodLot
          And Num_SeqIte = @it_NumSeqIte

          -- ajusta pis/Cofins
          Update it
            Set it.Vlr_Pis = 0.01
          From NFEIT it
          Where it.Cod_Estabe = @PCodEstabe
          And it.Protocolo = @PNumNot
          And it.Cod_Produto = @it_CodPrd
          And it.Cod_Lote = @it_CodLot
          And it.Num_SeqIte = @it_NumSeqIte
          And (it.Vlr_BasPis > 0) and (it.Alq_Pis > 0) and (it.Vlr_Pis = 0)
    
          Update it
            Set it.Vlr_Cofins = 0.01
          From NFEIT it
          Where it.Cod_Estabe = @PCodEstabe
          And it.Protocolo = @PNumNot
          And it.Cod_Produto = @it_CodPrd
          And it.Cod_Lote = @it_CodLot
          And it.Num_SeqIte = @it_NumSeqIte
          And (it.Vlr_BasCofins > 0) and (it.Alq_Cofins > 0) and (it.Vlr_Cofins = 0)

          Fetch Next From NFEIT_Cr Into @it_CodPrd, @it_CodLot, @it_NumSeqIte, @it_VlrBasTri, @it_VlrSbtRes, 
                                        @it_VlrIpi, @it_VlrIcmNor, @it_VlrIcmTri, 
                                        @it_TipLis, @pr_CodNcm
        END 
      
      CLOSE NFEIT_Cr
      DEALLOCATE NFEIT_Cr 
     
      Update NFECB
        Set Vlr_Pis = (Select Round(Sum(IsNull(Vlr_Pis,0)),2) From NFEIT Where Cod_Estabe = @PCodEstabe and Protocolo = @PNumNot),
            Vlr_Cofins = (Select Round(Sum(IsNull(Vlr_Cofins,0)),2) From NFEIT Where Cod_Estabe = @PCodEstabe and Protocolo = @PNumNot)
      Where Cod_Estabe = @PCodEstabe 
      and Protocolo = @PNumNot

    end  -- if PTipEntSai = 'E'

Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_RetornaItensNF]
@PCodEstabe int,
@PNumNota int,
@PSerNota varchar(3),
@PTipNota char(1)

AS

SET NOCOUNT ON 

Set dateformat ymd

IF OBJECT_ID('tempdb..#TMP_Itens') IS NOT NULL
  DROP TABLE #TMP_Itens
  
CREATE TABLE #TMP_Itens
(
    Chave int identity,
    Cod_Produto int,
    Num_SeqIte int,
    Num_SeqPdc varchar(6),
    Cod_EAN varchar(14),
    Tip_Sai varchar(1),
    Cod_NCM varchar(8),
    Cod_GrpPrc varchar(1),
    Cod_Cfo int,
    Tip_Por344 varchar(2),
    Tip_LisPis varchar(3),
    Des_Produto varchar(120),
    Obs_Produto varchar(500), 
    Und_Com varchar(12),
    Qtd_Com numeric(18,8),
    Prc_UniCom numeric(18,8),
    Vlr_TotBruIte numeric(18,8),
    Vlr_TotIte numeric(18,8),
    Per_Desconto numeric(18,8),
    Vlr_BasRepIcm numeric(18,8),
    Per_RepIcm numeric(7,4),
    Vlr_RepIcm numeric(18,8),
    Tip_Consumidor varchar(1),
    Vlr_DscTri numeric(18,8),
    Per_DscTri numeric(18,2),
    Vlr_DscRat numeric(18,8),
    Vlr_DscBonRat numeric(18,8),
    Vlr_DscTotIte numeric(18,8),
    Vlr_BasSbtRes numeric(18,8),
    Vlr_SbtRes numeric(18,8), 
    Vlr_BasSbtEmb numeric(18,8),
    Vlr_SbtEmb numeric(18,8), 
    Cod_Lote varchar(20), 
    Cod_LoteOri varchar(20), 
    Dat_Vencim datetime,
    Dat_Fabric datetime,
    Qtd_MesValid integer,
    Vlr_Frete numeric(18,8),
    Vlr_Seguro numeric(18,8),
    Vlr_DspRat numeric(18,8),
    Vlr_DspExt numeric(18,8), 
    Vlr_TotDsp numeric(18,8), 
    Und_Tri varchar(12),
    Qtd_Tri int,
    Prc_UniTri numeric(18,8),
    Cod_OriPrd varchar(1),
    Cod_CstIcm varchar(2),
    Cod_CsosnIcm varchar(3),
    Cod_ModBasCalIcm varchar(1),
    Per_RedBasCalIcm numeric(8,4),
    Vlr_BasIcm numeric(18,8),
    Alq_Icm numeric(8,4),
    Vlr_Icm numeric(18,8), 
    Dif_VlrIcm numeric(18,8), 
    Vlr_BasIcmPro numeric(18,8),
    Vlr_IcmPro numeric(18,8), 
    Per_IcmDiferi numeric(8,4),
    Vlr_IcmDiferi numeric(18,8), 
    Vlr_DscCalSuframa numeric(18,8),
    Vlr_IcmDesone numeric(18,8), 
    Cod_MtvIcmDesone varchar(1),
    Vlr_BasIcmSbtRet numeric(18,8), 
    Vlr_IcmSbtRet numeric(18,8),
    Cod_ModBasCalIcmSbt varchar(1),
    Alq_AgrSbt numeric(8,4), 
    Per_RedBasCalIcmSbt numeric(8,4),
    Vlr_BasIcmSbt numeric(18,8), 
    Alq_IcmSbt numeric(8,4),
    Vlr_IcmSbt numeric(18,8),
    CST_Ipi varchar(2), 
    Cod_EnqIpi varchar(3),
    Vlr_BasIpi numeric(18,8),
    Alq_Ipi numeric(8,4),
    Vlr_Ipi numeric(18,8),
    Vlr_BasDevIpi numeric(18,8),
    Per_DevIpi numeric(8,4),
    Vlr_DevIpi numeric(18,8), 
    CST_Pis varchar(2), 
    Vlr_BasPis numeric(18,8), 
    Alq_Pis numeric(8,4),
    Vlr_Pis numeric(18,8),
    Dif_VlrPis numeric(18,8),
    CST_Cofins varchar(2), 
    Vlr_BasCofins numeric(18,8), 
    Alq_Cofins numeric(8,4), 
    Vlr_Cofins numeric(18,8),
    Dif_VlrCofins numeric(18,8),
    Prc_MaxCon numeric(18,8),
    Prc_Fabric numeric(18,8),
    Des_Fabric varchar(25),
    Flg_DscItePdv bit,
    Prc_UniPdv numeric(18,8),
    Per_DscPdv numeric(8,4),
    Cod_CEST varchar(7),    
    Vlr_BasIcmDes numeric(18,8),
    Per_AcrAlqIntFcp numeric(8,4),
    Alq_IntDes numeric(8,4),
    Alq_Interesta numeric(8,4),
    Per_PrvParIcm numeric(8,4),
    Vlr_IcmFcpDes numeric(18,8),
    Vlr_IcmParDes numeric(18,8),
    Vlr_IcmParRem numeric(18,8),
    Cod_PedCmpCli varchar(20),
    Str_VolEmb varchar(50),
    Obs_IteNf varchar(200),
    Reg_MS varchar(20),
    Des_MtvIseRegMS varchar(255),

    Alq_FcpIcm numeric(8,4),
    Vlr_FcpIcm numeric(18,8),
    Alq_FcpSbt numeric(8,4), 
    Vlr_FcpSbt numeric(18,8), 
    Alq_FcpSbtRet numeric(8,4),
    Vlr_FcpSbtRet numeric(18,8),

    vBCSTRet numeric(18,8),
    pST numeric(8,4),
    vICMSSubstituto numeric(18,8),
    vICMSSTRet numeric(18,8),
    vBCFCPSTRet numeric(18,8),
    pFCPSTRet numeric(8,4), 
    vFCPSTRet numeric(18,8),
    pRedBCEfet numeric(8,4),
    vBCEfet numeric(18,8),
    pICMSEfet numeric(8,4),
    vICMSEfet numeric(18,8),

    cBenef varchar(10)
) 


Declare @Tab Table(
  ChaveTab Int Identity(1,1) PRIMARY KEY
, Obs_Fiscal varchar(800)
)

Declare @NumPdv int,
        @Chave int,
        @ChaveTab int,
        @CodPrd int,
        @SeqIte int,
        @CodLot varchar(20),
        @DatVct datetime,
        @DatFab datetime,
        @QtdMesVld integer,
        @WCodLotOri varchar(20),
        @WValDif numeric(18,8),
        @ParDif numeric(4,2),
        @WValLimDif numeric(18,8),

        @WStatusCab varchar(1),
        @WTipNotCab varchar(1),
        @WValCabRetCStat smallint,
        @WCodTipCon varchar(1),
        @WDatEmiCab datetime,
        @WValCabCodRegTri int,
        @WValCabTipConsumidor varchar(1),
        @WValCabUFEmi varchar(2),
        @WValCabUFDes varchar(2),
        @WValCabBasIcm numeric(18,8),
        @WValCabIcm numeric(18,8),
        @WValCabIcmPro numeric(18,8),
        @WValCabDscCom numeric(18,8),
        @WValCabDscBon numeric(18,8),
        @WValCabRepIcm numeric(18,8),
        @WValCabDscTri numeric(18,8),
        @WValCabBasIcmSbt numeric(18,8),
        @WValCabIcmSbt numeric(18,8),
        @WValCabBasSbtRes numeric(18,8),
        @WValCabSbtRes numeric(18,8),
        @WValCabSbtEmb numeric(18,8),
        @WValCabIpi numeric(18,8),
        @WValCabDevIpi numeric(18,8),
        @WValCabPis numeric(18,8),
        @WValCabCof numeric(18,8),
        @WValCabIcmParDes numeric(18,8), 
        @WValCabIcmParRem numeric(18,8),
        @WValCabCodCmpCli varchar(20),
        @WValCabIcmFcpDes numeric(18,8), 
        @WValCabFcpIcm numeric(18,8), 
        @WValCabFcpSbt numeric(18,8), 
        @WValCabFcpSbtRet numeric(18,8), 
        @WValCabDscSufram numeric(18,8), 
        @WCabObsRodape varchar(max),
        @WCabInsSufram varchar(9),

        @WDesProduto varchar(120),
        @WDesCplProduto varchar(max),
        @WTipLisPis varchar(3),
        @WVlrTotBruIte numeric(18,8),
        @WVlrTotLiqIte numeric(18,8),
        @WVlrDscTotIte numeric(18,8),
        @WVlrBasRepIcm numeric(18,8),
        @WPerRepIcm numeric(7,4),
        @WVlrRepIcm numeric(18,8),
        @WFlgDscItePdv bit,
        @WPrcUniPdv numeric(18,8),
        @WPerDscPdv numeric(8,4),
        @WPerDsc    numeric(8,4),
        @WVlrBasSbtRes numeric(18,8),
        @WVlrBasSbtEmb numeric(18,8),
        @WVlrSbtRes numeric(18,8), 
        @WVlrSbtEmb numeric(18,8),
        @WTipCon varchar(1),
        @WVlrDscTri numeric(18,8),
        @WPerDscTri numeric(18,2),
        @WPerDscIte numeric(18,2),
        @WDesFabric varchar(25),
        @WTipPor344 varchar(2),
        @WTipSai varchar(1),
        @WStrVolEmb varchar(50),
        @WObsIteNf varchar(800),
        @WPrcFabric numeric(18,8),
        @WPerParIcmDef numeric(8,4),
        @WPerAlqInterestaDef numeric(8,4),
        @WAlqIcm numeric(8,4),
        @WObsAux varchar(max),
        @WObsFis varchar(800)


-- normaliza PRODU
Update PRODU
   Set Reg_MS = IsNull(Reg_MS,'')
 Where Reg_MS <> Ltrim(Rtrim(Reg_MS))

-- preencher com zeros à esquerda até 13 posições
Update PRODU
Set Reg_MS = Substring('0000000000000',1,13-Len(Reg_MS))+Reg_MS
Where IsNull(Reg_MS,'') <> ''
And Len(IsNull(Reg_MS,'')) < 13 
And ISNULL(Reg_MS, '') <> 'ISENTO' 

-- parametros na memoria
Declare @pm_FlgImpDscEmbNot bit,
        @pm_CtrImpIteNotFis varchar(1),
        @pm_CodImpPrcFab varchar(1),
        @pm_CodImpDscFab varchar(1),
        @pm_CodImpPMC varchar(1),
        @pm_VerNfe varchar(20),
        @WSelect varchar(max)

Select @pm_FlgImpDscEmbNot = IsNull(FlgImpDscEmbNot,0),
       @pm_CtrImpIteNotFis = IsNull(Ctr_ImpIteNotFis,'') 
From PARAM 
Where Cod_Estabe = @PCodEstabe

Set @pm_CodImpPrcFab = Substring((Select LTrim(Val_Param) From FS_PARAM Where Cod_Estabe = @PCodEstabe and Cod_Param = 'NFE_CFG_DNF_PFABNFE'),1,1)
Set @pm_CodImpDscFab = Substring((Select LTrim(Val_Param) From FS_PARAM Where Cod_Estabe = @PCodEstabe and Cod_Param = 'NFE_CFG_DNF_IMPFBNFE'),1,1)
Set @pm_CodImpPMC = Substring((Select LTrim(Val_Param) From FS_PARAM Where Cod_Estabe = @PCodEstabe and Cod_Param = 'NFE_CFG_DNF_PMCNFE'),1,1)
-- versão da NF-e
Set @pm_VerNfe = Substring((Select Ltrim(Rtrim(Val_Param)) From FS_PARAM Where Cod_Estabe = @PCodEstabe and Cod_PARAM = 'NFE_CFG_VER'),1,20)
if (@pm_VerNfe <> '') and (charIndex('.',@pm_VerNfe) = 0)
  Set @pm_VerNfe = @pm_VerNfe + '.0'

-------------------------------------------------------------------------------------------------------------------------
if @PTipNota = 'S'
  begin

    -- atualiza IE cabecalho
    Update cb 
       Set cb.Cgf = cl.Cgf
     From NFSCB cb 
          Inner Join CLIEN cl on cb.Cod_Cliente = cl.Codigo
    Where cb.Cod_Estabe = @PCodEstabe 
      and cb.Ser_Nota = @PSerNota 
      and cb.Num_Nota = @PNumNota
      and cb.Cod_Cliente > 0
      And IsNull(cl.Cgf,'') <> ''
      And cb.Cgf <> cl.Cgf

    Update cb 
       Set cb.Inscricao_Suframa = cl.Inscricao_Suframa
      From NFSCB cb 
           Inner Join CLIEN cl on cb.Cod_Cliente = cl.Codigo
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Ser_Nota = @PSerNota 
       and cb.Num_Nota = @PNumNota
       and cb.Cod_Cliente > 0
       And IsNull(cl.Inscricao_Suframa,'') <> ''
       And cb.Inscricao_Suframa <> cl.Inscricao_Suframa

    Update cb 
       Set cb.Cgf = fo.Cgf_Rg
      From NFSCB cb 
           Inner Join FORNE fo on cb.Cod_Fornecedor = fo.Codigo
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Ser_Nota = @PSerNota 
       and cb.Num_Nota = @PNumNota
       and cb.Cod_Fornecedor > 0
       and IsNull(fo.Cgf_Rg,'') <> ''
       and cb.Cgf <> fo.Cgf_Rg

    Exec PR_CalcTributSTRetAntNFSCB @PCodEstabe, @PSerNota, @PNumNota

    -- monta mensagens NFS em NSCOB e NSIOB
    Exec PR_GeraMensagensNF @PCodEstabe, @PNumNota, @PSerNota, @PTipNota

    Select @NumPdv = IsNull(cb.Cod_Pedido,0), 
           @WStatusCab = IsNull(cb.Status,''),
           @WValCabRetCStat = IsNull(cb.Ret_CStat,0),
           @WTipNotCab = cb.Tip_Saida, 
           @WCodTipCon = dbo.FN_CodTipConsum (cb.Tip_Consumidor, '', cb.Cgc, cb.Cgf, cb.Estado),
           @WDatEmiCab = cb.Dat_Emissao,
           @WValCabCodRegTri = IsNull(cb.Cod_RegTri,0),
           @WValCabTipConsumidor = IsNull(cb.Tip_Consumidor,''),
           @WValCabUFEmi = IsNull(es.Des_Estado,''),
           @WValCabUFDes = IsNull(cb.Estado,''),
           @WValCabBasIcm = Round(IsNull(cb.Vlr_BasIcmsTri,0),2),
           @WValCabIcm = Round(IsNull(cb.Vlr_IcmsTri,0),2),
           @WValCabIcmPro = Round(IsNull(cb.Vlr_IcmsNor,0),2),
           @WValCabDscCom = Round(IsNull(cb.Vlr_DescontoCom,0),2),
           @WValCabDscBon = Round(IsNull(cb.Vlr_DscBon,0),2),
           @WValCabRepIcm = Round(IsNull(cb.Vlr_RepIcms,0),2),
           @WValCabDscTri = Round(IsNull(cb.Vlr_DscTri,0),2),
           @WValCabBasIcmSbt = Round(IsNull(cb.Vlr_BasSubsTrib,0),2),
           @WValCabIcmSbt = Round(IsNull(cb.Vlr_SubsTrib,0),2),
           @WValCabBasSbtRes = Round(IsNull(cb.Vlr_BasSbtRes,0),2),
           @WValCabSbtRes = Round(IsNull(cb.Vlr_SbtRes,0),2),
           @WValCabSbtEmb = Round(IsNull(oc.Vlr_SubsTrib,0),2),  -- aqui pode ser Vlr_SbtRes, recalcular este valor
           @WValCabIpi = Case When (cb.Tip_Saida = 'D') and (IsNull(cb.Vlr_Ipi,0) > 0) then 0 Else Round(IsNull(cb.Vlr_Ipi,0),2) End, 
           @WValCabDevIpi = Case When (cb.Tip_Saida = 'D') and (IsNull(cb.Vlr_Ipi,0) > 0) then Round(IsNull(cb.Vlr_Ipi,0),2) Else 0 End, 
           @WValCabPis = Round(IsNull(cb.Vlr_Pis,0),2),
           @WValCabCof = Round(IsNull(cb.Vlr_Cofins,0),2),
           @WValCabIcmParDes = Round(IsNull(cb.Vlr_IcmParDes,0),2), 
           @WValCabIcmParRem = Round(IsNull(cb.Vlr_IcmParRem,0),2),
           @WValCabCodCmpCli = IsNull(cb.Ide_PedCmp,''),
           @WValCabIcmFcpDes = Round(IsNull(cb.Vlr_IcmFcpDes,0),2), 
           @WValCabFcpIcm = Round(IsNull(cb.Vlr_FcpIcm,0),2), 
           @WValCabFcpSbt = Round(IsNull(cb.Vlr_FcpSbt,0),2), 
           @WValCabFcpSbtRet = Round(IsNull(cb.Vlr_FcpSbtRet,0),2),
           @WValCabDscSufram = Round(IsNull(cb.Vlr_DscCalSuframa,0),2),
           @WCabObsRodape = IsNull(cb.Obs_Rodape,''),
           @WCabInsSufram = IsNull(cb.Inscricao_Suframa,'?')
      From NFSCB cb 
           Inner Join ESTAB es on cb.Cod_Estabe = es.Cod_Estabe
           left join NSOCB oc on ((cb.Cod_Estabe = oc.Cod_Estabe) and (cb.Ser_Nota = oc.Ser_Nota) and (cb.Num_Nota = oc.Num_Nota))       
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Ser_Nota = @PSerNota 
       and cb.Num_Nota = @PNumNota

/* aqui registros em NSCOB montados em uFiscal

    -- Observacao cabeçalho
    Set @WObsAux = Ltrim(Rtrim(@WCabObsRodape))

    Delete From @Tab


    Insert Into @Tab (Obs_Fiscal)
      Select Des_Observ From NSCOB
       Where Cod_Estabe = @PCodEstabe 
         and Ser_Nota = @PSerNota 
         and Num_Nota = @PNumNota

    While Exists(Select 1 From @Tab)
      begin
        Select top 1
               @ChaveTab = ChaveTab
             , @WObsFis = Obs_Fiscal
          From @Tab
         Order by ChaveTab

        if PatIndex(@WObsFis+'%', @WObsAux) = 0
          begin
            if (Len(@WObsAux) > 0) and
               (Substring(@WObsAux,1,Len(@WObsAux)) <> ';')
              Set @WObsAUx = @WObsAux + ';  '

            Set @WObsAux = @WObsAux + @WObsFis
          end

        Delete From @Tab Where ChaveTab = @ChaveTab
      end

    -- FECOP Icms
    if (@WValCabFcpIcm > 0) and  -- NFSCB: Vlr_FcpIcm, Vlr_BasIcmsNor
       (PatIndex('%B.Calculo Fecop%', @WObsAux) = 0)
      begin
        if (Len(@WObsAux) > 0) and
           (Substring(@WObsAux,1,Len(@WObsAux)) <> ';')
          Set @WObsAUx = @WObsAux + ';  '

        Set @WObsAux = @WObsAux + 
                               'B.Calculo Fecop: '+cast(cast(Round(@WValCabIcmPro,2) as money) as varchar)+' '+
                       'Vlr.Fecop: '+cast(cast(Round(@WValCabFcpIcm,2) as money) as varchar) -- +char(13)+char(10)
      end

    -- FECOP ST
    if (@WValCabFcpSbt > 0) and  -- NFSCB.Vlr_FcpSbt
       (PatIndex('%B.Calc.Fecop ST%', @WObsAux) = 0)
      begin
        if (Len(@WObsAux) > 0) and
           (Substring(@WObsAux,1,Len(@WObsAux)) <> ';')
          Set @WObsAUx = @WObsAux + ';  '

        Set @WObsAux = @WObsAux + 
                               'B.Calc.Fecop ST: '+cast(cast(Round(@WValCabBasIcmSbt,2) as money) as varchar)+' '+
                       'Vlr.Fecop ST: '+cast(cast(Round(@WValCabFcpSbt,2) as money) as varchar) -- +char(13)+char(10)
      end

    -- SUFRAMA
        -- Conforme ICM (65/88) e Lei 10.966/2004 Art 2º desconto de R$ 99,99 aplicado ref. isenção ICMS - 12% Suframa destinatário XXXXXXXXX
    if (@WValCabDscSufram > 0) and
       (PatIndex('%Lei 10.966/2004%', @WObsAux) = 0)
      begin
        Set @WAlqIcm = 0

        -- pegar alq de um item suframa....  
        Select Top 1 @WAlqIcm = Case When (@WTipNotCab <> 'D') then Isnull(rx.Alq_IcmExtLoc,0) Else Isnull(rx.Alq_IcmExtReg,0) End
          From NFSIT it
               inner Join RTXCT rx on rx.Cod_RegTri = @WValCabCodRegTri and rx.Cod_ClaTri = it.Cod_ClaTri
         Where IsNull(it.Vlr_DscCalSuframa,0) > 0 

        if (Len(@WObsAux) > 0) and
           (Substring(@WObsAux,1,Len(@WObsAux)) <> ';')
          Set @WObsAUx = @WObsAux + ';  '

        Select @WObsAux = @WObsAux +
                          'Conforme ICM (65/88) e Lei 10.966/2004 Art 2º '+
                          'desconto de '+cast(cast(Round(@WValCabDscSufram,2) as money) as varchar)+' '+
                          'aplicado ref. isenção ICMS - '+cast(cast(Round(@WAlqIcm,2) as money) as varchar)+'% '+
                          'destinatario '+cl.Razao_Social  -- +char(13)+char(10)
             From NFSCB cb 
                  Inner Join CLIEN cl on cb.Cod_CLiente = cl.Codigo
             Where cb.Cod_Estabe = @PCodEstabe
             And cb.Ser_Nota = @PSerNota
             And cb.Num_Nota = @PNumNota
      end

    if @WObsAux <> ''
      Update NFSCB
        Set Obs_Rodape = @WObsAux
      Where Cod_Estabe = @PCodEstabe
      And Ser_Nota = @PSerNota
      And Num_Nota = @PNumNota

*/

    if Exists(Select 1 From NFSIT it Inner Join PRODU pr on pr.Codigo = it.Cod_Produto
               Where it.Cod_Estabe = @PCodEstabe
                 And it.Num_Nota = @PNumNota
                 And it.Ser_Nota = @PSerNota
                 And IsNull(it.Cod_NCM,'') <> cast(Substring(IsNull(pr.Cod_ClaFis,''),1,8) as varchar))
      begin
        Exec PR_RecalculaPisCofins @PCodEstabe, @PNumNota, @PSerNota, @PTipNota
        if @@error <> 0
          begin
            Rollback Transaction
            Return
          end
      end

    Update it
       Set it.Cod_NCM = cast(Substring(IsNull(pr.Cod_ClaFis,''),1,8) as varchar)
      From NFSIT it
           Inner Join PRODU pr on pr.Codigo = it.Cod_Produto
     Where it.Cod_Estabe = @PCodEstabe
       And it.Num_Nota = @PNumNota
       And it.Ser_Nota = @PSerNota
       And IsNull(it.Cod_NCM,'') <> cast(Substring(IsNull(pr.Cod_ClaFis,''),1,8) as varchar)
       And ((@WValCabRetCStat <> 100) and (@WValCabRetCStat <> 101) and (@WValCabRetCStat <> 102))
       And @WStatusCab <> 'C'

    Update it
       Set it.Cod_CEST = cast(Substring(IsNull(pr.Cod_CEST,''),1,7) as varchar)
      From NFSIT it
           Inner Join PRODU pr on pr.Codigo = it.Cod_Produto
     Where it.Cod_Estabe = @PCodEstabe
       And it.Num_Nota = @PNumNota
       And it.Ser_Nota = @PSerNota
       And IsNull(it.Cod_CEST,'') <> cast(Substring(IsNull(pr.Cod_CEST,''),1,7) as varchar)
       And ((@WValCabRetCStat <> 100) and (@WValCabRetCStat <> 101) and (@WValCabRetCStat <> 102))
       And @WStatusCab <> 'C'

    Update it
       Set it.Cod_GrpPrc = IsNull(pr.Cod_GrpPrc,'')
      From NFSIT it
           Inner Join PRODU pr on pr.Codigo = it.Cod_Produto
     Where it.Cod_Estabe = @PCodEstabe
       And it.Num_Nota = @PNumNota
       And it.Ser_Nota = @PSerNota
--       And IsNull(it.Cod_GrpPrc,'') = ''
       And it.Cod_GrpPrc <> IsNull(pr.Cod_GrpPrc,'')
       And ((@WValCabRetCStat <> 100) and (@WValCabRetCStat <> 101) and (@WValCabRetCStat <> 102))
       And @WStatusCab <> 'C'

    Update it
       Set it.Cod_OriMer = IsNull(pr.Cod_OriMer,'0')
      From NFSIT it
           Inner Join PRXES pr on pr.Cod_Estabe = it.Cod_Estabe and pr.Cod_Produt = it.Cod_Produto
     Where it.Cod_Estabe = @PCodEstabe
       And it.Num_Nota = @PNumNota
       And it.Ser_Nota = @PSerNota
--       And IsNull(it.Cod_OriMer,'') = ''
       And it.Cod_OriMer <> IsNull(pr.Cod_OriMer,'0')
       And ((@WValCabRetCStat <> 100) and (@WValCabRetCStat <> 101) and (@WValCabRetCStat <> 102))
       And @WStatusCab <> 'C'


    -- atualiza dados faturamento por peso/volume
    Update it
      Set it.Des_UnvPesVolImpFat = ap.Des_UndPesVolApr,
          it.Qtd_PesVolImpFat = (it.Qtd_Produto+it.Qtd_Bonificacao)/it.Fat_CnvImpFat*ap.Qtd_PesVolApr,
          it.Prc_UniPesVolImpFat = it.Prc_Unitario*it.Fat_CnvImpFat/ap.Qtd_PesVolApr
    From NFSIT it 
         Inner Join PARAM pm on it.Cod_Estabe = pm.Cod_Estabe
         Inner Join PRXAP ap on it.Cod_Produto = ap.Cod_Produt and it.Fat_CnvImpFat = ap.Fat_CnvApr
    Where it.Cod_Estabe = @PCodEstabe
    And it.Num_Nota = @PNumNota
    And it.Ser_Nota = @PSerNota
    And it.Fat_CnvImpFat > 0
    And IsNull(it.Des_UnvImpFat,'') = IsNull(ap.Des_UnvApr,'')
    And IsNull(pm.FlgAltUnvItePdv,0) = 1
    And ((IsNull(ap.Flg_FatPes,0) = 1) or (IsNull(ap.Flg_FatVol,0) = 1))
    And IsNull(ap.Qtd_PesVolApr,0) > 0


    -- % FCP default
    Set @WPerParIcmDef = IsNull((Select max(Per_PrvParIcm)
                                 From NFSIT
                                 Where Cod_Estabe = @PCodEstabe
                                 And Num_Nota = @PNumNota
                                 And Ser_Nota = @PSerNota),0)
      
    -- 7%  UF Emissao: Sul e SE exceto ES:  ';MG;RJ;SP;PR;SC;RS;'
    --        Destino: N, NE e ES
    if (Charindex(@WValCabUFEmi,';MG;RJ;SP;PR;SC;RS;') > 0) and   -- S, SE, exceto ES
           (Charindex(@WValCabUFDes,';MG;RJ;SP;PR;SC;RS;') = 0)       -- N, NE e ES
      Set @WPerAlqInterestaDef = 7.00
    else
      Set @WPerAlqInterestaDef = 12.00


    -- atualiza cBenef NFSIT: UF Emitente
    -- Exige o código de benefício fiscal (cBenef) quando se utiliza um CST de benefício fiscal (20, 30, 40, 41, 50, 51, 60 ou 90).
        -- verifica beneficio por NCM
        -- devolucao ?????
/*
    Update it
      Set it.cBenef = ''
    From NFSIT it
    Where it.Cod_Estabe = @PCodEstabe
    And it.Num_Nota = @PNumNota
    And it.Ser_Nota = @PSerNota

    Update it
      Set it.cBenef = IsNull(un.Cod_Benefe,'')
    From NFSIT it
         Inner JOIN UFNCM un on (un.Cod_UF = @WValCabUFEmi) and (un.Cod_NCM = Substring(it.Cod_NCM,1,Len(IsNull(un.Cod_NCM,''))))
    Where it.Cod_Estabe = @PCodEstabe
    And it.Num_Nota = @PNumNota
    And it.Ser_Nota = @PSerNota
    And IsNull(un.Cod_Benefe,'') <> ''
--    And Charindex(it.Ctrl_Tributacao,';20;30;40;41;50;51;60;90;') > 0
    And Charindex(it.Ctrl_Tributacao,dbo.FN_ListaCSTBeneficio(un.Cod_Benefe)) > 0
    And Len(IsNull(un.Cod_NCM,'')) < 8

    Update it
      Set it.cBenef = IsNull(un.Cod_Benefe,'')
    From NFSIT it
         Inner JOIN UFNCM un on un.Cod_UF = @WValCabUFEmi and un.Cod_NCM = it.Cod_NCM
    Where it.Cod_Estabe = @PCodEstabe
    And it.Num_Nota = @PNumNota
    And it.Ser_Nota = @PSerNota
    And IsNull(un.Cod_Benefe,'') <> ''
    And Charindex(it.Ctrl_Tributacao,dbo.FN_ListaCSTBeneficio(un.Cod_Benefe)) > 0

        -- verifica beneficio por Produto
    Update it
      Set it.cBenef = IsNull(up.Cod_Benefe,'')
    From NFSIT it
         Inner JOIN UFXPR up on up.Cod_UF = @WValCabUFEmi and up.Cod_Produt = it.Cod_Produto
    Where it.Cod_Estabe = @PCodEstabe
    And it.Num_Nota = @PNumNota
    And it.Ser_Nota = @PSerNota
    And IsNull(up.Cod_Benefe,'') <> ''
    And Charindex(it.Ctrl_Tributacao,dbo.FN_ListaCSTBeneficio(up.Cod_Benefe)) > 0
*/

    Update it
       Set it.cBenef = dbo.FN_RetornaCBenef(@WValCabUFEmi, it.Ctrl_Tributacao, it.Cod_NCM, it.Cod_Produto, @WDatEmiCab)
     From NFSIT it
    Where it.Cod_Estabe = @PCodEstabe
      And it.Num_Nota = @PNumNota
      And it.Ser_Nota = @PSerNota

   -- paleativo: corrige CST 90 para não contribuintes
    Update it
       Set it.Ctrl_Tributacao = '41'
      From NFSIT it
     Where it.Cod_Estabe = @PCodEstabe
       And it.Num_Nota = @PNumNota
       And it.Ser_Nota = @PSerNota
       And @WCodTipCon = 'N'
       And it.Ctrl_Tributacao = '90'

   -- paleativo: corrige % Repasse enquanto este % não for determinado pela procedure PR_CalTributItem....
    Update it
       Set it.Per_RepIcms = Case
                              When it.Vlr_RepIcms = 0 then 0
                              When (IsNull(rx.Cod_RegTri,0) > 0) and (@WTipNotCab <> 'D') then Round(rx.C_PerRepIcmLoc,2)
                              When (IsNull(rx.Cod_RegTri,0) > 0) and (@WTipNotCab  = 'D') then Round(rx.C_PerRepIcmReg,2)
                              -- Diego: Forçando o valor para a Neosul (Clamed) Temporário, rever com o Cládio
                              When (IsNull(it.Vlr_BasRepIcms,0) > 0) and (Round(it.Vlr_RepIcms*100/it.Vlr_BasRepIcms,2) > 14) then 14.58
                              When (IsNull(it.Vlr_BasRepIcms,0) > 0) and (Round(it.Vlr_RepIcms*100/it.Vlr_BasRepIcms,2) >  6) then  6.82
                              When IsNull(it.Vlr_BasRepIcms,0) > 0 then Round(it.Vlr_RepIcms*100/it.Vlr_BasRepIcms,2)
                              Else 0
                            End
      From NFSIT it
           left Join RTXCT rx on rx.Cod_RegTri = @WValCabCodRegTri and rx.Cod_ClaTri = it.Cod_ClaTri
     Where it.Cod_Estabe = @PCodEstabe
       And it.Num_Nota = @PNumNota
       And it.Ser_Nota = @PSerNota
       And IsNull(it.Per_RepICms,0) = 0

    Insert Into #TMP_Itens
      Select it.Cod_Produto, it.Num_SeqIte,
             Num_SeqPdc = Case 
                            When IsNull(it.Num_SeqPdc,'') <> '' then Substring(IsNull(it.Num_SeqPDc,''),1,6)
                            Else Substring(Cast(it.Num_SeqIte as varchar),1,6)
                          End,
             Cod_EAN = Case 
                         When (IsNull(pr.Cod_Ean, '') = '') and Exists(Select 1 From PREAN pe Where pr.Codigo = pe.Cod_Produt And pe.Tip_Cod = '3') Then
                             (Select top 1 IsNull(pe.Cod_Ean, '') 
                                From PREAN pe 
                               Where pr.Codigo = pe.Cod_Produt 
                                 And pe.Tip_Cod = '3'
                                 And len(pe.Cod_Ean) > 1 
                               Order by len(pe.Cod_Ean) Desc)
                         When (IsNull(pr.Cod_Ean, '') = '') and Exists(Select 1 From PREAN pe  Where pr.Codigo = pe.Cod_Produt And pe.Tip_Cod = '4') Then
                             (Select top 1 IsNull(pe.Cod_Ean, '') 
                                From PREAN pe 
                               Where pr.Codigo = pe.Cod_Produt 
                                 And pe.Tip_Cod = '4'
                                 And len(pe.Cod_Ean) > 1 
                               Order by len(pe.Cod_Ean) Desc)
                         Else IsNull(pr.Cod_Ean,'')
                       End,
             Tip_Sai = IsNull(it.Tip_Sai,''),
             Cod_NCM = IsNull(it.Cod_NCM,''),
             Cod_GrpPrc = IsNull(it.Cod_GrpPrc,''),
             it.Cod_Cfo, 
             Tip_Por344 = IsNull(pr.Tip_Por344,''),
             Tip_LisPis = ISNull(it.Tip_Aux,''),
             Des_Produto = Case 
                             When ix.Cod_Produt > 0 then Substring(ix.Des_PrdDet,1,120) 
                             When IsNull(it.Des_AprImpFat,'') <> '' then rtrim(pr.Descri)+' '+it.Des_AprImpFat
                             Else pr.Descricao
                           End,
             Obs_Produto = '', 

             Und_Com = Case
                         When IsNull(it.Qtd_PesVolImpfat,0) > 0 then it.Des_UnvPesVolImpFat
                             When (IsNull(it.Qtd_ImpFat,0) > 0) and (IsNull(it.Prc_UniImpFat,0) > 0) and (IsNull(it.Des_UnvImpFat,'') <> '') and
                              (not Exists(Select 1 From NFSIT 
                                           Where Cod_Estabe = it.Cod_Estabe 
                                             And Ser_Nota = it.Ser_Nota And Num_Nota = it.Num_Nota
                                             And Cod_Produto = it.Cod_Produto
                                             And Qtd_ImpFat-cast(Qtd_ImpFat as integer) <> 0)) then it.Des_UnvImpFat
                         When ((ix.Cod_Produt > 0) and (IsNull(ix.Des_UndVen,'') <> '')) then ix.Des_UndVen
                         Else pr.Unidade_Venda
                       End,
             Qtd_Com = Case 
                         When IsNull(it.Qtd_PesVolImpfat,0) > 0 then it.Qtd_PesVolImpfat
                             When (IsNull(it.Qtd_ImpFat,0) > 0) and (IsNull(it.Prc_UniImpFat,0) > 0) and
                              (not Exists(Select 1 From NFSIT 
                                           Where Cod_Estabe = it.Cod_Estabe 
                                             And Ser_Nota = it.Ser_Nota And Num_Nota = it.Num_Nota
                                             And Cod_Produto = it.Cod_Produto
                                             And Qtd_ImpFat-cast(Qtd_ImpFat as integer) <> 0)) then Qtd_ImpFat
                         Else IsNull(it.Qtd_Produto,0)+IsNull(it.Qtd_Bonificacao,0)
                       end,

             Prc_UniCom = Case 
                            When IsNull(it.Qtd_PesVolImpfat,0) > 0 then it.Prc_UniPesVolImpFat
                                When (IsNull(it.Qtd_ImpFat,0) > 0) and (IsNull(it.Prc_UniImpFat,0) > 0) and
                                 (not Exists(Select 1 From NFSIT 
                                              Where Cod_Estabe = it.Cod_Estabe 
                                                And Ser_Nota = it.Ser_Nota And Num_Nota = it.Num_Nota
                                                And Cod_Produto = it.Cod_Produto
                                                And Qtd_ImpFat-cast(Qtd_ImpFat as integer) <> 0)) then it.Prc_UniImpFat
                            Else IsNull(it.Prc_Unitario,0)
                          end,

             Vlr_TotBruIte = Round(IsNull(it.Prc_Unitario,0)*(IsNull(it.Qtd_Produto,0)+IsNull(it.Qtd_Bonificacao,0)),2),
--             Vlr_TotIte = Round(IsNull(it.Qtd_Produto,0)*(IsNull(it.Prc_Unitar,0)*(1-IsNull(it.Per_Desconto,0)/100)),2),
--             Vlr_TotIte = Round(IsNull(it.Vlr_TotItem,0),2),
             Vlr_TotIte = Case
                            When Round(IsNull(it.Vlr_TotItem,0),2) <= Round(IsNull(it.Prc_Unitario,0)*(IsNull(it.Qtd_Produto,0)+IsNull(it.Qtd_Bonificacao,0)),2)
                                 Then Round(IsNull(it.Vlr_TotItem,0),2) 
                            Else Round(IsNull(it.Prc_Unitario,0)*(IsNull(it.Qtd_Produto,0)+IsNull(it.Qtd_Bonificacao,0)),2)
                          End,
             Per_Desconto = IsNull(it.Per_Desconto,0),
             Vlr_BasRepIcm = IsNull(it.Vlr_BasRepIcms,0),
             Per_RepIcm = IsNull(it.Per_RepIcms,0),
             Vlr_RepIcm = Round(IsNull(it.Vlr_RepIcms,0),2),
             Tip_Consumidor = @WValCabTipConsumidor,
             Vlr_DscTri = Round(IsNull(it.Vlr_DscTri,0),2),
                         Per_DscTri = IsNull(it.Per_DscTri,0),
             Vlr_DscRat = Round(IsNull(it.Vlr_DescRateado,0),2),
             Vlr_DscBonRat = Round(IsNull(it.Vlr_DscBonRat,0),2),
             Vlr_DscTotIte = 0,
             Vlr_BasSbtRes = Round(IsNull(it.Vlr_BasSbtRes,0),2),        
             Vlr_SbtRes = Round(IsNull(it.Vlr_SbtRes,0),2), 
             Vlr_BasSbtEmb = Round(IsNull(oi.Vlr_BasSubsTrib,0),2),
             Vlr_SbtEmb = Round(IsNull(oi.Vlr_SubsTrib,0),2),
             it.Cod_Lote, 
             it.Cod_Lote, 
             IsNull(lt.Dat_Vencim,0),
             IsNull(lt.Dat_Fabric,0),
             IsNull(pr.Validade,0),
             Vlr_Frete  = Round(IsNull(it.Vlr_Frete,0),2),
             Vlr_Seguro = Round(IsNull(it.Vlr_Seguro,0),2),
             Vlr_DspRat = Round(IsNull(it.Vlr_DespRateada,0),2),
             Vlr_DspExt = Round(IsNull(it.Vlr_DspExt,0),2),
             Vlr_TotDsp = 0,
             Und_Tri = pr.Unidade_Venda,
             Qtd_Tri = IsNull(it.Qtd_Produto,0)+IsNull(it.Qtd_Bonificacao,0),
             Prc_UniTri = IsNull(it.Prc_Unitario,0),          
             Cod_OriPrd = IsNull(it.Cod_OriMer,'0'),
             Cod_CstIcm = IsNull(it.Ctrl_Tributacao,''),
             Cod_CsosnIcm = IsNull(it.Cod_CSOSN,''),
             Cod_ModBasCalIcm = IsNull(it.Cod_ModBasCalIcm,''),
             Per_RedBasCalIcm = IsNull(it.Per_RedBasCalIcm,0),
             Vlr_BasIcm = Round(IsNull(it.Vlr_BasIcmsTri,0),2),
             Alq_Icm = IsNull(it.Alq_Icms,0),
             Vlr_Icm = Round(IsNull(it.Vlr_IcmsTri,0),2),
             Dif_VlrIcm = Round(IsNull(it.Vlr_IcmsTri,0),2) - IsNull(it.Vlr_IcmsTri,0),
             Vlr_BasIcmPro = Round(IsNull(it.Vlr_BasIcmsNor,0),2),
             Vlr_IcmPro = Round(IsNull(it.Vlr_IcmsNor,0),2),
             Per_IcmDiferi = IsNull(it.Per_IcmDiferi,0),
             Vlr_IcmDiferi = Round(IsNull(it.Vlr_IcmDiferi,0),2),
             Vlr_DscCalSuframa = Round(IsNull(it.Vlr_DscCalSuframa,0),2),
             Vlr_IcmDesone = IsNull(it.Vlr_IcmsDeson,0), 
             Cod_MtvIcmDesone = IsNull(it.Cod_MtvIcmsDeson,''),
             Vlr_BasIcmSbtRet = 0,
             Vlr_IcmSbtRet = 0,  --IsNull(oi.Vlr_SubsTrib,0),
             Cod_ModBasCalIcmSbt = IsNull(it.Cod_ModBasCalIcmSbt,''),
             Alq_AgrSbt = IsNull(it.Alq_AgrSbt,0), 
             Per_RedBasCalIcmSbt = IsNull(it.Per_RedBasCalIcmSbt,0),
             Vlr_BasIcmSbt = Round(IsNull(it.Vlr_BasSubsTrib,0),2),
             Alq_IcmSbt = IsNull(it.Alq_IcmSbt,0),
             Vlr_IcmSbt = Round(IsNull(it.Vlr_SubsTrib,0),2),

             CST_Ipi    = Case When IsNull(CST_Ipi,'') = '' then '99' Else CST_Ipi End, -- outras
                         Cod_EnqIpi = Case When IsNull(Cod_EnqIpi,'') = '' then '999' Else Cod_EnqIpi End,
                         Vlr_BasIpi = Case When (@WTipNotCab = 'D') and (IsNull(it.Vlr_BasIpi,0) > 0) then 0 Else Round(IsNull(it.Vlr_BasIpi,0),2) End,
             Alq_Ipi    = Case When (@WTipNotCab = 'D') and (IsNull(it.Vlr_Ipi,0) > 0) then 0 
                               Else Case When it.Vlr_TotItem > 0 then (it.Vlr_Ipi * 100 / it.Vlr_TotItem) Else 0 End End, 
             Vlr_Ipi    = Case When (@WTipNotCab = 'D') and (IsNull(it.Vlr_Ipi,0) > 0) then 0 Else IsNull(it.Vlr_Ipi,0) End, 
                         Vlr_BasDevIpi = Case When (@WTipNotCab = 'D') and (IsNull(it.Vlr_BasIpi,0) > 0) then Round(IsNull(it.Vlr_BasIpi,0),2) Else 0 End,
             Per_DevIpi = Case When (@WTipNotCab = 'D') and (IsNull(it.Vlr_Ipi,0) > 0) then 100.00 Else 0 End,
             Vlr_DevIpi = Case When (@WTipNotCab = 'D') and (IsNull(it.Vlr_Ipi,0) > 0) then it.Vlr_Ipi Else 0 End,

             it.CST_Pis, it.Vlr_BasPis, it.Alq_Pis, Vlr_Pis = Round(IsNull(it.Vlr_Pis,0),2), 
             Dif_VlrPis = Round(IsNull(it.Vlr_Pis,0),2)-IsNull(it.Vlr_Pis,0), 
             it.CST_Cofins, it.Vlr_BasCofins, it.Alq_Cofins, Vlr_Cofins = Round(IsNull(it.Vlr_Cofins,0),2),
             Dif_VlrCofins = Round(IsNull(it.Vlr_Cofins,0),2)-IsNull(it.Vlr_Cofins,0),
             Prc_MaxCon = Case
                            When @pm_CodImpPMC = '1' then IsNull(it.Prc_MaxCon,0)*IsNull(it.Fat_CnvImpFat,1)
                            Else 0
                          End, 
             Prc_Fabric = IsNull(it.Prc_Fabric,0)*IsNull(it.Fat_CnvImpFat,1), 
             Des_Fabric = Case 
                             When (ix.Cod_Produt > 0) and (IsNull(ix.Des_Fabric,'') <> '') then Substring(ix.Des_Fabric,1,25) 
                             Else Substring(fb.Fantasia,1,25)
                           End,
             Flg_DscItePdv = IsNull(it.Flg_DscItePdv,0),
             Prc_UniPdv = ISNULL(it.Prc_UniPdv,0),
             Per_DscPdv = ISNULL(it.Per_DscPdv,0),
             Cod_CEST = ISNULL(it.Cod_CEST,''),
  
             Vlr_BasIcmDes = Case 
                               When (@WPerParIcmDef > 0) or (IsNull(it.Vlr_IcmFcpDes,0) > 0) then Round(IsNull(it.Vlr_BasIcmsNor,0),2) 
                               Else 0
                             End,
             Per_AcrAlqIntFcp = Case
                                  When (ISNULL(it.Per_PrvParIcm,0) > 0) and (IsNull(it.Vlr_IcmFcpDes,0) > 0) then ISNULL(it.Per_AcrAlqIntFcp,0) 
                                  Else 0
                                End,
             Alq_IntDes = Case 
                            When (@WPerParIcmDef > 0) then ISNULL(it.Alq_IntIcmDes,0)
                            Else 0
                          End,
             Alq_Interesta = Case
                               When (@WPerParIcmDef > 0) and (it.Cod_OriMer IN ('1', '2', '3', '8')) then 4.0 /* DMD-8037: Regra NA09-20 */
                 When (@WPerParIcmDef > 0) and (ISNULL(it.Alq_Icms,0) > 0) then ISNULL(it.Alq_Icms,0)
                               When (@WPerParIcmDef > 0) and (ISNULL(it.Alq_Icms,0) = 0) then @WPerAlqInterestaDef                 
                               Else 0
                             End,
             Per_PrvParIcm = Case 
                               When (@WPerParIcmDef > 0) or (IsNull(it.Vlr_IcmFcpDes,0) > 0) then @WPerParIcmDef 
                               Else 0 
                             End, 
             Vlr_IcmFcpDes = Round(IsNull(it.Vlr_IcmFcpDes,0),2), 
             Vlr_IcmParDes = Round(IsNull(it.Vlr_IcmParDes,0),2), 
             Vlr_IcmParRem = Round(IsNull(it.Vlr_IcmParRem,0),2),
             Cod_PedCmpCli = @WValCabCodCmpCli,
             Str_VolEmb = IsNull(it.Str_VolEmb,''),
             Obs_IteNf = IsNull(it.Obs_Nf,''),
             Reg_MS = IsNull(pr.Reg_MS,''),
             Des_MtvIseRegMS = Substring(IsNull(pr.Des_MtvIseRegMS,''),1,255),

             Alq_FcpIcm = IsNull(it.Alq_FcpIcm,0),
             Vlr_FcpIcm = Round(IsNull(it.Vlr_FcpIcm,0),2),
             Alq_FcpSbt = IsNull(it.Alq_FcpSbt,0),
             Vlr_FcpSbt = Round(IsNull(it.Vlr_FcpSbt,0),2),
             Alq_FcpSbtRet = IsNull(it.Alq_FcpSbtRet,0),
             Vlr_FcpSbtRet = Round(IsNull(it.Vlr_FcpSbtRet,0),2),

             vBCSTRet = IsNull(it.vBCSTRet,0),
             pST = IsNull(it.pST,0),
             vICMSSubstituto = IsNull(it.vICMSSubstituto,0),
             vICMSSTRet = IsNull(it.vICMSSTRet,0),
             vBCFCPSTRet = IsNull(it.vBCFCPSTRet,0),
             pFCPSTRet = IsNull(it.pFCPSTRet,0), 
             vFCPSTRet = Round(IsNull(it.vFCPSTRet,0),2),

             pRedBCEfet = Case When @WValCabTipConsumidor = 'F' then IsNull(it.pRedBCEfet,0) Else 0 End,  -- somente para consumidor final: @WValCabTipConsumidor
             vBCEfet    = Case When @WValCabTipConsumidor = 'F' then IsNull(it.vBCEfet,0)    Else 0 End,
             pICMSEfet  = Case When @WValCabTipConsumidor = 'F' then IsNull(it.pICMSEfet,0)  Else 0 End,
             vICMSEfet  = Case When @WValCabTipConsumidor = 'F' then IsNull(it.vICMSEfet,0)  Else 0 End,

             cBenef = IsNull(it.cBenef,'')

      From NFSIT it
           Inner Join PRODU pr on pr.Codigo = it.Cod_Produto
           Inner Join FABRI fb on fb.Codigo = pr.Cod_Fabricante
           left  join NSOIT oi on ((it.Cod_Estabe = oi.Cod_Estabe) and (it.Ser_Nota = oi.Ser_Nota) and (it.Num_Nota = oi.Num_Nota)       
                              and (it.Cod_Produto = oi.Cod_Produto) and (it.Cod_Lote = oi.Cod_Lote) and (it.Num_SeqIte = oi.Num_SeqIte)) 
           left  join ITDES ix on ((it.Cod_Estabe = ix.Cod_Estabe) and (ix.Num_Pedido = @NumPdv) and (it.Cod_Produto = ix.Cod_Produt)) 
           left  Join (Select Cod_Estabe, Cod_Produt, Cod_Lote,
                              Dat_Vencim = MIN(Dat_Vencim), Dat_Fabric = MIN(Dat_Fabric) 
                        From PRLOT 
                       Where Cod_Estabe = @PCodEstabe
                       Group by Cod_Estabe, Cod_Produt, Cod_Lote) lt on ((it.Cod_Estabe = lt.Cod_Estabe) and (it.Cod_Produto = lt.Cod_Produt) and (it.Cod_Lote = lt.Cod_Lote))
      Where it.Cod_Estabe = @PCodEstabe
        And it.Num_Nota = @PNumNota
        And it.Ser_Nota = @PSerNota
      Order by it.Cod_Produto

  end  -- if @PTipNota = 'S'
else
  begin

    -- se for devolucao
    if @WTipNotCab = 'D'
      Exec PR_CalcTributSTRetAntNFECB @PCodEstabe, @PNumNota

    -- normaliza itens da NF
    Update it
       Set it.Cod_NCM = cast(Substring(IsNull(pr.Cod_ClaFis,''),1,8) as varchar)
      From NFEIT it
           Inner Join PRODU pr on pr.Codigo = it.Cod_Produto
     Where it.Cod_Estabe = @PCodEstabe
       And it.Protocolo = @PNumNota
       And IsNull(it.Cod_NCM,'') <> cast(Substring(IsNull(pr.Cod_ClaFis,''),1,8) as varchar)
       And ((@WValCabRetCStat <> 100) and (@WValCabRetCStat <> 101) and (@WValCabRetCStat <> 102))
       And @WStatusCab <> 'C'

    Update it
       Set it.Cod_CEST = cast(Substring(IsNull(pr.Cod_CEST,''),1,7) as varchar)
      From NFEIT it
           Inner Join PRODU pr on pr.Codigo = it.Cod_Produto
     Where it.Cod_Estabe = @PCodEstabe
       And it.Protocolo = @PNumNota
       And IsNull(it.Cod_CEST,'') <> cast(Substring(IsNull(pr.Cod_CEST,''),1,7) as varchar)
       And ((@WValCabRetCStat <> 100) and (@WValCabRetCStat <> 101) and (@WValCabRetCStat <> 102))
       And @WStatusCab <> 'C'

    Update it
       Set it.Cod_OriMer = IsNull(pr.Cod_OriMer,'0')
      From NFEIT it
           Inner Join PRXES pr on pr.Cod_Estabe = it.Cod_Estabe and pr.Cod_Produt = it.Cod_Produto
     Where it.Cod_Estabe = @PCodEstabe
       And it.Protocolo = @PNumNota
--       And IsNull(it.Cod_OriMer,'') = ''
       And it.Cod_OriMer <> IsNull(pr.Cod_OriMer,'0')
       And ((@WValCabRetCStat <> 100) and (@WValCabRetCStat <> 101) and (@WValCabRetCStat <> 102))
       And @WStatusCab <> 'C'

    -- atualiza IE cabecalho
    Update cb 
       Set cb.Cgf_Rg = fo.Cgf_Rg
      From NFECB cb 
           Inner Join FORNE fo on cb.Cod_EmiFornec = fo.Codigo
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Protocolo = @PNumNota
       and cb.Cod_EmiFornec > 0
       And IsNull(fo.Cgf_Rg,'') <> ''
       And cb.Cgf_Rg <> fo.Cgf_Rg

    Update cb 
       Set cb.Cgf_Rg = cl.Cgf
      From NFECB cb 
           Inner Join CLIEN cl on cb.Cod_EmiCliente = cl.Codigo
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Protocolo = @PNumNota
       and cb.Cod_EmiCliente > 0
       And IsNull(cl.Cgf,'') <> ''
       And cb.Cgf_Rg <> cl.Cgf

    Update cb 
       Set cb.Cgf_Rg = tr.Cgf_Rg
      From NFECB cb 
           Inner Join TRANS tr on cb.Cod_EmiTransp = tr.Codigo
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Protocolo = @PNumNota
       and cb.Cod_EmiTransp > 0
       And IsNull(tr.Cgf_Rg,'') <> ''
       And cb.Cgf_Rg <> tr.Cgf_Rg


    -- monta mensagens NFS em NECOB e NEIOB
    Exec PR_GeraMensagensNF @PCodEstabe, @PNumNota, @PSerNota, @PTipNota

    Select @NumPdv = cb.Cod_Pedido, 
           @WStatusCab = IsNull(cb.Status,''),
           @WValCabRetCStat = IsNull(cb.Ret_CStat,0),
           @WTipNotCab = cb.Tip_NF,
           @WCodTipCon = dbo.FN_CodTipConsum (cb.Tip_Consumidor, '', cb.Cgc_Cpf, cb.Cgf_Rg, cb.Cod_UfOrigem),
           @WDatEmiCab = cb.Dat_Emissao,
           @WValCabCodRegTri = IsNull(cb.Cod_RegTri,0),
           @WValCabTipConsumidor = IsNull(cb.Tip_Consumidor,''),
           @WValCabUFEmi = IsNull(cb.Cod_UFOrigem,''),
           @WValCabUFDes = IsNull(es.Des_Estado,''),
           @WValCabBasIcm = Round(IsNull(cb.Vlr_BasIcmsTri,0),2),
           @WValCabIcm = Round(IsNull(cb.Vlr_IcmsTri,0),2),
           @WValCabIcmPro = Round(IsNull(cb.Vlr_IcmsNor,0),2),
           @WValCabDscCom = Round(IsNull(cb.Vlr_Desconto,0),2),
           @WValCabDscBon = 0,
           @WValCabRepIcm = Round(IsNull(cb.Vlr_RepIcms,0),2),
           @WValCabDscTri = Round(IsNull(cb.Vlr_DscTri,0),2),
           @WValCabBasIcmSbt = Round(IsNull(cb.Vlr_BasIstFon,0),2),
           @WValCabIcmSbt = Round(IsNull(cb.Vlr_IstFon,0),2),
           @WValCabBasSbtRes = Round(IsNull(cb.Vlr_BasSbtRes,0),2),
           @WValCabSbtRes = Round(IsNull(cb.Vlr_SbtRes,0),2),
           @WValCabIpi = Round(IsNull(cb.Vlr_Ipi,0),2),
           @WValCabDevIpi = 0,
           @WValCabPis =  Round(IsNull(cb.Vlr_Pis,0),2),
           @WValCabCof =  Round(IsNull(cb.Vlr_Cofins,0),2),
           @WValCabIcmParDes = Round(IsNull(cb.Vlr_IcmParDes,0),2), 
           @WValCabIcmParRem = Round(IsNull(cb.Vlr_IcmParRem,0),2),
           @WValCabCodCmpCli = '',
           @WValCabIcmFcpDes = Round(IsNull(cb.Vlr_IcmFcpDes,0),2), 
           @WValCabFcpIcm = Round(IsNull(cb.Vlr_FcpIcm,0),2), 
           @WValCabFcpSbt = Round(IsNull(cb.Vlr_FcpSbt,0),2), 
           @WValCabFcpSbtRet = Round(IsNull(cb.Vlr_FcpSbtRet,0),2)
      From NFECB cb 
           Inner Join ESTAB es on cb.Cod_Estabe = es.Cod_Estabe
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Protocolo = @PNumNota

    Set @WPerParIcmDef = IsNull((Select max(Per_PrvParIcm)
                                   From NFEIT
                                  Where Cod_Estabe = @PCodEstabe
                                    And Protocolo = @PNumNota),0)
    -- 7%  UF Emissao: Sul e SE exceto ES:  ';MG;RJ;SP;PR;SC;RS;'
    --        Destino: N, NE e ES
    if (Charindex(@WValCabUFEmi,';MG;RJ;SP;PR;SC;RS;') > 0) and   -- S, SE, exceto ES
           (Charindex(@WValCabUFDes,';MG;RJ;SP;PR;SC;RS;') = 0)       -- N, NE e ES
      Set @WPerAlqInterestaDef = 7.00
    else
      Set @WPerAlqInterestaDef = 12.00
    
    -- atualiza cBenef NFEIT: UF Emitente
    -- Exige o código de benefício fiscal (cBenef) quando se utiliza um CST de benefício fiscal (20, 30, 40, 41, 50, 51, 60 ou 90).
        -- verifica beneficio por NCM
        -- cBenef em devolução é calculado em PR_CalculaTributosEntradasDevlucao
    Exec PR_CalculaBeneficiosEntrada @PCodEstabe, @PNumNota

    Insert Into #TMP_Itens
      Select it.Cod_Produto, it.Num_SeqIte,
             Num_SeqPdc = Substring(Cast(it.Num_SeqIte as varchar),1,6),
             Cod_EAN = Case 
                         When (IsNull(pr.Cod_Ean, '') = '') and Exists(Select 1 From PREAN pe Where pr.Codigo = pe.Cod_Produt And pe.Tip_Cod = '3') Then
                             (Select top 1 IsNull(pe.Cod_Ean, '') 
                                From PREAN pe 
                               Where pr.Codigo = pe.Cod_Produt 
                                 And pe.Tip_Cod = '3'
                                 And len(pe.Cod_Ean) > 1 
                               Order by len(pe.Cod_Ean) Desc)
                         When (IsNull(pr.Cod_Ean, '') = '') and Exists(Select 1 From PREAN pe  Where pr.Codigo = pe.Cod_Produt And pe.Tip_Cod = '4') Then
                             (Select top 1 IsNull(pe.Cod_Ean, '') 
                                From PREAN pe 
                               Where pr.Codigo = pe.Cod_Produt 
                                 And pe.Tip_Cod = '4'
                                 And len(pe.Cod_Ean) > 1 
                               Order by len(pe.Cod_Ean) Desc)
                         Else IsNull(pr.Cod_Ean,'')
                       End,
             Tip_Sai = '',
             Cod_NCM = ISNULL(it.Cod_NCM,''),
             Cod_GrpPrc = IsNull(pr.Cod_GrpPrc,''),
             it.Cod_Cfo, 
             Tip_Por344 = IsNull(pr.Tip_Por344,''),
             Tip_LisPis = ISNull(it.Tip_LisPis,''),
             Des_Produto = pr.Descricao,
             Obs_Produto = '',
             Und_Com = pr.Unidade_Venda,
             Qtd_Com = IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0),
             Prc_UniCom = IsNull(it.Prc_Unitario,0),
             Vlr_TotBruIte = Round(IsNull(it.Prc_Unitario,0)*(IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)),2),
--             Vlr_TotIte = Round(IsNull(it.Qtd_Pedido,0)*(IsNull(it.Prc_Unitario,0)*(1-IsNull(it.Per_DescItem,0)/100)),2),
--             Vlr_TotIte = Round(IsNull(it.Vlr_TotItem,0),2),
             Vlr_TotIte = Case
                            When Round(IsNull(it.Vlr_TotItem,0),2) <= Round(IsNull(it.Prc_Unitario,0)*(IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)),2)
                            Then Round(IsNull(it.Vlr_TotItem,0),2) 
                            Else Round(IsNull(it.Prc_Unitario,0)*(IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)),2)
                          End,
             Per_Desconto = IsNull(it.Per_DescItem,0),
             Vlr_BasRepIcm = IsNull(it.Vlr_BasRepIcm,0),
             Per_RepIcm = IsNull(it.Per_RepIcm,0),
             Vlr_RepIcm = Round(IsNull(it.Vlr_RepIcm,0),2),
             Tip_Consumidor = @WValCabTipConsumidor,
             Vlr_DscTri = Round(IsNull(it.Vlr_DscTri,0),2),
             Per_DscTri = 0,
             Vlr_DscRat = Round(IsNull(it.Vlr_DescRateado,0),2),
             Vlr_DscBonRat = 0,
             Vlr_DscTotIte = 0,
             Vlr_BasSbtRes = Round(IsNull(it.Vlr_BasSbtRes,0),2),        
             Vlr_SbtRes = Round(IsNull(it.Vlr_SbtRes,0),2), 
             Vlr_BasSbtEmb = 0,
             Vlr_SbtEmb = 0, 
             it.Cod_Lote,
             it.Cod_Lote, 
             IsNull(lt.Dat_Vencim,0),
             IsNull(lt.Dat_Fabric,0),
             IsNull(pr.Validade,0),
             Vlr_Frete = Round(IsNull(it.Vlr_Frete,0),2),
             Vlr_Seguro = Round(IsNull(it.Vlr_Seguro,0),2),
             Vlr_DspRat = Round(IsNull(it.Vlr_DespRateada,0),2),
             Vlr_DspExt = Round(IsNull(it.Vlr_DspExt,0),2),
             Vlr_TotDsp = 0,
             Und_Tri = pr.Unidade_Venda,
             Qtd_Tri = IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0),
             Prc_UniTri = IsNull(it.Prc_Unitario,0),          
             Cod_OriPrd = IsNull(it.Cod_OriMer,'0'),
             Cod_CstIcm = IsNull(it.Ctrl_Tributacao,''),
             Cod_CsosnIcm = IsNull(it.Cod_CSOSN,''),
             Cod_ModBasCalIcm = IsNull(it.Cod_ModBasCalIcm,''),
             Per_RedBasCalIcm = IsNull(it.Per_RedBasCalIcm,0),
             Vlr_BasIcm = Round(IsNull(it.Vlr_BasIcmsTrib,0),2),
             Alq_Icm = IsNull(it.Alq_Icms,0),
             Vlr_Icm = Round(IsNull(it.Vlr_IcmsTrib,0),2),
             Dif_VlrIcm = Round(IsNull(it.Vlr_IcmsTrib,0),2) - IsNull(it.Vlr_IcmsTrib,0),
             Vlr_BasIcmPro = Round(IsNull(it.Vlr_BasIcmsNor,0),2),
             Vlr_IcmPro = Round(IsNull(it.Vlr_IcmsNor,0),2),
             Per_IcmDiferi = IsNull(it.Per_IcmDiferi,0),
             Vlr_IcmDiferi = Round(IsNull(it.Vlr_IcmDiferi,0),2),
             Vlr_DscCalSuframa = Round(IsNull(it.Vlr_DscCalSuframa,0),2),
             Vlr_IcmDesone = IsNull(it.Vlr_IcmsDeson,0), 
             Cod_MtvIcmDesone = IsNull(it.Cod_MtvIcmsDeson,''),
             Vlr_BasIcmSbtRet = 0,
             Vlr_IcmSbtRet = 0,
             Cod_ModBasCalIcmSbt = IsNull(it.Cod_ModBasCalIcmSbt,''),
             Alq_AgrSbt = IsNull(it.Alq_AgrDeb,0), 
             Per_RedBasCalIcmSbt = IsNull(it.Per_RedBasCalIcmSbt,0),
             Vlr_BasIcmSbt = Round(IsNull(it.Vlr_BasSubsTrib,0),2),
             Alq_IcmSbt = Case When IsNull(it.Alq_IcmSbt,0) > 0 then it.Alq_IcmSbt Else IsNull(it.Alq_IcmDeb,0) End,  -- ????
             Vlr_IcmSbt = Round(IsNull(it.Vlr_SubsTrib,0),2),
             CST_Ipi    = Case When IsNull(CST_Ipi,'') = '' then '49' Else CST_Ipi End, -- outras
             Cod_EnqIpi = Case When IsNull(Cod_EnqIpi,'') = '' then '999' Else Cod_EnqIpi End,
             Vlr_BasIpi = IsNull(it.Vlr_BasIpi,0),
             Alq_Ipi = Case 
                         When it.Vlr_TotItem > 0 then (it.Vlr_Ipi * 100 / it.Vlr_TotItem) 
                         Else 0
                       End, 
             Vlr_Ipi = it.Vlr_Ipi, 
             Vlr_BasDevIpi = 0,
             Per_DevIpi = 0,
             Vlr_DevIpi = 0,
             it.CST_Pis, it.Vlr_BasPis, it.Alq_Pis, Vlr_Pis = Round(IsNull(it.Vlr_Pis,0),2), 
             Dif_VlrPis = Round(IsNull(it.Vlr_Pis,0),2)-IsNull(it.Vlr_Pis,0), 
             it.CST_Cofins, it.Vlr_BasCofins, it.Alq_Cofins, Vlr_Cofins = Round(IsNull(it.Vlr_Cofins,0),2),
             Dif_VlrCofins = Round(IsNull(it.Vlr_Cofins,0),2)-IsNull(it.Vlr_Cofins,0),
             Prc_MaxCon = Case
                            When @pm_CodImpPMC = '1' then IsNull(it.Prc_MaxCon,0)*IsNull(it.Fator_Fat,1)
                            Else 0
                          End, 
             Prc_Fabric = IsNull(it.Prc_Fabric,0)*IsNull(it.Fator_Fat,1), 
             Des_Fabric = Substring(fb.Fantasia,1,25),
             Flg_DscItePdv = 0,
             Prc_UniPdv = 0,
             Per_DscPdv = 0,
             Cod_CEST = ISNULL(it.Cod_CEST,''),
             
             Vlr_BasIcmDes = Case 
                               When (@WPerParIcmDef > 0) and (IsNull(it.Vlr_IcmFcpDes,0) > 0)  then Round(IsNull(it.Vlr_BasIcmsNor,0),2) 
                               Else 0
                             End,
             Per_AcrAlqIntFcp = Case
                                  When (ISNULL(it.Per_PrvParIcm,0) > 0) and (IsNull(it.Vlr_IcmFcpDes,0) > 0) then ISNULL(it.Per_AcrAlqIntFcp,0)
                                  Else 0
                                End,
             Alq_IntDes = Case 
                            When (@WPerParIcmDef > 0) then ISNULL(it.Alq_IntIcmDes,0)
                            Else 0
                          End,
             Alq_Interesta = Case
                               When (@WPerParIcmDef > 0) and (it.Cod_OriMer IN ('1', '2', '3', '8')) then 4.0 /* DMD-8037: Regra NA09-20 */
                 When (@WPerParIcmDef > 0) and (ISNULL(it.Alq_Icms,0) > 0) then ISNULL(it.Alq_Icms,0)
                               When (@WPerParIcmDef > 0) and (ISNULL(it.Alq_Icms,0) = 0) then @WPerAlqInterestaDef                 
                               Else 0
                             End,
             Per_PrvParIcm = Case 
                               When (@WPerParIcmDef > 0) and (IsNull(it.Vlr_IcmFcpDes,0) > 0) then @WPerParIcmDef 
                               Else 0 
                             End, 

             Vlr_IcmFcpDes = Round(IsNull(it.Vlr_IcmFcpDes,0),2), 
             Vlr_IcmParDes = Round(IsNull(it.Vlr_IcmParDes,0),2),
             Vlr_IcmParRem = Round(IsNull(it.Vlr_IcmParRem,0),2), 
             Cod_PedCmpCli = @WValCabCodCmpCli,
             Str_VolEmb = '',
             Obs_IteNf = '',
             Reg_MS = IsNull(pr.Reg_MS,''),
             Des_MtvIseRegMS = Substring(IsNull(pr.Des_MtvIseRegMS,''),1,255),

             Alq_FcpIcm = IsNull(it.Alq_FcpIcm,0),
             Vlr_FcpIcm = Round(IsNull(it.Vlr_FcpIcm,0),2),
             Alq_FcpSbt = IsNull(it.Alq_FcpSbt,0),
             Vlr_FcpSbt = Round(IsNull(it.Vlr_FcpSbt,0),2),
             Alq_FcpSbtRet = IsNull(it.Alq_FcpSbtRet,0),
             Vlr_FcpSbtRet = Round(IsNull(it.Vlr_FcpSbtRet,0),2),

             vBCSTRet = IsNull(it.Xml_vBCSTRet,0),
             pST = IsNull(it.Xml_pST,0),
             vICMSSubstituto = IsNull(it.Xml_vICMSSubstituto,0),
             vICMSSTRet = IsNull(it.Xml_vICMSSTRet,0),
             vBCFCPSTRet = IsNull(it.Xml_vBCFCPSTRet,0),
             pFCPSTRet = IsNull(it.Xml_pFCPSTRet,0),
             vFCPSTRet = IsNull(it.Xml_vFCPSTRet,0),

             pRedBCEfet = Case When @WValCabTipConsumidor = 'F' then IsNull(it.Xml_pRedBCEfet,0) Else 0 End,
             vBCEfet    = Case When @WValCabTipConsumidor = 'F' then IsNull(it.Xml_vBCEfet,0)    Else 0 End,
             pICMSEfet  = Case When @WValCabTipConsumidor = 'F' then IsNull(it.Xml_pICMSEfet,0)  Else 0 End,
             vICMSEfet  = Case When @WValCabTipConsumidor = 'F' then IsNull(it.Xml_vICMSEfet,0)  Else 0 End,

             cBenef = IsNull(it.cBenef,'')

      From NFEIT it
           Inner Join NFECB cb on cb.Protocolo = it.Protocolo
           Inner Join PRODU pr on pr.Codigo = it.Cod_Produto
           Inner Join FABRI fb on fb.Codigo = pr.Cod_Fabricante
           left outer Join (Select Cod_Estabe, Cod_Produt, Cod_Lote,
                            Dat_Vencim = MIN(Dat_Vencim), Dat_Fabric = MIN(Dat_Fabric) 
                            From PRLOT 
                            Where Cod_Estabe = @PCodEstabe
                            Group by Cod_Estabe, Cod_Produt, Cod_Lote) lt on ((it.Cod_Estabe = lt.Cod_Estabe) and (it.Cod_Produto = lt.Cod_Produt) and (it.Cod_Lote = lt.Cod_Lote))
           
      Where it.Cod_Estabe = @PCodEstabe
      And it.Protocolo = @PNumNota
      Order by it.Cod_Produto
  end  
  
--normaliza lote ------------------------------------------------------------------------------------------------
DECLARE ITENS_Cr Cursor Local Fast_Forward For
  Select Chave, Cod_Lote, Dat_Vencim, Dat_Fabric, Qtd_MesValid
  From #TMP_Itens
  Where ((Dat_Vencim < 10) or (Dat_Fabric < 10))
        
OPEN ITENS_Cr
FETCH NEXT FROM ITENS_Cr INTO @Chave, @CodLot, @DatVct, @DatFab, @QtdMesVld 
WHILE @@FETCH_STATUS = 0
BEGIN
  if @DatVct < 10
    begin
      Set @CodLot = ''
      Set @DatVct = null
      Set @DatFab = null 
    end      
  else  
  if @DatFab < 10
    begin
      if @QtdMesVld <= 0
        Set @QtdMesVld = 24
      if @QtdMesVld > 1000
        Set @QtdMesVld = 60   
      Set @DatFab = DATEADD(mm,-@QtdMesVld,@DatVct)
          if @DatFab > @WDatEmiCab
        Set @DatFab = @WDatEmiCab
    end  

  Update #TMP_Itens
    Set Cod_Lote = @CodLot,
        Dat_Vencim = @DatVct,
        Dat_Fabric = @DatFab  
  Where Chave = @Chave

  FETCH NEXT FROM ITENS_Cr INTO @Chave, @CodLot, @DatVct, @DatFab, @QtdMesVld
END

CLOSE ITENS_Cr
DEALLOCATE ITENS_Cr  

-- Normaliza desconto Comercial ----------------------------------------------------------------------------------------------
Set @WValDif = Round(@WValCabDscCom - (Select SUM(Vlr_DscRat) From #TMP_Itens),2) 
if @WValDif < 0
  Set @ParDif = -0.01  
else  
  Set @ParDif = 0.01  
  
while (@WValDif <> 0) and (Abs(@WValDif) < @WValCabDscCom)
  begin
    if @ParDif > 0
      DECLARE ITENS_Cr Cursor Local Fast_Forward For
        Select Chave
        From #TMP_Itens
        Where Vlr_DscRat > 0
        Order by Vlr_TotIte desc, Chave
    else
      DECLARE ITENS_Cr Cursor Local Fast_Forward For
        Select Chave
        From #TMP_Itens
        Where Vlr_DscRat > 0
        Order by Vlr_TotIte desc, Chave 
        
    OPEN ITENS_Cr
    FETCH NEXT FROM ITENS_Cr INTO @Chave 
    WHILE @@FETCH_STATUS = 0
    BEGIN
      if @WValDif <> 0
         begin
           Update #TMP_Itens
             Set Vlr_DscRat = Vlr_DscRat + @ParDif   
           Where Chave = @Chave
           And Vlr_DscRat > 0
                      
           Set @WValDif = @WValDif - @ParDif
         end
       else
         Break  
      FETCH NEXT FROM ITENS_Cr INTO @Chave
    END

    CLOSE ITENS_Cr
    DEALLOCATE ITENS_Cr     
          
  end  -- while @WValDif <> 0
------------------------------------------------------------------------------------------------------------------------

-- Normaliza desconto Bonificacao ----------------------------------------------------------------------------------------------
Set @WValDif = Round(@WValCabDscBon - (Select SUM(Vlr_DscBonRat) From #TMP_Itens),2) 
if @WValDif < 0
  Set @ParDif = -0.01  
else  
  Set @ParDif = 0.01  
  
