           Where Chave = @Chave
           And Vlr_FcpIcm > 0
                      
           Set @WValDif = @WValDif - @ParDif
         end
       else
         Break  
      FETCH NEXT FROM ITENS_Cr INTO @Chave
    END

    CLOSE ITENS_Cr
    DEALLOCATE ITENS_Cr     
          
  end  -- while @WValDif <> 0

-- normaliza FcpSbt ----------------------------------------------------------------------------------------
Set @WValDif = Round(@WValCabFcpSbt - (Select SUM(Vlr_FcpSbt) From #TMP_Itens),2) 
if @WValDif < 0
  Set @ParDif = -0.01  
else  
  Set @ParDif = 0.01  
  
while (@WValDif <> 0) and (Abs(@WValDif) < @WValCabFcpSbt)
  begin
    if @ParDif > 0
      DECLARE ITENS_Cr Cursor Local Fast_Forward For
        Select Chave
        From #TMP_Itens
        Where Vlr_FcpSbt > 0
        Order by Vlr_TotIte desc, Chave 
    else
      DECLARE ITENS_Cr Cursor Local Fast_Forward For
        Select Chave
        From #TMP_Itens
        Where Vlr_FcpSbt > 0
        Order by Vlr_TotIte desc, Chave 
        
    OPEN ITENS_Cr
    FETCH NEXT FROM ITENS_Cr INTO @Chave 
    WHILE @@FETCH_STATUS = 0
    BEGIN
      if @WValDif <> 0
         begin
           Update #TMP_Itens
             Set Vlr_FcpSbt = Vlr_FcpSbt + @ParDif   
           Where Chave = @Chave
           And Vlr_FcpSbt > 0
                      
           Set @WValDif = @WValDif - @ParDif
         end
       else
         Break  
      FETCH NEXT FROM ITENS_Cr INTO @Chave
    END

    CLOSE ITENS_Cr
    DEALLOCATE ITENS_Cr     
          
  end  -- while @WValDif <> 0

