----------------------------------------------------------------------------------------------------------

------- Normaliza FCP: B.Calculo x Aliquota = Vlr_IcmFcp  -----------------------------------------------------------
--  está alterando NFSCB.Vlr_IcmFcpDes ????
if Round(@WValCabIcmFcpDes,2) = Round((Select SUM(Vlr_IcmFcpDes) From #TMP_Itens),2) 
  begin
    Set @WValDif = Round(@WValCabIcmFcpDes - (Select sum(Round(Vlr_BasIcmDes*Per_AcrAlqIntFcp/100,2)) From #TMP_Itens),2) 
    if ABS(@WValDif) > 0 
      begin
        Update #TMP_Itens
          Set Vlr_IcmFcpDes = Round(Vlr_BasIcmDes*Per_AcrAlqIntFcp/100,2)
          Where Round(Vlr_BasIcmDes*Per_AcrAlqIntFcp/100,2) <> Vlr_IcmFcpDes
          
        -- atualiza valor na tabela de origem (alterando valor original ????)
        Set @WValCabIcmFcpDes = Round((Select sum(Vlr_IcmFcpDes) From #TMP_Itens),2)
        if @PTipNota = 'S'
          begin
            Update NFSCB
              Set Vlr_IcmFcpDes = @WValCabIcmFcpDes
            Where Cod_Estabe = @PCodEstabe 
            and Ser_Nota = @PSerNota 
            and Num_Nota = @PNumNota
          end
        else
          begin
            Update NFECB
              Set Vlr_IcmFcpDes = @WValCabIcmFcpDes
            From NFECB 
            Where Cod_Estabe = @PCodEstabe 
            and Protocolo = @PNumNota
          end
      end
  end  

---------------------------------------------------------------------------------------------------------------

-- normaliza EAN (a partir da versão 4.0)
Update #TMP_Itens
  Set Cod_EAN = 'SEM GTIN'
Where IsNull(Cod_EAN,'') = ''
And Cast(Substring(@pm_VerNfe,1,CharIndex('.',@pm_VerNfe)-1) as int) > 3

------------------------------------------------------------------------------------------------------------------
-- recalcula campos
Update #TMP_Itens
  Set Vlr_DscTotIte = Vlr_TotBruIte - Vlr_TotIte + Vlr_DscRat + Vlr_DscBonRat + Vlr_DscTri, -- desc. sem repasse
      Vlr_TotDsp = Vlr_DspRat + Vlr_DspExt + Vlr_SbtRes,
      Vlr_BasIcmSbtRet = Vlr_BasSbtRes + Vlr_BasSbtEmb,
      Vlr_IcmSbtRet = Vlr_SbtRes + Vlr_SbtEmb
      
-- monta observacao 
DECLARE ITENS_Cr Cursor Local Fast_Forward For
  Select Chave, Cod_Produto, Num_SeqIte, Cod_Lote, Cod_LoteOri, Tip_LisPis, Vlr_TotBruIte, Vlr_DscTotIte,
         Flg_DscItePdv, Prc_UniPdv, Per_DscPdv, Prc_Fabric,
         Vlr_BasSbtRes, Vlr_SbtRes, Vlr_BasSbtEmb, Vlr_SbtEmb, Tip_Consumidor,
         Vlr_DscTri, Per_DscTri, Des_Produto, Des_Fabric, Tip_Por344, Tip_Sai, 
         Str_VolEmb, Obs_IteNf, Vlr_BasRepIcm, Per_RepIcm, Vlr_RepIcm,
         Per_Desconto = Case When (Vlr_DscRat + Vlr_DscBonRat) > 0 then 0 Else Per_Desconto End,
         Vlr_TotIte
  From #TMP_Itens
  Order by Chave 
OPEN ITENS_Cr
FETCH NEXT FROM ITENS_Cr INTO @Chave, @CodPrd, @SeqIte, @CodLot, @WCodLotOri, @WTipLisPis, @WVlrTotBruIte, @WVlrDscTotIte,
                              @WFlgDscItePdv, @WPrcUniPdv, @WPerDscPdv, @WPrcFabric,
                              @WVlrBasSbtRes, @WVlrSbtRes, @WVlrBasSbtEmb, @WVlrSbtEmb, @WTipCon,
                              @WVlrDscTri, @WPerDscTri, @WDesProduto, @WDesFabric, @WTipPor344, @WTipSai, 
                              @WStrVolEmb, @WObsIteNf, @WVlrBasRepIcm, @WPerRepIcm, @WVlrRepIcm, @WPerDscIte, @WVlrTotLiqIte
WHILE @@FETCH_STATUS = 0
  BEGIN
    -- monta observacao cancatenada infAdProd
    Set @WDesCplProduto = ''

    Delete From @Tab

    if @PTipNota = 'S'
      Insert Into @Tab (Obs_Fiscal)
        Select Des_Observ From NSIOB
         Where Cod_Estabe = @PCodEstabe 
           and Ser_Nota = @PSerNota 
           and Num_Nota = @PNumNota
           and Cod_Produto = @CodPrd
           and Cod_Lote = @CodLot
           and Num_SeqIte = @SeqIte
    else
      Insert Into @Tab (Obs_Fiscal)
        Select Des_Observ From NEIOB
         Where Cod_Estabe = @PCodEstabe 
           and Protocolo = @PNumNota
           and Cod_Produto = @CodPrd
           and Cod_Lote = @CodLot
           and Num_SeqIte = @SeqIte

    While Exists(Select 1 From @Tab)
      begin
        Select top 1
               @ChaveTab = ChaveTab
             , @WObsFis = Obs_Fiscal
          From @Tab
         Order by ChaveTab

        if PatIndex(@WObsFis+'%', @WDesCplProduto) = 0
          begin
            if (Len(@WDesCplProduto) > 0) and
               (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
              Set @WDesCplProduto = @WDesCplProduto + ';  '
            Set @WDesCplProduto = @WDesCplProduto + @WObsFis
          end

        Delete From @Tab Where ChaveTab = @ChaveTab
      end


    if (@pm_CodImpDscFab = '1') and (@WDesFabric <> '')
      Set @WDesProduto = @WDesProduto+' ('+Substring(@WDesFabric,1,5)+')'
    if @WTipPor344 <> ''
      Set @WDesProduto = @WDesProduto+' ('+@WTipPor344+')'  
    if @WTipSai = 'B'                     
      Set @WDesProduto = @WDesProduto+' **Bonific.**'

    if (@CodLot = '') and (@WCodLotOri <> '')
      begin
        if (Len(@WDesCplProduto) > 0) and
           (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
          Set @WDesCplProduto = @WDesCplProduto + ';  '
        Set @WDesCplProduto = @WDesCplProduto + 'Lote: '+@WCodLotOri
      end
    
    if (@pm_CodImpPrcFab = '1') and (@WPrcFabric > 0)
      begin
        if (Len(@WDesCplProduto) > 0) and
           (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
          Set @WDesCplProduto = @WDesCplProduto + ';  '
        Set @WDesCplProduto = @WDesCplProduto + 'PF: '+CAST(cast(@WPrcFabric as numeric(12,2)) as varchar)
      end


    Set @WTipLisPis = Case              
                        When @WTipLisPis = 'P' then '(+)'
                        When @WTipLisPis = 'N' then '(-)'
                        When @WTipLisPis = 'X' then '(n)'
                        When @WTipLisPis = 'O' then '(o)'
                      End
    if (Len(@WDesCplProduto) > 0) and
       (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
      Set @WDesCplProduto = @WDesCplProduto + ';  '
    Set @WDesCplProduto = @WDesCplProduto+'Lista '+@WTipLisPis

    -- desconto repasse
    if @WPerRepIcm > 0
      begin
        if (Len(@WDesCplProduto) > 0) and
           (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
          Set @WDesCplProduto = @WDesCplProduto + ';  '
        Set @WDesCplProduto = @WDesCplProduto + 'Repasse '+CAST(cast(@WPerRepIcm as numeric(8,2)) as varchar)+'%'
      end

    -- desconto total (-repasse)
    Set @WPerDsc = 0
    if (@WVlrDscTotIte > 0) and (@WVlrTotBruIte > 0) 
      begin
        if @WPerDscIte > 0 
          Set @WPerDsc = @WPerDscIte
        else
          Set @WPerDsc = Round(@WVlrDscTotIte*100/@WVlrTotBruIte,2)
        if @WPerDsc > 0
          Set @WDesCplProduto = @WDesCplProduto + 'Desc.'+CAST(cast(@WPerDsc as numeric(8,2)) as varchar)+'%  '
      end

    if (@pm_FlgImpDscEmbNot = 1) and (@WFlgDscItePdv = 1) and (@WPerDscPdv > 0) 
      begin
        if (Len(@WDesCplProduto) > 0) and
           (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
          Set @WDesCplProduto = @WDesCplProduto + ';  '
        Set @WDesCplProduto = @WDesCplProduto + 'Desc.Emb.'+CAST(cast(@WPerDscPdv as numeric(8,2)) as varchar)+'%'
      end
    
    if ((@WVlrBasSbtRes+@WVlrBasSbtEmb) > 0) and
       ((@WVlrSbtRes+@WVlrSbtEmb) > 0)
      begin
        if (Len(@WDesCplProduto) > 0) and
           (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
          Set @WDesCplProduto = @WDesCplProduto + ';  '
        Set @WDesCplProduto = @WDesCplProduto + 'BCRE: '+CAST(cast((@WVlrBasSbtRes+@WVlrBasSbtEmb) as numeric(12,2)) as varchar)
        Set @WDesCplProduto = @WDesCplProduto + '  VRE: '+CAST(cast((@WVlrSbtRes+@WVlrSbtEmb) as numeric(12,2)) as varchar)
      end   
  
/*    
    if @WVlrDscTri > 0
      if Charindex(@WTipCon,';P;E;M;') > 0  -- consumidor final
        Set @WDesCplProduto = @WDesCplProduto + 'ICMS abatido no valor de '+CAST(cast(@WVlrDscTri as numeric(12,2)) as varchar)+'  '
          else
      if @WPerDscTri > 0
        Set @WDesCplProduto = @WDesCplProduto + 'Desc.Repasse '+ CAST(cast(@WVlrDscTri as numeric(12,2)) as varchar) +'/'+CAST(@WPerDscTri as varchar)+'%  '
*/

    if @WStrVolEmb <> ''
      begin
        if (Len(@WDesCplProduto) > 0) and
           (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
          Set @WDesCplProduto = @WDesCplProduto + ';  '
        Set @WDesCplProduto = @WDesCplProduto + @WStrVolEmb
      end

    if @WObsIteNf <> ''
      begin
        if (Len(@WDesCplProduto) > 0) and
           (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
          Set @WDesCplProduto = @WDesCplProduto + ';  '
        Set @WDesCplProduto = @WDesCplProduto + @WObsIteNf
      end
---------------------------------------------------------------------------------------------------

    Update #TMP_Itens
      Set Des_Produto = @WDesProduto,
          Obs_Produto = Substring(@WDesCplProduto,1,500)
    Where Chave = @Chave

  FETCH NEXT FROM ITENS_Cr INTO @Chave, @CodPrd, @SeqIte, @CodLot, @WCodLotOri, @WTipLisPis, @WVlrTotBruIte, @WVlrDscTotIte,
                                @WFlgDscItePdv, @WPrcUniPdv, @WPerDscPdv, @WPrcFabric,
                                @WVlrBasSbtRes, @WVlrSbtRes, @WVlrBasSbtEmb, @WVlrSbtEmb, @WTipCon,
                                @WVlrDscTri, @WPerDscTri, @WDesProduto, @WDesFabric, @WTipPor344, @WTipSai, 
                                @WStrVolEmb, @WObsIteNf, @WVlrBasRepIcm, @WPerRepIcm, @WVlrRepIcm, @WPerDscIte, @WVlrTotLiqIte
END

CLOSE ITENS_Cr
DEALLOCATE ITENS_Cr     
      
----------------------------------------------------------------------------------------------------------

Set @WSelect = 'Select cProd = Cod_Produto, 
       cEAN = Cod_EAN, 
       NCM = Cod_NCM, 
       nItem = Num_SeqIte,
       nItemPed = Num_SeqPdc,
       Cod_GrpPrc = Cod_GrpPrc,
       CFOP = Cod_Cfo, 
       Tip_Por344,
       xProd = Des_Produto,
       cProdANVISA = Reg_MS, 
       xMotivoIsencao = Des_MtvIseRegMS,

       infAdProd = Obs_Produto,
       uCom = Und_Com,
       qCom = Qtd_Com,
       vUnCom = Prc_UniCom,
       vProd = Vlr_TotBruIte,
       vDesc = Vlr_DscTotIte + Vlr_RepIcm,
       Vlr_LiqMer = Vlr_TotIte,
       Vlr_BasSbtRes, Vlr_SbtRes, 
       nLote = Cod_Lote, 
       dVal = Dat_Vencim,
       dFab = Dat_Fabric,
       vFrete = Vlr_Frete,
       vSeg = Vlr_Seguro,
       vOutro = Vlr_TotDsp,
       uTrib = Und_Tri,
       qTrib = Qtd_Tri,
       vUnTrib = Prc_UniTri,

       orig = Cod_OriPrd,
       CST_Icm = Cod_CstIcm,
       CSOSN_Icm = Cod_CsosnIcm,
       modBC = Cod_ModBasCalIcm,
       pRedBC = Per_RedBasCalIcm, 
       vBC = Vlr_BasIcm, 
       pICMS = Alq_Icm - Alq_FcpIcm, 
           
       vICMSOp = Vlr_IcmPro,
       pDif = Per_IcmDiferi,
       vIcmsDif = Case 
                    When Vlr_IcmDiferi > 0 then 
                      Case 
                        When Vlr_IcmDiferi = (Vlr_IcmPro - (Vlr_Icm - Vlr_FcpIcm)) then Vlr_IcmDiferi 
                        Else (Vlr_IcmPro - (Vlr_Icm - Vlr_FcpIcm)) 
                      End
                    Else 0
                  End,
       vICMS = Vlr_Icm - Vlr_FcpIcm, 
       vICMSDeson = Vlr_IcmDesone, 
       motDesICMS = Cod_MtvIcmDesone,

       modBCST = Cod_ModBasCalIcmSbt,
       pMVAST = Alq_AgrSbt, 
       pRedBCST = Per_RedBasCalIcmSbt,
       vBCST = Vlr_BasIcmSbt, 
       pICMSST = Alq_IcmSbt - Alq_FcpSbt, 
       vICMSST = Vlr_IcmSbt - Vlr_FcpSbt,
       
       CST_Ipi, cEnq = Cod_EnqIpi,
       vBCIPI = Vlr_BasIpi+Vlr_BasDevIpi, 
       pIPI = Alq_Ipi, vIPI = Vlr_Ipi,
       pDevol = Per_DevIpi, vIPIDevol = Vlr_DevIpi,

       CST_Pis, Vlr_BasPis, Alq_Pis, Vlr_Pis,
       CST_Cofins, Vlr_BasCofins, Alq_Cofins, Vlr_Cofins, 
       vPMC = Prc_MaxCon, 
       Prc_Fabric,
  
       CEST = Cod_CEST,

       vBCUFDest = Vlr_BasIcmDes,
       vBCFCPUFDest = Vlr_BasIcmDes,
       pFCPUFDest = Per_AcrAlqIntFcp, 
       pICMSUFDest = Alq_IntDes,    
       pICMSInter = Alq_Interesta,
       pICMSInterPart = Per_PrvParIcm,

       vFCPUFDest = Vlr_IcmFcpDes,
       vICMSUFDest = Vlr_IcmParDes,    
       vICMSUFRemet = Vlr_IcmParRem,

       vBCFCP = Vlr_BasIcm,
       pFCP = Alq_FcpIcm,         
       vFCP = Vlr_FcpIcm,         

       vBCFCPST = Vlr_BasIcmSbt,
       pFCPST = Alq_FcpSbt,       
       vFCPST = Vlr_FcpSbt,       

       vBCSTRet, 
       pST,
       vICMSSubstituto,
       vICMSSTRet,

       vBCFCPSTRet,
       pFCPSTRet, 
       vFCPSTRet, 

       pRedBCEfet,
       vBCEfet,
       pICMSEfet,
       vICMSEfet,
           
       cBenef, 
       xPed = Cod_PedCmpCli   
       
From #TMP_Itens '

if @pm_CtrImpIteNotFis = 'A'
  Set @WSelect = @WSelect +'Order by xProd'
else  
  Set @WSelect = @WSelect +'Order by cProd'

Exec (@WSelect)

DROP TABLE #TMP_Itens

RETURN;

