CREATE PROCEDURE [dbo].[PR_IncluiTBPDE]
(
@PSta varchar(1),
@PCodEstabe int, 
@PCodLayout int,
@PCodGrpLay int, 
@PNomArquiv varchar(80),
@PDatArquiv datetime,
@PIsnArquiv bigint output
)

AS

BEGIN

  Set @PIsnArquiv = 0

  BEGIN TRANSACTION

  if rtrim(ltrim(@PSta)) = '' 
    Set @PSta = 'X'


  if Exists(Select 1 From ESTAB
             Where Cod_Estabe = @PCodEstabe) and
     (not Exists(Select 1 
                   From TBPDE
                  Where Cod_Estabe = @PCodEstabe 
                    And Cod_Layout = @PCodLayout 
                    And Cod_Grupo  = @PCodGrpLay 
                    And Nom_Arquiv = @PNomArquiv 
                    And Dat_Arquiv = @PDatArquiv))
    begin
      Insert Into TBPDE (
        Cod_Estabe, Cod_Layout, Cod_Grupo, Nom_Arquiv, Dat_Arquiv, Sta_Arquiv, Dat_IniPro) 
      Values (
        @PCodEstabe, @PCodLayout, @PCodGrpLay, @PNomArquiv, @PDatArquiv, @PSta, GetDate())
      if @@error <> 0
        begin
          if @@trancount > 0
	        Rollback Transaction
          Return
        end
      end

  Set @PIsnArquiv = IsNull((Select Isn_Arquiv 
                              From TBPDE 
                             Where Cod_Estabe = @PCodEstabe
                               And Cod_Layout = @PCodLayOut
                               And Cod_Grupo  = @PCodGrpLay
                               And Nom_Arquiv = @PNomArquiv
                               And Dat_Arquiv = @PDatArquiv),0)

  if @@trancount > 0
    COMMIT TRANSACTION
END
GO

SET ANSI_NULLS ON
