As
Begin
    Declare @FlgPolOk bit;

    Select @FlgPolOk = FlgPolOk 
      From dbo.FN_ViewPoliticaAtiva (@PIdPolCom, @PDatRef);

	-- Retorna o resultado da function
	Return IsNull(@FlgPolOk,0);
End
