-- atualiza Prc_MaxCon nos estabelecimentos
if Update(Prc_MaxCon12)
  Update pr
     Set pr.Prc_MaxCon = case
                           when (Round(IsNull(es.Per_AlqIcm,0),2) = 12.00) or ((Charindex(es.Des_Estado,';MG;SP;') > 0) and (IsNull(p.Flg_Generico,0) = 1)) then p.Prc_MaxCon12
