if Update(Prc_MaxCon19)
  Update pr
     Set pr.Prc_MaxCon = case 
                           when Round(IsNull(es.Per_AlqIcm,0),2) = 19.00 then p.Prc_MaxCon19
                           else pr.Prc_MaxCon
