         inner join ESTAB es on pr.Cod_Estabe = es.Cod_Estabe
   Where pr.Prc_MaxCon <> case 
                            when Round(IsNull(es.Per_AlqIcm,0),2) = 19.00 then p.Prc_MaxCon19
                            else pr.Prc_MaxCon
                          end
if Update(Prc_MaxCon20)
  Update pr
     Set pr.Prc_MaxCon = case 
                           when Round(IsNull(es.Per_AlqIcm,0),2) = 20.00 then p.Prc_MaxCon20
                           else pr.Prc_MaxCon
