  end
*/

  
  -- corrige saldo negativo em PRLOT
  if Exists(Select 1 
              From PRLOT 
             Where Cod_Estabe = @PCodEstabe
               And ( (Qtd_Saldo < 0) or (Qtd_Fisico < 0) or 
                     (Qtd_SldPra < 0) or (Qtd_FisPra < 0) or 
                     (Qtd_SldDep < 0) or (Qtd_FisDep < 0) ))
    begin
      Update PRLOT
         Set Qtd_FisPra = Qtd_FisPra + Abs(Qtd_SldPra)
       Where Cod_Estabe = @PCodEstabe
         And Qtd_SldPra < 0
  
      Update PRLOT
         Set Qtd_FisDep = Qtd_FisDep + Abs(Qtd_SldDep)
       Where Cod_Estabe = @PCodEstabe
         And Qtd_SldDep < 0
    end

  -- corrige saldo negativo em PRLTL
  if Exists(Select Cod_Produt, Cod_Lote, Qtd_Fisico, Qtd_Solicitado, Qtd_Saldo 
              From PRLTL 
             Where Cod_Estabe = @PCodEstabe
               And ( (Qtd_Saldo < 0) or (Qtd_Fisico < 0) or 
                     (Qtd_SldPra < 0) or (Qtd_FisPra < 0) or 
                     (Qtd_SldDep < 0) or (Qtd_FisDep < 0) ))
    begin
      Update PRLTL
         Set Qtd_FisPra = Qtd_FisPra + Abs(Qtd_SldPra)
       Where Cod_Estabe = @PCodEstabe
         And Qtd_SldPra < 0
  
      Update PRLTL
         Set Qtd_FisDep = Qtd_FisDep + Abs(Qtd_SldDep)
       Where Cod_Estabe = @PCodEstabe
         And Qtd_SldDep < 0
    end


/*
-- verifica qtd.disponivel de PRXES com LOTES
-- Lotes > PRXES  e PRLOT atende diferenca (1)
if Exists(Select p.Cod_Produt
            From PRXES p Left Join
                 (Select Cod_Estabe, Cod_Produt, sum(Qtd_Saldo) as QtdSldFra, sum(Qtd_Solicitado) as QtdSolFra
                    From PRLOT 
                   Where Cod_Estabe = @PCodEstabe
                     And ((Qtd_Saldo > 0) or (Qtd_Solicitado > 0))
                   Group by Cod_Estabe, Cod_Produt) l on (p.Cod_Estabe = l.Cod_Estabe and p.Cod_Produt = l.Cod_Produt) Left Join
                 (Select Cod_Estabe, Cod_Produt, sum(Qtd_Saldo) as QtdSldDep, sum(Qtd_Solicitado) as QtdSolDep
                    From PRLTL
                   Where Cod_Estabe = @PCodEstabe
                     And ((Qtd_Saldo > 0) or (Qtd_Solicitado > 0))
                   Group by Cod_Estabe, Cod_Produt) d on (p.Cod_Estabe = d.Cod_Estabe and p.Cod_Produt = d.Cod_Produt)
           Where p.Cod_Estabe = @PCodEstabe 
             And (p.Qtd_Dispon+p.Qtd_Solici+p.Qtd_Reserv+p.Qtd_Avaria-IsNull(QtdSolFra,0)-IsNull(QtdSolDep,0)) < IsNull(l.QtdSldFra,0)+IsNull(d.QtdSldDep,0)
             And IsNull(l.QtdSldFra,0) >= IsNull(l.QtdSldFra,0)+IsNull(d.QtdSldDep,0)-(p.Qtd_Dispon+p.Qtd_Solici+p.Qtd_Reserv+p.Qtd_Avaria-IsNull(QtdSolFra,0)-IsNull(QtdSolDep,0))
             And p.Qtd_Fisico >= 0
             And p.Qtd_Dispon >= 0)
  begin
--    PRINT '===> Ajustando DIVERGENCIAS DE ESTOQUES: PRODU x PRLOT (1)- PRLOT > PRODU'
    Declare PRODU_Cr Cursor Local For 
      Select p.Cod_Produt,
             IsNull(l.QtdSldFra,0)+IsNull(d.QtdSldDep,0)-(p.Qtd_Dispon+p.Qtd_Solici+p.Qtd_Reserv+p.Qtd_Avaria-IsNull(QtdSolFra,0)-IsNull(QtdSolDep,0)) as Qtd_Dif                                                        
        From PRXES p Left Join
             (Select Cod_Estabe, Cod_Produt, sum(Qtd_Saldo) as QtdSldFra, sum(Qtd_Solicitado) as QtdSolFra
                From PRLOT 
               Where Cod_Estabe = @PCodEstabe
                 And ((Qtd_Saldo > 0) or (Qtd_Solicitado > 0))
               Group by Cod_Estabe, Cod_Produt) l on (p.Cod_Estabe = l.Cod_Estabe and p.Cod_Produt = l.Cod_Produt) Left Join
             (Select Cod_Estabe, Cod_Produt, sum(Qtd_Saldo) as QtdSldDep, sum(Qtd_Solicitado) as QtdSolDep
                From PRLTL
               Where Cod_Estabe = @PCodEstabe
                 And ((Qtd_Saldo > 0) or (Qtd_Solicitado > 0))
               Group by Cod_Estabe, Cod_Produt) d on (p.Cod_Estabe = d.Cod_Estabe and p.Cod_Produt = d.Cod_Produt)
       Where p.Cod_Estabe = @PCodEstabe 
         And (p.Qtd_Dispon+p.Qtd_Solici+p.Qtd_Reserv+p.Qtd_Avaria-IsNull(QtdSolFra,0)-IsNull(QtdSolDep,0)) < IsNull(l.QtdSldFra,0)+IsNull(d.QtdSldDep,0)
         And IsNull(l.QtdSldFra,0) >= IsNull(l.QtdSldFra,0)+IsNull(d.QtdSldDep,0)-(p.Qtd_Dispon+p.Qtd_Solici+p.Qtd_Reserv+p.Qtd_Avaria-IsNull(QtdSolFra,0)-IsNull(QtdSolDep,0))
         And p.Qtd_Fisico >= 0
         And p.Qtd_Dispon >= 0
       Order by p.Cod_Produt
    Open PRODU_Cr
    Fetch Next From PRODU_Cr Into @CodPrd, @QtdDif
    While @@FETCH_STATUS = 0
      begin
        -- tenta decrementar do estoque 2
        Declare PRLOT_Cr Cursor Local For 
          Select Cod_Dep, Cod_Lote, Qtd_SldDep
            From PRLOT
           Where Cod_Estabe = @PCodEstabe
             And Cod_Produt = @CodPrd
             and Qtd_SldDep > 0
           Order by Cod_Dep, Dat_Vencim
        Open PRLOT_Cr
        Fetch Next From PRLOT_Cr Into @CodDep, @CodLot, @QtdSldDep  
        While (@QtdDif > 0) and (@@FETCH_STATUS = 0)
          begin
            if @QtdSldDep >= @QtdDif
              Set @QtdMov = @QtdDif
            else
              Set @QtdMov = @QtdSldDep
            Update PRLOT
               Set Qtd_FisDep = Qtd_FisDep - @QtdMov
             Where Cod_Estabe = @PCodEstabe 
               And Cod_Dep = @CodDep
               And Cod_Produt = @CodPrd 
               and Cod_Lote = @CodLot
            Set @QtdDif = @QtdDif - @QtdMov
            Fetch Next From PRLOT_Cr Into @CodDep, @CodLot, @QtdSldDep
          end
        Close PRLOT_Cr
        Deallocate PRLOT_Cr

        -- se ainda houver diferenca, tenta decrementar do estoque 1
        if @QtdDif > 0 
          begin
            Declare PRLOT_Cr Cursor Local For 
              Select Cod_Dep, Cod_Lote, Qtd_SldPra
                From PRLOT
               Where Cod_Estabe = @PCodEstabe
                 And Cod_Produt = @CodPrd
                 and Qtd_SldPra > 0
               Order by Cod_Dep, Dat_Vencim
            Open PRLOT_Cr
            Fetch Next From PRLOT_Cr Into @CodDep, @CodLot, @QtdSldPra
            While (@QtdDif > 0) and (@@FETCH_STATUS = 0)
              begin
                if @QtdSldPra >= @QtdDif
                  Set @QtdMov = @QtdDif
                else
                  Set @QtdMov = @QtdSldPra
                Update PRLOT
                   Set Qtd_FisPra = Qtd_FisPra - @QtdMov
                 Where Cod_Estabe = @PCodEstabe 
                   And Cod_Dep = @CodDep
                   And Cod_Produt = @CodPrd 
                   and Cod_Lote = @CodLot
                Set @QtdDif = @QtdDif - @QtdMov
                Fetch Next From PRLOT_Cr Into @CodDep, @CodLot, @QtdSldPra
              end
            Close PRLOT_Cr
            Deallocate PRLOT_Cr
          end

        Fetch Next From PRODU_Cr Into @CodPrd, @QtdDif
      end
    Close PRODU_Cr
    Deallocate PRODU_Cr
  end
*/


  Exec PR_CorrigeEstoqueProdut @PCodEstabe, 0

COMMIT TRANSACTION
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[FN_QtdLoteDisponivel]
(
  @PCodEstabe int,
  @PCodCliPag int,
  @PCodPrd int,
  @PDatBas smalldatetime,
  @PQtdMesMinPrzVctLot int,
  @PIdPolCom int
)
RETURNS int

AS

BEGIN

Declare @QtdLotDis int,
        @QtdPck int,
		@QtdDep int

if IsNull(@PDatBas,0) = 0
  Set @PDatBas = cast(GetDate() as date)

Set @QtdLotDis = 0

-- total disponivel no picking
Set @QtdPck = IsNull((Select sum(IsNull(lt.Qtd_Saldo,0))
                        From PRLOT lt Inner Join 
                             PRODU pr on (lt.Cod_Produt = pr.Codigo) Left Join
                             (Select pl.Cod_Produt, pl.Cod_Lote
                                From PCXPL pl Inner Join 
                                     POCOM pc on (pl.Id_PolCom = pc.Id_Polcom)
                               Where pc.Id_PolCom = @PIdPolCom
                                 And ( (pc.Dat_Inicio Is Null  or (@PDatBas >= pc.Dat_Inicio))  and
                                       (pc.Dat_Termino Is Null or (@PDatBas <= pc.Dat_Termino)) and
                                       (pc.Bloqueado Is Null or pc.Bloqueado = 0) ) 
                             ) x on (lt.Cod_Produt = x.Cod_Produt and lt.Cod_Lote = x.Cod_Lote) Left Join
                             CLPRV vp on (vp.Cod_CliPag = @PCodCliPag and vp.Cod_Produt = pr.Codigo) Left Join
                             CLFBV vf on (vf.Cod_CliPag = @PCodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante)
                       Where lt.Cod_Estabe = @PCodEstabe
                         And lt.Cod_Produt = @PCodPrd
                         And lt.Qtd_Saldo > 0
                         And ( (IsNull(x.Cod_Produt,0) > 0) or
                               ( (x.Cod_Produt is null) and 
                                 ( (lt.Dat_Vencim is null) or 
                                   (lt.Dat_Vencim >= Case
                                                       When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                       When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                       Else dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(@PQtdMesMinPrzVctLot,0))
                                                     End) ) ) ) ) ,0)
            
Set @QtdDep = IsNull((Select sum(IsNull(lt.Qtd_Saldo,0))
                        From PRLTL lt Inner Join 
                             PRODU pr on (lt.Cod_Produt = pr.Codigo) Left Join
                             (Select pl.Cod_Produt, pl.Cod_Lote
                                From PCXPL pl Inner Join 
                                     POCOM pc on (pl.Id_PolCom = pc.Id_Polcom)
                               Where pc.Id_PolCom = @PIdPolCom
                                 And ( (pc.Dat_Inicio Is Null  or (@PDatBas >= pc.Dat_Inicio))  and
                                       (pc.Dat_Termino Is Null or (@PDatBas <= pc.Dat_Termino)) and
                                       (pc.Bloqueado Is Null or pc.Bloqueado = 0) ) 
                             ) x on (lt.Cod_Produt = x.Cod_Produt and lt.Cod_Lote = x.Cod_Lote) Left Join
                             CLPRV vp on (vp.Cod_CliPag = @PCodCliPag and vp.Cod_Produt = pr.Codigo) Left Join
                             CLFBV vf on (vf.Cod_CliPag = @PCodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante)
                       Where lt.Cod_Estabe = @PCodEstabe 
                         And lt.Cod_Produt = @PCodPrd
                         And lt.Qtd_Saldo > 0
                         And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'D'
                         And ( (IsNull(x.Cod_Produt,0) > 0) or
                               ( (x.Cod_Produt is null) and 
                                 ( (lt.Dat_Vencim is null) or 
                                   (lt.Dat_Vencim >= Case
                                                       When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                       When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                       Else dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(@PQtdMesMinPrzVctLot,0))
                                                     End) ) ) ) ) ,0)

Set @QtdLotDis = @QtdPck + @QtdDep

-- Retorna o resultado da function
RETURN @QtdLotDis

END
GO

SET ANSI_NULLS ON  
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[FN_IdPoliticaItem]
(
@PCodEstabe int,
@PCodLayout int,
@PCodGrpLay int,
@PCodOri varchar(1),
@PCodCli int,
@PIdPolCab int,
@PFlgPolCabInf bit,
@PCodPrd int,
@PQtdPed int,
@PDscInf numeric(18,8),
@PFlgDscInf bit,
@PFlgUsaPolLay bit,  -- utiliza somente politicas vinculadas
@PDatRef datetime    -- data do pedido, data atual
)

RETURNS int

AS

BEGIN

Set @PCodOri = Ltrim(Rtrim(@PCodOri))

Declare @PIdPolCom int,
        @pm_FlgUsaPolComPdv bit,
        @pm_FlgSugPolComIdeal bit,
        @pm_FlgSugPolComMenDsc bit

Select @pm_FlgUsaPolComPdv = IsNull(FlgUsaPolComPdv,0),
       @pm_FlgSugPolComIdeal = IsNull(FlgSugPolComIdeal,0),
       @pm_FlgSugPolComMenDsc = IsNull(FlgSugPolComMenDsc,0)
From PARAM
Where Cod_Estabe = @PCodEstabe

Set @PIdPolCom = 0

if @pm_FlgUsaPolComPdv = 1
  begin
    Set @PIdPolCom = (Select top 1 x.Id_PolCom 
                      From (Select p.Id_PolCom, p.Dat_Cadastro, s.Per_Descon, s.Ordem, s.Nivel,
                                   Prioridade1 = Case 
                                                   When (IsNull(s.Per_Descon,0) >= @PDscInf) and 
                                                        (@PIdPolCab > 0) and (p.Id_PolCom = @PIdPolCab) then '1'
                                                   When (IsNull(s.Per_Descon,0) >= @PDscInf) and (IsNull(lp.Id_PolCom,0) > 0) then '2'
                                                   When (IsNull(s.Per_Descon,0) >= @PDscInf) then '3'
                                                   --demais poiiticas
                                                   Else '4' 
                                                 End
                            From POCOM p 
                                 Inner Join PCXES pe on ((p.Id_PolCom = pe.Id_PolCom) and (pe.Cod_Estabe = @PCodEstabe))
                                 Left  Join dbo.FN_ViewPoliticasProduto(@PIdPolCab, @PCodPrd, @PDatRef) s on (p.Id_PolCom = s.Id_PolCom) 
                                 Left  Join LGXPC lp on (lp.Cod_Estabe = @PCodEstabe and lp.Cod_Layout = @PCodLayout and lp.Cod_Grupo = @PCodGrpLay and lp.Id_PolCom = p.Id_PolCom)
                                 Left  Join CLIEN cl on cl.Codigo = @PCodCli
                                 Left  Join PCXCL pc on ((p.Id_PolCom = pc.Id_PolCom) and (pc.Cod_Client = cl.Codigo)) 
                                 Left  Join PCXGC pg on ((p.Id_PolCom = pg.Id_PolCom) and (pg.Cod_GrpCli = cl.Cod_GrpCli)) 
                                 Left  Join PCXUF pu on ((p.Id_PolCom = pu.Id_PolCom) and (pu.Cod_Uf = cl.Cod_Estado)) 
                            
                            Where IsNull(p.Tip_PolCom,'') <> 'KIT'
                            And ( (p.Dat_Inicio Is Null  or (@PDatRef >= p.Dat_Inicio))  and
                                  (p.Dat_Termino Is Null or (@PDatRef <= p.Dat_Termino)) and
                                  (p.Bloqueado Is Null or p.Bloqueado = 0) ) 

                            And ( (@PCodOri = '') or
                                  ((@PCodOri = 'M') And (IsNull(p.Flg_Cfv,0) = 1)) or  -- movel - força de vendas 
                                  (((@PCodOri = 'T') or (@PCodOri = 'W')) And ((IsNull(p.Flg_PedEle,0) = 1) or (IsNull(p.Flg_Web,0) = 1))) or  -- E-commerce / internet
                                  ((@PCodOri <> '') and (CharIndex(@PCodOri,';M;T;W;') = 0) And (IsNull(p.Flg_Televendas,0) = 1)) ) 
                            And IsNull(s.Ordem,0) > 0 
                            And dbo.FN_PoliticaProdutoValida(@PCodEstabe, @PCodOri, p.Id_PolCom, @PCodPrd) = 1
                            
                            -- filtrar politicas validas para o cliente e produto vinculadas ao layout
                            And ((@PFlgUsaPolLay = 1) and (IsNull(lp.Id_PolCom,0) > 0) or (@PFlgUsaPolLay = 0))
                            And ((pc.Cod_Client > 0) or (pg.Cod_GrpCli > 0) or (pu.Cod_Uf <> ''))
                            
                            -- filtrar politicas que atendem o desconto, quando for o caso
                            And (((@PFlgDscInf = 0) and (s.Per_DesCon >= 0)) or 
                                 ((@PFlgDscInf = 1) and (s.Per_DesCon > = @PDscInf))) 
							And (@PQtdPed >= S.Qtd_Minimo)) x
                        
                      --Order by Prioridade1, Nivel, Ordem, Dat_Cadastro Desc, Id_PolCom desc )
                      Order by 
                        -- pedido eletronico
                        Case When (@PCodLayout > 0) then Prioridade1 End,
                        Case When (@PCodLayout > 0) then Nivel End,
                        Case When (@PCodLayout > 0) then Ordem End,
                        Case When (@PCodLayout > 0) then Dat_Cadastro End Desc,
                        Case When (@PCodLayout > 0) then Id_PolCom End Desc,
                     
                        -- Menor desconto
                        Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 1) then Per_Descon End,
                        Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 1) then Prioridade1 End,
                        Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 1) then Nivel End,
                        Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 1) then Ordem End,
                        Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 1) then Dat_Cadastro End Desc,
                        Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 1) then Id_PolCom End desc,
                     
                        -- Maior desconto
                        Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 0) then Per_Descon End Desc,
                        Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 0) then Prioridade1 End,
                        Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 0) then Nivel End,
                        Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 0) then Ordem End,
                        Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 0) then Dat_Cadastro End Desc,
                        Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 0) then Id_PolCom End desc)

    ------------------------------------------------------------------------------------------------------------------------------------------

    if (IsNull(@PIdPolCom,0) = 0) and (@PDscInf > 0)
      begin
        Set @PDscInf = 0

        Set @PIdPolCom = (Select top 1 x.Id_PolCom 
                          From (Select p.Id_PolCom, p.Dat_Cadastro, s.Per_Descon, s.Ordem, s.Nivel,
                                       Prioridade1 = Case 
                                                       When (IsNull(s.Per_Descon,0) >= @PDscInf) and 
                                                            (@PIdPolCab > 0) and (p.Id_PolCom = @PIdPolCab) then '1'
                                                       When (IsNull(s.Per_Descon,0) >= @PDscInf) and (IsNull(lp.Id_PolCom,0) > 0) then '2'
                                                       When (IsNull(s.Per_Descon,0) >= @PDscInf) then '3'
                                                       --demais poiiticas
                                                       Else '4' 
                                                     End
                                From POCOM p 
                                     Inner Join PCXES pe on ((p.Id_PolCom = pe.Id_PolCom) and (pe.Cod_Estabe = @PCodEstabe))
                                     Left  Join dbo.FN_ViewPoliticasProduto(@PIdPolCab, @PCodPrd, @PDatRef) s on (p.Id_PolCom = s.Id_PolCom) 
                                     Left  Join LGXPC lp on (lp.Cod_Estabe = @PCodEstabe and lp.Cod_Layout = @PCodLayout and lp.Cod_Grupo = @PCodGrpLay and lp.Id_PolCom = p.Id_PolCom)
                                     Left  Join CLIEN cl on cl.Codigo = @PCodCli
                                     Left  Join PCXCL pc on ((p.Id_PolCom = pc.Id_PolCom) and (pc.Cod_Client = cl.Codigo)) 
                                     Left  Join PCXGC pg on ((p.Id_PolCom = pg.Id_PolCom) and (pg.Cod_GrpCli = cl.Cod_GrpCli)) 
                                     Left  Join PCXUF pu on ((p.Id_PolCom = pu.Id_PolCom) and (pu.Cod_Uf = cl.Cod_Estado)) 
                                
                                Where IsNull(p.Tip_PolCom,'') <> 'KIT'
                                And ( (p.Dat_Inicio Is Null  or (@PDatRef >= p.Dat_Inicio))  and
                                      (p.Dat_Termino Is Null or (@PDatRef <= p.Dat_Termino)) and
                                      (p.Bloqueado Is Null or p.Bloqueado = 0) ) 

                                And ( (@PCodOri = '') or
                                      ((@PCodOri = 'M') And (IsNull(p.Flg_Cfv,0) = 1)) or  -- movel - força de vendas 
                                      (((@PCodOri = 'T') or (@PCodOri = 'W')) And ((IsNull(p.Flg_PedEle,0) = 1) or (IsNull(p.Flg_Web,0) = 1))) or  -- E-commerce / internet
                                      ((@PCodOri <> '') and (CharIndex(@PCodOri,';M;T;W;') = 0) And (IsNull(p.Flg_Televendas,0) = 1)) ) 

                                And IsNull(s.Ordem,0) > 0 
                                And dbo.FN_PoliticaProdutoValida(@PCodEstabe, @PCodOri, p.Id_PolCom, @PCodPrd) = 1
                                
                                -- filtrar politicas validas para o cliente e produto vinculadas ao layout
                                And ((@PFlgUsaPolLay = 1) and (IsNull(lp.Id_PolCom,0) > 0) or (@PFlgUsaPolLay = 0))
                                And ((pc.Cod_Client > 0) or (pg.Cod_GrpCli > 0) or (pu.Cod_Uf <> ''))
                                
                                -- filtrar politicas que atendem o desconto, quando for o caso
                                And (((@PFlgDscInf = 0) and (s.Per_DesCon >= 0)) or 
                                     ((@PFlgDscInf = 1) and (s.Per_DesCon > = @PDscInf))) 
								And (@PQtdPed >= S.Qtd_Minimo)) x
                            
                          --Order by Prioridade1, Nivel, Ordem, Dat_Cadastro Desc, Id_PolCom desc )
                          Order by 
                            -- pedido eletronico
                            Case When (@PCodLayout > 0) then Prioridade1 End,
                            Case When (@PCodLayout > 0) then Nivel End,
                            Case When (@PCodLayout > 0) then Ordem End,
                            Case When (@PCodLayout > 0) then Dat_Cadastro End Desc,
                            Case When (@PCodLayout > 0) then Id_PolCom End Desc,
                         
                            -- Menor desconto
                            Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 1) then Per_Descon End,
                            Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 1) then Prioridade1 End,
                            Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 1) then Nivel End,
                            Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 1) then Ordem End,
                            Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 1) then Dat_Cadastro End Desc,
                            Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 1) then Id_PolCom End desc,
                         
                            -- Maior desconto
                            Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 0) then Per_Descon End Desc,
                            Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 0) then Prioridade1 End,
                            Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 0) then Nivel End,
                            Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 0) then Ordem End,
                            Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 0) then Dat_Cadastro End Desc,
                            Case When (@PCodLayout = 0) and (@pm_FlgSugPolComMenDsc = 0) then Id_PolCom End desc)
       
      end

  end  -- if @pm_FlgUsaPolComPdv = 1

-- Retorna o resultado da function
RETURN IsNull(@PIdPolCom,0)

END
GO

SET ANSI_NULLS ON  
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[FN_IdPolComLayValido]
(
@PCodEstabe int,
@PCodLayout int,
@PCodGrupo int,
@PCodCli int
)

RETURNS int

AS

BEGIN

Declare @PIdPolCom int = 0

-- sugere a primeira politica que atende ao cliente e se for unica

if (Select count(p.Id_PolCom)
      From POCOM p 
           Inner Join (Select distinct it.Id_PolCom  -- prioridade: politica que não bloqueiam uso de outras politicas, data de cadastro mais recente
                         From LGXPC it 
                              Inner Join POCOM p on it.Id_PolCom = p.Id_PolCom 
                              Inner Join PCXES pe on it.Id_PolCom = pe.Id_PolCom and pe.Cod_Estabe = it.Cod_Estabe 
                        Where it.Cod_Estabe = @PCodEstabe
                          And it.Cod_Layout = @PCodLayout
                          And it.Cod_Grupo = @PCodGrupo
                          And ( (p.Dat_Inicio Is Null  or (cast(GetDate() as Date) >= p.Dat_Inicio))  and
                                (p.Dat_Termino Is Null or (cast(GetDate() as Date) <= p.Dat_Termino)) and
                                (p.Bloqueado Is Null or p.Bloqueado = 0) )
                          And ((p.Flg_PedEle = 1) or (p.Flg_Web = 1))) x on p.Id_PolCOm = x.Id_PolCom
           Left  Join CLIEN cl on cl.Codigo = @PCodCli
           Left  Join PCXCL pc on ((p.Id_PolCom = pc.Id_PolCom) and (pc.Cod_Client = cl.Codigo)) 
           Left  Join PCXGC pg on ((p.Id_PolCom = pg.Id_PolCom) and (pg.Cod_GrpCli = cl.Cod_GrpCli)) 
           Left  Join PCXUF pu on ((p.Id_PolCom = pu.Id_PolCom) and (pu.Cod_Uf = cl.Cod_Estado)) 
     Where ((IsNull(pc.Cod_Client,0) > 0) or (IsNull(pg.Cod_GrpCli,0) > 0) or (IsNull(pu.Cod_Uf,'') <> '')) ) = 1

  Select top 1 @PIdPolCom = p.Id_PolCom
    From POCOM p 
         Inner Join (Select distinct it.Id_PolCom,  -- prioridade: politica que não bloqueiam uso de outras politicas, data de cadastro mais recente
  	                        Ordem = Case 
                                      When IsNull(p.Flg_BlqPolDifItePdv,0) = 0 Then '1' 
                                      Else '2'
                                    End,
                            p.Dat_Cadastro								 
                       From LGXPC it 
                            Inner Join POCOM p on it.Id_PolCom = p.Id_PolCom 
                            Inner Join PCXES pe on it.Id_PolCom = pe.Id_PolCom and pe.Cod_Estabe = it.Cod_Estabe 
                      Where it.Cod_Estabe = @PCodEstabe
                        And it.Cod_Layout = @PCodLayout
                        And it.Cod_Grupo = @PCodGrupo
                          And ( (p.Dat_Inicio Is Null  or (cast(GetDate() as Date) >= p.Dat_Inicio))  and
                                (p.Dat_Termino Is Null or (cast(GetDate() as Date) <= p.Dat_Termino)) and
                                (p.Bloqueado Is Null or p.Bloqueado = 0) )
                        And ((p.Flg_PedEle = 1) or (p.Flg_Web = 1))) x on p.Id_PolCOm = x.Id_PolCom
         Left Join CLIEN cl on cl.Codigo = @PCodCli
         Left Join PCXCL pc on ((p.Id_PolCom = pc.Id_PolCom) and (pc.Cod_Client = cl.Codigo)) 
         Left Join PCXGC pg on ((p.Id_PolCom = pg.Id_PolCom) and (pg.Cod_GrpCli = cl.Cod_GrpCli)) 
         Left Join PCXUF pu on ((p.Id_PolCom = pu.Id_PolCom) and (pu.Cod_Uf = cl.Cod_Estado)) 
   Where ((IsNull(pc.Cod_Client,0) > 0) or (IsNull(pg.Cod_GrpCli,0) > 0) or (IsNull(pu.Cod_Uf,'') <> '')) 
   Order by Ordem, p.Tip_PolCom, x.Dat_Cadastro desc, p.Id_PolCom desc

-- Retorna o resultado da function
RETURN IsNull(@PIdPolCom,0)

END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[FN_EstoqueDisponivelLoteVen]
(
  @PCodEstabe int
, @PCodPrd int
, @PCodCliPagOpc int
, @PDatBas smalldatetime = null
, @PQtdMesMinPrzVctLotOpc int = null
, @PIdPolComOpc int  = null
)

RETURNS int

AS

BEGIN

Declare @QtdLotDis int

if IsNull(@PDatBas,0) = 0
  Set @PDatBas = cast(GetDate() as date)

Set @QtdLotDis = 0

Set @QtdLotDis = IsNull((Select QtdLotDis = IsNull(pk.Qtd_Saldo,0) + IsNull(dp.Qtd_Saldo,0)
                           From PRXES p Left Join

						        (Select lt.Cod_Produt, Qtd_Saldo = sum(lt.Qtd_Saldo)
                                   From (Select l1.Cod_Produt, l1.Qtd_Saldo
                                           From PRLOT l1 Inner Join
                                                PRODU pr on l1.Cod_Produt = pr.Codigo Inner Join
                                                DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and 
                                                            l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @PCodCliPagOpc Left Join
                                                (Select pl.Cod_Produt, pl.Cod_Lote
                                                   From PCXPL pl Inner Join 
                                                        POCOM pc on (pl.Id_PolCom = pc.Id_Polcom)
                                                  Where pc.Id_PolCom = @PIdPolComOpc
                                                    And ( (pc.Dat_Inicio Is Null  or (@PDatBas >= pc.Dat_Inicio))  and
                                                          (pc.Dat_Termino Is Null or (@PDatBas <= pc.Dat_Termino)) and
                                                          (pc.Bloqueado Is Null or pc.Bloqueado = 0) ) 
                                                ) x on (l1.Cod_Produt = x.Cod_Produt and l1.Cod_Lote = x.Cod_Lote) Left Join
                                                CLPRV vp on (vp.Cod_CliPag = @PCodCliPagOpc and vp.Cod_Produt = pr.Codigo) Left Join
                                                CLFBV vf on (vf.Cod_CliPag = @PCodCliPagOpc and vf.Cod_Fabric = pr.Cod_Fabricante)
                                          Where l1.Cod_Estabe = @PCodEstabe
                                            And l1.Cod_Produt = @PCodPrd
                                            And IsNull(l1.Qtd_Saldo,0) > 0 

                                            And ( (IsNull(x.Cod_Produt,0) > 0) or
                                                  ( (x.Cod_Produt is null) and 
                                                    ( (l1.Dat_Vencim is null) or 
                                                      (l1.Dat_Vencim >= Case
                                                                          When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                          When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                          Else dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(@PQtdMesMinPrzVctLotOpc,0))
                                                                        End) ) ))  

                                          UNION ALL

                                         Select l2.Cod_Produt, l2.Qtd_Saldo
                                           From PRLOT l2 inner Join
                                                PRODU pr on l2.Cod_Produt = pr.Codigo Left Join
                                                (Select pl.Cod_Produt, pl.Cod_Lote
                                                   From PCXPL pl Inner Join 
                                                        POCOM pc on (pl.Id_PolCom = pc.Id_Polcom)
                                                  Where pc.Id_PolCom = @PIdPolComOpc
                                                    And ( (pc.Dat_Inicio Is Null  or (@PDatBas >= pc.Dat_Inicio))  and
                                                          (pc.Dat_Termino Is Null or (@PDatBas <= pc.Dat_Termino)) and
                                                          (pc.Bloqueado Is Null or pc.Bloqueado = 0) ) 
                                                ) x on (l2.Cod_Produt = x.Cod_Produt and l2.Cod_Lote = x.Cod_Lote) Left Join
                                                CLPRV vp on (vp.Cod_CliPag = @PCodCliPagOpc and vp.Cod_Produt = pr.Codigo) Left Join
                                                CLFBV vf on (vf.Cod_CliPag = @PCodCliPagOpc and vf.Cod_Fabric = pr.Cod_Fabricante)

                                          Where l2.Cod_Estabe = @PCodEstabe 
                                            And l2.Cod_Produt = @PCodPrd

                                            And IsNull(l2.Qtd_Saldo,0) > 0 
                                            And ( (IsNull(x.Cod_Produt,0) > 0) or
                                                  ( (x.Cod_Produt is null) and 
                                                    ( (l2.Dat_Vencim is null) or 
                                                      (l2.Dat_Vencim >= Case
                                                                          When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                          When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                          Else dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(@PQtdMesMinPrzVctLotOpc,0))
                                                                        End) ) ))  

                                            And not Exists(Select 1 From DPXGC x 
                                                            Where x.Cod_Estabe = @PCodEstabe And x.Cod_Dep = l2.Cod_Dep)) lt
                                  Group by lt.Cod_Produt) pk on p.Cod_Produt = pk.Cod_Produt Left Join

                                (Select lt.Cod_Produt, Qtd_Saldo = sum(lt.Qtd_Saldo)
                                   From (Select l1.Cod_Estabe, l1.Cod_Produt, l1.Qtd_Saldo
                                           From PRLTL l1 Inner Join
                                                PRODU pr on l1.Cod_Produt = pr.Codigo Inner Join
                                                DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep 
                                                        and de.Cod_GrpCli = @PCodCliPagOpc Left Join
                                                (Select pl.Cod_Produt, pl.Cod_Lote
                                                   From PCXPL pl Inner Join 
                                                        POCOM pc on (pl.Id_PolCom = pc.Id_Polcom)
                                                  Where pc.Id_PolCom = @PIdPolComOpc
                                                    And ( (pc.Dat_Inicio Is Null  or (@PDatBas >= pc.Dat_Inicio))  and
                                                          (pc.Dat_Termino Is Null or (@PDatBas <= pc.Dat_Termino)) and
                                                          (pc.Bloqueado Is Null or pc.Bloqueado = 0) ) 
                                                ) x on (l1.Cod_Produt = x.Cod_Produt and l1.Cod_Lote = x.Cod_Lote) Left Join
                                                CLPRV vp on (vp.Cod_CliPag = @PCodCliPagOpc and vp.Cod_Produt = pr.Codigo) Left Join
                                                CLFBV vf on (vf.Cod_CliPag = @PCodCliPagOpc and vf.Cod_Fabric = pr.Cod_Fabricante)
                                          Where l1.Cod_Estabe = @PCodEstabe
                                            And dbo.FN_TipLocEnd(l1.Cod_Estabe, l1.Cod_Dep, l1.Num_Rua) = 'D'
                                            And l1.Cod_Produt = @PCodPrd
                                            And IsNull(l1.Qtd_Saldo,0) > 0 

                                            And ( (IsNull(x.Cod_Produt,0) > 0) or
                                                  ( (x.Cod_Produt is null) and 
                                                    ( (l1.Dat_Vencim is null) or 
                                                      (l1.Dat_Vencim >= Case
                                                                          When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                          When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                          Else dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(@PQtdMesMinPrzVctLotOpc,0))
                                                                        End) ) ))  


                                          UNION ALL

                                         Select l2.Cod_Estabe, l2.Cod_Produt, l2.Qtd_Saldo
                                           From PRLTL l2 Inner Join
                                                PRODU pr on l2.Cod_Produt = pr.Codigo Left Join
                                                (Select pl.Cod_Produt, pl.Cod_Lote
                                                   From PCXPL pl Inner Join 
                                                        POCOM pc on (pl.Id_PolCom = pc.Id_Polcom)
                                                  Where pc.Id_PolCom = @PIdPolComOpc
                                                    And ( (pc.Dat_Inicio Is Null  or (@PDatBas >= pc.Dat_Inicio))  and
                                                          (pc.Dat_Termino Is Null or (@PDatBas <= pc.Dat_Termino)) and
                                                          (pc.Bloqueado Is Null or pc.Bloqueado = 0) ) 
                                                ) x on (l2.Cod_Produt = x.Cod_Produt and l2.Cod_Lote = x.Cod_Lote) Left Join
                                                CLPRV vp on (vp.Cod_CliPag = @PCodCliPagOpc and vp.Cod_Produt = pr.Codigo) Left Join
                                                CLFBV vf on (vf.Cod_CliPag = @PCodCliPagOpc and vf.Cod_Fabric = pr.Cod_Fabricante)

                                          Where l2.Cod_Estabe = @PCodEstabe 
                                            And dbo.FN_TipLocEnd(l2.Cod_Estabe, l2.Cod_Dep, l2.Num_Rua) = 'D'
                                            And l2.Cod_Produt = @PCodPrd
                                            And IsNull(l2.Qtd_Saldo,0) > 0 

                                            And IsNull(l2.Qtd_Saldo,0) > 0 
                                            And ( (IsNull(x.Cod_Produt,0) > 0) or
                                                  ( (x.Cod_Produt is null) and 
                                                    ( (l2.Dat_Vencim is null) or 
                                                      (l2.Dat_Vencim >= Case
                                                                          When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                          When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                          Else dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(@PQtdMesMinPrzVctLotOpc,0))
                                                                        End) ) ))  

                                            And not Exists (Select 1 From DPXGC x Where x.Cod_Estabe = @PCodEstabe and x.Cod_Dep = l2.Cod_Dep)) lt

							      Group by lt.Cod_Produt) dp on p.Cod_Produt = dp.Cod_Produt  

                          Where p.Cod_Estabe = @PCodEstabe 
                            And p.Cod_Produt = @PCodPrd) ,0)

-- Retorna o resultado da function
RETURN @QtdLotDis

END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE TRIGGER [dbo].[TR_FS_NFCCE_GravaFLTRC] ON [dbo].[FS_NFCCE] 
FOR INSERT,UPDATE
NOT FOR REPLICATION
AS
BEGIN
  -- comando p/ corrigir erro delphi/ado: record was changed by another user
  SET NOCOUNT ON

  if Update(Xml_Retorno)
    begin  
      IF Not Exists(Select 1 from PARAM p Inner Join inserted i on p.Cod_Estabe = i.Cod_Estabe 
          Where ISNULL(p.Des_TknTreinacon,'')<>'')  
        return

      DECLARE @ArqXML nvarchar(max),   
              @NumCnpj varchar(14),
              @ChvAcesso varchar(44); 

      Select @ArqXML    = CONVERT(nvarchar(max), f.Xml_Retorno),           
             @ChvAcesso = i.Chv_Nfe,
             @NumCnpj   = i.Num_Cnpj                
      From Inserted i 
      Inner Join FS_NFCCE f on (i.Chv_Nfe = f.Chv_Nfe)     
      Where f.Des_CstatCC = '135'

      if (IsNull(@NumCnpj,'') <> '') and (IsNull(@ChvAcesso,'') <> '') and (IsNUll(@ArqXML,'') <> '')
        Insert Into FLTRC (Num_Cnpj, Chv_Acesso, Arquivo) Values (@NumCnpj, @ChvAcesso, @ArqXML)
    end
END

GO


SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

