      if (IsNull(@NumCnpj,'') <> '') and (IsNull(@ChvAcesso,'') <> '') and (IsNUll(@ArqXML,'') <> '')
        Insert Into FLTRC (Num_Cnpj, Chv_Acesso, Arquivo) Values (@NumCnpj, @ChvAcesso, @ArqXML)                                  
    end
