CREATE TRIGGER [dbo].[TR_NFECB_GravaFLTRC] ON [dbo].[NFECB] 
FOR INSERT,UPDATE
NOT FOR REPLICATION
AS
BEGIN
  -- comando p/ corrigir erro delphi/ado: record was changed by another user
  SET NOCOUNT ON

  if Update(Arquivo)
    begin  
      IF Not Exists(Select 1 from PARAM p Inner Join inserted i on p.Cod_Estabe = i.Cod_Estabe 
          Where ISNULL(p.Des_TknTreinacon,'')<>''
            And ISNULL(p.FlgUsaInfArm,0)<>0
            And ISNULL(p.DesUsuInfArm, '')<>''
            And ISNULL(p.DesSnhInfArm, '')<>'')   
        return

      DECLARE @ArqXML nvarchar(max),   
              @NumCnpj varchar(14),
              @ChvAcesso varchar(44);        

      Select @ArqXML    = CONVERT(nvarchar(max), n.Arquivo),           
             @ChvAcesso = i.Chv_Acesso,
             @NumCnpj   = e.Num_Cnpj         
      From Inserted i
      Inner Join ESTAB e on e.Cod_Estabe = i.Cod_Estabe
      Inner Join NFECB n on n.Cod_Estabe = i.Cod_Estabe And n.Protocolo = i.Protocolo
      Where i.Status = 'F'
        And ((ISNULL(i.Flg_ImpNot,0) = 0) OR (i.Ret_cStat = '100' and ISNULL(i.Flg_ImpNot,0) = 1))
             
      if (IsNull(@NumCnpj,'') <> '') and (IsNull(@ChvAcesso,'') <> '') and (IsNUll(@ArqXML,'') <> '')
        Insert Into FLTRC (Num_Cnpj, Chv_Acesso, Arquivo) Values (@NumCnpj, @ChvAcesso, @ArqXML)
    end
END

