CREATE PROCEDURE [dbo].[PR_GeraPdvRemConsig]
@PCodEstabe int, 
@PIdConsig int, 
@PNumSequen int,
@PTipOpe varchar(3),
@PNumPdv int output,
@PMsgErr varchar(8000) output

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now  smalldatetime = GetDate(),
        @Date smalldatetime = cast(GetDate() as Date)

Set @PNumPdv = 0
Set @PMsgErr = ''

if not Exists(Select 1 
                From CNGCB 
               Where Cod_Estabe = @PCodEstabe And Id_Consig = @PIdConsig And Sta_Consig = 'P') 
  Set @PMsgErr = 'Contrato de Consignação não está "pendente"'
else
if not Exists(Select 1 
                From CNGCB cb
                     Inner Join CLIEN cl on cb.Cod_TipCng = 'C' and cb.Cod_Entida = cl.Codigo 
               Where cb.Cod_Estabe = @PCodEstabe And cb.Id_Consig = @PIdConsig)
  Set @PMsgErr = 'Clinte inválido'
else
if not Exists(Select 1 
                From CNGRC 
               Where Cod_Estabe = @PCodEstabe And Id_Consig = @PIdConsig And Num_Sequen = @PNumSequen And Sta_CngPed = '1') 
  Set @PMsgErr = 'Não existe pedido a gerar'
else
if not Exists(Select 1 
                From CNGRI it 
               Where it.Cod_Estabe = @PCodEstabe And it.Id_Consig = @PIdConsig and it.Num_Sequen = @PNumSequen
                 And it.Qtd_Pedido > 0)
  Set @PMsgErr = 'Não existe itens a gerar'
else
if not Exists(Select 1 
                From CNGRI it 
                     Inner Join PRXES pr on it.Cod_Estabe = pr.Cod_Estabe and it.Cod_Produt = pr.Cod_Produt 
               Where it.Cod_Estabe = @PCodEstabe And it.Id_Consig = @PIdConsig and it.Num_Sequen = @PNumSequen)
  Set @PMsgErr = 'Não existe itens a gerar'
else
if Exists(Select 1 
            From PDVCB 
           Where Cod_Estabe = @PCodEstabe and Id_Consig = @PIdConsig and Num_SequenciaCtr = @PNumSequen)
  Select @PMsgErr = 'Pedido ('+cast(Numero as varchar)+') já havia sido gerado'
    From PDVCB 
   Where Cod_Estabe = @PCodEstabe and Id_Consig = @PIdConsig and Num_SequenciaCtr = @PNumSequen
else
if not Exists(Select 1 
                From TPOPE 
               Where Tip_EntSai = 'S' and Cod_CfoNorInt = 5917 and Cod_CfoNorExt = 6917
                 And Cod_Ope = @PTipOpe And Tip_Ope = 'O')
  Set @PMsgErr = 'Tipo de operação (O/5917/6917) inválido para Remessa em Consignação'
else
  begin

    BEGIN TRANSACTION

    Declare @ct_CodCli int,
            @ct_IdPolCom int, 
            @ct_CodVended int,
            @ct_CodOperad int,
            @ct_CodDigita int,
--            @ct_PerComVnd numeric(8,4),

            @pm_FlgUsaPolComPdv bit,
            @pm_FlgAltUnvItePdv bit, 
            @pm_FlgRegDscCliItePdv bit,

            @WFlgUsaWms bit,
            @WFlgBlqWms bit, 
            @WFlgBlqPol bit,
            @WCodTabPrz int, 
            @WCodLayout int,
            @WFlgBlqDscAutIte bit,
            @WFlgCriVrb bit,
            @WFlgBlqQtdPar bit, 

            @WFlgSnhEsp bit,          
            @WFlgNaoCriConCom bit,    
            @WFlgBlqCriPrcVen bit,
            @WNomUsuSnhEsp varchar(35)

    Select @pm_FlgAltUnvItePdv = IsNull(FlgAltUnvItePdv,0), 
           @pm_FlgRegDscCliItePdv = IsNull(FlgRegDscCliItePdv,0),
           @pm_FlgUsaPolComPdv = IsNull(FlgUsaPolComPdv,0)
      From PARAM
     Where Cod_Estabe = @PCodEstabe

    Select @ct_CodCli = cl.Codigo,
           @ct_IdPolCom = IsNull(ct.Id_PolCom,0),
           @ct_CodVended = ct.Cod_Vended, 
           @ct_CodOperad = ct.Cod_Operad, 
           @ct_CodDigita = ct.Cod_Digita 
    From CNGCB ct
           Inner Join CLIEN cl on ct.Cod_TipCng = 'C' and ct.Cod_Entida = cl.Codigo 
     Where ct.Cod_Estabe = @PCodEstabe and ct.Id_Consig = @PIdConsig

    -- WMS
    Set @WFlgUsaWms = (Select dbo.FN_ModExtOk(HASHBYTES('MD5','WMS'),
                                              HASHBYTES('MD5',(Select Num_Cnpj From ESTAB Where Cod_Estabe = @PCodEstabe))))

    Set @WFlgBlqWms = 0
    Set @WFlgBlqPol = 0
    Set @WCodTabPrz = 0
    Set @WCodLayout = 0

  -- Substring(Cod_OrigemPdv,1,1) = 'G'
    Exec PR_IncluiPDVCB 'P', @PCodEstabe, @PNumPdv output, 'G', @ct_CodCli, @WFlgUsaWms, @PTipOpe,
                        @ct_CodVended, @ct_CodOperad, @ct_CodDigita, @ct_IdPolCom, @WCodTabPrz, @WCodLayout,
                        @WFlgBlqWms, @WFlgBlqPol, @PMsgErr output

    Update pv
       Set pv.Status2 = 'X'
         , pv.Tip_Vencimento = ''
         , pv.Id_Consig = @PIdConsig    
         , pv.Num_SequenciaCtr = @PNumSequen
     From PDVCB pv
    Where pv.Cod_Estabe = @PCodEstabe
      And pv.Numero = @PNumPdv

    if @PNumPdv > 0
      begin
    
        Declare @WPFlgAchou bit,
                @WPTipSai varchar(1),
                @WPCodLot varchar(20),
                @WPLocFis varchar(15),
                @WPCodFab int,
                @WPFatCnvImpFat int,
                @WPPrcFab numeric(18,8),
                @WPPrcMaxCon numeric(18,8),
                @WPPrcRefFpb numeric(18,8),
                @WPPrcCusMinComMarkup numeric(18,8),
                @WPPrcTab numeric(18,8),
                @WPPrcTabBru numeric(18,8),
                @WPPrcUni numeric(18,8),
                @WPPrcUniLiqPer numeric(18,8),
                @WPFlgEmbDscPrc bit,
                @WPPerDscLin numeric(18,8),
                @WPPerDscPrz numeric(18,8),
                @WPPerDscVis numeric(18,8),
                @WPQtdPrzMax int,
                @WPCodRej varchar(3),
                @WPDesMsg varchar(80),
                @WPCmp varchar(20),
                @WPNomUsuDbq varchar(35),
                @WPDesMsgDbq varchar(60),
    
                @cr_NumSeq int,
                @cr_CodPrd int,
                @cr_QtdPed int, 
                @cr_PrcUni numeric(18,8), 
                @cr_PerDsc numeric(8,4), 
                @cr_FatCnvApr int,
                @cr_QtdImpFat numeric(18,4), 
                @cr_PrcUniImp numeric(18,8), 
                @cr_CodRej varchar(3),
                --@cr_DesMsg varchar(80),
                @WIte_QtdSolInf int,
                @WIte_QtdPedInf int, 
                @WIte_QtdBonInf int,
                @WIte_IdPolCom int,
    
                @WPPerDscPolCom numeric(18,8),
                @WPPerDscVisPolCom numeric(18,8),
                @WPPrcPolCom numeric(18,8),
                @WPQtdPrzPolCom int,
                @WPCodKitPrm int,
                @WPCodPromoc int,
                @WPFlgVerba bit,
                @WPFlgPolPrm bit,
    
                @WPC_PrcUni numeric(18,8),
                @WPC_PerDscIte numeric(18,8),
                @WPPrcUniLiqPdv numeric(18,8),
                @WPC_VlrDesconto numeric(18,8)  -- aqui
    
    ----------------------------------------------------------------------------------
    
        Declare PDVIT_Cr Cursor Local Fast_Forward For
    
          Select NumSeq = row_number() over(Order by it.Num_Sequen), it.Cod_Produt,
                 QtdPed = it.Qtd_Pedido,  
                 PrcUni = it.Prc_Unitar, 
                 it.Per_Descon, 
                 IsNull(it.Fat_CnvApr,1), QtdImpFat = it.Qtd_Pedido, PrcUniImp = it.Prc_Unitar
            From CNGRI it
                 Inner Join PRXES p on it.Cod_Estabe = p.Cod_Estabe and it.Cod_Produt = p.Cod_Produt
           Where it.Cod_Estabe = @PCodEstabe 
             And it.Id_Consig = @PIdConsig 
             And it.Num_Sequen = @PNumSequen
             And it.Qtd_Pedido > 0
    
        Open PDVIT_Cr
        Fetch Next From PDVIT_Cr Into @cr_NumSeq, @cr_CodPrd, 
                                      @cr_QtdPed, @cr_PrcUni, @cr_PerDsc, 
                                      @cr_FatCnvApr, @cr_QtdImpFat, @cr_PrcUniImp 
        While @@FETCH_STATUS = 0
          begin
            Set @WIte_QtdPedInf = @cr_QtdPed
            Set @WIte_QtdBonInf = 0
            Set @WIte_IdPolcom  = 0   -- ???????

            Set @WFlgBlqDscAutIte = 0
    
            Exec PR_InfoDefaultPDVIT @pm_FlgUsaPolComPdv, @PCodEstabe, @PNumPdv, @cr_CodPrd, 
                                     @WIte_QtdPedInf, @WIte_QtdBonInf, @WIte_IdPolCom output, @WFlgBlqDscAutIte,
                                     @WPFlgAchou output,
                                     @WPLocFis output,
                                     @WPCodFab output,
                                     @WPPrcFab output,
                                     @WPPrcMaxCon output,
                                     @WPPrcRefFpb output,
                                     @WPPrcTab output,
                                     @WPPrcTabBru output,
                                     @WPFatCnvImpFat output,     
                                     @WPPrcUni output,
                                     @WPPrcCusMinComMarkup output,
                                     @WPPerDscPolCom output,
                                     @WPPerDscVisPolCom output,
                                     @WPPrcPolCom output,
                                     @WPQtdPrzPolCom output,
                                     @WPFlgVerba output,
                                     @WPFlgPolPrm output,
                                     @WPCodKitPrm output,
                                     @WPCodPromoc output,
                                     @WPFlgEmbDscPrc output, 
                                     @WPQtdPrzMax output,
                                     @WPPerDscLin output,
                                     @WPPerDscPrz output,
                                     @WPPerDscVis output,
                                     @WPPrcUniLiqPer output
    
            if @WPFlgAchou = 1
              begin

                /*if @cr_PrcUni > 0 Conforme reunião com a Meire, 31/03/23, não há comno definir preço em consignação (validação indevida)
                  begin       
                    Set @WPPrcUni       = @cr_PrcUni
                    Set @WPPerDscLin    = @cr_PerDsc  
                    Set @WPPerDscPrz    = @cr_PerDsc
                    Set @WPPerDscVis    = @cr_PerDsc
                  end*/

                if IsNull(@cr_PrcUniImp,0) = 0
                  Set @cr_PrcUniImp = @WPPrcUni*@cr_FatCnvApr

                Set @WPCodLot       = '*'
                Set @WPTipSai       = ''
                Set @WPFatCnvImpFat = @cr_FatCnvApr
    
    ----------------------------------------------------------------
                --  calcfields 
                Set @WPC_PrcUni = @WPPrcUni
                Set @WPC_PerDscIte = @cr_PerDsc
                   
                --  calcula preco unitario liquido
                Set @WPPrcUniLiqPdv = @WPPrcUni*(1-@WPC_PerDscIte/100)
                   
                if @WPFlgEmbDscPrc = 1
                  begin
                    Set @WPC_PrcUni = @WPPrcUni*(1-@WPC_PerDscIte/100)
                    Set @WPC_PerDscIte = 0
                  end
                   
                Set @WFlgSnhEsp = 0 
                Set @WNomUsuSnhEsp = ''
                Set @WFlgNaoCriConCom = 0  -- coloquei
                Set @WFlgBlqCriPrcVen = 0  -- coloquei
                Set @WFlgCriVrb = 0        -- coloquei
                Set @WFlgBlqQtdPar = 0
    
                Exec PR_CriticaItemPDV @pm_FlgUsaPolComPdv, @PCodEstabe, @PNumPdv, @cr_CodPrd, 
                                       @WIte_IdPolCom, @WIte_QtdPedInf, @WIte_QtdBonInf, @WPTipSai, @WPQtdPrzMax,
                                       @WPPrcUni, @WPPerDscVis, @WPPerDscPrz, @cr_QtdImpFat, @cr_PrcUniImp,
                                       @WPCodKitPrm, @WPPerDscPolCom, @WPPerDscVisPolCom, @WPPrcPolCom,
                                       @WPPrcUniLiqPdv, @WPPrcCusMinComMarkup, @WPPrcUniLiqPer, @WPFlgVerba,
                                       @WFlgSnhEsp, @WNomUsuSnhEsp, @WFlgNaoCriConCom, @WFlgBlqCriPrcVen, @WFlgCriVrb, @WFlgBlqQtdPar,
                                       @WPCodRej output, @WPDesMsg output, @WPCmp output, @WPNomUsuDbq output, @WPDesMsgDbq output

                Set @WIte_QtdSolInf = @WIte_QtdPedInf + @WIte_QtdBonInf
    
                if (@WPDesMsg = '') or (Substring(@WPCodRej,1,2) = 'PZ')  
                  begin
                    Set @WPCodRej = ''
                    Set @WPDesMsg = ''
                  end
                else
                  begin
                    Set @WIte_QtdPedInf = 0
                    Set @WIte_QtdBonInf = 0
                  end
    
                --Set @WPCodRej = @cr_CodRej
                --Set @WPDesMsg = @cr_DesMsg
    
                Insert Into PDVIT (Cod_Estabe, Num_SeqDig, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai)
                  Values (@PCodEstabe, @cr_NumSeq, @PNumPdv, @cr_CodPrd, @WPCodLot, @WPTipSai)
                         
                Update PDVIT 
                   Set Qtd_Pedido = @WIte_QtdPedInf 
                     , Qtd_Bonificacao = @WIte_QtdBonInf 
                     , Id_PolCom = @WIte_IdPolCom 
                     , Loc_Fisica = @WPLocFis 
                     , Cod_Fabricante = @WPCodFab
                     , Qtd_PrzMax = @WPQtdPrzMax 
                     , Prc_Fabric = @WPPrcFab 
                     , Prc_MaxCon = @WPPrcMaxCon 
                     , Prc_RefFpb = @WPPrcRefFpb 
                     , Prc_Tabela = @WPPrcTab 
                     , Prc_TabBru = @WPPrcTabBru
           , Prc_Unitario = @WPPrcUni
                     , Per_Desconto = @WPPerDscLin 
                     , Per_Descon = @WPPerDscPrz 
                     , Per_DscVis = @WPPerDscVis 
                     , Flg_Verba = @WPFlgVerba 
                     , Prc_CusMinComMarkup = @WPPrcCusMinComMarkup
                     , Qtd_PrzPolCom = @WPQtdPrzPolCom 
           , Prc_PolCom = @WPPrcPolCom 
           , Per_DscPolCom = @WPPerDscPolCom 
           , Per_DscVisPolCom = @WPPerDscVisPolCom 
           , Cod_KitPrm = @WPCodKitPrm 
           , Cod_Promocao = @WPCodPromoc

                     , Prc_UniPde = 0
           , Per_DscPde = 0 
           , Cod_PrjPde = '' 
           , Num_SeqPdc = ''
                         
                     , Flg_PrcUniDsc = @WPFlgEmbDscPrc 
                     , Fat_CnvImpFat = @cr_FatCnvApr 
           , Qtd_ImpFat = @cr_QtdImpFat 
           , Prc_UniImpFat = @cr_PrcUniImp
           , C_PrcUni = @WPC_PrcUni 
           , C_PerDscIte = @WPC_PerDscIte

                     , Prc_UniLiqPer = @WPPrcUniLiqPer 
           , Qtd_Solicitado = @WIte_QtdSolInf 
           , Qtd_Acerto = 0 
           , Flg_PolPrm = @WPFlgPolPrm

                     , Cod_MtvRej = @WPCodRej
           , Des_MtvRej = Substring(@WPDesMsg,1,40)
           , Nom_UsuDesbloq = Substring(@WPNomUsuDbq,1,15)
           , Des_MsgDesbloq = Substring(@WPDesMsgDbq,1,60)

                 Where Cod_Estabe = @PCodEstabe
                   And Cod_Pedido = @PNumPdv
                   And Cod_Produto = @cr_CodPrd 
                   And Cod_Lote = @WPCodLot
                   And Tip_Sai = @WPTipSai


                --  atualiza motivo qdo for o caso
                Update PDVIT 
                   Set Cod_MtvRej = Case 
                                      When Qtd_Pedido > 0 then 'ES-' 
                                      Else 'ES0'
                                     End 
                 Where Cod_Estabe = @PCodEstabe
                   And Cod_Pedido = @PNumPdv
                   And Cod_Produto = @cr_CodPrd 
                   And Cod_Lote = @WPCodLot
                   And Tip_Sai = @WPTipSai
                   And Qtd_Pedido < Qtd_Solicitado 
                   And IsNull(Cod_MtvRej,'') = '' 

              end  -- if @WPFlgAchou = 1
    
            Fetch Next From PDVIT_Cr Into @cr_NumSeq, @cr_CodPrd, 
                                          @cr_QtdPed, @cr_PrcUni, @cr_PerDsc, 
                                          @cr_FatCnvApr, @cr_QtdImpFat, @cr_PrcUniImp 
          end
        Close PDVIT_Cr
        Deallocate PDVIT_Cr

        Update PDVCB 
         Set Status2 = 'A'
         Where Cod_Estabe = @PCodEstabe
           And Numero = @PNumPdv
    
        Exec PR_AtualizaCNGRI @PCodEstabe, @PIdConsig, @PNumSequen
        if (@@error <> 0)
          begin
            if @@trancount > 0
              Rollback Transaction
            Return
          end

        Update CNGRC
           Set Sta_CngPed = '2',
       Num_PedVen = @PNumPdv 
         Where Cod_Estabe = @PCodEstabe 
           And Id_Consig  = @PIdConsig 
           And Num_Sequen = @PNumSequen

      end  -- if @PNumPdv > 0
    
    if @@trancount > 0
      COMMIT TRANSACTION

  end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/*
Copia dedobramentos em PDECB
*/

CREATE PROCEDURE [dbo].[_CopiaPDECB]
@PCodEstabe int,
@PCodLayout int,
@PNumCnpj varchar(14),
@PCodPedCli varchar(20),
@PNumDesdobOri int,         -- dedobramento origem
@PNumDesdobDes int,         -- dedobramento destino
@PNewPedVen int             -- novo pedido de venda

AS

SET NOCOUNT ON

if Exists(Select 1 From PDECB 
            Where Cod_Estabe = @PCodEstabe And Cod_Layout = @PCodLayout And Num_Cnpj = @PNumCnpj And Cod_PedCli = @PCodPedCli And 
                  Num_Desdob = @PNumDesdobOri)
  begin

    BEGIN TRANSACTION

      -- inclui desdobramento de destino
      if not Exists(Select 1 From PDECB 
                      Where Cod_Estabe = @PCodEstabe And Cod_Layout = @PCodLayout And Num_Cnpj = @PNumCnpj And Cod_PedCli = @PCodPedCli And 
                            Num_Desdob = @PNumDesdobDes)
        Insert Into PDECB (Cod_Estabe,  Cod_Layout,  Num_Cnpj,  Cod_PedCli,  Num_Desdob)
                   Values (@PCodEstabe, @PCodLayout, @PNumCnpj, @PCodPedCli, @PNumDesdobDes)

      -- copiar todos os campos....exceto Num_PedVen, Vlr_Total, Qtd_Itens
      Update d
        Set d.Cod_MtvRej = '',
            d.Des_MtvRej = '',
            d.Num_PedVen = @PNewPedVen,
            d.Id_PolCom =  o.Id_PolCom,
            d.Cod_PolCom = o.Cod_PolCom,
            d.Isn_Arquiv = o.Isn_Arquiv,
            d.Sta_Pedido = o.Sta_Pedido,
            d.Cod_CliArq = o.Cod_CliArq,
            d.Cod_Client = o.Cod_Client,
            d.Cod_ConComArq = o.Cod_ConComArq,
            d.Cod_ForArq = o.Cod_ForArq,
            d.Cod_Operad = o.Cod_Operad,
            d.Cod_CtrPrj = o.Cod_CtrPrj,
            d.Cod_FabClp = o.Cod_FabClp,
            d.Cod_GrpClp = o.Cod_GrpClp,
            d.Cod_OriPed = o.Cod_OriPed,
            d.Cod_PedCmpCli = o.Cod_PedCmpCli,
            d.Cod_PrzArq = o.Cod_PrzArq,
            d.Cod_Projeto = o.Cod_Projeto,
            d.Cod_TabPrz = o.Cod_TabPrz,
            d.Cod_TipPrzArq = o.Cod_TipPrzArq,
            d.Cod_Vended = o.Cod_Vended,
            d.Dat_Cancel = o.Dat_Cancel,
            d.Dat_Encerra = o.Dat_Encerra,
            d.Dat_Inicio = o.Dat_Inicio,
            d.Dat_LeiPed = o.Dat_LeiPed,
            d.Dat_PedArq = o.Dat_PedArq,
            d.Dat_Validade = o.Dat_Validade,
            d.EAN_Comprador = o.EAN_Comprador,
            d.EAN_LocEntrega = o.EAN_LocEntrega,
            d.EAN_Fornecedor = o.EAN_Fornecedor,
            d.EAN_LocFatura = o.EAN_LocFatura,
            d.Flg_FatPedIntegral = o.Flg_FatPedIntegral,
            d.Flg_PolPedInf = o.Flg_PolPedInf,
            d.Layout = o.Layout,
            d.Nom_ArqPed = o.Nom_ArqPed,
            d.Num_PdConv = o.Num_PdConv,
            d.Num_CnpjEmpArq = o.Num_CnpjEmpArq,
            d.Num_CnpjGerPed = o.Num_CnpjGerPed,
            d.Num_SeqArq     = o.Num_SeqArq,
            d.Num_SeqArquiv  = o.Num_SeqArquiv,
            d.Observacao = o.Observacao,
            d.Obs_NotFis = o.Obs_NotFis,
            d.Per_DscCom  = o.Per_DscCom ,
            d.Per_DscFin = o.Per_DscFin,
            d.Qtd_PrzMed = o.Qtd_PrzMed,
            d.Qtd_Parcela = o.Qtd_Parcela,
            d.Qtd_Intervalo = o.Qtd_Intervalo,
            d.Time_ArqPed= o.Time_ArqPed,
            d.Tip_Compra = o.Tip_Compra,
            d.Tip_Fatura = o.Tip_Fatura,
            d.Tip_PedArq = o.Tip_PedArq,
            d.Tip_Pedido = o.Tip_Pedido,
            d.Tip_Ret = o.Tip_Ret,
            d.Tip_VctArq = o.Tip_VctArq,
            d.Tip_Vencimento = o.Tip_Vencimento,
            d.Ver_Layout = o.Ver_Layout
        From PDECB d 
             Inner Join PDECB o on (d.Cod_Estabe = o.Cod_Estabe and d.Cod_Layout = o.Cod_Layout And d.Num_Cnpj = o.Num_Cnpj And d.Cod_PedCli = o.Cod_PedCli)
        Where d.Cod_Estabe = @PCodEstabe And d.Cod_Layout = @PCodLayout And d.Num_Cnpj = @PNumCnpj And d.Cod_PedCli = @PCodPedCli 
        and d.Num_Desdob = @PNumDesdobDes
        and o.Num_Desdob = @PNumDesdobOri
      
    if @@trancount > 0
      COMMIT TRANSACTION

  end

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/*
Copia item PDEIT do desdobramento origem para destino. Elimina origem.
*/

CREATE PROCEDURE [dbo].[_CopiaItemPDEIT]
@PCodEstabe int,
@PCodLayout int,
@PNumCnpj varchar(14),
@PCodPedCli varchar(20),
@PNumDesdobOri int,         -- dedobramento origem
@PCodPrdCli varchar(14),
@PNumDesdobDes int,         -- dedobramento destino
@PFlgDelRegOri bit          -- elimina registro origem

AS

SET NOCOUNT ON

if Exists(Select 1 From PDEIT 
            Where Cod_Estabe = @PCodEstabe And Cod_Layout = @PCodLayout And Num_Cnpj = @PNumCnpj And Cod_PedCli = @PCodPedCli And 
                  Num_Desdob = @PNumDesdobOri And Cod_PrdCli = @PCodPrdCli)
  begin

    BEGIN TRANSACTION

      if not Exists(Select 1 From PDEIT 
                      Where Cod_Estabe = @PCodEstabe And Cod_Layout = @PCodLayout And Num_Cnpj = @PNumCnpj And Cod_PedCli = @PCodPedCli And 
                            Num_Desdob = @PNumDesdobDes And Cod_PrdCli = @PCodPrdCli)
        Insert into PDEIT (Cod_Estabe, Cod_Layout, Num_Cnpj, Cod_PedCli, Num_Desdob, Cod_PrdCli)
                   Values (@PCodEstabe, @PCodLayout, @PNumCnpj, @PCodPedCli, @PNumDesdobDes, @PCodPrdCli)

      Update new
         Set Tip_CodPrd = ori.Tip_CodPrd,
             Cod_Produt = ori.Cod_Produt,
             Qtd_Pedido = ori.Qtd_Pedido,
             Prc_Unitario = ori.Prc_Unitario,
             Per_Desconto = ori.Per_Desconto,
             Qtd_Atendi = ori.Qtd_Atendi,
             Und_Venda = ori.Und_Venda,
             Qtd_Embala = ori.Qtd_Embala,
             Id_PolCom = ori.Id_PolCom,
             Per_DscVis = ori.Per_DscVis,
             Qtd_PrzMax = ori.Qtd_PrzMax,
             Per_DscAut = ori.Per_DscAut,
             C_VlrPrcDsc = ori.C_VlrPrcDsc,
             C_TipLisPis = ori.C_TipLisPis,
             Per_Descon = ori.Per_Descon,
             Cod_MtvRej = ori.Cod_MtvRej,
             Des_MtvRej = ori.Des_MtvRej,
             Cod_PrdRef = ori.Cod_PrdRef,
             Cod_Projeto = ori.Cod_Projeto,
             Num_SeqPdc = ori.Num_SeqPdc,
             Num_IteCot = ori.Num_IteCot,
             Cod_PrdEmbFec = ori.Cod_PrdEmbFec,
             Qtd_PedEmbFec = ori.Qtd_PedEmbFec,
             Qtd_AteEmbFec = ori.Qtd_AteEmbFec,
             Flg_QtdPedTotEmbFec = ori.Flg_QtdPedTotEmbFec,
             Tip_Sai = ori.Tip_Sai,
             Per_DscExt = ori.Per_DscExt,
             Cod_Convenio = ori.Cod_Convenio,
             Fat_CnvImpFat = ori.Fat_CnvImpFat,
             Prc_UniImpFat = ori.Prc_UniImpFat,
             Fat_AprPad = ori.Fat_AprPad,
             Des_UnvImpFat = ori.Des_UnvImpFat,
             Des_AprImpFat = ori.Des_AprImpFat,
             Per_DscEmbPrc = ori.Per_DscEmbPrc,
             Cod_MtvRejOri = ori.Cod_MtvRejOri,
             Cod_PrdLayout = ori.Cod_PrdLayout,
             Cod_TipEmb = ori.Cod_TipEmb,
             Cod_TipDsc = ori.Cod_TipDsc,
             Flg_PolInf = ori.Flg_PolInf,
             Flg_PrcInf = ori.Flg_PrcInf,
             Flg_DscInf = ori.Flg_DscInf,
             Flg_PrzInf = ori.Flg_PrzInf,
             Qtd_Prz = ori.Qtd_Prz,
             Cod_PolCOm = ori.Cod_PolCom,
             Msg_Erro = ori.Msg_Erro,
             Cod_TipPrzArq = ori.Cod_TipPrzArq,
             Cod_PrzArq = ori.Cod_PrzArq,
             Prc_BasUni = ori.Prc_BasUni,
             Prc_LiqUni = ori.Prc_LiqUni,
             Cod_ConComArq = ori.Cod_ConComArq,
             Per_Repass = ori.Per_Repass,
             Cod_LotPrd = ori.Cod_LotPrd,
             Dat_VctPrd = ori.Dat_VctPrd,
             EAN_ProdutoArq = ori.EAN_ProdutoArq,
             Flg_BlqQtdPar = ori.Flg_BlqQtdPar,
             Num_SeqItem = ori.Num_SeqItem,
             Prc_UnitarArq = ori.Prc_UnitarArq,
             Per_DesconArq = ori.Per_DesconArq

        From PDEIT new Inner Join
             PDEIT ori on (new.Cod_Estabe = ori.Cod_Estabe and new.Cod_Layout = ori.Cod_Layout and new.Num_Cnpj = ori.Num_Cnpj and
                         new.Cod_PedCli = ori.Cod_PedCli and ori.Num_Desdob = @PNumDesdobOri and new.Cod_PrdCli = ori.Cod_PrdCli) 
       Where new.Cod_Estabe = @PCodEstabe      
         and new.Cod_Layout = @PCodLayout
         and new.Num_Cnpj = @PNumCnpj 
         and new.Cod_PedCli = @PCodPedCli 
         and new.Num_Desdob = @PNumDesdobDes
         and new.Cod_PrdCli = @PCodPrdCli
	 
      if (@@rowcount > 0) and  -- elimina registro de origem
         (@PFlgDelRegOri = 1)
        Delete From PDEIT
         Where Cod_Estabe = @PCodEstabe And Cod_Layout = @PCodLayout And Num_Cnpj = @PNumCnpj And Cod_PedCli = @PCodPedCli And 
               Num_Desdob = @PNumDesdobOri And Cod_PrdCli = @PCodPrdCli
      
    COMMIT TRANSACTION
  end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[FN_ExisteLoteDisponivel]
(
  @PCodEstabe int,
  @PCodCliPag int,
  @PCodPrd int,
  @PDatBas smalldatetime,
  @PQtdMesMinPrzVctLot int
)
RETURNS bit

AS

BEGIN

Declare @FlgAchou bit

Set @FlgAchou = 0

if Exists(Select 1
            From PRLOT lt  
                 Inner Join PRODU pr on lt.Cod_Produt = pr.Codigo 
                 Left  Join CLPRV vp on vp.Cod_CliPag = @PCodCliPag and vp.Cod_Produt = pr.Codigo 
                 Left  Join CLFBV vf on vf.Cod_CliPag = @PCodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
           Where lt.Cod_Estabe = @PCodEstabe
             And lt.Cod_Produt = @PCodPrd
             And lt.Qtd_Saldo > 0
             And ((lt.Dat_Vencim is null) or 
                  (lt.Dat_Vencim >= Case
                                      When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                      When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                      Else dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(@PQtdMesMinPrzVctLot,0))
                                    End)) 
           Group by lt.Cod_Lote, lt.Dat_Vencim) OR
   Exists(Select 1
            From PRLTL lt
                 Inner Join PRODU pr on lt.Cod_Produt = pr.Codigo 
                 Left  Join CLPRV vp on vp.Cod_CliPag = @PCodCliPag and vp.Cod_Produt = pr.Codigo 
                 Left  Join CLFBV vf on vf.Cod_CliPag = @PCodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
           Where lt.Cod_Estabe = @PCodEstabe 
             And lt.Cod_Produt = @PCodPrd
             And lt.Qtd_Saldo > 0
             And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'D'
             And ((lt.Dat_Vencim is null) or 
                  (lt.Dat_Vencim >= Case
                                      When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                      When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                      Else dbo.FN_DataVenctoMinimo(@PDatBas,IsNull(@PQtdMesMinPrzVctLot,0))
                                    End)) 
           Group by lt.Cod_Lote, lt.Qtd_EmbFec, lt.Dat_Vencim)
  Set @FlgAchou = 1

-- Retorna o resultado da function
RETURN @FlgAchou

END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

