CREATE FUNCTION [dbo].[FN_FlgMarkupPDVCB]
(
  @PIdPolCom int
)
RETURNS bit

AS

BEGIN

Declare @WFlgMarkup bit,
        @Date smalldatetime

Set @WFlgMarkup = 0
Set @Date = cast(GetDate() as date)

if Exists(Select 1
            From POCOM 
           Where Id_PolCom = @PIdPolCom
             And ((Dat_Inicio is Null)  or (@Date >= Dat_Inicio)) 
             And ((Dat_Termino is Null) or (@Date <= Dat_Termino)) 
             And IsNull(Bloqueado,0) = 0 
             And IsNull(Flg_MarkupCusCom,0) = 1)
   Set @WFlgMarkup = 1

-- Retorna o resultado da function
RETURN IsNull(@WFlgMarkup,0)

END
