CREATE FUNCTION [dbo].[FN_ItensLotesPdvOk]
(
  @PEstabe int,
  @PNumPdv int
)
RETURNS bit

AS

BEGIN

  -- Declarar variável de retorno da function
  DECLARE @FlgOk bit

  Set @FlgOk = 0
  
  if Exists(Select 1 From PDVLT Where Cod_Estabe = @PEstabe and Cod_Pedido = @PNumPdv)
    if Exists(Select 1
                From (Select Cod_Produto, QtdIte = SUM(IsNull(Qtd_Pedido,0)+Isnull(Qtd_Bonificacao,0)) 
                        From PDVIT 
                       Where Cod_Estabe = @PEstabe
                         And Cod_Pedido = @PNumPdv
                         And (IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) > 0 
                       Group by Cod_Produto) it Left Outer Join 
                     (Select Cod_Produt, QtdLot = SUM(IsNull(Qtd_Lote,0)) 
                        From PDVLT lt 
                       Where Cod_Estabe = @PEstabe
                         And Cod_Pedido = @PNumPdv
                         And IsNull(Qtd_Lote,0) > 0
                       Group by Cod_Produt) lt on it.Cod_Produto = lt.Cod_Produt 
               Where IsNull(it.QtdIte,0) <> IsNull(lt.QtdLot,0))
      Set @FlgOk = 1
 
  -- Retorna o resultado da function
  RETURN @FlgOk

 END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[FN_PrcCusPrdDatRef]
(
@PCodEstabe int,
@PCodPrd int,
@PCodCus char(1),   -- Preco (V)enda, (E)ntrada sem IPI, (I)- entrada com IPI, (C)usto, (M)édio, (B)-Medio Comercial
@PCodOri char(1),   -- (G)erencial,(O)ficial, (N)ao Oficial
@PDatRef smalldatetime
)
RETURNS numeric(18,4)

AS

BEGIN

Declare @PVlrCus numeric(18,4)

Set @PVlrCus = 0
Set @PDatRef = @PDatRef + 1

-- Preco pelo Registro do Historico de Precos
-- nao eh pelo preco de entrada (compra)
if ((@PCodCus <> 'E') and (@PCodCus <> 'I'))
  if Exists(Select 1 From HSPRC 
             Where Cod_Estabe = @PCodEstabe And Cod_Produto = @PCodPrd
               And Dat_Alteracao < @PDatRef)
    Select top 1 
	       @PVlrCus = Case 
                        When (@PCodCus = 'V') then Vlr_PrcVen
                        When (@PCodCus = 'C') then Vlr_CusLiqPra
                        When (@PCodCus = 'B') and (IsNull(Vlr_CusMedCom,0) > 0) then Vlr_CusMedCom
                        When (@PCodCus = 'B') and (IsNull(Vlr_CusMedCom,0) = 0) then Vlr_CusMed
                        When (@PCodCus = 'M') and (@PCodOri = 'G') then Vlr_CusMed
                        When (@PCodCus = 'M') and (@PCodOri = 'O') then Vlr_CusMedPra
                        When (@PCodCus = 'M') and (@PCodOri = 'N') then Vlr_CusMedDep
                        Else 0
                      End
	  From HSPRC 
     Where Cod_Estabe = @PCodEstabe
       And Cod_Produto = @PCodPrd
       And Dat_Alteracao < @PDatRef
     Order by Dat_Alteracao desc, Seq_Alteracao desc


-- Preco pelo Registro de Entrada
if IsNull(@PVlrCus,0) = 0 
  Select top 1 
	     @PVlrCus = Case 
                      When (@PCodCus = 'C') then i.Cus_LiqUni
                      When (@PCodCus = 'M') or (@PCodCus = 'B') then i.Prc_CustoMedio
                      When (@PCodCus = 'V') then i.Prc_Venda
                      When (@PCodCus = 'E') then i.Prc_Unitario*(1-i.Per_DescItem/100)
                      When (@PCodCus = 'I') then i.Prc_Unitario*(1-i.Per_DescItem/100)+(i.Vlr_Ipi/(i.Qtd_Pedido+i.Qtd_Bonificacao))
                      When (@PCodCus = 'X') then Round((i.Vlr_TotItem-i.Vlr_DescRateado-IsNull(i.Vlr_DscTri,0)+i.Vlr_DespRateada+i.Vlr_Ipi)/(i.Qtd_Pedido+i.Qtd_Bonificacao),4)
                      Else 0
                    End
    From NFEIT i 
         Inner Join NFECB c on i.Cod_Estabe = c.Cod_Estabe and i.Protocolo = c.Protocolo 
   Where c.Status = 'F' and c.Tip_NF = 'C'
     And c.Cod_Estabe = @PCodEstabe
     And i.Cod_Produto = @PCodPrd
     And i.Dat_Movimento < @PDatRef
   Order by i.Dat_Movimento desc, i.Protocolo desc


-- ultimo caso pega precos atuais do cadastro
if IsNull(@PVlrCus,0) = 0 
  Select @PVlrCus = Case 
                      When (@PCodCus = 'C') or (@PCodCus = 'X') then es.Prc_CusLiqEnt
                      When (@PCodCus = 'B') and (IsNull(es.Prc_CusMedCom,0) > 0) then es.Prc_CusMedCom
                      When (@PCodCus = 'B') and (IsNull(es.Prc_CusMedCom,0) = 0) then es.Prc_CusMed
                      When (@PCodCus = 'M') and (@PCodOri = 'G') then es.Prc_CusMed
                      When (@PCodCus = 'M') and (@PCodOri = 'O') then es.Prc_CusMedPra
                      When (@PCodCus = 'M') and (@PCodOri = 'N') then es.Prc_CusMedDep
                      When (@PCodCus = 'E') then es.Prc_UltEnt*(1-IsNull(es.Per_DscUltEnt,0)/100)
                      When (@PCodCus = 'I') then (es.Prc_UltEnt*(1-IsNull(es.Per_DscUltEnt,0)/100))*(1+IsNull(pr.Per_Ipi,0)/100)
                      Else es.Prc_Venda
                    End
    From PRXES es
         inner join PRODU pr on es.Cod_Produt = pr.Codigo
   Where es.Cod_Estabe = @PCodEstabe
     And es.Cod_Produt = @PCodPrd

-- Retorna o resultado da function
RETURN Round(@PVlrCus,4)

END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 
CREATE FUNCTION [dbo].[Fn_StaCtaRec]
(
  @PCodEstabe int,
  @PCodDoc int,
  @PDatRef smalldatetime
)
RETURNS varchar(1)
 
AS
 
BEGIN
 
  -- Declarar variável de retorno da function
  Declare @Cod_Sta varchar(1)

  if dbo.Fn_SldCtaRec(@PCodEstabe,@PCodDoc,@PDatRef) > 0
    begin
      Set @Cod_Sta = 'A'
      if Exists(Select 1 From BXREC Where Cod_Estabe = @PCodEstabe And Cod_Documento = @PCodDoc 
	            And Dat_Lancamento <= @PDatRef And Status = 'P')
        Set @Cod_Sta = 'P' 
	end
  else
    begin
      Set @Cod_Sta = 'Q'
      if Exists(Select 1 From BXREC Where Cod_Estabe = @PCodEstabe And Cod_Documento = @PCodDoc 
	            And Dat_Lancamento <= @PDatRef And Status = 'B')
        Set @Cod_Sta = 'B'
      else
      if Exists(Select 1 From CTREC Where Cod_Estabe = @PCodEstabe And Cod_Documento = @PCodDoc 
	            And IsNull(Dat_Devol,0) > 0 and @PdatRef >= IsNull(Dat_Devol,0))
        Set @Cod_Sta = 'D'
      else
      if Exists(Select 1 From CTREC Where Cod_Estabe = @PCodEstabe And Cod_Documento = @PCodDoc 
	            And IsNull(Dat_Cancel,0) > 0 and @PdatRef >= IsNull(Dat_Cancel,0))
        Set @Cod_Sta = 'C'
	end

  -- Retorna o resultado da function
  RETURN @Cod_Sta
 
END
 
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_AnalisaCreditoCliente]
@PCodOpe varchar(3),   -- COT-cotacao, <>- outras
@PCodEstabe int,
@PCodCli int,
@PNumPdv int,
@PMsg varchar(8000) output,
@PSta smallint output,
@PStaLic varchar(1) output,
@PCodMtv varchar(3) output

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime

Set @Now = GetDate()
Set @Date = cast(GetDate() as date)

Set @PMsg = ''
Set @PSta = 0      -- 0=verde; 1=amarelo; 2=vermelho; 3=preto
Set @PStaLic = ''  -- licencas do cliente quando paremetrizado, B=bloqueado (vencido)
Set @PCodMtv = ''  -- codigo motivo rejeição

if Exists(Select Codigo From CLIEN Where Codigo = @PCodCli)
  BEGIN

  Declare @cl_Bloqueado bit, 
          @cl_Motivo_Bloqueio varchar(30), 
          @cl_Usuario_Bloqueio varchar(15),
          @cl_Atraso_Atual int, 
          @cl_Atraso_Permitido int,
          @cl_Sta_ChqVnc varchar(1),
          @cl_Cod_CliPag int,
          @cl_SldLimCred numeric(18,4),
          @cl_Limite_Credito numeric(18,4),
          @cl_Atraso_MedAtu int,
		  @cl_Data_UltimaFatura smalldatetime,
		  @cl_Data_Cadastro smalldatetime,
		  @cl_Dat_LimCreAtu smalldatetime,
          @cl_Cod_InfCredito int,
          @cl_Flg_NaoBlqDocPdv bit,
          @cl_Flg_NaoBlqFinPdv bit,

          @ic_Descricao varchar(30),
          @ic_Controle varchar(1),

          @pm_FlgBlqIncPdvCliAtr bit,
          @pm_FlgBlqPdvAtrCtr bit,
          @pm_FlgCtrBlqPdvLicCli bit,
          @pm_QtdDiaAtrMedCtr int,
          @pm_QtdMesTmpCom int,
          @pm_FlgBlqVenCliSemLimCre bit,
          @pm_FlgBlqCtrDocClaPrd bit,

		  @Wpr_FlgBlqCtrLic bit,
          @WValTotPdvPen numeric(18,4),
          @WAtrMedAtu int,
          @WFlgLicSauIrr bit,
          @WFlgLicAnvIrr bit,
          @WFlgLicCrfIrr bit,
          @WFlgAlvFunIrr bit,
          @WMsgLicIrr varchar(30),
		  @WFlgBlqCtrDocClaPrd bit

  Select @cl_Bloqueado = IsNull(cl.Bloqueado,0), 
         @cl_Motivo_Bloqueio = IsNull(cl.Motivo_Bloqueio,''), 
         @cl_Usuario_Bloqueio = IsNull(cl.Usuario_Bloqueio,''),
         @cl_Atraso_Atual = IsNull(cl.Atraso_Atual,0), 
         @cl_Atraso_Permitido = IsNull(cl.Atraso_Permitido,0),
         @cl_Sta_ChqVnc = IsNull(cl.Sta_ChqVnc,''),
         @cl_Cod_CliPag = IsNull(cl.Cod_CliPag,0),
         @cl_Limite_Credito = IsNull(cl.Limite_Credito,0),
         @cl_SldLimCred = IsNull(cl.Limite_Credito,0) - IsNull(cl.Total_Debito,0),
		 @cl_Atraso_MedAtu = IsNull(cl.Atraso_MedAtu,0),
         @cl_Data_UltimaFatura = IsNull(cl.Data_UltimaFatura,0),
         @cl_Data_Cadastro = IsNull(cl.Data_Cadastro,0),
         @cl_Dat_LimCreAtu = IsNull(cl.Dat_LimCreAtu,0),
         @cl_Cod_InfCredito = IsNull(Cod_InfCredito,0),
		 @cl_Flg_NaoBlqDocPdv = IsNull(cl.Flg_NaoBlqDocPdv,0),
		 @cl_Flg_NaoBlqFinPdv = IsNull(cl.Flg_NaoBlqFinPdv,0),
         @ic_Descricao = IsNull(ic.Descricao,''),
         @ic_Controle = IsNull(ic.Controle,'')
    From CLIEN cl
         Left Outer Join INFCR ic on cl.Cod_InfCredito = ic.Codigo
	Where cl.Codigo = @PCodCli

  if @cl_Flg_NaoBlqFinPdv = 0
    if Exists(Select 1 From CLIEN Where IsNull(Flg_NaoBlqFinPdv,0) = 1 And Cod_CliPag = @cl_Cod_CliPag)
      Set @cl_Flg_NaoBlqFinPdv = 1

  Select @pm_FlgBlqIncPdvCliAtr = IsNull(FlgBlqIncPdvCliAtr,0),
         @pm_FlgBlqPdvAtrCtr = IsNull(FlgBlqPdvAtrCtr,0),
         @pm_FlgCtrBlqPdvLicCli = IsNull(FlgCtrBlqPdvLicCli,0),
         @pm_QtdDiaAtrMedCtr = IsNull(QtdDiaAtrMedCtr,0),
         @pm_QtdMesTmpCom = IsNull(QtdMesTmpCom,0),
         @pm_FlgBlqVenCliSemLimCre = IsNull(FlgBlqVenCliSemLimCre,0),
         @pm_FlgBlqCtrDocClaPrd = IsNull(FlgBlqCtrDocClaPrd,0)
    From PARAM
	Where Cod_Estabe = @PCodEstabe

    -- ver bloqueio manual
    if @cl_Bloqueado = 1
      begin
        Set @PSta = 3
        Set @PCodMtv = 'CLB'
--        if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
        if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
        Set @PMsg = @PMsg + @cl_Motivo_Bloqueio+' ('+@cl_Usuario_Bloqueio+')'
      end

    -- bloqueio financeiro
    if @cl_Flg_NaoBlqFinPdv = 0  -- nunca bloqueia financeiramente
      begin

        if @pm_FlgBlqIncPdvCliAtr = 1
          if @cl_Atraso_Atual > @cl_Atraso_Permitido
            begin
              Set @PSta = 3
              Set @PCodMtv = 'CLB'
              if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
              Set @PMsg = @PMsg + 'ATRASO ATUAL MAIOR QUE O PERMITIDO' 
            end

        -- ver bloqueio por cheques
        if @cl_Sta_ChqVnc = '1' 
          begin
            if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
            Set @PMsg = @PMsg + 'CHEQUE(s) P/TIT(s).VENCIDO(s)'
            if 2 > @PSta
              Set @PSta = 2
          end
        else
          if @cl_Cod_CliPag > 0
            begin
              -- verifica atraso do grupo
              if Exists(Select 1 From CLIEN 
                          Where Cod_CliPag = @cl_Cod_CliPag
                          And Sta_ChqVnc = '1')
                begin
                  if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
                  Set @PMsg = @PMsg + 'CHEQUE(s) P/TIT(s).VENCIDO(s) (GRUPO)'
                  if 2 > @PSta
                    Set @PSta = 2
                end
            end

        if @cl_Sta_ChqVnc = '2' 
          begin
            if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
            Set @PMsg = @PMsg + 'CHEQUE(s).DEVOLVIDO(s)'
            if 2 > @PSta
              Set @PSta = 2
          end
        else
          if @cl_Cod_CliPag > 0
            begin
              -- verifica atraso do grupo
              if Exists(Select 1 From CLIEN 
                          Where Cod_CliPag = @cl_Cod_CliPag
                          And Sta_ChqVnc = '2')
                begin
                  if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
                  Set @PMsg = @PMsg + 'CHEQUE(s).DEVOLVIDO(s) (GRUPO)'
                  if 2 > @PSta
                    Set @PSta = 2
                end
            end
       
        if @cl_Sta_ChqVnc = '3'
          begin
            if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
            Set @PMsg = @PMsg + 'CHEQUE(s).BAIXADO(s)'
            if 2 > @PSta
              Set @PSta = 2
          end
        else
          if @cl_Cod_CliPag > 0
            begin
              -- verifica atraso do grupo
              if Exists(Select 1 From CLIEN 
                          Where Cod_CliPag = @cl_Cod_CliPag
                          And Sta_ChqVnc = '3')
                begin
                  if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
                  Set @PMsg = @PMsg + 'CHEQUE(s).BAIXADO(s) (GRUPO)'
                  if 2 > @PSta
                    Set @PSta = 2
                end
            end

        -- ver bloqueio automatico
        -- debita pedidos nao faturados do limite de credito+
        Set @cl_SldLimCred = dbo.FN_SaldoCreditoCliente(@PCodEstabe,@PCodCli)
        if @cl_SldLimCred < 0
          begin
            if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
            Set @PMsg = @PMsg + 'LIMITE DE CRÉDITO ESTOURADO'
            if 2 > @PSta
              Set @PSta = 2

/*
            -- bloqueia cliente se for o caso
            Update CLIEN
              Set Bloqueado = 1,
                  Motivo_Bloqueio = 'Bloq. auto. por lim. de créd.'
            Where Codigo = @PCodCli
            And IsNull(Bloqueado,0) = 0
            And @pm_FlgBlqVenCliSemLimCre = 1
*/
          end

        if @cl_Atraso_Atual > @cl_Atraso_Permitido
          begin
            if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
            Set @PMsg = @PMsg + 'ATRASO NOS PAGAMENTOS'
            if 2 > @PSta
              Set @PSta = 2
          end
        else
          if @cl_Cod_CliPag > 0
            begin
              -- verifica atraso do grupo
              if Exists(Select 1 From CLIEN 
                          Where Cod_CliPag = @cl_Cod_CliPag
                          And Atraso_Atual > Atraso_Permitido)
                begin
                  if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
                  Set @PMsg = @PMsg + 'ATRASO NOS PAGAMENTOS(GRUPO)'
                  if 2 > @PSta
                    Set @PSta = 2
                end
            end

        if @pm_FlgBlqPdvAtrCtr = 1
          if @cl_Atraso_MedAtu > @pm_QtdDiaAtrMedCtr
            begin
              if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
              Set @PMsg = @PMsg + 'ATRASO MEDIO MAIOR QUE O PERMITIDO'
              if 2 > @PSta
                Set @PSta = 2
            end
          else
            if @cl_Cod_CliPag > 0
              begin
                -- verifica atraso medio do grupo
    			Set @WAtrMedAtu = 0
	    		Set @WAtrMedAtu = IsNull((Select Sum(IsNull(Atraso_MedAtu,0))/count(*) as Atr_MedMed From CLIEN 
                                          Where Cod_CliPag = @cl_Cod_CliPag
                                          And Atraso_MedAtu > 0),0)
                if IsNull(@WAtrMedAtu,0) > @pm_QtdDiaAtrMedCtr
                  begin
                    if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
                    Set @PMsg = @PMsg + 'ATRASO MEDIO MAIOR QUE O PERMITIDO(GRUPO)'
                    if 2 > @PSta
                      Set @PSta = 2
                  end
              end

        if @pm_QtdMesTmpCom > 0 
          if ((DateDiff(day,@cl_Data_UltimaFatura,@Date)/ 30) > @pm_QtdMesTmpCom) and
             ((DateDiff(day,@cl_Data_Cadastro,@Date)/ 30) > @pm_QtdMesTmpCom) and
             ((DateDiff(day,@cl_Dat_LimCreAtu,@Date)/ 30) > @pm_QtdMesTmpCom) 
            begin
              if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
              Set @PMsg = @PMsg + 'CLIENTE NÃO COMPRA HÁ MAIS DE '+cast(@pm_QtdMesTmpCom as varchar)+' MESES'
              if 2 > @PSta
                Set @PSta = 2
            end

        -- ver bloqueio por inf. de credito
        if @cl_Cod_InfCredito > 0 
          begin
            if IsNull(@ic_Descricao,'') <> ''
              begin
                if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
                Set @PMsg = @PMsg + @ic_Descricao
                if @ic_Controle = 'B' -- bloqueado
                  if 3 > @PSta
                    begin
                      Set @PSta = 3
                      Set @PCodMtv = 'CLB'
                    end
                  else
			        Set @PCodMtv = ''
                else
                if @ic_Controle = 'A'   -- aprovacao
                  if 2 > @PSta
                    Set @PSta = 2
                  else
	    		    Set @PCodMtv = ''
                else
                if @ic_Controle = 'O'   -- observacao
                  if 1 > @PSta
                    Set @PSta = 1
              end
          end

      end  -- if @cl_Flg_NaoBlqFinPdv = 0

    -- ver bloqueios por licenças vencidas
	-- licença da saúde
    Exec PR_AnalisaLicencaCliente @PCodOpe, 'SAUDE',  @PCodCli, @WFlgLicSauIrr output, @WMsgLicIrr output
    if @WFlgLicSauIrr = 1
      if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
        Set @PMsg = @PMsg + @WMsgLicIrr

	-- licença da ANVISA
    Exec PR_AnalisaLicencaCliente @PCodOpe, 'ANVISA',  @PCodCli, @WFlgLicAnvIrr output, @WMsgLicIrr output
    if @WFlgLicAnvIrr = 1
      if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
        Set @PMsg = @PMsg + @WMsgLicIrr

    -- licenca CRF
    Exec PR_AnalisaLicencaCliente @PCodOpe, 'CRF',  @PCodCli, @WFlgLicCrfIrr output, @WMsgLicIrr output
    if @WFlgLicCrfIrr = 1
      if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
        Set @PMsg = @PMsg + @WMsgLicIrr

    -- ALvara de funcionamento
    Exec PR_AnalisaLicencaCliente @PCodOpe, 'ALVARA',  @PCodCli, @WFlgAlvFunIrr output, @WMsgLicIrr output
    if @WFlgAlvFunIrr = 1
      if DATALENGTH(@PMsg) > 0 Set @PMsg = @Pmsg + ';'
        Set @PMsg = @PMsg + @WMsgLicIrr


    -- verifica se existe pelo menos 1 item que necessita de validação da documentação
    Set @Wpr_FlgBlqCtrLic = 0
    if (@PNumPdv > 0) and
       (@pm_FlgBlqCtrDocClaPrd = 1) and   -- parametro global: Ignora bloqueio controle de documentação por classificação de produto
       not Exists(Select 1
                    From PDVIT it
                         Inner join PRODU pr on pr.Codigo = it.Cod_Produto		 
                         Left  Join CLASS c1 on Substring(pr.Cod_Classif,1,2) = c1.Codigo
                         Left  Join CLASS c2 on Substring(pr.Cod_Classif,1,4) = c2.Codigo
                         Left  Join CLASS c3 on Substring(pr.Cod_Classif,1,7) = c3.Codigo
                   Where it.Cod_Estabe = @PCodEstabe
                     and it.Cod_Pedido = @PNumPdv
                     and it.Qtd_Pedido > 0
                     and IsNull(c1.Flg_BlqCtrDocClaPrd,0) = 0
                     and IsNull(c2.Flg_BlqCtrDocClaPrd,0) = 0
                     and IsNull(c3.Flg_BlqCtrDocClaPrd,0) = 0)
          Set @Wpr_FlgBlqCtrLic = 1  -- ignora bloqueio de controle de documentacao

/*
    Set @Wpr_FlgBlqCtrLic = 0
    if @PNumPdv > 0
	  begin
        set @Wpr_FlgBlqCtrLic = 1
        DECLARE Table_Cr CURSOR Local Fast_Forward For
          Select FlgBlqCtrDocClaPrd = Case 
                                        When (pm.FlgBlqCtrDocClaPrd = 1) And (Select cl.Flg_BlqCtrDocClaPrd From CLASS cl Where cl.codigo =  Left(pd.cod_Classif, 2) And  cl.Flg_BlqCtrDocClaPrd = 1) = 1 Then 1 
                                        When (pm.FlgBlqCtrDocClaPrd = 1) And (Select cl.Flg_BlqCtrDocClaPrd From CLASS cl Where cl.codigo =  Left(pd.cod_Classif, 4) And  cl.Flg_BlqCtrDocClaPrd = 1) = 1 Then 1 
                                        When (pm.FlgBlqCtrDocClaPrd = 1) And (Select cl.Flg_BlqCtrDocClaPrd From CLASS cl Where cl.codigo =  Left(pd.cod_Classif, 7) And  cl.Flg_BlqCtrDocClaPrd = 1) = 1 Then 1 
                                        Else 0
                                      End
          From PDVIT it
                Inner join PARAM pm on pm.Cod_Estabe = it.Cod_Estabe
	  	        Inner join PRODU pd on pd.Codigo = it.Cod_Produto		 
          Where it.Cod_Estabe = @PCodEstabe
	        and it.Cod_Pedido = @PNumPdv
        OPEN Table_Cr
        FETCH NEXT FROM Table_Cr INTO @WFlgBlqCtrDocClaPrd
        WHILE @@FETCH_STATUS = 0
        BEGIN
	      if @WFlgBlqCtrDocClaPrd = 0
	        set @Wpr_FlgBlqCtrLic = 0   
	      FETCH NEXT FROM Table_Cr INTO @WFlgBlqCtrDocClaPrd
        END
        CLOSE Table_Cr
        DEALLOCATE Table_Cr 
 	  End
*/

    if (@cl_Flg_NaoBlqDocPdv = 0) and (@Wpr_FlgBlqCtrLic = 0) -- nunca bloqueia pedido por documentação
      if @pm_FlgCtrBlqPdvLicCli = 1  -- valida documentação
        begin
          if (@WFlgLicSauIrr = 1) or (@WFlgLicAnvIrr = 1) or (@WFlgLicCrfIrr = 1) or (@WFlgAlvFunIrr = 1)
            Set @PStaLic = 'B'
        end
      else
        begin
          if (@WFlgLicAnvIrr = 1) or (@WFlgLicCrfIrr = 1) or (@WFlgAlvFunIrr = 1)
            begin
              if 2 > @PSta
                Set @PSta = 2
            end
        end

  END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_RateiaDescontosPDV]
@PCodEstabe int,
@PNumPdv int

AS

SET NOCOUNT ON 
SET ANSI_WARNINGS OFF

if Exists(Select 1
            From PDVCB cb
                 Inner Join (Select Cod_Estabe, Cod_Pedido, 
                                    C_DscIte = sum(IsNull(Vlr_DscRat,0))
                               From PDVIT
                              Where Cod_Estabe = @PCodEstabe
                                and Cod_Pedido = @PNumPdv
                              Group by Cod_Estabe, Cod_Pedido
                             ) it on cb.Cod_Estabe = it.Cod_Estabe and cb.Numero = it.Cod_Pedido
           Where cb.Cod_Estabe = @PCodEstabe
             and cb.Numero = @PNumPdv
             and IsNull(cb.C_VlrDesconto,0) <> it.C_DscIte
         ) or
   Exists(Select 1
            From PDVIT 
           Where Cod_Estabe = @PCodEstabe
             and Cod_Pedido = @PNumPdv
            And IsNull(Vlr_DscRat,0) > 0
            And Right(Cast(IsNull(Vlr_DscRat,0) as numeric(18,8)),6) > 0
         )
  begin
  BEGIN TRANSACTION

  Declare @cb_VlrDscCom numeric(18,4),
          @cb_VlrItens numeric(18,4),
          @cb_TotItens int,

          @it_CodPrd int,
          @it_CodLot varchar(20),
          @it_TipSai varchar(1),
          @it_QtdPrd int,
          @it_QtdBon int,
          @it_PerDsc numeric(18,4),
          @it_FlgBlqDsc bit,
          @it_VlrTotIte numeric(18,4),

          @WFlgDsc bit,
          @WDscIte numeric(18,4),
          @WAccDsc numeric(18,4),
          @WAccIte int

  Select @cb_VlrDscCom = IsNull(cb.C_VlrDesconto,0)
    From PDVCB cb
   Where cb.Cod_Estabe = @PCodEstabe
     And cb.Numero = @PNumPdv
	 
  Update PDVIT
     Set Vlr_DscRat = 0
   Where Cod_Estabe = @PCodEstabe
     And Cod_Pedido = @PNumPdv

  -- somente itens com PDVIT.Desconto = 0 serao considerados no rateamento de descontos, caso contrario rateia entre todos os itens
  Set @WFlgDsc = 0
  if Exists(Select 1 From PDVIT Where Cod_Estabe = @PCodEstabe and Cod_Pedido = @PNumPdv And Qtd_Pedido > 0 And IsNull(Desconto,0) = 0)
    begin
      Set @WFlgDsc = 1
      Set @cb_TotItens = (Select count(*) From PDVIT Where Cod_Estabe = @PCodEstabe and Cod_Pedido = @PNumPdv And Qtd_Pedido > 0 And IsNull(Desconto,0) = 0)
      Set @cb_VlrItens = (Select sum(C_PrcTotal) From PDVIT Where Cod_Estabe = @PCodEstabe and Cod_Pedido = @PNumPdv And Qtd_Pedido > 0 And IsNull(Desconto,0) = 0)

      if @cb_VlrDscCom > @cb_VlrItens
        Set @WFlgDsc = 0
    end

  if @WFlgDsc = 0
    begin
      Set @cb_TotItens = (Select count(*) From PDVIT Where Cod_Estabe = @PCodEstabe and Cod_Pedido = @PNumPdv And Qtd_Pedido > 0)
      Set @cb_VlrItens = (Select sum(C_PrcTotal) From PDVIT Where Cod_Estabe = @PCodEstabe and Cod_Pedido = @PNumPdv And Qtd_Pedido > 0)
    end

  Set @WAccDsc = 0
  Set @WAccIte = 0

  Declare PDVIT_Cr Cursor Local Fast_Forward For 

    Select Cod_Produto, Cod_Lote, Tip_Sai, Qtd_Pedido, Qtd_Bonificacao, Per_Desconto, 
           IsNull(Desconto,0), C_PrcTotal
      From PDVIT 
     Where Cod_Estabe = @PCodEstabe and Cod_Pedido = @PNumPdv
       And Qtd_Pedido > 0
     Order By C_PrcTotal

  Open PDVIT_Cr
  Fetch Next From PDVIT_Cr Into @it_CodPrd, @it_CodLot, @it_TipSai, @it_QtdPrd, @it_QtdBon, @it_PerDsc, 
                                @it_FlgBlqDsc, @it_VlrTotIte
  While @@FETCH_STATUS = 0
    begin
      Set @WDscIte = 0

      -- rateia descontos
      if (@WFlgDsc = 0) or (@it_FlgBlqDsc = 0)
        begin
          Set @WAccIte = @WAccIte + 1
          Set @WDscIte = Round(@cb_VlrDscCom*@it_VlrTotIte/@cb_VlrItens,2)
          
          if (@WAccDsc + @WDscIte) > @cb_VlrDscCom 
            Set @WDscIte = @cb_VlrDscCom - @WAccDsc

          -- assegura fechamento de valores no ultimo item
          if @WAccIte = @cb_TotItens 
            begin
              Set @WDscIte = @cb_VlrDscCom - @WAccDsc
            end
        end

      Update PDVIT
         Set Vlr_DscRat = @WDscIte
       Where Cod_Estabe = @PCodEstabe
         And Cod_Pedido = @PNumPdv
         And Cod_Produto = @it_CodPrd
         And Cod_Lote = @it_CodLot
         And Tip_Sai = @it_TipSai
        
      -- acumula valores 
      Set @WAccDsc = @WAccDsc + @WDscIte

      EXEC PR_CalcTributPdvit @PCodEstabe, @PNumPdv, @it_CodPrd, @it_CodLot, @it_TipSai 
      if @@error <> 0
        begin
          if @@trancount > 0
            Rollback Transaction
          Return
        end

      Fetch Next From PDVIT_Cr Into @it_CodPrd, @it_CodLot, @it_TipSai, @it_QtdPrd, @it_QtdBon, @it_PerDsc,
                                    @it_FlgBlqDsc, @it_VlrTotIte
    end
  Close PDVIT_Cr
  Deallocate PDVIT_Cr

  if @@trancount > 0
    COMMIT TRANSACTION
  end    
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_RateiaDespesasPDV] 
@PCodEstabe int,
@PNumPdv int

AS

SET NOCOUNT ON

if Exists(Select cb.Cod_Estabe, cb.Numero, cb.Vlr_Despes, cb.Vlr_Frete, it.C_DspIte
            From PDVCB cb
                 Inner Join (Select Cod_Estabe, Cod_Pedido, C_DspIte = sum(Vlr_Despes)
                               From PDVIT
                              Where Cod_Estabe = @PCodEstabe
                                and Cod_Pedido = @PNumPdv
                              Group by Cod_Estabe, Cod_Pedido) it on cb.Cod_Estabe = it.Cod_Estabe and cb.Numero = it.Cod_Pedido
           Where cb.Cod_Estabe = @PCodEstabe
             and cb.Numero = @PNumPdv
             and (IsNull(cb.Vlr_Despes,0)+IsNull(cb.Vlr_Frete,0)) <> it.C_DspIte) or
   Exists(Select 1
            From PDVIT
           Where Cod_Estabe = @PCodEstabe
             and Cod_Pedido = @PNumPdv
             And ( (IsNull(Vlr_Despes,0) > 0) and (Right(Cast(IsNull(Vlr_Despes,0) as numeric(18,8)),6) > 0) ) 
         )
  begin
    BEGIN TRANSACTION
  
    Declare @cb_TotItens int,
            @cb_VlrItens numeric(18,4),
            @cb_ValDsp numeric(18,4),
            @it_CodPrd int,
            @it_CodLot varchar(20),
            @it_TipSai varchar(1),
            @it_VlrIcmNor numeric(18,4),
            @it_VlrTotIte numeric(18,4),

            @WDspIte numeric(18,4),

            @WAccDsp numeric(18,4),
            @WAccIte int,
            @WFlgIcm bit
  
    Select @cb_ValDsp = Round(Isnull(Vlr_Despes,0),2)+Round(Isnull(Vlr_Frete,0),2)
      From PDVCB 
     Where Cod_Estabe = @PCodEstabe 
       and Numero = @PNumPdv

    -- somente itens com icms normal(se houver) serao considerados no rateamento de despesas, caso contrario rateia entre todos os itens
    if Exists(Select 1 From PDVIT Where Cod_Estabe = @PCodEstabe and Cod_Pedido = @PNumPdv And Qtd_Pedido > 0 And Vlr_IcmsNor > 0)
      begin
        Set @WFlgIcm = 1
        Set @cb_TotItens = (Select count(*) From PDVIT Where Cod_Estabe = @PCodEstabe and Cod_Pedido = @PNumPdv And Qtd_Pedido > 0 And Vlr_IcmsNor > 0)
        Set @cb_VlrItens = (Select sum(C_PrcTotal) From PDVIT Where Cod_Estabe = @PCodEstabe and Cod_Pedido = @PNumPdv And Qtd_Pedido > 0 And Vlr_IcmsNor > 0)
      end
    else
      begin
        Set @WFlgIcm = 0
        Set @cb_TotItens = (Select count(*) From PDVIT Where Cod_Estabe = @PCodEstabe and Cod_Pedido = @PNumPdv And Qtd_Pedido > 0)
        Set @cb_VlrItens = (Select sum(C_PrcTotal) From PDVIT Where Cod_Estabe = @PCodEstabe and Cod_Pedido = @PNumPdv And Qtd_Pedido > 0)
      end

    Update PDVIT
       Set Vlr_Despes = 0
     Where Cod_Estabe = @PCodEstabe
       and Cod_Pedido = @PNumPdv

    Set @WAccDsp = 0
    Set @WAccIte = 0

    Declare PDVIT_Cr Cursor Local Fast_Forward For 
   
      Select Cod_Produto, Cod_Lote, Tip_Sai, Vlr_IcmsNor, C_PrcTotal
        From PDVIT 
       Where Cod_Estabe = @PCodEstabe 
         And Cod_Pedido = @PNumPdv
         And Qtd_Pedido > 0
       Order By C_PrcTotal
   
    Open PDVIT_Cr
    Fetch Next From PDVIT_Cr Into @it_CodPrd, @it_CodLot, @it_TipSai, @it_VlrIcmNor, @it_VlrTotIte
    While @@FETCH_STATUS = 0
      begin
        if (@WFlgIcm = 0) or (@it_VlrIcmNor > 0)
          Set @WAccIte = @WAccIte + 1
   
        Set @WDspIte = 0
   
        if Round(@it_VlrTotIte*100,2) > 0 
          begin
            -- rateia despesas
            if (@WFlgIcm = 0) or (@it_VlrIcmNor > 0)
              begin
                Set @WDspIte = Round(@cb_ValDsp*@it_VlrTotIte/@cb_VlrItens,2)
                
                if (@WAccDsp + @WDspIte) > @cb_ValDsp 
                  Set @WDspIte = @cb_ValDsp - @WAccDsp
              end
          end  -- if Round(@it_VlrTotIte*100,2) > 0 
   
        -- assegura fechamento de valores no ultimo item
        if (@WFlgIcm = 0) or (@it_VlrIcmNor > 0)
          if @WAccIte = @cb_TotItens 
            begin
              Set @WDspIte = @cb_ValDsp - @WAccDsp
            end
   
        Update PDVIT
           Set Vlr_Despes = @WDspIte
         Where Cod_Estabe = @PCodEstabe
           And Cod_Pedido = @PNumPdv
           And Cod_Produto = @it_CodPrd
           And Cod_Lote = @it_CodLot
           And Tip_Sai = @it_TipSai
          
        -- acumula valores 
        Set @WAccDsp = @WAccDsp + @WDspIte
   
        EXEC PR_CalcTributPdvit @PCodEstabe, @PNumPdv, @it_CodPrd, @it_CodLot, @it_TipSai
        if @@error <> 0
          begin
            if @@trancount > 0
              Rollback Transaction
            Return
          end
   
        Fetch Next From PDVIT_Cr Into @it_CodPrd, @it_CodLot, @it_TipSai, 
                                      @it_VlrIcmNor, @it_VlrTotIte
      end
    Close PDVIT_Cr
    Deallocate PDVIT_Cr
   
    if @@trancount > 0
      COMMIT TRANSACTION
  end -- if Exists(
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_AtualizaCabecPDV]
@CodEstabe int,
@NumPdv int

AS

SET NOCOUNT ON

Begin Transaction

Declare @cb_VlrBasDsc numeric(18,4),
        @cb_VlrDscCom numeric(18,4),
        @cb_VlrRepDsc numeric(18,4),
        @cb_QtdItePrm int,
        @cb_VlrBasPar numeric(18,4)


-- verifica se necessita ratear despesas...
Exec PR_RateiaDespesasPDV @CodEstabe, @NumPdv
if @@error <> 0
  begin
    if @@trancount > 0
      Rollback Transaction
    Return
  end


-- verifica se necessita ratear descontos...
Set @cb_VlrBasDsc = 0
Set @cb_VlrDscCom = 0
Set @cb_VlrRepDsc = 0
Set @cb_QtdItePrm = 0
Set @cb_VlrBasPar = 0

Set @cb_VlrBasDsc = Isnull(Round((Select Sum(C_PrcTotal)  from PDVIT Where Qtd_Pedido > 0 and Cod_Estabe = @CodEstabe and IsNull(Desconto,0) = 0      and Cod_Pedido = @NumPdv),2),0)
Set @cb_VlrRepDsc = Isnull(Round((Select Sum(Vlr_RepIcms) from PDVIT Where Qtd_Pedido > 0 and Cod_Estabe = @CodEstabe and IsNull(Desconto,0) = 0      and Cod_Pedido = @NumPdv),2),0)
Set @cb_VlrBasPar = Isnull(Round((Select Sum(C_PrcTotal)  from PDVIT Where Qtd_Pedido > 0 and Cod_Estabe = @CodEstabe and IsNull(Flg_BlqInfPar,0) = 0 and Cod_Pedido = @NumPdv),2),0)

Set @cb_QtdItePrm = Isnull((Select Count(*) from PDVIT 
                             Where Qtd_Pedido > 0 and Cod_Estabe = @CodEstabe and Cod_Pedido = @NumPdv
                               And (Qtd_Bonificacao > 0 or Per_Desconto > 0)
                               -- aqui deveia considerer descontos embutidos no preço, etc....
                           ),0)

Update PDVCB
   Set Vlr_BasDscCom = @cb_VlrBasDsc,
       --C_VlrDesconto = Round(IsNull(Per_DescontoCom,0)/100 * (IsNull(@cb_VlrBasDsc,0)-IsNull(@cb_VlrRepDsc,0)),2), calculado na trigger
       Vlr_BasPar    = @cb_VlrBasPar,
       Qtd_ItensProm = @cb_QtdItePrm
 Where Cod_Estabe = @CodEstabe 
   and Numero = @NumPdv

Exec PR_RateiaDescontosPDV @CodEstabe, @NumPDv
if @@error <> 0
  begin
    if @@trancount > 0
      Rollback Transaction
    Return
  end


Update cb
   Set cb.Qtd_Itens     = IsNull(it.S_QtdIte,0)
     , cb.Vlr_LiqItens  = IsNull(it.S_VlrLiqIte,0)
     , cb.C_VlrDesconto = IsNull(it.S_VlrDscRat,0)

     , cb.Vlr_RepIcms   = IsNull(S_VlrRepIcm,0)
     , cb.Vlr_SubsTrib  = IsNull(S_VlrSubTri,0)
     , cb.Vlr_SbtRes    = IsNull(S_VlrSbtRes,0)
     , cb.Vlr_DscTri    = IsNull(S_VlrDscTri,0)
     , cb.Vlr_IcmsDeson = IsNull(S_VlrIcmDes,0)
     , cb.Vlr_DscBon    = IsNull(S_VlrDscBon,0)
     , cb.Vlr_Despes    = IsNull(S_VlrDespes,0)
     , cb.Vlr_DspExt    = IsNull(S_VlrDspExt,0)
     , cb.Vlr_Ipi       = IsNull(S_VlrIpi,0)
     , cb.Vlr_Verba     = IsNull(S_VlrVerba,0)
     , cb.Per_Rnt       = IsNull(S_PerRnt,0)
	 , cb.Vlr_BasIrf    = IsNull(S_VlrBasIrf,0)
	 , cb.Vlr_Irf       = IsNull(S_VlrIrf,0) 
  From PDVCB cb
       Left Join (Select Cod_Estabe, Cod_Pedido
                       , S_QtdIte    = count(*)
                       , S_VlrLiqIte = Round(Sum(IsNull(C_PrcTotal,0)),2)
                       , S_VlrDscRat = Round(Sum(IsNull(Vlr_DscRat,0)),2)

                       , S_VlrRepIcm = Round(Sum(IsNull(Vlr_RepIcms,0)),2)
                       , S_VlrSubTri = Round(Sum(IsNull(Vlr_SubsTrib,0)),2)
                       , S_VlrSbtRes = Round(Sum(IsNull(Vlr_SbtRes,0)),2)
                       , S_VlrDscTri = Round(Sum(IsNull(Vlr_DscTri,0)),2)
                       , S_VlrIcmDes = Round(Sum(IsNull(Vlr_IcmsDeson,0)),2)
                       , S_VlrDscBon = Round(Sum(IsNull(Vlr_Bonificacao,0)),2)
                       , S_VlrDespes = Round(Sum(IsNull(Vlr_Despes,0)),2)
                       , S_VlrDspExt = Round(Sum(IsNull(Vlr_DspExt,0)),2)
                       , S_VlrIpi    = Round(Sum(IsNull(Vlr_Ipi,0)),2)
                       , S_VlrVerba  = Round(Sum(IsNull(Vlr_Verba,0)),2)
                       , S_PerRnt    = Case 
                                         When Exists(Select 1 From PDVIT Where Cod_Estabe = @CodEstabe and Cod_Pedido = @NumPdv and Tip_BasRnt = 'M') -- MarkUp 
                                           then Case 
                                                  When (Select sum(Prc_BasRnt*(Qtd_Pedido+Qtd_Bonificacao))) > 0 
                                                    then (Select ((sum(Vlr_BasTri+Vlr_SbtRes)/sum(Prc_BasRnt*(Qtd_Pedido+Qtd_Bonificacao))-1)*100))
                                                  Else 0
                                                End
                                         When (Select sum(C_PrcTotal)) > 0 then (Select Sum(Per_Rnt*C_PrcTotal)/sum(C_PrcTotal))
                                         Else -100.0
                                        End
					   , S_VlrBasIrf        = Round(Sum(IsNull(Vlr_BasIrf,0)),2)
					   , S_VlrIrf           = Round(Sum(IsNull(Vlr_Irf,0)),2) 
                    From PDVIT
                   Where Cod_Estabe = @CodEstabe 
                     And Cod_Pedido = @NumPdv
                     And Qtd_Pedido > 0
                   Group by Cod_Estabe, Cod_Pedido
                 ) it on cb.Cod_Estabe = it.Cod_Estabe and cb.Numero = it.Cod_Pedido
 Where cb.Cod_Estabe = @CodEstabe 
   And cb.Numero = @NumPdv

Update PDVCB
   Set C_VlrPedido = dbo.FN_ValPdv(Cod_Estabe,Numero)
 Where Cod_Estabe = @CodEstabe 
   and Numero = @NumPdv

Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CalculaVencPDV]
@CodEstabe int,
@CodPed int

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = cast(GetDate() as date)

-- normaliza campos 
if (Select IsNull(op.Flg_LanFin,0)
      From PDVCB pv 
           Inner Join TPOPE op on (pv.Tip_Faturamento = op.Cod_Ope)
     Where pv.Cod_Estabe = @CodEstabe 
       And pv.Numero = @CodPed) = 0
  begin    
    Update PDVCB
       Set Tip_Vencimento = 'A'
     Where Cod_Estabe = @CodEstabe
       And Numero = @CodPed
    
    Delete From PDVDP
     Where Cod_Estabe = @CodEstabe
       And Cod_Pedido = @CodPed  
  end

Update PDVCB
   Set Flg_CnvDscIteDscGlb = Case
                               When Id_PolCom > 0 then 0
                               Else (Select IsNull(FlgCnvDscIteDscCom,0) From PARAM Where Cod_Estabe = @CodEstabe)  
                             End,
       Tip_DscPdv = Case 
	                  When Id_PolCom > 0 then 'C'
	 				 Else Tip_DscPdv
                    End
 Where Cod_Estabe = @CodEstabe
  And Numero = @CodPed

--Update PDVCB  
--  Set Flg_CnvDscIteDscGlb = (Select IsNull(FlgCnvDscIteDscCom,0) From PARAM Where Cod_Estabe = @CodEstabe)  
--Where Cod_Estabe = @CodEstabe
--And Numero = @CodPed  

Update PDVCB  
   Set Flg_CnvDscIteDscGlb = 1
 Where Cod_Estabe = @CodEstabe
   And Numero = @CodPed  
   And Tip_DscPdv = 'F'
   And IsNull(Flg_CnvDscIteDscGlb,0) = 0


Delete From PDVIT 
 Where Cod_Estabe = @CodEstabe 
   And Cod_Pedido = @CodPed 
   And Qtd_Pedido > 0 
   And Prc_Unitario = 0.00


-- valida tabela de prazos se for o caso
if ((Select Tip_Vencimento From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @CodPed) = 'T') and
   (not Exists(Select pz.Cod_Prz 
                 From PRZCB pz Inner Join PDVCB cb on cb.Cod_Prz = pz.Cod_Prz 
                Where cb.Cod_Estabe = @CodEstabe
                  And cb.Numero = @CodPed
                  And pz.Qtd_PrzMed > 0))
  begin
    RAISERROR('Tabela de prazos inválida',16,1)
	Return
  end
else
BEGIN
Begin Transaction

-- bloqueia pedido
Update PDVCB
   Set Qtd_Itens = Qtd_Itens + 0,
       Flg_Calc = 1
 Where Cod_Estabe = @CodEstabe
   And Numero = @CodPed

if (Select IsNull(C_VlrPedido,0) From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @CodPed) = 0
  Update PDVCB
     Set Vlr_Despes = Vlr_Despes + 0
   Where Cod_Estabe = @CodEstabe
     And Numero = @CodPed

-- variaveis de trabalho
Declare @WtipPrz varchar(1),
        @WValDup numeric(18,4),
        @WValSubTri numeric(18,4),
        @WValSbtRes numeric(18,4),
        @WValBasPed numeric(18,4),
        @WValAcc numeric(18,4),
        @WFlgApr bit,
        @WRecalcula bit,
        @WDatVct smalldatetime,
        @WDatVctAnt smalldatetime,
        @WQtdPrzAnt int,

        @cl_DiaSemVctTit tinyint,
        @cl_FlgBlqDupExtSbt bit,
        @cl_FlgBlqIncImpPriDup bit,

        @ag_VlrDspBolBan numeric(18,4),
        @ag_PerTaxAdm numeric(18,4),
        @ag_CodAplTaxAdm varchar(1),

        @cr_CodPrd int,
        @cr_CodLot varchar(20),
        @cr_TipSai varchar(1),
        @cr_CVlrLiq numeric(18,4),
        @cr_CPrcTot numeric(18,4),
        @cr_PerDscVis numeric(18,4),
        @cr_QtdPrzMax int,
        @cr_PerDscPrz numeric(18,4),
        @cr_FlgBlqDsc bit, 

        @cr_QtdPrz int,
        @cr_VlrItens numeric(18,4),
        @cr_VlrDscFin numeric(18,4),
        @cr_VlrDscCom numeric(18,4),

        @WSomat numeric(18,4),
        @WValLiqAcc numeric(18,4),
        @WValBruAcc numeric(18,4),
        @WValDscAcc numeric(18,4),
        @WValIte numeric(18,4),
        @WValBru numeric(18,4),
        @WValDscFin numeric(18,4),
        @WValDscCom numeric(18,4),
        @WValTotLiq numeric(18,4),
        @WValDespes numeric(18,4),
        @WValTotDspBolBan  numeric(18,4),
        @WQtdPrz int,
        @WPerDsc numeric(18,4),
        @WConPar tinyint,
        @WFlgIncDupSbt bit    -- indica se cria nova parcela p/ sbt

-- variaveis que serao gravadas em PDVCB
Declare @PQtdPar int,
        @PQtdInt int,
        @PQtdPrzMed numeric(18,4),
        @PFlgVlrFin bit ,
        @PPerDscCom numeric(18,4),
        @PPerDscFin numeric(18,4),
        @PTipDsc varchar(1),
		@PPerDscComMemo numeric(18,4)

-- variaveis para guardar campos de tabelas
Declare @cb_TipVct varchar(1),
        @cb_IdPolCom int,
        @cb_VlrLiqIte numeric(18,4),
        @cb_VlrRepIcm numeric(18,4),
        @cb_VlrSubTri numeric(18,4),
        @cb_VlrSbtRes numeric(18,4),
        @cb_VlrDespes numeric(18,4),
        @cb_VlrDscTri numeric(18,4),
        @cb_BasDscCom numeric(18,4),
        @cb_CVlrPed numeric(18,4),
        @cb_DatPed smalldatetime,
        @cb_CodPrz int,
        @cb_FlgCnvDscIteDscGlb bit,
        @op_FlgLanFin bit,
        @op_VlrMinDup numeric(18,4),
        @pm_FlgDebBlqBanVrbVdr bit,
        @pm_FlgImpPriDup bit,
        @pm_QtdPrzMaxImpSbt int,
        @pm_QtdDiaDupVis int,
        @pm_QtdDiaPrgDupApr int

Select @WTipPrz = Substring(cb.Cod_OrigemPdv,2,1),
       @cb_CVlrPed = Round(IsNull(cb.C_VlrPedido,0),2),
       @cb_TipVct = cb.Tip_Vencimento,
       @cb_IdPolCom = IsNull(cb.Id_PolCom,0),
       @cb_VlrLiqIte = IsNull(cb.Vlr_LiqItens,0),
       @cb_VlrRepIcm = IsNull(cb.Vlr_RepIcms,0),
       @cb_VlrSubTri = Round(IsNull(cb.Vlr_SubsTrib,0),2),
       @cb_VlrSbtRes = Round(IsNull(cb.Vlr_SbtRes,0),2),
       @cb_VlrDespes = IsNull(cb.Vlr_Despes,0),
       @cb_VlrDscTri = IsNull(cb.Vlr_DscTri,0),
       @cb_BasDscCom = IsNull(cb.Vlr_BasDscCom,0),
       @cb_DatPed = cb.Dat_Pedido,
       @cb_CodPrz = IsNull(cb.Cod_Prz,0),
       @cb_FlgCnvDscIteDscGlb = IsNull(Flg_CnvDscIteDscGlb,0),

       @PPerDscCom = isnull(cb.Per_DescontoCom,0),
       @PPerDscFin = isnull(cb.Per_DescontoFin,0),
       @PQtdPar = IsNull(cb.Qtd_Parcela,0),
       @PQtdInt = IsNull(cb.Qtd_Intervalo,0),
       @PQtdPrzMed = IsNull(cb.Qtd_PrzMed,0),
       @PTipDsc = cb.Tip_DscPdv,

       @cl_DiaSemVctTit = IsNull(cl.Dia_SemVctTitEsp,0),
       @cl_FlgBlqDupExtSbt = IsNull(cl.Flg_BlqDupExtSbt,0),
       @cl_FlgBlqIncImpPriDup = IsNull(en.Flg_BlqIncSbtPriDup,0),

       @ag_VlrDspBolBan = case 
                            When (Isnull(ag.Flg_CobDspBolBanNtf,0) = 1) and (Tipo = 'BC') and
                                 (IsNull(cl.Flg_BlqCobTxaBan,0) = 0) then Round(Isnull(ag.Vlr_DspBolBan,0),2)
                            else 0
                          end,
       @ag_PerTaxAdm = IsNull(ag.Per_TaxAdm,0),
       @ag_CodAplTaxAdm = IsNull(Cod_AplTaxAdm,''),

       @op_FlgLanFin = IsNull(Flg_LanFin,0),
       @op_VlrMinDup = IsNull(Vlr_MinDup,0)

  From PDVCB cb 
       Left Join CLIEN cl on cb.Cod_Cliente = cl.Codigo 
       Left Join ENXES en on cb.Cod_Estabe = en.Cod_Estabe and cl.Cgc_Cpf = en.Num_CgcCpf and cl.Codigo = en.Cod_Client
       Left Join AGCOB ag on cb.Cod_Agente = ag.Codigo
       Left Join TPOPE op on cb.Tip_Faturamento = op.Cod_Ope
 Where cb.Cod_Estabe = @CodEstabe
   And cb.Numero = @CodPed

Select @pm_FlgImpPriDup = IsNull(FlgIncImpPriDup,0),
       @pm_QtdPrzMaxImpSbt = Case
                               When (IsNull(FlgIncImpPriDup,0) = 1) and (@cl_FlgBlqDupExtSbt = 0) Then IsNull(QtdPrzMaxImpSbt,0)
                               Else 0
                             End,
       @pm_QtdDiaDupVis = IsNull(QtdDiaDupVis,0),
       @pm_QtdDiaPrgDupApr = Isnull(QtdDiaPrgDupApr,0),
       @pm_FlgDebBlqBanVrbVdr = IsNull(FlgDebBlqBanVrbVdr,0)
  From PARAM
 Where Cod_Estabe = @CodEstabe



if (@PQtdInt = 0) and 
   Exists(Select 1 From PDVDP Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Num_SeqPar = 1) and
   Exists(Select 1 From PDVDP Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Num_SeqPar = 2) 
  Select @PQtdInt = Cast(((Select Dat_Vencim From PDVDP Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Num_SeqPar = 2) -
                          (Select Dat_Vencim From PDVDP Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Num_SeqPar = 1)) as int)

if (@PQtdPar = 0) and 
   Exists(Select 1 From PDVDP Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed) 
  Select @PQtdPar = count(*) From PDVDP Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed

/*
  -- calcula despesa ref. taxa administrativa
  Set @WValDespes = 0.00     
  if @ag_PerTaxAdm > 0
    begin
      if @ag_CodAplTaxAdm = 'P' -- margem (participação)
        Set @WValDespes = Round(@cb_VlrLiqIte/(1-@ag_PerTaxAdm/100),2)-Round(@cb_VlrLiqIte,2)
      if @ag_CodAplTaxAdm = 'A'  -- mark-up (acrescimo)
        Set @WValDespes = Round(@cb_VlrLiqIte*@ag_PerTaxAdm/100,2)     
    end

  -- calcula despesa boleto bancario a cobrar na nota fiscal
  Set @WValTotDspBolBan = 0
  if @op_FlgLanFin = 1
    begin
      Set @WValTotDspBolBan = Round(Isnull(@ag_VlrDspBolBan,0) * @PQtdPar,2)
      Set @WValDespes = @WValDespes + @WValTotDspBolBan
    end

  -- debita taxa boleto para vendedor
  if @TipNfs = 'V'
    begin
      -- taxa boleto
      if @pm_FlgDebBlqBanVrbVdr = 1
        begin
          Set @WValDespes = @WValDespes - @WValTotDspBolBan    -- isenta cliente
        end
    end

*/




if (@pm_FlgImpPriDup = 1) and (@cl_FlgBlqIncImpPriDup = 1)
  Set @pm_FlgImpPriDup = 0


-- Manter Desconto Comercial caso tenha algum valor
if @PPerDscCom > 0
  Set  @PPerDscComMemo = @PPerDscCom

-- garante que nao ha desconto financeiro em operacoes que nao geram lancamentos financeiros
if @op_FlgLanFin = 0
  begin
    Set @PPerDscFin = 0
    Set @PTipDsc = 'C' 
  end

-- sinalizador para recalcular o pedido
Set @WRecalcula = 0

-- ver se inclui total imposto na 1a. duplic
Set @WValBasPed = @cb_CVlrPed
if @pm_FlgImpPriDup = 1
  Set @WValBasPed = @WValBasPed - @cb_VlrSubTri - @cb_VlrSbtRes

-- Prazo linear com conversao de desconto item p/ global
if (@WTipPrz = 'L') and (@cb_FlgCnvDscIteDscGlb = 1)  and (@cb_IdPolCom = 0) and
   (Exists(Select 1 From PDVIT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed and Qtd_Pedido > 0 and ((Per_Desconto > 0) or (Per_Descon > 0))))
  begin
    Set @PPerDscCom = 0
    if @cb_IdPolCom = 0
      Set @PPerDscFin = 0
    -- tipo de desconto financeiro ou comercial
    if @PTipDsc <> 'F'
      Set @PTipDsc  = 'C'

  -- zera desc. cabecalho se houve alteracoes devido a calc. anterior
    Update PDVCB
      Set Per_DescontoCom = 0,
          Per_DescontoFin = 0
      Where Cod_Estabe = @CodEstabe
      And Numero = @CodPed

  -- Normaliza descontos nos itens e recalcula tributos
    Update PDVIT
      Set Per_Descon = Per_Desconto,
          Per_Desconto = 0
      Where Cod_Estabe = @CodEstabe
      And Cod_Pedido = @CodPed 
      And Qtd_Pedido > 0
      And Per_Desconto > 0

    Declare PDVIT_Cr Cursor Local Fast_Forward For
      Select Cod_Produto, Cod_Lote, Tip_Sai
        From PDVIT 
        Where Cod_Estabe = @CodEstabe
        And Cod_Pedido = @CodPed 
        And Qtd_Pedido > 0  
        And Per_Descon > 0
        
    Open PDVIT_Cr
    Fetch Next From PDVIT_Cr Into @cr_CodPrd, @cr_CodLot, @cr_TipSai
    While @@FETCH_STATUS = 0
      begin
        EXEC PR_CalcTributPdvit @CodEstabe, @CodPed, @cr_CodPrd, @cr_CodLot, @cr_TipSai
        Fetch Next From PDVIT_Cr Into @cr_CodPrd, @cr_CodLot, @cr_TipSai
      end
    Close PDVIT_Cr
    Deallocate PDVIT_Cr

    Set @WRecalcula = 0

    -- Desconto Financeiro ou comercial
    Set @WValDscAcc = Round((Select sum(Round(C_PrcTotal,2)*Per_Descon/100) From PDVIT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed and Qtd_Pedido > 0 and Per_Descon > 0),2)
    if @WValDscAcc > 0
      begin
        -- tem que recalcular valor do pedido devido a alteracao no desconto
        Set @WRecalcula = 1
        if @PTipDsc = 'F'
          begin
--12/04/2011            Set @WValLiqAcc = (Select sum(Round(C_VlrLiquido,2)) From PDVIT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed and Qtd_Pedido > 0)
            Set @WValLiqAcc = (Select sum(Round(C_PrcTotal,2)) From PDVIT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed and Qtd_Pedido > 0 and Desconto = 0)
            if @cb_IdPolCom = 0
              Set @PPerDscFin = @WValDscAcc * 100 /@WValLiqAcc
          end
        else
          begin
            Set @WValBruAcc = (Select sum(Round(C_PrcTotal,2)) From PDVIT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed and Qtd_Pedido > 0 and Desconto = 0)
            Set @PPerDscCom = @WValDscAcc * 100 /@WValBruAcc
          end
      end
  end    -- Prazo linear com conversao de deconto item p/ global
else
  begin
    Set @WRecalcula = 1   -- recalcula tributos  p/ todas as outras situacoes
    if (@WTipPrz = 'L') and ((@cb_VlrSubTri+@cb_VlrSbtRes) > 0) and (@PPerDscFin > 0)
      begin
        Set @WValDscCom = 0
        if @PPerDscCom > 0
          Set @WValDscCom = Round((@cb_BasDscCom-@cb_VlrRepIcm)*@PPerDscCom/100,2)
        Set @WValTotLiq = @cb_VlrLiqIte - @WValDscCom - @cb_VlrRepIcm - @cb_VlrDscTri
         -- calcula novo desc fin
--12/04/2011        Set @PPerDscFin = Round(@WValTotLiq*@PPerDscFin/(@WValTotLiq+@cb_VlrSubTri+@cb_VlrSbtRes),4)
      end
  end

-- Tipo de prazo F-fabricante
if (@WTipPrz = 'F') or (@cb_IdPolCom > 0)
  begin
    if @cb_TipVct <> 'V'
      Set @PQtdPrzMed = 0
    Set @PFlgVlrFin = 0
    Set @PPerDscCom = 0
    if @cb_IdPolCom = 0
      Set @PPerDscFin = 0

    -- tipo de desconto financeiro ou comercial
    if @PTipDsc = 'F'
      Set @PFlgVlrFin = 1
    else
      begin
        Set @PTipDsc  = 'C'
        Set @PFlgVlrFin = 0
      end

-- PRINT comandos abaixo náo estavam comentados
  -- zera desc. cabecalho se houve alteracoes devido a calc. anterior
--    Update PDVCB
--      Set Per_DescontoCom = 0,
--          Per_DescontoFin = 0
--      Where Cod_Estabe = @CodEstabe
--      And Numero = @CodPed

    -- cria tabela temporaria local
    Create Table #PRZAX
     (Qtd_Prz int not null Primary Key,
      Vlr_Itens numeric(18,4) not null,
      Vlr_DscFin numeric(18,4) not null,
      Vlr_DscCom numeric(18,4) not null)

    -- Normaliza desconto dos itens antes de iniciar os calculos
    Update PDVIT
      Set Per_Desconto = Case
                           When @PTipDsc = 'C' and @cb_FlgCnvDscIteDscGlb = 0 and @cb_TipVct = 'V' then Isnull(Per_DscVis,0)
                           When @PTipDsc = 'C' and @cb_FlgCnvDscIteDscGlb = 0 and @cb_TipVct <> 'V' then Isnull(Per_Descon,0)
                           Else 0
                         End
      Where Cod_Estabe = @CodEstabe
      And Cod_Pedido = @CodPed and Qtd_Pedido > 0

    -- inicializa acumuladores
    Set @WSomat = 0
    Set @WValLiqAcc = 0
    Set @WValBruAcc = 0
    Set @WValDscAcc = 0

    Declare PDVIT_Cr Cursor Local Fast_Forward For
      Select Cod_Produto, Cod_Lote, Tip_Sai, 
	         Case 
			   When @pm_FlgImpPriDup = 1 then C_VlrLiquido-IsNull(Vlr_SubsTrib,0)-IsNull(Vlr_SbtRes,0)
			   Else C_VlrLiquido
             End, 
			 C_PrcTotal, Per_DscVis, Qtd_PrzMax, Per_Descon, Desconto
        From PDVIT 
        Where Cod_Estabe = @CodEstabe
        And Cod_Pedido = @CodPed 
        And Qtd_Pedido > 0
    Open PDVIT_Cr
    Fetch Next From PDVIT_Cr Into @cr_CodPrd, @cr_CodLot, @cr_TipSai, @cr_CVlrLiq, @cr_CPrcTot, @cr_PerDscVis, @cr_QtdPrzMax, @cr_PerDscPrz, @cr_FlgBlqDsc
    While @@FETCH_STATUS = 0
      begin
        -- valor liquido do item (+ imp, - desc...)
        Set @WValIte = Round(@cr_CVlrLiq,2)
        Set @WValBru = Round(@cr_CPrcTot,2)
        if @cb_TipVct = 'V'
          begin
            Set @WQtdPrz = cast(@PQtdPrzMed as int)
            if (@WQtdPrz = 0) or (@WQtdPrz > @pm_QtdDiaDupVis)
              Set @WQtdPrz = @pm_QtdDiaDupVis
            Set @WPerDsc = Isnull(@cr_PerDscVis,0)
           end
        else
           begin
             Set @WQtdPrz = @cr_QtdPrzMax
             Set @WPerDsc = Isnull(@cr_PerDscPrz,0)
           end
        Set @WValDscFin = 0
        Set @WValDscCom = 0

        if (@PTipDsc = 'C' and @cb_FlgCnvDscIteDscGlb = 0) or (@cb_TipVct = 'A')
          Set @WValDscCom = 0
        else
        if @PTipDsc = 'F'
          Set @WValDscFin = @WValBru*@WPerDsc/100
        else
          Set @WValDscCom = @WValBru*@WPerDsc/100

        -- acumular p/ calc. prazo ponderado
        Set @WSomat = @WSomat + (@WValIte *@WQtdPrz)
        Set @WValLiqAcc = @WValLiqAcc + @WValIte
        if IsNull(@cr_FlgBlqDsc,0) = 0
          Set @WValBruAcc = @WValBruAcc + @WValBru
        Set @WValDscAcc = @WValDscAcc + (@WValBru*@WPerDsc/100)

        if Exists(Select Qtd_Prz From #PRZAX Where Qtd_Prz = @WQtdPrz)
          Update #PRZAX
            Set Vlr_Itens = Vlr_Itens + @WValIte,
                Vlr_DscFin = Vlr_DscFin + @WValDscFin,
                Vlr_DscCom = Vlr_DscCom + @WValDscCom
            Where Qtd_Prz = @WQtdPrz
        else
          Insert into #PRZAX Values(@WQtdPrz,@WValIte,@WValDscFin,@WValDscCom)

        Fetch Next From PDVIT_Cr Into @cr_CodPrd, @cr_CodLot, @cr_TipSai, @cr_CVlrLiq, @cr_CPrcTot, @cr_PerDscVis, @cr_QtdPrzMax, @cr_PerDscPrz, @cr_FlgBlqDsc
      end
    Close PDVIT_Cr
    Deallocate PDVIT_Cr

    -- Prazo Medio Ponderado
    if @cb_TipVct = 'A'
      begin
        Set @PQtdPrzMed = 0
        Set @PFlgVlrFin = 0
        Set @PPerDscCom = 0
        if @cb_IdPolCom = 0
          Set @PPerDscFin = 0
        -- recalcula valor do pedido devido a alteracao no desconto
        Set @WRecalcula = 1
      end
    else
      begin
        if @WValLiqAcc > 0
          Set @PQtdPrzMed = Round(@WSomat/@WValLiqAcc,0)

        -- Desconto Financeiro ou comercial
        Set @WValDscAcc = Round(@WValDscAcc,2)
        if (@WValDscAcc > 0) or (@PPerDscComMemo > 0) 
          if (@PTipDsc = 'F') and (@cb_IdPolCom = 0)
--12/04/2011            Set @PPerDscFin = @WValDscAcc * 100 /@WValLiqAcc
            Set @PPerDscFin = @WValDscAcc * 100 /@WValBruAcc
          else
            begin
              if @cb_FlgCnvDscIteDscGlb = 1
                begin
                  Set @PPerDscCom = @WValDscAcc * 100 /@WValBruAcc
                  -- recalcula valor do pedido devido a alteracao no desconto
                  Set @WRecalcula = 1
                end
			  else
			    if @PPerDscComMemo > 0
				  begin
			        Set @PPerDscCom = @PPerDscComMemo
					Set @WRecalcula = 1
				  end
            end

        -- aqui  09/06/2016
		-- desdobra prazos por prazo/fabricante
        if @cb_TipVct = 'D' 
		  begin
            -- cria tabela temporaria local
            Create Table #PRZAX2
             (Qtd_Prz int not null Primary Key,
              Vlr_Itens numeric(18,4) not null,
              Vlr_DscFin numeric(18,4) not null,
              Vlr_DscCom numeric(18,4) not null)

            Declare @WQtdInt int,
                    @WQtdDesdob int,
				    @WValIteDesdob numeric(18,4),
				    @WValDscFinDesdob numeric(18,4),
				    @WValDscComDesdob numeric(18,4),
				    @WValIteAcc  numeric(18,4),
				    @WValDscFinAcc numeric(18,4),
				    @WValDscComAcc numeric(18,4)

            Set @WQtdInt = @PQtdInt

            Declare PRZAX_Cr Cursor Local For
              Select Qtd_Prz, Vlr_Itens, Vlr_DscFin, Vlr_DscCom
                From #PRZAX
             Open PRZAX_Cr
            Fetch Next From PRZAX_Cr Into @cr_QtdPrz, @cr_VlrItens, @cr_VlrDscFin, @cr_VlrDscCom
            While @@FETCH_STATUS = 0
              begin
		        -- define quantidade de desdobramentos por prazo
                Set @WQtdDesdob = @PQtdPar
				if @WQtdDesdob < 1
				  Set @WQtdDesdob = 1      

                -- calcula qtd minima de desdobramentos verificando o valor minimo (pode reduzir a qtd de parcelas)
                if @WQtdDesdob > 0 
			      begin
                    Set @WValIteDesdob = Round(@cr_VlrItens/@WQtdDesdob,2)
                    while (@WValIteDesdob < @op_VlrMinDup) and (@WQtdDesdob > 1)
                      begin
                        Set @WQtdDesdob = @WQtdDesdob - 1
                        Set @WValIteDesdob = Round(@cr_VlrItens/@WQtdDesdob,2)
                      end
                  end

			    while @WQtdDesdob > 1
			      begin
                    -- se parcela for par, intervalo tem que ser par...
                    if (@WQtdDesdob > 1) and (@WQtdDesdob % 2 = 0)
                      if @WQtdInt % 2  <> 0
                        Set @WQtdInt = @WQtdInt + 1

                    -- prazo do 1o. desdobramento
                    Set @WQtdPrzAnt = @cr_QtdPrz - floor((@WQtdDesdob - 1)*@WQtdInt*1.0/2)

	     			if @WQtdPrzAnt >= @pm_QtdDiaDupVis
		    		  break
                    else
                      Set @WQtdDesdob = @WQtdDesdob - 1
			      end  -- while @WQtdDesdob > 1

                if @WQtdDesdob > 1 
                  begin
                    Set @WValIteDesdob = Round(@cr_VlrItens/@WQtdDesdob,2)
                    Set @WValDscFinDesdob = Round(@cr_VlrDscFin/@WQtdDesdob,2)
                    Set @WValDscComDesdob = Round(@cr_VlrDscCom/@WQtdDesdob,2)
			      end
		        else
			      begin
			        Set @WQtdDesdob = 1
					Set @WQtdPrzAnt = @cr_QtdPrz
                    Set @WValIteDesdob = @cr_VlrItens
                    Set @WValDscFinDesdob = @cr_VlrDscFin
                    Set @WValDscComDesdob = @cr_VlrDscCom
			      end

                Set @WConPar = 0
                Set @WValIteAcc = @cr_VlrItens
                Set @WValDscFinAcc = @cr_VlrDscFin
                Set @WValDscComAcc = @cr_VlrDscCom

			    while @WConPar < @WQtdDesdob
			      begin
                    Set @WConPar = @WConPar + 1
    
     	            if @WConPar = @WQtdDesdob
	    			  begin
                        Set @WValIteDesdob = @WValIteAcc
			    		Set @WValDscFinDesdob = @WValDscFinAcc
				    	Set @WValDscComDesdob = @WValDscComAcc
				      end

                    if Exists(Select Qtd_Prz From #PRZAX2 Where Qtd_Prz = @WQtdPrzAnt)
                      Update #PRZAX2
                        Set Vlr_Itens = Vlr_Itens + @WValIteDesdob,
                            Vlr_DscFin = Vlr_DscFin + @WValDscFinDesdob,
                            Vlr_DscCom = Vlr_DscCom + @WValDscComDesdob
                        Where Qtd_Prz = @WQtdPrzAnt
                    else
                      Insert into #PRZAX2 Values(@WQtdPrzAnt,@WValIteDesdob,@WValDscFinDesdob,@WValDscComDesdob)

                    Set @WQtdPrzAnt = @WQtdPrzAnt + @WQtdInt
                    Set @WValIteAcc = @WValIteAcc - @WValIteDesdob
                    Set @WValDscFinAcc = @WValDscFinAcc - @WValDscFinDesdob
                    Set @WValDscComAcc = @WValDscComAcc - @WValDscComDesdob
			      end

                Fetch Next From PRZAX_Cr Into @cr_QtdPrz, @cr_VlrItens, @cr_VlrDscFin, @cr_VlrDscCom
              end
            Close PRZAX_Cr
            Deallocate PRZAX_Cr

			Delete From #PRZAX
			Insert #PRZAX
			  Select * From #PRZAX2
			Delete From #PRZAX2

		  end  -- if @cb_TipVct = 'D' 

      end
  end    -- prazo fabricante         if @WTipPrz = 'F'

-- atualiza PDVCB para recalcular valores calculados
if (@WTipPrz = 'F') or (@cb_IdPolCom > 0)
  Update PDVCB
    Set Qtd_Parcela = @PQtdPar,
        Qtd_Intervalo = @PQtdInt,
        Per_DescontoCom = @PPerDscCom,
        Per_DescontoFin = @PPerDscFin,
        Qtd_PrzMed = @PQtdPrzMed,
        Flg_VlrFinanc = @PFlgVlrFin,
        Tip_DscPdv = @PTipDsc
    Where Cod_Estabe = @CodEstabe
    And Numero = @CodPed
else
  Update PDVCB
    Set Qtd_Parcela = @PQtdPar,
        Qtd_Intervalo = @PQtdInt,
        Per_DescontoCom = @PPerDscCom,
        Per_DescontoFin = @PPerDscFin
    Where Cod_Estabe = @CodEstabe
    And Numero = @CodPed

-- ver se recalcula impostos de itens devido alteracao de desconto no cabecalho
if @WRecalcula = 1
  begin
    Declare PDVIT_Cr Cursor Local Fast_Forward For
      Select Cod_Produto, Cod_Lote, Tip_Sai
        From PDVIT 
        Where Cod_Estabe = @CodEstabe
        And Cod_Pedido = @CodPed 
        And Qtd_Pedido > 0
    Open PDVIT_Cr
    Fetch Next From PDVIT_Cr Into @cr_CodPrd, @cr_CodLot, @cr_TipSai
    While @@FETCH_STATUS = 0
      begin

        EXEC PR_CalcTributPdvit @CodEstabe, @CodPed, @cr_CodPrd, @cr_CodLot, @cr_TipSai

        Fetch Next From PDVIT_Cr Into @cr_CodPrd, @cr_CodLot, @cr_TipSai
      end
    Close PDVIT_Cr
    Deallocate PDVIT_Cr
  end

-- pega valores atualizados do cabecalho
Select @cb_CVlrPed = Round(IsNull(C_VlrPedido,0),2),
       @cb_VlrSubTri = Round(IsNull(Vlr_SubsTrib,0),2),
       @cb_VlrSbtRes = Round(IsNull(Vlr_SbtRes,0),2)
  From PDVCB
  Where Cod_Estabe = @CodEstabe
  And Numero = @CodPed

-- ver se inclui total imposto na 1a. duplic
Set @WValBasPed = @cb_CVlrPed
if @pm_FlgImpPriDup = 1
  Set @WValBasPed = @WValBasPed - @cb_VlrSubTri - @cb_VlrSbtRes

-- se nao utiliza tabela de prazos
if @cb_TipVct <> 'T'
  begin         
    -- CALCULA VENCIMENTOS
    -- inicializa campos
    Delete From PDVDP
      Where Cod_Estabe = @CodEstabe
      And Cod_Pedido = @CodPed
    
    Set @WConPar = 0  -- contador de parcelas
    
    -- prazo fabricante nao ponderado
    if ((@WTipPrz = 'F') or (@cb_IdPolCom > 0)) and (@cb_TipVct <> 'P') 
      begin
        if @cb_TipVct = 'A'  -- apresentacao
          begin
            Set @WDatVct = dbo.FN_DataDaSemana(@Date+@pm_QtdDiaPrgDupApr,@cl_DiaSemVctTit)
            if not Exists(Select 1 From PDVDP 
                          Where Cod_Estabe = @CodEstabe
                          And Cod_Pedido = @CodPed 
                          And Dat_Vencim = @WDatVct 
                          And Flg_Apresentacao = 1)
              begin
                Set @WConPar = @WConPar + 1
                Insert Into PDVDP (Cod_Estabe, Cod_Pedido, Dat_Vencim, Num_SeqPar, Vlr_Duplic, Vlr_SbtEmb, Vlr_ResEmb, Flg_DupExt, Flg_Apresentacao)
                           Values (@CodEstabe, @CodPed, @WDatVct, @WConPar, 0, 0, 0, 0, 1)
              end
              
            Update PDVDP
			  Set Vlr_Duplic = Vlr_Duplic + @WValBasPed
            Where Cod_Estabe = @CodEstabe
            And Cod_Pedido = @CodPed 
            And Dat_Vencim = @WDatVct
            And Flg_Apresentacao = 1  
            
          end
        else
          begin
            Declare @WUltPar int 

            Set @WUltPar = (Select count(*) From #PRZAX)

			Set @WValAcc = @WValBasPed

            -- calcula vencimentos
            Declare PRZAX_Cr Cursor Local Fast_Forward For
              Select Qtd_Prz, Vlr_Itens, Vlr_DscFin, Vlr_DscCom
                From #PRZAX
            Open PRZAX_Cr
            Fetch Next From PRZAX_Cr Into @cr_QtdPrz, @cr_VlrItens, @cr_VlrDscFin, @cr_VlrDscCom
            While @@FETCH_STATUS = 0
              begin
                Set @WConPar = @WConPar + 1
        
                if @WConPar = @WUltPar
                  Set @WValDup = Round(@WValAcc,2)
                else
                  Set @WValDup = Round(@cr_VlrItens-@cr_VlrDscCom,2)
                      
                Set @WValDscFin = 0
                if @PTipDsc = 'F'
                  Set @WValDscFin = Round(@cr_VlrDscFin,4)
                   
                Set @WDatVct = dbo.FN_DataDaSemana(@cb_DatPed+@cr_QtdPrz,@cl_DiaSemVctTit)

                Insert Into PDVDP (Cod_Estabe, Cod_Pedido, Dat_Vencim, Num_SeqPar, Vlr_Duplic, Vlr_SbtEmb, Vlr_ResEmb, Vlr_DescFinanc, Flg_DupExt)
                           Values (@CodEstabe, @CodPed, @WDatVct, @WConPar, @WValDup, 0, 0, @WValDscFin, 0)
                           
                Set @WValAcc = @WValAcc - @WValDup

                 Fetch Next From PRZAX_Cr Into @cr_QtdPrz, @cr_VlrItens, @cr_VlrDscFin, @cr_VlrDscCom
              end
            Close PRZAX_Cr
            Deallocate PRZAX_Cr

            -- garante pelo menos uma duplicata
            if @WConPar = 0
              begin
                Set @WConPar = @WConPar + 1
                Set @WDatVct = dbo.FN_DataDaSemana(@cb_DatPed+cast(@PQtdPrzMed as int),@cl_DiaSemVctTit)

                Insert Into PDVDP (Cod_Estabe, Cod_Pedido, Dat_Vencim, Num_SeqPar, Vlr_Duplic, Vlr_SbtEmb, Vlr_ResEmb, Flg_DupExt)
                           Values (@CodEstabe, @CodPed, @WDatVct, @WConPar, @WValBasPed, 0, 0, 0) 
              end

           Set @PQtdPar = @WConPar
               
          end  -- else if @cb_TipVct = 'A'
      end  -- if ((@WTipPrz = 'F') or (@cb_IdPolCom > 0)) and (@cb_TipVct <> 'P') 

    -- CALCULA VENCIMENTOS
    -- prazo linear ou fabricante ponderado
    if (@WTipPrz <> 'F') or (((@WTipPrz = 'F') or (@cb_IdPolCom > 0)) and @cb_TipVct = 'P')
      begin
        Set @WFlgApr = 0
        if @cb_TipVct = 'A'
          Set @WFlgApr = 1
      
        -- calcula o valor de uma duplicata verificando o valor minimo (pode reduzir a qtd de parcelas)
        if @PQtdPar > 0 
          Set @WValDup = Round(@WValBasPed/@PQtdPar,2)
        else
          Set @WValDup = 0
        while (@WValDup < @op_VlrMinDup) and (@PQtdPar > 1)
          begin
            Set @PQtdPar = @PQtdPar - 1
            Set @WValDup = Round(@WValBasPed/@PQtdPar,2)
          end

        -- se parcela for par, intervalo tem que ser par...
--        if (@PQtdPar > 1) and (@PQtdPar % 2 = 0)
--          if @PQtdInt % 2  <> 0
--            Set @PQtdInt = @PQtdInt + 1

        -- aqui  09/06/2016
        while @PQtdPar > 1
		  begin
            -- se parcela for par, intervalo tem que ser par...
            if (@PQtdPar > 1) and (@PQtdPar % 2 = 0)
              if @PQtdInt % 2  <> 0
                Set @PQtdInt = @PQtdInt + 1

            -- prazo do 1o. desdobramento
            Set @WQtdPrzAnt = @PQtdPrzMed - floor((@PQtdPar - 1)*@PQtdInt*1.0/2)

            if @WQtdPrzAnt >= @pm_QtdDiaDupVis
		      break
            else
              Set @PQtdPar = @PQtdPar - 1
          end  -- while @PQtdPar > 1

        if @PQtdPar > 0 
          begin
            Delete From PDVDP
            Where Cod_Estabe = @CodEstabe
            And Cod_Pedido = @CodPed
          end

        Set @WConPar = 1
        Set @WDatVctAnt = @cb_DatPed + cast(@PQtdPrzMed as int) - floor((@PQtdPar - 1)*@PQtdInt*1.0/2)
        Set @WValAcc = 0 -- para calcular a primeira, que terá o residuo (acumulador das parcelas exceto a 1a.)
        while @WConPar <= @PQtdPar
          begin
            Set @WDatVct = dbo.FN_DataDaSemana(@WDatVctAnt,@cl_DiaSemVctTit)
            Insert Into PDVDP (Cod_Estabe, Cod_Pedido, Dat_Vencim, Num_SeqPar, Vlr_Duplic, Vlr_SbtEmb, Vlr_ResEmb, Flg_Apresentacao, Flg_DupExt)
                       Values (@CodEstabe, @CodPed, @WDatVct, @WConPar, @WValDup, 0, 0, @WFlgApr, 0)
            if @WConPar > 1           
              Set @WValAcc = @WValAcc + @WValDup
            Set @WDatVctAnt = @WDatVctAnt + @PQtdInt
            Set @WConPar = @WConPar + 1
          end
          
        -- calcula o valor da primeira que terá o residuo 
        if Exists(Select Num_SeqPar From PDVDP Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Num_SeqPar = 1)
          begin
            Update PDVDP
              Set Vlr_Duplic = Round(@WValBasPed-@WValAcc,2)
              Where Cod_Estabe = @CodEstabe
              And Cod_Pedido = @CodPed
              And Num_SeqPar = 1
          end
      end  -- se prazo linear ou fabricante ponderado
      
  end    --  if @cb_TipVct <> 'T'
else
  begin
    if Exists(Select Cod_Prz From PRZCB 
                Where Cod_Prz = @cb_CodPrz 
                And Qtd_PrzMed > 0)  
      begin
        Declare @pz_QtdParPrz tinyint,
                @pz_QtdPrzMed int,
                @cr_QtdPrzPar smallint, 
                @cr_Per_ParPar numeric(18,8)
                
        Select @pz_QtdParPrz = Qtd_ParPrz,
               @pz_QtdPrzMed = Qtd_PrzMed
          From PRZCB
          Where Cod_Prz = @cb_CodPrz

        Set @PQtdPrzMed = @pz_QtdPrzMed
        Set @PQtdPar = @pz_QtdParPrz

        Delete From PDVDP
          Where Cod_Estabe = @CodEstabe
          And Cod_Pedido = @CodPed

        -- calcula os valores dos titulos
        Set @WValAcc = 0
        Set @WConPar = @pz_QtdParPrz

        Declare PRZIT_Cr Cursor Local Fast_Forward For
          Select Qtd_PrzPar, Per_ParPar 
            From PRZIT 
            Where Cod_Prz = @cb_CodPrz
            Order by Qtd_PrzPar desc  -- residuo vai para o 1o vencimento
        Open PRZIT_Cr
        Fetch Next From PRZIT_Cr Into @cr_QtdPrzPar, @cr_Per_ParPar
        While @@FETCH_STATUS = 0
          begin
            if @WConPar > 0
              begin
                if @WConPar = 1
                  Set @WValDup = Round(@WValBasPed-@WValAcc,2)
                else
                  Set @WValDup = Round(@WValBasPed*@cr_Per_ParPar/100,2)
                Set @WDatVct = dbo.FN_DataDaSemana(@cb_DatPed+@cr_QtdPrzPar,@cl_DiaSemVctTit)

                Insert Into PDVDP (Cod_Estabe, Cod_Pedido, Dat_Vencim, Num_SeqPar, Vlr_Duplic, Vlr_SbtEmb, Vlr_ResEmb, Flg_DupExt)
                           Values (@CodEstabe, @CodPed, @WDatVct, @WConPar, @WValDup, 0, 0, 0)

                Set @WValAcc = @WValAcc + @WValDup
                Set @WConPar = @WConPar - 1
              end

            Fetch Next From PRZIT_Cr Into @cr_QtdPrzPar, @cr_Per_ParPar
          end

        Close PRZIT_Cr
        Deallocate PRZIT_Cr

        -- Normaliza prazos nos itens
        Update PDVIT
          Set Qtd_PrzMax = @PQtdPrzMed
          Where Cod_Estabe = @CodEstabe
          And Cod_Pedido = @CodPed and Qtd_Pedido > 0
      end
  end
--------------------------------------------------------------------------------------------------------------------

if (@WTipPrz = 'F') or (@cb_IdPolCom > 0)
  Update PDVCB
     Set Qtd_PrzMed = @PQtdPrzMed
     Where Cod_Estabe = @CodEstabe
     And Numero = @CodPed

Update PDVCB
  Set Qtd_Parcela = @PQtdPar,
      Qtd_Intervalo = @PQtdInt
   Where Cod_Estabe = @CodEstabe
   And Numero = @CodPed

-- inclui ST na 1a. duplicata
if (@pm_FlgImpPriDup = 1) and
((@cb_VlrSubTri + @cb_VlrSbtRes) > 0)
  begin
    Set @WFlgIncDupSbt = 0  -- indica se cria nova parcela para ST
    if @pm_QtdPrzMaxImpSbt > 0
      begin
        -- prazo maximo p/ ST
        Set @WDatVct = dbo.FN_DataDaSemana(@cb_DatPed+@pm_QtdPrzMaxImpSbt,@cl_DiaSemVctTit)
        
        -- prazo da 1a. parcela
        Select top 1 @WDatVctAnt = Dat_Vencim 
          From PDVDP 
          Where Cod_Estabe = @CodEstabe
          And Cod_Pedido = @CodPed 
          And Num_SeqPar = 1
          
        -- verifica se vencimento da 1a.parcela é maior que vencimento minimo p/ ST
        if (@WDatVctAnt > @WDatVct) and
           ((@cb_VlrSubTri + @cb_VlrSbtRes) >= @op_VlrMinDup)
          Set @WFlgIncDupSbt = 1  -- indica se cria nova parcela para sbt
          
      end
     
    -- cria nova 1a.parcela
    if @WFlgIncDupSbt = 1 
      begin
        if Exists(Select 1 From PDVDP Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Num_SeqPar = 1)
          begin
            Update PDVDP
              Set Num_SeqPar = Num_SeqPar + 1 
              Where Cod_Estabe = @CodEstabe
              And Cod_Pedido = @CodPed
      
            Update PDVCB
              Set Qtd_Parcela = Qtd_Parcela + 1
              Where Cod_Estabe = @CodEstabe
              And Numero = @CodPed
          end

        Insert Into PDVDP (Cod_Estabe, Cod_Pedido, Dat_Vencim, Num_SeqPar, Vlr_Duplic, Vlr_SbtEmb, Vlr_ResEmb, Flg_DupExt)
                   Values (@CodEstabe, @CodPed, @WDatVct, 1, 0, 0, 0, 0)
      end
     
    -- acrescenta ST à 1a. parcela  
    Update PDVDP
      Set Vlr_Duplic = Vlr_Duplic + @cb_VlrSubTri + @cb_VlrSbtRes,
          Vlr_SbtEmb = @cb_VlrSubTri,
          Vlr_ResEmb = @cb_VlrSbtRes
      Where Cod_Estabe = @CodEstabe
      And Cod_Pedido = @CodPed
      And Num_SeqPar = 1
   end

-- rateia subst.tribut e ressarcimento embutidos no valor
Set @WValSubTri = @cb_VlrSubTri - (Select SUM(Vlr_SbtEmb) From PDVDP Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed)
Set @WValSbtRes = @cb_VlrSbtRes - (Select SUM(Vlr_ResEmb) From PDVDP Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed)

if @WValSubTri < 0
  Set @WValSubTri = 0
if @WValSbtRes < 0
  Set @WValSbtRes = 0  

if @WValSubTri > 0
  begin
    -- rateia
    Update PDVDP
      Set Vlr_SbtEmb = Round(@WValSubTri*Vlr_Duplic/@cb_CVlrPed,2,1)
      Where Cod_Estabe = @CodEstabe
      And Cod_Pedido = @CodPed

    Set @WValAcc = ISNULL(ROUND((Select SUM(ISNULL(Vlr_SbtEmb,0)) From PDVDP Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Num_SeqPar > 1),2),0)
    
    -- calcula o valor da primeira que terá o residuo
    Update PDVDP
      Set Vlr_SbtEmb = Round(@cb_VlrSubTri-@WValAcc,2)
      Where Cod_Estabe = @CodEstabe
      And Cod_Pedido = @CodPed
      And Num_SeqPar = 1
  end

if @WValSbtRes > 0
  begin
    -- rateia
    Update PDVDP
      Set Vlr_ResEmb = Round(@WValSbtRes*Vlr_Duplic/@cb_CVlrPed,2,1)
      Where Cod_Estabe = @CodEstabe
      And Cod_Pedido = @CodPed

    Set @WValAcc = ISNULL(ROUND((Select SUM(ISNULL(Vlr_ResEmb,0)) From PDVDP Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Num_SeqPar > 1),2),0)

    -- calcula o valor da primeira que terá o residuo
    Update PDVDP
       Set Vlr_ResEmb = Round(@cb_VlrSbtRes-@WValAcc,2)
     Where Cod_Estabe = @CodEstabe
       And Cod_Pedido = @CodPed
       And Num_SeqPar = 1
  end

Set @WValDespes = 0.00     

if @op_FlgLanFin = 0
  begin
    Delete From PDVDP
     Where Cod_Estabe = @CodEstabe
       And Cod_Pedido = @CodPed
      
    Update PDVCB
       Set Qtd_Parcela = @PQtdPar,
           Qtd_Intervalo = @PQtdInt
     Where Cod_Estabe = @CodEstabe
       And Numero = @CodPed
  end
else
  begin
    -- calcula despesa ref. taxa administrativa
    if @ag_PerTaxAdm > 0
      begin
        if @ag_CodAplTaxAdm = 'P' -- margem (participação)
          Set @WValDespes = Round(@cb_VlrLiqIte/(1-@ag_PerTaxAdm/100),2)-Round(@cb_VlrLiqIte,2)
        if @ag_CodAplTaxAdm = 'A'  -- mark-up (acrescimo)
          Set @WValDespes = Round(@cb_VlrLiqIte*@ag_PerTaxAdm/100,2)     
      end

    -- calcula despesa boleto bancario a cobrar na nota fiscal
    Set @WValTotDspBolBan = 0
    if @op_FlgLanFin = 1
      begin
        Set @WValTotDspBolBan = Round(Isnull(@ag_VlrDspBolBan,0) * @PQtdPar,2)
        Set @WValDespes = @WValDespes + @WValTotDspBolBan
      end

    -- debita taxa boleto para vendedor
    if 1 = 1 --@TipNfs = 'V'
      begin
        -- taxa boleto
        if @pm_FlgDebBlqBanVrbVdr = 1
          begin
            Set @WValDespes = @WValDespes - @WValTotDspBolBan    -- isenta cliente
          end
      end
  end

/*
if @cb_VlrDespes <> @WValDespes
  begin
-- print 'Vou ratear despesas'
    Exec PR_RateiaDespesasPDV @CodEstabe, @CodPEd
  end
*/

-- libera pedido
Update PDVCB
   Set Flg_Calc = 0               
 Where Cod_Estabe = @CodEstabe
   And Numero = @CodPed

if @@trancount > 0
  Commit Transaction
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_DesdobraPDECB]
@PCodEstabe int,
@PCodLayout int,
@PNumCnpj varchar(14),
@PCodPedCli varchar(20)

AS

SET NOCOUNT ON

if not Exists(Select 1 From dbo.PDECB 
               Where Cod_Estabe = @PCodEstabe And Cod_Layout = @PCodLayout 
                 And Num_Cnpj   = @PNumCnpj   And Cod_PedCli = @PCodPedCli 
                 And ((IsNull(Num_PedVen,0) > 0) or (Sta_Pedido <> '0'))) and
   Exists(Select 1 From dbo.PDECB 
           Where Cod_Estabe = @PCodEstabe And Cod_Layout = @PCodLayout 
             And Num_Cnpj   = @PNumCnpj   And Cod_PedCli = @PCodPedCli 
             And IsNull(Num_PedVen,0) = 0 And Sta_Pedido = '0')
  begin
    BEGIN TRANSACTION

    Declare @PNumDesdob int,
            @PMsgSql varchar(400),

            @WIte_NumDesdob int,
            @WIte_Ordem varchar(1),
			@WIte_CodPrdArq varchar(14),

            @WIte_IdPolCom int,
            @WIte_CodPolCom varchar(25),
            @WIte_FlgBlqPolDIfCabPdv bit,

			@pe_IdPolCom int,
            @pe_FlgBlqPolDifItePdv bit,
			@pe_CodMtvRej varchar(3)

-----------------------  CANCELA DESDOBRAMENTOS  ----------------------------------------------------------------------------------------------------

    -- menor desdobramento deve ser = 1
	if not Exists(Select 1 From dbo.PDECB 
                   Where Cod_Estabe = @PCodEstabe And Cod_Layout = @PCodLayout 
                     And Num_Cnpj   = @PNumCnpj   And Cod_PedCli = @PCodPedCli
                     And Num_Desdob = 1)
      begin
        Set @PNumDesdob = (Select min(Num_Desdob) From dbo.PDECB
                            Where Cod_Estabe = @PCodEstabe And Cod_Layout = @PCodLayout 
                              And Num_Cnpj   = @PNumCnpj   And Cod_PedCli = @PCodPedCli)

        Update dbo.PDECB
           Set Num_Desdob = 1
         Where Cod_Estabe = @PCodEstabe And Cod_Layout = @PCodLayout
           And Num_Cnpj = @PNumCnpj And Cod_PedCli = @PCodPedCli
           And Num_Desdob = @PNumDesdob
           And @PNumDesdob <> 1
      end

    Set @PNumDesdob = 1

    -- agrupa todos os itens para desdobramento 1
    Update dbo.PDEIT
       Set Num_Desdob  = @PNumDesdob
     Where Cod_Estabe  = @PCodEstabe And Cod_Layout = @PCodLayout 
       And Num_Cnpj    = @PNumCnpj   And Cod_PedCli = @PCodPedCli
       And Num_Desdob <> @PNumDesdob

    -- cancela pedidos desdobrados, se houver
    Delete From dbo.PDECB
     Where Cod_Estabe  = @PCodEstabe And Cod_Layout = @PCodLayout 
       And Num_Cnpj    = @PNumCnpj   And Cod_PedCli = @PCodPedCli
       And Num_Desdob <> @PNumDesdob

    -- atualiza/corrige/re-seta dados em PDECB
    Update dbo.PDECB
       Set Qtd_Itens = (Select count(*) From dbo.PDEIT 
                         Where Cod_Estabe = @PCodEstabe And Cod_Layout = @PCodLayout 
                           And Num_Cnpj   = @PNumCnpj   And Cod_PedCli = @PCodPedCli 
                           And Num_Desdob = @PNumDesdob),
           Cod_MtvRej = '',
           Des_MtvRej = '',
           Id_PolCom  = Case When IsNull(Flg_PolPedInf,0) = 0 then 0 Else Id_PolCom End,
           Cod_PolCom = Case When IsNull(Flg_PolPedInf,0) = 0 then '' Else Cod_PolCom End
     Where Cod_Estabe = @PCodEstabe And Cod_Layout = @PCodLayout 
       And Num_Cnpj   = @PNumCnpj   And Cod_PedCli = @PCodPedCli
       And Num_Desdob = @PNumDesdob

    -- atualiza/corrige/re-seta dados em PDEIT
    Update dbo.PDEIT
       Set Qtd_Atendi = 0, 
           Cod_MtvRej = '',
           Des_MtvRej = '',
           Id_PolCom  = Case When IsNull(Flg_PolInf,0) = 0 then 0 Else Id_PolCom End,
           Cod_PolCom = Case When IsNull(Flg_PolInf,0) = 0 then '' Else Cod_PolCOm End
     Where Cod_Estabe = @PCodEstabe And Cod_Layout = @PCodLayout 
       And Num_Cnpj   = @PNumCnpj   And Cod_PedCli = @PCodPedCli
       And Num_Desdob = @PNumDesdob

-----------------------------------------------------------------------------------------------------------------------------------------------------

    if not Exists(Select 1 From dbo.PDECB
                   Where Cod_Estabe  = @PCodEstabe And Cod_Layout = @PCodLayout 
                     And Num_Cnpj    = @PNumCnpj   And Cod_PedCli = @PCodPedCli
                     And Num_Desdob <> @PNumDesdob)
      begin

        Set @PMsgSql = ''

        Begin Try

          -- valida/complementa dados PDECB e PDEIT, define politicas de comercialização
          Exec PR_ValidaDadosPDE @PCodEstabe, @PCodLayout, @PNumCnpj, @PCodPedCli, @PNumDesdob

		  -- desdobramento atual
		  Set @PNumDesdob = 1

		  Select @pe_IdPolCom = IsNull(cb.Id_PolCom,0),
                 @pe_FlgBlqPolDifItePdv = IsNull(pc.Flg_BlqPolDifItePdv,0), 
                 @pe_CodMtvRej = IsNull(cb.Cod_MtvRej,'')				 		   
		    From dbo.PDECB cb
                 Left Join dbo.POCOM pc on cb.Id_PolCom = pc.Id_PolCom
           Where cb.Cod_Estabe = @PCodEstabe And cb.Cod_Layout = @PCodLayout 
             And cb.Num_Cnpj   = @PNumCnpj  And cb.Cod_PedCli = @PCodPedCli
             And cb.Num_Desdob = @PNumDesdob

          -- desdobramento dos itens
          Declare @tab1 table(
            Chave1 int identity(1,1) primary key,
            Num_Desdob smallint, 
            Cod_PrdCli varchar(14), 
            Id_PolCom int, 
            Flg_BlqPolDIfCabPdv bit,
            Ordem char(1)
          )

          Insert into @tab1
            Select it.Num_Desdob, it.Cod_PrdCli, it.Id_PolCom, pc.Flg_BlqPolDIfCabPdv,
		           Ordem = Case 
                             When (@pe_IdPolCom > 0) and (it.Id_PolCom = @pe_IdPolCom) then '1' 						   
                             When IsNull(it.Id_PolCom,0) = 0 then '2' 
                             When (IsNull(pc.Id_PolCom,0) > 0) and (IsNull(pc.Flg_BlqPolDIfCabPdv,0) = 0) then '3'
                             Else '4'
                           End
		      From dbo.PDEIT it
                   Left Join dbo.POCOM pc on it.Id_PolCom = pc.Id_PolCom
             Where it.Cod_Estabe = @PCodEstabe And it.Cod_Layout = @PCodLayout 
               And it.Num_Cnpj   = @PNumCnpj   And it.Cod_PedCli = @PCodPedCli
               And IsNull(@pe_CodMtvRej,'') = ''
		     Order by Ordem, it.Id_PolCom


          Declare @WChave1 int = 0

          While (Select count(*) from @tab1) > 0
            BEGIN
              Select top 1 @WChave1 = Chave1,
                           @WIte_NumDesdob= Num_Desdob, 
                           @WIte_CodPrdArq = Cod_PrdCli, 
                           @WIte_IdPolCom = Id_PolCom, 
                           @WIte_FlgBlqPolDIfCabPdv = Flg_BlqPolDIfCabPdv,
                           @WIte_Ordem = Ordem
		        From @tab1 t
               Order by Ordem, Id_PolCom

              -- compara politica do cabecalho x politica do item
              -- verifica troca quando os 2 sao maior que zero
              if cast(@WIte_Ordem as int) > 2
                begin
                  if ((@WIte_IdPolCom > 0) and (@pe_IdPolCom > 0)) and
                     (@WIte_IdPolCom <> @pe_IdPolCom) and
                     ((@pe_FlgBlqPolDifItePdv = 1) or (@WIte_FlgBlqPolDIfCabPdv = 1)) 
                    begin
                      -- verifica se existe algum desdobramento que atende ao item
                      Set @PNumDesdob = (Select top 1 pe.Id_PolCom
                                           From dbo.PDECB pe
                                                Inner Join dbo.POCOM pc on pe.Id_PolCom = pc.Id_PolCom
                                          Where pe.Cod_Estabe = @PCodEstabe And pe.Cod_Layout = @PCodLayout 
                                            And pe.Num_Cnpj   = @PNumCnpj   And pe.Cod_PedCli = @PCodPedCli
                                            And ( (pe.Id_PolCom = @WIte_IdPolCom) or 
                                                  ((IsNull(pc.Flg_BlqPolDifItePdv,0) = 0) and (@WIte_FlgBlqPolDIfCabPdv = 0))) )
                 
                      -- se não houver dedobramento que atende item, cria novo             
                      if IsNull(@PNumDesdob,0) = 0
                        begin
                          Set @PNumDesdob = IsNull((Select max(Num_Desdob) From dbo.PDECB
                                                     Where Cod_Estabe = @PCodEstabe And Cod_Layout = @PCodLayout 
                                                       And Num_Cnpj   = @PNumCnpj   And Cod_PedCli = @PCodPedCli),0) + 1
                 
                          -- inclui desdobramento
                          Exec _CopiaPDECB @PCodEstabe, @PCodLayout, @PNumCnpj, @PCodPedCli, @WIte_NumDesdob, @PNumDesdob, 0
                 
                          -- atualiza politica novo desdobramento
                          Update cb
                             Set cb.Id_PolCom = IsNull(pc.Id_PolCom,0), 
                                 cb.Cod_PolCom = IsNull(pc.Cod_PolCom,'')
                           From dbo.PDECB cb 
                                Left Join dbo.POCOM pc on (pc.Id_PolCom = @WIte_IdPolCom)
                          Where cb.Cod_Estabe = @PCodEstabe And cb.Cod_Layout = @PCodLayout 
                            And cb.Num_Cnpj   = @PNumCnpj   And cb.Cod_PedCli = @PCodPedCli 
                            and cb.Num_Desdob = @PNumDesdob
                        end
                 
                      -- posiciona no novo desdobramento             
                      Select @pe_IdPolCom = IsNull(cb.Id_PolCom,0),
                             @pe_FlgBlqPolDifItePdv = IsNull(pc.Flg_BlqPolDifItePdv,0)
                        From dbo.PDECB cb
                             Left Join dbo.POCOM pc on cb.Id_PolCom = pc.Id_PolCom
                       Where cb.Cod_Estabe = @PCodEstabe And cb.Cod_Layout = @PCodLayout 
                         And cb.Num_Cnpj   = @PNumCnpj   And cb.Cod_PedCli = @PCodPedCli
                         And cb.Num_Desdob = @PNumDesdob
                    end

                  -- transfere item para novo dedobramento
                  Update dbo.PDEIT
                     Set Num_Desdob = @PNumDesdob
                   Where Cod_Estabe = @PCodEstabe And Cod_Layout = @PCodLayout 
                     And Num_Cnpj   = @PNumCnpj   And Cod_PedCli = @PCodPedCli
                     And Num_Desdob = @WIte_NumDesdob 
                     And Cod_PrdCli = @WIte_CodPrdArq
             
                end -- if cast(@WIte_Ordem as int) > 2

              Delete From @tab1 
               Where Chave1 = @WChave1
            END

        End Try
        Begin Catch
		  Select @PMsgSql = 'Erro na Rotina '+cast(ERROR_PROCEDURE() as varchar)+', '+
                            'Linha '         +cast(ERROR_LINE()      as varchar)+', '+
                            'Erro: '         +cast(ERROR_MESSAGE()   as varchar)

          Update dbo.PDECB
             Set Msg_Erro = @PMsgSql
           Where Cod_Estabe = @PCodEstabe
             And Cod_Layout = @PCodLayout
             And Num_Cnpj   = @PNumCnpj
             And Cod_PedCli = @PCodPedCli
             And IsNull(Msg_Erro,'') = ''

        End Catch

      end  -- if not Exists(Select 1 From PDECB

    if @@trancount > 0
      COMMIT TRANSACTION
  end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_FechaPdv]
@PCodEstabe int,
@PNumPdv int,
@PSt2 varchar(1)

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime

Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

if Charindex((Select Status2 From PDVCB Where Cod_Estabe = @PCodEstabe And Numero = @PNumPdv),';N;D;') > 0 
  RAISERROR('Pedido já faturado',16,1)
else
if Charindex((Select Status2 From PDVCB Where Cod_Estabe = @PCodEstabe And Numero = @PNumPdv),';F;') > 0 
  RAISERROR('Pedido já fechado',16,1)
else
if (Select Round(Vlr_LiqItens,2) From PDVCB Where Cod_Estabe = @PCodEstabe And Numero = @PNumPdv) <= 0.01
  RAISERROR('Valor do Pedido inválido',16,1)
BEGIN
Begin Transaction

Declare @pm_QtdDiaDupVis int = 0,
		@pm_CodAgeCobCar int = 0,
		@pm_PerRntMinPdv numeric(18,4) = 0,
		@op_FlgCli bit = 0

Select @pm_QtdDiaDupVis = IsNull(QtdDiaDupVis,0),
       @pm_CodAgeCobCar = IsNull(CodAgeCobCar,0),
       @pm_PerRntMinPdv = IsNull(PerRntMinPdv,0)
 From PARAM
 Where Cod_Estabe = @PCodEstabe

Update PDVCB
  Set Status2 = @PSt2,
      Flg_JaFechado = 1,
      Hor_Fechamento= @Now
  Where Cod_Estabe = @PCodEstabe
  And Numero = @PNumPdv

Set @op_FlgCli = IsNull((Select op.Flg_CodCli From TPOPE op Inner Join PDVCB cb on op.Cod_Ope = cb.Tip_Faturamento Where Cod_Estabe = @PCodEstabe And Numero = @PNumPdv),0)

-- se venda a vista ou apresentacao, agente = carteira
if @op_FlgCli = 1
  begin
    Update PDVCB
      Set Cod_Agente = @pm_CodAgeCobCar
      Where Cod_Estabe = @PCodEstabe
      And Numero = @PNumPdv
	  And Tip_Vencimento = 'V'
	  And @pm_QtdDiaDupVis < 3

    -- bloqueia por lucro geral
    Update PDVCB
      Set Cod_BlqRnt = 'B'
      Where Cod_Estabe = @PCodEstabe
      And Numero = @PNumPdv
      And @pm_PerRntMinPdv <> 0 
	  And Round(IsNull(Per_Rnt,0),2) < @pm_PerRntMinPdv

    -- bloqueia por lucro da Origem 
    Update cb
      Set cb.Cod_BlqRnt = 'B'
      From PDVCB cb
           Inner Join ORXES tb on cb.Cod_Estabe = tb.Cod_Estabe and Substring(cb.Cod_OrigemPdv,1,1) = tb.Cod_OriPed
      Where cb.Cod_Estabe = @PCodEstabe
      And cb.Numero = @PNumPdv
      And IsNull(tb.Per_LucMin,0) <> 0 
	  And Round(IsNull(cb.Per_Rnt,0),2) < IsNull(tb.Per_LucMin,0)

    -- bloqueia se houver ao menos 1 produto com lucro inferior ao permitido
    Update cb
      Set cb.Cod_BlqRnt = 'B'
      From PDVCB cb
      Where cb.Cod_Estabe = @PCodEstabe
      And cb.Numero = @PNumPdv
      And Exists(Select 1
                 From PDVIT it 
                      Inner JOIN PRXES pr on it.Cod_Estabe = pr.Cod_Estabe and it.Cod_Produto = pr.Cod_Produt 
                 Where it.Cod_Estabe = cb.Cod_Estabe 
                 And it.Cod_Pedido = cb.Numero
                 And IsNull(pr.Per_LucMin,0) <> 0
                 And IsNull(it.Per_Rnt,0) < IsNull(pr.Per_LucMin,0))

  end

-- registra hora da liberacao se pedido sem bloqueios
Update PDVCB
  Set Hor_Liberacao = @Now
  Where Cod_Estabe = @PCodEstabe
  And Numero = @PNumPdv
  And IsNull(Bloqueio,'') = ''
  And IsNull(Cod_BlqLic,'') <> 'B'
  And IsNull(Cod_BlqRnt,'') <> 'B'

-- cria cabecalho de conferencia somente se nao estiver bloqueado (verificacao feita na rotina)
Exec PR_CriaCabecCPV @PCodEstabe, @PNumPdv

-- imprime pre-nota
if @@trancount > 0
  Commit Transaction
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_SolicitaLoteProduto]
@PCodEstabe int,
@PCodPed int,
@PFlgLotEsp bit,
@PCodPrd int,
@PCodLot varchar(20),
@PTipSai varchar(1),
@PCodPrm int,
@PCodKitPrm int,
@PQtdPed int,
@PQtdBon int,
@PFatCnvImpFat int,
@PFlgLotNaoFra bit

AS

SET NOCOUNT ON

Set DateFormat ymd

Begin Transaction

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime

Set @Now = GetDate()
Set @Date = Cast(Cast(Year(@Now) as varchar)+'-'+Cast(Month(@Now) as varchar)+'-'+Cast(Day(@Now) as varchar)+' 00:00:00' as smalldatetime)

if @PQtdPed is null 
  Set @PQtdPed = 0
if @PQtdBon is null 
  Set @PQtdBon = 0
if IsNull(@PFatCnvImpFat,0) = 0
  Set @PFatCnvImpFat = 1
  
-- corrige saldos negativos
if Exists(Select Cod_Produt
          From PRLOT 
          Where Cod_Estabe = @PCodEstabe
          And Cod_Produt = @PCodPrd
          And ((Qtd_SolPra < 0) or (Qtd_SolDep < 0)))
  begin
    Update PRLOT
      Set Qtd_SolPra = 0
    Where Cod_Estabe = @PCodEstabe
    And Cod_Produt = @PCodPrd
    And Qtd_SolPra < 0
    
    Update PRLOT
      Set Qtd_SolDep = 0
    Where Cod_Estabe = @PCodEstabe
    And Cod_Produt = @PCodPrd
    And Qtd_SolDep < 0
  end

if Exists(Select Cod_Produt
          From PRLOT 
          Where Cod_Estabe = @PCodEstabe
          And Cod_Produt = @PCodPrd
          And ((Qtd_Saldo < 0) or (Qtd_Fisico < 0) or (Qtd_SldPra < 0) or (Qtd_FisPra < 0) or (Qtd_SldDep < 0) or (Qtd_FisDep < 0)))
  begin
    Update PRLOT
      Set Qtd_FisPra = Qtd_FisPra + Abs(Qtd_SldPra)
    Where Cod_Estabe = @PCodEstabe
    And Cod_Produt = @PCodPrd
    And Qtd_SldPra < 0
    
    Update PRLOT
      Set Qtd_FisDep = Qtd_FisDep + Abs(Qtd_SldDep)
    Where Cod_Estabe = @PCodEstabe
    And Cod_Produt = @PCodPrd
    And Qtd_SldDep < 0
  end
  
-- garante bloqueio do registro
Update PRXES
  Set Qtd_Solici = 0
Where Cod_Estabe = @PCodEstabe 
And Cod_Produt = @PCodPrd
And Qtd_Solici < 0

Update PRXES
  Set Qtd_PrmSolici = 0
Where Cod_Estabe = @PCodEstabe 
And Cod_Produt = @PCodPrd
And Qtd_PrmSolici < 0
  
Update PRXES
  Set Qtd_Solici = Qtd_Solici + 0
Where Cod_Estabe = @PCodEstabe
And Cod_Produt = @PCodPrd

Declare @CodDep smallint,
        @QtdPedAju int,
        @QtdBonAju int,
        @FatBon numeric(18,4),
        @PedSol int,
        @BonSol int,
        @LotAux varchar(20),
        @LotAlt varchar(20),
        @CodLotEsp varchar(20),  -- lote especifico
        @lt_LocEst varchar(1),
        @lt_DatVct smalldatetime,
        @lt_CodLot varchar(20),
        @lt_SldLot int,
        @AccQtdAte int,
        @AccBonAte int,
        @QtdDsp int,
		@QtdLotDsp int,
        @QtdDspPrd int,
        @QtdDspLot int,
        @QtdDspPrm int,
        @QtdEmbFec int,
        @FlgPrdForLin bit,
        @PerQtp numeric(18,4),
        @PerQtpAcu numeric(18,4),
        @pm_FlgPerCmpEst bit,
        @to_CodCfoNorInt int,
		@cl_CodCliPag int,
		@cl_QtdMesMinPrzVctLot int,
        @CodMtvRej varchar(3),
        @QtdSolPrdIni int,
        @WAccQtdTot int,
        @WQtdPra int,
        @WQtdDep int
        
-- sem WMS: deposito unico
Set @CodDep = IsNull((Select min(Cod_Dep) 
                        From TBDEP 
                       Where Cod_Estabe = @PCodEstabe),1)

-- coloca campos de tabela na memoria
Select @pm_FlgPerCmpEst = Isnull(FlgPerCmpEst,0)
From PARAM
Where Cod_Estabe = @PCodEstabe
  
Select @to_CodCfoNorInt = t.Cod_CfoNorInt
From TPOPE t 
     Inner Join PDVCB p on (t.Cod_Ope = p.Tip_Faturamento)
Where p.Cod_Estabe = @PCodEstabe
And p.Numero = @PCodPed

Select @cl_CodClipag = IsNull(cl.Cod_CliPag,0),
       @cl_QtdMesMinPrzVctLot = IsNull(Qtd_MesMinPrzVctLot,0)
From PDVCB cb
     Left Outer Join CLIEN cl on (cb.Cod_Cliente = cl.Codigo)
Where cb.Cod_Estabe = @PCodEstabe
And cb.Numero = @PCodPed

-- variaveis para salvar valores iniciais do pedido para serem usados qdo incluir uma nova linha (lote)
Declare @it_LocFis varchar(15), 
        @it_CodFab int, 
        @it_PerDsc numeric(18,4), 
        @it_PrcUni numeric(18,8), 
        @it_PrcTab numeric(18,4), 
        @it_PrcTabBru numeric(18,4), 
        @it_FlgPrcUniDsc bit, 
        @it_PrzMax int, 
        @it_DscPrz numeric(18,4), 
        @it_DscVis numeric(18,4),
        @it_QtdSol int,
        @it_PrcMaxCon numeric(18,4), 
        @it_PrcFab numeric(18,4), 
        @it_NumSeqDig int,
        @it_NomUsuDbq varchar(15),
        @it_DesUnvImpFat char(3),
        @it_DesAprImpFat varchar(12),
        @it_IdPolCom int,
        @it_FlgVerba bit, 
        @it_PrcPolCom numeric(18,8), 
        @it_PerDscPolCom numeric(18,4), 
        @it_PerDscVisPolCom numeric(18,4),
        @it_QtdPrzPolCom int,
        @it_FlgPolPrm bit,
        @it_PrcUniLiqPer numeric(18,4),
        @it_PrcLiqUltEnt numeric(18,4),
        @it_PrcRefFpb numeric(18,4),
        @it_PrcUniPde numeric(18,4), 
        @it_PerDscPde numeric(18,4), 
        @it_CodPrjPde varchar(12),
        @it_NumSeqPdc varchar(6),
        @it_PerVrbPar numeric(18,4), 
        @it_PerVrbBon numeric(18,4), 
        @it_VlrBonificacao numeric(18,4),
        @it_VlrDscBonRat numeric(18,4),
        @it_PrcCusMinComMarkup numeric(18,4),
        @it_VlrBasVerba numeric(18,4),
        @IdPolLot int   -- politica com lote especifico

        
Select @it_LocFis = it.Loc_Fisica,
       @it_CodFab = it.Cod_Fabricante,
       @it_QtdSol = IsNull(it.Qtd_Solicitado,0),
       @it_PerDsc = it.Per_Desconto,
       @it_PrcUni = it.Prc_Unitario,
       @it_PrcTab = it.Prc_Tabela,
       @it_PrcTabBru = it.Prc_TabBru,
       @it_FlgPrcUniDsc = it.Flg_PrcUniDsc,
       @it_PrzMax = it.Qtd_PrzMax,
       @it_DscPrz = it.Per_Descon,
       @it_DscVis = it.Per_DscVis,
       @it_PrcMaxCon = it.Prc_MaxCon,
       @it_PrcFab = it.Prc_Fabric,
       @it_NumSeqDig = it.Num_SeqDig,
       @it_NomUsuDbq = it.Nom_UsuDesbloq,
       @it_DesUnvImpFat = it.Des_UnvImpFat,
       @it_DesAprImpFat = it.Des_AprImpFat,
       @it_IdPolCom = it.Id_PolCom,
       @IdPolLot = Case
                     When Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = it.Cod_Estabe and pl.Id_PolCom = it.Id_PolCom and pl.Cod_Produt = it.Cod_Produto) then it.Id_PolCom
                     Else 0
                   End,
       @it_FlgVerba = IsNull(it.Flg_Verba,0), 
       @it_PrcPolCom = it.Prc_PolCom, 
       @it_PerDscPolCom = it.Per_DscPolCom, 
       @it_PerDscVisPolCom = it.Per_DscVisPolCom,
       @it_QtdPrzPolCom = it.Qtd_PrzPolCom,
       @it_FlgPolPrm = ISNULL(it.Flg_PolPrm,0),
       @it_PrcUniLiqPer = it.Prc_UniLiqPer,
       @it_PrcLiqUltEnt = it.Prc_LiqUltEnt,
       @it_PrcRefFpb = it.Prc_RefFpb,
       @it_CodPrjPde = it.Cod_PrjPde,
       @it_PerDscPde = it.Per_DscPde,
       @it_PrcUniPde = it.Prc_UniPde,
       @it_NumSeqPdc = it.Num_SeqPdc,
       @it_PerVrbPar = IsNull(it.Per_VrbPar,0), 
       @it_PerVrbBon = IsNull(it.Per_VrbBon,0), 
       @it_VlrBonificacao = ISNULL(it.Vlr_Bonificacao,0),
       @it_VlrDscBonRat = ISNULL(it.Vlr_DscBonRat,0),
       @it_PrcCusMinComMarkup = ISNULL(it.Prc_CusMinComMarkup,0),
       @it_VlrBasVerba = ISNULL(it.Vlr_BasVerba,0)
From PDVIT it
Where it.Cod_Estabe = @PCodEstabe 
And it.Cod_Pedido = @PCodPed 
And it.Cod_Produto = @PCodPrd 
And it.Cod_Lote = @PCodLot
And it.Tip_Sai = @PTipSai

if @it_QtdSol = 0
  Set @it_QtdSol = @PQtdPed + @PQtdBon

-- exclui o regitro de origem
Delete From PDVIT
Where Cod_Estabe = @PCodEstabe 
And Cod_Pedido = @PCodPed 
And Cod_Produto = @PCodPrd 
And Cod_Lote = @PCodLot
And Tip_Sai = @PTipSai

Set @AccQtdAte = 0
Set @AccBonAte = 0

Set @QtdDspLot = (Select sum(IsNull(Qtd_Saldo,0)) From PRLOT Where Cod_Estabe = @PCodEstabe And Qtd_Saldo > 0 And Cod_Produt = @PCodPrd)

Select @FlgPrdForLin = Case 
                         When Flag_ImprClassif1 = 'N' then 1 
                         Else 0 
                       End, 
       @QtdEmbFec = IsNull(Qtd_Embalagem,1)
From PRODU 
Where Codigo = @PCodPrd

if @QtdEmbFec = 0
  Set @QtdEmbFec = 1

Select @QtdDspPrd = dbo.FN_EstoqueDisponivelPrd(Cod_Estabe,Cod_Produt),
       @QtdSolPrdIni = ISNULL(Qtd_Solici,0),
       @QtdDspPrm = IsNull(Qtd_PrmDispon,0)
From PRXES 
Where Cod_Estabe = @PCodEstabe 
And Cod_Produt = @PCodPrd

if IsNull(@QtdDspLot,0) < IsNull(@QtdDspPrd,0)
  Set @QtdDsp = IsNull(@QtdDspLot,0)
else
  Set @QtdDsp = IsNull(@QtdDspPrd,0)
  
-- verifica estoque disponivel para promocao
if (@PCodPrm > 0) and 
   (Charindex((Select Substring(Cod_OrigemPdv,1,1) From PDVCB Where Cod_Estabe = @PCodEstabe And Numero = @PCodPed),';M;T;W;') > 0) 
  if IsNull((Select Flg_BlqCtrQtdPrm From PRMCB Where Codigo = @PCodPrm),0) = 0
    begin
      if @QtdDspPrm < 0 
        Set @QtdDspPrm = 0 
      if @QtdDspPrm < @QtdDsp
        Set @QtdDsp = @QtdDspPrm
    end
  
Set @lt_CodLot = '*'  
Set @CodMtvRej = ''

Set @QtdLotDsp = dbo.FN_QtdLoteDisponivel (@PCodEstabe, @cl_CodCliPag, @PCodPrd, @Date, @cl_QtdMesMinPrzVctLot, @IdPolLot)

-- verifica se existe lote para atendimento
if (@QtdDsp > 0) and (@QtdLotDsp = 0)
  begin
    Set @QtdDsp = 0
    Set @CodMtvRej = 'LT-'
  end

if @QtdLotDsp < @QtdDsp 
  Set @QtdDsp = @QtdLotDsp

if @QtdDsp > 0
  begin
    -- acumulador total de solicitacoes do produto
    Set @WAccQtdTot = 0

    if @PQtdPed+@PQtdBon > 0 
      Set @PerQtp = @PQtdPed*100/(@PQtdPed+@PQtdBon)
    else
      Set @PerQtp = 0

    -- ajusta quantidades conforme estoque disponivel
    Set @QtdPedAju = @PQtdPed
    Set @QtdBonAju = @PQtdBon
    if @QtdDsp < (@PQtdPed+@PQtdBon)
      begin
        if @PQtdBon > 0
          begin
            Set @FatBon = @PQtdBon*1.0/@PQtdPed*1.0
            Set @QtdBonAju = @FatBon*@QtdDsp/(1+@FatBon+0.05)
            Set @QtdPedAju = @QtdBonAju/@FatBon
          end
        else
          Set @QtdPedAju = @QtdDsp
      end

    -- inclui novo(s) registro(s) conforme disponibilidade dos lotes
    -- solicita lote especifico ou pelo vencimento
	if @PFlgLotEsp = 1
	  Set @CodLotEsp = @PCodLot
	else
	  Set @CodLotEsp = ''

    -- solicita lote por vencimento
    if @to_CodCfoNorInt > 0
      begin
        -- venda FAT
		if @pm_FlgPerCmpEst = 0  
          begin
            Declare PRLOT_Cr Cursor Local Fast_Forward For
              Select '1' as CodLocEst, lt.Dat_Vencim, lt.Cod_Lote, 
                     SldLot = Case 
                                When @PFlgLotNaoFra = 1 Then lt.Qtd_SldPra/@QtdEmbFec*@QtdEmbFec
                                Else lt.Qtd_SldPra 
                              End  
              From PRLOT lt Inner Join
                   PRODU pr on pr.Codigo = lt.Cod_Produt Left Outer Join
                   CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                   CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
              Where lt.Cod_Estabe = @PCodEstabe
              And lt.Cod_Dep = @CodDep
              And lt.Cod_Produt = @PCodPrd 
              And ( ((@PFlgLotEsp = 1) and (lt.Cod_Lote  = @CodLotEsp)) or 
                    ((@PFlgLotEsp = 0) and (lt.Cod_Lote <> @CodLotEsp)) )
              And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                          (lt.Dat_Vencim >= Case
                                                              When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                              When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                              Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                            End))) or
                    ((@IdPolLot > 0) and 
                     Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
              And lt.Qtd_Saldo > 0 
              And lt.Qtd_SldPra > 0
              Order by CodLocEst, lt.Dat_Vencim
          end
        else
          begin
            -- compartilha estoque
            Declare PRLOT_Cr Cursor Local Fast_Forward For 
              Select lt.CodLocEst, lt.Dat_Vencim, lt.Cod_Lote, lt.SldLot
              From ( Select '1' as CodLocEst, l1.Cod_Estabe, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote,
                            SldLot = Case 
                                       When @PFlgLotNaoFra = 1 Then l1.Qtd_SldPra/@QtdEmbFec*@QtdEmbFec
                                       Else l1.Qtd_SldPra 
                                     End  
                     From PRLOT l1 
                     Where l1.Cod_Estabe = @PCodEstabe
                     And l1.Cod_Dep = @CodDep
                     And l1.Cod_Produt = @PCodPrd 
                     And l1.Qtd_Saldo > 0 
                     And l1.Qtd_SldPra > 0
                     Union
                     Select '2' as CodLocEst, l2.Cod_Estabe, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                            SldLot = Case 
                                       When @PFlgLotNaoFra = 1 Then l2.Qtd_SldDep/@QtdEmbFec*@QtdEmbFec
                                      Else l2.Qtd_SldDep 
                                     End  
                     From PRLOT l2 
                     Where l2.Cod_Estabe = @PCodEstabe
                     And l2.Cod_Dep = @CodDep
                     And l2.Cod_Produt = @PCodPrd 
                     And l2.Qtd_Saldo > 0 
                     And l2.Qtd_SldDep > 0 ) lt Inner Join
                   PRODU pr on pr.Codigo = lt.Cod_Produt Left Outer Join
                   CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                   CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
              Where 1 = 1
              And ( ((@PFlgLotEsp = 1) and (lt.Cod_Lote  = @CodLotEsp)) or 
                    ((@PFlgLotEsp = 0) and (lt.Cod_Lote <> @CodLotEsp)) )
              And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                          (lt.Dat_Vencim >= Case
                                                              When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                              When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                              Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                            End))) or
                    ((@IdPolLot > 0) and 
                     Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
              Order by lt.CodLocEst, lt.Dat_Vencim
          end
      end
    else
      begin
        -- venda ORC
        if @pm_FlgPerCmpEst = 0
          begin
            Declare PRLOT_Cr Cursor Local Fast_Forward For
              Select '2' as CodLocEst, lt.Dat_Vencim, lt.Cod_Lote,
                     SldLot = Case 
                                When @PFlgLotNaoFra = 1 Then Qtd_SldDep/@QtdEmbFec*@QtdEmbFec
                                Else lt.Qtd_SldDep 
                              End  
              From PRLOT lt Inner Join
                   PRODU pr on pr.Codigo = lt.Cod_Produt Left Outer Join
                   CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                   CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
              Where lt.Cod_Estabe = @PCodEstabe
              And lt.Cod_Dep = @CodDep
              And lt.Cod_Produt = @PCodPrd 
              And ( ((@PFlgLotEsp = 1) and (lt.Cod_Lote  = @CodLotEsp)) or 
                    ((@PFlgLotEsp = 0) and (lt.Cod_Lote <> @CodLotEsp)) )
              And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                          (lt.Dat_Vencim >= Case
                                                              When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                              When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                              Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                            End))) or
                    ((@IdPolLot > 0) and 
                     Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
              And lt.Qtd_Saldo > 0 
              And lt.Qtd_SldDep > 0
              Order by CodLocEst, lt.Dat_Vencim
          end
        else
          begin
            -- compartilha estoque
            Declare PRLOT_Cr Cursor Local Fast_Forward For
              Select lt.CodLocEst, lt.Dat_Vencim, lt.Cod_Lote, lt.SldLot
              From ( Select '2' as CodLocEst, l2.Cod_Estabe, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote,
                            SldLot = Case 
                                       When @PFlgLotNaoFra = 1 Then l2.Qtd_SldDep/@QtdEmbFec*@QtdEmbFec
                                       Else l2.Qtd_SldDep 
                                     End  
                     From PRLOT l2
                     Where l2.Cod_Estabe = @PCodEstabe
                     And l2.Cod_Dep = @CodDep
                     And l2.Cod_Produt = @PCodPrd 
                     And l2.Qtd_Saldo > 0 
                     And l2.Qtd_SldDep > 0
                     Union
                     Select '1' as CodLocEst, l1.Cod_Estabe, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote,
                            SldLot = Case 
                                       When @PFlgLotNaoFra = 1 Then l1.Qtd_SldPra/@QtdEmbFec*@QtdEmbFec
                                       Else l1.Qtd_SldPra 
                                     End  
                     From PRLOT l1 
                     Where l1.Cod_Estabe = @PCodEstabe
                     And l1.Cod_Dep = @CodDep
                     And l1.Cod_Produt = @PCodPrd 
                     And l1.Qtd_Saldo > 0 
                     And l1.Qtd_SldPra > 0 ) lt Inner Join
                   PRODU pr on pr.Codigo = lt.Cod_Produt Left Outer Join
                   CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                   CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
              Where 1 = 1
              And ( ((@PFlgLotEsp = 1) and (lt.Cod_Lote  = @CodLotEsp)) or 
                    ((@PFlgLotEsp = 0) and (lt.Cod_Lote <> @CodLotEsp)) )
              And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                          (lt.Dat_Vencim >= Case
                                                              When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                              When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                              Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                            End))) or
                    ((@IdPolLot > 0) and 
                     Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
              Order by lt.CodLocEst desc, lt.Dat_Vencim
          end
      end

    Open PRLOT_Cr
    Fetch Next From PRLOT_Cr Into @lt_LocEst, @lt_DatVct, @lt_CodLot, @lt_SldLot 

    While (@AccQtdAte+@AccBonAte < @QtdPedAju+@QtdBonAju) and (@@FETCH_STATUS = 0)
      begin
        Set @PedSol = @QtdPedAju - @AccQtdAte
        Set @BonSol = @QtdBonAju - @AccBonAte

        -- se o saldo do lote nao atender a qtd.solicitada refazer a solicitacao proporcionalmente
        if @PedSol+@BonSol > @lt_SldLot
          begin
            Set @PedSol = Round(@lt_SldLot*@PerQtp/100,0)
            Set @BonSol = @lt_SldLot-@PedSol
          end

        -- garante as quantidades solicitadas
        if (@PedSol = 0) or ((@AccQtdAte+@PedSol) > @QtdPedAju) or ((@AccBonAte+@BonSol) > @QtdBonAju)
          Break

        -- Atualiza saldo do lote
        Set @WQtdPra = 0
        Set @WQtdDep = 0
        
        if @lt_LocEst = '1'
          begin
            Update PRLOT
              Set Qtd_SolPra = Qtd_SolPra + @PedSol + @BonSol
            Where Cod_Estabe = @PCodEstabe
            And Cod_Dep = @CodDep
            And Cod_Produt = @PCodPrd
            And Cod_Lote = @lt_CodLot
            Set @WQtdPra = @PedSol + @BonSol
            Set @WAccQtdTot = @WAccQtdTot + @WQtdPra
          end
        else
          begin
            Update PRLOT
              Set Qtd_SolDep = Qtd_SolDep + @PedSol + @BonSol
            Where Cod_Estabe = @PCodEstabe
            And Cod_Dep = @CodDep
            And Cod_Produt = @PCodPrd
            And Cod_Lote = @lt_CodLot
            Set @WQtdDep = @PedSol + @BonSol
            Set @WAccQtdTot = @WAccQtdTot + @WQtdDep
          end
       
        -- incrementa saldo solicitado em PRXES
        Update PRXES 
          Set Qtd_Solici = Qtd_Solici + @PedSol + @BonSol
        Where Cod_Estabe = @PCodEstabe
        And Cod_Produt = @PCodPrd
      
        Update PRXES
          Set Qtd_PrmSolici = Qtd_PrmSolici + @PedSol + @BonSol
        Where Cod_Estabe = @PCodEstabe
        And Cod_Produt = @PCodPrd 
        And IsNull(@PCodPrm,0) > 0


        Set @AccQtdAte = @AccQtdAte + @PedSol
        Set @AccBonAte = @AccBonAte + @BonSol

        -- atualiza qtd atendida e o lote ativo
        if Exists(Select Cod_Produto From PDVIT 
                  Where Cod_Estabe = @PCodEstabe
                  And Cod_Pedido = @PCodPed 
                  and Cod_Produto = @PCodPrd 
                  and Cod_Lote = @lt_CodLot
                  and Tip_Sai = @PTipSai)
          begin
            Update PDVIT
              Set Qtd_Pedido = Qtd_Pedido + @PedSol,
                  Qtd_Bonificacao = Qtd_Bonificacao + @BonSol,
                  Qtd_Solicitado = Qtd_Solicitado + @PedSol + @BonSol,
                  Qtd_Pra = Qtd_Pra + @WQtdPra,
                  Qtd_Dep = Qtd_Dep + @WQtdDep   
            Where Cod_Estabe = @PCodEstabe
            and Cod_Pedido = @PCodPed 
            and Cod_Produto = @PCodPrd 
            and Cod_Lote = @lt_CodLot
            and Tip_Sai = @PTipSai
          end
        else
          begin
            Insert into PDVIT (Cod_Estabe, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai, Qtd_Pedido, Qtd_Bonificacao, Loc_Fisica, Cod_Fabricante, 
                               Cod_Promocao, Cod_KitPrm, Per_Desconto, Prc_Unitario, Qtd_PrzMax, Per_Descon, Per_DscVis, 
                               Qtd_Solicitado, Flg_PrcUniDsc, Prc_Tabela, Prc_TabBru, Qtd_Pra, Qtd_Dep, Prc_MaxCon, Prc_Fabric,
                               Num_SeqDig, Nom_UsuDesbloq, Des_UnvImpFat, Des_AprImpFat, 
                               Id_PolCom, Flg_Verba, Prc_PolCom, Per_DscPolCom, Per_DscVisPolCom,
                               Qtd_PrzPolCom, Flg_PolPrm, Prc_UniLiqPer, Prc_LiqUltEnt, Prc_RefFpb,
                               Cod_PrjPde, Prc_UniPde, Per_DscPde, Num_SeqPdc, Per_VrbPar, Per_VrbBon,
                               Vlr_Bonificacao, Vlr_DscBonRat, Prc_CusMinComMarkup, Vlr_BasVerba)
                       
                       Values (@PCodEstabe, @PCodPed, @PCodPrd, @lt_CodLot, @PTipSai, @PedSol, @BonSol, @it_LocFis, @it_CodFab, 
                               @PCodPrm, @PCodKitPrm, @it_PerDsc, @it_PrcUni, @it_PrzMax, @it_DscPrz, @it_DscVis, 
                               @PedSol+@BonSol, @it_FlgPrcUniDsc, @it_PrcTab, @it_PrcTabBru, @WQtdPra, @WQtdDep, @it_PrcMaxCon, @it_PrcFab,
                               @it_NumSeqDig, @it_NomUsuDbq, @it_DesUnvImpFat, @it_DesAprImpFat, 
                               @it_IdPolCom, @it_FlgVerba, @it_PrcPolCom, @it_PerDscPolCom, @it_PerDscVisPolCom,
                               @it_QtdPrzPolCom, @it_FlgPolPrm, @it_PrcUniLiqPer, @it_PrcLiqUltEnt, @it_PrcRefFpb,
                               @it_CodPrjPde, @it_PrcUniPde, @it_PerDscPde, @it_NumSeqPdc, @it_PerVrbPar, @it_PerVrbBon,
                               @it_VlrBonificacao, @it_VlrDscBonRat, @it_PrcCusMinComMarkup, @it_VlrBasVerba)
          if @@error <> 0
              begin
                Rollback Transaction
                Return
              end
          end

        -- decrementa quantidade solicitada inicial
        Set @it_QtdSol = @it_QtdSol - @PedSol - @BonSol
        Set @LotAlt = @lt_CodLot

        -- normaliza valores
        Update PDVIT
          Set Qtd_ImpFat = (Qtd_Pedido+Qtd_Bonificacao)*1.0/@PFatCnvImpFat,
              Fat_CnvImpFat = @PFatCnvImpFat,
              Prc_UniImpFat = Prc_Unitario * @PFatCnvImpFat
        Where Cod_Estabe = @PCodEstabe
        and Cod_Pedido = @PCodPed 
        And Cod_Produto = @PCodPrd 
        And Cod_Lote = @lt_CodLot
        And Tip_Sai = @PTipSai

        -- calcula tributos      
        EXEC PR_CalcTributPdvit @PCodEstabe, @PCodPed, @PCodPrd, @lt_CodLot, @PTipSai
        if @@error <> 0
          begin
            Rollback Transaction
            Return
          end

        Fetch Next From PRLOT_Cr Into @lt_LocEst, @lt_DatVct, @lt_CodLot, @lt_SldLot 
      end
    Close PRLOT_Cr
    Deallocate PRLOT_Cr

    -- verifica bonificacao
    if @PQtdBon > 0
      begin
        if @AccQtdAte + @AccBonAte > 0 
          Set @PerQtpAcu = @AccQtdAte*100/(@AccQtdAte+@AccBonAte)
        else
          Set @PerQtpAcu = 0
        if Round(@PerQtpAcu*100,0) <> Round(@PerQtp*100,0)
          begin
            Set @AccQtdAte = 0
            Set @AccBonAte = 0
--            Rollback Transaction A 
            Rollback Transaction 
            Return
          end
      end

/*    
    -- incrementa saldo solicitado
    Update PRXES 
      Set Qtd_Solici = Qtd_Solici + @AccQtdAte + @AccBonAte
    Where Cod_Estabe = @PCodEstabe
    And Cod_Produt = @PCodPrd
      
    Update PRXES
      Set Qtd_PrmSolici = Qtd_PrmSolici + @AccQtdAte + @AccBonAte
    Where Cod_Estabe = @PCodEstabe
    And Cod_Produt = @PCodPrd 
    And IsNull(@PCodPrm,0) > 0
*/
  end

-- registra faltas
if @AccQtdAte+@AccBonAte < @PQtdPed+@PQtdBon
  begin
    Set @LotAux = '*'
    Set @LotAux = @lt_CodLot
        
    if @CodMtvRej = ''
      if @QtdDsp > 0
        Set @CodMtvRej = 'ES-'   -- estoque insuficiente
      else
      if @FlgPrdForLin = 1
        Set @CodMtvRej = 'PR-'   -- produto descontinuado
      else
        Set @CodMtvRej = 'ES0'   -- estoque zero
    
    if Exists(Select Cod_Produto From PDVIT Where Cod_Estabe = @PCodEstabe and Cod_Pedido = @PCodPed and Cod_Produto = @PCodPrd and Cod_Lote = @LotAux and Tip_Sai = @PTipSai)
      begin
        Update PDVIT
          Set Qtd_Solicitado = Qtd_Solicitado + @PQtdPed + @PQtdBon - @AccQtdAte - @AccBonAte,
              Cod_MtvRej = @CodMtvRej
        Where Cod_Estabe = @PCodEstabe
        and Cod_Pedido = @PCodPed 
        and Cod_Produto = @PCodPrd 
        and Cod_Lote = @LotAux
        and Tip_Sai = @PTipSai
      end
    else
      begin
        Insert into PDVIT (Cod_Estabe, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai, Qtd_Pedido, Qtd_Bonificacao, Loc_Fisica, Cod_Fabricante, 
                           Cod_Promocao, Cod_KitPrm, Per_Desconto, Prc_Unitario, Qtd_PrzMax, Per_Descon, Per_DscVis, 
                           Qtd_Solicitado, Flg_PrcUniDsc, Prc_Tabela, Prc_TabBru, Qtd_Pra, Qtd_Dep,
                           Prc_MaxCon, Prc_Fabric, Num_SeqDig, Nom_UsuDesbloq, Des_UnvImpFat, Des_AprImpFat,
                           Id_PolCom, Flg_Verba, Prc_PolCom, Per_DscPolCom, Per_DscVisPolCom, Cod_MtvRej,
                           Qtd_PrzPolCom, Flg_PolPrm, Prc_UniLiqPer, Prc_LiqUltEnt, Prc_RefFpb,
                           Cod_PrjPde, Prc_UniPde, Per_DscPde, Num_SeqPdc, Per_VrbPar, Per_VrbBon,
                           Vlr_Bonificacao, Vlr_DscBonRat, Prc_CusMinComMarkup, Vlr_BasVerba)
                           
                   Values (@PCodEstabe, @PCodPed, @PCodPrd, @LotAux, @PTipSai, 0, 0, @it_LocFis, @it_CodFab, 
                           @PCodPrm, @PCodKitPrm, @it_PerDsc, @it_PrcUni, @it_PrzMax, @it_DscPrz, @it_DscVis, 
                           @PQtdPed+@PQtdBon-@AccQtdAte-@AccBonAte, @it_FlgPrcUniDsc, @it_PrcTab, @it_PrcTabBru, 0, 0,
                           @it_PrcMaxCon, @it_PrcFab, @it_NumSeqDig, @it_NomUsuDbq, @it_DesUnvImpFat, @it_DesAprImpFat,
                           @it_IdPolCom, @it_FlgVerba, @it_PrcPolCom, @it_PerDscPolCom, @it_PerDscVisPolCom, @CodMtvRej,
                           @it_QtdPrzPolCom, @it_FlgPolPrm, @it_PrcUniLiqPer, @it_PrcLiqUltEnt, @it_PrcRefFpb,
                           @it_CodPrjPde, @it_PrcUniPde, @it_PerDscPde, @it_NumSeqPdc, @it_PerVrbPar, @it_PerVrbBon,
                           @it_VlrBonificacao, @it_VlrDscBonRat, @it_PrcCusMinComMarkup, @it_VlrBasVerba)
                           
        if @@error <> 0
          begin
            Rollback Transaction
            Return
          end
      end

    -- decrementa quantidade solicitada inicial
    Set @it_QtdSol = @it_QtdSol - @PQtdPed - @PQtdBon + @AccQtdAte + @AccBonAte
    Set @LotAlt = @LotAux

    -- normaliza valores
    Update PDVIT
      Set Qtd_ImpFat = (Qtd_Pedido+Qtd_Bonificacao)*1.0/@PFatCnvImpFat,
          Fat_CnvImpFat = @PFatCnvImpFat,
          Prc_UniImpFat = Prc_Unitario * @PFatCnvImpFat
    Where Cod_Estabe = @PCodEstabe
    And Cod_Pedido = @PCodPed 
    And Cod_Produto = @PCodPrd 
    And Cod_Lote = @LotAux
    And Tip_Sai = @PTipSai

    -- calcula tributos      
    EXEC PR_CalcTributPdvit @PCodEstabe, @PCodPed, @PCodPrd, @LotAux, Tip_Sai
    if @@error <> 0
      begin
        Rollback Transaction
        Return
      end

  end

-- ajusta quantidade solicitada
if @it_QtdSol < 0
  Set @it_QtdSol = 0
if @it_QtdSol > 0 
  begin
    Update PDVIT
      Set Qtd_Solicitado = Qtd_Solicitado + @it_QtdSol
    Where Cod_Estabe = @PCodEstabe
    and Cod_Pedido = @PCodPed 
    And Cod_Produto = @PCodPrd 
    And Cod_Lote = @LotAlt
    And Tip_Sai = @PTipSai
  end

if (@QtdSolPrdIni + @WAccQtdTot) <>
   IsNull((Select IsNull(Qtd_Solici,0) From PRXES Where Cod_Estabe = @PCodEstabe And Cod_Produt = @PCodPrd),0) 
  begin
    RAISERROR('Erro na solicitação do Produto',16,1)
    Rollback Transaction
  end  
else
  Commit Transaction

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE TRIGGER [dbo].[TR_PDVIT_CalculaTributos] ON [dbo].[PDVIT] 
FOR INSERT, UPDATE, DELETE 
NOT FOR REPLICATION
AS

-- comando p/ corrigir erro delphi/ado: record was changed by another user
SET NOCOUNT ON 

/*
SET CONTEXT_INFO 0x31415161345234625623046972340597854029752304523067825672039782364082

if (SELECT CONTEXT_INFO()) = 0x31415161345234625623046972340597854029752304523067825672039782364082
  RETURN
*/

Declare @CodEstabe int,
        @CodPed int,
        @IdConsig int = 0,
        @NumSeqCtr int = 0,
        @CodPrd int,
        @CodLot varchar(20),
        @TipSai varchar(1),
        @CodPrm int,
        @CodKitPrm int,
        @QtdPed int,
        @QtdBon int,
        @QtdPra int,
        @QtdDep int,
        @FatCnvImpFat int,
        @TipPed varchar(1),
        @StaPdv1 varchar(1),
        @StaPdv2 varchar(1),
        @TipBlq varchar(2),
        @NumPrtOri int,            -- numero do protocolo de origem se pedido foi gerado por uma NFE
        @CodOriPed varchar(2),
        @FlgCal bit,
        @FlgCalAnt bit,
        @FlgLotEsp bit,    -- lote especifico
        @FlgAltQtd bit,
        @FlgAltPrc bit,
        @FlgWms bit,
        @FlgCriIteFec bit,
        @FlgLotNaoFra bit,
        @FlgTemPDVLT bit,
        @CodGrpCli int,
        @CodCliPag int,
		@QtdMesMinPrzVctLot int

Set @FlgAltQtd = 0
Set @FlgAltPrc = 0

if Update(Qtd_Pedido) or Update(Qtd_Bonificacao) or Update(Id_PolCom)
  Set @FlgAltQtd = 1
  
if (@FlgAltQtd = 0) and ((Select Count(*) from Deleted) > 0) and ((Select Count(*) from Inserted) = 0)
  Set @FlgAltQtd = 1

if (@FlgAltQtd = 0) and ((Select Count(*) from Inserted) > 0) and ((Select Count(*) from Deleted) = 0)
  Set @FlgAltQtd = 1
  
if Update(Prc_Unitario) or Update(Per_Desconto) or Update(Per_Descon) or Update(Per_DscVis)
  Set @FlgAltPrc = 1

if (Select Count(*) from Deleted) > 0
  begin
    Select @TipPed    = IsNull(Ltrim(Rtrim(cb.Tip_Pedido)),''),
           @StaPdv1   = IsNull(Ltrim(Rtrim(cb.Status1)),''),
           @StaPdv2   = IsNull(Ltrim(Rtrim(cb.Status2)),''),
           @TipBlq    = IsNull(Ltrim(Rtrim(cb.Bloqueio)),''),
           @NumPrtOri = IsNull(cb.Num_PrtOri,0),
           @FlgCal    = IsNull(cb.Flg_Calc,0),
           @FlgWms    = IsNull(cb.Flg_Wms,0),
           @IdConsig  = IsNull(cb.Id_Consig,0),
           @NumSeqCtr = IsNull(cb.Num_SequenciaCtr,0)
      From PDVCB cb Inner Join 
           Deleted d on cb.Cod_Estabe = d.Cod_Estabe And cb.Numero = d.Cod_Pedido

    if @FlgCal = 0
      begin
        DECLARE Deleted_Cr CURSOR Local Fast_Forward For
          Select d.Cod_Estabe, d.Cod_Pedido,
                 d.Cod_Produto, d.Cod_Lote,
                 d.Tip_Sai, IsNull(d.Cod_Promocao,0), 
                 IsNull(d.Qtd_Pedido,0), IsNull(d.Qtd_Bonificacao,0),
                 IsNull(d.Qtd_Pra,0), IsNull(d.Qtd_Dep,0)
            From Deleted d
           Order by d.Cod_Produto
        OPEN Deleted_Cr
        FETCH NEXT FROM Deleted_Cr INTO @CodEstabe, @CodPed,
                                        @CodPrd, @CodLot,
                                        @TipSai, @CodPrm,
                                        @QtdPed, @QtdBon,
                                        @QtdPra, @QtdDep
        WHILE @@FETCH_STATUS = 0
        BEGIN
          -- decrementa quantidades solicitadas
          -- esta rotina nao eh executada qdo se exclui o cab. do pedido e a trigger de PDVCB executa rotina que exclui itens em PDVIT (o cab. nao existe mais)
          if (@QtdPra+@QtdDep) <> (@QtdPed+@QtdBon)
            begin
              Set @QtdPra = @QtdPed + @QtdBon - @QtdDep
            end
          if @FlgAltQtd = 1
            if @FlgWms = 0
              EXEC PR_DecrementaSaldoSolicitado @CodEstabe, @TipPed, @StaPdv1, @StaPdv2, @TipBlq, @NumPrtOri,
                                                @CodPrd, @CodLot, @CodPrm, @QtdPra, @QtdDep
            else
              begin
                EXEC PR_DecrementaSaldoSolicitado_PRODU @CodEstabe, @TipPed, @StaPdv1, @StaPdv2, @TipBlq, @CodPrd, @CodPrm, @QtdPra, @QtdDep, 0
              end  

          FETCH NEXT FROM Deleted_Cr INTO @CodEstabe, @CodPed,
                                          @CodPrd, @CodLot,
                                          @TipSai, @CodPrm,
                                          @QtdPed, @QtdBon,
                                          @QtdPra, @QtdDep
        END

        CLOSE Deleted_Cr
        DEALLOCATE Deleted_Cr           
      end       
  end

if (Select Count(*) from Inserted) > 0
  begin
    Select @TipPed = IsNull(Ltrim(Rtrim(cb.Tip_Pedido)),''),
           @TipBlq = IsNull(Ltrim(Rtrim(cb.Bloqueio)),''),
           @CodOriPed = IsNull(cb.Cod_OrigemPdv,''),
           @FlgCal = IsNull(cb.Flg_Calc,0),
           @FlgWms = IsNull(cb.Flg_Wms,0),
           @CodGrpCli = IsNull(cb.Cod_GrpCli,0),
		   @CodCliPag = IsNull(cl.Cod_CliPag,0),
		   @QtdMesMinPrzVctLot = IsNull(cl.Qtd_MesMinPrzVctLot,0),
           @FlgCriIteFec = IsNull(cb.Flg_CriIteFec,0),
           @FlgLotEsp = Case 
                          When IsNull(cb.Num_Referencia,0)+IsNull(cb.Num_PrtOri,0) > 0 Then 1 
                          Else 0 
                        End,
           @FlgLotNaoFra = Case
                             When (IsNull(cb.Cod_Contrato,0) > 0) and (CharIndex(cb.Tip_Consumidor,'PEM') > 0) Then 1
                             Else 0
                           End,

           @IdConsig  = IsNull(cb.Id_Consig,0),
           @NumSeqCtr = IsNull(cb.Num_SequenciaCtr,0)
      From PDVCB cb Left Outer Join
	       CLIEN cl on cb.Cod_Cliente = cl.Codigo Inner Join 
           Inserted i on cb.Cod_Estabe = i.Cod_Estabe And cb.Numero = i.Cod_Pedido 


    if ((@FlgCal = 0) and (@TipPed = 'P') and (@TipBlq <> 'SR') and (@QtdPed > 0)) or
--        ((@FlgCriIteFec = 0) or (@TipSai = 'B') or (@FlgAltPrc = 1))
        ((@FlgCriIteFec = 0) or (@TipSai = 'B') or (@FlgAltPrc = 1)or (@FlgAltQtd = 1))
      begin
	    Set @FlgCalAnt = @FlgCal

        -- coloca o pedido em modo de calculo para evitar recursividade na procedure PR_SolicitaLoteProduto
        Update PDVCB
          Set Flg_Calc = 1
          Where Cod_Estabe = @CodEstabe
          And Numero = @CodPed

        DECLARE Inserted_Cr CURSOR Local Fast_Forward For
          Select i.Cod_Estabe, i.Cod_Pedido,
                 i.Cod_Produto, i.Cod_Lote,
                 i.Tip_Sai, IsNull(i.Cod_Promocao,0), IsNull(Cod_KitPrm,0),
                 IsNull(i.Qtd_Pedido,0), IsNull(i.Qtd_Bonificacao,0),
                 Case 
                   When IsNull(i.Fat_CnvImpFat,1) = 0 then 1
                   Else IsNull(i.Fat_CnvImpFat,1)
                 End
            From Inserted i
           Order by i.Cod_Produto
        OPEN Inserted_Cr
        FETCH NEXT FROM Inserted_Cr INTO @CodEstabe, @CodPed,
                                         @CodPrd,@CodLot,
                                         @TipSai, @CodPrm, @CodKitPrm,
                                         @QtdPed, @QtdBon,
                                         @FatCnvImpFat
        WHILE @@FETCH_STATUS = 0
        BEGIN
          if (@FlgCal = 0) and (@TipPed = 'P') and (@TipBlq <> 'SR') and (@QtdPed > 0) and (@FlgAltQtd = 1)
            begin
               -- solicita o(s) lote(s) do produto / calcula tributos e campos calculados
              if @FlgWms = 0
                begin
                  EXEC PR_SolicitaLoteProduto @CodEstabe, @CodPed, @FlgLotEsp, @CodPrd, @CodLot, @TipSai, @CodPrm, @CodKitPrm, @QtdPed, @QtdBon, @FatCnvImpFat, @FlgLotNaoFra
                end
              else
                begin
                  Set @FlgTemPDVLT = 0
                  if Exists(Select 1 From PDVLT Where Cod_Estabe = @CodEstabe and Cod_Pedido = @CodPed)
                    Set @FlgTemPDVLT = 1
                  EXEC PR_IncrementaSaldoSolicitado @CodEstabe, @CodPed, @CodGrpCli, @CodCliPag, @QtdMesMinPrzVctLot, @CodOriPed, @FlgTemPDVLT, @CodPrd, @CodLot, @TipSai, @CodPrm, @QtdPed, @QtdBon, @FatCnvImpFat
                end
            end

          -- calcula tributos  e campos calculados     
          if (@FlgCriIteFec = 0) or (@TipSai = 'B') or (@FlgAltQtd = 1) or (@FlgAltPrc = 1)
            EXEC PR_CalcTributPdvit @CodEstabe, @CodPed, @CodPrd, @CodLot, @TipSai

          FETCH NEXT FROM Inserted_Cr INTO @CodEstabe, @CodPed,
                                           @CodPrd,@CodLot,
                                           @TipSai, @CodPrm, @CodKitPrm,
                                           @QtdPed, @QtdBon,
                                           @FatCnvImpFat
        END

        CLOSE Inserted_Cr
        DEALLOCATE Inserted_Cr           

        Update PDVCB
          Set Flg_Calc = @FlgCalAnt
          Where Cod_Estabe = @CodEstabe
          And Numero = @CodPed
      end       
  end  -- se inserted

-- Atualiza cabeçalho do pedido
EXEC PR_AtualizaCabecPDV @CodEstabe, @CodPed

-- Atualiza consignacao
if @IdConsig > 0
  Exec PR_AtualizaCNGRI @CodEstabe, @IdConsig, @NumSeqCtr

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_GeraPedidoVendaPDE]
@PCodEstabe int,
@PCodLayout int,
@PNumCnpj varchar(14),
@PCodPedCli varchar(20),
@PNumDesdob int,
@PNumPdv int = NULL output,     -- se = 0 : cria novo pedido
@PMsgErr varchar(8000) output

AS

SET NOCOUNT ON

Set @PMsgErr = ''

if not Exists(Select 1 From dbo.PDECB 
              Where Cod_Estabe = @PCodEstabe And Cod_Layout = @PCodLayout And Num_Cnpj = @PNumCnpj And Cod_PedCli = @PCodPedCli And Num_Desdob = @PNumDesdob)
  Set @PMsgErr ='Pedido Eletrônico não existe'
else
if Exists(Select 1 From dbo.PDECB 
          Where Cod_Estabe = @PCodEstabe And Cod_Layout = @PCodLayout And Num_Cnpj = @PNumCnpj And Cod_PedCli = @PCodPedCli And Num_Desdob = @PNumDesdob
          And IsNull(Sta_Pedido,'') <> '0')
  Set @PMsgErr ='Pedido Eletrônico inválido (status)'
else
if not Exists(Select 1 From dbo.PDEIT 
              Where Cod_Estabe = @PCodEstabe And Cod_Layout = @PCodLayout And Num_Cnpj = @PNumCnpj And Cod_PedCli = @PCodPedCli And Num_Desdob = @PNumDesdob)
  Set @PMsgErr ='Pedido Eletrônico inválido (sem itens)'
else
  begin

    if @PNumPdv is null
      Set @PNumPdv = 0

    if not Exists(Select 1
                    From dbo.PDECB
                   Where Cod_Estabe = @PCodEstabe
                     And Cod_Layout = @PCodLayout
                     And Num_Cnpj   = @PNumCnpj
                     And Cod_PedCli = @PCodPedCli
                     And Num_Desdob = @PNumDesdob
                     And IsNull(Num_PedVen,0) > 0)
      begin  
        EXEC PR_ProxNumero 'Pedido_Venda', @PNumPdv output
      end  

    BEGIN TRANSACTION

    Set @PMsgErr = ''

    Declare @WCodDig int,
            @WTipFat varchar(3),
            @WTipPrc varchar(1),
            @WMsgAux varchar(100),
            @WNumSeqIte int,
            @WTipPrz varchar(1),
            @WNomUsuSnhEsp varchar(35),
            @WFlgBlqDscAutIte bit,
            @WFlgBlqAltPrcPol bit,
            @WTipImpPrcPdvCfg varchar(1),
            @WTipImpPrcPdv varchar(1),
            @WFlgTemVdrVnc bit,
            @WFlgUsaVdrPar bit,
            @WFlgSnhEsp bit,          
            @WFlgBlqCriConCom bit,    
            @WFlgBlqCriPrcVen bit,
            @WFlgBlqEstFisNeg bit,
            @WFlgCriVrb bit,
            @WFatCnvCxaFec int,			     
            @WPerDscArq numeric(8,4),
            @WPrcUniArq numeric(18,8),
            @WPerDsc numeric(8,4),
            @WPrcLiqArq numeric(18,8),
            @WDesLayout varchar(25),

            @WFlgBlqWms bit = 0,     -- nunca usa WMS
            @WFlgBlqPol bit = 0,     -- nunca usa politica
            @WFlgUsaWms bit = 0

    Declare @pm_FlgUsaPolComPdv bit = 0,
            @pm_PrzRefPrcVen int,
            @pm_FlgAltUnvItePdv bit,
            @pm_CodVdrPdvCon int,
            @pm_QtdDecPrcItePdv int,

            @pe_NumPedVen int,
            @pe_Layout varchar(20),
            @pe_CodOriPed varchar(1),
            @pe_TipPed varchar(1),
            @pe_CodPedCmpCli varchar(20),
            @pe_CodClient int, 
            @pe_CodVended int, 
            @pe_CodOperad int,
            @pe_IdPolCom int,
            @pe_CodTabPrz int,
            @pe_CodMtvRej varchar(3),
            @pe_CodGrpClp int,
            @pe_FlgFatPedIntegral bit

    -- PARAM
    Select @pm_FlgUsaPolComPdv = IsNull(FlgUsaPolComPdv,0),
           @pm_PrzRefPrcVen = IsNull(PrzRefPrcVen,0),
           @pm_FlgAltUnvItePdv = IsNull(FlgAltUnvItePdv,0),
		   @pm_CodVdrPdvCon = IsNull(CodVdrPdvCon,0),
           @pm_QtdDecPrcItePdv = IsNull(QtdDecPrcItePdv,0)
      From dbo.PARAM
      Where Cod_Estabe = @PCodEstabe

    -- PDECB
    Select @pe_NumPedVen = IsNull(Num_PedVen,0),
           @pe_CodOriPed = IsNull(Cod_OriPed,''),
           @pe_TipPed = IsNull(Tip_Pedido,''),
           @pe_CodPedCmpCli = IsNull(Cod_PedCmpCli,''),
           @pe_CodClient = IsNull(Cod_Client,0), 
           @pe_CodVended = IsNull(Cod_Vended,0), 
           @pe_CodOperad = IsNull(Cod_Operad,0), 
           @pe_IdPolCom = IsNull(Id_PolCom,0),
           @pe_CodTabPrz = IsNull(Cod_TabPrz,0),
		   @pe_CodMtvRej = IsNull(Cod_MtvRej,''),
           @pe_CodGrpClp = IsNull(Cod_GrpClp,0),
           @pe_FlgFatPedIntegral = ISNULL(Flg_FatPedIntegral, 0)
      From dbo.PDECB
     Where Cod_Estabe = @PCodEstabe
       And Cod_Layout = @PCodLayout
       And Num_Cnpj = @PNumCnpj
       And Cod_PedCli = @PCodPedCli
       And Num_Desdob = @PNumDesdob

    Set @WDesLayout = (Select Des_Layout From dbo.TBCLP Where Cod_Layout = @PCodLayout)

    -- TBLPG
    Set @WFlgBlqDscAutIte = 0
    Set @WTipImpPrcPdvCfg = ''
    Set @WFlgTemVdrVnc = 0
    Set @WFlgUsaVdrPar = 0

    if Exists(Select 1 From dbo.TBLPG Where Cod_Estabe = @PCodEstabe And Cod_Layout = @PCodLayout And Cod_Grupo = @pe_CodGrpClp)
      begin
        Select @WFlgBlqDscAutIte = IsNull(it.Flg_BlqDscAutIte,0),
               @WTipImpPrcPdvCfg = IsNull(it.Tip_ImpPrcPdv,0),
               @WFlgBlqAltPrcPol = IsNull(Flg_BlqAltPrcPol,0),
               @WFlgTemVdrVnc = Case 
                                  When Exists(Select 1 From dbo.LGXVD Where Cod_Estabe = it.Cod_Estabe and Cod_Layout = it.Cod_Layout and Cod_Grupo = it.Cod_Grupo) then Cast(1 as bit) 
                                  Else Cast(0 as bit) 
                                End,
               @WFlgUsaVdrPar = IsNull(Flg_UsaVdrPar,0)
          From dbo.TBLPG it
         Where it.Cod_Estabe = @PCodEstabe
           And it.Cod_Layout = @PCodLayout
           And it.Cod_Grupo = @pe_CodGrpClp
      end

    Set @WTipImpPrcPdv = @WTipImpPrcPdvCfg
    if @WTipImpPrcPdv = 'A'
      Set @WFlgBlqCriConCom = 1
    else
      Set @WFlgBlqCriConCom = 0

    if IsNull(@pe_NumPedVen,0) > 0
      Set @PNumPdv = @pe_NumPedVen

   if (@PNumPdv = 0) or (not Exists(Select Numero From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv))
      begin
        -- WMS
        Set @WFlgUsaWms = (Select dbo.FN_ModExtOk(HASHBYTES('MD5','WMS'),
		                                          HASHBYTES('MD5',(Select Num_Cnpj From dbo.ESTAB Where Cod_Estabe = @PCodEstabe))))

        if @pe_CodOriPed = '' Set @pe_CodOriPed = 'A'

        -- ajusta flags
        if @WFlgBlqWms = 1         -- nunca usa WMS
          Set @WFlgUsaWms = 0

        if @WFlgBlqPol = 1         -- nunca usa politica
          begin
            Set @pm_FlgUsaPolComPdv = 0
            Set @pe_IdPolCom = 0
          end
        
        Set @WTipFat = 'FAT'
        Set @WCodDig = 0
        Set @WFlgBlqWms = 0
        Set @WFlgBlqPol = 0

        Exec PR_IncluiPDVCB 'P', @PCodEstabe, @PNumPdv output, @pe_CodOriPed, @pe_CodClient, @WFlgUsaWms, @WTipFat,
                            @pe_CodVended, @pe_CodOperad, @WCodDig, @pe_IdPolCom, @pe_CodTabPrz, @PCodLayout,
                            @WFlgBlqWms, @WFlgBlqPol, @PMsgErr output

		Update dbo.PDECB
           Set Cod_MtvRej = 'CAD',
               Des_MtvRej = @PMsgErr
         Where Cod_Estabe = @PCodEstabe
           And Cod_Layout = @PCodLayout
           And Num_Cnpj   = @PNumCnpj
           And Cod_PedCli = @PCodPedCli
           And Num_Desdob = @PNumDesdob
           And @PMsgErr <> ''

        -- procedimento que simula EditCodClienteExit no EdPedVen
		-- já eh executado em PR_IncluiPDVCB
        --Exec PR_InfoDefaultPDVCB @PCodEstabe, @PNumPdv
      end  -- if @PNumPdv = 0

    Update pv
       Set pv.Status2 = 'X',    
           pv.Cod_PedCli = @PCodPedCli, 
           pv.Cod_PedCmpCli = Case 
                                When IsNull(pe.Cod_PedCmpCli,'') <> '' then IsNull(pe.Cod_PedCmpCli,'') 
                                Else @PCodPEdCli 
                              End,
           pv.Cod_PrjPde = IsNull(pe.Cod_Projeto,''),
           pv.Tip_Vencimento = '',
           pv.Observacao = pe.Observacao,     -- ''
           pv.Obs_NotFis = pe.Obs_NotFis,      -- ''
           pv.Qtd_Parcela = IsNull(pe.Qtd_Parcela,0), 
           pv.Qtd_PrzMed  = IsNull(pe.Qtd_PrzMed,0)*1.0,
           pv.Dat_LimEnvPrp = cast(pe.Dat_Encerra as smalldatetime)
      From dbo.PDVCB pv, dbo.PDECB pe
     Where pv.Cod_Estabe = @PCodEstabe
       And pv.Numero = @PNumPdv
       And pv.Status1 = 'P'     -- Pendente
       And ((pv.Status2 = 'A') or (pv.Status2 = 'X'))  -- em aberto    
       And pe.Cod_Estabe = @PCodEstabe
       And pe.Cod_Layout = @PCodLayout
       And pe.Num_Cnpj   = @PNumCnpj
       And pe.Cod_PedCli = @PCodPedCli
       And pe.Num_Desdob = @PNumDesdob

    -- registra num.pedido venda em PDECB (informação necessária ao incluir itens em PDVIT) em 25/08/2022
    Update dbo.PDECB
       Set Num_PedVen = @PNumPdv
     Where Cod_Estabe = @PCodEstabe
       And Cod_Layout = @PCodLayout
       And Num_Cnpj   = @PNumCnpj
       And Cod_PedCli = @PCodPedCli
       And Num_Desdob = @PNumDesdob

    -- inclui itens somente se pedido está "aberto"
    if Exists(Select Numero From dbo.PDVCB 
               Where Cod_Estabe = @PCodEstabe and Numero = @PNumPdv 
                 And Status1 = 'P' And ((Status2 = 'A') or (Status2 = 'X')))
      begin

        Declare @op_CfoNorInt int,
                @cl_Codigo int,
                @cl_FlgLicSauInv bit,
                @cl_FlgLicAnvInv bit,
                @pv_CodTipPed varchar(3)  -- 'PDV','COT'

        Select @WTipPrc = op.Tip_Prc,    -- ver tipo de transacao p/ escolher o preco a ser utilizado no pedido
               @op_CfoNorInt = IsNull(op.Cod_CfoNorInt,0),
               @WTipPrz = Substring(cb.Cod_OrigemPdv,2,1),
               @cl_Codigo = IsNull(cl.Codigo,0), 
               @cl_FlgLicSauInv = 0,
               @cl_FlgLicAnvInv = 0,
               @pv_CodTipPed = Case When cb.Tip_Pedido = 'C' then 'COT' Else'PDV' End
          From dbo.PDVCB cb 
               Left Outer Join dbo.TPOPE op on cb.Tip_Faturamento = op.Cod_Ope 
               Left Outer Join dbo.CLIEN cl on cb.Cod_Cliente = cl.Codigo 
         Where cb.Cod_Estabe = @PCodEstabe
           And cb.Numero = @PNumPdv
           And cb.Status1 = 'P'
           And ((cb.Status2 = 'A') or (cb.Status2 = 'X')) 

        -- flg licenças
        Set @cl_FlgLicSauInv = 0
        Set @cl_FlgLicAnvInv = 0
        if @cl_Codigo > 0
          begin
            Exec PR_AnalisaLicencaCliente @pv_CodTipPed, 'SAUDE',  @cl_Codigo, @cl_FlgLicSauInv output, @WMsgAux output
            Exec PR_AnalisaLicencaCliente @pv_CodTipPed, 'ANVISA', @cl_Codigo, @cl_FlgLicAnvInv output, @WMsgAux output
          end
         
        -- estoque fiscal
        Set @WFlgBlqEstFisNeg = 0
        if (IsNull((Select BlqEstFisNeg From dbo.PMEST Where Cod_Estabe = @PCodEstabe),0) = 1) and (@op_CfoNorInt > 0)
          Set @WFlgBlqEstFisNeg = 1

         -- coloca o pedido em processamento
        Update dbo.PDVCB 
           Set Status2 = 'X'
         Where Cod_Estabe = @PCodEstabe
           And Numero = @PNumPdv
           And Status2 <> 'X' 

        -- sequencial do item na PDVIT
        Set @WNumSeqIte = IsNull((Select max(Num_SeqDig) From dbo.PDVIT 
                                   Where Cod_Estabe = @PCodEstabe
                                     And Cod_Pedido = @PNumPdv),0) + 1

        -- inclui itens emm PDVIT
        Declare @WPFlgAchou bit,
                @WPLocFis varchar(15),
                @WPCodFab int,
                @WPFatCnvImpFat int,
                @WPPrcFab numeric(18,8),
                @WPPrcMaxCon numeric(18,8),
                @WPPrcRefFpb numeric(18,8),
                @WPPrcCusMinComMarkup numeric(18,8),
                @WPPrcTab numeric(18,8),
                @WPPrcTabBru numeric(18,8),
                @WPPrcUni numeric(18,8),
                @WPPrcMin numeric(18,8),
                @WPPrcUniLiqPer numeric(18,8),
                @WPFlgEmbDscPrc bit,
                @WPPerDscLin numeric(8,4),
                @WPPerDscPrz numeric(8,4),
                @WPPerDscVis numeric(8,4),
                @WPQtdPrzMax int,

                @WPPerDscPolCom numeric(8,4),
                @WPPerDscVisPolCom numeric(8,4),
                @WPPrcPolCom numeric(18,8),
                @WPQtdPrzPolCom int,
                @WPCodKitPrm int,
                @WPCodPromoc int,
                @WPFlgVerba bit,
                @WPFlgPolPrm bit,
                @WPVlrVrbDis numeric(18,4),

                @WPCodRej varchar(3),
                @WPDesMsg varchar(80),
                @WPCmp varchar(20),
                @WPNomUsuDbq varchar(35),
                @WPDesMsgDbq varchar(60),
                @WPQtdImpFat int, 
                @WPPrcUniImpFat numeric(18,8),
		        @WPCodLot varchar(20),
                @WPPrcUniPde numeric(18,8),
                @WPPerDscPde numeric(8,4),
                @WPCodPrjPde varchar(12),
                @WPNumSeqPdc varchar(6),
                @WPTipSai varchar(1),
                @WPC_PrcUni numeric(18,8),
                @WPC_PerDscIte numeric(8,4),
                @WPPrcUniLiqPdv numeric(18,8),
                --@WPC_VlrDesconto numeric(18,8),
                --@WPC_PrcTotal numeric(18,8),

                @WIte_Chave int = 0,
                @WIte_FlgDscInf bit,
                @WIte_FlgPrcInf bit,
                @WIte_FlgPrzInf bit,
                @WIte_FlgPolInf bit,
                @WIte_FlgBlqQtdPar bit,

				@WIte_CodPrdArq varchar(14),
		        @WIte_CodPrd int,
                @WIte_CodRej varchar(3),
                @WIte_FatCnvImpFat int,
                @WIte_FatAprPad smallint,
                @WIte_QtdPed int,
                @WIte_QtdBon int,
                @WIte_PrcUni numeric(18,4),
                @WIte_IdPolCom int,
                @WIte_PerDsc numeric(18,4),
                @WIte_PrcUniArq numeric(18,8),
                @WIte_PerDscArq numeric(8,4),

                @WIte_QtdPedInf int,
                @WIte_QtdBonInf int,
                @WIte_QtdSolInf int,
                @WIte_QtdAceInf int,
                @WIte_PrcUniInf numeric(18,8),
                @WIte_PerDscInf numeric(8,4),
                @WIte_DesUnvImpFat varchar(3),
				@WIte_DesAprImpFat varchar(12), 
                @WIte_PrcUniImpFat numeric(18,8),
                @WIte_CodProjeto varchar(12),
                @WIte_NumSeqPdc varchar(6),
                @WIte_TipSai varchar(1),
                @WIte_CodTipDsc varchar(1),
                @WIte_CodPrdEmbFec varchar(4), 
                @WIte_QtdEmbFec int,
                @WIte_PerDscEmbPrc numeric(8,4),

                @Wpr_PrcCusLiqEnt numeric(18,4),

                @pvit_CodLot varchar(20),
                @ap_FatCnvApr int,
                @ap_DesUnvApr varchar(3),
                @ap_DesApr varchar(12),

                @pc_FlgNegDsc bit,
                @pc_FlgBlqVerba bit,

				@WQtdPedAte int,
                @WQtdFisDsp int


        Declare @tb_PDEIT table(
          Chave int identity(1,1) primary key,
          Cod_PrdCli varchar(14), 
          Cod_Produt int, 
          Tip_Sai varchar(1), 
          Qtd_Pedido int, 
          Prc_Unitario numeric(18,4),
          Cod_TipDsc varchar(1), 
          Per_Desconto numeric(18,4), 
          Id_PolCom int, 
		  Cod_PrdEmbFec varchar(14),
          Qtd_Embala int,
          Fat_CnvImpFat int, 
          Fat_AprPad smallint,
          Des_UnvImpFat char(3),
          Des_AprImpFat varchar(12),
          Prc_UniImpFat numeric(18,8),
          Cod_Projeto varchar(12),
          Num_SeqPdc varchar(6),
          Per_DscEmbPrc numeric(18,4),
          Flg_PrcInf bit,
          Flg_DscInf bit,
          Flg_PrzInf bit,
          Flg_PolInf bit,
          Flg_BlqQtdPar bit,
          Prc_UnitarArq numeric(18,4),
          Per_DesconArq numeric(8,4)
        )


        -- normaliza campos em PDEIT
        Update dbo.PDEIT
           Set Prc_UnitarArq = Case When IsNull(Flg_PrcInf,0) = 1 Then IsNull(Prc_Unitario,0) Else 0 End, 
               Per_DesconArq = Case When IsNull(Flg_DscInf,0) = 1 Then IsNull(Per_Desconto,0) Else 0 End
         Where Cod_Estabe = @PCodEstabe
           And Cod_Layout = @PCodLayout
           And Num_Cnpj   = @PNumCnpj
           And Cod_PedCli = @PCodPedCli
           And Num_Desdob = @PNumDesdob


        -- seleciona registros candidatos
        Insert Into @tb_PDEIT
          Select Cod_PrdCli, IsNull(Cod_Produt,0), IsNull(Tip_Sai,''), IsNull(Qtd_Pedido,0), IsNull(Prc_Unitario,0), 
                 IsNull(Cod_TipDsc,''), IsNull(Per_Desconto,0), IsNull(Id_PolCom,0), IsNull(Cod_PrdEmbFec,''), IsNull(Qtd_Embala,0),
                 IsNull(Fat_CnvImpFat,0), IsNull(Fat_AprPad,0), IsNull(Des_UnvImpFat,''), IsNull(Des_AprImpFat,''), 
                 IsNull(Prc_UniImpFat,0), IsNull(Cod_Projeto,''), IsNull(Num_SeqPdc,''), IsNull(Per_DscEmbPrc,0),
				 IsNull(Flg_PrcInf,0), IsNull(Flg_DscInf,0), IsNull(Flg_PrzInf,0), IsNull(Flg_PolInf,0), IsNull(Flg_BlqQtdPar,0),
				 IsNull(Prc_UnitarArq,0), IsNull(Per_DesconArq,0)
            From dbo.PDEIT
           Where Cod_Estabe = @PCodEstabe
             And Cod_Layout = @PCodLayout
             And Num_Cnpj   = @PNumCnpj
             And Cod_PedCli = @PCodPedCli
             And Num_Desdob = @PNumDesdob

        While Exists(Select 1 From @tb_PDEIT)
          BEGIN
            Select top 1 @WIte_Chave = t.Chave,
                         @WIte_CodPrdArq = t.Cod_PrdCli, 
                         @WIte_CodPrd = t.Cod_Produt,
                         @WIte_TipSai = t.Tip_Sai,
                         @WIte_QtdPed = t.Qtd_Pedido,
                         @WIte_PrcUni = t.Prc_Unitario,
                         @WIte_CodTipDsc = t.Cod_TipDsc, 
                         @WIte_PerDsc = t.Per_Desconto, 
                         @WIte_IdPolCom = t.Id_PolCom, 
                         @WIte_CodPrdEmbFec = t.Cod_PrdEmbFec, 
                         @WIte_QtdEmbFec = t.Qtd_Embala,
                         @WIte_FatCnvImpFat = t.Fat_CnvImpFat, 
                         @WIte_FatAprPad = t.Fat_AprPad, 
                         @WIte_DesUnvImpFat = t.Des_UnvImpFat, 
                         @WIte_DesAprImpFat = t.Des_AprImpFat, 
                         @WIte_PrcUniImpFat = t.Prc_UniImpFat, 
                         @WIte_CodProjeto = t.Cod_Projeto,
                         @WIte_NumSeqPdc = t.Num_SeqPdc,
                         @WIte_PerDscEmbPrc = t.Per_DscEmbPrc,
                         @WIte_FlgPrcInf = t.Flg_PrcInf, 
                         @WIte_FlgDscInf = t.Flg_DscInf, 
                         @WIte_FlgPrzInf = t.Flg_PrzInf, 
                         @WIte_FlgPolInf = t.Flg_PolInf, 
                         @WIte_FlgBlqQtdPar = t.Flg_BlqQtdPar,
                         @WIte_PrcUniArq = t.Prc_UnitarArq, 
                         @WIte_PerDscArq = t.Per_DesconArq
              From @tb_PDEIT t

            -- Tudofarma: Cod_TipDsc = '1' (industria) -> @WTipImpPrcPdv = 'A'
            if @WIte_CodTipDsc = '1' --desconto da industria
              begin
                Set @WIte_FlgDscInf = 1
                Set @WTipImpPrcPdv = @WTipImpPrcPdvCfg   -- aceita, rejeita ou ignora
              end
            else
            if @WIte_CodTipDsc = '0' --desconto distribuidor
              Set @WTipImpPrcPdv = 'I' 
				              
            Set @WIte_CodRej = ''
            Set @WQtdPedAte  = 0
            Set @WIte_QtdBon = 0
            if @WIte_FatCnvImpFat = 0 
              Set @WIte_FatCnvImpFat = 1
            if @WIte_FatAprPad = 0 
              Set @WIte_FatAprPad = 1

            if @WIte_CodPrd = 0 
              begin
                Set @WIte_CodRej = 'PRX'    -- produto invalido
              end

            -- inclui PDVIT
            if @WIte_CodPrd > 0
              begin

                Select @pvit_CodLot = IsNull(Cod_Lote,'') 
                  From dbo.PDVIT 
                 Where Cod_Estabe = @PCodEstabe
                   And Cod_Pedido = @PNumPdv
                   And Cod_Produto = @WIte_CodPrd
                 Order by Qtd_Pedido desc 

                if not Exists(Select Cod_Lote From dbo.PDVIT 
                               Where Cod_Estabe = @PCodEstabe
                                 And Cod_Pedido = @PNumPdv
                                 And Cod_Produto = @WIte_CodPrd) 
                  begin  

-------------------------  Confirmar se vem tudo calculado em PDEIT --------------------------------------------------------------------------------------------------------------------
                    if @WIte_FatCnvImpFat = 0 
                      Set @WIte_FatCnvImpFat = 1

                    if @WIte_FatAprPad = 0 
                      Set @WIte_FatAprPad = 1

                    if (@pm_FlgAltUnvItePdv = 1) and (@WIte_FatCnvImpFat = 1) and
                       Exists(Select Cod_Apr From dbo.PRXAP 
                               Where Cod_Produt = @WIte_CodPrd 
                                 And IsNull(Flg_Padrao,0) = 1 And IsNull(Fat_CnvApr,0) > 1) 
                      begin
                        Select @ap_DesApr = Des_Apr, 
                               @ap_FatCnvApr = IsNull(Fat_CnvApr,0), 
                               @ap_DesUnvApr = IsNull(Des_UnvApr,'') 
                          From dbo.PRXAP 
                         Where Cod_Produt = @WIte_CodPrd
                           And IsNull(Flg_Padrao,0) = 1 
                           And IsNull(Fat_CnvApr,0) > 1 

-----------------------------------------------------------------------------
                       Set @WIte_FatAprPad    = @ap_FatCnvApr
                       Set @WIte_FatCnvImpFat = @ap_FatCnvApr
                       Set @WIte_DesUnvImpFat = @ap_DesUnvApr
                       Set @WIte_DesAprImpFat = @ap_DesApr
                      end

                    if (@WIte_PrcUniImpFat = 0) and (@WIte_FatCnvImpFat > 1) 
                      Set @WIte_PrcUniImpFat = @WIte_PrcUni * @WIte_FatCnvImpFat

-------------------------------------------------------------------------------------------------------------

                    Set @WIte_QtdPedInf = @WIte_QtdPed*@WIte_FatAprPad
                    Set @WIte_QtdBonInf = @WIte_QtdBon*@WIte_FatAprPad
                    Set @WIte_PrcUniInf = @WIte_PrcUni/@WIte_FatAprPad
                    Set @WIte_PerDscInf = @WIte_PerDsc

--------------------------------------------------------------------------------------------------------------

                    if (@pe_IdPolCom = 0) and (@WIte_IdPolCom > 0)
                      begin
                        Set @pe_IdPolCom = @WIte_IdPolCom
                        --RegravaRegistroPdecb('POL')
                        Update dbo.PDECB
                           Set Id_PolCom = @pe_IdPolCom
                         Where Cod_Estabe = @PCodEstabe
                           And Cod_Layout = @PCodLayout
                           And Num_Cnpj = @PNumCnpj
                           And Cod_PedCli = @PCodPedCli
                           And Num_Desdob = @PNumDesdob
                      end

                    if (@WFlgTemVdrVnc = 1) and (@pe_CodVended = 0) 
                      begin
                        -- pega vendedor
                        if (@WIte_CodPrd > 0) and (@pe_CodClient > 0)
                          begin
                            Select @pe_CodVended = lg.Cod_Vended 
                              From dbo.LGXVD lg 
                                   Inner Join dbo.PRODU pr on pr.Codigo = @WIte_CodPrd
                             Where lg.Cod_Estabe = @PCodEstabe
                               And lg.Cod_Layout = @PCodLayOut
                               And lg.Cod_Grupo = @pe_CodGrpClp
                               And lg.Cod_Client = @pe_CodClient 
                               And lg.Cod_Fabric = pr.Cod_Fabricante
                          end
                         
                        if (@pe_CodVended = 0) and (@WFlgUsaVdrPar = 1)
                          Set @pe_CodVended = @pm_CodVdrPdvCon
                         
                        --RegravaRegistroPdecb('VDR')
                        Update dbo.PDECB
                           Set Cod_Vended = @pe_CodVended
                         Where Cod_Estabe = @PCodEstabe
                           And Cod_Layout = @PCodLayout
                           And Num_Cnpj = @PNumCnpj
                           And Cod_PedCli = @PCodPedCli
                           And Num_Desdob = @PNumDesdob
                           And @pe_CodVended > 0
                      end

-- @WIte_FatCnvImpFat, : pode ter sido alterado devido apresentação padrão: 
-- @WIte_QtdPedInf, 
-- @WIte_QtdBonInf
-- @WIte_PrcUniInf

                    Exec PR_InfoDefaultPDVIT @pm_FlgUsaPolComPdv, @PCodEstabe, @PNumPdv, @WIte_CodPrd, 
                                             @WIte_QtdPedInf, @WIte_QtdBonInf, @WIte_IdPolCom output, @WFlgBlqDscAutIte,
                                             @WPFlgAchou output,
                                             @WPLocFis output,
                                             @WPCodFab output,
                                             @WPPrcFab output,
                                             @WPPrcMaxCon output,
                                             @WPPrcRefFpb output,
                                             @WPPrcTab output,
                                             @WPPrcTabBru output,
                                             @WPFatCnvImpFat output,     -- ???? @WIte_FatCnvImpFat
                                             @WPPrcUni output,
                                             @WPPrcCusMinComMarkup output,
                                             @WPPerDscPolCom output,
                                             @WPPerDscVisPolCom output,
                                             @WPPrcPolCom output,
                                             @WPQtdPrzPolCom output,
                                             @WPFlgVerba output,
                                             @WPFlgPolPrm output,
                                             @WPCodKitPrm output,
                                             @WPCodPromoc output,
                                             @WPFlgEmbDscPrc output, 
                                             @WPQtdPrzMax output,
                                             @WPPerDscLin output,
                                             @WPPerDscPrz output,
                                             @WPPerDscVis output,
                                             @WPPrcUniLiqPer output

                    if @WPFlgAchou = 1
                      begin
                        if @pm_FlgUsaPolComPdv = 0
                          begin
                            if @WTipImpPrcPdv <> 'I' 
                              if (@WIte_FlgDscInf = 1) or (@WIte_FlgPrcInf = 1)
                                begin
                                  -- variaveis ref. desc. a ser considerado
                                  Set @WPerDscArq = 0
                                  if (@WIte_FlgDscInf = 1) and ((@WTipImpPrcPdv = 'A') or (@WTipImpPrcPdv = 'R')) and (IsNull(@WIte_PerDscEmbPrc,0) = 0) 
                                    Set @WPerDscArq = @WIte_PerDsc

                                  Set @WPrcUniArq = @WPPrcUni

                                  if (@WIte_FlgPrcInf = 1) and ((@WTipImpPrcPdv = 'A') or (@WTipImpPrcPdv = 'R'))
                                    Set @WPrcUniArq = @WIte_PrcUniInf

                                  if Isnull(@WPrcUniArq,0) = IsNull(@WPPrcUni,0)
                                    Set @WPerDsc = @WPerDscArq
                                  else
                                    begin
                                      Set @WPrcLiqArq = Round(@WPrcUniArq*(1-@WPerDscArq/100),@pm_QtdDecPrcItePdv)
                                      if @WPPrcUni > @WPrcLiqArq 
                                         Set @WPerDsc = Round((@WPPrcUni-@WPrcLiqArq)*100/@WPPrcUni,2)
                                      else
                                        Set @WPerDsc = @WIte_PerDscEmbPrc
                                    end

                                  Set @WPPrcUni = @WPrcUniArq
                                  Set @WPPerDscLin = @WPerDsc
                                  Set @WPPerDscPrz = @WPerDsc
                                  Set @WPPerDscVis = @WPerDsc
                                end
                          end  -- if @pm_FlgUsaPolComPdv = 0

                        if @pm_FlgUsaPolComPdv = 1
                          begin
                            Set @pc_FlgNegDsc = 0
                            Set @pc_FlgBlqVerba = 0
                            
                            Select @pc_FlgNegDsc = IsNull(Flg_NegDsc,0), 
                                   @pc_FlgBlqVerba = Case 
                                                       When ((IsNull(Flg_AcuVrbPos,0) = 0) and (IsNull(Flg_AcuVrbNeg,0) = 0)) then 1 
                                                       Else 0 
                                                     End
                              From dbo.POCOM 
                             Where Id_PolCom = @WIte_IdPolCom 

                            --  politica de comercialização (não alterava preço unitario), somente desconto, e, se estiver configurado para permitir negociação
                            if ((@pc_FlgNegDsc = 1) and (@WTipImpPrcPdv <> 'I'))
                              begin
                                if (@WIte_FlgDscInf = 1) or (@WIte_FlgPrcInf = 1) 
                                  begin
                                    -- variaveis ref. desc. a ser considerado
                                    Set @WPerDscArq = 0
                                    if (@WIte_FlgDscInf = 1) and ((@WTipImpPrcPdv = 'A') or (@WTipImpPrcPdv = 'R')) and (IsNull(@WIte_PerDscEmbPrc,0) = 0) 
                                      Set @WPerDscArq = @WIte_PerDsc
                            
                                    Set @WPrcUniArq = @WPPrcUni
                                    if (@WIte_FlgPrcInf = 1) and ((@WTipImpPrcPdv = 'A') or (@WTipImpPrcPdv = 'R')) 
                                      Set @WPrcUniArq = @WIte_PrcUniInf
                            
                                    --  verifica se permite alterar preço da politica
                                    if @WFlgBlqAltPrcPol = 0 
                                      begin
                                        Set @WPPrcUni = @WPrcUniArq
                                        Set @WPerDsc  = @WPerDscArq
                                      end
                                    else
                                      begin
                                        if Round(@WPrcUniArq,2) = Round(@WPPrcUni,2) 
                                          Set @WPerDsc = @WPerDscArq
                                        else
                                          begin
                                            Set @WPrcLiqArq = Round(@WPrcUniArq*(1-@WPerDscArq/100),@pm_QtdDecPrcItePdv)
                                            if @WPPrcUni > @WPrcLiqArq 
                                              Set @WPerDsc = Round((@WPPrcUni-@WPrcLiqArq)*100/@WPPrcUni,2)
                                            else
                                              Set @WPerDsc = @WIte_PerDscEmbPrc
                                          end
                                      end
                            
                                    Set @WPPerDscPrz = @WPerDsc
                                    Set @WPPerDscVis = @WPerDsc
                                  end
                              end  -- if ((@pc_FlgNegDsc = 1) and (@WTipImpPrcPdv <> 'I'))
                          end  -- if @pm_FlgUsaPolComPdv = 1

                        Set @WPCodLot = '*'

                        if @WIte_FatCnvImpFat = 0 
                          Set @WIte_FatCnvImpFat = 1
                       
                        -- estoque fiscal negativo
                        if @WFlgBlqEstFisNeg = 1
                          begin
                            Set @WQtdFisDsp = dbo.FN_SldFiscalDisponPrd(@PCodEstabe,@WIte_CodPrd)
                            if @WIte_QtdPedInf > @WQtdFisDsp
                              begin
                                if @WQtdFisDsp < 0 Set @WQtdFisDsp = 0
                                Set @WIte_QtdPedInf = @WQtdFisDsp
                              end
                          end
                       
                        Set @WPPrcUniPde = @WPPrcUni
                        if @WTipPrz = 'L' 
                          Set @WPPerDscPde = @WPPerDscLin  -- Per_Desconto
                        else
                          Set @WPPerDscPde = @WPPerDscPrz  -- Per_Descon

                        Set @WPCodPrjPde = @WIte_CodProjeto
                        Set @WPNumSeqPdc = @WIte_NumSeqPdc
                        Set @WPTipSai = @WIte_TipSai
                     
                        -- calcfields 
                        -- arredonda prc_unitario conforma parametro do sistema
                        Set @WPPrcUni = Round(@WPPrcUni,@pm_QtdDecPrcItePdv)

                        if @WPFatCnvImpFat <> @WIte_FatCnvImpFat
                          Set @WPFatCnvImpFat = @WIte_FatCnvImpFat   -- em 23/08/2020
                        Set @WPQtdImpFat = Round((@WIte_QtdPedInf + @WIte_QtdBonInf)/@WIte_FatCnvImpFat,0)  -- calculado na trigger
                        Set @WPPrcUniImpFat = @WPPrcUni * @WIte_FatCnvImpFat  -- calculado na trigger

                        Set @WPC_PrcUni = @WPPrcUni
                        if @WTipPrz = 'L'
                          Set @WPC_PerDscIte = @WPPerDscLin
                        else
                          Set @WPC_PerDscIte = @WPPerDscPrz
                     
                        --  calcula preco unitario liquido
                        Set @WPPrcUniLiqPdv = @WPPrcUni*(1-@WPC_PerDscIte/100)
                        
                        --Set @WPC_VlrDesconto = 0
                        if @WPFlgEmbDscPrc = 1
                          begin
                            if @WTipPrz = 'L'
                              Set @WPC_PrcUni = @WPPrcUni*(1-@WPPerDscLin/100)
                            else
                              Set @WPC_PrcUni = @WPPrcUni*(1-@WPPerDscPrz/100)
                        
                            Set @WPC_PerDscIte = 0
                          end
                        
                        --Set @WPC_VlrDesconto = Round(@WIte_QtdPedInf*@WPC_PrcUni,2) - Round(@WIte_QtdPedInf*@WPC_PrcUni*(1-@WPC_PerDscIte/100),2)  -- calculado na trigger
                        --Set @WPC_PrcTotal = Round(@WIte_QtdPedInf*@WPC_PrcUni,2) - @WPC_VlrDesconto   -- trigger
                        
                        Set @WFlgSnhEsp = 0 
                        Set @WNomUsuSnhEsp = ''
                        Set @WFlgCriVrb = 0        -- coloquei

                       -- preço mínimo
                        Set @WPPrcMin = 0   -- calcula na critica
                        Set @WPVlrVrbDis = 0 -- calcula na critica

						-- tem que informar atual: @WPPrcPolCom, @WPQtdPrzPolCom, @WPPerDscPolCom, @WPPerDscVisPolCom  (InfoDefault)

                        --  normaliza campos: @WTipImpPrcPdv = (A)ceita, (R)ejeita, (I)gnora 
                        if @WTipImpPrcPdv = 'A'
                          Set @WFlgBlqCriConCom = 1
                        else
                          Set @WFlgBlqCriConCom = 0

                        if ((@WIte_FlgPrcInf = 1) or (@WIte_FlgDscInf = 1)) and 
                           (@WTipImpPrcPdv = 'A') 
                          Set @WFlgBlqCriPrcVen = 1 
                        else
                          Set @WFlgBlqCriPrcVen = 0

                        Exec PR_CriticaItemPDVIT @pm_FlgUsaPolComPdv, @PCodEstabe, @PNumPdv, @WIte_CodPrd, @WPTipSai,
                                                 @WIte_IdPolCom, @WIte_QtdPedInf output, @WIte_QtdBonInf, @WPQtdPrzMax output,
                                                 @WPPrcUni, @WPPerDscLin output, @WPPerDscPrz output, @WPPerDscVis output, 
                                                 @WPFatCnvImpFat, @WPQtdImpFat output, @WPPrcUniImpFat,
                                                 @WPPrcTabBru, @WPPrcTab output, @WPPrcUniLiqPer output, @WPPrcMin,
                                                 @WPCodKitPrm, @WPPrcCusMinComMarkup, 
                                                 @WPPrcPolCom output, @WPQtdPrzPolCom output, @WPPerDscPolCom output, @WPPerDscVisPolCom output, 
                                                 @WPFlgVerba output, @WPVlrVrbDis, @WFlgSnhEsp, @WNomUsuSnhEsp,
                                                 @WIte_FlgBlqQtdPar, @WFlgBlqCriConCom, @WFlgBlqCriPrcVen, @WFlgCriVrb, @WFlgBlqDscAutIte,
                                                 @WIte_QtdSolInf output, @WIte_QtdAceInf output, @WPFlgPolPrm output, @WPCodPromoc output, 
                                                 @WPCodRej output, @WPDesMsg output, @WPCmp output, @WPNomUsuDbq output, @WPDesMsgDbq  output

                    --Set @WIte_QtdPedInf = @WIte_QtdPed*@WIte_FatAprPad
                    --Set @WIte_QtdBonInf = @WIte_QtdBon*@WIte_FatAprPad
                    --Set @WIte_PrcUniInf = @WIte_PrcUni/@WIte_FatAprPad
---------------------------------------------------------------------------------------------------

                        if (@WPDesMsg = '') or (Substring(@WPCodRej,1,2) = 'PZ')  
                          begin
                            Set @WPCodRej = ''
                            Set @WPDesMsg = ''
                          end
                        else
                          begin
                            Set @WIte_QtdPedInf = 0
                            Set @WIte_QtdBonInf = 0
                          end

                        Insert Into PDVIT (Cod_Estabe, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai)
                          Values (@PCodEstabe, @PNumPdv, @WIte_CodPrd, @WPCodLot, @WPTipSai)

                        Update PDVIT
                           Set Num_SeqDig = @WNumSeqIte,
                               Qtd_Pedido = @WIte_QtdPedInf, 
                               Qtd_Bonificacao = @WIte_QtdBonInf, 
							   Id_PolCom = @WIte_IdPolCom, 
							   Loc_Fisica = @WPLocFis,   
							   Cod_Fabricante = @WPCodFab,
                               Qtd_PrzMax = @WPQtdPrzMax, 
							   Prc_Fabric = @WPPrcFab, 
							   Prc_MaxCon = @WPPrcMaxCon, 
							   Prc_RefFpb = @WPPrcRefFpb,   
							   Prc_Tabela = @WPPrcTab, 
							   Prc_TabBru = @WPPrcTabBru, 
                               Prc_Unitario = @WPPrcUni, 
							   Per_Desconto = @WPPerDscLin, 
							   Per_Descon = @WPPerDscPrz,   
							   Per_DscVis = @WPPerDscVis,  
							   Flg_Verba = @WPFlgVerba,  
							   Prc_CusMinComMarkup = @WPPrcCusMinComMarkup, 
                               Qtd_PrzPolCom = @WPQtdPrzPolCom, 
							   Prc_PolCom = @WPPrcPolCom, 
							   Per_DscPolCom = @WPPerDscPolCom, 
							   Per_DscVisPolCom = @WPPerDscVisPolCom,  
							   Cod_KitPrm = @WPCodKitPrm,    
							   Cod_Promocao = @WPCodPromoc,
                               Fat_CnvImpFat = @WIte_FatCnvImpFat, 
							   Qtd_ImpFat = @WPQtdImpFat,          -- calculado na trigger
							   Prc_UniImpFat = @WPPrcUniImpFat,    -- calculado na trigger
							   Des_UnvImpFat = @WIte_DesUnvImpFat, 
							   Des_AprImpFat = @WIte_DesAprImpFat, 
                               Prc_UniPde = @WPPrcUniPde, 
							   Per_DscPde = @WPPerDscPde, 
							   Cod_PrjPde = @WPCodPrjPde, 
							   Num_SeqPdc = @WPNumSeqPdc, 
                               Flg_PrcUniDsc = @WPFlgEmbDscPrc, 
							   C_PrcUni = @WPC_PrcUni, 
							   C_PerDscIte = @WPC_PerDscIte, 
							   --C_VlrDesconto = @WPC_VlrDesconto, -- calculado na trigger
                               --C_PrcTotal = @WPC_PrcTotal,     -- calculado na trigger
							   Prc_UniLiqPer = @WPPrcUniLiqPer, 
							   Qtd_Solicitado = @WIte_QtdSolInf, 
							   Qtd_Acerto = @WIte_QtdAceInf,
                               Flg_PolPrm = @WPFlgPolPrm, 
							   Cod_MtvRej = @WPCodRej, 
							   Des_MtvRej = Substring(@WPDesMsg,1,80), 
							   Nom_UsuDesbloq = Substring(@WPNomUsuDbq,1,15), 
							   Des_MsgDesbloq = Substring(@WPDesMsgDbq,1,60)
                         Where Cod_Estabe  = @PCodEstabe
                           And Cod_Pedido  = @PNumPdv 
                           And Cod_Produto = @WIte_CodPrd 
                           And Cod_Lote    = @WPCodLot 
                           And Tip_Sai     = @WPTipSai

                        Set @WNumSeqIte = @WNumSeqIte + 1
   
                        --  abate quantidade atendida
                        Update it 
                           Set it.Qtd_Pedido = Round(it.Qtd_Pedido*(1-IsNull(lg.Per_AbatimQtd,0)/100),0) 
                          From dbo.PDVIT it 
                               Inner Join dbo.PDVCB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Cod_Pedido = cb.Numero 
                               Inner JOIN dbo.LGXGC lg on lg.Cod_Estabe = cb.Cod_Estabe and lg.Cod_Layout = @PCodLayout And
                                                          lg.Cod_Grupo = @pe_CodGrpClp and lg.Cod_GrpCli = cb.Cod_GrpCli 
                         Where cb.Cod_Estabe  = @PCodEstabe
                           And cb.Numero      = @PNumPdv
                           And it.Cod_Produto = @WIte_CodPrd 
                           And it.Cod_Lote    = @WPCodLot
                           And it.Tip_Sai     = @WPTipSai
                           And IsNull(lg.Per_AbatimQtd,0) > 0 
                           And it.Qtd_Pedido >= IsNull(lg.Qtd_AbatimMin,0) 

                        --  atualiza motivo qdo for o caso
                        Update it 
                           Set it.Cod_MtvRej = Case 
                                                 When it.Qtd_Pedido > 0 then 'ES-' 
                                                 Else 'ES0'
                                               End 
                          From dbo.PDVIT it 
                         Where it.Cod_Estabe = @PCodEstabe
                           And it.Cod_Pedido = @PNumPdv
                           And it.Cod_Produto = @WIte_CodPrd 
                           And it.Cod_Lote = @WPCodLot
                           And it.Tip_Sai = @WPTipSai
                           And it.Qtd_Pedido < it.Qtd_Solicitado 
                           And IsNull(it.Cod_MtvRej,'') = '' 
                      end  -- if @WPFlgAchou = 1
                    else
                      begin
                        Set @WIte_CodRej = 'PRX'    --  produto invalido
                      end

                  end  

                else
                  begin
                    -- acumula em PDVIT
                    Update dbo.PDVIT 
                       Set Qtd_Pedido = Qtd_Pedido + @WIte_QtdPedInf
                     Where Cod_Estabe = @PCodEstabe
                       And Cod_Pedido = @PNumPdv
                       And Cod_Produto = @WIte_CodPrd
                       And Cod_Lote = @pvit_CodLot
                  end

                -- registra falta e motivo de rejeicao
                Set @WFatCnvCxaFec = 1
                if (@WIte_CodPrdEmbFec <> '') and (@WIte_QtdEmbFec > 0) 
                  Set @WFatCnvCxaFec = @WIte_QtdEmbFec

                Exec PR_VerificaFaltasPdv false, @PCodEstabe, @PNumPdv, @WIte_CodPrd, @WFatCnvCxaFec, @WTipPrz,
                                          @WQtdPedAte output, @WIte_PrcUniInf output, @WIte_PerDscInf output, @WIte_CodRej output

              end  --if @WIte_CodPrd > 0
            else
              begin
                Set @WQtdPedAte = 0
              end

            -- aquix WQtdPedAte converter WIte_PrcUni
            if @WIte_PrcUni = 0
              Set @WIte_PrcUni = Round((@WIte_PrcUniInf*@WIte_FatAprPad),@pm_QtdDecPrcItePdv)

            if (@WIte_PrcUniImpFat = 0) and (@WIte_FatCnvImpFat > 1) 
              Set @WIte_PrcUniImpFat = Round((@WIte_PrcUniInf*@WIte_FatAprPad),@pm_QtdDecPrcItePdv) * @WIte_FatCnvImpFat

            Set @WQtdPedAte = @WQtdPedAte/@WIte_FatAprPad

            -- Atualizar PDEIT.Fat_AprPad : @WIte_FatAprPad
            Update dbo.PDEIT
               Set Fat_CnvImpFat = @WIte_FatCnvImpFat,
                   Fat_AprPad    = @WIte_FatAprPad,
                   Des_UnvImpFat = @WIte_DesUnvImpFat,
                   Des_AprImpFat = @WIte_DesAprImpFat,
                   Prc_UniImpFat = @WIte_PrcUniImpFat
             Where Cod_Estabe = @PCodEstabe
               And Cod_Layout = @PCodLayout
               And Num_Cnpj   = @PNumCnpj
               And Cod_PedCli = @PCodPedCli
               And Num_Desdob = @PNumDesdob
               And Cod_PrdCli = @WIte_CodPrdArq

            Delete 
              From @tb_PDEIT 
             Where Chave = @WIte_Chave
          end

      end  

------------------------------------------------------------------------------------------------------------------------------------------------------

    -- Finaliza
    Update dbo.PDVCB 
       Set Status2 = 'A',
           Cod_LayoutPde = @PCodLayout,
           Des_LayoutPde = @WDesLayout
     Where Cod_Estabe = @PCodEstabe
       And Numero = @PNumPdv
       And Status2 = 'X'

    Update dbo.PDECB
       Set Sta_Pedido = '1', 
           Num_PedVen = @PNumPdv,
           Msg_Erro = Substring(@PMsgErr,1,400)
    Where Cod_Estabe = @PCodEstabe
      And Cod_Layout = @PCodLayout
      And Num_Cnpj   = @PNumCnpj
      And Cod_PedCli = @PCodPedCli
      And Num_Desdob = @PNumDesdob
      And Sta_Pedido = '0'

    Update dbo.PDEIT
       Set Cod_MtvRej    = 'PRX',
           Cod_MtvRejOri = 'PRX'
     Where Cod_Estabe = @PCodEstabe
       And Cod_Layout = @PCodLayout
       And Num_Cnpj   = @PNumCnpj
       And Cod_PedCli = @PCodPedCli
       And Num_Desdob = @PNumDesdob
       And Cod_Produt = 0

    Update it
       Set it.Cod_MtvRej    = ipv.CodMtvRej, 
	       it.Cod_MtvRejOri = ipv.CodMtvRej, 
	       --it.Des_MtvRej, 
		   it.Qtd_Atendi    = ipv.QtdPdv,
		   it.Prc_Unitario  = ipv.PrcUnitar,
		   it.Per_Desconto  = ipv.PerDescon,
		   it.Fat_CnvImpFat = ipv.FatCnvImp,
		   it.Des_UnvImpFat = ipv.DesUnvImp,
		   it.Des_AprImpFat = ipv.DesAprImp,
		   it.Prc_UniImpFat = ipv.PrcUniImp
      From dbo.PDECB cb
           Inner Join dbo.PDEIT it on cb.Cod_Estabe = it.Cod_Estabe and 
	                                  cb.Cod_Layout = it.Cod_Layout and
	                                  cb.Num_Cnpj = it.Num_Cnpj and
		                              cb.Cod_PedCli = it.Cod_PedCli and
      				                  cb.Num_Desdob = it.Num_Desdob
           Inner Join (Select Cod_Estabe, Cod_Pedido, Cod_Produto,
                              QtdPdv = sum(Qtd_Pedido+Qtd_Bonificacao),
                              CodMtvRej = max(IsNull(Cod_MtvRej,'')),
                              PrcUnitar = max(Prc_Unitario),
                              PerDescon = max(Per_Desconto),
                              FatCnvImp = max(Fat_CnvImpFat),
                              DesUnvImp = max(Des_UnvImpFat),
                              DesAPrImp = max(Des_AprImpFat),
                              PrcUniImp = max(Prc_UniImpFat)
                         From dbo.PDVIT
                        Where Cod_Estabe = @PCodEstabe
                          And Cod_Pedido = @PNumPdv
                        Group by Cod_Estabe, Cod_Pedido, Cod_Produto) ipv on it.Cod_Estabe = ipv.Cod_Estabe and 
                                                                             cb.Num_PedVen = ipv.Cod_Pedido and 
                                                                             it.Cod_Produt = ipv.Cod_Produto 
     Where cb.Cod_Estabe = @PCodEstabe
       And cb.Cod_Layout = @PCodLayout
       And cb.Num_Cnpj   = @PNumCnpj
       And cb.Cod_PedCli = @PCodPedCli
       And cb.Num_Desdob = @PNumDesdob


    -- PDEIT.Qtd_Atendi deve está alimentado antes do cálculo do total
    declare @VlrTotal numeric(18,8)
	set @VlrTotal = 
			Round((Select Sum(Round(Qtd_Atendi*Prc_Unitario*(1-IsNull(Per_Desconto,0)/100),2)) 
				   From dbo.PDEIT 
				   Where Cod_Estabe = @PCodEstabe 
				     And Cod_Layout = @PCodLayout 
					 And Num_Cnpj = @PNumCnpj 
					 And Cod_PedCli = @PCodPedCli 
					 And Num_Desdob = @PNumDesdob),2)
	set @VlrTotal = ISNULL(@VlrTotal, 0)

    Update dbo.PDECB
       Set Vlr_Total = @VlrTotal
    Where Cod_Estabe = @PCodEstabe
      And Cod_Layout = @PCodLayout
      And Num_Cnpj   = @PNumCnpj
      And Cod_PedCli = @PCodPedCli
      And Num_Desdob = @PNumDesdob
      And ISNULL(Vlr_Total, 0) <> @VlrTotal


    --  verifica se pedido pode ser rejeitado
    Exec PR_RejeitaPDVCB @PCodEstabe, @PNumPdv, @pe_FlgFatPedIntegral, @WPCodRej output, @WPDesMsg output

    if @WPCodRej <> ''
      begin
        if Exists(Select Numero From dbo.PDVCB 
                   Where Cod_Estabe = @PCodEstabe
                     And Numero = @PNumPdv
                     And Status1 = 'P'
                     And ((Status2 = 'A') or (Status2 = 'X')))
          begin
            Delete From dbo.PDVCB 
             Where Cod_Estabe = @PCodEstabe
               And Numero = @PNumPdv
   
            Set @PNumPdv = 0

            -- zera qtds atendidas em PDEIT
            Update dbo.PDEIT 
               Set Qtd_Atendi = 0
             Where Cod_Estabe = @PCodEstabe
               And Cod_Layout = @PCodLayout
               And Num_Cnpj = @PNumCnpj
               And Cod_PedCli = @PCodPedCli
               And Num_Desdob = @PNumDesdob
   
            -- motivos de rejeicao
            if not ((@WDesLayout = 'CLAMED') or
                    (@WDesLayout = 'PDVLINK_TEUTO') or
                    (@WDesLayout = 'PDVLINK_AUGEFARMA') or 
                    (@WDesLayout = 'PDVLINK_INOVA') or 
                    (@WDesLayout = 'PDVLINK_REDEMED') or 
                    (@WDesLayout = 'PDVLINK_NATULAB') or
                    (@WDesLayout = 'WEBLINE') or 
                    (@WDesLayout = 'CALLFARMA') or
                    (@WDesLayout = 'CLOSEUP')) 
              begin
                Update dbo.PDEIT 
                   Set Cod_MtvRej = @WPCodRej,
                       Des_MtvRej = Substring(@WPDesMsg,1,80)
                 Where Cod_Estabe = @PCodEstabe
                   And Cod_Layout = @PCodLayout
                   And Num_Cnpj   = @PNumCnpj
                   And Cod_PedCli = @PCodPedCli
                   And Num_Desdob = @PNumDesdob
                   And IsNull(Cod_MtvRej,'') = ''
              end  -- if not ((@WDesLayout = 'WEBLINE') or

            Update dbo.PDECB 
               Set Vlr_Total = 0,
                   Num_PedVen = 0, 
                   Cod_MtvRej = @WPCodRej, 
                   Des_MtvRej = Substring(@WPDesMsg,1,40)  
             Where Cod_Estabe = @PCodEstabe
               And Cod_Layout = @PCodLayout
               And Num_Cnpj   = @PNumCnpj
               And Cod_PedCli = @PCodPedCli
               And Num_Desdob = @PNumDesdob

          end  -- if Exists(Select Numero From dbo.PDVCB 
      end  -- if @WPCodRej <> ''

    if @@trancount > 0
      COMMIT TRANSACTION
  end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CalcTributItemEntrada]
@PCodEstabe int,
@PDatMov smalldatetime,
@PDatEmi smalldatetime,
@PTipNot char(1),
@PCfoCab smallint,
@PCodRegTri int,

@PFlgCalIcmSbt bit,       
@PFlgCalIcmPro bit,       
@PFlgCalRepIcm bit,       
@PFlgCalPisCof bit,       
@PFlgCalIpi bit,
@PFlgDscIcmDesone bit,                  -- icms desonerado eh abatido no valor da nf
@PFlgIncIpiBasIcmTrib bit,              -- adiciona valor ipi ICMS tributável para notas de devolução de uso e consumo

@PClaTri varchar(4),                    -- classificacao tributaria do produto ja existente/importado/devolucao
@PTipLisPis varchar(1),
@PFlgSbtEmbPrc bit,                     -- indica ST embutida no preço

@PCodPrd int,
@PQtdPed int,
@PQtdBon int,
@PPrcUniIte numeric(18,8),
@PPerDscIte numeric(18,8),

@PVlrDscRat numeric(18,4),          
@PVlrDspTot numeric(18,4),              -- despesas totais: frete, seguro, ....
@PVlrDspSbt numeric(18,4), 
@PVlrIpi numeric(18,4),    
@PVlrBasSuf numeric(18,4),
@PVlrTaxSuf numeric(18,4),

@PArqPrcFab numeric(18,4),              -- Pr.Fabrica em PDVIT os NFSIT
@PArqPrcVen numeric(18,4),              -- Pr.Venda
@PArqPrcMax numeric(18,4),              -- Pr.Max.Consumidor
@PArqPrcRefFpb numeric(18,4),           -- Pr.Ref.Farmacia Popular
@PArqPrcPon numeric(18,4),              -- Pr.Medio Ponderado Consumidor Final

@PPrcFab numeric(18,4) output,          -- Pr.Fabrica
@PPrcVen numeric(18,4) output,          -- Pr.Venda
@PPrcMax numeric(18,4) output,          -- Pr.Max.Consumidor
@PPrcRefFpb numeric(18,4) output,       -- Pr.Ref.Farmacia Popular
@PPrcPonFin numeric(18,4) output,       -- Pr.Medio Ponderado Consumidor Final

@PCodModBasCalIcm char(1) output,
@PCodModBasCalIcmSbt char(1) output,
@PCodSt varchar(2) output,
@PCodCsosn varchar(3) output,
@PCstIpi varchar(2) output,
@PCstPis varchar(2) output,
@PCstCof varchar(2) output,
@PTipPrcBasDebSbt varchar(1) output,
@PTipPrcBasCreSbt varchar(1) output,
@PBasTri numeric(18,4) output,          -- valor base tributação
@PAlqIcm numeric(18,4) output,
@PBasIcmPro numeric(18,4) output,       -- Base ICMS proprio
@PIcmPro numeric(18,4) output,          -- ICMS proprio
@PVlrPrdSub numeric(18,4) output,
@PBasSubFnt numeric(18,4) output,
@PVlrSubFnt numeric(18,4) output,
@PBasSbtRes numeric(18,4) output,
@PVlrSbtRes numeric(18,4) output,
@PBasSubRec numeric(18,4) output,
@PVlrSubRec numeric(18,4) output,
@PBasIcm numeric(18,4) output,          -- base icms tributavel
@PVlrIcm numeric(18,4) output,          -- icms tributavel
@PBasIpi numeric(18,4) output,
@PVlrIse numeric(18,4) output,
@PVlrPrdAnt numeric(18,4) output,
@PBasAnt numeric(18,4) output,
@PVlrAnt numeric(18,4) output,
@PVlrOut numeric(18,4) output,
@PPerRedBasCalIcmDeb numeric(18,4) output,
@PAlqAgrDeb numeric(18,4) output,
@PPerRedBasCalDeb numeric(18,4) output,
@PAlqIcmDeb numeric(18,4) output,
@PVlrDebIcm numeric(18,4) output,
@PPerRedBasCalIcmCre numeric(18,4) output,
@PPerLimBasCalCreSbt numeric(18,4) output,
@PVlrLimCreIcm numeric(18,4) output,
@PVlrDspSubCusCreIcm numeric(18,4) output,
@PVlrBasPis numeric(18,4) output,
@PAlqPis numeric(18,4) output,
@PVlrPis numeric(18,4) output,
@PVlrBasCof numeric(18,4) output,
@PAlqCof numeric(18,4) output,
@PVlrCof numeric(18,4) output,
@PVlrSuf numeric(18,4) output,
@PVlrDsp numeric(18,4) output,
@PFlgUsaCreIcmSbt bit output,

@PAlqIpi numeric(18,4) output,
@PCodNcm varchar(8) output,

@PFlgUsaCrePresum bit output,
@PAlqCrePresum numeric(18,4) output,

@PDatRefPrdCip datetime output,

-- novos em 15/01/2019
@PAlqIcmFcp numeric(18,4) output,
@PVlrIcmFcp numeric(18,4) output,       -- icms tributavel FCP: embutido em @PVlrIcm
@PAlqIcmSbtFcp numeric(18,4) output,
@PVlrSubFcp numeric(18,4) output,
@PAlqIcmSbtFcpRet numeric(18,4) output,
@PVlrSubFcpRet numeric(18,4) output,
@PAlqIcmSbtFcpRec numeric(18,4) output,
@PVlrSubFcpRec numeric(18,4) output,
@PAlqIcmSbtFcpAnt numeric(18,4) output,
@PVlrSubFcpAnt numeric(18,4) output,

--novos em 11/06/2019
@PPerIcmDiferi numeric(18,4) output,
@PVlrIcmDiferi numeric(18,4) output,

-- novo em 19/11/2019
@PVlrIcmDesone numeric(18,4) output,      -- icms desonerado
@PMtvIcmDesone varchar(1) output,         -- cod.motivo icms desonerado
@PVlrDst numeric(18,4) output             -- icms desonerado concedido como desconto (desconto de tributacao)

AS

SET NOCOUNT ON 

Begin Transaction

-- variaveis de trabalho
Declare @WQtdLoop tinyint, 
        @WClaTriExt varchar(4),
        @WQtdDecRndTrb tinyint,
        @PObsNf varchar(200),
        @WLiq numeric(18,4),
        @WVlrIte numeric(18,4),
        @WCre numeric(18,4),
        @WCreFcp numeric(18,4),
		@WIcmProFcp numeric(18,4),
        @WCreSbt numeric(18,4),
        @WCreSbtFcp numeric(18,4),
        @WVlrPrdSbt numeric(18,4),
        @WVlrImpSbt numeric(18,4),
        @WVlrPrdSbtLim numeric(18,4),
        @WVlrMinSbt numeric(18,4),
        @WVlrMinBasCalSbt numeric(18,4),
        @WVlrBasSbt numeric(18,4),
        @WVlrBasLimCreSbt numeric(18,4),

        @WVlrPrdSbtOpc numeric(18,4),
        @WVlrImpSbtOpc numeric(18,4),
        @WVlrDebIcmOpc numeric(18,4),

        @WPrcAux numeric(18,4),
        @it_Vlr_TotIte numeric(18,4),
        @it_Vlr_BruIte numeric(18,4)
        
-- variaveis de trabalho extra
Declare @WPerRepIcm numeric(18,4),
        @WPerDspSubCusCreIcm numeric(18,4),
        @WAlqIcmExt numeric(18,4),
        @WAlqIcmExtFcp numeric(18,4),
        @WCtrBasCalDeb varchar(1),
        @WCtrBasCalCre varchar(1),
        @WAlqAgrDeb numeric(18,4),
        @WFatSubTriDeb numeric(18,4),
        @WPerRedBasCalDeb numeric(18,4),
		@WTipPrcLimMinIcmSbt varchar(1),
        @WPerLimMinIcmSbt numeric(18,4),
        @WPerRedBasCalDebOpc numeric(18,4),
        @WTipPrcLimMinBasCalIcmSbt varchar(1),
        @WPerLimMinBasCalIcmSbt numeric(18,4),
        @WAlqAgrLimMinBasCalIcmSbt numeric(18,4),
        @WPerResExt numeric(18,4),
        @WTipCreSbt varchar(1),
        @WAlqDebSbt numeric(18,4),
        @WFlgImpSbtFnt bit,
        @WPerRedBasCalIcmInt numeric(18,4),
        @WAlqIcmInt numeric(18,4),
        @WAlqIcmIntFcp numeric(18,4),
        @WVlrBasPisCof numeric(18,4),
        @WFlgUsaCrePresum bit,
        @WFlgDatEmiPrdCip bit,
        @WFlgDatAntUltAtuPrdCip bit,
        @WAlqCrePresum numeric(18,4),
        @WDatAntUltAlt smalldatetime,
        @WVlrBasResExt numeric(18,4),
        @PVlrBasCalSubTriEntMed numeric(18,4),
        @WDebSbtFcp numeric(18,4),
        @WPerIcmDesRedBasCal numeric(18,4),
        @WPerIcmDesone numeric(18,4),
        @WCodMtvDesone varchar(2),
        @WFlgDscDesIcm bit,
        @WFlgIcmIsento bit

Declare @em_CodTipLuc varchar(2),
        @em_DesEstado varchar(2),
        @pm_FlgExcIcmCalPis bit = 0,
        @pm_FlgIncIpiCalPis bit

Declare @pr_PrcFab numeric(18,4),
        @pr_PrcVen numeric(18,4),
        @pr_PrcMax numeric(18,4),
        @pr_PrcRefFpb numeric(18,4),
        @pr_VlrBasCalSubTriEntMed numeric(18,4)

Declare @rt_ClaTriExt varchar(4),
        @rt_Cod_ImpNotSai varchar(2),
        @rt_Cod_CSOSNSai varchar(3),
        @rt_Tip_PrcBasDebSbt char(1),
        @rt_Ctrl_BasCalDebSai char(1),
        @rt_Alq_AgrDebSai numeric(18,4),
        @rt_Per_RedBasCalDebSai numeric(18,4),
        @rt_Per_LimMinIcmSbtSaiRedDeb numeric(18,4),        
        @rt_Tip_PrcLimMinBasCalIcmSbtSai varchar(1),    -- em 08/01/2019
        @rt_Alq_AgrLimMinBasCalIcmSbtSai numeric(18,4), -- em 08/01/2019       
        @rt_Per_ResExtSai numeric(18,4),        
        @rt_Tip_CreSbtSai char(1),
        @rt_Alq_DebSbtSai numeric(18,4),
        @rt_Alq_IcmIntReg numeric(18,4),
        @rt_Per_AcrAlqIntFcpReg numeric(18,4),
        @rt_Per_RedBasCalIntReg numeric(18,4),
        @rt_Tip_PrcBasCreSbtSai char(1),
        @rt_Ctrl_BasCalCreSai char(1),
        @rt_Alq_IcmExtLoc numeric(18,4),
        @rt_Per_AcrAlqExtFcpLoc numeric(18,4),
        @rt_Per_RedBasCalExtLoc numeric(18,4),
        @rt_Per_IcmDiferiExtLoc numeric(18,4),
        @rt_Per_IcmDesoneExtLoc numeric(18,4),
        @rt_Cod_MtvDesIcmLoc varchar(2),
        @rt_Flg_DscDesIcmLoc bit,
        @rt_C_PerRepIcmLoc numeric(18,4),
        
        @rt_Cod_ImpNotEnt varchar(2),
        @rt_Cod_CSOSNEnt varchar(3),
        @rt_Tip_PrcBasSbtEnt varchar(1),
        @rt_Ctrl_BasCalDebEnt varchar(1),
        @rt_Alq_AgrDebEnt numeric(18,4),
        @rt_Per_RedBasCalDebEnt numeric(18,4),
        @rt_Tip_PrcLimMinBasCalIcmSbtEnt varchar(1),
        @rt_Per_LimMinBasCalIcmSbtEnt numeric(18,4), 
        @rt_Per_ResExtEnt numeric(18,4),        
        @rt_Tip_CreSbtEnt varchar(1),
        @rt_Alq_DebSbtEnt numeric(18,4),
        @rt_Flg_ImpSbtFntEnt bit, 
        @rt_Alq_IcmIntLoc numeric(18,4),
        @rt_Per_AcrAlqIntFcpLoc numeric(18,4),
        @rt_Per_RedBasCalIntLoc numeric(18,4),
        @rt_Tip_PrcBasCreSbtEnt varchar(1),
        @rt_Ctrl_BasCalCreEnt varchar(1),
        @rt_Per_LimBasCalCreSbtEnt numeric(18,4),
        @rt_Alq_IcmExtReg numeric(18,4),
        @rt_Per_AcrAlqExtFcpReg numeric(18,4),
        @rt_Per_RedBasCalExtReg numeric(18,4),
        @rt_Per_IcmDiferiExtReg numeric(18,4),
        @rt_Per_IcmDesoneExtReg numeric(18,4),
        @rt_Cod_MtvDesIcmReg varchar(2),
        @rt_Flg_DscDesIcmReg bit,
        @rt_C_PerRepIcmReg numeric(18,4),
		@rt_Tip_PrcLimMinIcmSbtEnt varchar(1),
        @rt_Per_LimMinIcmSbtEnt numeric(18,4),
        @rt_Per_RedBasCalDebEntOpc numeric(18,4),
		@rt_PerDspCusEnt  numeric(18,4),

		@rt_Alq_CrePresum numeric(18,4),
        @rg_Flg_UsaCrePresum bit,
        @rg_Flg_DatEmiPrdCip bit,
		@rg_Flg_DatAntUltAtuPrdCip bit,
        @ct_FlgSujAntIcm bit

-- coloca campos de tabelas na memoria
-- ESTAB / PARAM
Select @em_CodTipLuc = IsNull(Cod_TipLucro,''),
       @em_DesEstado = IsNull(Des_Estado,'')
  From ESTAB
Where Cod_Estabe = @PCodEstabe  

Select @pm_FlgIncIpiCalPis = IsNull(FlgIncIpiCalPis,0),
       @pm_FlgExcIcmCalPis = IsNull(FlgExcIcmCalPis,0)
  From PARAM
Where Cod_Estabe = @PCodEstabe  


-- qtd casa decimais para arredondamento de tributos
-- as bases de calculo sempre 2 casas
Set @WQtdDecRndTrb = 2

Set @WQtdLoop = 1

LOOP_INICIO:

Set @PBasTri    = 0
Set @PBasIcmPro = 0
Set @PAlqIcm    = 0
Set @PIcmPro    = 0
Set @PBasIcm    = 0
Set @PVlrIcm    = 0
Set @PVlrIse    = 0
Set @PVlrOut    = 0

Set @PVlrPrdSub = 0
Set @PBasSubFnt = 0
Set @PVlrSubFnt = 0
Set @PBasSbtRes = 0
Set @PVlrSbtRes = 0
Set @PBasSubRec = 0
Set @PVlrSubRec = 0
Set @PVlrPrdAnt = 0
Set @PBasAnt    = 0
Set @PVlrAnt    = 0

Set @PBasIpi    = 0
Set @PVlrSuf    = 0
Set @PVlrDsp    = 0

Set @PPerRedBasCalIcmDeb = 0
Set @PAlqAgrDeb = 0
Set @PPerRedBasCalDeb = 0
Set @PAlqIcmDeb = 0
Set @PVlrDebIcm = 0
Set @PPerRedBasCalIcmCre = 0
Set @PPerLimBasCalCreSbt = 0
Set @PVlrLimCreIcm = 0
Set @PVlrDspSubCusCreIcm = 0
Set @PCodModBasCalIcm = ''
Set @PCodModBasCalIcmSbt = ''
Set @PFlgUsaCreIcmSbt = 0
Set @PAlqIpi = 0
Set @PCodNcm = ''
Set @PFlgUsaCrePresum = 0
Set @PAlqCrePresum = 0
Set @PObsNf = ''

Set @PAlqIcmFcp = 0
Set @PVlrIcmFcp = 0
Set @PAlqIcmSbtFcp = 0
Set @PVlrSubFcp = 0
Set @PAlqIcmSbtFcpRet = 0
Set @PVlrSubFcpRet = 0
Set @PAlqIcmSbtFcpRec = 0
Set @PVlrSubFcpRec = 0
Set @PAlqIcmSbtFcpAnt = 0
Set @PVlrSubFcpAnt = 0

Set @PPerIcmDiferi = 0
Set @PVlrIcmDiferi = 0

Set @PVlrIcmDesone = 0
Set @PMtvIcmDesone = ''
Set @PVlrDst = 0

Set @WVlrBasResExt = 0
Set @WIcmProFcp = 0
Set @WDebSbtFcp = 0

-- coloca campos de RTXCT na memoria
Select @rt_Cod_ImpNotSai  = IsNull(rx.Cod_ImpNotSai,''),
       @rt_Cod_CSOSNSai = IsNull(rx.Cod_CSOSNSai,''),
       @rt_ClaTriExt = IsNull(rx.Cod_ClaTriExt,''),
       @rt_Tip_PrcBasDebSbt = IsNull(rx.Tip_PrcBasDebSbt,''),
       @rt_Ctrl_BasCalDebSai = IsNull(rx.Ctrl_BasCalDebSai,''),
       @rt_Alq_AgrDebSai = Isnull(rx.Alq_AgrDebSai,0),
       @rt_Per_RedBasCalDebSai = Isnull(rx.Per_RedBasCalDebSai,0),
       @rt_Per_LimMinIcmSbtSaiRedDeb = IsNull(rx.Per_LimMinIcmSbtSaiRedDeb,0),

	   @rt_Tip_PrcLimMinBasCalIcmSbtSai = IsNull(rx.Tip_PrcLimMinBasCalIcmSbtSai,''),
	   @rt_Alq_AgrLimMinBasCalIcmSbtSai = IsNull(rx.Alq_AgrLimMinBasCalIcmSbtSai,0),

       @rt_Per_ResExtSai = IsNull(rx.Per_ResExtSai,0),
       @rt_Tip_CreSbtSai = Isnull(rx.Tip_CreSbtSai,''),
       @rt_Alq_DebSbtSai = Isnull(rx.Alq_DebSbtSai,0),
       @rt_Alq_IcmIntReg = Isnull(rx.Alq_IcmIntReg,0),
       @rt_Per_AcrAlqIntFcpReg = Isnull(rx.Per_AcrAlqIntFcpReg,0),
       @rt_Per_RedBasCalIntReg = Isnull(rx.Per_RedBasCalIntReg,0),
       @rt_Tip_PrcBasCreSbtSai = IsNull(rx.Tip_PrcBasCreSbtSai,''),
       @rt_Ctrl_BasCalCreSai = IsNull(rx.Ctrl_BasCalCreSai,''),
       @rt_Alq_IcmExtLoc = Isnull(rx.Alq_IcmExtLoc,0),
       @rt_Per_AcrAlqExtFcpLoc = Isnull(rx.Per_AcrAlqExtFcpLoc,0),
       @rt_Per_RedBasCalExtLoc = Isnull(rx.Per_RedBasCalExtLoc,0),
       @rt_Per_IcmDiferiExtLoc = Isnull(rx.Per_IcmDiferiExtLoc,0),
       @rt_Per_IcmDesoneExtLoc = Isnull(rx.Per_IcmDesoneExtLoc,0),
       @rt_Cod_MtvDesIcmLoc = Isnull(rx.Cod_MtvDesIcmLoc,'9'),
       @rt_C_PerRepIcmLoc = Isnull(rx.C_PerRepIcmLoc,0),
       @rt_Cod_ImpNotEnt  = IsNull(rx.Cod_ImpNotEnt,''),
       @rt_Cod_CSOSNEnt = IsNull(rx.Cod_CSOSNEnt,''),
       @rt_Tip_PrcBasSbtEnt = IsNull(rx.Tip_PrcBasSbtEnt,''),
       @rt_Ctrl_BasCalDebEnt  = IsNull(rx.Ctrl_BasCalDebEnt,''),
       @rt_Alq_AgrDebEnt = Isnull(rx.Alq_AgrDebEnt,0),
       @rt_Per_RedBasCalDebEnt = Isnull(rx.Per_RedBasCalDebEnt,0),
       @rt_Tip_PrcLimMinBasCalIcmSbtEnt = IsNull(Tip_PrcLimMinBasCalIcmSbtEnt,''),
       @rt_Per_LimMinBasCalIcmSbtEnt = IsNull(Per_LimMinBasCalIcmSbtEnt,0),
       @rt_Per_ResExtEnt = IsNull(rx.Per_ResExtEnt,0),
       @rt_Tip_CreSbtEnt = IsNull(rx.Tip_CreSbtEnt,''),
       @rt_Alq_DebSbtEnt = Isnull(rx.Alq_DebSbtEnt,0),
       @rt_Flg_ImpSbtFntEnt = IsNull(rx.Flg_ImpSbtFntEnt,0),
       @rt_Alq_IcmIntLoc = Isnull(rx.Alq_IcmIntLoc,0),
       @rt_Per_AcrAlqIntFcpLoc = IsNull(rx.Per_AcrAlqIntFcpLoc,0),
       @rt_Per_RedBasCalIntLoc = Isnull(rx.Per_RedBasCalIntLoc,0),
       @rt_Tip_PrcBasCreSbtEnt = IsNull(rx.Tip_PrcBasCreSbtEnt,''),
       @rt_Ctrl_BasCalCreEnt = IsNull(rx.Ctrl_BasCalCreEnt,''),
       @rt_Per_LimBasCalCreSbtEnt = IsNull(rx.Per_LimBasCalCreSbtEnt,0),
       @rt_Alq_IcmExtReg = Isnull(rx.Alq_IcmExtReg,0),
       @rt_Per_AcrAlqExtFcpReg = Isnull(rx.Per_AcrAlqExtFcpReg,0),
       @rt_Per_RedBasCalExtReg = Isnull(rx.Per_RedBasCalExtReg,0),
       @rt_C_PerRepIcmReg = Isnull(rx.C_PerRepIcmReg,0),
       @rt_Per_IcmDiferiExtReg = Isnull(rx.Per_IcmDiferiExtReg,0),
       @rt_Per_IcmDesoneExtReg = Isnull(rx.Per_IcmDesoneExtReg,0),
       @rt_Cod_MtvDesIcmReg = Isnull(rx.Cod_MtvDesIcmReg,'9'),
	   @rt_Tip_PrcLimMinIcmSbtEnt = IsNull(rx.Tip_PrcLimMinIcmSbtEnt,''),
       @rt_Per_LimMinIcmSbtEnt = IsNull(rx.Per_LimMinIcmSbtEnt,0),
       @rt_Per_RedBasCalDebEntOpc = IsNull(rx.Per_RedBasCalDebEntOpc,0),
	   @rt_PerDspCusEnt = IsNull(rx.Per_DspCusEnt,0),
       @rg_Flg_UsaCrePresum = IsNull(rg.Flg_UsaCrePresum,0),
       @rg_Flg_DatEmiPrdCip = IsNull(rg.Flg_DatEmiPrdCip,0),
       @rg_Flg_DatAntUltAtuPrdCip = IsNull(rg.Flg_DatAntUltAtuPrdCip,0),
       @rt_Alq_CrePresum = Case 
	                         When IsNull(rg.Flg_UsaCrePresum,0) = 1 then IsNull(rx.Alq_IcmPresumReg,0) 
							 Else 0 
                           End    
  From RTXCT rx
       Inner Join RGTRI rg on rx.Cod_RegTri = rg.Cod_RegTri
Where rx.Cod_RegTri = @PCodRegTri
and rx.Cod_ClaTri = @PClaTri

Select @ct_FlgSujAntIcm = IsNull(Flg_SujAntIcm,0) 
  From CLTRI
Where Cod_ClaTri = @PClaTri

if @PTipNot <> 'D'  -- tipo da nota diferente de devolucao
  begin
    -- compras, outras entradas
	Set @WClaTriExt             = @rt_ClaTriExt
    Set @PCodSt                 = @rt_Cod_ImpNotEnt
    Set @PCodCsosn              = @rt_Cod_CSOSNEnt
    Set @PTipPrcBasDebSbt       = @rt_Tip_PrcBasSbtEnt
    Set @WCtrBasCalDeb          = @rt_Ctrl_BasCalDebEnt
          
    Set @PAlqAgrDeb             = @rt_Alq_AgrDebEnt
    Set @WFatSubTriDeb          = 1 + @rt_Alq_AgrDebEnt/100
    Set @PPerRedBasCalDeb       = @rt_Per_RedBasCalDebEnt
          
    Set @WTipPrcLimMinBasCalIcmSbt = @rt_Tip_PrcLimMinBasCalIcmSbtEnt
    Set @WPerLimMinBasCalIcmSbt    = @rt_Per_LimMinBasCalIcmSbtEnt
    Set @WAlqAgrLimMinBasCalIcmSbt = 0

    Set @WPerResExt             = @rt_Per_ResExtEnt
    Set @WTipCreSbt             = @rt_Tip_CreSbtEnt
    Set @WAlqDebSbt             = @rt_Alq_DebSbtEnt
	Set @WTipPrcLimMinIcmSbt    = @rt_Tip_PrcLimMinIcmSbtEnt
    Set @WPerLimMinIcmSbt       = @rt_Per_LimMinIcmSbtEnt
    Set @WAlqIcmInt             = @rt_Alq_IcmIntLoc
    Set @WAlqIcmIntFcp          = @rt_Per_AcrAlqIntFcpLoc
    Set @PPerRedBasCalIcmDeb    = @rt_Per_RedBasCalIntLoc
    Set @WPerRedBasCalDebOpc    = @rt_Per_RedBasCalDebEntOpc
    Set @WFlgImpSbtFnt          = @rt_Flg_ImpSbtFntEnt

    Set @PTipPrcBasCreSbt       = @rt_Tip_PrcBasCreSbtEnt
    Set @WCtrBasCalCre          = @rt_Ctrl_BasCalCreEnt
    Set @PPerLimBasCalCreSbt    = @rt_Per_LimBasCalCreSbtEnt
    Set @WAlqIcmExt             = @rt_Alq_IcmExtReg
    Set @WAlqIcmExtFcp          = @rt_Per_AcrAlqExtFcpReg
    Set @PPerRedBasCalIcmCre    = @rt_Per_RedBasCalExtReg
	Set @PPerIcmDiferi          = @rt_Per_IcmDiferiExtReg
	Set @WPerIcmDesone          = @rt_Per_IcmDesoneExtReg
    Set @WCodMtvDesone          = @rt_Cod_MtvDesIcmReg
    Set @WFlgDscDesIcm          = @rt_Flg_DscDesIcmReg
    Set @WPerRepIcm             = @rt_C_PerRepIcmReg
  	Set @WPerDspSubCusCreIcm    = @rt_PerDspCusEnt
    Set @WFlgUsaCrePresum       = @rg_Flg_UsaCrePresum
    Set @WAlqCrePresum          = @rt_Alq_CrePresum
	Set @WFlgDatEmiPrdCip       = @rg_Flg_DatEmiPrdCip
	Set @WFlgDatAntUltAtuPrdCip = @rg_Flg_DatAntUltAtuPrdCip
  end
else
  begin
    -- devolucao
	Set @WClaTriExt             = ''
    Set @PCodSt                 = @rt_Cod_ImpNotSai
    Set @PCodCsosn              = @rt_Cod_CSOSNSai
    Set @PTipPrcBasDebSbt       = @rt_Tip_PrcBasDebSbt
    Set @WCtrBasCalDeb          = @rt_Ctrl_BasCalDebSai
    
    Set @PAlqAgrDeb             = @rt_Alq_AgrDebSai
    Set @WFatSubTriDeb          = 1 + @rt_Alq_AgrDebSai/100
    Set @PPerRedBasCalDeb       = @rt_Per_RedBasCalDebSai
    
    Set @WTipPrcLimMinBasCalIcmSbt = @rt_Tip_PrcLimMinBasCalIcmSbtSai
    Set @WPerLimMinBasCalIcmSbt    = 0
    Set @WAlqAgrLimMinBasCalIcmSbt = @rt_Alq_AgrLimMinBasCalIcmSbtSai     

    Set @WPerResExt             = @rt_Per_ResExtSai
    Set @WTipCreSbt             = @rt_Tip_CreSbtSai
    Set @WAlqDebSbt             = @rt_Alq_DebSbtSai
	Set @WTipPrcLimMinIcmSbt    = ''
    Set @WPerLimMinIcmSbt       = 0
    Set @WAlqIcmInt             = @rt_Alq_IcmIntReg
    Set @WAlqIcmIntFcp          = @rt_Per_AcrAlqIntFcpReg
    Set @PPerRedBasCalIcmDeb    = @rt_Per_RedBasCalIntReg
    Set @WPerRedBasCalDebOpc    = 0
    Set @WFlgImpSbtFnt          = 1

    Set @PTipPrcBasCreSbt       = @rt_Tip_PrcBasCreSbtSai
    Set @WCtrBasCalCre          = @rt_Ctrl_BasCalCreSai
    Set @PPerLimBasCalCreSbt    = 0
    Set @WAlqIcmExt             = @rt_Alq_IcmExtLoc
    Set @WAlqIcmExtFcp          = @rt_Per_AcrAlqExtFcpLoc
    Set @PPerRedBasCalIcmCre    = @rt_Per_RedBasCalExtLoc
    Set @PPerIcmDiferi          = @rt_Per_IcmDiferiExtLoc
    Set @WPerIcmDesone          = @rt_Per_IcmDesoneExtLoc
    Set @WCodMtvDesone          = @rt_Cod_MtvDesIcmLoc
    Set @WFlgDscDesIcm          = @rt_Flg_DscDesIcmLoc
    Set @WPerRepIcm             = @rt_C_PerRepIcmLoc
    Set @WPerDspSubCusCreIcm    = 0
    Set @WFlgUsaCrePresum       = 0
    Set @WAlqCrePresum          = 0
	Set @WFlgDatEmiPrdCip       = 0
	Set @WFlgDatAntUltAtuPrdCip = 0

end

-- coloca campo de PRODU na memoria
Select @PTipLisPis = pr.Tip_LisPis,
       @PCodNcm = Substring(Ltrim(Rtrim(pr.Cod_ClaFis)),1,8),
       @PAlqIpi = IsNull(pr.Per_Ipi,0),
       @pr_PrcVen = Isnull(p.Prc_Venda,0),
       @pr_PrcRefFpb = Isnull(pr.Prc_RefFpb,0),
       @pr_PrcFab = Case
                      When (Round(@WAlqIcmInt,2) = 12.00) and (IsNull(pr.Prc_Fabric12,0)  > 0) Then IsNull(pr.Prc_Fabric12,0)
                      When (Round(@WAlqIcmInt,2) = 17.00) and (IsNull(pr.Prc_Fabric17,0)  > 0) Then IsNull(pr.Prc_Fabric17,0)
                      When (Round(@WAlqIcmInt,2) = 17.50) and (IsNull(pr.Prc_Fabric175,0) > 0) Then IsNull(pr.Prc_Fabric175,0)
                      When (Round(@WAlqIcmInt,2) = 18.00) and (IsNull(pr.Prc_Fabric18,0)  > 0) Then IsNull(pr.Prc_Fabric18,0)
                      When (Round(@WAlqIcmInt,2) = 19.00) and (IsNull(pr.Prc_Fabric19,0)  > 0) Then IsNull(pr.Prc_Fabric19,0)
                      When (Round(@WAlqIcmInt,2) = 20.00) and (IsNull(pr.Prc_Fabric20,0)  > 0) Then IsNull(pr.Prc_Fabric20,0)
                      When (Round(@WAlqIcmInt,2) = 21.00) and (IsNull(pr.Prc_Fabric21,0)  > 0) Then IsNull(pr.Prc_Fabric21,0)
                      When (Round(@WAlqIcmInt,2) = 22.00) and (IsNull(pr.Prc_Fabric22,0)  > 0) Then IsNull(pr.Prc_Fabric22,0)
                      Else Isnull(p.Prc_Fabric,0)
                    End,
       @pr_PrcMax = Case
                      When (Round(@WAlqIcmInt,2) = 12.00) and (IsNull(pr.Prc_MaxCon12,0)  > 0) Then IsNull(pr.Prc_MaxCon12,0)
                      When (Round(@WAlqIcmInt,2) = 17.00) and (IsNull(pr.Prc_MaxCon17,0)  > 0) Then IsNull(pr.Prc_MaxCon17,0)
                      When (Round(@WAlqIcmInt,2) = 17.50) and (IsNull(pr.Prc_MaxCon175,0) > 0) Then IsNull(pr.Prc_MaxCon175,0)
                      When (Round(@WAlqIcmInt,2) = 18.00) and (IsNull(pr.Prc_MaxCon18,0)  > 0) Then IsNull(pr.Prc_MaxCon18,0)
                      When (Round(@WAlqIcmInt,2) = 19.00) and (IsNull(pr.Prc_MaxCon19,0)  > 0) Then IsNull(pr.Prc_MaxCon19,0)
                      When (Round(@WAlqIcmInt,2) = 20.00) and (IsNull(pr.Prc_MaxCon20,0)  > 0) Then IsNull(pr.Prc_MaxCon20,0)
                      When (Round(@WAlqIcmInt,2) = 21.00) and (IsNull(pr.Prc_MaxCon21,0)  > 0) Then IsNull(pr.Prc_MaxCon21,0)
                      When (Round(@WAlqIcmInt,2) = 22.00) and (IsNull(pr.Prc_MaxCon22,0)  > 0) Then IsNull(pr.Prc_MaxCon22,0)
                      Else Isnull(p.Prc_MaxCon,0)
                    End,
	   @pr_VlrBasCalSubTriEntMed = IsNull(p.Vlr_BasCalSubTriEntMed,0)
  From PRXES p Inner Join PRODU pr on p.Cod_Produt = pr.Codigo
Where p.Cod_Estabe = @PCodEstabe 
And p.Cod_Produt = @PCodPrd

Set @PPrcVen = ISNULL(@PArqPrcVen,0)

if @PTipNot = 'D'  -- tipo da nota devolucao
  begin
    Set @PPrcFab = IsNull(@PArqPrcFab,0)
    Set @PPrcMax = IsNull(@PArqPrcMax,0)
	Set @PPrcRefFpb = IsNull(@PArqPrcRefFpb,0)
  end
else
  begin
    Set @PPrcFab = 0
    Set @PPrcMax = 0
	Set @PPrcRefFpb = 0
  end

-- data anterior á ult. atualização de preço
if Exists(Select 1
          From HSPRC
          Where Cod_Estabe = @PCodEstabe
          And Cod_Produto = @PCodPrd
          And Dat_Alteracao <= @PDatMov)
  Select top 1 @WDatAntUltAlt = Dat_Alteracao - 1
  From HSPRC
  Where Cod_Estabe = @PCodEstabe
  And Cod_Produto = @PCodPrd
  And Dat_Alteracao <= @PDatMov
  Order by Dat_Alteracao desc
else
  Set @WDatAntUltAlt = @PDatMov

-- data referencia para preços "monitorados"
Set @PDatRefPrdCip = Case 
                       When @WFlgDatEmiPrdCip = 1 then @PDatEmi
                       When @WFlgDatAntUltAtuPrdCip = 1 then @WDatAntUltAlt
                       Else @PDatMov
                     End

if @PPrcVen = 0
  begin
    Set @WPrcAux = IsNull((Select TOP 1 Vlr_PrcVen
                             From HSPRC
                           Where Cod_Estabe = @PCodEstabe 
                           and Cod_Produto = @PCodPrd
                           And Dat_Alteracao <= @PDatMov
                           Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
    if @WPrcAux > 0
      Set @PPrcVen = @WPrcAux
    else           
      Set @PPrcVen = @pr_PrcVen
  end

if @PPrcRefFpb = 0
  begin
    Set @WPrcAux = IsNull((Select TOP 1 Vlr_RefFpb
                           From HSPRC
                           Where Cod_Estabe = @PCodEstabe 
                           and Cod_Produto = @PCodPrd
                           and Dat_Alteracao <= @PDatRefPrdCip 
                           Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
    if @WPrcAux > 0
      Set @PPrcRefFpb = @WPrcAux
    else           
      Set @PPrcRefFpb = @pr_PrcRefFpb
  end

if @PPrcFab = 0
  begin
    Set @WPrcAux = Case
                     When Round(@WAlqIcmInt,2) = 12.00 Then IsNull((Select TOP 1 Vlr_PrcFab12 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip 
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 17.00 Then IsNull((Select TOP 1 Vlr_PrcFab17 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip 
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 17.50 Then IsNull((Select TOP 1 Vlr_PrcFab175 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 18.00 Then IsNull((Select TOP 1 Vlr_PrcFab18 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 19.00 Then IsNull((Select TOP 1 Vlr_PrcFab19 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 20.00 Then IsNull((Select TOP 1 Vlr_PrcFab20 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 21.00 Then IsNull((Select TOP 1 Vlr_PrcFab21 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 22.00 Then IsNull((Select TOP 1 Vlr_PrcFab22 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     Else IsNull((Select TOP 1 Vlr_PrcFab From HSPRC
                                  Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                  And Dat_Alteracao <= @PDatRefPrdCip
                                  Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                   End                       
                           
    if @WPrcAux > 0
      Set @PPrcFab = @WPrcAux
    else           
      Set @PPrcFab = @pr_PrcFab
  end
      
if @PPrcMax = 0
  begin
    Set @WPrcAux = Case
                     When Round(@WAlqIcmInt,2) = 12.00 Then IsNull((Select TOP 1 Vlr_PrcMaxCon12 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 17.00 Then IsNull((Select TOP 1 Vlr_PrcMaxCon17 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 17.50 Then IsNull((Select TOP 1 Vlr_PrcMaxCon175 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 18.00 Then IsNull((Select TOP 1 Vlr_PrcMaxCon18 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 19.00 Then IsNull((Select TOP 1 Vlr_PrcMaxCon19 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 20.00 Then IsNull((Select TOP 1 Vlr_PrcMaxCon20 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 21.00 Then IsNull((Select TOP 1 Vlr_PrcMaxCon21 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 22.00 Then IsNull((Select TOP 1 Vlr_PrcMaxCon22 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     Else IsNull((Select TOP 1 Vlr_PrcMaxCon
                                  From HSPRC
                                  Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                  And Dat_Alteracao <= @PDatRefPrdCip
                                  Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                   End
                   
    if @WPrcAux > 0
      Set @PPrcMax = @WPrcAux
    else           
      Set @PPrcMax = @pr_PrcMax
  end

-- PMPF - Preco Medio Ponderado ao Consumidor Final
if @PPrcPonFin = 0
  Set @PPrcPonFin = (Select dbo.FN_PrcMedPonFin (@em_DesEstado,@PCodPrd,@PDatEmi))

Set @PVlrBasCalSubTriEntMed = @pr_VlrBasCalSubTriEntMed  -- 08/01/2019

-- verifica se utiliza classificação tributária extra (uma unica vez)
--if (@PFlgCalIcmSbt = 1) and
if ( ((@PTipPrcBasDebSbt <> 'X') and (@PTipPrcBasDebSbt <> 'O')) or (@ct_FlgSujAntIcm = 1) ) and (@PFlgSbtEmbPrc = 0) and  -- produto suj.subst.trib. ou antecip.
   (((@PTipPrcBasDebSbt = 'D') and (@PPrcPonFin = 0)) or
    ((@PTipPrcBasDebSbt = 'M') and (@PPrcMax = 0))) and
   (@WClaTriExt <> '') and
   (@PClaTri <> @WClaTriExt) and
   (@WQtdLoop = 1)
  begin
    Set @WQtdLoop = @WQtdLoop + 1
    Set @PClaTri = @WClaTriExt
    GOTO LOOP_INICIO
  end

-- valor bruto/total do item
Set @it_Vlr_BruIte = Round((@PPrcUniIte * (@PQtdPed+@PQtdBon)),2)
Set @it_Vlr_TotIte = Round(@PQtdPed * @PPrcUniIte * (1-@PPerDscIte/100),2)

-- calcula despesa tributaria 
  if @WPerResExt > 0
    begin
      Set @WVlrBasResExt = @it_Vlr_TotIte
      Set @PVlrDsp = Round(@WVlrBasResExt * @WPerResExt/100,2)
    end

-- valor liquido do item
Set @WVlrIte = @it_Vlr_TotIte - @PVlrDscRat


-----------  DESONERAÇÃO ICMS  -----------------------------------------------------------------------------
-- desoneração somente sobre valor item (sem frete / despesas)
-- ou existe redução, ou desoneração ou suframa
Set @WFlgIcmIsento = 0
Set @WPerIcmDesRedBasCal = 0 -- desoneração de icms por redução de base de cálculo

if @PFlgCalIcmPro = 1
  begin
    if @WAlqIcmExt = @WPerIcmDesone
      Set @WFlgIcmIsento = 1
    
    -- desoneração por redução de base de cálculo
    if @PPerRedBasCalIcmCre > 0
      Set @WPerIcmDesRedBasCal = Round(@WAlqIcmExt*@PPerRedBasCalIcmCre/100,4)
-- desoneração não é obrigatória:
--    if @WPerIcmDesone = 0
--      Set @WPerIcmDesone = @WPerIcmDesRedBasCal
    
    if @WPerIcmDesone > 0
      begin
        Set @PMtvIcmDesone = @WCodMtvDesone
        Set @PVlrIcmDesone = Round(Round(@WVlrIte,2)*@WPerIcmDesone/100,@WQtdDecRndTrb)
    
    	-- se for desoneracao por redução de base de calculo não abate valor na NF -- 
        if ((@WFlgDscDesIcm = 1) or @PFlgDscIcmDesone = 1) and 
    	   (@PPerRedBasCalIcmCre = 0)  
          Set @PVlrDst = @PVlrIcmDesone
      end
  end  -- if @PFlgCalIcmPro = 1
----------- FIM DESONERAÇÃO ICMS  -----------------------------------------------------------------------------

Set @WLiq = Round(@WVlrIte,2) - @PVlrDst

-- valor liquido do item sem reducao da base de calculo p/ credito Icms
Set @WLiq = Round(@WLiq + @PVlrDspTot + @PVlrDsp,2)

-- registra icms proprio, icms tributavel da operacao se DEB/CRE ou SUB.TRIB.
Set @WCre = 0
Set @PAlqIcm = @WAlqIcmExt

Set @WCreFcp = 0
Set @PAlqIcmFcp = @WAlqIcmExtFcp  

/*
if @PAlqIcm > 0
  Set @PBasTri = @WLiq   -- valor base p/ tributos
else  
  Set @PBasTri = Round(@it_Vlr_TotIte - @PVlrDscRat,2)  -- valor base sem despesas
*/

Set @PBasTri = @WLiq

Set @PBasIcmPro = Round(@PBasTri*(1-@PPerRedBasCalIcmCre/100),2)
Set @PIcmPro = Round(@PBasIcmPro * @PAlqIcm/100, @WQtdDecRndTrb)
if @PIcmPro = 0
  Set @PBasIcmPro = 0

Set @WIcmProFcp = Round(@PBasIcmPro * @PAlqIcmFcp/100, @WQtdDecRndTrb)
Set @PVlrIcmDiferi = Round(@PIcmPro * @PPerIcmDiferi/100, @WQtdDecRndTrb)

-- calcula valor de custo substituto do credito de icms
if (@WPerDspSubCusCreIcm > 0) and (@PAlqIcm > 0)
  Set @PVlrDspSubCusCreIcm = @PBasTri * @WPerDspSubCusCreIcm/100

-- credito com reducao da base de calculo p/ credito Icms
--if Charindex(@PCodSt,';00;10;20;30;60;70;90;51;') > 0 
if (@PFlgCalIcmPro = 1) or (@PFlgCalIcmSbt = 1)
  begin
    Set @WCre = @PIcmPro
    Set @WCreFcp = @WIcmProFcp
    if @WCre > 0
      Set @PCodModBasCalIcm = '3'
  end

-- calcula icms tributavel (debito/credito)  aqui novo
if (@PFlgCalIcmPro = 1) and (@PTipPrcBasDebSbt = 'X')   -- nao eh subst.tributaria
  begin
    Set @PBasIcm = @PBasIcmPro
    if @WPerIcmDesRedBasCal > 0
      Set @PVlrIcm = @PIcmPro - @PVlrIcmDiferi  -- @PIcmPro já está com redução de B.C.
    else
      Set @PVlrIcm = @PIcmPro - @PVlrIcmDesone - @PVlrIcmDiferi
    Set @PVlrIcmFcp = @WIcmProFcp
    if @WFlgIcmIsento = 1
      begin
        Set @PBasIcm = 0
        Set @PVlrIcm = 0
        Set @PVlrIcmFcp = 0
      end

    Set @PFlgUsaCrePresum = @WFlgUsaCrePresum
    Set @PAlqCrePresum = @WAlqCrePresum
  end

-- Calcula Base de Cálculo do IPI (valor bruto)
Set @PCstIpi = ''
if @PVlrIpi > 0
  begin
    Set @PCstIpi = '49'   -- outras entradas
    Set @PBasIpi = @it_Vlr_TotIte
  end

-- ver se eh ST sem retencao
if @PTipPrcBasDebSbt = 'O' 
  begin
    Set @PVlrPrdSub = 0
    Set @PAlqIcmDeb = 0
    Set @PAlqAgrDeb = 0
    Set @PPerRedBasCalDeb = 0
    Set @PBasSubFnt = 0
    Set @PVlrSubFnt = 0
    Set @PBasSbtRes = 0
    Set @PVlrSbtRes = 0
    Set @PBasSubRec = 0
    Set @PVlrSubRec = 0
    Set @PVlrPrdAnt = 0
    Set @PBasAnt    = 0
    Set @PVlrAnt    = 0
--    Set @PBasIcmPro = 0
--    Set @PIcmPro    = 0
--    Set @WIcmProFcp = 0
    Set @PBasIcm    = 0
    Set @PVlrIcm    = 0
    Set @PVlrIcmFcp = 0
    Set @PVlrIse    = 0
    Set @PVlrOut    = @WLiq
    Set @PCodModBasCalIcm = ''
    Set @PCodModBasCalIcmSbt = ''
    Set @PFlgUsaCrePresum = @WFlgUsaCrePresum
    Set @PAlqCrePresum = @WAlqCrePresum
  end

-- Calcula Substituicao Tributaria ou Antecipacao de Icms
Set @WVlrPrdSbt = 0
Set @WVlrImpSbt = 0
Set @WVlrPrdSbtLim = 0   -- limitador p/ pr. transacao ou p.fábrica

if (@PFlgCalIcmSbt = 1) and
   ( ((@PTipPrcBasDebSbt <> 'X') and (@PTipPrcBasDebSbt <> 'O')) or
     (@ct_FlgSujAntIcm = 1) )  and  
   (@PFlgSbtEmbPrc = 0)  -- produto suj.subst.trib. ou antecip.
  begin
    -- credito presumido p/ uso no calculo de custo
    Set @PFlgUsaCrePresum = 0
    Set @PAlqCrePresum = 0

    if @WCtrBasCalDeb = 'B'    -- pelo vlr. bruto
      begin
        if @PTipPrcBasDebSbt = 'D'           -- utiliza PMPF do cadastro
          Set @WVlrPrdSbt = @PPrcPonFin * (@PQtdPed + @PQtdBon)
        else
        if @PTipPrcBasDebSbt = 'M'      -- utiliza P.M.C. do cadastro
          Set @WVlrPrdSbt = @PPrcMax * (@PQtdPed+@PQtdBon)
        else
        if @PTipPrcBasDebSbt = 'F'       -- utiliza preco fabrica do cadastro
          Set @WVlrPrdSbt = (@PPrcFab * (@PQtdPed+@PQtdBon)) + @PVlrIpi
        else
        if @PTipPrcBasDebSbt = 'P'      -- utiliza Preço Referencia Farmacia Popular do cadastro
          Set @WVlrPrdSbt = @PPrcRefFpb * (@PQtdPed+@PQtdBon)
        else
        if @PTipPrcBasDebSbt = 'V'       -- utiliza preco venda do cadastro
          Set @WVlrPrdSbt = (@PPrcVen * (@PQtdPed+@PQtdBon)) + @PVlrIpi
        else
          Set @WVlrPrdSbt = @it_Vlr_BruIte + @PVlrIpi + @PVlrDspSbt  + @PVlrDspTot + @PVlrDsp   -- transacao
      end
    else
      begin
        Set @WVlrPrdSbt = @PBasTri + @PVlrIpi + @PVlrDspSbt
      end

    Set @WVlrPrdSbt = @WVlrPrdSbt * (1-@PPerRedBasCalDeb/100)
    Set @WVlrBasSbt = @WVlrPrdSbt * @WFatSubTriDeb

    -- calcula valor minimo p/ B.Cálculo de ST
    Set @WVlrMinBasCalSbt = 0

	-- 08/01/2019 : compatibilizar com calculo da saida
    -- média da B.C. de Entrada + Agreg.
    if @WTipPrcLimMinBasCalIcmSbt = 'E'
      Set @WVlrMinBasCalSbt = Round(@PVlrBasCalSubTriEntMed * (1 + @WAlqAgrLimMinBasCalIcmSbt/100),2)

    if @WTipPrcLimMinBasCalIcmSbt = 'F' 
      Set @WVlrMinBasCalSbt = Round((@PPrcFab * (@PQtdPed+@PQtdBon)) * @WPerLimMinBasCalIcmSbt/100,4)

    if @WVlrBasSbt < @WVlrMinBasCalSbt
      Set @WVlrBasSbt = @WVlrMinBasCalSbt    

    Set @WVlrBasSbt = Round(@WVlrBasSbt,2)

    if @WTipCreSbt = 'F'    -- Valor da substituicao fixo
      begin
        Set @PFlgUsaCreIcmSbt = 0
        Set @WVlrImpSbt = @WVlrBasSbt * @WAlqDebSbt / 100
        Set @PAlqIcmDeb = @WAlqDebSbt
        Set @PVlrPrdSub = @WVlrPrdSbt

		Set @PAlqIcmSbtFcp = @WAlqIcmIntFcp
        Set @PVlrSubFcp = @WVlrBasSbt * @PAlqIcmSbtFcp / 100

        if @WFlgImpSbtFnt = 1 
          begin
            if @PAlqAgrDeb > 0
              Set @PCodModBasCalIcmSbt = '4'  -- Margem Valor Agregado (%)
            else
              Set @PCodModBasCalIcmSbt = '0'  -- preco tabela ou maximo sugerido
          end
        else
          Set @PCodModBasCalIcmSbt = ''
      end
    else
      begin
        -- substituicao com agregacao
        -- debito com red. base de calculo icms
        Set @PFlgUsaCreIcmSbt = 1
        Set @PAlqIcmDeb = @WAlqIcmInt
        Set @PVlrDebIcm = @WVlrBasSbt * @PAlqIcmDeb / 100

		Set @PAlqIcmSbtFcp = @WAlqIcmIntFcp
        Set @WDebSbtFcp = @WVlrBasSbt * @PAlqIcmSbtFcp / 100   

        Set @WVlrBasLimCreSbt = @WVlrBasSbt

        if @WCtrBasCalCre = 'B'       -- credito pelo vlr.bruto
          begin
            if @PTipPrcBasCreSbt = 'F'    -- utiliza preco fabrica do cadastro
              Set @WCreSbt = @PPrcFab * (@PQtdPed+@PQtdBon)
            else
            if @PTipPrcBasCreSbt = 'V'    -- utiliza preco venda do cadastro
              Set @WCreSbt = @PPrcVen * (@PQtdPed+@PQtdBon)
            else
              Set @WCreSbt = @it_Vlr_BruIte  -- transacao
            -- credito com red.base de calculo
            Set @WCreSbt = @WCreSbt * (1-@PPerRedBasCalIcmCre/100) * @WAlqIcmExt / 100
            Set @WCreSbtFcp = @WCreSbt * (1-@PPerRedBasCalIcmCre/100) * @WAlqIcmExtFcp / 100
          end
        else
          begin
            Set @WCreSbt = @WCre
            Set @WCreSbtFcp = @WCreFcp
          end

        -- valor limite de credito na substituicao tributaria
        Set @PVlrLimCreIcm = 0
        if @PPerLimBasCalCreSbt > 0
          Set @PVlrLimCreIcm = @WVlrBasLimCreSbt*@PPerLimBasCalCreSbt*@WAlqIcmExt/10000

        if (@PVlrLimCreIcm > 0) and (@WCreSbt > @PVlrLimCreIcm) 
          Set @WCreSbt = @PVlrLimCreIcm

        -- calcula icm subst.
        Set @WVlrImpSbt = @PVlrDebIcm - @WCreSbt
		Set @PVlrSubFcp = @WDebSbtFcp - @WCreSbtFcp

		if @PAlqAgrDeb > 0
          Set @PCodModBasCalIcmSbt = '4'  -- Margem Valor Agregado (%)
        else
          Set @PCodModBasCalIcmSbt = '0'  
      end

    -- verifica limitador de ST
    Set @WVlrMinSbt = 0
    if @WPerLimMinIcmSbt > 0 
      begin
        if @WTipPrcLimMinIcmSbt = 'L'
          Set @WVlrPrdSbtLim = @PBasTri + @PVlrIpi + @PVlrDspSbt
        else
        if @WTipPrcLimMinIcmSbt = 'F'
          Set @WVlrPrdSbtLim = (@PPrcFab * (@PQtdPed+@PQtdBon)) + @PVlrIpi
        Set @WVlrMinSbt = @WVlrPrdSbtLim*@WPerLimMinIcmSbt/100
      end

    if (@WVlrImpSbt < @WVlrMinSbt) and (Round(@WVlrMinSbt,2) > 0) 
      begin
        Set @WVlrPrdSbt = @WVlrPrdSbtLim
        Set @WVlrBasSbt = @WVlrPrdSbtLim
        Set @WVlrImpSbt = @WVlrMinSbt
        Set @PAlqIcmDeb = @WPerLimMinIcmSbt

		Set @PAlqIcmSbtFcp = @WAlqIcmIntFcp
        Set @PVlrSubFcp = @WVlrBasSbt * @PAlqIcmSbtFcp / 100

        if @WFlgImpSbtFnt = 1
          begin
            if @PAlqAgrDeb > 0
              Set @PCodModBasCalIcmSbt = '4'  -- Margem Valor Agregado (%)
            else
              Set @PCodModBasCalIcmSbt = '0'  -- preco tabela ou maximo sugerido
          end
       else
         Set @PCodModBasCalIcmSbt = ''
      end

    -- verifica S.T. opcional
    Set @WVlrImpSbtOpc = 0
    if @WPerRedBasCalDebOpc > 0
      begin
        Set @WVlrDebIcmOpc = 0
        Set @WVlrPrdSbtOpc = @PPrcMax * (@PQtdPed+@PQtdBon)
        Set @WVlrPrdSbtOpc = @WVlrPrdSbtOpc * (1-@WPerRedBasCalDebOpc/100)

        -- calcula S.T. opcional
        Set @WVlrDebIcmOpc = @WVlrPrdSbtOpc * @WAlqIcmInt/100
        Set @WVlrImpSbtOpc = @WVlrDebIcmOpc - @WCre

        if (@WVlrImpSbtOpc < @WVlrImpSbt) and (Round(@WVlrImpSbtOpc,2) > 0)
          begin
            Set @WVlrPrdSbt = @WVlrPrdSbtOpc
            Set @WVlrBasSbt = @WVlrPrdSbtOpc
            Set @WVlrImpSbt = @WVlrImpSbtOpc

            Set @PAlqIcmSbtFcp = @WAlqIcmIntFcp
            Set @PVlrSubFcp = @WVlrBasSbt * @PAlqIcmSbtFcp / 100   

            Set @PTipPrcBasDebSbt = 'M'   -- P.M.C.
            Set @PFlgUsaCreIcmSbt = 1
            Set @PAlqAgrDeb = 0
            Set @PPerRedBasCalDeb = @WPerRedBasCalDebOpc
            Set @PVlrDebIcm = @WVlrDebIcmOpc
            Set @PAlqIcmDeb = @WAlqIcmInt

            if @WFlgImpSbtFnt = 1
              begin
                if @PAlqAgrDeb > 0
                  Set @PCodModBasCalIcmSbt = '4'  -- Margem Valor Agregado (%)
                else
                  Set @PCodModBasCalIcmSbt = '0'  -- preco tabela ou maximo sugerido
              end
            else
              Set @PCodModBasCalIcmSbt = ''
          end
      end
    
    -- verifica valor ST
    if @WVlrImpSbt <= 0
      begin
        Set @WVlrImpSbt = 0
        Set @PVlrSubFcp = 0
        if @WVlrBasSbt = 0
          begin
            Set @PCodModBasCalIcmSbt = ''
            Set @WVlrPrdSbt = 0
            Set @PAlqIcmDeb = 0
            Set @PAlqAgrDeb = 0
            Set @PPerRedBasCalIcmDeb = 0
            Set @PAlqIcmSbtFcp = 0
          end
      end

    if @ct_FlgSujAntIcm = 0
      begin
        -- subst. tributaria
        Set @PVlrPrdSub = @WVlrPrdSbt
        if @WFlgImpSbtFnt = 1
          begin
            Set @PBasSubFnt = @WVlrBasSbt
            Set @PVlrSubFnt = @WVlrImpSbt
          end
        else
          begin
            Set @PBasSubRec = @WVlrBasSbt
            Set @PVlrSubRec = @WVlrImpSbt

            Set @PAlqIcmSbtFcpRec = @PAlqIcmSbtFcp
            Set @PVlrSubFcpRec = @PVlrSubFcp
            Set @PAlqIcmSbtFcp = 0
            Set @PVlrSubFcp = 0
          end
      end
    else
      begin
        -- antecip. tributaria
        Set @PVlrPrdAnt = @WVlrPrdSbt
        Set @PBasAnt    = @WVlrBasSbt
        Set @PVlrAnt    = @WVlrImpSbt

        Set @PAlqIcmSbtFcpAnt = @PAlqIcmSbtFcp
        Set @PVlrSubFcpAnt = @PVlrSubFcp
        Set @PAlqIcmSbtFcp = 0
        Set @PVlrSubFcp = 0

        -- Calcula Base Calc.ICMS deb/cre
        if @WAlqIcmExt > 0
          begin
            if @PFlgCalIcmPro = 1
               begin
                 Set @PBasIcm = @PBasIcmPro
                 if @WPerIcmDesRedBasCal > 0
                   Set @PVlrIcm = @PIcmPro - @PVlrIcmDiferi  -- @PIcmPro já está com redução de B.C.
                 else
                   Set @PVlrIcm = @PIcmPro - @PVlrIcmDesone - @PVlrIcmDiferi
                 Set @PVlrIcmFcp = @WIcmProFcp
               end
            if @WFlgIcmIsento = 1
              begin
                Set @PBasIcm = 0
                Set @PVlrIcm = 0
                Set @PVlrIcmFcp = 0
              end
          end
      end
  end  -- if (@PFlgCalIcmSbt = 1) and ... produto suj.subst.trib. ou antecip.

/*
else
  -- Calcula Base Calc.ICMS deb/cre
  begin
    Set @PFlgUsaCrePresum = @WFlgUsaCrePresum
    Set @PAlqCrePresum = @WAlqCrePresum
    if @WAlqIcmExt > 0 
      begin
        Set @PBasIcm = @PBasIcmPro
        if @WPerIcmDesRedBasCal > 0
          Set @PVlrIcm = @PIcmPro - @PVlrIcmDiferi  -- @PIcmPro já está com redução de B.C.
        else
          Set @PVlrIcm = @PIcmPro - @PVlrIcmDesone - @PVlrIcmDiferi
        Set @PVlrIcmFcp = @WIcmProFcp
        if @WFlgIcmIsento = 1
          begin
            Set @PBasIcm = 0
            Set @PVlrIcm = 0
            Set @PVlrIcmFcp = 0
          end
      end
    else
      -- Calcula Valor Isento (AQUI não funciona mais... alíquota nunca pode ser zero
      Set @PVlrIse = Round(@PBasTri,2)
  end
*/


-- nao houve tributacao qualquer
if (@PFlgCalIcmPro = 0) and (@PFlgCalIcmSbt = 0)
  begin
    Set @PVlrOut = @PBasIcmPro
    if Charindex(@PCodSt,';51;') = 0  -- if Charindex(@PCodSt,';51;90;') = 0
--      Set @PCodSt = '41'   -- para não contribuinte
      Set @PCodSt = '90'     -- para contribuinte 
  end

-- CST sujeitas a ST 10;30;70
if (@PFlgCalIcmSbt = 1) and (@WVlrImpSbt = 0) and (Charindex(@PCodSt,';10;30;60;70;') > 0) 
  if Charindex(@PCodSt,';10;70;') > 0 
    begin
      Set @PBasIcm = @PBasIcmPro
      if @WPerIcmDesRedBasCal > 0
        Set @PVlrIcm = @PIcmPro - @PVlrIcmDiferi  -- @PIcmPro já está com redução de B.C.
      else
        Set @PVlrIcm = @PIcmPro - @PVlrIcmDesone - @PVlrIcmDiferi
      Set @PVlrIcmFcp = @WIcmProFcp
      if @WFlgIcmIsento = 1
        begin
          Set @PBasIcm = 0
          Set @PVlrIcm = 0
          Set @PVlrIcmFcp = 0
        end
      if @WVlrBasSbt = 0
        if @PCodSt = '70'
          Set @PCodSt = '20' 
        else
          Set @PCodSt = '00' 
    end
  else
    begin
      Set @PVlrOut = @PBasIcmPro
      if @WVlrBasSbt > 0 
        if @PCodSt = '60'
          Set @WVlrBasSbt = 0
      if @WVlrBasSbt = 0
        if @PCodSt = '30'
          if @WFlgIcmIsento = 1
            Set @PCodSt = '40'
          else			 
            Set @PCodSt = '41' 
    end

-- exige tributacao icm
if (@PFlgCalIcmPro = 1) and
   (Charindex(@PCodSt,';00;10;20;51;70;90;') > 0)
  begin
    Set @PBasIcm = @PBasIcmPro
    if @WPerIcmDesRedBasCal > 0
      Set @PVlrIcm = @PIcmPro - @PVlrIcmDiferi  -- @PIcmPro já está com redução de B.C.
    else
      Set @PVlrIcm = @PIcmPro - @PVlrIcmDesone - @PVlrIcmDiferi
    Set @PVlrIcmFcp = @WIcmProFcp
    if @WFlgIcmIsento = 1
      begin
        Set @PBasIcm = 0
        Set @PVlrIcm = 0
        Set @PVlrIcmFcp = 0
      end
  end

-- ajusta cst de isento
if (@PVlrIcm = 0) and
   (Charindex(@PCodSt,';30;40;41;50;60;') = 0)   
  begin
    if Charindex(@PCodSt,';00;20;51;') > 0
      if @WFlgIcmIsento = 1
        Set @PCodSt = '40'
      else			 
        Set @PCodSt = '41' 

    if Charindex(@PCodSt,';10;;70;') > 0
      Set @PCodSt = '30'
    else
    if ((@PVlrSubFnt+@PVlrSbtRes) > 0)
      Set @PCodSt = '30'
    else
      if @WFlgIcmIsento = 1
        Set @PCodSt = '40'
      else			 
        Set @PCodSt = '41' 
  end

-- nao exige tributacao icm
if Charindex(@PCodSt,';30;40;41;50;60;') > 0 
  begin
    Set @PBasIcm = 0
    Set @PVlrIcm = 0
    Set @PVlrIcmFcp = 0
  end

if (@PCodSt = '90') and (@PTipPrcBasDebSbt = 'O')
  begin
    Set @PBasIcm = 0
    Set @PVlrIcm = 0
    Set @PVlrIcmFcp = 0
  end

if (@PVlrIse = 0) and (@PVlrOut = 0) and 
   (@PVlrSubFnt = 0) and (@PVlrSbtRes = 0) and (@PVlrSubRec = 0) and (@PVlrAnt = 0) and
   (@PVlrIcm = 0) 
  if (@PFlgCalIcmPro = 1) or (@PFlgCalIcmSbt = 1)
    Set @PVlrIse = @PBasTri
  else
    Set @PVlrOut = @PBasTri

-- AQUI não funciona mais... alíquota interna nunca pode ser zero
if @PVlrIse > 0 
  if @PAlqIcm = 0
    begin
      Set @PBasIcmPro = 0
      Set @PIcmPro = 0
      Set @WIcmProFcp = 0
      Set @PBasIcm = 0
      Set @PVlrIcm = 0
      Set @PVlrIcmFcp = 0
      Set @PVlrOut = 0
      if @WFlgIcmIsento = 1
        Set @PCodSt = '40'
      else			 
        Set @PCodSt = '41' 
    end

-- ICM presumido
if (@PVlrIcm > 0) and (@PFlgUsaCrePresum = 0)
  begin
    Set @PFlgUsaCrePresum = @WFlgUsaCrePresum
    Set @PAlqCrePresum = @WAlqCrePresum
  end

-- ajusta ressarcimento de ST
if @PCodSt = '60' 
  begin
    Set @PBasSbtRes = @PBasSubFnt
    Set @PVlrSbtRes = @PVlrSubFnt
    Set @PBasSubFnt = 0
    Set @PVlrSubFnt = 0

    Set @PAlqIcmSbtFcpRet = @PAlqIcmSbtFcp 
    Set @PVlrSubFcpRet = @PVlrSubFcp
    Set @PAlqIcmSbtFcp = 0
    Set @PVlrSubFcp = 0
  end

-- calcula outros valores de icms
Set @PVlrOut = Round((@WLiq - @PVlrIse - @PBasIcm),2)
if @PVlrOut < 0
  Set @PVlrOut = 0
if @PVlrOut > @WLiq
  Set @PVlrOut = Round(@WLiq,2)

-- ajusta Cod.Modalidade base de calculo icm sbt
if @PVlrSubFnt > 0
  if @PAlqAgrDeb > 0
    Set @PCodModBasCalIcmSbt = '4'  -- Margem Valor Agregado (%)
  else
     Set @PCodModBasCalIcmSbt = '0'  -- preco tabela ou maximo sugerido
else
  Set @PCodModBasCalIcmSbt = ''

if Charindex(@PCodSt,';30;40;41;50;60;') > 0
  Set @PCodModBasCalIcm = ''
if Charindex(@PCodSt,';00;20;40;41;50;51;60;') > 0
  Set @PCodModBasCalIcmSbt = ''

-- aqui TESTE em 24/03/2022: zerar ICMS proprio...
if Round(@PVlrIse,2) > 0
  begin
    Set @PAlqIcm = 0  -- ????? pode zerar ?????
    Set @PBasIcmPro = 0
    Set @PIcmPro = 0 
    Set @PBasIcm = 0
    Set @PVlrIcm = 0 
    Set @PVlrIcmFcp = 0
    Set @PVlrOut = 0
  end


-- adiciona valor ipi ICMS tributável para notas de devolução de uso e consumo
--if (@PBasIcm > 0) and (@PTipNot = 'D') and (@PFlgIncIpiBasIcmTrib = 1) 
--  Set @PBasIcm = @PBasIcm + @PVlrIpi


-- pis/cofins
Set @WVlrBasPisCof = Round(@WLiq,2)

--ressarcimento é despesa
Set @WVlrBasPisCof = Round(@WLiq+@PVlrSbtRes,2)  

-- ipi
if @pm_FlgIncIpiCalPis = 1
  Set @WVlrBasPisCof = @WVlrBasPisCof + @PVlrIpi

-- exclui icm destacado na devolução de venda
if @pm_FlgExcIcmCalPis = 1
  begin
    if @PTipNot = 'D'  -- devolução de venda
      Set @WVlrBasPisCof = @WVlrBasPisCof - @PVlrIcm
    else
      Set @WVlrBasPisCof = @WVlrBasPisCof - @PIcmPro
  end

Exec PR_CalculaPisCofins @PCodEstabe, @PFlgCalPisCof, 'E', @em_CodTipLuc, @PDatMov, @PCfoCab, 0, @PCodNcm, @PTipLisPis, @WVlrBasPisCof, 
                         @PCstPis output, @PVlrBasPis output, @PAlqPis output, @PVlrPis output,
                         @PCstCof output, @PVlrBasCof output, @PAlqCof output, @PVlrCof output, @PObsNf output

-- Suframa
if (@PAlqIpi > 0) and (@PVlrBasSuf > 0)
  Set @PVlrSuf = @it_Vlr_TotIte/@PVlrBasSuf*@PVlrTaxSuf

Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CalcVerbaNFE]
@PCodEstabe int,
@PNumPrt int  -- 100057032

AS

SET NOCOUNT ON 

Begin Transaction

Update it
   Set it.Vlr_DscIte2 = 0
  From NFECB cb
       Inner Join NFEIT it on it.Cod_Estabe = cb.Cod_Estabe and it.Protocolo = cb.Protocolo
 Where cb.Cod_Estabe = @PCodEstabe
   And cb.Protocolo = @PNumPrt
--   And cb.Status <> 'F'
   And cb.Status <> 'C'

-- gera verba somente para compras e fornecedor habilitado
if Exists(Select 1
            From NFECB cb
                 Inner Join FORNE fo on cb.Cod_EmiFornec = fo.Codigo
           Where cb.Cod_Estabe = @PCodEstabe 
             And cb.Protocolo = @PNumPrt
             And cb.Tip_NF = 'C'
             And IsNull(fo.Flg_GerVrb,0) = 1
--             And cb.Status <> 'F'
		     And cb.Status <> 'C')
  begin
    Declare @cb_CodFor int,
            @fo_VlrMinVrb numeric(18,4),
            @WIdPcfor int,
            @WDatRefPrdCip smalldatetime  -- data referencia para preços "monitorados"

    Select @cb_CodFor = cb.Cod_EmiFornec,
           @fo_VlrMinVrb = IsNull(fo.Vlr_MinVrb,0),
           @WDatRefPrdCip = (Select max(Dat_RefPrdCip) From NFEIT Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumPrt)
      From NFECB cb
           Inner Join FORNE fo on cb.Cod_EmiFornec = fo.Codigo
     Where cb.Cod_Estabe = @PCodEstabe 
       And cb.Protocolo = @PNumPrt

    if Exists(Select 1 From NFEPC Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumPrt)
	  begin
        Update it
	       Set it.Vlr_DscIte2 = Case
                                  When Abs(Round(it.Qtd_Pedido*Round(i.Prc_Unitario*(1-i.Per_Desconto/100),2),2) - Round(it.Vlr_TotItem-it.Vlr_DescRateado-IsNull(it.Vlr_DscTri,0),2)) > @fo_VlrMinVrb then
                                    Round(it.Qtd_Pedido*Round(i.Prc_Unitario*(1-i.Per_Desconto/100),2),2) - Round(it.Vlr_TotItem-it.Vlr_DescRateado-IsNull(it.Vlr_DscTri,0),2)
                                  Else 0
                                End
          From NFEIT it
               Inner Join NFEPC cb on it.Cod_Estabe = cb.Cod_Estabe and it.Protocolo = cb.Protocolo
	           Inner Join PDCCB c on cb.Cod_Estabe = c.Cod_Estabe and cb.Cod_Pedido = c.Numero
               Inner Join PDCIT i on c.Cod_Estabe = i.Cod_Estabe and c.Numero = i.Numero and it.Cod_Produto = i.Cod_Produto
         Where it.Cod_Estabe = @PCodEstabe
           And it.Protocolo = @PNumPrt
	  end
    else
      begin
        if Exists(Select 1
                    From PCFOR 
                   Where Cod_Fornec = @cb_CodFor
                     And Dat_Valida >= @WDatRefPrdCip)
          begin
            Set @WIdPcfor = (Select top 1 Id_PCFOR From PCFOR 
                              Where Cod_Fornec = @cb_CodFor
                                And Dat_Valida >= @WDatRefPrdCip
                              Order by Dat_Valida)

            Update it
               Set it.Vlr_DscIte2 = Case
                                      When Abs(Round(it.Qtd_Pedido*Round(it.Prc_Fabric*(1-(dbo.Fn_PerDscNegFor(@WIdPcfor,it.Cod_Produto,it.Qtd_Pedido))/100),2),2) - Round(it.Vlr_TotItem-it.Vlr_DescRateado-IsNull(it.Vlr_DscTri,0),2)) > @fo_VlrMinVrb then
                                        Round(it.Qtd_Pedido*Round(it.Prc_Fabric*(1-(dbo.Fn_PerDscNegFor(@WIdPcfor,it.Cod_Produto,it.Qtd_Pedido))/100),2),2) - Round(it.Vlr_TotItem-it.Vlr_DescRateado-IsNull(it.Vlr_DscTri,0),2)
                                      Else 0
                                    End
              From NFEIT it
             Where it.Cod_Estabe = @PCodEstabe
               And it.Protocolo = @PNumPrt
          end
      end

    Update cb
       Set cb.Vlr_Verba = Round(it.VlrTotVerba,2)
      From NFECB cb
           Inner Join (Select Cod_Estabe, Protocolo, VlrTotVerba = sum(IsNull(Vlr_DscIte2,0)) 
                         From NFEIT
                        Where Cod_Estabe = @PCodEstabe
                          And Protocolo = @PNumPrt
                        Group by Cod_Estabe, Protocolo ) it on it.Cod_Estabe = cb.Cod_Estabe and it.Protocolo = cb.Protocolo
     Where cb.Cod_Estabe = @PCodEstabe
       And cb.Protocolo = @PNumPrt
  end  -- if Exists(Select 

-- calcula comissões e verbas de devoluções
Exec PR_CalculaComissoesVerbasDevolucao @PCodEstabe, @PNumPrt

Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CalculaTributosEntradaDevolucao]
@PCodEstabe int,
@PNumPrt int

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime

Set @Now = GetDate()
Set @Date = cast(GetDate() as Date)

Declare @PSerNotSai varchar(3),
        @PNumNotSai int,
        @StrMsg varchar(400),
        @StrPrd varchar(100),
		@CodPrd int,
		@FlgErr bit = 0

-- registra documentos relacionados
Exec PR_RegistraNEREF @PCodEstabe, @PNumPrt
if @@error <> 0
  begin
    Rollback Transaction
    Return
  end

Set @FlgErr = 0

if not Exists(Select 1 From NFECB 
               Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumPrt 
                 And Tip_NF = 'D' And ((Status = 'A') or (Status = 'P')))
  begin
    Set @FlgErr = 1
    Set @StrMsg = 'Nota Fiscal de Devolução Não Localizada ou Inválida'
  end
else
if (Select count(*) From NEREF Where Cod_Estabe = @PCodEstabe And Tip_EntSai = 'S' And Protocolo = @PNumPrt) <> 1
  begin
    Set @FlgErr = 1
    Set @StrMsg = 'Existe mais de 1 ou nenhum documento de saída relacionado'
  end
else
  begin
    -- verifica itens não relacionados no documento de saida
    Select @PSerNotSai = Ser_DocRef,
           @PNumNotSai = Num_DocRef
      From NEREF
     Where Cod_Estabe = @PCodEstabe
       and Protocolo = @PNumPrt 
       and Tip_EntSai = 'S'

    if Exists(Select 1
                From NFEIT ite
                     Left Join NFSIT its on ite.Cod_Estabe = its.Cod_Estabe and its.Ser_Nota = @PSerNotSai And its.Num_Nota = @PNumNotSai And ite.Cod_Produto = its.Cod_Produto
               Where ite.Cod_Estabe = @PCodEstabe
                 And ite.Protocolo = @PNumPrt
                 And its.Cod_Produto is null)
      begin
        Set @StrPrd = ''
        Set @CodPrd = 0

        while Exists(Select 1
                       From NFEIT ite
                            Left Join NFSIT its on ite.Cod_Estabe = its.Cod_Estabe and its.Ser_Nota = @PSerNotSai And its.Num_Nota = @PNumNotSai And ite.Cod_Produto = its.Cod_Produto
                      Where ite.Cod_Estabe = @PCodEstabe
                        And ite.Protocolo = @PNumPrt
                        And its.Cod_Produto is null
                        And ite.Cod_Produto > @CodPrd)
          begin
            Set @CodPrd = (Select top 1 ite.Cod_Produto
                             From NFEIT ite
                                  Left Join NFSIT its on ite.Cod_Estabe = its.Cod_Estabe and its.Ser_Nota = @PSerNotSai And its.Num_Nota = @PNumNotSai And ite.Cod_Produto = its.Cod_Produto
                            Where ite.Cod_Estabe = @PCodEstabe
                              And ite.Protocolo = @PNumPrt
                              And its.Cod_Produto is null
                              And ite.Cod_Produto > @CodPrd
                            Order by ite.Cod_Produto)
                               
            if LEN(@StrPrd) + LEN(cast(@CodPrd as varchar)+';') < 101               
              Set @StrPrd = @StrPrd + cast(@CodPrd as varchar)+';'                 
          end 
                
        Set @FlgErr = 1
        Set @StrMsg = 'Protocolo ('+CAST(@PNumPrt as varchar)+') com produtos não relacionaos no documento de saída: '+@StrPrd
      end
  end

-----------------------------------------------------------------------------------------------------------------------------------------

if @FlgErr = 1
  RAISERROR(@StrMsg,16,1)
else
BEGIN

BEGIN TRANSACTION

Declare @it_CodPrd int,
        @it_CodLot varchar(20),
        @it_NumSeqIte int,

        @it_PrcUni numeric(18,8),
        @it_QtdPed int,
        @it_QtdBon int,
        @it_PerDscIte numeric(18,8),
        @it_VlrDscRat numeric(18,4),
        @it_VlrDscTri numeric(18,4),
        @it_VlrDspRat numeric(18,4),

		@it_TipLisPis varchar(1), 
        @it_CodClaTri varchar(4),
        @it_CodSt varchar(2),
        @it_CodCsosn varchar(3),
        @it_PrcTabela numeric(18,4),
        @it_PrcFabric numeric(18,4),
        @it_PrcMaxCon numeric(18,4),
        @it_PrcRefFpb numeric(18,4),
        @it_PrcPonFin numeric(18,4),

        @it_VlrBasTri numeric(18,4),
        @it_AlqIcm numeric(18,4),
        @it_VlrBasIcmNor numeric(18,4),
        @it_VlrIcmNor numeric(18,4),
        @it_VlrBasRepIcm numeric(18,4),
        @it_VlrRepIcm numeric(18,4),
        @it_VlrBasIcmTri numeric(18,4),
        @it_VlrIcmTri numeric(18,4),
        @it_VlrIseIcm  numeric(18,4),
        @it_VlrOutIcm  numeric(18,4),
        @it_PerIcmDiferi numeric(18,4),
        @it_VlrIcmDiferi numeric(18,4),

        @it_CodOriMer varchar(1),
        @it_VlrBasIpi numeric(18,4),
        @it_VlrIpi numeric(18,4),
        @it_CstIpi varchar(2),
        @it_AlqIpi numeric(7,4),
        @it_CodEnqIpi varchar(3),


        @it_FlgUsaDebPresum bit, 
        @it_AlqDebPresum numeric(18,4),
        @it_VlrPrdSubTri numeric(18,4),

        @it_AlqIcmSbt numeric(18,4),
        @it_AlqAgrSbt numeric(18,4),
        @it_PerRedBasCalIcmSbt numeric(18,4),  

        @it_VlrBasSubTri numeric(18,4),
        @it_VlrSubTri numeric(18,4),
        @it_VlrBasSbtRes numeric(18,4),
        @it_VlrSbtRes numeric(18,4),

        @it_PerRedBasCalIcm numeric(18,4),
        @it_CodModBasCalIcm varchar(1),
        @it_CodModBasCalIcmSbt varchar(1),

        @it_CstPis varchar(2),
        @it_VlrBasPis numeric(18,4),
        @it_AlqPis numeric(18,4),
        @it_VlrPis numeric(18,4),
        @it_CstCof varchar(2),
        @it_VlrBasCof numeric(18,4),
        @it_AlqCof numeric(18,4),
        @it_VlrCof numeric(18,4),
        @it_VlrPisEst numeric(18,4),  -- estorno pis
        @it_VlrCofEst numeric(18,4),  -- estorno cofins

        @it_AlqIcmFcp numeric(18,4),
        @it_VlrIcmFcp numeric(18,4),          -- icms tributavel FCP: embutido em @PVlrIcm
        @it_AlqIcmSbtFcp numeric(18,4),
        @it_VlrSbtFcp numeric(18,4),
        @it_AlqIcmSbtFcpRet numeric(18,4),
        @it_VlrSubFcpRet numeric(18,4),

        @it_PrcVen numeric(18,4),
        @it_PrcUltEnt numeric(18,4),

        @it_VlrDscBonRat numeric(18,4),
        @it_VlrTotDspRat numeric(18,4),
        @it_VlrDspExt numeric(18,4),
        @it_VlrFrete numeric(18,4),
        @it_VlrSeguro numeric(18,4),
        @it_CodCfo smallint,

        @it_vBCSTRet numeric(18,4),
        @it_pST numeric(8,4),
        @it_vICMSSubstituto numeric(18,4),
        @it_vICMSSTRet numeric(18,4),
        @it_vBCFCPSTRet numeric(18,4),
        @it_pFCPSTRet numeric(8,4),
        @it_vFCPSTRet numeric(18,4),
        @it_pRedBCEfet numeric(8,4),
        @it_vBCEfet numeric(18,4),
        @it_pICMSEfet numeric(8,4),
        @it_vICMSEfet numeric(18,4),

        @it_cBenef varchar(10),

        @pr_AlqIpi numeric(18,4),
        @pr_TipLisPis varchar(1),
        @pr_CodNcm varchar(8)


-- variaveis de trabalho
Declare @WCodCfoNor smallint,
        @WCodCfoSbt smallint,
        @WFlgOpeInt bit,
        @WVlrBasPisCof numeric(18,4),
        @WFator numeric(18,8),
        @WObsNf varchar(200)

-- coloca campos de NFECB na memoria
Declare @cb_CodCfo smallint,
        @cb_CodOpe varchar(3),
        @cb_Estado varchar(2),
        @cb_DatMov datetime,
        @cb_TipDevEcf varchar(1),
        @em_CodEst varchar(2),
        @em_CodTipLuc varchar(2),
		@em_FlgContriSubstituido bit,
		@rt_FlgConsumFin bit,
        @pm_FlgIncIpiCalPis bit,
        @pm_FlgExcIcmCalPis bit

Select @em_CodEst = Des_Estado,
       @em_CodTipLuc = IsNull(Cod_TipLucro,''),
       @em_FlgContriSubstituido = IsNull(Flg_ContriSubstituido,0)
  From ESTAB
 Where Cod_Estabe = @PCodEstabe  

Select @pm_FlgIncIpiCalPis = IsNull(FlgIncIpiCalPis,0),
       @pm_FlgExcIcmCalPis = IsNull(FlgExcIcmCalPis,0)
  From PARAM
Where Cod_Estabe = @PCodEstabe

Select @cb_CodCfo = IsNull(cb.Cod_Cfo,0),
       @cb_CodOpe = cb.Cod_Ope,
       @cb_Estado = cb.Cod_UfOrigem,
       @cb_DatMov = cb.Dat_Movimento,
       @cb_TipDevEcf = ISNULL(cb.Tip_DevEcf, ''),
	   @rt_FlgConsumFin = IsNull(rt.Flg_ConsumFin,0)
  From NFECB cb Left Join
       RGTRI rt on cb.Cod_RegTri = rt.Cod_RegTri
 Where cb.Cod_Estabe = @PCodEstabe and cb.Protocolo = @PNumPrt

-- operacao interna ou externa
if @cb_Estado = @em_CodEst
  Set @WFlgOpeInt = 1
else
  Set @WFlgOpeInt = 0

-- colococa campos de TPOPE na memoria
Declare @to_CodCfoConFinInt smallint,
        @to_CodCfoConFinExt smallint,
	    @to_CodCfoNorInt smallint,
        @to_CodCfoNorExt smallint,
        @to_CodCfoSbtInt smallint,
        @to_CodCfoSbtExt smallint,
        @to_CodCfoSubstituidoInt smallint,
        @to_CodCfoSubstituidoExt smallint,
        @to_FlgCalIcmSbt bit,
        @to_FlgCalIcmNor bit,
        @to_FlgCalRepIcm bit,
        @to_FlgCalPisCof bit

Set @WCodCfoNor = 0
Set @WCodCfoSbt = 0
Set @to_FlgCalIcmSbt = 0
Set @to_FlgCalIcmNor = 0
Set @to_FlgCalRepIcm = 0
Set @to_FlgCalPisCof = 0

if Exists(Select Cod_Ope From TPOPE Where Cod_Ope = @cb_CodOpe)
  begin
    Select @to_CodCfoConFinInt = IsNull(Cod_CfoConFinInt,0),
	       @to_CodCfoConFinExt = IsNull(Cod_CfoConFinExt,0),
	       @to_CodCfoNorInt = Isnull(Cod_CfoNorInt,0),       
           @to_CodCfoNorExt = Isnull(Cod_CfoNorExt,0),
           @to_CodCfoSbtInt = Case 
                                When @em_FlgContriSubstituido = 1 and IsNull(Cod_CfoSbtIntSubstituido,0) > 0 then Cod_CfoSbtIntSubstituido
			                    Else Isnull(Cod_CfoSbtInt,0)
	 				          End, 
           @to_CodCfoSbtExt = Case 
	                            When @em_FlgContriSubstituido = 1 and IsNull(Cod_CfoSbtExtSubstituido,0) > 0 then Cod_CfoSbtExtSubstituido
					            Else Isnull(Cod_CfoSbtExt,0)
					          End,
           @to_CodCfoSubstituidoInt = IsNull(Cod_CfoSbtIntSubstituido,0),
           @to_CodCfoSubstituidoExt = IsNull(Cod_CfoSbtExtSubstituido,0),
           @to_FlgCalIcmSbt = case 
                                When @WFlgOpeInt = 1 then Isnull(Flg_CalIcmSbt,0)
                                else Isnull(Flg_CalIcmSbtExt,0)
                              end,
           @to_FlgCalIcmNor = case 
                                When @WFlgOpeInt = 1 then Isnull(Flg_CalIcmNor,0)
                                else Isnull(Flg_CalIcmNorExt,0)
                              end,
           @to_FlgCalRepIcm = case 
                                When @WFlgOpeInt = 1 then Isnull(Flg_CalRepIcmInt,0)
                                else Isnull(Flg_CalRepIcm,0)
                              end,
           @to_FlgCalPisCof = Isnull(Flg_CalPisCof,0)
      From TPOPE
     Where Cod_Ope = @cb_CodOpe

    if @rt_FlgConsumFin = 1
      if @WFlgOpeInt = 1
	    begin
          Set @WCodCfoNor = @to_CodCfoConFinInt
          Set @WCodCfoSbt = @to_CodCfoConFinInt
        end
      else
	    begin
          Set @WCodCfoNor = @to_CodCfoConFinExt
          Set @WCodCfoSbt = @to_CodCfoConFinExt
        end
    else
      if @WFlgOpeInt = 1
        begin
          Set @WCodCfoNor = @to_CodCfoNorInt
          Set @WCodCfoSbt = @to_CodCfoSbtInt
        end
      else
        begin
          Set @WCodCfoNor = @to_CodCfoNorExt
          Set @WCodCfoSbt = @to_CodCfoSbtExt
        end
  end

-- normaliza CFO
if (@WCodCfoNor = 0) or (@WCodCfoSbt= 0)
  EXEC PR_CfopEntSai  @PCodEstabe, @cb_CodCfo, @WCodCfoNor output, @WCodCfoSbt output


Declare NFEIT_Cr Cursor Local Fast_Forward For 

  Select Cod_Produto, Cod_Lote, Num_SeqIte,
         Qtd_Pedido, Qtd_Bonificacao, Prc_Unitario, Per_DescItem
    From NFEIT 
   Where Cod_Estabe = @PCodEstabe 
     and Protocolo = @PNumPrt

Open NFEIT_Cr
Fetch Next From NFEIT_Cr Into @it_CodPrd, @it_CodLot, @it_NumSeqIte,
                              @it_QtdPed, @it_QtdBon, @it_PrcUni, @it_PerDscIte

While @@FETCH_STATUS = 0
  begin

    Select @pr_CodNcm = Substring(Ltrim(Rtrim(pr.Cod_ClaFis)),1,8),
           @pr_TipLisPis = IsNull(pr.Tip_LisPis,''),
           @pr_AlqIpi = IsNull(pr.Per_Ipi,0)
      From PRXES p 
           Inner Join PRODU pr on p.Cod_Produt = pr.Codigo
    Where p.Cod_Estabe = @PCodEstabe
    And p.Cod_Produt = @it_CodPrd

    if Exists(Select 1 From NFSIT 
              Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNotSai and Num_Nota = @PNumNotSai and 
                    Cod_Produto = @it_CodPrd and Cod_Lote = @it_CodLot)
      Select top 1 @WFator = (@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Produto+Qtd_Bonificacao),
	               @it_TipLisPis       = Tip_Aux,
                   @it_CodClaTri       = Cod_ClaTri,
                   @it_CodSt           = Ctrl_Tributacao,
                   @it_CodCsosn        = Cod_CSOSN,
                   @it_PrcTabela       = IsNull(Prc_TabBru,0),
                   @it_PrcFabric       = IsNull(Prc_Fabric,0),
                   @it_PrcMaxCon       = IsNull(Prc_MaxCon,0),
                   @it_PrcRefFpb       = IsNull(Prc_RefFpb,0),
                   @it_PrcPonFin       = IsNull(Prc_PonFin,0),
                   @it_PrcUltEnt       = IsNull(Prc_LiqUltEnt,0),
                   @it_VlrBasTri       = IsNull(Vlr_BasTri,0),
                   @it_AlqIcm          = Isnull(Alq_Icms,0),
                   @it_VlrBasIcmNor    = IsNull(Vlr_BasIcmsNor,0),
                   @it_VlrIcmNor       = IsNull(Vlr_IcmsNor,0),
                   @it_VlrBasRepIcm    = IsNull(Vlr_BasRepIcms,0),
                   @it_VlrRepIcm       = IsNull(Vlr_RepIcms,0),

                   @it_PerRedBasCalIcm = IsNull(Per_RedBasCalIcm,0),
                   @it_CodModBasCalIcm = IsNull(Cod_ModBasCalIcm,''),
                   @it_CodModBasCalIcmSbt = IsNull(Cod_ModBasCalIcmSbt,''),

                   @it_VlrPrdSubTri    = IsNull(Vlr_PrdSubTri,0),
                   @it_AlqIcmSbt       = IsNull(Alq_IcmSbt,0),
                   @it_AlqAgrSbt       = IsNull(Alq_AgrSbt,0),
                   @it_PerRedBasCalIcmSbt = IsNull(Per_RedBasCalIcmSbt,0),  
                   @it_VlrBasSubTri    = IsNull(Vlr_BasSubsTrib,0),
                   @it_VlrSubTri       = IsNull(Vlr_SubsTrib,0),
                   @it_VlrBasSbtRes    = IsNull(Vlr_BasSbtRes,0),
                   @it_VlrSbtRes       = IsNull(Vlr_SbtRes,0),

                   @it_VlrBasIcmTri    = IsNull(Vlr_BasIcmsTri,0),
                   @it_VlrIcmTri       = IsNull(Vlr_IcmsTri,0),
                   @it_VlrIseIcm       = IsNull(Vlr_Isento,0),
                   @it_VlrOutIcm       = IsNull(Vlr_Outros,0),

                   @it_PerIcmDiferi    = IsNull(Per_IcmDiferi,0),
                   @it_VlrIcmDiferi    = IsNull(Vlr_IcmDiferi,0),

                   @it_VlrBasIpi       = IsNull(Vlr_BasIpi,0),
                   @it_VlrIpi          = IsNull(Vlr_Ipi,0),

                   @it_CodOriMer       = IsNull(Cod_OriMer,''),
                   @it_CstIpi          = IsNull(CST_Ipi,''),
                   @it_AlqIpi          = IsNull(Alq_Ipi,0),
                   @it_CodEnqIpi       = IsNull(Cod_EnqIpi,''),

                   @it_VlrPisEst       = IsNull(Vlr_Pis,0),
                   @it_VlrCofEst       = IsNull(Vlr_Cofins,0),

                   @it_AlqIcmFcp       = IsNull(Alq_FcpIcm,0),
                   @it_VlrIcmFcp       = IsNull(Vlr_FcpIcm,0),
                   @it_AlqIcmSbtFcp    = IsNull(Alq_FcpSbt,0),
                   @it_VlrSbtFcp       = IsNull(Vlr_FcpSbt,0),
                   @it_AlqIcmSbtFcpRet = IsNull(Alq_FcpSbtRet,0),
                   @it_VlrSubFcpRet    = IsNull(Vlr_FcpSbtRet,0),

                   @it_VlrDscRat       = IsNull(Vlr_DescRateado,0),
                   @it_VlrDscTri       = IsNull(Vlr_DscTri,0),
                   @it_VlrDscBonRat    = IsNull(Vlr_DscBonRat,0),

                   @it_VlrTotDspRat    = IsNull(Vlr_DespRateada,0)+Isnull(Vlr_Frete,0)+IsNull(Vlr_Seguro,0),
                   @it_VlrDspRat       = IsNull(Vlr_DespRateada,0),
                   @it_VlrFrete        = Isnull(Vlr_Frete,0),
                   @it_VlrSeguro       = Isnull(Vlr_Seguro,0),
                   @it_VlrDspExt       = Isnull(Vlr_DspExt,0),

                   @it_vBCSTRet        = IsNull(vBCSTRet,0),
                   @it_pST             = IsNull(pST,0), 
                   @it_vICMSSubstituto = IsNull(vICMSSubstituto,0),
                   @it_vICMSSTRet      = IsNull(vICMSSTRet,0),
                   @it_vBCFCPSTRet     = IsNull(vBCFCPSTRet,0),
                   @it_pFCPSTRet       = IsNull(pFCPSTRet,0),
                   @it_vFCPSTRet       = IsNull(vFCPSTRet,0),

                   @it_pRedBCEfet      = IsNull(pRedBCEfet,0),
                   @it_vBCEfet         = IsNull(vBCEfet,0),
                   @it_pICMSEfet       = IsNull(pICMSEfet,0),
                   @it_vICMSEfet       = IsNull(vICMSEfet,0),

                   @it_cBenef          = IsNull(cBenef,'')
      From NFSIT 
      Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNotSai and Num_Nota = @PNumNotSai and 
            Cod_Produto = @it_CodPrd and Cod_Lote = @it_CodLot
    else
    if Exists(Select 1 From NFSIT 
              Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNotSai and Num_Nota = @PNumNotSai and 
                      Cod_Produto = @it_CodPrd)
      Select top 1 
             @WFator = (@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Produto+Qtd_Bonificacao),
             @it_TipLisPis       = Tip_Aux,
             @it_CodClaTri       = Cod_ClaTri,
             @it_CodSt           = Ctrl_Tributacao,
             @it_CodCsosn        = Cod_CSOSN,
             @it_PrcTabela       = IsNull(Prc_TabBru,0),
             @it_PrcFabric       = IsNull(Prc_Fabric,0),
             @it_PrcMaxCon       = IsNull(Prc_MaxCon,0),
             @it_PrcRefFpb       = IsNull(Prc_RefFpb,0),
             @it_PrcPonFin       = IsNull(Prc_PonFin,0),
             @it_PrcUltEnt       = IsNull(Prc_LiqUltEnt,0),
             @it_VlrBasTri       = IsNull(Vlr_BasTri,0),
             @it_AlqIcm          = Isnull(Alq_Icms,0),
             @it_VlrBasIcmNor    = IsNull(Vlr_BasIcmsNor,0),
             @it_VlrIcmNor       = IsNull(Vlr_IcmsNor,0),
             @it_VlrBasRepIcm    = IsNull(Vlr_BasRepIcms,0),
             @it_VlrRepIcm       = IsNull(Vlr_RepIcms,0),
	 
             @it_PerRedBasCalIcm = IsNull(Per_RedBasCalIcm,0),
             @it_CodModBasCalIcm = IsNull(Cod_ModBasCalIcm,''),
             @it_CodModBasCalIcmSbt = IsNull(Cod_ModBasCalIcmSbt,''),
	 
             @it_VlrPrdSubTri    = IsNull(Vlr_PrdSubTri,0),
             @it_AlqIcmSbt       = IsNull(Alq_IcmSbt,0),
             @it_AlqAgrSbt       = IsNull(Alq_AgrSbt,0),
             @it_PerRedBasCalIcmSbt = IsNull(Per_RedBasCalIcmSbt,0),  
             @it_VlrBasSubTri    = IsNull(Vlr_BasSubsTrib,0),
             @it_VlrSubTri       = IsNull(Vlr_SubsTrib,0),
             @it_VlrBasSbtRes    = IsNull(Vlr_BasSbtRes,0),
             @it_VlrSbtRes       = IsNull(Vlr_SbtRes,0),
	 
             @it_VlrBasIcmTri    = IsNull(Vlr_BasIcmsTri,0),
             @it_VlrIcmTri       = IsNull(Vlr_IcmsTri,0),
             @it_VlrIseIcm       = IsNull(Vlr_Isento,0),
             @it_VlrOutIcm       = IsNull(Vlr_Outros,0),
	 
             @it_PerIcmDiferi    = IsNull(Per_IcmDiferi,0),
             @it_VlrIcmDiferi    = IsNull(Vlr_IcmDiferi,0),
	 
             @it_VlrBasIpi       = IsNull(Vlr_BasIpi,0),
             @it_VlrIpi          = IsNull(Vlr_Ipi,0),
             @it_CodOriMer       = IsNull(Cod_OriMer,''),
             @it_CstIpi          = IsNull(CST_Ipi,''),
             @it_AlqIpi          = IsNull(Alq_Ipi,0),
             @it_CodEnqIpi       = IsNull(Cod_EnqIpi,''),
	 
             @it_VlrPisEst       = IsNull(Vlr_Pis,0),
             @it_VlrCofEst       = IsNull(Vlr_Cofins,0),
	 
             @it_AlqIcmFcp       = IsNull(Alq_FcpIcm,0),
             @it_VlrIcmFcp       = IsNull(Vlr_FcpIcm,0),
             @it_AlqIcmSbtFcp    = IsNull(Alq_FcpSbt,0),
             @it_VlrSbtFcp       = IsNull(Vlr_FcpSbt,0),
             @it_AlqIcmSbtFcpRet = IsNull(Alq_FcpSbtRet,0),
             @it_VlrSubFcpRet    = IsNull(Vlr_FcpSbtRet,0),
	 
             @it_VlrDscRat       = IsNull(Vlr_DescRateado,0),
             @it_VlrDscTri       = IsNull(Vlr_DscTri,0),
             @it_VlrDscBonRat    = IsNull(Vlr_DscBonRat,0),
	 
             @it_VlrTotDspRat    = IsNull(Vlr_DespRateada,0)+Isnull(Vlr_Frete,0)+IsNull(Vlr_Seguro,0),
             @it_VlrDspRat       = IsNull(Vlr_DespRateada,0),
             @it_VlrFrete        = Isnull(Vlr_Frete,0),
             @it_VlrSeguro       = Isnull(Vlr_Seguro,0),
             @it_VlrDspExt       = Isnull(Vlr_DspExt,0),
	
             @it_vBCSTRet        = IsNull(vBCSTRet,0),
             @it_pST             = IsNull(pST,0), 
             @it_vICMSSubstituto = IsNull(vICMSSubstituto,0),
             @it_vICMSSTRet      = IsNull(vICMSSTRet,0),
             @it_vBCFCPSTRet     = IsNull(vBCFCPSTRet,0),
             @it_pFCPSTRet       = IsNull(pFCPSTRet,0),
             @it_vFCPSTRet       = IsNull(vFCPSTRet,0),
	 
             @it_pRedBCEfet      = IsNull(pRedBCEfet,0),
             @it_vBCEfet         = IsNull(vBCEfet,0),
             @it_pICMSEfet       = IsNull(pICMSEfet,0),
             @it_vICMSEfet       = IsNull(vICMSEfet,0),
	 
             @it_cBenef          = IsNull(cBenef,'')
        From NFSIT 
       Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNotSai and Num_Nota = @PNumNotSai and Cod_Produto = @it_CodPrd

    Set @it_VlrBasTri       = Round(@it_VlrBasTri*@WFator,4)
    Set @it_VlrBasIcmNor    = Round(@it_VlrBasIcmNor*@WFator,2)
    Set @it_VlrIcmNor       = Round(@it_VlrIcmNor*@WFator,4)

    Set @it_VlrBasRepIcm    = Round(@it_VlrBasRepIcm*@WFator,2)
    Set @it_VlrRepIcm       = Round(@it_VlrRepIcm*@WFator,4)

    Set @it_VlrPrdSubTri    = Round(@it_VlrPrdSubTri*@WFator,2)
    Set @it_VlrBasSubTri    = Round(@it_VlrBasSubTri*@WFator,2)
    Set @it_VlrSubTri       = Round(@it_VlrSubTri*@WFator,4)
    Set @it_VlrBasSbtRes    = Round(@it_VlrBasSbtRes*@WFator,2)
    Set @it_VlrSbtRes       = Round(@it_VlrSbtRes*@WFator,4)

    Set @it_VlrBasIcmTri    = Round(@it_VlrBasIcmTri*@WFator,2)
    Set @it_VlrIcmTri       = Round(@it_VlrIcmTri*@WFator,4)
    Set @it_VlrIseIcm       = Round(@it_VlrIseIcm*@WFator,4)
    Set @it_VlrOutIcm       = Round(@it_VlrOutIcm*@WFator,4)

    Set @it_VlrIcmDiferi    = Round(IsNull(@it_VlrIcmDiferi*@WFator,0),4)

    Set @it_VlrBasIpi       = Round(@it_VlrBasIpi*@WFator,2)
    Set @it_VlrIpi          = Round(@it_VlrIpi*@WFator,4)

    Set @it_VlrPisEst       = Round(@it_VlrPisEst*@WFator,4)
    Set @it_VlrCofEst       = Round(@it_VlrCofEst*@WFator,4)

    Set @it_VlrIcmFcp       = Round(@it_VlrIcmFcp*@WFator,4)
    Set @it_VlrSbtFcp       = Round(@it_VlrSbtFcp*@WFator,4)
    Set @it_VlrSubFcpRet    = Round(@it_VlrSubFcpRet*@WFator,4)

    Set @it_VlrDscRat       = Round(@it_VlrDscRat*@WFator,4)

    if @cb_TipDevEcf = 'D'
      Set @it_VlrDscRat = 0

    Set @it_VlrDscTri       = Round(@it_VlrDscTri*@WFator,4)
    Set @it_VlrDscBonRat    = Round(@it_VlrDscBonRat*@WFator,4)

    Set @it_VlrTotDspRat    = Round(@it_VlrTotDspRat*@WFator,4)
    Set @it_VlrDspRat       = Round(@it_VlrDspRat*@WFator,4)
    Set @it_VlrFrete        = Round(@it_VlrFrete*@WFator,4)
    Set @it_VlrSeguro       = Round(@it_VlrSeguro*@WFator,4)
    Set @it_VlrDspExt       = Round(@it_VlrDspExt*@WFator,4)

    Set @it_vBCSTRet        = Round(@it_vBCSTRet*@WFator,2)
    Set @it_vICMSSubstituto = Round(@it_vICMSSubstituto*@WFator,4)
    Set @it_vICMSSTRet      = Round(@it_vICMSSTRet*@WFator,4)
    Set @it_vBCFCPSTRet     = Round(@it_vBCFCPSTRet*@WFator,2)
    Set @it_vFCPSTRet       = Round(@it_vFCPSTRet*@WFator,4)

    Set @it_vBCEfet         = Round(@it_vBCEfet*@WFator,2)
    Set @it_vICMSEfet       = Round(@it_vICMSEfet*@WFator,4)

    -- define CFOP do item conforme CST
    --if Charindex(@it_CodSt,'10;30;60;70;90;') > 0 
    if Charindex(@it_CodSt,'10;30;60;70;') > 0 
      Set @it_CodCfo = @WCodCfoSbt
    else
      Set @it_CodCfo = @WCodCfoNor

    if (@rt_FlgConsumFin = 0) and (@it_CodSt = '60')
      if @WFlgOpeInt = 1
        begin
          if (@it_CodCfo <> @to_CodCfoSubstituidoInt) and (@to_CodCfoSubstituidoInt > 0)
            Set @it_CodCfo = @to_CodCfoSubstituidoInt
        end
    else
      if @WFlgOpeInt = 0
        begin
          if (@it_CodCfo <> @to_CodCfoSubstituidoExt) and (@to_CodCfoSubstituidoExt > 0)
            Set @it_CodCfo = @to_CodCfoSubstituidoExt
        end


    -- pis/cofins
    Set @WVlrBasPisCof = Round(@it_VlrBasTri+@it_VlrSbtRes,2)

    -- ipi
    if @pm_FlgIncIpiCalPis = 1
      Set @WVlrBasPisCof = @WVlrBasPisCof + @it_VlrIpi

    -- exclui icm destacado
    if @pm_FlgExcIcmCalPis = 1
      Set @WVlrBasPisCof = @WVlrBasPisCof - @it_VlrIcmTri

    Exec PR_CalculaPisCofins @PCodEstabe, @to_FlgCalPisCof, 'E', @em_CodTipLuc, @cb_DatMov, @cb_CodCfo, 0, @pr_CodNcm, @pr_TipLisPis, @WVlrBasPisCof, 
                             @it_CstPis output, @it_VlrBasPis output, @it_AlqPis output, @it_VlrPis output,
                             @it_CstCof output, @it_VlrBasCof output, @it_AlqCof output, @it_VlrCof output, @WObsNf output

    -- grava valores em NFEIT
    Update NFEIT
      Set Cod_ClaTri          = @it_CodClaTri,
          Tip_LisPis          = @pr_TipLisPis,
          Per_IpiCad          = @pr_AlqIpi,
          Cod_Ncm             = @pr_CodNcm,
          --Dat_RefPrdCip = @PDatRefPrdCip,
          Prc_Venda           = @it_PrcTabela,
          Prc_Fabric          = @it_PrcFabric,
          Prc_MaxCon          = @it_PrcMaxCon,
          Prc_RefFpb          = @it_PrcRefFpb,
          Prc_PonFin          = @it_PrcPonFin,

          Cod_Cfo             = @it_CodCfo,
          Vlr_BasTri          = @it_VlrBasTri,
          Ctrl_Tributacao     = @it_CodSt,
          Cod_CSOSN           = @it_CodCsosn,
          --Tip_PrcBasDebSbt = @PTipPrcBasDebSbt,  
          --Tip_PrcBasCreSbt = @PTipPrcBasCreSbt,

          Alq_Icms            = @it_AlqIcm,
          Vlr_BasIcmsNor      = @it_VlrBasIcmNor,
          Vlr_IcmsNor         = @it_VlrIcmNor,

          Flg_UsaCrePresum    = @it_FlgUsaDebPresum,
          Alq_IcmPresum       = @it_AlqDebPresum,

          Vlr_PrdSubTri       = @it_VlrPrdSubTri,
          Vlr_BasSubsTrib     = @it_VlrBasSubTri,
          Vlr_SubsTrib        = @it_VlrSubTri,
          Vlr_BasSbtRes       = @it_VlrBasSbtRes,
          Vlr_SbtRes          = @it_VlrSbtRes,
          Vlr_BasDifTri       = 0,
          Vlr_DifTri          = 0,
          Vlr_BasAntRec       = 0,
          Vlr_PrdAntRec       = 0,
          Vlr_AntRec          = 0,

          Vlr_BasIcmsTrib     = @it_VlrBasIcmTri,
          Vlr_IcmsTrib        = @it_VlrIcmTri,
          Vlr_Isento          = @it_VlrIseIcm,
          Vlr_Outros          = @it_VlrOutIcm,

          Per_IcmDiferi       = 0,
          Vlr_IcmDiferi       = 0,

          --Flg_UsaCreIcmSbt = @PFlgUsaCreIcmSbt,
          --Per_RedBasCalIcmDeb = @PPerRedBasCalIcmDeb,

          Alq_AgrDeb          = @it_AlqAgrSbt,
          Per_RedBasCalDeb    = @it_PerRedBasCalIcmSbt,
          Alq_IcmDeb          = @it_AlqIcmSbt,
          --Alq_IcmSbt          = @it_AlqIcmSbt,

          --Vlr_DebIcm = @PVlrDebIcm,
          Per_RedBasCalIcmCre = @it_PerRedBasCalIcm,
          --Per_LimBasCalCreSbt = @PPerLimBasCalCreSbt,
          --Vlr_LimCreIcm = @PVlrLimCreIcm,
	      --Vlr_DspCusEnt = @PVlrDspSubCusCreIcm,

          Cod_ModBasCalIcm    = @it_CodModBasCalIcm,
          Cod_ModBasCalIcmSbt = @it_CodModBasCalIcmSbt,
          --CST_Ipi = @PCstIpi,

          CST_Pis             = @it_CstPis,
          Vlr_BasPis          = @it_VlrBasPis,
          Alq_Pis             = @it_AlqPis,
          Vlr_Pis             = @it_VlrPis,

          Vlr_Suframa         = 0,  --@PVlrSuf
          Vlr_DspExt          = @it_VlrDspExt,

          CST_Cofins          = @it_CstCof,
          Vlr_BasCofins       = @it_VlrBasCof,
          Alq_Cofins          = @it_AlqCof,
          Vlr_Cofins          = @it_VlrCof,

          Vlr_PisEstDev       = @it_VlrPisEst,
          Vlr_CofEstDev       = @it_VlrCofEst,

          Alq_FcpIcm          = @it_AlqIcmFcp, 
          Vlr_FcpIcm          = @it_VlrIcmFcp, 
          Alq_FcpSbt          = @it_AlqIcmSbtFcp, 
          Vlr_FcpSbt          = @it_VlrSbtFcp, 
          Alq_FcpSbtRet       = @it_AlqIcmSbtFcpRet, 
          Vlr_FcpSbtRet       = @it_VlrSubFcpRet,

          Alq_FcpSbtRec       = 0, 
          Vlr_FcpSbtRec       = 0,
          Alq_FcpSbtAnt       = 0, 
          Vlr_FcpSbtAnt       = 0,

          Cod_OriMer          = @it_CodOriMer,
          CST_Ipi             = '',  -- ????
          Vlr_BasIpi          = @it_VlrBasIpi,
		  Vlr_Ipi             = @it_VlrIpi,
          Cod_EnqIpi          = @it_CodEnqIpi,

		  Vlr_Frete           = @it_VlrFrete,
		  Vlr_Seguro          = @it_VlrSeguro,
		  Vlr_DespRateada     = @it_VlrDspRat,
		  Vlr_DescRateado     = @it_VlrDscRat + @it_VlrRepIcm + @it_VlrDscBonRat,
          Vlr_DscTri          = @it_VlrDscTri,

		  cBenef               = @it_cBenef,

          Xml_vBCSTRet        = @it_vBCSTRet,
          Xml_pST             = @it_pST,
          Xml_vICMSSubstituto = @it_vICMSSubstituto,
          Xml_vICMSSTRet      = @it_vICMSSTRet,
          Xml_vBCFCPSTRet     = @it_vBCFCPSTRet,
          Xml_pFCPSTRet       = @it_pFCPSTRet,
          Xml_vFCPSTRet       = @it_vFCPSTRet,

          Xml_pRedBCEfet      = @it_pRedBCEfet,
          Xml_vBCEfet         = @it_vBCEfet,
          Xml_pICMSEfet       = @it_pICMSEfet,
          Xml_vICMSEfet       = @it_vICMSEfet

    Where Cod_Estabe = @PCodEstabe and Protocolo = @PNumPrt 
    And Cod_Produto = @it_CodPrd and Cod_Lote = @it_CodLot and Num_SeqIte = @it_NumSeqIte

    -- calc fields
    Update NFEIT
      Set Vlr_DscIte1 = Round(Prc_Unitario*Qtd_Pedido,2) - Round(Prc_Unitario*Qtd_Pedido*(1-Per_DescItem/100),2),
          Vlr_DscIte2 = 0,
          Vlr_TotItem = Round(Prc_Unitario*Qtd_Pedido*(1-Per_DescItem/100),2),
          Vlr_BruItem = Round(Prc_Unitario*(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)),2),
          Vlr_DescItem = Round(Prc_Unitario*(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)),2) - Round(Prc_Unitario*Qtd_Pedido*(1-Per_DescItem/100),2)
    Where Cod_Estabe = @PCodEstabe
      And Protocolo = @PNumPrt

    Update NFEIT
       Set Vlr_LiqIte = dbo.FN_ValLiqIteNFEIT(Cod_Estabe,
                                              Protocolo,
                                              Cod_Produto,
                                              Cod_Lote,
                                              Num_SeqIte)
     Where Cod_Estabe = @PCodEstabe and Protocolo = @PNumPrt 
       And Cod_Produto = @it_CodPrd and Cod_Lote = @it_CodLot and Num_SeqIte = @it_NumSeqIte

    Fetch Next From NFEIT_Cr Into @it_CodPrd, @it_CodLot, @it_NumSeqIte,
                                  @it_QtdPed, @it_QtdBon, @it_PrcUni, @it_PerDscIte
  end

Close NFEIT_Cr
Deallocate NFEIT_Cr


-- calcula comissões e verbas de devoluções
Exec PR_CalcVerbaNFE @PCodEstabe, @PNumPrt


-- atualiza cabeçalho
Exec PR_NormalizaValoresNFE @PCodEstabe, @PNumPrt

COMMIT TRANSACTION

END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CalculaTributosSaidaDevolucao]
@PCodEstabe int,
@PSerNot varchar(3),
@PNumNot int

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime

Set @Now = GetDate()
Set @Date = cast(GetDate() as date)

Declare @NumPrt int,
        @StrMsg varchar(400),
        @StrPrd varchar(100),
		@CodPrd int,
		@FlgErr bit = 0

-- registra documentos relacionados
Exec PR_RegistraNSREF @PCodEstabe, @PSernot, @PNumNot
if @@error <> 0
  begin
    Rollback Transaction
    Return
  end

Set @FlgErr = 0

if not Exists(Select 1 From NFSCB 
              Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot And Tip_Saida = 'D' And Status = 'A')
  begin
    Set @FlgErr = 1
    Set @StrMsg = 'Nota Fiscal de Devolução Não Localizada ou Inválida'
  end
else
if (Select count(*) From NSREF Where Cod_Estabe = @PCodEstabe And Tip_EntSai = 'E' And Ser_Nota = @PSerNot And Num_Nota = @PNumNot) <> 1
  begin
    Set @FlgErr = 1
    Set @StrMsg = 'Existe mais de 1 ou nenhum documento de saída relacionado'
  end
else
  begin
    -- verifica itens não relacionados no documento de saida
    Select @NumPrt = Num_DocRef
    From NSREF
    Where Cod_Estabe = @PCodEstabe
    and Ser_Nota = @PSerNot
    and Num_Nota = @PNumNot 
    and Tip_EntSai = 'E'

    if Exists(Select 1
                From NFSIT its
                     Left Join NFEIT ite on ite.Cod_Estabe = its.Cod_Estabe And ite.Protocolo = @NumPrt  And ite.Cod_Produto = its.Cod_Produto
               Where ite.Cod_Estabe = @PCodEstabe
                 And its.Ser_Nota = @PSerNot
                 And its.Num_Nota = @PNumNot
                 And ite.Cod_Produto is null)
      begin
        Set @StrPrd = ''
        Set @CodPrd = 0

        while Exists(Select 1
                       From NFSIT its
                            Left Join NFEIT ite on ite.Cod_Estabe = its.Cod_Estabe And ite.Protocolo = @NumPrt  And ite.Cod_Produto = its.Cod_Produto
                      Where its.Cod_Estabe = @PCodEstabe
                        And its.Ser_Nota = @PSerNot
                        And its.Num_Nota = @PNumNot
                        And ite.Cod_Produto is null
                        And its.Cod_Produto > @CodPrd)
          begin
            Set @CodPrd = (Select top 1 its.Cod_Produto
                           From NFSIT its
                                Left Join NFEIT ite on ite.Cod_Estabe = its.Cod_Estabe And ite.Protocolo = @NumPrt  And ite.Cod_Produto = its.Cod_Produto
                           Where its.Cod_Estabe = @PCodEstabe
                           And its.Ser_Nota = @PSerNot
                           And its.Num_Nota = @PNumNot
                           And ite.Cod_Produto is null
                           And its.Cod_Produto > @CodPrd
                           Order by its.Cod_Produto)
                               
            if LEN(@StrPrd) + LEN(cast(@CodPrd as varchar)+';') < 101               
              Set @StrPrd = @StrPrd + cast(@CodPrd as varchar)+';'                 
          end 
                
        Set @FlgErr = 1
        Set @StrMsg = 'NF ('+CAST(@PNumNot as varchar)+') com produtos não relacionaos no documento de entrada: '+@StrPrd
      end
  end

-----------------------------------------------------------------------------------------------------------------------------------------

if @FlgErr = 1
  RAISERROR(@StrMsg,16,1)
else
BEGIN

BEGIN TRANSACTION

Declare @it_CodPrd int,
        @it_CodLot varchar(20),
        @it_NumSeqIte int,

        @it_PrcUni numeric(18,8),
        @it_QtdPed int,
        @it_QtdBon int,
        @it_PerDscIte numeric(18,8),
        @it_VlrDscRat numeric(18,4),
        @it_VlrDscTri numeric(18,4),
        @it_VlrDspRat numeric(18,4),

		@it_TipLisPis varchar(1), 
        @it_CodClaTri varchar(4),
        @it_CodSt varchar(2),
        @it_CodCsosn varchar(3),
        @it_PrcTabela numeric(18,4),
        @it_PrcFabric numeric(18,4),
        @it_PrcMaxCon numeric(18,4),
        @it_PrcRefFpb numeric(18,4),

        @it_VlrBasTri numeric(18,4),
        @it_AlqIcm numeric(18,4),
        @it_VlrBasIcmNor numeric(18,4),
        @it_VlrIcmNor numeric(18,4),
        @it_VlrBasRepIcm numeric(18,4),
        @it_VlrRepIcm numeric(18,4),
        @it_VlrBasIcmTri numeric(18,4),
        @it_VlrIcmTri numeric(18,4),
        @it_VlrIseIcm  numeric(18,4),
        @it_VlrOutIcm  numeric(18,4),
        @it_PerIcmDiferi numeric(18,4),
        @it_VlrIcmDiferi numeric(18,4),
        @it_VlrBasIpi numeric(18,4),
        @it_VlrIpi numeric(18,4),

        @it_FlgUsaDebPresum bit, 
        @it_AlqDebPresum numeric(18,4),
        @it_VlrPrdSubTri numeric(18,4),

        @it_AlqIcmSbt numeric(18,4),
        @it_AlqAgrSbt numeric(18,4),
        @it_PerRedBasCalIcmSbt numeric(18,4),  

        @it_VlrBasSubTri numeric(18,4),
        @it_VlrSubTri numeric(18,4),
        @it_VlrBasSbtRes numeric(18,4),
        @it_VlrSbtRes numeric(18,4),

        @it_PerRedBasCalIcm numeric(18,4),
        @it_CodModBasCalIcm varchar(1),
        @it_CodModBasCalIcmSbt varchar(1),

        @it_CstPis varchar(2),
        @it_VlrBasPis numeric(18,4),
        @it_AlqPis numeric(18,4),
        @it_VlrPis numeric(18,4),
        @it_CstCof varchar(2),
        @it_VlrBasCof numeric(18,4),
        @it_AlqCof numeric(18,4),
        @it_VlrCof numeric(18,4),
        @it_VlrPisEst numeric(18,4),  -- estorno pis
        @it_VlrCofEst numeric(18,4),  -- estorno cofins

        @it_AlqIcmFcp numeric(18,4),
        @it_VlrIcmFcp numeric(18,4),          -- icms tributavel FCP: embutido em @PVlrIcm
        @it_AlqIcmSbtFcp numeric(18,4),
        @it_VlrSbtFcp numeric(18,4),
        @it_AlqIcmSbtFcpRet numeric(18,4),
        @it_VlrSubFcpRet numeric(18,4),

        @it_PrcVen numeric(18,4),
        @it_PrcUltEnt numeric(18,4),

        @it_VlrDscBonRat numeric(18,4),
        @it_VlrTotDspRat numeric(18,4),
        @it_VlrDspExt numeric(18,4),
        @it_VlrFrete numeric(18,4),
        @it_VlrSeguro numeric(18,4),
        @it_CodCfo smallint,
        @it_VlrComissao numeric(18,4),
        @it_VlrComTlmkt numeric(18,4),
        @it_VlrVerba numeric(18,4),
		@it_VlrVrbOpe numeric(18,4),
		@it_VlrVrbSup numeric(18,4),

        @pr_AlqIpi numeric(18,4),
        @pr_TipLisPis char(1),
        @pr_CodNcm varchar(8),
        @pr_CodGrpPrc varchar(1)

-- variaveis de trabalho
Declare @WCodCfoNor smallint,
        @WCodCfoSbt smallint,
        @WFlgOpeInt bit,
        @WFlgSbtEmbPrc bit,
        @WVlrBasPisCof numeric(18,4),
        @WObsNf varchar(200)

-- coloca campos de NFSCB na memoria
Declare @cb_CodOpe varchar(3),
        @cb_CodCfo smallint,
        @cb_Estado varchar(2),
        @cb_DatEmi datetime,
        @cl_CodRamAtv int,
		@rt_FlgConsumFin bit,
        @rt_FlgUsaCfoSbtSaiIntGenSim bit,
        @em_CodEst varchar(2),
        @em_CodTipLuc varchar(2),
		@em_FlgContriSubstituido bit,
        @pm_FlgIncIpiCalPis bit,
        @pm_FlgExcIcmCalPis bit

Select @em_CodEst = Des_Estado,
       @em_CodTipLuc = IsNull(Cod_TipLucro,''),
       @em_FlgContriSubstituido = IsNull(Flg_ContriSubstituido,0)
  From ESTAB
Where Cod_Estabe = @PCodEstabe  

Select @pm_FlgIncIpiCalPis = IsNull(FlgIncIpiCalPis,0),
       @pm_FlgExcIcmCalPis = IsNull(FlgExcIcmCalPis,0)
  From PARAM
Where Cod_Estabe = @PCodEstabe

-- indica se reduz aliq. PIS/COFINS
Set @cl_CodRamAtv = 0

Select @cb_CodOpe = cb.Cod_Ope,
       @cb_CodCfo = IsNull(cb.Cod_Cfo1,0),
       @cb_Estado = cb.Estado,
       @cb_DatEmi = cb.Dat_Emissao,
       @cl_CodRamAtv = IsNull(cl.Cod_RamoAtividade,0),
	   @rt_FlgConsumFin = IsNull(rt.Flg_ConsumFin,0),
       @rt_FlgUsaCfoSbtSaiIntGenSim = IsNull(rt.Flg_UsaCfoSbtSaiIntGenSim,0)
  from NFSCB cb Left Outer Join
       CLIEN cl on cb.Cod_Cliente = cl.Codigo Left Outer Join
       RGTRI rt on cb.Cod_RegTri = rt.Cod_RegTri
Where cb.Cod_Estabe = @PCodEstabe 
and cb.Ser_Nota = @PSerNot and cb.Num_Nota = @PNumNot

-- operacao interna ou externa
if @cb_Estado = @em_CodEst
  Set @WFlgOpeInt = 1
else
  Set @WFlgOpeInt = 0

-- colococa campos de TPOPE na memoria
Declare @to_CodCfoConFinInt smallint,
        @to_CodCfoConFinExt smallint,
	    @to_CodCfoNorInt smallint,
        @to_CodCfoNorExt smallint,
        @to_CodCfoSbtInt smallint,
        @to_CodCfoSbtExt smallint,
        @to_CodCfoSubstituidoInt smallint,
        @to_CodCfoSubstituidoExt smallint,
        @to_FlgCalIcmSbt bit,
        @to_FlgCalIcmNor bit,
        @to_FlgCalRepIcm bit,
        @to_FlgCalPisCof bit

Set @WCodCfoNor = 0
Set @WCodCfoSbt = 0
Set @to_FlgCalIcmSbt = 0
Set @to_FlgCalIcmNor = 0
Set @to_FlgCalRepIcm = 0
Set @to_FlgCalPisCof = 0

if Exists(Select Cod_Ope From TPOPE Where Cod_Ope = @cb_CodOpe)
  begin
    Select @to_CodCfoConFinInt = IsNull(Cod_CfoConFinInt,0),
	       @to_CodCfoConFinExt = IsNull(Cod_CfoConFinExt,0),
	       @to_CodCfoNorInt = Isnull(Cod_CfoNorInt,0),       
           @to_CodCfoNorExt = Isnull(Cod_CfoNorExt,0),
           @to_CodCfoSbtInt = Case 
                                When @em_FlgContriSubstituido = 1 and IsNull(Cod_CfoSbtIntSubstituido,0) > 0 then Cod_CfoSbtIntSubstituido
			                    Else Isnull(Cod_CfoSbtInt,0)
	 				          End, 
           @to_CodCfoSbtExt = Case 
	                            When @em_FlgContriSubstituido = 1 and IsNull(Cod_CfoSbtExtSubstituido,0) > 0 then Cod_CfoSbtExtSubstituido
					            Else Isnull(Cod_CfoSbtExt,0)
					          End,
           @to_CodCfoSubstituidoInt = IsNull(Cod_CfoSbtIntSubstituido,0),
           @to_CodCfoSubstituidoExt = IsNull(Cod_CfoSbtExtSubstituido,0),
           @to_FlgCalIcmSbt = case 
                                When @WFlgOpeInt = 1 then Isnull(Flg_CalIcmSbt,0)
                                else Isnull(Flg_CalIcmSbtExt,0)
                              end,
           @to_FlgCalIcmNor = case 
                                When @WFlgOpeInt = 1 then Isnull(Flg_CalIcmNor,0)
                                else Isnull(Flg_CalIcmNorExt,0)
                              end,
           @to_FlgCalRepIcm = case 
                                When @WFlgOpeInt = 1 then Isnull(Flg_CalRepIcmInt,0)
                                else Isnull(Flg_CalRepIcm,0)
                              end,
           @to_FlgCalPisCof = Isnull(Flg_CalPisCof,0)
      From TPOPE
      Where Cod_Ope = @cb_CodOpe

    if @rt_FlgConsumFin = 1
      if @WFlgOpeInt = 1
	    begin
          Set @WCodCfoNor = @to_CodCfoConFinInt
          Set @WCodCfoSbt = @to_CodCfoConFinInt
        end
      else
	    begin
          Set @WCodCfoNor = @to_CodCfoConFinExt
          Set @WCodCfoSbt = @to_CodCfoConFinExt
        end
    else
      if @WFlgOpeInt = 1
        begin
          Set @WCodCfoNor = @to_CodCfoNorInt
          Set @WCodCfoSbt = @to_CodCfoSbtInt
        end
      else
        begin
          Set @WCodCfoNor = @to_CodCfoNorExt
          Set @WCodCfoSbt = @to_CodCfoSbtExt
        end
  end

-- normaliza CFO
if (@WCodCfoNor = 0) or (@WCodCfoSbt= 0)
  EXEC PR_CfopEntSai @PCodEstabe, @cb_CodCfo, @WCodCfoNor output, @WCodCfoSbt output


Declare NFSIT_Cr Cursor Local Fast_Forward For 

  Select Cod_Produto, Cod_Lote, Num_SeqIte,
         Qtd_Produto, Qtd_Bonificacao, Prc_Unitario, Per_Desconto
    From NFSIT 
    Where Cod_Estabe = @PCodEstabe 
    and Ser_Nota = @PSerNot
    and Num_Nota = @PNumNot

Open NFSIT_Cr
Fetch Next From NFSIT_Cr Into @it_CodPrd, @it_CodLot, @it_NumSeqIte,
                              @it_QtdPed, @it_QtdBon, @it_PrcUni, @it_PerDscIte

While @@FETCH_STATUS = 0
  begin

    Select @pr_CodNcm = Substring(Ltrim(Rtrim(pr.Cod_ClaFis)),1,8),
           @pr_TipLisPis = pr.Tip_LisPis,
           @pr_AlqIpi = IsNull(pr.Per_Ipi,0),
           @pr_CodGrpPrc = ISNULL(pr.Cod_GrpPrc,'')
      From PRXES p 
           Inner Join PRODU pr on p.Cod_Produt = pr.Codigo
    Where p.Cod_Estabe = @PCodEstabe
    And p.Cod_Produt = @it_CodPrd

    if Exists(Select 1 From NFEIT 
              Where Cod_Estabe = @PCodEstabe and Protocolo = @NumPrt and 
                    Cod_Produto = @it_CodPrd and Cod_Lote = @it_CodLot)
      Select top 1 @it_TipLisPis    = Tip_LisPis,
                   @it_CodClaTri    = Cod_ClaTri,

                   @it_CodSt        = Case 
                                        When (IsNull(Ctrl_Tributacao,'') = '30') And (IsNull(Vlr_SubsTrib,0) > 0) then 
                                          Case When IsNull(Per_RedBasCalIcmCre,0) > 0 then '70' Else '10' End
                                        When IsNull(Vlr_DifTri,0) > 0 then
                                          Case When IsNull(Per_RedBasCalIcmCre,0) > 0 then '20' Else '00' End
                                        Else Ctrl_Tributacao 
                                      End,  
	               @it_CodCsosn     = Case 
				                        When (IsNull(Ctrl_Tributacao,'') = '30') And (Vlr_SubsTrib > 0) then '201'
                                        When IsNull(Vlr_DifTri,0) > 0 then '101' 
                                        Else Cod_CSOSN 
                                      End,   
                   @it_VlrBasIcmTri = Case When ((IsNull(Ctrl_Tributacao,'') = '30')  and (IsNull(Vlr_SubsTrib,0) > 0)) or (IsNull(Vlr_DifTri,0) > 0)
                                        then Round(IsNull(Vlr_BasIcmsNor,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),2) 
                                        Else Round(IsNull(Vlr_BasIcmsTrib,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),2) End,
                   @it_VlrIcmTri    = Case When ((IsNull(Ctrl_Tributacao,'') = '30')  and (IsNull(Vlr_SubsTrib,0) > 0)) or (IsNull(Vlr_DifTri,0) > 0)
                                        then Round(IsNull(Vlr_IcmsNor,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),2)    
                                        Else Round(IsNull(Vlr_IcmsTrib,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),2) End,

                   @it_PrcTabela    = IsNull(Prc_Venda,0),
                   @it_PrcFabric    = IsNull(Prc_Fabric,0),
                   @it_PrcMaxCon    = IsNull(Prc_MaxCon,0),
                   @it_PrcRefFpb    = IsNull(Prc_RefFpb,0),
                   --@it_PrcUltEnt    = IsNull(Prc_LiqUltEnt,0),
                   @it_VlrBasTri    = IsNull(Vlr_BasTri,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),
                   @it_AlqIcm       = Isnull(Alq_Icms,0),
                   @it_VlrBasIcmNor = Round(IsNull(Vlr_BasIcmsNor,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),2),
                   @it_VlrIcmNor    = IsNull(Vlr_IcmsNor,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),
                   @it_VlrBasRepIcm = Round(IsNull(Vlr_BasRepIcm,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),2),
                   @it_VlrRepIcm    = IsNull(Vlr_RepIcm,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),

                   @it_PerRedBasCalIcm = IsNull(Per_RedBasCalIcmCre,0),
                   @it_CodModBasCalIcm = IsNull(Cod_ModBasCalIcm,''),
                   @it_CodModBasCalIcmSbt = IsNull(Cod_ModBasCalIcmSbt,''),

                   @it_VlrPrdSubTri = Round(IsNull(Vlr_PrdSubTri,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),2),
                   @it_AlqIcmSbt    = Case When IsNull(Alq_IcmSbt,0) > 0 then IsNull(Alq_IcmSbt,0) Else IsNull(Alq_IcmDeb,0) End,   -- ?????
                   @it_AlqAgrSbt    = IsNull(Alq_AgrDeb,0),
                   @it_PerRedBasCalIcmSbt = IsNull(Per_RedBasCalIcmSbt,0),  

                   @it_VlrBasSubTri = Round(IsNull(Vlr_BasSubsTrib,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),2),
                   @it_VlrSubTri    = IsNull(Vlr_SubsTrib,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),
                   @it_VlrBasSbtRes = Round(IsNull(Vlr_BasSbtRes,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),2),
                   @it_VlrSbtRes    = IsNull(Vlr_SbtRes,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),

                   @it_VlrIseIcm    = Round(IsNull(Vlr_Isento,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),2),
                   @it_VlrOutIcm    = Round(IsNull(Vlr_Outros,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),2),

                   @it_PerIcmDiferi = IsNull(Per_IcmDiferi,0),
                   @it_VlrIcmDiferi = Round(IsNull(Vlr_IcmDiferi,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),2),

                   @it_VlrBasIpi    = Round(IsNull(Vlr_BasIpi,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),2),
                   @it_VlrIpi       = IsNull(Vlr_Ipi,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),

                   @it_VlrPisEst    = IsNull(Vlr_Pis,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)), 
                   @it_VlrCofEst    = IsNull(Vlr_Cofins,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)), 

                   @it_AlqIcmFcp    = IsNull(Alq_FcpIcm,0),
                   @it_VlrIcmFcp    = IsNull(Vlr_FcpIcm,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),
                   @it_AlqIcmSbtFcp = IsNull(Alq_FcpSbt,0),
                   @it_VlrSbtFcp    = IsNull(Vlr_FcpSbt,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),
                   @it_AlqIcmSbtFcpRet = IsNull(Alq_FcpSbtRet,0),
                   @it_VlrSubFcpRet = IsNull(Vlr_FcpSbtRet,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),

                   @it_VlrDscRat    = IsNull(Vlr_DescRateado,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),
                   @it_VlrDscTri    = IsNull(Vlr_DscTri,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),
                   @it_VlrDscBonRat = 0,

                   @it_VlrTotDspRat = (IsNull(Vlr_DespRateada,0)+Isnull(Vlr_Frete,0)+IsNull(Vlr_Seguro,0))*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),
                   @it_VlrDspRat    = IsNull(Vlr_DespRateada,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),
                   @it_VlrFrete     = Isnull(Vlr_Frete,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),
                   @it_VlrSeguro    = Isnull(Vlr_Seguro,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),
                   @it_VlrDspExt    = Isnull(Vlr_DspExt,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),

                   @it_VlrComissao  = IsNull(Vlr_Comissao,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),
                   @it_VlrComTlmkt  = IsNull(Vlr_ComTlmkt,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),
                   @it_VlrVerba     = IsNull(Vlr_Verba,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),
                   @it_VlrVrbOpe    = IsNull(Vlr_VrbOpe,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),
                   @it_VlrVrbSup    = IsNull(Vlr_VrbSup,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao))
From NFEIT 
      Where Cod_Estabe = @PCodEstabe and Protocolo = @NumPrt and 
            Cod_Produto = @it_CodPrd and Cod_Lote = @it_CodLot
    else
      if Exists(Select 1 From NFEIT 
                Where Cod_Estabe = @PCodEstabe and Protocolo = @NumPrt and 
                      Cod_Produto = @it_CodPrd)
        Select top 1 @it_TipLisPis = Tip_LisPis,
                   @it_CodClaTri    = Cod_ClaTri,

                   @it_CodSt        = Case 
                                        When (IsNull(Ctrl_Tributacao,'') = '30') And (IsNull(Vlr_SubsTrib,0) > 0) then 
                                          Case When IsNull(Per_RedBasCalIcmCre,0) > 0 then '70' Else '10' End
                                        When IsNull(Vlr_DifTri,0) > 0 then
                                          Case When IsNull(Per_RedBasCalIcmCre,0) > 0 then '20' Else '00' End
                                        Else Ctrl_Tributacao 
                                      End,  
	               @it_CodCsosn     = Case 
				                        When (IsNull(Ctrl_Tributacao,'') = '30') And (Vlr_SubsTrib > 0) then '201'
                                        When IsNull(Vlr_DifTri,0) > 0 then '101' 
                                        Else Cod_CSOSN 
                                      End,   
                   @it_VlrBasIcmTri = Case When ((IsNull(Ctrl_Tributacao,'') = '30')  and (IsNull(Vlr_SubsTrib,0) > 0)) or (IsNull(Vlr_DifTri,0) > 0)
                                        then Round(IsNull(Vlr_BasIcmsNor,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),2) 
                                        Else Round(IsNull(Vlr_BasIcmsTrib,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),2) End,
                   @it_VlrIcmTri    = Case When ((IsNull(Ctrl_Tributacao,'') = '30')  and (IsNull(Vlr_SubsTrib,0) > 0)) or (IsNull(Vlr_DifTri,0) > 0)
                                        then Round(IsNull(Vlr_IcmsNor,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),2)    
                                        Else Round(IsNull(Vlr_IcmsTrib,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),2) End,

                   @it_PrcTabela    = IsNull(Prc_Venda,0),
                   @it_PrcFabric    = IsNull(Prc_Fabric,0),
                   @it_PrcMaxCon    = IsNull(Prc_MaxCon,0),
                   @it_PrcRefFpb    = IsNull(Prc_RefFpb,0),
                   --@it_PrcUltEnt    = IsNull(Prc_LiqUltEnt,0),
                   @it_VlrBasTri    = IsNull(Vlr_BasTri,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),
                   @it_AlqIcm       = Isnull(Alq_Icms,0),
                   @it_VlrBasIcmNor = Round(IsNull(Vlr_BasIcmsNor,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),2),
                   @it_VlrIcmNor    = IsNull(Vlr_IcmsNor,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),
                   @it_VlrBasRepIcm = Round(IsNull(Vlr_BasRepIcm,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),2),
                   @it_VlrRepIcm    = IsNull(Vlr_RepIcm,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),

                   @it_PerRedBasCalIcm = IsNull(Per_RedBasCalIcmCre,0),
                   @it_CodModBasCalIcm = IsNull(Cod_ModBasCalIcm,''),
                   @it_CodModBasCalIcmSbt = IsNull(Cod_ModBasCalIcmSbt,''),

                   @it_VlrPrdSubTri = Round(IsNull(Vlr_PrdSubTri,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),2),
                   @it_AlqIcmSbt    = Case When IsNull(Alq_IcmSbt,0) > 0 then IsNull(Alq_IcmSbt,0) Else IsNull(Alq_IcmDeb,0) End,   -- ?????
                   @it_AlqAgrSbt    = IsNull(Alq_AgrDeb,0),

                   @it_PerRedBasCalIcmSbt = IsNull(Per_RedBasCalIcmSbt,0),  
                   @it_VlrBasSubTri = Round(IsNull(Vlr_BasSubsTrib,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),2),
                   @it_VlrSubTri    = IsNull(Vlr_SubsTrib,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),
                   @it_VlrBasSbtRes = Round(IsNull(Vlr_BasSbtRes,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),2),
                   @it_VlrSbtRes    = IsNull(Vlr_SbtRes,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),

                   @it_VlrIseIcm    = Round(IsNull(Vlr_Isento,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),2),
                   @it_VlrOutIcm    = Round(IsNull(Vlr_Outros,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),2),

                   @it_PerIcmDiferi = IsNull(Per_IcmDiferi,0),
                   @it_VlrIcmDiferi = Round(IsNull(Vlr_IcmDiferi,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),2),

                   @it_VlrBasIpi    = Round(IsNull(Vlr_BasIpi,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),2),
                   @it_VlrIpi       = IsNull(Vlr_Ipi,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),

                   @it_VlrPisEst    = IsNull(Vlr_Pis,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)), 
                   @it_VlrCofEst    = IsNull(Vlr_Cofins,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)), 

                   @it_AlqIcmFcp    = IsNull(Alq_FcpIcm,0),
                   @it_VlrIcmFcp    = IsNull(Vlr_FcpIcm,0),
                   @it_AlqIcmSbtFcp = IsNull(Alq_FcpSbt,0),
                   @it_VlrSbtFcp    = IsNull(Vlr_FcpSbt,0),
                   @it_AlqIcmSbtFcpRet = IsNull(Alq_FcpSbtRet,0),
                   @it_VlrSubFcpRet = IsNull(Vlr_FcpSbtRet,0),

                   @it_VlrDscRat    = IsNull(Vlr_DescRateado,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),
                   @it_VlrDscTri    = IsNull(Vlr_DscTri,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),
                   @it_VlrDscBonRat = 0,

                   @it_VlrTotDspRat = (IsNull(Vlr_DespRateada,0)+Isnull(Vlr_Frete,0)+IsNull(Vlr_Seguro,0))*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),
                   @it_VlrDspRat    = IsNull(Vlr_DespRateada,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),
                   @it_VlrFrete     = Isnull(Vlr_Frete,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),
                   @it_VlrSeguro    = Isnull(Vlr_Seguro,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),

                   @it_VlrComissao  = IsNull(Vlr_Comissao,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),
                   @it_VlrComTlmkt  = IsNull(Vlr_ComTlmkt,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),
                   @it_VlrVerba     = IsNull(Vlr_Verba,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),
                   @it_VlrVrbOpe    = IsNull(Vlr_VrbOpe,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao)),
                   @it_VlrVrbSup    = IsNull(Vlr_VrbSup,0)*((@it_QtdPed+@it_QtdBon)*1.0/(Qtd_Pedido+Qtd_Bonificacao))
        From NFEIT 
        Where Cod_Estabe = @PCodEstabe And Protocolo = @NumPrt and Cod_Produto = @it_CodPrd


    -- define CFOP do item conforme CST
    if Charindex(@it_CodSt,';10;30;60;70;90;') > 0 
      Set @it_CodCfo = @WCodCfoSbt
    else
      Set @it_CodCfo = @WCodCfoNor

	-- verifica CFOP de genericos e similares em op.internas: alterado verifica CFOP para operações com debito presumido
--    if (@WFlgOpeInt = 1) and (@rt_FlgUsaCfoSbtSaiIntGenSim = 1) and
--       (CHARINDEX(@pr_CodGrpPrc,';G;S;') > 0) and (@it_CodCfo = @WCodCfoNor)
--      Set @it_CodCfo = @WCodCfoSbt   
    if (@rt_FlgUsaCfoSbtSaiIntGenSim = 1) and
       (@it_FlgUsaDebPresum = 1) and (@it_AlqDebPresum > 0) and (@it_AlqDebPresum <> @it_AlqIcm)
      Set @it_CodCfo = @WCodCfoSbt   

    if (@rt_FlgConsumFin = 0) and (@it_CodSt = '60')
      if @WFlgOpeInt = 1
        begin
          if (@it_CodCfo <> @to_CodCfoSubstituidoInt) and (@to_CodCfoSubstituidoInt > 0)
            Set @it_CodCfo = @to_CodCfoSubstituidoInt
        end
    else
      if @WFlgOpeInt = 0
        begin
          if (@it_CodCfo <> @to_CodCfoSubstituidoExt) and (@to_CodCfoSubstituidoExt > 0)
            Set @it_CodCfo = @to_CodCfoSubstituidoExt
        end


    -- PIS/COFINS
    Set @WFlgSbtEmbPrc = 0

    Set @WVlrBasPisCof = @it_VlrBasTri

    -- ressarcimento
    if (@it_VlrSbtRes > 0) and (@WFlgSbtEmbPrc = 0)
      Set @WVlrBasPisCof = Round(@it_VlrBasTri+@it_VlrSbtRes,2)

    -- ipi
    if @pm_FlgIncIpiCalPis = 1  
      Set @WVlrBasPisCof = @WVlrBasPisCof + @it_VlrIpi

    -- exclui icms próprio, se for devolução de compra
    if @pm_FlgExcIcmCalPis = 1
      Set @WVlrBasPisCof = @WVlrBasPisCof - @it_VlrIcmNor

    Exec PR_CalculaPisCofins @PCodEstabe, @to_FlgCalPisCof, 'S', @em_CodTipLuc, @cb_DatEmi, @cb_CodCfo, @cl_CodRamAtv, @pr_CodNcm, @pr_TipLisPis, @WVlrBasPisCof, 
                             @it_CstPis output, @it_VlrBasPis output, @it_AlqPis output, @it_VlrPis output,
                             @it_CstCof output, @it_VlrBasCof output, @it_AlqCof output, @it_VlrCof output, @WObsNf output
 

    -- grava valores em NFSIT
    Update NFSIT
      Set Cod_ClaTri          = @it_CodClaTri,
          Tip_Aux             = @pr_TipLisPis,
          --Per_IpiCad          = @pr_AlqIpi,
          Cod_Ncm             = @pr_CodNcm,
          --Dat_RefPrdCip = @PDatRefPrdCip,
          Prc_Tabela          = @it_PrcTabela,
          Prc_Fabric          = @it_PrcFabric,
          Prc_MaxCon          = @it_PrcMaxCon,
          Prc_RefFpb          = @it_PrcRefFpb,

          Cod_Cfo             = @it_CodCfo,
          Vlr_BasTri          = @it_VlrBasTri,
          Ctrl_Tributacao     = @it_CodSt,
          Cod_CSOSN           = @it_CodCsosn,
          --Tip_PrcBasDebSbt = @PTipPrcBasDebSbt,  
          --Tip_PrcBasCreSbt = @PTipPrcBasCreSbt,

          Alq_Icms            = @it_AlqIcm,
          Vlr_BasIcmsNor      = @it_VlrBasIcmNor,
          Vlr_IcmsNor         = @it_VlrIcmNor,

          Flg_UsaDebPresum    = @it_FlgUsaDebPresum,
          Alq_IcmPresum       = @it_AlqDebPresum,

          Vlr_PrdSubTri       = @it_VlrPrdSubTri,
          Vlr_BasSubsTrib     = @it_VlrBasSubTri,
          Vlr_SubsTrib        = @it_VlrSubTri,
          Vlr_BasSbtRes       = @it_VlrBasSbtRes,
          Vlr_SbtRes          = @it_VlrSbtRes,

          Vlr_BasRecSbt       = 0,
          Vlr_RecSbt          = 0,

          Vlr_BasIcmsTri      = @it_VlrBasIcmTri,
          Vlr_IcmsTri         = @it_VlrIcmTri,
          Vlr_Isento          = @it_VlrIseIcm,
          Vlr_Outros          = @it_VlrOutIcm,

          Per_IcmDiferi       = @it_PerIcmDiferi,
          Vlr_IcmDiferi       = @it_VlrIcmDiferi,

          --Flg_UsaCreIcmSbt = @PFlgUsaCreIcmSbt,
          --Per_RedBasCalIcmDeb = @PPerRedBasCalIcmDeb,

          Alq_AgrSbt          = @it_AlqAgrSbt,
          Per_RedBasCalIcmSbt = @it_PerRedBasCalIcmSbt,
          Alq_IcmSbt          = @it_AlqIcmSbt,

          --Vlr_DebIcm = @PVlrDebIcm,
          Per_RedBasCalIcm     = @it_PerRedBasCalIcm,
          --Per_LimBasCalCreSbt = @PPerLimBasCalCreSbt,
          --Vlr_LimCreIcm = @PVlrLimCreIcm,
	      --Vlr_DspCusEnt = @PVlrDspSubCusCreIcm,

          Cod_ModBasCalIcm    = @it_CodModBasCalIcm,
          Cod_ModBasCalIcmSbt = @it_CodModBasCalIcmSbt,
          --CST_Ipi = @PCstIpi,

          CST_Pis             = @it_CstPis,
          Vlr_BasPis          = @it_VlrBasPis,
          Alq_Pis             = @it_AlqPis,
          Vlr_Pis             = @it_VlrPis,

          Vlr_DscCalSuframa   = 0, 
          Vlr_DspExt          = @it_VlrDspExt,

          CST_Cofins          = @it_CstCof,
          Vlr_BasCofins       = @it_VlrBasCof,
          Alq_Cofins          = @it_AlqCof,
          Vlr_Cofins          = @it_VlrCof,

          Vlr_PisEstDev       = @it_VlrPisEst,
          Vlr_CofEstDev       = @it_VlrCofEst,

          Alq_FcpIcm          = @it_AlqIcmFcp, 
          Vlr_FcpIcm          = @it_VlrIcmFcp, 
          Alq_FcpSbt          = @it_AlqIcmSbtFcp, 
          Vlr_FcpSbt          = @it_VlrSbtFcp, 
          Alq_FcpSbtRet       = @it_AlqIcmSbtFcpRet, 
          Vlr_FcpSbtRet       = @it_VlrSubFcpRet,

          Alq_FcpSbtRec       = 0, 
          Vlr_FcpSbtRec       = 0,
          --Alq_FcpSbtAnt       = 0, 
          --Vlr_FcpSbtAnt       = 0,

          Vlr_BasIpi          = @it_VlrBasIpi,
		  Vlr_Ipi             = @it_VlrIpi,
		  Vlr_Frete           = @it_VlrFrete,
		  Vlr_Seguro          = @it_VlrSeguro,
		  Vlr_DespRateada     = @it_VlrDspRat,
		  Vlr_DescRateado     = @it_VlrDscRat + @it_VlrRepIcm + @it_VlrDscBonRat,
		  Vlr_DscTri          = @it_VlrDscTri,
          Vlr_Comissao        = @it_VlrComissao,
          Vlr_ComTlmkt        = @it_VlrComTlmkt,
          Vlr_Verba           = @it_VlrVerba,
          Vlr_VrbOpe          = @it_VlrVrbOpe,
          Vlr_VrbSup          = @it_VlrVrbSup

    Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot 
    And Cod_Produto = @it_CodPrd and Cod_Lote = @it_CodLot and Num_SeqIte = @it_NumSeqIte

    -- calc fields
    Update NFSIT
      Set Vlr_LiqItem = IsNull(Vlr_TotItem,0) - IsNull(Vlr_RepIcms,0) - Isnull(Vlr_DescRateado,0) - IsNull(Vlr_DscBonRat,0) - IsNull(Vlr_DscTri,0) 
	                  + IsNull(Vlr_SubsTrib,0) + IsNull(Vlr_SbtRes,0) + + IsNull(Vlr_RecSbt,0) + IsNull(Vlr_Ipi,0) + Isnull(Vlr_DespRateada,0) + Isnull(Vlr_DspExt,0),
          Vlr_LiqVenIte = IsNull(Vlr_TotItem,0) - IsNull(Vlr_RepIcms,0) - Isnull(Vlr_DescRateado,0) - IsNull(Vlr_DscBonRat,0) - IsNull(Vlr_DscTri,0),
          Prc_UniImpFat = Prc_Unitario * Fat_CnvImpFat
    Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot 
    And Cod_Produto = @it_CodPrd and Cod_Lote = @it_CodLot and Num_SeqIte = @it_NumSeqIte

    Fetch Next From NFSIT_Cr Into @it_CodPrd, @it_CodLot, @it_NumSeqIte,
                                  @it_QtdPed, @it_QtdBon, @it_PrcUni, @it_PerDscIte
  end

Close NFSIT_Cr
Deallocate NFSIT_Cr

-- atualiza cabeçalho
Exec PR_NormalizaValoresNFS @PCodEstabe, @PSerNot, @PNumNot

COMMIT TRANSACTION
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_DesdobraPDV]
@TipDesdob varchar(1),  -- 'I'-Incetivo fiscal, 'G'-genericos/similares, 'L'-produto com mais de 1 lote, 'B'-bonificados
@CodEstabe int,
@CodPed int,
@CodPdvGer Int Output

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Date smalldatetime
Set @Date = cast(cast(GetDate() as date) as smalldatetime)

Declare @WQtdIteRef int,
        @WQtdIteOut int,
		@WFlgIncIte bit,
		@WCodPrdAnt int,
        @WIdIncFis smallint,
        @nw_TipFat varchar(3),
        @cb_FlgCriIteFec bit,
        @cb_NumPdvLig  int

Set @CodPdvGer = 0

Set @WIdIncFis = 0
Set @WQtdIteRef = 0
Set @WQtdIteOut = 0
Set @nw_TipFat = '?'
Set @cb_FlgCriIteFec = 1   -- ajusta Flg_CriIteFec = 1 para nao forçar recalculo de tributos do novo pedido
Set @cb_NumPdvLig = 0

if (IsNull(@TipDesdob,'') <> 'L') and
   (IsNull(@TipDesdob,'') <> 'G') and
   (IsNull(@TipDesdob,'') <> 'B')
  Set @TipDesdob = 'I'

if (@TipDesdob = 'L')
  begin
    Set @WQtdIteRef = IsNull((Select count (*) 
                                From (Select Cod_Estabe, Cod_Pedido, Cod_Produto, QtdLot=count(*)
                                        From PDVIT
                                       Where Cod_Estabe = @CodEstabe
                                         And Cod_Pedido = @CodPed
                                         And Qtd_Pedido > 0
                                       Group by Cod_Estabe, Cod_Pedido, Cod_Produto
                                      Having count(*) > 1) x),0)
  end

if (@TipDesdob = 'B') and
   ((Select IsNull(Flg_GerPdvBon,0) From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @CodPed) = 1) and
   ((Select IsNull(Num_PdvLig,0) From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @CodPed) = 0) and
   ((Select Substring(Cod_OrigemPdv,1,1) From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @CodPed) <> 'D') and
   ((Select tp.Tip_Ope 
         From TPOPE tp 
              Inner Join PDVCB pv on (pv.Tip_Faturamento = tp.Cod_Ope) 
         Where pv.Cod_Estabe = @CodEstabe And pv.Numero = @CodPed) = 'V') 
  begin
    Set @cb_NumPdvLig    = @CodPed
    Set @cb_FlgCriIteFec = 0  -- tem que recalcular tributos
    Set @nw_TipFat = (Select IsNull(CodTpvBon,'') From PARAM Where Cod_Estabe = @CodEstabe)

    -- calcula qtd itens bonificados
    Set @WQtdIteRef = (Select count(*) 
                         From PDVIT it 
                              Inner Join PRODU pr on it.Cod_Produto = pr.Codigo
                        Where it.Cod_Estabe = @CodEstabe
                          And it.Cod_Pedido = @CodPed
                          And it.Qtd_Bonificacao > 0)
  end

if (@TipDesdob = 'G') and
   ((Select IsNull(Flg_DesdobGenericos,0) From ESTAB Where Cod_Estabe = @CodEstabe) = 1)
  begin
    -- calcula qtd itens genericos/similares
    Set @WQtdIteRef = IsNull((Select count(*) 
                                From PDVIT it 
                                     Inner Join PRODU pr on it.Cod_Produto = pr.Codigo
                               Where it.Cod_Estabe = @CodEstabe
                                 And it.Cod_Pedido = @CodPed
                                 And it.Qtd_Pedido > 0
                                 And ((pr.Cod_GrpPrc = 'G') or (pr.Cod_GrpPrc = 'S'))),0)
                   
    -- calcula qtd itens não genericos/similares
    Set @WQtdIteOut = IsNull((Select count(*) 
                                From PDVIT it 
                                     Inner Join PRODU pr on it.Cod_Produto = pr.Codigo
                               Where it.Cod_Estabe = @CodEstabe
                                 And it.Cod_Pedido = @CodPed
                                 And it.Qtd_Pedido > 0
                                 And ((pr.Cod_GrpPrc <> 'G') and (pr.Cod_GrpPrc <> 'S'))),0)
  end

if (@TipDesdob = 'I')
  begin
    -- determina o incentivo fiscal (com mais itens)
    Set @WIdIncFis = IsNull((Select top 1 v.Id_IncFis
                               From PDVIT it 
                                    Inner Join V_PrdIncFis v on it.Cod_Estabe = v.Cod_Estabe and it.Cod_Produto = v.Cod_Produt
                                    Inner Join ESXIF x on it.Cod_Estabe = x.Cod_Estabe and v.Id_IncFis = x.Id_IncFis
                              Where it.Cod_Estabe = @CodEstabe
                                And it.Cod_Pedido = @CodPed
                                And it.Qtd_Pedido > 0
                                And IsNull(x.Flg_PdvEsp,0) = 1
                              Group by v.Id_IncFis
                              Order by count(*) desc),0)

   -- calcula qtd itens incentivados
   Set @WQtdIteRef = IsNull((Select count(*) 
                               From PDVIT it 
                                    Inner Join PRODU pr on it.Cod_Produto = pr.Codigo
                              Where it.Cod_Estabe = @CodEstabe
                                And it.Cod_Pedido = @CodPed
                                And it.Qtd_Pedido > 0
                                And dbo.FN_ProdutoIncentivado(it.Cod_Estabe,it.Cod_Produto,@WIdIncFis) = 1),0)
                  
   -- calcula qtd itens não incentivados
   Set @WQtdIteOut = IsNull((Select count(*) 
                               From PDVIT it Inner Join PRODU pr on it.Cod_Produto = pr.Codigo
                              Where it.Cod_Estabe = @CodEstabe
                                And it.Cod_Pedido = @CodPed
                                And it.Qtd_Pedido > 0
                                And dbo.FN_ProdutoIncentivado(it.Cod_Estabe,it.Cod_Produto,@WIdIncFis) = 0),0)
  
   -- pedido possui somente produtos incentivados
   if @WQtdIteRef > 0 and @WQtdIteOut = 0
     begin
       Update PDVCB
          Set Id_IncFis = @WIdIncFis
        Where Cod_Estabe = @CodEstabe
          And Numero = @CodPed
          And IsNull(Id_IncFis,0) = 0
     end

  end

/*
if (Select Status1 From PDVCB Where Cod_Estabe = @CodEstabe And Numero  = @CodPed) <> 'P'
  RAISERROR('Pedido não está pendente',16,1)
else
if (@TipDesdob = 'L') and (Select Status2 From PDVCB Where Cod_Estabe = @CodEstabe And Numero  = @CodPed) <> 'F'
  RAISERROR('Pedido não está fechado',16,1)
else
if (@TipDesdob = 'I') and (Select Status2 From PDVCB Where Cod_Estabe = @CodEstabe And Numero  = @CodPed) <> 'A'
  RAISERROR('Pedido não está aberto',16,1)
else
if (@TipDesdob = 'G') and (Select Status2 From PDVCB Where Cod_Estabe = @CodEstabe And Numero  = @CodPed) <> 'A'
  RAISERROR('Pedido não está aberto',16,1)
else
if (@TipDesdob = 'B') and (Select Status2 From PDVCB Where Cod_Estabe = @CodEstabe And Numero  = @CodPed) <> 'A'
  RAISERROR('Pedido não está aberto',16,1)
else

if (@TipDesdob = 'B') and (@WQtdIteRef > 0) and
   ((Select IsNull(Flg_GerPdvBon,0) From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @CodPed) = 1) and 
   (not Exists(Select 1 From TPOPE Where Cod_Ope = @nw_TipFat))  
  RAISERROR('Tipo de Operação parametrizado p/ Bonificação inválido',16,1)
else
*/

if ( (Select Status1 From PDVCB Where Cod_Estabe = @CodEstabe And Numero  = @CodPed) = 'P' ) and
   ( ( (@TipDesdob = 'L') and ((Select Status2 From PDVCB Where Cod_Estabe = @CodEstabe And Numero  = @CodPed) = 'F') ) or
     ( (@TipDesdob = 'I') and ((Select Status2 From PDVCB Where Cod_Estabe = @CodEstabe And Numero  = @CodPed) = 'A') ) or
     ( (@TipDesdob = 'G') and ((Select Status2 From PDVCB Where Cod_Estabe = @CodEstabe And Numero  = @CodPed) = 'A') ) or
     ( (@TipDesdob = 'B') and 
       ((Select Status2 From PDVCB Where Cod_Estabe = @CodEstabe And Numero  = @CodPed) = 'A') and
       ((Select IsNull(Flg_GerPdvBon,0) From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @CodPed) = 1) and
       (Exists(Select 1 From TPOPE Where Cod_Ope = @nw_TipFat)) )
   )

  if ( (@TipDesdob = 'L') and (@WQtdIteRef > 0) ) or
     ( (@TipDesdob = 'I') and (@WQtdIteRef > 0) and (@WQtdIteOut > 0) ) or
     ( (@TipDesdob = 'G') and (@WQtdIteRef > 0) and (@WQtdIteOut > 0) ) or
     ( (@TipDesdob = 'B') and (@WQtdIteRef > 0) ) 
    begin
      Begin Transaction
      -- bloqueia registro
      Update PDVCB
         Set Qtd_Itens = Qtd_Itens + 0
       Where Cod_Estabe = @CodEstabe 
         And Numero = @CodPed
  
      --variaveis p/ campos de PDVIT
      Declare @it_CodPrd int,
              @it_CodLot varchar(20),
              @it_TipSai varchar(1),
              @it_QtdPed int,
              @it_QtdBon int,
              @it_QtdPra int,
              @it_QtdDep int,
              @nw_QtdPra int,
              @nw_QtdDep int
  
      --coloca campos de PDVCB na memoria
      Declare @cb_BlqAnt varchar(2),
              @cb_CodOriPdv varchar(2)
  
      -- Variável auxiliar . . . 
      Declare @Pde_Cod_Layout int,
              @Pde_Num_Cnpj varchar(14),   
              @Pde_Cod_PedCli varchar(20),
              @Pde_Num_Desdob smallint,
              @Pde_Num_DesdobDes smallint,
              @Pdeit_Num_Desdob smallint,
              @Pdeit_Cod_PrdCli varchar(14)
  
      Select @cb_BlqAnt = Bloqueio,
             @cb_CodOriPdv = Cod_OrigemPdv
        From PDVCB 
       Where Cod_Estabe = @CodEstabe 
         And Numero = @CodPed
  
      -- cria novo pedido
      EXEC PR_ProxNumero 'Pedido_Venda', @CodPdvGer output
      
      -- cria cabecalho novo pedido com Tipo do bloqueio = 'SR' para nao decrementar saldo e em modo de calculo
      Insert into PDVCB (Cod_Estabe, Numero)
        Values (@CodEstabe, @CodPdvGer)
      if @@error <> 0
        begin
          if @@trancount > 0
            Rollback Transaction
          Return
        end
  
      Update d
         Set d.Status1            = 'P',
             d.Status2            = 'A',
             d.Flg_JaFechado      = 0,
             d.Qtd_ImpPnt         = 0,
             d.Dat_Pedido         = @Date,
             d.Hor_Entrada        = GetDate(),
             d.Bloqueio           = 'SR',
             d.Flg_Calc           = 1,
             d.Flg_CriIteFec      = @cb_FlgCriIteFec,
  
             d.Num_PdvPai         = @CodPed,
             d.Num_PdvLig         = @cb_NumPdvLig,
             d.Id_IncFis          = @WIdIncFis,
             d.Tip_Pedido         = o.Tip_Pedido,
             d.Cod_OrigemPdv      = o.Cod_OrigemPdv,
             d.Tip_Faturamento    = Case 
                                      When @TipDesdob = 'B' Then @nw_TipFat 
                                      Else o.Tip_Faturamento 
                                    End,
             d.Flg_ComisNormal    = IsNull(o.Flg_ComisNormal,0),
             d.Flg_TabProgres     = IsNull(o.Flg_TabProgres,0),
             d.Flg_Credito        = IsNull(o.Flg_Credito,0),
             d.Flg_WMS            = IsNull(o.Flg_WMS,0),
             d.Flg_CalCom         = IsNull(o.Flg_CalCom,0),
             d.Flg_GerPdvBon      = IsNull(o.Flg_GerPdvBon,0),
             d.Flg_GerRetBon      = IsNull(o.Flg_GerRetBon,0),
             d.Cod_Cliente        = o.Cod_Cliente,
             d.Cod_RegTri         = o.Cod_RegTri,
             d.Cod_Agente         = o.Cod_Agente,
             d.Cod_Transportadora = o.Cod_Transportadora,
             d.Cod_Rota           = o.Cod_Rota,
             d.Des_LayoutPalm     = o.Des_LayoutPalm,
             d.Des_LayoutPde      = o.Des_LayoutPde,
             d.Cod_Vendedor       = o.Cod_Vendedor,
             d.Cod_VendTlmkt      = o.Cod_VendTlmkt,
             d.Cod_Digitador      = o.Cod_Digitador,
             d.Cod_Gerencia       = o.Cod_Gerencia,
             d.Cod_Supervisor     = o.Cod_Supervisor,
             d.Cod_GerOpe         = o.Cod_GerOpe,
             d.Cod_SupOpe         = o.Cod_SupOpe,
             d.Tip_Vencimento     = o.Tip_Vencimento,
             d.Qtd_PrzMed         = o.Qtd_PrzMed,
             d.Qtd_Parcela        = o.Qtd_Parcela,
             d.Qtd_Intervalo      = o.Qtd_Intervalo,
             d.Tip_DscPdv         = o.Tip_DscPdv,
             d.Num_Lote           = o.Num_Lote,
             d.Per_DescontoCom    = IsNull(o.Per_DescontoCom,0),
             d.Per_DescontoFin    = IsNull(o.Per_DescontoFin,0),
             d.Observacao         = o.Observacao,
             d.Msg_Bloqueio       = o.Msg_Bloqueio, 
             d.Obs_NotFis         = o.Obs_NotFis,  
             d.Tip_Consumidor     = o.Tip_Consumidor,
             d.Cod_PedRem         = o.Cod_PedRem,
             d.Cod_PedCli         = o.Cod_PedCli,
             d.Cod_Prz            = o.Cod_Prz,
             d.Cod_TabPrc         = o.Cod_TabPrc,
             d.Cod_PolCom         = o.Cod_PolCom,
             d.Id_PolCom          = o.Id_PolCom,
             d.Flg_MarkupCusCom   = IsNull(o.Flg_MarkupCusCom,0),
             d.Tip_SaiPdv         = o.Tip_SaiPdv,
             d.Tip_RatBon         = IsNull(o.Tip_RatBon,''),
             d.Tip_GerVrb         = o.Tip_GerVrb,
             d.Tip_Frete          = o.Tip_Frete,
             d.Cod_PedCmpCli      = o.Cod_PedCmpCli,
                                        
             d.Usuario            = o.Usuario,
             d.Transacao          = GetDate()
        From PDVCB d, PDVCB o
       Where d.Cod_Estabe = @CodEstabe
         And d.Numero = @CodPdvGer
         And o.Cod_Estabe = @CodEstabe 
         And o.Numero = @CodPed
  
      if (@TipDesdob = 'L')  -- Exists PDVLT
        begin
  	    Delete From PDVLT
           Where Cod_Estabe = @CodEstabe 
             and Cod_Pedido = @CodPdvGer
        end
  
      -- Variáveis para verificar se o pedido origem foi lido à partir de um pedido eletrônico (PDECB)
      Set @Pde_Num_Cnpj = ''
      Set @Pde_Cod_PedCli = ''
      Set @Pde_Num_Desdob = 0
  
      -- Se no pedido origem existir registro em PDECB, gravar um novo registro para o novo pedido gerado...
      -- Isso faz com que o retorno do arquivo de nota seja gerado no DMDPe. 
      if Exists(Select Num_Cnpj From PDECB Where Cod_Estabe = @CodEstabe And Num_PedVen = @CodPed)
        begin
          Select top 1
                 @Pde_Cod_Layout = Cod_Layout, 
                 @Pde_Num_Cnpj = RTRIM(Num_Cnpj),   
                 @Pde_Cod_PedCli = RTRIM(Cod_PedCli),
                 @Pde_Num_Desdob = Num_Desdob
            From PDECB
           Where Cod_Estabe = @CodEstabe 
             And Num_PedVen = @CodPed
  
          Set @Pde_Num_DesdobDes = Isnull((Select MAX(Num_Desdob) From PDECB Where Cod_Estabe = @CodEstabe And Cod_Layout = @Pde_Cod_Layout And Num_Cnpj = @Pde_Num_Cnpj And Cod_PedCli = @Pde_Cod_PedCli),0) + 1
    
          Exec _CopiaPDECB @CodEstabe, @Pde_Cod_Layout, @Pde_Num_Cnpj, @Pde_Cod_PedCli, @Pde_Num_Desdob, @Pde_Num_DesdobDes, @CodPdvGer
          if @@error <> 0
            begin
              if @@trancount > 0
                Rollback Transaction
              Return
            end
        end
        
      -- muda o bloqueio temporariamente para nao decrementar saldos
      Update PDVCB
         Set Bloqueio = 'SR',
             Flg_Calc = 1
  		   -- Flg_CriIteFec = 0    p/ bonificação
       Where Cod_Estabe = @CodEstabe     
         And Numero = @CodPed
  
  	Set @WCodPrdAnt = -1
  
      if (@TipDesdob = 'I')
  	  begin
          -- seleciona itens de pedidos "incentivados"
          Declare PDVIT_Cr Cursor Local Fast_Forward For 
  
            Select it.Cod_Produto, it.Cod_Lote, it.Tip_Sai,
                   it.Qtd_Pedido, it.Qtd_Bonificacao, it.Qtd_Pra, it.Qtd_Dep
              From PDVIT it 
                   Inner Join PRODU pr on it.Cod_Produto = pr.Codigo 
             Where it.Cod_Estabe = @CodEstabe 
               and it.Cod_Pedido = @CodPed 
               and it.Qtd_Pedido > 0
               and dbo.FN_ProdutoIncentivado(it.Cod_Estabe,it.Cod_Produto,@WIdIncFis) = 1
             Order by C_PrcTotal Desc
  	  end
  
      if (@TipDesdob = 'B')
  	  begin
          -- seleciona itens de pedidos não genericos/similares
          Declare PDVIT_Cr Cursor Local Fast_Forward For 
  
            Select it.Cod_Produto, it.Cod_Lote, it.Tip_Sai,
                   it.Qtd_Pedido, it.Qtd_Bonificacao, it.Qtd_Pra, it.Qtd_Dep
              From PDVIT it 
                   Inner Join PRODU pr on it.Cod_Produto = pr.Codigo 
             Where it.Cod_Estabe = @CodEstabe 
               and it.Cod_Pedido = @CodPed 
               and it.Qtd_Bonificacao > 0
             Order by C_PrcTotal Desc
  	  end
  
      if (@TipDesdob = 'G')
  	  begin
          -- seleciona itens de pedidos não genericos/similares
          Declare PDVIT_Cr Cursor Local Fast_Forward For 
  
            Select it.Cod_Produto, it.Cod_Lote, it.Tip_Sai,
                   it.Qtd_Pedido, it.Qtd_Bonificacao, it.Qtd_Pra, it.Qtd_Dep
              From PDVIT it 
                   Inner Join PRODU pr on it.Cod_Produto = pr.Codigo 
             Where it.Cod_Estabe = @CodEstabe 
               and it.Cod_Pedido = @CodPed 
               and it.Qtd_Pedido > 0
               and ((pr.Cod_GrpPrc <> 'G') and (pr.Cod_GrpPrc <> 'S'))
             Order by C_PrcTotal Desc
  	  end
  
      if (@TipDesdob = 'L')
  	  begin
          -- seleciona itens de pedidos com mais de um lote
  		--   Set @QtdLotDsp = dbo.FN_QtdLoteDisponivel (@CodEstabe, @CodCliPag, @CodPrd, @Date, @QtdMesMinPrzVctLot)
          Declare PDVIT_Cr Cursor Local Fast_Forward For 
  
            Select it.Cod_Produto, it.Cod_Lote, it.Tip_Sai,
                   it.Qtd_Pedido, it.Qtd_Bonificacao, it.Qtd_Pra, it.Qtd_Dep
              From PDVIT it
             Where it.Cod_Estabe = @CodEstabe
               And it.Cod_Pedido = @CodPed
               And it.Qtd_Pedido > 0
               And Exists(Select Cod_Produto, count(*)
                            From PDVIT
                           Where Cod_Estabe = @CodEstabe
                             And Cod_Pedido = @CodPed
                             And Qtd_Pedido > 0
                             And Cod_Produto = it.Cod_Produto
                           Group by Cod_Produto
                          Having count(*) > 1)
             Order by it.Cod_Produto, it.Tip_Sai desc, it.C_PrcTotal desc
        end
  
      Open PDVIT_Cr
      Fetch Next From PDVIT_Cr Into @it_CodPrd, @it_CodLot, @it_TipSai,
                                    @it_QtdPed, @it_QtdBon, @it_QtdPra, @it_QtdDep
      While @@FETCH_STATUS = 0
        begin
  	    Set @WFlgIncIte = 0
  
          -- normaliza estoques
          if @it_QtdPra < 0
            Set @it_QtdPra = 0
          if @it_QtdDep < 0
            Set @it_QtdDep = 0  
          if (@it_QtdPra+@it_QtdDep) <> (@it_QtdPed+@it_QtdBon)
            Set @it_QtdPra = @it_QtdPed + @it_QtdBon - @it_QtdDep
  
          Set @nw_QtdPra = @it_QtdPra
          Set @nw_QtdDep = @it_QtdDep
  
          if (@TipDesdob = 'L') and (@WCodPrdAnt = @it_CodPrd)
            Set @WFlgIncIte = 1
          else
          if (@TipDesdob = 'I')
            Set @WFlgIncIte = 1
  		else
          if (@TipDesdob = 'G')
            Set @WFlgIncIte = 1
  		else
          if (@TipDesdob = 'B')
            begin
              Set @WFlgIncIte = 1
  
              Set @nw_QtdPra = 0
              Set @nw_QtdDep = 0
  
              -- determina estoque 2
              if @it_QtdDep > 0
                if @it_QtdDep > @it_QtdBon
                  begin
                    Set @nw_QtdDep = @it_QtdBon
                    Set @it_QtdDep = @it_QtdDep - @it_QtdBon
                  end
                 else
                   begin
                    Set @nw_QtdDep = @it_QtdDep
                    Set @it_QtdDep = 0
                   end
        
              -- determina estoque 1
              if @nw_QtdDep < @it_QtdBon
                if @it_QtdPra > 0
                  if @it_QtdPra > (@it_QtdBon-@nw_QtdDep)
                    begin
                      Set @nw_QtdPra = (@it_QtdBon-@nw_QtdDep)
                      Set @it_QtdPra = @it_QtdPra - (@it_QtdBon-@nw_QtdDep)
                    end
                  else
                    begin
                      Set @nw_QtdPra = @it_QtdPra
                      Set @it_QtdPra = 0
                    end
        
              -- normaliza estoques 
              if (@it_QtdPra+@it_QtdDep) <> @it_QtdPed
                Set @it_QtdPra = @it_QtdPed - @it_QtdDep
  
              if @nw_QtdPra < 0
                Set @nw_QtdPra = 0
              if @nw_QtdDep < 0
                Set @nw_QtdDep = 0
              if (@nw_QtdPra+@nw_QtdDep) <> @it_QtdBon
                Set @nw_QtdPra = @it_QtdBon - @nw_QtdDep
  
            end  -- if (@TipDesdob = 'B')
  
          -- inclui item novo pedido
  		if @WFlgIncIte = 1
  		  begin
              Insert into PDVIT (Cod_Estabe, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai)
                Values (@CodEstabe, @CodPdvGer, @it_CodPrd, @it_CodLot, @it_TipSai)
              if @@error <> 0
                begin
                  if @@trancount > 0
                    Rollback Transaction
                  Return
                end
  
              Update d
                Set d.Qtd_Pedido          = Case 
                                              When @TipDesdob = 'B' then @it_QtdBon 
                                              Else @it_QtdPed 
                                             End,
                    d.Qtd_Bonificacao     = Case 
                                              When @TipDesdob = 'B' then 0 
                                              Else @it_QtdBon 
                                             End,
                    d.Qtd_Solicitado      = Case 
                                              When @TipDesdob = 'B' then @it_QtdBon 
                                              Else o.Qtd_Solicitado 
                                             End,
                    d.Qtd_ImpFat          = Case 
                                              When @TipDesdob = 'B' then @it_QtdBon*1.0/o.Fat_CnvImpFat 
                                              Else (@it_QtdPed+@it_QtdBon)*1.0/o.Fat_CnvImpFat
                                             End,
                    d.Qtd_Pra             = @nw_QtdPra,
                    d.Qtd_Dep             = @nw_QtdDep,
  
                    d.Prc_Unitario        = o.Prc_Unitario,
                    d.Per_Desconto        = IsNull(o.Per_Desconto,0),
                    d.Per_Descon          = IsNull(o.Per_Descon,0),
                    d.Per_DscVis          = IsNull(o.Per_DscVis,0),
                    d.C_PrcUni            = o.C_PrcUni,
                    d.C_PerDscIte         = IsNull(o.C_PerDscIte,0),
                    d.C_VlrDesconto       = o.C_VlrDesconto,
                    d.C_PrcTotal          = o.C_PrcTotal,
                    d.Fat_CnvImpFat       = o.Fat_CnvImpFat,
                    d.Prc_UniImpFat       = o.Prc_Unitario*o.Fat_CnvImpFat,
                    d.Des_UnvImpFat       = o.Des_UnvImpFat,
                    d.Des_AprImpFat       = o.Des_AprImpFat,
  
                    d.Loc_Fisica          = o.Loc_Fisica,
                    d.Cod_Fabricante      = o.Cod_Fabricante,
                    d.Cod_Promocao        = o.Cod_Promocao,
                    d.Qtd_PrzMax          = o.Qtd_PrzMax,
                    d.Prc_Tabela          = o.Prc_Tabela,
                    d.Prc_TabBru          = o.Prc_TabBru,
                    d.Flg_PrcUniDsc       = IsNull(o.Flg_PrcUniDsc,0),
                    d.Desconto            = IsNull(o.Desconto,0),
                    d.Flg_BlqInfPar       = IsNull(o.Flg_BlqInfPar,0),
  									    
                    d.Prc_MaxCon          = o.Prc_MaxCon,
                    d.Prc_Fabric          = o.Prc_Fabric,
                    d.Num_SeqDig          = o.Num_SeqDig,
                    d.Nom_UsuDesbloq      = o.Nom_UsuDesbloq,
                                                      
                    d.Id_PolCom           = o.Id_PolCom,
                    d.Flg_Verba           = IsNull(o.Flg_Verba,0),
                    d.Prc_PolCom          = o.Prc_PolCom,
                    d.Per_DscPolCom       = IsNull(o.Per_DscPolCom,0),
                    d.Per_DscVisPolCom    = IsNull(o.Per_DscVisPolCom,0),
                    d.Prc_CusMinComMarkup = IsNull(o.Prc_CusMinComMarkup,0),
                    d.Cod_KitPrm          = IsNull(o.Cod_KitPrm,0),
  
                    d.Vlr_BasVerba        = IsNull(o.Vlr_BasVerba,0),
                    d.Per_VrbPar          = IsNull(o.Per_VrbPar,0),
                    d.Vlr_VrbPar          = IsNull(o.Vlr_VrbPar,0),
                    d.Per_VrbBon          = IsNull(o.Per_VrbBon,0),
                    d.Vlr_VrbBon          = IsNull(o.Vlr_VrbBon,0),
                    d.Vlr_Bonificacao     = IsNull(o.Vlr_Bonificacao,0),
                    d.Vlr_DscBonRat       = IsNull(o.Vlr_DscBonRat,0),
  
                    d.Cod_PrjPde          = o.Cod_PrjPde,
                    d.Prc_UniPde          = IsNull(o.Prc_UniPde,0),
                    d.Per_DscPde          = IsNull(o.Per_DscPde,0),
                    d.Num_SeqPdc          = o.Num_SeqPdc
               From PDVIT d, PDVIT o
              Where d.Cod_Estabe  = o.Cod_Estabe
                And d.Cod_Pedido  = @CodPdvGer
                And d.Cod_Produto = o.Cod_Produto
                And d.Cod_Lote    = o.Cod_Lote
                And d.Tip_Sai     = o.Tip_Sai
  
                And o.Cod_Estabe  = @CodEstabe 
                And o.Cod_Pedido  = @CodPed
                And o.Cod_Produto = @it_CodPrd 
                And o.Cod_Lote    = @it_CodLot
                And o.Tip_Sai     = @it_TipSai
  
              if (@TipDesdob = 'L')  -- Exists PDVLT
  			  begin
  			    if not Exists(Select 1 From PDVLT 
  				               Where Cod_Estabe = @CodEstabe
  							     And Cod_Pedido = @CodPdvGer
  							     And Cod_Produt = @it_CodPrd
  							     And Cod_Lote = @it_CodLot)
                    begin
                      Insert Into PDVLT (Cod_Estabe, Cod_Pedido, Num_Vol, Cod_Produt, Cod_Lote, Qtd_Lote, Qtd_CxaFec,
  				                       Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_LocFis,
  					                   Qtd_LotePra, Qtd_LoteDep, Vol_TotIte, Qtd_EmbFec, Flg_Desord, Cod_FunSep, Transacao)
  			            Select @CodEstabe, @CodPdvGer, 1, Cod_Produt, Cod_Lote, Qtd_Lote, Qtd_CxaFec,
  				               Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_LocFis,
  					           Qtd_LotePra, Qtd_LoteDep, Vol_TotIte, Qtd_EmbFec, Flg_Desord, Cod_FunSep, Transacao
  				          From PDVLT
                           Where Cod_Estabe = @CodEstabe 
                             and Cod_Pedido = @CodPed 
                             and Cod_Produt = @it_CodPrd 
                             and Cod_Lote   = @it_CodLot
                      if @@error <> 0
                        begin
                          if @@trancount > 0
                            Rollback Transaction
                          Return
                        end
  
                      -- elimina rgistro origem
                      Delete From PDVLT
                       Where Cod_Estabe = @CodEstabe 
                         and Cod_Pedido = @CodPed 
                         and Cod_Produt = @it_CodPrd 
                         and Cod_Lote   = @it_CodLot
  				  end
  			  end  -- if (@TipDesdob = 'L')
  
              if Exists(Select it.Cod_Produt 
                          From PDEIT it Inner Join 
                               PDECB cb on ((it.Cod_Estabe = cb.Cod_Estabe) and (it.Cod_Layout = cb.Cod_Layout) and (it.Num_Cnpj = cb.Num_Cnpj) and (it.Cod_PedCli = cb.Cod_PedCli) and (it.Num_Desdob = cb.Num_Desdob)) 
                         Where it.Cod_Estabe = @CodEstabe      
                           and it.Cod_Layout = @Pde_Cod_Layout
                           and it.Num_Cnpj   = @Pde_Num_Cnpj 
                           and it.Cod_PedCli = @Pde_Cod_PedCli 
                           and it.Cod_Produt = @it_CodPrd 
                           and cb.Num_PedVen = @CodPed
                           and @Pde_Num_Cnpj <> '')
                begin
                  -- salvando produto que será deletado
                  Select @Pdeit_Num_Desdob = it.Num_Desdob,
      				   @Pdeit_Cod_PrdCli = it.Cod_PrdCli
                    From PDEIT it Inner Join 
                         PDECB cb on ((it.Cod_Estabe = cb.Cod_Estabe) and 
                                      (it.Cod_Layout = cb.Cod_Layout) and 
                                      (it.Num_Cnpj   = cb.Num_Cnpj) and 
                                      (it.Cod_PedCli = cb.Cod_PedCli) and 
                                      (it.Num_Desdob = cb.Num_Desdob)) 
                   Where it.Cod_Estabe = @CodEstabe      
                     and it.Cod_Layout = @Pde_Cod_Layout
                     and it.Num_Cnpj   = @Pde_Num_Cnpj 
                     and it.Cod_PedCli = @Pde_Cod_PedCli 
                     and it.Cod_Produt = @it_CodPrd 
                     and cb.Num_PedVen = @CodPed
  
      			-- transfere registro, eliminando origem
                  Exec _CopiaItemPDEIT @CodEstabe, @Pde_Cod_Layout, @Pde_Num_Cnpj, @Pde_Cod_PedCli, @Pdeit_Num_Desdob, @Pdeit_Cod_PrdCli, @Pde_Num_DesdobDes, 1 
                  if @@error <> 0
                    begin
                      if @@trancount > 0
                        Rollback Transaction
                      Return
                    end
  
                  -- aquix novo
                  if @TipDesdob = 'B'
                    begin
                      -- atualiza registro destino
                      Update PDEIT                          
                         Set Qtd_Pedido = @it_QtdBon,
                             Qtd_Atendi = 0
                       Where Cod_Estabe = @CodEstabe                  
                         and Cod_Layout = @Pde_Cod_Layout
                         and Num_Cnpj   = @Pde_Num_Cnpj
                         and Cod_PedCli = @Pde_Cod_PedCli 
                         and Num_Desdob = @Pde_Num_DesdobDes
                         and Cod_PedCli = @Pdeit_Cod_PrdCli
               
                      -- atualiza registro origem
                      Update PDEIT                          
                         Set Qtd_Pedido = Case
                                            When Qtd_Pedido > @it_QtdBon Then Qtd_Pedido - @it_QtdBon
                                            Else 1
                                          End
                       Where Cod_Estabe = @CodEstabe                  
                         and Cod_Layout = @Pde_Cod_Layout
                         and Num_Cnpj = @Pde_Num_Cnpj
                         and Cod_PedCli = @Pde_Cod_PedCli 
                         and Num_Desdob = @Pdeit_Num_Desdob
                         and Cod_PedCli = @Pdeit_Cod_PrdCli
  
                    end  -- if @TipDesdob = 'B'
  
                end  -- if Exists(
  
              -- atualiza item do pedido origem
              if @TipDesdob <> 'B'
                begin
                  Delete From PDVIT 
                   Where Cod_Estabe  = @CodEstabe 
                     and Cod_Pedido  = @CodPed 
                     and Cod_Produto = @it_CodPrd 
                     and Cod_Lote    = @it_CodLot
                     and Tip_Sai     = @it_TipSai
                end
              else
                begin
                  -- atualiza item do pedido de origem
                  -- tributos sao recalculados na triggeer
                  Update PDVIT
                     Set Qtd_Bonificacao = 0,
                         Qtd_Solicitado = Qtd_Solicitado - @it_QtdBon,
                         Qtd_Pra = @it_QtdPra,
                         Qtd_Dep = @it_QtdDep,
                         Qtd_ImpFat = Qtd_Pedido*1.0/Fat_CnvImpFat
                   Where Cod_Estabe  = @CodEstabe     
                     and Cod_Pedido  = @CodPed 
                     and Cod_Produto = @it_CodPrd 
                     and Cod_Lote    = @it_CodLot
                     and Tip_Sai     = @it_TipSai
                end
  
  		  end  -- if @WFlgIncIte = 1
  
            Set @WCodPrdAnt = @it_CodPrd
  
          Fetch Next From PDVIT_Cr Into @it_CodPrd, @it_CodLot, @it_TipSai,
                                        @it_QtdPed, @it_QtdBon, @it_QtdPra, @it_QtdDep
        end
        
      Close PDVIT_Cr
      Deallocate PDVIT_Cr
  
  
      --  pedido origem
      Update PDVCB
         Set Bloqueio = @cb_BlqAnt,
             Flg_Calc = 0
       Where Cod_Estabe = @CodEstabe     
         And Numero = @CodPed
  
      Exec PR_AtualizaCabecPDV @CodEstabe, @CodPed
      if @@error <> 0
        begin
          if @@trancount > 0
            Rollback Transaction
          Return
        end


      if (@TipDesdob = 'I') or
         (@TipDesdob = 'G') or
         (@TipDesdob = 'B')
        begin
          --  pedido origem
          Update PDVCB
             Set Flg_CriIteFec = 0
           Where Cod_Estabe = @CodEstabe     
             And Numero = @CodPed
  
          if @TipDesdob = 'B'
            Update PDVCB
               Set Num_PdvLig = @CodPdvGer
                   --Num_PdvFilho = @CodPdvGer,
             Where Cod_Estabe = @CodEstabe     
               And Numero = @CodPed
          else
            Delete From PDVDP
             Where Cod_Estabe = @CodEstabe 
               And Cod_Pedido = @CodPed
  
          --  Pedido gerado
          Update PDVCB
             Set Bloqueio = @cb_BlqAnt,
                 Status2 = 'A',
                 Cod_OrigemPdv = Case 
                                   When @TipDesdob = 'B' then 'D'+Substring(@cb_CodOriPdv,2,1) 
                                   Else @cb_CodOriPdv 
                                 End,
                 Flg_JaFechado = 0,
                 Flg_Calc = 0,
                 Flg_CriIteFec = 0
           Where Cod_Estabe = @CodEstabe     
             And Numero = @CodPdvGer
        end
  
      if (@TipDesdob = 'L')
        begin
          Exec PR_CalculaVencPDV @CodEstabe, @CodPed
          if @@error <> 0
            begin
              if @@trancount > 0
                Rollback Transaction
              Return
            end
  
          --  Pedido gerado
          Update d
             Set d.Bloqueio = o.Bloqueio,
                 d.Status1 = o.Status1,
                 d.Status2 = o.Status2,
                 d.Flg_JaFechado = o.Flg_JaFechado,
                 d.Flg_CriIteFec = o.Flg_CriIteFec,
                 d.Flg_Calc = 0
            From PDVCB d, PDVCB o
           Where d.Cod_Estabe = @CodEstabe     
             And d.Numero = @CodPdvGer
             And o.Cod_Estabe = @CodEstabe     
             And o.Numero = @CodPed
  
          Exec PR_CalculaVencPDV @CodEstabe, @CodPdvGer
          if @@error <> 0
            begin
              if @@trancount > 0
                Rollback Transaction
              Return
            end
        end
  
      -- Atualizar PDECB dos pedidos
      if @Pde_Num_Cnpj <> ''
        Update cb
           Set cb.Vlr_Total = IsNull(it.VlrTot,0)
          From PDECB cb Inner Join 
               (Select Cod_Estabe, Cod_Layout, Num_Cnpj, Cod_PedCli, Num_Desdob,
                       VlrTot = sum(Round(Qtd_Pedido*Prc_Unitario*(1-IsNull(Per_Desconto,0)/100),2)) 
                  From PDEIT
                 Where Cod_Estabe = @CodEstabe 
                   And Cod_Layout = @Pde_Cod_Layout
                   And Num_Cnpj   = @Pde_Num_Cnpj
                   And Cod_PedCli = @Pde_Cod_PedCli
                 Group by Cod_Estabe, Cod_Layout, Num_Cnpj, Cod_PedCli, Num_Desdob) it on ((cb.Cod_Estabe = it.Cod_Estabe) and
                                                                                           (cb.Cod_Layout = it.Cod_Layout) and
                                                                                           (cb.Num_Cnpj   = it.Num_Cnpj) and 
                                                                                           (cb.Cod_PedCli = it.Cod_PedCli) and 
                                                                                           (cb.Num_Desdob = it.Num_Desdob))
         Where cb.Cod_Estabe = @CodEstabe
           And cb.Cod_Layout = @Pde_Cod_Layout
           And cb.Num_Cnpj   = @Pde_Num_Cnpj
           And cb.Cod_PedCli = @Pde_Cod_PedCli
           And cb.Num_Desdob = @Pde_Num_Desdob
  
      if @@trancount > 0
        Commit Transaction
    end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_FecAutPDV]
@PCodEstabe int,
@PNumPdv int,
@PMsgErr varchar(8000) output

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime

Set @Now  = GetDate()
Set @Date = cast(GetDate() as date)

/*
if Charindex((Select Status2 From PDVCB Where Cod_Estabe = @PCodEstabe And Numero = @PNumPdv),';N;D;') > 0 
  RAISERROR('Pedido já faturado',16,1)
else
if Charindex((Select Status2 From PDVCB Where Cod_Estabe = @PCodEstabe And Numero = @PNumPdv),';F;') > 0 
  RAISERROR('Pedido já fechado',16,1)
else
*/

if Exists(Select 1 From PDVCB  Where Cod_Estabe = @PCodEstabe And Numero = @PNumPdv) and
   (Charindex((Select Status2 From PDVCB Where Cod_Estabe = @PCodEstabe And Numero = @PNumPdv),';N;D;F;') = 0)
BEGIN
Begin Transaction

Declare @pv_CodTipPed varchar(3),  -- 'PDV','COT'
        @pv_TipFat varchar(3) = '',
        @pv_TipPrz varchar(1) = '',
        @pv_OriPdv varchar(1) = '',
		@pv_IdPolCom int = 0,
        @pv_CodRegTri int = 0,
		@pv_CodCli int = 0,
        @pv_VlrLiqIte numeric(18,4),
		@pv_TipVct varchar(1),            -- Tip_Vencimento original
		@P_TipVct varchar(1),             -- Tip_Vencimento a gravar
		@P_CodPrz int = 0,                -- Cod_Prz
		@P_QtdPrzMed numeric(18,8) = 0,   -- Qtd_PrzMed
		@P_QtdParcela int = 0,            -- Qtd_ParPrz
		@P_QtdIntervalo int = 0,          -- Qtd_Intervalo
		@P_PerDescontoCom numeric(18,8),  -- Per_DescontoCom
		@P_PerDescontoFin numeric(18,8),  -- Per_DescontoFin

        @pm_FlgBlqVenCliSemLimCre bit = 0,
        @pm_QtdDiaDupVis int = 0,		 
        @pc_FlgSugDscGlbPdv bit = 0,
        @pc_PerDscComVis numeric (18,8) = 0,
        @pc_PerDscComPrz numeric (18,8) = 0,
        @pc_PerDscFinVis numeric (18,8) = 0,
        @pc_PerDscFinPrz numeric (18,8) = 0,
        @op_FlgCodCli bit = 0,
        @op_FlgLanFin bit = 0,
        @op_QtdMaxDup int = 0,
        @op_VlrMinDup numeric(18,4) = 0,

		@WFlgPdvOk bit = 0,
		@WCodPrd int = 0,
		@WSldCreCli numeric(18,4) = 0,
        @WMsgObs varchar(8000),
        @WMsgAux varchar(8000),
        @WSta smallint,
        @WStaLic varchar(1),
        @WCodMtv varchar(3),
		@WCodPdvInc int = 0,
		@WCodPdvGen int = 0,
		@WCodPdvBon int = 0

-- verifica se rateia descontos por bonificacao
Exec PR_RateiaDescontoBonificacaoPDVCB @PCodEstabe, @PNumPdv
if @@error <> 0
  begin
    if @@trancount > 0
      Rollback Transaction
    Return
  end    

Select @pm_FlgBlqVenCliSemLimCre = IsNull(FlgBlqVenCliSemLimCre,0),
       @pm_QtdDiaDupVis = IsNull(QtdDiaDupVis,0)
  From PARAM
 Where Cod_Estabe = @PCodEstabe

Select @pv_CodTipPed = Case When cb.Tip_Pedido = 'C' then 'COT' Else'PDV' End,
       @pv_TipFat = IsNull(cb.Tip_Faturamento,''),
       @pv_OriPdv = Substring(IsNull(cb.Cod_OrigemPdv,''),1,1),
       @pv_TipPrz = Substring(IsNull(cb.Cod_OrigemPdv,''),2,1),
	   @pv_IdPolCom = IsNull(cb.Id_PolCom,0),
	   @pv_CodRegTri = IsNull(cb.Cod_RegTri,0),
       @pv_CodCli = IsNull(cb.Cod_Cliente,0),
       @pv_VlrLiqIte = IsNull(cb.Vlr_LiqItens,0),
	   @pv_TipVct = IsNull(cb.Tip_Vencimento,''),
       @WMsgObs = IsNull(cb.Observacao,''),
	   @P_CodPrz = IsNull(cb.Cod_Prz,0),
	   @P_QtdPrzMed = IsNull(cb.Qtd_PrzMed,0),
	   @P_QtdParcela = IsNull(cb.Qtd_Parcela,0),
       @P_QtdIntervalo = IsNull(cb.Qtd_Intervalo,0),
       @P_PerDescontoCom = IsNull(cb.Per_DescontoCom,0),
       @P_PerDescontoFin = IsNull(cb.Per_DescontoFin,0),

       @pc_FlgSugDscGlbPdv = IsNull(pc.Flg_SugDscGlbPdv,0),
       @pc_PerDscComVis = IsNull(pc.Per_DscComVis,0), 
       @pc_PerDscComPrz = IsNull(pc.Per_DscCom,0), 
       @pc_PerDscFinVis = IsNull(pc.Per_DscFinVis,0), 
       @pc_PerDscFinPrz = IsNull(pc.Per_DscFin,0) 

  From PDVCB cb
       Left Join POCOM pc on cb.Id_PolCOm = pc.Id_PolCom
 Where cb.Cod_Estabe = @PCodEstabe
   And cb.Numero = @PNumPdv

Set @WFlgPdvOk = 0
Set @PMsgErr = ''
Set @P_TipVct = ''

if @pv_IdPolCom > 0 
  begin
    if @pv_TipPrz = 'F'
      begin
        Set @WFlgPdvOk = 1
        Set @P_TipVct = 'C'
      end
    else
    if (@pv_TipPrz = 'L') and (@P_CodPrz = 0)
      begin
        Set @P_CodPrz = dbo.FN_SugerePrazoPDVCB (@PCodEstabe, @pv_OriPdv, @pv_CodCli, @pv_IdPolCom, cast(@P_QtdPrzMed as int), @P_QtdParcela, @pv_VlrLiqIte)
        if @P_CodPrz = 0
          begin
            Set @WMsgAux = 'Não existe prazo que atende ao pedido'
            if Charindex(@WMsgAux,@WMsgObs) = 0  
              begin
                if DataLength(@WMsgObs) > 0 Set @WMsgObs = @WMsgObs + ';'
                Set @WMsgObs = @WMsgObs + @WMsgAux
              end
          end
      end
  end

if (@P_CodPrz > 0) and
   Exists(Select 1 From PRZCB Where Cod_Prz = @P_CodPrz And Flg_ParOk = 1) 
  begin
    Set @P_QtdPrzMed = 0
	Set @P_QtdParcela = 0

    Select @P_QtdPrzMed = Qtd_PrzMed, 
           @P_QtdParcela = Qtd_ParPrz 
      From PRZCB 
     Where Cod_Prz = @P_CodPrz
       And Flg_ParOk = 1 

    Set @WFlgPdvOk = 1
    Set @P_TipVct = 'T'
  end

if @pv_TipVct = 'V' 
  begin
    Set @P_TipVct = 'V'
    Set @P_CodPrz = 0
    Set @P_QtdPrzMed = @pm_QtdDiaDupVis
	Set @P_QtdParcela = 1
    Set @P_QtdIntervalo = 0

    Set @WFlgPdvOk = 1
  end

-- verifica tributacao
Set @WCodPrd = 0

Select top 1 @WCodPrd = it.Cod_Produto
  From PDVIT it 
       Left Join RTXCT rx on rx.Cod_RegTri = @pv_CodRegTri and it.Cod_ClaTri = rx.Cod_ClaTri 
 Where it.Cod_Estabe = @PCodEstabe
   And it.Cod_Pedido = @PNumPdv
   And it.Qtd_Pedido > 0
   And rx.Cod_RegTri is null 

if IsNull(@WCodPrd,0) > 0
  begin
    Set @WFlgPdvOk = 0
    Set @WMsgAux = 'Existe pelo menos 1 item ('+CAST(@WCodPrd as varchar)+') com tributacao nao configurada'

    if DataLength(@PMsgErr) > 0 Set @PMsgErr = @PMsgErr + char(13)+char(10)
    Set @PMsgErr = @PMsgErr + @WMsgAux

    if Charindex(@WMsgAux,@WMsgObs) = 0  
      begin
        if DataLength(@WMsgObs) > 0 Set @WMsgObs = @WMsgObs + char(13)+char(10)
        Set @WMsgObs = @WMsgObs + @WMsgAux
      end
  end

-- verifica fabricante
Set @WCodPrd = 0

Select top 1 @WCodPrd = it.Cod_Produto
  From PDVIT it 
       Inner Join PRODU pr on it.Cod_Produto = pr.Codigo 
 Where it.Cod_Estabe = @PCodEstabe
   And it.Cod_Pedido = @PNumPdv
   And it.Qtd_Pedido > 0
   And it.Cod_Fabricante <> pr.Cod_Fabricante 

if IsNull(@WCodPrd,0) > 0
  begin
    Set @WFlgPdvOk = 0
    Set @WMsgAux = 'Existe pelo menos 1 item ('+CAST(@WCodPrd as varchar)+') com fabricante <> cadastro'

    if DataLength(@PMsgErr) > 0 Set @PMsgErr = @PMsgErr + char(13)+char(10)
    Set @PMsgErr = @PMsgErr + @WMsgAux

    if Charindex(@WMsgAux,@WMsgObs) = 0  
      begin
        if DataLength(@WMsgObs) > 0 Set @WMsgObs = @WMsgObs + char(13)+char(10)
        Set @WMsgObs = @WMsgObs + @WMsgAux
      end
  end

-- verifica verba
Exec PR_MsgCriticaVerbaPdv @PCodEstabe, @PNumPdv, @WMsgAux Output
if @WMsgAux <> ''
  begin
    Set @WFlgPdvOk = 0

    if DataLength(@PMsgErr) > 0 Set @PMsgErr = @PMsgErr + char(13)+char(10)
    Set @PMsgErr = @PMsgErr + @WMsgAux

    if Charindex(@WMsgAux,@WMsgObs) = 0  
      begin
        if DataLength(@WMsgObs) > 0 Set @WMsgObs = @WMsgObs + char(13)+char(10)
        Set @WMsgObs = @WMsgObs + @WMsgAux
      end
  end


if (@WFlgPdvOk = 0) and
   (CharIndex(@pv_OriPdv,';M;T;W;') > 0) and
   (DataLength(@WMsgObs) > 0)
  begin
    Update PDVCB
       Set Observacao = @WMsgObs
     Where Cod_Estabe = @PCodEstabe
       And Numero = @PNumPdv
  end
else
if @WFlgPdvOk = 1
  begin
    if (@pv_IdPolCom > 0) and
       (@pc_FlgSugDscGlbPdv = 1)
      begin
        if @P_TipVct = 'V'
          begin
            if @P_PerDescontoCom = 0 
              Set @P_PerDescontoCom = @pc_PerDscComVis
            if @P_PerDescontoFin = 0 
              Set @P_PerDescontoFin = @pc_PerDscFinVis
          end
        else
          begin
            if @P_PerDescontoCom = 0
               Set @P_PerDescontoCom = @pc_PerDscComPrz
            if @P_PerDescontoFin = 0 
              Set @P_PerDescontoFin = @pc_PerDscFinPrz
          end
      end

    Update PDVCB
       Set Tip_Vencimento =	@P_TipVct,
           Cod_Prz = @P_CodPrz,
           Qtd_PrzMed =	@P_QtdPrzMed,
           Qtd_Parcela = @P_QtdParcela,
           Qtd_Intervalo = @P_QtdIntervalo,
           Per_DescontoCom = @P_PerDescontoCom,
           Per_DescontoFin = @P_PerDescontoFin
     Where Cod_Estabe = @PCodEstabe
       And Numero = @PNumPdv

    Exec PR_CalculaVencPDV @PCodEstabe, @PNumPdv
	if @@ERROR <> 0
      begin
        if @@trancount > 0
          Rollback Transaction
		Return
      end

    -- critica se houver alteração do tipo de faturanebto(operação)
    Exec PR_CriticaFecPDV @pv_TipFat, @PCodEstabe, @PNumPdv
	if @@ERROR <> 0
      begin
        if @@trancount > 0
          Rollback Transaction
		Return
      end

    -- aqui faz outras criticas
    Set @op_FlgCodCli = 0
    Set @op_FlgLanFin = 0
    Set @op_QtdMaxDup = 0
    Set @op_VlrMinDup = 0
    if not Exists(Select 1 
                    From TPOPE op 
                         Inner Join PDVCB cb on op.Cod_Ope = cb.Tip_Faturamento 
                   Where Cod_Estabe = @PCodEstabe And Numero = @PNumPdv)
      begin
        Set @WFlgPdvOk = 0
        if DataLength(@PMsgErr) > 0 Set @PMsgErr = @PMsgErr + char(13)+char(10)
        Set @PMsgErr = @PMsgErr + 'Tipo de Operação invalida'
      end
    else
      begin
        Select @op_FlgCodCli = IsNull(Flg_CodCli,0), 
               @op_FlgLanFin = IsNull(Flg_LanFin,0), 
               @op_QtdMaxDup = IsNull(Qtd_MaxDup,0), 
               @op_VlrMinDup = IsNull(Vlr_MinDup,0)
          From TPOPE op 
               Inner Join PDVCB cb on op.Cod_Ope = cb.Tip_Faturamento 
         Where Cod_Estabe = @PCodEstabe And Numero = @PNumPdv        
      end

    -- data de vencimentos e valores dos titulos
    if (@op_FlgCodCli = 1) and (@op_FlgLanFin = 1)
      begin
        if (Select Round(C_VlrPedido,2) From PDVCB Where Cod_Estabe = @PCodEstabe And Numero = @PNumPdv) <>
           (Select Round(sum(Vlr_Duplic),2) From PDVDP Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @PNumPdv)
          begin
            Set @WFlgPdvOk = 0
            if DataLength(@PMsgErr) > 0 Set @PMsgErr = @PMsgErr + char(13)+char(10)
            Set @PMsgErr = @PMsgErr + 'Valor do Pedido x Titulos divergentes'
          end

        if Exists(Select 1 From PDVDP Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @PNumPdv And Vlr_Duplic < @op_VlrMinDup)
          begin
            Set @WFlgPdvOk = 0
            if DataLength(@PMsgErr) > 0 Set @PMsgErr = @PMsgErr + char(13)+char(10)
            Set @PMsgErr = @PMsgErr + 'Existe pelo menos 1 Titulo com valor menor que o minimo permitido'
          end
      end

    if @WFlgPdvOk = 1
      begin
        Exec PR_AnalisaCreditoCliente @pv_CodTipPed, @PCodEstabe, @pv_CodCli, @PNumPdv, 
                                      @WMsgAux output,
                                      @WSta output,
                                      @WStaLic output,
                                      @WCodMtv output

        Set @WSldCreCli = IsNull((Select dbo.FN_SaldoCreditoCliente(@PCodEstabe,@pv_CodCli)),0)

        Update PDVCB
           Set Bloqueio = Case 
		                    When @WSta > 1 Then 'CR' 
                            When Round(C_VlrPedido,2) > @WSldCreCli then 'CR' 
                            Else '' 
                          End,
               Msg_Bloqueio = Case 
                                When Round(C_VlrPedido,2) > @WSldCreCli then 'ESTOUROU LIM. DE CRÉDITO' 
                                Else '' 
                              End,
               Flg_Credito = @WSta,
               Cod_BlqLic = @WStaLic,
               Cod_MtvRej = @WCodMtv
         Where Cod_Estabe = @PCodEstabe
           And Numero = @PNumPdv

        -- bloqueia cliente se for o caso
        if @pm_FlgBlqVenCliSemLimCre = 1
          Update cl
             Set cl.Bloqueado = 1,
                 cl.Motivo_Bloqueio = 'Bloq. auto. por lim. de créd.'
            From PDVCB cb
		         Inner Join CLIEN cl on cb.Cod_Cliente = cl.Codigo
           Where cb.Cod_Estabe = @PCodEstabe
             And cb.Numero = @PNumPdv
             And IsNull(cl.Bloqueado,0) = 0
             And Round(cb.C_VlrPedido,2) > @WSldCreCli

        -- desdobra incentivos fiscais
        Exec PR_DesdobraPDV 'I', @PCodEstabe, @PNumPdv, @WCodPdvInc Output

        -- desdobra genericos/similares
        Exec PR_DividePDVGen @PCodEstabe, @PNumPdv, @WCodPdvGen output 

        -- desdobra bonificacoes
        Exec PR_DividePDVBon @PCodEstabe, @PNumPdv, @WCodPdvBon output 


        --  fecha pedido
        Exec PR_FechaPDV @PCodEstabe, @PNumPdv, 'F'

        if @WCodPdvInc > 0 
          begin
            Exec PR_FecAutPdv @PCodEstabe, @WCodPdvInc, @WMsgAux output
          end

        if @WCodPdvGen > 0 
          begin
            Exec PR_FecAutPdv @PCodEstabe, @WCodPdvGen, @WMsgAux output
          end

        if @WCodPdvBon > 0 
          begin
            Exec PR_FecAutPdv @PCodEstabe, @WCodPdvBon, @WMsgAux output
          end

      end
   end   --  if @WFlgPdvOk = 1

if @@trancount > 0
  Commit Transaction
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_GeraNFS]
@CodEstabe int,                -- estabelecimento
@CodPed int,                   -- num. do pedido
@CodCfo int,                   -- codigo fiscal de operacao
@NumSel bigint,                -- num. do selo fiscal inicial
@NumFor int,                   -- num. do formulario inicial
@TipNfs varchar(1),            -- tipo de nota: 'V', 'D', 'O'
@DesUsu varchar(15),           -- usuario
@SerNfsRet varchar(3) output,  -- serie NF gerada
@NumNfsRet int output          -- num. NF gerada

AS

SET ANSI_WARNINGS OFF
SET NOCOUNT ON 

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime,
        @MsgErr varchar(200),
        @WFlgWMS bit

Set @Now = GetDate()
Set @Date = cast(GetDate() as Date)

If (@DesUsu = '' or @DesUsu = 'SISTEMA')
  Set @DesUsu = dbo.FN_UsuarioInfarma()

Set @SerNfsRet = ''
Set @NumNfsRet = 0
Set @MsgErr = ''

if Charindex((Select Status2 From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @CodPed),';N;D;') > 0 
  Set @MsgErr = 'Pedido já faturado'
else
if ((Select IsNull(FlgNfe,0) From PARAM Where Cod_Estabe = @CodEstabe) = 1) and (not Exists(Select 1 From NMNFE Where Cod_Estabe = @CodEstabe And Flg_Padrao = 1))
  Set @MsgErr = 'Não existe série padrão cadastrada para nota fiscal eletrônica'
else
if (Select Ltrim(Rtrim(IsNull(Cod_TipLucro,''))) From ESTAB Where Cod_Estabe = @CodEstabe) = ''
  Set @MsgErr = 'Tipo de Lucro do Estabelecimento não cadastrado'
else
if ((Select Flg_Wms From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @CodPed) = 1) and
   Exists(Select it.QtdIte, lt.QtdLot
          From (Select Cod_Produto, QtdIte = SUM(IsNull(Qtd_Pedido,0)+Isnull(Qtd_Bonificacao,0))
                  From PDVIT 
                 Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed
                   And (IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) > 0
                 Group by Cod_Produto) it Full Outer Join
               (Select Cod_Produt, QtdLot = SUM(IsNull(Qtd_Lote,0))
                  From PDVLT
                 Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed
                   And IsNull(Qtd_Lote,0) > 0
                 Group by Cod_Produt) lt on it.Cod_Produto = lt.Cod_Produt
          Where (IsNull(it.QtdIte,0) <> IsNull(lt.QtdLot,0)))
  Set @MsgErr = 'Existem inconsistências nos Lotes do Pedido. Cancele-o'
else
-- verifica se existe NF faturada para este pedido nos ultimos 6 meses
if Exists(Select 1 From NFSCB
           Where Cod_Estabe = @CodEstabe
             And Cod_Pedido = @CodPed
             And DATEDIFF (month,Dat_Emissao,@Date ) < 6)
  Set @MsgErr = (Select top 1 'Já existe uma NF('+cast(Num_Nota as varchar)+') '+
                              'emitida para este pedido('+cast(@CodPed as varchar)+')'
                   From NFSCB
                  Where Cod_Estabe = @CodEstabe
                    And Cod_Pedido = @CodPed
                    And DATEDIFF (month,Dat_Emissao,@Date ) < 6)


if @MsgErr <> ''
  RAISERROR(@MsgErr,16,1)
else
begin
  Begin Transaction

  Set @SerNfsRet = ''
  Set @NumNfsRet = 0

  Set @WFlgWMS = IsNull((Select Flg_Wms From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @CodPed),0)

  Update PDVCB
     Set Qtd_Itens = Qtd_Itens + 0 
   Where Cod_Estabe = @CodEstabe And Numero = @CodPed
  if (@@error <> 0)
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end

  Update NMFIS
     Set Nota_Fiscal_M1 = Nota_Fiscal_M1 + 0
   Where Cod_Estabe = @CodEstabe
  if (@@error <> 0)
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end

  Update NMNFE     
     Set Num_Nfe = Num_Nfe + 0
   Where Cod_Estabe = @CodEstabe 
     And Flg_Padrao = 1
  if (@@error <> 0)
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end

  Declare @WCodOri varchar(20)

  -- variaveis a gravar em NFSCB
  Declare @PEspNfs varchar(3),
          @PQtdPagNfs int,
          @PSerSel varchar(2),
          @PNumSel bigint,
          @PNumFor int,
          @PCodCfo smallint,
          @PDatEmi smalldatetime,
          @PTipVct varchar(1),
          @PTipRetImp varchar(1),
          @PPerDscFin numeric(18,4),   -- novo desc. financeiro sobre valor toal da nf
          @PPerDscFinLiq numeric(18,4),  -- % aplicado sobre Valor da mercadoria
          @PCgc varchar(14),
          @PCgf varchar(15),
          @PDesEnd  varchar(50),
          @PDesBai varchar(20),
          @PCep varchar(8),
          @PEst varchar(2),
          @PDesCid varchar(25),
          @PCodCid int,
          @PCodCidIbge varchar(7),
          @PCodMacReg int,
          @PCodMicReg int,
          @PQtdPar int,
          @PQtdPrzMed numeric(18,4),
          @PFlgComNor bit,
          @PPerComVnd numeric(18,4),
          @PPerComOpe numeric(18,4),
          @PPerComSup numeric(18,4),
          @PPerComGer numeric(18,4),
          @PPerComSupOpe numeric(18,4),
          @PPerComGerOpe numeric(18,4),
          @PModNotFis varchar(2),
          @PCodStaNfe varchar(1),
          @PUfPlaVei varchar(2),
          @PCodPlaVei varchar(10),
		  @PNumInscriSbtEmiUfd varchar(15),

          @PVlrDebVrbVdr numeric(18,4),
          @PVlrComTra numeric(18,4),
          @PVlrDscCom numeric(18,4),
          @PVlrOutDsp numeric(18,4),
          @WVlrOutDsp numeric(18,4),
          @PVlrTotNot numeric(18,4),

          @PVlrSubTri numeric(18,4),
          @PVlrDscTri numeric(18,4),
          @PVlrRecSbt numeric(18,4),
          @PVlrFcpSbt numeric(18,4),
          @PVlrFcpSbtRec numeric(18,4)

  -- coloca campos de PDVCB na memoria
  Declare @cb_TipFat varchar(3),
          @cb_TipSaiPdv varchar(1),
          @cb_TipGerVrb varchar(1),
          @cb_TipRatBon varchar(1),
          @cb_FlgBlqDebVrbNotBon bit,
          @cb_StaPdv1 varchar(1),
          @cb_StaPdv2 varchar(1),
          @cb_TipBlq varchar(2),
          @cb_QtdIte int,
          @cb_TipVct varchar(1),
          @cb_CodCli int,
          @cb_TipCon varchar(1),
          @cb_CodFun int,
          @cb_NomCon varchar(45),
          @cb_CodOriPdv varchar(2),
          @WCodOriPdv varchar(1),
          @cb_CodDig int,
          @cb_CodOpe int,
          @cb_CodVdr int,
          @cb_CodSup int,
          @cb_CodGer int,
          @cb_CodSupOpe int,
          @cb_CodGerOpe int,
          @cb_CodAgc int,
          @cb_CodTra int,
          @cb_CodRot int,
          @cb_CodRegTri int,
          @cb_VlrLiqIte numeric(18,4),
          @cb_VlrBasDscCom numeric(18,4),
          @cb_VlrBasPar numeric(18,4),
          @cb_VlrRepIcm numeric(18,4),
          @cb_VlrSubTri numeric(18,4),
          @cb_VlrSubTriFcp numeric(18,4),
          @cb_VlrSbtRes numeric(18,4),
          @cb_VlrDscTri numeric(18,4),
          @cb_VlrDscBon numeric(18,4),
          @cb_VlrDspExt numeric(18,4),
          @cb_VlrDespes numeric(18,4),
          @cb_VlrIpi numeric(18,4),
          @cb_QtdPes numeric(18,4),
          @cb_QtdVol int,
          @cb_IdPolCom int,
          @cb_PerSubFat  numeric(7,4),
          @cb_PerDscCom numeric(7,4),
          @cb_FlgVlrFin bit,
          @cb_ObsNfs varchar(1600),
          @cb_DatPed smalldatetime,
          @cb_CodPedCliPde varchar(20),
          @cb_CodPedCmpCli varchar(20),
          @cb_NotEmpCli varchar(20),
          @cb_NumConCli varchar(40),
          @cb_DesLayPde varchar(25),
          @cb_CodPrjPde varchar(12),
          @cb_DesConven varchar(30),
          @cb_CodCtr int,
          @cb_NumSeqCtr int,
          @cb_IdConsig int,
          @WCodTipSaiCng varchar(3),
          @cb_TipFrete varchar(1),
          @cb_VlrFrete numeric(18,4),
          @cb_VlrFrePrv numeric(18,4),
          @cb_PerComSup numeric(7,4),
          @cb_PerComGer numeric(7,4),
          @cb_PerComSupOpe numeric(7,4),
          @cb_PerComGerOpe numeric(7,4),
          @cb_FlgGerRetBon bit,
          @cb_UfPlaVei varchar(2),
          @cb_CodPlaVei varchar(10),
          @cb_VlrSdoVrb numeric(18,4),
          @cb_InscricaoSuframa varchar(9),
		  @cb_VlrBasIrf numeric(18,4),
		  @cb_VlrIrf numeric(18,4),		
		  @cb_VlrSemIrf numeric(18,4), 
          @pc_Controle_Saldo varchar(1),
          @pc_FlgAcuVrbPos bit,
          @pc_FlgAcuVrbNeg bit,
          @pc_FlgMarkupCusCom bit,
		  @pc_FlgCtrPdvVrbVdr bit,
		  @pc_FlgCtrPdvVrbOpe bit

  -- normaliza supervisor/gerencia
    Update cb 
       Set cb.Cod_Supervisor = ve.Cod_Supervisor 
     From PDVCB cb 
	      Inner Join VENDE ve on cb.Cod_Vendedor = ve.Codigo
    Where cb.Cod_Estabe = @CodEstabe 
	  And cb.Numero = @CodPed
      And IsNull(cb.Cod_Supervisor,0) <> IsNull(ve.Cod_Supervisor,0)
      
    Update cb 
       Set cb.Cod_Gerencia = su.Cod_Gerencia
      From PDVCB cb 
	       Inner Join VENDE ve on cb.Cod_Vendedor = ve.Codigo
           Inner Join SUPER su on ve.Cod_Supervisor = su.Codigo
     Where cb.Cod_Estabe = @CodEstabe 
	   And cb.Numero = @CodPed
       And IsNull(cb.Cod_Gerencia,0) <> IsNull(su.Cod_Gerencia,0)

    Update cb 
       Set cb.Cod_SupOpe = ve.Cod_Supervisor 
      From PDVCB cb 
	       Inner Join VENDE ve on cb.Cod_VendTlmkt = ve.Codigo
     Where cb.Cod_Estabe = @CodEstabe 
	   And cb.Numero = @CodPed
       And IsNull(cb.Cod_SupOpe,0) <> IsNull(ve.Cod_Supervisor,0)
      
    Update cb 
       Set cb.Cod_GerOpe = su.Cod_Gerencia
      From PDVCB cb 
	       Inner Join VENDE ve on cb.Cod_VendTlmkt = ve.Codigo
           Inner Join SUPER su on ve.Cod_Supervisor = su.Codigo
     Where cb.Cod_Estabe = @CodEstabe 
	   And cb.Numero = @CodPed
       And IsNull(cb.Cod_GerOpe,0) <> IsNull(su.Cod_Gerencia,0)

  Select @cb_TipFat = cb.Tip_Faturamento,
         @cb_TipSaiPdv = IsNull(cb.Tip_SaiPdv,''),
         @cb_TipGerVrb = IsNull(cb.Tip_GerVrb,''),
         @cb_TipRatBon = IsNull(cb.Tip_RatBon,''),
         @cb_FlgBlqDebVrbNotBon = IsNull(cb.Flg_BlqDebVrbNotBon,0),
         @cb_StaPdv1 = cb.Status1,
         @cb_StaPdv2 = cb.Status2,
         @cb_TipBlq = cb.Bloqueio,
         @cb_TipVct = cb.Tip_Vencimento,
         @cb_CodCli = cb.Cod_Cliente,
         @cb_TipCon = cb.Tip_Consumidor,
         @cb_CodFun = cb.Cod_Funcionario,
         @cb_NomCon = cb.Consumidor,
         @cb_CodOriPdv = cb.Cod_OrigemPdv,
         @WCodOriPdv = Substring(cb.Cod_OrigemPdv,1,1),
         @cb_CodDig = cb.Cod_Digitador,
         @cb_CodOpe = cb.Cod_VendTlmkt,
         @cb_CodVdr = cb.Cod_Vendedor,
         @cb_CodSup = cb.Cod_Supervisor,
         @cb_CodGer = cb.Cod_Gerencia,
         @cb_CodSupOpe = cb.Cod_SupOpe,
         @cb_CodGerOpe = cb.Cod_GerOpe,
         @cb_CodAgc = cb.Cod_Agente,
         @cb_CodTra = cb.Cod_Transportadora,
         @cb_CodRot = IsNull(cb.Cod_Rota,0),
         @cb_CodRegTri = cb.Cod_RegTri,
         @cb_VlrLiqIte = cb.Vlr_LiqItens,
         @cb_VlrBasDscCom = cb.Vlr_BasDscCom,
         @cb_VlrBasPar = cb.Vlr_BasPar,
         @cb_VlrRepIcm = ISNULL(cb.Vlr_RepIcms,0),
         @cb_VlrSubTri = ISNULL(cb.Vlr_SubsTrib,0),
         @cb_VlrSbtRes = ISNULL(cb.Vlr_SbtRes,0),
         @cb_VlrDscTri = ISNULL(cb.Vlr_DscTri,0),
         @cb_VlrDscBon = ISNULL(cb.Vlr_DscBon,0),
         @cb_VlrDspExt = ISNULL(cb.Vlr_DspExt,0),
         @cb_VlrDespes = ISNULL(cb.Vlr_Despes,0),
         @cb_VlrIpi = ISNULL(cb.Vlr_Ipi,0),
         @cb_QtdPes = cb.Qtd_Peso,
         @cb_QtdVol = cb.Qtd_Volumes,
         @cb_IdPolCom = cb.Id_PolCom, 
         @cb_QtdIte = cb.Qtd_Itens,
         @cb_PerSubFat = cb.Per_SubFat,
         @cb_PerDscCom = IsNull(cb.Per_DescontoCom,0),
         @cb_FlgVlrFin = cb.Flg_VlrFinanc,
         @cb_ObsNfs = Substring(cb.Obs_NotFis,1,1600),
         @cb_DatPed = cb.Dat_Pedido,
         @cb_CodPedCliPde = cb.Cod_PedCli,
         @cb_CodPedCmpCli = cb.Cod_PedCmpCli,
         @cb_NotEmpCli = cb.Ide_NotEmp,
         @cb_NumConCli = cb.Ide_Contra,
         @cb_DesLayPde = cb.Des_LayoutPde,
         @cb_CodPrjPde = cb.Cod_PrjPde,
         @cb_DesConven = cb.Des_Convenio,
         @cb_CodCtr = cb.Cod_Contrato,
         @cb_IdConsig = IsNull(cb.Id_Consig,0),
         @cb_NumSeqCtr = cb.Num_SequenciaCtr,
         @cb_TipFrete = IsNull(cb.Tip_Frete,'1'),   -- '1'-CIF
         @cb_VlrFrete = Round(IsNull(cb.Vlr_Frete,0),2),
         @cb_VlrFrePrv = Round(IsNull(cb.Vlr_FrePrv,0),2),
         @cb_FlgGerRetBon = IsNull(cb.Flg_GerRetBon,0),
         @cb_PerComSup = IsNull(cb.Per_ComSup,0),
         @cb_PerComGer = IsNull(cb.Per_ComGer,0),
         @cb_PerComSupOpe = IsNull(cb.Per_ComSupOpe,0),
         @cb_PerComGerOpe = IsNull(cb.Per_ComGerOpe,0),
         @cb_UfPlaVei = Ltrim(Rtrim(cb.Uf_PlaVei)),
         @cb_CodPlaVei =  Ltrim(Rtrim(cb.Cod_PlaVei)),
         @cb_VlrSdoVrb = IsNull(cb.Vlr_Verba,0),
         @cb_InscricaoSuframa = IsNull(cb.Inscricao_Suframa,''),
		 @cb_VlrBasIrf = IsNull(cb.Vlr_BasIrf,0),
		 @cb_VlrIrf = IsNull(cb.Vlr_Irf,0),

         @PQtdPar = cb.Qtd_Parcela,
         @PQtdPrzMed = cb.Qtd_PrzMed,
         @PPerDscFinLiq = IsNull(cb.Per_DescontoFin,0),
         @PFlgComNor = cb.Flg_ComisNormal,
         @PPerComOpe = Round(IsNull(cb.Per_ComOpe,0),2),
         @PPerComVnd = Round(IsNull(cb.Per_ComVnd,0),2),
         @pc_Controle_Saldo = pc.Controle_Saldo, 
         @pc_FlgAcuVrbPos = pc.Flg_AcuVrbPos,
         @pc_FlgAcuVrbNeg = pc.Flg_AcuVrbNeg,
         @pc_FlgMarkupCusCom = pc.Flg_MarkupCusCom,
         @pc_FlgCtrPdvVrbVdr = pc.Flg_CtrPdvVrbVdr,
         @pc_FlgCtrPdvVrbOpe = pc.Flg_CtrPdvVrbOpe

    From PDVCB cb
         left join VENDE ve on ve.Codigo = cb.Cod_Vendedor
         left join POCOM pc on pc.Id_PolCom = cb.Id_PolCom
         left join PCXVE xv on xv.Id_PolCom = cb.Id_PolCom and xv.Cod_Vended = cb.Cod_Vendedor
         left join PCXOP xo on xo.Id_PolCom = cb.Id_PolCom and xo.Cod_Vended = cb.Cod_VendTlmkt
         left join PCXSU xs on xs.Id_PolCom = cb.Id_PolCom and xs.Cod_Super  = ve.Cod_Supervisor
   Where cb.Cod_Estabe = @CodEstabe 
     And cb.Numero = @CodPed

  Select @cb_VlrSubTriFcp = ROUND(SUM(ISNULL(Vlr_FcpSbt,0)),2)          
    From PDVIT
   Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed

  -- coloca campos de ESTAB na memoria
  Declare @em_Cep varchar(8),
          @em_CodEst varchar(2),
          @em_CodTipLuc varchar(2),
		  @em_FlgContriSubstituido bit

  Select @em_Cep = Num_Cep,
         @em_CodEst = Des_Estado,
         @em_CodTipLuc = IsNull(Cod_TipLucro,''),
		 @em_FlgContriSubstituido = IsNull(Flg_ContriSubstituido,0)
    From ESTAB
    Where Cod_Estabe = @CodEstabe

  -- coloca campos de PARAM na memoria
  Declare @pm_NumItePagNfs int,
          @pm_FlgCtrSelFis bit,
          @pm_ModeloNotaFiscal varchar(3),
          @pm_SerieSeloFiscal varchar(2),
          @pm_CodCidEmpLoc int,
          @pm_CodMacRegEmpLoc int,
          @pm_CodMicRegEmpLoc int,
          @pm_FlgComPrdPrpDsc bit,
          @pm_FlgDespachMercad bit,
          @pm_FlgNfe bit,
          @pm_FlgIncIpiCalPis bit,
          @pm_FlgExcIcmCalPis bit,
          @pm_FlgDebBlqBanVrbVdr bit,
          @pm_PerCusFinDiaExcPrzMedCfg numeric(18,4),
          @pm_QtdPrzMedCfg int

  Select @pm_NumItePagNfs = IsNull(NumItePagNfs,0),
         @pm_FlgCtrSelFis = IsNull(FlgCtrSelFis,0),
         @pm_ModeloNotaFiscal = ModeloNotaFiscal,
         @pm_SerieSeloFiscal = SerieSeloFiscal,
         @pm_CodCidEmpLoc = CodCidadeEmpLoc,
         @pm_CodMacRegEmpLoc = CodMacRegEmpLoc,
         @pm_CodMicRegEmpLoc = CodMicRegEmpLoc,
         @pm_FlgComPrdPrpDsc = IsNull(FlgComPrdPrpDsc,0),
         @pm_FlgDespachMercad = IsNull(FlgDespachMercad,0),
         @pm_FlgNfe = IsNull(FlgNfe,0),
         @pm_FlgIncIpiCalPis = IsNull(FlgIncIpiCalPis,0),
         @pm_FlgExcIcmCalPis = IsNull(FlgExcIcmCalPis,0),
		 @pm_FlgDebBlqBanVrbVdr = IsNull(FlgDebBlqBanVrbVdr,0),
		 @pm_PerCusFinDiaExcPrzMedCfg = IsNull(PerCusFinDiaExcPrzMedCfg,0),
		 @pm_QtdPrzMedCfg = IsNull(QtdPrzMedCfg,0)
    From PARAM
   Where Cod_Estabe = @CodEstabe 

  -- coloca campos de CLIEN na memoria
  if Exists(Select Codigo From CLIEN Where Codigo = @cb_CodCli)
    begin
      Update CLIEN
         Set Total_Debito = IsNull(Total_Debito,0) + 0
       Where Codigo = @cb_CodCli
    end

  Declare @cl_CodEst varchar(2),
          @cl_TipCon varchar(1),
          @cl_CodCid int,
          @cl_CodBai int,
          @cl_CgcCpf varchar(14),
          @cl_Cgf varchar(15),
          @cl_DesEnd varchar(65),
          @cl_Cep varchar(8),
          @cl_FlgBlqCobTxaBan bit,
          @cl_CodRamAtv int,
          @uf_FlgRegSubTri bit,
          @Uf_BlqInsEstSbtNfs bit,
          @uf_NumInscriSbt varchar(15),
          @PTotDebCli numeric(18,4),
          @PVlrUltFatCli numeric(18,4),
          @PVlrMaiFatCli numeric(18,4)
            
  Select @cl_CodEst = cl.Cod_Estado,
         @cl_TipCon = cl.Tipo_Consumidor,
         @cl_CodCid = cl.Cod_Cidade,
         @cl_CodBai = cl.Cod_Bairro,
         @cl_CgcCpf = cl.Cgc_Cpf,
         @cl_Cgf = cl.Cgf,
         @cl_DesEnd = case
                        when IsNull(cl.Endereco,'') <> '' and IsNull(cl.Numero,'') <> '' and IsNull(cl.Complemento,'') <> '' then
                             ltrim(rtrim(cl.Endereco))+', '+ltrim(rtrim(cl.Numero))+', '+ltrim(rtrim(cl.Complemento))
                        else ltrim(rtrim(cl.Endereco))+', '+ltrim(rtrim(cl.Numero))
                      end,
         @cl_Cep = cl.Cep, 
         @cl_FlgBlqCobTxaBan = cl.Flg_BlqCobTxaBan,
		 @cl_CodRamAtv = cl.Cod_RamoAtividade,
         @PTotDebCli = IsNull(cl.Total_Debito,0),
         @PVlrUltFatCli = IsNull(cl.Valor_UltimaFatura,0),
         @PVlrMaiFatCli = IsNull(cl.Valor_MaiorFatura,0)
    From CLIEN cl 
    Where cl.Codigo = @cb_CodCli

  -- coloca campos de UFXES na memoria
  Select @uf_FlgRegSubTri = IsNull(Flg_RegSubTri,0),
         @Uf_BlqInsEstSbtNfs = IsNull(Flg_BlqNumInscriSubTriNfs,0),
         @uf_NumInscriSbt = case 
                              when (IsNull(Num_InscriSubTri,'') <> '.') and (IsNull(Num_InscriSubTri,'') <> '')  then IsNull(Num_InscriSubTri,'')
                              else ''
                            end
    From UFXES
   Where Cod_Estabe = @CodEstabe
     And Cod_UF = @cl_CodEst

  if @uf_FlgRegSubTri is null Set @uf_FlgRegSubTri = 0
  if @Uf_BlqInsEstSbtNfs is null Set @Uf_BlqInsEstSbtNfs = 0
  if @uf_NumInscriSbt is null Set @uf_NumInscriSbt = ''

  -- coloca campos de CIDAD na memoria
  Declare @ci_DesCid varchar(25),
          @ci_CodCidIbge varchar(7)

  Select @ci_DesCid = Descricao,
         @ci_CodCidIbge = Cod_CidIbge
    From CIDAD
   Where Cod_Estado = @cl_CodEst
     And Codigo = @cl_CodCid

  -- coloca campos de BAIRR na memoria
  Declare @ba_DesBai varchar(20),
          @ba_CodMacReg int,
          @ba_CodMicReg int 
    
  Select @ba_DesBai = Descricao,
         @ba_CodMacReg = Cod_MacroReg,
         @ba_CodMicReg = Cod_MicroReg
    From BAIRR
   Where Cod_Estado = @cl_CodEst
     And Cod_Cidade = @cl_CodCid
     And Codigo = @cl_CodBai

  -- coloca campos de TRANS na memoria
  Declare @tr_Pessoa varchar(1),
          @tr_PerFrete numeric(18,4),
          @tr_VlrMin numeric(18,4),
          @tr_FlgCalFreVerMer bit,
          @tr_UfPlaVei varchar(2),
          @tr_CodPlaVei varchar(10)

  Select @tr_Pessoa = tr.Pessoa,
         @tr_PerFrete = Case 
                          When tx.Cod_Transp is null then IsNull(tr.Per_Frete,0) 
                          Else IsNull(tx.Per_Frete,0) 
                        End,
         @tr_VlrMin = Case 
                          When tx.Cod_Transp is null then IsNull(tr.Vlr_Minimo,0) 
                          Else IsNull(tx.Vlr_Minimo,0) 
                        End,
         @tr_FlgCalFreVerMer = Case 
                                 When tx.Cod_Transp is null then IsNull(tr.Flg_CalFreVlrMer,0) 
                                 Else IsNull(tx.Flg_CalFreVlrMer,0) 
                               End,
         @tr_UfPlaVei = IsNull(Uf_PlaVei,''),
         @tr_CodPlaVei = IsNull(Cod_PlaVei,'')
    From TRANS tr
         Left Join TRXUF tx on tr.Codigo = tx.Cod_Transp and tx.Cod_UF COLLATE DATABASE_DEFAULT = @cl_CodEst COLLATE DATABASE_DEFAULT 
   Where tr.Codigo = @cb_CodTra


  -- colocar campos de AGCOB na memoria 
  -- despesa de boleto somente para banco cobrado na NF
  Declare @ag_VlrDspBolBan numeric(18,4),
          @ag_PerTaxAdm numeric(18,4),
          @ag_CodAplTaxAdm varchar(1)

  Select @ag_VlrDspBolBan = case 
                              When (Isnull(Flg_CobDspBolBanNtf,0) = 1) and (Tipo = 'BC') and
                                   (IsNull(@cl_FlgBlqCobTxaBan,0) = 0) then Round(Isnull(Vlr_DspBolBan,0),2)
                              else 0
                            end,
         @ag_PerTaxAdm = IsNull(Per_TaxAdm,0),
         @ag_CodAplTaxAdm = IsNull(Cod_AplTaxAdm,'')
    From AGCOB
   Where Codigo = @cb_CodAgc
    
  -- coloca campos de RGTRI na memoria
  Declare @rt_FlgConsumFin bit,
          @rt_CtrImpIcmTotNfs bit,
          @rt_FlgDscIcmOrgPub bit,
          @rt_FlgDscIcmOrgPubAcr bit,
          @rt_FlgUsaCfoSbtSaiIntGenSim bit

  Select @rt_FlgConsumFin = IsNull(Flg_ConsumFin,0),
         @rt_CtrImpIcmTotNfs = Isnull(Ctrl_ImpIcmTotNfs,0),
         @rt_FlgDscIcmOrgPub = IsNull(Flg_DscIcmOrgPub,0),
         @rt_FlgDscIcmOrgPubAcr = IsNull(Flg_DscIcmOrgPubAcr,0),
         @rt_FlgUsaCfoSbtSaiIntGenSim = IsNull(Flg_UsaCfoSbtSaiIntGenSim,0)
    From RGTRI
   Where Cod_RegTri = @cb_CodRegTri

  -- coloca campos TPOPE na memoria
  Declare @to_CodCfoConFinInt smallint,
          @to_CodCfoConFinExt smallint,
	      @to_CodCfoNorInt smallint,
          @to_CodCfoNorExt smallint,
          @to_CodCfoSbtInt smallint,
          @to_CodCfoSbtExt smallint,
          @to_CodCfoSubstituidoInt smallint,
          @to_CodCfoSubstituidoExt smallint,
          @to_FlgLanFin bit,
          @to_FlgBlqImpVol bit,
          @to_FlgCalPisCof bit,
          @to_IsnCtaFinDeb int,
          @to_IsnCtaFinDebInterv int,
          @to_IsnCtaFinCre int,
          @cf_FlgBlqTrfEstFis bit,
          @WCodCfoNor smallint,
          @WCodCfoSbt smallint,
          @WCodCfoBon smallint,
          @WFlgOpeInt bit,
          @WFlgRecalcula bit,
          @WVlrAux numeric(18,4)

  Select @to_CodCfoConFinInt = IsNull(Cod_CfoConFinInt,0),
	     @to_CodCfoConFinExt = IsNull(Cod_CfoConFinExt,0),
	     @to_CodCfoNorInt = Isnull(Cod_CfoNorInt,0),       
         @to_CodCfoNorExt = Isnull(Cod_CfoNorExt,0),
         @to_CodCfoSbtInt = Case 
		                      When @em_FlgContriSubstituido = 1 and IsNull(Cod_CfoSbtIntSubstituido,0) > 0 then Cod_CfoSbtIntSubstituido
							  Else Isnull(Cod_CfoSbtInt,0)
							End, 
         @to_CodCfoSbtExt = Case 
		                      When @em_FlgContriSubstituido = 1 and IsNull(Cod_CfoSbtExtSubstituido,0) > 0 then Cod_CfoSbtExtSubstituido
							  Else Isnull(Cod_CfoSbtExt,0)
							End, 
         @to_CodCfoSubstituidoInt = IsNull(Cod_CfoSbtIntSubstituido,0),
         @to_CodCfoSubstituidoExt = IsNull(Cod_CfoSbtExtSubstituido,0),
         @to_FlgLanFin = Isnull(Flg_LanFin,0),
         @to_FlgBlqImpVol = IsNull(Flg_BlqImpVol,0), 
         @to_FlgCalPisCof = IsNull(Flg_CalPisCof,0),
         @to_IsnCtaFinDeb = ISNULL(Isn_CtaFinDeb,0),
         @to_IsnCtaFinCre = ISNULL(Isn_CtaFinCre,0)
    From TPOPE
   Where Cod_Ope = @cb_TipFat 

  -- plano de contas   
  if (Select IsNull(FlgUsaInterv,0) From PMFIN) = 0
    begin
      Set @to_IsnCtaFinDeb = IsNull((Select Isn_CtaFin From CLIEN Where Codigo = @cb_CodCli),0)
      Set @to_IsnCtaFinCre = 0
    end
  else
    begin
      Set @to_IsnCtaFinDebInterv = 0
      if not Exists(Select 1 From PCFIN Where Isn_CtaFin = @to_IsnCtaFinDeb)
        Set @to_IsnCtaFinDeb = 0
      if not Exists(Select 1 From PCFIN Where Isn_CtaFin = @to_IsnCtaFinCre)
        Set @to_IsnCtaFinCre = 0
    
      if (@to_IsnCtaFinDeb = 0) or (@to_IsnCtaFinCre = 0)
        begin
          Set @to_IsnCtaFinDeb = 0
          Set @to_IsnCtaFinCre = 0
        end
      else
        if @to_IsnCtaFinDeb = (Select IsnCtaFinRecCli From PMFIN) 
          begin
            Set @to_IsnCtaFinDebInterv = IsNull((Select Isn_CtaFin From CLIEN Where Codigo = @cb_CodCli),0)
            if @to_IsnCtaFinDebInterv > 0
              Set @to_IsnCtaFinDeb = @to_IsnCtaFinDebInterv
          end
      if @to_IsnCtaFinDeb = @to_IsnCtaFinCre
        begin
         Set @to_IsnCtaFinDeb = 0
         Set @to_IsnCtaFinCre = 0
        end    
    end
     
  -- operacao interna ou externa
  if @cl_CodEst = @em_CodEst
    Set @WFlgOpeInt = 1
  else
    Set @WFlgOpeInt = 0

  if @rt_FlgConsumFin = 1
    if @WFlgOpeInt = 1
	  begin
        Set @WCodCfoNor = @to_CodCfoConFinInt
        Set @WCodCfoSbt = @to_CodCfoConFinInt
        Set @WCodCfoBon = 5910
      end
    else
	  begin
        Set @WCodCfoNor = @to_CodCfoConFinExt
        Set @WCodCfoSbt = @to_CodCfoConFinExt
        Set @WCodCfoBon = 6910
      end
  else
    if @WFlgOpeInt = 1
      begin
        Set @WCodCfoNor = @to_CodCfoNorInt
        Set @WCodCfoSbt = @to_CodCfoSbtInt
        Set @WCodCfoBon = 5910
	  end
    else
      begin
        Set @WCodCfoNor = @to_CodCfoNorExt
        Set @WCodCfoSbt = @to_CodCfoSbtExt
        Set @WCodCfoBon = 6910
      end

  -- coloca campos de NMFIS na memoria
  Declare @nm_NotFis int,
          @nm_SerNotFis int,
          @nm_ModNotFis varchar(2)

  if @pm_FlgNfe = 1
    begin
      -- verifica serie especifica para "incentivos"
      if Exists(Select ix.Ser_NfeEsp
                  From PDVCB cb
                       Inner Join ESXIF ix on cb.Cod_Estabe = ix.Cod_Estabe and cb.Id_IncFis = ix.Id_IncFis
                 Where cb.Cod_Estabe = @CodEstabe
                   And cb.Numero = @CodPed
                   And IsNull(ix.Ser_NfeEsp,0) > 0)
        if not Exists(Select ix.Ser_NfeEsp
                        From PDVCB cb
                             Inner Join ESXIF ix on cb.Cod_Estabe = ix.Cod_Estabe and cb.Id_IncFis = ix.Id_IncFis
                             Left  Join NMNFE nm on cb.Cod_Estabe = nm.Cod_Estabe and ix.Ser_NfeEsp = nm.Ser_Nfe
                       Where cb.Cod_Estabe = @CodEstabe
                         And cb.Numero = @CodPed
                         And IsNull(ix.Ser_NfeEsp,0) > 0
                         And IsNull(nm.Ser_Nfe,0) > 0)
          begin
            Insert Into NMNFE (Cod_Estabe, Ser_Nfe, Num_Nfe, Flg_Padrao, Flg_Contingencia, Mod_Nfe)
              Select cb.Cod_Estabe, ix.Ser_NfeEsp, 0, 0, 0, '55'
                From PDVCB cb
                     Inner Join ESXIF ix on cb.Cod_Estabe = ix.Cod_Estabe and cb.Id_IncFis = ix.Id_IncFis
               Where cb.Cod_Estabe = @CodEstabe
                 And cb.Numero = @CodPed
		  end

      -- poe dados de NMNFE na memoria
      if Exists(Select ix.Ser_NfeEsp
                  From PDVCB cb
                       Inner Join ESXIF ix on cb.Cod_Estabe = ix.Cod_Estabe and cb.Id_IncFis = ix.Id_IncFis
                       Inner Join NMNFE nm on cb.Cod_Estabe = nm.Cod_Estabe and ix.Ser_NfeEsp = nm.Ser_Nfe
                 Where cb.Cod_Estabe = @CodEstabe
                   And cb.Numero = @CodPed
                   And IsNull(ix.Ser_NfeEsp,0) > 0)
        Select @nm_SerNotFis = ix.Ser_NfeEsp
          From PDVCB cb
               Inner Join ESXIF ix on cb.Cod_Estabe = ix.Cod_Estabe and cb.Id_IncFis = ix.Id_IncFis
               Left Join NMNFE nm on cb.Cod_Estabe = nm.Cod_Estabe and ix.Ser_NfeEsp = nm.Ser_Nfe
          Where cb.Cod_Estabe = @CodEstabe
          And cb.Numero = @CodPed
          And IsNull(nm.Ser_Nfe,0) > 0
      else
        Select @nm_SerNotFis = Ser_Nfe
          From NMNFE
         Where Cod_Estabe = @CodEstabe 
           And Flg_Padrao = 1

      Select @nm_NotFis = Num_Nfe,
             @nm_ModNotFis = Mod_Nfe
        From NMNFE
       Where Cod_Estabe = @CodEstabe 
         And Ser_Nfe = @nm_SerNotFis
    end
  else
    begin
      Select @nm_NotFis = Nota_Fiscal_M1
        From NMFIS
       Where Cod_Estabe = @CodEstabe
    end

  -- variaveis de trabalho
  Declare @WQtdMov int,
          @WQtdPraNeg int,
          @WQtdDepNeg int,
          @WFlgEmpPra bit,
          @WFlgEmpDep bit,
          @WQtdMovLot int,
          @WQtdMovPed int,
          @WQtdMovBon int,
          @WQtdMovPra int,
          @WQtdMovDep int,
		  @WQtdDifDia int,
          @WTipNfs varchar(1),
          @WCodTabComOpe int,
          @WCodTabComVdr int,
          @WSumVlrBasDscIte numeric(18,4),
          @WCVlrTotNot numeric(18,4),
          @WVlrTotLiq numeric(18,4),
          @WVlrDesc numeric(18,4),
          @WVlrTotDspBolBan numeric(18,4),
          @WVlrJurPrzExc numeric(18,4),
          @WVlrBasFre numeric(18,4),
          @WCodDoc int,
          @WQtdPrdVrb int,
          @WPerRetBon numeric(18,4),
          @WCodPrm int,  -- codigo da promocao ou flag de politica promocional
          @WTipSai varchar(1),  -- 'B' = bonificacao
          @WVlrBasComiss numeric(18,4), 
          @WTipDes varchar(3),
          @WCodDes int,
          @WVlrMov numeric(18,4),
          @WIdTransacao int,
          @WCodFor int,
          @WVlrEdi numeric(18,4),
          @WVlrBru numeric(18,4),
          @WVlrLiqIte numeric(18,4),
          @WVlrLiqIteCusMed numeric(18,4)

          
  Set @PDatEmi = @Date
  Set @PEspNfs = ''
  Set @SerNfsRet = @cb_TipFat  -- FAT,ORC,FUN
  if @CodEstabe is null
    Set @CodEstabe = 0
  Set @NumNfsRet = @CodPed
  Set @PSerSel = ''
  Set @PNumSel = 0
  Set @PNumFor = 0
  Set @PQtdPagNfs = 0
  Set @PModNotFis = ''
  Set @PCodStaNfe = ''

  if @WCodCfoNor > 0
    begin
      Set @PEspNfs = 'NFF'
      Set @PQtdPagNfs = 0
      Set @PNumFor = 0
      Set @NumNfsRet = @nm_NotFis + 1

      if @pm_FlgNfe = 1 
        begin
          Set @SerNfsRet = cast(@nm_SerNotFis as varchar)
          Set @PModNotFis = @nm_ModNotFis
          Set @PCodStaNfe = 'N'         
		  exec PR_ProximoNumFiscal @CodEstabe, '', @nm_SerNotFis, 1, @NumNfsRet;
        end
      else
        begin
          Set @SerNfsRet = @pm_ModeloNotaFiscal    -- FAT para M1
          Set @PModNotFis = @pm_ModeloNotaFiscal
          Set @PCodStaNfe = ''
          if @pm_NumItePagNfs > 0
            Set @PQtdPagNfs = Ceiling(@cb_QtdIte*1.00 /@pm_NumItePagNfs)
          Set @PNumFor = @NumFor + @PQtdPagNfs - 1
          -- atualiza NMFIS
          if @pm_FlgCtrSelFis = 1
            begin
              Set @PSerSel = @pm_SerieSeloFiscal
              Set @PNumSel = @NumSel + @PQtdPagNfs - 1
              Update NMFIS
                 Set Nota_Fiscal_M1 = @NumNfsRet,
                     Formulario_M1 = @PNumFor,
                     Selo_Fiscal = @PNumSel
               Where Cod_Estabe = @CodEstabe    
            end
          else
            begin
              Update NMFIS
                 Set Nota_Fiscal_M1 = @NumNfsRet,
                     Formulario_M1 = @PNumFor
               Where Cod_Estabe = @CodEstabe    
            end
        end
    end

  if (@cb_TipVct <> 'V') and (@cb_TipVct <> 'A')
    Set @PTipVct = 'P'   -- parcelado
  else
    Set @PTipVct = @cb_TipVct

  Set @PVlrDscCom = 0
  Set @WSumVlrBasDscIte = 0
  if @cb_PerDscCom > 0
    begin
      Set @PVlrDscCom = Round((@cb_VlrBasDscCom - @cb_VlrRepIcm) * @cb_PerDscCom/100,2)
      Set @WSumVlrBasDscIte = IsNull((Select sum(Round(Qtd_Pedido*C_PrcUni*(1-C_PerDscIte/100),2)-Vlr_RepIcms)
                                        From PDVIT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed
                                         And Desconto = 0 And Qtd_Pedido > 0),0)
      if @PVlrDscCom > @WSumVlrBasDscIte
        begin
          Set @PVlrDscCom = 0
          Set @cb_PerDscCom = 0
        end
     end
    
  -- registra tipo de retencao do imp. subst.
  -- se nao tem credenciamento no estado: nao retem na fonte
  -- F- imposto incluido no valor da NF
  -- R- imposto a recolher, nao incluido na NF mas cobrado na duplicata
  Set @PTipRetImp = 'F'
  if @to_CodCfoNorInt > 0  
    if @uf_FlgRegSubTri = 0
      Set @PTipRetImp = 'R'

  if @PTipRetImp = 'R'
    Set @PVlrTotNot = @cb_VlrLiqIte - @PVlrDscCom - @cb_VlrDscBon - @cb_VlrRepIcm + @cb_VlrDespes + @cb_VlrDspExt + @cb_VlrIpi + @cb_VlrSbtRes
  else
    Set @PVlrTotNot = @cb_VlrLiqIte - @PVlrDscCom - @cb_VlrDscBon - @cb_VlrRepIcm + @cb_VlrDespes + @cb_VlrDspExt + @cb_VlrIpi + @cb_VlrSbtRes + @cb_VlrSubTri - @cb_VlrDscTri

  if @cb_FlgVlrFin = 1
    if (@WCodCfoNor > 0) or (@SerNfsRet = 'ORC') or (@to_FlgLanFin = 1)
      begin
        -- recalcula prazo medio, qtd parcelas e desc. financ. ponderado da nf
        Declare @WSomat numeric(18,4), 
                @WVlrDup numeric(18,4), 
                @WVlrFin numeric(18,4)

        Set @PQtdPar = Isnull((Select COUNT(*)
                                 From PDVDP
                                Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed),0)
                
        Set @WSomat = Isnull((Select sum(Vlr_Duplic*cast(Dat_Vencim - @cb_DatPed as int))
                                From PDVDP
                               Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed
                                 And IsNull(Flg_Apresentacao,0)=0),0)
        
        Set @WVlrDup = Isnull((Select sum(Vlr_Duplic)
                                 From PDVDP
                                Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed),0)
                
        Set @WVlrFin = Isnull((Select sum(Vlr_DescFinanc)
                                 From PDVDP
                                Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed),0)
                
        -- atualiza cabecalho da NF
        if @WVlrDup > 0 
          begin
            Set @PQtdPrzMed = Round(@WSomat/@WVlrDup,0)
            if @cb_TipVct <> 'P'    --nao ponderado
              Set @PPerDscFinLiq = Round(@WVlrFin*100/@WVlrDup,4) 
          end
        else
          begin
            Set @PQtdPrzMed = 0
            Set @PPerDscFin = 0
          end
      end

  -- recalcula desconto financeiro (aplicar somente sobre valor tot. mercadoria) p/ gravar no item
  Set @PPerDscFin = IsNull(@PPerDscFinLiq,0)
  if ((@cb_VlrSubTri+@cb_VlrSbtRes) > 0) and (@PPerDscFinLiq > 0)
    begin
      Set @WVlrTotLiq = @cb_VlrLiqIte - @PVlrDscCom - @cb_VlrDscBon - @cb_VlrRepIcm - @cb_VlrDscTri 
      Set @WVlrDesc = @PPerDscFinLiq * @WVlrTotLiq / 100
      Set @WVlrTotLiq = @WVlrTotLiq + @cb_VlrSubTri + @cb_VlrSbtRes
      if @WVlrTotLiq > 0 
        Set @PPerDscFin = Round(@WVlrDesc/@WVlrTotLiq*100,2)
    end

  -- calcula despesa ref. taxa administrativa
  Set @WVlrOutDsp = 0.00     
  if @ag_PerTaxAdm > 0
    begin
      if @ag_CodAplTaxAdm = 'P' -- margem (participação)
        Set @WVlrOutDsp = Round(@cb_VlrLiqIte/(1-@ag_PerTaxAdm/100),2)-Round(@cb_VlrLiqIte,2)
      if @ag_CodAplTaxAdm = 'A'  -- mark-up (acrescimo)
        Set @WVlrOutDsp = Round(@cb_VlrLiqIte*@ag_PerTaxAdm/100,2)     
    end

  -- calcula despesa boleto bancario a cobrar na nota fiscal
  Set @WVlrTotDspBolBan = 0
  if @to_FlgLanFin = 1
    begin
      Set @WVlrTotDspBolBan = Round(Isnull(@ag_VlrDspBolBan,0) * @PQtdPar,2)
      Set @WVlrOutDsp = @WVlrOutDsp + @WVlrTotDspBolBan
    end

  -- debito verba/despesa de boleto vendedor
  Set @PVlrDebVrbVdr = 0
  if @TipNfs = 'V'
    begin
      -- taxa boleto
      if @pm_FlgDebBlqBanVrbVdr = 1
        begin
          Set @PVlrDebVrbVdr = @WVlrTotDspBolBan
          Set @WVlrOutDsp = @WVlrOutDsp - @WVlrTotDspBolBan    -- isenta cliente
        end
      -- juros prazo excedente
      Set @WVlrJurPrzExc = 0
      Set @WQtdDifDia = cast(@PQtdPrzMed as int) - @pm_QtdPrzMedCfg
      if (@WQtdDifDia > 0) and (@pm_QtdPrzMedCfg > 0) and (@pm_PerCusFinDiaExcPrzMedCfg > 0)
        begin
          Set @WVlrJurPrzExc = @WQtdDifDia*@pm_PerCusFinDiaExcPrzMedCfg*@PVlrTotNot/100
          Set @PVlrDebVrbVdr = @PVlrDebVrbVdr + @WVlrJurPrzExc
        end   
    end

  if @cb_VlrDespes <> @WVlrOutDsp
    Set @PVlrOutDsp = @WVlrOutDsp
  else
    Set @PVlrOutDsp = @cb_VlrDespes

  if @cb_CodCli > 0
    begin
      Set @PCgc = @cl_CgcCpf
      Set @PCgf = @cl_Cgf
      Set @PDesEnd  = Substring(@cl_DesEnd,1,50)
      Set @PDesBai = @ba_DesBai
      Set @PCep = @cl_Cep
      Set @PEst = @cl_CodEst
      Set @PDesCid = @ci_DesCid
      Set @PCodCid = @cl_CodCid
      Set @PCodCidIbge = @ci_CodCidIbge
      Set @PCodMacReg = @ba_CodMacReg 
      Set @PCodMicReg = @ba_CodMicReg
     end
  else
    begin
      Set @PCgc = ''
      Set @PCgf = ''
      Set @PDesEnd  = ''
      Set @PDesBai = ''
      Set @PCep = @em_Cep 
      Set @PEst = @em_CodEst
      Set @PDesCid = (Select Descricao From CIDAD Where Cod_Estado = @em_CodEst And Codigo = @pm_CodCidEmpLoc)
      Set @PCodCid = @pm_CodCidEmpLoc
      Set @PCodCidIbge = (Select Cod_CidIbge From CIDAD Where Cod_Estado = @em_CodEst And Codigo = @pm_CodCidEmpLoc)
      Set @PCodMacReg = @pm_CodMacRegEmpLoc
      Set @PCodMicReg = @pm_CodMicRegEmpLoc
    end

  -- Grava registro NFSCB 
  if (@cb_VlrSubTri+@cb_VlrSbtRes) > 0
    Set @PCodCfo = @WCodCfoSbt
  else
    Set @PCodCfo = @WCodCfoNor

  Set @PUfPlaVei = @cb_UfPlaVei
  Set @PCodPlaVei = @cb_CodPlaVei
  if (@PUfPlaVei = '') and (@tr_Pessoa = 'F')
    begin
      Set @PUfPlaVei = @tr_UfPlaVei
      Set @PCodPlaVei = @tr_CodPlaVei
    end

  -- registra Insc.Est. ST do emitente na UF destino
--  if (@WFlgOpeInt = 0) and (@uf_FlgRegSubTri= 1) and (@uf_BlqInsEstSbtNfs = 0)
  if @uf_FlgRegSubTri= 1
    Set @PNumInscriSbtEmiUfd = @uf_NumInscriSbt
  else
    Set @PNumInscriSbtEmiUfd = ''


  -- aqui cuidado: implementar em PR_AtualizaCabecNFS ou PR_CalcTributNFS ?????
  if @PTipRetImp = 'R'
    begin
      Set @PVlrSubTri = 0
      Set @PVlrDscTri = 0
      Set @PVlrRecSbt = @cb_VlrSubTri
	  if @cb_VlrSubTri >= @cb_VlrDscTri
        Set @PVlrRecSbt = @cb_VlrSubTri - @cb_VlrDscTri
    
	  Set @PVlrFcpSbt = 0
	  Set @PVlrFcpSbtRec = @cb_VlrSubTriFcp 
    end
  else
    begin
      Set @PVlrSubTri = @cb_VlrSubTri
      Set @PVlrDscTri = @cb_VlrDscTri
      Set @PVlrRecSbt = 0

	  Set @PVlrFcpSbt = @cb_VlrSubTriFcp
	  Set @PVlrFcpSbtRec = 0
    end


  Insert into NFSCB (Cod_Estabe, Ser_Nota, Num_Nota)
    Values (@CodEstabe, @SerNfsRet, @NumNfsRet)
  if @@error <> 0
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end    

  Select @cf_FlgBlqTrfEstFis = IsNull(Flg_BlqTrfEstFis,0) 
    From TBCFO 
   Where Codigo = @PCodCfo

  Update NFSCB 
     Set Esp_Nota = @PEspNfs, 
         Qtd_PagNf = @PQtdPagNfs, 
         Ser_Selo = @PSerSel, 
         Num_Selo = @PNumSel, 
         Num_Formulario = @PNumFor,
         Cod_Cfo1 = @PCodCfo,
         Flg_BlqTrfEstFis = IsNull(@cf_FlgBlqTrfEstFis,0),
         Flg_WMS = @WFlgWMS, 
         Cod_ModDoc = @PModNotFis, 
         Cod_StaNfe = @PCodStaNfe, 
         Flg_RetEnt = 0, 
         Flg_Storage = 0,  
         Flg_Email = 0,

         Tip_Vencimento = @PTipVct,
         Dat_Emissao = @PDatEmi, 
         Cod_Cliente = @cb_CodCli, 
         Tip_Consumidor = @cb_TipCon, 
         Cod_Funcionario = @cb_CodFun, 
         Consumidor = @cb_NomCon, 
         Cod_Pedido = @CodPed,  
         Cod_OrigemNfs = @cb_CodOriPdv,
         Cod_Digitador = @cb_CodDig,  
         Cod_VendTlmkt = @cb_CodOpe, 
         Cod_Vendedor = @cb_CodVdr, 
         Cod_Supervisor = @cb_CodSup, 
         Cod_Gerencia = @cb_CodGer, 
         Cod_SupOpe = @cb_CodSupOpe,  
         Cod_GerOpe = @cb_CodGerOpe, 
         Cod_Agente = @cb_CodAgc,  
         Cod_Transportadora = @cb_CodTra, 
         Cod_Rota = @cb_CodRot, 
         Cod_Ope = @cb_TipFat,
         Cod_RamAtv = @cl_CodRamAtv, 

         Vlr_FrePrv = @cb_VlrFrePrv, 
         Qtd_PrzMed = @PQtdPrzMed, 
         Qtd_Parcela = @PQtdPar, 
         Id_PolCom = @cb_IdPolCom, 
         Per_Faturado = cast(@cb_PerSubFat as int), 
         Num_NotSubFat = 0,  
         Per_DescontoFin = @PPerDscFin, 
         Per_DscFinLiq = @PPerDscFinLiq, 

         Qtd_Peso = @cb_QtdPes, 
         Qtd_Volumes = @cb_QtdVol, 

         Vlr_BasDscCom = @cb_VlrBasDscCom, 
         Vlr_BasPar = @cb_VlrBasPar, 

         Cod_RegTri = @cb_CodRegTri,
         Flg_IcmsSobreTotal = @rt_CtrImpIcmTotNfs, 
         Num_InscriSubTriEmiUfd = @PNumInscriSbtEmiUfd, 
         Inscricao_Suframa = @cb_InscricaoSuframa, 
         Vlr_SubsTribEmb = 0,

         Per_DescontoCom = @cb_PerDscCom, 
         Vlr_DscBon = @cb_VlrDscBon, 

         Cgc = @PCgc,  
         Cgf = @PCgf, 
         Endereco = @PDesEnd, 
         Bairro = @PDesBai, 
         Cep = @PCep, 
         Estado = @PEst, 
         Cidade = @PDesCid, 
         Cod_Cidade = @PCodCid, 
         Cod_CidIbge = @PCodCidIbge, 
         Cod_MacroReg = @PCodMacReg, 
         Cod_MicroReg = @PCodMicReg,

         Flg_ComisNormal = @PFlgComNor,  
         Per_ComOpe = @PPerComOpe,  
         Per_ComVnd = @PPerComVnd, 
         Per_ComSup = 0, 
         Per_ComGer = 0, 
         Per_ComSupOpe = 0,  
         Per_ComGerOpe = 0,
         Vlr_ComPagTlmkt = 0,  
         Vlr_ComPag = 0, 
         Vlr_ComPagSup = 0, 
         Vlr_ComPagGer = 0, 
         Vlr_ComPagSupOpe = 0, 
         Vlr_ComPagGerOpe = 0,

         Ide_PedCmp = @cb_CodPedCmpCli,  
         Ide_NotEmp = @cb_NotEmpCli, 
         Ide_Contra = @cb_NumConCli, 
         Des_Convenio = @cb_DesConven, 
         Des_LayoutPde = @cb_DesLayPde, 
         Cod_PrjPde = @cb_CodPrjPde,
         Cod_PedCliPde = @cb_CodPedCliPde,

         Flg_BlqImpVol = @to_FlgBlqImpVol, 
         Uf_PlaVei = @PUfPlaVei, 
         Cod_PlaVei = @PCodPlaVei, 
         Cod_Contrato = @cb_CodCtr, 
         Id_Consig = @cb_IdConsig,  
         Num_SequenciaCtr = @cb_NumSeqCtr,
         
         Vlr_DebVrbVdr = @PVlrDebVrbVdr, 
         Tip_GerVrb = @cb_TipGerVrb, 
         
         -- atualizados em PR_AtualizaCabecNFS
         Tip_Frete = @cb_TipFrete, 
         Qtd_Itens = @cb_QtdIte, 
         Vlr_LiqItens = @cb_VlrLiqIte,  
         VlrBruItens = 0, 
         Vlr_DescontoCom = @PVlrDscCom, 
         Vlr_OutDsp = @PVlrOutDsp, 
         Vlr_TotalNota = (@PVlrTotNot + @PVlrOutDsp),
         Vlr_Frete = @cb_VlrFrete, 
         Vlr_DspExt = @cb_VlrDspExt, 
         Vlr_BasRepIcms = 0, 
         Vlr_RepIcms = @cb_VlrRepIcm, 
         Vlr_PrdSubTri = 0, 
         Vlr_BasSubsTrib = 0, 
         Vlr_BasSbtRes = 0,
         Vlr_BasRecSbt = 0, 
         Vlr_BasIcmsNor = 0, 
         Vlr_IcmsNor = 0, 
         Vlr_BasIcmsTri = 0, 
         Vlr_IcmsTri = 0, 
         Vlr_BasIpi = 0,
         Vlr_Ipi = 0, 
         Vlr_Isento = 0, 
         Vlr_Outros = 0, 

         -- dependem de NFSCB.Tip_RetImp: @PTipRetImp  
         Tip_RetImp = @PTipRetImp,
         Vlr_SubsTrib = @PVlrSubTri, 
         Vlr_DscTri = @PVlrDscTri, 
         Vlr_RecSbt = @PVlrRecSbt, 
         Vlr_FcpSbt = @PVlrFcpSbt, 
         Vlr_FcpSbtRec = @PVlrFcpSbtRec, 

         Vlr_ComTlmkt = 0,  
         Vlr_Comissao = 0, 
         Vlr_ComSup = 0, 
         Vlr_ComGer = 0, 
         Vlr_ComSupOpe = 0, 
         Vlr_ComGerOpe = 0, 
         Val_ComTra = 0,

         Obs_Rodape = @cb_ObsNfs, 
         Usuario = @DesUsu, 
         Transacao = @Now,
		 Vlr_BasIrf = @cb_VlrBasIrf,
		 Vlr_Irf = @cb_VlrIrf

   Where Cod_Estabe = @CodEstabe
     And Ser_Nota = @SerNfsRet
     And Num_Nota = @NumNfsRet

  -- variaveis a gravar em NFSIT
  Declare @P_PerDsc numeric(18,4),
          @P_NumSeqIte int,
          @P_CodCfo smallint,
          @P_PrcCusMed numeric(18,4),
          @P_PrcCusCom numeric(18,4),
          @P_FlgIncFis bit,
          @P_VlrBruIte numeric(18,4),
          @P_VlrTotIte numeric(18,4),
          @P_VlrDscIte numeric(18,4),
          @P_VlrDscRat numeric(18,4),
          @P_VlrLiqIte numeric(18,4),
          @P_VlrLiqVenIte numeric(18,4),
          @P_PerComOpe numeric(18,4),
          @P_VlrComOpe numeric(18,4),
          @P_PerComVnd numeric(18,4),
          @P_VlrComVnd numeric(18,4),
          @P_PerComSup numeric(18,4),
          @P_VlrComSup numeric(18,4),
          @P_PerComGer numeric(18,4),
          @P_VlrComGer numeric(18,4),
          @P_PerComSupOpe numeric(18,4),
          @P_VlrComSupOpe numeric(18,4),
          @P_PerComGerOpe numeric(18,4),
          @P_VlrComGerOpe numeric(18,4),
          @P_FlgComNor bit,
          @P_PerComTra numeric(18,4),
          @P_VlrComTra numeric(18,4),
          @P_PerDscFin numeric(18,4),
          @P_PerVrbPar numeric (18,4),
          @P_VlrVrbPar numeric(18,4),
          @P_PerVrbBon numeric (18,4),
          @P_VlrVrbBon numeric(18,4),

          -- wms:
          @P_CodLot varchar(20),
          @P_QtdPed int,
          @P_QtdBon int,
          @P_QtdPra int,
          @P_QtdDep int,
          @P_QtdImpFat numeric(18,4),
          @P_VlrDscBonRat numeric(18,4),
          @P_VlrDespes numeric(18,4),
          @P_VlrDspExt numeric(18,4),
          @P_VlrBasIcmNor numeric (18,4),
          @P_VlrIcmNor numeric (18,4),
          @P_VlrBasRepIcm numeric (18,4),
          @P_VlrRepIcm numeric (18,4),
          @P_VlrPrdSubTri numeric (18,4),
          @P_VlrBasSubTri numeric (18,4),
          @P_VlrSubTri numeric (18,4),
          @P_VlrBasSbtRes numeric (18,4),
          @P_VlrSbtRes numeric (18,4),
          @P_VlrBasDscTri numeric (18,4),
          @P_VlrDscTri numeric (18,4),
          @P_VlrBasRecSbt numeric (18,4),
          @P_VlrRecSbt numeric (18,4),
          @P_VlrBasIcmTri numeric (18,4),
          @P_VlrIcmTri numeric (18,4),
          @P_VlrIcmDiferi numeric(18,4),
          @P_VlrIsento numeric (18,4),
          @P_VlrOutros numeric (18,4),
          @P_VlrBasTri numeric (18,4),

          @P_VlrBasVerba numeric(18,4),
          @P_VlrVerba numeric(18,4),
          @P_VlrVrbVdr numeric(18,4),
          @P_VlrVrbOpe numeric(18,4),
          @P_VlrVrbSup numeric(18,4),

          @P_VlrBonificacao numeric (18,4),
          @P_VlrDscBonDup numeric (18,4),
          @P_VlrIcmDesone numeric (18,4),
          @P_VlrDscCalSuframa numeric (18,4),
          
          -- FCP
          @P_VlrIcmParDes numeric(18,4),
          @P_VlrIcmParRem numeric(18,4),
          @P_VlrIcmFcpDes numeric (18,4), 
          @P_VlrFcpIcm numeric(18,4),
          @P_VlrFcpSbt numeric(18,4),
          @P_VlrFcpSbtRec numeric(18,4),
          @P_VlrFcpSbtRet numeric(18,4),

          -- IPI
          @P_VlrBasIpi numeric(18,4), 
          @P_VlrIpi numeric(18,4),

          -- pis/cofins
          @P_CstPis varchar(2),
          @P_VlrBasPis numeric(18,4),
          @P_AlqPis numeric(7,4),
          @P_VlrPis numeric(18,4),
          @P_CstCof varchar(2),
          @P_VlrBasCof numeric(18,4),
          @P_AlqCof numeric(7,4),
          @P_VlrCof numeric(18,4),
		  @P_ObsNf varchar(200),
          @WVlrBasPisCof numeric(18,4)
                 
  Declare @it_CodPrd int,
          @it_CodLot varchar(20),
          @it_TipSai varchar(1),
          @it_QtdSol int,
          @it_QtdPra int,
          @it_QtdDep int,
          @it_PerDsc numeric(7,4),
          @it_CPerDscIte numeric (18,4),
          @it_PrcUni numeric(18,8),
          @it_PrcUniSemAcrIcm numeric(18,8),
          @it_FlgPrcUniAcrIcm bit,
          @it_PrcUniComAcrIcm numeric(18,8),
          @it_CPrcUni numeric (18,8),
          @it_CodPrjPde varchar(12),
          @it_PrcUniPde numeric (18,8),
          @it_PerDscPde numeric(7,4),
          @it_NumSeqPdc varchar(6),
          @it_PrcTab numeric (18,4),
          @it_PrcTabBru numeric (18,4),
          @it_PrcFab numeric (18,4),
          @it_PrcMax numeric (18,4),
          @it_PrcRefFpb numeric (18,4),
          @it_FlgPrcUniDsc bit,
          @it_FlgBlqInfPar bit,
          @it_CodPrm int, 
          @it_FlgPolPrm bit,
          @it_TipAux varchar(1),
          @it_CodClaTri varchar(4),
          @it_CodCst varchar(2),
          @it_CodCsosn varchar(3),
          @it_FlgBlqDsc bit,
          @it_PerDscVis numeric (7,4),
          @it_PerDscPrz numeric (7,4),
          @it_FatCnvImpFat int,
          @it_PrcUniImpFat numeric(18,8),
          @it_DesUnvImpFat varchar(3),
          @it_DesAprImpFat varchar(12),
          @it_IdPolCom int, 
          @it_AlqIcm numeric (7,4),
		  @it_CodKitPrm int,
		  @it_FlgUsaDebPresum bit,
		  @it_AlqIcmPresum numeric (7,4),
          @it_PerLucBru numeric (18,4),
		            
          -- campos calculados
          @it_VlrBruIte numeric(18,4),
          @it_VlrTotIte numeric(18,4),
          @it_VlrLiqIte numeric(18,4),
          ------------------------------------------------------
          @it_QtdPed int,
          @it_QtdBon int,
          @it_QtdImpFat numeric(18,4),
          @it_VlrBasIcmNor numeric (18,4),
          @it_VlrIcmNor numeric (18,4),
          @it_VlrBasRepIcm numeric (18,4),
          @it_PerRepIcm numeric (7,4),
          @it_VlrRepIcm numeric (18,4),
          @it_VlrPrdSubTri numeric (18,4),
          @it_VlrBasSubTri numeric (18,4),
          @it_VlrSubTri numeric (18,4),
          @it_VlrBasSbtRes numeric (18,4),
          @it_VlrSbtRes numeric (18,4),
          @it_VlrBasDscTri numeric (18,4),
          @it_PerDscTri numeric (7,4),
          @it_VlrDscTri numeric (18,4),
          @it_VlrBasIcmTri numeric (18,4),
          @it_VlrIcmTri numeric (18,4),
          @it_PerIcmDiferi numeric (9,4),
          @it_VlrIcmDiferi numeric (18,4),
          @it_VlrIsento numeric (18,4),
          @it_VlrOutros numeric (18,4),
          @it_VlrDscBonRat numeric (18,4),
          @it_VlrDespes numeric (18,4),
          @it_VlrDspExt numeric (18,4),
          @it_VlrBru numeric (18,4),
          @it_VlrDscBonDup numeric (18,4),
          @it_VlrBonificacao numeric (18,4),
          @it_PrcCusMinComMarkup numeric (18,4),             

          @it_VlrBasVerba numeric (18,4),
          @it_VlrVerba numeric (18,4),
          @it_VlrVrbVdr numeric (18,4),
          @it_VlrVrbOpe numeric (18,4),
          @it_VlrVrbSup numeric (18,4),

          @it_PrcPolCom numeric (18,8),
          @it_PerDscPolCom numeric (7,4),

          @it_CodModBasCalIcm varchar(1),
          @it_CodModBasCalIcmSbt varchar(1),
          @it_VlrBasTri numeric (18,8),
          @it_PerRedBasCalIcm numeric (18,4),
          @it_PerRedBasCalIcmSbt numeric (18,4),
          @it_AlqIcmSbt numeric (7,4),
          @it_AlqAgrSbt numeric (7,4),
          
          @it_AlqIntIcmDes numeric(7,4), 
          @it_PerPrvParIcm numeric(18,4),
          @it_VlrIcmParDes numeric(18,4),
          @it_VlrIcmParRem numeric(18,4),

          @it_PerAcrAlqIntFcp numeric(7,4), 
          @it_VlrIcmFcpDes numeric(18,4),

          @it_AlqFcpIcm numeric(7,4),
          @it_VlrFcpIcm numeric(18,4),
          @it_AlqFcpSbt numeric(7,4),
          @it_VlrFcpSbt numeric(18,4),
          @it_AlqFcpSbtRet numeric(7,4),
          @it_VlrFcpSbtRet numeric(18,4),

          @it_VlrIcmDesone numeric(18,4),
          @it_CodMtvIcmDesone varchar(1),
          @it_VlrDscCalSuframa numeric(18,4),
          @it_FlgIncFis bit,

          @it_CodOriMer varchar(1), 
          @it_VlrBasIpi  numeric(18,4),
          @it_VlrIpi numeric(18,4),
          @it_AlqIpi numeric(7,4), 
          @it_CstIpi varchar(2), 
          @it_CodEnqIpi varchar(3),

          @lt_Chave int,
          @lt_CodLot varchar(20), 
          @lt_QtdIte int,
          @lt_QtdLot int, 
          @lt_QtdCxaFec int, 
          @lt_QtdPra int, 
          @lt_QtdDep int,
          @lt_CodDep smallint,
          @lt_NumRua smallint,
          @lt_NumCol smallint,
          @lt_NumNiv smallint,
          @lt_NumApt smallint,
          @lt_CodLocFis varchar(15), 
          @lt_QtdEmbFec int,
          @rx_CodCst varchar(2),
          @pr_CodClaFis varchar(20),
          @pr_CodCest varchar(7),
          @pr_CodGrpPrc varchar(1),          
		  @it_CodFab int,
		  
		  -- IRRF
		  @cb_VlrBasIrfIt numeric(18,4),
		  @cb_AlqIrfIt numeric(7,4),
		  @cb_VlrIrfIt numeric(18,4)
                    
  Declare @WFlgAcumula bit,
          @WFatBon numeric(18,8),
          @WFatParIte numeric(18,8),
          
          @Acp_UndIte int,
          
          @Sld_QtdPed int,
          @Sld_QtdBon int,

          @Acp_VlrTotIte numeric(18,4),
          @Acp_VlrLiqIte numeric(18,4),
          @Acp_VlrBruIte numeric(18,4),
          @Acp_VlrDscBonRat numeric(18,4),
          @Acp_VlrDespes numeric(18,4),
          @Acp_VlrDspExt numeric(18,4),
          @Acp_VlrBasIcmNor numeric (18,4),
          @Acp_VlrIcmNor numeric (18,4),
          @Acp_VlrBasRepIcm numeric (18,4),
          @Acp_VlrRepIcm numeric (18,4),
          @Acp_VlrPrdSubTri numeric (18,4),
          @Acp_VlrBasSubTri numeric (18,4),
          @Acp_VlrSubTri numeric (18,4),
		  @Acp_VlrBasSbtRes numeric (18,4),
          @Acp_VlrSbtRes numeric (18,4),
          @Acp_VlrBasDscTri numeric (18,4),
          @Acp_VlrDscTri numeric (18,4),
          @Acp_VlrBasIcmTri numeric (18,4),
          @Acp_VlrIcmTri numeric (18,4),
          @Acp_VlrIcmDiferi numeric (18,4),
          @Acp_VlrIcmDesone numeric (18,4),
		  @Acp_VlrDscCalSuf numeric(18,4),
          @Acp_VlrIsento numeric (18,4),
          @Acp_VlrOutros numeric (18,4),
          @Acp_VlrBasTri numeric (18,4),

          @Acp_VlrBasVerba numeric (18,4),
          @Acp_VlrVerba numeric (18,4),
          @Acp_VlrVrbVdr numeric (18,4),
          @Acp_VlrVrbOpe numeric (18,4),
          @Acp_VlrVrbSup numeric (18,4),

          @Acp_VlrBonificacao numeric (18,4),
          @Acp_VlrDscBonDup numeric (18,4),
          
          @Acp_VlrIcmParDes numeric(18,4),
          @Acp_VlrIcmParRem numeric(18,4),

          @Acp_VlrIcmFcpDes numeric(18,4),

          @Acp_VlrFcpIcm numeric(18,4),
          @Acp_VlrFcpSbt numeric(18,4),
          @Acp_VlrFcpSbtRet numeric(18,4),

          @Acp_VlrBasIpi numeric(18,4),
          @Acp_VlrIpi numeric(18,4)


  -- pega tabela de comissao do vendedor e operador
  Set @WCodTabComOpe = (Select Cod_TabCom From VEXES Where Cod_Estabe = @CodEstabe And Cod_Vended = @cb_CodOpe)
  Set @WCodTabComVdr = (Select Cod_TabCom From VEXES Where Cod_Estabe = @CodEstabe And Cod_Vended = @cb_CodVdr)

  -- comissao de supervisor/gerencia do vendedor    
  Set @cb_PerComSup = (Select IsNull(Per_ComNor,0) From SUPER Where Codigo = @cb_CodSup)
  Set @cb_PerComGer = (Select IsNull(Per_ComNor,0) From GEREN Where Codigo = @cb_CodGer)

  -- comissao de supervisor/gerencia do operador    
  Set @cb_PerComSupOpe = (Select IsNull(Per_ComNor,0) From SUPER Where Codigo = @cb_CodSupOpe)
  Set @cb_PerComGerOpe = (Select IsNull(Per_ComNor,0) From GEREN Where Codigo = @cb_CodGerOpe)

  -- verifica se existe registros em PDVLT (WMS)
  Set @WCodOri = ''
  Set @WFlgAcumula = 0
  if Exists(Select 1 From PDVLT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Qtd_Lote > 0)
    begin
      Set @WFlgAcumula = 1 
      -- calcula volume e itens em PDVLT
      Set @cb_QtdIte = IsNull((Select count(*) From (Select distinct Cod_Produt, Cod_Lote From PDVLT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Qtd_Lote > 0) x),0)
--      Set @cb_QtdVol = IsNull((Select count(distinct Num_Vol) From PDVLT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Qtd_Lote > 0),0)
      
      -- configura cod. origem
      if @TipNfs = 'V'
        Set @WCodOri = 'SAI_VEN'
      else  
      if @TipNfs = 'D'
        Set @WCodOri = 'SAI_DEV'
      else  
      if @TipNfs = 'T'
        Set @WCodOri = 'SAI_TRF'
      else  
      if @TipNfs = 'O'
        Set @WCodOri = 'SAI_OUT'
    end

  -- Gera itens da nota
  -- inmportante que seja zero. Parametro utilizado em uma consulta abaixo
  Set @P_NumSeqIte = 0

  -- cria tabela dos lotes do produto que serao utilizados
  Create Table #PDVLT_AUX
       (Chave int identity,
        Cod_Lote varchar(20),
        Qtd_CxaFec int,
        Cod_Dep smallint,
        Num_Rua smallint,
        Num_Col smallint,
        Num_Niv smallint,
        Num_Apt smallint,
        Cod_LocFis varchar(15),
        Qtd_EmbFec int,
        Qtd_Ite int,
        Qtd_Lot int,
        Qtd_Pra int,
        Qtd_Dep int)


  -- R0005  -----------------------------------------------------------------------------------------------------------------
  Declare PRODU_Cr Cursor Local Fast_Forward For 
  
    Select distinct Cod_Produto
      From PDVIT
     Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed
       And (IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) > 0

  Open PRODU_Cr
  Fetch Next From PRODU_Cr Into @it_CodPrd
  While @@FETCH_STATUS = 0
    begin
      if @WFlgAcumula = 1 
        begin
          Insert Into #PDVLT_AUX (Cod_Lote, Qtd_CxaFec, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_LocFis, Qtd_EmbFec,
                                  Qtd_Ite, Qtd_Lot, Qtd_Pra, Qtd_Dep)
            Select Cod_Lote, Qtd_CxaFec, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_LocFis, Qtd_EmbFec,
                   count(*) as QtdIte, sum(Qtd_Lote) as QtdLot, 
                   sum(IsNull(Qtd_LotePra,0)) as QtdPra, sum(IsNull(Qtd_LoteDep,0)) as QtdDep
              From PDVLT
             Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed
              And Cod_Produt = @it_CodPrd
              And Qtd_Lote > 0
            Group by Cod_Lote, Qtd_CxaFec, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_LocFis, Qtd_EmbFec
            Order by Cod_Lote, Qtd_CxaFec
            
            -- insere registros PRLOG  
            Declare PDVLTAUX_Cr Cursor Local Fast_Forward For 

              Select Cod_Lote, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Qtd_Lot
                From #PDVLT_AUX
               Where Qtd_Lot > 0

            Open PDVLTAUX_Cr
            Fetch Next From PDVLTAUX_Cr Into @lt_CodLot, @lt_CodDep, @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt, @lt_QtdLot 
            While @@FETCH_STATUS = 0
              begin
                -- saida: qtd negativa
                Set @lt_QtdLot = @lt_QtdLot*(-1) 
                Exec PR_InserePRLOG @CodEstabe, @it_CodPrd, @lt_CodLot, @lt_CodDep, 
                                    @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt,
                                    @lt_QtdLot, @WCodOri, '', @SerNfsRet, @NumNfsRet, '', @DesUsu
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      Rollback Transaction
                    Return
                  end    
                Fetch Next From PDVLTAUX_Cr Into @lt_CodLot, @lt_CodDep, @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt, @lt_QtdLot 
              end  
            Close PDVLTAUX_Cr 
            Deallocate PDVLTAUX_Cr
        end
      else
        begin
          Insert Into #PDVLT_AUX (Cod_Lote, Qtd_CxaFec, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_LocFis, Qtd_EmbFec,
                                  Qtd_Ite, Qtd_Lot, Qtd_Pra, Qtd_Dep)
            Select Cod_Lote, 0, 01, 0, 0, 0, 0, '*', 0, 
                   count(*) as QtdIte, sum(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) as QtdPdv, 
                   sum(IsNull(Qtd_Pra,0)) as QtdPra, sum(IsNull(Qtd_Dep,0)) as QtdDep
              From PDVIT
             Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed
               And Cod_Produto = @it_CodPrd
               And Qtd_Pedido > 0
             Group by Cod_Lote
             Order by Cod_Lote
        end


      -- R0010 -------------------------------------------------------------------------------------------------------------------- 
      --- seleciona itens do pedidos que serao faturados
      Declare PDVIT_Cr Cursor Local Fast_Forward For 

        Select it.Cod_Lote, IsNull(it.Tip_Sai,''), it.Qtd_Solicitado, IsNull(it.Qtd_Pedido,0), IsNull(it.Qtd_Bonificacao,0), it.Per_Desconto, it.C_PerDscIte, 
               it.Prc_Unitario, it.C_PrcUni, IsNull(it.Prc_UniSemAcrIcm,0), IsNull(Flg_PrcUniAcrIcm,0), IsNull(it.Prc_UniComAcrIcm,0),
			   it.Prc_Tabela, it.Prc_TabBru, it.Prc_Fabric, it.Prc_MaxCon, it.Prc_RefFpb, it.Flg_BlqInfPar,
               it.Flg_PrcUniDsc, it.Cod_Promocao, it.Tip_Aux, it.Cod_ClaTri, Ltrim(Rtrim(it.Ctrl_Tributacao)), Ltrim(Rtrim(it.Cod_CSOSN)), it.Desconto, it.Per_DscVis, it.Per_Descon,
               IsNull(it.Vlr_DscBonRat,0), IsNull(it.Vlr_Despes,0), IsNull(it.Vlr_DspExt,0), it.Vlr_BasIcmsNor, it.Alq_Icms, it.Vlr_IcmsNor, it.Vlr_BasRepIcms, IsNull(it.Per_RepIcms,0), it.Vlr_RepIcms, it.Vlr_PrdSubTri,
               it.Vlr_BasSubsTrib, it.Vlr_SubsTrib, IsNull(it.Vlr_BasSbtRes,0), IsNull(it.Vlr_SbtRes,0), IsNull(it.Vlr_BasDscTri,0), it.Per_DscTri, IsNull(it.Vlr_DscTri,0), 
               it.Vlr_BasIcmsTri, it.Vlr_IcmsTri, it.Vlr_Isento, it.Vlr_Outros, it.Vlr_Bruto,
               IsNull(it.Fat_CnvImpFat,0), it.Qtd_ImpFat, it.Prc_UniImpFat, it.Des_UnvImpFat, it.Des_AprImpFat, it.Id_PolCom, it.Qtd_Pra, it.Qtd_Dep,
               it.Cod_ModBasCalIcm, it.Cod_ModBasCalIcmSbt, it.Vlr_BasTri, it.Per_RedBasCalIcm, it.Per_RedBasCalIcmSbt, 
               it.Alq_IcmSbt, it.Alq_AgrSbt, IsNull(it.Vlr_Verba,0), IsNull(it.Vlr_VrbVdr,0), IsNull(it.Vlr_VrbOpe,0), IsNull(it.Vlr_VrbSup,0), 
               it.Cod_PrjPde, it.Prc_UniPde, it.Per_DscPde, it.Num_SeqPdc, IsNull(it.Flg_PolPrm,0),
               IsNull(it.Vlr_DscBonDup,0), IsNull(it.Vlr_Bonificacao,0), IsNull(it.Prc_CusMinComMarkup,0), IsNull(it.Vlr_BasVerba,0),
               IsNull(it.Alq_IntIcmDes,0), IsNull(it.Per_AcrAlqIntFcp,0), IsNull(it.Per_PrvParIcm,0),
               IsNull(it.Vlr_IcmFcpDes,0), IsNull(it.Vlr_IcmParDes,0), IsNull(it.Vlr_IcmParRem,0), IsNull(it.Cod_KitPrm,0), IsNull(it.Flg_UsaDebPresum,0), IsNull(it.Alq_IcmPresum,0),
			   IsNull(it.Prc_PolCom,0), IsNull(it.Per_DscPolCom,0),
			   IsNull(it.Vlr_IcmsDeson,0), IsNull(it.Cod_MtvIcmsDeson,''), IsNull(it.Vlr_DscCalSuframa,0), IsNull(it.Flg_IncFis,0),
			   IsNull(it.Alq_FcpIcm,0), IsNull(it.Vlr_FcpIcm,0), IsNull(it.Alq_FcpSbt,0), IsNull(it.Vlr_FcpSbt,0), IsNull(it.Alq_FcpSbtRet,0), IsNull(it.Vlr_FcpSbtRet,0),
			   IsNull(it.Per_IcmDiferi,0), IsNull(it.Vlr_IcmDiferi,0), pr.Cod_Fabricante,
               IsNull(it.Cod_OriMer,'0'), IsNull(it.Vlr_BasIpi,0), IsNull(it.Vlr_Ipi,0), IsNull(it.Alq_Ipi,0), IsNull(it.CST_Ipi,''), IsNull(it.Cod_EnqIpi,''), 
			   IsNull(Vlr_BasIrf, 0), IsNull(Alq_Irf, 0), IsNull(Vlr_Irf, 0) 
          From PDVIT it
               Inner join PRODU pr on pr.Codigo = it.Cod_Produto
         Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed
           And Cod_Produto = @it_CodPrd
           And (IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) > 0

      Open PDVIT_Cr
      Fetch Next From PDVIT_Cr Into @it_CodLot, @it_TipSai, @it_QtdSol, @it_QtdPed, @it_QtdBon, @it_PerDsc, @it_CPerDscIte, 
                                    @it_PrcUni, @it_CPrcUni, @it_PrcUniSemAcrIcm, @it_FlgPrcUniAcrIcm, @it_PrcUniComAcrIcm,
                                    @it_PrcTab, @it_PrcTabBru, @it_PrcFab, @it_PrcMax, @it_PrcRefFpb, @it_FlgBlqInfPar,
                                    @it_FlgPrcUniDsc, @it_CodPrm, @it_TipAux, @it_CodClaTri, @it_CodCst, @it_CodCsosn, @it_FlgBlqDsc, @it_PerDscVis, @it_PerDscPrz,
                                    @it_VlrDscBonRat, @it_VlrDespes, @it_VlrDspExt, @it_VlrBasIcmNor, @it_AlqIcm, @it_VlrIcmNor, @it_VlrBasRepIcm, @it_PerRepIcm, @it_VlrRepIcm, @it_VlrPrdSubTri,
                                    @it_VlrBasSubTri, @it_VlrSubTri, @it_VlrBasSbtRes, @it_VlrSbtRes, @it_VlrBasDscTri, @it_PerDscTri, @it_VlrDscTri, 
                                    @it_VlrBasIcmTri, @it_VlrIcmTri, @it_VlrIsento,  @it_VlrOutros, @it_VlrBru,
                                    @it_FatCnvImpFat, @it_QtdImpFat, @it_PrcUniImpFat, @it_DesUnvImpFat, @it_DesAprImpFat, @it_IdPolCom, @it_QtdPra, @it_QtdDep,
                                    @it_CodModBasCalIcm, @it_CodModBasCalIcmSbt, @it_VlrBasTri, @it_PerRedBasCalIcm, @it_PerRedBasCalIcmSbt, 
                                    @it_AlqIcmSbt, @it_AlqAgrSbt, @it_VlrVerba, @it_VlrVrbVdr, @it_VlrVrbOpe, @it_VlrVrbSup,
                                    @it_CodPrjPde, @it_PrcUniPde, @it_PerDscPde, @it_NumSeqPdc, @it_FlgPolPrm,
                                    @it_VlrDscBonDup, @it_VlrBonificacao, @it_PrcCusMinComMarkup, @it_VlrBasVerba,
                                    @it_AlqIntIcmDes, @it_PerAcrAlqIntFcp, @it_PerPrvParIcm, 
                                    @it_VlrIcmFcpDes, @it_VlrIcmParDes, @it_VlrIcmParRem, @it_CodKitPrm, @it_FlgUsaDebPresum, @it_AlqIcmPresum,
									@it_PrcPolCom, @it_PerDscPolCom,
                                    @it_VlrIcmDesone, @it_CodMtvIcmDesone, @it_VlrDscCalSuframa, @it_FlgIncFis,
                                    @it_AlqFcpIcm, @it_VlrFcpIcm, @it_AlqFcpSbt, @it_VlrFcpSbt, @it_AlqFcpSbtRet, @it_VlrFcpSbtRet,
                                    @it_PerIcmDiferi, @it_VlrIcmDiferi, @it_CodFab,
                                    @it_CodOriMer, @it_VlrBasIpi, @it_VlrIpi, @it_AlqIpi, @it_CSTIpi, @it_CodEnqIpi, @cb_VlrBasIrfIt, @cb_AlqIrfIt, @cb_VlrIrfIt 
      While @@FETCH_STATUS = 0
        begin
          if @it_FatCnvImpFat = 0
            Set @it_FatCnvImpFat = 1

          -- CFOp do item
          Select @P_PrcCusMed = IsNull(p.Prc_CusMed,0),
                 @P_PrcCusCom = Case 
                                  When IsNull(p.Prc_CusMedCom,0) > 0 Then IsNull(p.Prc_CusMedCom,0) 
                                  Else IsNull(p.Prc_CusMed,0) 
                                End,
                 @P_FlgIncFis = IsNull(pr.Flg_IncFis,0),
                 @it_TipAux = pr.Tip_LisPis,
                 @pr_CodClaFis = Ltrim(Rtrim(pr.Cod_ClaFis)),
                 @pr_CodCEST = Ltrim(Rtrim(pr.Cod_CEST)),
                 @pr_CodGrpPrc = ISNULL(pr.Cod_GrpPrc,'')
            From PRXES p 
                 Inner Join PRODU pr on p.Cod_Produt = pr.Codigo
           Where p.Cod_Estabe = @CodEstabe
             And p.Cod_Produt = @it_CodPrd

          Set @P_FlgIncFis = @it_FlgIncFis

          if IsNull(@it_CodCst,'') = ''
            begin
              Set @rx_CodCst = Ltrim(Rtrim(IsNull((Select Cod_ImpNotSai From RTXCT Where Cod_RegTri = @cb_CodRegTri And Cod_ClaTri = @it_CodClaTri),'')))
              Set @it_CodCst = @rx_CodCst
             end
          if Len(@it_CodCst) < 2
            Set @it_CodCst = @it_CodCst + '0'

          if Charindex(@it_CodCst,';10;30;60;70;') > 0
            Set @P_CodCfo = @WCodCfoSbt
          else
            Set @P_CodCfo = @WCodCfoNor
            
          -- registra desconto informado no item  (se desc. foi convertido para Global o valor inicial fica armazenado aqui)
          Set @P_PerDsc = 0
          Set @P_PerDscFin = 0
          if Substring(@cb_CodOriPdv,2,1) = 'F'
            begin
              if @cb_TipVct = 'V'
                Set @P_PerDsc = @it_PerDscVis
              else
                Set @P_PerDsc = @it_PerDscPrz
              if @PPerDscFinLiq > 0
                Set @P_PerDscFin = @P_PerDsc
            end
          else
            begin
              Set @P_PerDsc = @it_PerDscPrz    
              Set @P_PerDscFin = @PPerDscFinLiq
            end

          Set @it_VlrBruIte = Round(@it_CPrcUni * (@it_QtdPed+@it_QtdBon),2)
          Set @it_VlrTotIte = Round(@it_QtdPed * @it_CPrcUni * (1-@it_CPerDscIte/100),2)
          if @it_FlgBlqDsc = 1
            Set @it_VlrLiqIte = @it_VlrTotIte - @it_VlrRepIcm - @it_VlrDscBonRat + @it_VlrDespes + @it_VlrDspExt + @it_VlrSubTri + @it_VlrSbtRes - @it_VlrDscTri
          else
            Set @it_VlrLiqIte = @it_VlrTotIte * (1 - @cb_PerDscCom/100) - @it_VlrRepIcm - @it_VlrDscBonRat + @it_VlrDespes + @it_VlrDspExt + @it_VlrSubTri + @it_VlrSbtRes - @it_VlrDscTri

          -- inicializa acumuladores do item do pedido
          Set @Acp_UndIte = 0

          -- indice de bonificacao
          if @it_QtdBon > 0
            Set @WFatBon = @it_QtdBon*1.0/(@it_QtdPed+@it_QtdBon)
          else
            Set @WFatBon = 0

          Set @Sld_QtdPed = @it_QtdPed
          Set @Sld_QtdBon = @it_QtdBon

          while (@Sld_QtdPed+@Sld_QtdBon) > 0
            begin
              -- selciona lotes ainda disponiveis
              Declare PDVLTAUX_Cr Cursor Local Fast_Forward For 
              
                Select Chave, Cod_Lote, Qtd_CxaFec, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, 
                       Cod_LocFis, Qtd_EmbFec, Qtd_Ite, Qtd_Lot, Qtd_Pra, Qtd_Dep
                From #PDVLT_AUX
                Where Qtd_Lot > 0
                
              Open PDVLTAUX_Cr
              Fetch Next From PDVLTAUX_Cr Into @lt_Chave, @lt_CodLot, @lt_QtdCxaFec, @lt_CodDep, @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt, 
                                               @lt_CodLocFis, @lt_QtdEmbFec, @lt_QtdIte, @lt_QtdLot, @lt_QtdPra, @lt_QtdDep
             
              While (@@FETCH_STATUS = 0) and ((@Sld_QtdPed+@Sld_QtdBon) > 0)
                begin
                  Set @P_CodLot = @lt_CodLot
                  Set @P_QtdPed = 0
                  Set @P_QtdBon = 0
                  Set @P_QtdPra = 0
                  Set @P_QtdDep = 0

                  if (@lt_QtdPra+@lt_QtdDep) <> @lt_QtdLot
                    Set @lt_QtdPra = @lt_QtdLot - @lt_QtdDep
                    
                  -- acumula quantidades por lote ---
                  While (@P_CodLot = @lt_CodLot) and ((@Sld_QtdPed+@Sld_QtdBon) > 0) and (@@FETCH_STATUS = 0)
                    begin
                      Set @WQtdMovLot = 0
                      Set @WQtdMovPed = 0
                      Set @WQtdMovBon = 0
                      Set @WQtdMovPra = 0
                      Set @WQtdMovDep = 0

                      -- qtd. lote (Qtd_Ped, Qtd_Bon) -------------------
                      if (@Sld_QtdPed+@Sld_QtdBon) > @lt_QtdLot
                        Set @WQtdMovLot = @lt_QtdLot           
                      else
                        Set @WQtdMovLot = @Sld_QtdPed+@Sld_QtdBon
                      if @Sld_QtdBon > 0
                        Set @WQtdMovBon = Round(@WQtdMovLot*@WFatBon,0)
                      Set @WQtdMovPed = @WQtdMovLot - @WQtdMovBon
                      ---------------------------------------------------

                      if @WQtdMovLot > @lt_QtdPra
                        Set @WQtdMovPra = @lt_QtdPra
                      else
                        Set @WQtdMovPra = @WQtdMovLot
                      Set @WQtdMovDep = @WQtdMovLot - @WQtdMovPra
                      
                      -- atualiza lotes estoque grosso/fino f[@lt_QtdCxaFec]
                      -- configura flag de emprestimo de estoque
                      Set @WFlgEmpPra = 0
                      Set @WFlgEmpDep = 0
                      if (@PCodCfo > 0) and (@WQtdMovDep > 0)
                        Set @WFlgEmpDep = 1 
                      if (@PCodCfo = 0) and (@WQtdMovPra > 0)
                        Set @WFlgEmpPra = 1 

                      -- grava movimento (saida: sinal negativo)
                      Set @WQtdPraNeg = @WQtdMovPra * (-1)
                      Set @WQtdDepNeg = @WQtdMovDep * (-1)
  
                      if (@lt_QtdCxaFec > 0) and ((IsNull(@lt_CodLocFis,'') = '') or (@lt_CodLocFis <> 'PRLOT'))   -- depositO FECHADO
                        begin
                          -- atualiza mov em PRSLD e fisico em PRLTL e PRODU
                          EXEC PR_AtualizaSaldoEstoqueGrosso @CodEstabe, @it_CodPrd, @P_CodLot, @lt_QtdEmbFec, @lt_CodDep, @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt,
                                                             @PDatEmi, 'S', @TipNfs, @WQtdPraNeg, @WFlgEmpPra, @WQtdDepNeg, @WFlgEmpDep
                          if (@@error <> 0)
                            begin
                              if @@trancount > 0
                                Rollback Transaction
                              Return
                            end
                            
                          -- retira a quantidade solicitada (em PRLTL)
                          EXEC PR_DecrementaSaldoSolicitado_PRLTL @CodEstabe, 'P', @cb_StaPdv1, @cb_StaPdv2, @cb_TipBlq, @it_CodPrd, @P_CodLot, @lt_QtdEmbFec,
                                                                  @lt_CodDep, @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt, @WQtdMovPra, @WQtdMovDep
                          if (@@error <> 0)
                            begin
                              if @@trancount > 0
                                Rollback Transaction
                              Return
                            end
                        end
                      else
                        begin
                          -- atualiza mov em PRSLD e fisico em PRLOT e PRODU
                          EXEC PR_AtualizaSaldoEstoque 'NF', @CodEstabe, @lt_CodDep, @it_CodPrd, @P_CodLot, @PdatEmi, 'S', @TipNfs, @WQtdPraNeg, @WFlgEmpPra, @WQtdDepNeg, @WFlgEmpDep
                          if (@@error <> 0)
                            begin
                              if @@trancount > 0
                                Rollback Transaction
                              Return
                            end
                            
                          -- retira a quantidade solicitada (em PRLOT)
                          EXEC PR_DecrementaSaldoSolicitado_PRLOT @CodEstabe, 'P', @cb_StaPdv1, @cb_StaPdv2, @cb_TipBlq, @it_CodPrd, @P_CodLot, @lt_CodDep, @WQtdMovPra, @WQtdMovDep
                          if (@@error <> 0)
                            begin
                              if @@trancount > 0
                                Rollback Transaction
                              Return
                            end
                        end

                      -- acumula por lote
                      Set @P_QtdPed = @P_QtdPed + @WQtdMovPed
                      Set @P_QtdBon = @P_QtdBon + @WQtdMovBon
                      Set @P_QtdPra = @P_QtdPra + @WQtdMovPra
                      Set @P_QtdDep = @P_QtdDep + @WQtdMovDep

                      -- decrementa saldos           
                      Set @Sld_QtdPed = @Sld_QtdPed - @WQtdMovPed
                      Set @Sld_QtdBon = @Sld_QtdBon - @WQtdMovBon

                      Update #PDVLT_AUX
                         Set Qtd_Lot = Qtd_Lot - @WQtdMovLot,
                             Qtd_Pra = Qtd_Pra - @WQtdMovPra,
                             Qtd_Dep = Qtd_Dep - @WQtdMovDep
                       Where Chave = @lt_Chave
                        
                      Delete From #PDVLT_AUX
                       Where Qtd_Lot = 0 

                      Fetch Next From PDVLTAUX_Cr Into @lt_Chave, @lt_CodLot, @lt_QtdCxaFec, @lt_CodDep, @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt, 
                                                       @lt_CodLocFis, @lt_QtdEmbFec, @lt_QtdIte, @lt_QtdLot, @lt_QtdPra, @lt_QtdDep
                    end  -- While (@P_CodLot = @lt_CodLot) and (@lt_QtdLot > 0)

                  -- calcula participacao
                  Set @WFatParIte = (@P_QtdPed+@P_QtdBon)*1.0/(@it_QtdPed+@it_QtdBon)
                  if @it_FatCnvImpFat > 0
                    Set @P_QtdImpFat = Round((@P_QtdPed+@P_QtdBon)*1.0/@it_FatCnvImpFat,0)
                  else
                    Set @P_QtdImpFat = 0

                  Set @P_VlrBruIte = Round(@WFatParIte*@it_VlrBruIte,2)
                  Set @P_VlrTotIte = Round(@WFatParIte*@it_VlrTotIte,2)
                  Set @P_VlrLiqIte = @WFatParIte*@it_VlrLiqIte
                  Set @P_VlrBasTri = Round(@WFatParIte*@it_VlrBasTri,2)

                  -- preciso do repasse e desconto rateado p/ comparar B.C. Icms 
                  Set @P_VlrBasRepIcm = Round(@WFatParIte*@it_VlrBasRepIcm,2)
                  Set @P_VlrRepIcm = @WFatParIte*@it_VlrRepIcm
                  
                  Set @P_VlrDscRat = 0
                  if (@it_FlgBlqDsc = 0) and (@WSumVlrBasDscIte > 0)
                    Set @P_VlrDscRat = (@P_VlrTotIte - @P_VlrRepIcm) * @PVlrDscCom/@WSumVlrBasDscIte
                    
                  Set @P_VlrBasDscTri = Round(@WFatParIte*@it_VlrBasDscTri,2)
                  Set @P_VlrDscTri = Round(@WFatParIte*@it_VlrDscTri,2)
                  Set @P_VlrDscBonRat = Round(@WFatParIte*@it_VlrDscBonRat,2)
                  
                  Set @P_VlrDespes = Round(@WFatParIte*@it_VlrDespes,2)
                  Set @P_VlrDspExt = Round(@WFatParIte*@it_VlrDspExt,2)

                  Set @P_VlrBasIcmNor = Round(@WFatParIte*@it_VlrBasIcmNor,2)
                  Set @P_VlrIcmNor = @WFatParIte*@it_VlrIcmNor
                  Set @P_VlrBasIcmTri = Round(@WFatParIte*@it_VlrBasIcmTri,2)
                  Set @P_VlrIcmTri = @WFatParIte*@it_VlrIcmTri
                  Set @P_VlrIcmDiferi = @WFatParIte*@it_VlrIcmDiferi
				  Set @P_VlrIcmDesone = @WFatParIte*@it_VlrIcmDesone
				  Set @P_VlrDscCalSuframa = @WFatParIte*@it_VlrDscCalSuframa
                  Set @P_VlrIsento = Round(@WFatParIte*@it_VlrIsento,2)
                  Set @P_VlrOutros = Round(@WFatParIte*@it_VlrOutros,2)

                  Set @P_VlrPrdSubTri = Round(@WFatParIte*@it_VlrPrdSubTri,2)
                  Set @P_VlrBasSubTri = Round(@WFatParIte*@it_VlrBasSubTri,2)
                  Set @P_VlrSubTri = @WFatParIte*@it_VlrSubTri
                  Set @P_VlrBasSbtRes = Round(@WFatParIte*@it_VlrBasSbtRes,2)
                  Set @P_VlrSbtRes = @WFatParIte*@it_VlrSbtRes
                  Set @P_VlrBasRecSbt = 0
                  Set @P_VlrRecSbt = 0
                  Set @P_VlrFcpSbtRec = 0

                  Set @P_VlrBasVerba  = Round(@WFatParIte*@it_VlrBasVerba,2)
                  Set @P_VlrVerba     = Round(@WFatParIte*@it_VlrVerba,2)
                  Set @P_VlrVrbVdr    = Round(@WFatParIte*@it_VlrVrbVdr,2)
                  Set @P_VlrVrbOpe    = Round(@WFatParIte*@it_VlrVrbOpe,2)
                  Set @P_VlrVrbSup    = Round(@WFatParIte*@it_VlrVrbSup,2)

                  Set @P_VlrBonificacao = Round(@WFatParIte*@it_VlrBonificacao,2)
                  Set @P_VlrDscBonDup = Round(@WFatParIte*@it_VlrDscBonDup,2)

                  Set @P_VlrIcmParDes = @WFatParIte*@it_VlrIcmParDes
                  Set @P_VlrIcmParRem = @WFatParIte*@it_VlrIcmParRem 
                  Set @P_VlrIcmFcpDes = @WFatParIte*@it_VlrIcmFcpDes
                  Set @P_VlrFcpIcm = @WFatParIte*@it_VlrFcpIcm
                  Set @P_VlrFcpSbt = @WFatParIte*@it_VlrFcpSbt
                  Set @P_VlrFcpSbtRet = @WFatParIte*@it_VlrFcpSbtRet 

                  -- garante fechamento de valores
                  Set @Acp_UndIte = @Acp_UndIte + @P_QtdPed + @P_QtdBon

                  if @Acp_UndIte = @it_QtdPed+@it_QtdBon -- ultimo item....
                    begin
                      Select @Acp_VlrBruIte    = IsNull(sum(IsNull(Vlr_BruItem,0)),0)
                           , @Acp_VlrTotIte    = IsNull(sum(IsNull(Vlr_TotItem,0)),0)
                           , @Acp_VlrLiqIte    = IsNull(sum(IsNull(Vlr_LiqItem,0)),0)

                           , @Acp_VlrDscBonRat = IsNull(sum(IsNull(Vlr_DscBonRat,0)),0)
                           , @Acp_VlrDespes    = IsNull(sum(IsNull(Vlr_DespRateada,0)),0)
                           , @Acp_VlrDspExt    = IsNull(sum(IsNull(Vlr_DspExt,0)),0)

                           , @Acp_VlrBasIpi    = IsNull(sum(IsNull(Vlr_Ipi,0)),0)
                           , @Acp_VlrIpi       = IsNull(sum(IsNull(Vlr_Ipi,0)),0)

                           , @Acp_VlrBasTri    = IsNull(sum(IsNull(Vlr_BasTri,0)),0)
                           , @Acp_VlrBasRepIcm = IsNull(sum(IsNull(Vlr_BasRepIcms,0)),0)
                           , @Acp_VlrRepIcm    = IsNull(sum(IsNull(Vlr_RepIcms,0)),0)
                           , @Acp_VlrBasIcmNor = IsNull(sum(IsNull(Vlr_BasIcmsNor,0)),0)
                           , @Acp_VlrIcmNor    = IsNull(sum(IsNull(Vlr_IcmsNor,0)),0)
                           , @Acp_VlrBasIcmTri = IsNull(sum(IsNull(Vlr_BasIcmsTri,0)),0)
                           , @Acp_VlrIcmTri    = IsNull(sum(IsNull(Vlr_IcmsTri,0)),0)
                           , @Acp_VlrIsento    = IsNull(sum(IsNull(Vlr_Isento,0)),0)
                           , @Acp_VlrOutros    = IsNull(sum(IsNull(Vlr_Outros,0)),0)

                           , @Acp_VlrBasDscTri = IsNull(sum(IsNull(Vlr_BasDscTri,0)),0)
                           , @Acp_VlrDscTri    = IsNull(sum(IsNull(Vlr_DscTri,0)),0)
                           , @Acp_VlrIcmDiferi = IsNull(sum(IsNull(Vlr_IcmDiferi,0)),0)
                           , @Acp_VlrIcmDesone = IsNull(sum(IsNull(Vlr_IcmsDeson,0)),0)
                           , @Acp_VlrDscCalSuf = IsNull(sum(IsNull(Vlr_DscCalSuframa,0)),0)

                           , @Acp_VlrPrdSubTri = IsNull(sum(IsNull(Vlr_PrdSubTri,0)),0)
                           , @Acp_VlrBasSubTri = IsNull(sum(IsNull(Vlr_BasSubsTrib,0)),0)
                           , @Acp_VlrSubTri    = IsNull(sum(IsNull(Vlr_SubsTrib,0)),0)
                           , @Acp_VlrBasSbtRes = IsNull(sum(IsNull(Vlr_BasSbtRes,0)),0)
                           , @Acp_VlrSbtRes    = IsNull(sum(IsNull(Vlr_SbtRes,0)),0)

                           , @Acp_VlrIcmParDes = IsNull(sum(IsNull(Vlr_IcmParDes,0)),0)
                           , @Acp_VlrIcmParRem = IsNull(sum(IsNull(Vlr_IcmParRem,0)),0)
                           , @Acp_VlrIcmFcpDes = IsNull(sum(IsNull(Vlr_IcmFcpDes,0)),0)
                           , @Acp_VlrFcpIcm    = IsNull(sum(IsNull(Vlr_FcpIcm,0)),0)
                           , @Acp_VlrFcpSbt    = IsNull(sum(IsNull(Vlr_FcpSbt,0)),0)
                           , @Acp_VlrFcpSbtRet = IsNull(sum(IsNull(Vlr_FcpSbtRet,0)),0)

                           , @Acp_VlrBasVerba  = IsNull(sum(IsNull(Vlr_BasVerba,0)),0)
                           , @Acp_VlrVerba     = IsNull(sum(IsNull(Vlr_Verba,0)),0)
                           , @Acp_VlrVrbVdr    = IsNull(sum(IsNull(Vlr_VrbVdr,0)),0)
                           , @Acp_VlrVrbOpe    = IsNull(sum(IsNull(Vlr_VrbOpe,0)),0)
                           , @Acp_VlrVrbSup    = IsNull(sum(IsNull(Vlr_VrbSup,0)),0)

                           --, sum(Vlr_Bonificacao)
                           , @Acp_VlrDscBonDup = IsNull(sum(IsNull(Vlr_DscBonDup,0)),0)
                           
                        From NFSIT 
                       Where Cod_Estabe = @CodEstabe 
                         And Ser_Nota = @SerNfsRet 
                         And Num_Nota = @NumNfsRet
                         And Cod_Produto = @it_CodPrd  
						 And Cod_LotPdv = @it_CodLot
						 And Tip_Sai  = @it_TipSai

					  Set @P_VlrBruIte = @it_VlrBruIte - @Acp_VlrBruIte
                      Set @P_VlrTotIte = @it_VlrTotIte - @Acp_VlrTotIte
                      Set @P_VlrLiqIte = @it_VlrLiqIte - @Acp_VlrLiqIte
                      Set @P_VlrDscBonRat = @it_VlrDscBonRat - @Acp_VlrDscBonRat 
                      Set @P_VlrDespes = @it_VlrDespes - @Acp_VlrDespes 
                      Set @P_VlrDspExt = @it_VlrDspExt - @Acp_VlrDspExt 
                      Set @P_VlrBasTri = @it_VlrBasTri - @Acp_VlrBasTri
                      Set @P_VlrBasRepIcm = @it_VlrBasRepIcm - @Acp_VlrBasRepIcm
                      Set @P_VlrRepIcm = @it_VlrRepIcm - @Acp_VlrRepIcm
                      Set @P_VlrBasIcmNor = @it_VlrBasIcmNor - @Acp_VlrBasIcmNor
                      Set @P_VlrIcmNor = @it_VlrIcmNor - @Acp_VlrIcmNor
                      Set @P_VlrBasIcmTri = @it_VlrBasIcmTri - @Acp_VlrBasIcmTri
                      Set @P_VlrIcmTri = @it_VlrIcmTri - @Acp_VlrIcmTri
                      Set @P_VlrIsento = @it_VlrIsento - @Acp_VlrIsento
                      Set @P_VlrOutros = @it_VlrOutros - @Acp_VlrOutros
                      Set @P_VlrBasDscTri = @it_VlrBasDscTri - @Acp_VlrBasDscTri 
                      Set @P_VlrDscTri = @it_VlrDscTri - @Acp_VlrDscTri 
                      Set @P_VlrIcmDiferi = @it_VlrIcmDiferi - @Acp_VlrIcmDiferi
                      Set @P_VlrIcmDesone = @it_VlrIcmDesone - @Acp_VlrIcmDesone
                      Set @P_VlrDscCalSuframa = @it_VlrDscCalSuframa - @Acp_VlrDscCalSuf
                      Set @P_VlrPrdSubTri = @it_VlrPrdSubTri - @Acp_VlrPrdSubTri
                      Set @P_VlrBasSubTri = @it_VlrBasSubTri - @Acp_VlrBasSubTri
                      Set @P_VlrSubTri = @it_VlrSubTri - @Acp_VlrSubTri
                      Set @P_VlrBasSbtRes = @it_VlrBasSbtRes - @Acp_VlrBasSbtRes
                      Set @P_VlrSbtRes = @it_VlrSbtRes - @Acp_VlrSbtRes

                      Set @P_VlrIcmParDes = @it_VlrIcmParDes - @Acp_VlrIcmParDes
                      Set @P_VlrIcmParRem = @it_VlrIcmParRem - @Acp_VlrIcmParRem
                      Set @P_VlrIcmFcpDes = @it_VlrIcmFcpDes - @Acp_VlrIcmFcpDes
                      Set @P_VlrFcpIcm = @it_VlrFcpIcm - @Acp_VlrFcpIcm
                      Set @P_VlrFcpSbt = @it_VlrFcpSbt - @Acp_VlrFcpSbt
                      Set @P_VlrFcpSbtRet = @it_VlrFcpSbtRet - @Acp_VlrFcpSbtRet

                      Set @P_VlrBasVerba  = @it_VlrBasVerba - @Acp_VlrBasVerba
                      Set @P_VlrVerba     = @it_VlrVerba    - @Acp_VlrVerba
                      Set @P_VlrVrbVdr    = @it_VlrVrbVdr   - @Acp_VlrVrbVdr
                      Set @P_VlrVrbOpe    = @it_VlrVrbOpe   - @Acp_VlrVrbOpe
                      Set @P_VlrVrbSup    = @it_VlrVrbSup   - @Acp_VlrVrbSup

                      Set @P_VlrBonificacao = @it_VlrBonificacao - @Acp_VlrBonificacao
                      Set @P_VlrDscBonDup = @it_VlrDscBonDup - @Acp_VlrDscBonDup

                      Set @P_VlrBasIpi = @it_VlrBasIpi - @Acp_VlrBasIpi
                      Set @P_VlrIpi = @it_VlrIpi - @Acp_VlrIpi
                    end

                  -- grava item da nota
                  if @PTipRetImp = 'R'
                    begin
                      if Charindex(@it_CodCst,';10;30;70;') > 0
                        begin
                          if @P_VlrIcmTri > 0
                            if @it_PerRedBasCalIcm > 0
                              Set @it_CodCst = '20'    -- tributacao com reducao
                            else
                              Set @it_CodCst = '00'    -- tributacao integral
                          else
                            Set @it_CodCst = '41'    -- nao tributada
                        end
                      if @it_CodCst <> '60'
                        Set @P_CodCfo = @WCodCfoNor

                      Set @P_VlrBasRecSbt = @P_VlrBasSubTri
                      Set @P_VlrRecSbt = @P_VlrSubTri
                      if @P_VlrSubTri >= @P_VlrDscTri
                        Set @P_VlrRecSbt = @P_VlrSubTri - @P_VlrDscTri                 
                      Set @P_VlrBasSubTri = 0
                      Set @P_VlrSubTri = 0

					  Set @P_VlrFcpSbtRec = @P_VlrFcpSbt
					  Set @P_VlrFcpSbt = 0

					  Set @P_VlrBasDscTri = 0
					  Set @it_PerDscTri = 0
                      Set @P_VlrDscTri = 0
                    end

                  -- recalcula preco unitario a ser impresso na NF
                  if @it_FlgPrcUniDsc = 1
                    Set @it_PrcUniImpFat = @it_CPrcUni*@it_FatCnvImpFat

                  -- verifica CFOP de genericos e similares em op.internas: alterado verifica CFOP para operações com debito presumido
--                  if (@WFlgOpeInt = 1) and (@rt_FlgUsaCfoSbtSaiIntGenSim = 1) and
--                     (CHARINDEX(@pr_CodGrpPrc,';G;S;') > 0) and (@P_CodCfo = @WCodCfoNor)
--                    Set @P_CodCfo = @WCodCfoSbt   
                  if (@rt_FlgUsaCfoSbtSaiIntGenSim = 1) and
                     (@it_FlgUsaDebPresum = 1) and (@it_AlqIcmPresum > 0) and (@it_AlqIcmPresum <> @it_AlqIcm) 
                    Set @P_CodCfo = @WCodCfoSbt   

                  -- verifica CFOP contribuinte substituto (5403), substituido (5405)
--                  if Charindex(@PEst,';PE;SC;RS;') > 0
--                    begin
--                      if (@P_CodCfo = 5403) or (@P_CodCfo = 5405)
--                        if Charindex(@it_CodCst,';10;30;70;') > 0
--                          Set @P_CodCfo = 5403
--                        else
--                          Set @P_CodCfo = 5405
--                    end

                  if (@rt_FlgConsumFin = 0) and (@it_CodCst = '60')
                    if @WFlgOpeInt = 1
                      begin
                        if (@P_CodCfo <> @to_CodCfoSubstituidoInt) and (@to_CodCfoSubstituidoInt > 0)
                          Set @P_CodCfo = @to_CodCfoSubstituidoInt
                      end
                    else
                    if @WFlgOpeInt = 0
                      begin
                        if (@P_CodCfo <> @to_CodCfoSubstituidoExt) and (@to_CodCfoSubstituidoExt > 0)
                          Set @P_CodCfo = @to_CodCfoSubstituidoExt
                      end
                 
                  --ajusta ressarcimento ST
                  if (@it_CodCst = '60') and (@P_VlrSubTri > 0)
                    begin
                      Set @P_VlrBasSbtRes = @P_VlrBasSubTri 
                      Set @P_VlrSbtRes = @P_VlrSubTri
                      Set @P_VlrBasSubTri = 0 
                      Set @P_VlrSubTri = 0 

                      Set @P_VlrFcpSbtRet = @P_VlrFcpSbt
					  Set @P_VlrFcpSbt = 0
                    end

                  -- pis/cofins --------------------------------------------------------------------------------------------
                  Set @WVlrBasPisCof = @P_VlrBasTri -- @it_VlrBasTri
				  if @P_VlrSbtRes > 0
                    Set @WVlrBasPisCof = Round(@WVlrBasPisCof+@P_VlrSbtRes,2) 

                  -- normaliza CFOP de bonificacao antes de gravar NFSIT
                  -- somente quando a bonificacao não é rateada como desconto para TODOS os itens (inclusive o item bonificado)
                  -- o item pode ter sido "bonificado" rateando seu valor para outros itens: neste caso o cfop do item não é de bonificação
                  if ((@it_TipSai = 'B') and (@cb_TipRatBon <> 'T')) or (@cb_TipSaiPdv = 'B')
                    Set @P_CodCfo = @WCodCfoBon   

                  -- ipi
                  if @pm_FlgIncIpiCalPis = 1  
                    Set @WVlrBasPisCof = @WVlrBasPisCof + @P_VlrIpi

                  -- exclui icms destacado  
                  if @pm_FlgExcIcmCalPis = 1
                    Set @WVlrBasPisCof = @WVlrBasPisCof - @P_VlrIcmTri -- @P_VlrIcmNor

                  Exec PR_CalculaPisCofins @CodEstabe, @to_FlgCalPisCof, 'S', @em_CodTipLuc, @Date, @P_CodCfo, @cl_CodRamAtv, @pr_CodClaFis, @it_TipAux, @WVlrBasPisCof, 
                                           @P_CstPis output, @P_VlrBasPis output, @P_AlqPis output, @P_VlrPis output,
                                           @P_CstCof output, @P_VlrBasCof output, @P_AlqCof output, @P_VlrCof output, @P_ObsNf output
                  if (@@error <> 0)
                    begin
                      if @@trancount > 0
                        Rollback Transaction
                      Return
                    end

                  -- vlr. do desconto do item
                  if @P_VlrBruIte > @P_VlrTotIte
                    Set @P_VlrDscIte = @P_VlrBruIte - @P_VlrTotIte
                  else
                    Set @P_VlrDscIte = 0
                    
                  -- desconto do cabecalho rateado para o item  (ja foi calculado acima)
                    
                  Set @P_VlrLiqVenIte = @P_VlrTotIte - @P_VlrDscRat - @P_VlrDscBonRat - @P_VlrRepIcm  - @P_VlrDscTri

                  ---- recalcula verbas de bonfificações para clientes
                  Set @P_PerVrbPar = 0
                  Set @P_VlrVrbPar = 0
                  Set @P_PerVrbBon = 0
                  Set @P_VlrVrbBon = 0
                  if (@cb_FlgGerRetBon = 1) and (@cb_CodCli > 0)
                    begin
                      -- bonificacao de produto 
                      -- obtem quantidade total do produto no pedido
                      Set @WQtdPrdVrb = IsNull((Select sum(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0))
                                                  From PDVIT 
                                                 Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed
                                                   And Cod_Produto = @it_CodPrd 
                                                   And Qtd_Pedido > 0),0)

                      Set @WPerRetBon = IsNull((Select top 1 it.Per_RetBon 
                                                  From PRBCB cb Inner Join PRBIT it on cb.Id_PRBCB = it.Id_PRBCB
                                                 Where @PdatEmi between cb.Dat_Ini and cb.Dat_Fim
                                                   And cb.Cod_Produt = @it_CodPrd
                                                   And Qtd_Minima <= @WQtdPrdVrb
                                                 Order by it.Qtd_Minima desc),0)
                                            
                      Set @P_PerVrbBon = @WPerRetBon
                      Set @P_VlrVrbBon = Round(@P_VlrLiqVenIte*@WPerRetBon/100,2,1)
                  
                      -- bonificacao de parceria
                      Set @WPerRetBon = IsNull((Select top 1 Per_RetBon
                                                From ((Select top 1 '3' as Num_Ord, cb.Per_RetBon, cb.Numero
                                                         From PARCE cb
                                                        Where cb.Status = '0'
                                                          And cb.CodCli = @cb_CodCli
                                                        Order by cb.Numero desc) 
                                                      UNION
                                                      (Select top 1 '2' as Num_Ord, it.Per_RetBon, cb.Numero
                                                         From PARCE cb Inner Join 
                                                              PARBF it on (cb.Numero = it.Cod_Parcer) Inner Join
                                                              PRODU pr on (it.Cod_Fabric = pr.Cod_Fabricante) 
                                                        Where cb.Status = '0'
                                                          And cb.CodCli = @cb_CodCli
                                                          And pr.Codigo = @it_CodPrd
                                                        Order by cb.Numero desc) 
                                                      UNION
                                                      (Select top 1 '1' as Num_Ord, it.Per_RetBon, cb.Numero
                                                         From PARCE cb Inner Join 
                                                              PARBP it on (cb.Numero = it.Cod_Parcer)
                                                        Where cb.Status = '0'
                                                          And cb.CodCli = @cb_CodCli
                                                          And it.Cod_Produt = @it_CodPrd
                                                        Order by cb.Numero desc)) x
                                                Order by Num_Ord),0)                    
                      Set @P_PerVrbPar = @WPerRetBon
                      Set @P_VlrVrbPar = Round(@P_VlrLiqVenIte*@WPerRetBon/100,2,1)
                    end

                  -- calcula comissao do item
                  Set @WPerRetBon = @P_PerVrbBon + @P_PerVrbPar
                  Set @WCodPrm = ISNULL(@it_CodPrm,0)+ISNULL(@it_FlgPolPrm,0)

                  if ((@it_TipSai = 'B') and (@cb_TipRatBon <> 'T')) or (@cb_TipSaiPdv = 'B')
                    Set @WTipSai = 'B'
                  else  
                    Set @WTipSai = ''
                  
                  Set @WVlrBasComiss = @P_VlrTotIte - @P_VlrRepIcm - @P_VlrDscRat - @P_VlrDscTri

                  Set @it_PerLucBru = 0
                  EXEC PR_CalcComisItemSaida @CodEstabe, @CodPed, @it_CodPrd, @WTipSai, @cb_CodCli, @PDatEmi, @WVlrBasComiss,
                                             @it_CPrcUni, @it_PrcTab, @it_FlgPrcUniDsc, @it_FlgBlqInfPar,
                                             @WCodPrm, @P_PerDsc, @it_CPerDscIte, @cb_PerDscCom, @PPerDscFin, @PTipVct, @PQtdPrzMed,
                                             @PPerComVnd, @WCodTabComVdr, @PPerComOpe, @WCodTabComOpe, @cb_PerComSup, @cb_PerComGer, @cb_PerComSupOpe, @cb_PerComGerOpe, 
                                             @it_IdPolCom, @WPerRetBon, @it_PerLucBru, @P_FlgComNor output, 
                                             @P_PerComOpe output, @P_PerComVnd output, @P_PerComSup output, @P_PerComGer output, @P_PerComSupOpe output, @P_PerComGerOpe output, 
                                             @P_VlrComOpe output, @P_VlrComVnd output, @P_VlrComSup output, @P_VlrComGer output, @P_VlrComSupOpe output, @P_VlrComGerOpe output
                  if (@@error <> 0)
                    begin
                      if @@trancount > 0
                        Rollback Transaction
                      Return
                    end

                  -- calcula comissao de entrega de venda
                  if ((@it_TipSai = 'B') and (@cb_TipRatBon <> 'T')) or (@cb_TipSaiPdv = 'B')
                    Set @WTipSai = 'B'
                  else  
                    Set @WTipSai = ''

                  Set @P_PerComTra = 0
                  Set @P_VlrComTra = 0
                  if (@tr_Pessoa = 'F') and (@TipNfs = 'V') and (@WTipSai <> 'B') and (@it_TipSai <> 'B')
                    begin
                      Select @P_PerComTra = Isnull(Per_ComEnt,0) From PRXES Where Cod_Estabe = @CodEstabe and Cod_Produt = @it_CodPrd
                      Set @P_VlrComTra = @WVlrBasComiss * @P_PerComTra/100
                    end

                  -- retira a quantidade solicitada (em PRODU)
                  EXEC PR_DecrementaSaldoSolicitado_PRODU @CodEstabe, 'P', @cb_StaPdv1, @cb_StaPdv2, @cb_TipBlq, @it_CodPrd, @it_CodPrm, @P_QtdPra, @P_QtdDep, 0
                  if (@@error <> 0)
                    begin
                      if @@trancount > 0
                        Rollback Transaction
                      Return
                    end

                  -- grava movimento (saida: sinal negativo)
                  Set @WQtdMov = (@P_QtdPed + @P_QtdBon) * (-1)
                  if @it_CodPrm > 0
                    begin
                      EXEC PR_GravaPrmMv @CodEstabe, @it_CodPrm, @it_CodPrd, @PDatEmi, @TipNfs, @SerNfsRet, @NumNfsRet, @WQtdMov
                      if (@@error <> 0)
                        begin
                          if @@trancount > 0
                            Rollback Transaction
                          Return
                        end
                    end

                  -- grava estatisticas relativas ao item -----------------------------------------------------------------
				  -- executado após gravaçãodo ítem
                  Set @WQtdMov = @P_QtdPed + @P_QtdBon

                  if @cb_CodCli > 0
                    begin
                      if ((@P_VlrVrbPar <> 0) or (@P_VlrVrbBon <> 0)) and (@TipNfs = 'V') and (@it_TipSai <> 'B')
                        begin
                          Exec PR_AtualizaSaldoVBCSD @CodEstabe, @cb_CodCli, @PDatEmi, 0, @it_CodPrd, @P_CodLot, 'S', @TipNfs, @SerNfsRet, @NumNfsRet, @P_VlrVrbPar, @P_VlrVrbBon, '', 'SISTEMA'

                          if (@@error <> 0)
                            begin
                              if @@trancount > 0
                                Rollback Transaction
                              Return
                            end 
                        end
                    end

                  -- grava movimento relativo a remessa(somente) em consignação: CFOP: 5917 ou 6917 
                  if (@cb_IdConsig > 0) and (@cb_NumSeqCtr > 0) and (dbo.FN_CfopConsigValido(@CodCfo) = 1) 
                    begin
                      if dbo.FN_TipoNFConsig(@CodCfo) = 'R'
                        Set @WCodTipSaiCng = 'NFR'
                      else
                        Set @WCodTipSaiCng = 'NFF'

                      Exec PR_GravaMovimeCNGMV @CodEstabe, @cb_IdConsig, @it_CodPrd, @P_CodLot,
                                               @PDatEmi, 'S', @WCodTipSaiCng, @SerNfsRet, @NumNfsRet, @it_TipSai, 'F', 
                                               @WQtdMov, @it_CPrcUni
                      if (@@error <> 0)
                        begin
                          if @@trancount > 0
                            Rollback Transaction
                          Return
                        end
                    end

                  -- verbas
                  Set @pc_Controle_Saldo = ''
                  if Exists (Select 1 From POCOM Where Id_PolCom = @it_IdPolCom)
                    Select @pc_Controle_Saldo = pc.Controle_Saldo, 
                           @pc_FlgAcuVrbPos = pc.Flg_AcuVrbPos,
                           @pc_FlgAcuVrbNeg = pc.Flg_AcuVrbNeg,
                           @pc_FlgCtrPdvVrbVdr = pc.Flg_CtrPdvVrbVdr,
                           @pc_FlgCtrPdvVrbOpe = pc.Flg_CtrPdvVrbOpe
                      From POCOM pc
                     Where pc.Id_PolCOm = @it_IdPolCom

                  if ((@it_TipSai = 'B') and (@cb_TipRatBon <> '')) or (@cb_TipSaiPdv = 'B')
                    Set @WTipSai = 'B'
                  else  
                    Set @WTipSai = ''

                  if ( (@pc_Controle_Saldo = 'V') or (@pc_Controle_Saldo = 'F') ) and
                       (@P_VlrVerba <> 0                                    ) and
                       ( ( (@TipNfs = 'V') and (@it_TipSai <> 'B') ) or
                         ( @WTipSai = 'B')                                      )
                    begin

                      if (@P_VlrVrbVdr <> 0) and (IsNull(@cb_CodVdr, 0) > 0)
                    	begin
                    	  if (@pc_FlgCtrPdvVrbVdr = 1) and
                             ( ((@pc_FlgAcuVrbPos = 1) and (@P_VlrVrbVdr > 0)) or 
                               ((@pc_FlgAcuVrbNeg = 1) and (@P_VlrVrbVdr < 0)) )  
                            begin							  
                              if @pc_Controle_Saldo = 'V' -- Vendedor/Operador
                                Exec PR_AtualizaSaldoVBSLD @CodEstabe, @cb_CodVdr,             @PDatEmi, 0, @it_CodPrd, @P_CodLot, @it_TipSai, 'S', @TipNfs, @SerNfsRet, @NumNfsRet, @P_VlrVrbVdr, '', 'SISTEMA'
                              else
                                Exec PR_AtualizaSaldoVBFSL @CodEstabe, @cb_CodVdr, @it_CodFab, @PDatEmi, 0, @it_CodPrd, @P_CodLot, @it_TipSai, 'S', @TipNfs, @SerNfsRet, @NumNfsRet, @P_VlrVrbVdr, '', 'SISTEMA'
                    	      if (@@error <> 0)
                    		    begin
                                   if @@trancount > 0
                      		         Rollback Transaction
                    		       Return
                    		    end
                            end
                    	end
                    
                      if (@P_VlrVrbOpe <> 0) and (IsNull(@cb_CodOpe, 0) > 0)
                    	begin
                    	  if (@pc_FlgCtrPdvVrbOpe = 1) and 
                             ( ((@pc_FlgAcuVrbPos = 1) and (@P_VlrVrbOpe > 0)) or
                               ((@pc_FlgAcuVrbNeg = 1) and (@P_VlrVrbOpe < 0)) )
                            begin							  
                              if @pc_Controle_Saldo = 'V' -- Vendedor/Operador
                                Exec PR_AtualizaSaldoVBSLD @CodEstabe, @cb_CodOpe,             @PDatEmi, 0, @it_CodPrd, @P_CodLot, @it_TipSai, 'S', @TipNfs, @SerNfsRet, @NumNfsRet, @P_VlrVrbOpe, '', 'SISTEMA'
                              else
                                Exec PR_AtualizaSaldoVBFSL @CodEstabe, @cb_CodOpe, @it_CodFab, @PDatEmi, 0, @it_CodPrd, @P_CodLot, @it_TipSai, 'S', @TipNfs, @SerNfsRet, @NumNfsRet, @P_VlrVrbOpe, '', 'SISTEMA'
                              if (@@error <> 0)
                                begin
                                  if @@trancount > 0
                                    Rollback Transaction
                                  Return
                                end
                    		end
                    	end
                    
                      if (@P_VlrVrbSup <> 0) and (IsNull(@cb_CodSup, 0) > 0)
                        begin
                          if (@pc_FlgCtrPdvVrbVdr = 1) or (@pc_FlgCtrPdvVrbOpe = 1) 
                            begin
                    	      if ( (@pc_FlgAcuVrbPos = 1) and (@P_VlrVrbSup > 0) ) or
                                 ( (@pc_FlgAcuVrbNeg = 1) and (@P_VlrVrbSup < 0) )
                                begin
                                  Exec PR_AtualizaSaldoVBSSD @CodEstabe, @cb_CodSup, @PDatEmi, 0, @it_CodPrd, @P_CodLot, @it_TipSai, 'S', @TipNfs, @SerNfsRet, @NumNfsRet, @P_VlrVrbSup, '', 'SISTEMA'
                                  if (@@error <> 0)
                                    begin
                                      if @@trancount > 0
                                        Rollback Transaction
                                      Return
                                    end
                                end
                            end
                    	end

                    end  -- if (@P_VlrVerba <> 0)


                  -- verba fornecedor   
                  Set @WVlrBru = Round(@P_QtdPed*@it_PrcFab,2)
                  Set @WVlrEdi = Round(@P_QtdPed*@it_PrcUniPde*(1-@it_PerDscPde/100),2)
                  if @WVlrEdi > 0
                    begin
                      Set @WVlrMov = @WVlrBru - @WVlrEdi
                      Set @WCodFor = IsNull((Select fb.Cod_ForPref From PRODU pr Inner Join FBXES fb on pr.Cod_Fabricante = fb.Cod_FAbric and @CodEstabe = fb.Cod_Estabe
                                              Where pr.Codigo = @it_CodPrd),0)
                      if (@WCodFor > 0) and (@WVlrMov > 0) and (@TipNfs = 'V') and (@it_TipSai <> 'B') --(@it_TipSai <> 'B')
                        begin
                          Exec PR_AtualizaSaldoVBFSD @CodEstabe, @WCodFor, @PDatEmi, 0, @it_CodPrd, @P_CodLot, 'S', @TipNfs, @SerNfsRet, @NumNfsRet, @WVlrMov, 'SAIDA NF', 'SISTEMA'
                          if (@@error <> 0)
                            begin
                              if @@trancount > 0
                                Rollback Transaction
                              Return
                            end
                        end
                    end
                 
                  -- garante compatibilidade de valores  
                  -- @P_VlrTotIte - @P_VlrRepIcm - @P_VlrDscRat - @P_VlrDscBonRat - @P_VlrDscTri + desp.rateada
                  
                  if Round(@P_VlrBasTri,2) <> Round(@P_VlrTotIte-@P_VlrRepIcm-@P_VlrDscRat-@P_VlrDscBonRat-@P_VlrDscTri+@P_VlrDespes+@P_VlrDspExt,2)
                    Set @P_VlrBasTri = Round(@P_VlrTotIte-@P_VlrRepIcm-@P_VlrDscRat-@P_VlrDscBonRat-@P_VlrDscTri+@P_VlrDespes+@P_VlrDspExt,2) 
                 
                  if Round(@P_VlrBasIcmNor,2) > Round(@P_VlrBasTri,2)
                    begin
                     Set @P_VlrBasIcmNor = Round(@P_VlrBasTri,2)
                     Set @P_VlrIcmNor = @P_VlrBasIcmNor*@it_AlqIcm/100
                    end
                   
                  if Round(@P_VlrBasIcmTri,2) > Round(@P_VlrBasTri,2)
                    begin
                     Set @P_VlrBasIcmTri = Round(@P_VlrBasTri,2)
                     Set @P_VlrIcmTri = @P_VlrBasIcmTri*@it_AlqIcm/100
                    end
                   
                  if Round(@P_VlrIsento,2) > Round(@P_VlrBasTri,2)
                    begin
                     Set @P_VlrIsento = Round(@P_VlrBasTri,2)
                    end

                  if Round(@P_VlrOutros,2) > Round(@P_VlrBasTri,2)  -- + ipi, frete, seguro. ouras despesa
                    begin
                     Set @P_VlrOutros = Round(@P_VlrBasTri,2)
                    end

                  if Round(@P_QtdImpFat*100,0) <> Round((Cast(@P_QtdPed+@P_QtdBon as numeric(18,4))/@it_FatCnvImpFat)*100,0) 
                    Set @P_QtdImpFat = Cast(@P_QtdPed+@P_QtdBon as numeric(18,4))/@it_FatCnvImpFat
                  if Round(@it_PrcUniImpFat*10000,0) <> Round(@it_CPrcUni*@it_FatCnvImpFat*10000,0)
                    Set @it_PrcUniImpFat = @it_CPrcUni*@it_FatCnvImpFat
                    
                  --volumes Str_VolEmb varchar(50)
                  Declare @NumVolAnt int = 0,
                          @NumVol int = 0,
                          @StrVol varchar(50) = ''

                  if Exists(Select 1 From PDVLT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Qtd_Lote > 0)
				    begin
                      Set @StrVol = 'Volume: '
                      while Exists(Select distinct Num_Vol
                                     From PDVLT
                                    Where Cod_Estabe = @CodEstabe 
                                     And Cod_Pedido = @CodPed
                                     And Cod_Produt = @it_CodPrd
                                     And Cod_Lote = @P_CodLot
                                     And Num_Vol > @NumVolAnt)
                        begin
                          Select top 1 @NumVol = Num_Vol
                            From PDVLT
                           Where Cod_Estabe = @CodEstabe 
                             And Cod_Pedido = @CodPed
                             And Cod_Produt = @it_CodPrd
                             And Cod_Lote = @P_CodLot
                             And Num_Vol > @NumVolAnt
                           Order by Num_Vol

                          if @StrVol <> 'Volume: '
                            Set @StrVol = @StrVol + ','
                          Set @StrVol = @StrVol + CAST(@NumVol as varchar)
                          Set @NumVolAnt = @NumVol
                        end
					end

                  Set @P_NumSeqIte = @P_NumSeqIte + 1

                  Insert into NFSIT
                    (Cod_Estabe, Ser_Nota, Num_Nota, Cod_Produto, Cod_Lote, Num_SeqIte, Cod_LotPdv, Tip_Sai)
                    Values
                    (@CodEstabe, @SerNfsRet, @NumNfsRet, @it_CodPrd, @P_CodLot, @P_NumSeqIte, @it_CodLot, @it_TipSai)
                  if (@@error <> 0)
                    begin
                      if @@trancount > 0
                        Rollback Transaction
                      Return
                    end

                  Update NFSIT
                     Set Qtd_Produto = @P_QtdPed, 
                         Qtd_Bonificacao = @P_QtdBon,  

                         Flg_DscItePdv = @it_FlgPrcUniDsc, 
                         Per_Descon = @P_PerDsc,   -- desconto embutido no preço
                         Prc_UniPdv = @it_PrcUni, 
                         Per_DscPdv = @it_PerDsc, 

                         Per_Desconto = @it_CPerDscIte,
                         Prc_Unitario = @it_CPrcUni,        -- preço com desconto embutido
                         Prc_UniImpFat = @it_PrcUniImpFat,  -- @it_CPrcUni*Fat_CnvImpFat

                         Prc_UniSemAcrIcm = @it_PrcUniSemAcrIcm, 
                         Flg_PrcUniAcrIcm = @it_FlgPrcUniAcrIcm, 
                         Prc_UniComAcrIcm = @it_PrcUniComAcrIcm, 
                         Prc_Tabela = @it_PrcTab, 
                         Per_DescontoFin = @P_PerDscFin, 
                         Cod_Promocao = @it_CodPrm, 

                         Qtd_Pra = @P_QtdPra, 
                         Qtd_Dep = @P_QtdDep,

                         Vlr_DscBonRat = @P_VlrDscBonRat, 
                         Vlr_CusIte = @P_PrcCusMed, 
                         Vlr_CusComIte = @P_PrcCusCom, 
                         Flg_ComisNormal = @P_FlgComNor, 
                         Cod_GrpPrc = @pr_CodGrpPrc, 
                         Fat_CnvImpFat = @it_FatCnvImpFat, 
                         Qtd_ImpFat = @P_QtdImpFat, 
                         Des_UnvImpFat = @it_DesUnvImpFat, 
                         Des_AprImpFat = @it_DesAprImpFat, 

                         Cod_PrjPde = @it_CodPrjPde, 
                         Prc_UniPde = @it_PrcUniPde, 
                         Per_DscPde = @it_PerDscPde, 
                         Num_SeqPdc = @it_NumSeqPdc, 

                         Id_PolCom = @it_IdPolCom,
                         Flg_PolPrm = @it_FlgPolPrm, 
                         Prc_CusMinComMarkup = @it_PrcCusMinComMarkup,  
                         Cod_KitPrm = @it_CodKitPrm, 
                         Prc_PolCom = @it_PrcPolCom, 
                         Per_DscPolCom = @it_PerDscPolCom, 

                         Vlr_DespRateada = @P_VlrDespes, 

                         -- campos calculados em PR_CalcTributNFSIT
                         Tip_Aux = @it_TipAux,  
                         Flg_BlqDsc = @it_FlgBlqDsc, 
                         Flg_BlqInfPar = @it_FlgBlqInfPar, 
                         Cod_Cfo = @P_CodCfo, 
                         Ctrl_Tributacao = @it_CodCst, 
                         Cod_CSOSN = @it_CodCsosn, 
                         Cod_ClaTri = @it_CodClaTri, 
                         Prc_TabBru = @it_PrcTabBru, 
                         Prc_Fabric = @it_PrcFab, 
                         Prc_MaxCon = @it_PrcMax, 
                         Prc_RefFpb = @it_PrcRefFpb, 

                         Vlr_DescRateado = @P_VlrDscRat, 
                         Vlr_BasTri = @P_VlrBasTri, 
                         Cod_ModBasCalIcm = @it_CodModBasCalIcm,
                         Alq_Icms = @it_AlqIcm, 
                         Per_RedBasCalIcm = @it_PerRedBasCalIcm, 
                         Vlr_BasIcmsNor = @P_VlrBasIcmNor, 
                         Vlr_IcmsNor = @P_VlrIcmNor,
                         Vlr_BasRepIcms = @P_VlrBasRepIcm, 
                         Per_RepIcms = @it_PerRepIcm,
                         Vlr_RepIcms = @P_VlrRepIcm,  
                         Vlr_PrdSubTri = @P_VlrPrdSubTri, 
                         Cod_ModBasCalIcmSbt = @it_CodModBasCalIcmSbt, 
                         Alq_IcmSbt = @it_AlqIcmSbt, 
                         Alq_AgrSbt = @it_AlqAgrSbt,
                         Per_RedBasCalIcmSbt = @it_PerRedBasCalIcmSbt, 
                         Vlr_BasSubsTrib = @P_VlrBasSubTri, 
                         Vlr_SubsTrib = @P_VlrSubTri, 
                         Vlr_BasSbtRes = @P_VlrBasSbtRes, 
                         Vlr_SbtRes = @P_VlrSbtRes, 
                         Vlr_BasDscTri = @P_VlrBasDscTri, 
                         Per_DscTri = @it_PerDscTri, 
                         Vlr_DscTri = @P_VlrDscTri, 
                         Vlr_BasRecSbt = @P_VlrBasRecSbt, 
                         Vlr_RecSbt = @P_VlrRecSbt, 
                         Vlr_BasIcmsTri = @P_VlrBasIcmTri, 
                         Vlr_IcmsTri = @P_VlrIcmTri, 
                         Vlr_Isento = @P_VlrIsento, 
                         Vlr_Outros = @P_VlrOutros, 
                         Vlr_DspExt = @P_VlrDspExt, 

                         CST_Pis = @P_CstPis, 
                         Vlr_BasPis = @P_VlrBasPis, 
                         Alq_Pis = @P_AlqPis, 
                         Vlr_Pis = @P_VlrPis, 
                         CST_Cofins = @P_CstCof, 
                         Vlr_BasCofins = @P_VlrBasCof, 
                         Alq_Cofins = @P_AlqCof, 
                         Vlr_Cofins = @P_VlrCof, 

                         Obs_Nf = @P_ObsNf, 
                         Alq_IntIcmDes = @it_AlqIntIcmDes, 
                         Per_PrvParIcm = @it_PerPrvParIcm, 
                         Vlr_IcmParDes = @P_VlrIcmParDes, 
                         Vlr_IcmParRem = @P_VlrIcmParRem, 
                         Vlr_IcmsDeson = @P_VlrIcmDesone, 
                         Cod_MtvIcmsDeson = @it_CodMtvIcmDesone, 
                         Flg_IncFis = @P_FlgIncFis,
                         Vlr_DscCalSuframa = @P_VlrDscCalSuframa,
                         Flg_UsaDebPresum = @it_FlgUsaDebPresum, 
                         Alq_IcmPresum = @it_AlqIcmPresum,
                         Per_AcrAlqIntFcp = @it_PerAcrAlqIntFcp, 
                         Vlr_IcmFcpDes = @P_VlrIcmFcpDes, 
                         Alq_FcpIcm = @it_AlqFcpIcm, 
                         Vlr_FcpIcm = @P_VlrFcpIcm,
                         Alq_FcpSbt =  @it_AlqFcpSbt, 
                         Vlr_FcpSbt = @P_VlrFcpSbt, 
                         Alq_FcpSbtRet = @it_AlqFcpSbtRet, 
                         Vlr_FcpSbtRet = @P_VlrFcpSbtRet, 
                         Per_IcmDiferi = @it_PerIcmDiferi, 
                         Vlr_IcmDiferi = @P_VlrIcmDiferi,

                         -- ??? :
                         Vlr_FcpSbtRec = @P_VlrFcpSbtRec, 
                         Vlr_SubsTribEmb = 0, 

						 Cod_OriMer = @it_CodOriMer,
						 Vlr_BasIpi = @P_VlrBasIpi,
						 Alq_Ipi = @it_AlqIpi,
                         Vlr_Ipi = @P_VlrIpi, 
						 CST_Ipi = @it_CstIpi,
                         Cod_EnqIpi = @it_CodEnqIpi,

                         Per_ComTlmkt = @P_PerComOpe, 
                         Vlr_ComTlmkt = @P_VlrComOpe, 
                         Per_Comissao = @P_PerComVnd, 
                         Vlr_Comissao = @P_VlrComVnd, 
                         Per_ComSup = @P_PerComSup, 
                         Vlr_ComSup = @P_VlrComSup, 
                         Per_ComGer = @P_PerComGer,  
                         Vlr_ComGer = @P_VlrComGer, 
                         Per_ComSupOpe = @P_PerComSupOpe, 
                         Vlr_ComSupOpe = @P_VlrComSupOpe, 
                         Per_ComGerOpe = @P_PerComGerOpe, 
                         Vlr_ComGerOpe = @P_VlrComGerOpe, 
                         Per_ComTra = @P_PerComTra, 
                         Val_ComTra = @P_VlrComTra,

                         Cod_CtlSldVrb = @pc_Controle_Saldo,  
                         Vlr_BasVerba = @P_VlrBasVerba, 
--                         Vlr_Verba = @P_VlrVrbVdr,    -- até 25/11/2022 
						 Vlr_Verba = @P_VlrVerba, 
                         Vlr_VrbVdr = @P_VlrVrbVdr, 
                         Vlr_VrbOpe = @P_VlrVrbOpe, 
                         Vlr_VrbSup = @P_VlrVrbSup, 
                         Per_VrbPar = @P_PerVrbPar, 
                         Vlr_VrbPar = @P_VlrVrbPar, 
                         Per_VrbBon = @P_PerVrbBon, 
                         Vlr_VrbBon = @P_VlrVrbBon, 
                         Vlr_DscBonDup = @P_VlrDscBonDup,

                         Str_VolEmb = @StrVol, 
                         Vlr_Frete = 0, 
                         Vlr_Seguro = 0,

                         Transacao = @Now,
						 
						 Vlr_BasIrf = @cb_VlrBasIrfIt, 
						 Alq_Irf = @cb_AlqIrfIt, 
						 Vlr_Irf = @cb_VlrIrfIt 
						 
                   Where Cod_Estabe = @CodEstabe
                     And Ser_Nota = @SerNfsRet 
                     And Num_Nota = @NumNfsRet
                     And Cod_Produto = @it_CodPrd
                     And Cod_Lote = @P_CodLot
                     And Num_SeqIte = @P_NumSeqIte

                  Update NFSIT
                     Set Vlr_BruItem  = Round(Prc_Unitario * (Qtd_Produto + Qtd_Bonificacao),2),
                         Vlr_TotItem  = Round(Qtd_Produto * Prc_Unitario*(1-Per_Desconto/100),2),  
                         Vlr_DescItem = Round(Prc_Unitario * (Qtd_Produto + Qtd_Bonificacao),2) - Round(Qtd_Produto * Prc_Unitario*(1-Per_Desconto/100),2),

                         Vlr_LiqItem = Round(Qtd_Produto * Prc_Unitario*(1-Per_Desconto/100),2) --IsNull(Vlr_TotItem,0) 
                                     - IsNull(Vlr_RepIcms,0) - Isnull(Vlr_DescRateado,0) - IsNull(Vlr_DscBonRat,0) - IsNull(Vlr_DscTri,0)
                                     + IsNull(Vlr_SubsTrib,0) + IsNull(Vlr_SbtRes,0) + IsNull(Vlr_RecSbt,0) + IsNull(Vlr_Ipi,0) + Isnull(Vlr_DespRateada,0)  + Isnull(Vlr_DspExt,0),
                         Vlr_LiqVenIte = Round(Qtd_Produto * Prc_Unitario*(1-Per_Desconto/100),2) --IsNull(Vlr_TotItem,0) 
                                       - IsNull(Vlr_RepIcms,0) - Isnull(Vlr_DescRateado,0) - IsNull(Vlr_DscBonRat,0) - IsNull(Vlr_DscTri,0)
                   Where Cod_Estabe = @CodEstabe
                     And Ser_Nota = @SerNfsRet 
                     And Num_Nota = @NumNfsRet
                     And Cod_Produto = @it_CodPrd
                     And Cod_Lote = @P_CodLot
                     And Num_SeqIte = @P_NumSeqIte

                  -- insere registros NSIUM
                  Insert Into NSIUM (Cod_Estabe, Ser_Nota, Num_Nota, Cod_Produto, Cod_Lote, Num_SeqIte, Cod_IUM, Cod_IUC)
                    Select @CodEstabe, @SerNfsRet, @NumNfsRet, ci.Cod_Produt, ci.Cod_Lote, @P_NumSeqIte, ci.Cod_IUM, ci.Cod_IUC
                      From CPIUM ci 
                     Where ci.Cod_Estabe = @CodEstabe And ci.Num_PedCnf = @CodPed
                       And ci.Cod_Produt = @it_CodPrd
                       And ci.Cod_Lote = @P_CodLot
                  if (@@error <> 0)
                    begin
                      if @@trancount > 0
                        Rollback Transaction
                      Return
                    end
                    
                  -- acumula valores p/  cabecalho
                  if @P_FlgComNor = 0
                    Set @PFlgComNor = 0


                end  -- While (@@FETCH_STATUS = 0) and (@Sld_QtdPed+@Sld_QtdBon) > 0)
              
              Close PDVLTAUX_Cr 
              Deallocate PDVLTAUX_Cr
                
            end  -- while (@Sld_QtdPed+@Sld_QtdBon) > 0

          Fetch Next From PDVIT_Cr Into @it_CodLot, @it_TipSai, @it_QtdSol, @it_QtdPed, @it_QtdBon, @it_PerDsc, @it_CPerDscIte, 
                                        @it_PrcUni, @it_CPrcUni, @it_PrcUniSemAcrIcm, @it_FlgPrcUniAcrIcm, @it_PrcUniComAcrIcm,
                                        @it_PrcTab, @it_PrcTabBru, @it_PrcFab, @it_PrcMax, @it_PrcRefFpb, @it_FlgBlqInfPar,
                                        @it_FlgPrcUniDsc, @it_CodPrm, @it_TipAux, @it_CodClaTri, @it_CodCst, @it_CodCsosn, @it_FlgBlqDsc, @it_PerDscVis, @it_PerDscPrz,
                                        @it_VlrDscBonRat, @it_VlrDespes, @it_VlrDspExt, @it_VlrBasIcmNor, @it_AlqIcm, @it_VlrIcmNor, @it_VlrBasRepIcm, @it_PerRepIcm, @it_VlrRepIcm, @it_VlrPrdSubTri,
                                        @it_VlrBasSubTri, @it_VlrSubTri, @it_VlrBasSbtRes, @it_VlrSbtRes, @it_VlrBasDscTri, @it_PerDscTri, @it_VlrDscTri, 
                                        @it_VlrBasIcmTri, @it_VlrIcmTri, @it_VlrIsento,  @it_VlrOutros, @it_VlrBru,
                                        @it_FatCnvImpFat, @it_QtdImpFat, @it_PrcUniImpFat, @it_DesUnvImpFat, @it_DesAprImpFat, @it_IdPolCom, @it_QtdPra, @it_QtdDep,
                                        @it_CodModBasCalIcm, @it_CodModBasCalIcmSbt, @it_VlrBasTri, @it_PerRedBasCalIcm, @it_PerRedBasCalIcmSbt, 
                                        @it_AlqIcmSbt, @it_AlqAgrSbt, @it_VlrVerba, @it_VlrVrbVdr, @it_VlrVrbOpe, @it_VlrVrbSup,
                                        @it_CodPrjPde, @it_PrcUniPde, @it_PerDscPde, @it_NumSeqPdc, @it_FlgPolPrm,
                                        @it_VlrDscBonDup, @it_VlrBonificacao, @it_PrcCusMinComMarkup, @it_VlrBasVerba,
                                        @it_AlqIntIcmDes, @it_PerAcrAlqIntFcp, @it_PerPrvParIcm,
                                        @it_VlrIcmFcpDes, @it_VlrIcmParDes, @it_VlrIcmParRem, @it_CodKitPrm, @it_FlgUsaDebPresum, @it_AlqIcmPresum,
                                        @it_PrcPolCom, @it_PerDscPolCom,
                                        @it_VlrIcmDesone, @it_CodMtvIcmDesone, @it_VlrDscCalSuframa, @it_FlgIncFis,
                                        @it_AlqFcpIcm, @it_VlrFcpIcm, @it_AlqFcpSbt, @it_VlrFcpSbt, @it_AlqFcpSbtRet, @it_VlrFcpSbtRet,
                                        @it_PerIcmDiferi, @it_VlrIcmDiferi, @it_CodFab,
                                        @it_CodOriMer, @it_VlrBasIpi, @it_VlrIpi, @it_AlqIpi, @it_CSTIpi, @it_CodEnqIpi, @cb_VlrBasIrfIt, @cb_AlqIrfIt, @cb_VlrIrfIt 
        end  --   While @@FETCH_STATUS = 0

      Close PDVIT_Cr 
      Deallocate PDVIT_Cr
      -- R0010 -------------------------------------------------------------------------------------------------------------------- 
      
      Fetch Next From PRODU_Cr Into @it_CodPrd
    end
    
  Close PRODU_Cr 
  Deallocate PRODU_Cr

  -- grava faltas
  Declare PDVIT_Cr Cursor Local Fast_Forward For 

    Select it.Cod_Produto, 
           sum(IsNull(it.Qtd_Solicitado,0)-IsNull(it.Qtd_Pedido,0)-IsNull(it.Qtd_Bonificacao,0)), 
           sum(Round((IsNull(it.Qtd_Solicitado,0)-IsNull(it.Qtd_Pedido,0)-IsNull(it.Qtd_Bonificacao,0))
                      *(it.C_PrcUni*(1-it.C_PerDscIte/100))*(1-@cb_PerDscCom/100),2))
      From PDVIT it
           Inner join PRODU pr on pr.Codigo = it.Cod_Produto
     Where Cod_Estabe = @CodEstabe 
       And Cod_Pedido = @CodPed
       And IsNull(it.Qtd_Solicitado,0) > (IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0))
     Group by it.Cod_Produto

  Open PDVIT_Cr
  Fetch Next From PDVIT_Cr Into @it_CodPrd, @WQtdMov, @WVlrTotLiq 

  While @@FETCH_STATUS = 0
    begin
      EXEC PR_AcuFalNfsItePrd @CodEstabe, @TipNfs, 'F', @PDatEmi, @it_CodPrd, @WQtdMov, @WVlrTotLiq
      if (@@error <> 0)
        begin
          if @@trancount > 0
            Rollback Transaction
          Return
        end

      Fetch Next From PDVIT_Cr Into @it_CodPrd, @WQtdMov, @WVlrTotLiq
    end  --   While @@FETCH_STATUS = 0

  Close PDVIT_Cr 
  Deallocate PDVIT_Cr

  -- R0005  -----------------------------------------------------------------------------------------------------------------

  Drop Table #PDVLT_AUX

  -- calcula frete p/ pessoa juridica
  if (@tr_Pessoa <> 'F') and (@TipNfs = 'V') and (@cb_TipSaiPdv <> 'B')
    begin
      Set @WVlrTotLiq = @cb_VlrLiqIte - @PVlrDscCom - @cb_VlrDscBon - @cb_VlrRepIcm - @cb_VlrDscTri
      if @tr_FlgCalFreVerMer = 1
        Set @WVlrBasFre = @WVlrTotLiq
      else
        Set @WVlrBasFre = @PVlrTotNot

      Set @PVlrComTra = Round(@WVlrBasFre*@tr_PerFrete/100,2)
      if Round(@PVlrComTra*100,2) < Round(@tr_VlrMin*100,2)
        Set @PVlrComTra = @tr_VlrMin
    end

  -- recalcula parceria pois estava errado na PDVCB    
  Set @cb_VlrBasPar = IsNull((Select sum(it.VlrTotIte)     
                                From (Select VlrTotIte = Case
                                                           When b.Flg_BlqDsc = 0 then Round((IsNull(b.Vlr_TotItem,0)*(1-a.Per_DescontoCom/100)-IsNull(b.Vlr_RepIcms,0)-IsNull(b.Vlr_DscTri,0)),2)
                                                           Else (IsNull(b.Vlr_TotItem,0)-IsNull(b.Vlr_RepIcms,0)-IsNull(b.Vlr_DscTri,0))
                                                         End
                                        From NFSCB a 
                                             Inner Join NFSIT b on ((a.Cod_Estabe = b.Cod_Estabe) and (a.Ser_Nota = b.Ser_Nota) and (a.Num_Nota = b.Num_Nota))
                                       Where a.Cod_Estabe = @CodEstabe and a.Ser_Nota = @SerNfsRet and a.Num_Nota = @NumNfsRet
                                         And b.Flg_BlqInfPar = 0) it),0)

  -- Cfop do cabecalho com o do item de maior valor atualizadoem PR_AtualizaCabecNFS
  
  Update NFSCB
     Set Status = 'F',
         Tip_Saida = @TipNfs,
         Flg_MovEst = 1,
         Cod_Cfo1 = @PCodCfo,
         Flg_ComisNormal = @PFlgComNor,
         Vlr_BasPar = Round(@cb_VlrBasPar,2),
         Val_ComTra = Round(@PVlrComTra,2)
   Where Cod_Estabe = @CodEstabe 
     And Ser_Nota = @SerNfsRet
     And Num_Nota = @NumNfsRet

  -- rateia desconto comercial, qdo for o caso
  Exec PR_RateiaDescontosNFS @CodEstabe, @SerNfsRet, @NumNfsRet
  if @@error <> 0
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end    

  -- rateia comissão de transporte, qdo for o caso
  Exec PR_RateiaComissaoTranspNFS @CodEstabe, @SerNfsRet, @NumNfsRet
  if @@error <> 0
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end    

  -- atualiza valores do cabeçalho
  Exec PR_AtualizaCabecNFS @CodEstabe, @SerNfsRet, @NumNfsRet
  if @@error <> 0
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end    

  -- atualiza PRXES
  Update pr
     Set pr.Dat_UltVen = x.Dat_Emissao
    From PRXES pr 
         Inner Join (Select cb.Dat_Emissao, cb.Cod_Estabe, it.Cod_Produto
                       From NFSCB cb 
                            Inner Join NFSIT it on (cb.Cod_Estabe = it.Cod_Estabe and cb.Ser_Nota = it.Ser_Nota and cb.Num_Nota = it.Num_Nota)
                      Where cb.Cod_Estabe = @CodEstabe
                        And cb.Ser_Nota = @SerNfsRet
                        And cb.Num_Nota = @NumNfsRet 
                        And Tip_Saida = 'V') x ON (pr.Cod_Estabe = x.Cod_Estabe And pr.Cod_Produt = x.Cod_Produto)

  -- gera contas a receber
  if @to_FlgLanFin = 1
    begin

      EXEC PR_GeraTitulosFat @CodEstabe, @SerNfsRet, @NumNfsRet, @to_IsnCtaFinDeb, @to_IsnCtaFinCre, @DesUsu
      if (@@error <> 0)
        begin
          if @@trancount > 0
            Rollback Transaction
          Return
        end

      -- campo calculado da nota
      -- valor real da NF p/ atualizar acumuladores do sistema
      if @PTipRetImp = 'R'   -- imposto a recolher nao incluido no Total da NF
        Set @WCVlrTotNot = @PVlrTotNot + @cb_VlrSubTri - @cb_VlrDscTri
      else
        Set @WCVlrTotNot = @PVlrTotNot 
      -- atualiza cliente
      Set @PTotDebCli = @PTotDebCli + @WCVlrTotNot
      Set @PVlrUltFatCli = @WCVlrTotNot
      if @WCVlrTotNot > @PVlrMaiFatCli
        Set @PVlrMaiFatCli = @WCVlrTotNot

      Update CLIEN
         Set Total_Debito = @PTotDebCli,
             Data_UltimaFatura = @PDatEmi,
             Valor_UltimaFatura = @PVlrUltFatCli,
             Valor_MaiorFatura = @PVlrMaiFatCli
       Where Codigo = @cb_CodCli
    end
  else
    begin
      -- lancamentos gerenciais
      Set @WVlrMov = (Select Vlr_TotalNota From NFSCB Where Cod_Estabe = @CodEstabe and Ser_Nota = @SerNfsRet And Num_Nota = @NumNfsRet)
      Set @WIdTransacao = (Select Id_Transacao From NFSCB Where Cod_Estabe = @CodEstabe and Ser_Nota = @SerNfsRet And Num_Nota = @NumNfsRet)
  
      -- inclui conta credora
      if @to_IsnCtaFinCre > 0
        Exec PR_AtualizaPCMOV 'I', @CodEstabe, @to_IsnCtaFinCre, @Date, 'NFSCB', 'NFS', @SerNfsRet, @NumNfsRet, 0, @WIdTransacao, @WVlrMov
  
      -- inclui conta devedora
      if @to_IsnCtaFinDeb > 0
        begin
          Set @WVlrMov = -@WVlrMov
          Exec PR_AtualizaPCMOV 'I', @CodEstabe, @to_IsnCtaFinDeb, @Date, 'NFSCB', 'NFS', @SerNfsRet, @NumNfsRet, 0, @WIdTransacao, @WVlrMov
        end
    end

  -- atualiza PDVCB
  if (@pm_FlgDespachMercad = 0) or (Charindex(@cb_TipFat,';FUN;CON;') > 0)
    Update PDVCB
      Set Cod_SerNfs = @SerNfsRet,
          Cod_NumNfsIni = @NumNfsRet,
          Hor_Fatura = @Now,
          Hor_Saida = @Now,
          Status1 = 'D',
          Status2 = 'D',
          Flg_Credito = null
      Where Cod_Estabe = @CodEstabe And Numero = @CodPed
  else
    Update PDVCB
      Set Cod_SerNfs = @SerNfsRet,
          Cod_NumNfsIni = @NumNfsRet,
          Hor_Fatura = @Now,
          Status2 = 'N',
          Flg_Credito = null
      Where Cod_Estabe = @CodEstabe And Numero = @CodPed

  -- elimina conferencia em aberto 
  Delete From CPVCB
   Where Cod_Estabe = @CodEstabe And Num_PedCnf = @CodPed
     And Sta_PedCnf = '0'
  if (@@error <> 0)
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end


  -- atualiza estatisticas do item
  Exec PR_AtualizaEstatisticasNFS @CodEstabe, @SerNfsRet, @NumNfsRet, 'F'
  if @@error <> 0
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end

  -- recalcula NF se houver despesas ou se orgao publico com desconto ICMS
  -- PDVIT.Vlr_Despes = despesa + frete. na NFSIT estes valores são separados
  Set @WFlgRecalcula = 0
  if (@PVlrOutDsp+@cb_VlrFrete) > 0
    Set @WFlgRecalcula = 1
  if ((@rt_FlgDscIcmOrgPub = 1) or (@rt_FlgDscIcmOrgPubAcr = 1)) and ((@cl_TipCon = 'P') or (@cl_TipCon = 'E') or (@cl_TipCon = 'M'))   
    Set @WFlgRecalcula = 1

  if @WFlgRecalcula = 1
    begin
      EXEC PR_RecalculaNFSCB @CodEstabe, @SerNfsRet, @NumNfsRet
      if (@@error <> 0)
        begin
          if @@trancount > 0
            Rollback Transaction
          Return
        end
    end  

  -- debita verba do vendedor
  if @PVlrDebVrbVdr > 0
    begin
      Set @WVlrMov = -@PVlrDebVrbVdr
      Exec PR_AtualizaSaldoVBSLD @CodEstabe, @cb_CodVdr, @PDatEmi, 0, 0, '', '', 'S', @TipNfs, @SerNfsRet, @NumNfsRet, @WVlrMov, '', 'SISTEMA'
      if (@@error <> 0)
        begin
          if @@trancount > 0
            Rollback Transaction
          Return
        end
    end

  -- recalcula NFS (embutir sbt no preco) se for o caso
  EXEC PR_RecalculaNFS_Sbt @CodEstabe, @SerNfsRet, @NumNfsRet
  if (@@error <> 0)
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end

  -- gera vale (devolucao)   
  if (@TipNfs = 'D') and ((@cb_CodCli > 0) or (@cb_CodFun > 0))
    begin
       Set @WVlrMov = (Select Vlr_TotalNota From NFSCB Where Cod_Estabe = @CodEstabe and Ser_Nota = @SerNfsRet And Num_Nota = @NumNfsRet)
      if @cb_CodCli > 0
        begin
          Set @WTipDes = 'CLI'
          Set @WCodDes = @cb_CodCli
        end
      else
      if @cb_CodFun > 0
        begin
          Set @WTipDes = 'FUN'
          Set @WCodDes = @cb_CodFun
        end

      EXEC PR_ProxNumero 'Vale', @WCodDoc output
      if @@error <> 0
        begin
          if @@trancount > 0
            Rollback Transaction
          Return
        end

      -- inclui vale
      Insert into VALES
        (Cod_Estabe, Cod_Vale, Des_Vale, Tip_Entid, Cod_Entid, Dat_Emissa, Val_Vale, Deb_Cre, 
         Cod_CtrLanAut, Ser_CtrLanAut, Num_CtrLanAut, Isn_CtaFinDeb, Isn_CtaFinCre, Usuario, Transacao)
      Values
        (@CodEstabe, @WCodDoc,'NFS Devolucao: '+@SerNfsRet+'/'+cast(@NumNfsRet as varchar), @WTipDes, @WCodDes, @Date, @WVlrMov, 'D',
         'DNS', @SerNfsRet, @NumNfsRet, @to_IsnCtaFinDeb, @to_IsnCtaFinCre, @DesUsu,@Now)
    end
      
  -- elimina registros em TBIUM
  Delete ti
    From TBIUM ti, CPIUM ci 
   Where ti.Cod_Estabe = ci.Cod_Estabe 
     And ti.Cod_IUM = ci.Cod_IUM
     And ci.Cod_Estabe = @CodEstabe 
     And ci.Num_PedCnf = @CodPed

  -- gera contrato a partir das faltas, se for o caso
  EXEC PR_CriaContratoPendenciasPedido @CodEstabe, @CodPed
  if (@@error <> 0)
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end

  -- atualiza itens na tabela de contratos hospitalares 
  if (@cb_CodCtr > 0) and (@cb_NumSeqCtr > 0)
    begin
      Exec PR_FaturaContratoHosp @CodEstabe, @CodPed, @cb_CodCtr, @cb_NumSeqCtr
      if (@@error <> 0)
        begin
          if @@trancount > 0
            Rollback Transaction
          Return
        end
    end

  -- atualiza itens na tabela de consignações
  if (@cb_IdConsig > 0) and (@cb_NumSeqCtr > 0)
    begin
      Exec PR_FaturaConsignacao 'S', @CodEstabe, @SerNfsRet, @NumNfsRet, @cb_IdConsig, @cb_NumSeqCtr
      if (@@error <> 0)
        begin
          if @@trancount > 0
            Rollback Transaction
          Return
        end
    end

  -- libera endereço Cross Docking do depósito
  if Exists(Select 1 From PDVCB 
             Where Cod_Estabe = @CodEstabe 
               And Numero = @CodPed
               And IsNull(Num_PrtOri,0) > 0)
    begin
      Declare @WNumProtoc int
      Set @WNumProtoc = IsNull((Select Num_PrtOri From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @CodPed),0)
      Exec PR_VinculaDesvinculaEnderecoNFE 'D', @CodEstabe, @WNumProtoc
    end

  if @@trancount > 0
    Commit Transaction
end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ValidaProduto]
@PCodEstabe int,        
@PTipCodPrd varchar(1) output,
@PCodPrdArq varchar(14),          -- codigo a ser validado
@PCodPrdRef varchar(20) output,   -- codigo a ser validado
@PCodPrdEan varchar(13),           -- codigo a ser validado
@PCodPrd int output,
@PUndVen varchar(3) output,
@PCodPrdEmbFec varchar(14) output,
@PQtdEmbFec int output

AS

SET NOCOUNT ON

if IsNull(@PTipCodPrd,'') = '' 
  Set @PTipCodPrd = '2'   -- Cod_EAN
Set @PCodPrdArq = Ltrim(Rtrim(@PCodPrdArq))
Set @PCodPrdEan = Ltrim(Rtrim(@PCodPrdEan))
Set @PCodPrdRef = Ltrim(Rtrim(@PCodPrdRef))
Set @PCodPrdEmbFec = Ltrim(Rtrim(@PCodPrdEmbFec))

Set @PUndVen = ''
Set @PQtdEmbFec = 0

if @PCodPrdArq <> '' 
  begin
    if @PTipCodPrd = '2' 
      begin
        if not Exists(Select 1
                        From PRXES pr 
                             Inner Join PRODU p on pr.Cod_Produt = p.Codigo 
                             Left  Join PREAN ea on p.Codigo = ea.Cod_Produt 
                        Where pr.Cod_Estabe = @PCodEstabe
                        And IsNull(pr.Flg_BlqVen,0) = 0 And p.Flag_ImprClassif1 <> 'N' And p.Tipo = 'R'
                        And (((IsNull(p.Cod_Ean,'') <> '') and (p.Cod_Ean = @PCodPrdArq)) or
	                         ((IsNull(ea.Cod_EAN,'') <> '') and (ea.Cod_EAN = @PCodPrdArq)))) and
           Exists(Select 1
                    From PRXES pr 
                         Inner Join PRODU p on pr.Cod_Produt = p.Codigo 
                         Left Join  PREAN ea on p.Codigo = ea.Cod_Produt 
                    Where pr.Cod_Estabe = @PCodEstabe
                    And IsNull(pr.Flg_BlqVen,0) = 0  And p.Flag_ImprClassif1 <> 'N' And p.Tipo = 'R'
                    And cast(p.Codigo as bigint) = @PCodPrdArq)
          Set @PTipCodPrd = '1'
      end
    else
    if @PTipCodPrd = '1' 
      begin
        if not Exists(Select 1
                        From PRXES pr 
                             Inner Join PRODU p on pr.Cod_Produt = p.Codigo 
                             Left Join  PREAN ea on p.Codigo = ea.Cod_Produt 
                        Where pr.Cod_Estabe = @PCodEstabe
                        And IsNull(pr.Flg_BlqVen,0) = 0 And p.Flag_ImprClassif1 <> 'N' And p.Tipo = 'R'
                        And cast(p.Codigo as bigint) = @PCodPrdArq) and
           Exists(Select 1
                    From PRXES pr 
                         Inner Join PRODU p on pr.Cod_Produt = p.Codigo 
                         Left  Join PREAN ea on p.Codigo = ea.Cod_Produt 
                    Where pr.Cod_Estabe = @PCodEstabe
                    And IsNull(pr.Flg_BlqVen,0) = 0 And p.Flag_ImprClassif1 <> 'N' And p.Tipo = 'R'
                    And (((IsNull(p.Cod_Ean,'') <> '') and (p.Cod_Ean = @PCodPrdArq)) or
	                         ((IsNull(ea.Cod_EAN,'') <> '') and (ea.Cod_EAN = @PCodPrdArq)))) 
          Set @PTipCodPrd = '2'
      end

    if (@PTipCodPrd = '2') and 
        Exists(Select 1
                 From PRXES pr 
                      Inner Join PRODU p on pr.Cod_Produt = p.Codigo 
                      Left  Join PREAN ea on p.Codigo = ea.Cod_Produt 
                 Where pr.Cod_Estabe = @PCodEstabe
                 And IsNull(pr.Flg_BlqVen,0) = 0 And p.Flag_ImprClassif1 <> 'N' And p.Tipo = 'R'
                 And (((IsNull(p.Cod_Ean,'') <> '') and (p.Cod_Ean = @PCodPrdArq)) or
	                  ((IsNull(ea.Cod_EAN,'') <> '') and (ea.Cod_EAN = @PCodPrdArq))))
        Set @PCodPrd = IsNull((Select top 1 p.Codigo
                                 From PRXES pr 
                                      Inner Join PRODU p on pr.Cod_Produt = p.Codigo 
                                      Left  Join PREAN ea on p.Codigo = ea.Cod_Produt 
                                 Where pr.Cod_Estabe = @PCodEstabe
                                 And IsNull(pr.Flg_BlqVen,0) = 0 And p.Flag_ImprClassif1 <> 'N' And p.Tipo = 'R'
                                 And (((IsNull(p.Cod_Ean,'') <> '') and (p.Cod_Ean = @PCodPrdArq)) or
	                                  ((IsNull(ea.Cod_EAN,'') <> '') and (ea.Cod_EAN = @PCodPrdArq)))),0)

    if (@PTipCodPrd = '1') and
        Exists(Select 1
                 From PRXES pr 
                      Inner Join PRODU p on pr.Cod_Produt = p.Codigo 
                      Left Join  PREAN ea on p.Codigo = ea.Cod_Produt 
                 Where pr.Cod_Estabe = @PCodEstabe
                 And IsNull(pr.Flg_BlqVen,0) = 0 And p.Flag_ImprClassif1 <> 'N' And p.Tipo = 'R'
                 And cast(p.Codigo as bigint) = @PCodPrdArq)
      Set @PCodPrd = IsNull((Select p.Codigo From PRODU p Where cast(p.Codigo as bigint) = @PCodPrdArq),0)

  end

if (@PCodPrd = 0) and (@PCodPrdEan <> '') 
  begin
    if Exists(Select 1
                From PRXES pr 
                     Inner Join PRODU p on pr.Cod_Produt = p.Codigo 
                     Left  Join PREAN ea on p.Codigo = ea.Cod_Produt 
               Where pr.Cod_Estabe = @PCodEstabe
                 And IsNull(pr.Flg_BlqVen,0) = 0 And p.Flag_ImprClassif1 <> 'N' And p.Tipo = 'R'
                 And (((IsNull(p.Cod_Ean,'') <> '') and (p.Cod_Ean = @PCodPrdEan)) or
                      ((IsNull(ea.Cod_EAN,'') <> '') and (ea.Cod_EAN = @PCodPrdEan)))) 
      begin
        Set @PTipCodPrd = '2'
        Set @PCodPrdArq = @PCodPrdEan
        Set @PCodPrd = IsNull((Select top 1 p.Codigo
                                 From PRXES pr 
                                      Inner Join PRODU p on pr.Cod_Produt = p.Codigo 
                                      Left  Join PREAN ea on p.Codigo = ea.Cod_Produt 
                                Where pr.Cod_Estabe = @PCodEstabe
                                  And IsNull(pr.Flg_BlqVen,0) = 0 And p.Flag_ImprClassif1 <> 'N' And p.Tipo = 'R'
                                  And (((IsNull(p.Cod_Ean,'') <> '') and (p.Cod_Ean = @PCodPrdEan)) or
	                                   ((IsNull(ea.Cod_EAN,'') <> '') and (ea.Cod_EAN = @PCodPrdEan)))),0)
      end
  end

if (@PCodPrd = 0) and (@PCodPrdRef <> '') 
  begin
    if EXists(Select 1 
	            From PRXES pr 
                     Inner Join PRODU p on pr.Cod_Produt = p.Codigo 
                Where pr.Cod_Estabe = @PCodEstabe
                And IsNull(pr.Flg_BlqVen,0) = 0 And p.Flag_ImprClassif1 <> 'N' And p.Tipo = 'R'
                And p.Ref_Fabricante = Substring(@PCodPrdRef,1,15))
      begin
        Select @PTipCodPrd = '3',   -- Cod.Prd referencia
               @PCodPrdArq = @PCodPrdRef,
		       @PCodPrd = Codigo
          From PRODU 
          Where Ref_Fabricante = SUbstring(@PCodPrdRef,1,15)
      end
  end


if @PCodPrd > 0
  Select @PUndVen = Unidade_Venda,
         @PQtdEmbFec = Qtd_Embalagem
    From PRODU 
    Where Codigo = @PCodPrd
else
  begin
    Set @PUndVen = ''
    Set @PQtdEmbFec = 0
  end

-- valida DUN-14
if @PCodPrdEmbFec <> '' 
  begin
    Set @PTipCodPrd = '2'
    if Exists(Select 1
                From PRXES pr 
                     Inner Join PRODU p on pr.Cod_Produt = p.Codigo 
                     Left  Join PREAN ea on p.Codigo = ea.Cod_Produt 
                Where pr.Cod_Estabe = @PCodEstabe
                And IsNull(pr.Flg_BlqVen,0) = 0 And p.Flag_ImprClassif1 <> 'N' And p.Tipo = 'R'
                And ((IsNull(ea.Cod_EAN,'') <> '') and (ea.Cod_EAN = @PCodPrdEmbFec))) 
      Select top 1 
             @PCodPrd = p.Codigo,
             @PUndVen = ea.Des_UndEmb, 
             @PQtdEmbFec = ea.Qtd_UndEmb 
        From PRXES pr 
             Inner Join PRODU p on pr.Cod_Produt = p.Codigo 
             Left Outer Join PREAN ea on p.Codigo = ea.Cod_Produt 
        Where pr.Cod_Estabe = @PCodEstabe
        And IsNull(pr.Flg_BlqVen,0) = 0 And p.Flag_ImprClassif1 <> 'N' And p.Tipo = 'R'
        And ((IsNull(ea.Cod_EAN,'') <> '') and (ea.Cod_EAN = @PCodPrdEmbFec)) 
    else
      begin
        Set @PCodPrd = 0
        Set @PUndVen = ''
        Set @PQtdEmbFec = 0
      end
  end

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_VerificaEstoque]
@CodEstabe int

AS

SET NOCOUNT ON 

Print ''
Print 'Verifica estoques negativos em PRXES:'


  -- verifica qtd.fisico > 0 em PRXES sem registro em PRSLD
  if Exists(Select p.Cod_Produt
            From PRXES p Left Outer Join 
                 PRSLD s on p.Cod_Estabe = s.Cod_Estabe and p.Cod_Produt = s.Cod_Produt 
            Where p.Cod_Estabe = @CodEstabe 
            And p.Qtd_Fisico > 0 and s.Cod_Produt is null)
    Select p.Cod_Produt as 'Prd.c/estoque(PRXES) s/registro em PRSLD',
           p.Qtd_Fisico as 'FISICO em PRXES'
    From PRXES p Left Outer Join
         PRSLD s on p.Cod_Estabe = s.Cod_Estabe and p.Cod_Produt = s.Cod_Produt 
    Where p.Cod_Estabe = @CodEstabe 
    And p.Qtd_Fisico > 0 and s.Cod_Produt is null
    
  -- verifica estoque negativo em PRODU
  if Exists(Select Cod_Produt 
            From PRXES 
            Where Cod_Estabe = @CodEstabe 
            And (Qtd_Dispon < 0) or (Qtd_Fisico < 0))
    begin
      PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': ===> Existem ESTOQUES NEGATIVOS EM PRXES'
      Select Cod_Produt as 'Prd. c/Estoque Negativo', 
             Qtd_Fisico as 'Fisico', 
             Qtd_Reserv as 'Reservado', 
             Qtd_Avaria as 'Avariado', 
             Qtd_Solici as 'Solicitado', 
             Qtd_Dispon as 'Disponivel'
      From PRXES 
      Where Cod_Estabe = @CodEstabe 
      And (Qtd_Dispon < 0) or (Qtd_Fisico < 0)
    end
  else
    PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': Estoques Negativos em PRXES: ok'



Print ''
Print 'Verifica divergências entre PRXES x PRSLD:'

  -- divergencias PRX x PRSLD
  if Exists(Select p.Cod_Produt
            From PRXES p Inner Join 
                 (Select Cod_Estabe, Cod_Produt, Dat_Mov = MAX(Dat_Movime)
                  From PRSLD
                  Where Cod_Estabe = @CodEstabe
                  Group by Cod_Estabe, Cod_Produt) x on p.Cod_Estabe = x.Cod_Estabe and p.Cod_Produt = x.Cod_Produt Inner Join 
                 PRSLD s ON ((p.Cod_Estabe = s.Cod_Estabe) and (p.Cod_Produt = s.Cod_Produt) and (x.Dat_Mov = s.Dat_Movime))
            Where p.Cod_Estabe = @CodEstabe
            and p.Qtd_Fisico <> s.Qtd_SldAtu)
    begin
      PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': ===> Existem DIVERGENCIAS DE ESTOQUES: PRXES x PRSLD'
      Select p.Cod_Estabe,
	         p.Cod_Produt as 'Prd.c/divergência (PRXES x PRSLD)', 
             p.Qtd_Fisico as 'Físico em PRODU', 
             s.Qtd_SldAtu as 'Físico em PRSLD'
      From PRXES p Inner Join 
           (Select Cod_Estabe, Cod_Produt, Dat_Mov = MAX(Dat_Movime)
            From PRSLD
            Where Cod_Estabe = @CodEstabe
            Group by Cod_Estabe, Cod_Produt) x on p.Cod_Estabe = x.Cod_Estabe and p.Cod_Produt = x.Cod_Produt Inner Join 
           PRSLD s ON ((p.Cod_Estabe = s.Cod_Estabe) and (p.Cod_Produt = s.Cod_Produt) and (x.Dat_Mov = s.Dat_Movime))
      Where p.Cod_Estabe = @CodEstabe
      and p.Qtd_Fisico <> s.Qtd_SldAtu  
    end
  else
    begin
      PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': Estoque Físico: PRXES x PRSLD ok!'
      if Exists(Select 1 From PRXES
                Where Cod_Estabe = @CodEstabe
                And Qtd_Dispon <> (Qtd_Fisico-Qtd_Solici-Qtd_Reserv-Qtd_Avaria))
        begin
          PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': ===> Existem DIVERGENCIAS DOS ESTOQUES EM PRXES'
          Select Cod_Estabe,
		         Cod_Produt as 'Prd.c/divergência (PRXES)', 
				 Qtd_Fisico,
				 Qtd_Solici,
				 Qtd_Reserv,
				 Qtd_Avaria,  
                 Qtd_Dispon as 'Disponivel Cadastrado', 
                 (Qtd_Fisico-Qtd_Solici-Qtd_Reserv-Qtd_Avaria) as 'Disponivel Calculado'
          From PRXES 
          Where Cod_Estabe = @CodEstabe
          And Qtd_Dispon <> (Qtd_Fisico-Qtd_Solici-Qtd_Reserv-Qtd_Avaria)
        end
      else
      PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': Estoques em PRXES ok!'
    end


Print ''
Print 'Verifica divergências em estoques reservados:'

  -- verifica estoque reservado
  if Exists(Select p.Cod_Produt, p.Qtd_Reserv, r.QtdResTot 
            From PRXES p Left Outer Join
                 (Select Cod_Produto, QtdResTot=sum(IsNull(Qtd_Movimento,0)+IsNull(Qtd_ResDep,0))
                  From RESER
                  Where Cod_Estabe = @CodEstabe
                  Group by Cod_Produto) r on (p.Cod_Produt = r.Cod_Produto)
            Where p.Cod_Estabe = @CodEstabe 
            And p.Qtd_Reserv <> IsNull(r.QtdResTot,0))
    begin          
      PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': ===> Existem DIVERGENCIAS DE ESTOQUES: PRXES x RESER'
      Select p.Cod_Estabe,
	         p.Cod_Produt as 'Prd.c/divergência (PRXES x RESER)', 
             p.Qtd_Reserv  as 'Reservado em PRXES', 
             r.QtdResTot as 'Reservado em RESER'
      From PRXES p Left Outer Join
           (Select Cod_Produto, QtdResTot=sum(IsNull(Qtd_Movimento,0)+IsNull(Qtd_ResDep,0))
            From RESER
            Where Cod_Estabe = @CodEstabe
            Group by Cod_Produto) r on (p.Cod_Produt = r.Cod_Produto)
      Where p.Cod_Estabe = @CodEstabe
      And p.Qtd_Reserv <> IsNull(r.QtdResTot,0)
    end
  else
    PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': Estoques Reservados em PRXES: ok'



Print ''
Print 'Verifica divergências em estoques avariados:'

  -- verifica estoque avariado
  if Exists(Select p.Cod_Produt, p.Qtd_Avaria, a.QtdAvaTot 
            From PRXES p Left Outer Join
                 (Select Cod_Produto, QtdAvaTot=sum(IsNull(Qtd_Movimento,0)+IsNull(Qtd_AvaDep,0))
                  From AVARI
                  Where Cod_Estabe = @CodEstabe
                  Group by Cod_Produto) a on (p.Cod_Produt = a.Cod_Produto)
            Where p.Cod_Estabe = @CodEstabe 
            And p.Qtd_Avaria <> IsNull(a.QtdAvaTot,0))
    begin          
      PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': ===> Existem DIVERGENCIAS DE ESTOQUES: PRXES x AVARI'
      Select p.Cod_Estabe,
	         p.Cod_Produt as 'Prd.c/divergência (PRXES x AVARI)', 
             p.Qtd_Avaria  as 'Avariado em PRXES', 
             a.QtdAvaTot as 'Avariado em AVARI'
      From PRXES p Left Outer Join
           (Select Cod_Produto, QtdAvaTot=sum(IsNull(Qtd_Movimento,0)+IsNull(Qtd_AvaDep,0))
            From AVARI
            Where Cod_Estabe = @CodEstabe
            Group by Cod_Produto) a on (p.Cod_Produt = a.Cod_Produto)
      Where p.Cod_Estabe = @CodEstabe 
      And p.Qtd_Avaria <> IsNull(a.QtdAvaTot,0)
    end
  else
    PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': Estoques Avariados em PRXES: ok'



Print ''
Print 'Verifica divergências em estoques solicitados em  PRXES x (PDVIT+ORCIT):'

  -- verifica estoque solicitado em PRXES
  if Exists(Select p.Cod_Produt,
                   IsNull(p.Qtd_Solici,0), IsNull(x.Qtd_Solicitado,0)+IsNull(y.Qtd_Solicitado,0)
            From PRXES p LEFT OUTER JOIN 
                 (Select it.Cod_Produto,
                         sum(IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)) as Qtd_Solicitado
                  From PDVCB cb Inner Join
                       PDVIT it on (cb.Cod_Estabe = it.Cod_Estabe And cb.Numero = it.Cod_Pedido)
                  Where cb.Cod_Estabe = @CodEstabe      
                  and cb.Tip_Pedido = 'P'
                  and cb.Status1 = 'P'
                  and cb.Status2 <> 'N'
                  and cb.Status2 <> 'D'
                  and IsNull(cb.Bloqueio,'') <> 'SR'
                  and (IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)) > 0
                  Group by it.Cod_Produto) x ON (p.Cod_Produt = x.Cod_Produto) LEFT OUTER JOIN 
                 (Select it.Cod_Produt,
                         sum(IsNull(it.Qtd_Produt,0)) as Qtd_Solicitado
                  From ORCCB cb Inner Join
                       ORCIT it on (cb.Cod_Estabe = it.Cod_Estabe And cb.Cod_Orcame = it.Cod_Orcame)
                  Where cb.Cod_Estabe = @CodEstabe      
                  And cb.Sta_Movime = 'F'
                  and IsNull(cb.Num_Docume,0) = 0
                  and it.Tip_EntSai = 'S'
                  And IsNull(cb.Cod_OriVen,'') <> 'DMD'
                  and (IsNull(it.Qtd_Produt,0)) > 0
                  Group by it.Cod_Produt) y ON (p.Cod_Produt = y.Cod_Produt)
            Where p.Cod_Estabe = @CodEstabe      
            And IsNull(p.Qtd_Solici,0) <> IsNull(x.Qtd_Solicitado,0)+IsNull(y.Qtd_Solicitado,0))
    begin
      PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': ===> Existem DIVERGENCIAS DE ESTOQUES: PRXES x (PDVIT+ORCIT)'
      
      Select p.Cod_Estabe,
	         p.Cod_Produt as 'Prd.c/divergência (PRXES x (PDVIT+ORCIT))', 
             p.Qtd_Solici as 'Solicitado em PRXES', 
             IsNull(x.Qtd_Solicitado,0) as 'Solicitado em PDVIT', 
             IsNull(y.Qtd_Solicitado,0) as 'Solicitado em ORCIT'
            From PRXES p LEFT OUTER JOIN
                 (Select it.Cod_Produto,
                         sum(IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)) as Qtd_Solicitado
                  From PDVCB cb Inner Join
                       PDVIT it on (cb.Cod_Estabe = it.Cod_Estabe and cb.Numero = it.Cod_Pedido)
                  Where cb.Cod_Estabe = @CodEstabe      
                  and cb.Tip_Pedido = 'P'
                  and cb.Status1 = 'P'
                  and cb.Status2 <> 'N'
                  and cb.Status2 <> 'D'
                  and IsNull(cb.Bloqueio,'') <> 'SR'
                  and (IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)) > 0
                  Group by it.Cod_Produto) x ON (p.Cod_Produt = x.Cod_Produto) LEFT OUTER JOIN
                 (Select it.Cod_Produt,
                         sum(IsNull(it.Qtd_Produt,0)) as Qtd_Solicitado
                  From ORCCB cb Inner Join
                       ORCIT it on (cb.Cod_Estabe = it.Cod_Estabe And cb.Cod_Orcame = it.Cod_Orcame)
                  Where cb.Cod_Estabe = @CodEstabe      
                  And cb.Sta_Movime = 'F'
                  and IsNull(cb.Num_Docume,0) = 0
                  and it.Tip_EntSai = 'S'
                  And IsNull(cb.Cod_OriVen,'') <> 'DMD'
                  and (IsNull(it.Qtd_Produt,0)) > 0
                  Group by it.Cod_Produt) y ON (p.Cod_Produt = y.Cod_Produt)
            Where p.Cod_Estabe = @CodEstabe      
            And IsNull(p.Qtd_Solici,0) <> IsNull(x.Qtd_Solicitado,0)+IsNull(y.Qtd_Solicitado,0)
      Order by p.Cod_Produt
    end
  else
    PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': Estoques Solicitados em PRXES: ok'



Print ''
Print 'Verifica divergências em estoques solicitados em PRLOT x (PDV+AVARI+RESER+ORC):'

  -- verifica lotes solicitados em PRLOT
  if Exists(Select lt.Cod_Produt, lt.Cod_Lote, lt.Qtd_Solicitado, 
                   (IsNull(a.Qtd_Sol,0)+IsNull(b.Qtd_Sol,0)+IsNull(c.Qtd_Sol,0)+IsNull(d.Qtd_Sol,0)+IsNull(e.Qtd_Sol,0)) as Qtd_SolTot
            From (Select Cod_Estabe, Cod_Produt, Cod_Lote, Qtd_Solicitado=SUM(IsNull(Qtd_Solicitado,0))
                  From PRLOT
                  Where Cod_Estabe = @CodEstabe
                  Group by Cod_Estabe, Cod_Produt, Cod_Lote) lt Left Outer Join
  
                 (Select it.Cod_Produto, it.Cod_Lote,
                         sum(Isnull(it.Qtd_Pra,0))+sum(Isnull(it.Qtd_Dep,0)) as Qtd_Sol
                  From PDVCB cb Inner Join 
                       PDVIT it on (cb.Cod_Estabe = it.Cod_Estabe And cb.Numero = it.Cod_Pedido)
                  Where cb.Cod_Estabe = @CodEstabe
                  and cb.Tip_Pedido = 'P'
                  and IsNull(cb.Flg_WMS,0) = 0
                  and cb.Status1 = 'P'
                  and cb.Status2 <> 'N'
                  and cb.Status2 <> 'D'
                  and IsNull(cb.Bloqueio,'') <> 'SR'
                  and (IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)) > 0
                  Group by it.Cod_Produto, it.Cod_Lote) a ON (lt.Cod_Produt = a.Cod_Produto and lt.Cod_Lote = a.Cod_Lote) Left Outer Join
                  
                 (Select it.Cod_Produt, it.Cod_Lote,
                         sum(Isnull(it.Qtd_LotePra,0))+sum(Isnull(it.Qtd_LoteDep,0)) as Qtd_Sol
                  From PDVCB cb Inner Join
                       PDVLT it on (cb.Cod_Estabe = it.Cod_Estabe And cb.Numero = it.Cod_Pedido)
                  Where cb.Cod_Estabe = @CodEstabe
                  and cb.Tip_Pedido = 'P'
                  and IsNull(cb.Flg_WMS,0) = 1
                  and cb.Status1 = 'P'
                  and cb.Status2 <> 'N'
                  and cb.Status2 <> 'D'
                  and IsNull(cb.Bloqueio,'') <> 'SR'
                  and IsNull(it.Qtd_Lote,0) > 0
                  and it.Qtd_CxaFec = 0
                  Group by it.Cod_Produt, it.Cod_Lote) b ON (lt.Cod_Produt = b.Cod_Produt and lt.Cod_Lote = b.Cod_Lote) Left Outer Join
                  
                 (Select Cod_Produto, Cod_Lote,                     
                         sum(Isnull(Qtd_Movimento,0))+sum(Isnull(Qtd_AvaDep,0)) as Qtd_Sol
                  From AVARI
                  Where Cod_Estabe = @CodEstabe
                  Group by Cod_Produto, Cod_Lote) c ON (lt.Cod_Produt = c.Cod_Produto and lt.Cod_Lote = c.Cod_Lote) Left Outer Join
  
                 (Select Cod_Produto, Cod_Lote,                     
                         sum(Isnull(Qtd_Movimento,0))+sum(Isnull(Qtd_ResDep,0)) as Qtd_Sol
                  From RESER
                  Where Cod_Estabe = @CodEstabe
                  Group by Cod_Produto, Cod_Lote) d ON (lt.Cod_Produt = d.Cod_Produto and lt.Cod_Lote = d.Cod_Lote) Left Outer Join
  
                 (Select it.Cod_Produt, it.Cod_Lote,
                         sum(Isnull(it.Qtd_Produt,0)) as Qtd_Sol
                  From ORCCB cb Inner Join
                       ORCIT it on (cb.Cod_Estabe = it.Cod_Estabe and cb.Cod_Orcame = it.Cod_Orcame)
                  Where cb.Cod_Estabe = @CodEstabe
                  And cb.Sta_Movime = 'F'
                  and IsNull(cb.Num_Docume,0) = 0
                  and it.Tip_EntSai = 'S'
                  And IsNull(cb.Cod_OriVen,'') <> 'DMD'
                  and (IsNull(it.Qtd_Produt,0)) > 0
                  Group by it.Cod_Produt, it.Cod_Lote) e ON (lt.Cod_Produt = e.Cod_Produt and lt.Cod_Lote = e.Cod_Lote) 
                  
            Where lt.Cod_Estabe = @CodEstabe      
            And lt.Qtd_Solicitado <> (IsNull(a.Qtd_Sol,0)+IsNull(b.Qtd_Sol,0)+IsNull(c.Qtd_Sol,0)+IsNull(d.Qtd_Sol,0)+IsNull(e.Qtd_Sol,0)))
    begin
      PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': ===> Existem DIVERGENCIAS DE QUANTIDADES SOLICITADAS: PRLOT x (PDV+AVARI+RESER+ORC)'
      Select lt.Cod_Estabe,
	         lt.Cod_Produt as 'Produto', 
             lt.Cod_Lote as 'Lote', 
             lt.Qtd_Solicitado as 'Qtd.Solicitada em PRLOT', 
             (IsNull(a.Qtd_Sol,0)+IsNull(b.Qtd_Sol,0)+IsNull(c.Qtd_Sol,0)+IsNull(d.Qtd_Sol,0)+IsNull(e.Qtd_Sol,0)) as 'Qtd.Solicida em (PDV+RESER+AVARI+ORC)'
      From (Select Cod_Estabe, Cod_Produt, Cod_Lote, Qtd_Solicitado=SUM(IsNull(Qtd_Solicitado,0))
            From PRLOT
            Where Cod_Estabe = @CodEstabe
            Group by Cod_Estabe, Cod_Produt, Cod_Lote) lt Left Outer Join
  
           (Select it.Cod_Produto, it.Cod_Lote,
                   sum(Isnull(it.Qtd_Pra,0))+sum(Isnull(it.Qtd_Dep,0)) as Qtd_Sol
            From PDVCB cb Inner Join 
                 PDVIT it on (cb.Cod_Estabe = it.Cod_Estabe and cb.Numero = it.Cod_Pedido)
            Where cb.Cod_Estabe = @CodEstabe
            and cb.Tip_Pedido = 'P'
            and IsNull(cb.Flg_WMS,0) = 0
            and cb.Status1 = 'P'
            and cb.Status2 <> 'N'
            and cb.Status2 <> 'D'
            and IsNull(cb.Bloqueio,'') <> 'SR'
            and (IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)) > 0
            Group by it.Cod_Produto, it.Cod_Lote) a ON (lt.Cod_Produt = a.Cod_Produto and lt.Cod_Lote = a.Cod_Lote) Left Outer Join
      
           (Select it.Cod_Produt, it.Cod_Lote,
                   sum(Isnull(it.Qtd_LotePra,0))+sum(Isnull(it.Qtd_LoteDep,0)) as Qtd_Sol
            From PDVCB cb Inner Join
                 PDVLT it on (cb.Cod_Estabe = it.Cod_Estabe and cb.Numero = it.Cod_Pedido)
            Where cb.Cod_Estabe = @CodEstabe
            and cb.Tip_Pedido = 'P'
            and IsNull(cb.Flg_WMS,0) = 1
            and cb.Status1 = 'P'
            and cb.Status2 <> 'N'
            and cb.Status2 <> 'D'
            and IsNull(cb.Bloqueio,'') <> 'SR'
            and IsNull(it.Qtd_Lote,0) > 0
            and it.Qtd_CxaFec = 0
            Group by it.Cod_Produt, it.Cod_Lote) b ON (lt.Cod_Produt = b.Cod_Produt and lt.Cod_Lote = b.Cod_Lote) Left Outer Join
            
           (Select Cod_Produto, Cod_Lote,                     
                   sum(Isnull(Qtd_Movimento,0))+sum(Isnull(Qtd_AvaDep,0)) as Qtd_Sol
            From AVARI
            Where Cod_Estabe = @CodEstabe
            Group by Cod_Produto, Cod_Lote) c ON (lt.Cod_Produt = c.Cod_Produto and lt.Cod_Lote = c.Cod_Lote) Left Outer Join
       
           (Select Cod_Produto, Cod_Lote,                     
                   sum(Isnull(Qtd_Movimento,0))+sum(Isnull(Qtd_ResDep,0)) as Qtd_Sol
            From RESER
            Where Cod_Estabe = @CodEstabe
            Group by Cod_Produto, Cod_Lote) d ON (lt.Cod_Produt = d.Cod_Produto and lt.Cod_Lote = d.Cod_Lote) Left Outer Join
                       
           (Select it.Cod_Produt, it.Cod_Lote,
                   sum(Isnull(it.Qtd_Produt,0)) as Qtd_Sol
            From ORCCB cb Inner Join
                 ORCIT it on (cb.Cod_Estabe = it.Cod_Estabe and cb.Cod_Orcame = it.Cod_Orcame)
            Where cb.Cod_Estabe = @CodEstabe
            And cb.Sta_Movime = 'F'
            and IsNull(cb.Num_Docume,0) = 0
            and it.Tip_EntSai = 'S'
            And IsNull(cb.Cod_OriVen,'') <> 'DMD'
            and (IsNull(it.Qtd_Produt,0)) > 0
            Group by it.Cod_Produt, it.Cod_Lote) e ON (lt.Cod_Produt = e.Cod_Produt and lt.Cod_Lote = e.Cod_Lote) 
                       
      Where lt.Cod_Estabe = @CodEstabe      
      And lt.Qtd_Solicitado <> (IsNull(a.Qtd_Sol,0)+IsNull(b.Qtd_Sol,0)+IsNull(c.Qtd_Sol,0)+IsNull(d.Qtd_Sol,0)+IsNull(e.Qtd_Sol,0))
    end
  else
    PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': Estoques Solicitado em PRLOT x (PDV+AVARI+RESER+ORC): ok'



Print ''
Print 'Verifica divergências de quantidades solicitadas: PRLTL x PDVLT :'

  
  -- verifica lotes solicitados em PRLTL
  if Exists(Select lt.Cod_Produt, lt.Cod_Lote, sum(lt.Qtd_Solicitado), x.Qtd_SolTotPdv
            From PRLTL lt 
            Inner Join (Select it.Cod_Produt, it.Cod_Lote,
                              sum(Isnull(it.Qtd_LotePra,0))+sum(Isnull(it.Qtd_LoteDep,0)) as Qtd_SolTotPdv
                       From PDVCB cb, PDVLT it
                       Where cb.Cod_Estabe = it.Cod_Estabe 
                       and cb.Numero = it.Cod_Pedido
                       and cb.Cod_Estabe = @CodEstabe
                       and cb.Tip_Pedido = 'P'
                       and IsNull(cb.Flg_WMS,0) = 1
                       and cb.Status1 = 'P'
                       and cb.Status2 <> 'N'
                       and cb.Status2 <> 'D'
                       and IsNull(cb.Bloqueio,'') <> 'SR'
                       and IsNull(it.Qtd_Lote,0) > 0
                       and it.Qtd_CxaFec > 0
                       Group by it.Cod_Produt, it.Cod_Lote) x on (lt.Cod_Produt = x.Cod_Produt and lt.Cod_Lote = x.Cod_lote)
            Where lt.Cod_Estabe = @CodEstabe
            Group by lt.Cod_Produt, lt.Cod_Lote, x.Qtd_SolTotPdv
            Having sum(lt.Qtd_Solicitado) <> IsNull(x.Qtd_SolTotPdv,0))
    begin
      PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': ===> Existem DIVERGENCIAS DE QUANTIDADES SOLICITADAS: PRLTL x PDVLT'

      Select lt.Cod_Estabe,
	         lt.Cod_Produt as 'Produto', lt.Cod_Lote as 'Lote', sum(lt.Qtd_Solicitado) as 'Qtd.Solicitada em PRLTL', 
             IsNull(x.Qtd_SolTotPdv,0) as 'Qtd.Solicida em PDVCB'
      From PRLTL lt 
      Inner Join (Select it.Cod_Produt, it.Cod_Lote,
                         sum(Isnull(it.Qtd_LotePra,0))+sum(Isnull(it.Qtd_LoteDep,0)) as Qtd_SolTotPdv
                 From PDVCB cb, PDVLT it
                 Where cb.Cod_Estabe = it.Cod_Estabe 
                 and cb.Numero = it.Cod_Pedido
                 and cb.Cod_Estabe = @CodEstabe
                 and cb.Tip_Pedido = 'P'
                 and IsNull(cb.Flg_WMS,0) = 1
                 and cb.Status1 = 'P'
                 and cb.Status2 <> 'N'
                 and cb.Status2 <> 'D'
                 and IsNull(cb.Bloqueio,'') <> 'SR'
                 and IsNull(it.Qtd_Lote,0) > 0
                 and it.Qtd_CxaFec > 0
                 Group by it.Cod_Produt, it.Cod_Lote) x on (lt.Cod_Produt = x.Cod_Produt and lt.Cod_Lote = x.Cod_lote)
      Where lt.Cod_Estabe = @CodEstabe           
      Group by lt.Cod_Estabe, lt.Cod_Produt, lt.Cod_Lote, x.Qtd_SolTotPdv
      Having sum(lt.Qtd_Solicitado) <> IsNull(x.Qtd_SolTotPdv,0)
    end
  else
    PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': Estoques Solicitado em PRLTL x PDVLT: ok'




Print ''
Print 'Verifica slados negativos em PRLOT:'

  -- verifica saldo negativo em PRLOT
  if Exists(Select Cod_Produt From PRLOT Where Cod_Estabe = @CodEstabe And (Qtd_SldPra < 0) or (Qtd_SldDep < 0))
    begin
      PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': ===> Existem SALDOS NEGATIVOS EM PRLOT'
      Select Cod_Produt as 'Prd. c/Saldo Negativo (PRLOT)', 
             Cod_Lote,
             Qtd_SldPra as 'Saldo 1', 
             Qtd_SldDep as 'Saldo 2'
      From PRLOT
      Where Cod_Estabe = @CodEstabe 
      And (Qtd_SLdPra < 0) or (Qtd_SldDep < 0)
    end
  else
    PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': Saldos Negativos em PRLOT: ok'

Print ''
Print 'Verifica saldos negativos em PRLTL:'

  -- verifica saldo negativo em PRLTL
  if Exists(Select Cod_Produt From PRLTL Where Cod_Estabe = @CodEstabe And (Qtd_SldPra < 0) or (Qtd_SldDep < 0))
    begin
      PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': ===> Existem SALDOS NEGATIVOS EM PRLTL'
      Select Cod_Produt as 'Prd. c/Saldo Negativo (PRLTL)', 
             Cod_Lote,
             Qtd_SldPra as 'Saldo 1', 
             Qtd_SldDep as 'Saldo 2'
      From PRLTL
      Where Cod_Estabe = @CodEstabe 
      And (Qtd_SLdPra < 0) or (Qtd_SldDep < 0)
    end
  else
    PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': Saldos Negativos em PRLTL: ok'


Print ''
Print 'Verifica divergências de estoques: PRXES x PRLOT+PRLTL :'

  -- verifica qtd.disponivel de PRXES com saldo em PRLOT
  if Exists(Select p.Cod_Produt From PRXES p Left Outer Join 
                                 PRLOT l on p.Cod_Estabe = l.Cod_Estabe and p.Cod_Produt = l.Cod_Produt Left Outer Join 
                                 PRLTL d on p.Cod_Estabe = d.Cod_Estabe and p.Cod_Produt = d.Cod_Produt
            Where p.Cod_Estabe = @CodEstabe
            and p.Qtd_Dispon > 0
            And l.Cod_Produt is Null And d.Cod_Produt is Null)
    Select p.Cod_Produt as 'Prd.s/Lotes disponíveis', p.Qtd_Dispon as 'Disponível em PRXES'
      From PRXES p Left Outer Join 
           PRLOT l on p.Cod_Estabe = l.Cod_Estabe and p.Cod_Produt = l.Cod_Produt Left Outer Join 
           PRLTL d on p.Cod_Estabe = d.Cod_Estabe and p.Cod_Produt = d.Cod_Produt
      Where p.Cod_Estabe = @CodEstabe
      and p.Qtd_Dispon > 0
      And l.Cod_Produt is Null And d.Cod_Produt is Null
    
  if Exists(Select p.Cod_Produt
              From PRXES p 
                   Left Outer Join
                   (Select Cod_Produt, sum(Qtd_Saldo) as QtdSldFra, sum(Qtd_Solicitado) as QtdSolFra
                      From PRLOT 
                      Where Cod_Estabe = @CodEstabe
                      and ((Qtd_Saldo > 0) or (Qtd_Solicitado > 0))
                      Group by Cod_Produt) l on (p.Cod_Produt = l.Cod_Produt)
                   Left Outer Join
                   (Select Cod_Produt, sum(Qtd_Saldo) as QtdSldDep, sum(Qtd_Solicitado) as QtdSolDep
                      From PRLTL
                      Where Cod_Estabe = @CodEstabe
                      and ((Qtd_Saldo > 0) or (Qtd_Solicitado > 0))
                      Group by Cod_Produt) d on (p.Cod_Produt = d.Cod_Produt)     
            Where p.Cod_Estabe = @CodEstabe 
            and p.Qtd_Dispon+(p.Qtd_Solici+p.Qtd_Reserv+p.Qtd_Avaria-IsNull(QtdSolFra,0)-IsNull(QtdSolDep,0)) <> IsNull(l.QtdSldFra,0)+IsNull(d.QtdSldDep,0))
    begin
      PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': ===> Existem DIVERGENCIAS DE ESTOQUES: PRXES x PRLOT+PRLTL'
      Select p.Cod_Estabe,
	         p.Cod_Produt as 'Prd.c/divergência (PRXES x PRLOT+PRLTL)', p.Qtd_Dispon as 'Disponível em PRXES', 
             IsNull(l.QtdSldFra,0)+IsNull(d.QtdSldDep,0) as 'Disponível em PRLOT+PRLTL',
             (p.Qtd_Solici+p.Qtd_Reserv+p.Qtd_Avaria-IsNull(QtdSolFra,0)-IsNull(QtdSolDep,0)) as 'Lotes nao solicitados',
             IsNull(l.QtdSldFra,0)+IsNull(d.QtdSldDep,0)-(p.Qtd_Dispon+p.Qtd_Solici+p.Qtd_Reserv+p.Qtd_Avaria-IsNull(QtdSolFra,0)-IsNull(QtdSolDep,0)) as 'Diferença'
        From PRXES p 
             Left Outer Join
            (Select Cod_Produt, sum(Qtd_Saldo) as QtdSldFra, sum(Qtd_Solicitado) as QtdSolFra
               From PRLOT 
               Where Cod_Estabe = @CodEstabe 
               and ((Qtd_Saldo > 0) or (Qtd_Solicitado > 0))
               Group by Cod_Produt) l on (p.Cod_Produt = l.Cod_Produt)
             Left Outer Join
            (Select Cod_Produt, sum(Qtd_Saldo) as QtdSldDep, sum(Qtd_Solicitado) as QtdSolDep
               From PRLTL
               Where Cod_Estabe = @CodEstabe 
               and ((Qtd_Saldo > 0) or (Qtd_Solicitado > 0))
               Group by Cod_Produt) d on (p.Cod_Produt = d.Cod_Produt)
        Where p.Cod_Estabe = @CodEstabe 
        and p.Qtd_Dispon+(p.Qtd_Solici+p.Qtd_Reserv+p.Qtd_Avaria-IsNull(QtdSolFra,0)-IsNull(QtdSolDep,0)) <> IsNull(l.QtdSldFra,0)+IsNull(d.QtdSldDep,0)
        Order by p.Cod_Produt
    end
  else
    PRINT '  Estabelecimento '+cast(@CodEstabe as varchar)+': Estoque Disponível: PRXES x PRLOT+PRLTL ok!'

PRINT ''
PRINT 'FIM DE VERIFICACAO ...'
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_SolicitaLoteEspecificoPDV]
/*
Solicita lote especifico do Picking

*/
@PCodEstabe int,
@PCodPed int,             
@PCodPrd int,
@PCodLotEsp varchar(20),  -- lote especifico
@PQtdPed int             -- quantidade pedida do lote
--@PMsg varchar(80) output  -- Quantidde pedida do lote: 1000. Quantidae Atendida: 1000.

AS

SET NOCOUNT ON 

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)


Declare @MsgErr varchar(50) = '',
        @QtdSld int = 0,
        @FlgUndMin bit = 0 

Set @PCodLotEsp = Ltrim(Rtrim(@PCodLotEsp))

if not Exists(Select 1 From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PCodPed)
  begin
    RAISERROR('Pedido inexistente',16,1)
    Return
  end

if not Exists(Select 1 From PDVIT Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @PCodPed And Cod_Produto = @PCodPrd And Qtd_Pedido > 0)
  begin
    RAISERROR('Produto inexiste no pedido',16,1)
    Return
  end

Set @MsgErr = IsNull((Select MsgErr = Case
                                        When CharIndex(Status2,';N;D;') > 0 then 'Pedido já faturado'
                                        When (Status1 <> 'P') or (Status2 <> 'F') then 'Pedido não está pendente/fechado'
                                        When IsNull(Bloqueio,'') <> '' then 'Pedido está bloqueado'
                                        When IsNull(Flg_Wms,0) = 0 then 'Pedido não permite solicitar lotes'
                                        Else ''
                                      End
                        From PDVCB
                       Where Cod_Estabe = @PCodEstabe
                         And Numero = @PCodPed),'')

if (@MsgErr = '') and
   Exists(Select Cod_Produto, Tip_Sai, count(*) From PDVIT Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @PCodPed Group By Cod_Produto, Tip_Sai Having count(*) > 1)
  Set @MsgErr = 'Existe mais de um lote no pedido'

if @MsgErr <> ''
  begin
    RAISERROR(@MsgErr,16,1)
    Return
  end

if @PCodLotEsp = ''
  begin
    RAISERROR('Lote não informado',16,1)
    Return
  end

Set @QtdSld = IsNull((Select Qtd_Saldo From PRLOT Where Cod_Estabe = @PCodEstabe and Cod_Produt = @PCodPrd and Cod_Lote = @PCodLotEsp),0)
if @QtdSld = 0
  begin
    RAISERROR('Produto/Lote inexistente ou Sem Estoque',16,1)
    Return
  end

if @PQtdPed <= 0
  begin
    RAISERROR('Quantidade solicitada inválida',16,1)
    Return
  end

-- verifica se a qtd solicitade não excede a qtd pendente a solicitar
Set @QtdSld = IsNull((Select QtdSld = (IsNull(it.QtdPdvTot,0)-IsNull(d.QtdSolTot,0))
                        From (Select Cod_Estabe, Cod_Produto, sum(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) as QtdPdvTot
                                From PDVIT 
                               Where Cod_Estabe = @PCodEstabe
                                And Cod_Pedido = @PCodPed
                                And Cod_Produto = @PCodPrd
                                And IsNull(Qtd_Pedido,0) > 0
                              Group by Cod_Estabe, Cod_Produto
                             ) it Left Outer Join

                             (Select Cod_Estabe, Cod_Produt, sum(IsNull(Qtd_Lote,0)) as QtdSolTot
                                From PDVLT
                               Where Cod_Estabe = @PCodEstabe
                                And Cod_Pedido = @PCodPed
                                And Cod_Produt = @PCodPrd
                                And IsNull(Qtd_Lote,0) > 0 
                              Group by Cod_Estabe, Cod_Produt
                             ) d on (it.Cod_Estabe = d.Cod_Estabe and it.Cod_Produto = d.Cod_Produt
                     )
                    ),0)
if @QtdSld < 0
  begin
    RAISERROR('Quantidade já solicitada excede à quatidade pedida',16,1)
    Return
  end
if @QtdSld = 0
  begin
    RAISERROR('Quantidade do pedido já foi totalmente atendida',16,1)
    Return
  end
if @PQtdPed > @QtdSld
  begin
    Set @MsgErr = 'Quantidade pedida excede quantidade pendente ('+cast(@QtdSld as varchar)+')'
    RAISERROR(@MsgErr,16,1)
    Return
  end

-- verifica se cliente bloqueia produto com mais de um lote
if Exists(Select 1 From CLIEN cl Inner Join PDVCB cb on (cb.Cod_Cliente = cl.Codigo)
           Where cb.Cod_Estabe = @PCodEstabe And cb.Numero = @PCodPed
             And IsNull(cl.Flg_BlqLotVarPdv,0) = 1) and
   Exists(Select 1 From PDVLT WHere Cod_Estabe = @PCodEstabe And Cod_Pedido = @PCodPed 
             And Cod_Produt = @PCodPrd And Cod_Lote <> @PCodLotEsp)
  begin
    RAISERROR('Cliente não permite mais de um lote do mesmo produto',16,1)
    Return
  end

-- verifica se trabalha com unidade minima
Set @MsgErr = ''

Select @FlgUndMin = IsNull(FlgAltUnvItePdv,0) 
  From PARAM Where Cod_Estabe = @PCodEstabe

-- se trabalha com unidade minima verifica apresentações padrão
if Exists(Select 1
            From PDVIT it
                 Inner Join PARAM pa on it.Cod_Estabe = pa.Cod_Estabe
                 Left  Join PRXAP ap on it.Cod_Produto = ap.Cod_Produt and IsNull(ap.Flg_Padrao,0) = 1
           Where it.Cod_Estabe = @PCodEstabe And it.Cod_Pedido = @PCodPed And it.Cod_Produto = @PCodPrd
             And it.Qtd_Pedido > 0
             And @FlgUndMin = 1
             And ap.Cod_Produt is null)
  Set @MsgErr = 'Produto sem Apresentação Padrão'
else
-- se trabalha com unidade minima verifica produtos com mais de 1 apresentação padrão
if Exists(Select 1
            From PRXAP ap
           Where ap.Flg_Padrao = 1
             And @FlgUndMin = 1
             And Exists(Select 1 From PDVIT it Where it.Cod_Estabe = @PCodEstabe and it.Cod_Pedido = @PCodPed And it.Cod_Produto = ap.Cod_Produt And it.Qtd_Pedido > 0 )
           Group by ap.Cod_Produt
          Having count(*) > 1)
  Set @MsgErr = 'Produto com mais de uma Apresentação Padrão'
else
  -- se trabalha com unidade minima verifica produtos sem medidas da embalagem padrao
if Exists(Select 1
            From PDVIT it
                 Left Join PRXAP ap on it.Cod_Produto = ap.Cod_Produt and ap.Flg_Padrao = 1
           Where it.Cod_Estabe = @PCodEstabe 
             And it.Cod_Pedido = @PCodPed 
             And it.Cod_Produto = @PCodPrd
             And it.Qtd_Pedido > 0
             And ((IsNull(ap.Fat_CnvApr,0) = 0) or (IsNull(ap.Vol_Emb,0) = 0))
             And @FlgUndMin = 1)
  Set @MsgErr = 'Produto com Cadastro da Apresentação Padrão Incompleto'
else
-- se nao trabalha com unidade minima verifica produtos sem medidas da embalagem padrao
if Exists(Select 1
            From PDVIT it
                 Left Join PRODU pr on it.Cod_Produto = pr.Codigo
           Where it.Cod_Estabe = @PCodEstabe 
             And it.Cod_Pedido = @PCodPed 
             And it.Cod_Produto = @PCodPrd
             And it.Qtd_Pedido > 0
             And IsNull(pr.Vol_Emb,0) = 0
             And @FlgUndMin = 0)
  Set @MsgErr = 'Produto com Cadastro da Embalagem Padrão Incompleto'

if @MsgErr <> ''
  begin
    RAISERROR(@MsgErr,16,1)
    Return
  end


BEGIN
  --Set @PMsg = ''

  Declare @CodPrd int,
          @TipSai varchar(1),
          @QtdSdo int,
          @CodLotTip varchar(20),
          @QtdTotTip int,
          @QtdPraTip int,
          @QtdDepTip int,
          @QtdFra int,
          @QtdEmbFec int,
          @QtdSldFiscal int,
          @QtdSolTot int,
          @cl_CodCliPag int,
          @cl_CodGrpCli int,
          @cl_QtdMesMinPrzVctLot int,
          @cl_FlgBlqLotVarPdv bit,
          @FlgIntWms bit = 0,
          @BlqEstFisNeg bit = 0,
          @StaIntWms varchar(1),
          @FlgTipVenFat bit = 0,
          @FlgPodeFechar bit = 0,
		  @Usuario varchar(15)

  Set @Usuario = dbo.FN_UsuarioInfarma()

  Select @FlgIntWms = IsNull(FlgIntegrWmsExt,0),
         @BlqEstFisNeg = IsNull(BlqEstFisNeg,0)   -- nao permite negativar estoque fiscal
    From PMEST Where Cod_Estabe = @PCodEstabe

  Select @StaIntWms = IsNull(cb.Sta_IntWms,''),
         @FlgTipVenFat = Case When ISNull(op.Cod_CfoNorInt,0) > 0 then 1 ELse 0 End
    From PDVCB cb
         Left Join TPOPE op on cb.Tip_Faturamento = op.Cod_Ope 
   Where cb.Cod_Estabe = @PCodEstabe and cb.Numero = @PCodPed


  Begin Transaction

    Set @FlgPodeFechar = 0

    if @FlgIntWms = 0
      Set @FlgPodeFechar = 1
    else
    if @StaIntWms = ''
      begin
	  -- aqui ????
        Update PDVCB
           Set Sta_IntWMS = '0'
         Where Cod_Estabe = @PCodEstabe 
           And Numero = @PCodPed
           And IsNull(Sta_IntWMS,'') = ''

--aqui        Exec PR_WMSGerarXMLSaida @PCodEstabe, @PCodPed
      end

    if @FlgPodeFechar = 1
      begin 
		-- TBZON
        Update TBZON
           Set Num_Esteira = 1
         Where Cod_Estabe = @PCodEstabe
           And ISNULL(Num_Esteira,0) = 0

        Declare @NumVol int,
                @to_CodCfoNorInt int,
                @DatVct smalldatetime,
                @CodLot varchar(20),
                @LocEst varchar(1),
                @OrdDep varchar(1),
                @CodDep int, 
                @NumEst smallint,
                @NumRua int, 
                @NumCol int, 
                @NumNiv int, 
                @NumApt int, 
                @SldLot int,
                @FatCnvAprEmbPad int,
                @QtdPra int,
                @QtdDep int,
                @QtdLot int,
                @FlgDesord bit,
                @dx_CodLocFis varchar(15),
                @pr_VolUniMin numeric(18,8),  -- @pr_VolEmb
                @VolTotIte numeric(18,4),
                @QtdAteAcu int,
                @QtdAte int

        Select @cl_CodCliPag = Case 
                                 When IsNull(cl.Cod_CliPag,0) > 0 then cl.Cod_CliPag
                                 Else IsNull(cl.Codigo,0)
                               End,
               @cl_QtdMesMinPrzVctLot = IsNull(cl.Qtd_MesMinPrzVctLot,0),
               @cl_CodGrpCli = IsNull(cl.Cod_GrpCli,0),
			   @cl_FlgBlqLotVarPdv = IsNull(Flg_BlqLotVarPdv,0)
          From PDVCB cb Left Join CLIEN cl on (cb.Cod_Cliente = cl.Codigo)
         Where cb.Cod_Estabe = @PCodEstabe 
           And cb.Numero = @PCodPed
          
        Select @to_CodCfoNorInt = IsNull(t.Cod_CfoNorInt,0)
          From PDVCB p Left Join TPOPE t on (t.Cod_Ope = p.Tip_Faturamento)
         Where p.Cod_Estabe = @PCodEstabe 
           And p.Numero = @PCodPed

        Set @NumVol = 0

        -- elimina registro de conferencia existentes
        if Exists(Select 1 from CPVIT Where Cod_Estabe = @PCodEstabe And Num_PedCnf = @PCodPed) 
          Delete from CPVIT Where Cod_Estabe = @PCodEstabe And Num_PedCnf = @PCodPed
        if Exists(Select 1 From CPVCB Where Cod_Estabe = @PCodEstabe And Num_PedCnf = @PCodPed)
          Delete from CPVCB Where Cod_Estabe = @PCodEstabe And Num_PedCnf = @PCodPed
        
        -- cria arq. de fracionados
        IF OBJECT_ID('tempdb..#ARQ_FRAC') IS NOT NULL
          DROP TABLE #ARQ_FRAC
  
        CREATE TABLE #ARQ_FRAC
        (
            Chave int identity,
            Cod_Dep smallint,
            Num_Esteira smallint,
            Cod_Produto int,
            Cod_Lote varchar(20),
            Qtd_Lote int,
            Qtd_Pra int,
            Qtd_Dep int,
            Qtd_EmbFec int,
            Fat_CnvAprPad int, 
            Vol_UniIte numeric(18,8),
            Num_Rua smallint,
            Num_Col smallint,
            Num_Niv smallint,
            Num_Apt smallint,
            Cod_LocFis varchar(15),
            Flg_Desord bit
        ) 
        
        -- valida fracionado a solicitar descontando o que já foi soicitado (PDVLT)
        -- verifica se cliente bloqueia produto com lotes diferentes
        Select @QtdEmbFec = pr.Qtd_Embalagem, 
               @pr_VolUniMin = Case 
                                 When @FlgUndMin = 0 then IsNull(pr.Vol_Emb,0)
                                 Else IsNull(ap.Vol_Emb/ap.Fat_CnvApr,0)
                               End,
               @QtdFra = Case 
                           When x.QtdPen <= 0 then 0
                           When (@cl_FlgBlqLotVarPdv = 1) and 
                                Exists(Select 1 From PDVLT WHere Cod_Estabe = @PCodEstabe 
                                       And Cod_Pedido = @PCodPed And Cod_Produt = @PCodPrd And Cod_Lote <> @PCodLotEsp) then 0
                           When x.QtdPen >= @PQtdPed then @PQtdPed
                           Else x.QtdPen
                         End
          From (Select it.Cod_Produto, QtdPen = (it.QtdPdvTot-IsNull(d.QtdSolTot,0))
                  From (Select Cod_Produto, sum(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) as QtdPdvTot
                          From PDVIT 
                         Where Cod_Estabe = @PCodEstabe
                           And Cod_Pedido = @PCodPed
                           And Cod_Produto = @PCodPrd
                           And IsNull(Qtd_Pedido,0) > 0
                         Group by Cod_Produto
                       ) it Left Outer Join
             
                       (Select Cod_Produt, sum(IsNull(Qtd_Lote,0)) as QtdSolTot
                          From PDVLT
                         Where Cod_Estabe = @PCodEstabe
                           And Cod_Pedido = @PCodPed
                           And Cod_Produt = @PCodPrd
                           And IsNull(Qtd_Lote,0) > 0 
                         Group by Cod_Produt
                       ) d on ( it.Cod_Produto = d.Cod_Produt)
               ) x 
               Inner Join PRODU pr on (x.Cod_Produto = pr.Codigo)
               Left  Join PRXAP ap on (pr.Codigo = ap.Cod_Produt) and (ap.Flg_Padrao = 1)


        -- verifica estoque fiscal negativo
        -- nao permite negativar estoque fiscal
        if (@BlqEstFisNeg = 1) and (@FlgTipVenFat = 1)
          begin
            -- qtd solicitada anteriormente
            Set @QtdSolTot = IsNull((Select sum(Qtd_Lote) From PDVLT Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @PCodPed 
                                        And Cod_Produt = @PCodPrd),0)
            Set @QtdSldFiscal = dbo.FN_SldFiscalDisponPrd(@PCodEstabe,@PCodPrd) - @QtdSolTot
            if @QtdSldFiscal < 0 Set @QtdSldFiscal = 0
            if @QtdFra > @QtdSldFiscal 
              Set @QtdFra = @QtdSldFiscal
          end
 
        Set @QtdAteAcu = 0    -- acumulador por produto

        -- fracionados solicita somente pelo vencimento --
        if @to_CodCfoNorInt > 0
          begin
            Declare PRLOT_Cr Cursor Local Fast_Forward For   
              Select '1' as CodLocEst, lt.OrdDep, lt.Cod_Dep, lt.Dat_Vencim, lt.Cod_Lote, lt.Qtd_SldPra, lt.Fat_CnvAprEmbPad
                From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote, 
                             Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldPra=IsNull(l1.Qtd_SldPra,0), Fat_CnvAprEmbPad=IsNull(l1.Fat_CnvAprEmbPad,0) 
                        From PRLOT l1 Inner Join
                             DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli
                       Where l1.Cod_Estabe = @PCodEstabe 
                         And l1.Cod_Produt = @PCodPrd
                         And l1.Cod_Lote = @PCodLotEsp
                         And IsNull(l1.Qtd_Saldo,0) > 0 
                         and IsNull(l1.Qtd_SldPra,0) > 0
                      UNION ALL
                      Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Dep, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                             Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldPra=IsNull(l2.Qtd_SldPra,0), Fat_CnvAprEmbPad=IsNull(l2.Fat_CnvAprEmbPad,0)
                        From PRLOT l2 
                       Where l2.Cod_Estabe = @PCodEstabe 
                         And l2.Cod_Produt = @PCodPrd
                         And l2.Cod_Lote = @PCodLotEsp
                         And IsNull(l2.Qtd_Saldo,0) > 0 
                         And IsNull(l2.Qtd_SldPra,0) > 0
        			     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Inner Join 
                     PRODU pr on lt.Cod_Produt = pr.Codigo Left Outer Join
                     CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                     CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
               Where lt.Cod_Estabe = @PCodEstabe 
                 And lt.Cod_Produt = @PCodPrd
                 And lt.Cod_Lote = @PCodLotEsp
                 And IsNull(lt.Qtd_Saldo,0) > 0 and IsNull(lt.Qtd_SldPra,0) > 0
                 And ((lt.Dat_Vencim is null) or 
                      (lt.Dat_Vencim >= Case
                                          When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                          When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                          Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                        End)) 
              UNION ALL
              Select '2' as CodLocEst, lt.OrdDep, lt.Cod_Dep, lt.Dat_Vencim, lt.Cod_Lote, lt.Qtd_SldDep, lt.Fat_CnvAprEmbPad
                From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote, 
                             Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldDep=IsNull(l1.Qtd_SldDep,0), Fat_CnvAprEmbPad=IsNull(l1.Fat_CnvAprEmbPad,0) 
                        From PRLOT l1 Inner Join
                             DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli
                       Where l1.Cod_Estabe = @PCodEstabe 
                         And l1.Cod_Produt = @PCodPrd
                         And l1.Cod_Lote = @PCodLotEsp
                         And IsNull(l1.Qtd_Saldo,0) > 0 
                         and IsNull(l1.Qtd_SldDep,0) > 0
                      UNION ALL
                      Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Dep, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                             Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldDep=IsNull(l2.Qtd_SldDep,0), Fat_CnvAprEmbPad=IsNull(l2.Fat_CnvAprEmbPad,0)
                        From PRLOT l2 
                       Where l2.Cod_Estabe = @PCodEstabe 
                         And l2.Cod_Produt = @PCodPrd
                         And l2.Cod_Lote = @PCodLotEsp
                         And IsNull(l2.Qtd_Saldo,0) > 0 
                         And IsNull(l2.Qtd_SldDep,0) > 0
        			     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Inner Join 
                     PRODU pr on lt.Cod_Produt = pr.Codigo Left Outer Join
                     CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                     CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
               Where lt.Cod_Estabe = @PCodEstabe 
                 And lt.Cod_Produt = @PCodPrd
                 And lt.Cod_Lote = @PCodLotEsp
                 And IsNull(lt.Qtd_Saldo,0) > 0 and IsNull(lt.Qtd_SldDep,0) > 0
                 And ((lt.Dat_Vencim is null) or 
                      (lt.Dat_Vencim >= Case
                                          When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                          When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                          Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                        End)) 
               Order by OrdDep, Dat_Vencim, CodLocEst
          end
        else
          begin
            Declare PRLOT_Cr Cursor Local Fast_Forward For 
              Select '1' as CodLocEst, lt.OrdDep, lt.Cod_Dep, lt.Dat_Vencim, lt.Cod_Lote, lt.Qtd_SldPra, lt.Fat_CnvAprEmbPad
                From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote, 
                             Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldPra=IsNull(l1.Qtd_SldPra,0), Fat_CnvAprEmbPad=IsNull(l1.Fat_CnvAprEmbPad,0) 
                        From PRLOT l1 Inner Join
                             DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli
                       Where l1.Cod_Estabe = @PCodEstabe 
                         And l1.Cod_Produt = @PCodPrd
                         And l1.Cod_Lote = @PCodLotEsp
                         And IsNull(l1.Qtd_Saldo,0) > 0 
                         and IsNull(l1.Qtd_SldPra,0) > 0
                      UNION ALL
                      Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Dep, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                             Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldPra=IsNull(l2.Qtd_SldPra,0), Fat_CnvAprEmbPad=IsNull(l2.Fat_CnvAprEmbPad,0) 
                        From PRLOT l2 
                       Where l2.Cod_Estabe = @PCodEstabe 
                         And l2.Cod_Produt = @PCodPrd
                         And l2.Cod_Lote = @PCodLotEsp
                         And IsNull(l2.Qtd_Saldo,0) > 0 
                         And IsNull(l2.Qtd_SldPra,0) > 0
        			     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Inner Join 
                     PRODU pr on lt.Cod_Produt = pr.Codigo Left Outer Join
                     CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                     CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
               Where lt.Cod_Estabe = @PCodEstabe 
                 And lt.Cod_Produt = @PCodPrd
                 And lt.Cod_Lote = @PCodLotEsp
                 And IsNull(lt.Qtd_Saldo,0) > 0 and IsNull(lt.Qtd_SldPra,0) > 0
                 And ((lt.Dat_Vencim is null) or 
                      (lt.Dat_Vencim >= Case
                                          When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                          When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                          Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                        End)) 
              UNION ALL
              Select '2' as CodLocEst, lt.OrdDep, lt.Cod_Dep, lt.Dat_Vencim, lt.Cod_Lote, lt.Qtd_SldDep, lt.Fat_CnvAprEmbPad
                From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote, 
                             Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldDep=IsNull(l1.Qtd_SldDep,0), Fat_CnvAprEmbPad=IsNull(l1.Fat_CnvAprEmbPad,0)
                        From PRLOT l1 Inner Join
                             DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli
                       Where l1.Cod_Estabe = @PCodEstabe 
                         And l1.Cod_Produt = @PCodPrd
                         And l1.Cod_Lote = @PCodLotEsp
                         And IsNull(l1.Qtd_Saldo,0) > 0 
                         and IsNull(l1.Qtd_SldDep,0) > 0
                      UNION ALL
                      Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Dep, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                             Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldDep=IsNull(l2.Qtd_SldDep,0), Fat_CnvAprEmbPad=IsNull(l2.Fat_CnvAprEmbPad,0)
                        From PRLOT l2
                       Where l2.Cod_Estabe = @PCodEstabe 
                         And l2.Cod_Produt = @PCodPrd
                         And l2.Cod_Lote = @PCodLotEsp
                         And IsNull(l2.Qtd_Saldo,0) > 0 
                         And IsNull(l2.Qtd_SldDep,0) > 0
        			     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Inner Join 
                     PRODU pr on lt.Cod_Produt = pr.Codigo Left Outer Join
                     CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                     CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
               Where lt.Cod_Estabe = @PCodEstabe 
                 And lt.Cod_Produt = @PCodPrd
                 And lt.Cod_Lote = @PCodLotEsp
                 And IsNull(lt.Qtd_Saldo,0) > 0 and IsNull(lt.Qtd_SldDep,0) > 0
                 And ((lt.Dat_Vencim is null) or 
                      (lt.Dat_Vencim >= Case
                                          When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                          When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                          Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                        End)) 
               Order by OrdDep, Dat_Vencim, CodLocEst desc
          end
        -------------------------------------------------------------------------------------------------------------------------------------------------------
        Open PRLOT_Cr
        Fetch Next From PRLOT_Cr Into @LocEst, @OrdDep, @CodDep, @DatVct, @CodLot, @SldLot, @FatCnvAprEmbPad
        
        Set @QtdAteAcu = 0
        
        While (@QtdAteAcu < @QtdFra) and (@QtdFra > 0) and (@@FETCH_STATUS = 0)
          begin
            Set @QtdAte = @QtdFra - @QtdAteAcu
            -- se o saldo do lote nao atender a qtd.solicitada refazer a solicitacao proporcionalmente
            if @QtdAte > @SldLot
              begin
                Set @QtdAte = @SldLot
              end
             -- Atualiza saldo do lote
            Set @QtdPra = 0
            Set @QtdDep = 0
            if @LocEst = '1'
              Set @QtdPra = @QtdAte
            else
              Set @QtdDep = @QtdAte
        
            Update PRLOT
               Set Qtd_SolPra = Qtd_SolPra + @QtdPra,
                   Qtd_SolDep = Qtd_SolDep + @QtdDep
             Where Cod_Estabe = @PCodEstabe 
               And Cod_Dep = @CodDep
               And Cod_Produt = @PCodPrd
               And Cod_Lote = @CodLot
        
            Set @QtdAteAcu = @QtdAteAcu + @QtdAte
        
            -- verifica se lote foi solicitado fora de ordem
            Set @FlgDesord = 0
            if (@DatVct is not Null) and (@cl_QtdMesMinPrzVctLot > 0) and 
               (Exists(Select Cod_Lote From PRLOT Where Cod_Estabe = @PCodEstabe And Cod_Dep = @CodDep And Cod_Produt = @PCodPrd And Qtd_Saldo > 0 And Dat_Vencim < @DatVct))
              Set @FlgDesord = 1
                       
            -- pega endereço de picking do produto
            Select @NumRua = dx.Num_Rua,
                   @NumCol = dx.Num_Col,   
                   @NumNiv = dx.Num_Niv,   
                   @NumApt = dx.Num_Apt,
                   @dx_CodLocFis = dx.Cod_LocFis,
                   @NumEst = ISNULL(z.Num_Esteira,0)   
              From DPXPR dx Left Outer Join
                   TBZON z on (dx.Cod_Estabe = z.Cod_Estabe and dx.Num_Rua between z.Num_RuaIni and z.Num_RuaFim)
             Where dx.Cod_Estabe = @PCodEstabe
               And dx.Cod_Dep = @CodDep
               And dx.Cod_Produt = @PCodPrd
                   
            Insert Into #ARQ_FRAC (Cod_Dep, Num_Esteira, Cod_Produto, Cod_Lote, Qtd_Lote, Qtd_Pra, Qtd_Dep, Vol_UniIte, 
                                   Qtd_EmbFec, Fat_CnvAprPad, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_LocFis, Flg_Desord)
                           Values (@CodDep, @NumEst, @PCodPrd, @CodLot, @QtdAte, @QtdPra, @QtdDep, @pr_VolUniMin, 
                                   @QtdEmbFec, @FatCnvAprEmbPad, @NumRua, @NumCol, @NumNiv, @NumApt, @dx_CodLocFis, @FlgDesord)
        
            Fetch Next From PRLOT_Cr Into @LocEst, @OrdDep, @CodDep, @DatVct, @CodLot, @SldLot, @FatCnvAprEmbPad
        
          end  -- While (@QtdAteAcu < @QtdFra) and (@@FETCH_STATUS = 0)
          
        Close PRLOT_Cr
        Deallocate PRLOT_Cr
        

---------- **************************************************  solicita lotes por vencimento da LINHA DE PICKING (FRACIONADOS)  ***************************************************
        Declare PDVIT_Cr Cursor Local Fast_Forward For 

          Select Cod_Produto, Cod_Lote, Qtd_EmbFec, Fat_CnvAprPad, Cod_LocFis, Vol_UniIte, Qtd_Lote, Qtd_Pra, Qtd_Dep,
                 Num_Esteira, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Flg_Desord
            From #ARQ_FRAC
           Order by Cod_Dep, Num_Esteira, Num_Rua, Num_Col, Num_Niv, Num_Apt

        Open PDVIT_Cr
        Fetch Next From PDVIT_Cr Into @CodPrd, @CodLot, @QtdEmbFec, @FatCnvAprEmbPad, @dx_CodLocFis, @pr_VolUniMin, @QtdFra, @QtdPra, @QtdDep,
                                      @NumEst, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @FlgDesord 
                           
        While @@FETCH_STATUS = 0
          begin

            -- grava/regrava registro em PDVLT 
            Set @NumVol = 1
            Set @VolTotIte = (@QtdPra+@QtdDep)*@pr_VolUniMin
            if not Exists(Select 1 From PDVLT Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @PCodPed And Num_Vol = @NumVol And Cod_Produt = @CodPrd And Cod_Lote = @CodLot)
              begin
                Insert Into PDVLT (Cod_Estabe,  Cod_Pedido, Num_Vol, Cod_Produt, Cod_Lote
                                 , Qtd_EmbFec, Qtd_Lote, Qtd_CxaFec
                                 , Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_LocFis
                                 , Qtd_LotePra, Qtd_LoteDep, Vol_TotIte, Id_PolCom , Flg_Desord, Flg_Manual
                                 , Cod_FunSep, Transacao)
                           Values (@PCodEstabe, @PCodPed,   @NumVol, @CodPrd,    @CodLot
                                 ,  0,          0,        0
                                 ,  @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @dx_CodLocFis
                                 ,  0,          0,           0,          0,          @FlgDesord, 1
                                 ,  0,          @Now)
                if @@error <> 0
                  begin
                    Rollback Transaction
                    Return
                  end
              end
         
            Update PDVLT
               Set Qtd_Lote = IsNull(Qtd_Lote,0) +  @QtdPra+@QtdDep
                 , Vol_TotIte = IsNull(Vol_TotIte,0) + @VolTotIte
                 , Qtd_LotePra = IsNull(Qtd_LotePra,0) + @QtdPra
                 , Qtd_LoteDep = IsNull(Qtd_LoteDep,0) + @QtdDep
             Where Cod_Estabe = @PCodEstabe 
               And Cod_Pedido = @PCodPed 
               And Num_Vol = @NumVol 
               And Cod_Produt = @CodPrd 
               And Cod_Lote = @CodLot

            Update PDVLT
               Set Flg_Manual = 1
                 , Qtd_Manual = Qtd_Lote
             Where Cod_Estabe = @PCodEstabe 
               And Cod_Pedido = @PCodPed 
               And Num_Vol = @NumVol 
               And Cod_Produt = @CodPrd 
               And Cod_Lote = @CodLot


            -- atualiza status de separação de lotes (manual)
            Update PDVCB
               Set Sta_SepLot = 'M'
             Where Cod_Estabe = @PCodEstabe 
               and Numero = @PCodPed
               and IsNull(Sta_SepLot,'') <> 'M'
         
            -- atualiza quantidades em PDVIT
            Declare Table_Cr Cursor Local Fast_Forward For 
           
              Select Cod_Lote, Tip_Sai, IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)-IsNull(Qtd_Pra,0)-IsNull(Qtd_Dep,0)
                From PDVIT 
               Where Cod_Estabe = @PCodEstabe 
                 And Cod_Pedido = @PCodPed
                 And Cod_Produto = @CodPrd 
                 And IsNull(Qtd_Pedido,0) > 0
               Order by Tip_Sai
           
            Open Table_Cr
            Fetch Next From Table_Cr Into @CodLotTip, @TipSai, @QtdTotTip
            While @@FETCH_STATUS = 0
              begin
                Set @QtdPraTip = 0
                Set @QtdDepTip = 0
                  
                Set @QtdSdo = @QtdTotTip
                while (@QtdSdo > 0) and (@QtdPra + @QtdDep > 0)
                  begin
                    if (@QtdPra > 0) and (@QtdSdo > 0)
                      begin
                        if @QtdSdo > @QtdPra
                          Set @QtdPraTip = @QtdPra
                        else
                          Set @QtdPraTip = @QtdSdo
                        Set @QtdPra = @QtdPra - @QtdPraTip
                        Set @QtdSdo = @QtdSdo - @QtdPraTip
                      end
                            
                    if (@QtdDep > 0) and (@QtdSdo > 0)
                      begin
                        if @QtdSdo > @QtdDep
                          Set @QtdDepTip = @QtdDep
                        else
                          Set @QtdDepTip = @QtdSdo
                        Set @QtdDep = @QtdDep - @QtdDepTip
                        Set @QtdSdo = @QtdSdo - @QtdDepTip
                      end
                  end  -- while @QtdSdo > 0
                      
                Update PDVIT
                   Set Qtd_Pra = Qtd_Pra + @QtdPraTip,
                       Qtd_Dep = Qtd_Dep + @QtdDepTip
                 Where Cod_Estabe = @PCodEstabe 
                   And Cod_Pedido = @PCodPed 
                   And Cod_Produto = @CodPrd 
                   And Cod_Lote = @CodLotTip
                   And Tip_Sai = @TipSai
           
                Fetch Next From Table_Cr Into @CodLotTip, @TipSai, @QtdTotTip 
              end
            Close Table_Cr
            Deallocate Table_Cr
           
            Fetch Next From PDVIT_Cr Into @CodPrd, @CodLot, @QtdEmbFec, @FatCnvAprEmbPad, @dx_CodLocFis, @pr_VolUniMin, @QtdFra, @QtdPra, @QtdDep,
                                          @NumEst, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @FlgDesord 
                                              
              
          end    -- While @@FETCH_STATUS = 0
          
        Close PDVIT_Cr
        Deallocate PDVIT_Cr

        DROP TABLE #ARQ_FRAC
        
      end  -- if @FlgPodeFechar = 1

  Commit Transaction
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_RetornaAbstecimentoPedidosPendentes]
@PCodEstabe int,
@PNumPdvIni int,
@PNumPdvFim int,
@PCodRot int,
@PStrOriPdv varchar(30),
@PNumRuaIni int,
@PNumRuaFim int

WITH RECOMPILE 
AS

BEGIN

SET NOCOUNT ON 

BEGIN TRANSACTION

-- Pegar a data atual com a hora 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

Declare @CodPrd int,
        @CodGrpCli int,
        @DatVctMin smalldatetime, 
        @QtdPdv int,
        @ChavePdv int,
        @ChaveLot int,
        @ChaveLtl int,
        @DatVct smalldatetime, 
        @QtdSld int,
        @QtdEmbFec int,
        @QtdAteDep int,
        @QtdMov int,
        @CodDep smallint,
        @CodDepAnt smallint,
        @CodAba int,
        @DesAba varchar(50),
        @CodLot varchar(20),
        @NumRua smallint,
        @NumCol smallint,
        @NumNiv smallint,
        @NumApt smallint,
        @PCodRotIni int,
        @PCodRotFim int,
		@Usuario varchar(15)
        
Set @Usuario = dbo.FN_UsuarioInfarma()

Set @DesAba = ''
Set @PCodRotIni = 0
Set @PCodRotFim = 0

if @PCodRot > 0
  begin
    Set @DesAba = 'ROTA '+cast(@PCodRot as varchar)
    Set @PCodRotIni = @PCodRot
    Set @PCodRotFim = @PCodRot
  end
else
  begin
    Set @PCodRotIni = IsNull((Select Min(IsNull(Cod_Rota,0)) From PDVCB Where Cod_Estabe = @PCodEstabe),0)
    Set @PCodRotFim = IsNull((Select Max(IsNull(Cod_Rota,0)) From PDVCB Where Cod_Estabe = @PCodEstabe),0)
  end

if @PStrOriPdv <> ''
  begin
    if @DesAba <> ''
	  Set @DesAba = @DesAba + ' - ' 
    Set @DesAba = @DesAba + 'ORIGEM ('+@PStrOriPdv+')'
  end

if @PNumPdvIni > 0
  begin
    if @DesAba <> ''
	  Set @DesAba = @DesAba + ' - ' 
    if @PNumPdvFim > @PNumPdvIni 
      Set @DesAba = @DesAba + 'P.'+cast(@PNumPdvIni as varchar)+'_'+Cast(@PNumPdvFim as varchar)
    else
      Set @DesAba = @DesAba + 'PED.'+cast(@PNumPdvIni as varchar)
  end

if IsNull(@DesAba,'') = ''
  Set @DesAba = 'PED.'+ CONVERT(VARCHAR, @Date, 103);

if @PNumPdvFim = 0
  Set @PNumPdvFim = (Select MAX(Numero) From PDVCB Where Cod_Estabe = @PCodEstabe)

if @PNumRuaFim = 0
  Set @PNumRuaFim = (Select MAX(Num_Rua) From PRLTL Where Cod_Estabe = @PCodEstabe)
  
-- normaliza ABACB
Update ABACB
  Set Cod_Pro = 'A'  -- fracionados 'T' - pre-picking
Where IsNull(Rtrim(Ltrim(Cod_Pro)),'') = ''   

-- cria arq. de lotes q poderão ser necessários
IF OBJECT_ID('tempdb..#ARQ_PDVIT') IS NOT NULL
  DROP TABLE #ARQ_PDVIT

IF OBJECT_ID('tempdb..#ARQ_PRLTL') IS NOT NULL
  DROP TABLE #ARQ_PRLTL

IF OBJECT_ID('tempdb..#ARQ_PRLOT') IS NOT NULL
  DROP TABLE #ARQ_PRLOT

IF OBJECT_ID('tempdb..#ARQ_ABAST') IS NOT NULL
  DROP TABLE #ARQ_ABAST


CREATE TABLE #ARQ_PDVIT
(
    Chave int identity,
    Cod_Pedido int,
    Cod_GrpCli int,
    Cod_Produto int,
    Dat_VctMin smalldatetime,
    Qtd_Pdv int
) 

CREATE TABLE #ARQ_PRLTL
(
    Chave int identity,
    Cod_Dep smallint,
    Cod_Produto int,
    Dat_Vencim smalldatetime,
    Qtd_EmbFec int,
    Qtd_Saldo int
) 

CREATE TABLE #ARQ_PRLOT
(
    Chave int identity,
    Cod_Dep smallint,
    Cod_Produto int,
    Dat_Vencim smalldatetime,
    Qtd_Saldo int
) 

CREATE TABLE #ARQ_ABAST
(
    Cod_Dep smallint,
    Cod_Produto int,
    Dat_Vencim smalldatetime,
    Qtd_Lote int
) 


/* <Índices> */
CREATE UNIQUE CLUSTERED INDEX IX_CL_ARQ_PDVIT ON #ARQ_PDVIT (Chave);
CREATE NONCLUSTERED INDEX IX_ARQ_PDVIT_Cod_Produto ON #ARQ_PDVIT (Cod_Produto);
CREATE NONCLUSTERED INDEX IX_ARQ_PDVIT_Cod_GrpCli ON #ARQ_PDVIT (Cod_GrpCli);

CREATE UNIQUE CLUSTERED INDEX IX_CL_ARQ_PRLTL ON #ARQ_PRLTL (Chave);
CREATE NONCLUSTERED INDEX IX_CL_ARQ_PRLTL_Cod_Dep_Cod_Produto_Dat_Vencim ON #ARQ_PRLTL (Cod_Dep, Cod_Produto, Dat_Vencim);

CREATE UNIQUE CLUSTERED INDEX IX_CL_ARQ_PRLOT ON #ARQ_PRLOT (Chave);
CREATE NONCLUSTERED INDEX IX_CL_ARQ_PRLOT_Cod_Dep_Cod_Produto_Dat_Vencim ON #ARQ_PRLOT (Cod_Dep, Cod_Produto, Dat_Vencim);

CREATE CLUSTERED INDEX IX_CL_ARQ_ABAST ON #ARQ_ABAST (Cod_Dep, Cod_Produto, Dat_Vencim);
/* </Índices> */


-- cria arq. de pedidos
Insert Into #ARQ_PDVIT (Cod_Pedido, Cod_GrpCli, Cod_Produto, Dat_VctMin, Qtd_Pdv)
  Select a.Cod_Pedido, a.Cod_GrpCli, a.Cod_Produto, a.DatVctMin, a.QtdPdv
    From (Select it.Cod_Pedido, Cod_GrpCli=IsNull(cl.Cod_GrpCli,0), it.Cod_Produto, 
                 DatVctMin = Case 
                               When IsNull(vp.Cod_Produt,0) > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0)) 
                               When IsNull(vf.Cod_Fabric,0) > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0)) 
                               Else dbo.FN_DataVenctoMinimo(@Date,IsNull(cl.Qtd_MesMinPrzVctLot,0)) 
                             End, 
                 sum(it.Qtd_Pedido+it.Qtd_Bonificacao) as QtdPdv 
            From PDVCB cb Left Outer Join 
                 CLIEN cl on (cb.Cod_Cliente = cl.Codigo) Inner Join 
                 PDVIT it ON (cb.Cod_Estabe = it.Cod_Estabe and cb.Numero = it.Cod_Pedido) Inner Join 
                 PRODU pr on (it.Cod_Produto = pr.Codigo) Left Outer Join 
                 CLPRV vp on ((vp.Cod_CliPag = Case When IsNull(cl.Cod_CliPag,0) > 0 Then cl.Cod_CliPag Else cl.Codigo End) and 
                              (vp.Cod_Produt = pr.Codigo)) Left Outer Join 
                 CLFBV vf on ((vf.Cod_CliPag = Case When IsNull(cl.Cod_CliPag,0) > 0 Then cl.Cod_CliPag Else cl.Codigo End) and 
                              (vf.Cod_Fabric = pr.Cod_Fabricante)) 
          Where cb.Cod_Estabe = @PCodEstabe
          and cb.Status1 = 'P' and cb.Status2 = 'F'
          and cb.Tip_Pedido = 'P'
          and IsNull(cb.Flg_WMS,0) = 1 
          and IsNull(cb.Sta_IntWMS,'') = ''
          and IsNull(cb.Bloqueio,'') = ''
          and IsNull(cb.Cod_BlqRnt,'') <> 'B'
          and IsNull(cb.Cod_BlqLic,'') <> 'B'
          and it.Qtd_Pedido > 0
          and not Exists (Select 1 From PDVLT Where Cod_Estabe = cb.Cod_Estabe and Cod_Pedido = cb.Numero)
          and cb.Numero between @PNumPdvIni and @PNumPdvFim
          and IsNull(cb.Cod_Rota,0) between @PCodRotIni and @PCodRotFim
          and ((IsNull(@PStrOriPdv,'') = '') or (CharIndex(Substring(Cod_OrigemPdv,1,1),@PStrOriPdv) > 0))
          Group by it.Cod_Estabe, it.Cod_Pedido, IsNull(cl.Cod_GrpCli,0), it.Cod_Produto, cl.Qtd_MesMinPrzVctLot, 
                   vp.Cod_Produt, vp.Qtd_MesMinPrzVctLot, 
                   vf.Cod_Fabric, vf.Qtd_MesMinPrzVctLot) a
  Where not Exists (Select 1 From ABACB c Inner Join 
                                  ABAIT i on c.Cod_Estabe = i.Cod_Estabe and c.Cod_Abaste = i.Cod_Abaste 
                    Where c.Cod_Estabe = @PCodEstabe and c.Cod_Pro = 'A' and c.Cod_Sta <> 'F' and i.Cod_Produt = a.Cod_Produto) 

-- cria arq. de lotes PRLTL
Insert Into #ARQ_PRLTL (Cod_Dep, Cod_Produto, Dat_Vencim, Qtd_EmbFec, Qtd_Saldo)
  Select lt.Cod_Dep, lt.Cod_Produt, IsNull(lt.Dat_Vencim,0), lt.C_QtdEmbFec, sum(lt.Qtd_saldo)
  From PRLTL lt Inner Join 
       (Select distinct Cod_Produto
        From #ARQ_PDVIT) pv on lt.Cod_Produt = pv.Cod_Produto       
  Where lt.Cod_Estabe = @PCodEstabe
  And lt.Qtd_Saldo > 0
  And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'D'
  And lt.Qtd_Saldo >= lt.C_QtdEmbFec
  And lt.C_QtdEmbFec > 0 
  And lt.Num_Rua between @PNumRuaIni and @PNumRuaFim 
  Group by lt.Cod_Dep, lt.Cod_Produt, lt.Dat_Vencim, lt.C_QtdEmbFec 

-- cria arq. de lotes PRLOT
Insert Into #ARQ_PRLOT (Cod_Dep, Cod_Produto, Dat_Vencim, Qtd_Saldo)
  Select lt.Cod_Dep, lt.Cod_Produt, IsNull(lt.Dat_Vencim,0), sum(lt.Qtd_saldo)
  From PRLOT lt Inner Join
       (Select distinct Cod_Produto
        From #ARQ_PDVIT) pv on lt.Cod_Produt = pv.Cod_Produto       
  Where lt.Cod_Estabe = @PCodEstabe
  And lt.Qtd_Saldo > 0
  Group by lt.Cod_Dep, lt.Cod_Produt, lt.Dat_Vencim 

--------------------------------------------------------------------------------------------------------------------------------

-- seleciona itens de pedidos de depositos exclusivos
Declare PDVIT_Cr Cursor Local Fast_Forward For 
  Select a.Chave, a.Cod_GrpCli, a.Cod_Produto, a.Dat_VctMin, a.Qtd_Pdv
  From #ARQ_PDVIT a
   -- filtra grupos de clientes com depositos exclusivos
  Where Exists (Select 1 From DPXGC Where Cod_Estabe = @PCodEstabe and Cod_GrpCli = a.Cod_GrpCli)
  Order by Cod_Produto, Dat_VctMin 
Open PDVIT_Cr
Fetch Next From PDVIT_Cr Into @ChavePdv, @CodGrpCli, @CodPrd, @DatVctMin, @QtdPdv
While @@FETCH_STATUS = 0
  begin
    -- verifica se existe itens que podem ser atendidos pelo deposito exclusivo
    while Exists(Select 1
                   From #ARQ_PRLTL a
                 Where Cod_Produto = @CodPrd
                 And ((IsNull(a.Dat_Vencim,0) = 0) or (IsNull(a.Dat_Vencim,0) >= IsNull(@DatVctMin,0)))
                 And @QtdPdv >= a.Qtd_EmbFec
                 And a.Qtd_Saldo >= a.Qtd_EmbFec
                 And a.Qtd_EmbFec > 0
                 And Exists (Select 1 From DPXGC Where Cod_Estabe = @PCodEstabe and Cod_GrpCli = @CodGrpCli and Cod_Dep = a.Cod_Dep))
      begin
        Select top 1 @ChaveLtl = a.Chave, 
                     @DatVct = a.Dat_Vencim, 
                     @QtdSld = a.Qtd_Saldo, 
                     @QtdEmbFec = IsNull(a.Qtd_EmbFec,0) 
        From #ARQ_PRLTL a   
        Where a.Cod_Produto = @CodPrd
        And ((IsNull(a.Dat_Vencim,0) = 0) or (IsNull(a.Dat_Vencim,0) >= IsNull(@DatVctMin,0)))
        And @QtdPdv >= a.Qtd_EmbFec
        And a.Qtd_Saldo >= a.Qtd_EmbFec
        And a.Qtd_EmbFec > 0
        -- filtra depositos exclusivos
        And Exists (Select 1 From DPXGC Where Cod_Estabe = @PCodEstabe and Cod_GrpCli = @CodGrpCli and Cod_Dep = a.Cod_Dep)
        Order by Dat_Vencim, Cod_Dep

        Set @QtdAteDep = @QtdPdv/@QtdEmbFec*@QtdEmbFec

        -- simular atendimento do pulmão: dar baixa em PRLTL e PDVIT
        Update #ARQ_PRLTL
          Set Qtd_Saldo = Qtd_Saldo - @QtdAteDep
        Where Chave = @ChaveLtl
        
        Update #ARQ_PDVIT
          Set Qtd_Pdv = Qtd_Pdv - @QtdAteDep
        Where Chave = @ChavePdv
          
       Set @QtdPdv = @QtdPdv - @QtdAteDep    
       
      end

    Fetch Next From PDVIT_Cr Into @ChavePdv, @CodGrpCli, @CodPrd, @DatVctMin, @QtdPdv
  end
Close PDVIT_Cr
Deallocate PDVIT_Cr

-- seleciona itens de pedidos de depositos EXCLUSIVOS para atendimento pelo picking
Declare PDVIT_Cr Cursor Local Fast_Forward For 

  Select a.Chave, a.Cod_GrpCli, a.Cod_Produto, a.Dat_VctMin, a.Qtd_Pdv
  From #ARQ_PDVIT a
   -- filtra grupos de clientes com depositos exclusivos
  Where Exists (Select 1 From DPXGC Where Cod_Estabe = @PCodEstabe and Cod_GrpCli = a.Cod_GrpCli)
  Order by Cod_Produto, Dat_VctMin 
  
Open PDVIT_Cr
Fetch Next From PDVIT_Cr Into @ChavePdv, @CodGrpCli, @CodPrd, @DatVctMin, @QtdPdv
While @@FETCH_STATUS = 0
  begin
    -- verifica se existe itens que podem ser transferidos para picking
    while (IsNull((Select sum(a.Qtd_Saldo)
                   From #ARQ_PRLOT a
                   Where a.Cod_Produto = @CodPrd
                   And ((IsNull(a.Dat_Vencim,0) = 0) or (IsNull(a.Dat_Vencim,0) >= IsNull(@DatVctMin,0)))
                   And a.Qtd_Saldo > 0
                   -- filtra depositos exclusivos
                   And Exists (Select 1 From DPXGC Where Cod_Estabe = @PCodEstabe and Cod_Dep = a.Cod_Dep)),0) < @QtdPdv) and
          Exists(Select sum(a.Qtd_Saldo)
                 From #ARQ_PRLTL a
                 Where a.Cod_Produto = @CodPrd
                 And ((IsNull(a.Dat_Vencim,0) = 0) or (IsNull(a.Dat_Vencim,0) >= IsNull(@DatVctMin,0)))
                 And a.Qtd_Saldo > 0
                 And a.Qtd_EmbFec > 0
                 -- filtra depositos exclusivos
                 And Exists (Select 1 From DPXGC Where Cod_Estabe = @PCodEstabe and Cod_Dep = a.Cod_Dep)
                 Having SUM(Qtd_Saldo) > 0)
      begin
        Set @ChaveLtl = 0
        
        Select top 1 @ChaveLtl = a.Chave, 
                     @CodDep = a.Cod_Dep,
                     @DatVct = a.Dat_Vencim, 
                     @QtdSld = a.Qtd_Saldo,
                     @QtdEmbFec = IsNull(a.Qtd_EmbFec,0) 
        From #ARQ_PRLTL a 
        Where a.Cod_Produto = @CodPrd
        And ((IsNull(a.Dat_Vencim,0) = 0) or (IsNull(a.Dat_Vencim,0) >= IsNull(@DatVctMin,0)))
        And a.Qtd_Saldo > 0
        And a.Qtd_EmbFec > 0
        -- filtra depositos exclusivos
        And Exists (Select 1 From DPXGC Where Cod_Estabe = @PCodEstabe and Cod_Dep = a.Cod_Dep)
        Order by Dat_Vencim, Cod_Dep
        
        if not Exists(Select 1 From #ARQ_ABAST
                      Where Cod_Dep = @CodDep
                      And Cod_Produto = @CodPrd
                      And Dat_Vencim = @DatVct)     
            Insert Into #ARQ_ABAST (Cod_Dep, Cod_Produto, Dat_Vencim, Qtd_Lote)
              Values (@CodDep, @CodPrd, @DatVct, 0)
            
        Update #ARQ_ABAST
          Set Qtd_Lote = Qtd_Lote + @QtdEmbFec
        Where Cod_Dep = @CodDep
        And Cod_Produto = @CodPrd
        And Dat_Vencim = @DatVct
                          
        -- simular atendimento do picking: transferir de PRLTL, dar baixa em PRLOT e PDVIT
        Update #ARQ_PRLTL
          Set Qtd_Saldo = Qtd_Saldo - @QtdEmbFec
        Where Chave = @ChaveLtl

        if not Exists(Select Chave
                      From #ARQ_PRLOT
                      Where Cod_Dep = @CodDep
                      And Cod_Produto = @CodPrd
                      And Dat_Vencim = @DatVct)
          Insert Into #ARQ_PRLOT (Cod_Dep, Cod_Produto, Dat_Vencim, Qtd_Saldo)
            Values (@CodDep, @CodPrd, @DatVct, 0)

        Set @ChaveLot = 0
            
        Select top 1 @ChaveLot = Chave
        From #ARQ_PRLOT
        Where Cod_Dep = @CodDep
        And Cod_Produto = @CodPrd
        And Dat_Vencim = @DatVct

        Update #ARQ_PRLOT
          Set Qtd_Saldo = Qtd_Saldo + @QtdEmbFec
        Where Chave = @ChaveLot
  
/*        
        if @QtdEmbFec > @QtdPdv
          Set @QtdMov = @QtdPdv
        else  
          Set @QtdMov = @QtdEmbFec
        
        Update #ARQ_PDVIT
          Set Qtd_Pdv = Qtd_Pdv - @QtdMov
        Where Chave = @ChavePdv

        Update #ARQ_PRLOT
          Set Qtd_Saldo = Qtd_Saldo - @QtdMov
        Where Chave = @ChaveLot

        Set @QtdPdv = @QtdPdv - @QtdMov
*/            
      end
      
    -- dar baixa em PRLOT e PDVIT
    while (IsNull((Select sum(a.Qtd_Saldo)
                   From #ARQ_PRLOT a
                   Where a.Cod_Produto = @CodPrd
                   And ((IsNull(a.Dat_Vencim,0) = 0) or (IsNull(a.Dat_Vencim,0) >= IsNull(@DatVctMin,0)))
                   And a.Qtd_Saldo > 0
                   -- filtra depositos exclusivos
                   And Exists (Select 1 From DPXGC Where Cod_Estabe = @PCodEstabe And Cod_Dep = a.Cod_Dep)),0) > 0) and (@QtdPdv > 0)
      begin
        Set @QtdMov = 0

        Select top 1 @ChaveLot = a.Chave, 
                     @CodDep = a.Cod_Dep,
                     @DatVct = a.Dat_Vencim, 
                     @QtdSld = a.Qtd_Saldo
        From #ARQ_PRLOT a 
        Where a.Cod_Produto = @CodPrd
        And ((IsNull(a.Dat_Vencim,0) = 0) or (IsNull(a.Dat_Vencim,0) >= IsNull(@DatVctMin,0)))
        And a.Qtd_Saldo > 0
        -- filtra depositos exclusivos
        And Exists (Select 1 From DPXGC Where Cod_Estabe = @PCodEstabe and Cod_Dep = a.Cod_Dep)
        Order by Dat_Vencim, Cod_Dep

        if @QtdSld > @QtdPdv
          Set @QtdMov = @QtdPdv
        else  
          Set @QtdMov = @QtdSld

        Update #ARQ_PDVIT
          Set Qtd_Pdv = Qtd_Pdv - @QtdMov
        Where Chave = @ChavePdv

        Update #ARQ_PRLOT
          Set Qtd_Saldo = Qtd_Saldo - @QtdMov
        Where Chave = @ChaveLot

        Set @QtdPdv = @QtdPdv - @QtdMov
      end               
    
    Fetch Next From PDVIT_Cr Into @ChavePdv, @CodGrpCli, @CodPrd, @DatVctMin, @QtdPdv
  end
Close PDVIT_Cr
Deallocate PDVIT_Cr

------------------------------------------------------------------------------------------------------
------------------------------------------------------------------------------------------------------

-- seleciona itens de pedidos de depositos COMPARTILHADOS para atendimento pelo pulmão
Declare PDVIT_Cr Cursor Local Fast_Forward For 

  Select a.Chave, a.Cod_GrpCli, a.Cod_Produto, a.Dat_VctMin, a.Qtd_Pdv
  From #ARQ_PDVIT a
   -- filtra grupos de clientes com depositos compartilhados
  Where not Exists (Select 1 Cod_GrpCli From DPXGC Where Cod_Estabe = @PCodEstabe and Cod_GrpCli = a.Cod_GrpCli)
  Order by Cod_Produto, Dat_VctMin 
  
Open PDVIT_Cr
Fetch Next From PDVIT_Cr Into @ChavePdv, @CodGrpCli, @CodPrd, @DatVctMin, @QtdPdv
While @@FETCH_STATUS = 0
  begin
    -- verifica se existe itens que podem ser atendidos pelo deposito compartilhado
    while Exists(Select 1
                 From #ARQ_PRLTL a
                 Where a.Cod_Produto = @CodPrd
                 And ((IsNull(a.Dat_Vencim,0) = 0) or (IsNull(a.Dat_Vencim,0) >= IsNull(@DatVctMin,0)))
                 And @QtdPdv >= a.Qtd_EmbFec
                 And a.Qtd_Saldo >= a.Qtd_EmbFec
                 And a.Qtd_EmbFec > 0
                 -- filtra depositos compartilhados
                 And not Exists (Select 1 From DPXGC Where Cod_Estabe = @PCodEstabe And Cod_Dep = a.Cod_Dep))
      begin
        Select top 1 @ChaveLtl = a.Chave, 
                     @DatVct = a.Dat_Vencim, 
                     @QtdSld = a.Qtd_Saldo,
                     @QtdEmbFec = IsNull(a.Qtd_EmbFec,0) 
        From #ARQ_PRLTL a 
        Where a.Cod_Produto = @CodPrd
        And ((IsNull(a.Dat_Vencim,0) = 0) or (IsNull(a.Dat_Vencim,0) >= IsNull(@DatVctMin,0)))
        And @QtdPdv >= a.Qtd_EmbFec
        And a.Qtd_Saldo >= a.Qtd_EmbFec
        And a.Qtd_EmbFec > 0
        -- filtra depositos compartilhados
        And not Exists (Select 1 From DPXGC Where Cod_Estabe = @PCodEstabe and Cod_Dep = a.Cod_Dep)
        Order by Dat_Vencim, Cod_Dep
        
        Set @QtdAteDep = @QtdPdv/@QtdEmbFec*@QtdEmbFec

        -- simular atendimento do pulmão: dar baixa em PRLTL e PDVIT
        Update #ARQ_PRLTL
          Set Qtd_Saldo = Qtd_Saldo - @QtdAteDep
        Where Chave = @ChaveLtl
        
        Update #ARQ_PDVIT
          Set Qtd_Pdv = Qtd_Pdv - @QtdAteDep
        Where Chave = @ChavePdv
          
       Set @QtdPdv = @QtdPdv - @QtdAteDep    
       
      end
      
    Fetch Next From PDVIT_Cr Into @ChavePdv, @CodGrpCli, @CodPrd, @DatVctMin, @QtdPdv
  end
Close PDVIT_Cr
Deallocate PDVIT_Cr

-- seleciona itens de pedidos de todos depositos para atendimento pelo picking
Declare PDVIT_Cr Cursor Local Fast_Forward For 

  Select Chave, Cod_GrpCli, Cod_Produto, Dat_VctMin, Qtd_Pdv
  From #ARQ_PDVIT
   -- nao filtra grupos de clientes com depositos compartilhados
  --Where Cod_GrpCli not in (Select distinct Cod_GrpCli From DPXGC Where Cod_Estabe = @PCodEstabe)
  Order by Cod_Produto, Dat_VctMin 
  
Open PDVIT_Cr
Fetch Next From PDVIT_Cr Into @ChavePdv, @CodGrpCli, @CodPrd, @DatVctMin, @QtdPdv
While @@FETCH_STATUS = 0
  begin
    -- verifica se existe itens que podem ser transferidos para picking
    while (IsNull( (Select sum(a.Qtd_Saldo)
                      From #ARQ_PRLOT a
                     Where a.Cod_Produto = @CodPrd
                       And ((IsNull(a.Dat_Vencim,0) = 0) or (IsNull(a.Dat_Vencim,0) >= IsNull(@DatVctMin,0)))
                       And a.Qtd_Saldo > 0
                       -- filtra depositos compartilhados
                      And not Exists (Select 1 From DPXGC Where Cod_Estabe = @PCodEstabe and Cod_Dep = a.Cod_Dep)
					),0) < @QtdPdv) and
          Exists(Select sum(a.Qtd_Saldo)
                   From #ARQ_PRLTL a
                  Where a.Cod_Produto = @CodPrd
                    And ((IsNull(a.Dat_Vencim,0) = 0) or (IsNull(a.Dat_Vencim,0) >= IsNull(@DatVctMin,0)))
                    And a.Qtd_Saldo > 0
                    -- filtra depositos compartilhados
                    And not Exists (Select 1 From DPXGC Where Cod_Estabe = @PCodEstabe and Cod_Dep = a.Cod_Dep)
                 Having SUM(Qtd_Saldo) > 0)
      begin
        Set @ChaveLtl = 0
        
        Select top 1 @ChaveLtl = a.Chave, 
                     @CodDep = a.Cod_Dep,
                     @DatVct = a.Dat_Vencim, 
                     @QtdSld = a.Qtd_Saldo,
                     @QtdEmbFec = IsNull(a.Qtd_EmbFec,0) 
        From #ARQ_PRLTL a
        Where a.Cod_Produto = @CodPrd
        And ((IsNull(a.Dat_Vencim,0) = 0) or (IsNull(a.Dat_Vencim,0) >= IsNull(@DatVctMin,0)))
        And a.Qtd_Saldo > 0
        And a.Qtd_EmbFec > 0
        -- filtra depositos compartilhados
        And not Exists (Select 1 From DPXGC Where Cod_Estabe = @PCodEstabe and Cod_Dep = a.Cod_Dep)
        Order by Dat_Vencim, Cod_Dep
        
        if not Exists(Select 1 From #ARQ_ABAST
                      Where Cod_Dep = @CodDep
                      And Cod_Produto = @CodPrd
                      And Dat_Vencim = @DatVct)     
            Insert Into #ARQ_ABAST (Cod_Dep, Cod_Produto, Dat_Vencim, Qtd_Lote)
              Values (@CodDep, @CodPrd, @DatVct, 0)
            
        Update #ARQ_ABAST
          Set Qtd_Lote = Qtd_Lote + @QtdEmbFec
        Where Cod_Dep = @CodDep
        And Cod_Produto = @CodPrd
        And Dat_Vencim = @DatVct
                          
        -- simular atendimento do picking: transferir de PRLTL, dar baixa em PRLOT e PDVIT
        Update #ARQ_PRLTL
          Set Qtd_Saldo = Qtd_Saldo - @QtdEmbFec
        Where Chave = @ChaveLtl

        if not Exists(Select Chave
                      From #ARQ_PRLOT
                      Where Cod_Dep = @CodDep
                      And Cod_Produto = @CodPrd
                      And Dat_Vencim = @DatVct)
          Insert Into #ARQ_PRLOT (Cod_Dep, Cod_Produto, Dat_Vencim, Qtd_Saldo)
            Values (@CodDep, @CodPrd, @DatVct, 0)

        Set @ChaveLot = 0
            
        Select top 1 @ChaveLot = Chave
        From #ARQ_PRLOT
        Where Cod_Dep = @CodDep
        And Cod_Produto = @CodPrd
        And Dat_Vencim = @DatVct

        Update #ARQ_PRLOT
          Set Qtd_Saldo = Qtd_Saldo + @QtdEmbFec
        Where Chave = @ChaveLot
/*        
        if @QtdEmbFec > @QtdPdv
          Set @QtdMov = @QtdPdv
        else  
          Set @QtdMov = @QtdEmbFec
        
        Update #ARQ_PDVIT
          Set Qtd_Pdv = Qtd_Pdv - @QtdMov
        Where Chave = @ChavePdv

        Update #ARQ_PRLOT
          Set Qtd_Saldo = Qtd_Saldo - @QtdMov
        Where Chave = @ChaveLot

        Set @QtdPdv = @QtdPdv - @QtdMov
*/        
      end
      
    --  dar baixa em PRLOT e PDVIT
    while (IsNull( (Select sum(a.Qtd_Saldo)
                      From #ARQ_PRLOT a
                     Where a.Cod_Produto = @CodPrd
                       And ((IsNull(a.Dat_Vencim,0) = 0) or (IsNull(a.Dat_Vencim,0) >= IsNull(@DatVctMin,0)))
                       And a.Qtd_Saldo > 0
                       -- filtra depositos compartilhados
                       And not Exists (Select 1 From DPXGC Where Cod_Estabe = @PCodEstabe and Cod_Dep = a.Cod_Dep)
                   ),0) > 0) and (@QtdPdv > 0)
      begin
        Set @QtdMov = 0

        Select top 1 @ChaveLot = a.Chave, 
                     @CodDep = a.Cod_Dep,
                     @DatVct = a.Dat_Vencim, 
                     @QtdSld = a.Qtd_Saldo
        From #ARQ_PRLOT a 
        Where a.Cod_Produto = @CodPrd
        And ((IsNull(a.Dat_Vencim,0) = 0) or (IsNull(a.Dat_Vencim,0) >= IsNull(@DatVctMin,0)))
        And a.Qtd_Saldo > 0
        -- filtra depositos compartilhados
        And not Exists (Select 1 From DPXGC Where Cod_Estabe = @PCodEstabe and Cod_Dep = a.Cod_Dep)
        Order by Dat_Vencim, Cod_Dep

        if @QtdSld > @QtdPdv
          Set @QtdMov = @QtdPdv
        else  
          Set @QtdMov = @QtdSld

        Update #ARQ_PDVIT
          Set Qtd_Pdv = Qtd_Pdv - @QtdMov
        Where Chave = @ChavePdv

        Update #ARQ_PRLOT
          Set Qtd_Saldo = Qtd_Saldo - @QtdMov
        Where Chave = @ChaveLot

        Set @QtdPdv = @QtdPdv - @QtdMov
      end               
    
    Fetch Next From PDVIT_Cr Into @ChavePdv, @CodGrpCli, @CodPrd, @DatVctMin, @QtdPdv
  end
Close PDVIT_Cr
Deallocate PDVIT_Cr

