CREATE PROCEDURE [dbo].[PR_RateiaValoresPAGRT]
@PCodEstabe int,
@PCodCtaPag int

AS

SET NOCOUNT ON 


if Exists(Select 1
          From PAGRT rt 
               Inner Join PAGCT p on rt.Cod_Estabe = p.Cod_Estabe and rt.Cod_CtaPag = p.Cod_CtaPag
               Inner Join (Select Cod_Estabe, Cod_CtaPag, 
                                  TotValDocRat = sum(Round(Val_DocRat,2)),
                                  TotValDscRat = sum(Round(Val_DscRat,2)), 
                                  TotValRat    = sum(Round(Val_Rat,2))
                           From PAGRT
                           Group by Cod_Estabe, Cod_CtaPag) r on p.Cod_Estabe = r.Cod_Estabe and p.Cod_CtaPag = r.Cod_CtaPag
          Where rt.Cod_Estabe = @PCodEstabe
          And rt.Cod_CtaPag = @PCodCtaPag
          And ((p.Val_DscCon <> r.TotValDscRat) or
               (p.Val_Docume <> r.TotValDocRat)))
begin

  BEGIN TRANSACTION

      Update rt 
        Set rt.Val_DocRat = Round(rt.Val_Rat/r.TotValRat*p.Val_Docume,2),
            rt.Val_DscRat = Round(rt.Val_Rat/r.TotValRat*p.Val_DscCon,2)
       From PAGRT rt 
            Inner Join PAGCT p on rt.Cod_Estabe = p.Cod_Estabe and rt.Cod_CtaPag = p.Cod_CtaPag
            Inner Join (Select Cod_Estabe, Cod_CtaPag, 
                               TotValDocRat = sum(Round(Val_DocRat,2)),
                               TotValDscRat = sum(Round(Val_DscRat,2)), 
                               TotValRat    = sum(Round(Val_Rat,2))
                        From PAGRT
                        Group by Cod_Estabe, Cod_CtaPag) r on p.Cod_Estabe = r.Cod_Estabe and p.Cod_CtaPag = r.Cod_CtaPag
       Where rt.Cod_Estabe = @PCodEstabe
       And rt.Cod_CtaPag = @PCodCtaPag
       And r.TotValRat > 0
       And ((rt.Val_DocRat <> Round(rt.Val_Rat/r.TotValRat*p.Val_Docume,2)) or
            (rt.Val_DscRat = Round(rt.Val_Rat/r.TotValRat*p.Val_DscCon,2))) 

      Update rt 
        Set rt.Val_DocRat = rt.Val_DocRat - (r.TotValDocRat-p.Val_Docume)
       From PAGRT rt 
            Inner Join PAGCT p on rt.Cod_Estabe = p.Cod_Estabe and rt.Cod_CtaPag = p.Cod_CtaPag
            Inner Join (Select Cod_Estabe, Cod_CtaPag, 
                               TotValDocRat = sum(Round(Val_DocRat,2)),
                               TotValDscRat = sum(Round(Val_DscRat,2)), 
                               TotValRat    = sum(Round(Val_Rat,2))
                        From PAGRT 
                        Group by Cod_Estabe, Cod_CtaPag) r on p.Cod_Estabe = r.Cod_Estabe and p.Cod_CtaPag = r.Cod_CtaPag
       Where rt.Cod_Estabe = @PCodEstabe
       And rt.Cod_CtaPag = @PCodCtaPag
       And rt.Isn_CtaRat = (Select max(Isn_CtaRat) From PAGRT Where Cod_Estabe = @PCodEstabe and Cod_CtaPag = @PCodCtaPag)
       And r.TotValDocRat <> p.Val_Docume

      Update rt 
        Set rt.Val_DscRat = rt.Val_DscRat - (r.TotValDscRat-p.Val_DscCon)
       From PAGRT rt 
            Inner Join PAGCT p on rt.Cod_Estabe = p.Cod_Estabe and rt.Cod_CtaPag = p.Cod_CtaPag
            Inner Join (Select Cod_Estabe, Cod_CtaPag, 
                               TotValDocRat = sum(Round(Val_DocRat,2)),
                               TotValDscRat = sum(Round(Val_DscRat,2)), 
                               TotValRat    = sum(Round(Val_Rat,2))
                        From PAGRT
                        Group by Cod_Estabe, Cod_CtaPag) r on p.Cod_Estabe = r.Cod_Estabe and p.Cod_CtaPag = r.Cod_CtaPag
       Where rt.Cod_Estabe = @PCodEstabe
       And rt.Cod_CtaPag = @PCodCtaPag
       And rt.Isn_CtaRat = (Select max(Isn_CtaRat) From PAGRT Where Cod_Estabe = @PCodEstabe and Cod_CtaPag = @PCodCtaPag)
       And r.TotValDscRat <> p.Val_DscCon

  COMMIT TRANSACTION
end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_RateiaDespesasNFS]
@PCodEstabe int,
@PSerNot varchar(3),
@PNumNot int

AS

SET NOCOUNT ON

if Exists(Select 1
            From NFSCB cb
                 Inner Join (Select Cod_Estabe, Ser_Nota, Num_Nota, 
                                    C_DspIte = sum(IsNull(Vlr_DespRateada,0)),
                                    C_FreIte = sum(IsNull(Vlr_Frete,0)),
                                    C_SegIte = sum(IsNull(Vlr_Seguro,0))
                               From NFSIT
                              Where Cod_Estabe = @PCodEstabe
                                and Ser_Nota = @PSerNot
                                and Num_Nota = @PNumNot
                              Group by Cod_Estabe, Ser_Nota, Num_Nota
                             ) it on cb.Cod_Estabe = it.Cod_Estabe and cb.Ser_Nota = it.Ser_Nota and cb.Num_Nota = it.Num_Nota 
           Where cb.Cod_Estabe = @PCodEstabe
             and cb.Ser_Nota = @PSerNot
             and cb.Num_Nota = @PNumNot
             and ( (IsNull(cb.Vlr_OutDsp,0) <> it.C_DspIte) or
                   (IsNull(cb.Vlr_Frete,0)  <> it.C_FreIte) or 
                   (IsNull(cb.Vlr_Seguro,0) <> it.C_SegIte) ) 
         ) or
   Exists(Select 1
            From NFSIT
           Where Cod_Estabe = @PCodEstabe
             And Ser_Nota = @PSerNot
             And Num_Nota = @PNumNot
             And ( ((IsNull(Vlr_DespRateada,0) > 0) and (Right(Cast(IsNull(Vlr_DespRateada,0) as numeric(18,8)),6) > 0)) or 
                   ((IsNull(Vlr_Frete,0) > 0)       and (Right(Cast(IsNull(Vlr_Frete,0)       as numeric(18,8)),6) > 0)) or 
                   ((IsNull(Vlr_Seguro,0) > 0)      and (Right(Cast(IsNull(Vlr_Seguro,0)      as numeric(18,8)),6) > 0)) )
         )
  begin
    BEGIN TRANSACTION

    Declare @cb_ValDsp numeric(18,4),
            @cb_ValFre numeric(18,4),
            @cb_ValSeg numeric(18,4),
            @cb_VlrItens numeric(18,4),
            @cb_TotItens int,

            @it_CodPrd int,
            @it_CodLot varchar(20),
            @it_NumSeqIte int,
            @it_TipSai varchar(1),
            @it_QtdPrd int,
            @it_QtdBon int,
            @it_PerDsc numeric(18,4),
            @it_VlrIcmNor numeric(18,4),
            @it_VlrTotIte numeric(18,4),

            @WDspIte numeric(18,4),
            @WFreIte numeric(18,4),
            @WSegIte numeric(18,4),
            @WAccDsp numeric(18,4),
            @WAccFre numeric(18,4),
            @WAccSeg numeric(18,4),

            @WAccIte int,
            @WFlgIcm bit
  
    -- coloca campos de NFSCB na memoria
    Select @cb_ValDsp = Isnull(cb.Vlr_OutDsp,0),
           @cb_ValFre = Isnull(cb.Vlr_Frete,0),
           @cb_ValSeg = Isnull(cb.Vlr_Seguro,0)
      From NFSCB cb
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Ser_Nota = @PSerNot 
       and cb.Num_Nota = @PNumNot
  
    Update NFSIT
       Set Vlr_DespRateada = 0,
           Vlr_Frete = 0, 
           Vlr_Seguro = 0
     Where Cod_Estabe = @PCodEstabe
       And Ser_Nota = @PSerNot 
       And Num_Nota = @PNumNot

    -- somente itens com icms normal(se houver) serao considerados no rateamento de despesas, caso contrario rateia entre todos os itens
    Set @WFlgIcm = 0
    if Exists(Select 1 From NFSIT Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot And Qtd_Produto > 0 And Vlr_IcmsNor > 0)
      begin
        Set @WFlgIcm = 1
        Set @cb_TotItens = (Select count(*) From NFSIT Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot And Qtd_Produto > 0 And Vlr_IcmsNor > 0)
        Set @cb_VlrItens = (Select sum(Vlr_TotItem) From NFSIT Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot And Qtd_Produto > 0 And Vlr_IcmsNor > 0)

        if (@cb_ValDsp > @cb_VlrItens) or
           (@cb_ValFre > @cb_VlrItens) or
           (@cb_ValSeg > @cb_VlrItens)
          Set @WFlgIcm = 0
      end

    if @WFlgIcm = 0
      begin
        Set @cb_TotItens = (Select count(*) From NFSIT Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot And Qtd_Produto > 0)
        Set @cb_VlrItens = (Select sum(Vlr_TotItem) From NFSIT Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot And Qtd_Produto > 0)
      end
  
    Set @WAccDsp = 0
    Set @WAccFre = 0
    Set @WAccSeg = 0
    Set @WAccIte = 0
  
    Declare NFSIT_Cr Cursor Local Fast_Forward For 

      Select Cod_Produto, Cod_Lote, Num_SeqIte, IsNull(Tip_Sai,''), 
             Qtd_Produto, Qtd_Bonificacao, Per_Desconto, 
             Vlr_IcmsNor, Vlr_TotItem
        From NFSIT 
       Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
         And Qtd_Produto > 0
       Order By Vlr_TotItem
  
    Open NFSIT_Cr
    Fetch Next From NFSIT_Cr Into @it_CodPrd, @it_CodLot, @it_NumSeqIte, @it_TipSai,
                                  @it_QtdPrd, @it_QtdBon, @it_PerDsc, 
                                  @it_VlrIcmNor, @it_VlrTotIte
    While @@FETCH_STATUS = 0
      begin
        Set @WDspIte = 0
        Set @WFreIte = 0
        Set @WSegIte = 0
  
	    -- rateia despesas
        if (@WFlgIcm = 0) or (@it_VlrIcmNor > 0)
          begin
            Set @WAccIte = @WAccIte + 1

            Set @WDspIte = Round(@cb_ValDsp*@it_VlrTotIte/@cb_VlrItens,2)
            Set @WFreIte = Round(@cb_ValFre*@it_VlrTotIte/@cb_VlrItens,2)
            Set @WSegIte = Round(@cb_ValSeg*@it_VlrTotIte/@cb_VlrItens,2)
            
            if (@WAccDsp + @WDspIte) > @cb_ValDsp 
              Set @WDspIte = @cb_ValDsp - @WAccDsp
  
            if (@WAccFre + @WFreIte) > @cb_ValFre 
              Set @WFreIte = @cb_ValFre - @WAccFre
  
            if (@WAccSeg + @WSegIte) > @cb_ValSeg 
              Set @WSegIte = @cb_ValSeg - @WAccSeg

            -- assegura fechamento de valores no ultimo item
            if @WAccIte = @cb_TotItens 
              begin
                Set @WDspIte = @cb_ValDsp - @WAccDsp
                Set @WFreIte = @cb_ValFre - @WAccFre
                Set @WSegIte = @cb_ValSeg - @WAccSeg
              end
          end
  
        Update NFSIT
           Set Vlr_DespRateada = @WDspIte,
               Vlr_Frete = @WFreIte, 
               Vlr_Seguro = @WSegIte
         Where Cod_Estabe = @PCodEstabe
           And Ser_Nota = @PSerNot 
           And Num_Nota = @PNumNot
           And Cod_Produto = @it_CodPrd
           And Cod_Lote = @it_CodLot
           And Num_SeqIte = @it_NumSeqIte
          
        -- acumula valores 
        Set @WAccDsp = @WAccDsp + @WDspIte
        Set @WAccFre = @WAccFre + @WFreIte
        Set @WAccSeg = @WAccSeg + @WSegIte
  
        Exec PR_CalcTributNFSIT @PCodEstabe, @PSerNot, @PNumNot, @it_CodPrd, @it_CodLot, @it_NumSeqIte, @it_TipSai 	
        if @@error <> 0
          begin
            if @@trancount > 0
              Rollback Transaction
            Return
          end
  
        Fetch Next From NFSIT_Cr Into @it_CodPrd, @it_CodLot, @it_NumSeqIte, @it_TipSai,
                                      @it_QtdPrd, @it_QtdBon, @it_PerDsc,
                                      @it_VlrIcmNor, @it_VlrTotIte
      end
    Close NFSIT_Cr
    Deallocate NFSIT_Cr

   
    if @@trancount > 0
      COMMIT TRANSACTION
  end -- if Exists(
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CalcTributNFEIT]
@PCodEstabe int,
@PNumPrt int,
@PCodPrd int,
@PCodLot varchar(20),
@PNumSeqIte int,
@PTipNot char(1),
@PRegTri int,
@PFlgSbtEmbPrc bit                 -- indica ST embutida no preço

AS

SET NOCOUNT ON 

Begin Transaction

-- verifica se precisa recalcular valor st importado do Xml...
if Exists(Select 1
            From NFEIT it
                 Cross Apply (Select i.Cod_Produto, 
                                     QtdTotEnt = sum(i.Qtd_Pedido+i.Qtd_Bonificacao), 
                                     VlrTotSbt = sum(IsNull(i.Vlr_IcmRetXml,0)), 
                                     VlrTotBasSbt = sum(IsNull(i.Vlr_BasIcmRetXml,0))
                                From NFEIT i
                               Where i.Cod_Estabe = it.Cod_Estabe
                                 And i.Protocolo = it.Protocolo
                                 And i.Cod_Produto = it.Cod_Produto
                                 And i.Vlr_IcmRetXml > 0 
                               Group by Cod_Produto) x
           Where it.Cod_Estabe = @PCodEstabe
             And it.Protocolo = @PNumPrt
             And it.Cod_Produto = @PCodPrd
             And it.Cod_Lote = @PCodLot
             And it.Num_SeqIte = @PNumSeqIte
             And Round(IsNull(it.Vlr_IcmRetXml,0),2) <> Round(x.VlrTotSbt/x.QtdTotEnt*(it.Qtd_Pedido+it.Qtd_Bonificacao),2) )
  begin
    Declare @WQtdTotEnt int,
	        @WVlrTotSbt numeric(18,4), 
		    @WVlrTotBasSbt numeric(18,4)

    -- põe na memória valores totais do sbt do xml do produto
    Select @WQtdTotEnt = sum(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)), 
           @WVlrTotSbt = Round(sum(IsNull(Vlr_IcmRetXml,0)),2), 
           @WVlrTotBasSbt = Round(sum(IsNull(Vlr_BasIcmRetXml,0)),2)
      From NFEIT
     Where Cod_Estabe = @PCodEstabe
       And Protocolo = @PNumPrt
       And Cod_Produto = @PCodPrd
       And IsNull(Vlr_IcmRetXml,0) > 0 

    -- rateia valores sbt do xml
    Update it
       Set it.Vlr_IcmRetXml = Round(x.VlrTotSbt/x.QtdTotEnt*(it.Qtd_Pedido+it.Qtd_Bonificacao),2),
           it.Vlr_BasIcmRetXml = Round(x.VlrTotBasSbt/x.QtdTotEnt*(it.Qtd_Pedido+it.Qtd_Bonificacao),2)
      From NFEIT it
           Cross Apply (Select i.Cod_Produto, 
                               QtdTotEnt = sum(i.Qtd_Pedido+i.Qtd_Bonificacao), 
                               VlrTotSbt = sum(IsNull(i.Vlr_IcmRetXml,0)), 
                               VlrTotBasSbt = sum(IsNull(i.Vlr_BasIcmRetXml,0))
                          From NFEIT i
                         Where i.Cod_Estabe = it.Cod_Estabe
                           And i.Protocolo = it.Protocolo
                           And i.Cod_Produto = it.Cod_Produto
                           And i.Vlr_IcmRetXml > 0 
                         Group by Cod_Produto) x
     Where it.Cod_Estabe = @PCodEstabe
       And it.Protocolo = @PNumPrt
       And it.Cod_Produto = @PCodPrd
       And it.Cod_Lote = @PCodLot
       And it.Num_SeqIte = @PNumSeqIte
       And Round(IsNull(it.Vlr_IcmRetXml,0),2) <> Round(x.VlrTotSbt/x.QtdTotEnt*(it.Qtd_Pedido+it.Qtd_Bonificacao),2)

    -- ajusta valores totais xml original
    Update it
       Set it.Vlr_IcmRetXml = it.Vlr_IcmRetXml + (@WVlrTotSbt-x.VlrTotSbt),
           it.Vlr_BasIcmRetXml = it.Vlr_BasIcmRetXml + (@WVlrTotBasSbt-x.VlrTotBasSbt)
      From NFEIT it
           Cross Apply (Select i.Cod_Produto, 
                               QtdTotEnt = sum(i.Qtd_Pedido+i.Qtd_Bonificacao), 
                               VlrTotSbt = sum(IsNull(i.Vlr_IcmRetXml,0)), 
                               VlrTotBasSbt = sum(IsNull(i.Vlr_BasIcmRetXml,0))
                          From NFEIT i
                         Where i.Cod_Estabe = it.Cod_Estabe
                           And i.Protocolo = it.Protocolo
                           And i.Cod_Produto = it.Cod_Produto
                           And i.Vlr_IcmRetXml > 0 
                         Group by Cod_Produto) x
     Where it.Cod_Estabe = @PCodEstabe
       And it.Protocolo = @PNumPrt
       And it.Cod_Produto = @PCodPrd
       And it.Cod_Lote = @PCodLot
       And it.Num_SeqIte = @PNumSeqIte
       And (@WVlrTotSbt-x.VlrTotSbt) <> 0
  end


-- variaveis que serão gravadas na NFEIT
Declare @PPrcFab numeric(18,4),
        @PPrcVen numeric(18,4),
        @PPrcMax numeric(18,4),
        @PPrcRefFpb numeric(18,4),
        @PPrcPonFin numeric(18,4),
        
        @PTipPrcBasDebSbt varchar(1),
        @PTipPrcBasCreSbt varchar(1),
        @PBasTri numeric(18,4),
        @PCodSt varchar(2),
        @PCodCsosn varchar(3),
        @PClaTri varchar(4),
        @PCodModBasCalIcm varchar(1),
        @PAlqIcm numeric(18,4),
        @PBasIcmNor numeric(18,4),
        @PIcmNor numeric(18,4),
        @PCodModBasCalIcmSbt varchar(1),
        @PPerRedBasCalIcmDeb numeric(18,4),
        @PPerRedBasCalDeb numeric(18,4),
        @PAlqIcmDeb numeric(18,4),
        @PVlrDebIcm numeric(18,4),
        @PAlqAgrDeb numeric(18,4),
        @PPerRedBasCalIcmCre numeric(18,4),
        @PPerLimBasCalCreSbt numeric(18,4),
        @PVlrLimCreIcm numeric(18,4),
		@PVlrDspSubCusCreIcm numeric(18,4),
        @PVlrPrdSub numeric(18,4),
        @PBasSbtFnt numeric(18,4),
        @PVlrSbtFnt numeric(18,4),
        @PBasSbtRes numeric(18,4),
        @PVlrSbtRes numeric(18,4),
        @PBasSbtRec numeric(18,4),
        @PVlrSbtRec numeric(18,4),
        @PVlrPrdAnt numeric(18,4),
        @PBasAnt numeric(18,4),
        @PVlrAnt numeric(18,4),
        @PFlgUsaCreIcmSbt bit,
        @PBasIcm numeric(18,4),      -- icms tributavel
        @PVlrIcm numeric(18,4),      -- icms tributavel
        @PVlrIse numeric(18,4),
        @PVlrOut numeric(18,4),
        @PCstIpi varchar(2),
        @PBasIpi numeric(18,4),
        @PCstPis varchar(2),
        @PVlrBasPis numeric(18,4),
        @PAlqPis numeric(18,4),
        @PVlrPis numeric(18,4),
        @PVlrSuf numeric(18,4),
        @PVlrDsp numeric(18,4),
        @PCstCof varchar(2),
        @PVlrBasCof numeric(18,4),
        @PAlqCof numeric(18,4),
        @PVlrCof numeric(18,4),
        @PCodCfo smallint,
        
        @PTipLisPis varchar(1),
        @PAlqIpi numeric(18,4),
        @PCodNcm varchar(8),
        @PFlgUsaCrePresum bit,
        @PAlqCrePresum numeric(18,4),
        @PDatRefPrdCip datetime,

        @PAlqIcmFcp numeric(18,4),
        @PVlrIcmFcp numeric(18,4),          -- icms tributavel FCP: embutido em @PVlrIcm
        @PAlqIcmSbtFcp numeric(18,4),
        @PVlrSubFcp numeric(18,4),
        @PAlqIcmSbtFcpRet numeric(18,4),
        @PVlrSubFcpRet numeric(18,4),

        @PAlqIcmSbtFcpRec numeric(18,4),
        @PVlrSubFcpRec numeric(18,4),
        @PAlqIcmSbtFcpAnt numeric(18,4),
        @PVlrSubFcpAnt numeric(18,4),

        @PPerIcmDiferi numeric(18,4),
        @PVlrIcmDiferi numeric(18,4),

        @PVlrIcmDesone numeric(18,4), 
        @PMtvIcmDesone varchar(2),
        @PVlrDscTri numeric (18,4)

-- variaveis de trabalho
Declare @WCodCfoNor smallint,
        @WCodCfoSbt smallint,
        @WFlgOpeInt bit
        
-- coloca campos de NFECB na memoria
Declare @cb_CodCfo smallint,
        @cb_CodOpe varchar(3),
        @cb_Estado varchar(2),
        @cb_DatMov smalldatetime,
        @cb_DatEmi smalldatetime,
        @cb_Status varchar(1),
        @cb_VlrBasSuf numeric(18,4), 
        @cb_VlrSuf numeric(18,4),
		@cb_FlgDscIcmDesone bit,
        @em_CodEst varchar(2),
		@em_FlgContriSubstituido bit,
		@rt_FlgConsumFin bit

Select @em_CodEst = Des_Estado,
       @em_FlgContriSubstituido = IsNull(Flg_ContriSubstituido,0)
  From ESTAB
 Where Cod_Estabe = @PCodEstabe  

Select @cb_CodCfo = IsNull(cb.Cod_Cfo,0),
       @cb_CodOpe = cb.Cod_Ope,
       @cb_Estado = cb.Cod_UfOrigem,
       @cb_DatMov = cb.Dat_Movimento,
       @cb_DatEmi = cb.Dat_Emissao,
       @cb_Status = cb.Status,
       @cb_VlrBasSuf = IsNull(cb.Vlr_BasSuframa,0), 
       @cb_VlrSuf = IsNull(cb.Vlr_Suframa,0),
       @cb_FlgDscIcmDesone = IsNull(cb.Flg_DscIcmDesone,0),
	   @rt_FlgConsumFin = IsNull(rt.Flg_ConsumFin,0)
  from NFECB cb Left Join
       RGTRI rt on cb.Cod_RegTri = rt.Cod_RegTri
 Where cb.Cod_Estabe = @PCodEstabe and cb.Protocolo = @PNumPrt

-- operacao interna ou externa
if @cb_Estado = @em_CodEst
  Set @WFlgOpeInt = 1
else
  Set @WFlgOpeInt = 0

-- colococa campos de TPOPE na memoria
Declare @to_CodCfoConFinInt smallint,
        @to_CodCfoConFinExt smallint,
	    @to_CodCfoNorInt smallint,
        @to_CodCfoNorExt smallint,
        @to_CodCfoSbtInt smallint,
        @to_CodCfoSbtExt smallint,
        @to_CodCfoSubstituidoInt smallint,
        @to_CodCfoSubstituidoExt smallint,
        @to_FlgCalIcmSbt bit = 0,
        @to_FlgCalIcmNor bit = 0,
        @to_FlgCalRepIcm bit = 0,
        @to_FlgCalPisCof bit = 0,
        @to_FlgCalIpi bit,
		@to_FlgIncIpiBasIcmTrib bit

Set @WCodCfoNor = 0
Set @WCodCfoSbt = 0
Set @to_FlgCalIcmSbt = 0
Set @to_FlgCalIcmNor = 0
Set @to_FlgCalRepIcm = 0
Set @to_FlgCalPisCof = 0
Set @to_FlgCalIpi = 0
Set @to_FlgIncIpiBasIcmTrib = 0 

if Exists(Select Cod_Ope From TPOPE Where Cod_Ope = @cb_CodOpe)
  begin
    Select @to_CodCfoConFinInt = IsNull(Cod_CfoConFinInt,0),
	       @to_CodCfoConFinExt = IsNull(Cod_CfoConFinExt,0),
	       @to_CodCfoNorInt = Isnull(Cod_CfoNorInt,0),       
           @to_CodCfoNorExt = Isnull(Cod_CfoNorExt,0),
           @to_CodCfoSbtInt = Case 
                                When @em_FlgContriSubstituido = 1 and IsNull(Cod_CfoSbtIntSubstituido,0) > 0 then Cod_CfoSbtIntSubstituido
			                    Else Isnull(Cod_CfoSbtInt,0)
	 				          End, 
           @to_CodCfoSbtExt = Case 
	                            When @em_FlgContriSubstituido = 1 and IsNull(Cod_CfoSbtExtSubstituido,0) > 0 then Cod_CfoSbtExtSubstituido
					            Else Isnull(Cod_CfoSbtExt,0)
					          End,
           @to_CodCfoSubstituidoInt = IsNull(Cod_CfoSbtIntSubstituido,0),
           @to_CodCfoSubstituidoExt = IsNull(Cod_CfoSbtExtSubstituido,0),
           @to_FlgCalIcmSbt = case 
                                When @WFlgOpeInt = 1 then Isnull(Flg_CalIcmSbt,0)
                                else Isnull(Flg_CalIcmSbtExt,0)
                              end,
           @to_FlgCalIcmNor = case 
                                When @WFlgOpeInt = 1 then Isnull(Flg_CalIcmNor,0)
                                else Isnull(Flg_CalIcmNorExt,0)
                              end,
           @to_FlgCalRepIcm = case 
                                When @WFlgOpeInt = 1 then Isnull(Flg_CalRepIcmInt,0)
                                else Isnull(Flg_CalRepIcm,0)
                              end,
           @to_FlgCalPisCof = IsNull(Flg_CalPisCof,0),
           @to_FlgCalIpi = IsNull(Flg_CalIpi,0),
           @to_FlgIncIpiBasIcmTrib = Isnull(FlgIncIpiBasIcmTrib,0)
      From TPOPE
     Where Cod_Ope = @cb_CodOpe

    if @rt_FlgConsumFin = 1
      if @WFlgOpeInt = 1
	    begin
          Set @WCodCfoNor = @to_CodCfoConFinInt
          Set @WCodCfoSbt = @to_CodCfoConFinInt
        end
      else
	    begin
          Set @WCodCfoNor = @to_CodCfoConFinExt
          Set @WCodCfoSbt = @to_CodCfoConFinExt
        end
    else
      if @WFlgOpeInt = 1
        begin
          Set @WCodCfoNor = @to_CodCfoNorInt
          Set @WCodCfoSbt = @to_CodCfoSbtInt
        end
      else
        begin
          Set @WCodCfoNor = @to_CodCfoNorExt
          Set @WCodCfoSbt = @to_CodCfoSbtExt
        end
  end

-- coloca campo de PRODU na memoria
Declare @pr_ClaTri varchar(4),
        @pr_TipLisPis varchar(1)

Select @pr_ClaTri = IsNull(p.Cod_ClaTri,''),
       @pr_TipLisPis = IsNull(pr.Tip_LisPis,'')
  from PRXES p 
       Inner Join PRODU pr on p.Cod_Produt = pr.Codigo
 Where p.Cod_Estabe = @PCodEstabe     
   And p.Cod_Produt = @PCodPrd

-- coloca campos de NFEIT na memoria
Declare @it_PrcUni numeric(18,8),
        @it_PrcVen numeric(18,4),
        @it_PrcFab numeric(18,4),
        @it_PrcMax numeric(18,4),
        @it_PrcRefFpb numeric(18,4),
		@it_PrcPonFin numeric(18,4), 
        @it_QtdPed int,
        @it_QtdBon int,
        @it_PerDscIte numeric(18,8),
        @it_VlrDscRat numeric(18,4),
        @it_VlrDspTot numeric(18,4),
        @it_VlrDspSbt numeric(18,4),
        @it_VlrIpi numeric(18,4),
        @it_ClaTri varchar(4),
        @it_TipLisPis varchar(1),
		@it_XmlvICMSST numeric (18,4),
	    @it_XmlvBCST numeric (18,4)

Select @it_PrcUni = Isnull(Prc_Unitario,0), 
       @it_PerDscIte = IsNull(Per_DescItem,0),
       @it_PrcVen = Isnull(Prc_Venda,0),
       @it_PrcFab = Isnull(Prc_Fabric,0),
       @it_PrcMax = Isnull(Prc_MaxCon,0),
       @it_PrcRefFpb = Isnull(Prc_RefFpb,0),
       @it_PrcPonFin = IsNull(Prc_PonFin,0),
       @it_QtdPed = Isnull(Qtd_Pedido,0),
       @it_QtdBon = Isnull(Qtd_Bonificacao,0),
       @it_VlrDscRat = Isnull(Vlr_DescRateado,0),
       @it_VlrDspTot = Isnull(Vlr_DespRateada,0)+Isnull(Vlr_Frete,0)+Isnull(Vlr_Seguro,0),
       @it_VlrDspSbt = Isnull(Vlr_DspSbt,0),
       @it_VlrIpi = IsNull(Vlr_Ipi,0),
       @it_ClaTri = IsNull(Cod_ClaTri,''),
       @it_TipLisPis = IsNull(Tip_LisPis,''),
       @it_XmlvICMSST = Isnull(Vlr_IcmRetXml,0),      -- Xml_vICMSST + Xml_vFCPST
       @it_XmlvBCST = Isnull(Vlr_BasIcmRetXml,0)      -- Xml_vBCST
  From NFEIT 
 Where Cod_Estabe = @PCodEstabe and Protocolo = @PNumPrt and 
       Cod_Produto = @PCodPrd and Cod_Lote = @PCodLot and Num_SeqIte = @PNumSeqIte


-- calcula tributos
-- inicializar flag EMbtPrc

Set @PClaTri = @pr_ClaTri
Set @PTipLisPis = @pr_TipLisPis

if (@PTipNot = 'D') and (Charindex(@cb_Status,';A;P;') > 0)
  begin
    if @it_ClaTri <> ''
      Set @PClaTri = @it_ClaTri
    if @it_TipLisPis <> '' 
      Set @PTipLisPis = @it_TipLisPis
  end

Exec PR_CalcTributItemEntrada @PCodEstabe, @cb_DatMov, @cb_DatEmi, @PTipNot, @cb_CodCfo, @PRegTri,  
                              @to_FlgCalIcmSbt, @to_FlgCalIcmNor, @to_FlgCalRepIcm, @to_FlgCalPisCof, @to_FlgCalIpi,
                              @cb_FlgDscIcmDesone, @to_FlgIncIpiBasIcmTrib,
                              @PClaTri, @PTipLisPis, @PFlgSbtEmbPrc,          
                              @PCodPrd, @it_QtdPed, @it_QtdBon, @it_PrcUni, @it_PerDscIte,
                              @it_VlrDscRat, @it_VlrDspTot, @it_VlrDspSbt, @it_VlrIpi, @cb_VlrBasSuf, @cb_VlrSuf,
                              @it_PrcFab, @it_PrcVen, @it_PrcMax, @it_PrcRefFpb, @it_PrcPonFin,
                              @PPrcFab output, @PPrcVen output, @PPrcMax output, @PPrcRefFpb output, @PPrcPonFin output,
                              @PCodModBasCalIcm output, @PCodModBasCalIcmSbt output,
                              @PCodSt output, @PCodCsosn output, @PCstIpi output, @PCstPis output, @PCstCof output,
                              @PTipPrcBasDebSbt output, @PTipPrcBasCreSbt output,
                              @PBasTri output, @PAlqIcm output, @PBasIcmNor output, @PIcmNor output,
                              @PVlrPrdSub output, @PBasSbtFnt output, @PVlrSbtFnt output,
                              @PBasSbtRes output, @PVlrSbtRes output, @PBasSbtRec output, @PVlrSbtRec output,
                              @PBasIcm output, @PVlrIcm output, @PBasIpi output, @PVlrIse output, 
                              @PVlrPrdAnt output, @PBasAnt output, @PVlrAnt output, @PVlrOut output,
                              @PPerRedBasCalIcmDeb output, @PAlqAgrDeb output, @PPerRedBasCalDeb output,
                              @PAlqIcmDeb output, @PVlrDebIcm output, @PPerRedBasCalIcmCre output,
                              @PPerLimBasCalCreSbt output, @PVlrLimCreIcm output, @PVlrDspSubCusCreIcm output, 
                              @PVlrBasPis output, @PAlqPis output, @PVlrPis output, 
                              @PVlrBasCof output, @PAlqCof output, @PVlrCof output,
                              @PVlrSuf output, @PVlrDsp output, @PFlgUsaCreIcmSbt output,
                              @PAlqIpi output, @PCodNcm output, @PFlgUsaCrePresum output, @PAlqCrePresum output,
                              @PDatRefPrdCip output,
                              @PAlqIcmFcp output, @PVlrIcmFcp output, @PAlqIcmSbtFcp output, @PVlrSubFcp output, @PAlqIcmSbtFcpRet output, @PVlrSubFcpRet output,
                              @PAlqIcmSbtFcpRec output, @PVlrSubFcpRec output, @PAlqIcmSbtFcpAnt output, @PVlrSubFcpAnt output,
                              @PPerIcmDiferi output, @PVlrIcmDiferi output, @PVlrIcmDesone output, @PMtvIcmDesone output, @PVlrDscTri output

-- normaliza CFO
if (@WCodCfoNor = 0) or (@WCodCfoSbt= 0)
  EXEC PR_CfopEntSai  @PCodEstabe, @cb_CodCfo, @WCodCfoNor output, @WCodCfoSbt output

-- define CFOP do item conforme CST
--if Charindex(@PCodSt,'10;30;60;70;90;') > 0 
if Charindex(@PCodSt,'10;30;60;70;') > 0 
  Set @PCodCfo = @WCodCfoSbt
else
  Set @PCodCfo = @WCodCfoNor


if (@rt_FlgConsumFin = 0) and (@PCodSt = '60')
  if @WFlgOpeInt = 1
    begin
      if (@PCodCfo <> @to_CodCfoSubstituidoInt) and (@to_CodCfoSubstituidoInt > 0)
        Set @PCodCfo = @to_CodCfoSubstituidoInt
    end
else
  if @WFlgOpeInt = 0
    begin
      if (@PCodCfo <> @to_CodCfoSubstituidoExt) and (@to_CodCfoSubstituidoExt > 0)
        Set @PCodCfo = @to_CodCfoSubstituidoExt
    end

-- substiuição no XML difere do calculado no sistema
-- se sbt do Xml for menor que o calculado: calcula a diferença a recolher
if @it_XmlvBCST > 0
  begin
    if @PVlrSbtFnt > 0
      begin
        Set @PBasSbtRec = @PBasSbtFnt - @it_XmlvBCST
        Set @PVlrSbtRec = @PVlrSbtFnt - @it_XmlvICMSST
  
        Set @PBasSbtFnt = @it_XmlvBCST
        Set @PVlrSbtFnt = @it_XmlvICMSST
  
        if (@PVlrSbtRec < 0.01) or (@PBasSbtRec < 0)
          begin
            Set @PBasSbtRec = 0
            Set @PVlrSbtRec = 0
          end
      end
    else 
    if @PVlrSbtRes > 0
      begin
        Set @PBasSbtRec = @PBasSbtRes - @it_XmlvBCST
        Set @PVlrSbtRec = @PVlrSbtRes - @it_XmlvICMSST
  
        Set @PBasSbtRes = @it_XmlvBCST
        Set @PVlrSbtRes = @it_XmlvICMSST
  
        if (@PVlrSbtRes < 0.01) or (@PBasSbtRes < 0)
          begin
            Set @PBasSbtRes = 0
            Set @PVlrSbtRes = 0
          end
      end     
  end  -- if @it_XmlvBCST > 0

-- grava valores em NFEIT
Update NFEIT
   Set Cod_ClaTri = @PClaTri,
       Tip_LisPis = @PTipLisPis,
       Per_IpiCad = @PAlqIpi,
       Cod_Ncm = @PCodNcm,

       Dat_RefPrdCip = @PDatRefPrdCip,
       Prc_Venda  = @PPrcVen,
       Prc_Fabric = @PPrcFab,
       Prc_MaxCon = @PPrcMax,
       Prc_RefFpb = @PPrcRefFpb,
	   Prc_PonFin = @PPrcPonFin,

       Cod_Cfo = @PCodCfo,
       Vlr_BasTri = @PBasTri,
       Ctrl_Tributacao = @PCodSt,
       Cod_CSOSN = @PCodCsosn,
       Tip_PrcBasDebSbt = @PTipPrcBasDebSbt,  
       Tip_PrcBasCreSbt = @PTipPrcBasCreSbt,
       Alq_Icms = @PAlqIcm,
       Vlr_BasIcmsNor = @PBasIcmNor,
       Vlr_IcmsNor = @PIcmNor,
       Flg_UsaCrePresum = @PFlgUsaCrePresum, 
       Alq_IcmPresum  = @PAlqCrePresum,
	   
       Vlr_PrdSubTri = @PVlrPrdSub,
       Vlr_BasSubsTrib = @PBasSbtFnt,
       Vlr_SubsTrib = @PVlrSbtFnt,
       Vlr_BasSbtRes = @PBasSbtRes,
       Vlr_SbtRes = @PVlrSbtRes,
       Vlr_BasDifTri = @PBasSbtRec,
       Vlr_DifTri = @PVlrSbtRec,
       Vlr_BasAntRec = @PBasAnt,
       Vlr_PrdAntRec = @PVlrPrdAnt,
       Vlr_AntRec = @PVlrAnt,
	   
       Vlr_BasIcmsTrib = @PBasIcm,
       Vlr_IcmsTrib = @PVlrIcm,
       Vlr_BasIpi = @PBasIpi,
       Vlr_Isento = @PVlrIse,
       Vlr_Outros = @PVlrOut,
	   
       Flg_UsaCreIcmSbt = @PFlgUsaCreIcmSbt,
       Per_RedBasCalIcmDeb = @PPerRedBasCalIcmDeb,
       Alq_AgrDeb = @PAlqAgrDeb,
       Per_RedBasCalDeb = @PPerRedBasCalDeb,
       Alq_IcmDeb = @PAlqIcmDeb,       -- Alq_IcmSbt ????
       Vlr_DebIcm = @PVlrDebIcm,
       Per_RedBasCalIcmCre = @PPerRedBasCalIcmCre,
       Per_LimBasCalCreSbt = @PPerLimBasCalCreSbt,
       Vlr_LimCreIcm = @PVlrLimCreIcm,
	   Vlr_DspCusEnt = @PVlrDspSubCusCreIcm,
	   
       Cod_ModBasCalIcm = @PCodModBasCalIcm,
       Cod_ModBasCalIcmSbt = @PCodModBasCalIcmSbt,
       CST_Ipi = @PCstIpi,
	   
       CST_Pis = @PCstPis,
       Vlr_BasPis = @PVlrBasPis,
       Alq_Pis = @PAlqPis,
       Vlr_Pis = @PVlrPis,
       Vlr_Suframa = @PVlrSuf,
       Vlr_DspExt = @PVlrDsp,
       CST_Cofins = @PCstCof,
       Vlr_BasCofins = @PVlrBasCof,
       Alq_Cofins = @PAlqCof,
       Vlr_Cofins = @PVlrCof,
	   
       Alq_FcpIcm = @PAlqIcmFcp, 
       Vlr_FcpIcm = @PVlrIcmFcp, 
	   
       Alq_FcpSbt = @PAlqIcmSbtFcp, 
       Vlr_FcpSbt = @PVlrSubFcp, 
	   
       Alq_FcpSbtRet = @PAlqIcmSbtFcpRet, 
       Vlr_FcpSbtRet = @PVlrSubFcpRet,
	   
       Alq_FcpSbtRec = @PAlqIcmSbtFcpRec, 
       Vlr_FcpSbtRec = @PVlrSubFcpRec,
	   
       Alq_FcpSbtAnt = @PAlqIcmSbtFcpAnt, 
       Vlr_FcpSbtAnt = @PVlrSubFcpAnt,
	   
       Per_IcmDiferi = IsNull(@PPerIcmDiferi,0),  -- aqui ver pq precisa IsNull
       Vlr_IcmDiferi = IsNull(@PVlrIcmDiferi,0),  -- aqui ver pq precisa IsNull
	   
       Vlr_IcmsDeson = IsNull(@PVlrIcmDesone,0),  -- aqui ver pq precisa IsNull
       Cod_MtvIcmsDeson = @PMtvIcmDesone,
	   Vlr_DscTri = @PVlrDscTri

 Where Cod_Estabe = @PCodEstabe and Protocolo = @PNumPrt 
   And Cod_Produto = @PCodPrd and Cod_Lote = @PCodLot and Num_SeqIte = @PNumSeqIte


-- simula NFEIT_GravaCalcFields(NfeItCds)
-- calcula valor liquido e custo unitario do item na nota
-- procedimento sera executado tambem no fechamento da nota
Update NFEIT
   Set Vlr_LiqIte = dbo.FN_ValLiqIteNFEIT(Cod_Estabe,
                                          Protocolo,
                                          Cod_Produto,
                                          Cod_Lote,
                                          Num_SeqIte),
       Cus_LiqUni = dbo.FN_CusLiqUniNFEIT(Cod_Estabe,
                                          Protocolo,
                                          Cod_Produto,
                                          Cod_Lote,
                                          Num_SeqIte)
 Where Cod_Estabe = @PCodEstabe 
   and Protocolo = @PNumPrt 
   and Cod_Produto = @PCodPrd 
   and Cod_Lote = @PCodLot 
   and Num_SeqIte = @PNumSeqIte

Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CalculaValoresNfeSrvSuframa]
@PCodEstabe int,
@PNumPrt int

AS

SET NOCOUNT ON 

BEGIN TRANSACTION

-- coloca campos de tabelas na memoria
Declare @PValBas numeric(18,4),
        @PValImp numeric(18,4),
        @em_FlgSujSuframa bit

-- ESTAB
Select @em_FlgSujSuframa = IsNull(Flg_SujSuframa,0)
  From ESTAB
Where Cod_Estabe = @PCodEstabe  

Set @PValBas = 0
Set @PValImp = 0

if @em_FlgSujSuframa = 1
  begin
    Declare @WValBasTeto numeric(18,4),
            @WValImpTeto numeric(18,4),
            @WValMerIpi numeric(18,4),
            @WValTaxSrv numeric(18,4),
            @WFator int

    -- calcula valores tetos registrados na tabela de serviços da SUFRAMA
    Set @WValBasTeto = 0
    Set @WValImpTeto = 0

    if Exists(Select 1 From TBSUF)
      begin
         Select top 1 @WValBasTeto = Round(IsNull(Vlr_LimInt,0),2), 
                      @WValImpTeto = Round(IsNull(Vlr_TaxSrv,0),2) 
           From TBSUF 
         Order by Vlr_LimInt desc 

        -- calcula valor da mercadoria sujeito a IPI conf. cadastro no produto proveniente de industria(fabricante)
        -- e se nao houver IPI cobrado na NF
        Set @WValMerIpi = IsNull((Select sum(Round(it.Vlr_TotItem,2)) as Tot_Vlr 
                                    From NFECB cb Inner Join 
                                         FORNE fo on (cb.Cod_EmiFornec = fo.Codigo) Inner Join 
                                         NFEIT it on (cb.Cod_Estabe = it.Cod_Estabe) and (cb.Protocolo = it.Protocolo) Inner Join 
                                         PRODU pr on (it.Cod_Produto = pr.Codigo) 
                                  Where it.Cod_Estabe = @PCodEstabe
                                  And it.Protocolo = @PNumPrt
                                  And fo.Tipo = 'F'
                                  And IsNull(cb.Vlr_Ipi,0) = 0
                                  And IsNull(pr.Per_Ipi,0) > 0),0)
            
        if (@WValMerIpi > 0) and (@WValBasTeto > 0)
          begin
            Set @PValBas = @WValMerIpi

            -- determina fator em relacao ao teto
            Set @WFator = @WValMerIpi/@WValBasTeto  -- retorna parte inteira: trunca
            Set @PValImp = @WFator * @WValImpTeto

            -- calcula valor residual
            Set @WValMerIpi = @WValMerIpi - @WFator*@WValBasTeto
            if @WValMerIpi > 0
              begin
                Set @WValTaxSrv = 0

                Select top 1 @WValTaxSrv = Vlr_TaxSrv 
                  From TBSUF 
                Where Vlr_LimInt >= @WValMerIpi
                Order by Vlr_LimInt 

                Set @PValImp = @PValImp + IsNull(@WValTaxSrv,0)
              end
          end
          
      end

    -- registra valores Suframa em NFECB
    Update NFECB
      Set Vlr_BasSuframa = @PValBas,
          Vlr_Suframa = @PValImp
    Where Cod_Estabe = @PCodEstabe
    And Protocolo = @PNumPrt
      
  end

COMMIT TRANSACTION  
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_RateiaValoresNFEIT] 
@PCodEstabe int,
@PNumPrt int

WITH RECOMPILE
AS

SET NOCOUNT ON

Begin Transaction

  -- variaveis que serão gravadas na NFEIT
  Declare @P_DscRatIte numeric(18,4),
          @P_DspRatIte numeric(18,4),
          @P_FreIte numeric(18,4),
          @P_SegIte numeric(18,4),
          @P_DscIteExt numeric(18,4),
          @P_DspIteExt numeric(18,4),
          @P_VlrFreCte numeric(18,4),
          @P_DspIteSbt numeric(18,4)
  
  -- variaveis de trabalho
  Declare @WQtdIteDsc int,
          @WCabTotIte int, 
          @WCabVlrIte numeric(18,4),
          @WVlrBasIteDsc numeric(18,4),
          @WFlgSbtEmbPrc bit,

          @WAccDsc numeric(18,4),
          @WAccDsp numeric(18,4),
          @WAccFre numeric(18,4),
          @WAccSeg numeric(18,4),
          @WAccDscExt numeric(18,4),
          @WAccDspExt numeric(18,4),
          @WAccDspSbt numeric(18,4),
          @WAccFreCte numeric(18,4),
          @WAccIte int,
          @WAccIteDsc int

  -- poe na memoria campos NFECB
  Declare @cb_StrRelDoc varchar(60),
          @cb_TipNot varchar(1),
          @cb_CodCfo smallint,
          @cb_CodRegTri int,
          @cb_VlrDsc numeric(18,4),
          @cb_VlrDsp numeric(18,4),
          @cb_VlrFre numeric(18,4),
          @cb_VlrSeg numeric(18,4),
          @cb_VlrDscExtCus numeric(18,4),
          @cb_VlrDspExtCus numeric(18,4),
          @cb_VlrFreCte numeric(18,4),
          @cb_VlrDspSbt numeric(18,4)

  -- normaliza campos 
  Update NFECB
    Set Vlr_Mercadoria = round(Vlr_Mercadoria,2),
        Vlr_Desconto = round(Vlr_Desconto,2),
        Vlr_DscTri = round(IsNull(Vlr_DscTri,0),2),
        Vlr_IstFon = round(Vlr_IstFon,2),
        Vlr_SbtRes = round(Vlr_SbtRes,2),
        Vlr_Ipi = round(Vlr_Ipi,2),
        Vlr_Despesas = round(Vlr_Despesas,2),     
        Vlr_OutDsp = round(Vlr_OutDsp,2),
        Vlr_Frete = round(Vlr_Frete,2),
        Vlr_Seguro = round(Vlr_Seguro,2),
        Vlr_DspExt = round(Vlr_DspExt,2)
  Where Cod_Estabe = @PCodEstabe
  And Protocolo = @PNumPrt
        
  Select @cb_TipNot = Tip_NF, 
         @cb_CodCfo = Cod_Cfo,
         @cb_CodRegTri = Cod_RegTri,
         @cb_StrRelDoc = Ltrim(Rtrim(Str_RelDoc)),
         @cb_VlrDsc = Round(IsNull(Vlr_Desconto,0),2),
         @cb_VlrDsp = Round(IsNull(Vlr_Despesas,0)+IsNull(Vlr_OutDsp,0),2),
         @cb_VlrFre = Round(IsNull(Vlr_Frete,0),2),
         @cb_VlrSeg = Round(IsNull(Vlr_Seguro,0),2),
         @cb_VlrDscExtCus = Round(IsNull(Vlr_DscExtNotFis,0),2),
         @cb_VlrDspExtCus = Round(IsNull(Vlr_DspExtNotFis,0),2),
         @cb_VlrFreCte = Round(IsNull(Vlr_FreCte,0),2),
         @cb_VlrDspSbt = Round(IsNull(Vlr_DspSbt,0),2)
    From NFECB
  Where Cod_Estabe = @PCodEstabe
  And Protocolo = @PNumPrt

  Select @WCabTotIte = count(*), 
         @WCabVlrIte = sum(Round(IsNull(Vlr_TotItem,0),2))
    From NFEIT 
  Where Cod_Estabe = @PCodEstabe
  And Protocolo = @PNumPrt

  -- valor total dos itens sujeitos a descontos
  Set @WVlrBasIteDsc = 0
  Set @WQtdIteDsc = 0

  Select @WQtdIteDsc = count(*), 
         @WVlrBasIteDsc = sum(Round(IsNull(Vlr_TotItem,0),2))
    From NFEIT 
  Where Cod_Estabe = @PCodEstabe
  And Protocolo = @PNumPrt
  And IsNull(Flg_BlqDsc,0) = 0 

  -- calcula valores Suframa
  Exec PR_CalculaValoresNfeSrvSuframa @PCodEstabe,@PNumPrt
  if @@error <> 0
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end

  -- gera registro de nf relacionadas
  if @cb_StrRelDoc <> ''
    begin
      Exec PR_RegistraNEREF @PCodEstabe,@PNumPrt
      if @@error <> 0
        begin
          if @@trancount > 0
            Rollback Transaction
          Return
        end
    end

  -- se for devolução atualiza preços-base conforme NF Saída relacionada
  if @cb_TipNot = 'D'
    begin
      Update ite 
        Set ite.Prc_Venda  = Case When IsNull(its.Prc_TabBru,0) > 0 Then IsNull(its.Prc_TabBru,0) Else IsNull(ite.Prc_Venda,0)  End, 
            ite.Prc_fabric = Case When IsNull(its.Prc_fabric,0) > 0 Then IsNull(its.Prc_fabric,0) Else IsNull(ite.Prc_fabric,0) End, 
            ite.Prc_MaxCon = Case When IsNull(its.Prc_MaxCon,0) > 0 Then IsNull(its.Prc_MaxCon,0) Else IsNull(ite.Prc_MaxCon,0) End, 
            ite.Prc_RefFpb = Case When IsNull(its.Prc_RefFpb,0) > 0 Then IsNull(its.Prc_RefFpb,0) Else IsNull(ite.Prc_RefFpb,0) End 
        From NFEIT ite Inner Join 
            (Select distinct rf.Cod_Estabe, rf.Protocolo, cb.Dat_Emissao, it.Cod_Produto, it.Prc_TabBru, it.Prc_Fabric, it.Prc_MaxCon, it.Prc_RefFpb 
               From NFSIT it Inner Join 
                    NFSCB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Ser_Nota = cb.Ser_Nota and it.Num_Nota = cb.Num_Nota Inner Join 
                    NEREF rf on cb.Cod_Estabe = rf.Cod_Estabe and cb.Ser_Nota = rf.Ser_DocRef and cb.Num_Nota = rf.Num_DocRef 
             Where rf.Cod_Estabe = @PCodEstabe
             And rf.Protocolo = @PNumPrt
             And rf.Tip_EntSai = 'S') its on ite.Cod_Estabe = its.Cod_Estabe and ite.Protocolo = its.Protocolo and ite.Cod_Produto = its.Cod_Produto And 
                                             its.Dat_Emissao = (Select MAX(c.Dat_Emissao) 
                                                                  From NFSIT i Inner Join 
                                                                       NFSCB c on i.Cod_Estabe = c.Cod_Estabe and i.Ser_Nota = c.Ser_Nota and i.Num_Nota = c.Num_Nota Inner Join 
                                                                       NEREF r on c.Cod_Estabe = r.Cod_Estabe and c.Ser_Nota = r.Ser_DocRef and c.Num_Nota = r.Num_DocRef 
                                                                Where r.Cod_Estabe = @PCodEstabe 
                                                                And r.Protocolo = @PNumPrt
                                                                And r.Tip_EntSai = 'S'
                                                                And i.Cod_Produto = ite.Cod_Produto) 
      Where its.Cod_Estabe = @PCodEstabe
      And its.Protocolo = @PNumPrt
      And ((IsNull(ite.Prc_Venda,0)  <> IsNull(its.Prc_TabBru,0)) or 
           (IsNull(ite.Prc_fabric,0) <> IsNull(its.Prc_fabric,0)) or 
           (IsNull(ite.Prc_MaxCon,0) <> IsNull(its.Prc_MaxCon,0)) or 
           (IsNull(ite.Prc_RefFpb,0) <> IsNull(its.Prc_RefFpb,0))) 
    end

  -- desconto rateado para todos os itens,  despesas somente p/ itens com icms
  if IsNull(@cb_TipNot,'') = '' 
    begin
      Set @cb_TipNot = ISNULL((Select Tip_NotFis From TBCFO Where Codigo = @cb_CodCfo),'C')
    end

  -- inicializa acumuladores
  Set @WAccDsc = 0
  Set @WAccDsp = 0
  Set @WAccFre = 0
  Set @WAccSeg = 0

  Set @WAccDscExt = 0
  Set @WAccDspExt = 0
  Set @WAccFreCte = 0
  Set @WAccDspSbt = 0
  Set @WAccIte    = 0
  Set @WAccIteDsc = 0

  -- Percorre itens
  Declare @it_CodPrd int,
          @it_CodLot varchar(20), 
          @it_NumSeqIte int,
          @it_VlrIte numeric(18,4),
          @it_FlgBlqDsc bit
        
  DECLARE NFEIT_Cr CURSOR Local Fast_Forward For 

    Select it.Cod_Produto, it.Cod_Lote, it.Num_SeqIte,
           Round(IsNull(it.Vlr_TotItem,0),2),
           IsNull(it.Flg_BlqDsc,0)
      From NFEIT it Inner Join
           PRODU pr on it.Cod_Produto = pr.Codigo
    Where it.Cod_Estabe = @PCodEstabe
    And it.Protocolo = @PNumPrt

  OPEN NFEIT_Cr

  FETCH NEXT FROM NFEIT_Cr INTO @it_CodPrd, @it_CodLot, @it_NumSeqIte,
                                @it_VlrIte, @it_FlgBlqDsc

  WHILE @@FETCH_STATUS = 0
  BEGIN
    Set @WAccIte = @WAccIte + 1

    Set @P_DscRatIte = 0
    Set @P_DspRatIte = 0
    Set @P_FreIte = 0
    Set @P_SegIte = 0
    Set @P_DscIteExt = 0
    Set @P_DspIteExt = 0
    Set @P_VlrFreCte = 0
    Set @P_DspIteSbt = 0
  
    if @WCabVlrIte > 0
      begin
        -- rateia descontos
        if @it_FlgBlqDsc = 0
          begin
            Set @WAccIteDsc = @WAccIteDsc + 1
            Set @P_DscRatIte = Round(@cb_VlrDsc*@it_VlrIte/@WVlrBasIteDsc,2)
            if (@WAccDsc + @P_DscRatIte) > @cb_VlrDsc
              Set @P_DscRatIte = @cb_VlrDsc - @WAccDsc
          end

         -- rateia despesas/frete/seguro
        Set @P_DspRatIte = Round(@cb_VlrDsp*@it_VlrIte/@WCabVlrIte,2)
        if (@WAccDsp + @P_DspRatIte) > @cb_VlrDsp 
          Set @P_DspRatIte = @cb_VlrDsp - @WAccDsp

        Set @P_FreIte = Round(@cb_VlrFre*@it_VlrIte/@WCabVlrIte,2)
        if (@WAccFre + @P_FreIte) > @cb_VlrFre
          Set @P_FreIte = @cb_VlrFre - @WAccFre

        Set @P_SegIte = Round(@cb_VlrSeg*@it_VlrIte/@WCabVlrIte,2)
        if (@WAccSeg + @P_SegIte) > @cb_VlrSeg 
          Set @P_SegIte = @cb_VlrSeg - @WAccSeg

        -- rateia descontos extras
        Set @P_DscIteExt = Round(@cb_VlrDscExtCus*@it_VlrIte/@WCabVlrIte,2)
        if (@WAccDscExt + @P_DscIteExt) > @cb_VlrDscExtCus
          Set @P_DscIteExt = @cb_VlrDscExtCus - @WAccDscExt
        
        -- rateia despesas extras
        Set @P_DspIteExt = Round(@cb_VlrDspExtCus*@it_VlrIte/@WCabVlrIte,2)
        if (@WAccDspExt + @P_DspIteExt) > @cb_VlrDspExtCus
          Set @P_DspIteExt = @cb_VlrDspExtCus - @WAccDspExt
        
        -- rateia valor frete conhecimento transporte
        Set @P_VlrFreCte = Round(@cb_VlrFreCte*@it_VlrIte/@WCabVlrIte,2)
        if (@WAccFreCte + @P_VlrFreCte) > @cb_VlrFreCte
          Set @P_VlrFreCte = @cb_VlrFreCte - @WAccFreCte
        
        -- rateia despesas subst.tribut.
        Set @P_DspIteSbt = Round(@cb_VlrDspSbt*@it_VlrIte/@WCabVlrIte,2)
        if (@WAccDspSbt + @P_DspIteSbt) > @cb_VlrDspSbt
          Set @P_DspIteSbt = @cb_VlrDspSbt - @WAccDspSbt
      end

    -- assegura fechamento de valores no ultimo item
    if @WAccIte = @WCabTotIte
      begin
        Set @P_DscRatIte = @cb_VlrDsc - @WAccDsc
        Set @P_DspRatIte = @cb_VlrDsp - @WAccDsp
        Set @P_FreIte = @cb_VlrFre - @WAccFre
        Set @P_SegIte = @cb_VlrSeg - @WAccSeg
        Set @P_DscIteExt = @cb_VlrDscExtCus - @WAccDscExt
        Set @P_DspIteExt = @cb_VlrDspExtCus - @WAccDspExt
        Set @P_VlrFreCte = @cb_VlrFreCte - @WAccFreCte
        Set @P_DspIteSbt = @cb_VlrDspSbt - @WAccDspSbt
      end

    if @WAccIteDsc = @WQtdIteDsc 
      begin
        Set @P_DscRatIte = @cb_VlrDsc - @WAccDsc
      end

    Update NFEIT
      Set Vlr_DescRateado = @P_DscRatIte,
          Vlr_DespRateada = @P_DspRatIte,
          Vlr_Frete = @P_FreIte,
          Vlr_Seguro = @P_SegIte,
          Vlr_DscExtNotFis = @P_DscIteExt,
          Vlr_DspExtNotFis = @P_DspIteExt,
          Vlr_FreCte = @P_VlrFreCte,
          Vlr_DspSbt = @P_DspIteSbt
    Where Cod_Estabe = @PCodEstabe
    And Protocolo = @PNumPrt
    And Cod_Produto = @it_CodPrd
    and Cod_Lote = @it_CodLot 
    and Num_SeqIte = @it_NumSeqIte
    
    Set @WAccDsc = @WAccDsc + @P_DscRatIte
    Set @WAccDsp = @WAccDsp + @P_DspRatIte
    Set @WAccFre = @WAccFre + @P_FreIte
    Set @WAccSeg = @WAccSeg + @P_SegIte

    Set @WAccDscExt = @WAccDscExt + @P_DscIteExt
    Set @WAccDspExt = @WAccDspExt + @P_DspIteExt
    Set @WAccFreCte = @WAccFreCte + @P_VlrFreCte
    Set @WAccDspSbt = @WAccDspSbt + @P_DspIteSbt

    -- sbt incluida no preço
    Set @WFlgSbtEmbPrc = 0
    if Exists(Select 1
                From NFSCB cb Inner Join 
                     NFSIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Ser_Nota = it.Ser_Nota and cb.Num_Nota = it.Num_Nota Inner Join 
                     NEREF rf on cb.Cod_Estabe = rf.Cod_Estabe and cb.Ser_Nota = rf.Ser_DocRef and cb.Num_Nota = rf.Num_DocRef 
              Where rf.Cod_Estabe = @PCodEstabe
              And rf.Protocolo = @PNumPrt
              And rf.Tip_EntSai = 'S'
              And it.Cod_Produto = @it_CodPrd
              And IsNull(it.Vlr_SubsTribEmb,0) > 0 )
      Set @WFlgSbtEmbPrc = 1
 
    -- calcula tributacao
    Exec PR_CalcTributNFEIT @PCodEstabe, @PNumPrt, @it_CodPrd, @it_CodLot, @it_NumSeqIte,
                            @cb_TipNot, @cb_CodRegTri, @WFlgSbtEmbPrc
    if @@error <> 0
      begin
        if @@trancount > 0
          Rollback Transaction
        Return
      end
    
    FETCH NEXT FROM NFEIT_Cr INTO @it_CodPrd, @it_CodLot, @it_NumSeqIte,
                                  @it_VlrIte, @it_FlgBlqDsc
  END  -- while

  CLOSE NFEIT_Cr
  DEALLOCATE NFEIT_Cr

  --  registra em NEMEM configuracoes atuais de RTXCT
  Exec PR_RegistraNEMEM @PCodEstabe, @PNumPrt
  if @@error <> 0
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end

if @@trancount > 0
  Commit Transaction
  
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CriticaOperacaoTriangular]
@PCodEstabe int,
@PNumNota int,
@PSerNota varchar(3),
@PTipNota char(1),
@PMsgAlerta varchar(100) output,
@PMsgErro varchar(100) output

AS
SET NOCOUNT ON

Set @PMsgAlerta = ''
Set @PMsgErro = ''

Declare @WNumNotVnc int = 0,
        @WSerNotVnc varchar(3) = '',
        @WFlgOperacTriang bit = 0,
        @WMsgNumNotVinc varchar(30) = '',

        @WTipNf varchar(1),
        @WCodCfo int,
        @WCodFinNfe varchar(1),
		@WFlgMovEst bit,
        @WFlgAtuCus bit,
		@WVlrIcmsTri numeric(18,4),
		@WVlrPis numeric(18,4),
		@WFlgOpeVdo bit,

        @WTipNfVnc varchar(1),
        @WCodCfoVnc int = 0,
		@WFlgMovEstVnc bit = 0,
        @WFlgAtuCusVnc bit = 0,
		@WVlrIcmsTriVnc numeric(18,4) = 0,
		@WVlrPisVnc numeric(18,4) = 0,
		@WFlgOpeVdoVnc bit = 0

if @PTipNota = 'E'
  begin
    -- registra documentos relacionados
    if ((Select RTRIM(LTRIM(ISNULL(Str_RelDoc,'')))
           From NFECB 
          Where Cod_Estabe = @PCodEstabe 
            and Protocolo = @PNumNota) <> '') and
       not Exists(Select 1 From NEREF
                   Where Cod_Estabe = @PCodEstabe
                     and Protocolo = @PNumNota)
      Exec PR_RegistraNEREF @PCodEstabe, @PNumNota
    
    if ((Select RTRIM(LTRIM(ISNULL(Str_RelDoc,'')))
           From NFECB 
          Where Cod_Estabe = @PCodEstabe 
            and Protocolo = @PNumNota) = '') and
       Exists(Select 1 From NEREF
               Where Cod_Estabe = @PCodEstabe
                 and Protocolo = @PNumNota)
      Exec PR_RegistraNEREF @PCodEstabe, @PNumNota

    Select @WTipNf      = Tip_Nf,
           @WCodCfo     = IsNull(cb.Cod_Cfo,0), 
           @WCodFinNfe  = IsNull(cb.Cod_FinNfe,'1'),
           @WFlgMovEst  = IsNull(cb.Flg_MovEst,0), 
           @WFlgAtuCus  = IsNull(cb.Flg_AtuPrcCus,0),
           @WVlrIcmsTri = IsNull(cb.Vlr_IcmsTri,0), 
           @WVlrPis     = IsNull(cb.Vlr_Pis,0),
           @WFlgOpeVdo  = IsNull(op.Flg_OpeVdo,0)
      From NFECB cb
           inner Join TPOPE op  on cb.Cod_Ope = op.Cod_Ope
     Where cb.Cod_Estabe = @PCodEstabe
       And cb.Protocolo = @PNumNota

    if (@WFlgOpeVdo = 0) or
       ((@WCodFinNfe <> '1') and (@WCodFinNfe <> '4'))  -- '1'-Normal, '4'-Devolução
      Return 

    if (@WFlgOpeVdo = 1) and (@WFlgAtuCus = 1)
      begin
        if not Exists(Select 1 From NEREF
                       Where Cod_Estabe = @PCodEstabe
                         And Protocolo = @PNumNota
                         And Tip_EntSai = 'E')
          begin
            Set @PMsgErro = 'Necessário vincular uma NF de Entrada em Op.Triangular'
            Return
          end
      end  -- if @WFlgOpeVdo = 1

    -- verifica se existe NF vinculada
    Set @WNumNotVnc = 0
    Select top 1 
           @WNumNotVnc     = IsNull(rf.Num_DocRef,0),
           @WTipNfVnc      = IsNull(cbv.Tip_Nf,''), 
           @WCodCfoVnc     = IsNull(cbv.Cod_Cfo,0), 
    	   @WFlgMovEstVnc  = IsNull(cbv.Flg_MovEst,0),
           @WFlgAtuCusVnc  = IsNull(cbv.Flg_AtuPrcCus,0),
           @WVlrIcmsTriVnc = IsNull(cbv.Vlr_IcmsTri,0), 
           @WVlrPisVnc     = IsNull(cbv.Vlr_Pis,0),
    	   @WFlgOpeVdoVnc  = IsNull(opv.Flg_OpeVdo,0)
      From NEREF rf 
           Left  Join NFECB cbv on cbv.Cod_Estabe = rf.Cod_Estabe 
                               and cbv.Protocolo = rf.Num_DocRef 
           Left  Join TPOPE opv on cbv.Cod_Ope = opv.Cod_Ope
     Where rf.Cod_Estabe = @PCodEstabe
       And rf.Protocolo = @PNumNota
       And rf.Tip_EntSai = 'E' 
           
    -- verifica se a NF é vinculada à outra NF
    if IsNull(@WNumNotVnc,0) = 0
      Select top 1 
             @WNumNotVnc     = cb.Protocolo, 
             @WFlgMovEstVnc  = IsNull(cb.Flg_MovEst,0),
             @WFlgAtuCusVnc  = IsNull(cb.Flg_AtuPrcCus,0),
             @WVlrIcmsTriVnc = IsNull(cb.Vlr_IcmsTri,0), 
             @WVlrPisVnc     = IsNull(cb.Vlr_Pis,0),
             @WFlgOpeVdoVnc  = op.Flg_OpeVdo
        From NFECB cb
             inner Join TPOPE op on cb.Cod_Ope = op.Cod_Ope
             inner Join NEREF rf on cb.Cod_Estabe = rf.Cod_Estabe 
                                and cb.Protocolo = rf.Protocolo 
                                and rf.Tip_EntSai = 'E' 
                                and rf.Num_DocRef = @PNumNota
       Where cb.Cod_Estabe = @PCodEstabe

    Set @WMsgNumNotVinc = ' (Protoc.Vinc. '+cast(@WNumNotVnc as varchar)+')'

  end  -- if @PTipNota = 'E'


if @PTipNota = 'S'
  begin
    -- registra documentos relacionados
    if ((Select RTRIM(LTRIM(ISNULL(Str_RelDoc,'')))
           From NFSCB 
          Where Cod_Estabe = @PCodEstabe 
            and Ser_Nota = @PSerNota
            and Num_Nota = @PNumNota) <> '') and
       not Exists(Select 1 From NSREF
                   Where Cod_Estabe = @PCodEstabe
                     and Ser_Nota = @PSerNota
                     and Num_Nota = @PNumNota)
      Exec PR_RegistraNSREF @PCodEstabe, @PSerNota, @PNumNota
    
    if ((Select RTRIM(LTRIM(ISNULL(Str_RelDoc,'')))
           From NFSCB 
          Where Cod_Estabe = @PCodEstabe 
            and Ser_Nota = @PSerNota
            and Num_Nota = @PNumNota) = '') and
       Exists(Select 1 From NSREF
               Where Cod_Estabe = @PCodEstabe
                 and Ser_Nota = @PSerNota
                 and Num_Nota = @PNumNota)
      Exec PR_RegistraNSREF @PCodEstabe, @PserNota, @PNumNota

    Select @WTipNf      = cb.Tip_Saida, 
           @WCodCfo     = IsNull(cb.Cod_Cfo1,0), 
           @WCodFinNfe  = IsNull(cb.Cod_FinNfe,'1'),
           @WFlgMovEst  = IsNull(cb.Flg_MovEst,0), 
           @WFlgAtuCus  = IsNull(cb.Flg_MovEst,0),  -- cb.Flg_AtuPrcCus
           @WVlrIcmsTri = IsNull(cb.Vlr_IcmsTri,0), 
           @WVlrPis     = IsNull(cb.Vlr_Pis,0),
           @WFlgOpeVdo  = IsNull(op.Flg_OpeVdo,0)
      From NFSCB cb
           inner Join TPOPE op  on cb.Cod_Ope = op.Cod_Ope
     Where cb.Cod_Estabe = @PCodEstabe
       And cb.Ser_Nota = @PSerNota
       And cb.Num_Nota = @PNumNota

    if (@WFlgOpeVdo = 0) or
       ((@WCodFinNfe <> '1') and (@WCodFinNfe <> '4'))  -- '1'-Normal, '4'-Devolução
      Return 

    if (@WFlgOpeVdo = 1) and (@WFlgAtuCus = 1)
      begin
        if not Exists(Select 1 From NSREF
                       Where Cod_Estabe = @PCodEstabe
                         And Ser_Nota = @PSerNota
                         And Num_Nota = @PNumNota
                         And Tip_EntSai = 'S')
          begin
            Set @PMsgErro = 'Necessário vincular uma NF de Saída em Op.Triangular'
            Return
          end
      end  -- if @WFlgOpeVdo = 1

    -- verifica se existe NF vinculada
    Set @WNumNotVnc = 0
    Select top 1 
           @WSerNotVnc     = IsNull(rf.Ser_DocRef,0),
           @WNumNotVnc     = IsNull(rf.Num_DocRef,0),
           @WTipNfVnc      = IsNull(cbv.Tip_Saida,''), 
           @WCodCfoVnc     = IsNull(cbv.Cod_Cfo1,0), 
    	   @WFlgMovEstVnc  = IsNull(cbv.Flg_MovEst,0),
           @WFlgAtuCusVnc  = IsNull(cbv.Flg_MovEst,0),  -- Flg_AtuPrcCus
           @WVlrIcmsTriVnc = IsNull(cbv.Vlr_IcmsTri,0), 
           @WVlrPisVnc     = IsNull(cbv.Vlr_Pis,0),
    	   @WFlgOpeVdoVnc  = IsNull(opv.Flg_OpeVdo,0)
      From NSREF rf
           Left  Join NFSCB cbv on cbv.Cod_Estabe = rf.Cod_Estabe 
                               and cbv.Ser_Nota = rf.Ser_DocRef 
                               and cbv.Num_Nota = rf.Num_DocRef 
           Left  Join TPOPE opv on cbv.Cod_Ope = opv.Cod_Ope
     Where rf.Cod_Estabe = @PCodEstabe
       And rf.Ser_Nota = @PSerNota
       And rf.Num_Nota = @PNumNota
       And rf.Tip_EntSai = 'S' 
       
    -- verifica se a NF é vinculada à outra NF
    if IsNull(@WNumNotVnc,0) = 0
      Select top 1 
             @WSerNotVnc     = cb.Ser_Nota, 
             @WNumNotVnc     = cb.Num_Nota, 
             @WFlgMovEstVnc  = IsNull(cb.Flg_MovEst,0),
             @WFlgAtuCusVnc  = IsNull(cb.Flg_MovEst,0),
             @WVlrIcmsTriVnc = IsNull(cb.Vlr_IcmsTri,0), 
             @WVlrPisVnc     = IsNull(cb.Vlr_Pis,0),
             @WFlgOpeVdoVnc  = op.Flg_OpeVdo
        From NFSCB cb
             inner Join TPOPE op on cb.Cod_Ope = op.Cod_Ope
             inner Join NSREF rf on cb.Cod_Estabe = rf.Cod_Estabe 
                                and cb.Ser_Nota = rf.Ser_Nota
                                and cb.Num_Nota = rf.Num_Nota
                                and rf.Tip_EntSai = 'S' 
                                and rf.Num_DocRef = @PNumNota
       Where cb.Cod_Estabe = @PCodEstabe

    Set @WMsgNumNotVinc = ' (NF.Vinc. '+cast(@WNumNotVnc as varchar)+')'

  end  -- if @PTipNota = 'S'


-- verifica se é operação triangular
if (IsNull(@WNumNotVnc,0) > 0) and
   ((IsNull(@WFlgOpeVdo,0) = 1) or (IsNull(@WFlgOpeVdoVnc,0) = 1))
  Set @WFlgOperacTriang = 1

if @WFlgOperacTriang = 0
  begin
    Set @PMsgAlerta = 'Não foi possível identificar uma Op.Triangular'+@WMsgNumNotVinc
    Return
  end

if @WFlgOperacTriang = 1
  begin
    if @WCodCfo = @WCodCfoVnc
      begin
        Set @PMsgErro = 'As 2 Notas da op.triangular com o mesmo CFOp'+@WMsgNumNotVinc
        Return
      end

    -- somente uma das NF movimenta estoque e gera crédito icms, não gera crédito pis/cofins
    -- somente uma das NF não movimenta estoque, não gera crédito icms, gera crédito pis/cofins
    if (@WFlgMovEst = 1) and (@WFlgMovEstVnc = 1)
      begin
        Set @PMsgErro = 'As 2 Notas da op.triangular movimentam estoque'+@WMsgNumNotVinc
        Return
      end

    if (@WFlgMovEst = 0) and (@WFlgMovEstVnc = 0)
      begin
        Set @PMsgErro = 'Nenhuma das notas da op.triangular movimenta estoque'+@WMsgNumNotVinc
        Return
      end

    if (@WFlgAtuCus = 1) and (@WFlgAtuCusVnc = 1)
      begin
        Set @PMsgErro = 'As 2 Notas da op.triangular atualizam custos'+@WMsgNumNotVinc
        Return
      end

    if (@WFlgAtuCus = 0) and (@WFlgAtuCusVnc = 0)
      begin
        Set @PMsgErro = 'Nenhuma das notas da op.triangular atualiza custo'+@WMsgNumNotVinc
        Return
      end

    if (@WVlrIcmsTri > 0) and (@WVlrIcmsTriVnc > 0)
      begin
        if @PTipNota = 'E'
          Set @PMsgErro = 'As 2 Notas da op.triangular creditam Icms'+@WMsgNumNotVinc
        else
          Set @PMsgErro = 'As 2 Notas da op.triangular debitam Icms'+@WMsgNumNotVinc
        Return
      end

    if (@WVlrPis > 0) and (@WVlrPisVnc > 0)
      begin
        if @PTipNota = 'E'
          Set @PMsgErro = 'As 2 Notas da op.triangular creditam Pis/Cofins'+@WMsgNumNotVinc
        else
          Set @PMsgErro = 'As 2 Notas da op.triangular debitam Pis/Cofins'+@WMsgNumNotVinc
        Return
      end


/*
    if ((@WVlrIcmsTri > 0) and (@WVlrPis > 0)) or
       ((@WVlrIcmsTriVnc > 0) and (@WVlrPisVnc > 0))
      Set @PMsgErro = 'Créditos Icms e Pis na mesma NF em op.triangular'

    if (@WFlgMovEst = 0) and (@WVlrIcmsTri > 0)
      Set @PMsgErro = 'NF sem movimentação de estoque não gera crédito de Icms em op.triangular'

    if (@WFlgMovEstVnc = 0) and (@WVlrIcmsTriVnc > 0)
      Set @PMsgErro = 'NF vinculada sem movimentação de estoque não gera crédito de Icms em op.triangular'

    if (@WFlgMovEst = 1) and (@WVlrPis > 0)
      Set @PMsgErro = 'NF com movimentação de estoque não gera crédito de Pis em op.triangular'

    if (@WFlgMovEstVnc = 1) and (@WVlrPisVnc > 0)
      Set @PMsgErro = 'NF vinculada com movimentação de estoque não gera crédito de Pis em op.triangular'
*/

    if (@WVlrIcmsTri = 0) and (@WVlrIcmsTriVnc = 0) and
       (@WVlrPis = 0) and (@WVlrPisVnc = 0)
      if @PTipNota = 'E'
        Set @PMsgAlerta = 'Nenhuma das notas da op.triangular creditam Icms/pis/cofins'+@WMsgNumNotVinc
      else
        Set @PMsgAlerta = 'Nenhuma das notas da op.triangular debitam Icms/pis/cofins'+@WMsgNumNotVinc

    if (@PMsgAlerta = '') and (@WVlrIcmsTri = 0) and (@WVlrIcmsTriVnc = 0)
      if @PTipNota = 'E'
        Set @PMsgAlerta = 'Nenhuma das notas da op.triangular creditam Icms'+@WMsgNumNotVinc
      else
        Set @PMsgAlerta = 'Nenhuma das notas da op.triangular debitam Icms'+@WMsgNumNotVinc

    if (@PMsgAlerta = '') and (@WVlrPis = 0) and (@WVlrPisVnc = 0)
      if @PTipNota = 'E'
        Set @PMsgAlerta = 'Nenhuma das notas da op.triangular creditam Pis/Cofins'+@WMsgNumNotVinc
      else
        Set @PMsgAlerta = 'Nenhuma das notas da op.triangular debitam Pis/Cofins'+@WMsgNumNotVinc


    if @PTipNota = 'E'
      begin
        -- todos os itens iguais
        if Exists(Select 1
                    From (Select Cod_Produto, Cod_LOte, QtdPed=sum(Qtd_Pedido)
                            From NFEIT
                           Where Cod_Estabe = @PCodEstabe
                             And Protocolo = @PNumNota
                           Group by Cod_Produto, Cod_Lote) x
                         FULL OUTER JOIN
                         (Select Cod_Produto, Cod_LOte, QtdPed=sum(Qtd_Pedido)
                            From NFEIT
                           Where Cod_Estabe = @PCodEstabe
                             And Protocolo = @WNumNotVnc
                           Group by Cod_Produto, Cod_Lote) y on x.Cod_Produto = y.Cod_Produto and x.Cod_Lote = y.Cod_LOte
                   Where IsNull(x.QtdPed,0) <> IsNull(y.QtdPed,0))
          begin
            Select @PMsgErro = 'Existe ao menos 1 produto/lote (' + 
                   Case
                     When x.Cod_Produto > 0 then cast(x.Cod_Produto as varchar)+'/'+x.Cod_Lote+')'
                     Else cast(y.Cod_Produto as varchar)+'/'+y.Cod_Lote+')'
                   End +
                   ' divergente entre as notas'+@WMsgNumNotVinc
              From (Select Cod_Produto, Cod_LOte, QtdPed=sum(Qtd_Pedido)
                      From NFEIT
                     Where Cod_Estabe = @PCodEstabe
                       And Protocolo = @PNumNota
                     Group by Cod_Produto, Cod_Lote) x
                   FULL OUTER JOIN
                   (Select Cod_Produto, Cod_Lote, QtdPed=sum(Qtd_Pedido)
                      From NFEIT
                     Where Cod_Estabe = @PCodEstabe
                       And Protocolo = @WNumNotVnc
                     Group by Cod_Produto, Cod_Lote) y on x.Cod_Produto = y.Cod_Produto and x.Cod_Lote = y.Cod_LOte
             Where IsNull(x.QtdPed,0) <> IsNull(y.QtdPed,0)
    
            if @WFlgAtuCus = 0
              begin
                Set @PMsgAlerta = @PMsgErro
                Set @PMsgErro = ''
              end
          end  -- if Exists(Select 
    
        -- verifica se nota vinculada está fechada
        if @WFlgAtuCus = 1
          begin
            if not Exists(Select 1
                            From NFECB
                           Where Cod_Estabe = @PCodEstabe
                             And Protocolo = @WNumNotVnc
                             And Status = 'F')
              Set @PMsgErro = 'NF vinculada não está fechada'+@WMsgNumNotVinc
          end
      end
    else
      -- NF saida
      begin
        -- todos os itens iguais
        if Exists(Select 1
                    From (Select Cod_Produto, Cod_Lote, QtdPed=sum(Qtd_Produto)
                            From NFSIT
                           Where Cod_Estabe = @PCodEstabe
                             and Ser_Nota = @PSerNota
                             and Num_Nota = @PNumNota
                           Group by Cod_Produto, Cod_Lote) x
                         FULL OUTER JOIN
                         (Select Cod_Produto, Cod_LOte, QtdPed=sum(Qtd_Produto)
                            From NFSIT
                           Where Cod_Estabe = @PCodEstabe
                             and Ser_Nota = @WSerNotVnc
                             And Num_Nota = @WNumNotVnc
                           Group by Cod_Produto, Cod_Lote) y on x.Cod_Produto = y.Cod_Produto and x.Cod_Lote = y.Cod_LOte
                   Where IsNull(x.QtdPed,0) <> IsNull(y.QtdPed,0))
          begin
            Select @PMsgErro = 'Existe ao menos 1 produto/lote (' + 
                   Case
                     When x.Cod_Produto > 0 then cast(x.Cod_Produto as varchar)+'/'+x.Cod_Lote+')'
                     Else cast(y.Cod_Produto as varchar)+'/'+y.Cod_Lote+')'
                   End +
                   ' divergente entre as notas'+@WMsgNumNotVinc
              From (Select Cod_Produto, Cod_Lote, QtdPed=sum(Qtd_Produto)
                      From NFSIT
                     Where Cod_Estabe = @PCodEstabe
                       and Ser_Nota = @PSerNota
                       and Num_Nota = @PNumNota
                     Group by Cod_Produto, Cod_Lote) x
                   FULL OUTER JOIN
                   (Select Cod_Produto, Cod_Lote, QtdPed=sum(Qtd_Produto)
                      From NFSIT
                     Where Cod_Estabe = @PCodEstabe
                       and Ser_Nota = @WSerNotVnc
                       and Num_Nota = @WNumNotVnc
                     Group by Cod_Produto, Cod_Lote) y on x.Cod_Produto = y.Cod_Produto and x.Cod_Lote = y.Cod_Lote
             Where IsNull(x.QtdPed,0) <> IsNull(y.QtdPed,0)
    
            if @WFlgAtuCus = 0
              begin
                Set @PMsgAlerta = @PMsgErro
                Set @PMsgErro = ''
              end
          end
    
        -- verifica se nota vinculada está fechada
        if @WFlgAtuCus = 1
          begin
            if not Exists(Select 1
                            From NFSCB
                           Where Cod_Estabe = @PCodEstabe
                             And Ser_Nota = @WSerNotVnc
                             And Num_Nota = @WNumNotVnc
                             And Status = 'F')
              Set @PMsgErro = 'NF vinculada não está fechada'+@WMsgNumNotVinc
          end
      end

  end  -- if @WFlgOperacTriang = 1
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_GeraPedidosDesconsolidados]
@PIdPdvCon int,
@PTipAtuPrc varchar(1)

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime

Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

if (Select Sta_PdvCon From PVCCB Where Id_PdvCon = @PIdPdvCon)  <> '3'
  RAISERROR('Nota de Entrada ref.pedido consolidado não foi gerada',16,1)
else
if not Exists(Select 1 From NFECB Where Id_Pdvcon = @PIdPdvCon And Status = 'F')
  RAISERROR('Nota de Entrada ref.pedido consolidado não localizada ou não foi fechada',16,1)
else
if (Select count(*) From PVCIT Where Id_PdvCon = @PIdPdvCon) = 0
  RAISERROR('Não Existem pedidos vinculados a este lote de pedidos',16,1)
else
begin

  Declare @CodEstabeDes int = 0,
          @CodOpeDes varchar(3) = ''

  -- identifica estabelecimento destino
  Select @CodEstabeDes = Cod_Estabe,
         @CodOpeDes = Cod_Ope 
    From NFECB
    Where Id_PdvCon = @PIdPdvCon
    And Status = 'F'

  -- verifica se algum pedido já foi gerado
  if Exists(Select 1
              From PVCIT it
	               Inner Join PDVCB pv on it.Cod_Estabe = @CodEstabeDes and it.Cod_Pedido = pv.Numero
              Where it.Id_PdvCon = @PIdPdvCon)
    RAISERROR('Não Existem pedidos vinculados a este lote de pedidos',16,1)
  else
    Begin Transaction

    Declare @FlgErr bit = 0,
            @MsgErr varchar(8000) = '',
            @CodEstabeOri int = 0,
            @NumPdv int = 0,
			@FlgWms bit = 0,
            @cr_CodPrd int = 0, 
            @cr_CodLot varchar(20) = '',
            @cr_QtdLot int = 0,
            @it_TipSai varchar(1),
            @it_QtdSld int,
            @FatParIte numeric(18,8),
            @FlgAchou bit = 0,
            @QtdMov int

    Set @FlgErr = 0
    Set @MsgErr = ''

    -- seleciona pedidos de origem
    Declare PDVCB_Cr Cursor Local Fast_Forward For 

      Select Cod_Estabe, Cod_Pedido 
        From PVCIT
        Where Id_PdvCon = @PIdPdvCon
      Order by Cod_Pedido

    Open PDVCB_Cr
    Fetch Next From PDVCB_Cr Into @CodEstabeOri, @NumPdv
    While @@FETCH_STATUS = 0
      begin
        -- WMS pedido origem
		if Exists(Select 1 From PDVLT Where Cod_Estabe = @CodEstabeOri and Cod_Pedido = @NumPdv)  
          Set @FlgWms = 1
        else
          Set @FlgWms = 0
         
		-- importa cabeçalho
        INSERT  INTO PDVCB (Cod_Estabe, Numero, Tip_Pedido, Status1, Status2, Bloqueio, Flg_JaFechado, Flg_Calc,Qtd_ImpPnt,
                            Cod_OrigemPdv, Cod_PedRem, Cod_PedCli, Flg_ComisNormal, Per_ComVnd, Flg_TabProgres, Flg_WMS,
                            Tip_Faturamento, Tip_Vencimento, Dat_Pedido, Cod_SerNfs, Cod_NumNfsIni,
                            Cod_NumNfsFim, Cod_Cliente, Cod_Funcionario, Num_Lote, Consumidor, Tip_Consumidor,
                            Qtd_PrzMed, Qtd_Parcela, Qtd_Intervalo, Flg_PrzProm, Flg_VlrFinanc,
                            Cod_VendTlmkt, Cod_Vendedor, Cod_MicroReg, 
							--Cod_Agente, Cod_Transportadora, Cod_Rota, Cod_RegTri, 
                            Qtd_Itens, Qtd_ItensProm, Vlr_BasDscCom,
                            Vlr_BasPar, Vlr_LiqItens, Vlr_RepIcms, Vlr_Despes, Vlr_SubsTrib, Vlr_SbtRes, Vlr_DscTri, Tip_DscPdv,
                            Per_DescontoCom, Per_DescontoFin, C_VlrDesconto, C_VlrPedido, Observacao,
					        Qtd_Volumes, Qtd_Peso, Hor_Entrada, Hor_Prenota, Hor_Fatura, Hor_Saida,
                            Cod_FunSeparador, Cod_FunConferidor, Cod_FunEmbalador, Flg_Credito, Msg_Bloqueio,
                            Msg_NF, Nom_UsuDesbloq, Msg_JustDesbloq, Cod_Propos, Per_SubFat, Usuario, Transacao,
                            Per_DsdOrc,Cod_Prz,Hor_ConferIni,Hor_ConferFim,Cod_Digitador,Cod_GrpCli,
                            Per_DscPrz, Per_DscVis, Qtd_Prz, Cod_TabPrc, Num_Referencia, 
                            Obs_NotFis, Cod_TipPrp, Obs_IntCtaRec, Num_CotPdv, Per_Rnt, Cod_BlqRnt,
                            Nom_UsuDesbloqRnt, Cod_BlqLic, Nom_UsuDesbloqLic, Des_LayoutPalm, Num_ConReg,
                            Est_ConReg, Ide_NotEmp, Per_ComOpe, Qtd_PesBru, Dat_LimEnvPrp, Hor_Fechamento,
                            Hor_Liberacao, Hor_DbqFin, Hor_DbqLic, Hor_DbqRnt, Hor_ImpEtq, Vlr_Frete,
                            Cod_PolCom, Id_PolCom, Vlr_Verba, Ide_Contra, Cod_Contrato, Num_SequenciaCtr,
                            Flg_GerCtrFal, Flg_CriIteFec, Nom_UsuCancel, Msg_JustCancel, Vlr_FrePrv, Per_FrePrv,
                            Num_PdvLig, Cod_MtvRej, Des_MtvRej, Flg_GerPdvBon, Flg_GerRetBon, Des_LayoutPde,
                            Des_Convenio, UF_PlaVei, Cod_PlaVei, Flg_PriFat, Cod_PrjPde, Cod_PedCmpCli, 
                            Tip_RatBon, Flg_UsaPbm, Tip_SaiPdv, Flg_MarkupCusCom, Vlr_DscBon, Ide_NumPregao, 
							Cod_LayoutPde, Per_MarBru ) 

                     Select @CodEstabeDes, cb.Numero, cb.Tip_Pedido, 'P', 'A', cb.Bloqueio, cb.Flg_JaFechado, cb.Flg_Calc, cb.Qtd_ImpPnt,
                            cb.Cod_OrigemPdv, cb.Cod_PedRem, cb.Cod_PedCli, cb.Flg_ComisNormal, cb.Per_ComVnd, cb.Flg_TabProgres, 0,
                            cb.Tip_Faturamento, cb.Tip_Vencimento, cb.Dat_Pedido, cb.Cod_SerNfs, cb.Cod_NumNfsIni,
                            cb.Cod_NumNfsFim, cb.Cod_Cliente, cb.Cod_Funcionario, cb.Num_Lote, cb.Consumidor, cb.Tip_Consumidor,
                            cb.Qtd_PrzMed, cb.Qtd_Parcela, cb.Qtd_Intervalo, cb.Flg_PrzProm, cb.Flg_VlrFinanc,
                            cb.Cod_VendTlmkt, cb.Cod_Vendedor, cb.Cod_MicroReg, 
							--0, 0, 0, 0,
							cb.Qtd_Itens, cb.Qtd_ItensProm, cb.Vlr_BasDscCom,
                            cb.Vlr_BasPar, cb.Vlr_LiqItens, cb.Vlr_RepIcms, cb.Vlr_Despes, cb.Vlr_SubsTrib, cb.Vlr_SbtRes, cb.Vlr_DscTri, cb.Tip_DscPdv,
                            cb.Per_DescontoCom, cb.Per_DescontoFin, cb.C_VlrDesconto, cb.C_VlrPedido, cb.Observacao,
					        cb.Qtd_Volumes, cb.Qtd_Peso, cb.Hor_Entrada, cb.Hor_Prenota, cb.Hor_Fatura, cb.Hor_Saida,
                            cb.Cod_FunSeparador, cb.Cod_FunConferidor, cb.Cod_FunEmbalador, cb.Flg_Credito, cb.Msg_Bloqueio,
                            cb.Msg_NF, cb.Nom_UsuDesbloq, cb.Msg_JustDesbloq, cb.Cod_Propos, cb.Per_SubFat, cb.Usuario, cb.Transacao,
                            cb.Per_DsdOrc, cb.Cod_Prz, cb.Hor_ConferIni, cb.Hor_ConferFim, cb.Cod_Digitador, cb.Cod_GrpCli,
                            cb.Per_DscPrz, cb.Per_DscVis, cb.Qtd_Prz, cb.Cod_TabPrc, cb.Num_Referencia, 
                            cb.Obs_NotFis, cb.Cod_TipPrp, cb.Obs_IntCtaRec, cb.Num_CotPdv, cb.Per_Rnt, cb.Cod_BlqRnt,
                            cb.Nom_UsuDesbloqRnt, cb.Cod_BlqLic, cb.Nom_UsuDesbloqLic, cb.Des_LayoutPalm, cb.Num_ConReg,
                            cb.Est_ConReg, cb.Ide_NotEmp, cb.Per_ComOpe, cb.Qtd_PesBru, cb.Dat_LimEnvPrp, cb.Hor_Fechamento,
                            cb.Hor_Liberacao, cb.Hor_DbqFin, cb.Hor_DbqLic, cb.Hor_DbqRnt, cb.Hor_ImpEtq, cb.Vlr_Frete,
                            cb.Cod_PolCom, cb.Id_PolCom, cb.Vlr_Verba, cb.Ide_Contra, cb.Cod_Contrato, cb.Num_SequenciaCtr,
                            cb.Flg_GerCtrFal, cb.Flg_CriIteFec, cb.Nom_UsuCancel, cb.Msg_JustCancel, cb.Vlr_FrePrv, cb.Per_FrePrv,
                            cb.Num_PdvLig, cb.Cod_MtvRej, cb.Des_MtvRej, cb.Flg_GerPdvBon, cb.Flg_GerRetBon, cb.Des_LayoutPde,
                            cb.Des_Convenio, cb.UF_PlaVei, cb.Cod_PlaVei, cb.Flg_PriFat, cb.Cod_PrjPde, cb.Cod_PedCmpCli, 
                            cb.Tip_RatBon, cb.Flg_UsaPbm, cb.Tip_SaiPdv, cb.Flg_MarkupCusCom, cb.Vlr_DscBon, cb.Ide_NumPregao, 
							cb.Cod_LayoutPde, cb.Per_MarBru
                     From PDVCB cb
		             Where cb.Cod_Estabe = @CodEstabeOri
                     And cb.Numero = @NumPdv

		Update cb
          Set cb.Status1 = 'P',
              cb.Status2 = 'A',
		      cb.Flg_GerArqNf = 0,
              cb.Flg_JaFechado = 0, 
			  cb.Flg_Calc = 0,
			  cb.Qtd_ImpPnt = 0,
              cb.Cod_Agente = Case When IsNull(op.Cod_AgeCob,0) > 0 then op.Cod_AgeCob Else IsNull(es.Cod_AgeCob,0) End, 
              cb.Cod_Transportadora = IsNull(es.Cod_Transp,0),
              cb.Cod_Rota = IsNull(es.Cod_Rota,0),
              cb.Cod_RegTri = IsNull(es.Cod_RegTri,0)
          From PDVCB cb
               Left Join TPOPE op on cb.Tip_Faturamento = op.Cod_Ope
               Left Join CLIEN cl on cl.Codigo = cb.Cod_Cliente                         
               Left Join ENXES es on es.Cod_Estabe = cb.Cod_Estabe and es.Num_CgcCpf = cl.Cgc_Cpf
		  Where cb.Cod_Estabe = @CodEstabeDes
          And cb.Numero = @NumPdv

		-- importa itens
        INSERT INTO PDVIT (Cod_Estabe, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai, 
                           Qtd_Acerto, Qtd_Pendente, Qtd_Solicitado, 
						   Qtd_Pedido, Qtd_Bonificacao, Qtd_Pra, Qtd_Dep,
						   Vlr_BasVerba, Vlr_Verba, Vlr_Bonificacao, Vlr_Despes, Vlr_DscTri)  
          Select @CodEstabeDes, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai, 
                 Qtd_Acerto, Qtd_Pendente, Qtd_Solicitado, 
                 Qtd_Pedido, Qtd_Bonificacao, Qtd_Pra, Qtd_Dep,  
                 Vlr_BasVerba, Vlr_Verba, Vlr_Bonificacao, Vlr_Despes, Vlr_DscTri
            From PDVIT 
		    Where Cod_Estabe = @CodEstabeOri
            And Cod_Pedido = @NumPdv
			And @FlgWms = 0

        if @FlgWms = 1
          begin
            -- cria arq. de lotes e pedidos
            IF OBJECT_ID('tempdb..#ARQ_PDVLT') IS NOT NULL
              DROP TABLE #ARQ_PDVLT
  
            CREATE TABLE #ARQ_PDVLT
            (
                Cod_Produto int,
                Cod_Lote varchar(20),
			    Tip_Sai varchar(1),
                Qtd_Ace int, 
                Qtd_Pen int, 
                Qtd_Ped int,
                Qtd_Bon int,
                Qtd_Sol int,
                Qtd_Pra int,
                Qtd_Dep int,
                Vlr_BasVrb numeric(18,4), 
                Vlr_Vrb numeric(18,4), 
                Vlr_Bon numeric(18,4), 
                Vlr_Dsp numeric(18,4), 
                Vlr_DscTri numeric(18,4) 
            ) 

            Insert Into #ARQ_PDVLT (Cod_Produto, Cod_Lote, Tip_Sai) 
              Select x.Cod_Produt, x.Cod_Lote, x.TipSai
                From (Select distinct lt.Cod_Produt, lt.Cod_Lote, TipSai=IsNull(it.Tip_Sai,'')
                        From PDVLT lt inner Join
                             (Select distinct Cod_Produto, Tip_Sai
                                From PDVIT 
                                Where Cod_Estabe = @CodEstabeOri
                                And Cod_Pedido = @NumPdv
                                And Qtd_Pedido+Qtd_Bonificacao > 0) it on lt.Cod_Produt = it.Cod_Produto
                        Where lt.Cod_Estabe = @CodEstabeOri
                        And lt.Cod_Pedido = @NumPdv
                        And lt.Qtd_Lote > 0) x

            Update #ARQ_PDVLT
              Set Qtd_Ace = 0, 
                  Qtd_Pen = 0, 
                  Qtd_Ped = 0, 
                  Qtd_Bon = 0, 
                  Qtd_Sol = 0, 
                  Qtd_Pra = 0, 
                  Qtd_Dep = 0,
                  Vlr_BasVrb = 0, 
                  Vlr_Vrb = 0, 
                  Vlr_Bon = 0, 
                  Vlr_Dsp = 0, 
                  Vlr_DscTri = 0

            -- criar tabela itens de PDVIT e povoa
            IF OBJECT_ID('tempdb..#ARQ_PDVIT') IS NOT NULL
              DROP TABLE #ARQ_PDVIT

            CREATE TABLE #ARQ_PDVIT
            (
                Cod_Produto int,
			    Tip_Sai varchar(1),
                Qtd_Ace int, 
                Qtd_Pen int, 
                Qtd_Ped int,
                Qtd_Bon int,
				Qtd_Sld int,
                Qtd_Sol int,
                Qtd_Pra int,
                Qtd_Dep int,
                Vlr_BasVrb numeric(18,4), 
                Vlr_Vrb numeric(18,4), 
                Vlr_Bon numeric(18,4), 
                Vlr_Dsp numeric(18,4), 
                Vlr_DscTri numeric(18,4) 
            ) 

            Insert Into #ARQ_PDVIT (Cod_Produto, Tip_Sai, Qtd_Ace, Qtd_Pen, 
			                        Qtd_Ped, Qtd_Bon, Qtd_Sld, Qtd_Sol, Qtd_Pra, Qtd_Dep,
                                    Vlr_BasVrb, Vlr_Vrb, Vlr_Bon, Vlr_Dsp, Vlr_DscTri)
               Select Cod_Produto, Tip_Sai, QtdAce = sum(IsNull(Qtd_Acerto,0)), QtdPen = sum(IsNull(Qtd_Pendente,0)), 
                      QtdPed = sum(IsNull(Qtd_Pedido,0)), QtdBon = sum(IsNull(Qtd_Bonificacao,0)), sum(IsNull(Qtd_Pedido,0))+sum(IsNull(Qtd_Bonificacao,0)),
					  QtdSol = sum(IsNull(Qtd_Solicitado,0)), QtdPra = sum(IsNull(Qtd_Pra,0)), QtdDep = sum(IsNull(Qtd_Dep,0)), 
                      VlrBasVrb = sum(IsNull(Vlr_BasVerba,0)), VlrVrb = sum(IsNull(Vlr_Verba,0)), 
                      VlrBon = sum(IsNull(Vlr_Bonificacao,0)), VlrDsp = sum(IsNull(Vlr_Despes,0)), VlrDscTri = sum(IsNull(Vlr_DscTri,0))      
                 From PDVIT 
                 Where Cod_Estabe = @CodEstabeOri
                 And Cod_Pedido = @NumPdv
                 And IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0) > 0
                 Group by Cod_Produto, Tip_Sai
                 Order by Cod_Produto, Tip_Sai, sum(Qtd_Pedido+Qtd_Bonificacao) 

            -- gera qrquivo de itens/lotes
            Declare PDVLT_Cr Cursor Local Fast_Forward For

              Select Cod_Produt, Cod_Lote, QtdLot = sum(Qtd_Lote) 
                From PDVLT 
                Where Cod_Estabe = @CodEstabeOri
                And Cod_Pedido = @NumPdv
                Group by Cod_Produt, Cod_Lote 
				Order by Cod_Produt, sum(Qtd_Lote) desc, Cod_Lote

            Open PDVLT_Cr
            Fetch Next From PDVLT_Cr Into @cr_CodPrd, @cr_CodLot, @cr_QtdLot
            While @@FETCH_STATUS = 0
              begin
			    Set @FlgAchou = 1
                while (@cr_QtdLot > 0) and (@FlgAchou = 1)			   
				  begin
                    if Exists(Select 1 From #ARQ_PDVIT Where Cod_Produto = @cr_CodPrd And Qtd_Sld > 0)
                      begin
                        Set @FlgAchou = 1

                        Select top 1 @it_TipSai = Tip_Sai, 
                                     @it_QtdSld = Qtd_Sld
		    			  From #ARQ_PDVIT 
					      Where Cod_Produto = @cr_CodPrd 
					      And Qtd_Sld > 0 
					      Order by Qtd_Bon desc, Qtd_Sld desc

                        if @it_QtdSld > @cr_QtdLot
						  Set @QtdMov = @cr_QtdLot
                        else
						  Set @QtdMov = @it_QtdSld

                        Set @FatParIte = @QtdMov*1.0/@it_QtdSld 

                        -- proporcional:
                        Update lt 
                          Set lt.Qtd_Ace = Round(@FatParIte*it.Qtd_Ace,0),
		     				  lt.Qtd_Pen = Round(@FatParIte*it.Qtd_Pen,0),  
                              lt.Qtd_Bon = Round(@FatParIte*it.Qtd_Bon,0), 
                              lt.Qtd_Ped = @QtdMov-Round(@FatParIte*it.Qtd_Bon,0), 
                              lt.Qtd_Sol = Round(@FatParIte*it.Qtd_Sol,0), 
                              lt.Qtd_Pra = Round(@FatParIte*it.Qtd_Pra,0), 
                              lt.Qtd_Dep = @QtdMov-Round(@FatParIte*it.Qtd_Pra,0),

                              lt.Vlr_BasVrb = Round(@FatParIte*it.Vlr_BasVrb,2), 
                              lt.Vlr_Vrb = @FatParIte*it.Vlr_Vrb, 
                              lt.Vlr_Bon = @FatParIte*it.Vlr_Bon, 
                              lt.Vlr_Dsp = @FatParIte*it.Vlr_Dsp, 
                              lt.Vlr_DscTri = @FatParIte*it.Vlr_DscTri
                          From #ARQ_PDVLT lt, #ARQ_PDVIT it
                          Where lt.Cod_Produto = @cr_CodPrd 
                          And lt.Cod_Lote = @cr_CodLot
                          And lt.Tip_Sai = @it_TipSai
					      And lt.Cod_Produto = it.Cod_Produto
                          And lt.Tip_Sai = it.Tip_Sai

                        -- acumula
                        Set @cr_QtdLot = @cr_QtdLot - @QtdMov
						Update #ARQ_PDVIT 
                          Set Qtd_Sld = Qtd_Sld - @QtdMov
					      Where Cod_Produto = @cr_CodPrd 
						  And Tip_Sai = @it_TipSai
					   end
                     else
                       Set @FlgAchou = 0

				  end  -- while (@cr_QtdLot > 0) and (@FlgAchou = 1)

                Fetch Next From PDVLT_Cr Into @cr_CodPrd, @cr_CodLot, @cr_QtdLot
              end
            Close PDVLT_Cr
            Deallocate PDVLT_Cr

            -- importa itens
            INSERT INTO PDVIT (Cod_Estabe, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai, 
                               Qtd_Pedido, Qtd_Bonificacao, Qtd_Pra, Qtd_Dep,
                               Qtd_Acerto, Qtd_Pendente, Qtd_Solicitado, 
                               Vlr_BasVerba, Vlr_Verba, Vlr_Bonificacao, Vlr_Despes, Vlr_DscTri) 
              Select @CodEstabeDes, @NumPdv, Cod_Produto, Cod_Lote, Tip_Sai, 
                     IsNull(Qtd_Ped,0), IsNull(Qtd_Bon,0), IsNull(Qtd_Pra,0), IsNull(Qtd_Dep,0),
			         IsNull(Qtd_Ace,0), IsNull(Qtd_Pen,0), IsNull(Qtd_Sol,0),
					 Vlr_BasVrb, Vlr_Vrb, Vlr_Bon, Vlr_Dsp, Vlr_DscTri
                From #ARQ_PDVLT 


            IF OBJECT_ID('tempdb..#ARQ_PDVIT') IS NOT NULL
              DROP TABLE #ARQ_PDVIT
            IF OBJECT_ID('tempdb..#ARQ_PDVLT') IS NOT NULL
              DROP TABLE #ARQ_PDVLT

          end  -- if @FlgWms = 1

        UPDATE d
          Set d.Cod_Fabricante = o.Cod_Fabricante, 
		      d.Loc_Fisica = o.Loc_Fisica,
		      d.Flg_PrcUniDsc = o.Flg_PrcUniDsc, 
		      d.Prc_Unitario = o.Prc_Unitario, 
		      d.Per_Desconto = o.Per_Desconto, 
   		      d.Per_Descon = o.Per_Descon, 
		      d.Per_DscVis = o.Per_DscVis, 
		      d.Qtd_PrzMax = o.Qtd_PrzMax, 
		      d.Tip_Aux = o.Tip_Aux, 
		      d.Ctrl_Tributacao = o.Ctrl_Tributacao, 
		      d.Cod_ClaTri = o.Cod_ClaTri, 
		      d.Desconto = o.Desconto, 
		      d.Flg_BlqInfPar = o.Flg_BlqInfPar, 

		      d.Prc_TabBru = o.Prc_TabBru, 
   		      d.Prc_Tabela = o.Prc_Tabela, 
		      d.Prc_MaxCon = o.Prc_MaxCon, 
		      d.Prc_Fabric = o.Prc_Fabric, 
		      d.Prc_RefFpb = o.Prc_RefFpb, 
		      d.Prc_UniLiqPer = o.Prc_UniLiqPer, 
		      d.Prc_LiqUltEnt = o.Prc_LiqUltEnt, 

		      d.Num_SeqDig = o.Num_SeqDig, 
   		      d.Des_Und = o.Des_Und, 
   		      d.Qtd_AprPdv = o.Qtd_AprPdv, 
		      d.Des_UndVen = o.Des_UndVen, 
		      d.Flg_Entreg = o.Flg_Entreg, 
		      
              d.Fat_CnvImpFat = o.Fat_CnvImpFat,
		      d.Qtd_ImpFat = (d.Qtd_Pedido+d.Qtd_Bonificacao)/o.Fat_CnvImpFat,
		      d.Nom_UsuDesbloq = o.Nom_UsuDesbloq, 
		      d.Des_UnvImpFat = o.Des_UnvImpFat,
		      d.Des_AprImpFat = o.Des_AprImpFat, 
		      d.Flg_VctLic = o.Flg_VctLic, 
		      d.Per_Rnt = o.Per_Rnt, 
		      d.Prc_BasRnt = o.Prc_BasRnt, 
		      d.Id_PolCom = o.Id_PolCom, 
		      d.Prc_PolCom = o.Prc_PolCom, 
		      d.Per_DscPolCom = o.Per_DscPolCom, 
		      d.Per_DscVisPolCom = o.Per_DscVisPolCom, 
		      d.Qtd_PrzPolCom = o.Qtd_PrzPolCom, 
		      d.Flg_PolPrm = o.Flg_PolPrm, 
		      d.Flg_Verba = o.Flg_Verba, 
		      d.Des_MsgDesbloq = o.Des_MsgDesbloq, 
		      d.Cod_MtvRej = o.Cod_MtvRej, 
		      d.Des_MtvRej = o.Des_MtvRej, 
		      d.Prc_UniPde = o.Prc_UniPde, 
		      d.Per_DscPde = o.Per_DscPde, 
		      d.Cod_PrjPde = o.Cod_PrjPde, 
		      d.Num_SeqPdc = o.Num_SeqPdc, 
		      d.Num_IteCot = o.Num_IteCot, 
			  d.Prc_CusMinComMarkup = o.Prc_CusMinComMarkup,
		      d.Per_MarkupCusCom = o.Per_MarkupCusCom, 
--		      d.Prc_UniImpFat = o.Prc_UniImpFat, 
--		      d.C_PrcUni = o.C_PrcUni, 
--		      d.C_PerDscIte = o.C_PerDscIte, 
--		      d.Alq_Icms = o.Alq_Icms,
		      d.Cod_KitPrm = o.Cod_KitPrm,
			  d.Per_MarBru = o.Per_MarBru 

          From PDVIT d, PDVIT o
          Where o.Cod_Estabe = @CodEstabeOri
          And d.Cod_Estabe = @CodEstabeDes
		  And o.Cod_Pedido = @NumPdv
          And o.Cod_Pedido = d.Cod_Pedido
		  And o.Cod_Produto = d.Cod_Produto
		  And o.Tip_Sai = d.Tip_Sai

		-- importa pedido eletronico
        if Exists(Select 1 From PDECB Where Cod_Estabe = @CodEstabeOri And Num_PedVen = @NumPdv) and
		   (not Exists(Select 1 From PDECB Where Cod_Estabe = @CodEstabeDes And Num_PedVen = @NumPdv))
          begin
		    -- cabeçalho
            INSERT  INTO PDECB (Cod_Estabe, Num_Cnpj, Cod_PedCli, Num_Desdob, Dat_LeiPed, Num_PedVen, Sta_Pedido, Layout, 
                                Nom_ArqPed, Num_PdConv, Vlr_Total, EAN_Comprador, EAN_LocEntrega, EAN_Fornecedor, 
                                EAN_LocFatura, Id_PolCom, Dat_Validade, Des_Motivo, Dat_Inicio, Qtd_Itens, 
                                Tip_Vencimento, Vlr_TotalDscVis, Vlr_TotalDscPrz, Cod_Layout, Cod_GrpClp, 
                                Cod_MtvRej, Des_MtvRej, Qtd_PrzMed, Qtd_Parcela, Per_DscCom, Per_DscFin, Cod_TabPrz, 
                                Cod_Client, Time_ArqPed, Cod_Projeto, Observacao, Dat_PedArq, Cod_PedCmpCli, Obs_NotFis, Num_CnpjEmpArq,
								Cod_PrzArq, Cod_OriPed, Ver_Layout, Num_CnpjGerPed, Cod_CtrPrj, Tip_Pedido, Tip_Fatura) 
                         Select @CodEstabeDes, Num_Cnpj, Cod_PedCli, Num_Desdob, Dat_LeiPed, Num_PedVen, Sta_Pedido, Layout, 
                                Nom_ArqPed, Num_PdConv, Vlr_Total, EAN_Comprador, EAN_LocEntrega, EAN_Fornecedor, 
                                EAN_LocFatura, Id_PolCom, Dat_Validade, Des_Motivo, Dat_Inicio, Qtd_Itens, 
                                Tip_Vencimento, Vlr_TotalDscVis, Vlr_TotalDscPrz, Cod_Layout, Cod_GrpClp, 
                                Cod_MtvRej, Des_MtvRej, Qtd_PrzMed, Qtd_Parcela, Per_DscCom, Per_DscFin, Cod_TabPrz, 
                                Cod_Client, Time_ArqPed, Cod_Projeto, Observacao, Dat_PedArq, Cod_PedCmpCli, Obs_NotFis, Num_CnpjEmpArq,
								Cod_PrzArq, Cod_OriPed, Ver_Layout, Num_CnpjGerPed, Cod_CtrPrj, Tip_Pedido, Tip_Fatura

                           From PDECB
                           Where Cod_Estabe = @CodEstabeOri 
                           And Num_PedVen = @NumPdv
 
 		    -- itens
            INSERT INTO PDEIT (Cod_Estabe, Num_Cnpj, Cod_PedCli, Num_Desdob, Cod_PrdCli, Tip_CodPrd, Cod_Produt, 
                               Qtd_Pedido, Qtd_Atendi, Und_Venda, Qtd_Embala, Prc_Unitario, Per_Desconto, Id_PolCom, 
                               Per_DscVis, Qtd_PrzMax, Per_DscAut, C_VlrPrcDsc, Per_Descon, Cod_MtvRej, Des_MtvRej, 
                               Cod_Projeto, Cod_PrdRef, Cod_Layout, Num_SeqPdc, Num_IteCot, Cod_PrdEmbFec, Qtd_PedEmbFec,
							   Qtd_AteEmbFec, Flg_QtdPedTotEmbFec, Tip_Sai, Per_DscExt, Cod_Convenio, Fat_CnvImpFat, Prc_UniImpFat,
							   Fat_AprPad, Des_UnvImpFat, Des_AprImpFat, Per_DscEmbPrc, Cod_MtvRejOri, Cod_PrdLayout, Cod_TipEmb, Cod_TipDsc) 
                        Select @CodEstabeDes, it.Num_Cnpj, it.Cod_PedCli, it.Num_Desdob, it.Cod_PrdCli, it.Tip_CodPrd, it.Cod_Produt, 
                               it.Qtd_Pedido, it.Qtd_Atendi, it.Und_Venda, it.Qtd_Embala, it.Prc_Unitario, it.Per_Desconto, it.Id_PolCom, 
                               it.Per_DscVis, it.Qtd_PrzMax, it.Per_DscAut, it.C_VlrPrcDsc, it.Per_Descon, it.Cod_MtvRej, it.Des_MtvRej, 
                               it.Cod_Projeto, it.Cod_PrdRef, it.Cod_Layout, it.Num_SeqPdc, it.Num_IteCot, it.Cod_PrdEmbFec, it.Qtd_PedEmbFec,
							   it.Qtd_AteEmbFec, it.Flg_QtdPedTotEmbFec, it.Tip_Sai, it.Per_DscExt, it.Cod_Convenio, it.Fat_CnvImpFat, it.Prc_UniImpFat,
							   it.Fat_AprPad, it.Des_UnvImpFat, it.Des_AprImpFat, it.Per_DscEmbPrc, it.Cod_MtvRejOri, it.Cod_PrdLayout, it.Cod_TipEmb, it.Cod_TipDsc

                           From PDEIT it 
						        Inner Join PDECB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Num_Cnpj = cb.Num_Cnpj and 
								                       it.Cod_PedCli = cb.Cod_PedCli and it.Num_Desdob = cb.Num_Desdob
                           Where cb.Cod_Estabe = @CodEstabeOri 
                           And cb.Num_PedVen = @NumPdv

          end

		-- AtualizaPreco(PCodEstabe,WNumPdvImp,WTipAtu)
	    -- 'A': Altera todos os preços (Pr.Cadastro-Desc.Autom)
		Declare @pm_Cod_UF varchar(2),
                @pm_Tip_EmiDes varchar (1),
                @pm_Cod_EmiDes int

        if not Exists(Select pm.Tip_AtuPrc 
		                From PMTRF pm 
						     Inner Join ESTAB es on pm.Cod_EstabeEmiDes = es.Cod_Estabe
                             Left Join CLIEN cl on es.Num_Cnpj = cl.Cgc_Cpf
                             Left Join FORNE fo on es.Num_Cnpj = fo.Cgc_Cpf
                             Left Join TRANS tr on es.Num_Cnpj = tr.Cgc_Cpf
                        Where pm.Cod_Estabe = @CodEstabeDes 
						And pm.Cod_UF = es.Des_Estado 
						And pm.Tip_EntSai = 'E' 
                        And ((IsNull(fo.Codigo,0) > 0) or (IsNull(cl.Codigo,0) > 0) or (IsNull(tr.Codigo,0) > 0)))

          Insert Into PMTRF(Cod_Estabe, Cod_UF, Tip_EntSai, Cod_EstabeEmiDes, Tip_AtuPrc, Cod_TipOpe, Tip_EmiDes, Cod_EmiDes)
            Select @CodEstabeDes, es.Des_Estado, 'E', es.Cod_Estabe, 'A', @CodOpeDes,
			       Tip_EmiDes = Case
				                  When IsNull(fo.Codigo,0) > 0 then 'F'
				                  When IsNull(cl.Codigo,0) > 0 then 'C'
				                  When IsNull(tr.Codigo,0) > 0 then 'T'
                                  Else 'X' 
                                End,
			       Cod_EmiDes = Case
				                  When IsNull(fo.Codigo,0) > 0 then fo.Codigo
				                  When IsNull(cl.Codigo,0) > 0 then cl.Codigo
				                  When IsNull(tr.Codigo,0) > 0 then tr.Codigo
                                  Else 0
                                End
			  From ESTAB es
                   Left Join FORNE fo on es.Num_Cnpj = fo.Cgc_Cpf
                   Left Join CLIEN cl on es.Num_Cnpj = cl.Cgc_Cpf
                   Left Join TRANS tr on es.Num_Cnpj = tr.Cgc_Cpf
              Where es.Cod_Estabe = @CodEstabeOri

          -- guarda nammória campos de entrada
          Select @pm_Cod_UF = pm.Cod_UF,
                 @pm_Tip_EmiDes = pm.Tip_EmiDes,
                 @pm_Cod_EmiDes = pm.Cod_EmiDes
          From PMTRF pm 
               Inner Join ESTAB es on pm.Cod_EstabeEmiDes = es.Cod_Estabe
               Left Join CLIEN cl on es.Num_Cnpj = cl.Cgc_Cpf
               Left Join FORNE fo on es.Num_Cnpj = fo.Cgc_Cpf
               Left Join TRANS tr on es.Num_Cnpj = tr.Cgc_Cpf
          Where pm.Cod_Estabe = @CodEstabeDes 
          And pm.Cod_UF = es.Des_Estado 
          And pm.Tip_EntSai = 'E' 
          And ((IsNull(fo.Codigo,0) > 0) or (IsNull(cl.Codigo,0) > 0) or (IsNull(tr.Codigo,0) > 0))


        Select @PTipAtuPrc = IsNull(pm.Tip_AtuPrc,'')
          From PMTRF pm
          Where pm.Cod_Estabe = @CodEstabeDes
		  And pm.Cod_UF = @pm_Cod_UF
		  And pm.Tip_EntSai = 'E'
          And pm.Tip_EmiDes = @pm_Tip_EmiDes
          And pm.Cod_EmiDes = @pm_Cod_EmiDes

		if @PTipAtuPrc = '' Set @PTipAtuPrc = 'A'

        -- atualiza parâmetro
		Update pm
          Set pm.Tip_AtuPrc = @PTipAtuPrc
          From PMTRF pm
          Where pm.Cod_Estabe = @CodEstabeDes
		  And pm.Cod_UF = @pm_Cod_UF
		  And pm.Tip_EntSai = 'E'
          And pm.Tip_EmiDes = @pm_Tip_EmiDes
          And pm.Cod_EmiDes = @pm_Cod_EmiDes
          And pm.Tip_AtuPrc <> @PTipAtuPrc

		Exec PR_AtualizaPrecoPDVIT @CodEstabeDes, @NumPdv, @PTipAtuPrc
		if @@ERROR <> 0
		  begin
		    Rollback Transaction
			Return
		  end

		-- DmdDm.FecAutPdv(@CodEstabeDes,@NumPdv)
        Exec PR_FecAutPDV @CodEstabeDes, @NumPdv, @MsgErr output
		if @@ERROR <> 0
		  begin
		    Rollback Transaction
			Return
		  end

		-- Repoe Desbloqueios
        Update pd
          Set pd.Bloqueio = po.Bloqueio, 
              pd.Nom_UsuDesbloq = po.Nom_UsuDesbloq, 
              pd.Msg_JustDesbloq = po.Msg_JustDesbloq, 
              pd.Cod_BlqRnt = po.Cod_BlqRnt, 
              pd.Nom_UsuDesbloqRnt = po.Nom_UsuDesbloqRnt, 
              pd.Cod_BlqLic = po.Cod_BlqLic, 
              pd.Nom_UsuDesbloqLic = po.Nom_UsuDesbloqLic 
          From PDVCB pd, PVCIT po
          Where pd.Cod_Estabe = @CodEstabeDes 
          And pd.Numero = @NumPdv 
          And po.Id_PdvCon = @PIdPdvCon
          And po.Cod_Pedido = @NumPdv 

        Insert Into CLIOC (Cod_Client, Cod_Estabe, Transacao, Flg_LanAut, Des_Ocorre, Usuario) 
                    Select pd.Cod_Cliente, pd.Cod_Estabe, GETDATE(), 1,
					       DesOco = Case   
                                      When IsNull(po.Nom_UsuDesbloq,'')    <> '' then 'LIBERACAO DO PEDIDO (FINANCEIRO) '
                                      When IsNull(po.Nom_UsuDesbloqRnt,'') <> '' then 'LIBERACAO DO PEDIDO (RENTABILIDADE) '
                                      When IsNull(po.Nom_UsuDesbloqLic,'') <> '' then 'LIBERACAO DO PEDIDO (DOCUMENTO) '
                                      Else ''
                                    End, 
					       NomUsu = Case   
                                      When IsNull(po.Nom_UsuDesbloq,'')    <> '' then IsNull(po.Nom_UsuDesbloq,'')
                                      When IsNull(po.Nom_UsuDesbloqRnt,'') <> '' then IsNull(po.Nom_UsuDesbloqRnt,'')
                                      When IsNull(po.Nom_UsuDesbloqLic,'') <> '' then IsNull(po.Nom_UsuDesbloqLic,'')
                                      Else ''
                                    End
                      From PDVCB pd, PDVCB po
                      Where pd.Cod_Estabe = @CodEstabeDes
                      And pd.Numero = @NumPdv 
                      And po.Cod_Estabe = @CodEstabeOri
                      And po.Numero = @NumPdv 
                      And ((IsNull(po.Nom_UsuDesbloq,'') <> '') or 
					       (IsNull(po.Nom_UsuDesbloqRnt,'') <> '') or 
						   (IsNull(po.Nom_UsuDesbloqLic,'') <> ''))

        Fetch Next From PDVCB_Cr Into @CodEstabeOri, @NumPdv
      end
    Close PDVCB_Cr
    Deallocate PDVCB_Cr

    -- verica pedidos originais x pedidos gerados
    if (Select count(*)
         From (Select it.Cod_Pedido, Cod_Produto, Qtd=sum(it.Qtd_Pedido+it.Qtd_Bonificacao)
                 From PDVIT it
                 Where it.Cod_Estabe = @CodEstabeOri
                 And Exists(Select 1 From PVCIT x Where x.Id_PdvCon = @PIdPdvCon And x.Cod_Pedido = it.Cod_Pedido)
                 And (it.Qtd_Pedido+it.Qtd_Bonificacao) > 0
                 Group by it.Cod_Pedido, it.Cod_Produto
               EXCEPT
               Select it.Cod_Pedido, Cod_Produto, Qtd=sum(it.Qtd_Pedido+it.Qtd_Bonificacao)
                 From PDVIT it
                 Where it.Cod_Estabe = @CodEstabeDes
                 And Exists(Select 1 From PVCIT x Where x.Id_PdvCon = @PIdPdvCon And x.Cod_Pedido = it.Cod_Pedido)
                 And (it.Qtd_Pedido+it.Qtd_Bonificacao) > 0
                 Group by it.Cod_Pedido, it.Cod_Produto) vw) > 0
      begin
        Set @FlgErr = 1
      end

    if (@FlgWms = 1) and
       ((Select count(*)
           From (Select it.Cod_Pedido, Cod_Produt, Qtd=sum(it.Qtd_Lote)
                   From PDVLT it
                   Where it.Cod_Estabe = @CodEstabeOri
                   And Exists(Select 1 From PVCIT x Where x.Id_PdvCon = @PIdPdvCon And x.Cod_Pedido = it.Cod_Pedido)
                   And it.Qtd_Lote > 0
                   Group by it.Cod_Pedido, it.Cod_Produt
                 EXCEPT
                 Select it.Cod_Pedido, Cod_Produto, Qtd=sum(it.Qtd_Pedido+it.Qtd_Bonificacao)
                   From PDVIT it
                   Where it.Cod_Estabe = @CodEstabeDes
                   And Exists(Select 1 From PVCIT x Where x.Id_PdvCon = @PIdPdvCon And x.Cod_Pedido = it.Cod_Pedido)
                   And (it.Qtd_Pedido+it.Qtd_Bonificacao) > 0
                   Group by it.Cod_Pedido, it.Cod_Produto) vw) > 0)
      begin
        Set @FlgErr = 1
      end

    if @FlgErr = 1
      begin
        RAISERROR('Divergências entre Pedidos Origem x Gerados',16,1)
        Rollback Transaction
	  end
    else
      begin
        -- atualiza status que indica que foram gerados pedidos desconsolidados
        Update PVCCB 
          Set Sta_PdvCon = '4'   
          Where Id_PdvCon = @PIdPdvCon

        Commit Transaction
      end

end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ReabrePDC]
@CodEstabe int, 
@NumPed Int

AS

SET NOCOUNT ON

-- testa se o pedido ja esta em aberto
Declare @Sta varchar(1)
Set @Sta = (Select Status From PDCCB Where Cod_Estabe = @CodEstabe And Numero = @NumPed)
if @Sta = 'A'
  RAISERROR('O pedido informado já está em "Aberto"',16,1)
else
  begin
    Begin Transaction
      -- atualiza o cabecalho do pedido
      Update PDCCB
        Set Status = 'A'
      Where Cod_Estabe = @CodEstabe
      And Numero = @NumPed

      -- atualiza cadastro de produtos
      Update pr
        Set pr.Qtd_Transi = Case
                              When pr.Qtd_Transi < 0 then 0
                              When ((it.Qtd_Pedido + it.Qtd_Bonificacao) > (it.Qtd_Falta + it.Qtd_Fatura)) and
                                   (pr.Qtd_Transi >= ((it.Qtd_Pedido + it.Qtd_Bonificacao) - (it.Qtd_Falta + it.Qtd_Fatura))) then
                                    pr.Qtd_Transi - (it.Qtd_Pedido + it.Qtd_Bonificacao) - (it.Qtd_Falta + it.Qtd_Fatura)
                              Else 0
                            End
      From PDCIT it 
           Inner Join PRXES pr on ((it.Cod_Estabe = pr.Cod_Estabe) and (it.Cod_Produto = pr.Cod_Produt))
      Where it.Cod_Estabe = @CodEstabe     
      And it.Numero = @NumPed
      And (it.Qtd_Pedido + it.Qtd_Bonificacao) > (it.Qtd_Falta + it.Qtd_Fatura)

      -- atualiza itens do pedido
      Update PDCIT
        Set Qtd_Fatura = 0
      Where Cod_Estabe = @CodEstabe     
      And Numero = @NumPed

      -- exclui as previsoes de pagamentos
      Delete from PAGCT
      Where Cod_Estabe = @CodEstabe 
      and Cod_PrtPdc = @NumPed
    
      -- atualiza registros em NEIPC (itens de entrada relacionados ao pedido de compra)
      if not Exists (Select 1 From NEIPC Where Cod_Estabe = @CodEstabe And Num_PedCom = @NumPed)
        begin
          Exec PR_AtualizaNEIPC @CodEstabe, @NumPed
          if @@error <> 0
            begin
              Rollback Transaction
              Return
            end    
        end

    Commit Transaction
  end

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_FechaPDC]
@CodEstabe int,
@NumPed Int,
@NumPrt Int

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime

Set @Now = GetDate()
Set @Date = Cast(GetDate() as datetime)

-- testa se o pedido ja esta fechado
Declare @Sta varchar(1)
Set @Sta = (Select Status From PDCCB Where Cod_Estabe = @CodEstabe And Numero = @NumPed)
if @Sta = 'F'
  RAISERROR('Rotina de Fechamento já executada para o pedido informado',16,1)
else
  begin
    Begin Transaction

      -- atualiza registros em NEIPC (ites de entrada relacionados ao pedido de compra)
      if not Exists (Select 1 From NEIPC Where Cod_Estabe = @CodEstabe And Num_PedCom = @NumPed)
        begin
          Exec PR_AtualizaNEIPC @CodEstabe, @NumPed
          if @@error <> 0
            begin
              if @@trancount > 0
                Rollback Transaction
              Return
            end    
        end

      -- seta status do cabecalho do pedido como "Fechado"
      Update PDCCB
         Set Status = 'F'
       Where Cod_Estabe = @CodEstabe 
         And Numero = @NumPed

    -- coloca qtde faturada em PDCIT
/*    
      Update itp
        Set itp.Qtd_Fatura = Isnull(itp.Qtd_Fatura,0) + 
                             Isnull((Select sum(i.Qtd_Pedido+i.Qtd_Bonificacao)
                                       From NFEIT i Inner join 
                                            NFECB c on c.Cod_Estabe = i.Cod_Estabe and c.Protocolo = i.Protocolo Inner Join 
                                            PDCCB p on c.Cod_Estabe = i.Cod_Estabe and c.Cod_Pedido = p.Numero
                                       Where p.Cod_Estabe = @CodEstabe
                                       And p.Numero = @NumPed
                                       and i.Cod_Produto = itp.Cod_Produto
                                       and c.Status = 'F'
                                       group by i.Cod_Produto),0)
      From PDCIT itp 
           Inner Join NFECB cbn on cbn.Cod_Estabe = itp.Cod_Estabe and cbn.Cod_Pedido = itp.Numero
      Where cbn.Status = 'F' 
      and itp.Cod_Estabe = @CodEstabe
      and itp.Numero = @NumPed
*/

    if @NumPrt = 0
      begin
        Update ic
           Set ic.Qtd_Fatura = IsNull(n.QtdComRel,0)
          From PDCIT ic 
               Inner Join (Select i.Cod_Produto, QtdComRel = sum(i.Qtd_PedCom) 
                             From NEIPC i  
                                  Inner Join NFECB c on i.Cod_Estabe = c.Cod_Estabe And i.Protocolo = c.Protocolo                   
                            Where c.Cod_Estabe = @CodEstabe
                              And ((c.Status = 'F') or (c.Status = 'C'))
                              And i.Num_PedCom = @NumPed
                            Group by i.Cod_Produto) n on ic.Cod_Produto = n.Cod_Produto
         Where ic.Cod_Estabe = @CodEstabe
           and ic.Numero = @NumPed
      end
    else
      begin
        Update ic
           Set ic.Qtd_Fatura = IsNull(ic.Qtd_Fatura,0) + IsNull(n.QtdComRel,0)
          From PDCIT ic 
               Inner Join (Select i.Cod_Produto, QtdComRel = sum(i.Qtd_PedCom) 
                             From NEIPC i  
                                  Inner Join NFECB c on i.Cod_Estabe = c.Cod_Estabe And i.Protocolo = c.Protocolo                   
                            Where c.Cod_Estabe = @CodEstabe
                              And c.Protocolo = @NumPrt
                              And ((c.Status = 'F') or (c.Status = 'C'))
                              And i.Num_PedCom = @NumPed
                            Group by i.Cod_Produto) n on ic.Cod_Produto = n.Cod_Produto
         Where ic.Cod_Estabe = @CodEstabe
           and ic.Numero = @NumPed
      end  

    -- coloca qtde em transito no produto
    Update pr
       Set pr.Qtd_Transi = Isnull(pr.Qtd_Transi,0) + (Isnull(it.Qtd_Pedido,0) + Isnull(it.Qtd_Bonificacao,0)) -
                           (Isnull(it.Qtd_Falta,0) + Isnull(it.Qtd_Fatura,0))
      From PDCIT it 
           Inner Join PRXES pr on pr.Cod_Estabe = it.Cod_Estabe and pr.Cod_Produt = it.Cod_Produto
     Where pr.Cod_Estabe = @CodEstabe
       And it.Numero = @NumPed

    -- verifica se ficou alguma pendencia
    Update cb
       Set cb.Status = 'P'
      From PDCIT it 
           Inner Join PDCCB cb on cb.Cod_Estabe = it.Cod_Estabe and cb.Numero = it.Numero
     Where cb.Cod_Estabe = @CodEstabe
       And cb.Numero = @NumPed 
       and ((Isnull(it.Qtd_Pedido,0) + Isnull(it.Qtd_Bonificacao,0)) - (Isnull(it.Qtd_Falta,0) + Isnull(it.Qtd_Fatura,0))) > 0

    -- Força calculo correto dos itens do pedido de compra DMD-8266
    -- exec PR_ProIni_EliminaPendenciasPdc @CodEstabe,@NumPed
  
    -- GERA PREVISAO DE PAGAMENTOS 
    Exec PR_GeraPrevisaoPAGCT @CodEstabe, @NumPed
    if @@error <> 0
      begin
        if @@trancount > 0
          Rollback Transaction
        Return
      end

    if @@trancount > 0
      Commit Transaction
  end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_FechaNFE]
@CodEstabe int,
@NumPrt int,
@NumSel bigint,
@NumFrm int,
@SerNot varchar(3),
@MsgErr varchar(8000) output

AS

SET NOCOUNT ON
SET ANSI_WARNINGS OFF

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now  = GetDate()
Set @Date = cast(GetDate() as Date)

Set @MsgErr = ''

if (Select Status From NFECB Where Cod_Estabe = @CodEstabe and Protocolo  = @NumPrt) = 'F'
  begin
    Set @MsgErr = 'Nota Fiscal já fechada'
    Return
  end


/*
Status = 'P' : Autorizada
Status = 'O' : Em coleta
Status = 'R' : Coletada
Status = 'T' : Coleta autorizada
Status = 'L' : Em endereçamento
Status = 'E' : Endereçada
*/
Declare @FlgWms bit = 0,
        @FlgMovEst bit = 0,
        @FlgIntWms bit = 0,
        @StaIntWms varchar(1),
        @FlgOpeVdo bit = 0,          -- indica op.triangular, venda à ordem
        @IdOpeVdo int,               -- id da op.triangular
        @NumPrtVincOpeVdo int = 0,
        @FlgDevolOpeVdo bit = 0,     -- indica se é devolução op.triangular
        @MsgAlerta varchar(100) = '',
        @FlgPodeFechar bit = 0
 
Select @FlgIntWms = IsNull(FlgIntegrWmsExt,0) 
  From PMEST 
 Where Cod_Estabe = @CodEstabe
 
Select @FlgWms = IsNull(cb.Flg_WMS,0),
       @FlgMovEst = IsNull(cb.Flg_MovEst,0),
       @StaIntWms = IsNull(cb.Sta_IntWms,''),
       @FlgOpeVdo = IsNull(op.Flg_OpeVdo,0)
  From NFECB cb 
       Left Join TPOPE op on cb.Cod_Ope = op.Cod_Ope
 Where cb.Cod_Estabe = @CodEstabe 
   and cb.Protocolo = @NumPrt
 
if (@FlgMovEst = 1) and (@FlgWms = 1)
  begin
    if Exists(Select 1 
                From (Select Cod_Produto, Cod_Lote, 
                             QtdIte = sum(Qtd_Pedido+Qtd_Bonificacao)
                        From NFEIT 
                       Where Cod_Estabe = @CodEstabe 
                         and Protocolo = @NumPrt
                       Group by Cod_Produto, Cod_Lote ) i
                     Full Join
                     (Select Cod_Produt, Cod_Lote, 
                             QtdLot = IsNull(sum(Qtd_Est),0)
                        From NELTL
                       Where Cod_Estabe = @CodEstabe 
                         and Num_Protoc = @NumPrt
                       Group by Cod_Produt, Cod_Lote ) l on i.Cod_Produto = l.Cod_Produt and i.Cod_Lote = l.Cod_Lote
               Where IsNull(i.QtdIte,0) <> IsNull(l.QtdLot,0) )
      begin
        Set @MsgErr = 'Nota Fiscal com inconsistências nas quantidades para armazenagem'
        Return
      end
     
    if Exists(Select 1
                From NELTL
               Where Cod_Estabe = @CodEstabe 
                 and Num_Protoc = @NumPrt
                 and Tip_Local <> dbo.FN_TipLocEnd(Cod_Estabe, Cod_Dep, Num_Rua) )
      begin
        Set @MsgErr = 'Nota Fiscal com inconsistência na Estrutura para endereçamento com endereço'
        Return
      end
  end  -- if (@FlgMovEst = 1) and (@FlgWms = 1)

if Exists(Select 1 
            From NFECB cb 
                 Inner Join CNGDC dv on cb.Cod_Estabe = dv.Cod_Estabe and cb.Id_Consig  = dv.Id_Consig and
                                        cb.Num_SeqCtr = dv.Num_Sequen and cb.Num_SeqDev = dv.Num_SeqDev 
           Where cb.Cod_Estabe = @CodEstabe 
             and cb.Protocolo = @NumPrt
             and ((cb.Tip_NF <> 'D') or (Cod_FinNfe <> '4')))
    begin
      Set @MsgErr = 'Nota Fiscal com Tipo/Finalidade inválida '
      Return
    end

if Exists(Select 1 
            From NFECB cb 
                 Inner Join CNGDC dv on cb.Cod_Estabe = dv.Cod_Estabe and cb.Id_Consig  = dv.Id_Consig and
                                        cb.Num_SeqCtr = dv.Num_Sequen and cb.Num_SeqDev = dv.Num_SeqDev 
           Where cb.Cod_Estabe = @CodEstabe 
             and cb.Protocolo = @NumPrt
             and cb.Tip_NF = 'D'
             and dv.Tip_Devolu = 'S') 
  if not Exists(Select 1 From TPOPE 
                 Where Tip_EntSai = 'S' 
                   and CharIndex(cast(Cod_CfoNorInt as varchar),';5112;5114;') > 0 
                   and CharIndex(cast(Cod_CfoNorExt as varchar),';6112;6114;') > 0
                   and Tip_Ope = 'V' and IsNull(Flg_Bloqueado,0) = 0)
    begin
      Set @MsgErr = 'Não existe Operação configurada para Venda de Mercadoria Remetida Anteriormente em Consignação '
      Return
    end
 
if Exists(Select 1 
            From NFECB cb 
                 inner Join TPOPE op on cb.Cod_Ope = op.Cod_Ope         
           Where cb.Cod_Estabe = @CodEstabe 
             and cb.Protocolo = @NumPrt
             and IsNull(op.Flg_OpeVdo,0) = 1				 )
  begin
    Exec PR_CriticaOperacaoTriangular @CodEstabe, @NumPrt, '', 'E', @MsgAlerta output, @MsgErr output
  end
 
if @MsgErr <> ''
  Return
 
if @MsgErr = ''
  BEGIN
    Begin Transaction

    -- cria arq. temporario
    IF OBJECT_ID('tempdb..#ARQ_NELTL') IS NOT NULL
      DROP TABLE #ARQ_NELTL
 
    CREATE TABLE #ARQ_NELTL
    (
     Chave int identity,
     Cod_Prd int,
     Cod_Lot varchar(20),
     Tip_Loc varchar(1),
     Cod_Dep smallint,
     Num_Rua smallint,
     Num_Col smallint,
     Num_Niv smallint,
     Num_Apt smallint,
     Qtd_Lot int,
     Qtd_EmbFec int,
    ) 

    Set @FlgPodeFechar = 0

    if (@FlgWms = 0) or (@FlgMovEst = 0)
      Set @FlgPodeFechar = 1
    else
    if (@FlgIntWms = 0) and (@StaIntWms = '')
      Set @FlgPodeFechar = 1
    else
	if @FlgIntWms = 1
      begin
        if @StaIntWms = '1'
          Set @FlgPodeFechar = 1
	 else
          begin
            Update NFECB
               Set Sta_IntWMS = '0'
             Where Cod_Estabe = @CodEstabe 
               And Protocolo = @NumPrt
               And IsNull(Sta_IntWMS,'') = ''

            Exec PR_WMSGerarXMLEntrada @CodEstabe, @NumPrt
          end
      end

    -- registra documentos relacionados
    Exec PR_RegistraNEREF @CodEstabe, @NumPrt
    if @@error <> 0
      begin
        if @@trancount > 0
          RollBack Transaction
        Return
      end
  
    if @FlgOpeVdo = 1
      Exec PR_IncluiOPVDO @CodEstabe, @NumPrt, '', 'E', @IdOpeVdo output
  
    if @IdOpeVdo > 0
      Select top 1 
             @NumPrtVincOpeVdo = IsNull(rf.Num_DocRef,0),
             @FlgDevolOpeVdo   = Case
                                   When cb.Tip_NF  = 'D' then 1
                                   When cbv.Tip_NF = 'D' then 1
                                   Else 0
                                 End
        From NFECB cb
             inner Join NEREF rf  on cb.Cod_Estabe = rf.Cod_Estabe
                                 and cb.Protocolo = rf.Protocolo 
                                 and rf.Tip_EntSai = 'E' 
             inner join NFECB cbv on rf.Cod_Estabe = cbv.Cod_Estabe
                                 and rf.Num_DocRef = cbv.Protocolo
       Where cb.Cod_Estabe = @CodEstabe
         And cb.Protocolo = @NumPrt

    if @FlgPodeFechar = 1
      Begin 
          
        Declare @KCfoBonEntInt int = 1910,
                @KCfoBonEntExt int = 2910,		         
                @TipNfe varchar(1),
                @TipNfsRef varchar(1),
                @StaNfe varchar(1),
                @CodModDoc varchar(2),
                @CodRegTri int,
                @CodOpe varchar(3),
                @CodCfo int,
                @FlgBlqTrfEstFis bit,
                @CodUf char(2),
                @NumPed int,
                @FlgImpNot bit,
                @FlgDevTot bit,
                @CodEmiFor int,
                @CodEmiTra int,
                @CodEmiCli int,
                @CodVdr int,
                @CodVdrTlmkt int,
                @CodSup int,                  
                @TipEmi char(3),
                @CodEmi int,
                @ValNot numeric(18,4),
                @ValDspEmb numeric(18,4),
                @IdPdvCon int,
                @FlgReservConsig bit = 0,  -- reserva itens consignados quando for NF de devolução simbólica sem WMS
                @FlgFaturaConsig bit = 0,  -- gera fatura de consignados quando for NF de devolução simbólica
                @IdConsig int = 0,
                @NumSeqCtr smallint = 0,
                @NumSeqDev smallint = 0,
                @NumReserv int = 0,
                @DesHisReserv varchar(40) = '',
                @CodTipDevCng varchar(3) = '',
                @CodOpeSai varchar(3) = '',
                @IdTransacao int,
                @Usuario varchar(15),
                @DesMovime varchar(60),
                @Chave int,
                @CodPrd int,
                @CodLot varchar(20),
                @NumSeqIte smallint,
                @TipEnt varchar(1),
                @DatMov smalldatetime,
                @DatVct smalldatetime,
                @DatFab smalldatetime,
                @TipLoc varchar(1),
                @CodDep smallint,
                @NumRua smallint,
                @NumCol smallint,
                @NumNiv smallint,
                @NumApt smallint,
                @QtdPed int,
                @QtdBon int,
                @PrcUni numeric(18,8),
                @QtdEmbFec smallint,
                @QtdEst int,
                @QtdMov int,
                @QtdMovSld int,
                @CodPrm int,
                @QtdPrm int,
                @QtdPra int,
                @QtdDep int,
                @CusLiqUni numeric(18,4),
                @ValLiq numeric(18,4),
                @ValCusMed numeric(18,4),
                @ValPrcFab numeric(18,4),
                @VlrVerbaVdr numeric(18,4),
                @VlrVerbaSup numeric(18,4),
                @VlrVerbaOpe numeric(18,4),
                @VlrVerbaFor numeric(18,4),
                @QtdSldFis int,
                @WCodDoc int,
                @WCodOri varchar(20),
                @SerNotSai varchar(3),
                @NumNotSai int,
                @CodFab int,
                @QtdPrzMed numeric(18,4),
                @FlgDevChv Bit,
                @WIsnCtaFinEntid int,

                @em_CodEst varchar(2),
                @em_FlgContriSubstituido bit,
                @pm_NumItePagNfs int,
                @pm_FlgCtrSelFis bit,
                @pm_ModeloNotaFiscal varchar(3),
                @pm_SerieSeloFiscal varchar(2),
                @pm_FlgNfe bit,
                @pm_FlgUsaPrcCusLiqEnt bit,
                @pm_FlgManDupDevTotVen bit = 0,
                @pm_QtdDecPrcItePdv smallint,
                @pm_FlgDbqPrdVenAutEntCmp bit,
                @pm_FlgUsaInterv bit,
                @to_IsnCtaFinDeb int,
                @to_IsnCtaFinCre int,
                @to_IsnCtaFinCreInterv int,
                @to_IsnCtaFinDebInterv int,
                @pc_Controle_Saldo varchar(1),
                @pc_FlgAcuVrbPos bit,
                @pc_FlgAcuVrbNeg bit,
		        @pc_FlgCtrPdvVrbVdr bit,
		        @pc_FlgCtrPdvVrbOpe bit

        -- cfop bonificacao entrada
        Set @KCfoBonEntInt = 1910
        Set @KCfoBonEntExt = 2910
        Set @TipNfsRef = ''
                  
        -- poe dados da nf na memoria
        Select @TipNfe = cb.Tip_NF,  
               @StaNfe = cb.Status, 
               @CodModDoc = IsNull(cb.Cod_ModDoc,''),
               @DatMov = cb.Dat_Movimento,
               @CodRegTri = Isnull(cb.Cod_RegTri,0),
               @CodOpe = IsNull(cb.Cod_Ope,''),
               @CodCfo = Isnull(cb.Cod_Cfo,0),
               @FlgBlqTrfEstFis = cf.Flg_BlqTrfEstFis,
               @CodUf = Upper(cb.Cod_UfOrigem),
               @FlgMovEst = IsNull(cb.Flg_MovEst,0),
               @FlgImpNot = IsNull(cb.Flg_ImpNot,0),
               @FlgDevTot = IsNull(cb.Flg_DevTot,0),
               @CodEmiFor = IsNull(cb.Cod_EmiFornec,0),
               @CodEmiTra = IsNull(cb.Cod_EmiTransp,0),
               @CodEmiCli = IsNull(cb.Cod_EmiCliente,0),
               @CodVdr = IsNull(cb.Cod_Vendedor,0), 
               @CodVdrTlmkt = IsNull(cb.Cod_VendTlmkt,0),
               @CodSup = IsNull(ve.Cod_Supervisor,0),
               @ValNot = IsNull(cb.Vlr_Nota,0),
               @IdPdvCon = IsNull(cb.Id_PdvCon,0),

               @FlgReservConsig = Case 
                                    When (cb.Tip_NF = 'D') and (IsNull(cb.Flg_WMS,0) = 0) and 
                                          (IsNull(dv.Id_Consig,0) > 0) and (dv.Tip_Devolu = 'S') then 1 
                                    Else 0 
                                  End,
               @FlgFaturaConsig = Case 
                                    When (cb.Tip_NF = 'D') and 
                                         (IsNull(dv.Id_Consig,0) > 0) and (dv.Tip_Devolu = 'S') then 1 
                                    Else 0 
                                  End,
               @IdConsig        = Case 
                                    When (cb.Tip_NF = 'D') and (IsNull(dv.Id_Consig,0) > 0) then cb.Id_Consig 
                                    Else 0 
                                  End,
               @NumSeqCtr       = Case 
                                    When (cb.Tip_NF = 'D') and (IsNull(dv.Id_Consig,0) > 0) then cb.Num_SeqCtr 
                                    Else 0 
                                  End,
               @NumSeqDev       = Case 
                                    When (cb.Tip_NF = 'D') and (IsNull(dv.Id_Consig,0) > 0) then cb.Num_SeqDev 
                                    Else 0 
                                  End

          From NFECB cb
               left join TBCFO cf on cb.Cod_Cfo = cf.Codigo
               left join VENDE ve on cb.Cod_Vendedor = ve.Codigo
               left join CNGDC dv on cb.Cod_Estabe = dv.Cod_Estabe and cb.Id_Consig  = dv.Id_Consig and
                                     cb.Num_SeqCtr = dv.Num_Sequen and cb.Num_SeqDev = dv.Num_SeqDev 
         Where cb.Cod_Estabe = @CodEstabe 
           and cb.Protocolo = @NumPrt

        Set @Usuario = dbo.FN_UsuarioInfarma()

        Select @em_CodEst = Des_Estado,
               @em_FlgContriSubstituido = IsNull(Flg_ContriSubstituido,0)
          From ESTAB
         Where Cod_Estabe = @CodEstabe  
          
        -- coloca campos PARAM na memoria
        Select @pm_NumItePagNfs = IsNull(NumItePagNfs,0),
               @pm_FlgCtrSelFis = IsNull(FlgCtrSelFis,0),
               @pm_ModeloNotaFiscal = ModeloNotaFiscal,
               @pm_SerieSeloFiscal = SerieSeloFiscal,
               @pm_FlgNfe = IsNull(FlgNfe,0),
               @pm_FlgUsaPrcCusLiqEnt = IsNull(FlgUsaPrcCusLiqEnt,0),
               @pm_FlgManDupDevTotVen = IsNull(FlgManDupDevTotVen, 0),
               @pm_QtdDecPrcItePdv = IsNull(QtdDecPrcItePdv,2),
               @pm_FlgDbqPrdVenAutEntCmp = IsNull(FlgDbqPrdVenAutEntCmp,0)
          From PARAM    
         Where Cod_Estabe = @CodEstabe

        -- coloca campos TPOPE na memoria
        Select @pm_FlgUsaInterv = IsNull(FlgUsaInterv,0)
          From PMFIN
            
        Select @to_IsnCtaFinDeb = ISNULL(Isn_CtaFinDeb,0),
               @to_IsnCtaFinCre = ISNULL(Isn_CtaFinCre,0)
          From TPOPE
         Where Cod_Ope = @CodOpe
          
        -- configura cod. origem (WMS)
        Set @WCodOri = ''
        if @TipNfe = 'C'
          Set @WCodOri = 'ENT_COM'
        else  
        if @TipNfe = 'D'
          Set @WCodOri = 'ENT_DEV'
        else  
        if @TipNfe = 'T'
          Set @WCodOri = 'ENT_TRF'
        else  
        if @TipNfe = 'O'
          Set @WCodOri = 'ENT_OUT'
        
        -- poe na memoria conta da entidade para ser armazenada na tabela VALES
        Set @WIsnCtaFinEntid = 0
        if @CodEmiFor > 0
          Set @WIsnCtaFinEntid = IsNull((Select Isn_CtaFin From FORNE Where Codigo = @CodEmiFor),0)
        else
        if @CodEmiTra > 0  
          Set @WIsnCtaFinEntid = IsNull((Select Isn_CtaFin From TRANS Where Codigo = @CodEmiTra),0)
        else
        if @CodEmiCli > 0  
          Set @WIsnCtaFinEntid = IsNull((Select Isn_CtaFin From CLIEN Where Codigo = @CodEmiCli),0)
        
        -- plano de contas
        Set @to_IsnCtaFinCreInterv = 0
        Set @to_IsnCtaFinDebInterv = 0
        if @pm_FlgUsaInterv = 1
          begin
            if (@to_IsnCtaFinCre = (Select IsnCtaFinPagFor From PMFIN)) and (@CodEmiFor > 0)
              Set @to_IsnCtaFinCreInterv = @WIsnCtaFinEntid
                  
            if (@to_IsnCtaFinCre = (Select IsnCtaFinPagTra From PMFIN)) and (@CodEmiTra > 0)
              Set @to_IsnCtaFinCreInterv = @WIsnCtaFinEntid
                  
            if (@to_IsnCtaFinCre = (Select IsnCtaFinRecCli From PMFIN)) and (@CodEmiCli > 0)
              Set @to_IsnCtaFinCreInterv = @WIsnCtaFinEntid
                  
            if @to_IsnCtaFinCreInterv > 0
              Set @to_IsnCtaFinCre = @to_IsnCtaFinCreInterv 
              
            if (@to_IsnCtaFinDeb = (Select IsnCtaFinPagFor From PMFIN)) and (@CodEmiFor > 0)
              Set @to_IsnCtaFinDebInterv = IsNull((Select Isn_CtaFin From FORNE Where Codigo = @CodEmiFor),0)
                  
            if (@to_IsnCtaFinDeb = (Select IsnCtaFinPagTra From PMFIN)) and (@CodEmiTra > 0)
              Set @to_IsnCtaFinDebInterv = IsNull((Select Isn_CtaFin From TRANS Where Codigo = @CodEmiTra),0)
                  
            if (@to_IsnCtaFinDeb = (Select IsnCtaFinRecCli From PMFIN)) and (@CodEmiCli > 0)
              Set @to_IsnCtaFinDebInterv = IsNull((Select Isn_CtaFin From CLIEN Where Codigo = @CodEmiCli),0)
                  
            if @to_IsnCtaFinDebInterv > 0
              Set @to_IsnCtaFinDeb = @to_IsnCtaFinDebInterv 
              
            if not Exists(Select 1 From PCFIN Where Isn_CtaFin = @to_IsnCtaFinCre And Tip_CtaFin = 'A')
              Set @to_IsnCtaFinCre = 0
            if not Exists(Select 1 From PCFIN Where Isn_CtaFin = @to_IsnCtaFinDeb And Tip_CtaFin = 'A')
              Set @to_IsnCtaFinDeb = 0
        
            if (@to_IsnCtaFinDeb = 0) or (@to_IsnCtaFinCre = 0)
              begin
                if @@trancount > 0
                  RollBack Transaction
                RAISERROR('Pelo menos uma conta gerencial envolvida é inválida',16,1)
                Return
              end              
              
            if (@TipNfe = 'D') and (@FlgMovEst = 1) and            
                not Exists(Select pm.IsnCtaFinDespVal 
                             From PMFIN pm Inner Join
                                  PCFIN pc on pm.IsnCtaFinDespVal  = pc.Isn_CtaFin
                            Where pc.Tip_CtaFin = 'A')     
              begin
                if @@trancount > 0
                  RollBack Transaction
                RAISERROR('Parâmetro Financeiro Conta (CREDITOS A CONCEDER) não configurada',16,1)
                Return
              end              
                
          end  -- if @pm_FlgUsaInterv = 1
        else
          begin
            Set @to_IsnCtaFinDeb = 0
            Set @to_IsnCtaFinCre = @WIsnCtaFinEntid
            Set @to_IsnCtaFinDeb = @to_IsnCtaFinCre  -- igualando debito/credito em 26/06/2015
          end
                   
        -- calcula custo liquido
        Update NFEIT
           Set Vlr_LiqIte = dbo.FN_ValLiqIteNFEIT(Cod_Estabe,
                                                  Protocolo,
                                                  Cod_Produto,
                                                  Cod_Lote,
                                                  Num_SeqIte),
               Cus_LiqUni = dbo.FN_CusLiqUniNFEIT(Cod_Estabe,
                                                  Protocolo,
                                                  Cod_Produto,
                                                  Cod_Lote,
                                                  Num_SeqIte)
         Where Cod_Estabe = @CodEstabe 
           and Protocolo = @NumPrt
        
        -- atualiza cadastro de produtos
        Update pr
           Set pr.Flg_BlqVen = 0
          From NFEIT it Inner Join 
               PRXES pr on it.Cod_Estabe = pr.Cod_Estabe And it.Cod_Produto = pr.Cod_Produt
         Where it.Cod_Estabe = @CodEstabe 
           And it.Protocolo = @NumPrt 
           And @TipNfe = 'C'
           And @FlgMovEst = 1
           And IsNull(@pm_FlgDbqPrdVenAutEntCmp,0) = 1
           And IsNull(pr.Flg_BlqVen,0) = 1

        Update it 
           Set it.Val_PrcVen = Round(it.Cus_LiqUni*(1+IsNull(it.Per_Markup,0)/100),@pm_QtdDecPrcItePdv)
          From NFEIT it 
         Where it.Cod_Estabe = @CodEstabe 
           and it.Protocolo = @NumPrt
           And IsNull(it.Flg_PrcVen,0) = 1
           And IsNull(it.Cus_LiqUni,0) > 0
           And @pm_FlgUsaPrcCusLiqEnt = 1

        Update pr
           Set pr.Prc_VenAnt = case 
                                 When @DatMov > pr.Dat_PrcAtual then pr.Prc_Venda
                                 else pr.Prc_VenAnt
                               end,
               pr.Dat_PrcAnt = case 
                                 When @DatMov > pr.Dat_PrcAtual then pr.Dat_PrcAtual
                                 else pr.Dat_PrcAnt
                               end,
               pr.Prc_Venda = it.Val_PrcVen,
               pr.Dat_PrcAtual = @DatMov,
               pr.Usuario = @Usuario,
               pr.Transacao = @Now
          From NFEIT it Inner Join 
               PRXES pr on it.Cod_Estabe = pr.Cod_Estabe And it.Cod_Produto = pr.Cod_Produt 
         Where it.Cod_Estabe = @CodEstabe 
           And it.Protocolo = @NumPrt 
           And IsNull(it.Flg_PrcVen,0) = 1
           And IsNull(it.Val_PrcVen,0) > 0
           And IsNull(@pm_FlgUsaPrcCusLiqEnt,0) = 1

        -- seta o status de fechado
        Set @StaNfe = 'F'
        Update NFECB
           Set Status = @StaNfe,
               Flg_BlqTrfEstFis = IsNull(@FlgBlqTrfEstFis,0),
               Id_OpeVdo = @IdOpeVdo,
               Transacao = @Now
         Where Cod_Estabe = @CodEstabe 
           and Protocolo = @NumPrt

        if @IdOpeVdo > 0
          Update NFECB
             Set Id_OpeVdo = @IdOpeVdo
         Where Cod_Estabe = @CodEstabe 
           and Protocolo = @NumPrtVincOpeVdo

        -- atribui Protoclo de Entrada ao endereço de Cross Docking
        Update ed
           Set ed.Cod_Cntrol = 'NFE'
             , ed.Num_Cntrol =  cb.Protocolo 
          From NFECB cb
               inner join ENDDP ed on cb.Cod_Estabe = ed.Cod_Estabe and cb.Id_EndDep = ed.Id_EndDep
         Where cb.Cod_Estabe = @CodEstabe
           and cb.Protocolo = @NumPrt
           and IsNull(cb.Flg_CrossDocking,0) = 1

        -- reabre pedido de compra
        -- if @TipNfe = 'C'
        -- pedido de compra atualizado se na NF atual a Flg_MovEst = 1
        if @FlgMovEst = 1
          begin
            if Exists(Select 1 From NFEPC Where Cod_Estabe = @CodEstabe and Protocolo = @NumPrt)
              begin
                Declare Nfepc_Cr Cursor Local Fast_Forward For 
                  Select n.Cod_Pedido
                    From NFEPC n
	    			       Inner Join PDCCB p on n.Cod_Estabe = p.Cod_Estabe and n.Cod_Pedido = p.Numero
                    Where n.Cod_Estabe = @CodEstabe
                      And n.Protocolo = @NumPrt
               end
             else
               begin
                 Declare Nfepc_Cr Cursor Local Fast_Forward For 
                   Select n.Cod_Pedido
                     From NFEPC n
	    			       Inner Join PDCCB p on n.Cod_Estabe = p.Cod_Estabe and n.Cod_Pedido = p.Numero
                   Where n.Cod_Estabe = @CodEstabe
                     And n.Protocolo = @NumPrtVincOpeVdo
              end
            Open Nfepc_Cr
            Fetch Next From Nfepc_Cr Into @NumPed
           While @@FETCH_STATUS = 0
             begin
               Exec PR_ReabrePDC @CodEstabe, @NumPed
               Fetch Next From Nfepc_Cr  Into @NumPed
             end
           Close Nfepc_Cr
           Deallocate Nfepc_Cr
         end  -- @FlgMovEst = 1

        -- atualiza cadastro de produtos
        Update pr
           Set pr.Prc_VenAnt = case 
                                 When @DatMov > pr.Dat_PrcAtual then pr.Prc_Venda
                                 else pr.Prc_VenAnt
                               end,
               pr.Dat_PrcAnt = case 
                                 When @DatMov > pr.Dat_PrcAtual then pr.Dat_PrcAtual
                                 else pr.Dat_PrcAnt
                               end,
               pr.Prc_Venda = it.Val_PrcVen,
               pr.Dat_PrcAtual = @DatMov,
               pr.Usuario = @Usuario,
               pr.Transacao = @Now
          From NFEIT it Inner Join 
               PRXES pr on it.Cod_Estabe = pr.Cod_Estabe And it.Cod_Produto = pr.Cod_Produt
         Where it.Cod_Estabe = @CodEstabe 
           And it.Protocolo = @NumPrt 
           And IsNull(it.Flg_PrcVen,0) = 1
           And IsNull(it.Val_PrcVen,0) > 0
           And IsNull(@pm_FlgUsaPrcCusLiqEnt,0) = 0
          
        -- atualiza cadastro de produtos somente em entradas por compra
        Update pr
           Set pr.Per_Ipi = it.Alq_Ipi
          From NFEIT it Inner Join 
               PRODU pr on it.Cod_Produto = pr.Codigo
         Where it.Cod_Estabe = @CodEstabe 
           And it.Protocolo = @NumPrt 
           And @TipNfe = 'C'

        Update pr
           Set pr.Prc_CusLiqEnt = x.CusUniMedNfe,
               pr.Prc_EntAnt = pr.Prc_UltEnt,
               pr.Per_DscEntAnt = pr.Per_DscUltEnt,
               pr.Qtd_EntAnt = pr.Qtd_UltEnt,
               pr.Dat_EntAnt = pr.Dat_UltCompra,
               pr.Prc_UltEnt = x.PrcUniMedNfe,
               pr.Per_DscUltEnt = x.DscUniMedNfe,
               pr.Qtd_UltEnt = x.QtdTotNfe,
               pr.Dat_UltCompra = x.Dat_Movimento
          From PRXES pr Inner Join 
               (Select cb.Dat_Movimento, it.Cod_Estabe, it.Cod_Produto, 
                       sum(it.Qtd_Pedido+it.Qtd_Bonificacao) as QtdTotNfe,
                       sum(it.Cus_LiqUni*(it.Qtd_Pedido+it.Qtd_Bonificacao))/sum(it.Qtd_Pedido+it.Qtd_Bonificacao) as CusUniMedNfe,
                       sum(it.Prc_Unitario*(it.Qtd_Pedido+it.Qtd_Bonificacao))/sum(it.Qtd_Pedido+it.Qtd_Bonificacao) as PrcUniMedNfe,
                       sum(it.Per_DescItem*it.Prc_Unitario*(it.Qtd_Pedido+it.Qtd_Bonificacao))/sum(it.Prc_Unitario*(it.Qtd_Pedido+it.Qtd_Bonificacao)) as DscUniMedNfe
                  From NFECB cb Inner Join NFEIT it on ((cb.Cod_Estabe = it.Cod_Estabe) and (cb.Protocolo = it.Protocolo))
                 Where cb.Cod_Estabe = @CodEstabe 
                   and cb.Protocolo = @NumPrt 
                   and cb.Flg_AtuPrcCus = 1 and cb.Flg_MovEst = 1 and cb.Cod_Cfo > 0
                 Group by cb.Dat_Movimento, it.Cod_Estabe, it.Cod_Produto) x ON pr.Cod_Estabe = x.Cod_Estabe And pr.Cod_Produt = x.Cod_Produto
          
        Update pr
           Set pr.Prc_CusLiqEntDep = x.CusUniMedNfe,
               pr.Prc_EntAntDep = pr.Prc_UltEntDep,
               pr.Per_DscEntAntDep = pr.Per_DscUltEntDep,
               pr.Qtd_EntAntDep = pr.Qtd_UltEntDep,
               pr.Dat_EntAntDep = pr.Dat_UltEntDep,
               pr.Prc_UltEntDep = x.PrcUniMedNfe,
               pr.Per_DscUltEntDep = x.DscUniMedNfe,
               pr.Qtd_UltEntDep = x.QtdTotNfe,
               pr.Dat_UltEntDep = x.Dat_Movimento
          From PRXES pr Inner Join 
               (Select cb.Dat_Movimento, it.Cod_Estabe, it.Cod_Produto, 
                       sum(it.Qtd_Pedido+it.Qtd_Bonificacao) as QtdTotNfe,
                       sum(it.Cus_LiqUni*(it.Qtd_Pedido+it.Qtd_Bonificacao))/sum(it.Qtd_Pedido+it.Qtd_Bonificacao) as CusUniMedNfe,
                       sum(it.Prc_Unitario*(it.Qtd_Pedido+it.Qtd_Bonificacao))/sum(it.Qtd_Pedido+it.Qtd_Bonificacao) as PrcUniMedNfe,
                       sum(it.Per_DescItem*it.Prc_Unitario*(it.Qtd_Pedido+it.Qtd_Bonificacao))/sum(it.Prc_Unitario*(it.Qtd_Pedido+it.Qtd_Bonificacao)) as DscUniMedNfe
                  From NFECB cb Inner Join NFEIT it on ((cb.Cod_Estabe = it.Cod_Estabe) and (cb.Protocolo = it.Protocolo))
                 Where cb.Cod_Estabe = @CodEstabe 
                   and cb.Protocolo = @NumPrt 
                   and cb.Flg_AtuPrcCus = 1 and cb.Flg_MovEst = 1 and (Isnull(cb.Cod_Cfo,0) = 0)
                 Group by cb.Dat_Movimento, it.Cod_Estabe, it.Cod_Produto) x ON pr.Cod_Estabe = x.Cod_Estabe And pr.Cod_Produt = x.Cod_Produto
        
        --  guarda no item estoque e custo medio anterior a entrada
        Update it
           Set it.Prc_CusMedAnt = pr.Prc_CusMed,
               it.Vlr_BasCalSubTriEntMedAnt = pr.Vlr_BasCalSubTriEntMed,
               it.Qtd_FisAnt = case 
                                 When pr.Qtd_Fisico > 0 then pr.Qtd_Fisico
                                 else 0
                               end
          From NFEIT it Inner Join 
               NFECB cb on ((it.Cod_Estabe = cb.Cod_Estabe) and (it.Protocolo = cb.Protocolo)) Inner Join 
               PRXES pr on it.Cod_Estabe = pr.Cod_Estabe And it.Cod_Produto = pr.Cod_Produt
         Where cb.Cod_Estabe = @CodEstabe 
           and cb.Protocolo = @NumPrt
          
        -- base de calculo medio ST: compras, transferencias e bonificacoes
        Update pr
           Set pr.Vlr_BasCalSubTriEntMed = case
                                             when ((pr.Vlr_BasCalSubTriEntMed = 0) or (pr.Qtd_Fisico <= 0)) then x.BasCalSubTriMedNfe
                                             else (pr.Vlr_BasCalSubTriEntMed*pr.Qtd_Fisico + x.BasCalSubTriMedNfe*x.QtdTotNfe)/(pr.Qtd_Fisico+x.QtdTotNfe)
                                           end
          From PRXES pr Inner Join 
               (Select it.Cod_Estabe, it.Cod_Produto, sum(it.Qtd_Pedido+it.Qtd_Bonificacao) as QtdTotNfe,
                       sum(it.Vlr_BasSubsTrib)/sum(it.Qtd_Pedido+it.Qtd_Bonificacao) as BasCalSubTriMedNfe
                  From NFECB cb Inner Join 
                       NFEIT it on ((cb.Cod_Estabe = it.Cod_Estabe) and (cb.Protocolo = it.Protocolo))
                 Where cb.Cod_Estabe = @CodEstabe 
                   and cb.Protocolo = @NumPrt
                   and cb.Flg_AtuPrcCus = 1 and cb.Flg_MovEst = 1
                   and ((cb.Tip_NF = 'C') or (cb.Tip_NF = 'T') or (cb.Cod_Cfo = @KCfoBonEntExt) or (cb.Cod_Cfo = @KCfoBonEntInt))
        		     and IsNull(it.Vlr_BasSubsTrib,0) > 0
                 Group by it.Cod_Estabe, it.Cod_Produto) x ON pr.Cod_Estabe = x.Cod_Estabe And pr.Cod_Produt = x.Cod_Produto
          
        -- custo medio gerencial
        Update pr
           Set pr.Prc_CusMed = case
                                 when ((pr.Prc_CusMed = 0) or (pr.Qtd_Fisico <= 0)) then x.TotCusMed
                                 else (pr.Prc_CusMed*pr.Qtd_Fisico + x.TotCusMed*x.TotQtd)/(pr.Qtd_Fisico+x.TotQtd)
                               end
          From PRXES pr Inner Join 
               (Select ix.Cod_Estabe, ix.Cod_Produto, TotQtd=sum(ix.QtdTotNfe), TotCusMed=sum(ix.CusMedNfe)
                  From (Select it.Cod_Estabe, it.Cod_Cfo, it.Cod_Produto, 
                               QtdTotNfe = sum(it.Qtd_Pedido+it.Qtd_Bonificacao),
                               CusMedNfe = case 
                                             When ((cb.Cod_Cfo <> @KCfoBonEntInt) and (cb.Cod_Cfo <> @KCfoBonEntExt)) and  -- nao eh nf de bonificacao
                                                  ((it.Cod_Cfo = @KCfoBonEntInt) or (it.Cod_Cfo = @KCfoBonEntExt)) then 0
                                             Else sum(it.Cus_LiqUni*it.Qtd_Pedido)/sum(it.Qtd_Pedido+it.Qtd_Bonificacao)
                                           end
                          From NFECB cb Inner Join 
                               NFEIT it on ((cb.Cod_Estabe = it.Cod_Estabe) and (cb.Protocolo = it.Protocolo))
                         Where cb.Cod_Estabe = @CodEstabe
                           and cb.Protocolo = @NumPrt
                           and cb.Flg_AtuPrcCus = 1 and cb.Flg_MovEst = 1
                         Group by cb.Cod_Cfo, it.Cod_Estabe, it.Cod_Cfo, it.Cod_Produto) ix
                 Group by ix.Cod_Estabe, ix.Cod_Produto) x ON pr.Cod_Estabe = x.Cod_Estabe And pr.Cod_Produt = x.Cod_Produto
          
        -- custo medio 1
        Update pr
           Set pr.Prc_CusMedPra = case
                                    when ((pr.Prc_CusMedPra = 0) or (IsNull(s.Qtd_SldPra,0) <= 0)) then x.TotCusMed
                                    else (pr.Prc_CusMedPra*IsNull(s.Qtd_SldPra,0) + x.TotCusMed*x.TotQtd)/(IsNull(s.Qtd_SldPra,0)+x.TotQtd)
                                  end
          From PRXES pr Inner Join 
               (Select ix.Cod_Estabe, ix.Cod_Produto, TotQtd=sum(ix.QtdTotNfe), TotCusMed=sum(ix.CusMedNfe)
                  From (Select it.Cod_Estabe, it.Cod_Cfo, it.Cod_Produto, 
                               QtdTotNfe = sum(it.Qtd_Pedido+it.Qtd_Bonificacao),
                               CusMedNfe = case 
                                             When ((cb.Cod_Cfo <> @KCfoBonEntInt) and (cb.Cod_Cfo <> @KCfoBonEntExt)) and  -- nao eh nf de bonificacao
                                                  ((it.Cod_Cfo = @KCfoBonEntInt) or (it.Cod_Cfo = @KCfoBonEntExt)) then 0
                                             Else sum(it.Cus_LiqUni*it.Qtd_Pedido)/sum(it.Qtd_Pedido+it.Qtd_Bonificacao)
                                           end
                          From NFECB cb Inner Join 
                               NFEIT it on ((cb.Cod_Estabe = it.Cod_Estabe) and (cb.Protocolo = it.Protocolo))
                         Where cb.Cod_Estabe = @CodEstabe
                           and cb.Protocolo = @NumPrt
                           and cb.Flg_AtuPrcCus = 1 and cb.Flg_MovEst = 1 and Isnull(cb.Cod_Cfo,0) > 0
                         Group by cb.Cod_Cfo, it.Cod_Estabe, it.Cod_Cfo, it.Cod_Produto) ix
                 Group by ix.Cod_Estabe, ix.Cod_Produto) x ON pr.Cod_Estabe = x.Cod_Estabe And pr.Cod_Produt = x.Cod_Produto  Left Outer Join
             (Select Cod_Estabe, Cod_Produt, max(Dat_Movime) as UltDatMov 
                From PRSLD
               Where Cod_Estabe = @CodEstabe
               Group by Cod_Estabe, Cod_Produt) y ON pr.Cod_Estabe = y.Cod_Estabe And pr.Cod_Produt = y.Cod_Produt Left Outer Join 
             PRSLD s ON (pr.Cod_Estabe = s.Cod_Estabe And pr.Cod_Produt = s.Cod_Produt and y.UltDatMov = s.Dat_Movime)
          
        -- custo medio 2
        Update pr
           Set pr.Prc_CusMedDep = case
                                    when ((pr.Prc_CusMedDep = 0) or (IsNull(s.Qtd_SldDep,0) <= 0)) then x.CusMedNfe
                                    else (pr.Prc_CusMedDep*IsNull(s.Qtd_SldDep,0) + x.CusMedNfe*x.QtdTotNfe)/(IsNull(s.Qtd_SldDep,0)+x.QtdTotNfe)
                                  end
          From PRXES pr Inner Join 
               (Select it.Cod_Estabe, it.Cod_Produto, sum(it.Qtd_Pedido+it.Qtd_Bonificacao) as QtdTotNfe,
                       sum(it.Cus_LiqUni*it.Qtd_Pedido)/sum(it.Qtd_Pedido+it.Qtd_Bonificacao) as CusMedNfe
                  From NFECB cb Inner Join NFEIT it on ((cb.Cod_Estabe = it.Cod_Estabe) and (cb.Protocolo = it.Protocolo))
                 Where cb.Cod_Estabe = @CodEstabe 
                   and cb.Protocolo = @NumPrt 
                   and cb.Flg_AtuPrcCus = 1 and cb.Flg_MovEst = 1 and Isnull(cb.Cod_Cfo,0) = 0
                 Group by it.Cod_Estabe, it.Cod_Produto) x ON pr.Cod_Estabe = x.Cod_Estabe and pr.Cod_Produt = x.Cod_Produto Left Outer Join
               (Select Cod_Estabe, Cod_Produt, max(Dat_Movime) as UltDatMov 
                  From PRSLD
                 Where Cod_Estabe = @CodEstabe
                 Group by Cod_Estabe, Cod_Produt) y ON pr.Cod_Estabe = y.Cod_Estabe and pr.Cod_Produt = y.Cod_Produt Left Outer Join 
               PRSLD s ON (pr.Cod_Estabe = s.Cod_Estabe and pr.Cod_Produt = s.Cod_Produt and y.UltDatMov = s.Dat_Movime)
               
        -- atualiza custo medio comercial
		-- considerar verba do fornecedor : Vlr_DscIte2     
        Update pr
           Set pr.Prc_CusMedCom = case
                                    when ((pr.Prc_CusMedCom = 0) or (pr.Qtd_Fisico <= 0)) then x.TotCusMed
                                    else (pr.Prc_CusMedCom*pr.Qtd_Fisico + x.TotCusMed*x.TotQtd)/(pr.Qtd_Fisico+x.TotQtd)
                                  end
          From PRXES pr Inner Join 
               (Select ix.Cod_Estabe, ix.Cod_Produto, TotQtd=sum(ix.QtdTotNfe), TotCusMed=sum(ix.CusMedNfe)
                  From (Select it.Cod_Estabe, it.Cod_Cfo, it.Cod_Produto, 
                               QtdTotNfe = sum(it.Qtd_Pedido+it.Qtd_Bonificacao),
                               CusMedNfe = case 
                                             When ((cb.Cod_Cfo <> @KCfoBonEntInt) and (cb.Cod_Cfo <> @KCfoBonEntExt)) and  -- nao eh nf de bonificacao
                                                  ((it.Cod_Cfo = @KCfoBonEntInt) or (it.Cod_Cfo = @KCfoBonEntExt)) then 0
                                             Else case 
                                                    When IsNull(it.Vlr_DscIte2,0) > 0 then sum(it.Cus_LiqUni*it.Qtd_Pedido+it.Vlr_DscIte2)/sum(it.Qtd_Pedido+it.Qtd_Bonificacao)
                                                    Else sum(it.Cus_LiqUni*it.Qtd_Pedido)/sum(it.Qtd_Pedido+it.Qtd_Bonificacao)
                                                  end
                                           end
                          From NFECB cb Inner Join 
                               NFEIT it on ((cb.Cod_Estabe = it.Cod_Estabe) and (cb.Protocolo = it.Protocolo))
                         Where cb.Cod_Estabe = @CodEstabe
                           and cb.Protocolo = @NumPrt
                           and cb.Flg_AtuPrcCus = 1 and cb.Flg_MovEst = 1
                         Group by cb.Cod_Cfo, it.Cod_Estabe, it.Cod_Cfo, it.Cod_Produto, it.Vlr_DscIte2) ix
                 Group by ix.Cod_Estabe, ix.Cod_Produto) x ON pr.Cod_Estabe = x.Cod_Estabe And pr.Cod_Produt = x.Cod_Produto
        
        -- atualiza itens da nota   
        Update it
           Set it.Dat_Movimento = cb.Dat_Movimento,
               it.Transacao = @Now,
               it.Prc_CustoMedio = pr.Prc_CusMed,
               it.Prc_Venda = case 
                                When Isnull(it.Prc_Venda,0) = 0 then pr.Prc_Venda
                                else it.Prc_Venda
                              end,
               it.Prc_Fabric = case 
                                 When Isnull(it.Prc_Fabric,0) = 0 then pr.Prc_Fabric
                                 else it.Prc_Fabric
                               end,
               it.Prc_MaxCon = case 
                                 When Isnull(it.Prc_MaxCon,0) = 0 then pr.Prc_MaxCon
                                 else it.Prc_MaxCon
                               end
          From NFEIT it Inner Join 
               NFECB cb on ((it.Cod_Estabe = cb.Cod_Estabe) and (it.Protocolo = cb.Protocolo)) Inner Join 
               PRXES pr on it.Cod_Estabe = pr.Cod_Estabe and it.Cod_Produto = pr.Cod_Produt
         Where cb.Cod_Estabe = @CodEstabe 
           and cb.Protocolo = @NumPrt
          
        -- quando for o caso, acrescenta '#' na 1a. posicao do lote NFEIT e NELTL e NEIUM
        -- Estabelecimento - Ceara credenciado
        -- Fornecddor - regiao com termo de acordo no estado
        -- item marcado como estoque pago ST
        if (Upper(@em_CodEst) = 'CE') and (@CodUf = 'CE') and
             ((Select r.Flg_RegEspTrb From RGTRI r, ESTAB es Where es.Cod_Estabe = @CodEstabe and r.Cod_RegTri = es.Cod_RegTri) = 1) and
           ((Select Flg_RegEspTrb From RGTRI Where Cod_RegTri = @CodRegTri ) = 1)
          begin
            Update lt
               Set lt.Cod_Lote = '#'+Substring(lt.Cod_Lote,1,11)
              From NELTL lt Inner Join 
                   PRXES pr on (lt.Cod_Estabe = pr.Cod_Estabe and lt.Cod_Produt = pr.Cod_Produt) Inner Join 
                   NFEIT it on ((lt.Cod_Estabe = it.Cod_Estabe) and (lt.Num_Protoc = it.Protocolo) and (lt.Cod_Produt = it.Cod_Produto) and (lt.Cod_Lote = it.Cod_Lote))
             Where lt.Cod_Estabe = @CodEstabe 
               and lt.Num_Protoc = @NumPrt
               And IsNull(pr.Flg_RegSbtEsp,0) = 0
               And IsNull(it.Flg_RegEspTrb,0) = 1
               And Substring(lt.Cod_Lote,1,1) <> '#'
        
            Update it
               Set it.Cod_Lote = '#'+Substring(it.Cod_Lote,1,11)
              From NFEIT it Inner Join 
                   PRXES pr on (it.Cod_Estabe = pr.Cod_Estabe And it.Cod_Produto = pr.Cod_Produt)
             Where it.Cod_Estabe = @CodEstabe 
               and it.Protocolo = @NumPrt
               And IsNull(pr.Flg_RegSbtEsp,0) = 0
               And IsNull(it.Flg_RegEspTrb,0) = 1
               And Substring(it.Cod_Lote,1,1) <> '#'
          end
          
        -- Tem que ser Depois do PR_RegistraNEREF, para ter o vínculo
        Set @pc_Controle_Saldo = ''
        Select top 1 
               @pc_Controle_Saldo = pc.Controle_Saldo,
               @pc_FlgAcuVrbPos = pc.Flg_AcuVrbPos,
               @pc_FlgAcuVrbNeg = pc.Flg_AcuVrbNeg,
               @pc_FlgCtrPdvVrbVdr = pc.Flg_CtrPdvVrbVdr,
               @pc_FlgCtrPdvVrbOpe = pc.Flg_CtrPdvVrbOpe
          From NEREF r 
               Inner Join NFSCB cb on (r.Tip_EntSai = 'S' and 
                                       r.Cod_Estabe = cb.Cod_Estabe and 
                                       r.Ser_DocRef = cb.Ser_Nota and 
                                       r.Num_DocRef = cb.Num_Nota)
               Inner join POCOM pc on pc.Id_PolCom = cb.Id_PolCom
         Where r.Cod_Estabe = @CodEstabe
           And r.Protocolo = @NumPrt
	 
        -- recalcula verba fornecedor
        Exec PR_CalcVerbaNFE @CodEstabe, @NumPrt
        if @@error <> 0
          begin
            if @@trancount > 0
              RollBack Transaction
            Return
          end


        -- armazena NELTL em tabela temporaria
        if Exists(Select 1 From NELTL Where Cod_Estabe = @CodEstabe and Num_Protoc = @NumPrt)
          Insert Into #ARQ_NELTL
            Select Cod_Produt, Cod_Lote, Tip_Local, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Qtd_Est, Qtd_EmbFec
              From NELTL
             Where Cod_Estabe = @CodEstabe 
               and Num_Protoc = @NumPrt 

        -- dá entrada no estoque  Prc_Fabric, Prc_CustoMedio
        Declare Itens_Cr Cursor Local Fast_Forward For 
          Select it.Cod_Produto, it.Cod_Lote, it.Num_SeqIte, IsNull(it.Tip_Ent,''), it.Dat_Vencim, it.Dat_Fabric, 
		       it.Qtd_Pedido, it.Qtd_Bonificacao, it.Prc_Unitario, it.Cus_LiqUni, 
                 it.Vlr_LiqIte, it.Qtd_Promocao, IsNull(it.Vlr_VrbVdr,0), IsNull(it.Vlr_DscIte2,0),
			   (it.Qtd_Pedido+it.Qtd_Bonificacao)*IsNull(it.Prc_CustoMedio,0), 
                 (it.Qtd_Pedido+it.Qtd_Bonificacao)*IsNull(it.Prc_Fabric,0),
                 pr.Cod_Fabricante, IsNull(it.Vlr_VrbOpe,0), IsNull(it.Vlr_VrbSup,0)
            From NFEIT it 
                 Inner Join NFECB cb on ((it.Cod_Estabe = cb.Cod_Estabe) and (it.Protocolo = cb.Protocolo))
                 Inner Join PRODU pr on it.Cod_Produto = pr.Codigo
           Where cb.Cod_Estabe = @CodEstabe and cb.Protocolo = @NumPrt 
             and cb.Flg_MovEst = 1

        Open Itens_Cr
        Fetch Next From Itens_Cr Into @CodPrd, @CodLot, @NumSeqIte, @TipEnt, @DatVct, @DatFab, 
                                      @QtdPed, @QtdBon, @PrcUni, @CusLiqUni, 
                                      @ValLiq, @QtdPrm, @VlrVerbaVdr, @VlrVerbaFor,
                                      @ValCusMed, @ValPrcFab, @CodFab, @VlrVerbaOpe, @VlrVerbaSup
        While @@FETCH_STATUS = 0
          Begin
            -- qtd total a movimentar do item
            Set @QtdMov = @QtdPed + @QtdBon
          
            -- ver integracao ao WMS
            if @FlgWms = 0
              begin
                -- sem WMS: deposito unico
                Set @CodDep = IsNull((Select min(Cod_Dep) 
                                        From TBDEP 
                                       Where Cod_Estabe = @CodEstabe),1)

                -- se nao existir o lote, cria
                if not Exists(Select 1 From PRLOT Where Cod_Estabe = @CodEstabe and Cod_Dep = @CodDep and Cod_Produt = @CodPrd and Cod_Lote = @CodLot)
                  begin
                    Insert into PRLOT (Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote, Dat_Vencim, Dat_Fabric, Qtd_FisPra, Qtd_SolPra,Qtd_FisDep,Qtd_SolDep)
                               Values (@CodEstabe, @CodDep, @CodPrd, @CodLot, @DatVct, @DatFab, 0, 0, 0, 0)
                    if @@error <> 0
                      begin
                        if @@trancount > 0
                          RollBack Transaction
                        Return
                      end
                  end
                else
                  -- se for o caso atualiza o vencimento do lote existente
                  begin
                    Update PRLOT
                       Set Dat_Vencim = @DatVct,
                           Dat_Fabric = @DatFab
                     Where Cod_Estabe = @CodEstabe    
                       And Cod_Dep = @CodDep
                       And Cod_Produt = @CodPrd
                       And Cod_Lote = @CodLot
                       And ((Dat_Vencim is null) or (Dat_Vencim <> @DatVct) or 
                            (Dat_Fabric is null) or (Dat_Fabric <> @DatFab))
                  end           
            
                Set @QtdPra = 0
                Set @QtdDep = 0
                if @CodCfo > 0
                  Set @QtdPra = @QtdMov
                else
                  Set @QtdDep = @QtdMov  
                Exec PR_AtualizaSaldoEstoque 'NF', @CodEstabe, @CodDep, @CodPrd, @CodLot, @DatMov, 'E', @TipNfe, @QtdPra, 0, @QtdDep, 0
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      RollBack Transaction
                    Return
                  end

                -- reserva itens se for devolução simbolica de consignação
                if @FlgReservConsig = 1
                  begin
				 if @NumReserv = 0
                      begin
				     Set @NumReserv = IsNull((Select max(Numero) From RESER Where Cod_Estabe = @CodEstabe),0) + 1
                        Set @DesHisReserv = 'DEV.CONSIGNAÇÃO ;'+cast(@IdConsig as varchar)+';'+cast(@NumSeqCtr as varchar)+';'+cast(@NumSeqDev as varchar)+';' 
                      end

                    if Exists(Select 1 From RESER Where Cod_Estabe = @CodEstabe and Numero = @NumReserv and Cod_Produto = @CodPrd)
				   Set @NumReserv = IsNull((Select max(Numero) From RESER Where Cod_Estabe = @CodEstabe),0) + 1

                    -- registra reserva
                    Insert Into RESER (Cod_Estabe, Numero, Cod_Dep, Cod_Produto, Cod_Lote, Qtd_Movimento, Qtd_ResDep, Historico,
                                       Id_Consig, Num_SeqCtr, Num_SeqDev, Dat_Movimento, Usuario, Transacao)
                               Values (@CodEstabe, @NumReserv, @CodDep, @CodPrd, @CodLot, @QtdPra, @QtdDep, @DesHisReserv, 
                                       @IdConsig, @NumSeqCtr, @NumSeqDev, @Date, @Usuario, @Now)
                    if @@error <> 0
                      begin
                        if @@trancount > 0
                          RollBack Transaction
                        Return
                      end
                  end
           
              end  -- if @FlgWms = 0
            else
              begin
                -- selecionar até "quantidade" @QtdMov =  @QtdPed + @QtdBon
                -- entrada através de QtdPra e @QtdDep
                Set @QtdMovSld = @QtdMov
            
                While @QtdMovSld > 0
                  begin
            
                    Declare Lotes_Cr Cursor Local Fast_Forward For 
            
                      Select Chave, Tip_Loc, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Qtd_Lot, Qtd_EmbFec
                        From #ARQ_NELTL
                       Where Cod_Prd = @CodPrd
                         And Cod_Lot = @CodLot
                         And Qtd_Lot > 0
            
                    Open Lotes_Cr
                    Fetch Next From Lotes_Cr
                      Into @Chave, @TipLoc, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @QtdEst, @QtdEmbFec
                    
                    While (@@FETCH_STATUS = 0) and (@QtdMovSld > 0)
                      begin
                      
                        if @QtdEst > @QtdMovSld
                          Set @QtdEst = @QtdMovSld
                      
                        Set @QtdPra = 0
                        Set @QtdDep = 0
                        if @CodCfo > 0
                          Set @QtdPra = @QtdEst
                        else
                          Set @QtdDep = @QtdEst
                      
                        -- insere registros prlog
                        Exec PR_InserePRLOG @CodEstabe, @CodPrd, @CodLot, @CodDep, 
                                              @NumRua, @NumCol, @NumNiv, @NumApt,
                                              @QtdEst, @WCodOri, '', @NumPrt, '', '', @Usuario
                        if @@error <> 0
                          begin
                            if @@trancount > 0
                              RollBack Transaction
                            Return
                          end
                        
                        if Ltrim(Rtrim(@TipLoc)) = ''
                          Set @TipLoc = dbo.FN_TipLocEnd(@CodEstabe,@CodDep,@NumRua)
                        
                        if @TipLoc = 'P'   -- picking
                          begin
                            -- se nao existir o lote, cria
                            if not Exists(Select 1 From PRLOT Where Cod_Estabe = @CodEstabe and Cod_Dep = @CodDep and Cod_Produt = @CodPrd and Cod_Lote = @CodLot)
                              begin
                                Insert into PRLOT (Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote, Dat_Vencim, Dat_Fabric, Qtd_FisPra, Qtd_SolPra,Qtd_FisDep,Qtd_SolDep)
                                           Values (@CodEstabe, @CodDep, @CodPrd, @CodLot, @DatVct, @DatFab, 0, 0, 0, 0)
                                if @@error <> 0
                                  begin
                                    if @@trancount > 0
                                      RollBack Transaction
                                    Return
                                  end
                              end
                            else
                              -- se for o caso atualiza o vencimento do lote existente
                              begin
                                Update PRLOT
                                   Set Dat_Vencim = @DatVct,
                                       Dat_Fabric = @DatFab
                                 Where Cod_Estabe = @CodEstabe    
                                   And Cod_Dep = @CodDep
                                   And Cod_Produt = @CodPrd
                                   And Cod_Lote = @CodLot
                                   And ((Dat_Vencim is null) or (Dat_Vencim <> @DatVct) or 
                                        (Dat_Fabric is null) or (Dat_Fabric <> @DatFab))
                              end           
                              
                            -- atualiza mov em PRSLD e fisico em PRLOT e PRODU
                            Exec PR_AtualizaSaldoEstoque 'NF', @CodEstabe, @CodDep, @CodPrd, @CodLot, @DatMov, 'E', @TipNfe, @QtdPra, 0, @QtdDep, 0
                            if @@error <> 0
                              begin
                                if @@trancount > 0
                                  RollBack Transaction
                                Return
                              end
                          end
                        else
                          begin
                            -- elimina mesmo lote com saldo 0 e embalagem diferente
                            Delete From PRLTL
                              Where Cod_Estabe = @CodEstabe
                              And Cod_Produt = @CodPrd
                              And Cod_Lote = @CodLot
                              And Qtd_EmbFec <> @QtdEmbFec
                              And Qtd_Fisico = 0
                           
                            -- se nao existir o lote, cria
                            if not Exists(Select 1 From PRLTL 
                                           Where Cod_Estabe = @CodEstabe 
                           				   and Cod_Produt = @CodPrd 
                           				   and Cod_Lote = @CodLot 
                           				   and Qtd_EmbFec = @QtdEmbFec 
                           				   and Cod_Dep = @CodDep 
                           				   and Num_Rua = @NumRua and Num_Col = @NumCol 
                           				   and Num_Niv = @NumNiv and Num_Apt = @NumApt)
                              begin
                                Insert into PRLTL (Cod_Estabe, Cod_Produt, Cod_Lote, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Qtd_EmbFec, Dat_Vencim, Dat_Fabric, Dat_Entrada, Qtd_FisPra, Qtd_SolPra,Qtd_FisDep,Qtd_SolDep)
                                           Values (@CodEstabe, @CodPrd, @CodLot, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @QtdEmbFec, @DatVct, @DatFab, @DatMov, 0, 0, 0, 0)
                                if @@error <> 0
                                  begin
                                    if @@trancount > 0
                                      RollBack Transaction
                                    Return
                                  end
                              end
                             
                            Exec PR_AtualizaSaldoEstoqueGrosso @CodEstabe, @CodPrd, @CodLot, @QtdEmbFec, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @DatMov, 'E', @TipNfe, @QtdPra, 0, @QtdDep, 0
                            if @@error <> 0
                              begin
                                if @@trancount > 0
                                  RollBack Transaction
                                Return
                              end
                          end                       
                        
                        -- decrementa quantidade a movimentar
                        Update #ARQ_NELTL
                           Set Qtd_Lot = Qtd_Lot - (@QtdPra+@QtdDep)
                         Where Chave = @Chave
                        
                        Set @QtdMovSld = @QtdMovSld - (@QtdPra+@QtdDep)
                        
                        Fetch Next From Lotes_Cr
                         Into @Chave, @TipLoc, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @QtdEst, @QtdEmbFec
                         
                      end  -- While (@@FETCH_STATUS = 0) and (@QtdMovSld > 0)
                      
                    Close Lotes_Cr
                    Deallocate Lotes_Cr
            
                  end  -- While @QtdMovSld > 0
            
              end  -- if @FlgWms = 1
            
            -- da entrada na promocao
            if @QtdPrm > 0
              begin
                Select @CodPrm = Cod_Promocao From PRXES Where Cod_Estabe = @CodEstabe And Cod_Produt = @CodPrd
                if IsNull(@CodPrm,0) > 0
                  EXEC PR_GravaPrmMv @CodEstabe, @CodPrm, @CodPrd, @DatMov, 'C', '', @NumPrt, @QtdPrm
              end
            
            -- atualiza estatisticas de produtos 
            Exec PR_AcuEntNfeItePrd @CodEstabe, @TipNfe, @StaNfe, @CodPrd, @DatMov, @QtdMov, @ValLiq, @ValCusMed, @ValPrcFab
            if @@error <> 0
              begin
                if @@trancount > 0
                  RollBack Transaction
                Return
              end
          
            -- atualiza estatisticas de fabricantes 
            Exec PR_AcuEntNfeIteFor @CodEstabe, @TipNfe, @StaNfe, @CodPrd, @DatMov, @QtdMov, @ValLiq
            if @@error <> 0
              begin
                if @@trancount > 0
                  RollBack Transaction
                Return
              end

            -- atualiza estatisticas de clientes (devolução)
            if @CodEmiCli > 0
              begin
                Exec PR_AcuEntNfeIteCli @CodEstabe, @TipNfe, @StaNfe, @CodEmiCli, @DatMov, @QtdMov, @ValLiq
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      RollBack Transaction
                    Return
                  end
              end

            -- atualiza estatisticas de Vendedores (devolução)
            if @CodVdr > 0
              begin
                Exec PR_AcuEntNfeIteVen @CodEstabe, @TipNfe, @StaNfe, @CodVdr, @DatMov, @QtdMov, @ValLiq
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      RollBack Transaction
                    Return
                  end
              end

            -- atualiza verbas
            if (@TipNfe = 'D') and 
               ((@pc_Controle_Saldo = 'V') or (@pc_Controle_Saldo = 'F'))
              begin
                Set @DesMovime = 'DEVOLUCAO NF'

                -- atualiza verba vendedor
                if (@VlrVerbaVdr <> 0) and (IsNull(@CodVdr,0) > 0) 
                  begin
                    Set @VlrVerbaVdr = -@VlrVerbaVdr
                    if @pc_Controle_Saldo = 'V' -- Vendedor/Operador
                      Exec PR_AtualizaSaldoVBSLD @CodEstabe, @CodVdr,          @DatMov, 0, @CodPrd, @CodLot, @TipEnt, 'E', @TipNfe, '', @NumPrt, @VlrVerbaVdr, @DesMovime, @Usuario
                    else
                      Exec PR_AtualizaSaldoVBFSL @CodEstabe, @CodVdr, @CodFab, @DatMov, 0, @CodPrd, @CodLot, @TipEnt, 'E', @TipNfe, '', @NumPrt, @VlrVerbaVdr, @DesMovime, @Usuario
                    if (@@error <> 0)
                      begin
                        if @@trancount > 0
                          Rollback Transaction
                          Return
                      end
                  end
                 
                -- atualiza verba operador
                if (@VlrVerbaOpe <> 0) and (IsNull(@CodVdrTlmkt,0) > 0)
                  begin							  
                    Set @VlrVerbaOpe = -@VlrVerbaOpe
                    if @pc_Controle_Saldo = 'V' -- Vendedor/Operador
                      Exec PR_AtualizaSaldoVBSLD @CodEstabe, @CodVdrTlmkt,          @DatMov, 0, @CodPrd, @CodLot, @TipEnt, 'E', @TipNfe, '', @NumPrt, @VlrVerbaOpe, @DesMovime, @Usuario
                    else
                      Exec PR_AtualizaSaldoVBFSL @CodEstabe, @CodVdrTlmkt, @CodFab, @DatMov, 0, @CodPrd, @CodLot, @TipEnt, 'E', @TipNfe, '', @NumPrt, @VlrVerbaOpe, @DesMovime, @Usuario
                    if (@@error <> 0)
                      begin
                        if @@trancount > 0
                          Rollback Transaction
                        Return
                      end
                  end
                
                -- atualiza verba supervisor
                if (@VlrVerbaSup <> 0) and (IsNull(@CodSup,0) > 0)
                  begin
                    Set @VlrVerbaSup = -@VlrVerbaSup
                    Exec PR_AtualizaSaldoVBSSD @CodEstabe, @CodSup, @DatMov, 0, @CodPrd, @CodLot, @TipEnt, 'E', @TipNfe, '', @NumPrt, @VlrVerbaSup, @DesMovime, @Usuario
                    if (@@error <> 0)
                      begin
                        if @@trancount > 0
                          Rollback Transaction
                        Return
                      end
                end  
                 
              end  -- -- if (@TipNfe = 'D') and (@VlrVerbaVdr <> 0) and 


            -- atualiza verba fornecedor
            if (@VlrVerbaFor <> 0) and (@CodEmiFor > 0) 
              begin
                Set @DesMovime = 'ENTRADA NF'
                if @TipNfe = 'D'
                  begin
                    Set @VlrVerbaFor = -@VlrVerbaFor
                    Set @DesMovime = 'DEVOLUCAO NF'
                  end
                Exec PR_AtualizaSaldoVBFSD @CodEstabe, @CodEmiFor, @DatMov, 0, @CodPrd, @CodLot, 'E', @TipNfe, '', @NumPrt, @VlrVerbaFor, @DesMovime, @Usuario
                if (@@error <> 0)
                  begin
                    if @@trancount > 0
                      RollBack Transaction
                    Return
                  end
              end


          -- grava movimento relativo a devolução de consignação: CFOP: 
          if (@IdConsig > 0) and (@NumSeqCtr > 0) and (dbo.FN_CfopConsigValido(@CodCfo) = 1) 
            begin
              -- NDS = devolucaosimbolica : @FlgFaturaConsig = 1
              -- NDE = devolucao efetiva
              if @FlgFaturaConsig = 1 
                Set @CodTipDevCng = 'NDS'
              else
                Set @CodTipDevCng = 'NDE'

              Exec PR_GravaMovimeCNGMV @CodEstabe, @IdConsig, @CodPrd, @CodLot,
                                       @DatMov, 'E', @CodTipDevCng, '', @NumPrt, '', 'F', 
                                       @QtdMov, @PrcUni
              if (@@error <> 0)
                begin
                  if @@trancount > 0 
                    Rollback Transaction
                  Return
                end
            end

          -- atualiza TBIUM
            Insert Into TBIUM (Cod_Estabe, Cod_IUM, Cod_Produto, Cod_Lote, Cod_IUC)
              Select i1.Cod_Estabe, i1.Cod_IUM, i1.Cod_Produto, i1.Cod_Lote, i1.Cod_IUC
                From NEIUM i1 
                     Left Join TBIUM tb on i1.Cod_IUM = tb.Cod_IUM   
               Where i1.Cod_Estabe = @CodEstabe 
                 and i1.Protocolo = @NumPrt
                 And i1.Cod_Produto = @CodPrd
                 And i1.Cod_Lote = @CodLot 
                 And i1.Num_SeqIte = @NumSeqIte
                 And tb.Cod_IUM is null 
            if (@@error <> 0)
              begin
                if @@trancount > 0
                  RollBack Transaction
                Return
              end
               
            Update tb
               Set tb.Cod_Produto = i1.Cod_Produto,
                   tb.Cod_Lote = i1.Cod_Lote,
                   tb.Cod_IUC = i1.Cod_IUC
              From TBIUM tb Inner Join NEIUM i1 on tb.Cod_Estabe = i1.Cod_Estabe And tb.Cod_IUM = i1.Cod_IUM
             Where i1.Cod_Estabe = @CodEstabe 
               and i1.Protocolo = @NumPrt
               And i1.Cod_Produto = @CodPrd
               And i1.Cod_Lote = @CodLot 
               And i1.Num_SeqIte = @NumSeqIte
          
            Fetch Next From Itens_Cr Into @CodPrd, @CodLot, @NumSeqIte, @TipEnt, @DatVct, @DatFab, 
                                          @QtdPed, @QtdBon, @PrcUni, @CusLiqUni, 
                                          @ValLiq, @QtdPrm, @VlrVerbaVdr, @VlrVerbaFor,
                                          @ValCusMed, @ValPrcFab, @CodFab, @VlrVerbaOpe, @VlrVerbaSup
          end
        
        Close Itens_Cr
        Deallocate Itens_Cr
          
        -- atualiza estatistica do estabelecimento
        if @FlgMovEst = 1
          begin
            Exec PR_AcuEntNfeCabEmp @CodEstabe, @NumPrt, @TipNfe, @StaNfe, @DatMov
            if @@error <> 0
              begin
                if @@trancount > 0
                  RollBack Transaction
                Return
              end
          end
        
        Declare @WQtdIte int,
                @WQtdPgNf int,
                @WNumNot int,
                @WSerNot varchar(3),
                @WNumFor int,
                @WSerSel varchar(2),
                @WNumSel bigint,
                @WModNotFis varchar(2),
                @WCodStaNfe char(1),
                @nm_NotFis int,
                @nm_SerNotFis int,
                @nm_ModNotFis varchar(2),
                @fs_FlgOpcUsaCreLoj BIT = 0

        Select @fs_FlgOpcUsaCreLoj = ISNULL(Val_param, 0)  FROM fs_param WHERE Cod_Param = 'TRM_OPC_USACRELOJ'
  
        Set @WQtdPgNf = 0
        Set @WNumFor = 0
        Set @WSerSel = ''
        Set @WNumSel = 0
        Set @WModNotFis = @CodModDoc
        Set @WCodStaNfe = ''
        Set @WQtdIte = Isnull((Select count(*) From NFEIT Where Cod_Estabe = @CodEstabe and Protocolo = @NumPrt),0)
        
        -- verifica se é devolução total
        Set @SerNotSai = ''
        Set @NumNotSai = 0
        Set @ValDspEmb = 0

        if (@TipNfe = 'D') 
          begin
            Set @FlgDevTot = 0
	        Set @FlgDevChv = 0
	  
            Select top 1 @SerNotSai = Ser_DocRef, 
                         @NumNotSai = Num_DocRef
              From NEREF
             Where Cod_Estabe = @CodEstabe
               And Protocolo = @NumPrt
               And Tip_EntSai = 'S'

            Set @TipNfsRef = (Select IsNull(cb.Tip_Saida, '')
                                From NEREF r 
                                     Inner Join NFSCB cb on (r.Tip_EntSai = 'S' and 
                                                             r.Cod_Estabe = cb.Cod_Estabe and 
                                                             r.Ser_DocRef = cb.Ser_Nota and 
                                                             r.Num_DocRef = cb.Num_Nota)
                               Where r.Cod_Estabe = @CodEstabe
                                 And r.Protocolo = @NumPrt)

            --Alimenta variaveis a partir de devolução apenas com chave
            Select @FlgDevChv = Case When Isnull(cb.Chv_NotOri, '') <> '' Then 1 Else 0 End,
                   @TipNfsRef = 'S',
                   @SerNotSai = Substring(Chv_NotOri, 23, 3),
                   @NumNotSai = Substring(Chv_NotOri, 26, 9)
              From NFECB cb 
             Where cb.Cod_Estabe = @CodEstabe 
               And cb.Protocolo = @NumPrt
               And Isnull(cb.Chv_NotOri, '') <> ''

            if not Exists(Select e.Cod_Produto, s.Cod_Produto, e.QtdPrdEnt, s.QtdPrdSai
                            From (Select Cod_Produto, QtdPrdEnt=sum(Qtd_Pedido+Qtd_Bonificacao)
                                    From NFEIT
                                   Where Cod_Estabe = @CodEstabe
                                     And Protocolo = @NumPrt
                                   Group by Cod_Produto) e FULL OUTER JOIN
                                 (Select Cod_Produto, QtdPrdSai=sum(Qtd_Produto+Qtd_Bonificacao)
                                    From NFSIT
                                   Where Cod_Estabe = @CodEstabe
                                     And Ser_Nota = @SerNotSai
                                     And Num_Nota = @NumNotSai
                                   Group by Cod_Produto) s on (e.Cod_Produto = s.Cod_Produto)
                           Where IsNull(e.QtdPrdEnt,0) <> IsNull(s.QtdPrdSai,0))
              begin                         
                Set @FlgDevTot = 1
                Set @ValDspEmb = IsNull((Select sum(IsNull(cr.Vlr_DspEmb,0))
                                           From NEREF r Inner Join
                                                NFSCB cb on (r.Tip_EntSai = 'S' and r.Cod_Estabe = cb.Cod_Estabe and 
                                                             r.Ser_DocRef = cb.Ser_Nota and r.Num_DocRef = cb.Num_Nota) Inner Join
                                                CTREC cr on cr.Ser_NfOrigem = cb.Ser_Nota and cr.Num_NfOrigem = cb.Num_Nota and cb.Cod_Estabe = cr.Cod_Estabe
                                          Where r.Cod_Estabe = @CodEstabe
                                            And r.Protocolo = @NumPrt),0)
              end
          end

        if @FlgImpNot = 1
          begin
            if @pm_FlgNfe = 1 
              begin
                Update NMNFE     
                   Set Num_Nfe = Num_Nfe + 0
                 Where Cod_Estabe = @CodEstabe 
                   And Flg_Padrao = 1
         
                Select @nm_SerNotFis = Ser_Nfe,
                       @nm_NotFis = Num_Nfe,
                       @nm_ModNotFis = Mod_Nfe
                  From NMNFE
                 Where Cod_Estabe = @CodEstabe 
                   And Flg_Padrao = 1
         
                --  pega proximo numero da NF
                Set @WNumNot = @nm_NotFis+1
                Set @WSerNot = cast(@nm_SerNotFis as varchar)
                Set @WModNotFis = @nm_ModNotFis
                Set @WCodStaNfe = 'N'
         
                -- atualiza NMNFE
                Update NMNFE
                   Set Num_Nfe = @WNumNot
                 Where Cod_Estabe = @CodEstabe 
                   And Ser_Nfe = @nm_SerNotFis
              end
            else
              begin
                Update NMFIS
                   Set Nota_Fiscal_M1 = Nota_Fiscal_M1 + 0
                 Where Cod_Estabe = @CodEstabe
          
                Select @nm_NotFis = Nota_Fiscal_M1
                  From NMFIS
                 Where Cod_Estabe = @CodEstabe
          
                --  pega proximo numero da NF
                Set @WNumNot = @nm_NotFis+1
                Set @WSerNot = @pm_ModeloNotaFiscal   
                Set @WModNotFis = @pm_ModeloNotaFiscal
                Set @WCodStaNfe = ''
          
                Set @WQtdPgNf = 1
                if @WQtdIte > 0 and @pm_NumItePagNfs > 0
                  Set @WQtdPgNf = Ceiling(@WQtdIte*1.00 /@pm_NumItePagNfs)
                if @WQtdPgNf < 1
                  Set @WQtdPgNf = 1
                Set @WNumFor = @NumFrm + @WQtdPgNf - 1
          
                -- atualiza NMFIS
                if @pm_FlgCtrSelFis = 1
                  begin
                    Set @WSerSel = @pm_SerieSeloFiscal
                    Set @WNumSel = @NumSel + @WQtdPgNf - 1
                    Update NMFIS
                       Set Nota_Fiscal_M1 = @WNumNot,
                           Formulario_M1 = @WNumFor,
                           Selo_Fiscal = @WNumSel
                     Where Cod_Estabe = @CodEstabe    
                  end
                else
                  begin
                    Update NMFIS
                       Set Nota_Fiscal_M1 = @WNumNot,
                           Formulario_M1 = @WNumFor
                     Where Cod_Estabe = @CodEstabe    
                  end
              end
          
            Update NFECB
               Set Qtd_Itens = @WQtdIte,
                   Qtd_PagNf = @WQtdPgNf,
                   Serie = @WSerNot,
                   Numero = @WNumNot,
                   Num_Formulario = @WNumFor,
                   Ser_SeloFisTran = @WSerSel,
                   Num_SeloFisTran = @WNumSel,
                   Flg_DevTot = @FlgDevTot,
                   Cod_ModDoc = @WModNotFis, 
                   Cod_StaNfe =  @WCodStaNfe
             Where Cod_Estabe = @CodEstabe 
               and Protocolo = @NumPrt
          end
        else
          begin
            Update NFECB
               Set Qtd_Itens = @WQtdIte,
                   Qtd_PagNf = @WQtdPgNf,
                   Flg_DevTot = @FlgDevTot,
                   Cod_ModDoc = @WModNotFis, 
                   Cod_StaNfe =  @WCodStaNfe
             Where Cod_Estabe = @CodEstabe 
               and Protocolo = @NumPrt
          end
          
        -- atualiza status integracao WMS
        Update NFECB
           Set Sta_IntWMS = '3'
         Where Cod_Estabe = @CodEstabe 
           And Protocolo = @NumPrt
           And IsNull(Sta_IntWMS,'') <> ''
        
        -- atualiza CFOp dos itens
        if Exists(Select 1 From NFEIT 
                   Where Cod_Estabe = @CodEstabe and Protocolo = @NumPrt 
                     And IsNull(Cod_Cfo,0) = 0)
          begin
            Exec PR_AtualizaCFOpItemNf @CodEstabe, '', @NumPrt
            if @@error <> 0
              begin
                if @@trancount > 0
                  RollBack Transaction
                Return
              end
          end
        
        -- atualiza Cfop do cabecalho com o do item de maior valor
        if @WQtdIte > 0
          begin
            Exec PR_AtualizaCFOpNFECB @CodEstabe, @NumPrt
            if @@error <> 0
              begin
                if @@trancount > 0
                  RollBack Transaction
                Return
              end
          end
          
        -- ver se transfere saldos de PRSLD
        Exec PR_TransfEstNFE @CodEstabe, @NumPrt
        if @@error <> 0
          begin
            if @@trancount > 0
              RollBack Transaction
            Return
          end
        
        -- atualiza tipo de documento em PAGCT
        if Exists(Select Cod_CtaPag From PAGCT Where Cod_Estabe = @CodEstabe And Cod_PrtNfe = @NumPrt)
          begin
            While Exists(Select Cod_CtaPag From PAGCT 
                         Where Cod_Estabe = @CodEstabe And Cod_PrtNfe = @NumPrt And ISNULL(Id_Transacao,0) = 0)
              begin
                Select top 1 @WCodDoc = Cod_CtaPag 
                  From PAGCT 
                 Where Cod_Estabe = @CodEstabe And Cod_PrtNfe = @NumPrt And ISNULL(Id_Transacao,0) = 0
        
                EXEC PR_ProxNumeroEstab @CodEstabe, 'Id_Transacao', @IdTransacao output
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      RollBack Transaction
                    Return
                  end
        
                Update PAGCT
                   Set Id_Transacao = @IdTransacao
                 Where Cod_Estabe = @CodEstabe 
                   And Cod_CtaPag = @WCodDoc
             end
            
            -- tira da previsao em PAGCT 
            Update PAGCT
               Set Flg_Previs = 0
             Where Cod_Estabe = @CodEstabe
               And Cod_PrtNfe = @NumPrt
               And Flg_Previs = 1
         
            Update PAGCT
               Set Isn_CtaFin = @to_IsnCtaFinCre,
                   Dat_Registro = @DatMov,
                   Tip_Documento = case 
                                     When @CodCfo > 0 then 'DUP'
                                     else 'ORC'
                                   end
             Where Cod_Estabe = @CodEstabe
               And Cod_PrtNfe = @NumPrt
            
            if Exists(Select ct.Cod_CtaPag
                        From PAGCT ct Left Outer Join 
                             PCMOV mv on (ct.Id_Transacao = mv.Id_Transacao and 
                                          mv.Nom_Tabela = 'PAGCT' and 
                                          mv.Tip_Docume = 'PAG' and 
                                          ct.Cod_Estabe = mv.Cod_Estabe and 
                                          ct.Cod_CtaPag = mv.Num_Docume)
                       Where ct.Cod_PrtNfe = @NumPrt
                         And IsNull(ct.Id_Transacao,0) > 0     
                         And IsNull(ct.Isn_CtaFin,0) > 0
                         And mv.Id_Transacao is null)
              begin
                Update PAGCT
                   Set Val_Docume = Val_Docume + 0.01
                 Where Cod_Estabe = @CodEstabe 
                   And Cod_PrtNfe = @NumPrt
                  
                Update PAGCT
                   Set Val_Docume = Val_Docume - 0.01
                 Where Cod_Estabe = @CodEstabe 
                   And Cod_PrtNfe = @NumPrt
              end
              
            Update rt 
               Set rt.Isn_CtaFin = @to_IsnCtaFinDeb
              From PAGRT rt Inner Join PAGCT ct on (rt.Cod_Estabe = ct.Cod_Estabe and rt.Cod_CtaPag = ct.Cod_CtaPag)
             Where ct.Cod_Estabe = @CodEstabe 
               And ct.Cod_PrtNfe = @NumPrt
               And IsNull(rt.Isn_CtaFin,0) = 0
          
            if Exists(Select rt.Cod_CtaPag
                        From PAGCT ct Inner Join
                             PAGRT rt on ct.Cod_Estabe = rt.Cod_Estabe and ct.Cod_CtaPag = rt.Cod_CtaPag Left Outer Join 
                             PCMOV mv on (ct.Id_Transacao = mv.Id_Transacao and 
                                          mv.Nom_Tabela = 'PAGRT' and 
                                          mv.Tip_Docume = 'PAG' and 
                                          ct.Cod_Estabe = mv.Cod_Estabe and 
                                          ct.Cod_CtaPag = mv.Num_Docume)
                       Where ct.Cod_Estabe = @CodEstabe 
                         And ct.Cod_PrtNfe = @NumPrt
                         And IsNull(ct.Id_Transacao,0) > 0     
                         And IsNull(ct.Isn_CtaFin,0) > 0
                         And mv.Id_Transacao is null)
              begin
                Update rt
                   Set rt.Val_DocRat = rt.Val_DocRat + 0.01
                  From PAGRT rt Inner Join
                       PAGCT ct on rt.Cod_Estabe = ct.Cod_Estabe And rt.Cod_CtaPag = ct.Cod_CtaPag
                 Where ct.Cod_Estabe = @CodEstabe
                   And ct.Cod_PrtNfe = @NumPrt
                
                Update rt
                   Set rt.Val_DocRat = rt.Val_DocRat - 0.01
                  From PAGRT rt Inner Join
                       PAGCT ct on rt.Cod_Estabe = ct.Cod_Estabe and rt.Cod_CtaPag = ct.Cod_CtaPag
                 Where ct.Cod_Estabe = @CodEstabe 
                   And ct.Cod_PrtNfe = @NumPrt
              end
          
          end
        else
        -- ver se cria vales (devolucao). { (@TipNfsRef <> 'T') Para não gerar vales de uma Nota que sua origem é uma nota de transferência }
        if ( (@SerNot <> 'ECF') and 
		     (@TipNfe = 'D') and (@FlgMovEst = 1) and (@TipNfsRef <> 'T') and 
		     ((@CodEmiFor > 0) or (@CodEmiCli > 0) or (@CodEmiTra > 0)) ) AND
		   ( (@fs_FlgOpcUsaCreLoj = 0) or ((@fs_FlgOpcUsaCreLoj = 1) and (@SerNotSai <> 'ECF')) )
          begin
            if (@FlgDevTot = 1) and (@pm_FlgManDupDevTotVen = 0) and
               (not Exists(Select 1
			               From CTREC
                            Where Cod_Estabe = @CodEstabe     
                              And Ser_NfOrigem = @SerNotSai 
                              and Num_NfOrigem = @NumNotSai 
                              and Status <> 'A')) and
               (not Exists(Select 1
			               From BXREC bx Inner Join 
						        CTREC cr on bx.Cod_Estabe = cr.Cod_Estabe and bx.Cod_Documento = cr.Cod_Documento
                            Where cr.Cod_Estabe = @CodEstabe     
                              And cr.Ser_NfOrigem = @SerNotSai 
                              and cr.Num_NfOrigem = @NumNotSai))
              begin
                -- cancela os titulos
                Exec PR_CancelaDevolveTitulosCTREC @CodEstabe, @SerNotSai, @NumNotSai, @Usuario, 'D', @WIsnCtaFinEntid, @to_IsnCtaFinDeb
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      RollBack Transaction
                    Return
                  end
              end
            else
              begin
                if @CodEmiFor > 0
                  begin
                    Set @TipEmi = 'FOR'
                    Set @CodEmi = @CodEmiFor
                  end
                else
                if @CodEmiCli > 0
                  begin
                    Set @TipEmi = 'CLI'
                    Set @CodEmi = @CodEmiCli
                  end
                else
                if @CodEmiTra > 0
                  begin
                    Set @TipEmi = 'TRA'
                    Set @CodEmi = @CodEmiTra
                  end
          
                -- Parametro: Creditos a conceder
                if @pm_FlgUsaInterv = 1
                  Set @to_IsnCtaFinCre = (Select pm.IsnCtaFinDespVal 
                                            From PMFIN pm Inner Join
                                                 PCFIN pc on pm.IsnCtaFinDespVal  = pc.Isn_CtaFin
                                           Where pc.Tip_CtaFin = 'A')
             
                EXEC PR_ProxNumero 'Vale', @WCodDoc output
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      RollBack Transaction
                    Return
                  end
                
                -- inclui vale
                Insert into VALES
                  (Cod_Estabe, Cod_Vale, Des_Vale, Tip_Entid, Cod_Entid, Dat_Emissa, Val_Vale, Vlr_DspEmb, Deb_Cre, 
                   Cod_CtrLanAut, Num_CtrLanAut, Isn_CtaFinEntid, Isn_CtaFinDeb, Isn_CtaFinCre, Usuario, Transacao)
                Values
                  (@CodEstabe, @WCodDoc,'NFE Devolucao Protocolo: '+cast(@NumPrt as varchar), @TipEmi, @CodEmi, @DatMov, @ValNot+@ValDspEmb, @ValDspEmb, 'C',
                   'DNE', @NumPrt, @WIsnCtaFinEntid, @to_IsnCtaFinDeb, @to_IsnCtaFinCre, @Usuario, @Now)
              end
          end
        else
          begin
            -- lancamentos gerenciais
            Set @ValNot = (Select Vlr_Nota From NFECB Where Cod_Estabe = @CodEstabe and Protocolo = @NumPrt)
            Set @IdTransacao = (Select Id_Transacao From NFECB Where Cod_Estabe = @CodEstabe and Protocolo = @NumPrt)
            
            if @IdTransacao = 0     
              begin
                EXEC PR_ProxNumeroEstab @CodEstabe, 'Id_Transacao', @IdTransacao output
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      RollBack Transaction
                    Return
                  end
        
                Update NFECB
                   Set Id_Transacao = @IdTransacao
                 Where Cod_Estabe = @CodEstabe 
                   And Protocolo = @NumPrt 
              end
              
            -- inclui conta credora
            if @to_IsnCtaFinCre > 0
              begin
                Exec PR_AtualizaPCMOV 'I', @CodEstabe, @to_IsnCtaFinCre, @DatMov, 'NFECB', 'NFE', '', @NumPrt, 0, @IdTransacao, @ValNot
              end
        
            -- inclui conta devedora
            if @to_IsnCtaFinDeb > 0
              begin
                Set @ValNot = -@ValNot
                Exec PR_AtualizaPCMOV 'I', @CodEstabe, @to_IsnCtaFinDeb, @DatMov, 'NFECB', 'NFE', '', @NumPrt, 0, @IdTransacao, @ValNot
              end
          end


        -- ATENCAO: o fechamento do pedido era feito no módulo servidor por causa da rotina de geração de previsões: 05/09/2015
        -- fecha pedidos de compras relacionados
        -- pedido de compra atualizado se na NF atual a Flg_MovEst = 1
        if @FlgMovEst = 1
          begin
            if Exists(Select 1 From NFEPC Where Cod_Estabe = @CodEstabe and Protocolo = @NumPrt)
              begin
                -- registra data da entrada da nota no pedido de compra
                Update p
                   Set p.Dat_Entrada = @DatMov
                  From NFEPC n
                       Inner Join PDCCB p on n.Cod_Estabe = p.Cod_Estabe and n.Cod_Pedido = p.Numero
                 Where n.Cod_Estabe = @CodEstabe
                   And n.Protocolo = @NumPrt
       
                Declare Nfepc_Cr Cursor Local Fast_Forward For 
                  Select n.Cod_Pedido
                    From NFEPC n
                         Inner Join PDCCB p on n.Cod_Estabe = p.Cod_Estabe and n.Cod_Pedido = p.Numero
                   Where n.Cod_Estabe = @CodEstabe
                     And n.Protocolo = @NumPrt
	      	   And p.Status <> 'F'
              end
            else
              begin
                -- registra data da entrada da nota no pedido de compra
                Update p
                   Set p.Dat_Entrada = @DatMov
                  From NFEPC n
                       Inner Join PDCCB p on n.Cod_Estabe = p.Cod_Estabe and n.Cod_Pedido = p.Numero
                 Where n.Cod_Estabe = @CodEstabe
                   And n.Protocolo = @NumPrtVincOpeVdo
         
                Declare Nfepc_Cr Cursor Local Fast_Forward For 
                  Select n.Cod_Pedido
                    From NFEPC n
	      	       Inner Join PDCCB p on n.Cod_Estabe = p.Cod_Estabe and n.Cod_Pedido = p.Numero
                   Where n.Cod_Estabe = @CodEstabe
                     And n.Protocolo = @NumPrtVincOpeVdo
	      	   And p.Status <> 'F'
              end
            Open Nfepc_Cr
            Fetch Next From Nfepc_Cr Into @NumPed
            While @@FETCH_STATUS = 0
              begin
                -- aqui ao reabrir, Qtd_Fatura ficou = 0
                -- fechar com @NumPrt = 0
                -- Exec PR_FechaPDC @CodEstabe, @NumPed, @NumPrt
                Exec PR_FechaPDC @CodEstabe, @NumPed, 0
         
                Fetch Next From Nfepc_Cr Into @NumPed
              end
            Close Nfepc_Cr
            Deallocate Nfepc_Cr
          end  -- @FlgMovEst = 1

        -- calcula prazo medio de compra ???????
        -- DMD-6717: Análise e ajuste na informação de prazo médio de compra no relatório "Prazo Médio de Compras".	
		Update cb
           Set Qtd_PrzMed = Case
                              When cb.Tip_NF = 'C' Then IsNull(pg.QtdPrzMed,0)
                              Else 0
                            End
          From NFECB cb
               Left Join (Select Cod_Estabe, Cod_PrtNfe, 
                                 QtdPrzMed = sum(DATEDIFF(day, Dat_Emissa, Dat_Vencim)) / 
                                             (select count( cod_prtnfe) from pagct where Cod_Estabe = @CodEstabe and Cod_PrtNfe = @NumPrt)
                            from PAGCT
                           Where IsNull(Cod_PrtNfe,0) > 0
                             And IsNull(Dat_Vencim,0) >= IsNull(Dat_Emissa,0)
                           Group by Cod_Estabe, Cod_PrtNfe) pg on cb.Cod_Estabe = pg.Cod_Estabe and cb.Protocolo = pg.Cod_PrtNfe
         Where cb.Cod_Estabe = @CodEstabe 
           And cb.Protocolo = @NumPrt;


        -- cancela estoque pulmão (notas abertas importadas xml aguardando fechamento)
        Exec PR_ManutencaoEstoquePulmao @CodEstabe, @NumPrt
        if @@error <> 0
          begin
            if @@trancount > 0
              RollBack Transaction
            Return
          end
       
        -- importa pedidos desconsolidados se for o caso
        if @IdPdvCon > 0
          begin
            -- 'A': Altera todos os preços (Pr.Cadastro-Desc.Autom)
            Exec PR_GeraPedidosDesconsolidados @IdPdvCon, ''
            if @@error <> 0
              begin
                if @@trancount > 0
                  RollBack Transaction
                Return
              end
          end

        -- atualiza itens na tabela de consignações
        if (@IdConsig > 0) and (@NumSeqCtr > 0)
          begin
            Exec PR_FaturaConsignacao 'E', @CodEstabe, '', @NumPrt, @IdConsig, @NumSeqCtr
            if (@@error <> 0)
              begin
                if @@trancount > 0
                  Rollback Transaction
                Return
              end
          end

        -- fatura consignação
        if @FlgFaturaConsig = 1
          begin
            Set @CodOpeSai = (Select top 1 Cod_Ope From TPOPE 
                               Where Tip_EntSai = 'S' 
                                 and CharIndex(cast(Cod_CfoNorInt as varchar),';5112;5114;') > 0 
                                 and CharIndex(cast(Cod_CfoNorExt as varchar),';6112;6114;') > 0
                                 and Tip_Ope = 'V' and IsNull(Flg_Bloqueado,0) = 0)

            Exec PR_GeraNfsFatConsig @CodEstabe, @NumPrt, @CodOpeSai, @SerNotSai output, @NumNotSai output, @MsgErr output
            if @@error <> 0
              begin
                if @@trancount > 0
                  RollBack Transaction
                Return
              end
          end

      end  -- if @FlgPodeFechar = 1

    IF OBJECT_ID('tempdb..#ARQ_NELTL') IS NOT NULL
      DROP TABLE #ARQ_NELTL

    if @@trancount > 0          
      Commit Transaction   
  END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_FechaNFS]
@PCodEstabe int,
@PSerNot varchar(3),
@PNumNot int,
@PNumSel bigint,
@PNumFrm int

AS

SET ANSI_WARNINGS OFF
SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(GetDate() as Date)

if (Select Status From NFSCB Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota  = @PNumNot) = 'F'
  begin
    RAISERROR('Nota Fiscal já fechada',16,1)
    Return
  end
else
  begin

    -- pegar dados de venda de consignação
    Declare @ns_CodCfo int = 0,
            @ns_CodDep smallint = 0,
            @ns_FlgBlqTrfEstFis bit = 0,
	        @ns_IdConsig int = 0,
            @ns_NumSeqCtr smallint = 0, 
            @ns_NumSeqDev smallint = 0,
            @FlgOpeVdo bit = 0,          -- indica op.triangular, venda à ordem
            @IdOpeVdo int = 0,               -- id da op.triangular
            @SerNotVincOpeVdo varchar(3) = '',
            @NumNotVincOpeVdo int = 0,
            @FlgDevolOpeVdo bit = 0,     -- indica se é devolução op.triangular
            @FlgErr bit = 0,
            @MsgErr varchar(8000) = '',
    		@MsgAlerta varchar(100) = ''
    
    Select @ns_CodCfo = IsNull(ns.Cod_Cfo1,0),
           @ns_CodDep = Case 
                          When IsNull(ns.Cod_DepMovEst,0) = 0 then 
                            IsNull((Select min(Cod_Dep) From TBDEP Where Cod_Estabe = @PCodEstabe),1) 
                          Else IsNull(ns.Cod_DepMovEst,0)
                        End,
           @ns_FlgBlqTrfEstFis = IsNull(cf.Flg_BlqTrfEstFis,0),
	       @ns_IdConsig  = ns.Id_Consig,
           @ns_NumSeqCtr = ns.Num_SequenciaCtr, 
           @ns_NumSeqDev = ns.Num_SeqDev,
           @FlgOpeVdo = IsNull(op.Flg_OpeVdo,0)
      From NFSCB ns
           Left Join TPOPE op on ns.Cod_Ope = op.Cod_Ope
           Left Join TBCFO cf on ns.Cod_Cfo1 = cf.Codigo 
     Where ns.Cod_Estabe = @PCodEstabe
       And Ser_Nota = @PSerNot
       And Num_Nota = @PNumNot

    if CharIndex(cast(@ns_CodCfo as varchar),';5112;5114;6112;6114;') = 0 
      begin
        Set @ns_IdConsig  = 0
        Set @ns_NumSeqCtr = 0
        Set @ns_NumSeqDev = 0
      end

    if Exists(Select it.Num_SeqIte, it.Cod_Produto, it.Cod_Lote, lf.Num_Rua, lf.Num_Col, lf.Num_Niv, lf.Num_Apt, 
                     QtdPed = IsNull(it.Qtd_Produto,0)+ISNULL(it.Qtd_Bonificacao,0), 
                     QtdLot = IsNull(lt.Qtd_Saldo,0) 
              From NFSCB cb Inner Join 
                   NFSIT it on ((cb.Cod_Estabe = it.Cod_Estabe) and (cb.Ser_Nota = it.Ser_Nota) and (cb.Num_Nota = it.Num_Nota)) Left Outer Join 
                   NFSLT lf on it.Cod_Estabe = lf.Cod_Estabe and it.Ser_Nota = lf.Ser_Nota and it.Num_Nota = lf.Num_Nota and 
                               it.Cod_Produto = lf.Cod_Produto and it.Cod_Lote = lf.Cod_Lote and it.Num_SeqIte = lf.Num_SeqIte Left Outer Join 
                   PRLTL lt on lf.Cod_Estabe = lt.Cod_Estabe and lf.Cod_Produto = lt.Cod_Produt and lf.Cod_Lote = lt.Cod_Lote and lf.Cod_Dep = lt.Cod_Dep and 
                               lf.Num_Rua = lt.Num_Rua and lf.Num_Col = lt.Num_Col and lf.Num_Niv = lt.Num_Niv and lf.Num_Apt = lt.Num_Apt 
              Where cb.Cod_Estabe = @PCodEstabe 
              and cb.Ser_Nota = @PSerNot 
              and cb.Num_Nota = @PNumNot 
              and ISNULL(cb.Flg_MovEst,0) = 1
              And ISNULL(cb.Flg_WMS,0) = 1
              And (ISNULL(it.Qtd_Produto,0)+ISNULL(it.Qtd_Bonificacao,0)) > ISNULL(lt.Qtd_Saldo,0)) 
      begin
        Set @FlgErr = 1
        Set @MsgErr = 'Estoque(Armazenagem) insuficente de lote de Produto para completar a operação'
      end

    if Exists(Select it.Cod_Produto, it.Cod_Lote, IsNull(lt.Qtd_Saldo,0) as QtdSldLot, 
                     Sum(IsNull(it.Qtd_Produto,0)+IsNull(it.Qtd_Bonificacao,0)) as QtdTot 
              From NFSCB cb Inner Join 
                   NFSIT it on ((cb.Cod_Estabe = it.Cod_Estabe) and (cb.Ser_Nota = it.Ser_Nota) and (cb.Num_Nota = it.Num_Nota)) Left Outer Join 
                   (Select l1.Cod_Estabe, l1.Cod_Produt, l1.Cod_Lote, Qtd_Saldo=sum(l1.Qtd_Saldo)
                     From (Select Cod_Estabe, Cod_Produt, Cod_Lote, Qtd_Saldo
                             From PRLOT
                            Where Cod_Estabe = @PCodEstabe
                              And Cod_Dep = @ns_CodDep
                              And Qtd_Saldo > 0
                           UNION ALL
                           Select Cod_Estabe, Cod_Produt = Cod_Produto, Cod_Lote, Qtd_Saldo=IsNull(Qtd_Movimento,0)+IsNull(Qtd_ResDep,0)
                             From RESER 
                            Where Cod_Estabe = @PCodEstabe
                              And @ns_IdConsig > 0
                              And IsNull(Id_Consig,0)  = @ns_IdConsig
                              And IsNull(Num_SeqCtr,0) = @ns_NumSeqCtr
                              And IsNull(Num_SeqDev,0) = @ns_NumSeqDev  
                          ) l1
                    Group by l1.Cod_Estabe, l1.Cod_Produt, l1.Cod_Lote) lt on ((it.Cod_Estabe = lt.Cod_Estabe) and (it.Cod_Produto = lt.Cod_Produt) and (it.Cod_Lote = lt.Cod_Lote))
              Where cb.Cod_Estabe = @PCodEstabe 
              and cb.Ser_Nota = @PSerNot 
              and cb.Num_Nota = @PNumNot 
              and ISNULL(cb.Flg_MovEst,0) = 1
              and ISNULL(cb.Flg_WMS,0) = 0
              Group by it.Cod_Produto, it.Cod_Lote, lt.Qtd_Saldo
              Having Sum(IsNull(it.Qtd_Produto,0)+IsNull(it.Qtd_Bonificacao,0)) > IsNull(lt.Qtd_Saldo,0)) 
      begin
        Set @FlgErr = 1
        Set @MsgErr = 'Estoque(Picking) insuficente de lote de Produto para completar a operação'
      end

    -- critica op.triangular
    if @FlgOpeVdo = 1				
      begin
        Exec PR_CriticaOperacaoTriangular @PCodEstabe, @PNumNot, @PSerNot, 'S', @MsgAlerta output, @MsgErr output
		if @MsgErr <> ''
          Set @FlgErr = 1
      end


    if @FlgErr = 1
      begin
        RAISERROR(@MsgErr,16,1)
        Return
      end
    else 
    BEGIN
      Begin Transaction
      -- bloqueia cab da nota
      Update NFSCB 
         Set Qtd_Itens = 0,
             Qtd_PagNf = 0
       Where Cod_Estabe = @PCodEstabe 
         and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
  
      -- variaveis de campos do cabecalho
      Declare @PDatEmi smalldatetime,
              @cb_TipSai varchar(1),
              @cb_StaNot varchar(1),
              @cb_CodRegTri int,
              @cb_CodOpe varchar(3),
              @cb_CodCli int,
              @cb_CodFun int,
              @cb_CodFor int,
              @cb_CodVdr int,
              @cb_CodCfo int,
              @cb_ValNot numeric(18,4),
              @cb_FlgMovEst bit,
              @cb_FlgWMS bit,
              @cb_IdTransacao int,

              @cb_CodCliDevVdo int = 0,
              @cb_CodFunDevVdo int = 0,
              @cb_CodForDevVdo int = 0,
              @cb_CodTraDevVdo int = 0,
              @cb_NumPrtDevVdo int = 0,
              @cb_NumPrtDevVnc int = 0,
              @cb_IdOpeVdoDev  int = 0,

              @WCodDoc int,
              @WValMov numeric(18,4),
              @WCodEmiFor int,
              @WValVrbFor numeric(18,4),
              @WFlgOpeInt bit,
              @Usuario varchar(15)
  
      Select @PDatEmi = @Date,
             @cb_TipSai = cb.Tip_Saida,
             @cb_StaNot = cb.Status,
             @cb_CodRegTri = IsNull(cb.Cod_RegTri,0),
             @cb_CodOpe = IsNull(cb.Cod_Ope,''),
             @cb_CodCli = IsNull(cb.Cod_Cliente,0),
             @cb_CodFun = IsNull(cb.Cod_Funcionario,0),
             @cb_CodFor = IsNull(cb.Cod_Fornecedor,0),
             @cb_CodVdr = IsNull(cb.Cod_Vendedor,0),
             @cb_CodCfo = Isnull(cb.Cod_Cfo1,0),
             @cb_ValNot = IsNull(cb.Vlr_TotalNota,0),
             @cb_FlgMovEst = IsNull(cb.Flg_MovEst,0),
             @cb_FlgWMS = IsNull(cb.Flg_WMS,0),
             @cb_IdTransacao = IsNull(cb.Id_Transacao,0)
        From NFSCB cb
       Where cb.Cod_Estabe = @PCodEstabe 
         and cb.Ser_Nota = @PSerNot 
         and cb.Num_Nota = @PNumNot
  
      Set @Usuario = dbo.FN_UsuarioInfarma()

      -- registra documentos relacionados
      Exec PR_RegistraNSREF @PCodEstabe, @PSerNot, @PNumNot
      if @@error <> 0
        begin
          if @@trancount > 0 
            Rollback Transaction
          Return
        end

      if @FlgOpeVdo = 1
        Exec PR_IncluiOPVDO @PCodEstabe, @PNumNot, @PSerNot, 'S', @IdOpeVdo output

      Set @cb_CodCliDevVdo = 0
      Set @cb_CodForDevVdo = 0
      Set @cb_CodFunDevVdo = 0
      Set @cb_CodTraDevVdo = 0

      if @IdOpeVdo > 0
        Select top 1 
               @SerNotVincOpeVdo = IsNull(rf.Ser_DocRef,0),
               @NumNotVincOpeVdo = IsNull(rf.Num_DocRef,0),
               @FlgDevolOpeVdo   = Case
                                     When cb.Tip_Saida  = 'D' then 1
                                     When cbv.Tip_Saida = 'D' then 1
                                     Else 0
                                   End,
               @cb_CodCliDevVdo  = Case 
                                     When cbv.Tip_Saida = 'D' then IsNull(cbv.Cod_Cliente,0) 
                                     Else 0
                                   End,
               @cb_CodFunDevVdo  = Case 
                                     When cbv.Tip_Saida = 'D' then IsNull(cbv.Cod_Funcionario,0)
                                     Else 0
                                   End,
               @cb_CodForDevVdo  = Case 
                                     When cbv.Tip_Saida = 'D' then IsNull(cbv.Cod_Fornecedor,0)
                                     Else 0
                                   End
          From NFSCB cb
               inner Join NSREF rf  on cb.Cod_Estabe = rf.Cod_Estabe
                                   and cb.Ser_Nota = rf.Ser_Nota 
                                   and cb.Num_Nota = rf.Num_Nota 
                                   and rf.Tip_EntSai = 'S' 
               inner Join NFSCB cbv on cbv.Cod_Estabe = rf.Cod_Estabe
                                   and cbv.Ser_Nota = rf.Ser_DocRef
                                   and cbv.Num_Nota = rf.Num_DocRef
         Where cb.Cod_Estabe = @PCodEstabe
           And cb.Ser_Nota = @PSerNot
           And cb.Num_Nota = @PNumNot

      Declare @cl_CodEst varchar(2),
  	          @cl_TipCon char(1),
              @uf_FlgRegSubTri bit,
              @Uf_BlqInsEstSbtNfs bit,
              @uf_NumInscriSbt varchar(15),
              @em_CodEst varchar(2),
              @pm_NumItePagNfs int,
              @pm_FlgCtrSelFis bit
  
      Select @cl_CodEst = Cod_Estado,
             @cl_TipCon = Tipo_Consumidor
        From CLIEN
       Where Codigo = @cb_CodCli
  
      if @cl_TipCon is null Set @cl_TipCon = '?'
  
      Select @em_CodEst = Des_Estado
        From ESTAB
       Where Cod_Estabe = @PCodEstabe
  
      Select @pm_NumItePagNfs = Isnull(NumItePagNfs,0),
             @pm_FlgCtrSelFis = FlgCtrSelFis
        From PARAM
       Where Cod_Estabe = @PCodEstabe
  
      -- operacao interna ou externa
      if @cl_CodEst = @em_CodEst
        Set @WFlgOpeInt = 1
      else
        Set @WFlgOpeInt = 0
  
      -- coloca campos de UFXES na memoria
      Select @uf_FlgRegSubTri = IsNull(Flg_RegSubTri,0),
             @Uf_BlqInsEstSbtNfs = IsNull(Flg_BlqNumInscriSubTriNfs,0),
             @uf_NumInscriSbt = case 
                                  when (IsNull(Num_InscriSubTri,'') <> '.') and (IsNull(Num_InscriSubTri,'') <> '')  then IsNull(Num_InscriSubTri,'')
                                  else ''
                                end
        From UFXES
       Where Cod_Estabe = @PCodEstabe
         And Cod_UF = @cl_CodEst
  
      if @uf_FlgRegSubTri is null Set @uf_FlgRegSubTri = 0
      if @Uf_BlqInsEstSbtNfs is null Set @Uf_BlqInsEstSbtNfs = 0
      if @uf_NumInscriSbt is null Set @uf_NumInscriSbt = ''
  
      -- coloca campos de RGTRI na memoria
      Declare @rt_FlgDscIcmOrgPub bit,
              @rt_FlgDscIcmOrgPubAcr bit
  
      Select @rt_FlgDscIcmOrgPub = IsNull(Flg_DscIcmOrgPub,0),
             @rt_FlgDscIcmOrgPubAcr = IsNull(Flg_DscIcmOrgPubAcr,0)
        From RGTRI
       Where Cod_RegTri = @cb_CodRegTri
  
      if @rt_FlgDscIcmOrgPub is null
        Set @rt_FlgDscIcmOrgPub = 0
      if @rt_FlgDscIcmOrgPubAcr is null
        Set @rt_FlgDscIcmOrgPubAcr = 0


      Declare @WQtdMov int,
              @WQtdAcc int,
              @PQtdIte int,
              @PQtdPgNf int,
              @PNumInscriSbtEmiUfd varchar(15)
  
      Set @PQtdIte = 0
      Set @PQtdPgNf = 1
  	Set @PNumInscriSbtEmiUfd = ''
  
      Declare @it_CodPrd int,
              @it_CodLot varchar(20),
              @it_SeqIte int, 
              @it_TipSai varchar(1),
              @it_QtdPrd int,
              @it_QtdBon int,
              @it_PrcUni numeric(18,8),
              @PQtdPra int,
              @PQtdDep int,
              @lt_QtdSldPra int,
              @lt_QtdSldDep int,
              @lt_CodDep smallint,
              @lt_NumRua smallint,
              @lt_NumCol smallint,
              @lt_NumNiv smallint,
              @lt_NumApt smallint,
              @lt_QtdEmbFec int,
  
              @WQtdDep int,
              @WQtdPra int,
              @WQtdTot int,
              @WFlgEmpPra bit,
              @WFlgEmpDep bit,
              @WCodOri varchar(20),
              @WCodTipSaiCng varchar(3)
              
      -- normaliza fator de conversao      
      Update NFSIT
         Set Fat_CnvImpFat = 1
       Where Cod_Estabe = @PCodEstabe
         And Ser_Nota = @PSerNot
         And Num_Nota = @PNumNot
         And ISNULL(Fat_CnvImpFat,0) = 0 
          
      Update NFSIT
         Set Qtd_ImpFat = Cast(Qtd_Produto+Qtd_Bonificacao as numeric(18,4))/Fat_CnvImpFat
       Where Cod_Estabe = @PCodEstabe
         And Ser_Nota = @PSerNot
         And Num_Nota = @PNumNot
         And Round(Qtd_ImpFat*100,0) <> Round((Cast(Qtd_Produto+Qtd_Bonificacao as numeric(18,4))/Fat_CnvImpFat)*100,0) 
  
      Update NFSIT
         Set Prc_UniImpFat = Prc_Unitario*Fat_CnvImpFat
       Where Cod_Estabe = @PCodEstabe
         And Ser_Nota = @PSerNot
         And Num_Nota = @PNumNot
         And Round(Prc_UniImpFat*10000,0) <> Round(Prc_Unitario*Fat_CnvImpFat*10000,0)
      
      -- registra p.unitario e desconto pedido venda
      Update NFSIT
         Set Prc_UniPdv = Prc_Unitario,
             Per_DscPdv = Per_Desconto
       Where Cod_Estabe = @PCodEstabe
         And Ser_Nota = @PSerNot
         And Num_Nota = @PNumNot
    
      -- registra custos medio
      Update it 
         Set it.Vlr_CusIte = pr.Prc_CusMed,
             it.Vlr_CusComIte = Case 
                                  When IsNull(pr.Prc_CusMedCom,0) > 0 Then IsNull(pr.Prc_CusMedCom,0) 
                                  Else IsNull(pr.Prc_CusMed,0) 
                                End
       From NFSIT it Inner Join 
            PRXES pr on it.Cod_Estabe = pr.Cod_Estabe And it.Cod_Produto = pr.Cod_Produt 
      Where it.Cod_Estabe = @PCodEstabe
        And it.Ser_Nota = @PSerNot
        And it.Num_Nota = @PNumNot
      
    
      Set @WCodOri = ''
      
      -- se houver movimentacao de estoque:
      if @cb_FlgMovEst = 1
        begin
          if @cb_FlgWMS = 1
            begin
              -- configura cod. origem
              if @cb_TipSai = 'V'
                Set @WCodOri = 'SAI_VEN'
              else  
              if @cb_TipSai = 'D'
                Set @WCodOri = 'SAI_DEV'
              else  
              if @cb_TipSai = 'T'
                Set @WCodOri = 'SAI_TRF'
              else  
              if @cb_TipSai = 'O'
                Set @WCodOri = 'SAI_OUT'
            
              Declare NFSIT_Cr Cursor Local Fast_Forward For 
                Select it.Cod_Produto, it.Cod_Lote, it.Num_SeqIte, IsNull(it.Tip_Sai,''), it.Qtd_Produto, it.Qtd_Bonificacao, 
                       it.Prc_Unitario, IsNull(lt.Qtd_SldPra,0), IsNull(lt.Qtd_SldDep,0), IsNull(lt.Qtd_EmbFec,0), 
                       lf.Cod_Dep, lf.Num_Rua, lf.Num_Col, lf.Num_Niv, lf.Num_Apt
                  From NFSIT it Inner Join 
                       NFSLT lf on it.Cod_Estabe = lf.Cod_Estabe and it.Ser_Nota = lf.Ser_Nota and it.Num_Nota = lf.Num_Nota and 
                                   it.Cod_Produto = lf.Cod_Produto and it.Cod_Lote = lf.Cod_Lote and it.Num_SeqIte = lf.Num_SeqIte Left Outer Join 
                       PRLTL lt on lf.Cod_Estabe = lt.Cod_Estabe and lf.Cod_Produto = lt.Cod_Produt and lf.Cod_Lote = lt.Cod_Lote and lf.Cod_Dep = lt.Cod_Dep and 
                                   lf.Num_Rua = lt.Num_Rua and lf.Num_Col = lt.Num_Col and lf.Num_Niv = lt.Num_Niv and lf.Num_Apt = lt.Num_Apt 
                 Where it.Cod_Estabe = @PCodEstabe 
                   and it.Ser_Nota = @PSerNot 
                   and it.Num_Nota = @PNumNot
            end 
          else
            begin  -- não WMS
              -- se for o caso, elimina reserva ref. consignacao
              Delete From RESER 
               Where Cod_Estabe = @PCodEstabe
                 And @ns_IdConsig > 0
                 And IsNull(Id_Consig,0)  = @ns_IdConsig
                 And IsNull(Num_SeqCtr,0) = @ns_NumSeqCtr
                 And IsNull(Num_SeqDev,0) = @ns_NumSeqDev  
  
              Declare NFSIT_Cr Cursor Local Fast_Forward For 
                Select it.Cod_Produto, it.Cod_Lote, it.Num_SeqIte, IsNull(it.Tip_Sai,''), it.Qtd_Produto, it.Qtd_Bonificacao, 
                       it.Prc_Unitario, IsNull(lt.Qtd_SldPra,0), IsNull(lt.Qtd_SldDep,0), 0, 
                       IsNull(lt.Cod_Dep,1), 0, 0, 0, 0
                  From NFSIT it Left Outer Join 
                       PRLOT lt on ((it.Cod_Estabe = lt.Cod_Estabe) and (lt.Cod_Dep = @ns_CodDep) and (it.Cod_Produto = lt.Cod_Produt) and (it.Cod_Lote = lt.Cod_Lote))
                 Where it.Cod_Estabe = @PCodEstabe 
                   and it.Ser_Nota = @PSerNot 
                   and it.Num_Nota = @PNumNot 
            end
  
          Open NFSIT_Cr
          Fetch Next From NFSIT_Cr
            Into @it_CodPrd, @it_CodLot, @it_SeqIte, @it_TipSai, @it_QtdPrd, @it_QtdBon, @it_PrcUni,
                 @lt_QtdSldPra, @lt_QtdSldDep, @lt_QtdEmbFec, @lt_CodDep, @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt
  
          While @@FETCH_STATUS = 0
            begin
              Set @PQtdPra = 0
              Set @PQtdDep = 0
              Set @WQtdAcc = @it_QtdPrd+@it_QtdBon
              if @cb_CodCfo > 0 
                begin
                  if @lt_QtdSldPra >= @WQtdAcc
                    Set @WQtdMov = @WQtdAcc
                  else
                    Set @WQtdMov = @lt_QtdSldPra
                  Set @PQtdPra = @PQtdPra + @WQtdMov
                  Set @lt_QtdSldPra = @lt_QtdSldPra - @WQtdMov
                  Set @WQtdAcc = @WQtdAcc - @WQtdMov
                end
              else
                begin
                  if @lt_QtdSldDep >= @WQtdAcc
                    Set @WQtdMov = @WQtdAcc
                  else
                    Set @WQtdMov = @lt_QtdSldDep
                  Set @PQtdDep = @PQtdDep + @WQtdMov
                  Set @lt_QtdSldDep = @lt_QtdSldDep - @WQtdMov
                  Set @WQtdAcc = @WQtdAcc - @WQtdMov
                end
             
              if (@WQtdAcc > 0) and (@lt_QtdSldPra > 0)
                begin
                  if @lt_QtdSldPra >= @WQtdAcc
                    Set @WQtdMov = @WQtdAcc
                  else
                    Set @WQtdMov = @lt_QtdSldPra
                  Set @PQtdPra = @PQtdPra + @WQtdMov
                  Set @lt_QtdSldPra = @lt_QtdSldPra - @WQtdMov          
                  Set @WQtdAcc = @WQtdAcc - @WQtdMov
                end
  
              if (@WQtdAcc > 0) and (@lt_QtdSldDep > 0)
                begin
                  if @lt_QtdSldDep >= @WQtdAcc
                    Set @WQtdMov = @WQtdAcc
                  else
                    Set @WQtdMov = @lt_QtdSldDep
                  Set @PQtdDep = @PQtdDep + @WQtdMov
                  Set @lt_QtdSldDep = @lt_QtdSldDep - @WQtdMov          
                  Set @WQtdAcc = @WQtdAcc - @WQtdMov
                end
  
              if (@PQtdPra+@PQtdDep) <> (@it_QtdPrd+@it_QtdBon)
                begin
                  if @@trancount > 0 
                    Rollback Transaction
                  RAISERROR('Inconsistência entre quantidade saída e quantidade dos lotes',16,1)
                  Return
                end
  
              -- normaliza campos
              if @PQtdPra is null
                Set @PQtdPra = 0
              if @PQtdDep is null
                Set @PQtdDep = 0
              if (@PQtdPra+@PQtdDep) <> (@it_QtdPrd+@it_QtdBon)
                begin
                  Set @PQtdPra = @it_QtdPrd + @it_QtdBon - @PQtdDep
                end
            
              -- atualiza quantidades de lotes
              Update NFSIT
                 Set Qtd_Pra = @PQtdPra,
                     Qtd_Dep = @PQtdDep,
                     Transacao = @Now
               Where Cod_Estabe = @PCodEstabe 
                 and Ser_Nota = @PSerNot 
                 and Num_Nota = @PNumNot              
                 and Cod_Produto = @it_CodPrd
                 and Cod_Lote = @it_CodLot
                 and Num_SeqIte = @it_SeqIte
                
              if @cb_FlgWMS = 1
                Update NFSLT
                   Set Qtd_LotePra = @PQtdPra,
                       Qtd_LoteDep = @PQtdDep,
                       Transacao = @Now
                 Where Cod_Estabe = @PCodEstabe 
                   and Ser_Nota = @PSerNot 
                   and Num_Nota = @PNumNot              
                   and Cod_Produto = @it_CodPrd
                   and Cod_Lote = @it_CodLot
                   and Num_SeqIte = @it_SeqIte
                
              -- configura flag de emprestimo de estoque
              Set @WFlgEmpPra = 0
              Set @WFlgEmpDep = 0
              if (@cb_CodCfo > 0) and (@PQtdDep > 0)
                Set @WFlgEmpDep = 1 
              if (@cb_CodCfo = 0) and (@PQtdPra > 0)
                Set @WFlgEmpPra = 1 
  
              -- atualiza saldo estoque
              Set @WQtdPra = @PQtdPra * (-1)       
              Set @WQtdDep = @PQtdDep * (-1)       
              
              if @cb_FlgWMS = 1
                begin
                  -- registra log saida
                  Set @WQtdTot = @WQtdPra + @WQtdDep
                  
                  Exec PR_InserePRLOG @PCodEstabe, @it_CodPrd, @it_CodLot, @lt_CodDep, 
                                      @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt,
                                      @WQtdTot, @WCodOri, '', @PSerNot, @PNumNot, '', @Usuario
                  if @@error <> 0
                    begin
                      if @@trancount > 0 
                        Rollback Transaction
                      Return
                    end    
                  
                  EXEC PR_AtualizaSaldoEstoqueGrosso @PCodEstabe, @it_CodPrd, @it_CodLot, @lt_QtdEmbFec, @lt_CodDep, @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt,
                                                     @PDatEmi, 'S', @cb_TipSai, @WQtdPra, @WFlgEmpPra, @WQtdDep, @WFlgEmpDep
                end                                     
              else
                EXEC PR_AtualizaSaldoEstoque 'NF', @PCodEstabe, @lt_CodDep, @it_CodPrd, @it_CodLot, @PDatEmi, 'S', @cb_TipSai, @WQtdPra, @WFlgEmpPra, @WQtdDep, @WFlgEmpDep
              if @@error <> 0
                begin
                  if @@trancount > 0 
                    Rollback Transaction
                  Return
                end
  
              -- estorno de verba do fornecedor aqui 1
              Set @WValVrbFor = 0
              Set @WCodEmiFor = 0
  
              if (@cb_TipSai = 'D') and (@cb_FlgMovEst = 1) and
                 Exists(Select 1  -- NF Entrada de compra vinculada
                          From NSREF r
                               Inner Join NFECB cb on r.Cod_Estabe = cb.Cod_Estabe and r.Num_DocRef = cb.Protocolo
                               Inner Join NFEIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Protocolo = it.Protocolo And it.Cod_Produto = @it_CodPrd And it.Cod_Lote = @it_CodLot
                         Where r.Cod_Estabe = @PCodEstabe
                           And r.Ser_Nota = @PSerNot
                           And r.Num_Nota = @PNumNot
                           And r.Tip_EntSai = 'E'
                           And cb.Cod_EmiFornec > 0
                           And IsNull(it.Vlr_DscIte2,0) <> 0
                           And it.Qtd_Pedido > 0)
                begin
                  Select top 1 @WCodEmiFor = cb.Cod_EmiFornec,
  				             @WValVrbFor = (it.Vlr_DscIte2/it.Qtd_Pedido)
                   From NSREF r
                        Inner Join NFECB cb on r.Cod_Estabe = cb.Cod_Estabe and r.Num_DocRef = cb.Protocolo
                        Inner Join NFEIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Protocolo = it.Protocolo And it.Cod_Produto = @it_CodPrd And it.Cod_Lote = @it_CodLot
                  Where r.Cod_Estabe = @PCodEstabe
                    And r.Ser_Nota = @PSerNot
                    And r.Num_Nota = @PNumNot
                    And r.Tip_EntSai = 'E'
                    And cb.Cod_EmiFornec > 0
                    And IsNull(it.Vlr_DscIte2,0) <> 0
                    And it.Qtd_Pedido > 0
                end
  
              -- Op.Triangular  aqui ???
              if (@WCodEmiFor = 0) and
                 (@FlgDevolOpeVdo = 1) and (@cb_FlgMovEst = 0) and
                 Exists(Select 1  -- NF Entrada de compra vinculada à NF de saída vinculada
                          From NSREF r
                               Inner Join NFECB cb on r.Cod_Estabe = cb.Cod_Estabe and r.Num_DocRef = cb.Protocolo
                               Inner Join NFEIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Protocolo = it.Protocolo And it.Cod_Produto = @it_CodPrd And it.Cod_Lote = @it_CodLot
                         Where r.Cod_Estabe = @PCodEstabe
                           And r.Ser_Nota = @SerNotVincOpeVdo
                           And r.Num_Nota = @NumNotVincOpeVdo
                           And r.Tip_EntSai = 'E'
                           And cb.Cod_EmiFornec > 0
                           And IsNull(it.Vlr_DscIte2,0) <> 0
                           And it.Qtd_Pedido > 0)
                begin
                  Select top 1 @WCodEmiFor = cb.Cod_EmiFornec,
  				             @WValVrbFor = (it.Vlr_DscIte2/it.Qtd_Pedido)
                   From NSREF r
                        Inner Join NFECB cb on r.Cod_Estabe = cb.Cod_Estabe and r.Num_DocRef = cb.Protocolo
                        Inner Join NFEIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Protocolo = it.Protocolo And it.Cod_Produto = @it_CodPrd And it.Cod_Lote = @it_CodLot
                  Where r.Cod_Estabe = @PCodEstabe
                    And r.Ser_Nota = @SerNotVincOpeVdo
                    And r.Num_Nota = @NumNotVincOpeVdo
                    And r.Tip_EntSai = 'E'
                    And cb.Cod_EmiFornec > 0
                    And IsNull(it.Vlr_DscIte2,0) <> 0
                    And it.Qtd_Pedido > 0
                end

              -- estorna verba fornecedor
              if (@WValVrbFor <> 0) and (@WCodEmiFor > 0)
                begin
                  Set @WValVrbFor = -Round(@WValVrbFor*@it_QtdPrd,2)
                  Exec PR_AtualizaSaldoVBFSD @PCodEstabe, @WCodEmiFor, @PDatEmi, 0, @it_CodPrd, @it_CodLot, 'S', @cb_TipSai, @PSerNot, @PNumNot, @WValVrbFor, 'DEVOLUÇÃO NF', 'SISTEMA'
                  if (@@error <> 0)
                    begin
                      if @@trancount > 0 
                        Rollback Transaction
                      Return
                    end
                end
  
              -- grava movimento relativo a venda(somente) em consignação: CFOP: 5112/6112, 5113/6113, 5114/6114 
              if (@ns_IdConsig > 0) and (@ns_NumSeqCtr > 0) and (dbo.FN_CfopConsigValido(@cb_CodCfo) = 1) 
                begin
                  if dbo.FN_TipoNFConsig(@cb_CodCfo) = 'V'
                    Set @WCodTipSaiCng = 'NFF'
  				else
                    Set @WCodTipSaiCng = 'NFR'
  
                  Exec PR_GravaMovimeCNGMV @PCodEstabe, @ns_IdConsig, @it_CodPrd, @it_CodLot,
                                           @PDatEmi, 'S', @WCodTipSaiCng, @PSerNot, @PNumNot, @it_TipSai, 'F', 
                                           @WQtdMov, @it_PrcUni
                  if (@@error <> 0)
                    begin
                      if @@trancount > 0 
                        Rollback Transaction
                      Return
                    end
                end
  
              Fetch Next From NFSIT_Cr
                Into @it_CodPrd, @it_CodLot, @it_SeqIte, @it_TipSai, @it_QtdPrd, @it_QtdBon, @it_PrcUni,  
                     @lt_QtdSldPra, @lt_QtdSldDep, @lt_QtdEmbFec, @lt_CodDep, @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt
  
              Set @PQtdIte = @PQtdIte + 1
            end
  
          Close NFSIT_Cr
          Deallocate NFSIT_Cr
  
        end  -- if @cb_FlgMovEst = 1
  
      if @PQtdIte = 0
        Set @PQtdIte = Isnull((Select count(*) From NFSIT Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot),0)
  
      if @PQtdIte > 0
        Set @PQtdPgNf = Ceiling(@PQtdIte*1.00 /@pm_NumItePagNfs)
  
      Update NMFIS
         Set Formulario_M1 = @PNumFrm + @PQtdPgNf - 1,
             Selo_Fiscal = case 
                             When @Pm_FlgCtrSelFis = 1 then @PNumSel + @PQtdPgNf - 1
                             else Selo_Fiscal + 0
                           end
       Where Cod_Estabe = @PCodEstabe                  
  
      -- registra Insc.Est. ST do emitente na UF destino em op. interestaduais
      if (@WFlgOpeInt = 0) and (@uf_FlgRegSubTri= 1) and (@uf_BlqInsEstSbtNfs = 0)
        Set @PNumInscriSbtEmiUfd = @uf_NumInscriSbt
      else
        Set @PNumInscriSbtEmiUfd = ''
  
      Update NFSCB
         Set Dat_Emissao = @PDatEmi,
             Qtd_Itens = @PQtdIte,
             Qtd_PagNf = @PQtdPgNf,
             Num_Formulario = (Select Formulario_M1 from NMFIS Where Cod_Estabe = @PCodEstabe),
             Flg_BlqTrfEstFis = IsNull(@ns_FlgBlqTrfEstFis,0),
             Cod_Agente = (Select CodAgeCobCar from PARAM Where Cod_Estabe = @PCodEstabe),
             Num_InscriSubTriEmiUfd = @PNumInscriSbtEmiUfd,
             Status = 'F',
             Id_OpeVdo = @IdOpeVdo,
             Transacao = @Now,
             Ser_Selo = case 
                          When @Pm_FlgCtrSelFis = 1 then (Select SerieSeloFiscal from PARAM Where Cod_Estabe = @PCodEstabe)
                          else null
                        end,
             Num_Selo = case 
                          When @Pm_FlgCtrSelFis = 1 then (Select Selo_Fiscal from NMFIS Where Cod_Estabe = @PCodEstabe)
                          else 0
                        end
       Where Cod_Estabe = @PCodEstabe 
         and Ser_Nota = @PSerNot 
         and Num_Nota = @PNumNot
  
      if @IdOpeVdo > 0
        Update NFSCB
           Set Id_OpeVdo = @IdOpeVdo
         Where Cod_Estabe = @PCodEstabe 
           and Ser_Nota = @SerNotVincOpeVdo
           and Num_Nota = @NumNotVincOpeVdo

      --  atualiza CFOp dos itens
      if Exists(Select 1 From NFSIT
                 Where Cod_Estabe = @PCodEstabe 
                  and Ser_Nota = @PSerNot 
                  and Num_Nota = @PNumNot 
                  and IsNull(Cod_Cfo,0) = 0)
        begin
          Exec PR_AtualizaCFOpItemNf @PCodEstabe, @PSerNot, @PNumNot
          if @@error <> 0
            begin
              if @@trancount > 0 
                Rollback Transaction
              Return
            end
        end
  
      if @PQtdIte > 0
        begin
          -- atualiza Cfop do cabecalho com o do item de maior valor
          Exec PR_AtualizaCfopNFSCB @PCodEstabe, @PSerNot, @PNumNot
          if @@error <> 0
            begin
              if @@trancount > 0 
                Rollback Transaction
              Return
            end
        end
  
      -- ver se transfere saldos de PRSLD
      Exec PR_TransfEstNFS @PCodEstabe, @PSerNot, @PNumNot
      if @@error <> 0
        begin
          if @@trancount > 0 
            Rollback Transaction
          Return
        end
  
      -- atualiza estatisticas
      Exec PR_AtualizaEstatisticasNFS @PCodEstabe, @PSerNot, @PNumNot, 'F'
      if @@error <> 0
        begin
          if @@trancount > 0
            Rollback Transaction
          Return
        end
  
      -- recalcula NF se orgao publico com desconto ICMS
      if ((@rt_FlgDscIcmOrgPub = 1) or (@rt_FlgDscIcmOrgPubAcr = 1)) and ((@cl_TipCon = 'P') or (@cl_TipCon = 'E') or (@cl_TipCon = 'M'))
        begin
          EXEC PR_RecalculaNFSCB @PCodEstabe, @PSerNot, @PNumNot
          if (@@error <> 0)
            begin
              if @@trancount > 0 
                Rollback Transaction
              Return
            end
        end  
  
      Select @cb_ValNot = IsNull(Vlr_TotalNota,0)
        From NFSCB
       Where Cod_Estabe = @PCodEstabe 
         and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
     
      -- gera vales (devolucao)
      -- coloca campos TPOPE na memoria
      Declare @to_IsnCtaFinDeb int,
              @to_IsnCtaFinCre int,
              @to_IsnCtaFinCreInterv int,
              @to_IsnCtaFinDebInterv int,
              @WTipEntid varchar(3),
              @WCodEntid int,
              @WIsnCtaFinEntid int,
              @pm_FlgUsaInterv bit

      Select @pm_FlgUsaInterv = IsNull(FlgUsaInterv,0)
        From PMFIN
                  
      Select @to_IsnCtaFinDeb = ISNULL(Isn_CtaFinDeb,0),
             @to_IsnCtaFinCre = ISNULL(Isn_CtaFinCre,0)
        From TPOPE
       Where Cod_Ope = @cb_CodOpe
        
      Set @WTipEntid = ''
      Set @WCodEntid = 0
      Set @WIsnCtaFinEntid = 0

	  Declare @WCodCliAux int = 0,
              @WCodFunAux int = 0,
              @WCodForAux int = 0

     --------------------------------------------------------------------------------------------------

      if ((@cb_TipSai = 'D') or (@FlgDevolOpeVdo = 1)) and (@cb_FlgMovEst = 1) 
        begin
		  -- qual entidade gerar vale de débito
          -- OP.Triangular gerar vale de débito para entidade que gerou lançamento financeiro em PAGCT
          Set @cb_NumPrtDevVdo = 0
          Set @cb_NumPrtDevVnc = 0
          Set @cb_IdOpeVdoDev = 0

          if @FlgDevolOpeVdo = 1 
            begin
              -- verifica NFE vinculadas
              if Exists(Select 1  -- NF Entrada vinculada
                          From NSREF r
                               Inner Join NFECB cb on r.Cod_Estabe = cb.Cod_Estabe and r.Num_DocRef = cb.Protocolo
                         Where r.Cod_Estabe = @PCodEstabe
                           And r.Ser_Nota = @PSerNot
                           And r.Num_Nota = @PNumNot
                           And r.Tip_EntSai = 'E'
                           And IsNull(cb.Id_OPeVdo,0) > 0)
                begin
                  Select top 1 @cb_NumPrtDevVdo = cb.Protocolo,  -- NF Entrada vinculada
                               @cb_IdOpeVdoDev  = cb.Id_OpeVdo
                    From NSREF r
                         Inner Join NFECB cb on r.Cod_Estabe = cb.Cod_Estabe and r.Num_DocRef = cb.Protocolo
                   Where r.Cod_Estabe = @PCodEstabe
                     And r.Ser_Nota = @PSerNot
                     And r.Num_Nota = @PNumNot
                     And r.Tip_EntSai = 'E'
                     And IsNull(cb.Id_OPeVdo,0) > 0
      	    
                  if Exists (Select 1 From PAGCT Where Cod_Estabe = @PCodEstabe and Cod_PrtNfe = @cb_NumPrtDevVdo)
                    Select top 1 @cb_CodForDevVdo = cb.Cod_EmiFornec,
                                 @cb_CodCliDevVdo = cb.Cod_EmiCliente,
                                 @cb_CodTraDevVdo = cb.Cod_EmiTransp
                      From NFECB cb
                     Where Cod_Estabe = @PCodEstabe
                       And Protocolo = @cb_NumPrtDevVdo
                  else
                  if Exists(Select 1
                              From NFECB cb
                             Where Cod_Estabe = @PCodEstabe
                               And Id_OPeVdo = @cb_IdOpeVdoDev
	   	    		         And Protocolo <> @cb_NumPrtDevVdo
                               And Exists (Select 1 From PAGCT Where Cod_Estabe = @PCodEstabe and Cod_PrtNfe = cb.Protocolo))
                    begin
                      Select top 1 @cb_CodForDevVdo = cb.Cod_EmiFornec,
                                   @cb_CodCliDevVdo = cb.Cod_EmiCliente,
                                   @cb_CodTraDevVdo = cb.Cod_EmiTransp
                        From NFECB cb
                       Where Cod_Estabe = @PCodEstabe
                         And Id_OPeVdo = @cb_IdOpeVdoDev
	   	    		   And Protocolo <> @cb_NumPrtDevVdo
                         And Exists (Select 1 From PAGCT Where Cod_Estabe = @PCodEstabe and Cod_PrtNfe = cb.Protocolo)
                    end
      	    
                end -- if Exists(

              else
              -- verifica NFE vinculadas à NFS vinculada
              if Exists(Select 1  -- NF Entrada vinculada
                          From NSREF r
                               Inner Join NFECB cb on r.Cod_Estabe = cb.Cod_Estabe and r.Num_DocRef = cb.Protocolo
                         Where r.Cod_Estabe = @PCodEstabe
                           And r.Ser_Nota = @SerNotVincOpeVdo
                           And r.Num_Nota = @NumNotVincOpeVdo
                           And r.Tip_EntSai = 'E'
                           And IsNull(cb.Id_OPeVdo,0) > 0)
                begin
                  Select top 1 @cb_NumPrtDevVdo = cb.Protocolo,  -- NF Entrada vinculada
                               @cb_IdOpeVdoDev  = cb.Id_OpeVdo
                    From NSREF r
                         Inner Join NFECB cb on r.Cod_Estabe = cb.Cod_Estabe and r.Num_DocRef = cb.Protocolo
                   Where r.Cod_Estabe = @PCodEstabe
                     And r.Ser_Nota = @SerNotVincOpeVdo
                     And r.Num_Nota = @NumNotVincOpeVdo
                     And r.Tip_EntSai = 'E'
                     And IsNull(cb.Id_OPeVdo,0) > 0
      	    
                  if Exists (Select 1 From PAGCT Where Cod_Estabe = @PCodEstabe and Cod_PrtNfe = @cb_NumPrtDevVdo)
                    Select top 1 @cb_CodForDevVdo = cb.Cod_EmiFornec,
                                 @cb_CodCliDevVdo = cb.Cod_EmiCliente,
                                 @cb_CodTraDevVdo = cb.Cod_EmiTransp
                      From NFECB cb
                     Where Cod_Estabe = @PCodEstabe
                       And Protocolo = @cb_NumPrtDevVdo
                  else
                  if Exists(Select 1
                              From NFECB cb
                             Where Cod_Estabe = @PCodEstabe
                               And Id_OPeVdo = @cb_IdOpeVdoDev
	   	    		         And Protocolo <> @cb_NumPrtDevVdo
                               And Exists (Select 1 From PAGCT Where Cod_Estabe = @PCodEstabe and Cod_PrtNfe = cb.Protocolo))
                    begin
                      Select top 1 @cb_CodForDevVdo = cb.Cod_EmiFornec,
                                   @cb_CodCliDevVdo = cb.Cod_EmiCliente,
                                   @cb_CodTraDevVdo = cb.Cod_EmiTransp
                        From NFECB cb
                       Where Cod_Estabe = @PCodEstabe
                         And Id_OPeVdo = @cb_IdOpeVdoDev
	   	    		   And Protocolo <> @cb_NumPrtDevVdo
                         And Exists (Select 1 From PAGCT Where Cod_Estabe = @PCodEstabe and Cod_PrtNfe = cb.Protocolo)
                    end
      	    
                end -- if Exists(

            end  --  if @FlgDevolOpeVdo = 1 
		  -- fim da entidade ref. NFE que gerou Financeiro (PAGCT) -----------------


          if ((@cb_CodCliDevVdo > 0) or (@cb_CodFunDevVdo > 0) or (@cb_CodForDevVdo > 0))
            begin
              Set @WCodCliAux = @cb_CodCliDevVdo
              Set @WCodForAux = @cb_CodForDevVdo
              Set @WCodFunAux = @cb_CodFunDevVdo
            end
          else
            begin
              Set @WCodCliAux = @cb_CodCli
              Set @WCodForAux = @cb_CodFor
              Set @WCodFunAux = @cb_CodFun
            end

          if @WCodCliAux > 0  
            begin
              Set @WTipEntid = 'CLI'
              Set @WCodEntid = @WCodCliAux
              Set @WIsnCtaFinEntid = IsNull((Select Isn_CtaFin From CLIEN Where Codigo = @WCodCliAux),0)
            end
          else  
          if @WCodForAux > 0
            begin
              Set @WTipEntid = 'FOR'
              Set @WCodEntid = @WCodForAux
              Set @WIsnCtaFinEntid = IsNull((Select Isn_CtaFin From FORNE Where Codigo = @WCodForAux),0)
            end
          else
          if @WCodFunAux > 0  
            begin
              Set @WTipEntid = 'FUN'
              Set @WCodEntid = @WCodFunAux
              Set @WIsnCtaFinEntid = IsNull((Select Isn_CtaFin From FUNCI Where Codigo = @WCodFunAux),0)
            end
          else
          if @cb_CodTraDevVdo > 0  
            begin
              Set @WTipEntid = 'TRA'
              Set @WCodEntid = @cb_CodTraDevVdo
              Set @WIsnCtaFinEntid = IsNull((Select Isn_CtaFin From TRANS Where Codigo = @WCodFunAux),0)
            end

          -- plano de contas
          Set @to_IsnCtaFinCreInterv = 0
          Set @to_IsnCtaFinDebInterv = 0
          if @pm_FlgUsaInterv = 1
            begin
              if (@to_IsnCtaFinCre = (Select IsnCtaFinRecCli From PMFIN)) and (@WCodCliAux > 0)
                Set @to_IsnCtaFinCreInterv = @WIsnCtaFinEntid
                        
              if (@to_IsnCtaFinCre = (Select IsnCtaFinPagFor From PMFIN)) and (@WCodForAux > 0)
                Set @to_IsnCtaFinCreInterv = @WIsnCtaFinEntid
                        
              if (@to_IsnCtaFinCre = (Select IsnCtaFinPagFun From PMFIN)) and (@WCodFunAux > 0)
                Set @to_IsnCtaFinCreInterv = @WIsnCtaFinEntid
                    
              if (@to_IsnCtaFinCre = (Select IsnCtaFinPagTra From PMFIN)) and (@cb_CodTraDevVdo > 0)
                Set @to_IsnCtaFinCreInterv = @WIsnCtaFinEntid
					    
              if @to_IsnCtaFinCreInterv > 0
                Set @to_IsnCtaFinCre = @to_IsnCtaFinCreInterv 
                    


              if (@to_IsnCtaFinDeb = (Select IsnCtaFinRecCli From PMFIN)) and (@WCodCliAux > 0)
                Set @to_IsnCtaFinDebInterv = @WIsnCtaFinEntid
                        
              if (@to_IsnCtaFinDeb = (Select IsnCtaFinPagFor From PMFIN)) and (@WCodForAux > 0)
                Set @to_IsnCtaFinDebInterv = @WIsnCtaFinEntid
                        
              if (@to_IsnCtaFinDeb = (Select IsnCtaFinPagFun From PMFIN)) and (@WCodFunAux > 0)
                Set @to_IsnCtaFinDebInterv = @WIsnCtaFinEntid

              if (@to_IsnCtaFinDeb = (Select IsnCtaFinPagTra From PMFIN)) and (@cb_CodTraDevVdo > 0)
                Set @to_IsnCtaFinDebInterv = @WIsnCtaFinEntid
                        
              if @to_IsnCtaFinDebInterv > 0
                Set @to_IsnCtaFinDeb = @to_IsnCtaFinDebInterv 
                    
      
              if not Exists(Select 1 From PCFIN Where Isn_CtaFin = @to_IsnCtaFinCre And Tip_CtaFin = 'A')
                Set @to_IsnCtaFinCre = 0
              if not Exists(Select 1 From PCFIN Where Isn_CtaFin = @to_IsnCtaFinDeb And Tip_CtaFin = 'A')
                Set @to_IsnCtaFinDeb = 0
      
              if (@to_IsnCtaFinDeb = 0) or (@to_IsnCtaFinCre = 0)
                begin
                  if @@trancount > 0 
                    Rollback Transaction
                  RAISERROR('Pelo menos uma conta gerencial envolvida é inválida',16,1)
                  Return
                end              
               
              if (@cb_TipSai = 'D') and (@cb_FlgMovEst = 1) and
                 not Exists(Select pm.IsnCtaFinRecVal 
                            From PMFIN pm Inner Join
                                 PCFIN pc on pm.IsnCtaFinRecVal  = pc.Isn_CtaFin
                            Where pc.Tip_CtaFin = 'A')     
                begin
                  if @@trancount > 0 
                    Rollback Transaction
                  RAISERROR('Parâmetro Financeiro Conta (CREDITOS A RECEBER) não configurada',16,1)
                  Return
                end              
            end  -- if @pm_FlgUsaInterv = 1
          else
            begin
              Set @to_IsnCtaFinCre = 0
              Set @to_IsnCtaFinDeb = @WIsnCtaFinEntid
            end

          -- Parametro: Creditos a receber
          if @pm_FlgUsaInterv = 1
            Set @to_IsnCtaFinDeb = (Select pm.IsnCtaFinRecVal 
                                      From PMFIN pm Inner Join
                                           PCFIN pc on pm.IsnCtaFinRecVal  = pc.Isn_CtaFin
                                     Where pc.Tip_CtaFin = 'A')
  
          EXEC PR_ProxNumero 'Vale', @WCodDoc output
          if @@error <> 0
            begin
              if @@trancount > 0 
                Rollback Transaction
              Return
            end
  
          -- inclui vale
          Insert into VALES
            (Cod_Estabe, Cod_Vale, Des_Vale, Tip_Entid, Cod_Entid, Dat_Emissa, Val_Vale, Deb_Cre, 
             Cod_CtrLanAut, Ser_CtrLanAut, Num_CtrLanAut, Isn_CtaFinEntid, Isn_CtaFinDeb, Isn_CtaFinCre, Usuario, Transacao)
          Values
            (@PCodEstabe, @WCodDoc,'NFS Devolucao: '+@PSerNot+'/'+cast(@PNumNot as varchar), @WTipEntid, @WCodEntid, @Date, @cb_ValNot, 'D',
             'DNS', @PSerNot, @PNumNot, @WIsnCtaFinEntid, @to_IsnCtaFinDeb, @to_IsnCtaFinCre, @Usuario, @Now)

        end  -- if (@cb_TipSai = 'D') and (@cb_FlgMovEst = 1)
      else
        begin

          if ((@cb_CodCliDevVdo > 0) or (@cb_CodFunDevVdo > 0) or (@cb_CodForDevVdo > 0))
            begin
              Set @WCodCliAux = @cb_CodCliDevVdo
              Set @WCodForAux = @cb_CodForDevVdo
              Set @WCodFunAux = @cb_CodFunDevVdo
            end
          else
            begin
              Set @WCodCliAux = @cb_CodCli
              Set @WCodForAux = @cb_CodFor
              Set @WCodFunAux = @cb_CodFun
            end

          if @WCodCliAux > 0  
            begin
              Set @WTipEntid = 'CLI'
              Set @WCodEntid = @WCodCliAux
              Set @WIsnCtaFinEntid = IsNull((Select Isn_CtaFin From CLIEN Where Codigo = @WCodCliAux),0)
            end
          else  
          if @WCodForAux > 0
            begin
              Set @WTipEntid = 'FOR'
              Set @WCodEntid = @WCodForAux
              Set @WIsnCtaFinEntid = IsNull((Select Isn_CtaFin From FORNE Where Codigo = @WCodForAux),0)
            end
          else
          if @WCodFunAux > 0  
            begin
              Set @WTipEntid = 'FUN'
              Set @WCodEntid = @WCodFunAux
              Set @WIsnCtaFinEntid = IsNull((Select Isn_CtaFin From FUNCI Where Codigo = @WCodFunAux),0)
            end

          -- plano de contas
          Set @to_IsnCtaFinCreInterv = 0
          Set @to_IsnCtaFinDebInterv = 0
          if @pm_FlgUsaInterv = 1
            begin
              if (@to_IsnCtaFinCre = (Select IsnCtaFinRecCli From PMFIN)) and (@WCodCliAux > 0)
                Set @to_IsnCtaFinCreInterv = @WIsnCtaFinEntid
                        
              if (@to_IsnCtaFinCre = (Select IsnCtaFinPagFor From PMFIN)) and (@WCodForAux > 0)
                Set @to_IsnCtaFinCreInterv = @WIsnCtaFinEntid
                        
              if (@to_IsnCtaFinCre = (Select IsnCtaFinPagFun From PMFIN)) and (@WCodFunAux > 0)
                Set @to_IsnCtaFinCreInterv = @WIsnCtaFinEntid
                        
              if @to_IsnCtaFinCreInterv > 0
                Set @to_IsnCtaFinCre = @to_IsnCtaFinCreInterv 
                    
                    
              if (@to_IsnCtaFinDeb = (Select IsnCtaFinRecCli From PMFIN)) and (@WCodCliAux > 0)
                Set @to_IsnCtaFinDebInterv = @WIsnCtaFinEntid
                        
              if (@to_IsnCtaFinDeb = (Select IsnCtaFinPagFor From PMFIN)) and (@WCodForAux > 0)
                Set @to_IsnCtaFinDebInterv = @WIsnCtaFinEntid
                        
              if (@to_IsnCtaFinDeb = (Select IsnCtaFinPagFun From PMFIN)) and (@WCodFunAux > 0)
                Set @to_IsnCtaFinDebInterv = @WIsnCtaFinEntid
                        
              if @to_IsnCtaFinDebInterv > 0
                Set @to_IsnCtaFinDeb = @to_IsnCtaFinDebInterv 
                    
      
              if not Exists(Select 1 From PCFIN Where Isn_CtaFin = @to_IsnCtaFinCre And Tip_CtaFin = 'A')
                Set @to_IsnCtaFinCre = 0
              if not Exists(Select 1 From PCFIN Where Isn_CtaFin = @to_IsnCtaFinDeb And Tip_CtaFin = 'A')
                Set @to_IsnCtaFinDeb = 0
      
              if (@to_IsnCtaFinDeb = 0) or (@to_IsnCtaFinCre = 0)
                begin
                  if @@trancount > 0 
                    Rollback Transaction
                  RAISERROR('Pelo menos uma conta gerencial envolvida é inválida',16,1)
                  Return
                end              
     
              if (@cb_TipSai = 'D') and (@cb_FlgMovEst = 1) and            
                 not Exists(Select pm.IsnCtaFinRecVal 
                            From PMFIN pm Inner Join
                                 PCFIN pc on pm.IsnCtaFinRecVal  = pc.Isn_CtaFin
                            Where pc.Tip_CtaFin = 'A')     
                begin
                  if @@trancount > 0 
                    Rollback Transaction
                  RAISERROR('Parâmetro Financeiro Conta (CREDITOS A RECEBER) não configurada',16,1)
                  Return
                end              
            end  -- if @pm_FlgUsaInterv = 1
          else
            begin
              Set @to_IsnCtaFinCre = 0
              Set @to_IsnCtaFinDeb = @WIsnCtaFinEntid
            end



          if not Exists(Select Cod_Documento From CTREC Where Cod_Estabe = @PCodEstabe and Ser_NfOrigem = @PSerNot and Num_NfOrigem = @PNumNot)
            begin
              if @cb_IdTransacao = 0  
                begin
                  EXEC PR_ProxNumeroEstab @PCodEstabe, 'Id_Transacao', @cb_IdTransacao output
          
                  Update NFSCB
                     Set Id_Transacao = @cb_IdTransacao
                   Where Cod_Estabe = @PCodEstabe  
                     And Ser_Nota = @PSerNot
                     And Num_Nota = @PNumNot 
                end
  
              Set @WValMov = @cb_ValNot
              Exec PR_AtualizaPCMOV 'I', @PCodEstabe, @to_IsnCtaFinCre, @PDatEmi, 'NFSCB', 'NFS', @PSerNot, @PNumNot, 0, @cb_IdTransacao, @WValMov
  
              Set @WValMov = -@cb_ValNot
              Exec PR_AtualizaPCMOV 'I', @PCodEstabe, @to_IsnCtaFinDeb, @PDatEmi, 'NFSCB', 'NFS', @PSerNot, @PNumNot, 0, @cb_IdTransacao, @WValMov
            end
         else
           begin
             -- classifica contas financeiras CTREC
             Exec PR_ClassificaCtaFinNFS @cb_CodOpe, @WTipEntid, @WCodEntid, @to_IsnCtaFinDeb output, @to_IsnCtaFinCre output
  
             Update CTREC 
                Set Isn_CtaFin = @to_IsnCtaFinDeb,
                    Isn_CtaFinCre = @to_IsnCtaFinCre
              Where Cod_Estabe = @PCodEstabe
                And Ser_NfOrigem = @PSerNot
                And Num_NfOrigem = @PNumNot
           end
        end
  
      -- registra tributacao embutida no titulo a receber
      Exec PR_CalculaSbtEmbCTREC @PCodEstabe, @PSerNot, @PNumNot
      if @@error <> 0
        begin
          if @@trancount > 0 
            Rollback Transaction
          Return
        end
  
      -- atualiza itens na tabela de consignações
      if (@ns_IdConsig > 0) and (@ns_NumSeqCtr > 0)
        begin
          Exec PR_FaturaConsignacao 'S', @PCodEstabe, @PSerNot, @PNumNot, @ns_IdConsig, @ns_NumSeqCtr
          if (@@error <> 0)
            begin
              if @@trancount > 0 
                Rollback Transaction
              Return
            end
        end
  
      if @@trancount > 0 
        Commit Transaction
    END
  end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_InsereRegistroPDVLT]
/*
Solicita lote especifico do Picking
*/
@PCodEstabe int,
@PCodPed int,             
@PCodPrd int,
@PCodLotEsp varchar(20),  -- lote especifico
@PQtdPed int,             -- quantidade pedida do lote
@PMsg varchar(80)         -- Quantidde pedida do lote: 1000. Quantidae Atendida: 1000.

AS

SET NOCOUNT ON 

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)


Declare @MsgErr varchar(50) = '',
        @QtdSld int = 0,
        @FlgUndMin bit = 0 

Set @PCodLotEsp = Ltrim(Rtrim(@PCodLotEsp))

if not Exists(Select 1 From PDVCB Where Cod_Estabe = @PCodEstabe and Numero = @PCodPed)
  begin
    RAISERROR('Pedido inexistente',16,1)
    Return
  end

if not Exists(Select 1 From PDVIT Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @PCodPed And Cod_Produto = @PCodPrd And Qtd_Pedido > 0)
  begin
    RAISERROR('Produto inexiste no pedido',16,1)
    Return
  end

Set @MsgErr = IsNull((Select MsgErr = Case
                                        When CharIndex(Status2,';N;D;') > 0 then 'Pedido já faturado'
                                        When (Status1 <> 'P') or (Status2 <> 'F') then 'Pedido não está pendente/fechado'
                                        When IsNull(Bloqueio,'') <> '' then 'Pedido está bloqueado'
                                        When IsNull(Flg_Wms,0) = 0 then 'Pedido não permite solicitar lotes'
                                        Else ''
                                      End
                      From PDVCB
                      Where Cod_Estabe = @PCodEstabe
                      And Numero = @PCodPed),'')

if (@MsgErr = '') and
   Exists(Select Cod_Produto, Tip_Sai, count(*) From PDVIT Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @PCodPed Group By Cod_Produto, Tip_Sai Having count(*) > 1)
  Set @MsgErr = 'Existe mais de um lote no pedido'

if @MsgErr <> ''
  begin
    RAISERROR(@MsgErr,16,1)
    Return
  end

if @PCodLotEsp = ''
  begin
    RAISERROR('Lote não informado',16,1)
    Return
  end

Set @QtdSld = IsNull((Select Qtd_Saldo From PRLOT Where Cod_Estabe = @PCodEstabe and Cod_Produt = @PCodPrd and Cod_Lote = @PCodLotEsp),0)
if @QtdSld = 0
  begin
    RAISERROR('Produto/Lote inexistente ou Sem Estoque',16,1)
    Return
  end

if @PQtdPed <= 0
  begin
    RAISERROR('Quantidade solicitada inválida',16,1)
    Return
  end

-- verifica se a qtd solicitade não excede a qtd pendente a solicitar
Set @QtdSld = IsNull((Select QtdSld = (IsNull(it.QtdPdvTot,0)-IsNull(d.QtdSolTot,0))
                        From (Select Cod_Estabe, Cod_Produto, sum(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) as QtdPdvTot
                                From PDVIT 
                              Where Cod_Estabe = @PCodEstabe
                              And Cod_Pedido = @PCodPed
                              And Cod_Produto = @PCodPrd
                              And IsNull(Qtd_Pedido,0) > 0
                              Group by Cod_Estabe, Cod_Produto
                             ) it Left Outer Join

                             (Select Cod_Estabe, Cod_Produt, sum(IsNull(Qtd_Lote,0)) as QtdSolTot
                                From PDVLT
                              Where Cod_Estabe = @PCodEstabe
                              And Cod_Pedido = @PCodPed
                              And Cod_Produt = @PCodPrd
                              And IsNull(Qtd_Lote,0) > 0 
                              Group by Cod_Estabe, Cod_Produt
                             ) d on (it.Cod_Estabe = d.Cod_Estabe and it.Cod_Produto = d.Cod_Produt
                     )
                    ),0)
if @QtdSld < 0
  begin
    RAISERROR('Quantidade já solicitada excede à quatidade pedida',16,1)
    Return
  end
if @QtdSld = 0
  begin
    RAISERROR('Quantidade do pedido já foi totalmente atendida',16,1)
    Return
  end
if @PQtdPed > @QtdSld
  begin
    Set @MsgErr = 'Quantidade pedida excede quantidade pendente ('+cast(@QtdSld as varchar)+')'
    RAISERROR(@MsgErr,16,1)
    Return
  end

-- verifica se cliente bloqueia produto com mais de um lote
if Exists(Select 1 From CLIEN cl Inner Join PDVCB cb on (cb.Cod_Cliente = cl.Codigo)
          Where cb.Cod_Estabe = @PCodEstabe And cb.Numero = @PCodPed
          And IsNull(cl.Flg_BlqLotVarPdv,0) = 1) and
   Exists(Select 1 From PDVLT WHere Cod_Estabe = @PCodEstabe And Cod_Pedido = @PCodPed 
          And Cod_Produt = @PCodPrd And Cod_Lote <> @PCodLotEsp)
  begin
    RAISERROR('Cliente não permite mais de um lote do mesmo produto',16,1)
    Return
  end

-- verifica se trabalha com unidade minima
Set @MsgErr = ''

Select @FlgUndMin = IsNull(FlgAltUnvItePdv,0) 
  From PARAM Where Cod_Estabe = @PCodEstabe

-- se trabalha com unidade minima verifica apresentações padrão
if Exists(Select 1
          From PDVIT it
               Inner Join PARAM pa on it.Cod_Estabe = pa.Cod_Estabe
               Left Outer Join PRXAP ap on it.Cod_Produto = ap.Cod_Produt and IsNull(ap.Flg_Padrao,0) = 1
          Where it.Cod_Estabe = @PCodEstabe And it.Cod_Pedido = @PCodPed And it.Cod_Produto = @PCodPrd
          And it.Qtd_Pedido > 0
          And @FlgUndMin = 1
          And ap.Cod_Produt is null)
  Set @MsgErr = 'Produto sem Apresentação Padrão'
else
-- se trabalha com unidade minima verifica produtos com mais de 1 apresentação padrão
if Exists(Select 1
          From PRXAP ap
          Where ap.Flg_Padrao = 1
          And @FlgUndMin = 1
          And Exists(Select 1 From PDVIT it Where it.Cod_Estabe = @PCodEstabe and it.Cod_Pedido = @PCodPed And it.Cod_Produto = ap.Cod_Produt And it.Qtd_Pedido > 0 )
          Group by ap.Cod_Produt
          Having count(*) > 1)
  Set @MsgErr = 'Produto com mais de uma Apresentação Padrão'
else
  -- se trabalha com unidade minima verifica produtos sem medidas da embalagem padrao
if Exists(Select 1
          From PDVIT it
               Left Join PRXAP ap on it.Cod_Produto = ap.Cod_Produt and ap.Flg_Padrao = 1
          Where it.Cod_Estabe = @PCodEstabe 
          And it.Cod_Pedido = @PCodPed 
          And it.Cod_Produto = @PCodPrd
          And it.Qtd_Pedido > 0
          And ((IsNull(ap.Fat_CnvApr,0) = 0) or (IsNull(ap.Vol_Emb,0) = 0))
          And @FlgUndMin = 1)
  Set @MsgErr = 'Produto com Cadastro da Apresentação Padrão Incompleto'
else
-- se nao trabalha com unidade minima verifica produtos sem medidas da embalagem padrao
if Exists(Select 1
          From PDVIT it
               Left Join PRODU pr on it.Cod_Produto = pr.Codigo
          Where it.Cod_Estabe = @PCodEstabe 
          And it.Cod_Pedido = @PCodPed 
          And it.Cod_Produto = @PCodPrd
          And it.Qtd_Pedido > 0
          And IsNull(pr.Vol_Emb,0) = 0
          And @FlgUndMin = 0)
  Set @MsgErr = 'Produto com Cadastro da Embalagem Padrão Incompleto'

if @MsgErr <> ''
  begin
    RAISERROR(@MsgErr,16,1)
    Return
  end


BEGIN
  Set @PMsg = ''

  Declare @CodPrd int,
          @TipSai varchar(1),
          @QtdSdo int,
          @CodLotTip varchar(20),
          @QtdTotTip int,
          @QtdPraTip int,
          @QtdDepTip int,
          @QtdFra int,
          @QtdEmbFec int,
          @QtdSldFiscal int,
          @QtdSolTot int,
          @cl_CodCliPag int,
          @cl_CodGrpCli int,
          @cl_QtdMesMinPrzVctLot int,
          @cl_FlgBlqLotVarPdv bit,
          @FlgIntWms bit = 0,
          @BlqEstFisNeg bit = 0,
          @StaIntWms varchar(1),
          @FlgTipVenFat bit = 0,
          @FlgPodeFechar bit = 0,
		  @Usuario varchar(15)

  Set @Usuario = dbo.FN_UsuarioInfarma()

  Select @FlgIntWms = IsNull(FlgIntegrWmsExt,0),
         @BlqEstFisNeg = IsNull(BlqEstFisNeg,0)   -- nao permite negativar estoque fiscal
  From PMEST Where Cod_Estabe = @PCodEstabe

  Select @StaIntWms = IsNull(cb.Sta_IntWms,''),
         @FlgTipVenFat = Case When ISNull(op.Cod_CfoNorInt,0) > 0 then 1 ELse 0 End
  From PDVCB cb
       Left Join TPOPE op on cb.Tip_Faturamento = op.Cod_Ope 
  Where cb.Cod_Estabe = @PCodEstabe and cb.Numero = @PCodPed


  Begin Transaction

    Set @FlgPodeFechar = 0

    if @FlgIntWms = 0
      Set @FlgPodeFechar = 1
    else
    if @StaIntWms = ''
      begin
	  -- aqui ????
        Update PDVCB
          Set Sta_IntWMS = '0'
        Where Cod_Estabe = @PCodEstabe 
        And Numero = @PCodPed
        And IsNull(Sta_IntWMS,'') = ''

--aqui        Exec PR_WMSGerarXMLSaida @PCodEstabe, @PCodPed
      end

    if @FlgPodeFechar = 1
      begin 
		-- TBZON
        Update TBZON
          Set Num_Esteira = 1
        Where Cod_Estabe = @PCodEstabe
        And ISNULL(Num_Esteira,0) = 0

        Declare @NumVol int,
                @to_CodCfoNorInt int,
                @DatVct smalldatetime,
                @CodLot varchar(20),
                @LocEst varchar(1),
                @OrdDep varchar(1),
                @CodDep int, 
                @NumEst smallint,
                @NumRua int, 
                @NumCol int, 
                @NumNiv int, 
                @NumApt int, 
                @SldLot int,
                @FatCnvAprEmbPad int,
                @QtdPra int,
                @QtdDep int,
                @QtdLot int,
                @FlgDesord bit,
                @dx_CodLocFis varchar(15),
                @pr_VolUniMin numeric(18,8),  -- @pr_VolEmb
                @VolTotIte numeric(18,4),
                @QtdAteAcu int,
                @QtdAte int

        Select @cl_CodCliPag = Case 
                                 When IsNull(cl.Cod_CliPag,0) > 0 then cl.Cod_CliPag
                                 Else IsNull(cl.Codigo,0)
                               End,
               @cl_QtdMesMinPrzVctLot = IsNull(cl.Qtd_MesMinPrzVctLot,0),
               @cl_CodGrpCli = IsNull(cl.Cod_GrpCli,0),
			   @cl_FlgBlqLotVarPdv = IsNull(Flg_BlqLotVarPdv,0)
          From PDVCB cb Left Join CLIEN cl on (cb.Cod_Cliente = cl.Codigo)
        Where cb.Cod_Estabe = @PCodEstabe 
        And cb.Numero = @PCodPed
          
        Select @to_CodCfoNorInt = IsNull(t.Cod_CfoNorInt,0)
          From PDVCB p Left Join TPOPE t on (t.Cod_Ope = p.Tip_Faturamento)
        Where p.Cod_Estabe = @PCodEstabe 
        And p.Numero = @PCodPed

        Set @NumVol = 0

        -- elimina registro de conferencia existentes
        if Exists(Select 1 from CPVIT Where Cod_Estabe = @PCodEstabe And Num_PedCnf = @PCodPed) 
          Delete from CPVIT Where Cod_Estabe = @PCodEstabe And Num_PedCnf = @PCodPed
        if Exists(Select 1 From CPVCB Where Cod_Estabe = @PCodEstabe And Num_PedCnf = @PCodPed)
          Delete from CPVCB Where Cod_Estabe = @PCodEstabe And Num_PedCnf = @PCodPed
        
        -- cria arq. de fracionados
        IF OBJECT_ID('tempdb..#ARQ_FRAC') IS NOT NULL
          DROP TABLE #ARQ_FRAC
  
        CREATE TABLE #ARQ_FRAC
        (
            Chave int identity,
            Cod_Dep smallint,
            Num_Esteira smallint,
            Cod_Produto int,
            Cod_Lote nvarchar(20),
            Qtd_Lote int,
            Qtd_Pra int,
            Qtd_Dep int,
            Qtd_EmbFec int,
            Fat_CnvAprPad int, 
            Vol_UniIte numeric(18,8),
            Num_Rua smallint,
            Num_Col smallint,
            Num_Niv smallint,
            Num_Apt smallint,
            Cod_LocFis nvarchar(15),
            Flg_Desord bit
        ) 
        


        -- valida fracionado a solicitar descontando o que já foi soicitado (PDVLT)
        -- verifica se cliente bloqueia produto com lotes diferentes
        Select @QtdEmbFec = pr.Qtd_Embalagem, 
               @pr_VolUniMin = Case 
                                 When @FlgUndMin = 0 then IsNull(pr.Vol_Emb,0)
                                 Else IsNull(ap.Vol_Emb/ap.Fat_CnvApr,0)
                               End,
               @QtdFra = Case 
                           When x.QtdPen <= 0 then 0
                           When (@cl_FlgBlqLotVarPdv = 1) and 
                                Exists(Select 1 From PDVLT WHere Cod_Estabe = @PCodEstabe 
                                       And Cod_Pedido = @PCodPed And Cod_Produt = @PCodPrd And Cod_Lote <> @PCodLotEsp) then 0
                           When x.QtdPen >= @PQtdPed then @PQtdPed
                           Else x.QtdPen
                         End
          From (Select it.Cod_Produto, QtdPen = (it.QtdPdvTot-IsNull(d.QtdSolTot,0))
                  From (Select Cod_Produto, sum(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) as QtdPdvTot
                          From PDVIT 
                        Where Cod_Estabe = @PCodEstabe
                        And Cod_Pedido = @PCodPed
                        And Cod_Produto = @PCodPrd
                        And IsNull(Qtd_Pedido,0) > 0
                        Group by Cod_Produto
                       ) it Left Outer Join
             
                       (Select Cod_Produt, sum(IsNull(Qtd_Lote,0)) as QtdSolTot
                          From PDVLT
                        Where Cod_Estabe = @PCodEstabe
                        And Cod_Pedido = @PCodPed
                        And Cod_Produt = @PCodPrd
                        And IsNull(Qtd_Lote,0) > 0 
                        Group by Cod_Produt
                       ) d on ( it.Cod_Produto = d.Cod_Produt)
               ) x 
               Inner Join PRODU pr on (x.Cod_Produto = pr.Codigo)
               Left  Join PRXAP ap on (pr.Codigo = ap.Cod_Produt) and (ap.Flg_Padrao = 1)


        -- verifica estoque fiscal negativo
        -- nao permite negativar estoque fiscal
        if (@BlqEstFisNeg = 1) and (@FlgTipVenFat = 1)
          begin
            -- qtd solicitada anteriormente
            Set @QtdSolTot = IsNull((Select sum(Qtd_Lote) From PDVLT Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @PCodPed 
                                     And Cod_Produt = @PCodPrd),0)
            Set @QtdSldFiscal = dbo.FN_SldFiscalDisponPrd(@PCodEstabe,@PCodPrd) - @QtdSolTot
            if @QtdSldFiscal < 0 Set @QtdSldFiscal = 0
            if @QtdFra > @QtdSldFiscal 
              Set @QtdFra = @QtdSldFiscal
          end
 
        Set @QtdAteAcu = 0    -- acumulador por produto

        -- fracionados solicita somente pelo vencimento --
        if @to_CodCfoNorInt > 0
          begin
            Declare PRLOT_Cr Cursor Local Fast_Forward For   
              Select '1' as CodLocEst, lt.OrdDep, lt.Cod_Dep, lt.Dat_Vencim, lt.Cod_Lote, lt.Qtd_SldPra, lt.Fat_CnvAprEmbPad
                From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote, 
                             Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldPra=IsNull(l1.Qtd_SldPra,0), Fat_CnvAprEmbPad=IsNull(l1.Fat_CnvAprEmbPad,0) 
                        From PRLOT l1 Inner Join
                             DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli
                      Where l1.Cod_Estabe = @PCodEstabe 
                      And l1.Cod_Produt = @PCodPrd
                      And l1.Cod_Lote = @PCodLotEsp
                      And IsNull(l1.Qtd_Saldo,0) > 0 
                      and IsNull(l1.Qtd_SldPra,0) > 0
                      UNION ALL
                      Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Dep, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                             Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldPra=IsNull(l2.Qtd_SldPra,0), Fat_CnvAprEmbPad=IsNull(l2.Fat_CnvAprEmbPad,0)
                        From PRLOT l2 
                      Where l2.Cod_Estabe = @PCodEstabe 
                      And l2.Cod_Produt = @PCodPrd
                      And l2.Cod_Lote = @PCodLotEsp
                      And IsNull(l2.Qtd_Saldo,0) > 0 
                      And IsNull(l2.Qtd_SldPra,0) > 0
        			  And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Inner Join 
                     PRODU pr on lt.Cod_Produt = pr.Codigo Left Outer Join
                     CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                     CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
                Where lt.Cod_Estabe = @PCodEstabe 
                And lt.Cod_Produt = @PCodPrd
                And lt.Cod_Lote = @PCodLotEsp
                And IsNull(lt.Qtd_Saldo,0) > 0 and IsNull(lt.Qtd_SldPra,0) > 0
                And ((lt.Dat_Vencim is null) or 
                     (lt.Dat_Vencim >= Case
                                         When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                         When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                         Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                       End)) 
              UNION ALL
              Select '2' as CodLocEst, lt.OrdDep, lt.Cod_Dep, lt.Dat_Vencim, lt.Cod_Lote, lt.Qtd_SldDep, lt.Fat_CnvAprEmbPad
                From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote, 
                             Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldDep=IsNull(l1.Qtd_SldDep,0), Fat_CnvAprEmbPad=IsNull(l1.Fat_CnvAprEmbPad,0) 
                        From PRLOT l1 Inner Join
                             DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli
                      Where l1.Cod_Estabe = @PCodEstabe 
                      And l1.Cod_Produt = @PCodPrd
                      And l1.Cod_Lote = @PCodLotEsp
                      And IsNull(l1.Qtd_Saldo,0) > 0 
                      and IsNull(l1.Qtd_SldDep,0) > 0
                      UNION ALL
                      Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Dep, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                             Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldDep=IsNull(l2.Qtd_SldDep,0), Fat_CnvAprEmbPad=IsNull(l2.Fat_CnvAprEmbPad,0)
                        From PRLOT l2 
                      Where l2.Cod_Estabe = @PCodEstabe 
                      And l2.Cod_Produt = @PCodPrd
                      And l2.Cod_Lote = @PCodLotEsp
                      And IsNull(l2.Qtd_Saldo,0) > 0 
                      And IsNull(l2.Qtd_SldDep,0) > 0
        			  And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Inner Join 
                     PRODU pr on lt.Cod_Produt = pr.Codigo Left Outer Join
                     CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                     CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
                Where lt.Cod_Estabe = @PCodEstabe 
                And lt.Cod_Produt = @PCodPrd
                And lt.Cod_Lote = @PCodLotEsp
                And IsNull(lt.Qtd_Saldo,0) > 0 and IsNull(lt.Qtd_SldDep,0) > 0
                And ((lt.Dat_Vencim is null) or 
                     (lt.Dat_Vencim >= Case
                                         When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                         When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                         Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                       End)) 
              Order by OrdDep, Dat_Vencim, CodLocEst
          end
        else
          begin
            Declare PRLOT_Cr Cursor Local Fast_Forward For 
              Select '1' as CodLocEst, lt.OrdDep, lt.Cod_Dep, lt.Dat_Vencim, lt.Cod_Lote, lt.Qtd_SldPra, lt.Fat_CnvAprEmbPad
                From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote, 
                             Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldPra=IsNull(l1.Qtd_SldPra,0), Fat_CnvAprEmbPad=IsNull(l1.Fat_CnvAprEmbPad,0) 
                        From PRLOT l1 Inner Join
                             DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli
                      Where l1.Cod_Estabe = @PCodEstabe 
                      And l1.Cod_Produt = @PCodPrd
                      And l1.Cod_Lote = @PCodLotEsp
                      And IsNull(l1.Qtd_Saldo,0) > 0 
                      and IsNull(l1.Qtd_SldPra,0) > 0
                      UNION ALL
                      Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Dep, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                             Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldPra=IsNull(l2.Qtd_SldPra,0), Fat_CnvAprEmbPad=IsNull(l2.Fat_CnvAprEmbPad,0) 
                        From PRLOT l2 
                      Where l2.Cod_Estabe = @PCodEstabe 
                      And l2.Cod_Produt = @PCodPrd
                      And l2.Cod_Lote = @PCodLotEsp
                      And IsNull(l2.Qtd_Saldo,0) > 0 
                      And IsNull(l2.Qtd_SldPra,0) > 0
        			  And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Inner Join 
                     PRODU pr on lt.Cod_Produt = pr.Codigo Left Outer Join
                     CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                     CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
                Where lt.Cod_Estabe = @PCodEstabe 
                And lt.Cod_Produt = @PCodPrd
                And lt.Cod_Lote = @PCodLotEsp
                And IsNull(lt.Qtd_Saldo,0) > 0 and IsNull(lt.Qtd_SldPra,0) > 0
                And ((lt.Dat_Vencim is null) or 
                     (lt.Dat_Vencim >= Case
                                         When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                         When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                         Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                       End)) 
              UNION ALL
              Select '2' as CodLocEst, lt.OrdDep, lt.Cod_Dep, lt.Dat_Vencim, lt.Cod_Lote, lt.Qtd_SldDep, lt.Fat_CnvAprEmbPad
                From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote, 
                             Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldDep=IsNull(l1.Qtd_SldDep,0), Fat_CnvAprEmbPad=IsNull(l1.Fat_CnvAprEmbPad,0)
                        From PRLOT l1 Inner Join
                             DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli
                      Where l1.Cod_Estabe = @PCodEstabe 
                      And l1.Cod_Produt = @PCodPrd
                      And l1.Cod_Lote = @PCodLotEsp
                      And IsNull(l1.Qtd_Saldo,0) > 0 
                      and IsNull(l1.Qtd_SldDep,0) > 0
                      UNION ALL
                      Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Dep, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                             Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldDep=IsNull(l2.Qtd_SldDep,0), Fat_CnvAprEmbPad=IsNull(l2.Fat_CnvAprEmbPad,0)
                        From PRLOT l2
                      Where l2.Cod_Estabe = @PCodEstabe 
                      And l2.Cod_Produt = @PCodPrd
                      And l2.Cod_Lote = @PCodLotEsp
                      And IsNull(l2.Qtd_Saldo,0) > 0 
                      And IsNull(l2.Qtd_SldDep,0) > 0
        			  And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Inner Join 
                     PRODU pr on lt.Cod_Produt = pr.Codigo Left Outer Join
                     CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                     CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
                Where lt.Cod_Estabe = @PCodEstabe 
                And lt.Cod_Produt = @PCodPrd
                And lt.Cod_Lote = @PCodLotEsp
                And IsNull(lt.Qtd_Saldo,0) > 0 and IsNull(lt.Qtd_SldDep,0) > 0
                And ((lt.Dat_Vencim is null) or 
                     (lt.Dat_Vencim >= Case
                                         When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                         When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                         Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                       End)) 
              Order by OrdDep, Dat_Vencim, CodLocEst desc
          end
        -------------------------------------------------------------------------------------------------------------------------------------------------------
        Open PRLOT_Cr
        Fetch Next From PRLOT_Cr Into @LocEst, @OrdDep, @CodDep, @DatVct, @CodLot, @SldLot, @FatCnvAprEmbPad
        
        Set @QtdAteAcu = 0
        
        While (@QtdAteAcu < @QtdFra) and (@QtdFra > 0) and (@@FETCH_STATUS = 0)
          begin
            Set @QtdAte = @QtdFra - @QtdAteAcu
            -- se o saldo do lote nao atender a qtd.solicitada refazer a solicitacao proporcionalmente
            if @QtdAte > @SldLot
              begin
                Set @QtdAte = @SldLot
              end
             -- Atualiza saldo do lote
            Set @QtdPra = 0
            Set @QtdDep = 0
            if @LocEst = '1'
              Set @QtdPra = @QtdAte
            else
              Set @QtdDep = @QtdAte
        
            Update PRLOT
              Set Qtd_SolPra = Qtd_SolPra + @QtdPra,
                  Qtd_SolDep = Qtd_SolDep + @QtdDep
            Where Cod_Estabe = @PCodEstabe 
            And Cod_Dep = @CodDep
            And Cod_Produt = @PCodPrd
            And Cod_Lote = @CodLot
        
            Set @QtdAteAcu = @QtdAteAcu + @QtdAte
        
            -- verifica se lote foi solicitado fora de ordem
            Set @FlgDesord = 0
            if (@DatVct is not Null) and (@cl_QtdMesMinPrzVctLot > 0) and 
               (Exists(Select Cod_Lote From PRLOT Where Cod_Estabe = @PCodEstabe And Cod_Dep = @CodDep And Cod_Produt = @PCodPrd And Qtd_Saldo > 0 And Dat_Vencim < @DatVct))
              Set @FlgDesord = 1
                       
            -- pega endereço de picking do produto
            Select @NumRua = dx.Num_Rua,
                   @NumCol = dx.Num_Col,   
                   @NumNiv = dx.Num_Niv,   
                   @NumApt = dx.Num_Apt,
                   @dx_CodLocFis = dx.Cod_LocFis,
                   @NumEst = ISNULL(z.Num_Esteira,0)   
              From DPXPR dx Left Outer Join
                   TBZON z on (dx.Cod_Estabe = z.Cod_Estabe and dx.Num_Rua between z.Num_RuaIni and z.Num_RuaFim)
            Where dx.Cod_Estabe = @PCodEstabe
            And dx.Cod_Dep = @CodDep
            And dx.Cod_Produt = @PCodPrd
                   
            Insert Into #ARQ_FRAC (Cod_Dep, Num_Esteira, Cod_Produto, Cod_Lote, Qtd_Lote, Qtd_Pra, Qtd_Dep, Vol_UniIte, 
                                   Qtd_EmbFec, Fat_CnvAprPad, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_LocFis, Flg_Desord)
                           Values (@CodDep, @NumEst, @PCodPrd, @CodLot, @QtdAte, @QtdPra, @QtdDep, @pr_VolUniMin, 
                                   @QtdEmbFec, @FatCnvAprEmbPad, @NumRua, @NumCol, @NumNiv, @NumApt, @dx_CodLocFis, @FlgDesord)
        
            Fetch Next From PRLOT_Cr Into @LocEst, @OrdDep, @CodDep, @DatVct, @CodLot, @SldLot, @FatCnvAprEmbPad
        
          end  -- While (@QtdAteAcu < @QtdFra) and (@@FETCH_STATUS = 0)
          
        Close PRLOT_Cr
        Deallocate PRLOT_Cr
        

---------- **************************************************  solicita lotes por vencimento da LINHA DE PICKING (FRACIONADOS)  ***************************************************
        Declare PDVIT_Cr Cursor Local Fast_Forward For 

          Select Cod_Produto, Cod_Lote, Qtd_EmbFec, Fat_CnvAprPad, Cod_LocFis, Vol_UniIte, Qtd_Lote, Qtd_Pra, Qtd_Dep,
                 Num_Esteira, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Flg_Desord
          From #ARQ_FRAC
          Order by Cod_Dep, Num_Esteira, Num_Rua, Num_Col, Num_Niv, Num_Apt

        Open PDVIT_Cr
        Fetch Next From PDVIT_Cr Into @CodPrd, @CodLot, @QtdEmbFec, @FatCnvAprEmbPad, @dx_CodLocFis, @pr_VolUniMin, @QtdFra, @QtdPra, @QtdDep,
                                      @NumEst, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @FlgDesord 
                           
        While @@FETCH_STATUS = 0
          begin

            -- grava/regrava registro em PDVLT 
            Set @NumVol = 1
            Set @VolTotIte = (@QtdPra+@QtdDep)*@pr_VolUniMin
            if not Exists(Select 1 From PDVLT Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @PCodPed And Num_Vol = @NumVol And Cod_Produt = @CodPrd And Cod_Lote = @CodLot)
              begin
                Insert Into PDVLT (Cod_Estabe,  Cod_Pedido, Num_Vol, Cod_Produt, Cod_Lote, Qtd_EmbFec, Qtd_Lote, Qtd_CxaFec, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_LocFis,   Vol_TotIte, Qtd_LotePra, Qtd_LoteDep, Flg_Desord)
                           Values (@PCodEstabe, @PCodPed,   @NumVol, @CodPrd,    @CodLot,  0,          0,        0,          @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @dx_CodLocFis,0,          0,           0,           @FlgDesord)
                if @@error <> 0
                  begin
                    Rollback Transaction
                    Return
                  end
              end
         
            Update PDVLT
              Set Qtd_Lote = IsNull(Qtd_Lote,0) +  @QtdPra+@QtdDep,
                  Vol_TotIte = IsNull(Vol_TotIte,0) + @VolTotIte,
                  Qtd_LotePra = IsNull(Qtd_LotePra,0) + @QtdPra,
                  Qtd_LoteDep = IsNull(Qtd_LoteDep,0) + @QtdDep
            Where Cod_Estabe = @PCodEstabe 
            And Cod_Pedido = @PCodPed 
            And Num_Vol = @NumVol 
            And Cod_Produt = @CodPrd 
            And Cod_Lote = @CodLot
         
            -- atualiza quantidades em PDVIT
            Declare Table_Cr Cursor Local Fast_Forward For 
           
              Select Cod_Lote, Tip_Sai, IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)-IsNull(Qtd_Pra,0)-IsNull(Qtd_Dep,0)
                From PDVIT 
              Where Cod_Estabe = @PCodEstabe 
              And Cod_Pedido = @PCodPed
              And Cod_Produto = @CodPrd 
              And IsNull(Qtd_Pedido,0) > 0
              Order by Tip_Sai
           
            Open Table_Cr
            Fetch Next From Table_Cr Into @CodLotTip, @TipSai, @QtdTotTip
            While @@FETCH_STATUS = 0
              begin
                Set @QtdPraTip = 0
                Set @QtdDepTip = 0
                  
                Set @QtdSdo = @QtdTotTip
                while (@QtdSdo > 0) and (@QtdPra + @QtdDep > 0)
                  begin
                    if (@QtdPra > 0) and (@QtdSdo > 0)
                      begin
                        if @QtdSdo > @QtdPra
                          Set @QtdPraTip = @QtdPra
                        else
                          Set @QtdPraTip = @QtdSdo
                        Set @QtdPra = @QtdPra - @QtdPraTip
                        Set @QtdSdo = @QtdSdo - @QtdPraTip
                      end
                            
                    if (@QtdDep > 0) and (@QtdSdo > 0)
                      begin
                        if @QtdSdo > @QtdDep
                          Set @QtdDepTip = @QtdDep
                        else
                          Set @QtdDepTip = @QtdSdo
                        Set @QtdDep = @QtdDep - @QtdDepTip
                        Set @QtdSdo = @QtdSdo - @QtdDepTip
                      end
                  end  -- while @QtdSdo > 0
                      
                Update PDVIT
                  Set Qtd_Pra = Qtd_Pra + @QtdPraTip,
                      Qtd_Dep = Qtd_Dep + @QtdDepTip
                Where Cod_Estabe = @PCodEstabe 
                And Cod_Pedido = @PCodPed 
                And Cod_Produto = @CodPrd 
                And Cod_Lote = @CodLotTip
                And Tip_Sai = @TipSai
           
                Fetch Next From Table_Cr Into @CodLotTip, @TipSai, @QtdTotTip 
              end
            Close Table_Cr
            Deallocate Table_Cr
           
            Fetch Next From PDVIT_Cr Into @CodPrd, @CodLot, @QtdEmbFec, @FatCnvAprEmbPad, @dx_CodLocFis, @pr_VolUniMin, @QtdFra, @QtdPra, @QtdDep,
                                          @NumEst, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @FlgDesord 
                                              
              
          end    -- While @@FETCH_STATUS = 0
          
        Close PDVIT_Cr
        Deallocate PDVIT_Cr

        DROP TABLE #ARQ_FRAC
        
      end  -- if @FlgPodeFechar = 1

  Commit Transaction
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CalcPerComItemSaida]
@CodEstabe int,
@FlgVenVis bit,                   -- indica se eh venda a vista
@FlgComPrpDscTabRed bit,          -- indica se a comissao eh proporcional ao desconto tabelado com reducao na comissao 
@FlgComPrpDscTabFix bit,          -- indica se a comissao eh proporcional ao desconto tabelado com comissao fixa
@FlgComPrdPrpDsc bit,             -- indica se a comissao eh proporcional ao desconto por produto 
@FlgComFabPrpDsc bit,             -- indica se a comissao eh proporcional ao desconto por fabricante 
@FlgComVenAtvPas bit,             -- indica se a comisso eh ativa/passiva (politica de comercialização)   NOVO 11/02/2020
@FlgComTabLuc bit,                -- indica se a comisso eh calculada pela Tabela de Lucros   NOVO 18/04/2020
@CodTabCom int,                   -- cod. da tabela de comissao
@CodPrd int,			          
@CodFab int,                      -- cod. do fabricante
@ClaPrd varchar(4),               -- cod. da classif. do produto 
@FlgComNor bit,                   -- indica se comissao normal (nao reduzida)
@FlgCliPar bit,                   -- indica se eh cliente com parceria
@PerComFix numeric(18,4),         -- per.com fixa da venda na NF 
@DscTotIte numeric(18,4),         -- desconto total do item (calculado)
@PerRedComPol numeric(18,4),      -- per.red.comissao da politica de comercializacao
@PerRedVrbBon numeric(18,4),      -- per.red.comissao ref. a verba por bonificacoes
@PerComAtvPas numeric(18,4),      -- per.comissão ativa/passiva se @FlgComVenAtvPas = 1  --- NOVO 11/02/2020
@PerLuc numeric(18,4),            -- per. lucro se @FlgComTabLuc = 1  --- NOVO 11/02/2020
@PerComIte numeric(18,4) output,  -- per. da comissao do item
@PerComMin numeric(18,4) output   -- per. minimo


AS

SET NOCOUNT ON 

Begin Transaction

Set @PerComIte = 0
Set @PerComMin = 0
if @PerRedComPol is null
  Set @PerRedComPol = 0
if @PerRedVrbBon is null
  Set @PerRedVrbBon = 0  

if (@FlgComVenAtvPas = 1) or (@FlgComTabLuc = 1)
  begin
    Set @FlgComPrpDscTabRed = 0
    Set @FlgComPrpDscTabFix = 0
    Set @FlgComPrdPrpDsc = 0
    Set @FlgComFabPrpDsc = 0
  end


-------- Comissão Ativa e Passiva
if @FlgComVenAtvPas = 1
  begin
    Set @PerComIte = @PerComAtvPas
  end 
else
----- comissao por lucro
if @FlgComTabLuc = 1
  begin
    if Exists(Select 1 From TCXLC Where Cod_TabCom = @CodTabCom and Per_LucMax >= @PerLuc)
      Set @PerComIte = (Select top 1 Per_ComNor From TCXLC 
                        Where Cod_TabCom = @CodTabCom And Per_LucMax >= @PerLuc
                        Order By Per_LucMax)

    -- reduz comissao da politica
    Set @PerComIte = @PerComIte*(1-@PerRedComPol/100)          
  end 
else
-- comissao proporcional ao desconto
if (@FlgComPrpDscTabRed = 1) or (@FlgComPrpDscTabFix = 1)  
  begin
    if @PerComFix > 0
      Set @PerComIte = @PerComFix   -- pega a comiisao fixa para a NF
    else
      begin
        -- comissao por desc. tabelado
        Declare @WPerComNor numeric(18,4),
                @WPerRedFix numeric(18,4),
                @WDscTotIte numeric(18,4),
                @WFlgAchouTabDsc bit,
                @pm_PerRedComCliPar numeric(18,4)

        Select @pm_PerRedComCliPar = Isnull(PerRedComCliPar,0) 
          From PARAM
        Where Cod_Estabe = @CodEstabe

        Set @WDscTotIte = Round(@DscTotIte,2)
        Set @WPerComNor = 0
        Set @WPerRedFix = 0
        Set @WFlgAchouTabDsc = 0

        -- verifica tabela de descontos
        if @WDscTotIte > 0            
          begin
            if Exists(Select 1 From TCXDP Where Cod_TabCom = @CodTabCom and Cod_Produt = @CodPrd)
              begin
                Set @WFlgAchouTabDsc = 1
                if Exists(Select 1 From TCXDP Where Cod_TabCom = @CodTabCom and Cod_Produt = @CodPrd and Per_DscMax >= @WDscTotIte)
                  Select top 1 @WPerRedFix = Case
                                               When @FlgVenVis = 1 Then Isnull(Per_RedFixVis,0)
                                               Else Isnull(Per_RedFixPrz,0)
                                             End
                    From TCXDP
                  Where Cod_TabCom = @CodTabCom
                  And Cod_Produt = @CodPrd
                  And Per_DscMax >= @WDscTotIte
                  Order By Per_DscMax
                else
                  Select top 1 @WPerRedFix = Case
                                               When @FlgVenVis = 1 Then Isnull(Per_RedFixVis,0)
                                               Else Isnull(Per_RedFixPrz,0)
                                             End
                    From TCXDP
                  Where Cod_TabCom = @CodTabCom
                  And Cod_Produt = @CodPrd
                  Order By Per_DscMax desc
              end
            else
            if Exists(Select 1 From TCXDF Where Cod_TabCom = @CodTabCom and Cod_Fabric = @CodFab)
              begin
                Set @WFlgAchouTabDsc = 1
                if Exists(Select 1 From TCXDF Where Cod_TabCom = @CodTabCom and Cod_Fabric = @CodFab and Per_DscMax >= @WDscTotIte)
                  Select top 1 @WPerRedFix = Case
                                               When @FlgVenVis = 1 Then Isnull(Per_RedFixVis,0)
                                               Else Isnull(Per_RedFixPrz,0)
                                             End
                    From TCXDF
                  Where Cod_TabCom = @CodTabCom
                  And Cod_Fabric = @CodFab
                  And Per_DscMax >= @WDscTotIte
                  Order By Per_DscMax
                else
                  Select top 1 @WPerRedFix = Case
                                               When @FlgVenVis = 1 Then Isnull(Per_RedFixVis,0)
                                               Else Isnull(Per_RedFixPrz,0)
                                             End
                    From TCXDF
                  Where Cod_TabCom = @CodTabCom
                  And Cod_Fabric = @CodFab
                  Order By Per_DscMax desc
              end
            else  
            if Exists(Select 1 From TCXDC Where Cod_TabCom = @CodTabCom)
              begin
                Set @WFlgAchouTabDsc = 1
                if Exists(Select 1 From TCXDC Where Cod_TabCom = @CodTabCom and Per_DscMax >= @WDscTotIte)
                  Select top 1 @WPerRedFix = Case
                                                When @FlgVenVis = 1 Then Isnull(Per_RedFixVis,0)
                                                Else Isnull(Per_RedFixPrz,0)
                                              End
                    From TCXDC
                  Where Cod_TabCom = @CodTabCom
                  And Per_DscMax >= @WDscTotIte
                  Order By Per_DscMax
                else
                  Select top 1 @WPerRedFix = Case
                                               When @FlgVenVis = 1 Then Isnull(Per_RedFixVis,0)
                                               Else Isnull(Per_RedFixPrz,0)
                                             End
                    From TCXDC
                  Where Cod_TabCom = @CodTabCom
                  Order By Per_DscMax desc
              end
          end  -- if @WDscTotIte > 0

        -- verifica configuracao por produto
        if Exists(Select * From TCXPR Where Cod_TabCom = @CodTabCom and Cod_Produt = @CodPrd)
          begin
            Select @WPerComNor = Case
                                   When @FlgVenVis = 1 Then Isnull(Per_ComNorVis,0)
                                   Else Isnull(Per_ComNor,0)
                                 End,
                      @PerComMin = Case
                                     When @FlgVenVis = 1 Then Isnull(Per_ComRedVis,0)
                                     Else Isnull(Per_ComRed,0)
                                   End 
              From TCXPR 
            Where Cod_TabCom = @CodTabCom 
            And Cod_Produt = @CodPrd

            Set @PerComIte = Isnull(@WPerComNor,0)

            -- verifica tabela de descontos
            if @WDscTotIte > 0            
              if @WFlgAchouTabDsc = 1
                begin
                  if @FlgComPrpDscTabFix = 1
                    -- comissao fixa
                    Set @PerComIte = Isnull(@WPerComNor,0)
                  else
                    -- comissao reduzida
                    Set @PerComIte = IsNull(@WPerComNor,0) * (1 - IsNull(@WPerRedFix,0)/100)          
                end
              else  
                -- pega comissao minima
                Set @PerComIte = @PerComMin
          end
        else

        -- verifica configuracao por fabricante
        if Exists(Select * From TCXFR Where Cod_TabCom = @CodTabCom and Cod_Fornecedor = @CodFab)
          begin
            Select @WPerComNor = Case
                                   When @FlgVenVis = 1 Then Isnull(Per_ComNorVis,0)
                                   Else Isnull(Per_ComNor,0)
                                 End,
                      @PerComMin = Case
                                     When @FlgVenVis = 1 Then Isnull(Per_ComRedVis,0)
                                     Else Isnull(Per_ComRed,0)
                                   End 
              From TCXFR 
            Where Cod_TabCom = @CodTabCom 
            And Cod_Fornecedor = @CodFab

            Set @PerComIte = Isnull(@WPerComNor,0)

            -- verifica tabela de descontos
            if @WDscTotIte > 0            
              if @WFlgAchouTabDsc = 1
                begin
                  if @FlgComPrpDscTabFix = 1
                    -- comissao fixa
                    Set @PerComIte = Isnull(@WPerComNor,0)
                  else
                    -- comissao reduzida
                    Set @PerComIte = IsNull(@WPerComNor,0) * (1 - IsNull(@WPerRedFix,0)/100)
                end
              else  
                -- pega comissao minima
                Set @PerComIte = @PerComMin

            end
        else

          -- pega comissao padrao
          begin
            Select @WPerComNor = Case
                                   When @FlgVenVis = 1 Then Isnull(Per_ComNorVis,0)
                                   Else Isnull(Per_ComNor,0)
                                 End,
                      @PerComMin = Case
                                     When @FlgVenVis = 1 Then Isnull(Per_ComRedVis,0)
                                     Else Isnull(Per_ComRed,0)
                                   End 
              From TBCOM 
            Where Codigo = @CodTabCom

            Set @PerComIte = Isnull(@WPerComNor,0)

            -- verifica tabela de descontos
            if @WDscTotIte > 0            
              if @WFlgAchouTabDsc = 1
                begin
                  if @FlgComPrpDscTabFix = 1 
                    -- comissao fixa
                    Set @PerComIte = Isnull(@WPerComNor,0)
                  else
                    -- comissao reduzida
                    Set @PerComIte = IsNull(@WPerComNor,0) * (1 - IsNull(@WPerRedFix,0)/100)          
                end
              else  
                -- pega comissao minima
                Set @PerComIte = @PerComMin

          end

        -- clientes com parceria
        if @FlgCliPar = 1 and @pm_PerRedComCliPar > 0
          Set @PerComIte = @PerComIte * (1 - @pm_PerRedComCliPar/100)
    
        -- reduz comissao da politica
        Set @PerComIte = @PerComIte*(1-@PerRedComPol/100)          
    
        -- garante comissao minima
        if @PerComIte < @PerComMin
          Set @PerComIte = @PerComMin
      end
  end     -- fim comissao propo. desc. tabelado
else
---------------------------------------------------------------------------------------------------------------------------
if @FlgComPrdPrpDsc = 0   -- comissao nao eh proporcional ao desconto por  produto
  begin
    if @PerComFix > 0
      Set @PerComIte = @PerComFix   -- pega a comiisao fixa para a NF
    else
      begin
        -- comissao padrao
        if @FlgComNor = 1
           Set @PerComIte = (Select Per_ComNor From TBCOM Where Codigo = @CodTabCom)
        else
          Set @PerComIte = (Select Per_ComRed From TBCOM Where Codigo = @CodTabCom)
        Set @PerComMin = (Select Per_ComRed From TBCOM Where Codigo = @CodTabCom)

        -- comissao diferenciada por fabricante
        if Exists(Select * From TCXFR Where Cod_TabCom = @CodTabCom and Cod_Fornecedor = @CodFab)
          begin
            if @FlgComNor = 1
              Set @PerComIte = (Select Per_ComNor From TCXFR Where Cod_TabCom = @CodTabCom and Cod_Fornecedor = @CodFab)
            else
              Set @PerComIte = (Select Per_ComRed From TCXFR Where Cod_TabCom = @CodTabCom and Cod_Fornecedor = @CodFab)
            Set @PerComMin = (Select Per_ComRed From TCXFR Where Cod_TabCom = @CodTabCom and Cod_Fornecedor = @CodFab)
          end

        if @FlgComFabPrpDsc = 1
          begin
            -- comissao diferenciada por produto
            if Exists(Select * From TCXPR Where Cod_TabCom = @CodTabCom and Cod_Produt = @CodPrd)
              begin
                if @FlgComNor = 1
                  Set @PerComIte = (Select Per_ComNor From TCXPR Where Cod_TabCom = @CodTabCom and Cod_Produt = @CodPrd)
                else
                  Set @PerComIte = (Select Per_ComRed From TCXPR Where Cod_TabCom = @CodTabCom and Cod_Produt = @CodPrd)
                Set @PerComMin = (Select Per_ComRed From TCXPR Where Cod_TabCom = @CodTabCom and Cod_Produt = @CodPrd)
              end
          end
        else
          begin
            -- comissao diferenciada por grupo/classificacao
            if Exists(Select * From TCXCL Where Cod_TabCom = @CodTabCom and Cod_Classi = @ClaPrd)
              begin
                if @FlgComNor = 1
                  Set @PerComIte = (Select Per_ComNor From TCXCL Where Cod_TabCom = @CodTabCom and Cod_Classi = @ClaPrd)
                else
                  Set @PerComIte = (Select Per_ComRed From TCXCL Where Cod_TabCom = @CodTabCom and Cod_Classi = @ClaPrd)
                Set @PerComMin = (Select Per_ComRed From TCXCL Where Cod_TabCom = @CodTabCom and Cod_Classi = @ClaPrd)
              end
          end

        if @PerComIte is null
          Set @PerComIte = 0
        if @PerComMin is null
          Set @PerComMin = 0

        -- reduz comissao da politica
        Set @PerComIte = @PerComIte*(1-@PerRedComPol/100)          

        -- garante percentual minimo p/ com. proporc.desc. fabricante
        if @FlgComFabPrpDsc = 1
          if @PerComIte < @PerComMin
            if @PerComMin > 0
              Set @PerComIte = @PerComMin
      end

  end  -- comissao nao eh por produto
else
---------------------------------------------------------------------------------------------------------------------------
  begin
    -- comissao eh proporcional ao desconto por  produto
    -- comissao padrao
    Set @PerComIte = (Select Per_ComNor From TBCOM Where Codigo = @CodTabCom)
    Set @PerComMin = (Select Per_ComRed From TBCOM Where Codigo = @CodTabCom)

    -- comissao diferenciada por produto
    if Exists(Select * From TCXPR Where Cod_TabCom = @CodTabCom and Cod_Produt = @CodPrd)
      begin
        Set @PerComIte = (Select Per_ComNor From TCXPR Where Cod_TabCom = @CodTabCom and Cod_Produt = @CodPrd)
        Set @PerComMin = (Select Per_ComRed From TCXPR Where Cod_TabCom = @CodTabCom and Cod_Produt = @CodPrd)
      end

    if @PerComIte is null
      Set @PerComIte = 0
    if @PerComMin is null
      Set @PerComMin = 0

    if @PerComFix > 0
      Set @PerComIte = @PerComFix

    -- garante percentual minimo
    if @PerComIte > 0
      begin
        Set @PerComIte = @PerComIte - @DscTotIte

        -- reduz comissao da politica
        Set @PerComIte = @PerComIte*(1-@PerRedComPol/100)          
        
        if @PerComIte < @PerComMin
          if @PerComMin > 0
            Set @PerComIte = @PerComMin
      end

  end
---------------------------------------------------------------------------------------------------------------------------

-- reduz comissao ref.verba por bonificacao

Set @PerComIte = Round(@PerComIte*(1-@PerRedVrbBon/100),2)

Commit Transaction

GO

