GO

CREATE VIEW [dbo].[V_PCXOP] AS

SELECT p.Id_PolCom,
       p.Cod_Vended as Cod_Operador
  FROM PCXOP p
 WHERE Exists(Select 1
                From VENDE v 
                     Inner Join VEXES es on v.Codigo = es.Cod_Vended 
               Where v.Codigo = p.Cod_Vended
                 And es.Cod_TipVenBas = 'TLM' 
                 And v.Flg_Export = 1) 
   AND Exists (Select 1 
                 From POCOM 
                Where Id_PolCom = p.Id_PolCom
                  And (Flg_Cfv = 1 or Flg_Web = 1 or Flg_PedEle = 1)
                  And IsNull(Tip_PolCom,'') = ''
                  And ( (Dat_Inicio Is Null  or (cast(GetDate() as date) >= Dat_Inicio))  and
                        (Dat_Termino Is Null or (cast(GetDate() as date) <= Dat_Termino)) and
                        (Bloqueado Is Null or Bloqueado = 0) ) )
GO

