SET QUOTED_IDENTIFIER ON
GO

CREATE TRIGGER [dbo].[TR_ENDDP_CriticaExclusao] ON [dbo].[ENDDP] 
FOR DELETE 
AS

-- comando p/ corrigir erro delphi/ado: record was changed by another user
SET NOCOUNT ON 

Declare @MaxNivel int

Select @MaxNivel = p.QtdNivEndPck 
From PMEST p
Inner Join Deleted d on (p.Cod_Estabe = d.Cod_Estabe)

-- Verificar cadastro de produtos DPXPR
if (@MaxNivel = 4)
  begin
	if Exists(Select 1
			  from DPXPR p 
			  Inner Join Deleted e On     p.Cod_Estabe = e.Cod_Estabe
				and p.Num_Rua    = e.Num_Rua
				and p.Num_Niv    = e.Num_Niv    
				and p.Num_Col    = e.Num_Col
				and p.Num_Apt    = e.Num_Apt)
	  begin
		RAISERROR('Existe(m) produto(s) vinculado(s) a este endereço (DPXPR)',16,1)
		RollBack Transaction
	  end
  end
else
  begin
	if Exists(Select 1
			  from DPXPR p 
			  Inner Join Deleted e On     p.Cod_Estabe = e.Cod_Estabe
				and p.Num_Rua    = e.Num_Rua
				and p.Num_Niv    = e.Num_Niv    
				and p.Num_Col    = e.Num_Col)
	  begin
		RAISERROR('Existe(m) produto(s) vinculado(s) a este endereço (DPXPR)',16,1)
		RollBack Transaction
	  end
  end

-- Verificar estoque PRLTL
if (@MaxNivel = 4)
  begin
	if Exists(Select 1
			  from PRLTL p 
			  Inner Join Deleted e On     p.Cod_Estabe = e.Cod_Estabe
				and p.Num_Rua    = e.Num_Rua
				and p.Num_Niv    = e.Num_Niv    
				and p.Num_Col    = e.Num_Col
				and p.Num_Apt    = e.Num_Apt)
	  begin
		RAISERROR('Existe(m) produto(s) vinculado(s) a este endereço (PRLTL)',16,1)
		RollBack Transaction
	  end
  end
else
  begin
	if Exists(Select 1
			  from PRLTL p 
			  Inner Join Deleted e On     p.Cod_Estabe = e.Cod_Estabe
				and p.Num_Rua    = e.Num_Rua
				and p.Num_Niv    = e.Num_Niv    
				and p.Num_Col    = e.Num_Col)
	  begin
		RAISERROR('Existe(m) produto(s) vinculado(s) a este endereço (PRLTL)',16,1)
		RollBack Transaction
	  end
  end

GO

