CREATE PROCEDURE [dbo].[QG_CalcTributRetidosNFE]
@PCodEstabe int,
@PNumPrt int,
@PCodRegTri int

AS

SET NOCOUNT ON 

Declare @StrMsg varchar(400),
		@FlgErr bit = 0

Set @FlgErr = 0

if not Exists(Select Protocolo From NFECB Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumPrt And Tip_NF <> 'D')
  begin
    Set @FlgErr = 1
    Set @StrMsg = 'NF inexistente'
  end
else
if Charindex((Select Status From NFECB Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumPrt),';F;') = 0 
  begin
    Set @FlgErr = 1
    Set @StrMsg = 'NF não está fechada'
  end

if @FlgErr = 1
  RAISERROR(@StrMsg,16,1)
else
BEGIN
  BEGIN TRANSACTION

  -- variaveis de trabalho
  Declare @WFlgSbtEmbPrc bit

  
  -- Percorre itens
  Declare @it_CodPrd int,
          @it_CodLot varchar(20), 
          @it_NumSeqIte int,
          @it_VlrIte numeric(18,4),
          @it_FlgBlqDsc bit,
          @cb_TipNot varchar(1)
        
  Select @cb_TipNot=Tip_NF From NFECB
  Where Cod_Estabe = @PCodEstabe
  And Protocolo = @PNumPrt

  DECLARE NFEIT_Cr CURSOR Local Fast_Forward For 

    Select it.Cod_Produto, it.Cod_Lote, it.Num_SeqIte,
           Round(IsNull(it.Vlr_TotItem,0),2),
           IsNull(it.Flg_BlqDsc,0)
      From NFEIT it
    Where it.Cod_Estabe = @PCodEstabe
    And it.Protocolo = @PNumPrt
    And it.Ctrl_Tributacao = '60'
    And IsNull(it.Xml_vBCSTRet,0) = 0

  OPEN NFEIT_Cr

  FETCH NEXT FROM NFEIT_Cr INTO @it_CodPrd, @it_CodLot, @it_NumSeqIte,
                                @it_VlrIte, @it_FlgBlqDsc

  WHILE @@FETCH_STATUS = 0
  BEGIN

    -- sbt incluida no preço
    Set @WFlgSbtEmbPrc = 0
    if Exists(Select 1
                From NFSCB cb Inner Join 
                     NFSIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Ser_Nota = it.Ser_Nota and cb.Num_Nota = it.Num_Nota Inner Join 
                     NEREF rf on cb.Cod_Estabe = rf.Cod_Estabe and cb.Ser_Nota = rf.Ser_DocRef and cb.Num_Nota = rf.Num_DocRef 
              Where rf.Cod_Estabe = @PCodEstabe
              And rf.Protocolo = @PNumPrt
              And rf.Tip_EntSai = 'S'
              And it.Cod_Produto = @it_CodPrd
              And IsNull(it.Vlr_SubsTribEmb,0) > 0 )
      Set @WFlgSbtEmbPrc = 1
 
    -- calcula tributacao
    Exec QG_CalcTributRetidosNFEIT @PCodEstabe, @PNumPrt, @it_CodPrd, @it_CodLot, @it_NumSeqIte,
                                   @cb_TipNot, @PCodRegTri, @WFlgSbtEmbPrc
    if @@error <> 0
      begin
        Rollback Transaction
        Return
      end
    
    FETCH NEXT FROM NFEIT_Cr INTO @it_CodPrd, @it_CodLot, @it_NumSeqIte,
                                  @it_VlrIte, @it_FlgBlqDsc
  END  -- while

  CLOSE NFEIT_Cr
  DEALLOCATE NFEIT_Cr

  COMMIT TRANSACTION
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ReprocessaPDV]
@CodEstabe int,
@CodPed int

AS

SET NOCOUNT ON

Begin Transaction

Update PDVCB
  Set Qtd_Itens = Qtd_Itens + 0
Where Cod_Estabe = @CodEstabe 
And Numero = @CodPed

Declare @TipPed varchar(1),
        @TipBlq varchar(2),
        @CodOriPed varchar(2),
        @FlgWms bit,
        @FatCnvImpFat int,
        @FlgLotEsp bit,
        @FlgLotNaoFra bit,
        @FlgTemPDVLT bit,
        @CodGrpCli int,
        @CodCliPag int,
		@QtdMesMinPrzVctLot int
        
Select @TipPed = cb.Tip_Pedido,
       @TipBlq = cb.Bloqueio,
       @CodOriPed = IsNull(cb.Cod_OrigemPdv,''),
       @FlgWms = IsNull(cb.Flg_Wms,0),
       @FlgLotEsp = Case 
                      When IsNull(cb.Num_Referencia,0) > 0 then 1 
                      Else 0 
                    End,
       @FlgLotNaoFra = Case
                         When (IsNull(cb.Cod_Contrato,0) > 0) and (CharIndex(cb.Tip_Consumidor,'PEM') > 0) Then 1
                         Else 0
                       End,
       @CodGrpCli = IsNull(cb.Cod_GrpCli,0),
	   @CodCliPag = IsNull(cl.Cod_CliPag,0),
	   @QtdMesMinPrzVctLot = IsNull(cl.Qtd_MesMinPrzVctLot,0)
  from PDVCB cb
       Left Outer Join CLIEN cl on cb.Cod_Cliente = cl.Codigo
Where cb.Cod_Estabe = @CodEstabe 
And cb.Numero = @CodPed

if @TipPed = 'P' and @TipBlq = 'SR' 
  begin
    Declare @CodPrd int, 
            @CodLot varchar(20),
            @TipSai varchar(1),
            @CodPrm int,
            @CodKitPrm int,
            @QtdPed int,
            @QtdBon int

    Declare PDVIT_Cr Cursor Local Fast_Forward For 
      Select Cod_Produto, Cod_Lote, Tip_Sai, IsNull(Cod_Promocao,0), IsNull(Cod_KitPrm,0), IsNull(Qtd_Pedido,0), IsNull(Qtd_Bonificacao,0),
             Case 
               When IsNull(Fat_CnvImpFat,1) = 0 then 1
               Else IsNull(Fat_CnvImpFat,1)
             End
        From PDVIT 
      Where Cod_Estabe = @CodEstabe
      And Cod_Pedido = @CodPed
      And IsNull(Qtd_Pedido,0) > 0
    Open PDVIT_Cr
    Fetch Next From PDVIT_Cr Into @CodPrd, @CodLot, @TipSai, @CodPrm, @CodKitPrm, @QtdPed, @QtdBon, @FatCnvImpFat
    While @@FETCH_STATUS = 0
      begin
        if @FlgWms = 0
          EXEC PR_SolicitaLoteProduto @CodEstabe, @CodPed, @FlgLotEsp, @CodPrd, @CodLot, @TipSai, @CodPrm, @CodKitPrm, @QtdPed, @QtdBon, @FatCnvImpFat, @FlgLotNaoFra
        else
          begin
            Set @FlgTemPDVLT = 0
            if Exists(Select 1 From PDVLT Where Cod_Estabe = @CodEstabe and Cod_Pedido = @CodPed)
              Set @FlgTemPDVLT = 1
            EXEC PR_IncrementaSaldoSolicitado @CodEstabe, @CodPed, @CodGrpCli, @CodCliPag, @QtdMesMinPrzVctLot, @CodOriPed, @FlgTemPDVLT, @CodPrd, @CodLot, @TipSai, @CodPrm, @QtdPed, @QtdBon, @FatCnvImpFat
          end  
        Fetch Next From PDVIT_Cr Into @CodPrd, @CodLot, @TipSai, @CodPrm, @CodKitPrm, @QtdPed, @QtdBon, @FatCnvImpFat
      end
    Close PDVIT_Cr
    Deallocate PDVIT_Cr

  end

Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ReorganizaVolumePDVLT_CPVCB]
@CodEstabe int,
@CodPed int           -- num. do pedido

AS

SET NOCOUNT ON 

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

if Charindex((Select Status2 From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @CodPed),'N;D') > 0 
  RAISERROR('Pedido já faturado',16,1)
else
if ((Select Status1 From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @CodPed) <> 'P' ) or
   ((Select Status2 From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @CodPed) <> 'F' )
  RAISERROR('Pedido não está pendente/fechado',16,1)
else
if (Select IsNull(Bloqueio,'') From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @CodPed) <> '' 
  RAISERROR('Pedido está bloqueado',16,1)
else
if Not Exists(Select 1 From PDVLT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed)
  RAISERROR('Pedido não solicitou lotes',16,1)
else
if Exists(Select 1 From CPVCB Where Cod_Estabe = @CodEstabe And Num_PedCnf = @CodPed And Sta_PedCnf = '1')
  RAISERROR('Existe Conferência encerrada do Pedido',16,1)
else
begin
  Begin Transaction 

  Declare @QtdReg int,
          @NumVolMax int,
          @NumVol int,
          @NumSeq int

  Select @QtdReg = count(*) , @NumVolMax = max(Num_Vol)
    From (Select distinct Num_Vol
            From PDVLT
          Where Cod_Estabe = @CodEstabe 
          And Cod_Pedido = @CodPed) a
  Set @QtdReg = IsNull(@QtdReg,0)
  Set @NumVolMax = IsNull(@NumVolMax,0)
  
  -- verifca se reorganiza volumes
  if @QtdReg <> @NumVolMax 
    begin
      Set @NumSeq = 0
      Declare PDVLT_Cr Cursor Local Fast_Forward For
        Select distinct Num_Vol From PDVLT
        Where Cod_Estabe = @CodEstabe 
        And Cod_Pedido = @CodPed
        Order by Num_Vol 
      Open PDVLT_Cr
      Fetch Next From PDVLT_Cr Into @NumVol
      While @@FETCH_STATUS = 0
        begin
          Set @NumSeq = @NumSeq + 1
          if @NumVol > @NumSeq
            begin
              -- ajusta volume PDVLT
              Update PDVLT
                Set Num_Vol = @NumSeq
              Where Cod_Estabe = @CodEstabe 
              And Cod_Pedido = @CodPed
              And Num_Vol = @NumVol
                
              -- ajusta volume CPVCB
              Update CPVCB
                Set Num_VolCnf = @NumSeq
              Where Cod_Estabe = @CodEstabe 
              And Num_PedCnf = @CodPed
              And Num_VolCnf = @NumVol
            end
            
          Fetch Next From PDVLT_Cr Into @NumVol
        end    -- While @@FETCH_STATUS = 0
      Close PDVLT_Cr
      Deallocate PDVLT_Cr
    end

  Commit Transaction
  
end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_RecalculaNFS_SbtRes]
@PCodEstabe int,
@PSerNot varchar(3),
@PNumNot int

AS

SET NOCOUNT ON

Begin Transaction

if Exists(Select 1
            From NFSCB cb Inner Join 
                 NFSIT it on ((cb.Cod_Estabe = it.Cod_Estabe) and (cb.Ser_Nota = it.Ser_Nota) and (cb.Num_Nota = it.Num_Nota)) 
          Where cb.Cod_Estabe = @PCodEstabe 
          And cb.Ser_Nota = @PSerNot 
          And cb.Num_Nota = @PNumNot
          And cb.Status <> 'A'
          And ((cb.Cod_ModDoc <> '55') or
               ((cb.Cod_ModDoc = '55') and (IsNull(cb.Ret_CStat,0) > 0))) 
          And it.Qtd_Produto > 0
          And it.Ctrl_Tributacao = '60' 
          And IsNull(it.Vlr_SubsTrib,0) > 0)
 begin
   Declare @WValBasSbt numeric(18,4),
           @WValSbt numeric(18,4),
           @WValBasSbtRes numeric(18,4),
           @WValSbtRes numeric(18,4)

   -- armazena SBT inicial
   Select @WValBasSbt = IsNull(Vlr_BasSubsTrib,0),
          @WValSbt = IsNull(Vlr_SubsTrib,0)
     From NFSCB          
   Where Cod_Estabe = @PCodEstabe 
   And Ser_Nota = @PSerNot 
   And Num_Nota = @PNumNot

   -- calcula SBT ressarcimento CST = '60'       
   Select @WValBasSbtRes = ROUND(SUM(IsNull(Vlr_BasSubsTrib,0)),2),
          @WValSbtRes = ROUND(SUM(IsNull(Vlr_SubsTrib,0)),2)
     From NFSIT          
   Where Cod_Estabe = @PCodEstabe 
   And Ser_Nota = @PSerNot 
   And Num_Nota = @PNumNot
   And Ctrl_Tributacao = '60' 
   And IsNull(Vlr_SubsTrib,0) > 0

    if not Exists(Select 1
                    From NFSIT
                  Where Cod_Estabe = @PCodEstabe 
                  And Ser_Nota = @PSerNot 
                  And Num_Nota = @PNumNot
                  And Ctrl_Tributacao <> '60' 
                  And IsNull(Vlr_SubsTrib,0) > 0)
      begin
        Set @WValBasSbtRes = @WValBasSbt
        Set @WValSbtRes = @WValSbt
      end

    -- normaliza campos
    if @WValBasSbtRes > @WValBasSbt
      Set @WValBasSbtRes = @WValBasSbt
    if @WValSbtRes > @WValSbt
      Set @WValSbtRes = @WValSbt
      
    -- atualiza SBT ressarcimento nos itens
    Update NFSIT
      Set Vlr_BasSbtRes = IsNull(Vlr_BasSubsTrib,0),
          Vlr_SbtRes = IsNull(Vlr_SubsTrib,0)
    Where Cod_Estabe = @PCodEstabe 
    And Ser_Nota = @PSerNot 
    And Num_Nota = @PNumNot
    And Ctrl_Tributacao = '60'

    Update NFSIT
      Set Vlr_BasSubsTrib = 0,
          Vlr_SubsTrib = 0
    Where Cod_Estabe = @PCodEstabe 
    And Ser_Nota = @PSerNot 
    And Num_Nota = @PNumNot
    And Ctrl_Tributacao = '60' 

    Update NFSIT
      Set Vlr_BasSbtRes = 0
    Where Cod_Estabe = @PCodEstabe 
    And Ser_Nota = @PSerNot 
    And Num_Nota = @PNumNot
    And Vlr_BasSbtRes Is Null

    Update NFSIT
      Set Vlr_SbtRes = 0
    Where Cod_Estabe = @PCodEstabe 
    And Ser_Nota = @PSerNot 
    And Num_Nota = @PNumNot
    And Vlr_SbtRes Is Null

    -- atualiza SBT ressarcimento no cabecalho
    Update NFSCB
      Set Vlr_BasSbtRes = @WValBasSbtRes,
          Vlr_SbtRes = @WValSbtRes,
          Vlr_BasSubsTrib = Vlr_BasSubsTrib - @WValBasSbtRes,           
          Vlr_SubsTrib = Vlr_SubsTrib - @WValSbtRes
    Where Cod_Estabe = @PCodEstabe 
    And Ser_Nota = @PSerNot 
    And Num_Nota = @PNumNot
   
 end          

Commit Transaction

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_RecalculaNFE_SbtRes]
@PCodEstabe int,
@PNumPrt int

AS

SET NOCOUNT ON

Begin Transaction

if Exists(Select 1
            From NFECB cb Inner Join 
                 NFEIT it on (cb.Cod_Estabe = it.Cod_Estabe) and (cb.Protocolo = it.Protocolo) 
          Where cb.Cod_Estabe = @PCodEstabe
          and cb.Protocolo = @PNumPrt
          And Charindex(cb.Status,';C;F;') > 0
          And ((cb.Cod_ModDoc <> '55') or
               ((cb.Cod_ModDoc = '55') and (IsNull(cb.Ret_CStat,0) > 0))) 
          And it.Qtd_Pedido > 0
          And it.Ctrl_Tributacao = '60' 
          And IsNull(it.Vlr_SubsTrib,0) > 0)
 begin
   Declare @WValBasSbt numeric(18,4),
           @WValSbt numeric(18,4),
           @WValBasSbtRes numeric(18,4),
           @WValSbtRes numeric(18,4)

   -- armazena SBT inicial
   Select @WValBasSbt = IsNull(Vlr_BasIstFon,0),
          @WValSbt = IsNull(Vlr_IstFon,0)
     From NFECB          
   Where Cod_Estabe = @PCodEstabe
   and Protocolo = @PNumPrt

   -- calcula SBT ressarcimento CST = '60'       
   Select @WValBasSbtRes = ROUND(SUM(IsNull(Vlr_BasSubsTrib,0)),2),
          @WValSbtRes = ROUND(SUM(IsNull(Vlr_SubsTrib,0)),2)
     From NFEIT          
   Where Cod_Estabe = @PCodEstabe
   and Protocolo = @PNumPrt
   And Ctrl_Tributacao = '60' 
   And IsNull(Vlr_SubsTrib,0) > 0

    if not Exists(Select 1
                    From NFEIT
                  Where Cod_Estabe = @PCodEstabe
                  and Protocolo = @PNumPrt
                  And Ctrl_Tributacao <> '60' 
                  And IsNull(Vlr_SubsTrib,0) > 0)
      begin
        Set @WValBasSbtRes = @WValBasSbt
        Set @WValSbtRes = @WValSbt
      end

    -- normaliza campos
    if @WValBasSbtRes > @WValBasSbt
      Set @WValBasSbtRes = @WValBasSbt
    if @WValSbtRes > @WValSbt
      Set @WValSbtRes = @WValSbt
      
    -- atualiza SBT ressarcimento nos itens
    Update NFEIT
      Set Vlr_BasSbtRes = IsNull(Vlr_BasSubsTrib,0),
          Vlr_SbtRes = IsNull(Vlr_SubsTrib,0)
    Where Cod_Estabe = @PCodEstabe
    and Protocolo = @PNumPrt
    And Ctrl_Tributacao = '60'

    Update NFEIT
      Set Vlr_BasSubsTrib = 0,
          Vlr_SubsTrib = 0
    Where Cod_Estabe = @PCodEstabe
    and Protocolo = @PNumPrt
    And Ctrl_Tributacao = '60' 

    Update NFEIT
      Set Vlr_BasSbtRes = 0
    Where Cod_Estabe = @PCodEstabe
    and Protocolo = @PNumPrt
    And Vlr_BasSbtRes Is Null

    Update NFEIT
      Set Vlr_SbtRes = 0
    Where Cod_Estabe = @PCodEstabe
    and Protocolo = @PNumPrt
    And Vlr_SbtRes Is Null

    -- atualiza SBT ressarcimento no cabecalho
    Update NFECB
      Set Vlr_BasSbtRes = @WValBasSbtRes,
          Vlr_SbtRes = @WValSbtRes,
          Vlr_BasIstFon = Vlr_BasIstFon - @WValBasSbtRes,           
          Vlr_IstFon = Vlr_IstFon - @WValSbtRes
    Where Cod_Estabe = @PCodEstabe
    and Protocolo = @PNumPrt
   
 end          

Commit Transaction

GO

