CREATE PROCEDURE [dbo].[PR_ReabrePdv] 
@CodEstabe int,
@CodPed int

AS

SET NOCOUNT ON

Begin Transaction

Declare @TipBlq varchar(2),
        @TipFat varchar(3),
        @CodOriPdv varchar(1),
        @CodCli int,
        @NumPdvLig int

Update PDVCB
  Set Qtd_Itens = Qtd_Itens + 0,
      Flg_Calc = 1,
      Flg_CriIteFec = 1
Where Cod_Estabe = @CodEstabe    
And Numero = @CodPed

-- estorna rateio de descontos bonificados
if Exists(Select 1 From PDVIT Where Cod_Estabe = @CodEstabe and Cod_Pedido = @CodPed And ((IsNull(Vlr_DscBonRat,0) > 0) or (Vlr_DscBonRat is null))) 
  begin
    Declare @CodPrd int, 
            @CodLot varchar(20), 
            @TipSai varchar(1) 

    DECLARE Table_Cr CURSOR Local Fast_Forward For 
    
    Select Cod_Produto, Cod_Lote, Tip_Sai 
      From PDVIT 
    Where Cod_Estabe = @CodEstabe
    And Cod_Pedido = @CodPed 
    And ((IsNull(Vlr_DscBonRat,0) > 0) or (Vlr_DscBonRat is null))
  
    OPEN Table_Cr 
    FETCH NEXT FROM Table_Cr INTO @CodPrd, @CodLot, @TipSai 
    WHILE @@FETCH_STATUS = 0 
    BEGIN 
      Update PDVIT
        Set Vlr_DscBonRat = 0  
      Where Cod_Estabe = @CodEstabe
      And Cod_Pedido = @CodPed
      And Cod_Produto = @CodPrd
      And Cod_Lote = @CodLot
      And Tip_Sai =  @TipSai 
  
      EXEC PR_CalcTributPdvit @CodEstabe, @CodPed, @CodPrd, @CodLot, @TipSai 
      FETCH NEXT FROM Table_Cr INTO @CodPrd, @CodLot, @TipSai 
    END 
    CLOSE Table_Cr 
    DEALLOCATE Table_Cr 

    -- Atualiza cabeçalho do pedido
    EXEC PR_AtualizaCabecPDV @CodEstabe, @CodPed 

    -- Atualiza flag de critica de fechamento cabeçalho do pedido '+
    Update PDVCB 
      Set Flg_CriIteFec = 0 
    Where Cod_Estabe = @CodEstabe
    And Numero = @CodPed 
  end

-- estorna pedidos bonificados
Select @TipBlq = Bloqueio,
       @TipFat = Tip_Faturamento,
       @CodCli = Cod_Cliente,
       @CodOriPdv = SUBSTRING(Cod_OrigemPdv,1,1),
       @NumPdvLig = IsNull(Num_PdvLig,0)
  from PDVCB
Where Cod_Estabe = @CodEstabe
And Numero = @CodPed

if (@NumPdvLig > 0) and (@CodOriPdv <> 'D')
  if (Select SUBSTRING(Cod_OrigemPdv,1,1) From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @NumPdvLig) = 'D'
    begin
      Update PDVCB
        Set Qtd_Itens = Qtd_Itens + 0
      Where Cod_Estabe = @CodEstabe
      And Numero = @NumPdvLig
      
      -- nao deveria acontecer mas elimina itens do pedido bonificado que nao existe no pedido de origem  
      Delete p2
        From PDVIT p2 Left Outer Join 
             (Select Cod_Produto, Cod_Lote
              From PDVIT
              Where Cod_Estabe = @CodEstabe
              And Cod_Pedido = @CodPed 
              And Qtd_Pedido > 0) p1 on ((p1.Cod_Produto = p2.Cod_Produto) and (p1.Cod_Lote = p2.Cod_Lote))
      Where p2.Cod_Estabe = @CodEstabe      
      And p2.Cod_Pedido = @NumPdvLig
      And p1.Cod_Produto is null
        
      -- muda o bloqueio temporariamente para nao decrementar saldos
      -- ajusta Flg_CriIteFec = 1 para forçar recalculo de tributos
      Update PDVCB
        Set Bloqueio = 'SR',
            Flg_CriIteFec = 1
      Where Cod_Estabe = @CodEstabe
      And Numero = @CodPed
        
      Update PDVCB
        Set Bloqueio = 'SR',
            Flg_Calc = 1,
            Flg_CriIteFec = 1
      Where Cod_Estabe = @CodEstabe    
      And Numero = @NumPdvLig
        
      -- estorna quantidades
      Update p1
        Set p1.Qtd_Bonificacao = p1.Qtd_Bonificacao + p2.Qtd_Pedido + p2.Qtd_Bonificacao,
            p1.Qtd_Solicitado = p1.Qtd_Solicitado + p2.Qtd_Pedido + p2.Qtd_Bonificacao,
            p1.Qtd_Pra = p1.Qtd_Pra + p2.Qtd_Pra,
            p1.Qtd_Dep = p1.Qtd_Dep + p2.Qtd_Dep
        From PDVIT p1, PDVIT p2
      Where p1.Cod_Estabe = @CodEstabe
      And p1.Cod_Pedido = @CodPed
      And p2.Cod_Estabe = @CodEstabe
      And p2.Cod_Pedido = @NumPdvLig
      And p1.Cod_Produto = p2.Cod_Produto
      And p1.Cod_Lote = p2.Cod_Lote
      And p2.Qtd_Pedido > 0
        
      -- elimina pedido bonificado
      Delete From PDVIT
      Where Cod_Estabe = @CodEstabe
      And Cod_Pedido = @NumPdvLig
         
      Delete From PDVCB
      Where Cod_Estabe = @CodEstabe
      And Numero = @NumPdvLig 

      Delete From CPVIT 
      Where Cod_Estabe = @CodEstabe
      And Num_PedCnf = @NumPdvLig

      Delete From CPVCB 
      Where Cod_Estabe = @CodEstabe
      And Num_PedCnf = @NumPdvLig

      Update PDVCB
        Set Bloqueio = @TipBlq
      Where Cod_Estabe = @CodEstabe
      And Numero = @CodPed
  
    end

Update PDVCB
  Set Flg_Calc = 0
Where Cod_Estabe = @CodEstabe
And Numero = @CodPed

if @TipBlq = 'SR' 
  Exec PR_ReprocessaPDV @CodEstabe, @CodPed

--AnalisaCreditoCliente

Update cb
  Set cb.Bloqueio = null,
      cb.Status2 = 'A',
      cb.Hor_Fechamento = null,
      cb.Hor_Liberacao = null,
      cb.Hor_PreNota = null,
      cb.Hor_ConferFim = null,
      cb.Nom_UsuDesbloq = Case 
                            When IsNull(pa.FlgDispenPwdPedRea,0) = 0 then ''
                           End,
      cb.Msg_Bloqueio = null,
      cb.Hor_DbqFin = null,
      cb.Cod_BlqRnt = null,
      cb.Nom_UsuDesbloqRnt = '',
      cb.Hor_DbqRnt = null,
      cb.Cod_BlqLic = null,
      cb.Nom_UsuDesbloqLic = '',
      cb.Hor_DbqLic = null,
      cb.Num_Lote = 0,                         -- p/ funcionarios
      cb.Flg_GerCtrFal = 0,
      cb.Num_PdvLig = 0
  From PDVCB cb, PARAM pa    
  Where cb.Cod_Estabe = pa.Cod_Estabe 
  and cb.Cod_Estabe = @CodEstabe
  And cb.Numero = @CodPed

-- Reabre conferencia
Update CPVCB 
  Set Sta_PedCnf = '0',
      Hor_FimCnf = null 
Where Cod_Estabe = @CodEstabe
And Num_PedCnf = @CodPed

-- repoe o flag de credito do cliente
--  if Pos(PdvcbTblTip_Faturamento.Value,'FAT;ORC') <> 0 then
--    PdvcbTblFlg_Credito.Value := WSta;

Commit Transaction

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ProcessaResumoGeral]
  @PMes int
, @PAno int

AS

SET NOCOUNT ON

if (@PMes > 0) and (@PMes < 13) and (@PAno > 1950)
  begin
    Begin Transaction

    Declare @WCodEstabe int

    -- elimina registro do periodo
    Delete From ACMEN
     Where Mes_Movimento = @PMes
       and Ano_Movimento = @PAno

    -- insere registro 
    Insert into ACMEN (Cod_Estabe, Ano_Movimento, Mes_Movimento)
      Select distinct Cod_Estabe, @PAno, @PMes From ESTAB

    -- ACEMP
    Update am
       Set Vlr_Compras   = ae.VlrEntCom
         , Vlr_EntDev    = ae.VlrEntDev
         , Vlr_EntTrf    = ae.VlrEntTrf
         , Vlr_OutEnt    = ae.VlrEntOut
         , Vlr_Vendas    = ae.VlrSaiVen
         , Vlr_SaiDev    = ae.VlrSaiDev
         , Vlr_SaiTrf    = ae.VlrSaiTrf
         , Vlr_OutSai    = ae.VlrSaiOut
         , Vlr_DesCom    = ae.VlrDscCom
         , Qtd_NotCom    = ae.QtdNotEntCom
         , Qtd_NotEntDev = ae.QtdNotEntDev
         , Qtd_NotEntTrf = ae.QtdNotEntTrf
         , Qtd_NotOutEnt = ae.QtdNotEntOut
         , Qtd_NotVen    = ae.QtdNotSaiVen
         , Qtd_NotSaiDev = ae.QtdNotSaiDev
         , Qtd_NotSaiTrf = ae.QtdNotSaiTrf
         , Qtd_NotOutSai = ae.QtdNotSaiOut
         , Qtd_UniCom    = ae.QtdUniEntCom
         , Qtd_UniEntDev = ae.QtdUniEntDev
         , Qtd_UniEntTrf = ae.QtdUniEntTrf
         , Qtd_UniOutEnt = ae.QtdUniEntOut
         , Qtd_UniVen    = ae.QtdUniSaiVen
         , Qtd_UniSaiDev = ae.QtdUniSaiDev
         , Qtd_UniSaiTrf = ae.QtdUniSaiTrf
         , Qtd_UniOutSai = ae.QtdUniSaiOut
         , Qtd_Pedidos   = ae.QtdPedVen

      From ACMEN am
           Inner Join (Select Cod_Estabe
                            , VlrEntCom    = sum(IsNull(Vlr_Nfe,0))
                            , VlrEntDev    = sum(IsNull(Vlr_NfeDev,0))
                            , VlrEntTrf    = sum(IsNull(Vlr_NfeTrf,0))
                            , VlrEntOut    = sum(IsNull(Vlr_NfeOut,0))
                            , VlrSaiVen    = sum(IsNull(Vlr_TotNfsFat,0) + Isnull(Vlr_TotNfsOrc,0) + IsNull(Vlr_TotNfsFun,0) + Isnull(Vlr_TotNfsCon,0))
                            , VlrSaiDev    = sum(IsNull(Vlr_TotNfsDev,0))
                            , VlrSaiTrf    = sum(IsNull(Vlr_TotNfsTrf,0))
                            , VlrSaiOut    = sum(IsNull(Vlr_TotNfsOut,0))
                            , VlrDscCom    = sum(IsNull(Vlr_DesCom,0))
                            , QtdNotEntCom = cast(sum(IsNull(Qtd_Nfe,0)) as int)
                            , QtdNotEntDev = cast(sum(IsNull(Qtd_NfeDev,0)) as int)
                            , QtdNotEntTrf = cast(sum(IsNull(Qtd_NfeTrf,0)) as int)
                            , QtdNotEntOut = cast(sum(IsNull(Qtd_NfeOut,0)) as int)
                            , QtdNotSaiVen = cast(sum(IsNull(Qtd_NfsFat,0)) as int)
                            , QtdNotSaiDev = cast(sum(IsNull(Qtd_NfsDev,0)) as int)
                            , QtdNotSaiTrf = cast(sum(IsNull(Qtd_NfsTrf,0)) as int)
                            , QtdNotSaiOut = cast(sum(IsNull(Qtd_NfsOut,0)) as int)
                            , QtdUniEntCom = cast(sum(IsNull(Qtd_UniCom,0)) as int)
                            , QtdUniEntDev = cast(sum(IsNull(Qtd_UniEntDev,0)) as int)
                            , QtdUniEntTrf = cast(sum(IsNull(Qtd_UniEntTrf,0)) as int)
                            , QtdUniEntOut = cast(sum(IsNull(Qtd_UniEntOut,0)) as int)
                            , QtdUniSaiVen = cast(sum(IsNull(Qtd_UniVen,0)) as int)
                            , QtdUniSaiDev = cast(sum(IsNull(Qtd_UniSaiDev,0)) as int)
                            , QtdUniSaiTrf = cast(sum(IsNull(Qtd_UniSaiTrf,0)) as int)
                            , QtdUniSaiOut = cast(sum(IsNull(Qtd_UniSaiOut,0)) as int)
                            , QtdPedVen    = cast(sum(IsNull(Qtd_NfsFat,0) + Isnull(Qtd_NfsOrc,0)) as int)
                         From ACEMP 
                        Where Month(Dat_Movimento) = @PMes 
                          And Year(Dat_Movimento)  = @PAno
                        Group by Cod_Estabe) ae on am.Cod_Estabe = ae.Cod_Estabe
     Where am.Ano_Movimento = @PAno 
       And am.Mes_Movimento = @PMes

    -- NFSCB
    Update am
       Set Qtd_PrzMed    = ns.QtdPrzMed
         , Per_DscFinPon = ns.DscFinVen
         , Vlr_Comissao  = ns.VlrComiss
         , Vlr_DesPrm    = ns.VlrDscPrm

      From ACMEN am
           Inner Join (Select Cod_Estabe
                            , QtdPrzMed = Case 
                                            When sum(IsNull(Vlr_TotalNota,0)) > 0 then sum(IsNull(IsNull(Qtd_PrzMed,0)*Vlr_TotalNota,0))/sum(IsNull(Vlr_TotalNota,0))
                                            Else 0
                                          End
                            , DscFinVen = Case
                                            When sum(IsNull(Vlr_TotalNota,0)) > 0 then sum(IsNull(IsNull(Per_DescontoFin,0)*Vlr_TotalNota,0))/sum(IsNull(Vlr_TotalNota,0))
                                            Else 0
                                          End
                            , VlrComiss  = sum(IsNull(Vlr_Comissao,0)+IsNull(Vlr_ComTlmkt,0)+IsNull(Vlr_ComSup,0)+IsNull(Vlr_ComGer,0)+IsNull(Vlr_ComSupOpe,0)+IsNull(Vlr_ComGerOpe,0))
                            , VlrDscPrm  = sum(IsNull(VlrBruItens - Vlr_LiqItens,0)) 
                         From NFSCB 
                        Where Year(Dat_Emissao) = @PAno 
                          And Month(Dat_Emissao) = @PMes 
                          And Tip_Saida = 'V' 
                          And Status = 'F'
                        Group by Cod_Estabe) ns on am.Cod_Estabe = ns.Cod_Estabe
     Where am.Ano_Movimento = @PAno 
       And am.Mes_Movimento = @PMes

    -- Rentabilidade
	Update am
       Set am.Per_Rentab = rn.Per_Rentab
         , am.Vlr_Rentab = rn.Val_Rentab
      From ACMEN am inner Join
           (Select x.Cod_Estabe
                 , Per_Rentab = dbo.FN_PerLucro(x.Val_Venda,x.Val_Ressarcimento,x.Val_CustoLiquido)
                 , Val_Rentab = x.Val_Venda+x.Val_Ressarcimento-x.Val_CustoLiquido
              From (Select cb.Cod_Estabe
                         , Sum(it.ValLiqVen) Val_Venda
                         , Sum(it.ValRes) Val_Ressarcimento
                         , Sum(dbo.FN_ValCustosRentab('L',
			                        cb.Cod_Estabe,
                                    cb.Dat_Emissao,
                                    it.Cod_Produto,
                                    it.QtdPrd,
                                    it.ValLiqVen,     
                                    0,                                             -- @PVlrCusBas   
                                    it.ValPis,
                                    it.ValCof,
                                    it.ValIcm,
                                    it.ValRes,
                                    it.ValComiss,
                                    it.ValFrete,  -- frete
									it.ValVrbPar+it.ValVrbBon, 
									it.ValDspOpe,
									it.ValIrpj, 
									it.ValConSoc)) Val_CustoLiquido
                    From dbo.V_NFSIT_Rent it 
                             Inner Join dbo.V_NFSCB_Rent cb on ((cb.Cod_Estabe = it.Cod_Estabe) and (cb.Ser_Nota = it.Ser_Nota) and (cb.Num_Nota = it.Num_Nota)) 
                   Where YEAR(cb.Dat_Emissao) = @PAno
                     And MONTH(cb.Dat_Emissao) = @PMes
                     And cb.Status = 'F'
                     And cb.Tip_Saida = 'V'
                   Group by cb.Cod_Estabe) x) rn on am.Cod_Estabe = rn.Cod_Estabe

     Where am.Ano_Movimento = @PAno 
       and am.Mes_Movimento = @PMes

    -- NFECB
    Update am
       Set Qtd_PrzMedCom = IsNull(ne.QtdPrzMed,0)
      From ACMEN am
           Left Join (Select Cod_Estabe
                            , QtdPrzMed = Case 
                                            When sum(IsNull(Vlr_Nota,0)) > 0 then sum(IsNull(Qtd_PrzMed,0)*IsNull(Vlr_Nota,0))/sum(IsNull(Vlr_Nota,0)) 
                                            Else 0.00
                                          End
                         From NFECB 
                        Where Year(Dat_Movimento) = @PAno 
                          And Month(Dat_Movimento) = @PMes 
                          And Tip_NF = 'C' 
                          And Status = 'F'
                        Group by Cod_Estabe) ne on am.Cod_Estabe = ne.Cod_Estabe
     Where am.Ano_Movimento = @PAno 
       And am.Mes_Movimento = @PMes

    -- atualiza geral
    Set @WCodEstabe = -1
	
    While Exists(Select 1
                   From ESTAB
                  Where Cod_Estabe > @WCodEstabe)
    BEGIN
      Set @WCodEstabe = (Select top 1 Cod_Estabe
                           From ESTAB 
                          Where Cod_Estabe > @WCodEstabe
                          Order by Cod_Estabe)

      -- atualiza ACMEN
      Update ACMEN
         Set Qtd_Titulos    = (Select count(*) From CTREC Where Cod_Estabe = @WCodEstabe And Month(Dat_Emissao) = @PMes and Year(Dat_Emissao) = @PAno and Status <> 'C')
           , Vlr_Recebidos  = (Select sum(IsNull(Vlr_Principal,0)-IsNull(Vlr_Desconto,0)-IsNull(Vlr_Deducoes,0)-IsNull(Vlr_DscDev,0)+IsNull(Vlr_Multa,0)+IsNull(Vlr_Juros,0)+IsNull(Vlr_Acrescimos,0)) 
                                From BXREC Where Cod_Estabe = @WCodEstabe And Month(Dat_Caixa) = @PMes and Year(Dat_Caixa) = @PAno 
                                 And ((Status = 'Q') or (Status = 'P')))
           , Vlr_DscConRec  = (Select sum(IsNull(Vlr_Desconto,0)+IsNull(Vlr_Deducoes,0)+IsNull(Vlr_DscDev,0)) 
                                From BXREC Where Cod_Estabe = @WCodEstabe And Month(Dat_Caixa) = @PMes and Year(Dat_Caixa) = @PAno 
                                 And ((Status = 'Q') or (Status = 'P')))
           , Vlr_JurCobRec  = (Select sum(IsNull(Vlr_Juros,0)+IsNull(Vlr_Acrescimos,0)+IsNull(Vlr_Multa,0)) 
                                 From BXREC Where Cod_Estabe = @WCodEstabe And Month(Dat_Caixa) = @PMes and Year(Dat_Caixa) = @PAno 
                                  And ((Status = 'Q') or (Status = 'P')))
           , Qtd_PrzMedRec  = (Select Case
                                        When sum(cr.Vlr_Documento) > 0 then
                                          cast(sum(cr.Vlr_Documento*cr.Prazo_Recebimento)/sum(cr.Vlr_Documento) as int)
                                        Else 0
                                      End
                                 From (Select Vlr_Documento, Prazo_Recebimento = DateDiff(day,Dat_Emissao,Dat_Quitacao) 
                                         From CTREC
                                        Where Cod_Estabe = @WCodEstabe 
                                          And Year(Dat_Emissao) = @PAno And MONTH(Dat_Emissao) = @PMes
                                          And Status = 'Q') cr)
           , Qtd_AtrMedRec  = (Select Case 
                                        when sum(Vlr_Documento) > 0 then 
                                          cast(sum(Vlr_Documento*Atraso_Recebimento)/sum(Vlr_Documento) as int)
                                        else 0
                                      End
                                 From (Select Vlr_Documento, Atraso_Recebimento = DateDiff(day,Dat_Vencimento,Dat_Quitacao) 
                                         From CTREC
                                        Where Cod_Estabe = @WCodEstabe 
                                          And Year(Dat_Vencimento) = @PAno And MONTH(Dat_Emissao) = @PMes
                                          And Status = 'Q') cr)


            , Vlr_Pagos     = (Select sum(IsNull(bx.Val_Princi,0)-IsNull(bx.Val_Descon,0)-IsNull(bx.Val_OutDed,0)-IsNull(bx.Val_DscDev,0)+IsNull(bx.Val_Multa,0)+IsNull(bx.Val_Juros,0)+IsNull(bx.Val_OutAcr,0)) 
			                     From PAGBX bx 
                                      Inner Join PAGCT cp on bx.Cod_Estabe = cp.Cod_Estabe and bx.Cod_CtaPag = cp.Cod_CtaPag 
                                Where bx.Cod_Estabe = @WCodEstabe And Month(bx.Dat_Lancam) = @PMes and Year(bx.Dat_Lancam) = @PAno 
                                  And cp.Sta_Docume = 'Q')
            , Vlr_DscObtPag = (Select sum(IsNull(bx.Val_Descon,0)-IsNull(bx.Val_OutDed,0)-IsNull(bx.Val_DscDev,0)) 
                                 From PAGBX bx 
                                      Inner Join PAGCT cp on bx.Cod_Estabe = cp.Cod_Estabe and bx.Cod_CtaPag = cp.Cod_CtaPag 
						        Where bx.Cod_Estabe = @WCodEstabe And Month(bx.Dat_Lancam) = @PMes and Year(bx.Dat_Lancam) = @PAno
                                  And cp.Sta_Docume = 'Q')
            , Vlr_JurPagPag = (Select sum(IsNull(bx.Val_Multa,0)+IsNull(bx.Val_Juros,0)+IsNull(bx.Val_OutAcr,0)) 
                                 From PAGBX bx 
                                      Inner Join PAGCT cp on bx.Cod_Estabe = cp.Cod_Estabe and bx.Cod_CtaPag = cp.Cod_CtaPag 
                                Where bx.Cod_Estabe = @WCodEstabe And Month(bx.Dat_Lancam) = @PMes and Year(bx.Dat_Lancam) = @PAno 
                                  And cp.Sta_Docume = 'Q')
            , Qtd_PrzMedPag = (Select Case
                                        When sum(cp.Val_Docume) > 0 then
			                              cast(sum(cp.Val_Docume*cp.Prazo_Pagamento)/sum(cp.Val_Docume) as int)
									    Else 0
                                      End
                                 From (Select Val_Docume, Prazo_Pagamento =  DateDiff(day,Dat_Emissa,Dat_Quitac) 
                                         From PAGCT
                                        Where Cod_Estabe = @WCodEstabe 
                                          And Year(Dat_Emissa) = @PAno And MONTH(Dat_Emissa) = @PMes
                                          And Sta_Docume = 'Q') cp)

            , Qtd_CliVen    = (Select count(cl.Codigo) From CLIEN cl
                                Where Exists (Select 1
                                                From NFSIT it
                                                     Inner Join NFSCB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Ser_Nota = cb.Ser_Nota and it.Num_Nota = cb.Num_Nota
                                               Where cb.Cod_Estabe = @WCodEstabe 
                                                 And Month(cb.Dat_Emissao) = @PMes 
                                                 And Year(cb.Dat_Emissao) = @PAno 
                                                 And cb.Tip_Saida = 'V' and cb.Status = 'F'
                                                 And cb.Cod_Cliente = cl.Codigo))
            , Qtd_CliCad    = (Select count(cl.Codigo) From CLIEN cl 
                                Where IsNull(cl.Bloqueado,0) = 0 And (YEAR(cl.Data_Cadastro)*100+MONTH(cl.Data_Cadastro)) <= (@PAno*100+@PMes)
                                  And Exists(Select 1 
                                               From ENXES es Where es.Cod_Estabe = @WCodEstabe And es.Num_CgcCpf = cl.Cgc_Cpf))

            , Qtd_CidVen    = (Select count(distinct Cod_Cidade)
                                 From NFSCB 
                                Where Cod_Estabe = @WCodEstabe And Month(Dat_Emissao) = @PMes and Year(Dat_Emissao) = @PAno 
                                  And Tip_Saida = 'V' And Status = 'F' 
                                  And IsNull(Cod_Cidade,0) > 0)
            , Qtd_CidCad    = (Select count(distinct cl.Cod_Cidade) 
                                 From CLIEN cl
                                      Inner Join CIDAD ci on ci.Cod_Estado = cl.Cod_Estado and ci.Codigo = cl.Cod_Cidade 
                                Where (YEAR(cl.Data_Cadastro)*100+MONTH(cl.Data_Cadastro)) <= (@PAno*100+@PMes))

            , Qtd_FabVen    = (Select count(distinct pr.Cod_Fabricante)
                                 From NFSIT it
                                      Inner Join NFSCB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Ser_Nota = cb.Ser_Nota and it.Num_Nota = cb.Num_Nota
                                      Inner Join PRODU pr on it.Cod_Produto = pr.Codigo
                                Where cb.Cod_Estabe = @WCodEstabe 
                                  And Month(cb.Dat_Emissao) = @PMes 
                                  And Year(cb.Dat_Emissao) = @PAno 
                                  And cb.Tip_Saida = 'V' And cb.Status = 'F')
            , Qtd_FabCad    = (Select count(distinct fb.Codigo) 
                                 From FABRI fb 
                                      Inner Join PRODU pr on fb.Codigo = pr.Cod_Fabricante 
                                Where (YEAR(pr.Dat_Cadastro)*100+MONTH(pr.Dat_Cadastro)) <= (@PAno*100+@PMes)) 

            , Qtd_PrdVen    = (Select count(distinct it.Cod_Produto) 
                                 From NFSIT it
                                      Inner Join NFSCB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Ser_Nota = cb.Ser_Nota and it.Num_Nota = cb.Num_Nota
                                Where cb.Cod_Estabe = @WCodEstabe And Month(cb.Dat_Emissao) = @PMes and Year(cb.Dat_Emissao) = @PAno 
                                  And cb.Tip_Saida = 'V' and cb.Status = 'F')
            , Qtd_PrdCad    = (Select count(distinct pr.Codigo) 
                                 From PRODU pr 
                                Where (YEAR(pr.Dat_Cadastro)*100+MONTH(pr.Dat_Cadastro)) <= (@PAno*100+@PMes))

        Where Cod_Estabe    = @WCodEstabe 
          And Ano_Movimento = @PAno 
          and Mes_Movimento = @PMes
    END
    Commit Transaction
  end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ProIni_EncerraMes]
@CodEstabe int

WITH RECOMPILE
AS

SET NOCOUNT ON

Begin Transaction

  -- Pegar a data atual com a hora zerada 
  Set DateFormat ymd  
  Declare @Now smalldatetime,
          @Date smalldatetime,
      @pm_DatEncRotMen smalldatetime,
      @pm_QtdMesMedRotMen int,
        @AnoRef int,
        @MesRef int,
      @AnoMesPar int
        
  Set @Now = GetDate()
  Set @Date = cast(GetDate() as Date)

  -- verifica se executa encerramento mensal (todos os estabelecimentos)
  Select @pm_DatEncRotMen = IsNull(DatFecRotMen,0),
         @pm_QtdMesMedRotMen = IsNull(QtdMesMedRotMen,3)
    From PARAM 
   Where Cod_Estabe = @CodEstabe

  Set @AnoRef = DatePart(Year,@Date)
  Set @MesRef = DatePart(Month,@Date)
  Set @AnoMesPar = DatePart(Year,IsNull(@pm_DatEncRotMen,0))*100+DatePart(Month,IsNull(@pm_DatEncRotMen,0))

  if (@AnoRef*100+@MesRef) > @AnoMesPar
    begin
    Set @MesRef = @MesRef-1
    if @MesRef = 0
      begin
      Set @MesRef = 12
      Set @AnoRef = @AnoRef - 1
    end

      Exec PR_ProcessaClaABC @pm_QtdMesMedRotMen, 1, 1, 1
      if @@error <> 0
        begin
          Rollback Transaction
          Return
        end

      Exec PR_ProcessaResumoGeral @MesRef, @AnoRef
      if @@error <> 0
        begin
          Rollback Transaction
          Return
        end

      Exec PR_ProIni_ZeraVerbasMes -1     -- todos os estabelecimentos
      if @@error <> 0
        begin
          Rollback Transaction
          Return
        end

  end

Commit Transaction
GO


SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ProIni_ReservaProdutosVencidos] 
@CodEstabe int

WITH RECOMPILE
AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = cast(GetDate() as Date)

Begin Transaction

  Declare @WFlgUsaWms bit = 0,
          @pm_QtdDiaResPrdVen int,
          @pm_FlgResPrdVen bit,
          @DatLim smalldatetime,
          @pl_Chave int,
          @pl_CodDep smallint,
          @pl_CodPrd int,
          @pl_CodLot varchar(20),
          @pl_QtdSldPra int,
          @pl_QtdSldDep int,
          @rs_Numero int

  Set @WFlgUsaWms = (Select dbo.FN_ModExtOk(HASHBYTES('MD5','WMS'),
                                            HASHBYTES('MD5',(Select Num_Cnpj From dbo.ESTAB Where Cod_Estabe = @CodEstabe))))

  -- coloca campos de PARAM na memoria
  Select @pm_QtdDiaResPrdVen = Isnull(QtdDiaResPrdVen,0),
         @pm_FlgResPrdVen = IsNull(FlgResPrdVen,0)
    From PARAM
    Where Cod_Estabe = @CodEstabe

  if (@WFlgUsaWms = 0) and (@pm_FlgResPrdVen = 1)
    begin
      -- data de vencimento
      Set @DatLim = @Date + @pm_QtdDiaResPrdVen

      Declare @Tab Table(
        Chave Int Identity(1,1) PRIMARY KEY,
        Cod_Dep smallint, 
        Cod_Produt int, 
        Cod_Lote varchar(20), 
        Qtd_SldPra int,
        Qtd_SldDep int
      )

      -- seleciona lotes vencidos
      Insert Into @Tab (Cod_Dep, Cod_Produt, Cod_Lote, Qtd_SldPra, Qtd_SldDep)
        Select l.Cod_Dep, l.Cod_Produt, l.Cod_Lote, l.Qtd_SldPra, l.Qtd_SldDep
          From PRLOT l 
               inner Join PRXES p 
                       on l.Cod_Estabe = p.Cod_Estabe and l.Cod_Produt = p.Cod_Produt
          Where l.Cod_Estabe = @CodEstabe
            And l.Qtd_Saldo > 0 
            And IsNull(l.Dat_Vencim,0) > 0 
            And IsNull(l.Dat_Vencim,0) <= @DatLim 
            And p.Qtd_Dispon >= l.Qtd_Saldo

      -- reserva lotes vencidos
      While Exists(Select 1 From @Tab)
        begin
          Select top 1 @pl_Chave = Chave,
                       @pl_CodDep =  Cod_Dep,
                       @pl_CodPrd = Cod_Produt,
                       @pl_CodLot = Cod_Lote,
                       @pl_QtdSldPra = Qtd_SldPra,
                       @pl_QtdSldDep = Qtd_SldDep
            From @Tab
           Order by Chave

          Set @rs_Numero = IsNull((Select max(Numero) From RESER Where Cod_Estabe = @CodEstabe),0)
      
          While @rs_Numero >= 0
            begin
             Set @rs_Numero = @rs_Numero + 1
             if not Exists (Select Numero From RESER Where Cod_Estabe = @CodEstabe And Numero = @rs_Numero)
               begin
                 -- bloqueia produto
                 Update PRXES
                    Set Qtd_Transi = Qtd_Transi + 0
                  Where Cod_Estabe = @CodEstabe 
                    And Cod_Produt = @pl_CodPrd

                 -- registra reserva
                 Insert Into RESER (Cod_Estabe, Numero, Cod_Dep, Cod_Produto, Cod_Lote
                                 ,  Qtd_Movimento, Qtd_ResDep, Historico, Dat_Movimento, Usuario, Transacao)
                            Values (@CodEstabe, @rs_Numero, @pl_CodDep, @pl_CodPrd, @pl_CodLot
                                 ,  @pl_QtdSldPra, @pl_QtdSldDep, 'RESERVA AUTOMATICA POR VENCIMENTO', @Date, 'SISTEMA', @Now)
                 if @@error <> 0
                   RollBack Transaction

                 Break
               end
            end

          Delete From @Tab
           Where Chave = @pl_Chave

        end  -- While Exists(Select 1 From @Tab)

    end  -- if (@WFlgUsaWms = 0) and (@pm_FlgResPrdVen = 1)

Commit transaction
GO


SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ProIni_VerificaOcorrenciasCheques]
@CodEstabe int

WITH RECOMPILE
AS

SET NOCOUNT ON 

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
             @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(Cast(Year(@Now) as varchar)+'-'+Cast(Month(@Now) as varchar)+'-'+Cast(Day(@Now) as varchar)+' 00:00:00' as smalldatetime)

if (Select Isnull(QtdDiaRecChqDvl,0) From PARAM Where Cod_Estabe = @CodEstabe) > 0
  begin

  Begin Transaction

  Declare @ch_CodDoc int,
          @ch_Num varchar(12),
          @ch_Vlr numeric(18,4),
          @ch_CodVdr int,
          @ch_DatEnvVdr smalldatetime,
          @ch_DesUsu varchar(35),
          @pm_PerDedVlrChqDvl numeric(18,4),
          @pm_QtdDiaRecChqDvl int,
          @cr_CodDoc int,
          @cr_VlrSld numeric(18,4),
          @cr_DatVct smalldatetime,
          @cr_IsnCtaFin int,
          @cr_CodCntCus int,
          @WCodDoc int,
          @WValDoc numeric(18,4),
          @WValDeb numeric(18,4),
          @WStrDat varchar(10),
          @WQtdDiaAtr int

  -- coloca parametros na memoria
  Select @pm_QtdDiaRecChqDvl = Isnull(QtdDiaRecChqDvl,0),
         @pm_PerDedVlrChqDvl = Isnull(PerDedVlrChqDvl,0)
    From PARAM
    Where Cod_Estabe = @CodEstabe

  -- seleciona cheques entrgues ao vendedor e nao retornadps em x(parametro) dias
  Declare CHEQU_Cr Cursor Local Fast_Forward For 
    Select Cod_Cheque
      From CHEQU
      Where Cod_Cob = 'V'
      And Status = '2'
      And Cod_Estabe = @CodEstabe
      And (Dat_Env_Vdr + @pm_QtdDiaRecChqDvl) < @Date
  Open CHEQU_Cr
  Fetch Next From CHEQU_Cr Into @ch_CodDoc
  While @@FETCH_STATUS = 0
    begin
      -- coloca dados do cheque na memoria
      Select @ch_Num = Num_Cheque,
             @ch_Vlr = ChqVlr,
             @ch_CodVdr = Cod_Vendedor,
             @ch_DatEnvVdr = Dat_Env_Vdr,
             @ch_DesUsu = Usuario
        From CHEQU
        Where Cod_Cheque = @ch_CodDoc
        And Cod_Estabe = @CodEstabe

      -- inclui vale
      if not Exists(Select bx.Cod_Documento From CTREC cr, BXREC bx Where cr.Cod_Estabe = bx.Cod_Estabe And cr.Cod_Documento = bx.Cod_Documento And cr.Cod_Cheque = @ch_CodDoc And cr.Vlr_Saldo > 0 And cr.Cod_Estabe = @CodEstabe)
        begin
          EXEC PR_ProxNumero 'Vale', @WCodDoc output
          if @@error <> 0
            begin
              Rollback Transaction
              Return
            end
          -- calcula valor do vale de debito
          Set @WStrDat = Cast(Day(@ch_DatEnvVdr) as varchar) + '/' + Cast(Month(@ch_DatEnvVdr) as varchar) + '/' + Cast(Year(@ch_DatEnvVdr) as varchar)
          Set @WValDeb = (Select Val_Saldo From VALES Where Cod_Estabe = @CodEstabe And Cod_CtrLanAut = 'DVC' and Num_CtrLanAut = @ch_CodDoc) 
          if @WValDeb is null Set @WValDeb = 0
          Set @WValDoc =  Round(@ch_Vlr-@WValDeb,2)

          -- inclui vale
          Insert into VALES
            (Cod_Estabe, Cod_Vale, Des_Vale, Tip_Entid, Cod_Entid, Dat_Emissa, Dat_Vencim, Val_Vale, Deb_Cre, 
             Cod_CtrLanAut, Num_CtrLanAut, Usuario, Transacao)
          Values
            (@CodEstabe, @WCodDoc,'Ch. '+@ch_Num+' Ret. em '+@WStrDat,'VEN',@ch_CodVdr,@Date,@Date,@WValDoc,'D',
             'RTC',@ch_CodDoc,@ch_DesUsu, @Now)
          if @@error <> 0
            begin
              Rollback Transaction
              Return
            end

          -- muda status do cheque p/ trocado (8)
          Update CHEQU
            Set Status = '8'
            Where Cod_Cheque = @ch_CodDoc
            And Cod_Estabe = @CodEstabe
          if @@error <> 0
            begin
              Rollback Transaction
              Return
            end
        end  -- if @WFlgIncVal = 1

      -- baixa o titulo
      if Exists(Select Cod_Documento From CTREC Where Cod_Estabe = @CodEstabe And Cod_Cheque = @ch_CodDoc)
        begin
          Select @cr_CodDoc =  Cod_Documento,
                 @cr_VlrSld = Isnull(Vlr_Saldo,0),
                 @cr_DatVct = Dat_Vencimento,
                 @cr_IsnCtaFin = Isn_CtaFin,
                 @cr_CodCntCus = Cod_CntCus
            From CTREC 
            Where Cod_Estabe = @CodEstabe
            And Cod_Cheque = @ch_CodDoc
          
          if (@cr_VlrSld > 0) and (not Exists(Select Cod_Documento From BXREC Where Cod_Estabe = @CodEstabe And Cod_Documento = @cr_CodDoc)) 
            begin
              EXEC PR_ProxNumero 'Lancamento', @WCodDoc output
              if @@error <> 0
                begin
                  Rollback Transaction
                  Return
                end

              -- calcula atraso
              Set @WQtdDiaAtr = 0
              if @Date > @cr_DatVct
                Set @WQtdDiaAtr = Datediff(day,@cr_DatVct,@Date)

              -- insere baixa
              Insert into BXREC (Cod_Estabe,Cod_Documento,Cod_Lancamento,Cod_Rec,Tip_Baixa,Tip_Doc,Dat_Caixa,Dat_Lancamento,Dat_Registro,
                                 Vlr_Principal,Qtd_DiasAtraso,Status,Cod_CtrOri,Isn_CtaFin,Cod_CntCus,Usuario,Transacao)
                          Values(@CodEstabe,@cr_CodDoc, @WCodDoc, -4, 'P', 'E', @Date, @Date, @Date,
                                 @cr_VlrSld, @WQtdDiaAtr, 'Q','V',@cr_IsnCtaFin,@cr_CodCntCus,@ch_DesUsu, @Now)
              if @@error <> 0
                begin
                  Rollback Transaction
                  Return
                end

            end       
        end    -- if Exists(Select Cod_Documento From CTREC Where Cod_Cheque = @ch_CodDoc)

      Fetch Next From CHEQU_Cr Into @ch_CodDoc
    end
  Close CHEQU_Cr
  Deallocate CHEQU_Cr

  Commit transaction
  end

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[X_FN_ExisteEstoqueMes]
(
  @PCodEstabe int,
  @PCodPrd int,
  @PAno int,
  @PMes int
)
RETURNS bit

WITH ENCRYPTION
AS

BEGIN

  -- Declarar variável de retorno da function
  Declare @FlgEst bit

  Set @FlgEst = 0

  if (@PMes > 0) and (@PMes < 13)
    begin

      Declare @DatIni smalldatetime,
		      @DatFim smalldatetime,
		      @AnoAux int,
		      @MesAux int

      Set @DatIni = cast(cast(@PAno as varchar)+'-'+cast(@PMes as varchar)+'-01 00:00:00' as smalldatetime) - 1
      Set @DatFim = cast(cast(@PAno as varchar)+'-'+cast(@PMes as varchar)+'-28 00:00:00' as smalldatetime)

      Set @AnoAux = @PAno
      Set @MesAux = @PMes

      while (@PAno = @AnoAux) and (@PMes = @MesAux)
        begin
          Set @DatFim = @DatFim + 1
          Set @AnoAux = Year(@DatFim)
          Set @MesAux = Month(@DatFim)
        end

      Set @DatFim = @DatFim - 1

      while @DatIni <= @DatFim
        begin
          if dbo.FN_SldQtdFis ('',@PCodEstabe,@PCodPrd,@DatIni) > 0
	        begin
              Set @FlgEst = 1
		      Break
	        end
          Set @DatIni = @DatIni + 1
        end

	end

  -- Retorna o resultado da function
  RETURN IsNull(@FlgEst,0)

END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[FN_ExisteEstoqueMes]
(
  @PCodEstabe int,
  @PCodPrd int,
  @PAno int,
  @PMes int
)
RETURNS bit

AS

BEGIN

  -- Declarar variável de retorno da function
  Declare @FlgEst bit

  Set @FlgEst = 0

  -- verifica se existe saldo em qualquer dia do mes
  if Exists(Select 1
              From PRSLD
             Where Cod_Estabe = @PCodEstabe
               And Cod_Produt = @PCodPrd
               And YEAR(Dat_Movime) = @PAno
               And MONTH(Dat_Movime) = @PMes
               And ( (Qtd_SldAtu > 0) or 
                     ((IsNull(Qtd_SaiVen,0)+IsNull(Qtd_SaiTrf,0)+IsNull(Qtd_SaiDev,0)+IsNull(Qtd_SaiOut,0)) <> 0)) )
    Set @FlgEst = 1

  -- Retorna o resultado da function
  RETURN IsNull(@FlgEst,0)

END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ProIni_CalculaSaldoParceria]
@CodEstabe int,
@CodPar int        -- cod.parceria se = 0 atualiza todos 

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

Begin Transaction

Declare @pa_CodPar int,
        @pa_CodCli int,
        @pa_DatIni smalldatetime,
        @pa_DatFim smalldatetime,
        @pa_FlgGrpCliPag bit,
        @pm_FlgEncParAut bit,
        @cl_CodCliPag int

Select @pm_FlgEncParAut = IsNull(FlgEncParAut,0) From PARAM Where Cod_Estabe = @CodEstabe 

if @CodPar is null
  Set @CodPar = 0

if @CodPar = 0
  begin
    Declare PARCE_Cr Cursor Local Fast_Forward For 
      Select Numero, CodCli, DtaIni, DtaFim, IsNull(Flg_GrpCliPag,0)
        From PARCE 
      Where ((Status = '0') or (Status = '3'))
--      And Cod_Estabe = @CodEstabe
  end
else
  begin
    Declare PARCE_Cr Cursor Local Fast_Forward For 
      Select Numero, CodCli, DtaIni, DtaFim, IsNull(Flg_GrpCliPag,0)
        From PARCE 
      Where ((Status = '0') or (Status = '3'))
      And Numero = @CodPar
--      And Cod_Estabe = @CodEstabe
  end
Open PARCE_Cr
Fetch Next From PARCE_Cr Into @pa_CodPar, @pa_CodCli, @pa_DatIni, @pa_DatFim, @pa_FlgGrpCliPag
While @@FETCH_STATUS = 0
  begin
    -- atualiza saldo geral da parceria
    Set @cl_CodCliPag = 0
    -- ver se agrupa por cliente pagador
    if @pa_FlgGrpCliPag = 1
      Set @cl_CodCliPag = IsNull((Select Cod_CliPag From CLIEN Where Codigo = @pa_CodCli),0)
    
    if @cl_CodCliPag = 0
      begin
        Update PARCE
          Set Saldo = Round(SaldoAnt + IsNull((Select Sum(IsNull(Vlr_BasPar,0)) 
                                               From NFSCB 
                                               --Where Cod_Estabe = @CodEstabe 
                                               Where Cod_Cliente = @pa_CodCli 
                                               and Status = 'F' and Tip_Saida = 'V' 
                                               and Dat_Emissao between @pa_DatIni and @pa_DatFim 
                                               and IsNull(Vlr_BasPar,0) > 0),0),2),

              Qtd_Saldo =  Round(IsNull((Select sum(it.Qtd_Produto+it.Qtd_Bonificacao)
                                         From NFSCB cb Inner Join 
                                              NFSIT it on ((cb.Cod_Estabe = it.Cod_Estabe) and (cb.Ser_Nota = it.Ser_Nota) and (cb.Num_Nota = it.Num_Nota))
                                         --Where cb.Cod_Estabe = @CodEstabe 
                                         Where cb.Cod_Cliente = @pa_CodCli 
                                         and cb.Status = 'F' and cb.Tip_Saida = 'V' 
                                         and cb.Dat_Emissao between @pa_DatIni and @pa_DatFim 
                                         and IsNull(cb.Vlr_BasPar,0) > 0),0),0),
              Status = case
                         when ((@pm_FlgEncParAut = 1) and (@Date  > @pa_DatFim)) then '1'
                         else Status
                       end
          Where Numero = @pa_CodPar
--          And Cod_Estabe = @CodEstabe
      end
    else
      begin
        Update PARCE
          Set Saldo = Round(SaldoAnt + IsNull((Select Sum(IsNull(cb.Vlr_BasPar,0)) 
                                               From NFSCB cb Inner Join 
                                                    CLIEN cl on cb.Cod_Cliente = cl.Codigo 
                                               Where cl.Cod_CliPag = @cl_CodCliPag 
                                               --and cb.Cod_Estabe = @CodEstabe 
                                               and cb.Status = 'F' and cb.Tip_Saida = 'V' 
                                               and cb.Dat_Emissao between @pa_DatIni and @pa_DatFim 
                                               and IsNull(cb.Vlr_BasPar,0) > 0),0),2),

              Qtd_Saldo =  Round(IsNull((Select sum(it.Qtd_Produto+it.Qtd_Bonificacao)
                                         From NFSCB cb Inner Join 
                                              NFSIT it on ((cb.Cod_Estabe = it.Cod_Estabe) and (cb.Ser_Nota = it.Ser_Nota) and (cb.Num_Nota = it.Num_Nota)) Inner Join
                                              CLIEN cl on cb.Cod_Cliente = cl.Codigo
                                         Where cl.Cod_CliPag = @cl_CodCliPag 
                                         --and cb.Cod_Estabe = @CodEstabe 
                                         and cb.Status = 'F' and cb.Tip_Saida = 'V' 
                                         and cb.Dat_Emissao between @pa_DatIni and @pa_DatFim 
                                         and IsNull(cb.Vlr_BasPar,0) > 0),0),0),
              Status = case
                         when ((@pm_FlgEncParAut = 1) and (@Date  > @pa_DatFim)) then '1'
                         else Status
                       end
          Where Numero = @pa_CodPar
          --And Cod_Estabe = @CodEstabe     
      end

    -- atualiza saldo por fabricante
    if Exists(Select 1 From PARFB Where Cod_Parcer = @pa_CodPar)
      Update pf
        Set pf.Val_Saldo = Isnull(x.Vlr_Saldo,0),
            pf.Qtd_Saldo = Isnull(x.Qtd_Saldo,0)
        From PARFB pf,
                 (Select pr.Cod_Fabricante, sum(it.VlrTotIte) as Vlr_Saldo, 
                         sum(it.Qtd_Produto+it.Qtd_Bonificacao) as Qtd_Saldo
                    From NFSCB cb Inner Join 
                         (Select b.Cod_Estabe, b.Ser_Nota, b.Num_Nota, b.Cod_Produto, b.Qtd_Produto, b.Qtd_Bonificacao,
                                 VlrTotIte = Case
                                               When b.Flg_BlqDsc = 0 then Round((IsNull(b.Vlr_TotItem,0)*(1-a.Per_DescontoCom/100)-IsNull(b.Vlr_RepIcms,0)-IsNull(b.Vlr_DscTri,0)),2)
                                               Else (IsNull(b.Vlr_TotItem,0)-IsNull(b.Vlr_RepIcms,0)-IsNull(b.Vlr_DscTri,0))
                                             End
                          From NFSCB a Inner Join NFSIT b on ((a.Cod_Estabe = b.Cod_Estabe) and (a.Ser_Nota = b.Ser_Nota) and (a.Num_Nota = b.Num_Nota))
                          --Where a.Cod_Estabe = @CodEstabe 
                          Where a.Status = 'F'
                          And a.Tip_Saida = 'V' 
                          And a.Dat_Emissao between @pa_DatIni and @pa_DatFim
                          And IsNull(a.Vlr_BasPar,0) > 0
                          And IsNull(b.Flg_BlqInfPar,0) = 0) it on ((cb.Cod_Estabe = it.Cod_Estabe) and (cb.Ser_Nota = it.Ser_Nota) and (cb.Num_Nota = it.Num_Nota)) Inner Join
                          PRODU pr on (it.Cod_Produto = pr.Codigo)
                    Where cb.Cod_Cliente = @pa_CodCli
                    --And cb.Cod_Estabe = @CodEstabe 
                    And cb.Status = 'F'
                    And cb.Tip_Saida = 'V'
                    And cb.Dat_Emissao between @pa_DatIni and @pa_DatFim
                    And IsNull(cb.Vlr_BasPar,0) > 0
                    Group by pr.Cod_Fabricante) x
        Where pf.Cod_Parcer = @pa_CodPar
        And pf.Cod_Fabric = x.Cod_Fabricante
        --And pf.Cod_Estabe = @CodEstabe
        And ((IsNull(pf.Val_Objetivo,0) > 0) or (IsNull(pf.Qtd_Objetivo,0) > 0))

    -- atualiza saldo por produto
    if Exists(Select 1 From PARPR Where Cod_Parcer = @pa_CodPar)
      Update pp
        Set pp.Val_Saldo = Isnull(x.Vlr_Saldo,0),
            pp.Qtd_Saldo = Isnull(x.Qtd_Saldo,0)
        From PARPR pp,
             (Select pr.Codigo, sum(it.VlrTotIte) as Vlr_Saldo, 
                     sum(it.Qtd_Produto+it.Qtd_Bonificacao) as Qtd_Saldo
              From NFSCB cb Inner Join 
                   (Select b.Cod_Estabe, b.Ser_Nota, b.Num_Nota, b.Cod_Produto, b.Qtd_Produto, b.Qtd_Bonificacao, 
                           VlrTotIte = Case
                                         When b.Flg_BlqDsc = 0 then Round((IsNull(b.Vlr_TotItem,0)*(1-a.Per_DescontoCom/100)-IsNull(b.Vlr_RepIcms,0)-IsNull(b.Vlr_DscTri,0)),2)
                                         Else (IsNull(b.Vlr_TotItem,0)-IsNull(b.Vlr_RepIcms,0)-IsNull(b.Vlr_DscTri,0))
                                       End
                    From NFSCB a Inner Join NFSIT b on ((a.Cod_Estabe = b.Cod_Estabe) and (a.Ser_Nota = b.Ser_Nota) and (a.Num_Nota = b.Num_Nota))
                    --Where a.Cod_Estabe = @CodEstabe  
                    Where a.Status = 'F'
                    And a.Tip_Saida = 'V' 
                    And a.Dat_Emissao between @pa_DatIni and @pa_DatFim
                    And IsNull(a.Vlr_BasPar,0) > 0
                    And IsNull(b.Flg_BlqInfPar,0) = 0) it on ((cb.Cod_Estabe = it.Cod_Estabe) and (cb.Ser_Nota = it.Ser_Nota) and (cb.Num_Nota = it.Num_Nota)) Inner Join
                   PRODU pr on (it.Cod_Produto = pr.Codigo)
              Where cb.Cod_Cliente = @pa_CodCli
              --And cb.Cod_Estabe = @CodEstabe 
              And cb.Status = 'F'
              And cb.Tip_Saida = 'V'
              And cb.Dat_Emissao between @pa_DatIni and @pa_DatFim
              And IsNull(cb.Vlr_BasPar,0) > 0
              Group by pr.Codigo) x
        Where pp.Cod_Parcer = @pa_CodPar
        And pp.Cod_Produt = x.Codigo
        --And pp.Cod_Estabe = @CodEstabe
        And ((IsNull(pp.Val_Objetivo,0) > 0) or (IsNull(pp.Qtd_Objetivo,0) > 0))

    Fetch Next From PARCE_Cr Into @pa_CodPar, @pa_CodCli, @pa_DatIni, @pa_DatFim, @pa_FlgGrpCliPag
  end
Close PARCE_Cr
Deallocate PARCE_Cr

Commit transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_NormalizaFaltasDNCIT]
@PCodEstabe int,   -- 0
@PNumPrt int       -- 77628

AS

SET NOCOUNT ON
SET ANSI_WARNINGS OFF

begin
  -- existe coleta e faltas em DNCIT e ainda não foi normalizado (DNCCB.Flg_RepFal = 0)
 if Exists(Select 1
             From (Select it.Cod_Produt, it.Cod_Lote, 
                          Qtd_Coleta = Sum(IsNull(it.Qtd_Coleta,0))
                     From DNCIT it Inner Join
                          DNCCB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Protocolo = cb.Protocolo
                    Where it.Cod_Estabe = @PCodEstabe
                      and it.Protocolo  = @PNumPrt
                      and IsNull(cb.Flg_RepFal,0) = 0   -- ainda nao foi normalizado
                    Group by it.Cod_Produt, it.Cod_Lote) d Inner Join
                  (Select Cod_Produto, Cod_Lote, 
                          Qtd_Nota = Sum(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0))
                     From NFEIT  
                    Where Cod_Estabe = @PCodEstabe
                      and Protocolo  = @PNumPrt
                    Group by Cod_Produto, Cod_Lote) n on d.Cod_Produt = n.Cod_Produto and d.Cod_Lote = n.Cod_Lote
            Where n.Qtd_Nota <> d.Qtd_Coleta             -- existe falta
              And d.Qtd_Coleta > 0
		       And Exists(Select 1 From DNCIT     -- existe ao menos 1 coleta
                           Where Cod_Estabe = @PCodEstabe 
                             And Protocolo  = @PNumPrt 
                             And Qtd_Coleta > 0))
   begin
     Begin Transaction

       Update DNCIT 
          Set Qtd_Faltas = 0 
        Where Cod_Estabe = @PCodEstabe
          and Protocolo = @PNumPrt

       Declare @CodPrd int,
               @CodLot varchar(20),
               @QtdCol int,
               @QtdFal int,
               @QtdMov int,
               @CodConfer int

       DECLARE Table_Cr CURSOR LOCAL FAST_FORWARD FOR 

         Select d.Cod_Produt, d.Cod_Lote,
                Qtd_Falta = IsNull(n.Qtd_Nota,0)-d.Qtd_Coleta
           From (Select Cod_Produt, Cod_Lote, 
                        Qtd_Coleta = Sum(IsNull(Qtd_Coleta, 0))
                   From DNCIT
                  Where Cod_Estabe = @PCodEstabe
                    and Protocolo  = @PNumPrt
                  Group by Cod_Produt, Cod_Lote) d Left Join
                (Select Cod_Produto, Cod_Lote, 
                        Qtd_Nota = Sum(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0))
                   From NFEIT  
                  Where Cod_Estabe = @PCodEstabe
                    and Protocolo  = @PNumPrt
                  Group by Cod_Produto, Cod_Lote) n on d.Cod_Produt = n.Cod_Produto and d.Cod_Lote = n.Cod_Lote
          Where IsNull(n.Qtd_Nota,0) <> d.Qtd_Coleta
            And d.Qtd_Coleta > 0
      
       OPEN Table_Cr
       FETCH NEXT FROM Table_Cr INTO @CodPrd, @CodLot, @QtdFal
       WHILE @@FETCH_STATUS = 0
       BEGIN
         while @QtdFal <> 0
           begin
             DECLARE Dncit_Cr CURSOR LOCAL FAST_FORWARD FOR 

               Select Qtd_Coleta, Cod_Confer 
                 From DNCIT
                Where Cod_Estabe = @PCodEstabe
                  and Protocolo  = @PNumPrt
                  and Cod_Produt = @CodPrd
                  and Cod_Lote   = @CodLot
    
             OPEN Dncit_Cr
             FETCH NEXT FROM Dncit_Cr INTO @QtdCol, @CodConfer
             WHILE @@FETCH_STATUS = 0
             BEGIN
               if @QtdFal > @QtdCol
                 Set @QtdMov = @QtdCol
               else
                 Set @QtdMov = @QtdFal

               Update DNCIT 
                  Set Qtd_Faltas = @QtdMov
                Where Cod_Estabe = @PCodEstabe
                  And Protocolo  = @PNumPrt
                  And Cod_Produt = @CodPrd
                  And Cod_Lote   = @CodLot
                  And Cod_Confer = @CodConfer

               Set @QtdFal = @QtdFal - @QtdMov

               FETCH NEXT FROM Dncit_Cr INTO @QtdCol, @CodConfer
             END

             CLOSE Dncit_Cr
             DEALLOCATE Dncit_Cr

           end  -- while @QtdFal <> 0

         FETCH NEXT FROM Table_Cr INTO @CodPrd, @CodLot, @QtdFal
       END
       CLOSE Table_Cr
       DEALLOCATE Table_Cr
       
       Update DNCCB 
          Set Flg_RepFal = 1 
        Where Cod_Estabe = @PCodEstabe
          And Protocolo  = @PNumPrt

       if @@trancount > 0    
         COMMIT TRANSACTION

   end  -- if Exists(

end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_InventarioEncerramento]
@CodEstabe int,
@NumSeqBal int,
@Login varchar(15) 

AS

SET NOCOUNT ON
SET ANSI_WARNINGS OFF

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

BEGIN TRANSACTION
  if Exists(Select 1 From BALCB
             Where Cod_Estabe = @CodEstabe 
               And Num_SeqBal = @NumSeqBal 
               And IsNull(Flg_Proces,0) = 0)
    begin
      -- encerra inventario somente se não houver item pendente
      if not Exists(Select 1
                      From BALIT
                     Where Cod_Estabe = @CodEstabe 
                       And Num_SeqBal = @NumSeqBal 
                       And Num_Contag = 1
                       And Cod_Local = 1
                       And IsNull(Flg_Proces,0) = 0)
         begin
           -- atualiza BALIT
           Update it
              Set it.Val_VarPrcCus = Case
                                       When it.Tip_Movim = 'E' then Round(it.Qtd_Acerto*pr.Prc_CusLiqEnt,2)
                                       Else -Round(it.Qtd_Acerto*pr.Prc_CusLiqEnt,2)
                                     End,
                  it.Val_VarPrcMed = Case
                                       When it.Tip_Movim = 'E' then Round(it.Qtd_Acerto*pr.Prc_CusMed,2)
                                       Else -Round(it.Qtd_Acerto*pr.Prc_CusMed,2)
                                     End, 
                  it.Val_VarPrcVen = Case
                                       When it.Tip_Movim = 'E' then Round(it.Qtd_Acerto*pr.Prc_Venda,2)
                                       Else -Round(it.Qtd_Acerto*pr.Prc_Venda,2)
                                     End
             From BALCB cb Inner Join 
                  BALIT it on (cb.Cod_Estabe = it.Cod_Estabe and cb.Num_SeqBal = it.Num_SeqBal) Inner Join 
                  PRXES pr on (it.Cod_Estabe = pr.Cod_Estabe and it.Cod_Produt = pr.Cod_Produt)
            Where cb.Cod_Estabe = @CodEstabe
              And cb.Num_SeqBal = @NumSeqBal      
                 
           Update cb
              Set cb.Flg_Proces = 1, 
                  cb.Dat_Movime = @Date,
                  cb.Qtd_IteBal = it.QtdItens,
                  cb.Qtd_AceNeg = it.QtdAceNeg,
                  cb.Qtd_AcePos = it.QtdAcePos,
                  cb.Val_VarPrcCus = it.ValVarPrcCus,
                  cb.Val_VarPrcMed = it.ValVarPrcMed, 
                  cb.Val_VarPrcVen = it.ValVarPrcVen,
                  Usuario = @Login,
                  Transacao = @Now
             From BALCB cb Inner Join 
                  (Select Cod_Estabe, Num_SeqBal,
                          QtdItens = Count(Distinct Cod_Produt),
                          QtdAceNeg = Sum(Case When TIp_Movim = 'S' then Qtd_Acerto else 0 End),
                          QtdAcePos = Sum(Case When TIp_Movim = 'E' then Qtd_Acerto else 0 End),
                          ValVarPrcCus = SUM(Val_VarPrcCus),
                          ValVarPrcMed = SUM(Val_VarPrcMed),
                          ValVarPrcVen = SUM(Val_VarPrcVen)
                     From BALIT
                    Where Cod_Estabe = @CodEstabe
                      And Num_SeqBal = @NumSeqBal
                    Group by Cod_Estabe, Num_SeqBal) it on (cb.Cod_Estabe = it.Cod_Estabe and cb.Num_SeqBal = it.Num_SeqBal)
            Where cb.Cod_Estabe = @CodEstabe
              And cb.Num_SeqBal = @NumSeqBal 
           
         end  -- if not Exists(     
                
    end  -- if Exists(
            
COMMIT TRANSACTION
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_InventarioProcessaEstoque]
@CodEstabe int,
@NumSeqBal int,
@CodMveEnt int = 12,
@CodMveSai int = 22,
@Login varchar(15) 

AS

SET NOCOUNT ON
SET ANSI_WARNINGS OFF

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

-- ESTOQUES DE PRODUTOS RESERVADOS, AVARIADOS e SOLICITADOS POR PEDIDOS NAO SAO CONSIDERADOS

Declare @WNumCtg int,
        @WFlgOk bit,
        @WMsgErr varchar(60) ,
        @WTipMveEnt varchar(1),
        @WTipMveSai varchar(1),
        @WMaxDatMov smalldatetime,
        @WCodDep smallint,
        @WCodPrd int

-- verifica data da ultima movimentacao em PRSLD
Set @WMaxDatMov = (Select max(Dat_Movime) From PRSLD Where Cod_Estabe = @CodEstabe)

-- verifica codigos de movimentacao                 
Set @WTipMveEnt = (Select Tip_Movimento From TPMVE  Where Codigo = @CodMveEnt) 
Set @WTipMveSai = (Select Tip_Movimento From TPMVE  Where Codigo = @CodMveSai) 
-- tem que existir a 1a. contagem
Set @WNumCtg = (Select distinct top 1 Num_Contag From BALIT Where Cod_Estabe = @CodEstabe And Num_SeqBal = @NumSeqBal Order by Num_Contag)

if @Date < @WMaxDatMov
  RAISERROR('Existe(m) registro(s) de movimento(s) com data superior à data do processamento',16,1)
else
if @WTipMveEnt <> 'E'
  RAISERROR('Código de movimentação de entrada inválida',16,1)
else
if @WTipMveSai <> 'S'
  RAISERROR('Código de movimentação de saída inválida',16,1)
else
if @WNumCtg <> 1
  RAISERROR('Existe Contagem inválida',16,1)
else
  begin
    -- normaliza BALIT    
    Update BALIT
       Set Cod_MovEst = 0,
           Qtd_Acerto = 0,
           Qtd_EstPra = 0, 
           Qtd_EstDep = 0,
           Tip_Movim = ''
     Where Cod_Estabe = @CodEstabe 
       And Num_SeqBal = @NumSeqBal 
       And IsNull(Flg_Proces,0) = 0
    
    Set @WFlgOk = 1
    Set @WMsgErr = ''
    Set @WNumCtg = (Select Max(Num_Contag) From BALIT Where Cod_Estabe = @CodEstabe And Num_SeqBal = @NumSeqBal)

    if @WNumCtg > 1
      begin
        -- se existem mais de 1 contagem verificar diferencas entre contagem 1 e outras
        -- itens com contagens diferentes
        if Exists(Select 1
                    From BALIT b1
                   Where b1.Cod_Estabe = @CodEstabe 
                     And b1.Num_SeqBal = @NumSeqBal 
                     And b1.Num_Contag = 1
                     And b1.Cod_Local = 1
                     And IsNull(b1.Flg_Proces,0) = 0
                     And b1.Qtd_Produt <> (Select Qtd_Produt
                                             From BALIT 
                                            Where Cod_Estabe = @CodEstabe 
                                              And Num_SeqBal = @NumSeqBal 
                                              And Cod_Produt = b1.Cod_Produt
                                              And Cod_Lote = b1.Cod_Lote
                                              And Cod_Dep = b1.Cod_Dep
                                              And Num_Rua =  b1.Num_Rua
                                              And Num_Col = b1.Num_Col
                                              And Num_Niv = b1.Num_Niv
                                              And Num_Apt =  b1.Num_Apt
                                              And Cod_Local = b1.Cod_Local
                                              And Num_Contag = 2))
          begin
            Set @WFlgOk = 0
            Set @WMsgErr = 'Inconsistência(s) entre contagens 1 e 2)'
          end

        -- itens com lotes em 1 não existem em 2
        if @WFlgOk = 1	
          if Exists(Select 1
                      From BALIT b1 Left Outer Join
                           BALIT b2 on (b1.Cod_Estabe = b2.Cod_Estabe and b1.Num_SeqBal = b2.Num_SeqBal and
                                        b1.Cod_Produt = b2.Cod_Produt and b1.Cod_Lote = b2.Cod_Lote and
                                        b1.Cod_Dep = b2.Cod_Dep and b1.Num_Rua = b2.Num_Rua and 
                                        b1.Num_Col = b2.Num_Col and b1.Num_Niv = b2.Num_Niv and 
                                        b1.Num_Apt = b2.Num_Apt and b1.Cod_Local = b2.Cod_Local and
                                        b2.Num_Contag = 2)
                     Where b1.Cod_Estabe = @CodEstabe 
                       And b1.Num_SeqBal = @NumSeqBal 
                       And b1.Num_Contag = 1
                       And b1.Cod_Local = 1
                       And IsNull(b1.Flg_Proces,0) = 0
                       And b2.Cod_Produt is null)
            begin
              Set @WFlgOk = 0
              Set @WMsgErr = 'Falta(m) iten(s)/lote(s) na contagem 2'
            end

        -- itens com lotes em 2 não existem em 1
        if @WFlgOk = 1
          if Exists(Select 1
                      From BALIT b2 Left Outer Join
                           BALIT b1 on (b2.Cod_Estabe = b1.Cod_Estabe and b2.Num_SeqBal = b1.Num_SeqBal and
                                        b2.Cod_Produt = b1.Cod_Produt and b2.Cod_Lote = b1.Cod_Lote and
                                        b2.Cod_Dep = b1.Cod_Dep and b2.Num_Rua = b1.Num_Rua and 
                                        b2.Num_Col = b1.Num_Col and b2.Num_Niv = b1.Num_Niv and 
                                        b2.Num_Apt = b1.Num_Apt and b2.Cod_Local = b1.Cod_Local and
                                        b1.Num_Contag = 1 and b1.Cod_Local = 1 and IsNull(b1.Flg_Proces,0) = 0)
                     Where b2.Cod_Estabe = @CodEstabe 
                       And b2.Num_SeqBal = @NumSeqBal 
                       And b2.Num_Contag = 2
                       And b2.Cod_Local = 1
                       And b1.Cod_Produt is null)
            begin
              Set @WFlgOk = 0
              Set @WMsgErr = 'Falta(m) iten(s) na contagem 1'
            end

      end   -- if @WNumCtg > 1
   
    -- verifica DIVERGENCIAS DE ESTOQUES
    if @WFlgOk = 1    
      begin
        -- Normaliza datas em BALIT
        Update l1
           Set l1.Dat_VctLot = l2.Dat_Vencim,
               l1.Dat_Fabric = l2.Dat_Fabric
          From BALIT l1 Inner Join
               (Select Cod_Estabe, Cod_Produt, Cod_Lote, Dat_Vencim = max(Dat_VctLot), Dat_Fabric = max(Dat_Fabric)
                  From BALIT
                 Where Cod_Estabe = @CodEstabe
                   And Num_SeqBal = @NumSeqBal
                 Group by Cod_Estabe, Cod_Produt, Cod_Lote) l2 on l1.Cod_Estabe = l2.Cod_Estabe 
                                                              and l1.Cod_Produt = l2.Cod_Produt and l1.Cod_Lote = l2.Cod_Lote
         Where l1.Cod_Estabe = @CodEstabe 
           And l1.Num_SeqBal = @NumSeqBal
           And ((IsNull(l1.Dat_VctLot,0) <> IsNull(l2.Dat_Vencim,0)) or 
                (IsNull(l1.Dat_Fabric,0) <> IsNull(l2.Dat_Fabric,0)))       
        
        Update l1
           Set l1.Dat_VctLot = l2.Dat_Vencim,
               l1.Dat_Fabric = l2.Dat_Fabric
          From BALIT l1, PRLOT l2
         Where l1.Cod_Estabe = l2.Cod_Estabe
           And l1.Cod_Dep = l2.Cod_Dep
           And l1.Cod_Produt = l2.Cod_Produt
           And l1.Cod_Lote = l2.Cod_Lote
           And l1.Cod_Estabe = @CodEstabe 
           And l1.Num_SeqBal = @NumSeqBal
           And ((IsNull(l1.Dat_VctLot,0) <> IsNull(l2.Dat_Vencim,0)) or
                (IsNull(l1.Dat_Fabric,0) <> IsNull(l2.Dat_Fabric,0)))

        -- Normaliza PRLOT, PRLTL
        Update PRLOT
           Set Qtd_FisPra = 0
         Where Cod_Estabe = @CodEstabe  
           And ((Qtd_FisPra < 0) or (Qtd_FisPra is null))

        Update PRLOT
           Set Qtd_FisDep = 0
         Where Cod_Estabe = @CodEstabe  
           And ((Qtd_FisDep < 0) or (Qtd_FisDep is null))
      
        Update PRLTL
           Set Qtd_FisPra = 0
         Where Cod_Estabe = @CodEstabe  
           And ((Qtd_FisPra < 0) or (Qtd_FisPra is null))

        Update PRLTL
           Set Qtd_FisDep = 0
         Where Cod_Estabe = @CodEstabe  
           And ((Qtd_FisDep < 0) or (Qtd_FisDep is null))
       
        -- elimina lotes diferentes do mesmo produto no mesmo endereço (procura deixar pelo menos 1) 
        Delete lt
          From PRLTL lt Inner Join
               (Select Cod_Estabe, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_Produt, DatVct = MAX(Dat_Vencim), qtd = COUNT(*)
                  From PRLTL
                 Where Cod_Estabe = @CodEstabe
                 Group by Cod_Estabe, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_Produt
                Having COUNT(*) > 1) x on (lt.Cod_Estabe = x.Cod_Estabe and 
                                           lt.Cod_Dep = x.Cod_Dep and lt.Num_Rua = x.Num_Rua and 
                                           lt.Num_Col = x.Num_Col and lt.Num_Niv = x.Num_Niv and 
                                           lt.Num_Apt = x.Num_Apt and lt.Cod_Produt = x.Cod_produt)
         Where lt.Cod_Estabe = @CodEstabe                                 
           And lt.Qtd_Fisico = 0 
           and lt.Dat_Vencim < x.DatVct
      end

    -- verifica itens com depositos invalidos  
    if @WFlgOk = 1
      if Exists(Select 1
                  From BALIT it Inner Join
                       BALCB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Num_SeqBal = cb.Num_SeqBal
                 Where it.Cod_Estabe = @CodEstabe
                   And it.Num_SeqBal = @NumSeqBal
                   And it.Num_Contag = 1
                   And it.Cod_Local = 1
                   And IsNull(it.Flg_Proces,0) = 0
                   And IsNull(it.Cod_Dep,0) <> IsNull(cb.Cod_Dep,0))
      begin          
        Set @WFlgOk = 0
        Set @WMsgErr = 'Existem itens inventariados de outros depósitos'
      end  

    -- verifica produtos sem endereços Picking  
    if @WFlgOk = 1
      if Exists(Select 1
                  From BALIT it Inner Join
                       PRLTL lt on (it.Cod_Estabe = lt.Cod_Estabe and 
                                    it.Cod_Produt = lt.Cod_Produt and it.Cod_Lote = lt.Cod_Lote and 
                                    it.Cod_Dep = lt.Cod_Dep and it.Num_Rua = lt.Num_Rua and it.Num_Col = lt.Num_Col and 
                                    it.Num_Niv = lt.Num_Niv and it.Num_Apt = lt.Num_Apt) Left Outer Join
                       DPXPR dp on it.Cod_Estabe = dp.Cod_Estabe and it.Cod_Dep = dp.Cod_Dep and it.Cod_Produt = dp.Cod_Produt              
                 Where it.Cod_Estabe = @CodEstabe
                   And it.Num_SeqBal = @NumSeqBal
                   And it.Num_Contag = 1
                   And it.Cod_Local = 1
                   And IsNull(it.Flg_Proces,0) = 0
                   -- itens com acerto de saida
                   And (IsNull(lt.Qtd_SldPra,0)+IsNull(lt.Qtd_SldDep,0)) > IsNull(it.Qtd_Produt,0)
                   and IsNull(Flg_AutDiv,0) = 1
                   And dp.Cod_Produt is null)
      begin          
        Set @WFlgOk = 0
        
        Select top 1 @WCodDep = it.Cod_Dep, 
                     @WCodPrd = it.Cod_Produt
                From BALIT it Inner Join
                     PRLTL lt on (it.Cod_Estabe = lt.Cod_Estabe and 
                                  it.Cod_Produt = lt.Cod_Produt and it.Cod_Lote = lt.Cod_Lote and 
                                  it.Cod_Dep = lt.Cod_Dep and it.Num_Rua = lt.Num_Rua and it.Num_Col = lt.Num_Col and 
                                  it.Num_Niv = lt.Num_Niv and it.Num_Apt = lt.Num_Apt) Left Outer Join
                     DPXPR dp on it.Cod_Estabe = dp.Cod_Estabe and it.Cod_Dep = dp.Cod_Dep and it.Cod_Produt = dp.Cod_Produt              
               Where it.Cod_Estabe = @CodEstabe
                 And it.Num_SeqBal = @NumSeqBal
                 And it.Num_Contag = 1
                 And it.Cod_Local = 1
                 And IsNull(it.Flg_Proces,0) = 0
                 -- itens com acerto de saida
                 And (IsNull(lt.Qtd_SldPra,0)+IsNull(lt.Qtd_SldDep,0)) > IsNull(it.Qtd_Produt,0)
                 and IsNull(Flg_AutDiv,0) = 1
                 And dp.Cod_Produt is null        
        
        Set @WMsgErr = 'Produto('+cast(@WCodPrd as varchar)+') s/ender.Picking dep.('+cast(@WCodDep as varchar)+')'
      end  
      
    if @WFlgOk = 0
      RAISERROR(@WMsgErr,16,1)
    else
      begin
        Begin Transaction
          Declare @CodPrd int,
                  @CodLot varchar(20),
                  @QtdBal int,
                  @DatVct smalldatetime,
                  @DatFab smalldatetime,
                  @CodDep smallint,
                  @NumRua smallint,
                  @NumCol smallint,
                  @NumNiv smallint,
                  @NumApt smallint,
                  @QtdEmbFec int,
                  @NumPag int,
                  @NumSeqIte int,
                  @FlgAutDiv bit,
                  @SldPra int,
                  @SldDep int,
                  @WQtdSldTot int,
                  @WQtdDif int,
                  @WQtdMov int,
                  @WQtdPra int,
                  @WQtdDep int,
                  @WFlgEstFis bit,
                  @WNumRuaPck smallint,
                  @WNumColPck smallint,
                  @WNumNivPck smallint,
                  @WNumAptPck smallint,
                  @WCodOri varchar(20),
                  @WCodAcr int,
                  @QtdSldAntPra int,
                  @QtdSldAntDep int,
                  @WQtdMovPra int,
                  @WQtdMovDep int

          -- antes de processar tenta corrigir algum estoque inconsistente em PRXES
          Set @CodPrd = 0
          while Exists(Select 1
                         From BALIT b
                              inner join PRXES p on b.Cod_Estabe = p.Cod_Estabe and b.Cod_Produt = p.Cod_Produt
                        Where b.Cod_Estabe = @CodEstabe 
                          And b.Num_SeqBal = @NumSeqBal 
                          And b.Num_Contag = 1
                          And b.Cod_Local = 1
                          And IsNull(b.Flg_Proces,0) = 0
                          And b.Cod_Produt > @CodPrd
                          And p.Qtd_Fisico <> dbo.FN_EstoqueFisicoPrdLote(p.Cod_Estabe,p.Cod_Produt,'TODOS'))
            begin
              Select top 1 @CodPrd = b.Cod_Produt 
                From BALIT b
                     inner join PRXES p on b.Cod_Estabe = p.Cod_Estabe and b.Cod_Produt = p.Cod_Produt
               Where b.Cod_Estabe = @CodEstabe 
                 And b.Num_SeqBal = @NumSeqBal 
                 And b.Num_Contag = 1
                 And b.Cod_Local = 1
                 And IsNull(b.Flg_Proces,0) = 0
                 And b.Cod_Produt > @CodPrd
                 And p.Qtd_Fisico <> dbo.FN_EstoqueFisicoPrdLote(p.Cod_Estabe,p.Cod_Produt,'TODOS')
               Order by b.Cod_Produt

              Exec PR_CorrigeEstoqueProdut @CodEstabe, @CodPrd
              if @@error <> 0
                begin
                  Rollback Transaction
                  Return
                end
            end


          -- verifica se for implantacao de estoque (fiscal)
          Set @WFlgEstFis = 0  

          if not Exists(Select 1 From PRXES Where Cod_Estabe = @CodEstabe And Qtd_Dispon > 0)
            Set @WFlgEstFis = 1  -- estoque fiscal
         
          if (@WFlgEstFis = 0) and ((Select IsNull(FlgAlerta,0) From PARAM Where Cod_Estabe = @CodEstabe) = 1)
            Set @WFlgEstFis = 1  -- estoque fiscal

          -- inclui registros em BALIT de lotes que serao zerados (lotes iniciais que foram alterados na "digitação") 
          Insert Into BALIT (Cod_Estabe, Num_SeqBal, Cod_Produt, Cod_Lote, Cod_Local, Num_Contag, Cod_MovEst,
                             Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Dat_VctLot, Dat_Fabric,
                             Qtd_Produt, Flg_AutDiv, Cod_LoteOri, Num_Pagina, Num_SeqIte) 
             Select distinct Cod_Estabe, Num_SeqBal, Cod_Produt, Cod_LoteOri, 1, 1, @CodMveSai, 
                             Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Dat_VctLot, Dat_Fabric,
                             0, Flg_AutDiv, Cod_LoteOri, Num_Pagina, 
                             IsNull((Select max(Num_SeqIte) From BALIT Where Cod_Estabe = @CodEstabe And Num_SeqBal = @NumSeqBal),0)+1 
               From BALIT
              Where Cod_Estabe = @CodEstabe
                And Num_SeqBal = @NumSeqBal
                And Num_Contag = 1
                And Cod_Local = 1
                And IsNull(Flg_Proces,0) = 0
                And (ISNull(Cod_Lote,'') <> IsNull(Cod_LoteOri,'') And IsNull(Cod_LoteOri,'') <> '') -- DMD-7196 
                And IsNull(Flg_AutDiv,0) = 1
          if (@@error <> 0)
            begin
              Rollback Transaction
              Return
            end

------------------------------  D E P O S I T O --------------------------------------------------------------------            
          if Exists(Select 1
                      From BALCB
                     Where Cod_Estabe = @CodEstabe
                       And Num_SeqBal = @NumSeqBal
                       And IsNull(Flg_Proces,0) = 0
                       And Tip_Balanc = 'D') 
            begin
              -- inclui itens de BALIT com lotes inexistentes em PRLTL
              Insert into PRLTL (Cod_Estabe, Cod_Produt, Cod_Lote, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, 
                                 Qtd_EmbFec, Dat_Vencim, Dat_Fabric, Qtd_FisPra, Qtd_SolPra, Qtd_FisDep, Qtd_SolDep)
                Select distinct b.Cod_Estabe, b.Cod_Produt, b.Cod_Lote, b.Cod_Dep, b.Num_Rua, b.Num_Col, b.Num_Niv, b.Num_Apt,  
                                b.Qtd_EmbFec, b.Dat_VctLot, b.Dat_Fabric, 0, 0, 0, 0
                  From BALIT b Left Outer Join
                       PRLTL l on (b.Cod_Estabe = l.Cod_Estabe and 
                                   b.Cod_Produt = l.Cod_Produt and b.Cod_Lote = l.Cod_Lote and 
                                   b.Cod_Dep = l.Cod_Dep and b.Num_Rua = l.Num_Rua and b.Num_Col = l.Num_Col and 
                                   b.Num_Niv = l.Num_Niv and b.Num_Apt = l.Num_Apt)
                 Where b.Cod_Estabe = @CodEstabe 
                   And b.Num_SeqBal = @NumSeqBal 
                   And b.Num_Contag = 1
                   And b.Cod_Local = 1
                   And IsNull(b.Flg_Proces,0) = 0
                   And l.Cod_Produt is null
              if (@@error <> 0)
                begin
                  Rollback Transaction
                  Return
                end

              -- atualiza estoque disponivel atual de PRLTL em BALIT
              Update it
                 Set it.Qtd_SldEst = IsNull(lt.Qtd_SldPra,0)+IsNull(lt.Qtd_SldDep,0) 
                From BALIT it Inner Join
                     PRLTL lt on (it.Cod_Estabe = lt.Cod_Estabe and 
                                  it.Cod_Produt = lt.Cod_Produt and it.Cod_Lote = lt.Cod_Lote and 
                                  it.Cod_Dep = lt.Cod_Dep and it.Num_Rua = lt.Num_Rua and it.Num_Col = lt.Num_Col and 
                                  it.Num_Niv = lt.Num_Niv and it.Num_Apt = lt.Num_Apt)
               Where it.Cod_Estabe = @CodEstabe
                 And it.Num_SeqBal = @NumSeqBal
                 And it.Num_Contag = 1
                 And it.Cod_Local = 1
                 And IsNull(it.Flg_Proces,0) = 0
            
              Declare BALIT_Cr Cursor Local For 
                Select it.Cod_Produt, it.Cod_Lote, it.Qtd_Produt, it.Dat_VctLot, it.Dat_Fabric,
                       it.Cod_Dep, it.Num_Rua, it.Num_Col, it.Num_Niv, it.Num_Apt, it.Qtd_EmbFec,
                       it.Num_Pagina, it.Num_SeqIte, IsNull(Flg_AutDiv,0),
                       IsNull(lt.Qtd_SldPra,0), IsNull(lt.Qtd_SldDep,0) 
                  From BALIT it Inner Join
                       PRLTL lt on (it.Cod_Estabe = lt.Cod_Estabe and 
                                    it.Cod_Produt = lt.Cod_Produt and it.Cod_Lote = lt.Cod_Lote and 
                                    it.Cod_Dep = lt.Cod_Dep and it.Num_Rua = lt.Num_Rua and it.Num_Col = lt.Num_Col and 
                                    it.Num_Niv = lt.Num_Niv and it.Num_Apt = lt.Num_Apt)
                 Where it.Cod_Estabe = @CodEstabe
                   And it.Num_SeqBal = @NumSeqBal
                   And it.Num_Contag = 1
                   And it.Cod_Local = 1
                   And IsNull(it.Flg_Proces,0) = 0
                      
              Open BALIT_Cr
              Fetch Next From BALIT_Cr Into @CodPrd, @CodLot, @QtdBal, @DatVct, @DatFab,
                                            @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @QtdEmbFec,
                                            @NumPag, @NumSeqIte, @FlgAutDiv,
                                            @SldPra, @SldDep
              While @@FETCH_STATUS = 0
                begin
                  Set @WQtdSldTot = @SldPra + @SldDep
                  
                  if @QtdBal = @WQtdSldTot
                    begin
                      Update BALIT
                         Set Flg_Proces = 1,
                             Tip_Movim = 'X',
                             Cod_MovEst = 0,
                             Qtd_Acerto = 0,
                             Qtd_EstPra = 0, 
                             Qtd_EstDep = 0,
                             Transacao = @Now
                       Where Cod_Estabe = @CodEstabe
                         And Num_SeqBal = @NumSeqBal
                         And Cod_Produt = @CodPrd
                         And Cod_Lote = @CodLot
                         And Num_Contag = 1
                         And Cod_Local = 1
                         And Cod_Dep = @CodDep
                         And Num_Rua = @NumRua
                         And Num_Col = @NumCol
                         And Num_Niv = @NumNiv
                         And Num_Apt = @NumApt 

                      Update PRLTL
                         Set Dat_Vencim = @DatVct,
                             Dat_Fabric = @DatFab,
                             Qtd_EmbFec = @QtdEmbFec
                       Where Cod_Estabe = @CodEstabe      
                         And Cod_Produt = @CodPrd And Cod_Lote = @CodLot
                         And Cod_Dep = @CodDep And Num_Rua = @NumRua
                         And Num_Col = @NumCol And Num_Niv = @NumNiv
                         And Num_Apt = @NumApt
                         And ((Dat_Vencim <> @DatVct) or 					  
                              (Dat_Fabric <> @DatFab) or 					  
                              (Qtd_EmbFec <> @QtdEmbFec))
                    end
                    
                  -- poe endereco picking na memoria
                  Set @WNumRuaPck = 0
                  Select @WNumRuaPck = Num_Rua, 
                         @WNumColPck = Num_Col, 
                         @WNumNivPck = Num_Niv, 
                         @WNumAptPck = Num_Apt 
                    From DPXPR
                   Where Cod_Estabe = @CodEstabe 
                     And Cod_Dep = @CodDep
                     And Cod_Produt = @CodPrd

                  -- DAR SAIDA NO ESTOQUE (1)
                  if (@WQtdSldTot > @QtdBal) and (@FlgAutDiv = 1)
                    begin
                      if @WNumRuaPck = 0
                        begin
                          Set @WMsgErr = 'Produto('+cast(@CodPrd as varchar)+') s/ender.Picking dep.('+cast(@CodDep as varchar)+')'
                          RAISERROR(@WMsgErr,16,1)
                          Rollback Transaction
                          Return
                        end
                    
                      Set @WQtdDif = @WQtdSldTot - @QtdBal
                      Set @WQtdPra = 0
                      Set @WQtdDep = 0

                      if (@WQtdDif > 0) and (@SldDep > 0)
                        begin
                          Set @WQtdDep = Case 
                                           when @SldDep >= @WQtdDif then @WQtdDif 
                                           else @SldDep 
                                         End
			              Set @WQtdDif = @WQtdDif - @WQtdDep   
                        end
                      
                      if (@WQtdDif > 0) and (@SldPra > 0)
                        begin
                          Set @WQtdPra = Case 
                                           when @SldPra >= @WQtdDif then @WQtdDif 
                                           else @SldPra 
                                         End
                          Set @WQtdDif = @WQtdDif - @WQtdPra   
                        end
                        
                      -- transferencia de saida do deposito
                      Update PRLTL
                         Set Qtd_FisPra = Qtd_FisPra - @WQtdPra,
                             Qtd_FisDep = Qtd_FisDep - @WQtdDep,
                             Dat_Vencim = @DatVct,
                             Dat_Fabric = @DatFab,
                             Qtd_EmbFec = @QtdEmbFec
                       Where Cod_Estabe = @CodEstabe      
                         And Cod_Produt = @CodPrd And Cod_Lote = @CodLot
                         And Cod_Dep = @CodDep And Num_Rua = @NumRua
                         And Num_Col = @NumCol And Num_Niv = @NumNiv
                         And Num_Apt = @NumApt
                         And Qtd_SldPra >= @WQtdPra
                         And Qtd_SldDep >= @WQtdDep
                      if @@ROWCOUNT > 0 
                        begin
                          -- registra log de saida
                          Set @WCodOri = 'TRF_EST'
                          Set @WQtdMov = (@WQtdPra + @WQtdDep) * (-1)
                          Exec PR_InserePRLOG @CodEstabe, @CodPrd, @CodLot, @CodDep, 
                                              @NumRua, @NumCol, @NumNiv, @NumApt,
                                              @WQtdMov, @WCodOri, '', @NumSeqBal, '', '', @Login
                          if @@error <> 0 
                            begin
                              Rollback Transaction
                              Return
                            end 
                            
                          -- da entrada picking  
                          Update PRLOT
                             Set Qtd_FisPra = Qtd_FisPra + @WQtdPra,
                                 Qtd_FisDep = Qtd_FisDep + @WQtdDep                         
                           Where Cod_Estabe = @CodEstabe      
                             And Cod_Dep = @CodDep
                             And Cod_Produt = @CodPrd 
                             And Cod_Lote = @CodLot

                          -- registra transferencia de entrada
                          Set @WQtdMov = @WQtdPra + @WQtdDep
                          Exec PR_InserePRLOG @CodEstabe, @CodPrd, @CodLot, @CodDep, 
                                              @WNumRuaPck, @WNumColPck, @WNumNivPck, @WNumAptPck,
                                              @WQtdMov, @WCodOri, '', @NumSeqBal, '', '', @Login
                          if @@error <> 0 
                            begin
                              Rollback Transaction
                              Return
                            end 

                          -- da saida picking (acerto)   
                          Exec PR_ProxNumero 'Acerto', @WCodAcr output
                          if @@error <> 0
                            begin
                              Rollback Transaction
                              Return
                            end
                  
                          Insert into ACERT (Cod_Estabe, Numero, Dat_Movimento, 
                                             Cod_Produto, Cod_Lote, Dat_Vencimento, Dat_Fabric,
                                             Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt,
                                             Qtd_Acerto, Qtd_AceDep, Cod_TipMov, Num_SeqBal, Flg_NotFis, Historico, Usuario, Transacao)
                                    Values  (@CodEstabe, @WCodAcr, @Date, 
                                             @CodPrd, @CodLot, @DatVct, @DatFab,
                                             @CodDep, @WNumRuaPck, @WNumColPck, @WNumNivPck, @WNumAptPck,
                                             @WQtdPra, @WQtdDep, @CodMveSai, @NumSeqBal, 0, 'BALANCO', @Login, GetDate())
                          if @@error <> 0
                            begin
                              Rollback Transaction
                              Return
                            end

                          Update BALIT
                             Set Flg_Proces = 1,
                                 Tip_Movim = 'S',
                                 Cod_MovEst = @CodMveSai,
                                 Qtd_Acerto = @WQtdPra + @WQtdDep,
                                 Qtd_EstPra = @WQtdPra, 
                                 Qtd_EstDep = @WQtdDep,
                                 Transacao = @Now
                           Where Cod_Estabe = @CodEstabe
                            And Num_SeqBal = @NumSeqBal
                            And Cod_Produt = @CodPrd
                            And Cod_Lote = @CodLot
                            And Num_Contag = 1
                            And Cod_Local = 1
                            And Cod_Dep = @CodDep
                            And Num_Rua = @NumRua
                            And Num_Col = @NumCol
                            And Num_Niv = @NumNiv
                            And Num_Apt = @NumApt 

                        end  -- if @@ROWCOUNT > 0 

                    end  -- if (@WQtdSldTot > @QtdBal) and (@FlgAutDiv = 1)

                  -- DAR ENTRADA NO ESTOQUE (2)
                  if (@QtdBal > @WQtdSldTot) and (@FlgAutDiv = 1)
                    begin
                      if @WNumRuaPck = 0
                        begin
                          Set @WMsgErr = 'Produto('+cast(@CodPrd as varchar)+') s/ender.Picking dep.('+cast(@CodDep as varchar)+')'
                          RAISERROR(@WMsgErr,16,1)
                          Rollback Transaction
                          Return
                        end
                   
                      Set @WQtdDif = @QtdBal - @WQtdSldTot
                      
                      Exec PR_ProxNumero 'Acerto', @WCodAcr output
                      if @@error <> 0
                        begin
                          Rollback Transaction
                          Return
                        end
                    
                      Insert into ACERT (Cod_Estabe, Numero, Dat_Movimento, 
                                         Cod_Produto, Cod_Lote, Dat_Vencimento, Dat_Fabric,
                                         Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt,
                                         Qtd_Acerto, Qtd_AceDep, Cod_TipMov, Num_SeqBal, Flg_NotFis, Historico, Usuario, Transacao)
                                Values  (@CodEstabe, @WCodAcr, @Date, 
                                         @CodPrd, @CodLot, @DatVct, @DatFab,
                                         @CodDep, @WNumRuaPck, @WNumColPck, @WNumNivPck, @WNumAptPck,
                                         @WQtdDif, 0, @CodMveEnt, @NumSeqBal, 0, 'BALANCO', @Login, GetDate())
                      if @@error <> 0
                        begin
                          Rollback Transaction
                          Return
                        end
				    
                      -- transfere picking para deposito
                      Update PRLOT
                         Set Qtd_FisPra = Qtd_FisPra - @WQtdDif
                       Where Cod_Estabe = @CodEstabe  
                         And Cod_Dep = @CodDep
                         And Cod_Produt = @CodPrd 
                         And Cod_Lote = @CodLot
                         And Qtd_SldPra >= @WQtdDif
                      if @@ROWCOUNT > 0
                        begin
                          -- registra log de saida
                          Set @WCodOri = 'TRF_EST'
                          Set @WQtdMov = @WQtdDif * (-1)
                          Exec PR_InserePRLOG @CodEstabe, @CodPrd, @CodLot, @CodDep, 
                                              @WNumRuaPck, @WNumColPck, @WNumNivPck, @WNumAptPck,
                                              @WQtdMov, @WCodOri, '', @NumSeqBal, '', '', @Login
                          if @@error <> 0 
                            begin
                              Rollback Transaction
                              Return
                            end 
                        
                          -- transferencia de entrada
                          Update PRLTL
                             Set Qtd_FisPra = Qtd_FisPra + @WQtdDif,
                                 Dat_Vencim = @DatVct,
                                 Dat_Fabric = @DatFab,
                                 Qtd_EmbFec = @QtdEmbFec
                           Where Cod_Estabe = @CodEstabe      
                             And Cod_Produt = @CodPrd And Cod_Lote = @CodLot
                             And Cod_Dep = @CodDep And Num_Rua = @NumRua
                             And Num_Col = @NumCol And Num_Niv = @NumNiv
                             And Num_Apt = @NumApt
				    
                          -- registra log de entrada
                          Set @WQtdMov = @WQtdDif
                          Exec PR_InserePRLOG @CodEstabe, @CodPrd, @CodLot, @CodDep, 
                                              @NumRua, @NumCol, @NumNiv, @NumApt,
                                              @WQtdMov, @WCodOri, '', @NumSeqBal, '', '', @Login
                          if @@error <> 0 
                            begin
                              Rollback Transaction
                              Return
                            end 
				    
                          Update BALIT
                             Set Flg_Proces = 1,
                                 Tip_Movim = 'E',
                                 Cod_MovEst = @CodMveEnt,
                                 Qtd_Acerto = @WQtdDif,
                                 Qtd_EstPra = @WQtdDif, 
                                 Qtd_EstDep = 0,
                                 Transacao = @Now
                           Where Cod_Estabe = @CodEstabe
                             And Num_SeqBal = @NumSeqBal
                             And Cod_Produt = @CodPrd
                             And Cod_Lote = @CodLot
                             And Num_Contag = 1
                             And Cod_Local = 1
                             And Cod_Dep = @CodDep
                             And Num_Rua = @NumRua
                             And Num_Col = @NumCol
                             And Num_Niv = @NumNiv
                             And Num_Apt = @NumApt 
                        end 
                    end

                  Fetch Next From BALIT_Cr Into @CodPrd, @CodLot, @QtdBal, @DatVct, @DatFab,
                                                @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @QtdEmbFec,
                                                @NumPag, @NumSeqIte, @FlgAutDiv,
                                                @SldPra, @SldDep
                end
              Close BALIT_Cr
              Deallocate BALIT_Cr
              
              -- encerra inventario
              Exec PR_InventarioEncerramento @CodEstabe, @NumSeqBal, @Login 
              if @@error <> 0
                begin
                  Rollback Transaction
                  Return
                end

            end  -- if Exists(
            
          else
          
-------------------------------  P I C K I N G  --------------------------------------------------------------------            
          if Exists(Select 1
                      From BALCB
                     Where Cod_Estabe = @CodEstabe
                       And Num_SeqBal = @NumSeqBal
                       And IsNull(Flg_Proces,0) = 0
                       And Tip_Balanc = 'P') 
            begin
              -- inclui itens de BALIT com lotes inexistentes em PRLOT
              Insert into PRLOT (Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote, Dat_Vencim, Dat_Fabric, Qtd_FisPra, Qtd_SolPra, Qtd_FisDep, Qtd_SolDep)
                Select distinct b.Cod_Estabe, b.Cod_Dep, b.Cod_Produt, b.Cod_Lote, b.Dat_VctLot, b.Dat_Fabric, 0, 0, 0, 0
                  From BALIT b Left Outer Join
                       PRLOT l on (b.Cod_Estabe = l.Cod_Estabe and b.Cod_Dep = l.Cod_Dep and b.Cod_Produt = l.Cod_Produt and b.Cod_Lote = l.Cod_Lote)
                 Where b.Cod_Estabe = @CodEstabe 
                   And b.Num_SeqBal = @NumSeqBal 
                   And b.Num_Contag = 1
                   And b.Cod_Local = 1
                   And IsNull(b.Flg_Proces,0) = 0
                   And l.Cod_Produt is null
              if (@@error <> 0)
                begin
                  Rollback Transaction
                  Return
                end
  
              -- atualiza estoque disponivel atual de PRLOT em BALIT
              Update it
                 Set it.Qtd_SldEst = IsNull(lt.Qtd_SldPra,0)+IsNull(lt.Qtd_SldDep,0) 
                From BALIT it Inner Join
                     PRLOT lt on (it.Cod_Estabe = lt.Cod_Estabe and it.Cod_Dep = lt.Cod_Dep and 
                                  it.Cod_Produt = lt.Cod_Produt and it.Cod_Lote = lt.Cod_Lote)
               Where it.Cod_Estabe = @CodEstabe
                 And it.Num_SeqBal = @NumSeqBal
                 And it.Num_Contag = 1
                 And it.Cod_Local = 1
                 And IsNull(it.Flg_Proces,0) = 0
            
              Declare BALIT_Cr Cursor Local For 
                Select it.Cod_Produt, it.Cod_Lote, it.Qtd_Produt, it.Dat_VctLot, it.Dat_Fabric,
                       it.Cod_Dep, it.Num_Rua, it.Num_Col, it.Num_Niv, it.Num_Apt, it.Qtd_EmbFec,
                       it.Num_Pagina, it.Num_SeqIte, IsNull(Flg_AutDiv,0),
                       IsNull(lt.Qtd_SldPra,0), IsNull(lt.Qtd_SldDep,0) 
                  From BALIT it Inner Join
                       PRLOT lt on (it.Cod_Estabe = lt.Cod_Estabe and it.Cod_Dep = lt.Cod_Dep and 
                                    it.Cod_Produt = lt.Cod_Produt and it.Cod_Lote = lt.Cod_Lote)
                 Where it.Cod_Estabe = @CodEstabe
                   And it.Num_SeqBal = @NumSeqBal
                   And it.Num_Contag = 1
                   And it.Cod_Local = 1
                   And IsNull(it.Flg_Proces,0) = 0
                      
              Open BALIT_Cr
              Fetch Next From BALIT_Cr Into @CodPrd, @CodLot, @QtdBal, @DatVct, @DatFab,
                                            @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @QtdEmbFec,
                                            @NumPag, @NumSeqIte, @FlgAutDiv,
                                            @SldPra, @SldDep
              While @@FETCH_STATUS = 0
                begin
                  Set @WQtdSldTot = @SldPra + @SldDep
                  
                  if @QtdBal = @WQtdSldTot
                    begin
                      Update BALIT
                         Set Flg_Proces = 1,
                             Tip_Movim = 'X',
                             Cod_MovEst = 0,
                             Qtd_Acerto = 0,
                             Qtd_EstPra = 0, 
                             Qtd_EstDep = 0,
                             Transacao = @Now
                       Where Cod_Estabe = @CodEstabe
                         And Num_SeqBal = @NumSeqBal
                         And Cod_Produt = @CodPrd
                         And Cod_Lote = @CodLot
                         And Num_Contag = 1
                         And Cod_Local = 1
                         And Cod_Dep = @CodDep
                         And Num_Rua = @NumRua
                         And Num_Col = @NumCol
                         And Num_Niv = @NumNiv
                         And Num_Apt = @NumApt 
                    end

                  -- DAR SAIDA NO ESTOQUE (1)
                  if (@WQtdSldTot > @QtdBal) and (@FlgAutDiv = 1)
                    begin
                      Set @WQtdDif = @WQtdSldTot - @QtdBal
                      Set @WQtdPra = 0
                      Set @WQtdDep = 0

                      if (@WQtdDif > 0) and (@SldDep > 0)
                        begin
                          Set @WQtdDep = Case 
                                           when @SldDep >= @WQtdDif then @WQtdDif 
                                           else @SldDep 
                                         End
                          Set @WQtdDif = @WQtdDif - @WQtdDep   
                        end
                      
                      if (@WQtdDif > 0) and (@SldPra > 0)
                        begin
                          Set @WQtdPra = Case 
                                           when @SldPra >= @WQtdDif then @WQtdDif 
                                           else @SldPra 
                                         End
                          Set @WQtdDif = @WQtdDif - @WQtdPra   
                        end
                        
                      -- da saida picking (acerto)   
                      if Exists(Select 1 From PRLOT 
                                 Where Cod_Estabe = @CodEstabe 
                                   And Cod_Dep = @CodDep
                                   And Cod_Produt = @CodPrd And Cod_Lote = @CodLot 
                                   And Qtd_SldPra >= @WQtdPra 
                                   And Qtd_SldDep >= @WQtdDep)
                        begin
                          Exec PR_ProxNumero 'Acerto', @WCodAcr output
                          if @@error <> 0
                            begin
                              Rollback Transaction
                              Return
                            end
                  
                          Insert into ACERT (Cod_Estabe, Numero, Dat_Movimento, 
                                             Cod_Produto, Cod_Lote, Dat_Vencimento, Dat_Fabric,
                                             Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt,
                                             Qtd_Acerto, Qtd_AceDep, Cod_TipMov, Num_SeqBal, Flg_NotFis, Historico, Usuario, Transacao)
                                    Values  (@CodEstabe, @WCodAcr, @Date, 
                                             @CodPrd, @CodLot, @DatVct, @DatFab,
                                             @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt,
                                             @WQtdPra, @WQtdDep, @CodMveSai, @NumSeqBal, 0, 'BALANCO', @Login, GetDate())
                          if @@error <> 0
                            begin
                              Rollback Transaction
                              Return
                            end

                          Update BALIT
                             Set Flg_Proces = 1,
                                 Tip_Movim = 'S',
                                 Cod_MovEst = @CodMveSai,
                                 Qtd_Acerto = @WQtdPra + @WQtdDep,
                                 Qtd_EstPra = @WQtdPra, 
                                 Qtd_EstDep = @WQtdDep,
                                 Transacao = @Now
                           Where Cod_Estabe = @CodEstabe
                             And Num_SeqBal = @NumSeqBal
                             And Cod_Produt = @CodPrd
                             And Cod_Lote = @CodLot
                             And Num_Contag = 1
                             And Cod_Local = 1
                             And Cod_Dep = @CodDep
                             And Num_Rua = @NumRua
                             And Num_Col = @NumCol
                             And Num_Niv = @NumNiv
                             And Num_Apt = @NumApt 

                        end  -- if Exists(

                    end  -- if (@WQtdSldTot > @QtdBal) and (@FlgAutDiv = 1)

                  -- DAR ENTRADA NO ESTOQUE (2)
                  if (@QtdBal > @WQtdSldTot) and (@FlgAutDiv = 1)
                    begin
                      Set @WQtdDif = @QtdBal - @WQtdSldTot
                      
                      -- da entrada no picking (acerto) 
                      Exec PR_ProxNumero 'Acerto', @WCodAcr output
                      if @@error <> 0
                        begin
                          Rollback Transaction
                          Return
                        end
                  
                      Insert into ACERT (Cod_Estabe, Numero, Dat_Movimento, 
                                         Cod_Produto, Cod_Lote, Dat_Vencimento, Dat_Fabric,
                                         Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt,
                                         Qtd_Acerto, Qtd_AceDep, Cod_TipMov, Num_SeqBal, Flg_NotFis, Historico, Usuario, Transacao)
                                Values  (@CodEstabe, @WCodAcr, @Date, 
                                         @CodPrd, @CodLot, @DatVct, @DatFab,
                                         @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt,
                                         @WQtdDif, 0, @CodMveEnt, @NumSeqBal, 0, 'BALANCO', @Login, GetDate())
                      if @@error <> 0
                        begin
                          Rollback Transaction
                          Return
                        end

                      Update BALIT
                         Set Flg_Proces = 1,
                             Tip_Movim = 'E',
                             Cod_MovEst = @CodMveEnt,
                             Qtd_Acerto = @WQtdDif,
                             Qtd_EstPra = @WQtdDif, 
                             Qtd_EstDep = 0,
                             Transacao = @Now
                       Where Cod_Estabe = @CodEstabe
                         And Num_SeqBal = @NumSeqBal
                         And Cod_Produt = @CodPrd
                         And Cod_Lote = @CodLot
                         And Num_Contag = 1
                         And Cod_Local = 1
                         And Cod_Dep = @CodDep
                         And Num_Rua = @NumRua
                         And Num_Col = @NumCol
                         And Num_Niv = @NumNiv
                         And Num_Apt = @NumApt 
                    end

                  Fetch Next From BALIT_Cr Into @CodPrd, @CodLot, @QtdBal, @DatVct, @DatFab,
                                                @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @QtdEmbFec,
                                                @NumPag, @NumSeqIte, @FlgAutDiv,
                                                @SldPra, @SldDep
                end
              Close BALIT_Cr
              Deallocate BALIT_Cr
              
              -- encerra inventario
              Exec PR_InventarioEncerramento @CodEstabe, @NumSeqBal, @Login 
              if @@error <> 0
                begin
                  Rollback Transaction
                  Return
                end

            end  -- if Exists(
          

          -- iguala estoque entre PRXES e PRLOT
          -- dá entrada/saída em PRXES em estoques divergentes
          if Exists(Select 1
                      From BALIT b
                           inner join PRXES p on b.Cod_Estabe = p.Cod_Estabe and b.Cod_Produt = p.Cod_Produt
                     Where b.Cod_Estabe = @CodEstabe 
                       And b.Num_SeqBal = @NumSeqBal 
                       And b.Num_Contag = 1
                       And b.Cod_Local = 1
                       And IsNull(b.Flg_Proces,0) = 1
                       And p.Qtd_Fisico <> dbo.FN_EstoqueFisicoPrdLote(p.Cod_Estabe,p.Cod_Produt,'TODOS'))
            begin
              Declare PRSLD_Cr Cursor Local Fast_Forward For 
	     
                Select distinct b.Cod_Produt,
		 	          QtdDif =  p.Qtd_Fisico - dbo.FN_EstoqueFisicoPrdLote(p.Cod_Estabe,p.Cod_Produt,'TODOS')
                  From BALIT b
                       inner join PRXES p on b.Cod_Estabe = p.Cod_Estabe and b.Cod_Produt = p.Cod_Produt
                 Where b.Cod_Estabe = @CodEstabe 
                   And b.Num_SeqBal = @NumSeqBal 
                   And b.Num_Contag = 1
                   And b.Cod_Local = 1
                   And IsNull(b.Flg_Proces,0) = 1
                   And p.Qtd_Fisico <> dbo.FN_EstoqueFisicoPrdLote(p.Cod_Estabe,p.Cod_Produt,'TODOS')	    
		 
              Open PRSLD_Cr
              Fetch Next From PRSLD_Cr Into @CodPrd, @WQtdDif
              While @@FETCH_STATUS = 0
                begin
                  -- pega o ultimo movimento do produto
                  Select top 1 @QtdSldAntPra = IsNull(Qtd_SldPra,0), 
                               @QtdSldAntDep = IsNull(Qtd_SldDep,0)
                    From PRSLD 
                   Where Cod_Estabe = @CodEstabe
                     and Cod_Produt = @CodPrd 
                     and Dat_Movime <= @Date
                   Order By Dat_Movime desc
		 
                  if not Exists(Select 1 from PRSLD 
                                 Where Cod_Estabe = @CodEstabe and Cod_Produt = @CodPrd and Dat_Movime = @Date)
                    begin
                      Insert into PRSLD (Cod_Estabe, Cod_Produt, Dat_Movime, Qtd_SldPra,    Qtd_SldDep) 
                                 Values (@CodEstabe, @CodPrd,    @Date,      @QtdSldAntPra, @QtdSldAntDep) 
                      if (@@error <> 0)
                        begin
                          Rollback Transaction
                          Return
                        end
                    end
		 
                  -- dá saída em PRXES
                  if @WQtdDif > 0
                    begin
                      -- ver se pode retirar de entradas "manuais"
                      Declare @WQtdExcEnt int = 0
                      Select @WQtdExcEnt = Case
                                             When (IsNull(Qtd_InfEntInv,0) > 0) and (Qtd_EntOut >= Qtd_InfEntInv) then
                                               Case 
                                                 When IsNull(Qtd_InfEntInv,0) > @WQtdDif then @WQtdDif 
                                                 Else Qtd_InfEntInv 
                                               End
                                             Else  0
                                           End
                        From PRSLD
                       Where Cod_Estabe = @CodEstabe
                         and Cod_Produt = @CodPrd
                         and Dat_Movime = @Date
				   
                      if @WQtdExcEnt > 0
                        begin
                          Update PRSLD
                             Set Qtd_EntOut = Qtd_EntOut - @WQtdExcEnt,
                                 Qtd_InfEntInv = Qtd_InfEntInv - @WQtdExcEnt,
                                 @WQtdDif = @WQtdDif - @WQtdExcEnt
                           Where Cod_Estabe = @CodEstabe
                             and Cod_Produt = @CodPrd
                             and Dat_Movime = @Date
                        end


                    -- registra qtd ajustada "manualmente" em PRXES devido inconsistência 
                    if @WQtdDif > 0
                      begin
                        Update PRSLD 
                           Set Qtd_SaiOut = Qtd_SaiOut + @WQtdDif,
                               Qtd_InfSaiInv = IsNull(Qtd_InfSaiInv,0) + @WQtdDif
                         Where Cod_Estabe = @CodEstabe
                           and Cod_Produt = @CodPrd
                           and Dat_Movime = @Date
                      end
		          
                      -- saldos atuais
                      Select @SldPra = Qtd_SldPra, 
                             @SldDep = Qtd_SldDep
                        From PRSLD
                       Where Cod_Estabe = @CodEstabe
                         and Cod_Produt = @CodPrd
                         and Dat_Movime = @Date
		          
                      Set @WQtdMovDep = 0
                      Set @WQtdMovPra = 0
		          
                      -- repõe qtd subtraídas de outras entradas
                      Set @WQtdDif = @WQtdDif + @WQtdExcEnt

                      if (@SldDep > 0) and (@WQtdDif > 0)
                        begin
                          Set @WQtdMovDep = Case 
                                              when @SldDep < @WQtdDif then @SldDep 
                                              else @WQtdDif 
                                            End
                          Set @WQtdDif = @WQtdDif - @WQtdMovDep
                        end
                     
                      if (@SldPra > 0) and (@WQtdDif > 0)
                        begin
                          Set @WQtdMovPra = Case 
                                              when @SldPra < @WQtdDif then @SldPra 
                                              else @WQtdDif 
                                            End
                          Set @WQtdDif = @WQtdDif - @WQtdMovPra
                        end
		          
                      Update PRSLD 
                         Set Qtd_SldDep = Qtd_SldDep - @WQtdMovDep,
                             Qtd_SldPra = Qtd_SldPra - @WQtdMovPra
                       Where Cod_Estabe = @CodEstabe 
                         and Cod_Produt = @CodPrd
                         and Dat_Movime = @Date
		          
                      Update PRXES
                         Set Qtd_Fisico = Qtd_Fisico - @WQtdMovDep - @WQtdMovPra
                       Where Cod_Estabe = @CodEstabe 
                         And Cod_Produt = @CodPrd
		 
                    end  -- if @WQtdDif > 0
		 
                  -- dá entrada em PRXES
                  if @WQtdDif < 0
                    begin
                      Set @WQtdDif = Abs(@WQtdDif)  
		 
                      -- ver se pode retirar de saidas "manuais"
                      Declare @WQtdExcSai int = 0
                      Select @WQtdExcSai = Case
                                             When (IsNull(Qtd_InfSaiInv,0) > 0) and (Qtd_SaiOut >= Qtd_InfSaiInv) then
                                               Case 
                                                 When IsNull(Qtd_InfSaiInv,0) > @WQtdDif then @WQtdDif 
                                                 Else Qtd_InfSaiInv 
                                               End
                                             Else  0
                                           End
                        From PRSLD
                       Where Cod_Estabe = @CodEstabe
                         and Cod_Produt = @CodPrd
                         and Dat_Movime = @Date
			  
                      if @WQtdExcSai > 0
                        begin
                          Update PRSLD
                             Set Qtd_SaiOut = Qtd_SaiOut - @WQtdExcSai,
                                 Qtd_InfSaiInv = Qtd_InfSaiInv - @WQtdExcSai,
                                 @WQtdDif = @WQtdDif - @WQtdExcSai
                           Where Cod_Estabe = @CodEstabe
                             and Cod_Produt = @CodPrd
                             and Dat_Movime = @Date
                        end
			  
			  
                      -- registra qtd ajustada "manualmente" em PRXES devido inconsistência 
                      if @WQtdDif > 0
                        begin
                          Update PRSLD 
                             Set Qtd_EntOut = Qtd_EntOut + @WQtdDif,
                                 Qtd_InfEntInv = IsNull(Qtd_InfEntInv,0) + @WQtdDif
                           Where Cod_Estabe = @CodEstabe
                             and Cod_Produt = @CodPrd
                             and Dat_Movime = @Date
                        end


                      -- repõe qtd subtraídas de outras entradas
                      Set @WQtdDif = @WQtdDif + @WQtdExcSai

                      Update PRSLD 
                         Set Qtd_SldPra = Qtd_SldPra + @WQtdDif
                       Where Cod_Estabe = @CodEstabe 
                         and Cod_Produt = @CodPrd
                         and Dat_Movime = @Date
		          
                      Update PRXES
                         Set Qtd_Fisico = Qtd_Fisico + @WQtdDif
                       Where Cod_Estabe = @CodEstabe 
                         And Cod_Produt = @CodPrd
		 
                    end  -- if @WQtdDif < 0
		 
                  Fetch Next From PRSLD_Cr Into @CodPrd, @WQtdDif
                end
              Close PRSLD_Cr
              Deallocate PRSLD_Cr
            end  -- if Exists(Select 

        Commit Transaction
      end   
  end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CancelaPDV]
@CodEstabe int,
@CodPed int,
@NomUsu varchar(15),
@FlgAtuQtdSolici bit = 0

AS

SET NOCOUNT ON

-- Pegar a data atual com hora formatada compativel com delphi
Set DateFormat ymd
Declare @Now datetime
Set @Now = Cast(Cast(Datepart(yy,GetDate()) as varchar)+'-'+Cast(Datepart(mm,GetDate()) as varchar)+'-'+Cast(Datepart(dd,GetDate()) as varchar)+' '+
                Cast(Datepart(hh,GetDate()) as varchar)+':'+Cast(Datepart(mi,GetDate()) as varchar)+':'+Cast(Datepart(ss,GetDate()) as varchar) as datetime)

Begin Transaction

Declare @TipPed varchar(1),
        @StaPdv1 varchar(1),
        @StaPdv2 varchar(1),
        @TipBlq varchar(2),
        @IdConsig int,
        @NumSeqCtr int,
        @NumPrtOri int,
        @CodOriPdv varchar(1),
        @FlgWms bit,
        @CodCli int,
        @NumPdvLig int,
        @NomUsuCan varchar(15),
        @MsgCan varchar(80),
        @DesOco varchar(120),
        @FlgDel bit = 0

        
-- salva dados do cabecalho antes da exclusao dos itens
Select @TipPed = Tip_Pedido,
       @StaPdv1 = Status1,
       @StaPdv2 = Status2,
       @TipBlq = Bloqueio,
       @IdConsig = IsNull(Id_Consig,0),
       @NumSeqCtr = IsNull(Num_SequenciaCtr,0),
       @NumPrtOri = IsNull(Num_PrtOri,0),
       @FlgWms = IsNull(Flg_Wms,0),
       @CodCli = IsNull(Cod_Cliente,0),
       @NumPdvLig = IsNull(Num_PdvLig,0),
       @NomUsuCan = Nom_UsuCancel,
       @MsgCan = Ltrim(Rtrim(IsNull(Msg_JustCancel,'')))
  From PDVCB
 Where Cod_Estabe = @CodEstabe
   And Numero = @CodPed

if not Exists(Select 1 From TBGEN Where Cod_TabGen = 'MTV' And Cod_Gen = 'MVX')
  Insert Into TBGEN (Cod_TabGen, Cod_Gen, Des_Gen)
    Values ('MTV', 'MVX', 'Motivo Nao Especificado')

if @StaPdv1 <> 'C'
  begin

    -- atualizar PDVCB
    Update pv 
       Set pv.Cod_MtvRej = 'MVX',
           pv.Nom_UsuCancel = @NomUsu
      From PDVCB pv 
     Where pv.Cod_Estabe = @CodEstabe
       And pv.Numero = @CodPed
    And IsNull(pv.Cod_MtvRej,'') = ''

    -- atualizar PDECB
    Update pe 
       Set pe.Cod_MtvRej = pv.Cod_MtvRej, 
           pe.Des_MtvRej = tg.Des_Gen 
      From PDECB pe Inner Join 
           PDVCB pv on pe.Cod_Estabe = pv.Cod_Estabe and pe.Num_PedVen = pv.Numero Inner Join 
           TBGEN tg on ((tg.Cod_TabGen = 'MTV') and (tg.Cod_Gen = pv.Cod_MtvRej)) 
     Where pv.Cod_Estabe = @CodEstabe
       And pv.Numero = @CodPed
       And IsNull(pe.Cod_MtvRej,'') = ''

    if Exists(Select 1 From PDVIT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed)
      begin
        Set @FlgDel = 0
        EXEC PR_ExcluiCancelaItensPDV 'S', @CodEstabe, @CodPed, @TipPed, @StaPdv1, @StaPdv2, @TipBlq, @IdConsig, @NumSeqCtr, @NumPrtOri, 
                                      @FlgWms, @FlgDel, @FlgAtuQtdSolici
        if @@error <> 0
          begin
            if @@trancount > 0
              Rollback Transaction
            Return
          end
      end

    Update PDVCB
       Set Status1 = 'C',
           Bloqueio = 'SR',
           Flg_Credito = null,
           Hor_Cancel = @Now, 
           Usuario = @NomUsu,
           Transacao = GetDate()
     Where Cod_Estabe = @CodEstabe   
       And Numero = @CodPed

    Update pe 
       Set pe.Dat_Cancel = pv.Hor_Cancel
      From PDECB pe Inner Join 
           PDVCB pv on pe.Cod_Estabe = pv.Cod_Estabe and pe.Num_PedVen = pv.Numero
     Where pv.Cod_Estabe = @CodEstabe
       And pv.Numero = @CodPed

    -- hospitalar  
    -- exclui contratos vinculados
    Exec PR_ExcluiContratosPDV @CodEstabe, @CodPed, 0
    if @@error <> 0
      begin
        if @@trancount > 0
          Rollback Transaction
        Return
      end

    if @NumPdvLig > 0
      begin
        Set @CodOriPdv = (Select Substring(Cod_OrigemPdv,1,1) From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @NumPdvLig)
        if (@CodOriPdv = 'D') and        
           Exists(Select 1 From PDVCB 
                   Where Cod_Estabe = @CodEstabe
                     And Numero = @NumPdvLig
                     And Status2 <> 'N'
                     And Status2 <> 'D'
                     And Status2 <> 'X'
                     And Flg_Calc = 0
                     And ((Flg_WMS = 0) or 
                          ((Flg_WMS = 1) and (not Exists(Select 1 From PDVLT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @NumPdvLig)))))
          begin
            -- estorna quantidades
            Update p1
               Set p1.Qtd_Bonificacao = p1.Qtd_Bonificacao + p2.Qtd_Pedido + p2.Qtd_Bonificacao,
                   p1.Qtd_Solicitado = p1.Qtd_Solicitado + p2.Qtd_Pedido + p2.Qtd_Bonificacao,
                   p1.Qtd_Pra = p1.Qtd_Pra + p2.Qtd_Pra,
                   p1.Qtd_Dep = p1.Qtd_Dep + p2.Qtd_Dep
              From PDVIT p1, PDVIT p2
             Where p1.Cod_Estabe = @CodEstabe
               And p1.Cod_Pedido = @CodPed
               And p2.Cod_Estabe = @CodEstabe
               And p2.Cod_Pedido = @NumPdvLig
               And p1.Cod_Produto = p2.Cod_Produto
               And p1.Cod_Lote = p2.Cod_Lote
               And p1.Tip_Sai = p2.Tip_Sai
               And p2.Qtd_Pedido > 0
          
            Delete From PDVCB 
             Where Cod_Estabe = @CodEstabe
               And Numero = @NumPdvLig
          end
      end    
  end             
  
-- registra cancelamento do nas ocorrencias do cliente
if Exists(Select 1 From CLIEN Where Codigo = @CodCli and @CodCli > 0)
  begin
    Set @DesOco = 'CANCELAMENTO DO PEDIDO ' + cast(@CodPed as varchar)+':'
    if Exists(Select 1 From CLIOC Where Cod_Client = @CodCli and Upper(Des_Ocorre) = Upper(@DesOco))
      Delete From CLIOC Where Cod_Client = @CodCli and Upper(Des_Ocorre) = Upper(@DesOco)
    Delete From CLIOC Where IsNull(Ltrim(Rtrim(Des_Ocorre)),'') = ''

    Set @DesOco = @DesOco+' '+Ltrim(@MsgCan)
    Insert Into CLIOC (Cod_Client,Cod_Estabe,Transacao,Des_Ocorre,Usuario,Flg_LanAut)
               Values (@CodCli, @CodEstabe, @Now, @DesOco, @NomUsuCan, 1)
  end
  
if @@trancount > 0
  Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_BalanProcessaEstoque]
@CodEstabe int,
@DatPrc smalldatetime,
@CodMveEnt int,
@CodMveSai int,
@Login VarChar(15) 

AS

SET NOCOUNT ON
SET ANSI_WARNINGS OFF

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = cast(GetDAte() as date)

-- ESTOQUES DE PRODUTOS RESERVADOS, AVARIADOS e SOLICITADOS POR PEDIDOS NAO SAO CONSIDERADOS

Declare @WNumSeqBal int,
        @WNumCtg int,
        @WFlgOk bit,
        @WMsgErr varchar(40) ,
        @WQtdMve Int, 
        @WTipMveEnt varchar(1),
        @WTipMveSai varchar(1),
        @WMaxDatMov smalldatetime,
        @WQtdSldAnt int,
        @WQtdSldAtu int,
        @WCodDep smallint,
		@Usuario varchar(15)

-- verifica data da ultima movimentacao em PRSLD
Set @WMaxDatMov = (Select max(Dat_Movime) From PRSLD Where Cod_Estabe = @CodEstabe)

-- verifica codigos de movimentacao                 
Set @WTipMveEnt = (Select Tip_Movimento From TPMVE Where Codigo = @CodMveEnt) 
Set @WTipMveSai = (Select Tip_Movimento From TPMVE Where Codigo = @CodMveSai) 
-- tem que existir a 1a. contagem
Set @WNumCtg = (Select distinct top 1 Contagem From BALAN Where Cod_Estabe = @CodEstabe Order by Contagem)

if @Date < @WMaxDatMov
  RAISERROR('Existe(m) registro(s) de movimento(s) com data superior à data do processamento',16,1)
else
if @WTipMveEnt <> 'E'
  RAISERROR('Código de movimentação de entrada inválida',16,1)
else
if @WTipMveSai <> 'S'
  RAISERROR('Código de movimentação de saída inválida',16,1)
else
if @WNumCtg <> 1
  RAISERROR('Existe Contagem inválida',16,1)
else
  begin
	-- usuario infarma auditoria
	Set @Usuario = dbo.FN_UsuarioInfarma()
	if @Login = '' 
	  Set @Login = Substring(@Usuario,1,15)

    Set @WFlgOk = 1
    Set @WMsgErr = ''
    Set @WNumCtg = (Select Max(Contagem) From BALAN Where Cod_Estabe = @CodEstabe)

    Set @WCodDep = 1
    Update BALAN
       Set Cod_Dep = @WCodDep
     Where IsNull(Cod_Dep,0) = 0

    if @WNumCtg > 1
      begin
        -- se existem mais de 1 contagem verificar diferencas entre contagem 1 e outras
        -- itens com contagens diferentes
        if Exists(Select b1.Cod_Produto, b1.Cod_Lote, sum(b1.Quantidade)
                  From BALAN b1
                  Where b1.Cod_Estabe = @CodEstabe
                  And b1.Contagem = 1 
                  Group By b1.Cod_Produto, b1.Cod_Lote
                  Having sum(b1.Quantidade) <> (Select sum(Quantidade) From BALAN 
                                                Where Cod_Estabe = @CodEstabe 
                                                and Cod_Produto = b1.Cod_Produto
                                                and Cod_Lote = b1.Cod_Lote
                                                and Contagem = 2))
          begin
            Set @WFlgOk = 0
            Set @WMsgErr = 'Inconsistência(s) entre contagens 1 e 2)'
          end

        -- itens com lotes em 1 não existem em 2
        if @WFlgOk = 1
          if Exists(Select distinct b1.Cod_Produto, b1.Cod_Lote
                    From BALAN b1
                    Where b1.Cod_Estabe = @CodEstabe
                    and b1.Contagem = 1 
                    and b1.Cod_Lote not in (Select distinct Cod_Lote From BALAN 
                                            Where Cod_Estabe = @CodEstabe 
                                            and Cod_Produto = b1.Cod_Produto 
                                            And Contagem = 2))
            begin
              Set @WFlgOk = 0
              Set @WMsgErr = 'Falta(m) iten(s)/lote(s) na contagem 2'
            end

        -- itens com lotes em 2 não existem em 1
        if @WFlgOk = 1
          if Exists(Select distinct b2.Cod_Produto, b2.Cod_Lote
                    From BALAN b2
                    Where b2.Cod_Estabe = @CodEstabe 
                    and b2.Contagem = 2 
                    and b2.Cod_Lote not in (Select distinct Cod_Lote From BALAN 
                                            Where Cod_Estabe = @CodEstabe 
                                            and Cod_Produto = b2.Cod_Produto 
                                            And Contagem = 1))
            begin
              Set @WFlgOk = 0
              Set @WMsgErr = 'Falta(m) iten(s) na contagem 1'
            end

        -- itens em 1 não existem em 2
        if @WFlgOk = 1
          if Exists(Select Cod_Produto, Cod_Lote
                    From BALAN 
                    Where Cod_Estabe = @CodEstabe 
                    and Contagem = 1
                    and Cod_Produto not in (Select distinct Cod_Produto From BALAN Where Cod_Estabe = @CodEstabe and Contagem = 2))
            begin
              Set @WFlgOk = 0
              Set @WMsgErr = 'Falta(m) produto(s) na contagem 2'
            end

        -- itens em 2 não existem em 1
        if @WFlgOk = 1    
          if Exists(Select Cod_Produto, Cod_Lote
                    From BALAN 
                    Where Cod_Estabe = @CodEstabe 
                    and Contagem = 2 
                    and Cod_Produto not in (Select distinct Cod_Produto From BALAN Where Cod_Estabe = @CodEstabe and Contagem = 1))
            begin
              Set @WFlgOk = 0
              Set @WMsgErr = 'Falta(m) produto(s) na contagem 1'
            end
      end   -- if @WNumCtg > 1
   
    -- ver se existem produtos de mesmo lote com vencimentos diferentes
    if @WFlgOk = 1    
      begin
        if Exists(Select distinct b1.Cod_Produto, b1.Cod_LOte, b1.Dat_Vencim
                  From BALAN b1
                  Where b1.Cod_Estabe = @CodEstabe 
                  and b1.Cod_Produto in (Select b2.Cod_Produto
                                           From BALAN b2
                                           Where b2.Cod_Estabe = @CodEstabe 
                                           and b2.Cod_Produto = b1.Cod_Produto
                                           And b2.Cod_Lote = b1.Cod_Lote
                                           And b2.Dat_Vencim <> b1.Dat_Vencim
                                           And ((b2.Local <> b1.Local) or (b2.Contagem <> b2.Contagem))))
          begin
            Set @WFlgOk = 0
            Set @WMsgErr = 'Produto(s)/lote com Vencto.diferentes'
          end
        if Exists(Select distinct b1.Cod_Produto, b1.Cod_LOte, b1.Dat_Fabric
                  From BALAN b1
                  Where b1.Cod_Estabe = @CodEstabe 
                  and b1.Cod_Produto in (Select b2.Cod_Produto
                                           From BALAN b2
                                           Where b2.Cod_Estabe = @CodEstabe 
                                           and b2.Cod_Produto = b1.Cod_Produto
                                           And b2.Cod_Lote = b1.Cod_Lote
                                           And b2.Dat_Fabric <> b1.Dat_Fabric
                                           And ((b2.Local <> b1.Local) or (b2.Contagem <> b2.Contagem))))
          begin
            Set @WFlgOk = 0
            Set @WMsgErr = 'Produto(s)/lote com Fabricacao diferentes'
          end
      end

    -- verifica DIVERGENCIAS DE ESTOQUES
    if @WFlgOk = 1    
      begin
        -- Normaliza PRLOT, PRLTL
        Update PRLOT
           Set Qtd_FisPra = 0
         Where Cod_Estabe = @CodEstabe 
           And ((Qtd_FisPra < 0) or (Qtd_FisPra is null))

        Update PRLOT
           Set Qtd_FisDep = 0
         Where Cod_Estabe = @CodEstabe 
           And ((Qtd_FisDep < 0) or (Qtd_FisDep is null))
      
        Update PRLTL
           Set Qtd_FisPra = 0
         Where Cod_Estabe = @CodEstabe 
           And ((Qtd_FisPra < 0) or (Qtd_FisPra is null))

        Update PRLTL
           Set Qtd_FisDep = 0
         Where Cod_Estabe = @CodEstabe 
           And ((Qtd_FisDep < 0) or (Qtd_FisDep is null))
      end
      
    if @WFlgOk = 0
      RAISERROR(@WMsgErr,16,1)
    else
      begin
        Begin Transaction
          Declare @CodPrd int,
                  @CodLot varchar(20) ,
                  @DatVct smalldatetime,
                  @DatFab smalldatetime,
                  @SldPra int,
                  @SldDep int,
                  @CodLotDes varchar(20) ,
                  @DatVctDes smalldatetime,
                  @DatFabDes smalldatetime,
                  @QtdBal int,
                  @SldLot int,
                  @WQtdAccPra int,
                  @WQtdAccDep int,
                  @WQtdMovTot int,
                  @WQtdMovPra int,
                  @WQtdMovDep int,
                  @WQtdDif int,
                  @WQtdAccDif int,
                  @WCodPrdAnt int,
                  @WCodMve int,
                  @WNumAcerto int,
                  @WFlgEstFis bit,
                  @QtdEntPra int, 
                  @QtdEntDep int, 
                  @QtdSaiPra int, 
                  @QtdSaiDep int,
                  @QtdSldAntPra int,
                  @QtdSldAntDep int

          -- antes de processar tenta corrigir algum estoque inconsistente em PRXES
          Set @CodPrd = 0
          while Exists(Select 1
                         From BALAN b
                              inner join PRXES p on b.Cod_Estabe = p.Cod_Estabe and b.Cod_Produto = p.Cod_Produt
                        Where b.Cod_Estabe = @CodEstabe 
                          And b.Contagem = 1
                          And b.Cod_Produto > @CodPrd
                          And p.Qtd_Fisico <> dbo.FN_EstoqueFisicoPrdLote(p.Cod_Estabe,p.Cod_Produt,'TODOS'))
            begin
              Select top 1 @CodPrd = b.Cod_Produto 
                From BALAN b
                     inner join PRXES p on b.Cod_Estabe = p.Cod_Estabe and b.Cod_Produto = p.Cod_Produt
               Where b.Cod_Estabe = @CodEstabe 
                 And b.Contagem = 1
                 And b.Cod_Produto > @CodPrd
                 And p.Qtd_Fisico <> dbo.FN_EstoqueFisicoPrdLote(p.Cod_Estabe,p.Cod_Produt,'TODOS')
               Order by Cod_Produto

              Exec PR_CorrigeEstoqueProdut @CodEstabe, @CodPrd
              if @@error <> 0
                begin
                  Rollback Transaction
                  Return
                end
            end


          -- verifica se for implantacao de estoque (fiscal)
          Set @WFlgEstFis = 0  

          if not Exists(Select 1 From PRXES Where Cod_Estabe = @CodEstabe And Qtd_Dispon > 0)
            Set @WFlgEstFis = 1  -- estoque fiscal
         
          if (@WFlgEstFis = 0) and ((Select IsNull(FlgAlerta,0) From PARAM Where Cod_Estabe = @CodEstabe) = 1)
            Set @WFlgEstFis = 1  -- estoque fiscal

          -- sequencial inventario
          if not Exists(Select 1 From NUMER Where Campo = 'Inventario')
            Insert Into NUMER (Campo, Valor)
                       Values ('Inventario', 0)
                       
          Update NUMER 
             Set Valor = ISNULL((Select MAX(Num_SeqBal) From BALCB Where Cod_Estabe = @CodEstabe),0)
           Where Campo = 'Inventario'  
             And Valor <> ISNULL((Select MAX(Num_SeqBal) From BALCB Where Cod_Estabe = @CodEstabe),0)

          EXEC PR_ProxNumero 'Inventario', @WNumSeqBal output
          if @@error <> 0
            begin
              Rollback Transaction
              Return
            end

          -- cria tabela temporaria para acumular acertos
          IF OBJECT_ID('TempDB.dbo.#TMP_ACERT') IS NOT NULL
            DROP TABLE #TMP_ACERT

          CREATE TABLE #TMP_ACERT
               (Cod_Produt int  NOT NULL,
                Cod_Lote varchar(20)  NOT NULL,
                Dat_Vencim smalldatetime,
                Dat_Fabric smalldatetime,
                Qtd_EntPra int,
                Qtd_EntDep int,
                Qtd_SaiPra int,
                Qtd_SaiDep int)

          ALTER TABLE #TMP_ACERT ADD CONSTRAINT PK_TMP_ACERT PRIMARY KEY CLUSTERED 
               (Cod_Produt,
                Cod_Lote) ON [PRIMARY]

          -- atualiza tab. de produtos
          Update pr
             Set pr.Qtd_SldAntBal = p.Qtd_Fisico,
                 pr.Qtd_SldPraAntBal = IsNull(lt.QtdFisPraPck,0)+IsNull(dp.QtdFisPraDep,0),
                 pr.Num_SeqBal = @WNumSeqBal
            From PRXES p Inner Join 
                 PRODU pr on p.Cod_Produt = pr.Codigo Left Join
                 (Select Cod_Estabe, Cod_Produt, QtdFisPraPck = sum(IsNull(Qtd_FisPra,0)) 
                    From PRLOT
                   Where Cod_Estabe = @CodEstabe And IsNull(Qtd_FisPra,0) > 0 
                   Group by Cod_Estabe, Cod_Produt) lt on p.Cod_Estabe = lt.Cod_Estabe and p.Cod_Produt = lt.Cod_Produt Left Join
                 (Select Cod_Estabe, Cod_Produt, QtdFisPraDep = sum(IsNull(Qtd_FisPra,0)) 
                    From PRLTL
                   Where Cod_Estabe = @CodEstabe And IsNull(Qtd_FisPra,0) > 0 
                   Group by Cod_Estabe, Cod_Produt) dp on p.Cod_Estabe = dp.Cod_Estabe and p.Cod_Produt = dp.Cod_Produt
          Where p.Cod_Estabe = @CodEstabe      
            And Exists(Select 1 From BALAN b 
                        Where b.Cod_Estabe = p.Cod_Estabe and b.Cod_Produto = p.Cod_Produt And b.Contagem = 1)
                  
           -- se for o caso transfere estoques
           if @WFlgEstFis = 1
             begin
               Declare PRLOT Cursor Local Fast_Forward For 

                 Select lt.Cod_Produt, lt.Cod_Lote, lt.Dat_Vencim, lt.Dat_Fabric
                   From PRLOT lt
                  Where lt.Cod_Estabe = @CodEstabe 
                    And lt.Cod_Dep = @WCodDep
                    And Exists(Select 1 From BALAN ba 
                                Where ba.Cod_Estabe = lt.Cod_Estabe and ba.Cod_Produto = lt.Cod_Produt And ba.Contagem = 1)
                    And IsNull(lt.Qtd_SldDep,0) > 0
                      
               Open PRLOT
               Fetch Next From PRLOT Into @CodPrd, @CodLot, @DatVct, @DatFab
               While @@FETCH_STATUS = 0
                 begin
                   Set @SldDep = IsNull((Select IsNull(Qtd_SldDep,0) From PRLOT 
                                          Where Cod_Estabe = @CodEstabe And Cod_Dep = @WCodDep 
                                            And Cod_Produt = @CodPrd And Cod_Lote = @CodLot),0)
                 
                   if @SldDep > 0 
                     begin
                       -- dar saida do lote
                       EXEC PR_ProxNumero 'Acerto', @WNumAcerto output
                       if @@error <> 0
                         begin
                           Rollback Transaction
                           Return
                         end
                
                       Insert into ACERT (Cod_Estabe, Numero, Dat_Movimento, Cod_Produto, Cod_Lote, Dat_Vencimento, Dat_Fabric, Cod_Dep, 
                                          Qtd_Acerto, Qtd_AceDep, Cod_TipMov, Num_SeqBal, Flg_NotFis, Historico, Usuario, Transacao)
                                 Values  (@CodEstabe, @WNumAcerto, @Date, @CodPrd, @CodLot, @DatVct, @DatFab, @WCodDep,
                                          0, @SldDep, @CodMveSai, @WNumSeqBal, 0, 'BALANCO', @Usuario, GetDate())
                       if @@error <> 0
                         begin
                           Rollback Transaction
                           Return
                         end
                         
                       if not Exists(Select 1
                                       From #TMP_ACERT
                                      Where Cod_Produt = @CodPrd
                                        And Cod_Lote = @CodLot)
                         Insert Into #TMP_ACERT (Cod_Produt, Cod_Lote, Dat_Vencim, Dat_Fabric, Qtd_EntPra, Qtd_EntDep, Qtd_SaiPra, Qtd_SaiDep)
                                         Values (@CodPrd,    @CodLot,  @DatVct,    @DatFab,    0,          0,          0,    0)

                       Update #TMP_ACERT
                          Set Qtd_SaiPra = Qtd_SaiPra + 0,
                              Qtd_SaiDep = Qtd_SaiDep + @SldDep
                        Where Cod_Produt = @CodPrd
                          And Cod_Lote = @CodLot
                         
                       -- dar entrada do lote
                       EXEC PR_ProxNumero 'Acerto', @WNumAcerto output
                       if @@error <> 0
                         begin
                           Rollback Transaction
                           Return
                         end

                       Insert into ACERT (Cod_Estabe, Numero, Dat_Movimento, Cod_Produto, Cod_Lote, Dat_Vencimento, Dat_Fabric, Cod_Dep, 
                                          Qtd_Acerto, Qtd_AceDep, Cod_TipMov, Num_SeqBal, Flg_NotFis, Historico, Usuario, Transacao)
                                 Values  (@CodEstabe, @WNumAcerto, @Date, @CodPrd, @CodLot, @DatVct, @DatFab, @WCodDep,
                                          @SldDep, 0, @CodMveEnt, @WNumSeqBal, 0, 'BALANCO', @Usuario, GetDate())
                       if @@error <> 0
                         begin
                           Rollback Transaction
                           Return
                         end

                       if not Exists(Select 1
                                       From #TMP_ACERT
                                      Where Cod_Produt = @CodPrd
                                        And Cod_Lote = @CodLot)
                       Insert Into #TMP_ACERT (Cod_Produt, Cod_Lote, Dat_Vencim, Dat_Fabric, Qtd_EntPra, Qtd_EntDep, Qtd_SaiPra, Qtd_SaiDep)
                                       Values (@CodPrd,    @CodLot,  @DatVct,    @DatFab,    0,          0,          0,    0)
                                         
                       Update #TMP_ACERT
                          Set Qtd_EntPra = Qtd_EntPra + @SldDep,
                              Qtd_EntDep = Qtd_EntDep + 0
                        Where Cod_Produt = @CodPrd
                          And Cod_Lote = @CodLot

                     end

                   Fetch Next From PRLOT Into @CodPrd, @CodLot, @DatVct, @DatFab
                 end
               
               Close PRLOT
               Deallocate PRLOT
             end

          -- insere registro em BALCB
          Set @WNumCtg = (Select Max(Contagem) From BALAN Where Cod_Estabe = @CodEstabe)

          Insert Into BALCB (Cod_Estabe, Num_SeqBal, Tip_Balanc, Cod_Dep, Cod_CtrLoc, Qtd_Contag, Dat_Balanc, Flg_Proces, Usuario, Transacao)          
                     Values (@CodEstabe, @WNumSeqBal, 'P', @WCodDep, 'FRA', @WNumCtg , @Date, 0, 'SISTEMA', @Now)
          if @@error <> 0
            begin
              Rollback Transaction
              Return
            end

          -- inclui itens de BALAN com lotes inexistentes em PRLOT
          Insert into PRLOT (Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote, Dat_Vencim, Dat_Fabric, Qtd_FisPra, Qtd_SolPra, Qtd_FisDep, Qtd_SolDep)
            Select distinct @CodEstabe, @WCodDep, b.Cod_Produto, b.Cod_Lote, b.Dat_Vencim, b.Dat_Fabric, 0, 0, 0, 0
              From BALAN b 
             Where b.Cod_Estabe = @CodEstabe
               and b.Contagem = 1
               And not Exists(Select 1 From PRLOT l
                               Where b.Cod_Estabe = l.Cod_Estabe and l.Cod_Dep = @WCodDep 
                                 and b.Cod_Produto = l.Cod_Produt And b.Cod_Lote = l.Cod_Lote)
          if (@@error <> 0)
            begin
              Rollback Transaction
              Return
            end

----------------------------------------------------------------------------------------------------------------------------
          -- remaneja lotes com saldo de PRLOT nao inventariados em BALAN p/ lotes existentes em BALAN com menor saldo em PRLOT
          Declare PRLOT_Ori Cursor Local Fast_Forward For 

            Select l.Cod_Produt, l.Cod_Lote, l.Dat_Vencim, l.Dat_Fabric, Isnull(l.Qtd_SldPra,0), Isnull(l.Qtd_SldDep,0)
              From PRLOT l Left Join
                   (Select Cod_Estabe, Cod_Produto, Cod_Lote, QtdBal = SUM(Quantidade)
                      From BALAN
                     Where Cod_Estabe = @CodEstabe 
                       and Contagem = 1
                     Group by Cod_Estabe, Cod_Produto, Cod_Lote) b on l.Cod_Estabe = b.Cod_Estabe 
                                                                  and l.Cod_Produt = b.Cod_Produto and l.Cod_Lote = b.Cod_Lote 
              Where l.Cod_Estabe = @CodEstabe 
                and l.Cod_Dep = @WCodDep
                And l.Qtd_Saldo > 0
                And Exists(Select 1 From BALAN b 
                            Where b.Cod_Estabe = l.Cod_Estabe and b.Cod_Produto = l.Cod_Produt And b.Contagem = 1)
                and b.Cod_Produto is null
              Order by l.Cod_Produt, l.Cod_Lote

          Open PRLOT_Ori
          Fetch Next From PRLOT_Ori Into @CodPrd, @CodLot, @DatVct, @DatFab, @SldPra, @SldDep
          While @@FETCH_STATUS = 0
            begin
              -- dar saida em PRLOT
              EXEC PR_ProxNumero 'Acerto', @WNumAcerto output
              if @@error <> 0
                begin
                  Rollback Transaction
                  Return
                end
                
              Insert into ACERT (Cod_Estabe, Numero, Dat_Movimento, Cod_Produto, Cod_Lote, Dat_Vencimento, Dat_Fabric, Cod_Dep,
                                 Qtd_Acerto, Qtd_AceDep, Cod_TipMov, Num_SeqBal, Flg_NotFis, Historico, Usuario, Transacao)
                        Values  (@CodEstabe, @WNumAcerto, @Date, @CodPrd, @CodLot, @DatVct, @DatFab, @WCodDep,
                                 @SldPra, @SldDep, @CodMveSai, @WNumSeqBal, 0, 'BALANCO', @Usuario, GetDate())
              if @@error <> 0
                begin
                  Rollback Transaction
                  Return
                end

              if not Exists(Select 1
                              From #TMP_ACERT
                             Where Cod_Produt = @CodPrd
                               And Cod_Lote = @CodLot)
                Insert Into #TMP_ACERT (Cod_Produt, Cod_Lote, Dat_Vencim, Dat_Fabric, Qtd_EntPra, Qtd_EntDep, Qtd_SaiPra, Qtd_SaiDep)
                                Values (@CodPrd,    @CodLot,  @DatVct,    @DatFab,    0,          0,          0,    0)

              Update #TMP_ACERT
                 Set Qtd_SaiPra = Qtd_SaiPra + @SldPra,
                     Qtd_SaiDep = Qtd_SaiDep + @SldDep
               Where Cod_Produt = @CodPrd
                 And Cod_Lote = @CodLot

              -- dar entrada nos lotes do inventario se houver quantidade > 0 do produto
              if not Exists(Select 1
                              From BALAN
                             Where Cod_Estabe = @CodEstabe 
                               and Cod_Produto = @CodPrd
                               And Contagem = 1
                               And Quantidade > 0)
                begin
                  -- nao remaneja lotes pois não existe estoque contado
                  Set @WQtdAccPra = 0
                  Set @WQtdAccDep = 0
                end
              else
                begin
                  -- dar entrada em outro(s) lote(s) inventariado(s) do produto 
                  Set @WQtdAccPra = @SldPra
                  Set @WQtdAccDep = @SldDep

                  Declare PRLOT_Des Cursor Local Fast_Forward For 

                    Select l.Cod_Lote, l.Dat_Vencim, l.Dat_Fabric, IsNull(l.Qtd_Saldo,0), b.QtdBal
                      From PRLOT l Inner Join
                           (Select Cod_Estabe, Cod_Produto, Cod_Lote, QtdBal = SUM(Quantidade)
                              From BALAN
                             Where Cod_Estabe = @CodEstabe 
                               and Contagem = 1
                             Group by Cod_Estabe, Cod_Produto, Cod_Lote) b on l.Cod_Estabe = b.Cod_Estabe and l.Cod_Produt = b.Cod_Produto and l.Cod_Lote = b.Cod_Lote 
                      Where l.Cod_Estabe = @CodEstabe
                        and l.Cod_Dep = @WCodDep
                        And l.Cod_Produt = @CodPrd
                      order by l.Qtd_Saldo
                      
                  Open PRLOT_Des
                  Fetch Next From PRLOT_Des Into @CodLotDes, @DatVctDes, @DatFabDes, @SldLot, @QtdBal
                  While (@@FETCH_STATUS = 0) and ((@WQtdAccPra+@WQtdAccDep) > 0)
                    begin
                      if @SldLot < @QtdBal
                        begin
                          Set @WQtdDif = @QtdBal - @SldLot
                          Set @WQtdMovPra = 0
                          Set @WQtdMovDep = 0

                          -- estoque pra
                          if (@WQtdDif > 0) and (@WQtdAccPra > 0)
                            begin
                              Set @WQtdMovPra = Case
                                                  When @WQtdAccPra < @WQtdDif then @WQtdAccPra
                                                  Else @WQtdDif
                                                End
                              Set @WQtdDif = @WQtdDif - @WQtdMovPra
                              Set @WQtdAccPra = @WQtdAccPra - @WQtdMovPra
                            end

                          -- estoque dep
                          if (@WQtdDif > 0) and (@WQtdAccDep > 0)
                            begin
                              Set @WQtdMovDep = Case
                                                  When @WQtdAccDep < @WQtdDif then @WQtdAccDep
                                                  Else @WQtdDif
                                                End
                              Set @WQtdDif = @WQtdDif - @WQtdMovDep
                              Set @WQtdAccDep = @WQtdAccDep - @WQtdMovDep
                            end

                          -- dar entrada no lote
                          if (@WQtdMovPra+@WQtdMovDep) > 0
                            begin
                              EXEC PR_ProxNumero 'Acerto', @WNumAcerto output
                              if @@error <> 0
                                begin
                                  Rollback Transaction
                                  Return
                                end

                              if @WFlgEstFis = 1
                                begin
                                  Set @WQtdMovPra = @WQtdMovPra + @WQtdMovDep
                                  Set @WQtdMovDep = 0
                                end
                            
                              Insert into ACERT (Cod_Estabe, Numero, Dat_Movimento, Cod_Produto, Cod_Lote, Dat_Vencimento, Dat_Fabric, Cod_Dep,
                                                 Qtd_Acerto, Qtd_AceDep, Cod_TipMov, Num_SeqBal, Flg_NotFis, Historico, Usuario, Transacao)
                                        Values  (@CodEstabe, @WNumAcerto, @Date, @CodPrd, @CodLotDes, @DatVctDes, @DatFabDes, @WCodDep, 
                                                 @WQtdMovPra, @WQtdMovDep, @CodMveEnt, @WNumSeqBal, 0, 'BALANCO', @Usuario, GetDate())
                              if @@error <> 0
                                begin
                                  Rollback Transaction
                                  Return
                                end
                            
                              if not Exists(Select 1
                                              From #TMP_ACERT
                                             Where Cod_Produt = @CodPrd
                                               And Cod_Lote = @CodLotDes)
                                Insert Into #TMP_ACERT (Cod_Produt, Cod_Lote,   Dat_Vencim, Dat_Fabric, Qtd_EntPra, Qtd_EntDep, Qtd_SaiPra, Qtd_SaiDep)
                                                Values (@CodPrd,    @CodLotDes, @DatVctDes, @DatFabDes, 0,       0,          0,    0)

                              Update #TMP_ACERT
                                 Set Qtd_EntPra = Qtd_EntPra + @WQtdMovPra,
                                     Qtd_EntDep = Qtd_EntDep + @WQtdMovDep
                               Where Cod_Produt = @CodPrd
                                 And Cod_Lote = @CodLotDes
                            
                            end
                        end  -- if @SldLot < @QtdBal

                      Fetch Next From PRLOT_Des Into @CodLotDes, @DatVctDes, @DatFabDes, @SldLot, @QtdBal
                    end
                  Close PRLOT_Des
                  Deallocate PRLOT_Des

                  -- se ainda houver saldo de ajuste, acrescenta no ultimo lote selecionado
                  if (@WQtdAccPra+@WQtdAccDep) > 0
                    begin
                      EXEC PR_ProxNumero 'Acerto', @WNumAcerto output
                      if @@error <> 0
                        begin
                          Rollback Transaction
                          Return
                        end

                      if @WFlgEstFis = 1
                        begin
                          Set @WQtdAccPra = @WQtdAccPra + @WQtdAccDep
                          Set @WQtdAccDep = 0
                        end
                    
                      Insert into ACERT (Cod_Estabe, Numero, Dat_Movimento, Cod_Produto, Cod_Lote, Dat_Vencimento, Dat_Fabric, Cod_Dep,
                                         Qtd_Acerto, Qtd_AceDep, Cod_TipMov, Num_SeqBal, Flg_NotFis, Historico, Usuario, Transacao)
                                Values  (@CodEstabe, @WNumAcerto, @Date, @CodPrd, @CodLotDes, @DatVctDes, @DatFabDes, @WCodDep,
                                         @WQtdAccPra, @WQtdAccDep, @CodMveEnt, @WNumSeqBal, 0, 'BALANCO', @Usuario, GetDate())
                      if @@error <> 0
                        begin
                          Rollback Transaction
                          Return
                        end
                    
                      if not Exists(Select 1
                                      From #TMP_ACERT
                                     Where Cod_Produt = @CodPrd
                                       And Cod_Lote = @CodLotDes)
                        Insert Into #TMP_ACERT (Cod_Produt, Cod_Lote,   Dat_Vencim, Dat_Fabric, Qtd_EntPra, Qtd_EntDep, Qtd_SaiPra, Qtd_SaiDep)
                                        Values (@CodPrd,    @CodLotDes, @DatVctDes, @DatFabDes, 0,       0,          0,    0)

                      Update #TMP_ACERT
                         Set Qtd_EntPra = Qtd_EntPra + @WQtdAccPra,
                             Qtd_EntDep = Qtd_EntDep + @WQtdAccDep
                       Where Cod_Produt = @CodPrd
                         And Cod_Lote = @CodLotDes

                    end  -- if (@WQtdAccPra+@WQtdAccDep) > 0
                    
                end
                
              Fetch Next From PRLOT_Ori Into @CodPrd, @CodLot, @DatVct, @DatFab, @SldPra, @SldDep
            end
          Close PRLOT_Ori
          Deallocate PRLOT_Ori

-----------------------------------------------------------------------------------------------------
          -- iguala estoque entre PRLOT e BALAN
          Declare PRLOT_Cr Cursor Local Fast_Forward For 
   
            Select l.Cod_Produt, l.Cod_Lote, l.Dat_Vencim, l.Dat_Fabric, Isnull(l.Qtd_SldPra,0), Isnull(l.Qtd_SldDep,0), b.QtdBal
              From PRLOT l Inner Join
                   (Select Cod_Estabe, Cod_Produto, Cod_Lote, QtdBal = SUM(Quantidade)
                      From BALAN
                     Where Cod_Estabe = @CodEstabe 
                       and Contagem = 1
                     Group by Cod_Estabe, Cod_Produto, Cod_Lote) b on l.Cod_Estabe = b.Cod_Estabe 
                                                                  and l.Cod_Produt = b.Cod_Produto and l.Cod_Lote = b.Cod_Lote 
              Where l.Cod_Estabe = @CodEstabe
                and l.Cod_Dep = @WCodDep
              Order by l.Cod_Produt, l.Dat_Vencim

          Open PRLOT_Cr
          Fetch Next From PRLOT_Cr Into @CodPrd, @CodLot, @DatVct, @DatFab, @SldPra, @SldDep, @QtdBal
          While @@FETCH_STATUS = 0
            begin
              Set @WCodPrdAnt = @CodPrd
              Set @WQtdAccPra = 0

              while (@WCodPrdAnt = @CodPrd) and (@@FETCH_STATUS = 0)
                begin
                  Set @WQtdDif = @QtdBal - (@SldPra+@SldDep)

                  if @WQtdDif < 0  -- diminuir de PRLOT
                    begin                     
                      Set @WQtdAccDif = @WQtdDif * (-1)

                      while @WQtdAccDif > 0
                        begin
                          Set @WQtdMovPra = 0
                          Set @WQtdMovDep = 0

                          -- primeiro tenta retirar do estoque dep
                          if @SldDep > 0
                            begin
                              Set @WQtdMovDep = Case 
                                                  When @SldDep < @WQtdAccDif then @SldDep
                                                  Else @WQtdAccDif
                                                End
				              Set @WQtdAccDif = @WQtdAccDif - @WQtdMovDep
                            end

                          -- se preciso tenta retirar do estoque pra
                          if (@WQtdAccDif > 0) and (@SldPra > 0)
                            begin
                              Set @WQtdMovPra = Case 
                                                  When @SldPra < @WQtdAccDif then @SldPra
                                                  Else @WQtdAccDif
                                                End
                              Set @WQtdAccDif = @WQtdAccDif - @WQtdMovPra

                              -- acumular o estoque oficial retirado p/ acrescentar em outro lote
                              Set @WQtdAccPra = @WQtdAccPra + @WQtdMovPra
                            end

                          -- fazer o acerto
                          if (@WQtdMovPra+@WQtdMovDep) > 0
                            begin
                              EXEC PR_ProxNumero 'Acerto', @WNumAcerto output
                              if @@error <> 0
                                begin
                                  Rollback Transaction
                                  Return
                                end
                                
                              Insert into ACERT (Cod_Estabe, Numero, Dat_Movimento, Cod_Produto, Cod_Lote, Dat_Vencimento, Dat_Fabric, Cod_Dep, 
                                                 Qtd_Acerto, Qtd_AceDep, Cod_TipMov, Num_SeqBal, Flg_NotFis, Historico, Usuario, Transacao)
                                        Values  (@CodEstabe, @WNumAcerto, @Date, @CodPrd, @CodLot, @DatVct, @DatFab, @WCodDep,
                                                 @WQtdMovPra, @WQtdMovDep, @CodMveSai, @WNumSeqBal, 0, 'BALANCO', @Usuario, GetDate())
                              if @@error <> 0
                                begin
                                  Rollback Transaction
                                  Return
                               end
                               
                              if not Exists(Select 1
                                              From #TMP_ACERT
                                             Where Cod_Produt = @CodPrd
                                               And Cod_Lote = @CodLot)
                                Insert Into #TMP_ACERT (Cod_Produt, Cod_Lote, Dat_Vencim, Dat_Fabric, Qtd_EntPra, Qtd_EntDep, Qtd_SaiPra, Qtd_SaiDep)
                                                Values (@CodPrd,    @CodLot,  @DatVct,    @DatFab,    0,          0,          0,    0)

                              Update #TMP_ACERT
                                 Set Qtd_SaiPra = Qtd_SaiPra + @WQtdMovPra,
                                     Qtd_SaiDep = Qtd_SaiDep + @WQtdMovDep
                               Where Cod_Produt = @CodPrd
                                 And Cod_Lote = @CodLot
                            end
                          else
                            begin
                              RAISERROR('Estoque Insuficiente em PRLOT para processamento do Balanço',16,1)
                              Rollback Transaction
                              Return
                            end

                        end  -- while @WQtdAccDif > 0
                    end  -- if @WQtdDif < 0

                  if @WQtdDif > 0  -- acrescentar em PRLOT
                    begin                     
                      Set @WQtdAccDif = @WQtdDif

                      while @WQtdAccDif > 0
                        begin
                          Set @WQtdMovPra = 0
                          Set @WQtdMovDep = 0

                          -- primeiro ver se existe estoque pra pendente de outros lotes
                          if @WQtdAccPra > 0
                            begin
                              Set @WQtdMovPra = Case 
                                                  when @WQtdAccPra < @WQtdAccDif then @WQtdAccPra
                                                  else @WQtdAccDif 
                                                End
                              Set @WQtdAccPra = @WQtdAccPra - @WQtdMovPra
                              Set @WQtdAccDif = @WQtdAccDif - @WQtdMovPra
                            end

                          -- acrescenta em estoque dep
                          if @WQtdAccDif > 0
                            begin
                                Set @WQtdMovDep = @WQtdAccDif
                                Set @WQtdAccDif = @WQtdAccDif - @WQtdMovDep
                            end

                          -- fazer o acerto
                          if (@WQtdMovPra+@WQtdMovDep) > 0
                            begin
                              EXEC PR_ProxNumero 'Acerto', @WNumAcerto output
                              if @@error <> 0
                                begin
                                  Rollback Transaction
                                  Return
                                end

                              if @WFlgEstFis = 1
                                begin
                                  Set @WQtdMovPra = @WQtdMovPra + @WQtdMovDep
                                  Set @WQtdMovDep = 0
                                end
                                
                              Insert into ACERT (Cod_Estabe, Numero, Dat_Movimento, Cod_Produto, Cod_Lote, Dat_Vencimento, Dat_Fabric, Cod_Dep,
                                                 Qtd_Acerto, Qtd_AceDep, Cod_TipMov, Num_SeqBal, Flg_NotFis, Historico, Usuario, Transacao)
                                        Values  (@CodEstabe, @WNumAcerto, @Date, @CodPrd, @CodLot, @DatVct, @DatFab, @WCodDep,
                                                 @WQtdMovPra, @WQtdMovDep, @CodMveEnt, @WNumSeqBal, 0, 'BALANCO', @Usuario, GetDate())
                              if @@error <> 0
                                begin
                                  Rollback Transaction
                                  Return
                               end
                               
                              if not Exists(Select 1
                                              From #TMP_ACERT
                                             Where Cod_Produt = @CodPrd
                                               And Cod_Lote = @CodLot)
                                Insert Into #TMP_ACERT (Cod_Produt, Cod_Lote, Dat_Vencim, Dat_Fabric, Qtd_EntPra, Qtd_EntDep, Qtd_SaiPra, Qtd_SaiDep)
                                                Values (@CodPrd,    @CodLot,  @DatVct,    @DatFab,    0,          0,          0,    0)

                              Update #TMP_ACERT
                                 Set Qtd_EntPra = Qtd_EntPra + @WQtdMovPra,
                                     Qtd_EntDep = Qtd_EntDep + @WQtdMovDep
                               Where Cod_Produt = @CodPrd
                                 And Cod_Lote = @CodLot
                               
                            end

                        end  -- while @WQtdAccDif > 0
                    end  -- if @WQtdDif > 0

                  Fetch Next From PRLOT_Cr Into @CodPrd, @CodLot, @DatVct, @DatFab, @SldPra, @SldDep, @QtdBal
                end  -- while (@WCodPrdAnt = @CodPrd) and (@@FETCH_STATUS = 0)

            end -- While @@FETCH_STATUS = 0

          Close PRLOT_Cr
          Deallocate PRLOT_Cr

         -- atualiza tab. de produtos
          Update pr
             Set pr.Dat_PrcUltBal = @Date,
                 pr.Qtd_SldPosBal = p.Qtd_Fisico,
                 pr.Qtd_SldPraPosBal = IsNull(lt.QtdFisPraPck,0)+IsNull(dp.QtdFisPraDep,0)
            From PRXES p Inner Join 
                 PRODU pr on p.Cod_Produt = pr.Codigo Left Join
                 (Select Cod_Estabe, Cod_Produt, QtdFisPraPck = sum(IsNull(Qtd_FisPra,0)) 
                    From PRLOT
                   Where Cod_Estabe = @CodEstabe And IsNull(Qtd_FisPra,0) > 0 
                  Group by Cod_Estabe, Cod_Produt) lt on p.Cod_Estabe = lt.Cod_Estabe and p.Cod_Produt = lt.Cod_Produt Left Join
                 (Select Cod_Estabe, Cod_Produt, QtdFisPraDep = sum(IsNull(Qtd_FisPra,0)) 
                    From PRLTL
                   Where Cod_Estabe = @CodEstabe And IsNull(Qtd_FisPra,0) > 0 
                   Group by Cod_Estabe, Cod_Produt) dp on p.Cod_Estabe = dp.Cod_Estabe and p.Cod_Produt = dp.Cod_Produt
           Where p.Cod_Estabe = @CodEstabe 
             And Exists(Select 1 From BALAN b 
                         Where b.Cod_Estabe = p.Cod_Estabe and b.Cod_Produto = p.Cod_Produt And b.Contagem = 1)
             And pr.Num_SeqBal = @WNumSeqBal      
          
         -- atualiza vencimentos dos lotes
          Update lt
             Set lt.Dat_Vencim = b.Dat_Vencim
            From PRLOT lt, BALAN b
           Where lt.Cod_Estabe = b.Cod_Estabe 
             And lt.Cod_Produt = b.Cod_Produto
             and lt.Cod_Lote = b.Cod_Lote
             and b.Cod_Estabe = @CodEstabe 
             and b.Contagem = 1
             and not b.Dat_Vencim is null

         -- atualiza fabricacao dos lotes
          Update lt
             Set lt.Dat_Fabric = b.Dat_Fabric
            From PRLOT lt, BALAN b
           Where lt.Cod_Estabe = b.Cod_Estabe 
             And lt.Cod_Produt = b.Cod_Produto
             and lt.Cod_Lote = b.Cod_Lote
             and b.Cod_Estabe = @CodEstabe
             and b.Contagem = 1
             and not b.Dat_Fabric is null
 
------------------------------------------------------------------------------------------
          -- iguala estoque entre PRXES e PRLOT
         -- dá entrada/saída em PRXES em estoques divergentes
         if Exists(Select 1
                     From BALAN b
                          inner join PRXES p on b.Cod_Estabe = p.Cod_Estabe and b.Cod_Produto = p.Cod_Produt
                    Where b.Cod_Estabe = @CodEstabe 
                      And b.Contagem = 1
                      And p.Qtd_Fisico <> dbo.FN_EstoqueFisicoPrdLote(p.Cod_Estabe,p.Cod_Produt,'TODOS'))

           begin
             Declare PRSLD_Cr Cursor Local Fast_Forward For 
	    
               Select distinct b.Cod_Produto,
			          QtdDif =  p.Qtd_Fisico - dbo.FN_EstoqueFisicoPrdLote(p.Cod_Estabe,p.Cod_Produt,'TODOS')
                 From BALAN b
                      inner join PRXES p on b.Cod_Estabe = p.Cod_Estabe and b.Cod_Produto = p.Cod_Produt
                Where b.Cod_Estabe = @CodEstabe 
                  And b.Contagem = 1
                  And p.Qtd_Fisico <> dbo.FN_EstoqueFisicoPrdLote(p.Cod_Estabe,p.Cod_Produt,'TODOS')	    

             Open PRSLD_Cr
             Fetch Next From PRSLD_Cr Into @CodPrd, @WQtdDif
             While @@FETCH_STATUS = 0
               begin
                 -- pega o ultimo movimento do produto
                 Select top 1 @QtdSldAntPra = IsNull(Qtd_SldPra,0), 
                              @QtdSldAntDep = IsNull(Qtd_SldDep,0)
                   From PRSLD 
                  Where Cod_Estabe = @CodEstabe
                    and Cod_Produt = @CodPrd 
                    and Dat_Movime <= @DatPrc
                  Order By Dat_Movime desc

                 if not Exists(Select Cod_Produt from PRSLD 
                                Where Cod_Estabe = @CodEstabe and Cod_Produt = @CodPrd and Dat_Movime = @DatPrc)
                   begin
                     Insert into PRSLD (Cod_Estabe, Cod_Produt, Dat_Movime, Qtd_SldPra,    Qtd_SldDep) 
                                Values (@CodEstabe, @CodPrd,    @DatPrc,    @QtdSldAntPra, @QtdSldAntDep) 
                     if (@@error <> 0)
                       begin
                         Rollback Transaction
                         Return
                       end
                   end

                 -- dá saída em PRXES
                 if @WQtdDif > 0
                   begin
                     -- ver se pode retirar de entradas "manuais"
                     Declare @WQtdExcEnt int = 0
                     Select @WQtdExcEnt = Case
                                            When (IsNull(Qtd_InfEntInv,0) > 0) and (Qtd_EntOut >= Qtd_InfEntInv) then
                                              Case 
                                                When IsNull(Qtd_InfEntInv,0) > @WQtdDif then @WQtdDif 
                                                Else Qtd_InfEntInv 
                                              End
                                            Else  0
                                          End
                       From PRSLD
                      Where Cod_Estabe = @CodEstabe
                        and Cod_Produt = @CodPrd
                        and Dat_Movime = @DatPrc

                     if @WQtdExcEnt > 0
                       begin
                         Update PRSLD
                            Set Qtd_EntOut = Qtd_EntOut - @WQtdExcEnt,
                                Qtd_InfEntInv = Qtd_InfEntInv - @WQtdExcEnt,
                                @WQtdDif = @WQtdDif - @WQtdExcEnt
                          Where Cod_Estabe = @CodEstabe
                            and Cod_Produt = @CodPrd
                            and Dat_Movime = @DatPrc
                       end


                     -- registra qtd ajustada "manualmente" em PRXES devido inconsistência 
                     if @WQtdDif > 0
                       begin
                         Update PRSLD 
                            Set Qtd_SaiOut = Qtd_SaiOut + @WQtdDif,
                                Qtd_InfSaiInv = IsNull(Qtd_InfSaiInv,0) + @WQtdDif
                          Where Cod_Estabe = @CodEstabe
                            and Cod_Produt = @CodPrd
                            and Dat_Movime = @DatPrc
                       end

                     -- saldos atuais
                     Select @SldPra = Qtd_SldPra, 
                            @SldDep = Qtd_SldDep
                       From PRSLD
                      Where Cod_Estabe = @CodEstabe
                        and Cod_Produt = @CodPrd
                        and Dat_Movime = @DatPrc
		         
                     Set @WQtdMovDep = 0
                     Set @WQtdMovPra = 0
		         
                     -- repões qtd subtraídas de outras entradas
                     Set @WQtdDif = @WQtdDif + @WQtdExcEnt

                     if (@SldDep > 0) and (@WQtdDif > 0)
                       begin
                         Set @WQtdMovDep = Case 
                                             when @SldDep < @WQtdDif then @SldDep 
                                             else @WQtdDif 
                                           End
                         Set @WQtdDif = @WQtdDif - @WQtdMovDep
                       end
                    
                     if (@SldPra > 0) and (@WQtdDif > 0)
                       begin
                         Set @WQtdMovPra = Case 
                                             when @SldPra < @WQtdDif then @SldPra 
                                             else @WQtdDif 
                                           End
                         Set @WQtdDif = @WQtdDif - @WQtdMovPra
                       end

                     Update PRSLD 
                        Set Qtd_SldDep = Qtd_SldDep - @WQtdMovDep,
                            Qtd_SldPra = Qtd_SldPra - @WQtdMovPra
                      Where Cod_Estabe = @CodEstabe 
                        and Cod_Produt = @CodPrd
                        and Dat_Movime = @DatPrc
		         
                     Update PRXES
                        Set Qtd_Fisico = Qtd_Fisico - @WQtdMovDep - @WQtdMovPra
                      Where Cod_Estabe = @CodEstabe 
                        And Cod_Produt = @CodPrd

                   end  -- if @WQtdDif > 0

                 -- dá entrada em PRXES
                 if @WQtdDif < 0
                   begin
                     Set @WQtdDif = Abs(@WQtdDif)  

                     -- ver se pode retirar de saidas "manuais"
                     Declare @WQtdExcSai int = 0
                     Select @WQtdExcSai = Case
                                            When (IsNull(Qtd_InfSaiInv,0) > 0) and (Qtd_SaiOut >= Qtd_InfSaiInv) then
                                              Case 
                                                When IsNull(Qtd_InfSaiInv,0) > @WQtdDif then @WQtdDif 
                                                Else Qtd_InfSaiInv 
                                              End
                                            Else  0
                                          End
                       From PRSLD
                      Where Cod_Estabe = @CodEstabe
                        and Cod_Produt = @CodPrd
                        and Dat_Movime = @DatPrc

                     if @WQtdExcSai > 0
                       begin
                         Update PRSLD
                            Set Qtd_SaiOut = Qtd_SaiOut - @WQtdExcSai,
                                Qtd_InfSaiInv = Qtd_InfSaiInv - @WQtdExcSai,
                                @WQtdDif = @WQtdDif - @WQtdExcSai
                          Where Cod_Estabe = @CodEstabe
                            and Cod_Produt = @CodPrd
                            and Dat_Movime = @DatPrc
                       end


                     -- registra qtd ajustada "manualmente" em PRXES devido inconsistência 
                     if @WQtdDif > 0
                       begin
                         Update PRSLD 
                            Set Qtd_EntOut = Qtd_EntOut + @WQtdDif,
                                Qtd_InfEntInv = IsNull(Qtd_InfEntInv,0) + @WQtdDif
                          Where Cod_Estabe = @CodEstabe
                            and Cod_Produt = @CodPrd
                            and Dat_Movime = @DatPrc
                       end

		         
                     -- repõe qtd subtraídas de outras entradas
                     Set @WQtdDif = @WQtdDif + @WQtdExcSai

                     Update PRSLD 
                        Set Qtd_SldPra = Qtd_SldPra + @WQtdDif
                      Where Cod_Estabe = @CodEstabe 
                        and Cod_Produt = @CodPrd
                        and Dat_Movime = @DatPrc
		         
                     Update PRXES
                        Set Qtd_Fisico = Qtd_Fisico + @WQtdDif
                      Where Cod_Estabe = @CodEstabe 
                        And Cod_Produt = @CodPrd

                   end  -- if @WQtdDif < 0

                 Fetch Next From PRSLD_Cr Into @CodPrd, @WQtdDif
               end
             Close PRSLD_Cr
             Deallocate PRSLD_Cr
           end  -- if Exists(Select 
----------------------------------------------------------------------------------------- 
 
          -- gera registros BALIT
          Declare ACERT_Cr Cursor Local Fast_Forward For 

            Select Cod_Produt, Cod_Lote, Dat_Vencim, Dat_Fabric, Qtd_EntPra, Qtd_EntDep, Qtd_SaiPra, Qtd_SaiDep
              From #TMP_ACERT   

          Open ACERT_Cr
          Fetch Next From ACERT_Cr Into @CodPrd, @CodLot, @DatVct, @DatFab, @QtdEntPra, @QtdEntDep, @QtdSaiPra, @QtdSaiDep
          While @@FETCH_STATUS = 0
            begin
              if @QtdEntPra > @QtdSaiPra
                begin
                  Set @QtdEntPra = @QtdEntPra - @QtdSaiPra
                  Set @QtdSaiPra = 0
                end
              else
                begin
                  Set @QtdSaiPra = @QtdSaiPra - @QtdEntPra
                  Set @QtdEntPra = 0
                end
            
              if @QtdEntDep > @QtdSaiDep
                begin
                  Set @QtdEntDep = @QtdEntDep - @QtdSaiDep
                  Set @QtdSaiDep = 0
                end
              else
                begin
                  Set @QtdSaiDep = @QtdSaiDep - @QtdEntDep
                  Set @QtdEntDep = 0
                end
                
              -- atualiza estoque disponivel atual de PRLOT em BALIT
              Set @WQtdSldAtu = ISNULL((Select IsNull(Qtd_SldPra,0)+IsNull(Qtd_SldDep,0) 
                                          From PRLOT Where Cod_Estabe = @CodEstabe and Cod_Dep = @WCodDep
                                           And Cod_Produt = @CodPrd and Cod_Lote = @CodLot),0)
                
              -- entrada
              if @QtdEntPra+@QtdEntDep > 0
                begin
                  Set @WQtdSldAnt = @WQtdSldAtu - @QtdEntPra - @QtdEntDep 
                  Insert Into BALIT (Cod_Estabe, Num_SeqBal, Cod_Produt, Cod_Lote, Dat_VctLot, Dat_Fabric, Cod_Local, Num_Contag, 
                                     Cod_MovEst, Tip_Movim, Qtd_SldEst, Qtd_Produt, Qtd_Acerto, Qtd_EstPra, Qtd_EstDep, Transacao, Flg_Proces, Dat_Proces,
                                     Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt)
                            Values  (@CodEstabe, @WNumSeqBal, @CodPrd, @CodLot, @DatVct, @DatFab, 0, 1, 
                                     @CodMveEnt, 'E', @WQtdSldAnt, @WQtdSldAtu, @QtdEntPra+@QtdEntDep, @QtdEntPra, @QtdEntDep, GetDate(), 1, @Date,
                                     @WCodDep, 0, 0, 0, 0 )
                end
              
              -- saida
              if @QtdSaiPra+@QtdSaiDep > 0
                begin
                  Set @WQtdSldAnt = @WQtdSldAtu + @QtdSaiPra + @QtdSaiDep 
                  Insert Into BALIT (Cod_Estabe, Num_SeqBal, Cod_Produt, Cod_Lote, Dat_VctLot, Dat_Fabric, Cod_Local, Num_Contag, 
                                     Cod_MovEst, Tip_Movim, Qtd_SldEst, Qtd_Produt, Qtd_Acerto, Qtd_EstPra, Qtd_EstDep, Transacao, Flg_Proces, Dat_Proces,
                                     Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt)
                            Values  (@CodEstabe, @WNumSeqBal, @CodPrd, @CodLot, @DatVct, @DatFab, 0, 1, 
                                     @CodMveSai, 'S', @WQtdSldAnt, @WQtdSldAtu, @QtdSaiPra+@QtdSaiDep, @QtdSaiPra, @QtdSaiDep, GetDate(), 1, @Date,
                                     @WCodDep, 0, 0, 0, 0 )
                end

              Update it   
                 Set it.Qtd_Produt = (Select SUM(b.Quantidade) From BALAN b Where b.Cod_Estabe = @CodEstabe and b.Cod_Produto = @CodPrd and b.Cod_Lote = @CodLot And b.Contagem = 1)
                From BALIT it Inner Join 
                     BALAN ba on (it.Cod_Estabe = ba.Cod_Estabe and it.Num_SeqBal = @WNumSeqBal and 
                                  it.Cod_Local = 0 and it.Num_Contag = 1 and
                                  it.Cod_Produt = ba.Cod_Produto and it.Cod_Lote = ba.Cod_Lote)
               Where ba.Cod_Estabe = @CodEstabe 
                 and ba.Cod_Produto = @CodPrd
                 And ba.Cod_Lote = @CodLot
                 And ba.Contagem = 1
                 And ba.Local = (Select MIN(b2.LOCAL) From BALAN b2 Where b2.Cod_Estabe = @CodEstabe and b2.Cod_Produto = @CodPrd and b2.Cod_Lote = @CodLot And b2.Contagem = 1)

              Fetch Next From ACERT_Cr Into @CodPrd, @CodLot, @DatVct, @DatFab, @QtdEntPra, @QtdEntDep, @QtdSaiPra, @QtdSaiDep
            end
          Close ACERT_Cr
          Deallocate ACERT_Cr

          -- insere registros BALIT de produtos sem divergencias - nao houve acerto
          Insert Into BALIT (Cod_Estabe, Num_SeqBal, Cod_Produt, Cod_Lote, Dat_VctLot, Dat_Fabric, Cod_Local, Num_Contag, 
                             Cod_MovEst, Tip_Movim, Qtd_SldEst, Qtd_Produt, Qtd_Acerto, Qtd_EstPra, Qtd_EstDep, Transacao, Flg_Proces, Dat_Proces,
                             Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt)
            Select b.Cod_Estabe, @WNumSeqBal, b.Cod_Produto, b.Cod_Lote, b.Dat_Vencim, b.Dat_Fabric, 0, 1, 0, 
                   'X', b.QtdBal, b.QtdBal, 0, 0, 0, GetDate(), 1, @Date,
                   @WCodDep, 0, 0, 0, 0
              From (Select Cod_Estabe, Cod_Produto, Cod_Lote, Dat_Vencim, Dat_Fabric, QtdBal = SUM(Quantidade)
                      From BALAN
                     Where Cod_Estabe = @CodEstabe 
                       and Contagem = 1
                     Group by Cod_Estabe, Cod_Produto, Cod_Lote, Dat_Vencim, Dat_Fabric) b Left Join
                   BALIT it on (it.Cod_Estabe = b.Cod_Estabe and it.Num_SeqBal = @WNumSeqBal and 
                                it.Cod_Local = 0 and it.Num_Contag = 1 and
                                it.Cod_Produt = b.Cod_Produto and it.Cod_Lote = b.Cod_Lote)
             Where it.Cod_Estabe = @CodEstabe
               And it.Cod_Produt is null      

          -- atualiza BALIT e BALCB            
          Update it
             Set it.Val_VarPrcCus = Case
                                      When it.Tip_Movim = 'E' then Round(it.Qtd_Acerto*p.Prc_CusLiqEnt,2)
                                      Else -Round(it.Qtd_Acerto*p.Prc_CusLiqEnt,2)
                                    End,
                 it.Val_VarPrcMed = Case
                                      When it.Tip_Movim = 'E' then Round(it.Qtd_Acerto*p.Prc_CusMed,2)
                                      Else -Round(it.Qtd_Acerto*p.Prc_CusMed,2)
                                    End, 
                 it.Val_VarPrcVen = Case
                                      When it.Tip_Movim = 'E' then Round(it.Qtd_Acerto*p.Prc_Venda,2)
                                      Else -Round(it.Qtd_Acerto*p.Prc_Venda,2)
                                    End
            From BALCB cb Inner Join 
                 BALIT it on (cb.Cod_Estabe = it.Cod_Estabe and cb.Num_SeqBal = it.Num_SeqBal) Inner Join 
                 PRXES p on it.Cod_Estabe = p.Cod_Estabe and it.Cod_Produt = p.Cod_Produt
           Where cb.Cod_Estabe = @CodEstabe
             And cb.Num_SeqBal = @WNumSeqBal      
            
          Update cb
             Set cb.Flg_Proces = 1, 
                 cb.Dat_Movime = @Date,
                 cb.Qtd_IteBal = it.QtdItens,
                 cb.Qtd_AceNeg = it.QtdAceNeg,
                 cb.Qtd_AcePos = it.QtdAcePos,
                 cb.Val_VarPrcCus = it.ValVarPrcCus,
                 cb.Val_VarPrcMed = it.ValVarPrcMed, 
                 cb.Val_VarPrcVen = it.ValVarPrcVen
            From BALCB cb Inner Join 
                 (Select Cod_Estabe, Num_SeqBal,
                         QtdItens = Count(Distinct Cod_Produt),
                         QtdAceNeg = Sum(Case When TIp_Movim = 'S' then Qtd_Acerto else 0 End),
                         QtdAcePos = Sum(Case When TIp_Movim = 'E' then Qtd_Acerto else 0 End),
                         ValVarPrcCus = SUM(Val_VarPrcCus),
                         ValVarPrcMed = SUM(Val_VarPrcMed),
                         ValVarPrcVen = SUM(Val_VarPrcVen)
                    From BALIT
                   Where Cod_Estabe = @CodEstabe 
                     and Cod_Local = 0 and Num_Contag = 1
                   Group by Cod_Estabe, Num_SeqBal) it on (cb.Cod_Estabe = it.Cod_Estabe and cb.Num_SeqBal = it.Num_SeqBal)
           Where cb.Cod_Estabe = @CodEstabe
             And cb.Num_SeqBal = @WNumSeqBal 
          
          -- elimina registros em BALAN
          Delete From BALAN
           Where Cod_Estabe = @CodEstabe
          if @@error <> 0
            begin
              Rollback Transaction
              Return
            end

          IF OBJECT_ID('TempDB.dbo.#TMP_ACERT') IS NOT NULL
            DROP TABLE #TMP_ACERT

        Commit Transaction
      end   
  end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CadastraPrazoPDECB]
@PCodEstabe int,
@PCodLayout int,
@PNumCnpj varchar(14),
@PCodPedCli varchar(20),
@PNumDesdob smallint

AS

SET NOCOUNT ON

Declare @WQtdParcel int = 0,
        @WPriQtdPrz int = 0,
        @WSumParcel numeric(18,4) = 0

-- normaliza PDEPZ ----------------------------
Delete From PDEPZ
 Where Cod_Estabe = @PCodEstabe 
   And Cod_Layout = @PCodLayout 
   And Num_Cnpj   = @PNumCnpj 
   And Cod_PedCli = @PCodPedCli 
   And IsNull(Qtd_Prazo,0) = 0
   And IsNull(Per_Parcela,0) = 0

if Exists(Select 1 From PDEPZ  
           Where Cod_Estabe = @PCodEstabe 
             And Cod_Layout = @PCodLayout 
             And Num_Cnpj = @PNumCnpj 
             And Cod_PedCli = @PCodPedCli)
  begin

    Update PDEPZ
       Set Per_Parcela = Round(IsNull(Per_Parcela,0),2)
     Where Cod_Estabe = @PCodEstabe 
       And Cod_Layout = @PCodLayout 
       And Num_Cnpj   = @PNumCnpj 
       And Cod_PedCli = @PCodPedCli 

     -- calcula qtd de parcelas
     Set @WQtdParcel = (Select count(*) From PDEPZ
                         Where Cod_Estabe = @PCodEstabe 
                           And Cod_Layout = @PCodLayout 
                           And Num_Cnpj   = @PNumCnpj 
                           And Cod_PedCli = @PCodPedCli) 

    -- poe na memoria primeiro registro(parcela)
    Select top 1 @WPriQtdPrz = Qtd_Prazo 
      From PDEPZ
     Where Cod_Estabe = @PCodEstabe 
       And Cod_Layout = @PCodLayout 
       And Num_Cnpj   = @PNumCnpj 
       And Cod_PedCli = @PCodPedCli 
     Order by Qtd_Prazo

     -- calcula % das parcelas exceto a primeira
     if (Select sum(Per_Parcela) 
           From PDEPZ
          Where Cod_Estabe = @PCodEstabe 
            And Cod_Layout = @PCodLayout 
            And Num_Cnpj   = @PNumCnpj 
            And Cod_PedCli = @PCodPedCli
            And Qtd_Prazo <> @WPriQtdPrz) = 0.00
       Update PDEPZ
          Set Per_Parcela = Round(100.00/@WQtdParcel,2,1)  -- trunca
        Where Cod_Estabe = @PCodEstabe 
          And Cod_Layout = @PCodLayout 
          And Num_Cnpj   = @PNumCnpj 
          And Cod_PedCli = @PCodPedCli
          And Qtd_Prazo <> @WPriQtdPrz

    -- atualiza % 1a. parcela
    if (Select count(*) From PDEPZ) = 1
        Update PDEPZ
           Set Per_Parcela = 100.00
         Where Cod_Estabe  =  @PCodEstabe 
           And Cod_Layout  =  @PCodLayout 
           And Num_Cnpj    =  @PNumCnpj 
           And Cod_PedCli  =  @PCodPedCli 
           And Qtd_Prazo   =  @WPriQtdPrz
		   And Per_Parcela <> 100.00
    else 
      begin
        -- soma dos % das parcelas exceto a primeira
	    Select @WSumParcel = sum(Per_Parcela) 
          From PDEPZ
         Where Cod_Estabe = @PCodEstabe 
           And Cod_Layout = @PCodLayout 
           And Num_Cnpj   = @PNumCnpj 
           And Cod_PedCli = @PCodPedCli
           And Qtd_Prazo <> @WPriQtdPrz

        -- poe a diferença na primeira
        Update PDEPZ
           Set Per_Parcela =  (100.00 - @WSumParcel)
         Where Cod_Estabe  =  @PCodEstabe 
           And Cod_Layout  =  @PCodLayout 
           And Num_Cnpj    =  @PNumCnpj 
           And Cod_PedCli  =  @PCodPedCli 
           And Qtd_Prazo   =  @WPriQtdPrz
		   And Per_Parcela <> (100.00 - @WSumParcel)
		   And @WSumParcel <  100.00 
      end
    
  end --if Exists(

-- fim normaliza PDEPZ ----------------------------


if Exists(Select 1 From PDEPZ  
           Where Cod_Estabe = @PCodEstabe 
             And Cod_Layout = @PCodLayout 
             And Num_Cnpj = @PNumCnpj 
             And Cod_PedCli = @PCodPedCli 
             And Qtd_Prazo > 0) and
   ( (Select sum(Per_Parcela) 
        From PDEPZ
       Where Cod_Estabe = @PCodEstabe 
         And Cod_Layout = @PCodLayout 
         And Num_Cnpj   = @PNumCnpj 
         And Cod_PedCli = @PCodPedCli) = 100.00 )
begin
  BEGIN TRANSACTION 

  Declare @WCod_Prz int, 
          @WDes_Prz varchar(100), 
          @WPrz_Med int, 
          @WTip_Vct varchar(1), 
          @cr_CodPrz int, 
          @cr_QtdPrzPar int, 
          @cr_PerParPar numeric(18,4), 
          @WAchou bit 

  Set @WTip_Vct = 'T'
  Set @WCod_Prz = 0 
  Set @WAchou = 0

  if Exists(Select 1
              From PDECB cb 
                   Inner Join PDEPZ dp on ((cb.Cod_Estabe = dp.Cod_Estabe) and (cb.Cod_Layout = dp.Cod_Layout) and (cb.Num_Cnpj = dp.Num_Cnpj) and (cb.Cod_PedCli = dp.Cod_PedCli)) 
                   Inner Join PRZCB c on (cb.Qtd_Parcela = c.Qtd_ParPrz)
                   Inner Join PRZIT i on ((c.Cod_Prz = i.Cod_Prz) and (dp.Qtd_Prazo = i.Qtd_PrzPar) and (dp.Per_Parcela = i.Per_ParPar)) 
             Where cb.Cod_Estabe = @PCodEstabe 
               And cb.Cod_Layout = @PCodLayout 
               And cb.Num_Cnpj   = @PNumCnpj 
               And cb.Cod_PedCli = @PCodPedCli 
               And cb.Num_Desdob = @PNumDesdob 
               And c.Flg_ParOk   = 1) 
    begin 
      Declare PRZCB_cr CURSOR Local Fast_Forward For 

        Select distinct c.Cod_Prz 
          From PDECB cb
               Inner Join PDEPZ dp on ((cb.Cod_Estabe = dp.Cod_Estabe) and (cb.Cod_Layout = dp.Cod_Layout) and (cb.Num_Cnpj = dp.Num_Cnpj) and (cb.Cod_PedCli = dp.Cod_PedCli))
               Inner Join PRZCB c on (cb.Qtd_Parcela = c.Qtd_ParPrz)
               Inner Join PRZIT i on ((c.Cod_Prz = i.Cod_Prz) and (dp.Qtd_Prazo = i.Qtd_PrzPar) and (dp.Per_Parcela = i.Per_ParPar)) 
         Where cb.Cod_Estabe = @PCodEstabe 
           And cb.Cod_Layout = @PCodLayout 
           And cb.Num_Cnpj   = @PNumCnpj 
           And cb.Cod_PedCli = @PCodPedCli 
           And cb.Num_Desdob = @PNumDesdob 
           And c.Flg_ParOk   = 1 

      Open PRZCB_cr 
      Fetch Next From PRZCB_cr Into @cr_CodPrz 
      While (@@FETCH_STATUS = 0) 
      begin 
        Set @WAchou = 1 

        Declare PRZIT_cr CURSOR Local Fast_Forward For 
         
          Select Qtd_PrzPar, Per_ParPar 
            From PRZIT 
           Where Cod_Prz = @cr_CodPrz 

        Open PRZIT_cr 
        Fetch Next From PRZIT_cr Into @cr_QtdPrzPar, @cr_PerParPar 
        While @@FETCH_STATUS = 0 
        begin 
          if not Exists(Select 1 from PDEPZ 
                         Where Cod_Estabe  = @PCodEstabe 
                           And Cod_Layout  = @PCodLayout 
                           And Num_Cnpj    = @PNumCnpj 
                           And Cod_PedCli  = @PCodPedCli 
                           And Qtd_Prazo   = @cr_QtdPrzPar 
                           And Per_Parcela =  @cr_PerParPar) 
            begin 
              Set @WAchou = 0 
            end 
          Fetch Next From PRZIT_cr Into @cr_QtdPrzPar, @cr_PerParPar 
        end 
        Close PRZIT_cr 
        Deallocate PRZIT_cr 

        if @WAchou = 1 
          Set @WCod_Prz = @cr_CodPrz 
  
        Fetch Next From PRZCB_cr Into @cr_CodPrz 
      end 
  
      Close PRZCB_cr 
      Deallocate PRZCB_cr 
    end 
  
  if @WCod_Prz = 0 
    begin 
      Set @WCod_Prz = IsNull((Select MAX(Cod_Prz) From PRZCB),0) + 1 
      -- descricao do prazo
      Set @WDes_Prz = 'PE '

      Insert Into PRZCB (Cod_Prz, Descri_Prz, Qtd_ParPrz, Qtd_PrzMed, Flg_ParOk) 
        Select @WCod_Prz, @WDes_Prz, Qtd_Parcela, 0, 1 
          From PDECB 
         Where Num_Cnpj   = @PNumCnpj 
           And Cod_PedCli = @PCodPedCli 
           And Num_Desdob = @PNumDesdob
           And Cod_Estabe = @PCodEstabe					
   
      Insert Into PRZIT (Cod_Prz, Qtd_PrzPar, Per_ParPar) 
        Select @WCod_Prz, Qtd_Prazo, Per_Parcela 
          From PDEPZ 
         Where Cod_Estabe = @PCodEstabe 
           And Cod_Layout = @PCodLayout 
           And Num_Cnpj = @PNumCnpj 
           And Cod_PedCli = @PCodPedCli 
  
      Select @WPrz_Med = sum(it.Qtd_PrzPar*it.Per_ParPar/100) 
        From PRZCB cb 
             Inner Join PRZIT it on cb.Cod_Prz = it.Cod_Prz 
       Where cb.Cod_Prz = @WCod_Prz 
  
      Set @WDes_Prz = 'PE '+ (Select dbo.FN_ConcatenaPrazosPRZIT(1475,'/')) + ' DD'

      Update PRZCB 
         Set Descri_Prz = Substring(@WDes_Prz,1,25),
             Qtd_PrzMed = @WPrz_Med 
       Where Cod_Prz = @WCod_Prz 

    end 
  
  if @WCod_Prz > 0 
    begin 
      Select @WPrz_Med = sum(it.Qtd_PrzPar*it.Per_ParPar/100) 
        From PRZCB cb 
             Inner Join PRZIT it on cb.Cod_Prz = it.Cod_Prz 
       Where cb.Cod_Prz = @WCod_Prz 
  
      Update PDECB 
         Set Qtd_PrzMed = @WPrz_Med, 
             Tip_Vencimento = @WTip_Vct, 
             Cod_TabPrz = @WCod_Prz 
       Where Cod_Estabe = @PCodEstabe 
         And Cod_Layout = @PCodLayout 
         And Num_Cnpj   = @PNumCnpj 
         And Cod_PedCli = @PCodPedCli 
         And Num_Desdob = @PNumDesdob 
    end 

  if @@trancount > 0
    COMMIT TRANSACTION 
end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CadastraPrazosTudoFarma]
@PDesLayout varchar(25),
@PCodPrzLay varchar(6)

AS

SET NOCOUNT ON


if Exists(Select 1 From TBCLP Where Des_Layout = @PDesLayout)
begin

  BEGIN TRANSACTION 

  Declare @WCodLayout int,
          @WDesPrzLay varchar(40),
          @WQtdParLay smallint,
          @WQtdPrzMedLay int,

          @WCodPrz int,
          @WPrzMed int


  Set @WCodLayout = (Select top 1 Cod_Layout From TBCLP Where Des_Layout = 'TUDOFARMA')  

  if @WCodLayout > 0 
    begin

      -- PRAZO 107 --
      if @PCodPrzLay = '107'
        begin
          Set @WDesPrzLay = '07 DDL'
          Set @WQtdParLay = 1
          Set @WQtdPrzMedLay = 07
       
          Set @WCodPrz = 0    -- prazo infarma
       
         if not Exists(Select 1 From TLPPZ Where Cod_Layout = @WCodLayout And Cod_PrzLay = @PCodPrzLay)
            Insert Into TLPPZ (Cod_Layout, Cod_PrzLay, Des_PrzLay, Cod_PrzInf)
       	   Values (@WCodLayout, @PCodPrzLay, @WDesPrzLay, @WCodPrz)
       
           Set @WCodPrz = IsNull((Select Cod_PrzInf From TLPPZ Where Cod_Layout = @WCodLayout And Cod_PrzLay = @PCodPrzLay),0)
       
           -- o codigo do prazo correspondente no sistema eh invalido
           if not Exists(Select 1 From PRZCB Where Qtd_ParPrz = @WQtdParLay And Qtd_PrzMed = @WQtdPrzMedLay And Flg_ParOk = 1 And Cod_Prz = @WCodPrz)
             begin
               if Exists(Select 1 From PRZCB Where Qtd_ParPrz = @WQtdParLay And Qtd_PrzMed = @WQtdPrzMedLay And Flg_ParOk = 1)
                 Set @WCodPrz = (Select top 1 Cod_Prz From PRZCB Where Qtd_ParPrz = @WQtdParLay And Qtd_PrzMed = @WQtdPrzMedLay And Flg_ParOk = 1)
               else
                 begin
                   Set @WCodPrz = IsNull((Select MAX(Cod_Prz) From PRZCB),0) + 1 
       
                   Insert Into PRZCB (Cod_Prz, Descri_Prz, Qtd_ParPrz, Qtd_PrzMed, Flg_ParOk) 
                     Values (@WCodPrz, '07 DIAS', @WQtdParLay, @WQtdPrzMedLay, 1)
       
                   Insert Into PRZIT (Cod_Prz, Qtd_PrzPar, Per_ParPar) 
                     Values (@WCodPrz, 07, 100.0) 
       
                  Select @WPrzMed = Round(sum(it.Qtd_PrzPar*it.Per_ParPar/100),0) 
                    From PRZCB cb Inner JOIN 
                         PRZIT it on cb.Cod_Prz = it.Cod_Prz 
                    Where cb.Cod_Prz = @WCodPrz 
       
                  Update PRZCB 
                    Set Qtd_PrzMed = @WPrzMed 
                    Where Cod_Prz = @WCodPrz 
                 end
             end
       
          Update TLPPZ
            Set Cod_PrzInf = @WCodPrz
           Where Cod_Layout = @WCodLayout 
           And Cod_PrzLay = @PCodPrzLay
       
        end
