				               QtdPrzMinDscAtcCtr,FlgPrcEspHospit,CodRamAtvHospit,CodRamAtvOrgPub,CodRamAtvAtacad,FlgAlerta,
				               FlgIstRecDup,FlgBlqCriPrcVen,FlgEmbDscItePrcUni,QtdConBal,FlgImpIstOrc,DiaVctDupExtIst,FlgIntCtb,
				               FlgIntFis,FlgPdvPrzFab,FlgLimComMaxFab,FlgComRedItePrm,FlgExcImpOrcItePrm,FlgCmpAutChqVct,FlgEmiDup,
				               FlgIstOrcCli,VlrDebVndCtr,TipNotFis,FlgComPrpDsc,FlgCnvDscIteDscCom,FlgCnvPdvVal,FlgCalComDscFin,
				               FlgConferPed,FlgZerLimCre,PerMulAtrPag,QtdDiaProtes,PerMkpPrdCipNeg,PerMkpPrdCipPos,PerMkpPrdCipNeu,
				               FlgCalendContab,FlgImpItePrpNfs,DesArqAbcFar,FlgGerRecSubFat,FlgCtrSubFat,
				               FlgComPrdPrpDsc,FlgComPrdPrpDscPrm,FlgImpResFinPreNot,QtdDiaPerPdv,QtdDiaCanNtf,TipOrcame,
				               QtdDiaPrzEntChqVct,QtdDiaAtrMedCtr,QtdMesPagCtrAtr,FlgBlqPdvAtrCtr,StrCodAgcChqVct,FlgCtlLotSai,
				               FlgImpCtrPreNot,FlgComTabDsc,FlgTabPrcConFin,
				               FlgNaoRepIcmVen,FlgTabPrzVenLin,QtdDecPrcItePdv,TipCalCtbCtp,FlgCalCtbCtr,TipCalCtbCtr,TipCalCusPrd,
				               FlgAtuPrvEnt,FlgBasPrvConFin,FlgContribSubstituto,FlgPrzLinConFin,FlgImpDscEmbNot,FlgResPrdVen,
				               QtdDiaResPrdVen,FlgImpDesPrdCli,FlgNaoSugDscItePdv,FlgRegDscCliItePdv,PerRntMinPdv,FlgPerCmpEst,
				               FlgSubTriCusPrd,FlgIcmTriCusPrd,ValDspBolBan,FlgCobDspBanNtf,FlgRedComCliPar,FlgCtrEntNfs,
				               FlgSugPrmPdv,PerDscPrmExtVenVis,FlgPreEntNfe,PerDedVlrChqDvl,QtdDiaRecChqDvl,UltDatFecComVnd,
				               UltDatFecComEnt,PerMinRndCxaFecInfSugCmp,FlgCorAutFalPdvFecCnf,Dat_UltRemSerasa,FlgNaoObgSelFisOpeExt,
				               FlgComPrpDscTabRed,FlgComPrpDscTabFix,FlgGerComOpeAtv,PerRedComCliPar,CodOpeSemCom,FlgAltConComPdv,
				               FlgRegPrzPdvExcConCom,FlgDispenPwdPedRea,FlgTabPrzPrcVenLin,FlgFatAutPdvDiv,Str1EstCliGerRom,
				               CodCli1GerRom,CodOpe1GerRom,FlgAltUnvItePdv,FlgSugUnvPadPdv,FlgEncParAut,FlgCriPrcMinCusLiq,
				               FlgCriPrcMinPmz,FlgOmiEstNegCadPro,PerAcrCriPrcMinCusLiq,Flg_BlqAltQtdCnf,Flg_DivPdvVol,
				               FlgCanNotForaPerFis,FlgAtuPrcCusCadPro,Des_VersaoMin,FlgPisCofCusPrd,DesImpPckLst,
				               CodCtrImpAprPreNot,FlgBlqSugPrmQtdMin,FlgCalComPdv,FlgImpEmpVal,FlgCtrBlqPdvLicCli,
				               FlgNfe,FlgSolCrmPdv,FlgIncSbtPrcOpeInt,FlgInfFrePdv,FlgUsaPolComPdv,FlgImpRotBlq,
				               FlgUsaPsqPar,FlgManutencao,FlgDscAutPrxFatCli,FlgSugPolComIdeal,FlgAltDscPrdBlqDsc,
				               FlgCriIteFecPdv,FlgBlqMsgFecPdv,FlgUsaPrcBruEnt,FlgIncDscPrcOpeIntSbtEmb,FlgInfPrvFrePdv,
				               FlgBlqIcmTriCalRntPrdSbtFnt,FlgFecVlrPdvNfsSbtEmb,FlgGerAutPdvBon,CodTpvBon,FlgGerBonVlrCli,
				               CodEstabeCon,FlgBlqCnfLotPrd,PrzVctLot1,CorVctLot1,PrzVctLot2,CorVctLot2,PrzVctLot3,CorVctLot3,
				               FlgImpSldEstBal,FlgUsaEstornoNfe,FlgBlqIncPdvCliAtr,FlgBlqFecNfeDivPrc,PerDesPisLucRea,
				               PerDesPisLucPre,PerDesCofLucRea,PerDesCofLucPre,FlgIncIpiCalPis,FlgCalcRentPdvOnLine,
				               FlgArredondaPisCofins,FlgCriPrcMinCusMedCom,FlgNfeIntArtNew,FlgUsaCusMedComCalRnt,TipEmiNfe,
				               FlgBlqBonPdv,FlgNfeWebSer,FlgSugPolComMenDsc,FlgPerResExtEnt,FlgUsaColExp,FlgUsaColRec,QtdPrzMaxImpSbt,FlgUsaPbmSpv,
                               QtdDiaPerAud,QtdDiaPerMaiNfs,QtdDiaPerXmlNfs,FlgCotPrcPrd,FlgUsaDirGerCac,FlgExiPolSelPrdPedVen,FlgBlqCtrDocClaPrd,
							   FlgAtuTabPrcEnt,FlgExiGrpPrdPdv,DatUltAtuModExt,FlgManImpPckLst,FlgExbEstPrcAprPrd)
			Select @CodEstabe, UltDatAcesso,DatHorArqRot,VlrObjEmp,VlrLimComFun,PerComVdrAtoVen,
				               PerMinAcrComGer,PerMaxAcrComGer,CodAgeCobCar,FlgImpPedBlq,FlgImpPedDbq,FlgImpCupFun,
