				               CodVdrPdvCon,CodOpePdvFun,CodOpePdvCon,CodCidadeEmpLoc,CodMacRegEmpLoc,CodMicRegEmpLoc,
				               PerTaxJurMerc,PerCorPrcVen,PrzRefPrcVen,PrzPrc1,PrzPrc2,PrzPrc3,PrzPrc4,
				               FlgCtrLot,QtdDiaDupVis,TipPreNot,MrgErrAdmNfe,FlgFecFisNfe,FlgImpCliPreNot,FlgDespachMercad,
				               FlgIncImpPriDup,FlgImpSelFisNotFis,FlgImpHorSaiNotFis,FlgCtrDscIte,PerMaxDscIte,FlgCtrSelFis,
				               FlgIncImpOrc,FlgIncImpFun,FlgIncImpCon,FlgComRedIteDsc,PerMaxComNorIteDsc,FlgComRedNotDsc,
				               PerMaxComNorNotDsc,FlgComRedCliEsp,FlgOrcAgeCobCar,FlgDscFinIstOutEst,FlgBlqAltVndPdv,
				               FlgImpDscIteNfs,Ctr_ImpItePreNot,Ctr_ImpIteNotFis,FlgComVndCmpOpe,PerDscAtcCtr,QtdPrzDscAtcCtr,
				               QtdPrzMinDscAtcCtr,FlgPrcEspHospit,CodRamAtvHospit,CodRamAtvOrgPub,CodRamAtvAtacad,FlgAlerta,
				               FlgIstRecDup,FlgBlqCriPrcVen,FlgEmbDscItePrcUni,QtdConBal,FlgImpIstOrc,DiaVctDupExtIst,FlgIntCtb,
				               FlgIntFis,FlgPdvPrzFab,FlgLimComMaxFab,FlgComRedItePrm,FlgExcImpOrcItePrm,FlgCmpAutChqVct,FlgEmiDup,
				               FlgIstOrcCli,VlrDebVndCtr,TipNotFis,FlgComPrpDsc,FlgCnvDscIteDscCom,FlgCnvPdvVal,FlgCalComDscFin,
				               FlgConferPed,FlgZerLimCre,PerMulAtrPag,QtdDiaProtes,PerMkpPrdCipNeg,PerMkpPrdCipPos,PerMkpPrdCipNeu,
				               FlgCalendContab,FlgImpItePrpNfs,DesArqAbcFar,FlgGerRecSubFat,FlgCtrSubFat,
				               FlgComPrdPrpDsc,FlgComPrdPrpDscPrm,FlgImpResFinPreNot,QtdDiaPerPdv,QtdDiaCanNtf,TipOrcame,
				               QtdDiaPrzEntChqVct,QtdDiaAtrMedCtr,QtdMesPagCtrAtr,FlgBlqPdvAtrCtr,StrCodAgcChqVct,FlgCtlLotSai,
				               FlgImpCtrPreNot,FlgComTabDsc,FlgTabPrcConFin,
				               FlgNaoRepIcmVen,FlgTabPrzVenLin,QtdDecPrcItePdv,TipCalCtbCtp,FlgCalCtbCtr,TipCalCtbCtr,TipCalCusPrd,
				               FlgAtuPrvEnt,FlgBasPrvConFin,FlgContribSubstituto,FlgPrzLinConFin,FlgImpDscEmbNot,FlgResPrdVen,
				               QtdDiaResPrdVen,FlgImpDesPrdCli,FlgNaoSugDscItePdv,FlgRegDscCliItePdv,PerRntMinPdv,FlgPerCmpEst,
				               FlgSubTriCusPrd,FlgIcmTriCusPrd,ValDspBolBan,FlgCobDspBanNtf,FlgRedComCliPar,FlgCtrEntNfs,
				               FlgSugPrmPdv,PerDscPrmExtVenVis,FlgPreEntNfe,PerDedVlrChqDvl,QtdDiaRecChqDvl,UltDatFecComVnd,
				               UltDatFecComEnt,PerMinRndCxaFecInfSugCmp,FlgCorAutFalPdvFecCnf,Dat_UltRemSerasa,FlgNaoObgSelFisOpeExt,
				               FlgComPrpDscTabRed,FlgComPrpDscTabFix,FlgGerComOpeAtv,PerRedComCliPar,CodOpeSemCom,FlgAltConComPdv,
				               FlgRegPrzPdvExcConCom,FlgDispenPwdPedRea,FlgTabPrzPrcVenLin,FlgFatAutPdvDiv,Str1EstCliGerRom,
				               CodCli1GerRom,CodOpe1GerRom,FlgAltUnvItePdv,FlgSugUnvPadPdv,FlgEncParAut,FlgCriPrcMinCusLiq,
				               FlgCriPrcMinPmz,FlgOmiEstNegCadPro,PerAcrCriPrcMinCusLiq,Flg_BlqAltQtdCnf,Flg_DivPdvVol,
				               FlgCanNotForaPerFis,FlgAtuPrcCusCadPro,Des_VersaoMin,FlgPisCofCusPrd,DesImpPckLst,
				               CodCtrImpAprPreNot,FlgBlqSugPrmQtdMin,FlgCalComPdv,FlgImpEmpVal,FlgCtrBlqPdvLicCli,
				               FlgNfe,FlgSolCrmPdv,FlgIncSbtPrcOpeInt,FlgInfFrePdv,FlgUsaPolComPdv,FlgImpRotBlq,
				               FlgUsaPsqPar,FlgManutencao,FlgDscAutPrxFatCli,FlgSugPolComIdeal,FlgAltDscPrdBlqDsc,
				               FlgCriIteFecPdv,FlgBlqMsgFecPdv,FlgUsaPrcBruEnt,FlgIncDscPrcOpeIntSbtEmb,FlgInfPrvFrePdv,
				               FlgBlqIcmTriCalRntPrdSbtFnt,FlgFecVlrPdvNfsSbtEmb,FlgGerAutPdvBon,CodTpvBon,FlgGerBonVlrCli,
				               CodEstabeCon,FlgBlqCnfLotPrd,PrzVctLot1,CorVctLot1,PrzVctLot2,CorVctLot2,PrzVctLot3,CorVctLot3,
				               FlgImpSldEstBal,FlgUsaEstornoNfe,FlgBlqIncPdvCliAtr,FlgBlqFecNfeDivPrc,PerDesPisLucRea,
				               PerDesPisLucPre,PerDesCofLucRea,PerDesCofLucPre,FlgIncIpiCalPis,FlgCalcRentPdvOnLine,
				               FlgArredondaPisCofins,FlgCriPrcMinCusMedCom,FlgNfeIntArtNew,FlgUsaCusMedComCalRnt,TipEmiNfe,
				               FlgBlqBonPdv,FlgNfeWebSer,FlgSugPolComMenDsc,FlgPerResExtEnt,FlgUsaColExp,FlgUsaColRec,QtdPrzMaxImpSbt,FlgUsaPbmSpv,
                               QtdDiaPerAud,QtdDiaPerMaiNfs,QtdDiaPerXmlNfs,FlgCotPrcPrd,FlgUsaDirGerCac,FlgExiPolSelPrdPedVen,FlgBlqCtrDocClaPrd,
							   FlgAtuTabPrcEnt,FlgExiGrpPrdPdv,DatUltAtuModExt,FlgManImpPckLst,FlgExbEstPrcAprPrd
			From PARAM
			Where Cod_Estabe = @CodEstabePai
			And Not Exists(Select 1 From PARAM Where Cod_Estabe = @CodEstabe)

			-- AUDITORIA
			Set @RowCount = @@ROWCOUNT
			Set @TotalCount = @TotalCount+@RowCount;
			If @RowCount > 0
				Insert Into AUDIT (Cod_Estabe,Cod_Ope,Nom_Tabela,Chave1,Chave2,Nom_Campo,Des_Campo,
				            Observ,
				            Usuario,Transacao)
	            Values(@CodEstabe, 'I','PARAM',@CodEstabe,@IdSessao,'Cod_Estabe','PR_ConfiguraESTAB',
				            'Inclusão de '+Convert(varchar(20),@RowCount)+' Registros em PARAM',
					       @Usuario,GetDate() )

			If @RowCount = 0
				Insert Into AUDIT (Cod_Estabe,Cod_Ope,Nom_Tabela,Chave1,Chave2,Nom_Campo,Des_Campo,
				            Observ,
				            Usuario,Transacao)
	            Values(@CodEstabe, 'I','PARAM',@CodEstabe,@IdSessao,'Cod_Estabe','PR_ConfiguraESTAB',
				            'Atenção: Não foram inseridos registros em PARAM',
					       @Usuario,GetDate() )


	   	  End
	   	-- FINAL CRIAR PARAM

		-- Criar PMEST senão existir
		If (@Opcao = 0 or @Opcao = 2) And Not Exists(Select 1 From PMEST Where Cod_Estabe = @CodEstabe)
		  Begin
			Insert Into PMEST (Cod_Estabe ,
					CodClaAbc1 ,PerClaAbcVal1 ,PerClaAbcVol1 ,QtdDiaSeg1 ,CodClaAbc2 ,PerClaAbcVal2 ,PerClaAbcVol2 ,
					QtdDiaSeg2 ,CodClaAbc3 ,PerClaAbcVal3 ,PerClaAbcVol3 ,QtdDiaSeg3 ,CodClaAbc4 ,PerClaAbcVal4 ,PerClaAbcVol4 ,QtdDiaSeg4 ,CodClaAbc5 ,
					PerClaAbcVal5 ,PerClaAbcVol5 ,QtdDiaSeg5 ,CodClaAbc6 ,PerClaAbcVal6 ,PerClaAbcVol6 ,QtdDiaSeg6 ,Usuario ,Transacao ,CodZonDev ,
					CodZonCan ,CodZonDiv ,QtdNivEndPck ,QtdNivEndDep ,WmsFlgBlqImpEtqVol ,WmsFlgBlqImpCodBarPckLst ,WmsFlgBlqRotFecEmbPdv ,FlgCnfIUM ,
					WmsFlgImpFabPckLst ,BalImpIniCodBar ,BalImpTamCodBar ,BalImpIniQtdPrd ,BalImpTamQtdPrd ,BalExpIniCodBar ,BalExpTamCodBar ,BalExpIniDesPrd ,
					BalExpTamDesPrd ,BalExpIniQtdPrd ,BalExpTamQtdPrd ,BalExpFlgCodPrd ,DesMscEndPrd ,CodOpeNfsBal ,CodOpeNfeBal ,CodCliNotBal ,CodZonDivBal ,
					FlgBlqCnfTrf ,CodOpeWmsDef ,BlqEstFisNeg,FlgIntegrWmsExt,DesSisIntWms,FlgIgnQtdMenDvgPdc,FlgIgnPrcMenDvgPdc,WmsFlgBlqImpEtqVolPul)
			Select @CodEstabe ,
					CodClaAbc1 ,PerClaAbcVal1 ,PerClaAbcVol1 ,QtdDiaSeg1 ,CodClaAbc2 ,PerClaAbcVal2 ,PerClaAbcVol2 ,
					QtdDiaSeg2 ,CodClaAbc3 ,PerClaAbcVal3 ,PerClaAbcVol3 ,QtdDiaSeg3 ,CodClaAbc4 ,PerClaAbcVal4 ,PerClaAbcVol4 ,QtdDiaSeg4 ,CodClaAbc5 ,
					PerClaAbcVal5 ,PerClaAbcVol5 ,QtdDiaSeg5 ,CodClaAbc6 ,PerClaAbcVal6 ,PerClaAbcVol6 ,QtdDiaSeg6 ,Usuario ,Transacao ,CodZonDev ,
					CodZonCan ,CodZonDiv ,QtdNivEndPck ,QtdNivEndDep ,WmsFlgBlqImpEtqVol ,WmsFlgBlqImpCodBarPckLst ,WmsFlgBlqRotFecEmbPdv ,FlgCnfIUM ,
					WmsFlgImpFabPckLst ,BalImpIniCodBar ,BalImpTamCodBar ,BalImpIniQtdPrd ,BalImpTamQtdPrd ,BalExpIniCodBar ,BalExpTamCodBar ,BalExpIniDesPrd ,
					BalExpTamDesPrd ,BalExpIniQtdPrd ,BalExpTamQtdPrd ,BalExpFlgCodPrd ,DesMscEndPrd ,CodOpeNfsBal ,CodOpeNfeBal ,CodCliNotBal ,CodZonDivBal ,
					FlgBlqCnfTrf ,CodOpeWmsDef ,BlqEstFisNeg,FlgIntegrWmsExt,DesSisIntWms,FlgIgnQtdMenDvgPdc,FlgIgnPrcMenDvgPdc,WmsFlgBlqImpEtqVolPul
			From PMEST
			Where Cod_Estabe = @CodEstabePai
			And Not Exists(Select 1 From PMEST Where Cod_Estabe = @CodEstabe)

			-- AUDITORIA
			Set @RowCount = @@ROWCOUNT
			Set @TotalCount = @TotalCount+@RowCount;
			If @RowCount > 0
				Insert Into AUDIT (Cod_Estabe,Cod_Ope,Nom_Tabela,Chave1,Chave2,Nom_Campo,Des_Campo,
				            Observ,
				            Usuario,Transacao)
	            Values(@CodEstabe, 'I','PMEST',@CodEstabe,@IdSessao,'Cod_Estabe','PR_ConfiguraESTAB',
				            'Inclusão de '+Convert(varchar(20),@RowCount)+' Registros em PMEST',
					       @Usuario,GetDate() )

			If @RowCount = 0
				Insert Into AUDIT (Cod_Estabe,Cod_Ope,Nom_Tabela,Chave1,Chave2,Nom_Campo,Des_Campo,
				            Observ,
				            Usuario,Transacao)
	            Values(@CodEstabe, 'I','PMEST',@CodEstabe,@IdSessao,'Cod_Estabe','PR_ConfiguraESTAB',
				            'Atenção: Não foram inseridos registros em PMEST',
					       @Usuario,GetDate() )

	      End

		-- Criar FS_PARAM Se não existir nenhum parametro--
		If (@Opcao = 0 or @Opcao = 3) And Not Exists(Select 1 From FS_PARAM Where Cod_Estabe = @CodEstabe)
	      Begin
			Insert Into FS_PARAM
	           (Cod_Estabe ,Cod_Param
	           ,Tip_Param  ,Val_Param
	           ,Dsc_Param  
	           ,Grp_Param  ,Msk_Param)
	        Select @CodEstabe   ,fs.Cod_Param
	           ,fs.Tip_Param    ,fs.Val_Param
	           ,fs.Dsc_Param    
	           ,fs.Grp_Param    ,fs.Msk_Param
			From FS_PARAM fs
			Where fs.Cod_Estabe = @CodEstabePai
			And Not Exists(Select 1 From FS_PARAM 
				           Where Cod_Estabe = @CodEstabe
				           And Cod_Param = fs.Cod_Param)
			-- AUDITORIA
			Set @RowCount = @@ROWCOUNT
			Set @TotalCount = @TotalCount+@RowCount;
			If @RowCount > 0
				Insert Into AUDIT (Cod_Estabe,Cod_Ope,Nom_Tabela,Chave1,Chave2,Nom_Campo,Des_Campo,
				            Observ,
				            Usuario,Transacao)
	            Values(@CodEstabe, 'I','FS_PARAM',@CodEstabe,@IdSessao,'Cod_Estabe','PR_ConfiguraESTAB',
				            'Inclusão de '+Convert(varchar(20),@RowCount)+' Registros em FS_PARAM',
					       @Usuario,GetDate() )

			If @RowCount = 0
				Insert Into AUDIT (Cod_Estabe,Cod_Ope,Nom_Tabela,Chave1,Chave2,Nom_Campo,Des_Campo,
				            Observ,
				            Usuario,Transacao)
	            Values(@CodEstabe, 'I','FS_PARAM',@CodEstabe,@IdSessao,'Cod_Estabe','PR_ConfiguraESTAB',
				            'Atenção: Não foram inseridos registros em FS_PARAM',
					       @Usuario,GetDate() )
	      End


	    -- Criar MIX de PRODUTOS
	    If (@Opcao = 0 or @Opcao = 4)
	      Begin
			--Depósito PADRÃO

			--Verifica se nao existe cria
		    Select Top 1 @CodDep = Cod_Dep 
			From TBDEP 
			Where Cod_Estabe = @CodEstabe
			Order By Cod_Dep
		    
			If @@ROWCOUNT = 0 
			Begin
				Set @CodDep = IsNull(@CodDep,0) + 1
				Insert Into TBDEP(Cod_Dep,Des_Dep,Cod_Estabe)
				Values (@CodDep,'DEPOSITO PADRÃO',@CodEstabe)
				-- AUDITORIA
				Set @RowCount = @@ROWCOUNT
				Set @TotalCount = @TotalCount+@RowCount;
				If @RowCount > 0
					Insert Into AUDIT (Cod_Estabe,Cod_Ope,Nom_Tabela,Chave1,Chave2,Nom_Campo,Des_Campo,
								Observ,
								Usuario,Transacao)
					Values(@CodEstabe, 'I','TBDEP',@CodEstabe,@CodDep,'Cod_Estabe','PR_ConfiguraESTAB',
								'Inclusão de '+Convert(varchar(20),@RowCount)+' Registros em TBDEP',
							    @Usuario,GetDate() )

				If @RowCount = 0
					Insert Into AUDIT (Cod_Estabe,Cod_Ope,Nom_Tabela,Chave1,Chave2,Nom_Campo,Des_Campo,
								Observ,
								Usuario,Transacao)
					Values(@CodEstabe, 'I','TBDEP',@CodEstabe,@IdSessao,'Cod_Estabe','PR_ConfiguraESTAB',
								'Atenção: Não foram inseridos registros em TBDEP',
							   @Usuario,GetDate() )

			End

			--Criando MIX do estabelecimento novo
			--Copiar do estabelecimento pai - se existir
			IF Exists(Select 1 From PRXES Where Cod_Estabe = @CodEstabePai)
				Insert Into dbo.PRXES
							(Cod_Estabe, Cod_Produt	,Qtd_Transi, Qtd_Fisico				
							,Qtd_Solici, Qtd_Avaria	,Qtd_Reserv, Qtd_Dispon				
							,Qtd_Quaren, Qtd_CrossDock
							,Prc_Venda , Prc_Fabric ,Prc_MaxCon
							,Prc_Pmz   , Prc_Tabela ,Flg_BlqCfv, Flg_BlqCmp
							,Flg_BlqCot, Flg_BlqDsc ,Flg_BlqInfPar, Flg_BlqInfVen
							,Flg_BlqPrp, Flg_BlqVen ,Flg_CesBas, Flg_PlaFatPrcLiq
							,Flg_RegSbtEsp, Flg_UsoExcHsp ,Usuario , Transacao
							,Dat_PrcAtual, Dat_PrcFab, Cod_ClaTri, Cod_OriMer)
				Select       @CodEstabe,p.Codigo    ,0         ,0         
							,0         ,0           ,0         ,0         
							,0         ,0         
							,Prc_Venda =    case when es.Per_AlqIcm=12   then p.Prc_Fabric12
												 when es.Per_AlqIcm=17   then p.Prc_Fabric17
												 when es.Per_AlqIcm=17.5 then p.Prc_Fabric175
												 when es.Per_AlqIcm=18   then p.Prc_Fabric18
												 when es.Per_AlqIcm=19   then p.Prc_Fabric19
												 when es.Per_AlqIcm=20   then p.Prc_Fabric20
												 when es.Per_AlqIcm=21   then p.Prc_Fabric21
												 when es.Per_AlqIcm=22   then p.Prc_Fabric22
												 else e.Prc_Venda
											end
							,Prc_Fabric =   case when es.Per_AlqIcm=12   then p.Prc_Fabric12
												 when es.Per_AlqIcm=17   then p.Prc_Fabric17
												 when es.Per_AlqIcm=17.5 then p.Prc_Fabric175
												 when es.Per_AlqIcm=18   then p.Prc_Fabric18
												 when es.Per_AlqIcm=19   then p.Prc_Fabric19
												 when es.Per_AlqIcm=20   then p.Prc_Fabric20
												 when es.Per_AlqIcm=21   then p.Prc_Fabric21
												 when es.Per_AlqIcm=22   then p.Prc_Fabric22
												 else e.Prc_Fabric
											end
							,Prc_MaxCon =   case when es.Per_AlqIcm=12   then p.Prc_MaxCon12
												 when es.Per_AlqIcm=17   then p.Prc_MaxCon17
												 when es.Per_AlqIcm=17.5 then p.Prc_MaxCon175
												 when es.Per_AlqIcm=18   then p.Prc_MaxCon18
												 when es.Per_AlqIcm=19   then p.Prc_MaxCon19
												 when es.Per_AlqIcm=20   then p.Prc_MaxCon20
												 when es.Per_AlqIcm=21   then p.Prc_MaxCon21
												 when es.Per_AlqIcm=22   then p.Prc_MaxCon22
												 else e.Prc_MaxCon
											end

							,e.Prc_Pmz ,e.Prc_Tabela,e.Flg_BlqCfv,e.Flg_BlqCmp
							,e.Flg_BlqCot,e.Flg_BlqDsc,e.Flg_BlqInfPar,e.Flg_BlqInfVen
							,e.Flg_BlqPrp,e.Flg_BlqVen,e.Flg_CesBas,e.Flg_PlaFatPrcLiq
							,e.Flg_RegSbtEsp,e.Flg_UsoExcHsp, @Usuario ,GetDate()
							,cast( GetDate() as Date ),cast( GetDate() as Date), e.Cod_ClaTri, e.Cod_OriMer
				From PRODU p
				Inner Join PRXES e On e.Cod_Estabe = @CodEstabePai and p.Codigo = e.Cod_Produt
				Inner Join ESTAB es On es.Cod_Estabe = @CodEstabe -- Configuração do novo estabelecimento
				Where p.Codigo not in (Select x.Cod_Produt 
					                   From PRXES x 
									   Where x.Cod_Estabe = @CodEstabe
									   And x.Cod_Produt = p.Codigo)

			/*
			Após conversa com Meire, ficou esclarecido que se não for encontrado o produto no estabelecimento 
			sugerido(Pai) não é para ser importado, principalmente por conta da falta da classificação 
			tributaria, que irá impactarem questões fiscais.
			ELSE
				Insert Into dbo.PRXES
							(Cod_Estabe, Cod_Produt				
							,Qtd_Transi, Qtd_Fisico				
							,Qtd_Solici, Qtd_Avaria				
							,Qtd_Reserv, Qtd_Dispon				
							,Qtd_Quaren, Qtd_CrossDock 
							, Prc_Venda
                            ,Prc_Fabric, Prc_MaxCon							
							,Usuario   , Transacao
							,Dat_PrcAtual, Dat_PrcFab)
				Select       @CodEstabe,p.Codigo  
							,0         ,0         
							,0         ,0         
							,0         ,0         
							,0         ,0
							,Prc_Venda =    case when es.Per_AlqIcm=12   then p.Prc_Fabric12
												 when es.Per_AlqIcm=17   then p.Prc_Fabric17
												 when es.Per_AlqIcm=17.5 then p.Prc_Fabric175
												 when es.Per_AlqIcm=18   then p.Prc_Fabric18
												 when es.Per_AlqIcm=19   then p.Prc_Fabric19
												 else 0
											end
							,Prc_Fabric =   case when es.Per_AlqIcm=12   then p.Prc_Fabric12
												 when es.Per_AlqIcm=17   then p.Prc_Fabric17
												 when es.Per_AlqIcm=17.5 then p.Prc_Fabric175
												 when es.Per_AlqIcm=18   then p.Prc_Fabric18
												 when es.Per_AlqIcm=19   then p.Prc_Fabric19
												 else 0
											end
							,Prc_MaxCon =   case when es.Per_AlqIcm=12   then p.Prc_MaxCon12
												 when es.Per_AlqIcm=17   then p.Prc_MaxCon17
												 when es.Per_AlqIcm=17.5 then p.Prc_MaxCon175
												 when es.Per_AlqIcm=18   then p.Prc_MaxCon18
												 when es.Per_AlqIcm=19   then p.Prc_MaxCon19
												 else 0
											end
							,@Usuario  ,GetDate()
							,cast( GetDate() as Date ),cast( GetDate() as Date )
				From PRODU p
				Inner Join ESTAB es On es.Cod_Estabe = @CodEstabe -- Configuração do novo estabelecimento
				Where p.Codigo not in (Select Distinct x.Cod_Produt 
					                   From PRXES x 
						               Where x.Cod_Estabe = @CodEstabe 
									   And x.Cod_Produt = p.Codigo)
									   
			*/

			-- AUDITORIA
			Set @RowCount = @@ROWCOUNT
			Set @TotalCount = @TotalCount+@RowCount;
			If @RowCount > 0
				Insert Into AUDIT (Cod_Estabe,Cod_Ope,Nom_Tabela,Chave1,Chave2,Nom_Campo,Des_Campo,
				            Observ,
				            Usuario,Transacao)
	            Values(@CodEstabe, 'I','PRXES',@CodEstabe,@IdSessao,'Cod_Estabe','PR_ConfiguraESTAB',
				            'Inclusão de '+Convert(varchar(20),@RowCount)+' Registros em PRXES',
					       @Usuario,GetDate() )
			If @RowCount = 0
				Insert Into AUDIT (Cod_Estabe,Cod_Ope,Nom_Tabela,Chave1,Chave2,Nom_Campo,Des_Campo,
							Observ,
							Usuario,Transacao)
				Values(@CodEstabe, 'I','PRXES',@CodEstabe,@IdSessao,'Cod_Estabe','PR_ConfiguraESTAB',
							'Atenção: Não foram inseridos registros em PRXES',
						   @Usuario,GetDate() )

	      End

		-- Cria/Copia ENXES do estabelecimento pai se não existir --
		If (@Opcao = 0 or @Opcao = 5)
		  Begin
			Insert Into ENXES ( Cod_Estabe,       Num_CgcCpf,       Cod_Client,        Cod_RegTri,    Cod_AgeCob,         Cod_Transp,      Cod_Rota, Cod_EstEnt,
								Cod_EstabeEntida, Cod_IdeEntida,    Des_LayoutPdc,     Des_DirPedPdc, Des_DirPrePdc,      Des_DirNotPdc,
								Des_PrgComPdc,    Des_UltArqPdc,    Dat_UltArqPdc,     Num_SeqArqPdc, Des_EnderecoFtpPdc ,Des_UsuarioFtpPdc,
								Des_SenhaFtpPdc,  Vlr_UltimaFatura, Data_UltimaFatura, Usuario ,      Transacao,          Cod_DisTra,      UF_PlaVei,
								Cod_PlaVei,       Cod_AgePag,       Cod_Vendedor,      Cod_Operador,  Des_FtpUrlPdc,      Des_FtpUsrPdc,   Des_FtpSnhPdc, 
								Flg_BlqEmbDscItePrcUni,             Flg_BlqIncSbtPrc,  Flg_BlqIncSbtPriDup,               Flg_BlqFecVlrPdvNfsSbtEmb,        
								Flg_ImpSbtEmbPrc, Flg_InfXmlSbtEmbPrc,                 Cod_TabPrc,       Cod_TabPrz,       Qtd_PrzMax) 
			Select @CodEstabe,  a.Num_CgcCpf,     a.Cod_Client, a.Cod_RegTri,    a.Cod_AgeCob,       a.Cod_Transp,    a.Cod_Rota,           a.Cod_EstEnt,
								a.Cod_EstabeEntida,a.Cod_IdeEntida,   a.Des_LayoutPdc,    a.Des_DirPedPdc, a.Des_DirPrePdc,      a.Des_DirNotPdc,
								a.Des_PrgComPdc,   a.Des_UltArqPdc,   a.Dat_UltArqPdc,    a.Num_SeqArqPdc, a.Des_EnderecoFtpPdc, a.Des_UsuarioFtpPdc,
								a.Des_SenhaFtpPdc, a.Vlr_UltimaFatura,a.Data_UltimaFatura, @Usuario     , GetDate(),
								a.Cod_DisTra,a.UF_PlaVei, a.Cod_PlaVei,a.Cod_AgePag,a.Cod_Vendedor,
								a.Cod_Operador,a.Des_FtpUrlPdc,a.Des_FtpUsrPdc,a.Des_FtpSnhPdc,a.Flg_BlqEmbDscItePrcUni,a.Flg_BlqIncSbtPrc,
								a.Flg_BlqIncSbtPriDup,a.Flg_BlqFecVlrPdvNfsSbtEmb,a.Flg_ImpSbtEmbPrc,a.Flg_InfXmlSbtEmbPrc,a.Cod_TabPrc,
								a.Cod_TabPrz,a.Qtd_PrzMax
			From ENXES a
			Where Cod_Estabe = @CodEstabePai
					And isnull(a.Num_CgcCpf, '') <> '' -- Evitar erro de violação de chave primaria
					And Not Exists(Select 1 From ENXES b
				           Where b.Cod_Estabe = @CodEstabe
				           And b.Num_CgcCpf = a.Num_CgcCpf
						   And b.Cod_Client = a.Cod_Client)

			-- Campos complementares Clientes
			Update e
              Set e.Cod_Client = c.Codigo
            From ENXES e
			Inner join CLIEN c On c.Cgc_Cpf = E.Num_CgcCpf
			Where e.Cod_Estabe = @CodEstabe
			And Not Exists( Select 1 From ENXES x Where 
			                    x.Cod_Estabe = @CodEstabe
			                And x.Num_CgcCpf = c.Cgc_Cpf
			                And x.Cod_Client = c.Codigo)

			-- Campos complementares Fornecedores
			Update e
			 Set e.Cod_CadFor = f.Codigo
            From ENXES e
			Inner join FORNE f On f.Cgc_Cpf = E.Num_CgcCpf
			Where e.Cod_Estabe = @CodEstabe
			-- Campos complementares Transportadoras
			Update e
			 Set e.Cod_CadTra = t.Codigo
            From ENXES e
			Inner join TRANS t On t.Cgc_Cpf = E.Num_CgcCpf
			Where e.Cod_Estabe = @CodEstabe

			-- AUDITORIA
			Set @RowCount = @@ROWCOUNT
			Set @TotalCount = @TotalCount+@RowCount;
			If @RowCount > 0
				Insert Into AUDIT (Cod_Estabe,Cod_Ope,Nom_Tabela,Chave1,Chave2,Nom_Campo,Des_Campo,
				            Observ,
				            Usuario,Transacao)
	            Values(@CodEstabe,'I','ENXES',@CodEstabe,@IdSessao,'Cod_Estabe','PR_ConfiguraESTAB',
				            'Inclusão de '+Convert(varchar(20),@RowCount)+' Registros em ENXES',
					       @Usuario,GetDate() )
			If @RowCount = 0
				Insert Into AUDIT (Cod_Estabe,Cod_Ope,Nom_Tabela,Chave1,Chave2,Nom_Campo,Des_Campo,
							Observ,
							Usuario,Transacao)
				Values(@CodEstabe, 'I','ENXES',@CodEstabe,@IdSessao,'Cod_Estabe','PR_ConfiguraESTAB',
							'Atenção: Não foram inseridos registros em ENXES',
						   @Usuario,GetDate() )
	      End


		Commit Transaction		
	End Try
	Begin Catch
	    Select @ErroMsg = ERROR_MESSAGE()
	    Rollback
		RAISERROR (@ErroMsg,1, 1) 
	End Catch
    

  	FETCH NEXT FROM Table_Cr INTO @CodEstabe
END

CLOSE Table_Cr
DEALLOCATE Table_Cr    
RETURN @TotalCount

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_Carga_Fiscal_F02]
		@CodEstabe int,
        @Dat_Ini SmallDateTime,
        @Dat_Fim SmallDateTime

AS

--Carga Nota Fiscal
Set DateFormat YMD
Declare @Num_Cnpj Varchar(14)


Select @Num_Cnpj = Num_Cnpj From ESTAB Where Cod_Estabe = @CodEstabe

--Cabeçalho C100
Declare @Cod_Estabe Int,
        @Num_Protoc Int,
        @Tip_EntSai Varchar(3),
        @CodRegOri Int,
        @Dat_Movime SmallDateTime,
		@IND_OPER Int,
		@IND_EMIT Int,
		@COD_PART Varchar(60),
		@COD_MOD Varchar(2)  ,
        @COD_SIT Varchar(2) ,
        @SER Varchar(3) ,
        @NUM_DOC Varchar(9) , 
        @CHV_NFE Varchar(44) ,
        @DT_DOC Smalldatetime ,
        @DT_E_S Smalldatetime ,
        @VL_DOC Numeric(18,2),
        @IND_PGTO Int ,
        @VL_DESC Numeric(18,2) ,
        @VL_ABAT_NT Numeric(18,2) ,
        @VL_MERC Numeric(18,2) ,
        @IND_FRT Int ,
        @VL_FRT Numeric(18,2) ,
        @VL_SEG Numeric(18,2) ,
        @VL_OUT_DA Numeric(18,2) ,
        @VL_BC_ICMS Numeric(18,2) ,
        @VL_ICMS Numeric(18,2) ,
        @VL_BC_ICMS_ST Numeric(18,2) ,
        @VL_ICMS_ST Numeric(18,2) ,
        @VL_IPI Numeric(18,2) ,
        @VL_PIS Numeric(18,2) ,
        @VL_COFINS Numeric(18,2) ,
        @VL_PIS_ST Numeric(18,2) ,
        @VL_COFINS_ST Numeric(18,2)

--Itens/Totalizador C170/190
Declare @TableProdu Table( cProd int,cEAN varchar(14),NCM varchar(20),Cod_GrpPrc Varchar(10),CFOP int, Tip_Por344 varchar(2), xProd varchar(60), infAdProd varchar(500),uCom varchar(3),  
                           qCom int,vUnCom numeric(18,8),vProd numeric(18,8),vDesc numeric(18,8),Vlr_LiqMer numeric(18,8),Vlr_BasSbtRes numeric(18,8),Vlr_SbtRes numeric(18,8),  
                           nLote varchar(20),dVal smalldatetime,dFab smalldatetime,vFrete numeric(18,8),vSeg numeric(18,8),vOutro numeric(18,8),uTrib varchar(10),qTrib varchar(10),  
                           vUnTrib numeric(18,8), Orig varchar(2), CST_Icm varchar(2), CSOSN_Icm varchar(3),modBC varchar(1),pRedBC numeric(8,4),vBC numeric(18,8),  
                           pICMS numeric(8,4), vICMS numeric(18,8), vBCSTRet numeric(18,8), vICMSSTRet numeric(18,8), modBCST varchar(1),pMVAST numeric(8,4), pRedBCST numeric(8,4),  
                           vBCST numeric(18,4),pICMSST numeric(8,4), vICMSST numeric(18,8), CST_Ipi varchar(2),vBCIPI numeric(18,8),pIPI numeric(8,4),vIPI numeric(18,8),  
                           CST_Pis varchar(2), Vlr_BasPis numeric(18,8), Alq_Pis numeric(8,4), Vlr_Pis numeric(18,8), CST_Cofins varchar(2), Vlr_BasCofins numeric(18,8),  
                           Alq_Cofins numeric(8,4), Vlr_Cofins numeric(18,8), vPMC numeric(18,8), Prc_Fabric numeric(18,8), CEST varchar(7),vBCUFDest Numeric(18,8),pFCPUFDest Numeric(18,4),
						   pICMSUFDest Numeric(18,4),pICMSInter Numeric(18,4),pICMSInterPart Numeric(18,4),vFCPUFDest Numeric(18,4),vICMSUFDest Numeric(18,4),vICMSUFRemet Numeric(18,4), xPed Varchar(100))

Declare @NUM_ITEM Int , 
        @COD_ITEM Varchar(60) ,
        @DESCR_COMPL Varchar(100),
        @QTD Int ,
        @UNID Varchar(6) ,
        @VL_ITEM Numeric(18,2) ,
        @VL_DESCPrd Numeric(18,2) ,
        @IND_MOV Int ,
        @CST_ICMS Varchar(3) , 
        @CFOP Varchar(4) , 
        @COD_NAT Varchar(10) ,
        @VL_BC_ICMSPrd Numeric(18,2) ,
        @ALIQ_ICMS Numeric(18,2) , 
        @VL_ICMSPrd Numeric(18,2) , 
        @VL_BC_ICMS_STPrd Numeric(18,2) ,  
        @ALIQ_ST Numeric(18,2) ,
        @VL_ICMS_STPrd Numeric(18,2) ,
        @IND_APUR Int ,
        @CST_IPI Varchar(2) ,
        @COD_ENQ Varchar(3) , 
        @VL_BC_IPI Numeric(18,2) ,
        @ALIQ_IPI Numeric(18,2) ,
        @VL_IPIPrd Numeric(18,2) , 
        @CST_PIS Varchar(2) ,
        @VL_BC_PIS Numeric(18,2) ,
        @ALIQ_PIS_PERCENT Numeric(18,2) ,
        @QUANT_BC_PIS Int ,
        @ALIQ_PIS_REAIS Numeric(18,2) , 
        @VL_PISPrd Numeric(18,2) ,
        @CST_COFINS Varchar(2) ,
        @VL_BC_COFINS Numeric(18,2),
        @ALIQ_COFINS_PERCENT Numeric(18,2) ,
        @QUANT_BC_COFINS Int ,
        @ALIQ_COFINS_REAIS Numeric(18,2) ,
        @VL_COFINSPrd Numeric(18,2) ,
        @COD_CTA Int ,
        @VOutro Numeric(18,2) ,
        @pRedBC Numeric(18,2) ,
		@VL_OPR Numeric(18,2) ,
		@VL_RED_BC Numeric(18,2)
        
Declare CargaNfe Cursor Local Fast_Forward For

Select N.Cod_Estabe,
       Protocolo,
	   'E' Tip_EntSai,
       Dat_Movimento Dat_Movime,
       '0' IND_OPER,
	   '1' IND_EMIT,
	   Cgc_Cpf as COD_PART, 
	   Cod_ModDoc COD_MOD,
	   '00' COD_SIT,
	   Serie SER, 
	   Numero NUM_DOC,
	   Chv_Acesso CHV_NFE,
	   Dat_Emissao DT_DOC, 
       Dat_Movimento DT_E_S,
	   Vlr_Nota VL_DOC,
	   '0'  IND_PGTO,         
       Vlr_Desconto VL_DESC, 
	   0 VL_ABAT_NT,
	   Vlr_Mercadoria VL_MERC,
	   9 IND_FRT, 
	   Vlr_Frete VL_FRT,
	   Vlr_Seguro VL_SEG,       
       Vlr_Despesas VL_OUT_DA,
	   Vlr_BasIcmsTri VL_BC_ICMS,        
       Vlr_IcmsTri VL_ICMS, 
	   Vlr_BasIstFon VL_BC_ICMS_ST, 
       Vlr_IstFon VL_ICMS_ST, 
	   Vlr_Ipi VL_IPI,    
       Vlr_Pis VL_PIS, 
	   Vlr_Cofins VL_COFINS,
	   0 VL_PIS_ST,
	   0 VL_COFINS_ST 
From NFECB N
     Inner Join ESTAB E On (E.Cod_Estabe = N.Cod_Estabe)    
Where N.Cod_Estabe = @CodEstabe
And Dat_Movimento Between @Dat_Ini And @Dat_Fim 
And Status = 'F' 
And Num_Cnpj = @Num_Cnpj 
Union All
Select  N.Cod_Estabe,
        Num_Nota Num_Protoc,
        'S' Tip_EntSai,
		Dat_Emissao Dat_Movime, 
       '1' IND_OPER,
	   '0' IND_EMIT,
	   Cgc COD_PART, 
	   Cod_ModDoc COD_MOD,
	   '00' COD_SIT,
	   Ser_Nota SER,                                 
       Num_Nota NUM_DOC,
	   Chv_Acesso CHV_NFE,
	   Dat_Emissao DT_DOC, 
	   Dat_Emissao DT_E_S,
	   Vlr_TotalNota VL_DOC,
	   '0'  IND_PGTO,                 
       Vlr_DescontoCom VL_DESC,
	   0 VL_ABAT_NT,
	   Vlr_LiqItens VL_MERC,
	   9 IND_FRT, 
	   Vlr_Frete VL_FRT,
	   Vlr_Seguro VL_SEG,                
       Vlr_OutDsp VL_OUT_DA,
	   Vlr_BasIcmsTri VL_BC_ICMS,          
       Vlr_IcmsTri VL_ICMS,
	   Vlr_BasSubsTrib VL_BC_ICMS_ST,          
       Vlr_SubsTrib VL_ICMS_ST,
	   Vlr_Ipi VL_IPI,                            
       Vlr_Pis VL_PIS,
	   Vlr_Cofins VL_COFINS,             
       0 VL_PIS_ST, 
	   0 VL_COFINS_ST 
From NFSCB N
     Inner Join ESTAB E On (E.Cod_Estabe = N.Cod_Estabe)    
Where N.Cod_Estabe = @CodEstabe
And Dat_Emissao Between @Dat_Ini And @Dat_Fim 
And (Status = 'F') 
And Ser_Nota <> 'ECF'
And Num_Cnpj = @Num_Cnpj 
 
if Exists(Select 1 From FC_C100 Where Dat_Movime Between @Dat_Ini And @Dat_Fim)
  begin
	Delete From a
	From FC_C170 a
	Inner Join FC_C100 b On a.Num_Cnpj = b.Num_Cnpj and a.Cod_RegOriC100 =  b.Cod_RegOriC100
	Where b.Num_Cnpj = @Num_Cnpj And b.Dat_Movime Between @Dat_Ini And @Dat_Fim

	Delete From a
	From FC_C190 a
	Inner Join FC_C100 b On a.Num_Cnpj = b.Num_Cnpj and a.Cod_RegOriC100 =  b.Cod_RegOriC100
	Where b.Num_Cnpj = @Num_Cnpj And b.Dat_Movime Between @Dat_Ini And @Dat_Fim
	
	Delete from FC_C100 
	Where Num_Cnpj = @Num_Cnpj And Dat_Movime Between @Dat_Ini And @Dat_Fim

	Delete from FC_0190
	Where Num_Cnpj = @Num_Cnpj And Dat_Movime Between @Dat_Ini And @Dat_Fim
  end

Open CargaNfe
Fetch Next From CargaNfe
Into @Cod_Estabe,@Num_Protoc,@Tip_EntSai,@Dat_Movime,@IND_OPER,@IND_EMIT,@COD_PART,@COD_MOD,@COD_SIT,@SER,@NUM_DOC,
     @CHV_NFE,@DT_DOC,@DT_E_S,@VL_DOC,@IND_PGTO,@VL_DESC,@VL_ABAT_NT,@VL_MERC,@IND_FRT,@VL_FRT,@VL_SEG,
	 @VL_OUT_DA,@VL_BC_ICMS,@VL_ICMS,@VL_BC_ICMS_ST,@VL_ICMS_ST,@VL_IPI,@VL_PIS,@VL_COFINS,@VL_PIS_ST,
	 @VL_COFINS_ST

While @@FETCH_STATUS = 0
  Begin
    Set @CodRegOri = (Select IsNull(MAX(Cod_RegOriC100),0) + 1 Cod_RegOriC100 From FC_C100 Where Num_Cnpj = @Num_Cnpj)
	Set @Num_Item = 0

    Insert Into FC_C100 Values(@Num_Cnpj,@CodRegOri,@Dat_Movime,@IND_OPER,@IND_EMIT,@COD_PART,@COD_MOD,@COD_SIT,@SER,@NUM_DOC,
                               @CHV_NFE,@DT_DOC,@DT_E_S,@VL_DOC,@IND_PGTO,@VL_DESC,@VL_ABAT_NT,@VL_MERC,@IND_FRT,@VL_FRT,@VL_SEG,
	                           @VL_OUT_DA,@VL_BC_ICMS,@VL_ICMS,@VL_BC_ICMS_ST,@VL_ICMS_ST,@VL_IPI,@VL_PIS,@VL_COFINS,@VL_PIS_ST,
	                           @VL_COFINS_ST)

	
  Insert Into @TableProdu exec PR_RetornaItensNF @Cod_Estabe,@Num_Protoc,@SER,@Tip_EntSai

  Declare CargaNfeProdu Cursor Local Fast_Forward For  
		
  Select cProd,xProd,qCom,uCom,vProd,vDesc,0 IND_MOV,orig + CST_Icm CST_ICMS,CFOP,'' as COD_NAT,
         vBC,pIcms,vICMS,VBCST,pICMSST,vICMSST,0 IND_APUR,Cst_Ipi,'' as COD_ENQ,vBCIPI,pIPI,vIPI,Cst_PIS,
	     vlr_BasPis,Alq_Pis,0 QUANT_BC_PIS,0 ALIQ_PIS_REAIS,Vlr_Pis,Cst_Cofins,vlr_BasCofins,Alq_Cofins,
	     0 QUANT_BC_COFINS, 0 ALIQ_COFINS_REAIS,Vlr_Cofins,0 COD_CTA,VOutro, pRedBC   
  From @TableProdu
   
  Open CargaNfeProdu
  Fetch Next From CargaNfeProdu
  Into @COD_ITEM,@DESCR_COMPL,@QTD,@UNID,@VL_ITEM,@VL_DESCPrd,@IND_MOV,@CST_ICMS, 
       @CFOP,@COD_NAT,@VL_BC_ICMSPrd,@ALIQ_ICMS,@VL_ICMSPrd,@VL_BC_ICMS_STPrd,  
       @ALIQ_ST, @VL_ICMS_STPrd, @IND_APUR, @CST_IPI, @COD_ENQ,@VL_BC_IPI,
       @ALIQ_IPI,@VL_IPIPrd,@CST_PIS,@VL_BC_PIS,@ALIQ_PIS_PERCENT,
       @QUANT_BC_PIS,@ALIQ_PIS_REAIS,@VL_PISPrd,@CST_COFINS,
       @VL_BC_COFINS,@ALIQ_COFINS_PERCENT,@QUANT_BC_COFINS,
       @ALIQ_COFINS_REAIS,@VL_COFINSPrd,@COD_CTA,@VOutro, @pRedBC

  While @@FETCH_STATUS = 0
    Begin
	  Set @Num_Item = @Num_Item + 1
	  Insert Into FC_C170 Values(@Num_Cnpj,@CodRegOri,@Num_Item,@COD_ITEM,@DESCR_COMPL,@QTD,@UNID,@VL_ITEM,@VL_DESCPrd,@IND_MOV,@CST_ICMS, 
                                 @CFOP,@COD_NAT,@VL_BC_ICMSPrd,@ALIQ_ICMS,@VL_ICMSPrd,@VL_BC_ICMS_STPrd,  
                                 @ALIQ_ST, @VL_ICMS_STPrd, @IND_APUR, @CST_IPI, @COD_ENQ,@VL_BC_IPI,
                                 @ALIQ_IPI,@VL_IPIPrd,@CST_PIS,@VL_BC_PIS,@ALIQ_PIS_PERCENT,
                                 @QUANT_BC_PIS,@ALIQ_PIS_REAIS,@VL_PISPrd,@CST_COFINS,
                                 @VL_BC_COFINS,@ALIQ_COFINS_PERCENT,@QUANT_BC_COFINS,
                                 @ALIQ_COFINS_REAIS,@VL_COFINSPrd,@COD_CTA,@VOutro, @pRedBC)
	                                     
	  Fetch Next From CargaNfeProdu
	  Into @COD_ITEM,@DESCR_COMPL,@QTD,@UNID,@VL_ITEM,@VL_DESCPrd,@IND_MOV,@CST_ICMS, 
           @CFOP,@COD_NAT,@VL_BC_ICMSPrd,@ALIQ_ICMS,@VL_ICMSPrd,@VL_BC_ICMS_STPrd,  
           @ALIQ_ST, @VL_ICMS_STPrd, @IND_APUR, @CST_IPI, @COD_ENQ,@VL_BC_IPI,
           @ALIQ_IPI,@VL_IPIPrd,@CST_PIS,@VL_BC_PIS,@ALIQ_PIS_PERCENT,
           @QUANT_BC_PIS,@ALIQ_PIS_REAIS,@VL_PISPrd,@CST_COFINS,
           @VL_BC_COFINS,@ALIQ_COFINS_PERCENT,@QUANT_BC_COFINS,
           @ALIQ_COFINS_REAIS,@VL_COFINSPrd,@COD_CTA,@VOutro, @pRedBC
	End
             
	Delete From @TableProdu
	Close CargaNfeProdu
    Deallocate CargaNfeProdu  
	    

	--Carga C190 Totalizador
	    
    Declare CargaNfeTotalizador Cursor Local Fast_Forward  For

	Select CST_ICMS, 
	       CFOP,
	       ALIQ_ICMS, 
	       SUM(VL_Opr)VL_Opr,       
	       SUM(VL_BC_ICMS)VL_BC_ICMS, 
           SUM(VL_ICMS)VL_ICMS,       
           SUM(VL_BC_ICMS_ST)VL_BC_ICMS_ST, 
           SUM(VL_ICMS_ST)VL_ICMS_ST, 
           SUM(PRedBC)PRedBC,         
           SUM(VL_IPI)VL_IPI          
    From (  
        Select CST_ICMS, 
               CFOP, 
               Case When CST_ICMS Like '%60%' then 0 
                    When CST_ICMS Like '%40%' then 0 
                    When CST_ICMS Like '%41%' then 0 
                    Else ALIQ_ICMS 
               End ALIQ_ICMS, 
              (VL_ITEM + VL_ICMS_ST + vOutro + VL_IPI - VL_DESC )VL_Opr, 
               VL_BC_ICMS,  
               VL_ICMS,     
               VL_BC_ICMS_ST, 
               VL_ICMS_ST,    
               PRedBC,        
                VL_IPI         
        From FC_C170        
        where Cod_RegOriC100 = @CodRegOri
        And Num_Cnpj = @Num_Cnpj ) as Auxiliar 
        Group By CST_ICMS, 
                 CFOP,  
                 ALIQ_ICMS
				 
    Open CargaNfeTotalizador
    Fetch Next From CargaNfeTotalizador
	Into @CST_ICMS,@CFOP,@ALIQ_ICMS,@VL_OPR,
         @VL_BC_ICMS,@VL_ICMSPrd,@VL_BC_ICMS_STPrd,@VL_ICMS_STPrd, 
         @VL_RED_BC,@VL_IPIPrd

    While @@FETCH_STATUS = 0
	  Begin
	    Insert Into FC_C190 Values(@Num_Cnpj,@CodRegOri,@CST_ICMS,@CFOP,@ALIQ_ICMS,@VL_OPR,
                                   @VL_BC_ICMSPrd,@VL_ICMSPrd,@VL_BC_ICMS_STPrd,@VL_ICMS_STPrd, 
                                   @VL_RED_BC,@VL_IPI,'')

		Fetch Next From CargaNfeTotalizador
	    Into @CST_ICMS,@CFOP,@ALIQ_ICMS,@VL_OPR,
             @VL_BC_ICMS,@VL_ICMS,@VL_BC_ICMS_ST,@VL_ICMS_ST, 
             @VL_RED_BC,@VL_IPI
		 
	  End  
	    
	    Close CargaNfeTotalizador
        Deallocate CargaNfeTotalizador 

		Fetch Next From CargaNfe
        Into @Cod_Estabe,@Num_Protoc,@Tip_EntSai,@Dat_Movime,@IND_OPER,@IND_EMIT,@COD_PART,@COD_MOD,@COD_SIT,@SER,@NUM_DOC,
             @CHV_NFE,@DT_DOC,@DT_E_S,@VL_DOC,@IND_PGTO,@VL_DESC,@VL_ABAT_NT,@VL_MERC,@IND_FRT,@VL_FRT,@VL_SEG,
	         @VL_OUT_DA,@VL_BC_ICMS,@VL_ICMS,@VL_BC_ICMS_ST,@VL_ICMS_ST,@VL_IPI,@VL_PIS,@VL_COFINS,@VL_PIS_ST,
	         @VL_COFINS_ST
 End   
    
 Close CargaNfe
 Deallocate CargaNfe  
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ExcluiRECEB]
@PCodEstabe int, 
@PCodRec Int,
@PMsgErr varchar(80) output

AS

SET NOCOUNT ON

Set @PMsgErr = ''

-- verifica se existe baixa com data de fechamento de comissoes registrada
if Exists(Select 1
          From BXREC 
          Where Cod_Estabe = @PCodEstabe
          And Cod_Rec = @PCodRec
          And Dat_FecCom is not null)
  Set @PMsgErr = 'Existe pelo menos 1 recebimento com comissão fechada'

-- verifica se existe cheque compensado
if (@PMsgErr = '') and
   Exists(Select 1
          From CHEQU 
          Where Cod_Estabe = @PCodEstabe
          And Cod_Rec = @PCodRec
          And Status = '1')
  Set @PMsgErr = 'Existe pelo menos 1 cheque compensado'

-- verifica se o vale de vendedor está quitado
if (@PMsgErr = '') and
   Exists(Select 1
          From VALES 
          Where Cod_Estabe = @PCodEstabe
          And Cod_CtrLanAut = 'BXL' 
          And Num_CtrLanAut = @PCodRec
          And Dat_Pagame is Not Null)
  Set @PMsgErr = 'Existe pelo menos 1 Vale vinculado a este lote que já está pago'


if @PMsgErr =  ''
BEGIN
  BEGIN TRANSACTION 

  Declare @CodDoc int, 
          @CodLan int, 
          @IdTransacao int 

  -- Exclui lancamentos financeiros e gerenciais
  DECLARE Table_Cr Cursor Local Fast_Forward For 
    Select Cod_Lancam 
    From LANCB 
    Where Cod_Estabe = @PCodEstabe 
    And Cod_Rec = @PCodRec 
  OPEN Table_Cr 
  FETCH NEXT FROM Table_Cr INTO @CodLan 
  WHILE @@FETCH_STATUS = 0 
  BEGIN 
    Exec PR_CancelaBaixasLANCB @PCodEstabe, @CodLan 

    Delete From LANIT 
      Where Cod_Estabe = @PCodEstabe 
      And Cod_Lancam = @CodLan 

    Delete From LANCB 
      Where Cod_Estabe = @PCodEstabe 
      And Cod_Lancam = @CodLan 

    FETCH NEXT FROM Table_Cr INTO @CodLan 
  END 
  CLOSE Table_Cr 
  DEALLOCATE Table_Cr 

  -- exclui baixas por pagamentos e lançamentos gerenciais pendentes (depositos)
  DECLARE Table_Cr Cursor Local Fast_Forward For 
    Select Cod_Documento, Cod_Lancamento, Id_Transacao  
    From BXREC
    Where Cod_Estabe = @PCodEstabe  
    And Cod_Rec = @PCodRec 
  OPEN Table_Cr 
  FETCH NEXT FROM Table_Cr INTO @CodDoc, @CodLan, @IdTransacao 
  WHILE @@FETCH_STATUS = 0 
  BEGIN 
    if (@IdTransacao > 0) and
       Exists(Select 1 From PCMOV 
              Where Cod_Estabe = @PCodEstabe and Nom_Tabela = 'BXREC'
              and Tip_Docume = 'RT' and Id_Transacao = @IdTransacao) 
      Exec PR_ExcluiTransacoesPCMOV @PCodEstabe, @IdTransacao 

    Delete From BXREC 
    Where Cod_Estabe = @PCodEstabe 
    And Cod_Documento = @CodDoc  
    And Cod_Lancamento = @CodLan 

    Update CTREC 
      Set Vlr_Saldo = Vlr_Saldo + 0.00 
    Where Cod_Estabe = @PCodEstabe 
    And Cod_Documento = @CodDoc 

    FETCH NEXT FROM Table_Cr INTO @CodDoc, @CodLan, @IdTransacao 
  END 
  CLOSE Table_Cr 
  DEALLOCATE Table_Cr 

/*
  -- nao faz sentido: o cheque era vinculado e apos o cancelamento do lote o cheque continua a existir, sem vinculo ....
  -- atualiza recebimento no cheque vinculado a um titulo
  Update CHEQU 
    Set Cod_Rec = -1 
  Where IsNull(Cod_DocRel,0) > 0 
  And Cod_Rec = @PCodRec 
*/

  -- exclui cheques relacionados:
  Delete From CHEQU 
  Where Cod_Estabe = @PCodEstabe 
  And IsNull(Cod_DocRel,0) = 0 
  And Cod_Rec = @PCodRec 

  -- exclui depósitos relacionados
  Declare @Val_Utilizado Numeric(18,4)
  Declare Table_Cr Cursor Local Fast_Forward For 
    Select Cod_Lancam, Val_Utilizado 
    From DPXLT 
    Where Cod_Estabe = @PCodEstabe 
    And Cod_Rec = @PCodRec 
  OPEN Table_Cr 
  FETCH NEXT FROM Table_Cr INTO @CodLan, @Val_Utilizado 
  WHILE @@FETCH_STATUS = 0 
  BEGIN 
    Update LANCB 
      Set Val_Saldo = Val_Saldo + @Val_Utilizado 
    Where Cod_Estabe = @PCodEstabe 
    And Cod_Lancam = @CodLan 
    FETCH NEXT FROM Table_Cr INTO @CodLan, @Val_Utilizado 
  END 
  CLOSE Table_Cr 
  DEALLOCATE Table_Cr 
  
  Delete From DPXLT 
  Where Cod_Estabe = @PCodEstabe 
  And Cod_Rec = @PCodRec

  -- exclui vales relacionados
  Declare @CodVale int 
  Declare Table_Cr Cursor Local Fast_Forward For 
    Select Cod_Vale, Val_Utilizado 
    From CRXLT 
    Where Cod_Estabe = @PCodEstabe 
    And Cod_Rec = @PCodRec 
  OPEN Table_Cr 
  FETCH NEXT FROM Table_Cr INTO @CodVale, @Val_Utilizado 
  WHILE @@FETCH_STATUS = 0 
  BEGIN 
    Update VALES 
      Set Val_Saldo = Val_Saldo + @Val_Utilizado 
    Where Cod_Estabe = @PCodEstabe 
    And Cod_Vale = @CodVale 
    FETCH NEXT FROM Table_Cr INTO @CodVale, @Val_Utilizado
  END
  CLOSE Table_Cr
  DEALLOCATE Table_Cr
  
  Delete From CRXLT 
  Where Cod_Estabe = @PCodEstabe 
  And Cod_Rec = @PCodRec

  -- exclui vales de representantes relacionados
  Delete From VALES 
  Where Cod_Estabe = @PCodEstabe
  And Cod_CtrLanAut = 'BXL'
  And Num_CtrLanAut = @PCodRec

  -- exclui cabecalho do recebimento
  Delete From RECEB
  Where Cod_Estabe = @PCodEstabe
  And Cod_Rec = @PCodRec

  COMMIT TRANSACTION
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ExcluiLancPCMOV_LANCB]
@CodEstabe int,
@CodLanFin int

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

BEGIN TRANSACTION

if Exists(Select Cod_Lancam From LANCB Where Cod_Estabe = @CodEstabe And Cod_Lancam = @CodLanFin)
  begin
    Declare @la_TipLan varchar(2),
            @la_CodRec int,
            @WIdTransacao int,
            @cr_ValVal numeric(18,4), 
            @cr_CodLan int, 
            @cr_DatLan smalldatetime
  
    Select @la_TipLan = Tip_Lancam,
           @la_CodRec = ISNULL(Cod_Rec,0),
           @WIdTransacao = ISNULL(Id_Transacao,0)
      From LANCB
      Where Cod_Estabe = @CodEstabe 
      And Cod_Lancam = @CodLanFin

    -- exclui transacoes vinculadas a LANCB      
    if @WIdTransacao > 0
      begin
        Exec PR_ExcluiTransacoesPCMOV @CodEstabe, @WIdTransacao
        if (@@error <> 0)
          begin
            Rollback Transaction
            Return
          end
      end  -- if @WIdTransacao > 0
      
    -- exclui transacoes vinculadas a LANIT      
    if Exists(Select 1 From LANIT Where Cod_Estabe = @CodEstabe And Cod_Lancam = @CodLanFin And ISNULL(Id_Transacao,0) > 0)
      begin
        Declare LANIT_Cr Cursor Local Fast_Forward For 

          Select Id_Transacao
            From LANIT
            Where Cod_Estabe = @CodEstabe 
            And Cod_Lancam = @CodLanFin
            And ISNULL(Id_Transacao,0) > 0

        Open LANIT_Cr
        Fetch Next From LANIT_Cr Into @WIdTransacao
        While @@FETCH_STATUS = 0
          begin
            Exec PR_ExcluiTransacoesPCMOV @CodEstabe, @WIdTransacao
            if (@@error <> 0)
              begin
                Rollback Transaction
                Return
              end
                
            Fetch Next From LANIT_Cr Into @WIdTransacao
          end
        Close LANIT_Cr
        Deallocate LANIT_Cr
    end  -- if Exists(Select 1 From LANIT Where Cod_Estabe = @CodEstabe And Cod_Lancam = @CodLanFin And ISNULL(Id_Transacao,0) > 0)
    
    -- exclui transacoes vinculadas a RECEB      
    if @la_CodRec > 0
      begin

        -- exclui lançamentos gerenciais da conta financeira dos vales de vendedores
        Declare VALES_Cr Cursor Local Fast_Forward For 
            
          Select v.Val_Vale, l.Cod_Lancam, l.Dat_Lancam
            From VALES v Inner Join 
                 LANCB l on v.Cod_Estabe = l.Cod_Estabe and v.Cod_Lancam = l.Cod_Lancam
            Where v.Cod_Estabe = @CodEstabe 
            And v.Cod_CtrLanAut = 'BXL'
            And v.Num_CtrLanAut = @la_CodRec

        Open VALES_Cr
          
        Fetch Next From VALES_Cr Into @cr_ValVal, @cr_CodLan, @cr_DatLan

        While @@FETCH_STATUS = 0
          begin
            -- seleciona transacoes envolvidas   
            Declare PCMOV_Cr Cursor Local Fast_Forward For 
            
              Select Id_Transacao
                From PCMOV
                Where Nom_Tabela = 'LANCB'
                And ((Tip_Docume = 'PA') or (Tip_Docume = 'RA'))
                And Dat_Movime = @cr_DatLan 
                And Cod_Estabe = @CodEstabe
                And Cod_Lancam = @cr_CodLan
                And ABS(ROUND(Val_Movime,2)) = ABS(ROUND(@cr_ValVal,2))

            Open PCMOV_Cr
            Fetch Next From PCMOV_Cr Into @WIdTransacao
            While @@FETCH_STATUS = 0
              begin
                Exec PR_ExcluiTransacoesPCMOV @CodEstabe, @WIdTransacao
                if (@@error <> 0)
                  begin
                    Rollback Transaction
                    Return
                  end
                Fetch Next From PCMOV_Cr Into @WIdTransacao
              end

            Close PCMOV_Cr
            Deallocate PCMOV_Cr

            Fetch Next From VALES_Cr Into @cr_ValVal, @cr_CodLan, @cr_DatLan
          end

        Close VALES_Cr
        Deallocate VALES_Cr

        -- exclui lançamentos gerenciais dos vales de credito de clientes
        Declare PCMOV_Cr Cursor Local Fast_Forward For 
            
          Select Id_Transacao
            From PCMOV
            Where Nom_Tabela = 'CRXLT'
            And Cod_Estabe = @CodEstabe
            And Num_Docume = @la_CodRec

        Open PCMOV_Cr
          
        Fetch Next From PCMOV_Cr Into @WIdTransacao

        While @@FETCH_STATUS = 0
          begin
            Exec PR_ExcluiTransacoesPCMOV @CodEstabe, @WIdTransacao
            if (@@error <> 0)
              begin
                Rollback Transaction
                Return
              end
            Fetch Next From PCMOV_Cr Into @WIdTransacao
          end

        Close PCMOV_Cr
        Deallocate PCMOV_Cr

      end  -- if @la_CodRec > 0
      
  end
  
COMMIT TRANSACTION
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ExcluiCancelaPDVLT]
@PCodEstabe int,
@PNumPdv int,
@PNomUsu varchar(25)

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

Declare @MsgErr varchar(800),
        @cb_Status1 varchar(1),
        @cb_Status2 varchar(1),
        @FlgIntWms bit = 0,
        @StaIntWms varchar(1),
		@FlgPodeCancelar bit,
		@FlgAtuQtdSolici bit

Select @cb_Status1 = Status1,
       @cb_Status2 = Status2,
       @StaIntWms = IsNull(Sta_IntWms,'')	        
  From PDVCB
 Where Cod_Estabe = @PCodEstabe
   And Numero = @PNumPdv

Select @FlgIntWms = IsNull(FlgIntegrWmsExt,0) 
  From PMEST 
 Where Cod_Estabe = @PCodEstabe

Set @MsgErr = ''

if not Exists(Select 1
                From TBZON z 
                     inner join PMEST p on z.Cod_Estabe = p.Cod_Estabe and z.Cod_Zon = p.CodZonCan 
               Where z.Cod_Estabe = @PCodEstabe
                 And dbo.FN_TipLocEnd(z.Cod_Estabe, z.Cod_Dep, z.Num_RuaIni) = 'X'
                 And z.Cod_Dep > 0 And z.Num_RuaIni > 0)
  Set @MsgErr = 'Zona de Quarentena(cancelamentos) não configurada ou inválida'
else
if @cb_Status1 = 'C'
  Set @MsgErr = 'Pediddo já cancelado'
else
if @cb_Status2 = 'N'
  Set @MsgErr = 'Pediddo já faturado'
else
if not Exists(Select 1 From PDVLT Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @PNumPdv)
  Set @MsgErr = 'Pediddo não solicitou lotes'
else
if not ((@cb_Status1 = 'P') and (@cb_Status2 = 'F'))
  Set @MsgErr = 'Pediddo não nã está pendente/fechado'


if @MsgErr <> ''
  RAISERROR(@MSgErr,16,1)
else
BEGIN
  BEGIN TRANSACTION

  Set @FlgPodeCancelar = 0

  if (@FlgIntWms = 0) and (@StaIntWms = '')
    Set @FlgPodeCancelar = 1
  else
  if @FlgIntWms = 1
    begin
      if @StaIntWms = '4'
        Set @FlgPodeCancelar = 1
      else
        begin
          Update PDVCB
             Set Sta_IntWMS = '3'
           Where Cod_Estabe = @PCodEstabe 
             And Numero = @PNumPdv
             And IsNull(Sta_IntWMS,'') = ''

		  Exec PR_WMSGerarXMLEntradaCanPDV @PCodEstabe, @PNumPdv

        end
    end


  if @FlgPodeCancelar = 1
    begin
      Declare @WCodDep smallint,
              @WNumRua smallint,
              @WNumCol smallint,
              @WNumNiv smallint,
              @WNumApt smallint,
              @WDatVct smalldatetime,
              @WDatFab smalldatetime,
              @WCodOri varchar(20),
              @WQtdTrfTot int,
              @it_CodPrm int,

	          @lt_CodPrd int,
              @lt_CodLot varchar(20),
              @lt_QtdLot int,
              @lt_QtdPra int,
              @lt_QtdDep int,
              @lt_QtdCxaFec int,
              @lt_QtdEmbFec int,
              @lt_CodDep smallint,
              @lt_NumRua smallint,
              @lt_NumCol smallint,
              @lt_NumNiv smallint,
              @lt_NumApt smallint

      -- pega depósito/rua da zona de quarentena
      Select top 1 
             @WCodDep = z.Cod_Dep, 
             @WNumRua = z.Num_RuaIni 
        From TBZON z 
             inner join PMEST p on z.Cod_Estabe = p.Cod_Estabe and z.Cod_Zon = p.CodZonCan 
      Where z.Cod_Estabe = @PCodEstabe
        And dbo.FN_TipLocEnd(z.Cod_Estabe, z.Cod_Dep, z.Num_RuaIni) = 'X'

      Declare PDVLT_Cr Cursor Local Fast_Forward For 
        Select Cod_Produt, Cod_Lote, Qtd_Lote, Qtd_CxaFec, Qtd_EmbFec, Qtd_LotePra, Qtd_LoteDep, 
               Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt
          From PDVLT
         Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @PNumPdv

      Open PDVLT_Cr
      Fetch Next From PDVLT_Cr
        Into @lt_CodPrd, @lt_CodLot, @lt_QtdLot, @lt_QtdCxaFec, @lt_QtdEmbFec, @lt_QtdPra, @lt_QtdDep, 
             @lt_CodDep, @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt

      While @@FETCH_STATUS = 0
        begin
          if @lt_QtdPra is null
            Set @lt_QtdPra = 0
          if @lt_QtdDep is null
            Set @lt_QtdDep = 0
          if (@lt_QtdPra+@lt_QtdDep) <> @lt_QtdLot
            begin
              Set @lt_QtdPra = @lt_QtdLot - @lt_QtdDep
            end

          -- Transfere quantidades para zona de cancelamentos
          if (@lt_QtdCxaFec > 0) and (@FlgIntWms = 0)   -- deposito FECHADO
            begin
              Set @WNumCol = 0
              Set @WNumNiv = 0
              Set @WNumApt = 0
            end
          else
            begin
              Set @WNumCol = 1
              Set @WNumNiv = 1
              if (Select QtdNivEndPck From PMEST Where Cod_Estabe = @PCodEstabe) = 3
                Set @WNumApt = 0
              else
                Set @WNumApt = 1
            end

          -- se nao existir o lote, cria
          if (Select Count(*) From PRLTL 
               Where Cod_Estabe = @PCodEstabe 
                 And Cod_Produt = @lt_CodPrd and Cod_Lote = @lt_CodLot 
                 and Qtd_EmbFec = @lt_QtdEmbFec and Cod_Dep = @WCodDep 
                 and Num_Rua = @WNumRua and Num_Col = @WNumCol 
                 and Num_Niv = @WNumNiv and Num_Apt = @WNumApt) = 0
            begin
               -- pega o vencimento do lote
              Set @WDatVct = null
              Set @WDatFab = null
              if (@lt_QtdCxaFec > 0) and (@FlgIntWms = 0)  -- deposito FECHADO
                begin
                  Select @WDatVct = Dat_Vencim,
                         @WDatFab = Dat_Fabric
                    From PRLTL 
                   Where Cod_Estabe = @PCodEstabe 
                     And Cod_Produt = @lt_CodPrd and Cod_Lote = @lt_CodLot
                     And Qtd_EmbFec = @lt_QtdEmbFec And Cod_Dep = @lt_CodDep 
                     And Num_Rua = @lt_NumRua and Num_Col = @lt_NumCol 
                     And Num_Niv = @lt_NumNiv and Num_Apt = @lt_NumApt
                end
              else
                begin
                  Select @WDatVct = Dat_Vencim,
                         @WDatFab = Dat_Fabric
                    From PRLOT 
                   Where Cod_Estabe = @PCodEstabe 
                     And Cod_Dep = @lt_CodDep 
                     And Cod_Produt = @lt_CodPrd 
                     and Cod_Lote = @lt_CodLot
                end
 
              while Exists(Select * From PRLTL 
                            Where Cod_Estabe = @PCodEstabe 
                              And Cod_Produt = @lt_CodPrd and Cod_Lote = @lt_CodLot 
                              and Cod_Dep = @WCodDep and Num_Rua = @WNumRua 
                              and Num_Col = @WNumCol and Num_Niv = @WNumNiv 
                              and Num_Apt = @WNumApt)
                begin
                  Set @WNumNiv = @WNumNiv + 1
                end
 
              Insert into PRLTL (Cod_Estabe, Cod_Produt, Cod_Lote, Qtd_EmbFec, Dat_Vencim, Dat_Fabric, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Dat_Entrada, Qtd_FisPra, Qtd_SolPra,Qtd_FisDep,Qtd_SolDep)
                         Values (@PCodEstabe, @lt_CodPrd, @lt_CodLot, @lt_QtdEmbFec, @WDatVct, @WDatFab, @WCodDep, @WNumRua, @WNumCol, @WNumNiv, @WNumApt, @Date, 0, 0, 0, 0)
              if @@error <> 0
                begin
                  Rollback Transaction
                  Return
                end
           
            end -- if (Select Count(*) From PRLTL 

          -- cancela solicitacao/fisico
          if (@lt_QtdCxaFec > 0) and (@FlgIntWms = 0) -- depositO FECHADO
            begin
              Update PRLTL
                 Set Qtd_SolPra = Qtd_SolPra -  @lt_QtdPra
               Where Cod_Estabe = @PCodEstabe 
                 And Cod_Produt = @lt_CodPrd and Cod_Lote = @lt_CodLot
                 And Qtd_EmbFec = @lt_QtdEmbFec
                 And Cod_Dep = @lt_CodDep
                 And Num_Rua = @lt_NumRua and Num_Col = @lt_NumCol
                 And Num_Niv = @lt_NumNiv
                 And Num_Apt = @lt_NumApt
                 And @lt_QtdPra > 0
 
              Update PRLTL
                 Set Qtd_SolDep = Qtd_SolDep -  @lt_QtdDep
               Where Cod_Estabe = @PCodEstabe 
                 And Cod_Produt = @lt_CodPrd and Cod_Lote = @lt_CodLot
                 And Qtd_EmbFec = @lt_QtdEmbFec
                 And Cod_Dep = @lt_CodDep
                 And Num_Rua = @lt_NumRua and Num_Col = @lt_NumCol
                 And Num_Niv = @lt_NumNiv
                 And Num_Apt = @lt_NumApt
                 And @lt_QtdDep > 0
 
              Update PRLTL
                 Set Qtd_FisPra = Qtd_FisPra - @lt_QtdPra
               Where Cod_Estabe = @PCodEstabe 
                 And Cod_Produt = @lt_CodPrd and Cod_Lote = @lt_CodLot
                 And Qtd_EmbFec = @lt_QtdEmbFec
                 And Cod_Dep = @lt_CodDep
                 And Num_Rua = @lt_NumRua and Num_Col = @lt_NumCol
                 And Num_Niv = @lt_NumNiv
                 And Num_Apt = @lt_NumApt
                 And @lt_QtdPra > 0
 
              Update PRLTL
                 Set Qtd_FisDep = Qtd_FisDep - @lt_QtdDep
               Where Cod_Estabe = @PCodEstabe 
                 And Cod_Produt = @lt_CodPrd and Cod_Lote = @lt_CodLot
                 And Qtd_EmbFec = @lt_QtdEmbFec
                 And Cod_Dep = @lt_CodDep
                 And Num_Rua = @lt_NumRua and Num_Col = @lt_NumCol
                 And Num_Niv = @lt_NumNiv
                 And Num_Apt = @lt_NumApt
                 And @lt_QtdDep > 0
            end
          else
            begin
              Update PRLOT
                 Set Qtd_SolPra = Qtd_SolPra -  @lt_QtdPra
               Where Cod_Estabe = @PCodEstabe 
                 And Cod_Dep = @lt_CodDep 
                 And Cod_Produt = @lt_CodPrd 
                 and Cod_Lote = @lt_CodLot
                 And @lt_QtdPra > 0
 
              Update PRLOT
                 Set Qtd_SolDep = Qtd_SolDep -  @lt_QtdDep
               Where Cod_Estabe = @PCodEstabe 
                 And Cod_Dep = @lt_CodDep 
                 And Cod_Produt = @lt_CodPrd 
                 and Cod_Lote = @lt_CodLot
                 And @lt_QtdDep > 0
 
              Update PRLOT
                 Set Qtd_FisPra = Qtd_FisPra -  @lt_QtdPra
               Where Cod_Estabe = @PCodEstabe 
                 And Cod_Dep = @lt_CodDep 
                 And Cod_Produt = @lt_CodPrd 
                 and Cod_Lote = @lt_CodLot
                 And @lt_QtdPra > 0
 
              Update PRLOT
                 Set Qtd_FisDep = Qtd_FisDep -  @lt_QtdDep
               Where Cod_Estabe = @PCodEstabe 
                 And Cod_Dep = @lt_CodDep 
                 And Cod_Produt = @lt_CodPrd 
                 and Cod_Lote = @lt_CodLot
                 And @lt_QtdDep > 0
            end

          -- cancela solicitacao em PRODU
          Set @it_CodPrm = 0
          Select @it_CodPrm = Cod_Promocao
           From PDVIT 
          Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @PNumPdv 
            And Cod_Produto = @lt_CodPrd and Cod_Lote = '*'
 
          Update PRXES 
             Set Qtd_Solici = case 
                                when Qtd_Solici > @lt_QtdLot then Qtd_Solici - @lt_QtdLot
                                else 0
                              end
           Where Cod_Estabe = @PCodEstabe 
             And Cod_Produt = @lt_CodPrd
 
          Update PRXES 
             Set Qtd_PrmSolici = case 
                                   when Qtd_PrmSolici > @lt_QtdLot then Qtd_PrmSolici - @lt_QtdLot
                                   else 0
                                 end                                       
           Where Cod_Estabe = @PCodEstabe 
             And Cod_Produt = @lt_CodPrd and (@it_CodPrm > 0 and not @it_CodPrm is null)
			
		  set @FlgAtuQtdSolici = 1;
 
          -- transfere para zona de cancelados
          if @FlgIntWms = 0
            begin
              Update PRLTL
                 Set Qtd_FisPra = Qtd_FisPra +  @lt_QtdPra
               Where Cod_Estabe = @PCodEstabe 
                 And Cod_Produt = @lt_CodPrd and Cod_Lote = @lt_CodLot
                 And Qtd_EmbFec = @lt_QtdEmbFec
                 And Cod_Dep = @WCodDep
                 And Num_Rua = @WNumRua And Num_Col = @WNumCol
                 And Num_Niv = @WNumNiv And Num_Apt = @WNumApt
                 And @lt_QtdPra > 0
 
              Update PRLTL
                 Set Qtd_FisDep = Qtd_FisDep +  @lt_QtdDep
               Where Cod_Estabe = @PCodEstabe 
                 And Cod_Produt = @lt_CodPrd and Cod_Lote = @lt_CodLot
                 And Qtd_EmbFec = @lt_QtdEmbFec
                 And Cod_Dep = @WCodDep
                 And Num_Rua = @WNumRua And Num_Col = @WNumCol
                 And Num_Niv = @WNumNiv And Num_Apt = @WNumApt
                 And @lt_QtdDep > 0
 
              Set @WCodOri = 'CAN_PDV'
 
              -- registra log saida
              Set @WQtdTrfTot = (@lt_QtdPra + @lt_QtdDep) * (-1)
              Exec PR_InserePRLOG @PCodEstabe, @lt_CodPrd, @lt_CodLot, @lt_CodDep, 
                                  @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt,
                                  @WQtdTrfTot, @WCodOri, '', @PNumPdv, '', '', @PNomUsu
              if @@error <> 0 
                begin
                  Rollback Transaction
                  Return
                end 
 
              -- registra log entrada
              Set @WQtdTrfTot = @lt_QtdPra + @lt_QtdDep
              Exec PR_InserePRLOG @PCodEstabe, @lt_CodPrd, @lt_CodLot, @WCodDep, 
                                  @WNumRua, @WNumCol, @WNumNiv, @WNumApt,
                                  @WQtdTrfTot, @WCodOri, '', @PNumPdv, '', '', @PNomUsu
              if @@error <> 0 
                begin
                  Rollback Transaction
                  Return
                end

            end
	    
          Fetch Next From PDVLT_Cr
            Into @lt_CodPrd, @lt_CodLot, @lt_QtdLot, @lt_QtdCxaFec, @lt_QtdEmbFec, @lt_QtdPra, @lt_QtdDep, 
                 @lt_CodDep, @lt_NumRua, @lt_NumCol, @lt_NumNiv, @lt_NumApt

        end  -- While @@FETCH_STATUS = 0
  
      Close PDVLT_Cr
      Deallocate PDVLT_Cr
 
      -- cancela o pedido
      Delete From PDVLT
       Where Cod_Estabe = @PCodEstabe 
         And Cod_Pedido = @PNumPdv
 
      Exec PR_CancelaPDV @PCodEstabe, @PNumPdv, @PNomUsu, @FlgAtuQtdSolici
      if @@error <> 0
        begin
          Rollback Transaction
          Return
        end

      -- atualiza status integracao WMS
      Update PDVCB
         Set Sta_IntWMS = '6'
       Where Cod_Estabe = @PCodEstabe 
         And Numero = @PNumPdv
         And IsNull(Sta_IntWMS,'') <> ''

      -- Elimina a conferencia
      Delete From CPVIT
       Where Cod_Estabe = @PCodEstabe 
         And Num_PedCnf = @PNumPdv
 
      Delete From CPVCB
       Where Cod_Estabe = @PCodEstabe 
         And Num_PedCnf = @PNumPdv
 
    end  -- if @FlgPodeCancelar = 1

  if @@trancount > 0
    COMMIT TRANSACTION
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ExcluiCancelaNFSCB]
@PCodEstabe int,
@PSerNot varchar(3),
@PNumNot int,
@PCodMve int,
@PNomUsu varchar(15),
@PFlgCanPdv bit

AS

SET NOCOUNT ON
SET ANSI_WARNINGS OFF

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

Declare @cb_FlgWms bit,
        @cb_StaNot varchar(1),
        @cb_TipNot varchar(1),
        @cb_CodCfo int,
        @cb_DatEmi smalldatetime,
        @cb_MovEst bit,
        @cb_CodCli int,
        @cb_CodVdr int,
        @cb_CodOpe int,
        @cb_CodSup int,
        @cb_CodPdv int,
        @cb_SubFat int,
        @cb_ValDebVrbVdr numeric(18,4),
        @cb_ValNot numeric(18,4),
        @cb_CodFun int,
        @cb_CodFor int,
        @cb_CodCtr int,
        @cb_IdConsig int,
        @cb_NumSeqCtr int, 
        @cb_StaIntWms varchar(1),
        @cb_Usuario varchar(15),
        @cr_CodDoc int,
        @pm_FlgIntWms bit = 0,
    @FlgPodeCancelar bit,
        @va_IsnCtaFinDeb int,
        @va_IsnCtaFinCre int,
        @va_DatMovime smalldatetime,
        @va_NumSequen int,     
        @pm_FlgUsaInterv bit,
        @WMsg varchar(128),
        @WFlgErr bit,
        @WQtdEmbFec int,
        @WCodDepCan smallint,
        @WNumRuaCan smallint,
        @WNumCol smallint,
        @WNumNiv smallint,
        @WNumApt smallint,
        @WDatVct smalldatetime,
        @WDatFab smalldatetime,
        @WTipDes varchar(3),
        @WCodDes int,
        @WCodDoc int,
        @CodTipSaiCng varchar(3) = '',
    @pc_CtlSld varchar(1)

-- Validacao login usuario infarma  
if (@PNomUsu='' or @PNomUsu='SISTEMA')
  set @PNomUsu = dbo.FN_UsuarioInfarma()

-- coloca campos na memoria
Select @pm_FlgUsaInterv = IsNull(FlgUsaInterv,0)
  From PMFIN

Select @pm_FlgIntWms = IsNull(FlgIntegrWmsExt,0) 
  From PMEST Where Cod_Estabe = @PCodEstabe

Select @cb_FlgWms = IsNull(cb.Flg_Wms,0),
       @cb_StaIntWms = IsNull(cb.Sta_IntWms,''),          
       @cb_StaNot = cb.Status,
       @cb_TipNot = cb.Tip_Saida,
       @cb_CodCfo = Isnull(cb.Cod_Cfo1,0),
       @cb_DatEmi = cb.Dat_Emissao,
       @cb_MovEst = IsNull(cb.Flg_MovEst,0),
       @cb_CodCli = IsNull(cb.Cod_Cliente,0),
       @cb_CodFun = IsNull(cb.Cod_Funcionario,0),
       @cb_CodFor = IsNull(cb.Cod_Fornecedor,0),
       @cb_CodVdr = cb.Cod_Vendedor,
       @cb_CodOpe = IsNull(cb.Cod_VendTlmkt, 0),
       @cb_CodSup = cb.Cod_Supervisor,
       @cb_CodPdv = cb.Cod_Pedido,
       @cb_SubFat = cb.Num_NotSubFat,
       @cb_ValDebVrbVdr = IsNull(cb.Vlr_DebVrbVdr,0),
       @cb_ValNot = IsNull(cb.Vlr_TotalNota,0),
       @cb_CodCtr = IsNull(cb.Cod_Contrato,0),
       @cb_IdConsig = IsNull(cb.Id_Consig,0),
       @cb_NumSeqCtr = IsNull(cb.Num_SequenciaCtr,0), 
       @cb_Usuario = cb.Usuario,
     @pc_CtlSld = pc.Controle_Saldo
  From NFSCB cb
       Left Join POCOM pc on pc.Id_PolCom = cb.Id_PolCom
 Where cb.Cod_Estabe = @PCodEstabe and cb.Ser_Nota = @PSerNot and cb.Num_Nota = @PNumNot

if @cb_StaNot = 'C'
  RAISERROR('Nota já cancelada',16,1)
else
if (@cb_FlgWms = 1) and 
   not Exists(Select 1
                From TBZON z 
                     inner join PMEST p on z.Cod_Estabe = p.Cod_Estabe and z.Cod_Zon = p.CodZonCan 
               Where z.Cod_Estabe = @PCodEstabe
                 And dbo.FN_TipLocEnd(z.Cod_Estabe, z.Cod_Dep, z.Num_RuaIni) = 'X'
                 And z.Cod_Dep > 0 And z.Num_RuaIni > 0)
  RAISERROR('Zona de Quarentena(cancelamentos) não configurada ou inválida',16,1)
else

BEGIN
  BEGIN TRANSACTION

  Set @FlgPodeCancelar = 0

  if (@cb_FlgWms = 0) or (@cb_MovEst = 0)
    Set @FlgPodeCancelar = 1
  else
  if (@pm_FlgIntWms = 0) and (@cb_StaIntWms = '')
    Set @FlgPodeCancelar = 1
  else
  if @pm_FlgIntWms = 1
    begin
      if @cb_StaIntWms = '4'
        begin
          Set @FlgPodeCancelar = 1
          Set @PFlgCanPdv = (Select IsNull(Flg_CanPdv,0) From NFSCB
                              Where Cod_Estabe = @PCodEstabe 
                                And Ser_Nota = @PSerNot
                                And Num_Nota = @PNumNot)
        end
      else
        begin
          Update NFSCB
             Set Sta_IntWMS = '3'
           Where Cod_Estabe = @PCodEstabe 
             And Ser_Nota = @PSerNot
             And Num_Nota = @PNumNot
             And IsNull(Sta_IntWMS,'') = ''

          Update NFSCB
             Set Flg_CanPdv = @PFlgCanPdv,
           Usuario = @PNomUsu
           Where Cod_Estabe = @PCodEstabe 
             And Ser_Nota = @PSerNot
             And Num_Nota = @PNumNot

          Exec PR_WMSGerarXMLEntradaCanNFS @PCodEstabe, @PSerNot, @PNumNot

        end
    end

  if @FlgPodeCancelar = 1
    begin
              
      if (@cb_StaNot = 'A') and (@cb_TipNot <> 'V')
        begin
          -- exclui os itens
          Delete from NFSIT 
           Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot

          -- exclui as duplicatas
          Delete from CTREC
           Where Cod_Estabe = @PCodEstabe
             And Ser_NfOrigem = @PSerNot and Num_NfOrigem = @PNumNot

          -- se a nota tiver sido a ultima, exclui, senao cancela
          if @PSerNot = 'XXX'
            begin
              Delete from NFSCB
               Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
            end
          else
          if (Select Nota_Fiscal_M1 from NMFIS Where Cod_Estabe = @PCodEstabe) = @PNumNot
            begin
              Update NMFIS
                 Set Nota_Fiscal_M1 = @PNumNot - 1
               Where Cod_Estabe = @PCodEstabe
              
              Delete from NFSCB
               Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
            end
          else
            begin
              Update NFSCB
                 Set Status = 'C',
                     Dat_Cancelamento = @Date,
                     Flg_CanPdv = @PFlgCanPdv,
                     Usuario = @PNomUsu,
                     Transacao = GetDate()
               Where Cod_Estabe = @PCodEstabe 
                 and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
            end
        end
      else
      if (@cb_StaNot = 'F') and (@cb_MovEst = 0)
        begin
          -- cancela titulos
          Exec PR_CancelaDevolveTitulosCTREC @PCodEstabe, @PSerNot, @PNumNot, @PNomUsu, 'C', 0, 0
          if @@error <> 0
            begin
              if @@trancount > 0
                Rollback Transaction
              Return
            end

          -- cancela o cabeçalho
          Update NFSCB
             Set Status = 'C',
                 Dat_Cancelamento = @Date,
                 Flg_CanPdv = @PFlgCanPdv,
                 Usuario = @PNomUsu,
                 Transacao = GetDate()
           Where Cod_Estabe = @PCodEstabe 
             and Ser_Nota = @PSerNot and Num_Nota = @PNumNot

          -- transfere saldos de PRSLD
          EXEC PR_TransfEstNFS @PCodEstabe, @PSerNot, @PNumNot
          if @@error <> 0
            begin
              if @@trancount > 0
                Rollback Transaction
              Return
            end

          -- se for o caso cancela os desc. sub.fat na Nf origem (ORC)
          if (@PSerNot <> 'ORC') and (@cb_SubFat > 0)
            begin
              Declare CTREC_Cr Cursor Local Fast_Forward For 
                Select Cod_Documento
                  From CTREC
                 Where Cod_Estabe = @PCodEstabe
                   And Ser_NfOrigem = 'ORC' and Num_NfOrigem = @cb_SubFat
                  
              Open CTREC_Cr
              Fetch Next From CTREC_Cr
                Into @cr_CodDoc
              While @@FETCH_STATUS = 0
                begin
                  Update CTREC
                     Set Vlr_DscSubFat = 0
                   Where Cod_Estabe = @PCodEstabe
                     And Cod_Documento = @cr_CodDoc

                  -- atualiza saldo contas a receber
                  EXEC PR_AtualizaCtrec @PCodEstabe, @cr_CodDoc,0
                  if @@error <> 0
                    begin
                      if @@trancount > 0
                        Rollback Transaction
                      Return
                    end

                  Fetch Next From CTREC_Cr
                    Into @cr_CodDoc
                end
              Close CTREC_Cr
              Deallocate CTREC_Cr
            end
        end
      else
      if @Cb_StaNot = 'F' and @Cb_MovEst = 1
        if not Exists(Select Codigo from TPMVE Where Codigo = @PCodMve)
          begin
            Set @WMsg = 'O código para o Tipo de Movimento "'+Cast(@PCodMve as varchar(2))+
                                    '-Entrada por Cancelamento de NF" não foi '+
                                    'cadastrado em Tipos de Movimentação de Estoque'
            RAISERROR(@WMsg,16,1)
          end
        else
          begin
            Declare @it_CodPrd int,
                    @it_CodLot varchar(20),
                    @it_SeqIte int,
                    @it_TipSai varchar(1),
                    @it_QtdPrd int,
                    @it_QtdBon int,
                    @it_PrcUni numeric(18,8),
                    @it_QtdPra int,
                    @it_QtdDep int,
                    @it_VlrVrbPolVdr numeric(18,4),
          @it_VlrVrbPolOpe numeric(18,4),
                    @it_VlrVrbPolSup numeric(18,4),
                    @it_VlrVrbPar numeric(18,4),
                    @it_VlrVrbBon numeric(18,4),
                    @it_IdPolCom int,
                    @it_PrcFab numeric(18,4), 
                    @it_PrcUniPde numeric(18,4), 
                    @it_PerDscPde numeric(18,4),
                    @it_CodCfo int,
          @it_CodFab int,

                    @WCodOri varchar(20),
                    @WQtdMov int,
                    @WDatCan smalldatetime,
                    @WCodAcr int,
                    @WDesHst varchar(40),
                    @WQtdItePdv int,
                    @WQtdIteNfs int,
                    @WDivItens int,
                    @WFlgReaPdvOk bit,
                    @WQtdPra int ,
                    @WQtdDep int,
                    @WValMov numeric(18,4),
                    @WCodFor int,
                    @WValEdi numeric(18,4),
                    @WValBru numeric(18,4),
                    
                    @WNumRuaPck smallint,
                    @WNumColPck smallint,
                    @WNumNivPck smallint,
                    @WNumAptPck smallint

            -- pega depósito/rua da zona de quarentena(cancelamento)
            Select top 1 
                   @WCodDepCan = z.Cod_Dep, 
                   @WNumRuaCan = z.Num_RuaIni 
              From TBZON z 
                   inner join PMEST p on z.Cod_Estabe = p.Cod_Estabe and z.Cod_Zon = p.CodZonCan 
             Where z.Cod_Estabe = @PCodEstabe
               And dbo.FN_TipLocEnd(z.Cod_Estabe, z.Cod_Dep, z.Num_RuaIni) = 'X'

            -- se nao for cancelar pedido ver se esta ok pdv x nfs
            Set @WFlgReaPdvOk = 0
            if @PFlgCanPdv = 0
              begin
                Set @WQtdItePdv = IsNull((Select count(*) from PDVIT Where Cod_Estabe = @PCodEstabe and Cod_Pedido = @cb_CodPdv and Qtd_Pedido > 0),0)
                Set @WQtdIteNfs = IsNull((Select count(*) from NFSIT Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot),0)

                -- O mesmo produto pode ser dividido em lotes diferentes na nota
        Select @WDivItens = Count(1) 
                  From (Select Cod_Produto,Sum(Qtd_Pedido) as Qtd 
                          From PDVIT 
                         Where Cod_Estabe = @PCodEstabe 
                           And Cod_Pedido = @cb_CodPdv and Qtd_Pedido > 0
                         Group By Cod_Produto) p Full Join 
                       (Select Cod_Produto,Sum(Qtd_Produto) as Qtd 
                          From NFSIT 
                         Where Cod_Estabe = @PCodEstabe 
                           And Ser_Nota = @PSerNot and Num_Nota = @PNumNot
                         Group By Cod_Produto) n On p.Cod_Produto = n.Cod_Produto
         Where IsNull(p.Qtd,0) <> IsNull(n.Qtd,0)
        
                if (@WDivItens = 0) and (@WQtdItePdv > 0) and (@WQtdIteNfs > 0)
                  Set @WFlgReaPdvOk = 1
                else
                  begin
                    Set @WMsg = 'Divergencia entre itens do pedido e da nota. Pedido deve ser cancelado'
                    RAISERROR(@WMsg,16,1)
                  end
              end

            Update NFSCB
               Set Status = 'C',
                   Dat_Cancelamento = @Date,
                   Flg_CanPdv = @PFlgCanPdv,
                   Usuario = @PNomUsu,
                   Transacao = GetDate()
             Where Cod_Estabe = @PCodEstabe 
               and Ser_Nota = @PSerNot and Num_Nota = @PNumNot

            Set @WFlgErr = 0
            Set @WDatCan = @Date
            Set @WDesHst = 'CANCELAMENTO NF '+@PSerNot+' '+cast(@PNumNot as varchar)

            Declare NFSIT_Cr Cursor Local Fast_Forward For 
              Select it.Cod_Produto, it.Cod_Lote, it.Num_SeqIte, it.Qtd_Produto, it.Qtd_Bonificacao, it.Prc_Unitario,
                     IsNull(it.Cod_Cfo,0), IsNull(it.Prc_Fabric,0), IsNull(it.Prc_UniPde,0), IsNull(it.Per_DscPde,0), 
                     IsNull(it.Qtd_Pra,0), IsNull(it.Qtd_Dep,0), IsNull(it.Vlr_Verba,0), IsNull(it.Vlr_VrbOpe,0), IsNull(it.Vlr_VrbSup,0), IsNull(it.Vlr_VrbPar,0), 
                     IsNull(it.Vlr_VrbBon,0), IsNull(it.Id_PolCom,0), pr.Cod_Fabricante
                From NFSIT it 
                     Inner Join NFSCB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Ser_Nota = cb.Ser_Nota and it.Num_Nota = cb.Num_Nota
                     Inner Join PRODU pr on it.Cod_Produto = pr.Codigo
               Where cb.Cod_Estabe = @PCodEstabe and cb.Ser_Nota = @PSerNot and cb.Num_Nota = @PNumNot and cb.Flg_MovEst = 1

            Open NFSIT_Cr
            Fetch Next From NFSIT_Cr
              Into @it_CodPrd, @it_CodLot, @it_SeqIte, @it_QtdPrd, @it_QtdBon, @it_PrcUni,
                   @it_CodCfo, @it_PrcFab, @it_PrcUniPde, @it_PerDscPde,  
                   @it_QtdPra, @it_QtdDep, @it_VlrVrbPolVdr, @it_VlrVrbPolOpe, @it_VlrVrbPolSup, @it_VlrVrbPar, 
                   @it_VlrVrbBon, @it_IdPolCom, @it_CodFab 

            While (@@FETCH_STATUS = 0) and (@WFlgErr = 0)
              begin
                if (@it_QtdPra+@it_QtdDep) <> (@it_QtdPrd+@it_QtdBon)
                  Set @it_QtdPra = @it_QtdPrd + @it_QtdBon - @it_QtdDep

                Set @WNumCol = 0
                Set @WNumNiv = 0
                Set @WNumApt = 0
                Set @WDatVct = null
                Set @WDatFab = null
                Set @WQtdEmbFec = 1

                -- pega o vencimento do lote
                Select @WDatVct = Dat_Vencim, 
                       @WDatFab = Dat_Fabric 
                  From PRLOT 
                 Where Cod_Estabe = @PCodEstabe 
                   And Cod_Dep = @WCodDepCan
                   And Cod_Produt = @it_CodPrd 
                   and Cod_Lote = @it_CodLot

                if @WDatVct is null
                  Set @WDatVct = (Select top 1 Dat_Vencim From PRLTL Where Cod_Estabe = @PCodEstabe and Cod_Produt = @it_CodPrd and Cod_Lote = @it_CodLot And Cod_Dep = @WCodDepCan)
                if @WDatFab is null
                  Set @WDatFab = (Select top 1 Dat_Fabric From PRLTL Where Cod_Estabe = @PCodEstabe and Cod_Produt = @it_CodPrd and Cod_Lote = @it_CodLot And Cod_Dep = @WCodDepCan)

                -- verifica e ajusta se for emprestimo de estoque
                if (@cb_CodCfo > 0) and (@it_QtdDep > 0)
                  Set @it_QtdDep = @it_QtdDep * (-1) 
                if (@cb_CodCfo = 0) and (@it_QtdPra > 0)
                  Set @it_QtdPra = @it_QtdPra * (-1) 

                -- gera um acerto. o saldo é atualizado pela trigger
                Set @WNumRuaPck = 0
                Set @WNumColPck = 0
                Set @WNumNivPck = 0
                Set @WNumAptPck = 0
                
                Select @WNumRuaPck = Num_Rua, 
                       @WNumColPck = Num_Col, 
                       @WNumNivPck = Num_Niv, 
                       @WNumAptPck = Num_Apt 
                  From DPXPR 
                 Where Cod_Estabe = @PCodEstabe 
                   And Cod_Dep = @WCodDepCan
                   And Cod_Produt = @it_CodPrd

                Exec PR_ProxNumero 'Acerto', @WCodAcr output
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      Rollback Transaction
                    Return
                  end
                  
                Insert into ACERT (Cod_Estabe, Numero, Dat_Movimento, 
                                   Cod_Produto, Cod_Lote, Dat_Vencimento, Dat_Fabric,
                                   Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt,
                                   Qtd_Acerto, Qtd_AceDep, Cod_TipMov, Cod_OriMov, Historico, Usuario, Transacao)
                            Values(@PCodEstabe, @WCodAcr, @WDatCan,
                                   @it_CodPrd, @it_CodLot, @WDatVct, @WDatFab, 
                                   @WCodDepCan, @WNumRuaPck, @WNumColPck, @WNumNivPck, @WNumAptPck,
                                   @it_QtdPra, @it_QtdDep, @PCodMve, 'NF', @WDesHst,  @PNomUsu, GetDate())
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      Rollback Transaction
                    Return
                  end

                -- se WMS transfere para Zona de cancelamentos se não estiver integrado
                if (@cb_FlgWms = 1) and (@pm_FlgIntWms = 0)
                  begin
                    -- se nao existir o lote, cria
                    if (Select Count(*) From PRLTL 
                         Where Cod_Estabe = @PCodEstabe 
                           and Cod_Produt = @it_CodPrd and Cod_Lote = @it_CodLot
                           and Cod_Dep = @WCodDepCan and Num_Rua = @WNumRuaCan 
                           and Num_Col = @WNumCol and Num_Niv = @WNumNiv 
                           and Num_Apt = @WNumApt) = 0
                      begin
                        Insert into PRLTL (Cod_Estabe, Cod_Produt, Cod_Lote, Qtd_EmbFec, Dat_Vencim, Dat_Fabric, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Dat_Entrada, Qtd_FisPra, Qtd_SolPra,Qtd_FisDep,Qtd_SolDep)
                                   Values (@PCodEstabe, @it_CodPrd, @it_CodLot, @WQtdEmbFec, @WDatVct, @WDatFab, @WCodDepCan, @WNumRuaCan, @WNumCol, @WNumNiv, @WNumApt, @Date, 0, 0, 0, 0)
                        if @@error <> 0
                          begin
                            if @@trancount > 0
                              Rollback Transaction
                            Return
                          end
                      end

                    -- tira de PRLOT
                    Update PRLOT
                       Set Qtd_FisPra = Qtd_FisPra - Abs(@it_QtdPra)
                     Where Cod_Estabe = @PCodEstabe 
                       And Cod_Dep = @WCodDepCan
                       And Cod_Produt = @it_CodPrd 
                       and Cod_Lote = @it_CodLot
                       And Abs(@it_QtdPra) > 0
                       And Qtd_SldPra >= Abs(@it_QtdPra)
                       And @WFlgErr = 0
                    if (@@rowcount = 0) and (Abs(@it_QtdPra) > 0) and (@WFlgErr = 0)
                      begin
                        Set @WFlgErr = 1
                        Set @WMsg = 'Estoque insuficiente no Picking a transferir p/ zona de cancelamentos'
                      end

                    Update PRLOT
                       Set Qtd_FisDep = Qtd_FisDep - Abs(@it_QtdDep)
                     Where Cod_Estabe = @PCodEstabe
                       And Cod_Dep = @WCodDepCan 
                       And Cod_Produt = @it_CodPrd 
                       and Cod_Lote = @it_CodLot
                       And Abs(@it_QtdDep) > 0
                       And Qtd_SldDep >= Abs(@it_QtdDep)
                       And @WFlgErr = 0
                    if (@@rowcount = 0) and (Abs(@it_QtdDep) > 0) and (@WFlgErr = 0)
                      begin
                        Set @WFlgErr = 1
                        Set @WMsg = 'Estoque insuficiente no Picking a transferir p/ zona de cancelamentos'
                      end

                    -- transfere para zona de cancelados
                    Update PRLTL
                       Set Qtd_FisPra = Qtd_FisPra +  Abs(@it_QtdPra)
                     Where Cod_Estabe = @PCodEstabe 
                       And Cod_Produt = @it_CodPrd and Cod_Lote = @it_CodLot
                       And Cod_Dep = @WCodDepCan
                       And Num_Rua = @WNumRuaCan 
                       And Num_Col = @WNumCol
                       And Num_Niv = @WNumNiv
                       And Num_Apt = @WNumApt
                       And Abs(@it_QtdPra) > 0
                       And @WFlgErr = 0
                    if (@@rowcount = 0) and (Abs(@it_QtdPra) > 0) and (@WFlgErr = 0)
                      begin
                        Set @WFlgErr = 1
                        Set @WMsg = 'Erro na transferencia p/ zona de cancelamentos (endereço inexistente)'
                      end

                    Update PRLTL
                       Set Qtd_FisDep = Qtd_FisDep +  Abs(@it_QtdDep)
                     Where Cod_Estabe = @PCodEstabe 
                       And Cod_Produt = @it_CodPrd and Cod_Lote = @it_CodLot
                       And Cod_Dep = @WCodDepCan
                       And Num_Rua = @WNumRuaCan 
                       And Num_Col = @WNumCol
                       And Num_Niv = @WNumNiv
                       And Num_Apt = @WNumApt
                       And Abs(@it_QtdDep) > 0
                       And @WFlgErr = 0
                    if (@@rowcount = 0) and (Abs(@it_QtdDep) > 0) and (@WFlgErr = 0)
                      begin
                        Set @WFlgErr = 1
                        Set @WMsg = 'Erro na transferencia p/ zona de cancelamentos (endereço inexistente)'
                      end
                      
                    -- registra log entrada
                    Set @WCodOri = 'TRF_EST'

                    -- registra log transferencia picking p/ zona de cancelamento
                    -- saida picking
                    Set @WQtdMov = (Abs(@it_QtdPra) + Abs(@it_QtdDep)) * (-1)
                    Exec PR_InserePRLOG @PCodEstabe, @it_CodPrd, @it_CodLot, @WCodDepCan, 
                                        @WNumRuaPck, @WNumColPck, @WNumNivPck, @WNumAptPck,
                                        @WQtdMov, @WCodOri, '', @PSerNot, @PNumNot, '', @PNomUsu
                    if @@error <> 0 
                      begin
                        if @@trancount > 0
                          Rollback Transaction
                        Return
                      end 
                    
                    -- entrada na zona de cancelamento
                    Set @WQtdMov = Abs(@it_QtdPra) + Abs(@it_QtdDep)
                    Exec PR_InserePRLOG @PCodEstabe, @it_CodPrd, @it_CodLot, @WCodDepCan, 
                                        @WNumRuaCan, @WNumCol, @WNumNiv, @WNumApt,
                                        @WQtdMov, @WCodOri, '', @PSerNot, @PNumNot, '', @PNomUsu
                    if @@error <> 0 
                      begin
                        if @@trancount > 0
                          Rollback Transaction
                        Return
                      end 
                      
                  end    -- @cb_FlgWms = 1

                -- re-solicita pedido se for reabrir
                if (@WFlgReaPdvOk = 1 ) and (@WFlgErr = 0)
                  if ((@cb_FlgWms = 0) and (Exists(Select Cod_Pedido From PDVIT Where Cod_Estabe = @PCodEstabe and Cod_Pedido = @cb_CodPdv And Cod_Produto = @it_CodPrd And Cod_Lote = @it_CodLot And Qtd_Pedido > 0))) or
                     ((@cb_FlgWms = 1) and (Exists(Select Cod_Pedido From PDVIT Where Cod_Estabe = @PCodEstabe and Cod_Pedido = @cb_CodPdv And Cod_Produto = @it_CodPrd And Cod_Lote = '*' And Qtd_Pedido > 0)))
                    begin

                      if @cb_FlgWms = 0
                        Select @WQtdPra = Qtd_Pra,
                               @WQtdDep = Qtd_Dep
                          From PDVIT 
                         Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @cb_CodPdv And Cod_Produto = @it_CodPrd And Cod_Lote = @it_CodLot
                      else
                        Select @WQtdPra = Qtd_Pedido,
                               @WQtdDep = Qtd_Bonificacao
                          From PDVIT 
                         Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @cb_CodPdv And Cod_Produto = @it_CodPrd And Cod_Lote = '*'

                      if @WQtdPra is null
                        Set @WQtdPra = 0
                      if @WQtdDep is null
                        Set @WQtdDep = 0

                      if @cb_FlgWms = 0
                        begin
                          if @WQtdPra > 0
                            begin
                              Update PRLOT 
                                 Set Qtd_SolPra = Qtd_SolPra + @WQtdPra
                               Where Cod_Estabe = @PCodEstabe 
                                 /*And Cod_Dep = @WCodDepCan               DMD-8136*/
                                 And Cod_Produt = @it_CodPrd 
                                 and Cod_Lote = @it_CodLot
                                 And Qtd_SldPra >= @WQtdPra
                              if @@rowcount = 0
                                begin
                                  Set @WFlgErr = 1
                                  Set @WMsg = 'Inconsistencia nos lotes. Pedido deve ser cancelado'
                                end
                            end
                          if @WQtdDep > 0
                            begin
                              Update PRLOT 
                                 Set Qtd_SolDep = Qtd_SolDep + @WQtdDep
                               Where Cod_Estabe = @PCodEstabe 
                                 /*And Cod_Dep = @WCodDepCan               DMD-8136*/
                                 And Cod_Produt = @it_CodPrd 
                                 and Cod_Lote = @it_CodLot
                                 And Qtd_SldDep >= @WQtdDep
                              if @@rowcount = 0
                                begin
                                  Set @WFlgErr = 1
                                  Set @WMsg = 'Inconsistencia nos lotes. Pedido deve ser cancelado'
                                end
                          end
                        end

                      Update PRXES
                         Set Qtd_Solici = Qtd_Solici + @WQtdPra + @WQtdDep
                       Where Cod_Estabe = @PCodEstabe 
                         And Cod_Produt = @it_CodPrd
                    end                

                  else
                    begin
                      Set @WFlgErr = 1
                      Set @WMsg = 'Item inexistente no pedido: '+cast(@it_CodPrd as varchar)+'/'+@it_CodLot+'. Pedido deve ser cancelado'
                    end                

                if @WFlgErr = 0 
                  begin
                    -- identifica bonificacao  
                    Set @it_TipSai = ''
                    if (@it_CodCfo = 5910) or (@it_CodCfo = 6910)
                      Set @it_TipSai = 'B'
                      
                    if @cb_CodCli > 0 
                      begin
                         -- atualiza verbas do cliente 
                        if ((@it_VlrVrbPar <> 0) or (@it_VlrVrbBon <> 0)) and (@cb_TipNot = 'V') and (@it_TipSai = '')
                          begin
                            Set @it_VlrVrbPar = -@it_VlrVrbPar
                            Set @it_VlrVrbBon = -@it_VlrVrbBon
                            
                            Exec PR_AtualizaSaldoVBCSD @PCodEstabe, @cb_CodCli, @WDatCan, 0, @it_CodPrd, @it_CodLot, 'S', 'C', @PSerNot, @PNumNot, @it_VlrVrbPar, @it_VlrVrbBon, 'CANCELAMENTO NF', 'SISTEMA'
                            if (@@error <> 0)
                              begin
                                if @@trancount > 0
                                  Rollback Transaction
                                Return
                              end
                          end
                      end
 
                     -- grava movimento relativo a remessa/venda em consignação: CFOP: 5917/6917,  5112/6112, 5113/6113, 5114/6114 
                    if (@cb_IdConsig > 0) and (@cb_NumSeqCtr > 0) and (dbo.FN_CfopConsigValido(@cb_CodCfo) = 1)
                      begin
                        if dbo.FN_TipoNFConsig(@cb_CodCfo) = 'R'
                          Set @CodTipSaiCng = 'NFR'
                        else
                          Set @CodTipSaiCng = 'NFF'

                        Exec PR_GravaMovimeCNGMV @PCodEstabe, @cb_IdConsig, @it_CodPrd, @it_CodLot,
                                                 @cb_DatEmi, 'S', @CodTipSaiCng, @PSerNot, @PNumNot, @it_TipSai, 'C', 
                                                 @WQtdMov, @it_PrcUni
                        if (@@error <> 0)
                          begin
                            if @@trancount > 0
                              Rollback Transaction
                            Return
                          end
                      end

                    -- verba
                    -- @pc_CtlSld já está com controle da política do cabeçalho (default)
                    if Exists (Select 1 From POCOM Where Id_PolCom = @it_IdPolCom)
                      Select @pc_CtlSld = pc.Controle_Saldo
                        From POCOM pc
                       Where pc.Id_PolCom = @it_IdPolCom

                    if @pc_CtlSld = 'V' -- Vendedor/Operador
                      begin
                        -- atualiza verba de politica para vendedor  cuidado que pode ser NF de bonificacao tb
            if (@it_VlrVrbPolVdr <> 0) and (@cb_CodVdr >  0)
                          begin
                            Set @it_VlrVrbPolVdr = -@it_VlrVrbPolVdr
                            Exec PR_AtualizaSaldoVBSLD @PCodEstabe, @cb_CodVdr, @WDatCan, 0, @it_CodPrd, @it_CodLot, @it_TipSai, 'S', 'C', @PSerNot, @PNumNot, @it_VlrVrbPolVdr, 'CANCELAMENTO NF', 'SISTEMA'
                            if (@@error <> 0)
                              begin
                                if @@trancount > 0
                                  Rollback Transaction
                                Return
                              end
                          end

            -- atualiza verba de politica para Operador. Cuidado que pode ser NF de bonificação tb
            if (@it_VlrVrbPolOpe <> 0) and (@cb_CodOpe > 0)
              begin
              Set @it_VlrVrbPolOpe = -@it_VlrVrbPolOpe
              Exec PR_AtualizaSaldoVBSLD @PCodEstabe, @cb_CodOpe, @WDatCan, 0, @it_CodPrd, @it_CodLot, @it_TipSai, 'S', 'C', @PSerNot, @PNumNot, @it_VlrVrbPolOpe, 'CANCELAMENTO NF', 'SISTEMA'
              if (@@error <> 0)
                begin
                                if @@trancount > 0
                                  Rollback Transaction
                Return
                end
              end

                        -- atualiza verba de politica para supervidsor
            if (@it_VlrVrbPolSup <> 0) and (@cb_CodSup > 0)
                          begin
                            Set @it_VlrVrbPolSup = -@it_VlrVrbPolSup
                            Exec PR_AtualizaSaldoVBSSD @PCodEstabe, @cb_CodSup, @WDatCan, 0, @it_CodPrd, @it_CodLot, @it_TipSai, 'S', 'C', @PSerNot, @PNumNot, @it_VlrVrbPolSup, 'CANCELAMENTO NF', 'SISTEMA'
                            if (@@error <> 0)
                              begin
                                if @@trancount > 0
                                  Rollback Transaction
                                Return
                              end
                          end
                      end  -- if @pc_CtlSld = 'V' -- Vendedor/Operador

                    if @pc_CtlSld = 'F' -- Fabricante
                      begin
                        -- atualiza verba de politica para Vendedor. Cuidado que pode ser NF de bonificação tb
            if (@it_VlrVrbPolVdr <> 0) and (@cb_CodVdr > 0)
              begin
              Set @it_VlrVrbPolVdr = -@it_VlrVrbPolVdr
              Exec PR_AtualizaSaldoVBFSL @PCodEstabe, @cb_CodVdr, @it_CodFab, @WDatCan, 0, @it_CodPrd, @it_CodLot, @it_TipSai, 'S', 'C', @PSerNot, @PNumNot, @it_VlrVrbPolVdr, 'CANCELAMENTO NF', 'SISTEMA'
              if (@@error <> 0)
                begin
                                if @@trancount > 0
                                  Rollback Transaction
                Return
                end
              end
                      
            -- atualiza verba de politica para Operador. Cuidado que pode ser NF de bonificação tb
            if (@it_VlrVrbPolOpe <> 0) and (@cb_CodOpe > 0)
              begin
              Set @it_VlrVrbPolOpe = -@it_VlrVrbPolOpe
              Exec PR_AtualizaSaldoVBFSL @PCodEstabe, @cb_CodOpe, @it_CodFab, @WDatCan, 0, @it_CodPrd, @it_CodLot, @it_TipSai, 'S', 'C', @PSerNot, @PNumNot, @it_VlrVrbPolOpe, 'CANCELAMENTO NF', 'SISTEMA'
              if (@@error <> 0)
                begin
                                if @@trancount > 0
                                  Rollback Transaction
                Return
                end
              end
            end  -- if @pc_CtlSld = 'F' -- Fabricante

                    -- verba fornecedor   
                    Set @WValBru = Round(@it_QtdPrd*@it_PrcFab,2)
                    Set @WValEdi = Round(@it_QtdPrd*@it_PrcUniPde*(1-@it_PerDscPde/100),2)
                    if @WValEdi > 0
                      begin
                        Set @WValMov = @WValBru - @WValEdi
                        Set @WCodFor = IsNull((Select fb.Cod_ForPref From PRODU pr Inner Join FBXES fb on pr.Cod_Fabricante = fb.Cod_Fabric and @PCodEstabe = fb.Cod_Estabe
                                                Where pr.Codigo = @it_CodPrd),0)
                        if (@WCodFor > 0) and (@WValMov > 0) and (@it_TipSai = '')
                          begin
                            Set @WValMov = -@WValMov
                            Exec PR_AtualizaSaldoVBFSD @PCodEstabe, @WCodFor, @WDatCan, 0, @it_CodPrd, @it_CodLot, 'S', 'X', @PSerNot, @PNumNot, @WValMov, 'SAIDA NF', 'SISTEMA'
                            if (@@error <> 0)
                              begin
                                if @@trancount > 0
                                  Rollback Transaction
                                Return
                              end
                          end
                      end
                      
                  end

                Fetch Next From NFSIT_Cr
                  Into @it_CodPrd, @it_CodLot, @it_SeqIte, @it_QtdPrd, @it_QtdBon, @it_PrcUni,
                       @it_CodCfo, @it_PrcFab, @it_PrcUniPde, @it_PerDscPde,
                       @it_QtdPra, @it_QtdDep, @it_VlrVrbPolVdr, @it_VlrVrbPolOpe, @it_VlrVrbPolSup, @it_VlrVrbPar, 
                       @it_VlrVrbBon, @it_IdPolCom, @it_CodFab 
              end
            Close NFSIT_Cr
            Deallocate NFSIT_Cr

            if @WFlgErr = 1
              begin
                if @WMsg <> ''
                  RAISERROR(@WMsg,16,1)
                if @@trancount > 0
                  Rollback Transaction
                Return
              end

            -- cancela os titulos
            Exec PR_CancelaDevolveTitulosCTREC @PCodEstabe, @PSerNot, @PNumNot, @PNomUsu, 'C', 0, 0
            if @@error <> 0
              begin
                if @@trancount > 0
                  Rollback Transaction
                Return
              end

            -- atualiza estatisticas da nota: cabeçalho e itens
            Exec PR_AtualizaEstatisticasNFS @PCodEstabe, @PSerNot, @PNumNot, 'C'
            if @@error <> 0
              begin
                if @@trancount > 0
                  Rollback Transaction
                Return
              end

            -- atualiza verbas
            if @cb_ValDebVrbVdr > 0
              begin
                Exec PR_AtualizaSaldoVBSLD @PCodEstabe, @cb_CodVdr, @WDatCan, 0, 0, '', '', 'S', 'C', @PSerNot, @PNumNot, @cb_ValDebVrbVdr, 'CANCELAMENTO NF', 'SISTEMA'
                if (@@error <> 0)
                  begin
                    if @@trancount > 0
                      Rollback Transaction
                    Return
                  end
              end



            -- cancela o pedido
            if (@PFlgCanPdv = 1) and Exists(Select Numero From PDVCB Where Cod_Estabe = @PCodEstabe And Numero = @cb_CodPdv and Status1 <> 'C')
              begin
                Update PDVCB
                   Set Bloqueio = 'SR'
                 Where Cod_Estabe = @PCodEstabe 
                   And Numero = @cb_CodPdv and Status1 <> 'C'

                Exec PR_CancelaPDV @PCodEstabe, @Cb_CodPdv, @PNomUsu, 0
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      Rollback Transaction
                    Return
                  end
              end

            -- reabre o pedido
            if (@PFlgCanPdv = 0) and (@WFlgReaPdvOk = 1)
              begin
                Update PDVCB
                   Set Status1 = 'P',
                       Status2 = 'A',
                       Cod_SerNfs = null,
                       Cod_NumNfsIni = null,
                       Cod_NumNfsFim = null,
                       Cod_FunSeparador = 0,
                       Cod_FunConferidor = 0,
                       Cod_FunEmbalador = 0,
                       Qtd_Volumes = 0,
                       Qtd_Peso = 0,
                       Hor_PreNota = null,
                       Hor_Fatura = null,
                       Hor_Saida = null,
                       Hor_ConferIni = null,         
                       Hor_ConferFim = null         
                 Where Cod_Estabe = @PCodEstabe 
                   And Numero = @cb_CodPdv

                -- Elimina Solicitacao de Lotes
                Delete From PDVLT
                 Where Cod_Estabe = @PCodEstabe And Cod_Pedido = @cb_CodPdv

                -- Elimina a conferencia
                Delete From CPVIT
                 Where Cod_Estabe = @PCodEstabe And Num_PedCnf = @cb_CodPdv

                Delete From CPVCB
                 Where Cod_Estabe = @PCodEstabe And Num_PedCnf = @cb_CodPdv
  
                -- tem que excluir nota nao fiscal
                if @cb_CodCfo = 0
                  begin
                    Delete from NFSIT 
                     Where Cod_Estabe = @PCodEstabe 
                       and Ser_Nota = @PSerNot and Num_Nota = @PNumNot

                    Delete from NFSCB
                     Where Cod_Estabe = @PCodEstabe 
                      and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
                  end
                else
                  begin
                    Update NFSCB
                       Set Cod_Pedido = 0
                     Where Cod_Estabe = @PCodEstabe 
                       and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
                  end
              end  -- -- reabre o pedido

            -- atualiza contratos
            if (@cb_CodCtr > 0) and (@cb_NumSeqCtr > 0)
              begin
                Exec PR_RetornarItensCtrHospitalar @PCodEstabe, @cb_CodCtr, @cb_NumSeqCtr 
                if @@error <> 0
                  begin
                    if @@trancount > 0
                      Rollback Transaction
                    Return
                  end
              end

            -- atualiza itens na tabela de consignações
            if (@cb_IdConsig > 0) and (@cb_NumSeqCtr > 0)
              begin
                Exec PR_FaturaConsignacao 'S', @PCodEstabe, @PSerNot, @PNumNot, @cb_IdConsig, @cb_NumSeqCtr
                if (@@error <> 0)
                  begin
                    if @@trancount > 0
                      Rollback Transaction
                    Return
                  end
              end

            -- estorna vale
            if (@cb_TipNot = 'D') and ((@cb_CodCli > 0) or (@cb_CodFun > 0) or (@cb_CodFor > 0))
              begin
                if @cb_CodCli > 0
                  begin
                    Set @WTipDes = 'CLI'
                    Set @WCodDes = @cb_CodCli
                  end
                else
                if @cb_CodFun > 0
                  begin
                    Set @WTipDes = 'FUN'
                    Set @WCodDes = @cb_CodFun
                  end
                else
                if @cb_CodFor > 0
                  begin
                    Set @WTipDes = 'FOR'
                    Set @WCodDes = @cb_CodFor
                  end
                  
                if Exists(Select Cod_Vale From VALES
                           Where Cod_Estabe = @PCodEstabe 
                             And Cod_CtrLanAut = 'DNS'
                             And Num_CtrLanAut = @PNumNot
                             And Tip_Entid = @WTipDes
                             And Cod_Entid = @WCodDes
                             And Deb_Cre = 'D'
                             And Round(Val_Vale,2) = Round(@cb_ValNot,2))
                  begin
                    Delete From VALES
                     Where Cod_Estabe = @PCodEstabe 
                       And Cod_CtrLanAut = 'DNS'
                       And Num_CtrLanAut = @PNumNot
                       And Tip_Entid = @WTipDes
                       And Cod_Entid = @WCodDes
                       And Deb_Cre = 'D'
                       And Round(Val_Vale,2) = Round(@cb_ValNot,2)
                    if @@ROWCOUNT = 0
            begin                  
                        Set @va_IsnCtaFinDeb = 0
                        Set @va_IsnCtaFinCre = 0

                        -- pega contas gerenciais invertidas
                        if @pm_FlgUsaInterv = 1 
                          begin
                            Select @va_IsnCtaFinDeb = IsNull(Isn_CtaFinCre,0), 
                                   @va_IsnCtaFinCre = IsNull(Isn_CtaFinDeb,0)
                              From VALES
                             Where Cod_Estabe = @PCodEstabe 
                               And Cod_CtrLanAut = 'DNS'
                               And Num_CtrLanAut = @PNumNot
                               And Tip_Entid = @WTipDes
                               And Cod_Entid = @WCodDes
                               And Deb_Cre = 'D'
                          end
                  
                        -- inclui vale
                        EXEC PR_ProxNumero 'Vale', @WCodDoc output
                        if @@error <> 0
                          begin
                            if @@trancount > 0
                              Rollback Transaction
                            Return
                          end

                        Insert into VALES
                          (Cod_Estabe, Cod_Vale, Des_Vale, Tip_Entid, Cod_Entid, Dat_Emissa, Val_Vale, Deb_Cre, 
                           Cod_CtrLanAut, Num_CtrLanAut, Isn_CtaFinDeb, Isn_CtaFinCre, Usuario, Transacao)
                        Values
                          (@PCodEstabe, @WCodDoc,'NFS Cancelamento Devolucao: '+@PSerNot+'/'+cast(@PNumNot as varchar), @WTipDes, @WCodDes, @Date, @cb_ValNot, 'C',
                           'DNS', @PNumNot, @va_IsnCtaFinDeb, @va_IsnCtaFinCre, @cb_Usuario,@Now)
                      end
                  end
              end  -- estorna vale
              
          end
          
      -- exclui lançamentos em PCMOV
      while exists(Select Isn_CtaFin 
                     From PCMOV
                    Where Cod_Estabe = @PCodEstabe
                      And Nom_Tabela = 'NFSCB'
                      And Tip_Docume = 'NFS'
                      And Ser_Docume = @PSerNot
                      And Num_Docume = @PNumNot)
        begin
          Select top 1 @va_IsnCtaFinDeb = Isn_CtaFin, 
                       @va_DatMovime = Dat_Movime,
                       @va_NumSequen = Num_Sequen    
            From PCMOV
           Where Cod_Estabe = @PCodEstabe
             And Nom_Tabela = 'NFSCB'
             And Tip_Docume = 'NFS'
             And Ser_Docume = @PSerNot
             And Num_Docume = @PNumNot
    
          -- elimina registro em PCMOV
          Delete From PCMOV
           Where Cod_Estabe = @PCodEstabe
             And Nom_Tabela = 'NFSCB'
             And Tip_Docume = 'NFS'
             And Ser_Docume = @PSerNot
             And Num_Docume = @PNumNot
             And Isn_CtaFin = @va_IsnCtaFinDeb

          -- reprocessa saldo PCMOV
          Exec PR_ReprocessaPCMOV @va_IsnCtaFinDeb, @va_DatMovime
        end             

    end -- if @FlgPodeCancelar = 1

  if @@trancount > 0
    COMMIT TRANSACTION
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_GeraPedidoVendaCTRCB]
@PCodEstabe int, 
@PCodContra int, 
@PNumSequen int,  -- 0: não foi gerado CTPDC CTPDI
@PCodClient int,  -- 0: pega cliente do contrato
@PNumPdv int output,
@PMsgErr varchar(8000) output

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime

Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

Set @PNumPdv = 0
Set @PMsgErr = ''

if @PNumSequen = 0
  begin
    Set @PNumSequen = 1
    if not Exists(Select 1 From CTPDC Where Cod_Estabe = @PCodEstabe And Cod_Contrato = @PCodContra And Num_Sequencia = @PNumSequen) and
       Exists(Select 1 From CTRCB Where Cod_Estabe = @PCodEstabe And Cod_Contrato = @PCodContra And ((Sta_Contrato = '1')  or (Sta_Contrato = '2'))) and
	   Exists(Select 1 From CTRIT it Inner JOIN PRXES pr on it.Cod_Estabe = pr.Cod_Estabe and it.Cod_Produto = pr.Cod_Produt 
               Where it.Cod_Estabe = @PCodEstabe And it.Cod_Contrato = @PCodContra)
      begin
        -- inclui CTPDC
        Insert Into CTPDC (Cod_Estabe, Cod_Contrato, Num_Sequencia, Sta_CtrPed)
                   Values (@PCodEstabe, @PCodContra, @PNumSequen, '0')

        -- inclui CTPDI
        Insert Into CTPDI (Cod_Estabe, Cod_Contrato, Num_Sequencia, Cod_Produto, Qtd_Credito, Fat_CnvApr,
                           Qtd_Pedido, Prc_Unitario, Per_Desconto, Num_ItePrp, Num_SubIte)	 
          Select it.Cod_Estabe, it.Cod_Contrato, @PNumSequen, it.Cod_Produto,  it.Qtd_Credito, it.Fat_CnvApr,
                 QtdPed = Case When it.Qtd_Pedido > dbo.FN_EstoqueDisponivelPrd(pr.Cod_Estabe,pr.Cod_Produt) then dbo.FN_EstoqueDisponivelPrd(pr.Cod_Estabe,pr.Cod_Produt) Else it.Qtd_Pedido End, 
                 it.Prc_Unitario, it.Per_Desconto, it.Num_ItePrp, it.Num_SubIte
            From CTRIT it
                 Inner JOIN PRXES pr on it.Cod_Estabe = pr.Cod_Estabe and it.Cod_Produto = pr.Cod_Produt
           Where it.Cod_Estabe = @PCodEstabe
             And it.Cod_Contrato = @PCodContra
             And dbo.FN_EstoqueDisponivelPrd(pr.Cod_Estabe,pr.Cod_Produt) > 0

          -- atualiza status
          if Exists(Select 1 From CTPDI Where Cod_Estabe = @PCodEstabe and Cod_Contrato = @PCodContra and Num_Sequencia = @PNumSequen)
            Update CTPDC
               Set Sta_CtrPed = '1'
             Where Cod_Estabe = @PCodEstabe and Cod_Contrato = @PCodContra and Num_Sequencia = @PNumSequen
               And Sta_CtrPed = '0'
      end
  end

if @PCodClient = 0
  Set @PCodClient = (Select Cod_Cliente from CTRCB Where Cod_Estabe = @PCodEstabe And Cod_Contrato = @PCodContra)

if not Exists(Select 1 From CTRCB ct
                Inner Join CLIEN cl on ct.Cod_Cliente = cl.Codigo
              Where ct.Cod_Estabe = @PCodEstabe And ct.Cod_Contrato = @PCodContra) 
  begin
   RAISERROR('Cliente inválido',16,1)
   Return
  end
else
if Exists(Select 1 From CTPDC 
          Where Cod_Estabe = @PCodEstabe And Cod_Contrato = @PCodContra And Num_Sequencia = @PNumSequen And Sta_CtrPed <> '1')
  begin
    RAISERROR('Contrato não foi fechado',16,1)
    Return
  end
else
if Exists(Select 1 From CTRCB ct
           Inner Join CTPDC dt on ct.Cod_Estabe = dt.Cod_Estabe and ct.Cod_Contrato = dt.Cod_Contrato and dt.Num_Sequencia = @PNumSequen
          Where ct.Cod_Estabe = @PCodEstabe And ct.Cod_Contrato = @PCodContra And dt.Sta_CtrPed = '1') and
   Exists(Select 1 From CTPDI 
           Where Cod_Estabe = @PCodEstabe And Cod_Contrato = @PCodContra And Num_Sequencia = @PNumSequen)
  begin
    BEGIN TRANSACTION

      Declare @ct_CodVended int,
              @ct_CodOperad int,
              @ct_CodDigita int,
              @ct_PerComVnd numeric(8,4),
              @ct_NumContra varchar(15),
              @dt_IdeNotEmp varchar(20),

              @pm_FlgUsaPolComPdv bit,
              @pm_FlgAltUnvItePdv bit, 
              @pm_FlgRegDscCliItePdv bit,

              @WTipFat varchar(3),
              @WFlgUsaWms bit,
              @WFlgBlqWms bit, 
              @WFlgBlqPol bit,
              @WIdPolCom int, 
              @WCodTabPrz int, 
              @WCodLayout int,
              @WFlgBlqDscAutIte bit,
              @WFlgCriVrb bit,
              @WFlgBlqQtdPar bit, 

              @WFlgSnhEsp bit,          
              @WFlgNaoCriConCom bit,    
              @WFlgBlqCriPrcVen bit,
              @WNomUsuSnhEsp varchar(35)

      Select @pm_FlgAltUnvItePdv = IsNull(FlgAltUnvItePdv,0), 
             @pm_FlgRegDscCliItePdv = IsNull(FlgRegDscCliItePdv,0),
             @pm_FlgUsaPolComPdv = IsNull(FlgUsaPolComPdv,0)
        From PARAM
       Where Cod_Estabe = @PCodEstabe

      Select @ct_CodVended = ct.Cod_Vendedor, 
             @ct_CodOperad = ct.Cod_Operador, 
             @ct_CodDigita = ct.Cod_Digitador, 
             @ct_PerComVnd = ct.Per_ComVnd, 
             @ct_NumContra = ct.Num_Contrato, 
             @dt_IdeNotEmp = dt.Ide_NotEmp
	    From CTRCB ct
             Inner Join CTPDC dt on ct.Cod_Estabe = dt.Cod_Estabe and ct.Cod_Contrato = dt.Cod_Contrato and dt.Num_Sequencia = @PNumSequen
       Where ct.Cod_Estabe = @PCodEstabe 
         And ct.Cod_Contrato = @PCodContra
         And dt.Sta_CtrPed = '1'

      -- WMS
      Set @WFlgUsaWms = (Select dbo.FN_ModExtOk(HASHBYTES('MD5','WMS'),
                                                HASHBYTES('MD5',(Select Num_Cnpj From ESTAB Where Cod_Estabe = @PCodEstabe))))

      Set @WFlgBlqWms = 0
      Set @WFlgBlqPol = 0
      Set @WCodTabPrz = 0
      Set @WCodLayout = 0

      Set @WTipFat = 'FAT'
      Set @WIdPolCom = 0 

      Exec PR_IncluiPDVCB 'P', @PCodEstabe, @PNumPdv output, 'H', @PCodClient, @WFlgUsaWms, @WTipFat,
                          @ct_CodVended, @ct_CodOperad, @ct_CodDigita, @WIdPolCom, @WCodTabPrz, @WCodLayout,
                          @WFlgBlqWms, @WFlgBlqPol, @PMsgErr output

      Update pv
         Set pv.Status2 = 'X',    
             pv.Cod_OrigemPdv = 'HL',  -- ????  Hospitalar / Linear
             pv.Tip_Vencimento = '',
             pv.Cod_Contrato = @PCodContra,
             pv.Num_SequenciaCtr = @PNumSequen,
             pv.Ide_NotEmp = @dt_IdeNotEmp,
             pv.Per_ComVnd = @ct_PerComVnd,
             pv.Ide_Contra = @ct_NumContra,
             pv.Cod_PedCmpCli = @ct_NumContra
        From PDVCB pv
       Where pv.Cod_Estabe = @PCodEstabe
         And pv.Numero = @PNumPdv

      if @PNumPdv > 0
        begin
          Declare @WPFlgAchou bit,
                  @WPTipSai varchar(1),
                  @WPCodLot varchar(20),
                  @WPLocFis varchar(15),
                  @WPCodFab int,
                  @WPFatCnvImpFat int,
                  @WPPrcFab numeric(18,8),
                  @WPPrcMaxCon numeric(18,8),
                  @WPPrcRefFpb numeric(18,8),
                  @WPPrcCusMinComMarkup numeric(18,8),
                  @WPPrcTab numeric(18,8),
                  @WPPrcTabBru numeric(18,8),
                  @WPPrcUni numeric(18,8),
                  @WPPrcUniLiqPer numeric(18,8),
                  @WPFlgEmbDscPrc bit,
                  @WPPerDscLin numeric(18,8),
                  @WPPerDscPrz numeric(18,8),
                  @WPPerDscVis numeric(18,8),
                  @WPQtdPrzMax int,
                  @WPCodRej varchar(3),
                  @WPDesMsg varchar(80),
                  @WPCmp varchar(20),
                  @WPNomUsuDbq varchar(35),
                  @WPDesMsgDbq varchar(60),

                  @cr_NumSeq int,
                  @cr_CodPrd int,
                  @cr_QtdPed int, 
                  @cr_PrcUni numeric(18,8), 
                  @cr_PerDsc numeric(8,4), 
                  @cr_FatCnvApr int,
                  @cr_QtdImpFat numeric(18,4), 
                  @cr_PrcUniImp numeric(18,8), 
                  @cr_DesUnvImpFat varchar(3), 
                  @cr_DesAprImpFat varchar(12),
                  @cr_CodRej varchar(3),
                  @cr_DesMsg varchar(80),
                  @WIte_QtdSolInf int,
                  @WIte_QtdPedInf int, 
                  @WIte_QtdBonInf int,
                  @WIte_IdPolCom int,
      
                  @WPPerDscPolCom numeric(18,8),
                  @WPPerDscVisPolCom numeric(18,8),
                  @WPPrcPolCom numeric(18,8),
                  @WPQtdPrzPolCom int,
                  @WPCodKitPrm int,
                  @WPCodPromoc int,
                  @WPFlgVerba bit,
                  @WPFlgPolPrm bit,

                  @WPC_PrcUni numeric(18,8),
                  @WPC_PerDscIte numeric(18,8),
                  @WPPrcUniLiqPdv numeric(18,8),
                  @WPC_VlrDesconto numeric(18,8),
                  @WPC_PrcTotal numeric(18,8)

----------------------------------------------------------------------------------------

          Declare PDVIT_Cr Cursor Local Fast_Forward For

            Select NumSeq = row_number() over(Order by it.Num_Sequencia), it.Cod_Produto,
                   QtdPed = Case When it.Fat_cnvApr > 0 then it.Qtd_Pedido*it.Fat_CnvApr Else it.Qtd_Pedido End,  
				   PrcUni = Case When it.Fat_cnvApr > 0 then it.Prc_Unitario/it.Fat_CnvApr Else it.Prc_Unitario End, 
				   it.Per_Desconto, IsNull(it.Fat_CnvApr,1),
				   QtdImpFat = it.Qtd_Pedido, PrcUniImp = it.Prc_Unitario, DesUnvImpFat = c.Des_Und, 
                   DesAprImpFat = Case 
                                    When (@pm_FlgAltUnvItePdv = 0) then 'C/'+cast(c.Qtd_AprCtr as varchar)+' '+c.Des_UndVen
                                    Else Case
                                           When IsNull(ap.Cod_Apr,0) > 0 then ap.Des_Apr
                                           Else p.Aprese									   									 
                                         End
                                  End
              From CTPDI it
                   Inner Join CTRIT c  on (it.Cod_Estabe = c.Cod_Estabe and it.Cod_Contrato = c.Cod_Contrato and it.Cod_Produto = c.Cod_Produto)
                   Inner Join PRODU p  on (it.Cod_Produto = p.Codigo)
                   Left  Join PRXAP ap on (c.Cod_Produto = ap.Cod_Produt and c.Cod_Apr = ap.Cod_Apr)
             Where it.Cod_Estabe = @PCodEstabe 
               And it.Cod_Contrato = @PCodContra 
               And it.Num_Sequencia = @PNumSequen

          Open PDVIT_Cr
          Fetch Next From PDVIT_Cr Into @cr_NumSeq, @cr_CodPrd, @cr_QtdPed, @cr_PrcUni, @cr_PerDsc, @cr_FatCnvApr,
                                        @cr_QtdImpFat, @cr_PrcUniImp, @cr_DesUnvImpFat, @cr_DesAprImpFat
          While @@FETCH_STATUS = 0
            begin

              Set @WIte_QtdPedInf = @cr_QtdPed
              Set @WIte_QtdBonInf = 0
              Set @WIte_IdPolcom  = 0   -- ???????

              Set @WFlgBlqDscAutIte = 0

              Exec PR_InfoDefaultPDVIT @pm_FlgUsaPolComPdv, @PCodEstabe, @PNumPdv, @cr_CodPrd, 
                                       @WIte_QtdPedInf, @WIte_QtdBonInf, @WIte_IdPolCom output, @WFlgBlqDscAutIte,
                                       @WPFlgAchou output,
                                       @WPLocFis output,
                                       @WPCodFab output,
                                       @WPPrcFab output,
                                       @WPPrcMaxCon output,
                                       @WPPrcRefFpb output,
                                       @WPPrcTab output,
                                       @WPPrcTabBru output,
                                       @WPFatCnvImpFat output,     
                                       @WPPrcUni output,
                                       @WPPrcCusMinComMarkup output,
                                       @WPPerDscPolCom output,
                                       @WPPerDscVisPolCom output,
                                       @WPPrcPolCom output,
                                       @WPQtdPrzPolCom output,
                                       @WPFlgVerba output,
                                       @WPFlgPolPrm output,
                                       @WPCodKitPrm output,
                                       @WPCodPromoc output,
                                       @WPFlgEmbDscPrc output, 
                                       @WPQtdPrzMax output,
                                       @WPPerDscLin output,
                                       @WPPerDscPrz output,
                                       @WPPerDscVis output,
                                       @WPPrcUniLiqPer output

              if @WPFlgAchou = 1
                begin

                  Set @WPPrcUni       = @cr_PrcUni
                  Set @WPPerDscLin    = @cr_PerDsc  -- ????
                  Set @WPPerDscPrz    = @cr_PerDsc  -- ????
                  Set @WPPerDscVis    = @cr_PerDsc  -- ???
                  Set @WPCodLot       = '*'
                  Set @WPTipSai       = ''
                  Set @WPFatCnvImpFat = @cr_FatCnvApr

----------------------------------------------------------------------
                  --  calcfields 
                  Set @WPC_PrcUni = @WPPrcUni
                  Set @WPC_PerDscIte = @cr_PerDsc
                     
                  --  calcula preco unitario liquido
                  Set @WPPrcUniLiqPdv = @WPPrcUni*(1-@WPC_PerDscIte/100)
                     
                  Set @WPC_VlrDesconto = 0
                  if @WPFlgEmbDscPrc = 1
                    begin
                      Set @WPC_PrcUni = @WPPrcUni*(1-@WPC_PerDscIte/100)
                      Set @WPC_PerDscIte = 0
                    end
                     
                  Set @WPC_VlrDesconto = Round(@WIte_QtdPedInf*@WPC_PrcUni,2) - Round(@WIte_QtdPedInf*@WPC_PrcUni*(1-@WPC_PerDscIte/100),2)
                  Set @WPC_PrcTotal = Round(@WIte_QtdPedInf*@WPC_PrcUni,2) - @WPC_VlrDesconto

                  Set @WFlgSnhEsp = 0 
                  Set @WNomUsuSnhEsp = ''
                  Set @WFlgNaoCriConCom = 0  -- coloquei
                  Set @WFlgBlqCriPrcVen = 0  -- coloquei
                  Set @WFlgCriVrb = 0        -- coloquei
                  Set @WFlgBlqQtdPar = 0

                  Exec PR_CriticaItemPDV @pm_FlgUsaPolComPdv, @PCodEstabe, @PNumPdv, @cr_CodPrd, 
                                         @WIte_IdPolCom, @WIte_QtdPedInf, @WIte_QtdBonInf, @WPTipSai, @WPQtdPrzMax,
                                         @WPPrcUni, @WPPerDscVis, @WPPerDscPrz, @cr_QtdImpFat, @cr_PrcUniImp,
                                         @WPCodKitPrm, @WPPerDscPolCom, @WPPerDscVisPolCom, @WPPrcPolCom,
                                         @WPPrcUniLiqPdv, @WPPrcCusMinComMarkup, @WPPrcUniLiqPer, @WPFlgVerba,
                                         @WFlgSnhEsp, @WNomUsuSnhEsp, @WFlgNaoCriConCom, @WFlgBlqCriPrcVen, @WFlgCriVrb, @WFlgBlqQtdPar,
                                         @WPCodRej output, @WPDesMsg output, @WPCmp output, @WPNomUsuDbq output, @WPDesMsgDbq output

                  Set @WIte_QtdSolInf = @WIte_QtdPedInf + @WIte_QtdBonInf
/*
                  if (@WPDesMsg = '') or (Substring(@WPCodRej,1,2) = 'PZ')  
                    begin
                      Set @WPCodRej = ''
                      Set @WPDesMsg = ''
                    end
                  else
                    begin
                      Set @WIte_QtdPedInf = 0
                      Set @WIte_QtdBonInf = 0
                    end
*/
                  Set @WPCodRej = @cr_CodRej
                  Set @WPDesMsg = @cr_DesMsg

                  Insert Into PDVIT (
                          Cod_Estabe, Num_SeqDig, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai,
                          Qtd_Pedido, Qtd_Bonificacao, Id_PolCom, Loc_Fisica, Cod_Fabricante, 
                          Qtd_PrzMax, Prc_Fabric, Prc_MaxCon, Prc_RefFpb, Prc_Tabela, Prc_TabBru, 
                          Prc_Unitario, Per_Desconto, Per_Descon, Per_DscVis, Flg_Verba, Prc_CusMinComMarkup,
                          Qtd_PrzPolCom, Prc_PolCom, Per_DscPolCom, Per_DscVisPolCom, Cod_KitPrm, Cod_Promocao,  
                          Fat_CnvImpFat, Qtd_ImpFat, Prc_UniImpFat, Des_UnvImpFat, Des_AprImpFat, 
                          Prc_UniPde, Per_DscPde, Cod_PrjPde, Num_SeqPdc,  
                          Flg_PrcUniDsc, C_PrcUni, C_PerDscIte, C_VlrDesconto, 
                          C_PrcTotal, Prc_UniLiqPer, Qtd_Solicitado, Qtd_Acerto, Flg_PolPrm, 
                          Cod_MtvRej, Des_MtvRej, Nom_UsuDesbloq, Des_MsgDesbloq) 
                      Values (  
                          @PCodEstabe, @cr_NumSeq, @PNumPdv, @cr_CodPrd, @WPCodLot, @WPTipSai,
                          @WIte_QtdPedInf, @WIte_QtdBonInf, @WIte_IdPolCom, @WPLocFis, @WPCodFab,
                          @WPQtdPrzMax, @WPPrcFab, @WPPrcMaxCon, @WPPrcRefFpb, @WPPrcTab, @WPPrcTabBru, 
                          @WPPrcUni, @WPPerDscLin, @WPPerDscPrz, @WPPerDscVis, @WPFlgVerba, @WPPrcCusMinComMarkup,  
                          @WPQtdPrzPolCom, @WPPrcPolCom, @WPPerDscPolCom, @WPPerDscVisPolCom, @WPCodKitPrm, @WPCodPromoc,  
                          @cr_FatCnvApr, @cr_QtdImpFat, @cr_PrcUniImp, @cr_DesUnvImpFat, @cr_DesAprImpFat,
                          0, 0, '', '', 
                          @WPFlgEmbDscPrc, @WPC_PrcUni, @WPC_PerDscIte, @WPC_VlrDesconto, 
                          @WPC_PrcTotal, @WPPrcUniLiqPer, @WIte_QtdSolInf, 0, @WPFlgPolPrm, 
                          @WPCodRej, Substring(@WPDesMsg,1,40), Substring(@WPNomUsuDbq,1,15), Substring(@WPDesMsgDbq,1,60))


                  --  atualiza motivo qdo for o caso
                  Update it 
                     Set it.Cod_MtvRej = Case 
                                           When it.Qtd_Pedido > 0 then 'ES-' 
                                           Else 'ES0'
                                         End 
                    From PDVIT it 
                   Where it.Cod_Estabe = @PCodEstabe
                     And it.Cod_Pedido = @PNumPdv
                     And it.Cod_Produto = @cr_CodPrd 
                     And it.Cod_Lote = @WPCodLot
                     And it.Tip_Sai = @WPTipSai
                     And it.Qtd_Pedido < it.Qtd_Solicitado 
                     And IsNull(it.Cod_MtvRej,'') = '' 

                end  -- if @WPFlgAchou = 1

              Fetch Next From PDVIT_Cr Into @cr_NumSeq, @cr_CodPrd, @cr_QtdPed, @cr_PrcUni, @cr_PerDsc, @cr_FatCnvApr,
                                            @cr_QtdImpFat, @cr_PrcUniImp, @cr_DesUnvImpFat, @cr_DesAprImpFat

            end
          Close PDVIT_Cr
          Deallocate PDVIT_Cr

          Insert Into ITDES (Cod_Estabe, Num_Pedido, Cod_Produt, Des_PrdDet, Des_UndVen)
            Select @PCodEstabe, @PNumPdv, c.Cod_Produto, c.Des_IteCtr, it.Des_UnvImpFat
              From CTRIT c
                   Inner Join PDVIT it on c.Cod_Estabe = it.Cod_Estabe and it.Cod_Pedido = @PNumPdv and c.Cod_Produto = it.Cod_Produto
             Where c.Cod_Estabe = @PCodEstabe 
               And c.Cod_Contrato = @PCodContra 
               And c.Des_IteCtr is not null
               And not Exists(Select 1 From ITDES id 
                 			   Where it.Cod_Estabe = id.Cod_Estabe and it.Cod_Pedido = id.Num_Pedido and it.Cod_Produto = id.Cod_Produt)
               and @pm_FlgRegDscCliItePdv = 1

          Update PDVCB 
             Set Status2 = 'A'
           Where Cod_Estabe = @PCodEstabe
             And Numero = @PNumPdv

          Update CTPDC
             Set Sta_CtrPed = '2',
                 Num_PedVen = @PNumPdv
           Where Cod_Estabe = @PCodEstabe 
             And Cod_Contrato = @PCodContra 
             And Num_Sequencia = @PNumSequen

        end  -- if @PNumPdv > 0

    COMMIT TRANSACTION
  end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_GeraPedidoFaltasPDV]
@CodEstabe int,
@CodPed int,
@CodPdvGer Int Output

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

Set @CodPdvGer = 0

Declare @cl_CodCliPag int,
        @cl_@QtdMesMinPrzVctLot int,
		@cb_NumPdvPai int

Select @cl_CodCliPag = IsNull(cl.Cod_CliPag,0),
       @cl_@QtdMesMinPrzVctLot = IsNull(cl.Qtd_MesMinPrzVctLot,0),
	   @cb_NumPdvPai = IsNull(Num_PdvPai,0)
  From PDVCB cb 
	   Left Outer Join CLIEN cl on cb.Cod_Cliente = cl.Codigo
  Where cb.Cod_Estabe = @CodEstabe
  And cb.Numero = @CodPed

if Exists(Select 1
            From PDVIT it 
                 Inner Join PDVCB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Cod_Pedido = cb.Numero
            Where it.Cod_Estabe = @CodEstabe
            And it.Cod_Pedido = @CodPed
			And cb.Tip_Pedido = 'P'
            And cb.Status1 <> 'A'
            And it.Qtd_Solicitado > it.Qtd_Pedido
			And dbo.FN_QtdLoteDisponivel (@CodEstabe, @cl_CodCliPag, it.Cod_Produto, @Date, @cl_@QtdMesMinPrzVctLot, it.Id_PolCom) > 0)
  begin
    BEGIN TRANSACTION

    Declare @it_CodPrd int,
			@it_QtdDif int,
			@it_CodLot varchar(20),
			@it_TipSai varchar(1),
			@it_QtdSol int,
			@it_NumDesdob int,
			@it_CodPrdCli varchar(14),
            @pe_Cod_Layout int,
            @pe_Num_Cnpj varchar(14),   
            @pe_Cod_PedCli varchar(20),
            @pe_Num_Desdob smallint,
            @pe_Dat_LeiPed smalldatetime,
            @pe_Sta_Pedido varchar(1),
            @pe_Layout varchar(20),
            @pe_Nom_ArqPed varchar(80),
            @pe_Num_PdConv varchar(10),

			@WNumSeqDig int,
			@WQtdDec int

    -- bloqueia registro
    Update PDVCB
      Set Qtd_Itens = Qtd_Itens + 0
    Where Cod_Estabe = @CodEstabe 
    And Numero = @CodPed

    -- cria novo pedido
    EXEC PR_ProxNumero 'Pedido_Venda', @CodPdvGer output

	if @cb_NumPdvPai = 0
	  Set @cb_NumPdvPai = @CodPdvGer 
    
    -- cria cabecalho novo pedido com Tipo do bloqueio = 'SR' para nao decrementar saldo e em modo de calculo
    -- ajusta Flg_CriIteFec = 1 para nao forçar recalculo de tributos do novo pedido
    Insert into PDVCB (Cod_Estabe, Numero, Status1, Status2, Tip_Pedido, Flg_JaFechado, Qtd_ImpPnt, Dat_Pedido, Hor_Entrada,
                       Bloqueio, Flg_Calc, Cod_OrigemPdv, Transacao, Flg_CriIteFec, Tip_Faturamento,
                       Flg_ComisNormal, Flg_TabProgres, Flg_Credito, Flg_WMS,
                       Flg_CalCom, Flg_GerPdvBon, Flg_GerRetBon,
                       Cod_Cliente, Cod_RegTri, Cod_Agente, Cod_Transportadora, Cod_Rota, Des_LayoutPalm, Des_LayoutPde,
                       Cod_Gerencia, Cod_Supervisor, Cod_Vendedor, Cod_GerOpe, Cod_SupOpe, Cod_VendTlmkt, Cod_Digitador,
                       Tip_Vencimento, Qtd_PrzMed, Qtd_Parcela, Qtd_Intervalo, Tip_DscPdv, Num_Lote,
                       Per_DescontoCom, Per_DescontoFin, Msg_Bloqueio, Obs_NotFis, 
                       Tip_Consumidor, Cod_PedRem, Cod_PedCli, Usuario, Cod_Prz, Cod_TabPrc, Cod_PolCom, Id_PolCom,
                       Flg_MarkupCusCom, Tip_SaiPdv, Tip_RatBon, Tip_GerVrb, Tip_Frete,
					   Flg_CnvDscIteDscGlb, Num_PdvPai, 
					   Observacao)
                       
               Select @CodEstabe, @CodPdvGer, 'P', 'A', Tip_Pedido, 0, 0, @Date, GetDate(),
                       Bloqueio, 0, Cod_OrigemPdv, GetDate(), 1, Tip_Faturamento,
                       IsNull(Flg_ComisNormal,0), IsNull(Flg_TabProgres,0), IsNull(Flg_Credito,0), IsNull(Flg_WMS,0),
                       IsNull(Flg_CalCom,0), IsNull(Flg_GerPdvBon,0), IsNull(Flg_GerRetBon,0),
                       Cod_Cliente, Cod_RegTri, Cod_Agente, Cod_Transportadora, Cod_Rota, Des_LayoutPalm, Des_LayoutPde,
                       Cod_Gerencia, Cod_Supervisor, Cod_Vendedor, Cod_GerOpe, Cod_SupOpe, Cod_VendTlmkt, Cod_Digitador,
                       Tip_Vencimento, Qtd_PrzMed, Qtd_Parcela, Qtd_Intervalo, Tip_DscPdv, Num_Lote,
                       IsNull(Per_DescontoCom,0), IsNull(Per_DescontoFin,0), Msg_Bloqueio, Obs_NotFis, 
                       Tip_Consumidor, Cod_PedRem, Cod_PedCli, Usuario, Cod_Prz, Cod_TabPrc, Cod_PolCom, Id_PolCom,
                       IsNull(Flg_MarkupCusCom,0), Tip_SaiPdv, ISNULL(Tip_RatBon,''), Tip_GerVrb, Tip_Frete,
					   IsNull(Flg_CnvDscIteDscGlb,0), @cb_NumPdvPai,
					   'Pedido Desdobrado (mais de um lote) '
                 From PDVCB 
               Where Cod_Estabe = @CodEstabe 
               And Numero = @CodPed
    if @@error <> 0
      begin
        Rollback Transaction
        Return
      end

    -- seleciona itens
    Set @WNumSeqDig = 0

    Declare PDVIT_Cr Cursor Local Fast_Forward For 
      Select it.Cod_Produto, sum(Qtd_Solicitado-Qtd_Pedido)
        From PDVIT it
        Where it.Cod_Estabe = @CodEstabe
        And it.Cod_Pedido = @CodPed
		And IsNull(it.Tip_Sai,'') = ''
        And it.Qtd_Solicitado > it.Qtd_Pedido
		Group by it.Cod_Produto, it.Tip_Sai

    Open PDVIT_Cr
    Fetch Next From PDVIT_Cr Into @it_CodPrd, @it_QtdDif
    While @@FETCH_STATUS = 0
      begin
        -- inclui item novo pedido
        Set @WNumSeqDig = @WNumSeqDig + 1

        Insert into PDVIT (Cod_Estabe, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai,
                           Qtd_Solicitado, Qtd_Pedido, Qtd_Bonificacao, Loc_Fisica, Cod_Fabricante, Cod_Promocao,
                           Per_Desconto, Prc_Unitario, Qtd_PrzMax, Per_Descon, Per_DscVis,
                           Prc_Tabela, Prc_TabBru, Flg_PrcUniDsc, Desconto, Flg_BlqInfPar,
                           Prc_MaxCon, Prc_Fabric, Prc_RefFpb, Prc_UniLiqPer, Num_SeqDig, Nom_UsuDesbloq, 
                           Fat_CnvImpFat, Qtd_ImpFat, Des_UnvImpFat, Des_AprImpFat,
                           Id_PolCom, Flg_Verba, Prc_PolCom, Per_DscPolCom, Per_DscVisPolCom,
                           Cod_PrjPde, Prc_UniPde, Per_DscPde, Num_SeqPdc, Cod_KitPrm,
                           Per_VrbPar, Per_VrbBon, Vlr_VrbPar, Vlr_VrbBon, Vlr_DscBonRat)

              Select top 1 @CodEstabe, @CodPdvGer, Cod_Produto, '*', '',
                           @it_QtdDif, @it_QtdDif, 0, Loc_Fisica, Cod_Fabricante, Cod_Promocao,
                           IsNull(Per_Desconto,0), Prc_Unitario, Qtd_PrzMax, IsNull(Per_Descon,0), IsNull(Per_DscVis,0),
                           Prc_Tabela, Prc_TabBru, IsNull(Flg_PrcUniDsc,0), IsNull(Desconto,0), IsNull(Flg_BlqInfPar,0),
                           Prc_MaxCon, Prc_Fabric, Prc_RefFpb, Prc_UniLiqPer, @WNumSeqDig, Nom_UsuDesbloq, 
                           Fat_CnvImpFat, (Qtd_Pedido+Qtd_Bonificacao)*1.0/Fat_CnvImpFat, Des_UnvImpFat, Des_AprImpFat,
                           Id_PolCom, Flg_Verba, Prc_PolCom, IsNull(Per_DscPolCom,0), IsNull(Per_DscVisPolCom,0),
                           Cod_PrjPde, IsNull(Prc_UniPde,0), IsNull(Per_DscPde,0), Num_SeqPdc, 0,
                           0, 0, 0, 0, 0
                From PDVIT
                Where Cod_Estabe = @CodEstabe 
                and Cod_Pedido = @CodPed 
                and Cod_Produto = @it_CodPrd 
                      
        if @@error <> 0
          begin
            Rollback Transaction
            Return
          end

        Fetch Next From PDVIT_Cr Into @it_CodPrd, @it_QtdDif
      end
      
    Close PDVIT_Cr
    Deallocate PDVIT_Cr

	Delete 
	  From PDVIT
	  Where Cod_Estabe = @CodEstabe
	  And Cod_Pedido = @CodPdvGer
	  And IsNull(Qtd_Pedido,0) = 0

    if Exists(Select 1
                From PDVIT it 
                Where it.Cod_Estabe = @CodEstabe
                And it.Cod_Pedido = @CodPdvGer
                And it.Qtd_Pedido > 0)
      begin

        Exec PR_CalculaVencPDV @CodEstabe, @CodPdvGer
		if @@error <> 0
          begin
            Rollback Transaction
            Return
          end

		Exec PR_AtualizaCabecPDV @CodEstabe, @CodPdvGer
		if @@error <> 0
          begin
            Rollback Transaction
            Return
          end

        -- atualiza pedido origem
        Update PDVCB
          Set Num_PdvFilho = @CodPdvGer
          Where Cod_Estabe = @CodEstabe
          And Numero = @CodPed

        -- atualiza itens PDVIT origem
        Declare PDVIT_Cr Cursor Local Fast_Forward For 

          Select old.Cod_Produto, QtdDec = new.TotSol
		    From (Select Cod_Produto, TotSol = sum(Qtd_Solicitado)
                    From PDVIT
                    Where Cod_Estabe = @CodEstabe
                    And Cod_Pedido = @CodPed
					And Qtd_Solicitado > (Qtd_Pedido+Qtd_Bonificacao)
		            Group by Cod_Produto) old Inner Join
                 (Select Cod_Produto, TotSol = sum(Qtd_Solicitado)
                    From PDVIT
                    Where Cod_Estabe = @CodEstabe
                    And Cod_Pedido = @CodPdvGer
		            Group by Cod_Produto) new on old.Cod_Produto = new.Cod_Produto  
           Where new.TotSol > 0

        Open PDVIT_Cr
        Fetch Next From PDVIT_Cr Into @it_CodPrd, @it_QtdDif
        While @@FETCH_STATUS = 0
          begin
            -- ajusta quantidades solicitadas do pedido pai
			while (@it_QtdDif > 0) and 
			      Exists(Select 1 From PDVIT
				           Where Cod_Estabe = @CodEstabe 
                           And Cod_Pedido = @CodPed
			               And Cod_Produto = @it_CodPrd
			               And Qtd_Solicitado > Qtd_Pedido+Qtd_Bonificacao)
              begin
			    Select top 1 @it_CodLot = Cod_Lote, 
			                 @it_TipSai = Tip_Sai,
					    	 @it_QtdSol = Qtd_Solicitado-(Qtd_Pedido+Qtd_Bonificacao)
                  From PDVIT
                  Where Cod_Estabe = @CodEstabe
                  And Cod_Pedido = @CodPed
			      And Cod_Produto = @it_CodPrd
			      And Qtd_Solicitado > Qtd_Pedido+Qtd_Bonificacao

                if @it_QtdSol >= @it_QtdDif
                  Set @WQtdDec = @it_QtdDif
                else
                  Set @WQtdDec = @it_QtdSol
                Set @it_QtdDif = @it_QtdDif - @WQtdDec

				Update PDVIT
				  Set Qtd_Solicitado = Qtd_Solicitado - @WQtdDec
                  Where Cod_Estabe = @CodEstabe
                  And Cod_Pedido = @CodPed
			      And Cod_Produto = @it_CodPrd
			      And Cod_Lote = @it_CodLot
			      And Tip_Sai = @it_TipSai

			  end  -- while (@it_QtdDif> 0) and 

            Fetch Next From PDVIT_Cr Into @it_CodPrd, @it_QtdDif
          end
      
        Close PDVIT_Cr
        Deallocate PDVIT_Cr

		-- fecha pedido
        if (Select Round(sum(Vlr_Duplic),2)
            From PDVDP 
            Where Cod_Estabe = @CodEstabe
            And Cod_Pedido = @CodPdvGer) = (Select C_VlrPedido
			                                  From PDVCB
                                              Where Cod_Estabe = @CodEstabe
                                              And Numero = @CodPdvGer)
          Update PDVCB
            Set Status2 = 'F',
                Flg_JaFechado = 1,
                Hor_Fechamento = @Now,
				Hor_Liberacao = @Now
            Where Cod_Estabe = @CodEstabe
            And Numero = @CodPdvGer

        -- Se no pedido original existir registro em PDECB, gravar um novo registro para o novo pedido gerado...
        -- Isso faz com que o retorno do arquivo de nota seja gerado no DMDPe. 
        if Exists(Select Num_Cnpj From PDECB Where Cod_Estabe = @CodEstabe And Num_PedVen = @CodPed)
          begin
            Select top 1
                   @pe_Cod_Layout = Cod_Layout, 
                   @pe_Num_Cnpj = RTRIM(Num_Cnpj),   
                   @pe_Cod_PedCli = RTRIM(Cod_PedCli),
                   @pe_Dat_LeiPed = Dat_LeiPed,
                   @pe_Sta_Pedido = Sta_Pedido,
                   @pe_Layout = Layout,
                   @pe_Nom_ArqPed = Nom_ArqPed,
                   @pe_Num_PdConv = RTRIM(Num_PdConv)
              From PDECB
              Where Cod_Estabe = @CodEstabe 
              And Num_PedVen = @CodPed

            Set @pe_Num_Desdob = Isnull((Select MAX(Num_Desdob) From PDECB Where Cod_Estabe = @CodEstabe And Cod_Layout = @pe_Cod_Layout And Num_Cnpj = @pe_Num_Cnpj And Cod_PedCli = @pe_Cod_PedCli),0) + 1

            Delete From PDECB
              Where Cod_Estabe = @CodEstabe 
              and Cod_Layout = @pe_Cod_Layout
              and Num_Cnpj = @pe_Num_Cnpj 
              and Cod_PedCli = @pe_Cod_PedCli 
			  and Num_Desdob = @pe_Num_Desdob

            Insert into PDECB (Cod_Estabe, Cod_Layout, Num_Cnpj, Cod_PedCli, Num_Desdob, Dat_LeiPed, Num_PedVen, Sta_Pedido,
                               Layout, Nom_ArqPed, Num_PdConv)
                       Values (@CodEstabe, @pe_Cod_Layout, @pe_Num_Cnpj, @pe_Cod_PedCli, @pe_Num_Desdob, @pe_Dat_LeiPed, @CodPdvGer, @pe_Sta_Pedido,
                               @pe_Layout, @pe_Nom_ArqPed, @pe_Num_PdConv)
            if @@error <> 0
              begin
                Rollback Transaction
                Return
              end

            -- incluir PDEIT
            Delete From PDEIT
              Where Cod_Estabe = @CodEstabe 
              and Cod_Layout = @pe_Cod_Layout
              and Num_Cnpj = @pe_Num_Cnpj 
              and Cod_PedCli = @pe_Cod_PedCli 
			  and Num_Desdob = @pe_Num_Desdob

            Insert into PDEIT (Cod_Estabe, Cod_Layout, Num_Cnpj, Cod_PedCli, Num_Desdob, 
                               Cod_PrdCli, Tip_CodPrd, Cod_Produt, 
                               Qtd_Pedido, Qtd_Atendi, Und_Venda, Qtd_Embala, Cod_Projeto,
							   Prc_Unitario, Per_Desconto, Id_PolCom, Per_DscVis, Qtd_PrzMax,
							   Per_DscAut, Per_Descon, Cod_PrdRef)
                  Select top 1 @CodEstabe, @pe_Cod_Layout, @pe_Num_Cnpj, @pe_Cod_PedCli, @pe_Num_Desdob, 
                               it.Cod_PrdCli, it.Tip_CodPrd, it.Cod_Produt, 
                               pv.TotSol, pv.TotPed, it.Und_Venda, it.Qtd_Embala , it.Cod_Projeto,
							   it.Prc_Unitario, it.Per_Desconto, it.Id_PolCom, it.Per_DscVis, it.Qtd_PrzMax,
							   it.Per_DscAut, it.Per_Descon, it.Cod_PrdRef
                    From PDEIT it Inner Join 
                         PDECB cb on ((it.Cod_Estabe = cb.Cod_Estabe) and (it.Cod_Layout = cb.Cod_Layout) 
						          and (it.Num_Cnpj = cb.Num_Cnpj) and (it.Cod_PedCli = cb.Cod_PedCli) and (it.Num_Desdob = cb.Num_Desdob))  Inner Join
                         (Select Cod_Produto, 
			                     TotSol = sum(Qtd_Solicitado),
			                     TotPed = sum(Qtd_Pedido+Qtd_Bonificacao)
                            From PDVIT
                            Where Cod_Estabe = @CodEstabe
                            And Cod_Pedido = @CodPdvGer
		                    Group by Cod_Produto) pv on it.Cod_Produt = pv.Cod_Produto
                    Where it.Cod_Estabe = @CodEstabe      
                    and it.Cod_Layout = @pe_Cod_Layout
                    And it.Num_Cnpj = @pe_Num_Cnpj 
                    and it.Cod_PedCli = @pe_Cod_PedCli 
                    and it.Cod_Produt = @it_CodPrd 
                    and cb.Num_PedVen = @CodPed

            -- Atualizar PDECB do novo pedido
            if @pe_Num_Cnpj <> ''
              Update cb
                Set cb.Vlr_Total = IsNull(it.VlrTot,0)
                From PDECB cb Inner Join 
                     (Select Cod_Estabe, Cod_Layout, Num_Cnpj, Cod_PedCli, Num_Desdob,
                             VlrTot = sum(Round(Qtd_Pedido*Prc_Unitario*(1-IsNull(Per_Desconto,0)/100),2)) 
                        From PDEIT
                        Where Cod_Estabe = @CodEstabe 
                        And Cod_Layout = @pe_Cod_Layout
                        And Num_Cnpj = @pe_Num_Cnpj
                        And Cod_PedCli = @pe_Cod_PedCli
					    And Num_Desdob = @pe_Num_Desdob
                        Group by Cod_Estabe, Cod_Layout, Num_Cnpj, Cod_PedCli, Num_Desdob) it on ((cb.Cod_Estabe = it.Cod_Estabe) and
                                                                                                  (cb.Cod_Layout = it.Cod_Layout) and
                                                                                                  (cb.Num_Cnpj = it.Num_Cnpj) and 
                                                                                                  (cb.Cod_PedCli = it.Cod_PedCli) and 
                                                                                                  (cb.Num_Desdob = it.Num_Desdob))

            -- Atualizar PDEIT do pedido origem
            Declare PDEIT_Cr Cursor Local Fast_Forward For 

              Select old.Cod_Produt, QtdDec = new.TotSol
                From (Select Cod_Produt, TotSol = sum(Qtd_Pedido)
                        From PDEIT
                        Where Cod_Estabe = @CodEstabe      
                        and Cod_Layout = @pe_Cod_Layout
                        and Num_Cnpj = @pe_Num_Cnpj 
                        and Cod_PedCli = @pe_Cod_PedCli 
			            and Num_Desdob <> @pe_Num_Desdob
				        and Qtd_Pedido > Qtd_Atendi
				        Group by Cod_Produt) old Inner Join
                     (Select Cod_Produt, TotSol = sum(Qtd_Pedido)
                        From PDEIT 
                        Where Cod_Estabe = @CodEstabe 
                        And Cod_Layout = @pe_Cod_Layout
                        And Num_Cnpj = @pe_Num_Cnpj
                        And Cod_PedCli = @pe_Cod_PedCli
			            And Num_Desdob = @pe_Num_Desdob
				        Group by Cod_Produt) new on old.Cod_Produt = new.Cod_Produt  
               Where new.TotSol > 0

            Open PDEIT_Cr
            Fetch Next From PDEIT_Cr Into @it_CodPrd, @it_QtdDif
            While @@FETCH_STATUS = 0
              begin
                -- ajusta quantidades solicitadas do pedido pai
		    	while (@it_QtdDif > 0) and 
			          Exists(Select 1 From PDEIT
                               Where Cod_Estabe = @CodEstabe      
                               and Cod_Layout = @pe_Cod_Layout
                               and Num_Cnpj = @pe_Num_Cnpj 
                               and Cod_PedCli = @pe_Cod_PedCli 
			                   and Num_Desdob <> @pe_Num_Desdob
			                   and Cod_Produt = @it_CodPrd
				               and Qtd_Pedido > Qtd_Atendi)
                  begin
			        Select top 1 @it_CodPrdCli = Cod_PrdCli, 
			                     @it_NumDesdob = Num_Desdob,
		    			    	 @it_QtdSol = Qtd_Pedido-Qtd_Atendi
                      From PDEIT
                      Where Cod_Estabe = @CodEstabe      
                      and Cod_Layout = @pe_Cod_Layout
                      and Num_Cnpj = @pe_Num_Cnpj 
                      and Cod_PedCli = @pe_Cod_PedCli 
                      and Num_Desdob <> @pe_Num_Desdob
		              and Cod_Produt = @it_CodPrd
			          and Qtd_Pedido > Qtd_Atendi

                    if @it_QtdSol >= @it_QtdDif
                      Set @WQtdDec = @it_QtdDif
                    else
                      Set @WQtdDec = @it_QtdSol
                    Set @it_QtdDif = @it_QtdDif - @WQtdDec

    				Update PDEIT
	    			  Set Qtd_Pedido = Qtd_Pedido - @WQtdDec
                      Where Cod_Estabe = @CodEstabe
                      and Cod_Layout = @pe_Cod_Layout
                      and Num_Cnpj = @pe_Num_Cnpj 
                      and Cod_PedCli = @pe_Cod_PedCli 
                      and Num_Desdob = @it_NumDesdob
                      and Cod_PrdCli = @it_CodPrdCli

    			  end  -- while (@it_QtdDif> 0) and 

                Fetch Next From PDEIT_Cr Into @it_CodPrd, @it_QtdDif
              end
      
            Close PDEIT_Cr
            Deallocate PDEIT_Cr

          end  -- if Exists(Select Num_Cnpj From PDECB Where Cod_Estabe = @CodEstabe And Num_PedVen = @CodPed)

      end  -- if Exists(Select 1
    else
      begin
		Delete From PDVIT
          Where Cod_Estabe = @CodEstabe
          And Cod_Pedido = @CodPdvGer

		Delete From PDVCB
          Where Cod_Estabe = @CodEstabe
          And Numero = @CodPdvGer

		Set @CodPdvGer = 0
	  end

    COMMIT TRANSACTION
  end

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_GeraPedidoConsolidado]
@PIdPdvCon int,
@PTipOpe varchar(3), 
@PCodCli int,
@PCodVdr int,
@PCodOpe int,
@PDesUsu varchar(35),
@PMsgErr varchar(8000) output

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime

Set @Now  = GetDate()
Set @Date = cast(GetDate() as date)

Declare @CodEstabe int = 0,
        @NumPdv int = 0

Select @CodEstabe = Cod_Estabe, 
       @NumPdv = Num_PdvCon
  From PVCCB 
  Where Id_PdvCon = @PIdPdvCon

--Ajusta descrição usuario conforme função existente para evitar erro de "truncate" OUTROS-679
Set @PDesUsu = dbo.FN_UsuarioInfarma()


if (Select Sta_PdvCon From PVCCB Where Id_PdvCon = @PIdPdvCon)  <> '1'
  RAISERROR('Lote de Pedidos Matriz x Filiais não está aberto',16,1)
else
if (Select count(*) From PVCIT Where Id_PdvCon = @PIdPdvCon) = 0
  RAISERROR('Não Existem pedidos vinculados a este lote de pedidos',16,1)
else
if not Exists(Select Cod_Ope From TPOPE Where Cod_Ope = @PTipOpe and Tip_EntSai = 'S')
  RAISERROR('Tipo de Operação parametrizado inválido',16,1)
else
if not Exists(Select Codigo From CLIEN Where Codigo = @PCodCli)
  RAISERROR('Cliente parametrizado inválido',16,1)
else
if not Exists(Select Codigo From VENDE Where Codigo = @PCodVdr)
  RAISERROR('Vendedor parametrizado inválido',16,1)
else
if not Exists(Select Codigo From VENDE Where Codigo = @PCodOpe)
  RAISERROR('Operador parametrizado inválido',16,1)
else
if Exists(Select 1
          From PVCIT v
               Inner Join PDVCB cb on v.Cod_Estabe = cb.Cod_Estabe and v.Cod_Pedido = cb.Numero
	           Inner Join (Select Cod_Estabe, Cod_Pedido, Cod_Produto, QtdPdv=sum(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0))
	                       From PDVIT 
                           Where (IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) > 0
                           Group by Cod_Estabe, Cod_Pedido, Cod_Produto) it on cb.Cod_Estabe = it.Cod_Estabe and cb.Numero = it.Cod_pedido
               Full Join  (Select Cod_Estabe, Cod_Pedido, Cod_Produt, QtdLot=sum(IsNull(Qtd_Lote,0))
	                       From PDVLT 
			      	     Where IsNull(Qtd_Lote,0) > 0
				     Group by Cod_Estabe, Cod_Pedido, Cod_Produt) lt on cb.Cod_Estabe = lt.Cod_Estabe and cb.Numero = lt.Cod_pedido and it.Cod_Produto = lt.Cod_produt
          Where v.Id_Pdvcon = @PIdPdvCon
          And IsNull(cb.Flg_WMS,0) = 1
          And IsNull(it.QtdPdv,0) <> IsNull(lt.QtdLot,0))
  begin
    -- verifica divergencia entre PDVIT x PDVLT, se for o caso (WNMS)
    Declare @WCodPrd int,
            @WQtdPed int,
			@WQtdLot int,
            @WMsg varchar(50)

    Select top 1 
           @WCodPrd = Case When IsNull(it.Cod_Produto,0) > 0 then it.Cod_Produto else lt.Cod_Produt End, 
           @WQtdPed = IsNull(it.QtdPdv,0), @WQtdLot = IsNull(lt.QtdLot,0)
    From PVCIT v
         Inner Join PDVCB cb on v.Cod_Estabe = cb.Cod_Estabe and v.Cod_Pedido = cb.Numero
	     Inner Join (Select Cod_Estabe, Cod_Pedido, Cod_Produto, QtdPdv=sum(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0))
	                 From PDVIT 
                     Where (IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) > 0
                     Group by Cod_Estabe, Cod_Pedido, Cod_Produto) it on cb.Cod_Estabe = it.Cod_Estabe and cb.Numero = it.Cod_pedido
         Full Join  (Select Cod_Estabe, Cod_Pedido, Cod_Produt, QtdLot=sum(IsNull(Qtd_Lote,0))
	                 From PDVLT 
				     Where IsNull(Qtd_Lote,0) > 0
				     Group by Cod_Estabe, Cod_Pedido, Cod_Produt) lt on cb.Cod_Estabe = lt.Cod_Estabe and cb.Numero = lt.Cod_pedido and it.Cod_Produto = lt.Cod_produt
    Where v.Id_Pdvcon = @PIdPdvCon
    And IsNull(cb.Flg_WMS,0) = 1
    And IsNull(it.QtdPdv,0) <> IsNull(lt.QtdLot,0)
         
    Set @WMsg = 'Existe divergência de quantidade em PDVIT x PDVLT. Produto = '+CAST(@WCodPrd as varchar)
    RAISERROR(@WMsg,16,1)
  end
else                 
if @NumPdv > 0
  begin
    Begin Transaction

      Declare @CodEstCan int,
              @NumPdvCan int,
			  @FlgWmsCan bit,
              @CodOriPdv varchar(2) = '',
              @TotUndPdvCon int = 0,
              @TotUndPdvCan int = 0,

              @TipPrc varchar(1) = 'V',
			  @CodTabPrc int = 0,
              @WUndTotIte int = 0,
              @WUndTotSol int = 0,
              @WQtdItePrdLot int = 0,
              @WAccQtdIte int = 0,
              @WAccQtdSol int = 0,
              @WFatParIte numeric(18,8) = 0,

              @NumSeqDig int = 0,
              @PrcUni numeric(18,8) = 0,
              @CodPrdAnt int, 
              @CodPrd int, 
              @CodLot varchar(20),
			  @TipSai varchar(1),
              @CodDep smallint, 
              @NumRua smallint, 
              @NumCol smallint, 
              @NumNiv smallint, 
              @NumApt smallint, 
              @QtdPra int,
              @QtdDep int,
              @QtdTot int, 
              @QtdSol int,
              @QtdAce int, 
              @QtdPed int,
              @QtdBon int,
              @QtdPen int,

              @FatCnvImpFat int,
              @QtdImpFat int,
              @PrcUniImpFat numeric(18,8),
              @FlgUsaWms bit = 0,
              @FlgBlqWms bit = 0,        -- nunca usa WMS
              @FlgBlqPol bit = 0         -- nunca usa politica

	  Set @PMsgErr = ''
      Set @CodOriPdv = ''

      -- gera pedido sem wms, sem politica
      Set @FlgUsaWms = 0
      Set @FlgBlqWms = 1 
      Set @FlgBlqPol = 1

      -- cria pedido e coloca-o em processamento: Flg_Calc = 1
      Exec PR_IncluiPDVCB 'P', @CodEstabe, @NumPdv output, 'A', @PCodCli, @FlgUsaWms,
                          @PTipOpe, @PCodVdr, @PCodOpe, 0, 0, 0, 0,
                          @FlgBlqWms, @FlgBlqPol, @PMsgErr output
						  
	  if (@@error <> 0)
	    begin
		  Rollback Transaction
		  Return
		end

      if @PMsgErr = ''
        begin
          -- tipo de preço 
          Set @TipPrc = IsNull((Select Tip_Prc From TPOPE Where Cod_Ope = @PTipOpe),'V')
          Set @CodTabPrc = IsNull((Select Cod_TabPrc From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @NumPdv),0)
          Set @CodOriPdv = (Select IsNull(Cod_OrigemPdv,'') From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @NumPdv)

          -- coloca em processamento: Flg_Calc = 1
	      Update PDVCB
	        Set Num_Referencia = @NumPdv,
	    	    Cod_OrigemPdv = @CodOriPdv,
		    	Flg_WMS = 0, 
		    	Flg_Calc = 1
	      Where Cod_Estabe = @CodEstabe
	      And Numero = @NumPdv

          -- IncluiItens
          -- Seleciona pedidos vinculados ao lote
          DECLARE Pdvcb_Cr CURSOR Local Fast_Forward For 
            Select ic.Cod_Estabe, ic.Cod_Pedido, IsNull(cb.Flg_WMS,0) 
	          From PVCIT ic
			       Inner Join PDVCB cb on ic.Cod_Estabe = cb.Cod_Estabe and ic.Cod_Pedido = cb.Numero
		      Where ic.Id_PdvCon = @PIdPdvCon
          OPEN Pdvcb_Cr
          FETCH NEXT FROM Pdvcb_Cr INTO @CodEstCan, @NumPdvCan, @FlgWmsCan
          WHILE @@FETCH_STATUS = 0
          BEGIN
            Update PDVCB 
              Set Num_Referencia = @NumPdv,
		          Status1 = 'C',
                  Bloqueio = 'SR',
                  Flg_Credito = null,
                  Usuario = @PDesUsu,
                  Transacao = GetDate(),
                  Flg_Calc = 0 
              Where Cod_Estabe = @CodEstCan
              And Numero = @NumPdvCan

            -- transfere lotes de PRLTL p/ PRLOT se for o caso -----------------------------------------------------------
            -- inclui lotes em PRLOT
            DECLARE Table_Cr Cursor Local Fast_Forward For 

              Select Cod_Produt, Cod_Lote, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Qtd_LotePra, Qtd_LoteDep, Qtd_Lote 
                From PDVLT 
                Where Cod_Estabe = @CodEstCan 
                And Cod_Pedido = @NumPdvCan 
                And Cod_LocFis = 'PRLTL'

            OPEN Table_Cr 
            FETCH NEXT FROM Table_Cr INTO @CodPrd, @CodLot, @CodDep,  @NumRua, @NumCol, @NumNiv, @NumApt, @QtdPra, @QtdDep, @QtdTot 
            WHILE @@FETCH_STATUS = 0 
            BEGIN 
              -- registra PRLOT
              Insert into PRLOT (Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote, Dat_Vencim, Qtd_FisPra, Qtd_SolPra, Qtd_FisDep, Qtd_SolDep) 
                      Select ldp.Cod_Estabe, ldp.Cod_Dep, ldp.Cod_Produt, ldp.Cod_Lote, ldp.Dat_Vencim, 0, 0, 0, 0 
                        From PRLTL ldp Left Outer Join 
                             PRLOT lpk on (ldp.Cod_Estabe = lpk.Cod_Estabe and ldp.Cod_Produt = lpk.Cod_Produt and ldp.Cod_Lote = lpk.Cod_Lote) 
                        Where ldp.Cod_Estabe = @CodEstCan 
                        and ldp.Cod_Produt = @CodPrd 
                        and ldp.Cod_Lote = @CodLot 
                        and ldp.Cod_Dep = @CodDep 
                        and ldp.Num_Rua = @NumRua and ldp.Num_Col = @NumCol 
                        and ldp.Num_Niv = @NumNiv and ldp.Num_Apt = @NumApt 
                        and lpk.Cod_Produt is null 

              -- decrementa PRLTL
              Update PRLTL 
                Set Qtd_FisPra = Qtd_FisPra - @QtdPra, 
                    Qtd_SolPra = Qtd_SolPra - @QtdPra 
                Where Cod_Estabe = @CodEstCan 
                and Cod_Produt = @CodPrd 
                and Cod_Lote = @CodLot 
                and Cod_Dep = @CodDep 
                and Num_Rua = @NumRua and Num_Col = @NumCol 
                and Num_Niv = @NumNiv and Num_Apt = @NumApt 
                and @QtdPra > 0 

              Update PRLTL 
                Set Qtd_FisDep = Qtd_FisDep - @QtdDep, 
                    Qtd_SolDep = Qtd_SolDep - @QtdDep 
                Where Cod_Estabe = @CodEstCan 
                and Cod_Produt = @CodPrd 
                and Cod_Lote = @CodLot 
                and Cod_Dep = @CodDep 
                and Num_Rua = @NumRua and Num_Col = @NumCol 
                and Num_Niv = @NumNiv and Num_Apt = @NumApt 
                and @QtdDep > 0 

              -- transfere para PRLOT
              Update PRLOT 
                Set Qtd_FisPra = Qtd_FisPra + @QtdPra + @QtdDep, 
                    Qtd_SolPra = Qtd_SolPra + @QtdPra + @QtdDep 
                Where Cod_Estabe = @CodEstCan 
                and Cod_Dep = @CodDep 
                and Cod_Produt = @CodPrd 
                and Cod_Lote = @CodLot 

              FETCH NEXT FROM Table_Cr INTO @CodPrd, @CodLot, @CodDep,  @NumRua, @NumCol, @NumNiv, @NumApt, @QtdPra, @QtdDep, @QtdTot 
            END 
            CLOSE Table_Cr 
            DEALLOCATE Table_Cr 
            -- fim transfere lotes de PRLTL p/ PRLOT se for o caso -----------------------------------------------------------

---------------------------------------------------------------------------------------------------------------------------------------
			-- inclui itens no pedido consolidado
            Set @NumSeqDig = 0
            if @FlgWmsCan = 1
              begin
                DECLARE Pdvlt_Cr CURSOR Local Fast_Forward For 
                  SELECT Cod_Produt, Cod_Lote, QtdPed = sum(Qtd_Lote), QtdBon = 0
                    FROM PDVLT 
                    Where Cod_Estabe =  @CodEstCan 
                    And Cod_Pedido = @NumPdvCan 
                    GROUP BY Cod_Produt, Cod_Lote
					ORDER BY Cod_Produt
                OPEN Pdvlt_Cr
                FETCH NEXT FROM Pdvlt_Cr INTO @CodPrd, @CodLot, @QtdPed, @QtdBon
                WHILE @@FETCH_STATUS = 0
                BEGIN
				  Set @CodPrdAnt = @CodPrd

	    		  Set @WUndTotIte = IsNull((Select SUM(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0))
                                              From PDVIT 
                                              Where Cod_Estabe = @CodEstCan And Cod_Pedido = @NumPdvCan 
                                              And Cod_Produto = @CodPrd),0)

	    		  Set @WUndTotSol = IsNull((Select SUM(IsNull(Qtd_Solicitado,0))
                                              From PDVIT 
                                              Where Cod_Estabe = @CodEstCan And Cod_Pedido = @NumPdvCan 
                                              And Cod_Produto = @CodPrd),0)

                  Set @WQtdItePrdLot = (Select count (*) 
                                          From (Select distinct Cod_Produt, Cod_Lote
                                                  From PDVLT
                                                  Where Cod_Estabe = @CodEstCan
                                                  And Cod_Pedido = @NumPdvCan
                                                  And Cod_Produt = @CodPrd) t)

                  Set @PrcUni = dbo.FN_PrecoProduto (@CodEstabe, @TipPrc, @CodPrd, @CodTabPrc)

                  Set @WAccQtdIte = 0
                  Set @WAccQtdSol = 0

				  WHILE (@CodPrdAnt = @CodPrd) and (@@FETCH_STATUS = 0) 
				    begin
                      Set @WAccQtdIte = @WAccQtdIte + 1
                      -- participacao do item
                      Set @WFatParIte = @QtdPed*1.0/@WUndTotIte

                      if @WAccQtdIte = @WQtdItePrdLot
                        begin
                          Set @QtdSol =  @WUndTotSol - @WAccQtdSol
                        end
                      else
                        begin
                          Set @QtdSol = @QtdPed
                          Set @WAccQtdSol = @WAccQtdSol + @QtdSol
                        end

                      Set @QtdAce = 0
                      Set @QtdPen = 0
                      Set @TipSai = ''

                      -- normaliza valores
                      Set @QtdPra = @QtdPed+@QtdBon
                      Set @QtdDep = 0
                      Set @QtdImpFat = (@QtdPed+@QtdBon)/@FatCnvImpFat

                      if not Exists( Select 1 From PDVIT
                                       Where Cod_Estabe = @CodEstabe
                                       And Cod_Pedido = @NumPdv
									   And Cod_Produto = @CodPrd
                                       And Cod_Lote = @CodLot
                                       And Tip_Sai = @TipSai)						 
                        begin
                          Insert Into PDVIT (Cod_Estabe, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai,
                                             Num_SeqDig, Prc_Unitario, 
                                             Qtd_Solicitado, Qtd_Acerto, Qtd_Pedido, Qtd_Bonificacao, 
		    			                     Qtd_Pendente, Qtd_Pra, Qtd_Dep, Qtd_ImpFat)
                                     Values (@CodEstabe, @NumPdv, @CodPrd, @CodLot, @TipSai,
                                             @NumSeqDig, @PrcUni, 
                                             0, 0, 0, 0, 0, 0, 0, 0)

                          Update it
                            Set Cod_Fabricante = ic.Cod_Fabricante,
                                Loc_Fisica = ic.Loc_Fisica,
                                Flg_PrcUniDsc = ISNULL(ic.Flg_PrcUniDsc,0),
                                Per_Desconto = 0,
                                Per_Descon = 0,
                                Per_DscVis = 0,
                                Qtd_PrzMax = ISNULL(ic.Qtd_PrzMax,0),
                                Cod_Promocao = ISNULL(ic.Cod_Promocao,0),
                                Des_Und = ic.Des_Und,
                                Qtd_AprPdv = ic.Qtd_AprPdv,
                                Des_UndVen = ic.Des_UndVen,
                                Flg_Entreg = ISNULL(ic.Flg_Entreg,0),
							 
                                Prc_TabBru = ic.Prc_TabBru,
                                Prc_Tabela = ic.Prc_Tabela,
                                Prc_MaxCon = ic.Prc_MaxCon,
                                Prc_Fabric = ic.Prc_Fabric,
								 
                                Nom_UsuDesbloq = ic.Nom_UsuDesbloq,
                                Des_UnvImpFat = ic.Des_UnvImpFat,
                                Des_AprImpFat = ic.Des_AprImpFat,
                                Flg_VctLic = ISNULL(ic.Flg_VctLic,0)
                          From PDVIT it, (Select top 1 * 
                                          From PDVIT 
                                          Where Cod_Estabe = @CodEstCan 
	                                      And Cod_Pedido = @NumPdvCan 
                                          And Cod_Produto = @CodPrd
					                      Order by Tip_Sai) ic 
                          Where it.Cod_Estabe = @CodEstabe
                          And it.Cod_Pedido = @NumPdv
                          And it.Cod_Lote = @CodLot
                          And it.Tip_Sai = @TipSai						 
                          And ic.Cod_Estabe = @CodEstCan 
                          And ic.Cod_Pedido = @NumPdvCan
                          And it.Cod_Produto = ic.Cod_Produto
                        end

                      Update PDVCB 
                        Set Flg_Calc = 1 
                        Where Cod_Estabe = @CodEstabe
                        And Numero = @NumPdv
                        And IsNull(Flg_Calc,0) = 0 

                      -- normaliza valores
	        		  Set @FatCnvImpFat = (Select top 1 Fat_CnvImpFat 
		        	                       From PDVIT 
			        					   Where Cod_Estabe = @CodEstabe And Cod_Pedido = @NumPdv And Cod_Produto = @CodPrd)

                      Set @QtdPra = @QtdPed+@QtdBon
                      Set @QtdDep = 0
                      Set @QtdImpFat = (@QtdPed+@QtdBon)/@FatCnvImpFat

                      Update PDVIT
                        Set Qtd_Solicitado = Qtd_Solicitado + @QtdSol, 
                            Qtd_Acerto = Qtd_Acerto + @QtdAce, 
                            Qtd_Pedido = Qtd_Pedido + @QtdPed, 
                            Qtd_Bonificacao = Qtd_Bonificacao + @QtdBon, 
                            Qtd_Pendente = Qtd_Pendente + @QtdPen,
                            Qtd_Pra = Qtd_Pra + @QtdPra,
                            Qtd_Dep = Qtd_Dep + @QtdDep,
                            Qtd_ImpFat = Qtd_ImpFat + @QtdImpFat,
                            Prc_UniImpFat = Prc_Unitario*@FatCnvImpFat
                        Where Cod_Estabe = @CodEstabe
                        And Cod_Pedido = @NumPdv
                        And Cod_Produto = @CodPrd
                        And Cod_Lote = @CodLot
                        And Tip_Sai = @TipSai

                      FETCH NEXT FROM Pdvlt_Cr INTO @CodPrd, @CodLot, @QtdPed, @QtdBon
					end
                END
                CLOSE Pdvlt_Cr
                DEALLOCATE Pdvlt_Cr

              end
            else
              begin
                DECLARE Pdvit_Cr CURSOR Local Fast_Forward For 
                  Select Cod_Produto, Cod_Lote, 
                         sum(IsNull(Qtd_Solicitado,0)), sum(IsNull(Qtd_Pedido,0)), sum(IsNull(Qtd_Bonificacao,0)), 0, 0,
                         sum(IsNull(Qtd_Pra,0)+IsNull(Qtd_Dep,0)), 0
                    From PDVIT
                    Where Cod_Estabe =  @CodEstCan 
                    And Cod_Pedido = @NumPdvCan 
                    And (IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) > 0
				    Group by Cod_Produto, Cod_Lote
                OPEN Pdvit_Cr
                FETCH NEXT FROM Pdvit_Cr INTO @CodPrd, @CodLot, 
                                              @QtdSol, @QtdPed, @QtdBon, @QtdAce, @QtdPen,
                                              @QtdPra, @QtdDep 
                WHILE @@FETCH_STATUS = 0
                BEGIN   
                  -- checa se o produto já está no novo pedido
                  if not Exists(Select 1 From PDVIT
                                  Where Cod_Estabe = @CodEstabe
                                  And Cod_Pedido = @NumPdv
                                  And Cod_Produto = @CodPrd
                                  And Cod_Lote = @CodLot
								  And Tip_Sai = @TipSai)
                    begin
                      Set @NumSeqDig = @NumSeqDig + 1 
    				  Set @TipSai = ''
	    			  Set @PrcUni = dbo.FN_PrecoProduto (@CodEstabe, @TipPrc, @CodPrd, @CodTabPrc)

                      Insert Into PDVIT (Cod_Estabe, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai,
                                         Num_SeqDig, Prc_Unitario, 
                                         Qtd_Solicitado, Qtd_Acerto, Qtd_Pedido, Qtd_Bonificacao, 
					                     Qtd_Pendente, Qtd_Pra, Qtd_Dep, Qtd_ImpFat)
                                 Values (@CodEstabe, @NumPdv, @CodPrd, @CodLot, @TipSai,
                                         @NumSeqDig, @PrcUni, 
                                         0, 0, 0, 0, 0, 0, 0, 0)

                      Update it
                        Set Cod_Fabricante = ic.Cod_Fabricante,
                            Loc_Fisica = ic.Loc_Fisica,
                            Flg_PrcUniDsc = ISNULL(ic.Flg_PrcUniDsc,0),
                            Per_Desconto = 0,
                            Per_Descon = 0,
                            Per_DscVis = 0,
                            Qtd_PrzMax = ISNULL(ic.Qtd_PrzMax,0),
                            Cod_Promocao = ISNULL(ic.Cod_Promocao,0),
                            Des_Und = ic.Des_Und,
                            Qtd_AprPdv = ic.Qtd_AprPdv,
                            Des_UndVen = ic.Des_UndVen,
                            Flg_Entreg = ISNULL(ic.Flg_Entreg,0),
							 
                            Prc_TabBru = ic.Prc_TabBru,
                            Prc_Tabela = ic.Prc_Tabela,
                            Prc_MaxCon = ic.Prc_MaxCon,
                            Prc_Fabric = ic.Prc_Fabric,

                            Nom_UsuDesbloq = ic.Nom_UsuDesbloq,
                            Des_UnvImpFat = ic.Des_UnvImpFat,
                            Des_AprImpFat = ic.Des_AprImpFat,
                            Flg_VctLic = ISNULL(ic.Flg_VctLic,0)
                      From PDVIT it, PDVIT ic 
                      Where it.Cod_Estabe = @CodEstabe
                      And it.Cod_Pedido = @NumPdv
                      And ic.Cod_Estabe = @CodEstCan 
                      And ic.Cod_Pedido = @NumPdvCan
                      And it.Cod_Produto = ic.Cod_Produto
                      And it.Cod_Lote = ic.Cod_Lote
                      And it.Tip_Sai = @TipSai						 
                    end

                  Update PDVCB 
                    Set Flg_Calc = 1 
                    Where Cod_Estabe = @CodEstabe
                    And Numero = @NumPdv
                    And IsNull(Flg_Calc,0) = 0 

                  -- normaliza valores
	    		  Set @FatCnvImpFat = (Select top 1 Fat_CnvImpFat 
		    	                       From PDVIT 
			    					   Where Cod_Estabe = @CodEstabe And Cod_Pedido = @NumPdv And Cod_Produto = @CodPrd)

                  Set @QtdPra = @QtdPed+@QtdBon
                  Set @QtdDep = 0
                  Set @QtdImpFat = (@QtdPed+@QtdBon)/@FatCnvImpFat

                  Update PDVIT
                    Set Qtd_Solicitado = Qtd_Solicitado + @QtdSol, 
                        Qtd_Acerto = Qtd_Acerto + @QtdAce, 
                        Qtd_Pedido = Qtd_Pedido + @QtdPed, 
                        Qtd_Bonificacao = Qtd_Bonificacao + @QtdBon, 
                        Qtd_Pendente = Qtd_Pendente + @QtdPen,
                        Qtd_Pra = Qtd_Pra + @QtdPra,
                        Qtd_Dep = Qtd_Dep + @QtdDep,
                        Qtd_ImpFat = Qtd_ImpFat + @QtdImpFat,
                        Prc_UniImpFat = Prc_Unitario*@FatCnvImpFat
                    Where Cod_Estabe = @CodEstabe
                    And Cod_Pedido = @NumPdv
                    And Cod_Produto = @CodPrd
                    And Cod_Lote = @CodLot
                    And Tip_Sai = @TipSai

                  FETCH NEXT FROM Pdvit_Cr INTO @CodPrd, @CodLot, 
                                                @QtdSol, @QtdPed, @QtdBon, @QtdAce, @QtdPen,
                                                @QtdPra, @QtdDep
                END
                CLOSE Pdvit_Cr
                DEALLOCATE Pdvit_Cr

              end

            FETCH NEXT FROM Pdvcb_Cr INTO @CodEstCan, @NumPdvCan, @FlgWmsCan
          END
          CLOSE Pdvcb_Cr
          DEALLOCATE Pdvcb_Cr
-------------------------------------------------------------------------------------------------------

          Set @TotUndPdvCon = 0
          Set @TotUndPdvCan = 0

          Select @TotUndPdvCon = sum(Qtd_Pedido+IsNull(Qtd_Bonificacao,0)) 
            From PDVIT 
            Where Cod_Estabe = @CodEstabe
            And Cod_Pedido = @NumPdv
  
          Select @TotUndPdvCan = sum(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0)) 
            From PDVIT it
                 Inner Join PVCIT ic on it.Cod_Estabe = ic.Cod_Estabe and it.Cod_Pedido = ic.Cod_Pedido 
            Where ic.Id_PdvCon = @PIdPdvCon

          if (IsNull(@TotUndPdvCon,0) <> IsNull( @TotUndPdvCan,0)) or 
	         (IsNull(@TotUndPdvCon,0) = 0)
            begin
              Set @PMsgErr = 'Pedido Consolidado ('+Cast(@NumPdv as varchar)+') apresenta inconsistências nas quantidades. '
            end

          -- seta a flag para gerar arquivo de nf ao faturar
          -- seta a flag de movimentação de estoque do pedido para default 
          Update PDVCB 
            Set Flg_GerArqNF = 1,
                Flg_Calc = 0
            Where Cod_Estabe = @CodEstabe
            And Numero = @NumPdv

          Update PVCCB 
            Set Sta_PdvCon = '2'   -- indica que foi gerado pedido consolidado
            Where Id_PdvCon = @PIdPdvCon

        end -- if @PMsgErr = ''

    if @PMsgErr <> ''
      Rollback Transaction
	else
      Commit Transaction

  end  -- if @NumPdv > 0

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_GeraNfeDevConsig]
@PCodEstabe int,
@PIdConsig int,
@PNumSequen smallint,
@PNumSeqDev smallint,
@PCodOpeEnt varchar(3),
@PNumProtoc int output,
@PMsgErr varchar(8000) output

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = cast(GetDate() as Date)

Set @PNumProtoc = 0
Set @PMsgErr = ''

if not Exists(Select 1 
                From CNGCB cb
                     Inner Join CLIEN cl on cb.Cod_TipCng = 'C' and cb.Cod_Entida = cl.Codigo 
               Where cb.Cod_Estabe = @PCodEstabe And cb.Id_Consig = @PIdConsig)
  Set @PMsgErr = 'Cliente inválido'

if not Exists(Select 1 
                From CNGDC 
               Where Cod_Estabe = @PCodEstabe And Id_Consig = @PIdConsig 
                 And Num_Sequen = @PNumSequen And Num_SeqDev = @PNumSeqDev
           And Sta_CngPed = '1') 
  Set @PMsgErr = 'Não existe devolução a gerar'

if not Exists(Select 1 
                From CNGDI it 
               Where it.Cod_Estabe = @PCodEstabe And it.Id_Consig = @PIdConsig 
                 And it.Num_Sequen = @PNumSequen And Num_SeqDev = @PNumSeqDev
                 And it.Qtd_Pedido > 0)
  Set @PMsgErr = 'Não existe itens a devolver'

if not Exists(Select 1 
                From CNGDI it 
                     Inner Join PRXES pr on it.Cod_Estabe = pr.Cod_Estabe and it.Cod_Produt = pr.Cod_Produt 
               Where it.Cod_Estabe = @PCodEstabe And it.Id_Consig = @PIdConsig 
                 And it.Num_Sequen = @PNumSequen And Num_SeqDev = @PNumSeqDev)
  Set @PMsgErr = 'Não existe itens a devolver'

if Exists(Select 1 
            From NFECB 
           Where Cod_Estabe = @PCodEstabe and Id_Consig = @PIdConsig 
             And Num_SeqCtr = @PNumSequen And Num_SeqDev = @PNumSeqDev)
  Set @PMsgErr = 'Nota de devolução já foi gerada'


-- 1919/2919: dev.simbolica de mecadoria
if ((Select Tip_Devolu From CNGDC 
      Where Cod_Estabe = @PCodEstabe And Id_Consig = @PIdConsig 
        And Num_Sequen = @PNumSequen And Num_SeqDev = @PNumSeqDev) = 'S') and
   (not Exists(Select 1 
                 From TPOPE 
                Where Tip_EntSai = 'E' 
                  and CharIndex(cast(Cod_CfoNorInt as varchar),';1919;') > 0 
                  and CharIndex(cast(Cod_CfoNorExt as varchar),';2919;') > 0 
                  and Cod_Ope = @PCodOpeEnt and Tip_Ope = 'D'))
  Set @PMsgErr = 'Tipo de operação ('+@PCodOpeEnt+'/D/1919/2919) inválido para Devolução de Consignação'

-- 1918/2918: dev.de mercadoria remetida em consignação 
if ((Select Tip_Devolu From CNGDC 
      Where Cod_Estabe = @PCodEstabe And Id_Consig = @PIdConsig 
        And Num_Sequen = @PNumSequen And Num_SeqDev = @PNumSeqDev) = 'E') and
   (not Exists(Select 1 
                 From TPOPE 
                Where Tip_EntSai = 'E' 
                  and CharIndex(cast(Cod_CfoNorInt as varchar),';1918;') > 0 
                  and CharIndex(cast(Cod_CfoNorExt as varchar),';2918;') > 0
                  and Cod_Ope = @PCodOpeEnt and Tip_Ope = 'D'))
  Set @PMsgErr = 'Tipo de operação ('+@PCodOpeEnt+'/D/1918/2918) inválido para Devolução de Consignação'

if not Exists(Select 1
                From NFSCB cb 
                     Inner Join NFSIT it on it.Cod_Estabe = cb.Cod_Estabe and it.Ser_Nota = cb.Ser_Nota And it.num_Nota = cb.Num_Nota
                     Inner Join CNGDI dv on dv.Cod_Estabe = it.Cod_Estabe and dv.Cod_Produt = it.Cod_Produto and dv.Cod_Lote = it.Cod_Lote
                                     and dv.Id_Consig = cb.Id_Consig  and dv.Num_Sequen = @PNumSequen --cb.Num_SequenciaCtr
               Where cb.Cod_Estabe = @PCodEstabe
                 And cb.Id_Consig  = @PIdConsig) 
                 --And cb.Num_SequenciaCtr = @PNumSequen)
  Set @PMsgErr = 'Não existe NF de Remessa de Consignação vinculada'

if ((Select dbo.FN_ModExtOk(HASHBYTES('MD5','WMS'),
                            HASHBYTES('MD5',(Select Num_Cnpj From ESTAB Where Cod_Estabe = @PCodEstabe)))) = 1) and
   ((Select Tip_Devolu From CNGDC 
      Where Cod_Estabe = @PCodEstabe And Id_Consig = @PIdConsig 
        And Num_Sequen = @PNumSequen And Num_SeqDev = @PNumSeqDev) = 'S') and
   not Exists(Select 1 From TBZON Where Cod_Estabe = @PCodEstabe and Flg_CrossDocking = 1)
  Set @PMsgErr = 'Não existe zona de Cross Docking configurada (devolução simbólica)'

if @PMsgErr = ''
BEGIN
  BEGIN TRANSACTION

  Declare @TipDevoluCng varchar(1),
          @CodCliCng int,
 
          @SerNot varchar(3),
          @NumNot int,
          @CodCfoSai int,

          @WFlgUsaWms bit,

          @NumSeqIte int,
          @CodPrd int,
          @CodLot varchar(20),
          @QtdMov int,
          @PrcUni numeric(18,4),
          @PerDsc numeric(7,4),

          @CodVended int,
          @CodOperad int,

          @TipLoc varchar(1), 
          @CodDep smallint, 
          @NumRua smallint,  
          @NumCol smallint, 
          @NumNiv smallint, 
          @NumApt smallint,
          @QtdEmbFec smallint, 

          @op_TipOpe varchar(1), 
          @op_CodCfo int,
          @cb_CodRegTri int,
          @cb_CodEst varchar(2),
      @Usuario varchar(35),
      @ChvAcesso varchar (45),
      @CodTransp int 

  -- usuario infarma auditoria
  Set @Usuario = dbo.FN_UsuarioInfarma()

  -- WMS
  Set @WFlgUsaWms = (Select dbo.FN_ModExtOk(HASHBYTES('MD5','WMS'),
                                            HASHBYTES('MD5',(Select Num_Cnpj From ESTAB Where Cod_Estabe = @PCodEstabe))))

  Set @TipDevoluCng = (Select Tip_Devolu From CNGDC 
                        Where Cod_Estabe = @PCodEstabe And Id_Consig = @PIdConsig 
                          And Num_Sequen = @PNumSequen And Num_SeqDev = @PNumSeqDev)
  Set @CodVended = 0
  Set @CodOperad = 0
  Set @ChvAcesso = ''
  Set @CodTransp = 0 /* DMD-8045 */

  Select top 1 @SerNot    = cb.Ser_Nota, 
               @NumNot    = cb.Num_Nota,
               @CodCfoSai = cb.Cod_Cfo1,
               @CodVended = cb.Cod_Vendedor,
               @CodOperad = cb.Cod_VendTlmkt,
         @ChvAcesso = cb.Chv_Acesso,
         @CodTransp = cb.Cod_Transportadora 
    From NFSCB cb 
         Inner Join NFSIT it on it.Cod_Estabe = cb.Cod_Estabe and it.Ser_Nota = cb.Ser_Nota And it.num_Nota = cb.Num_Nota
         Inner Join CNGDI dv on dv.Cod_Estabe = it.Cod_Estabe and dv.Cod_Produt = it.Cod_Produto and dv.Cod_Lote = it.Cod_Lote
                            and dv.Id_Consig  = cb.Id_Consig  and dv.Num_Sequen = cb.Num_SequenciaCtr
   Where cb.Cod_Estabe = @PCodEstabe
     And cb.Id_Consig  = @PIdConsig 
     /*And cb.Num_SequenciaCtr = @PNumSequen DMD-8045: removido esse filtro */

  Select @CodCliCng = cl.Codigo
    From CNGCB cb
         Inner Join CLIEN cl on cb.Cod_TipCng = 'C' and cb.Cod_Entida = cl.Codigo 
   Where cb.Cod_Estabe = @PCodEstabe And cb.Id_Consig = @PIdConsig

  Select @op_TipOpe = Tip_Ope, 
         @op_CodCfo = Case When IsNull(@CodCfoSai,0) < 6000 then Cod_CfoNorInt else Cod_CfoNorExt End
    From TPOPE
   Where Cod_Ope = @PCodOpeEnt

  -- grava novo cabeçalho de NF
  -- Pega novo numero (protocolo)
  EXEC PR_ProxNumero 'Protocolo', @PNumProtoc output

  -- grava cabecalho
  Insert Into NFECB (Cod_Estabe,  Protocolo,   Cod_Ope,     Cod_Cfo,    Tip_NF,     Id_Consig,  Num_SeqCtr,  Num_SeqDev)
             Values (@PCodEstabe, @PNumProtoc, @PCodOpeEnt, @op_CodCfo, @op_TipOpe, @PIdConsig, @PNumSequen, @PNumSeqDev) 
  if @@error <> 0 
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end

  -- grava campos na nota
  Update cb
     Set cb.Especie = 'NF', 
         cb.Status ='A', 
         cb.Status_2 = '',
         cb.Dat_Movimento = @Date, 
         cb.Dat_Emissao = @Date, 
         cb.Dat_Entrada = @Date, 
         cb.Flg_WMS = @WFlgUsaWms,
         cb.Flg_CrossDocking = Case 
                                 When (@WFlgUsaWms = 1) and (@TipDevoluCng = 'S') then 1 
                                 Else 0 
                               End,
         cb.Flg_MovEst = 1, 
         cb.Flg_ImpNot = 1, 
         cb.Flg_DevTot = 0,

         cb.Qtd_PagNF = 1, 
         cb.Ser_SeloFisTran = '', 
         cb.Cod_FinNfe = '4',       -- devolução
         cb.Tip_Frete = '1',
 
         cb.Tip_DocRel = 'S',
         cb.Str_RelDoc = @SerNot+','+cast(@NumNot as varchar),
         cb.Flg_CalTrbDevCfg = 0,

         cb.Cod_Vendedor = @CodVended,   
         cb.Cod_VendTlmkt = @CodOperad,  
         cb.Tip_Emitente = 'C', 
         cb.Cod_EmiCliente = @CodCliCng, 
         cb.Cod_EmiFornec = 0,
         cb.Cod_EmiTransp = 0,
         cb.Cod_RegTri = en.Cod_RegTri,
         cb.Pessoa = cl.Pessoa,
         cb.Cgc_Cpf = cl.Cgc_Cpf,
         cb.Cgf_Rg = cl.Cgf,
         cb.Endereco = SUBSTRING(dbo.FN_EnderecoCompleto(cl.Endereco, cl.Numero, cl.Complemento),1,50),
         cb.Bairro = ba.Descricao,
         cb.Cidade = ci.Descricao,
         cb.Cod_UfOrigem = cl.Cod_Estado,
         cb.Cep = cl.Cep,
         cb.Cod_CidIbge = ci.Cod_CidIbge,
         cb.Usuario = @Usuario, 
         cb.Transacao = @Now, 
     cb.Chv_NotOri = @ChvAcesso,
     cb.Cod_Transp = @CodTransp 
    From NFECB cb 
         Inner Join CLIEN cl on (cl.Codigo = @CodCliCng) 
         Left  Join CIDAD ci on ((cl.Cod_Estado = ci.Cod_Estado) and (cl.Cod_Cidade = ci.Codigo)) 
         Left  Join BAIRR ba on ((cl.Cod_Estado = ba.Cod_Estado) and (cl.Cod_Cidade = ba.Cod_Cidade) and (cl.Cod_Bairro = ba.Codigo))
         Left  Join ENXES en on ((cb.Cod_Estabe = en.Cod_Estabe) and (cl.Cgc_Cpf = en.Num_CgcCpf)) 
   Where cb.Cod_Estabe = @PCodEstabe
     And cb.Protocolo = @PNumProtoc

  Delete From NELTL 
   Where Cod_Estabe = @PCodEstabe 
     and Num_Protoc = @PNumProtoc

  Select @cb_CodRegTri = Cod_RegTri,
         @cb_CodEst = Cod_UfOrigem
    From NFECB
   Where Cod_Estabe = @PCodEstabe
     And Protocolo = @PNumProtoc
 
  Set @NumSeqIte = 0

  DECLARE CNGDI_Cr CURSOR Local Fast_Forward For 
  
    Select dv.Cod_Produt, dv.Cod_Lote, dv.Qtd_Pedido, 
           C_PrcUni = Case When it.Cod_Produto > 0 then it.Prc_Unitario Else dv.Prc_Unitar End, 
           C_PerDsc = Case When it.Cod_Produto > 0 then it.Per_Desconto Else dv.Per_Descon End
      From CNGDI dv
           Left Join (Select Cod_Produto, Cod_Lote, 
                             Prc_Unitario = max(Prc_Unitario), 
                             Per_Desconto = max(Per_Desconto)
                        From NFSIT
                       Where Cod_Estabe = @PCodEstabe
                         And Ser_Nota = @SerNot
                         and Num_Nota = @NumNot
                       Group by Cod_Produto, Cod_Lote
                 ) it on dv.Cod_Produt = it.Cod_Produto and dv.Cod_Lote = it.Cod_Lote 
     Where dv.Cod_Estabe = @PCodEstabe 
       And dv.Id_Consig  = @PIdConsig 
       And dv.Num_Sequen = @PNumSequen 
       And dv.Num_SeqDev = @PNumSeqDev
       And dv.Qtd_Pedido > 0
  
  OPEN CNGDI_Cr
  FETCH NEXT FROM CNGDI_Cr INTO @CodPrd, @CodLot, @QtdMov, @PrcUni, @PerDsc
  WHILE @@FETCH_STATUS = 0
  BEGIN
    -- grava itens da nota
    Set @NumSeqIte = @NumSeqIte + 1
  
    -- aqui deveria pegar preço e desconto conforme NF de saída origem
    Insert Into NFEIT (Cod_Estabe,  Protocolo,   Cod_Produto, Cod_Lote, Num_SeqIte, Tip_Ent, Qtd_Pedido, Qtd_PedFat, Qtd_Bonificacao, Prc_Unitario, Per_DescItem, FATOR_FAT, Prc_UniFat) 
               Values (@PCodEstabe, @PNumProtoc, @CodPrd,     @CodLot,  @NumSeqIte, '',      @QtdMov,    @QtdMov   , 0,               @PrcUni,      @PerDsc,      1,        @PrcUni)
  
    -- atualiza campos do item da nota
    Update NFEIT
       Set Vlr_BruItem = Round(Prc_Unitario*(Qtd_Pedido+Qtd_Bonificacao),2),
           Vlr_TotItem = Round(Qtd_Pedido*(Prc_Unitario*(1-Per_DescItem/100)),2),
           Vlr_DescItem = 0
     Where Cod_Estabe = @PCodEstabe
       And Protocolo = @PNumProtoc
       And Cod_Produto = @CodPrd 
       And Cod_Lote = @CodLot 
       And Num_SeqIte = @NumSeqIte
  
    -- calcula tributacao
    --Exec PR_CalcTributNFEIT @PCodEstabe, @PNumProtoc, @CodPrd, @CodLot, @NumSeqIte,
    --                        @op_TipOpe, @cb_CodRegTri, 0

    -- NELTL....
    if @WFlgUsaWms = 1
      begin
    Set @CodDep = IsNull((Select min(Cod_Dep) From TBDEP Where Cod_Estabe = @PCodEstabe),1)

        if (Select FlgIntegrWmsExt From PMEST Where Cod_Estabe = @PCodEstabe) = 1
          begin
            Insert Into NELTL (Tip_Local, Cod_Estabe, Num_Protoc, Cod_Produt, Cod_Lote, 
                               Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, 
                               Qtd_Est, Qtd_EmbFec) 
              Select 'P', it.Cod_Estabe, it.Protocolo, it.Cod_Produto, it.Cod_Lote, 
                      dp.Cod_Dep, IsNull(dp.Num_Rua,0), IsNull(dp.Num_Col,0), IsNull(dp.Num_Niv,0), IsNull(dp.Num_Apt,0), 
                      it.QtdTotEnt, p.Qtd_Embalagem 
                From (Select Cod_Estabe, Protocolo, Cod_Produto, Cod_Lote, QtdTotEnt = SUM(IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) 
                        From NFEIT 
                       Group by Cod_Estabe, Protocolo, Cod_Produto, Cod_Lote) it Inner Join
                     PRXES pr on pr.Cod_Estabe = it.Cod_Estabe and pr.Cod_Produt = it.Cod_Produto Inner Join  
                     PRODU p on pr.Cod_Produt = p.Codigo Inner Join 
                     DPXPR dp on dp.Cod_Estabe  = it.Cod_Estabe And pr.Cod_Produt = dp.Cod_Produt 
               Where it.Cod_Estabe = @PCodEstabe
                 And it.Protocolo = @PNumProtoc
                 And dp.Cod_Dep = @CodDep
          end
        else
          begin
            -- cria endereço cross docking
            if @TipDevoluCng = 'S'
              begin
                Set @NumRua = (Select top 1 Num_RuaIni From TBZON Where Cod_Estabe = @PCodEstabe and Flg_CrossDocking = 1)
                Set @NumCol = IsNull((Select max(Num_Col) From ENDDP Where Cod_Estabe = @PCodEstabe and Cod_Dep = @CodDep),0) + 1
              end
            else
              begin
                Set @NumRua = (Select zn.Num_RuaIni 
                                 From TBZON zn 
                                      inner join PMEST pm on zn.Cod_Estabe = pm.Cod_Estabe 
                                Where zn.Cod_Estabe = @PCodEstabe
                                  And zn.Cod_Dep = @CodDep
                                  And zn.Cod_Zon = pm.CodZonDev)
                Set @NumCol = 1
              end       

            Set @NumNiv = 1
            Set @NumApt = 0

            -- elimina endereços órfãos
            if @TipDevoluCng = 'S'
              begin
                Delete en
                  From ENDDP en
                       Left Join NFECB cb on en.Cod_Estabe = cb.Cod_Estabe and en.Num_Cntrol = cb.Protocolo
                 Where IsNull(en.Cod_Cntrol,'') = 'NFE'  
                   And IsNull(en.Num_Cntrol,0) > 0
                   And cb.Protocolo is null

                Delete From ENDDP 
                 Where Cod_Estabe = @PCodEstabe 
                   And Cod_Dep = @CodDep        
                   And Num_Rua = @NumRua        
                   And Num_Col = @NumCol       

                Insert Into ENDDP (Cod_Estabe,  Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_Cntrol, Num_Cntrol,  Flg_Bloqueado)
                           Values (@PCodEstabe, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, 'NFE',      @PNumProtoc, 1)
              end

            Set @TipLoc = dbo.FN_TipLocEnd(@PCodEstabe, @CodDep, @NumRua)
            Set @QtdEmbFec = @QtdMov

            Insert Into NELTL (Cod_Estabe, Num_Protoc, Cod_Produt, Cod_Lote,
                               Tip_Local, Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt,
                               Qtd_Est, Qtd_EmbFec)
                       Values (@PCodEstabe, @PNumProtoc, @CodPrd, @CodLot,
                               @TipLoc, @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt,
                               @QtdMov, @QtdEmbFec)
          end
      end

    if @@error <> 0
      begin
        if @@trancount > 0
          Rollback Transaction
        Return
      end
  
    FETCH NEXT FROM CNGDI_Cr INTO @CodPrd, @CodLot, @QtdMov, @PrcUni, @PerDsc
  END
  
  CLOSE CNGDI_Cr
  DEALLOCATE CNGDI_Cr     

  -- calcula tributos da NF
  Exec PR_CalcTributNFECB @PCodEstabe, @PNumProtoc, 1
  if @@error <> 0
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end

  -- atualiza dados do cabecalho da nota gerada
  Exec PR_NormalizaValoresNFE @PCodEstabe, @PNumProtoc
  if @@error <> 0
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end

  -- atualiza status CNGDC
  Update CNGDC 
     Set Sta_CngPed = '2',
         Num_Protoc = @PNumProtoc
   Where Cod_Estabe = @PCodEstabe And Id_Consig = @PIdConsig 
     And Num_Sequen = @PNumSequen And Num_SeqDev = @PNumSeqDev

  -- fecha NFE: gera NF fatura se for devolução simbólica: CNGDC.Tip_Devolu = 'S'
/*  executa fechamento no Delphi
  Exec PR_FechaNFE @PCodEstabe, @PNumProtoc, 0, 0, '', @PMsgErr output
  if @@error <> 0
    begin
      if @@trancount > 0
        Rollback Transaction
      Return
    end
*/

  if @@trancount > 0  
    COMMIT TRANSACTION
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_GeraNfeDeNfs]
@PCodEstabe int,
@PSerNotSai varchar(3),
@PNumNotSai int,
@PCodEstabeDes int,
@PCodOpeEnt varchar(3),
@PFlgWms bit,
@PCodMtvDev varchar(3),
@PDesMtvDev varchar(40),
@PNumPrt int output

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime,
		@MsgErr varchar(80)

Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

Set @PCodOpeEnt = LTRIM(RTRIM(@PCodOpeEnt))

if (@PCodEstabe <> @PCodEstabeDes) and ((Select dbo.FN_InfarmaMultiEmpresa()) = 0)
  RAISERROR('Somente para Sistema Multi-Empresa',16,1)
else
if not Exists(Select Num_Nota From NFSCB 
               Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNotSai And Num_Nota = @PNumNotSai And Status <> 'A')
  RAISERROR('Nota Fiscal Não Localizada ou Inválida',16,1)
else
--if @PNumPrt > 0
--  begin
--    Set @MsgErr = 'Parâmetro (protocolo = '+cast(@PNumPrt as varchar)+') inválido'
--    RAISERROR(@MsgErr,16,1)
--  end
--else
if not Exists(Select 1 From ESTAB Where Cod_Estabe = @PCodEstabeDes)
  RAISERROR('Estabelecimento Destino inexistente',16,1)
else
begin

Declare @es_CodUF varchar(2) = '',
        @es_CodUFOri varchar(2) = '',
        @es_NumCnpjOri varchar(14) = '',
		@es_FlgContriSubstituido bit = 0,
		@pc_IdPdvCon int = 0,
		@rg_FlgConFin bit = 0,
		@ns_CodCfo int = 0,
		@ns_Estado varchar(2) = '',
		@ns_Cgc varchar(14) = '',
		@ns_CodCli int = 0,
		@ns_VlrSubTri numeric(18,4) = 0,
		@pm_FlgUsaEstornoNfe bit = 0,

		@ne_TipOpe varchar(1) = '',
        @ne_TipEmi varchar(1) = '',
		@ne_CodEmi int = 0,
        @ne_Cgc varchar(14) = '',
        @ne_Cgf varchar(15) = '',

		@ne_CodCfo int = 0,				 
        @ne_FlgBlqTrfEstFis bit = 0,
        @ne_FlgMovEst bit = 0,
        @ne_CodRegTri int = 0,
        @ne_CodTransp int = 0,
        @ne_Endereco varchar(50) = '',
        @ne_Bairro varchar(20) = '',
        @ne_Cidade varchar(25) = '',
        @ne_Cep varchar(8) = '',
        @ne_CodUfOri varchar(2) = '',
		@ne_CodCidIbge varchar(7),
		@op_TipOpe varchar(1),
		@op_FlgMovEst bit,

        @WFlgDscBon bit = 0,
        @WFlgConFin bit = 0,
		@WNumCnpj varchar(14) = '',
        @WCodCli int = 0,
		@UsuInfarma varchar(15)

Select @ne_CodRegTri = IsNull(ex.Cod_RegTri,0), 
	   @ne_CodTransp = IsNull(ex.Cod_Transp,0),
       @es_CodUF = es.Des_Estado,
	   @es_FlgContriSubstituido = IsNull(es.Flg_ContriSubstituido,0),
       @rg_FlgConFin = IsNull(rg.Flg_ConsumFin,0),
	   @pc_IdPdvCon = IsNull(pc.Id_PdvCon,0),
	   @ns_CodCfo = IsNull(ns.Cod_Cfo1,0),
	   @ns_Estado = IsNull(ns.Estado,''),
	   @ns_Cgc = IsNull(ns.Cgc,''),
       @ns_CodCli = IsNull(ns.Cod_Cliente,0),
	   @ns_VlrSubTri = IsNull(ns.Vlr_SubsTrib,0),
       @ne_TipOpe = IsNull(ns.Tip_Saida,op.Tip_Ope),
       @ne_FlgMovEst = IsNull(op.Flg_MovEst,IsNull(ns.Flg_MovEst,0)) 
  From NFSCB ns
       Inner Join ESTAB es on es.Cod_Estabe = @PCodEstabeDes
       Left  Join PVCCB pc on pc.Cod_Estabe = ns.Cod_Estabe and pc.Num_PdvCon = ns.Cod_Pedido
       Left  Join ENXES ex on ex.Cod_Estabe = es.Cod_Estabe and ns.Cgc = ex.Num_CgcCpf and ns.Cod_Cliente = ex.Cod_Client
	   Left  Join RGTRI rg on rg.Cod_RegTri = ex.Cod_RegTri
	   Left  Join TPOPE op on ns.Cod_Ope = op.Cod_Ope
 Where ns.Cod_Estabe = @PCodEstabe 
   And ns.Ser_Nota = @PSerNotSai
   And ns.Num_Nota = @PNumNotSai

Select @es_CodUFOri = Des_Estado,
       @es_NumCnpjOri = Num_Cnpj
  From ESTAB 
 Where Cod_Estabe = @PCodEstabe
  
Set @UsuInfarma = dbo.FN_UsuarioInfarma()
Set @ne_CodCfo = dbo.FN_InverteCfop(@ns_CodCfo)
if @ne_TipOpe = 'V' Set @ne_TipOpe = 'C'

-- tenta identificar Tipo de operação se for o caso -------------------------------------
-- pedido consolidado
if (IsNull(@PCodOpeEnt,'') = '') and (@pc_IdPdvCon > 0)
  begin
    Set @PCodOpeEnt = IsNull((Select pm.Cod_TipOpe
                                From PMTRF pm
                                     Left Join CLIEN cl on pm.Tip_EmiDes = 'C' And pm.Cod_EmiDes = cl.Codigo  
                                     Left Join FORNE fo on pm.Tip_EmiDes = 'F' And pm.Cod_EmiDes = fo.Codigo  
                                     Left Join TRANS tr on pm.Tip_EmiDes = 'T' And pm.Cod_EmiDes = tr.Codigo
                               Where pm.Cod_Estabe = @PCodEstabeDes  
                                 And pm.Cod_UF = @es_CodUFOri
                                 And pm.Tip_EntSai = 'E'
                                 And @es_NumCnpjOri = Case  
                                                        When pm.Tip_EmiDes = 'C' then cl.Cgc_Cpf
                                                        When pm.Tip_EmiDes = 'F' then fo.Cgc_Cpf
                                                        When pm.Tip_EmiDes = 'T' then tr.Cgc_Cpf
                                                        Else 'X'
                                                      End),'')
  end

if IsNull(@PCodOpeEnt,'') = ''
  Set @PCodOpeEnt = (Select top 1 Cod_Ope
                       From TPOPE 
                      Where Tip_EntSai = 'E'
                        And ((Cod_CfoNorInt = @ne_CodCfo) or 
                             (Cod_CfoSbtInt = @ne_CodCfo) or 
                             (Cod_CfoNorExt = @ne_CodCfo) or 
                             (Cod_CfoSbtExt = @ne_CodCfo))) 

if IsNull(@PCodOpeEnt,'') = ''
  Set @PCodOpeEnt = (Select top 1 Cod_Ope
                       From TPOPE 
                      Where Tip_EntSai = 'E'
                        And Tip_Ope = @ne_TipOpe)

--------------------------------------------------------------------------------------------------------------------

if (@PCodOpeEnt = '') or (not Exists(Select Cod_Ope From TPOPE Where Cod_Ope = @PCodOpeEnt and Tip_EntSai = 'E'))
  RAISERROR('Tipo de Operação de Entrada Inexistente ou Inválida',16,1)
else
BEGIN
BEGIN TRANSACTION

-- forçar = zero
Set @PNumPrt = 0

Select @op_TipOpe = Tip_Ope,
       @op_FlgMovEst = IsNull(Flg_movEst,0)
  From TPOPE 
 Where Cod_Ope = @PCodOpeEnt

-- identifica emitente 
if @op_TipOpe = 'D'
  begin
    --pelo cnpj da nf de saida
	Set @WNumCnpj = @ns_Cgc
    Set @WCodCli = @ns_CodCli
    if Exists(Select cl.Codigo 
                From CLIEN cl 
                     Inner Join ENXES en on en.Cod_Estabe = @PCodEstabeDes and en.Num_CgcCpf = cl.Cgc_Cpf and en.Cod_Client = cl.Codigo
			   Where cl.Codigo = @WCodCli)
      begin
        Set @ne_TipEmi = 'C'
        Select @ne_CodEmi = cl.Codigo, 
               @ne_Cgc = cl.Cgc_Cpf,
               @ne_Cgf= cl.Cgf,
	           @ne_CodRegTri = en.Cod_RegTri, 
		       @ne_CodTransp = en.Cod_Transp,
               @ne_Endereco = Substring(dbo.FN_EnderecoCompleto(cl.Endereco, cl.Numero, cl.Complemento),1,50),
		       @ne_Bairro = Substring(ba.Descricao,1,20),
		       @ne_Cidade = Substring(ci.Descricao,1,25), 
	           @ne_CodUfOri = cl.Cod_Estado, 
		       @ne_Cep = cl.Cep,
		       @ne_CodCidIbge = IsNull(ci.Cod_CidIbge,'')
          From CLIEN cl 
               Inner Join ENXES en on en.Cod_Estabe = @PCodEstabeDes and en.Num_CgcCpf = cl.Cgc_Cpf and en.Cod_Client = cl.Codigo
	           Left  Join CIDAD ci on cl.Cod_Estado = ci.Cod_Estado and cl.Cod_Cidade = ci.Codigo
	           Left  Join BAIRR ba on cl.Cod_Estado = ba.Cod_Estado and cl.Cod_Cidade = ba.Cod_Cidade and cl.Cod_Bairro = ba.Codigo
         Where cl.Codigo = @WCodCli
      end
    else
    if Exists(Select fo.Codigo From FORNE fo Inner Join ENXES en on fo.Cgc_Cpf = en.Num_CgcCpf 
              Where en.Cod_Estabe = @PCodEstabeDes And fo.Cgc_Cpf = @WNumCnpj)
      begin
        Set @ne_TipEmi = 'F'
        Select @ne_CodEmi = fo.Codigo, 
               @ne_Cgc = fo.Cgc_Cpf,
               @ne_Cgf= fo.Cgf_Rg,
	           @ne_CodRegTri = en.Cod_RegTri, 
		       @ne_CodTransp = en.Cod_Transp,
               @ne_Endereco = Substring(dbo.FN_EnderecoCompleto(fo.Endereco_Com, fo.Numero_Com, fo.Complemento_Com),1,50),
    		   @ne_Bairro = IsNull(Substring(ba.Descricao,1,20),Substring(fo.Bairro_Com,1,20)),
	    	   @ne_Cidade = IsNull(Substring(ci.Descricao,1,25),Substring(fo.Cidade_Com,1,25)), 
	           @ne_CodUfOri = fo.Estado_Com,
    		   @ne_Cep = fo.Cep_Com,
	    	   @ne_CodCidIbge = IsNull(ci.Cod_CidIbge,'')
          From FORNE fo 
               Inner Join ENXES en on fo.Cgc_Cpf = en.Num_CgcCpf 
    	       Left Join CIDAD ci on fo.Estado_Com = ci.Cod_Estado and fo.Cod_Cidade_Com = ci.Codigo
	           Left Join BAIRR ba on fo.Estado_Com = ba.Cod_Estado and fo.Cod_Cidade_Com = ba.Cod_Cidade and fo.Cod_Bairro_Com = ba.Codigo
         Where en.Cod_Estabe = @PCodEstabeDes
           And fo.Cgc_Cpf = @WNumCnpj
      end
    else
    if Exists(Select tr.Codigo From TRANS tr Inner Join ENXES en on tr.Cgc_Cpf = en.Num_CgcCpf 
              Where en.Cod_Estabe = @PCodEstabeDes And tr.Cgc_Cpf = @WNumCnpj)
      begin
        Set @ne_TipEmi = 'T'
        Select @ne_CodEmi = tr.Codigo, 
               @ne_Cgc = tr.Cgc_Cpf,
               @ne_Cgf= tr.Cgf_Rg,
    	       @ne_CodRegTri = en.Cod_RegTri, 
    		   @ne_CodTransp = en.Cod_Transp,
               @ne_Endereco = Substring(dbo.FN_EnderecoCompleto(tr.Endereco, tr.Numero, tr.Complemento),1,50),
    		   @ne_Bairro = IsNull(Substring(ba.Descricao,1,20),Substring(tr.Bairro,1,20)),
    		   @ne_Cidade = IsNull(Substring(ci.Descricao,1,25),Substring(tr.Cidade,1,25)), 
    	       @ne_CodUfOri = tr.Estado,
    		   @ne_Cep = tr.Cep,
    		   @ne_CodCidIbge = IsNull(ci.Cod_CidIbge,'')
          From TRANS tr 
               Inner Join ENXES en on tr.Cgc_Cpf = en.Num_CgcCpf 
    	       Left  Join CIDAD ci on tr.Estado = ci.Cod_Estado and tr.Cod_Cidade = ci.Codigo
     	       Left  Join BAIRR ba on tr.Estado = ba.Cod_Estado and tr.Cod_Cidade = ba.Cod_Cidade and tr.Cod_Bairro = ba.Codigo
         Where en.Cod_Estabe = @PCodEstabeDes
           And tr.Cgc_Cpf = @WNumCnpj
      end
  end  -- if @op_TipOpe = 'D'

if @pc_IdPdvCon > 0
  begin
	Set @WNumCnpj = @es_NumCnpjOri

    if not Exists(Select 1 From PMTRF Where Cod_Estabe = @PCodEstabeDes And Cod_UF = @es_CodUFOri And Tip_EntSai = 'E')
      begin
	    -- dispara trigger
        Update PMTRF 
           Set Cod_EmiDes = IsNull(Cod_EmiDes,0) + 0
         Where Cod_Estabe = @PCodEstabe
           And Cod_UF = @es_CodUF
           And Tip_EntSai = 'S'
      end

    Select @ne_TipEmi = IsNull(x.Tip_EmiDes,''), 
           @ne_CodEmi = IsNull(x.Cod_EmiDes,0),
	       @ne_Cgc = IsNull(x.Num_Cnpj,''),
    	   @ne_Cgf = IsNull(x.Insc_Est,''),
           @ne_CodRegTri = IsNull(ex.Cod_RegTri,0),
           @ne_CodTransp = IsNull(ex.Cod_Transp,0),
           @ne_Endereco = Substring(dbo.FN_EnderecoCompleto(x.Endereco,x.Numero,x.Complem),1,50),
    	   @ne_CodUfOri = IsNull(x.Cod_Estado,''),
           @ne_Cidade = Substring(IsNull(ci.Descricao,''),1,25),
    	   @ne_Bairro = Substring(IsNull(ba.Descricao,''),1,20),
	       @ne_CodCidIbge = IsNull(ci.Cod_CidIbge,'')
      From (Select pm.Tip_EmiDes, pm.Cod_EmiDes,
                   Num_Cnpj   = Case 
                                  When fo.Codigo > 0 then fo.Cgc_Cpf 
                                  When cl.Codigo > 0 then cl.Cgc_Cpf 
                                  When tr.Codigo > 0 then tr.Cgc_Cpf 
                                End,
                   Insc_Est   = Case 
                                  When fo.Codigo > 0 then fo.Cgf_Rg
                                  When cl.Codigo > 0 then cl.Cgf 
                                  When tr.Codigo > 0 then tr.Cgf_Rg 
                                End,
                   Endereco   = Case 
                                  When fo.Codigo > 0 then fo.Endereco_Com 
                                  When cl.Codigo > 0 then cl.Endereco
                                  When tr.Codigo > 0 then tr.Endereco
                                End,
                   Numero     = Case 
                                  When fo.Codigo > 0 then fo.Numero_Com 
                                  When cl.Codigo > 0 then cl.Numero
                                  When tr.Codigo > 0 then tr.Numero
                                End,
                   Complem    = Case 
                                  When fo.Codigo > 0 then fo.Complemento_Com 
                                  When cl.Codigo > 0 then cl.Complemento
                                  When tr.Codigo > 0 then tr.Complemento
                                End,
                   Cod_Estado = Case 
                                  When fo.Codigo > 0 then fo.Estado_Com 
                                  When cl.Codigo > 0 then cl.Cod_Estado
                                  When tr.Codigo > 0 then tr.Estado
                                End,
                   Cod_Cidade = Case 
                                  When fo.Codigo > 0 then fo.Cod_Cidade_Com 
                                  When cl.Codigo > 0 then cl.Cod_Cidade
                                  When tr.Codigo > 0 then tr.Cod_Cidade
                                End,
                   Cod_Bairro = Case 
                                  When fo.Codigo > 0 then fo.Cod_Bairro_Com 
                                  When cl.Codigo > 0 then cl.Cod_Bairro
                                  When tr.Codigo > 0 then tr.Cod_Bairro
                                End
              From PMTRF pm
                   Left Join CLIEN cl on pm.Tip_EmiDes = 'C' And pm.Cod_EmiDes = cl.Codigo  
                   Left Join FORNE fo on pm.Tip_EmiDes = 'F' And pm.Cod_EmiDes = fo.Codigo  
                   Left Join TRANS tr on pm.Tip_EmiDes = 'T' And pm.Cod_EmiDes = tr.Codigo
             Where pm.Cod_Estabe = @PCodEstabeDes  
               And pm.Cod_UF = @es_CodUFOri
               And pm.Tip_EntSai = 'E'
               And @es_NumCnpjOri = Case  
                                      When pm.Tip_EmiDes = 'C' then cl.Cgc_Cpf
                                      When pm.Tip_EmiDes = 'F' then fo.Cgc_Cpf
                                      When pm.Tip_EmiDes = 'T' then tr.Cgc_Cpf
                                      Else 'X'
                                    End) x
           Inner Join ENXES ex on ex.Cod_Estabe = @PCodEstabeDes and x.Num_Cnpj = ex.Num_CgcCpf 
           Left  Join CIDAD ci on x.Cod_Estado = ci.Cod_Estado and x.Cod_Cidade = ci.Codigo
           Left  Join BAIRR ba on x.Cod_Estado = ba.Cod_Estado and x.Cod_Cidade = ba.Cod_Cidade and x.Cod_Bairro = ba.Codigo
  end

if (@ne_Cgc = '') and
   Exists(Select Num_CgcCpf From ENTID Where Num_CgcCpf = @WNumCnpj)
  begin
    Set @ne_TipEmi = 'X'
    Select @ne_CodEmi = 0, 
           @ne_Cgc = en.Num_CgcCpf,
           @ne_Cgf= en.Num_CgfRg,
           @ne_CodRegTri = ex.Cod_RegTri, 
		   @ne_CodTransp = ex.Cod_Transp,
           @ne_Endereco = Substring(dbo.FN_EnderecoCompleto(en.Des_Endere, en.Num_Endere, en.Des_CplEnd),1,50),
  		   @ne_Bairro = Substring(en.Des_Bairro,1,20),
  		   @ne_Cidade = Substring(en.Des_Cidade,1,25),
   	       @ne_CodUfOri = en.Des_Estado,
   		   @ne_Cep = en.Num_Cep,
   		   @ne_CodCidIbge = IsNull(en.Cod_CidIbge,'')
      From ENTID en
           Inner Join ENXES ex on en.Num_CgcCpf = ex.Num_CgcCpf 
     Where ex.Cod_Estabe = @PCodEstabeDes
       And ex.Num_CgcCpf = @WNumCnpj
  end


if @ne_CodCfo = 0
  begin
    Select @ne_CodCfo = Case
                          When (@rg_FlgConFin = 1) and (@ns_Estado = @es_CodUF)  then op.Cod_CfoConFinInt
                          When (@rg_FlgConFin = 1) and (@ns_Estado <> @es_CodUF) then op.Cod_CfoConFinExt
                          When (@ns_VlrSubTri > 0) and (@ns_Estado = @es_CodUF)  and (@es_FlgContriSubstituido = 1) then op.Cod_CfoSbtIntSubstituido
                          When (@ns_VlrSubTri > 0) and (@ns_Estado = @es_CodUF)  and (@es_FlgContriSubstituido = 0) then op.Cod_CfoSbtInt
                          When (@ns_VlrSubTri > 0) and (@ns_Estado <> @es_CodUF) and (@es_FlgContriSubstituido = 1) then op.Cod_CfoSbtExtSubstituido
                          When (@ns_VlrSubTri > 0) and (@ns_Estado <> @es_CodUF) and (@es_FlgContriSubstituido = 0) then op.Cod_CfoSbtExt
                          When (@ns_VlrSubTri = 0) and (@ns_Estado = @es_CodUF)  then op.Cod_CfoNorInt
                          When (@ns_VlrSubTri = 0) and (@ns_Estado <> @es_CodUF) then op.Cod_CfoNorExt
                       End
	 From TPOPE op
    Where op.Cod_Ope = @PCodOpeEnt
  end

Select @ne_FlgBlqTrfEstFis = IsNull(Flg_BlqTrfEstFis,0) 
  From TBCFO 
 Where Codigo = @ne_CodCfo

Set @pm_FlgUsaEstornoNfe = IsNull((Select FlgUsaEstornoNfe From PARAM Where Cod_Estabe = @PCodEstabeDes),0)

if IsNull(@PNumPrt,0) = 0
  EXEC PR_ProxNumero 'Protocolo', @PNumPrt output

-- grava cabecalho
Insert Into NFECB (Cod_Estabe, Protocolo, Flg_Importado, Usuario, Transacao)
           Values (@PCodEstabeDes, @PNumPrt, 1, @UsuInfarma, @Now) 
if @@error <> 0
  begin
    Rollback Transaction
    Return
  end        
              
-- grava campos na nota
Update ne
   Set ne.Cod_Ope = @PCodOpeEnt,
       ne.Tip_NF = @op_TipOpe,
       ne.Cod_RegTri = @ne_CodRegTri,
       ne.Cod_Transp = @ne_CodTransp, 
       ne.Cod_Cfo = @ne_CodCfo,
       ne.Flg_BlqTrfEstFis = IsNull(@ne_FlgBlqTrfEstFis,0),
       ne.Cgc_Cpf = @ne_Cgc,
       ne.Cgf_Rg = @ne_Cgf,
	   ne.Tip_Emitente = @ne_TipEmi,
	   ne.Cod_EmiCliente = Case When @ne_TipEmi = 'C' then @ne_CodEmi Else 0 End,
	   ne.Cod_EmiFornec  = Case When @ne_TipEmi = 'F' then @ne_CodEmi Else 0 End,
	   ne.Cod_EmiTransp  = Case When @ne_TipEmi = 'T' then @ne_CodEmi Else 0 End,

       ne.Endereco = @ne_Endereco,
       ne.Cod_UfOrigem = @ne_CodUfOri,
       ne.Bairro = @ne_Bairro,
       ne.Cidade = @ne_Cidade,
       ne.Cep = @ne_Cep,
	   ne.Cod_CidIbge = @ne_CodCidIbge,

       ne.Status= 'A',
       ne.Status_2 = '',
	   ne.Id_PdvCon = @pc_IdPdvCon,   -- indica que foi gerado por consolidação
       ne.Cod_Pedido = 0,             -- pedido de compra
       ne.Flg_DevTot = 0,             -- nao eh devolucao total
       ne.Flg_MovEst = @op_FlgMovEst, -- movimenta estoque
       ne.Dat_Entrada = @Date,  
       ne.Dat_Emissao = @Date,
       ne.Dat_Movimento = @Date,
       ne.Flg_WMS = @PFlgWms,
       ne.Obs_Rodape = '',
       @WFlgDscBon = Case 
                       When IsNull(ns.Vlr_DscBon,0) > 0 then 1
                       Else 0 
                     End,
       ne.Num_Formulario = ns.Num_Formulario, 
       ne.Qtd_PagNf = ns.Qtd_PagNf, 
       ne.Qtd_Itens = ns.Qtd_Itens,
	   ne.Tip_Consumidor = ns.Tip_Consumidor,
       ne.Qtd_Volumes = ns.Qtd_Volumes,
       ne.Qtd_PesBru = ns.Qtd_PesBru,
       ne.Qtd_Peso = ns.Qtd_Peso,

       ne.Cod_VendTlmkt = ns.Cod_VendTlmkt,
       ne.Cod_Vendedor = ns.Cod_Vendedor,
       ne.Vlr_Mercadoria = ns.Vlr_LiqItens,
       ne.Vlr_Nota = ns.Vlr_TotalNota,
       
       ne.Cod_VlrFiscal = ns.Cod_VlrFiscal,
       ne.Vlr_BasIpi = IsNull(ns.Vlr_BasIpi,0),
       ne.Vlr_Ipi = IsNull(ns.Vlr_Ipi,0),
       ne.Vlr_BasIcmsNor = ns.Vlr_BasIcmsNor,
       ne.Vlr_IcmsNor = ns.Vlr_IcmsNor,
       ne.Vlr_BasIcmsTri = ns.Vlr_BasIcmsTri,
       ne.Vlr_IcmsTri = ns.Vlr_IcmsTri,
       ne.Vlr_BasIstFon = ns.Vlr_BasSubsTrib,
       ne.Vlr_IstFon = ns.Vlr_SubsTrib,
	   ne.Vlr_PrdSubTri = ns.Vlr_PrdSubTri,
       ne.Vlr_Desconto = IsNull(ns.Vlr_DescontoCom,0)+IsNull(ns.Vlr_DscBon,0)+
	                     IsNull(ns.Vlr_RepIcms,0),
	   ne.Vlr_Despesas = ns.Vlr_OutDsp,
	   ne.Vlr_DscTri = IsNull(ns.Vlr_DscTri,0),
       ne.Vlr_BasSbtRes = ns.Vlr_BasSbtRes,
       ne.Vlr_SbtRes = ns.Vlr_SbtRes,
       ne.Vlr_DspExt = ns.Vlr_DspExt,
       ne.Per_Comvnd = ns.Per_Comvnd,
       ne.Vlr_Outros = ns.Vlr_Outros,  
       ne.Vlr_Isento = ns.Vlr_Isento,
	   ne.Via_Transp = ns.Via_Transp,
	   ne.Tip_Frete = '1',
       ne.Vlr_Frete = 0,
       ne.Vlr_Seguro = 0,
--	  ne.Pessoa = ns.Pessoa,

       ne.Numero = Case
                     When @pc_IdPdvCon > 0 Then @PNumNotSai
                     Else 0
                   End,
       ne.Serie = Case
                    When @pc_IdPdvCon > 0 Then @PSerNotSai
                    Else 0
                  End,
       ne.Especie = 'NF',
       ne.Ser_SeloFisTran = '',

       ne.Flg_Importado = 0,
       ne.Flg_ImpNot = Case When @op_TipOpe = 'D' then 1 Else 0 End,  -- imprime NF
       ne.Flg_Estorno = Case When (@pm_FlgUsaEstornoNfe = 1) and (@op_TipOpe = 'D') then 1 Else 0 End,
       ne.Chv_Acesso = Case When @op_TipOpe = 'D' then '' Else ns.Chv_Acesso End,    
       ne.Cod_ModDoc = Case When @op_TipOpe = 'D' then '' Else ns.Cod_ModDoc End,    
       ne.Tip_DocRel = Case When @op_TipOpe = 'D' then 'S' Else '' End,
       ne.Str_RelDoc = Case When @op_TipOpe = 'D' then ns.Ser_Nota+','+cast(ns.Num_Nota as varchar) Else '' End,
	   ne.Cod_FinNfe = Case When @op_TipOpe = 'D' then '4' Else '1' End, --1-Normal  4- devolução
       ne.Cod_MtvDev = @PCodMtvDev,
       ne.Des_MtvDev = @PDesMtvDev

  From NFECB ne, NFSCB ns
 Where ne.Cod_Estabe = @PCodEstabeDes
   And ne.Protocolo = @PNumPrt
   And ns.Cod_Estabe = @PCodEstabe 
   And ns.Ser_Nota = @PSerNotSai 
   And ns.Num_Nota = @PNumNotSai

-- inclui itens
Insert Into NFEIT (Cod_Estabe, Protocolo, Cod_Produto, Cod_Lote, Num_SeqIte, Tip_Ent)
  Select @PCodEstabeDes, @PNumPrt, Cod_Produto, Cod_Lote, Num_SeqIte, ''
   From NFSIT
   Where Cod_Estabe = @PCodEstabe 
     And Ser_Nota = @PSerNotSai 
     And Num_Nota = @PNumNotSai

Update ne
   Set ne.Dat_Movimento = @Date,

       ne.Cod_ClaTri = ns.Cod_ClaTri,
       ne.Tip_LisPis = ns.Tip_Aux,

       ne.Prc_Venda  = ns.Prc_TabBru, 
       ne.Prc_Fabric = ns.Prc_Fabric,
       ne.Prc_MaxCon = ns.Prc_MaxCon,
       ne.Prc_RefFpb = ns.Prc_RefFpb,

       ne.Ctrl_Tributacao = ns.Ctrl_Tributacao,

       ne.Alq_Icms = ns.Alq_Icms, 
       ne.Vlr_BasIcmsNor = ns.Vlr_BasIcmsNor, 
       ne.Vlr_IcmsNor = ns.Vlr_IcmsNor,

       ne.Vlr_PrdSubTri = ns.Vlr_PrdSubTri,
	   ne.Vlr_BasSubsTrib = ns.Vlr_BasSubsTrib, 
	   ne.Vlr_SubsTrib = ns.Vlr_SubsTrib,  
       ne.Alq_IcmDeb = ns.Alq_IcmSbt,
--      ne.Alq_IcmSbt = ns.Alq_IcmSbt,

       ne.Vlr_BasSbtRes = ns.Vlr_BasSbtRes,
       ne.Vlr_SbtRes = ns.Vlr_SbtRes,
       ne.Vlr_DspExt  = ns.Vlr_DspExt,

 	   ne.Vlr_BasIcmsTrib = ns.Vlr_BasIcmsTri, 
	   ne.Vlr_IcmsTrib = ns.Vlr_IcmsTri,
       ne.Vlr_Isento = ns.Vlr_Isento,
       ne.Vlr_Outros = ns.Vlr_Outros,  

	   ne.Vlr_Ipi = ns.Vlr_Ipi, 
       ne.Vlr_Frete = 0,
       ne.Vlr_Seguro = 0,
	   ne.Vlr_DespRateada = ns.Vlr_DespRateada,
	   ne.Vlr_DescRateado = ns.Vlr_DescRateado,
	   ne.Vlr_DscTri = ns.Vlr_DscTri,
       ne.Vlr_Comissao = IsNull(ns.Vlr_Comissao,0),
       ne.Vlr_ComTlmkt = IsNull(ns.Vlr_ComTlmkt,0),
       ne.Vlr_Verba = IsNull(ns.Vlr_Verba,0),
	   ne.Vlr_VrbOpe = IsNull(ns.Vlr_VrbOpe,0),
	   ne.Vlr_VrbSup = IsNull(ns.Vlr_VrbSup,0),
       ne.Vlr_BasRepIcm = 0,  -- ns.Vlr_BasRepIcms
       ne.Vlr_RepIcm = 0,      --ns.Vlr_RepIcms
 
       ne.Flg_ComisNormal = ns.Flg_ComisNormal,
       ne.Dat_Fabric = (Select top 1 Dat_Fabric 
                          From PRLOT Where Cod_Estabe = ns.Cod_Estabe
                           and Cod_Produt = ns.Cod_Produto
                           and Cod_Lote = ns.Cod_Lote
                           and Dat_Fabric > 0
                         Order by Cod_Dep),
       ne.Dat_Vencim = (Select top 1 Dat_Vencim
                          From PRLOT Where Cod_Estabe = ns.Cod_Estabe
                           and Cod_Produt = ns.Cod_Produto
                           and Cod_Lote = ns.Cod_Lote
                         Order by Cod_Dep), 
       ne.Qtd_Pedido = ns.Qtd_Produto,
       ne.Qtd_Bonificacao = ns.Qtd_Bonificacao,
       ne.Prc_Unitario = ns.Prc_Unitario,
       ne.Per_DescItem = Case When ns.Per_Desconto > 0 then ns.Per_Desconto Else 0 End,

       ne.Flg_BlqDsc = Case 
                         When ((@WFlgDscBon = 1) and (IsNull(ns.Vlr_DscBonRat,0) = 0)) then 1 
                         Else 0 
                       End,

       ne.Fator_Fat = 1,
       ne.Qtd_PedFat = ns.Qtd_Produto,
       ne.Qtd_BonFat = ns.Qtd_Bonificacao,
       ne.Prc_UniFat = ns.Prc_Unitario,
	   ne.Per_Markup = IsNull(pr.Per_Markup,0),
	   ne.Cod_CEST = ns.Cod_CEST

  From NFEIT ne, NFSIT ns, PRODU pr
 Where ne.Cod_Estabe = @PCodEstabeDes
   And ne.Protocolo = @PNumPrt
   And ns.Cod_Estabe = @PCodEstabe 
   And ns.Ser_Nota = @PSerNotSai 
   And ns.Num_Nota = @PNumNotSai
   And ne.Cod_Produto = ns.Cod_Produto
   And ne.Cod_Lote = ns.Cod_Lote
   And ne.Num_SeqIte = ns.Num_SeqIte
   And pr.Codigo = ns.Cod_Produto

-- calc fields
Update NFEIT
   Set Vlr_DscIte1 = Case When Per_DescItem > 0 then Round(Prc_Unitario*Qtd_Pedido,2) - Round(Prc_Unitario*Qtd_Pedido*(1-Per_DescItem/100),2) Else 0 End,
       Vlr_DscIte2 = 0,
       Vlr_TotItem = Round(Prc_Unitario*Qtd_Pedido*(1-Per_DescItem/100),2),
       Vlr_BruItem = Round(Prc_Unitario*(Qtd_Pedido+IsNull(Qtd_Bonificacao,0)),2),
       Vlr_DescItem = Case 
                        When Per_DescItem > 0 then Round(Prc_Unitario*(Qtd_Pedido+IsNull(Qtd_Bonificacao,0)),2) - Round(Prc_Unitario*Qtd_Pedido*(1-Per_DescItem/100),2)
	                    Else Round(Prc_Unitario*IsNull(Qtd_Bonificacao,0),2) 
                      End
 Where Cod_Estabe = @PCodEstabeDes
   And Protocolo = @PNumPrt

Update NFEIT
   Set Vlr_LiqIte = Vlr_TotItem -
                    IsNull(Vlr_DescRateado,0) -
                    IsNull(Vlr_DscTri,0) +
                    IsNull(Vlr_DespRateada,0) +
                    IsNull(Vlr_SubsTrib,0) +
                    IsNull(Vlr_DifTri,0) +
                    IsNull(Vlr_SbtRes,0) +
                    IsNull(Vlr_Ipi,0) +
                    IsNull(Vlr_Suframa,0) +
                    IsNull(Vlr_Frete,0) +
                    IsNull(Vlr_Seguro,0) + 
                    IsNull(Vlr_DspExt,0)
 Where Cod_Estabe = @PCodEstabeDes
   And Protocolo = @PNumPrt

Exec PR_AtualizaCfopItemNf @PCodEstabeDes,'',@PNumPrt

-- inclui contas a pagar
if Exists(Select 1 From CTREC Where Cod_Estabe = @PCodEstabe And Ser_NfOrigem = @PSerNotSai And Num_NfOrigem = @PNumNotSai) and
   Exists(Select 1 From NFECB Where Cod_Estabe = @PCodEstabeDes And Protocolo = @PNumPrt And IsNull(Cod_EmiFornec,0) > 0)
  begin

    Declare @cb_CodFornec int,
            @cb_NumNot int,
	        @pm_CodAgeCobCar int,
            @pf_FlgUsaInterv bit,
            @pf_CodCntCusCtaPag int,
            @fo_IsnCtaFin int,
            @WCodCtaPag int,
            @WCodRat int,
            @cr_NumDoc varchar(12),
            @cr_DatEmi smalldatetime,
            @cr_DatVct smalldatetime, 
            @cr_PerDscAtc numeric(18,4),
            @cr_DatDscAtc smalldatetime, 
            @cr_VlrDscAtc numeric(18,4),
            @cr_VlrDoc numeric(18,4)

    Select @pm_CodAgeCobCar = CodAgeCobCar
      From PARAM
     Where Cod_Estabe = @PCodEstabe      

    Select @pf_FlgUsaInterv = IsNull(FlgUsaInterv,0),
           @pf_CodCntCusCtaPag = IsNull(CodCntCusCtaPag,0)
      From PMFIN

    Select @cb_CodFornec = cb.Cod_EmiFornec,
           @cb_NumNot = Numero, 
           @fo_IsnCtaFin = IsNull(fo.Isn_CtaFin,0)     
      From NFECB cb
	       Inner Join FORNE fo on cb.Cod_EmiFornec = fo.Codigo
     Where cb.Cod_Estabe = @PCodEstabeDes
       And cb.Protocolo = @PNumPrt

    -- novo financeiro: zera conta gerencial
    if @pf_FlgUsaInterv = 1
      Set @fo_IsnCtaFin = 0    

    DECLARE Ctrec_Cr CURSOR Local Fast_Forward For 
      Select NumDoc = (Num_Documento+Par_Documento), 
	         Dat_Emissao, Dat_Vencimento, 
             Per_DescFinanc, Dat_DscAtc, Vlr_DscAtc, 
		     VlrDoc = Round((Vlr_Documento-Vlr_DescConced),2)
        From CTREC
       Where Cod_Estabe = @PCodEstabe
         And Ser_NfOrigem = @PSerNotSai
         And Num_NfOrigem = @PNumNotSai
    OPEN Ctrec_Cr
    FETCH NEXT FROM Ctrec_Cr INTO @cr_NumDoc, @cr_DatEmi, @cr_DatVct, @cr_PerDscAtc, @cr_DatDscAtc, @cr_VlrDscAtc, @cr_VlrDoc
    WHILE @@FETCH_STATUS = 0
    BEGIN
      EXEC PR_ProxNumero 'Contas_Pagar', @WCodCtaPag output
      Insert into PAGCT (Cod_Estabe, Cod_CtaPag, Tip_Docume, Sta_Docume, Tip_Documento, Cod_Fornec, Dat_Emissa, Dat_Registro,
                         Num_NotOri, Cod_PrtNfe, Cod_PrtPdc, Flg_Consig, Flg_Previs, Cod_AgeCob, Num_Docume, Dat_Vencim,
                         Val_Docume, Val_Saldo, Observacao, Usuario, Transacao,
                         Per_DscAtc, Dat_DscAtc, Val_DscAtc, Isn_CtaFin)
                  Values(@PCodEstabeDes, @WCodCtaPag, 'F', 'A', 'DUP', @cb_CodFornec, @cr_DatEmi, @Date,
                         @cb_NumNot, @PNumPrt, 0, 0, 1, @pm_CodAgeCobCar, @cr_NumDoc, @cr_DatVct,
                         @cr_VlrDoc, @cr_VlrDoc, '', @UsuInfarma, GetDate(),
                         @cr_PerDscAtc, @cr_DatDscAtc, @cr_VlrDscAtc, @fo_IsnCtaFin)
      if @@error <> 0
        begin
          Rollback Transaction
          Return
        end

      EXEC PR_ProxNumero 'Isn_CtaRat', @WCodRat output
      if @@error <> 0
        begin
          Rollback Transaction
          Return
        end

      Insert into PAGRT (Cod_Estabe, Isn_CtaRat, Cod_CtaPag, Isn_CtaFin, Cod_CntCus, Val_DocRat, Val_DscRat)
                 Values (@PCodEstabeDes, @WCodRat, @WCodCtaPag, @fo_IsnCtaFin, @pf_CodCntCusCtaPag, @cr_VlrDoc, 0) 
      if @@error <> 0
        begin
          Rollback Transaction
          Return
        end

      FETCH NEXT FROM Ctrec_Cr INTO @cr_NumDoc, @cr_DatEmi, @cr_DatVct, @cr_PerDscAtc, @cr_DatDscAtc, @cr_VlrDscAtc, @cr_VlrDoc
    END
    CLOSE Ctrec_Cr
    DEALLOCATE Ctrec_Cr
  end  -- inclui contas a pagar

-- atualiza status que indica que foi gerado nota de entrada ref. pedido consolidado
Update PVCCB 
   Set Sta_PdvCon = '3'   
 Where Id_PdvCon = @pc_IdPdvCon

COMMIT TRANSACTION
END
end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].PR_GeraAbastecimentoPrePicking
@PCodEstabe int,
@PCodDep int,
@PCodFab int,
@PCodPrd int,
@PNumRuaOriIni int,
@PNumRuaOriFim int,
@PNumRuaDesIni int,
@PNumRuaDesFim int

AS

BEGIN

SET NOCOUNT ON 

SET ANSI_WARNINGS OFF
--SET ANSI_NULLS OFF

-- verifica se existe endereço disponivel pre-picking
if not Exists(Select 1 From V_ENDDP Where IsNull(Flg_PrePck,0) = 1 And IsNull(Vol_Dispon,0) > 1.0)
  begin
    RAISERROR('Não existe endereço pré-picking disponível',16,1)
	Return
  end
else
-- verifica se há integração com WMS externo
if (Select IsNull(FlgIntegrWmsExt,0) From PMEST Where Cod_Estabe = @PCodEstabe) = 0
BEGIN
BEGIN TRANSACTION

-- Pegar a data atual com a hora 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

Declare @CodPrd int,
        @FabIni int,
        @FabFim int,
        @StaAbc varchar(1),
        @QtdAba int,
        @QtdMov int,
        @CodAba int,

        @CodLot varchar(20),
        @DatVct smalldatetime,
        @QtdLotEnd int,
        @QtdEmbFec int,
        @QtdEmbFecCal int,
        @AccQtd int,
        @QtdFraArm int,

        @NumRuaDe smallint,
        @NumColDe smallint,
        @NumNivDe smallint,
        @NumAptDe smallint,
		@NumRuaPara smallint,
        @NumColPara smallint,
        @NumNivPara smallint,
        @NumAptPara smallint,

        @VolDis numeric(18,4),
        @VolUniEmbFec numeric(18,4),
        @VolTotArm numeric(18,4),
        @Cont smallint,
        @FlgAchou bit,
        @FlgCriouAba bit,
        @FlgLoteAnteriorAtendido bit

-- fabricante
Set @FabIni = @PCodFab
if @PCodFab > 0
  Set @FabFim = @PCodFab
else
  Set @FabFim = (Select max(Cod_Fabricante) From PRODU)

-- rua de origem final
if @PNumRuaOriFim = 0
  Set @PNumRuaOriFim = (Select max(Num_Rua) From ENDDP Where Cod_Estabe = @PCodEstabe And Cod_Dep = @PCodDep And IsNull(Flg_PrePck,0) = 0)

-- rua de destino final
if @PNumRuaDesFim = 0
  Set @PNumRuaDesFim = (Select max(Num_Rua) From ENDDP Where Cod_Estabe = @PCodEstabe And Cod_Dep = @PCodDep And IsNull(Flg_PrePck,0) = 1)

-- sinaliza que criou registro em ABACB
Set @FlgCriouAba = 0

-- produtos pre-picking que que necessitam abastecimento
Declare DPXPR_Cr Cursor Local Fast_Forward For 

  Select dp.Cod_Produt, pr.Sta_AbcAcesso, 
	     QtdAbaste = dp.Qtd_MaxPrePck - IsNull(lp.QtdSldPrePck,0)
  From DPXPR dp Inner Join
       PRODU pr on dp.Cod_Produt = pr.Codigo Left Join

	   -- qtd armazenada em endereços de pré-picking
       (Select l1.Cod_Produt, QtdSldPrePck=sum(l1.Qtd_Saldo) 
	    From PRLTL l1 Inner Join
             ENDDP e1 on (l1.Cod_Estabe = e1.Cod_Estabe and l1.Cod_Dep = e1.Cod_Dep and l1.Num_Rua = e1.Num_Rua and
                          l1.Num_Col = e1.Num_Col and l1.Num_Niv = e1.Num_Niv and l1.Num_Apt = e1.Num_Apt and
						  IsNull(e1.Flg_PrePck,0) = 1)
        Where l1.Cod_Estabe = @PCodEstabe
        And l1.Cod_Dep = @PCodDep
		And l1.Qtd_Saldo > 0
		And dbo.FN_TipLocEnd(l1.Cod_Estabe,l1.Cod_Dep,l1.Num_Rua) = 'D'
		Group by l1.Cod_Produt) lp on (dp.Cod_Produt = lp.Cod_Produt) Left Join

		-- qtd armazenada em endereços não pre-picking
       (Select l2.Cod_Produt, QtdSldPulmao = sum(l2.Qtd_Saldo)
        From PRLTL l2 Inner Join
             ENDDP e2 on (l2.Cod_Estabe = e2.Cod_Estabe and l2.Cod_Dep = e2.Cod_Dep and l2.Num_Rua = e2.Num_Rua and
                          l2.Num_Col = e2.Num_Col and l2.Num_Niv = e2.Num_Niv and l2.Num_Apt = e2.Num_Apt And +
					      IsNull(e2.Flg_PrePck,0) = 0 )
         Where l2.Cod_Estabe = @PCodEstabe   
         And l2.Cod_Dep = @PCodDep
         And dbo.FN_TipLocEnd(l2.Cod_Estabe,l2.Cod_Dep,l2.Num_Rua) = 'D'
         And l2.Qtd_Saldo > 0 
         Group by l2.Cod_Produt) lt on (dp.Cod_Produt = lt.Cod_Produt)

  Where dp.Cod_Estabe = @PCodEstabe
  And dp.Cod_Dep = @PCodDep
  And IsNull(dp.Flg_PrePck,0) = 1                         -- produtos destinados para pré-picking
  And dp.Qtd_MaxPrePck > 0                                -- existe configuração de armazenagem
  And not Exists (Select 1 From ABACB c Inner Join 
                                ABAIT i on c.Cod_Estabe = i.Cod_Estabe and c.Cod_Abaste = i.Cod_Abaste 
                  Where c.Cod_Estabe = @PCodEstabe and c.Cod_Pro = 'T' and c.Cod_Sta = 'A' and i.Cod_Produt = dp.Cod_Produt) 
  And pr.Cod_Fabricante between @FabIni and @FabFim
  And pr.Codigo > 0
  And IsNull(lt.QtdSldPulmao,0) > 0                       -- existe saldo deposito endereços não pre-picking
  And (dp.Qtd_MaxPrePck - IsNull(lp.QtdSldPrePck,0)) > 0  -- necessita abastecimento
  Order by pr.Sta_AbcAcesso, dp.Cod_Produt                -- ordenar por classificação acesso

Open DPXPR_Cr
Fetch Next From DPXPR_Cr Into @CodPrd, @StaAbc, @QtdAba
While @@FETCH_STATUS = 0 -- 1 (produtos pre-picking que necessitam reabastecimento)
  begin
    -- acumulador de qtd a abastecer: @CodPrd, @QtdAba
    Set @AccQtd = @QtdAba
    Set @FlgLoteAnteriorAtendido = 1

    -- selciona lotes endereços não pre-picking disponiveis por vencimento/end. mais distante
    DECLARE LOTES_Cr CURSOR Local Fast_Forward For 

        Select l.Cod_Lote, l.Dat_Vencim, l.Num_Rua, l.Num_Col, l.Num_Niv, l.Num_Apt, 
		       l.Qtd_EmbFec, l.C_QtdEmbFec, l.Qtd_Saldo
        From PRLTL l Inner Join
             ENDDP e on (l.Cod_Estabe = e.Cod_Estabe and l.Cod_Dep = e.Cod_Dep and l.Num_Rua = e.Num_Rua and
                          l.Num_Col = e.Num_Col and l.Num_Niv = e.Num_Niv and l.Num_Apt = e.Num_Apt And 
					      IsNull(e.Flg_PrePck,0) = 0 ) 
         Where l.Cod_Estabe = @PCodEstabe   
         And l.Cod_Dep = @PCodDep
         And dbo.FN_TipLocEnd(l.Cod_Estabe,l.Cod_Dep,l.Num_Rua) = 'D'
		 And l.Cod_Produt = @CodPrd
         And l.Qtd_Saldo > 0 
		 And l.Qtd_EmbFec > 0
         And l.Num_Rua between @PNumRuaOriIni and @PNumRuaOriFim
         Order by l.Dat_Vencim, l.Num_Rua desc, l.Num_Niv desc, l.Num_Apt desc, l.Num_Col desc

    OPEN LOTES_Cr
    FETCH NEXT FROM LOTES_Cr INTO @CodLot, @DatVct, @NumRuaDe, @NumColDe, @NumNivDe, @NumAptDe, 
	                              @QtdEmbFec, @QtdEmbFecCal, @QtdLotEnd

    WHILE (@@FETCH_STATUS = 0) and (@AccQtd > 0) and (@FlgLoteAnteriorAtendido = 1)  -- 2 (lotes disponiveis nao pre-picking)
    BEGIN
      -- inicializar contador de procura de endereços do lote
      Set @Cont = 1
      Set @FlgLoteAnteriorAtendido = 0

	  -- calcula volume da caixa fechada do lote
      Select @VolUniEmbFec = Case
                               When IsNull(e1.Vol_Emb,0) > 0 then e1.Vol_Emb
                               When (pr.Qtd_Embalagem = @QtdEmbFec) and (IsNull(pr.Alt_EmbCmp,0)) > 0 then pr.Alt_EmbCmp*pr.Lrg_EmbCmp*pr.Prf_EmbCmp
                               When IsNull(e2.Vol_Emb,0) > 0 then @QtdEmbFec*e2.Vol_Emb
                               When IsNull(pr.Alt_Emb,0) > 0 then @QtdEmbFec*pr.Alt_Emb*pr.Lrg_Emb*pr.Prf_Emb
                               Else 0
                             End
        From PRODU pr Left Join
             PREAN e1 on (pr.Codigo = e1.Cod_Produt and @QtdEmbFec = e1.Qtd_UndEmb and e1.Tip_Cod = '4' and e1.Vol_Emb > 0) Left Join
             PREAN e2 on (pr.Codigo = e2.Cod_Produt and e2.Tip_Cod = '3' and e2.Vol_Emb > 0)
        Where pr.Codigo = @CodPrd

      -- qtd do lote a movimentar - multiplo de cxa.fechada
      if @AccQtd >= @QtdLotEnd
        Set @QtdFraArm = @QtdLotEnd
      else
        Set @QtdFraArm = @AccQtd

      -- normaliza quantidade e volume a armazenar
      Set @QtdFraArm = (@QtdFraArm/@QtdEmbFecCal) * @QtdEmbFecCal
      Set @VolTotArm = (@QtdFraArm/@QtdEmbFecCal) * @VolUniEmbFec 

      -- devido a limitacao da chave em ABAIT so posso incluir um registro de PRLTL (Produto/lote/End.Armazenagem de origem)
      Set @FlgAchou = 0  -- sinaliza se a consulta relacionada com o contador obteve sucesso

	  -- procura endereços pre-picking disponiveis
      while (@QtdFraArm > 0) and (@Cont <= 4) and (@FlgAchou = 0)
        begin
           -- 1: seleciona somente endereços pre-picking com mesmo produto/lote 
          if @Cont = 1
            begin
              DECLARE ENDDP_Cr CURSOR Local Fast_Forward For 
                Select en.Num_Rua, en.Num_Col, en.Num_Niv, en.Num_Apt, en.Vol_Dispon
                  From V_ENDDP en
                Where en.Cod_Estabe = @PCodEstabe                             
                And en.Cod_Dep = @PCodDep                             
                And IsNull(en.Flg_DepFec,0) = 1 
                And IsNull(en.Flg_Bloqueado,0) = 0 
                And IsNull(en.Flg_PrePck,0) = 1 
                And en.Num_Rua between @PNumRuaDesIni and @PNumRuaDesFim
                And en.Vol_Dispon >= @VolTotArm --@VolUniEmbFec 
                And Exists(Select 1 From PRLTL lt Where lt.Cod_Estabe = en.Cod_Estabe and lt.Cod_Dep = en.Cod_Dep and 
                                                        lt.Num_Rua = en.Num_Rua and lt.Num_Col = en.Num_Col and
                                                        lt.Num_Niv = en.Num_Niv and lt.Num_Apt = en.Num_Apt and
														lt.Cod_Produt = @CodPrd and lt.Cod_Lote = @CodLot)
                Order by en.Num_Rua, en.Num_Col, en.Num_Niv
            end
          else  
           -- 2: seleciona somente endereços que atendem a quantidade e à curva (ou a mais proxima acima)
          if @Cont = 2
            begin
              DECLARE ENDDP_Cr CURSOR Local Fast_Forward For 
                Select en.Num_Rua, en.Num_Col, en.Num_Niv, en.Num_Apt, en.Vol_Dispon
                  From V_ENDDP en 
                Where en.Cod_Estabe = @PCodEstabe                             
                And en.Cod_Dep = @PCodDep                             
                And IsNull(en.Flg_DepFec,0) = 1 
                And IsNull(en.Flg_Bloqueado,0) = 0 
                And IsNull(en.Flg_PrePck,0) = 1 
                And en.Num_Rua between @PNumRuaDesIni and @PNumRuaDesFim
                And en.Vol_Dispon >= @VolTotArm  --@VolUniEmbFec 
                And Substring(IsNull(en.Str_AbcAcesso,''),1,1) >= @StaAbc
                And not Exists(Select 1 From PRLTL lt Where lt.Cod_Estabe = en.Cod_Estabe and lt.Cod_Dep = en.Cod_Dep and 
                                                            lt.Num_Rua = en.Num_Rua and lt.Num_Col = en.Num_Col and
                                                            lt.Num_Niv = en.Num_Niv and lt.Num_Apt = en.Num_Apt and
                                                            lt.Cod_Produt = @CodPrd)
                Order by Substring(IsNull(en.Str_AbcAcesso,''),1,1), en.Num_Rua, en.Num_Col, en.Num_Niv
            end
          else  
           -- 3: seleciona somente endereços que atendem a quantidade e sem curva definida
          if @Cont = 3
            begin
              DECLARE ENDDP_Cr CURSOR Local Fast_Forward For 
                Select en.Num_Rua, en.Num_Col, en.Num_Niv, en.Num_Apt, en.Vol_Dispon
                  From V_ENDDP en 
                Where en.Cod_Estabe = @PCodEstabe                             
                And en.Cod_Dep = @PCodDep                             
                And IsNull(en.Flg_DepFec,0) = 1 
                And IsNull(en.Flg_Bloqueado,0) = 0 
                And IsNull(en.Flg_PrePck,0) = 1 
                And en.Num_Rua between @PNumRuaDesIni and @PNumRuaDesFim
                And en.Vol_Dispon >= @VolTotArm 
                And Substring(IsNull(en.Str_AbcAcesso,''),1,1) = ''
                And not Exists(Select 1 From PRLTL lt Where lt.Cod_Estabe = en.Cod_Estabe and lt.Cod_Dep = en.Cod_Dep and 
                                                            lt.Num_Rua = en.Num_Rua and lt.Num_Col = en.Num_Col and
                                                            lt.Num_Niv = en.Num_Niv and lt.Num_Apt = en.Num_Apt and
                                                            lt.Cod_Produt = @CodPrd)
                Order by Substring(IsNull(en.Str_AbcAcesso,''),1,1), en.Num_Rua, en.Num_Col, en.Num_Niv
            end
          else  
           -- 4: seleciona somente endereços que atendem a quantidade e com curva inferior
          if @Cont = 4
            begin
              DECLARE ENDDP_Cr CURSOR Local Fast_Forward For 
                Select en.Num_Rua, en.Num_Col, en.Num_Niv, en.Num_Apt, en.Vol_Dispon
                  From V_ENDDP en 
                Where en.Cod_Estabe = @PCodEstabe                             
                And en.Cod_Dep = @PCodDep                             
                And IsNull(en.Flg_DepFec,0) = 1 
                And IsNull(en.Flg_Bloqueado,0) = 0 
                And IsNull(en.Flg_PrePck,0) = 1 
                And en.Num_Rua between @PNumRuaDesIni and @PNumRuaDesFim
                And en.Vol_Dispon >= @VolTotArm 
                And Substring(IsNull(en.Str_AbcAcesso,''),1,1) < @StaAbc
                And not Exists(Select 1 From PRLTL lt Where lt.Cod_Estabe = en.Cod_Estabe and lt.Cod_Dep = en.Cod_Dep and 
                                                            lt.Num_Rua = en.Num_Rua and lt.Num_Col = en.Num_Col and
                                                            lt.Num_Niv = en.Num_Niv and lt.Num_Apt = en.Num_Apt and
                                                            lt.Cod_Produt = @CodPrd)
                Order by Substring(IsNull(en.Str_AbcAcesso,''),1,1) desc, en.Num_Rua, en.Num_Col, en.Num_Niv
            end
            
          OPEN ENDDP_Cr
          FETCH NEXT FROM ENDDP_Cr INTO @NumRuaPara, @NumColPara, @NumNivPara, @NumAptPara, @VolDis
          WHILE (@@FETCH_STATUS = 0) and (@FlgAchou = 0)
          BEGIN
            Set @QtdMov = 0

            -- recalcula quantidade a movimentar
            if @VolUniEmbFec > 0
              begin
                if @VolTotArm > @VolDis
                  Set @QtdMov = (@VolDis/@VolUniEmbFec) * @QtdEmbFecCal
                else
                  Set @QtdMov = @QtdFraArm 
              end

            if @QtdMov > @QtdFraArm
              Set @QtdMov = @QtdFraArm 

            -- gera registro de abastecimento (pre-picking)
            if @QtdMov > 0
              begin
                -- cria registro cabeçalho em ABACB
                if @FlgCriouAba = 0
                  begin
                    Select @CodAba = IsNull((Select Max(Cod_Abaste) From ABACB Where Cod_Estabe = @PCodEstabe),0) + 1 
                    Insert Into ABACB (Cod_Estabe, Cod_Abaste, Des_Abaste, Cod_Dep, Cod_Pro, Cod_Sta, Usuario)
                               Values (@PcodEstabe, @CodAba, 'PRE-PICKING', @PCodDep, 'T', 'A', 'SISTEMA')
                    if @@error <> 0
                      begin
                        Rollback Transaction
                        Return
                      end

                    Set @FlgCriouAba = 1
                  end					   

                -- inclui registro ABAIT
                if not Exists(Select Cod_Produt 
                              From ABAIT
                              Where Cod_Estabe = @PCodEstabe
                              And Cod_Abaste = @CodAba         
                              And Cod_Produt = @CodPrd And Cod_Lote = @CodLot  
                              And Cod_Dep = @PCodDep
                              And Num_Rua = @NumRuaDe And Num_Col = @NumColDe
                              And Num_Niv = @NumNivDe And Num_Apt = @NumAptDe)
                  begin
                    Insert Into ABAIT (Cod_Estabe, Cod_Abaste, Cod_Produt, Cod_Lote, 
                                       Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Qtd_Mov,
                                       Num_RuaDes, Num_ColDes, Num_NivDes, Num_AptDes)
                               Values (@PCodEstabe, @CodAba, @CodPrd, @CodLot,
                                       @PCodDep, @NumRuaDe, @NumColDe, @NumNivDe, @NumAptDe, @QtdMov,
                                       @NumRuaPara, @NumColPara, @NumNivPara, @NumAptPara)
                    if @@error <> 0
                      begin
                        Rollback Transaction
                        Return
                      end

                    Set @FlgLoteAnteriorAtendido = 1
                    Set @QtdFraArm = @QtdFraArm - @QtdMov      
                    Set @AccQtd = @AccQtd - @QtdMov

                    -- sinaliza que achou
                    Set @FlgAchou = 1
                  end
                      
              end
            
            FETCH NEXT FROM ENDDP_Cr INTO @NumRuaPara, @NumColPara, @NumNivPara, @NumAptPara, @VolDis
          END  --WHILE (@@FETCH_STATUS = 0) and (@FlgAchou = 0)
          
          CLOSE ENDDP_Cr
          DEALLOCATE ENDDP_Cr    

          -- incrementa contador 
          Set @Cont = @Cont + 1

        end -- while (@QtdFraArm > 0) and (@Cont <= 4)

      FETCH NEXT FROM LOTES_Cr INTO @CodLot, @DatVct, @NumRuaDe, @NumColDe, @NumNivDe, @NumAptDe, 
	                                @QtdEmbFec, @QtdEmbFecCal, @QtdLotEnd
    END    -- WHILE (@@FETCH_STATUS = 0) and (@AccQtd > 0) and (@FlgLoteAnteriorAtendido = 1)  -- 2 (lotes disponiveis nao pre-picking)

    CLOSE LOTES_Cr
    DEALLOCATE LOTES_Cr    

    Fetch Next From DPXPR_Cr Into @CodPrd, @StaAbc, @QtdAba
  end  -- While @@FETCH_STATUS = 0 -- 1 (produtos pre-picking que necessitam reabastecimento)

Close DPXPR_Cr
Deallocate DPXPR_Cr

COMMIT TRANSACTION
END
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION dbo.FN_ProximoDiaUtil 
(
  @Dat_Ref DATETIME 
)
RETURNS DATETIME

AS

BEGIN 
 
  WHILE (1 = 1)
  BEGIN
    SET @Dat_Ref = @Dat_Ref + (CASE DATEPART(WEEKDAY, @Dat_Ref) 
                                 WHEN 1 THEN 1   -- domingo
                                 WHEN 7 THEN 2   -- sabado 
                                 ELSE 0 
                               END)
    IF EXISTS (SELECT 1 FROM dbo.TBFER WITH ( NOLOCK ) 
               WHERE Num_Dia = DAY(@Dat_Ref) AND Num_Mes = MONTH(@Dat_Ref) 
               AND ((Num_Ano = 0) or (Num_Ano = YEAR(@Dat_Ref)))
               AND Tip_Feriad = '1' )
      SET @Dat_Ref = @Dat_Ref + 1
    ELSE
      BREAK  
  END
 
  RETURN CAST(FLOOR(CAST(@Dat_Ref AS FLOAT)) AS DATETIME)
 
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION dbo.FN_DiaUtil 
(
  @Dat_Ref DATETIME 
)
RETURNS bit

AS

BEGIN 
 
  DECLARE @retorno BIT
 
  IF ( DATEPART(WEEKDAY, @Dat_Ref) IN ( 1, 7 ) )  -- 1-Domingo,  7-Sabado
    SET @retorno = 0    
  ELSE
    BEGIN
      IF EXISTS (SELECT 1 FROM dbo.TBFER WITH ( NOLOCK ) 
                 WHERE Num_Dia = DAY(@Dat_Ref) AND Num_Mes = MONTH(@Dat_Ref) 
                 AND ((Num_Ano = 0) or (Num_Ano = YEAR(@Dat_Ref)))
                 AND Tip_Feriad = '1') 
        SET @retorno = 0
      ELSE
        SET @retorno = 1
    END
    
  RETURN @retorno
 
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION dbo.FN_DiaUtilAnterior 
(
  @Dat_Ref DATETIME 
)
RETURNS DATETIME

AS

BEGIN
 
  WHILE (1 = 1)
  BEGIN
    SET @Dat_Ref = @Dat_Ref - (CASE DATEPART(WEEKDAY, @Dat_Ref) 
	                             WHEN 1 THEN 2   -- domingo
								 WHEN 7 THEN 1   -- sabado
								 ELSE 0 
	                           END)
    IF EXISTS (SELECT 1 FROM dbo.TBFER WITH ( NOLOCK ) 
               WHERE Num_Dia = DAY(@Dat_Ref) AND Num_Mes = MONTH(@Dat_Ref) 
               AND ((Num_Ano = 0) or (Num_Ano = YEAR(@Dat_Ref)))
               AND Tip_Feriad = '1')
      SET @Dat_Ref = @Dat_Ref - 1
    ELSE
      BREAK  
  END
 
  RETURN CAST(FLOOR(CAST(@Dat_Ref AS FLOAT)) AS DATETIME)
 
END
GO

SET ANSI_NULLS ON
