SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ProIni_AtualizaClientesAtraso]
@CodEstabe int,
@CodCli int        -- cod.cliente se = 0 atualiza todos os clientes

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = cast(GetDate() as Date)

Begin Transaction

  Set @CodEstabe = (Select top 1 Cod_Estabe From ESTAB order by Cod_Estabe)

  -- variaveis de trabalho
  Declare @WDatPag smalldatetime,
          @WObserv varchar(56),
          @WCodCliIni int,
          @WCodCliFim int

  -- coloca campos de PARAM na memoria
  Declare @pm_QtdMesPagCtrAtr int,
          @pm_FlgZerLimCre bit,
          @pm_QtdMesTmpCom int

  Select @pm_QtdMesPagCtrAtr = Isnull(QtdMesPagCtrAtr,0),
         @pm_FlgZerLimCre = Isnull(FlgZerLimCre,0),
         @pm_QtdMesTmpCom = Isnull(QtdMesTmpCom,0)
    From PARAM
    Where Cod_Estabe = @CodEstabe

  -- data base de pagamento p/ titulos quitados : calculo do atraso medio
  Set @WDatPag = @Date - (@pm_QtdMesPagCtrAtr*30)
  Set @WDatPag = Cast(Cast(Year(@WDatPag) as varchar) + '-' + Cast(Month(@WDatPag) as varchar) + '-01 00:00:00' as smalldatetime)

-- limita faixa de clientes
if @CodCli > 0
  begin
    Set @WCodCliIni = @CodCli
    Set @WCodCliFim = @CodCli
  end
else
  begin
    Set @WCodCliIni = 0
    Set @WCodCliFim = IsNull((Select max(Codigo) From CLIEN),0)
  end

-- verifica entrada de cheques pendentes
Update cr 
  Set cr.Sta_ChqVnc = '9'
  From CTREC cr
       Inner Join PARAM pm on cr.Cod_Estabe = pm.Cod_Estabe
  Where cr.Status = 'A'
  And Isnull(pm.QtdDiaPrzEntChqVct,0) > 0
  And Charindex(Substring('00000'+Cast(cr.Cod_Agente as varchar),Len('00000'+Cast(cr.Cod_Agente as varchar))-4,5),pm.StrCodAgcChqVct) > 0
  And (@Date-cr.Dat_Emissao) > Isnull(pm.QtdDiaPrzEntChqVct,0)
  And cr.Cod_Cliente between @WCodCliIni and @WCodCliFim
  And cr.Sta_ChqVnc <> '9'

-- ATUALIZA CLIENTES - GLOBAL  
-- total debito, atraso atual do cliente
Update cl
  Set cl.Total_Debito = IsNull(cr.Total_Debito,0),
      cl.Sta_ChqVnc = IsNull(cr.Sta_Chq,''),
      cl.Atraso_Atual = IsNull(cr.Maior_Atraso,0)
  From CLIEN cl Left Outer Join 
       (Select r.Cod_Cliente, max(r.Sta_Cheque) as Sta_Chq, 
               sum(r.Vlr_Debito) as Total_Debito, max(Dias_Atraso) as Maior_Atraso
        From (Select Cod_Cliente, IsNull(Sta_ChqVnc,'') as Sta_Cheque,
                     IsNull(Vlr_Saldo,0)+IsNull(Vlr_Pendente,0) as Vlr_Debito,
                     Dias_Atraso = Case
                                     When Tip_Vencimento = 'A' Then 0
                                     Else Case
                                            When @Date > IsNull(Dat_Vencimento,0)+IsNull(Qtd_DiaExtVct,0) Then 
                                              Case When (Dat_Quitacao is null) and (IsNull(Dat_Vencimento,0) > 0) Then dbo.FN_DiasAtraso(Dat_Vencimento,@Date)  --Cast((@Date-IsNull(Dat_Vencimento,0)-IsNull(Qtd_DiaExtVct,0)) as int)
                                                   Else Case 
                                                          When (Dat_Quitacao is not null) and (Dat_Quitacao > (IsNull(Dat_Vencimento,0)+IsNull(Qtd_DiaExtVct,0))) Then Cast((IsNull(Dat_Quitacao,0)-IsNull(Dat_Vencimento,0)-IsNull(Qtd_DiaExtVct,0)) as int)
                                                          Else 0
                                                         End
                                              End
                                            Else 0
                                          End           
                                   End
              From CTREC
              Where ((Status = 'A') or (Status = 'P')) 
              And Cod_Cliente between @WCodCliIni and @WCodCliFim ) r
              Group by r.Cod_Cliente) cr on cl.Codigo = cr.Cod_Cliente
  Where cl.Codigo between @WCodCliIni and @WCodCliFim
  And ((cl.Total_Debito <> IsNull(cr.Total_Debito,0)) or
       (cl.Sta_ChqVnc <> IsNull(cr.Sta_Chq,'')) or
       (cl.Atraso_Atual <> IsNull(cr.Maior_Atraso,0)))

-- maior atraso do cliente
Update cl
  Set cl.Maior_Atraso = IsNull(cr.Maior_Atraso,0)
  From CLIEN cl Left Outer Join 
       (Select r.Cod_Cliente, max(Dias_Atraso) as Maior_Atraso
        From (Select Cod_Cliente, IsNull(Sta_ChqVnc,'') as Sta_Cheque,
                     IsNull(Vlr_Saldo,0)+IsNull(Vlr_Pendente,0) as Vlr_Debito,
                     Dias_Atraso = Case
                                     When Tip_Vencimento = 'A' Then 0
                                     Else Case
                                            When @Date > IsNull(Dat_Vencimento,0)+IsNull(Qtd_DiaExtVct,0) Then 
                                              Case When (Dat_Quitacao is null) and (IsNull(Dat_Vencimento,0) > 0) Then Cast((@Date-IsNull(Dat_Vencimento,0)-IsNull(Qtd_DiaExtVct,0)) as int)
                                                   Else Case 
                                                          When (Dat_Quitacao is not null) and (Dat_Quitacao > (IsNull(Dat_Vencimento,0)+IsNull(Qtd_DiaExtVct,0))) Then Cast((IsNull(Dat_Quitacao,0)-IsNull(Dat_Vencimento,0)-IsNull(Qtd_DiaExtVct,0)) as int)
                                                          Else 0
                                                         End
                                              End
                                            Else 0
                                          End           
                                   End
              From CTREC
              Where ((Status <> 'C') and (Status <> 'D') and (Status <> 'B'))
              and Cod_Cliente between @WCodCliIni and @WCodCliFim) r
              Group by r.Cod_Cliente) cr on cl.Codigo = cr.Cod_Cliente
  Where cl.Codigo between @WCodCliIni and @WCodCliFim
  And cl.Maior_Atraso <> IsNull(cr.Maior_Atraso,0)


-- atraso medio
Update cl
  Set Atraso_MedAtu = IsNull(cr.Atraso_Medio,0)
  From CLIEN cl Left Outer Join
       (Select r.Cod_Cliente, Count(*) as Qtd_Tit, sum(r.Dias_Atraso) as Total_Atraso,
               Atraso_Medio = Case 
                                When Count(*) > 0 Then Cast((sum(r.Dias_Atraso)*1.0/Count(*)) as int)
                                Else 0
                               End
        From (Select a.Cod_Cliente, 
                     Dias_Atraso = Case
                                     When a.Tip_Vencimento = 'A' Then 0
                                     Else Case
                                            When @Date > IsNull(a.Dat_Vencimento,0)+IsNull(a.Qtd_DiaExtVct,0) Then 
                                              Case When (a.Dat_Quitacao is null) and (IsNull(a.Dat_Vencimento,0) > 0) Then Cast((@Date-IsNull(a.Dat_Vencimento,0)-IsNull(a.Qtd_DiaExtVct,0)) as int)
                                                   Else Case 
                                                          When (a.Dat_Quitacao is not null) and (a.Dat_Quitacao > (IsNull(a.Dat_Vencimento,0)+IsNull(a.Qtd_DiaExtVct,0))) Then Cast((IsNull(a.Dat_Quitacao,0)-IsNull(a.Dat_Vencimento,0)-IsNull(a.Qtd_DiaExtVct,0)) as int)
                                                          Else 0
                                                         End
                                              End
                                            Else 0
                                          End           
                                   End
              From CTREC a Inner Join CLIEN b on a.Cod_Cliente = b.Codigo
              Where ((a.Status = 'A') or (a.Status = 'P') or 
                     ((a.Status = 'Q') and (a.Dat_Quitacao >= Case When @pm_QtdMesPagCtrAtr > 0 Then @WDatPag Else b.Data_Cadastro End)))
              And a.Cod_Cliente between @WCodCliIni and @WCodCliFim) r
        Where r.Dias_Atraso > 0
        Group by r.Cod_Cliente) cr on cl.Codigo = cr.Cod_Cliente
  Where cl.Codigo between @WCodCliIni and @WCodCliFim
  And Atraso_MedAtu <> IsNull(cr.Atraso_Medio,0)
  
-- zera limite de credito
Set @WObserv = '** RENOVAR CADASTRO: Credito cancelado em '+Cast(@Date as varchar) + '//  '
Update CLIEN
  Set Vlr_LimCreAnt = IsNull(Limite_Credito,0),
      Limite_Credito = 0,
      Dat_LimCreAtu = @Date
 --     Observacao = @WObserv
  Where IsNull(Limite_Credito,0) > 0
  And @pm_FlgZerLimCre = 1 and @pm_QtdMesTmpCom > 0 
  And (Cast((@Date - IsNull(Data_UltimaFatura,0)) as int)/30 > @pm_QtdMesTmpCom) 
  And (Cast((@Date - IsNull(Data_Cadastro,0)) as int)/30 > @pm_QtdMesTmpCom)
  And Codigo between @WCodCliIni and @WCodCliFim
  
  -- DMD-6928 - Exclusão de dados inválidos na ENXES impactando em integração com ARTNEW Acripel
If Exists (Select 1
             From ENXES e 
                  Inner Join CLIEN c on e.Cod_Client = c.Codigo and e.Num_CgcCpf <> c.Cgc_Cpf)
Delete e
  From ENXES e 
       Inner Join CLIEN c on e.Cod_Client = c.Codigo and e.Num_CgcCpf <> c.Cgc_Cpf  

Commit Transaction

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_EliminaPendenciasPdc]
@CodEstabe int,
@NumPed int,
@CodPrd int       -- se = 0: cancela todos os itens : cancela o pedido todo

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

Begin Transaction

  Declare @WQtdPen int,
          @WFlgAtu bit,
          @it_CodPrd int, 
          @it_QtdPed int, 
          @it_QtdBon int, 
          @it_QtdFal int, 
          @it_QtdFat int

  Set @WFlgAtu = 0

  -- processa itens
  if @CodPrd > 0
    Declare PDCIT_Cr Cursor Local For 
      Select it.Cod_Produto, it.Qtd_Pedido, it.Qtd_Bonificacao, it.Qtd_Falta, it.Qtd_Fatura
        From PDCIT it Inner Join 
             PDCCB cb on cb.Cod_Estabe = it.Cod_Estabe and cb.Numero = it.Numero
        Where it.Cod_Estabe = @CodEstabe 
        And it.Numero = @NumPed
        And cb.Status = 'P'
        And it.Cod_Produto = @CodPrd
  else
    Declare PDCIT_Cr Cursor Local For 
      Select it.Cod_Produto, it.Qtd_Pedido, it.Qtd_Bonificacao, it.Qtd_Falta, it.Qtd_Fatura
        From PDCIT it Inner Join 
             PDCCB cb on cb.Cod_Estabe = it.Cod_Estabe and cb.Numero = it.Numero
        Where it.Cod_Estabe = @CodEstabe 
        And it.Numero = @NumPed
        And cb.Status = 'P'

  Open PDCIT_Cr
  Fetch Next From PDCIT_Cr Into @it_CodPrd, @it_QtdPed, @it_QtdBon, @it_QtdFal, @it_QtdFat
  While @@FETCH_STATUS = 0
    begin   
      Set @WFlgAtu = 1
      Set @WQtdPen = (@it_QtdPed + @it_QtdBon) - (@it_QtdFal + @it_QtdFat)

      Update PRXES
        Set Qtd_Transi = case
                           When Qtd_Transi  < 0 then 0 
                           When (@WQtdPen > 0) and (Qtd_Transi > @WQtdPen) then Qtd_Transi - @WQtdPen
                           else 0                                                                                                                 
                         end
      Where Cod_Estabe = @CodEstabe                 
      And Cod_Produt = @it_CodPrd

      Update PDCIT
        Set Qtd_Falta = Qtd_Pedido + Qtd_Bonificacao - Qtd_Fatura
      Where Cod_Estabe = @CodEstabe
      And Numero = @NumPed
      And Cod_Produto = @it_CodPrd

      Fetch Next From PDCIT_Cr Into @it_CodPrd, @it_QtdPed, @it_QtdBon, @it_QtdFal, @it_QtdFat
    end

  Close PDCIT_Cr
  Deallocate PDCIT_Cr

  if @CodPrd = 0
    -- elimina previsoes
    Delete cp
      From PAGCT cp Inner Join 
           PDCCB cb on cp.Cod_Estabe = cb.Cod_Estabe and cp.Cod_PrtPdc = cb.Numero
      Where cb.Cod_Estabe = @CodEstabe 
      And cp.Cod_PrtPdc = @NumPed
      and cp.Sta_Docume = 'A'
      and cb.Status = 'P'

  -- se não há nenhuma pendência, fecha o pedido
  if not Exists (Select 1 From PDCIT Where Cod_Estabe = @CodEstabe And Numero = @NumPed And Qtd_Pendente > 0)
    Update PDCCB
      Set Status = 'F',
          Dat_Fecham = @Date
      Where Cod_Estabe = @CodEstabe 
      And Numero = @NumPed
      And Status = 'P'

  if @WFlgAtu = 1
    begin
      -- GERA PREVISAO DE PAGAMENTOS 
      Exec PR_GeraPrevisaoPAGCT @CodEstabe, @NumPed
      if @@error <> 0
        begin
          Rollback Transaction
          Return
        end
	end

Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_TrocaLote]
@PCodEstabe int,
@PCodPrd int, 
@PCodLotAtu varchar(20),
@PCodLotNew varchar(20),
@PDatFabNew smalldatetime,
@PDatVctNew smalldatetime,
@PCodMveEnt int,
@PCodMveSai int,
@PQtdSldPraInf int = 0, 
@PQtdSldDepInf int = 0

AS

SET ANSI_WARNINGS OFF
SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

Declare @WTipMveEnt varchar(1),
        @WTipMveSai varchar(1)

-- verifica codigos de movimentacao                 
Set @WTipMveEnt = (Select Tip_Movimento From TPMVE Where Codigo = @PCodMveEnt) 
Set @WTipMveSai = (Select Tip_Movimento From TPMVE Where Codigo = @PCodMveSai) 

if (@PCodLotAtu = @PCodLotNew) and
   ((Select Dat_Fabric From PRLOT Where Cod_Estabe = @PCodEstabe And Cod_Produt = @PCodPrd And Cod_Lote = @PCodLotAtu) = @PDatFabNew) and
   ((Select Dat_Vencim From PRLOT Where Cod_Estabe = @PCodEstabe And Cod_Produt = @PCodPrd And Cod_Lote = @PCodLotAtu) = @PDatVctNew)
  RAISERROR('Não há qualquer alteração no lote',16,1)
else
if @WTipMveEnt <> 'E'
  RAISERROR('Código de movimentação de entrada inválida',16,1)
else
if @WTipMveSai <> 'S'
  RAISERROR('Código de movimentação de saída inválida',16,1)
else
BEGIN

  BEGIN TRANSACTION

  Declare @WCodAcr int,
          @Usuario varchar(15),
          @DesHistorico varchar(40),
          @DatVct smalldatetime, 
          @DatFab smalldatetime, 
          @QtdSldPra int, 
          @QtdSldDep int,
          @CodDep smallint,
          @NumRua smallint,
          @NumCol smallint,
          @NumNiv smallint,
          @NumApt smallint

  -- Auditoria usuario infarma ou banco
  Set @Usuario = dbo.FN_UsuarioInfarma()

  -- lotes de itens a movimentar
  DECLARE LOTES_Cr CURSOR Local Fast_Forward For 

    Select lt.Dat_Fabric, lt.Dat_Vencim, lt.Qtd_SldPra, lt.Qtd_SldDep,
           lt.Cod_Dep, dp.Num_Rua, dp.Num_Col, dp.Num_Niv, dp.Num_Apt
    From PRLOT lt         
		 Inner Join DPXPR dp on lt.Cod_Estabe = dp.Cod_Estabe and lt.Cod_Dep = dp.Cod_Dep and lt.Cod_PRodut = dp.Cod_Produt
    Where lt.Cod_Estabe = @PCodEstabe 
    And lt.Cod_Produt = @PCodPrd
    And lt.Cod_Lote = @PCodLotAtu 
    And lt.Qtd_Saldo > 0 
            
  OPEN LOTES_Cr
  FETCH NEXT FROM LOTES_Cr INTO @DatFab, @DatVct, @QtdSldPra, @QtdSldDep,
                                @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt

  WHILE @@FETCH_STATUS = 0
  BEGIN
    -- da saida picking (acerto)   
    Set @DesHistorico = 'TROCA DE LOTE ('+@PCodLotNew+')'

    Exec PR_ProxNumero 'Acerto', @WCodAcr output
    if @@error <> 0
      begin
        Rollback Transaction
        Return
      end

	if @PQtdSldPraInf > 0
      begin
	    Set @QtdSldPra = @PQtdSldPraInf
      end	  

	if @PQtdSldDepInf > 0
      begin
	    Set @QtdSldDep = @PQtdSldDepInf
      end	  

    Insert into ACERT (Cod_Estabe, Numero, Dat_Movimento,
                       Cod_Produto, Cod_Lote, Dat_Vencimento, Dat_Fabric,
                       Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt,
                       Qtd_Acerto, Qtd_AceDep, Cod_TipMov, Flg_NotFis, Historico, Usuario, Transacao)
              Values  (@PCodEstabe, @WCodAcr, @Date,
                       @PCodPrd, @PCodLotAtu, @DatVct, @DatFab,
                       @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt,
                       @QtdSldPra, @QtdSldDep, @PCodMveSai, 0, @DesHistorico, @Usuario, GetDate())
    if @@error <> 0
      begin
        Rollback Transaction
        Return
      end

    -- da entrada no picking (acerto)
    Set @DesHistorico = 'TROCA DE LOTE ('+@PCodLotAtu+')'

    Exec PR_ProxNumero 'Acerto', @WCodAcr output
    if @@error <> 0
      begin
        Rollback Transaction
        Return
      end
                  
    Insert into ACERT (Cod_Estabe, Numero, Dat_Movimento,
                       Cod_Produto, Cod_Lote, Dat_Vencimento, Dat_Fabric,
                       Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt,
                       Qtd_Acerto, Qtd_AceDep, Cod_TipMov, Flg_NotFis, Historico, Usuario, Transacao)
              Values  (@PCodEstabe, @WCodAcr, @Date, 
                       @PCodPrd, @PCodLotNew, @PDatVctNew, @PDatFabNew,
                       @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt,
                       @QtdSldPra, @QtdSldDep, @PCodMveEnt, 0, 'TROCA DE LOTE', @Usuario, GetDate())
    if @@error <> 0
      begin
        Rollback Transaction
        Return
      end

    FETCH NEXT FROM LOTES_Cr INTO @DatFab, @DatVct, @QtdSldPra, @QtdSldDep,
                                  @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt
  END
  CLOSE LOTES_Cr
  DEALLOCATE LOTES_Cr     

/*
  -- altera ltotes em PRLTL
  Update PRLTL 
    Set Cod_Lote = @PCodLotNew,
	    Dat_Fabric = @PDatFabNew, 
        Dat_Vencim = @PDatVctNew 
  Where Cod_Estabe = @PCodEstabe 
  And Cod_Produt = @PCodPrd 
  And Cod_Lote = @PCodLotAtu 
  And Qtd_Saldo > 0
*/

  COMMIT TRANSACTION

END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION dbo.[FN_TipSaiPdv] 
(
  @PCodOpe varchar(3)
)
RETURNS VARCHAR(1)
-- tipo de saida de Pedido de Venda: 'B'= bonificacao, 'V'endas, ..

AS

BEGIN

Declare @WTipSai varchar(1)

Set @WTipSai = IsNull((Select Case
                                When ((IsNull(Cod_CfoNorInt,0) = 5910) or (IsNull(Cod_CfoNorExt,0) = 6910)) then 'B'  -- bonificacao
                                Else Tip_Ope
                              End
                         From TPOPE 
                        Where Cod_Ope = @PCodOpe),'')

-- Retorna o resultado da function
RETURN @WTipSai

END
GO


SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ManutencaoCliente] 
@CodEstabe int,      -- estabelecimento
@Campo varchar(25),  -- nome do campo 
@Valor int,          -- novo valor
@Codigo int          -- cod. cliente

WITH ENCRYPTION 
AS

SET NOCOUNT ON

Begin Transaction

  if @Campo = 'Cod_Vendedor' 
    Update e
      Set e.Cod_Vendedor = @Valor
    From ENXES e 
         Inner Join CLIEN c ON c.Cgc_Cpf = e.Num_CgcCpf 
    Where e.Cod_Estabe =  @CodEstabe
    And c.Codigo = @Codigo

  if @Campo = 'Cod_OperTlmk' 
    Update e
      Set e.Cod_Operador = @Valor
    From ENXES e 
         Inner Join CLIEN c ON c.Cgc_Cpf = e.Num_CgcCpf 
    Where e.Cod_Estabe =  @CodEstabe
    And c.Codigo = @Codigo

  if @Campo = 'Cod_AgeCob' 
    Update e
      Set e.Cod_AgeCob = @Valor
    From ENXES e 
         Inner Join CLIEN c ON c.Cgc_Cpf = e.Num_CgcCpf 
    Where e.Cod_Estabe =  @CodEstabe
    And c.Codigo = @Codigo

  if @Campo = 'Cod_Transp' 
    Update e
      Set e.Cod_Transp = @Valor
    From ENXES e 
         Inner Join CLIEN c ON c.Cgc_Cpf = e.Num_CgcCpf 
    Where e.Cod_Estabe =  @CodEstabe
    And c.Codigo = @Codigo

  if @Campo = 'Cod_Rota' 
    Update e
      Set e.Cod_Rota = @Valor
    From ENXES e 
         Inner Join CLIEN c ON c.Cgc_Cpf = e.Num_CgcCpf 
    Where e.Cod_Estabe =  @CodEstabe
    And c.Codigo = @Codigo

  if @Campo = 'Cod_RegTri' 
    Update e
      Set e.Cod_RegTri = @Valor
    From ENXES e 
         Inner Join CLIEN c ON c.Cgc_Cpf = e.Num_CgcCpf 
    Where e.Cod_Estabe =  @CodEstabe
    And c.Codigo = @Codigo

Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

