CREATE VIEW dbo.V_VENDE

AS

Select v.Codigo, v.Nome_Guerra, v.Cod_EstabeOpe, v.Vlr_Objetivo, Vlr_Realizado = IsNull(n.Vlr_Realizado,0), 
       v.Cod_Supervisor, Vlr_Comissao = IsNull(n.Vlr_Comissao,0),
     v.Email, CPF_CNPJ = v.Cgc, 
     Situacao = Case When v.Bloqueado = 0 Then 
             'INATIVO'
            Else 
              'ATIVO'
          End
From VENDE v Left Outer Join 
     ( Select x.Cod_Vendedor, 
              Vlr_Realizado = SUM(x.Vlr_Realizado), 
              Vlr_Comissao = SUM(x.Vlr_Comissao)
       From ( Select cb.Cod_Vendedor, cb.Cod_Estabe, cb.Ser_Nota, cb.Num_Nota,  
                     Vlr_Realizado = ROUND(SUM(it.Vlr_LiqItem-it.Vlr_SubsTrib-it.Vlr_SbtRes-it.Vlr_RecSbt-it.Vlr_SubsTribEmb-it.Vlr_DespRateada),2),
                     Vlr_Comissao = ROUND(SUM(it.Vlr_Comissao),2)
              From NFSCB cb Inner Join 
                   NFSIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Ser_Nota = it.Ser_Nota And cb.Num_Nota = it.Num_Nota  
              Where cb.Status = 'F' 
              And cb.Tip_Saida = 'V' 
              And cb.Dat_Emissao >= DATEADD(mm, DATEDIFF(m,0,GETDATE()),0)
              And cb.Dat_Emissao <= DATEADD(s,-1,DATEADD(mm, DATEDIFF(m,0,GETDATE())+1,0))
              Group by cb.Cod_Vendedor, cb.Cod_Estabe, cb.Ser_Nota, cb.Num_Nota ) x
       Group by x.Cod_Vendedor ) n On (v.Codigo = n.Cod_Vendedor)
Where v.Cod_TipVenBas <> 'TLM'
And v.Flg_Export = 1 
GO


SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW dbo.V_CLIEN

AS

Select distinct
       c.Pessoa,
       Cod_Cliente = c.Codigo,
       Fantasia = Case 
                    When c.Fantasia is not Null Then c.Fantasia 
                    Else c.Razao_Social 
                  End,
       c.Cgc_Cpf,
       c.Cgf,
       c.Razao_Social,
       Endereco = Case
                    When (IsNull(c.Numero,'') <> '') and (IsNull(c.Complemento,'') <> '') then
                      Rtrim(Ltrim(c.Endereco))+', '+Rtrim(Ltrim(c.Numero))+', '+Rtrim(Ltrim(c.Complemento))
                    When (IsNull(c.Numero,'') <> '') then
                      Rtrim(Ltrim(c.Endereco))+', '+Rtrim(Ltrim(c.Numero))
                    When (IsNull(c.Complemento,'') <> '') then
                      Rtrim(Ltrim(c.Endereco))+', '+Rtrim(Ltrim(c.Complemento))
                    Else Rtrim(Ltrim(c.Endereco))
                  End,
       c.Numero, 
       c.Complemento, 
       Des_Bairro = IsNull(b.Descricao,''),
       Des_Cidade = IsNull(d.Descricao,''),
       c.Cod_Estado,
       c.Cep,
       c.Cod_DDD_1,
       Telefone = IsNull(c.Fone1,''),
       c.Cod_CliPag,
       Licenca_Saude = IsNull(c.Licenca_Saude,''),    
       Val_LicSau = Case 
                      When Year(c.Val_LicSau) > 1910 Then Convert(VarChar,c.Val_LicSau,103) 
                      Else '' 
                    End,
       Num_AlvFun = IsNull(c.Num_AlvFun,''),
       Val_AlvFun = Case 
                      When Year(c.Val_AlvFun) > 1910 Then Convert(VarChar,c.Val_AlvFun,103) 
                      Else '' 
                    End,
       Num_CRF = IsNull(c.Num_CerReg,''),                    
       Val_NumCRF = Case 
                      When Year(c.Val_CerReg) > 1910 Then Convert(VarChar,c.Val_CerReg,103) 
                      Else '' 
                    End,
       Num_Anvisa = IsNull(c.Num_Anvisa,''),                     
       Val_Anvisa = Case 
                      When Year(c.Val_Anvisa) > 1910 Then Convert(VarChar,c.Val_Anvisa,103) 
                      Else '' 
                    End,                
--       c.Cod_RegTri,

     Id_PolCOm = IsNull(c.Id_PolCom,0),
     Flg_BloqPolCom = IsNull(c.Flg_BlqPrm,0),
       c.Cod_TabPrc,
     Email = Upper(Case When dbo.FN_ValidaEmail(email) = 1 Then Email Else '' End),
       cx.Cod_Vendedor
From CLIEN c 
     Inner Join (Select cl.Codigo, es.Cod_Vendedor
                 From CLIEN cl
                      Inner Join ENXES es on cl.Cgc_Cpf = es.Num_CgcCpf and cl.Codigo = es.Cod_Client
                      Inner Join VENDE ve on es.Cod_Vendedor = ve.Codigo
                 Where ve.Flg_Export = 1
                 Union 
                 Select cl2.Codigo, c2.Cod_Vended
                 From CLXVE c2 
                      Inner Join CLIEN cl2 ON (c2.Cod_Client = cl2.Codigo) 
                      Inner Join VENDE ve2 ON (c2.Cod_Vended = ve2.Codigo) 
                 Where ve2.Flg_Export = 1) cx on c.Codigo = cx.Codigo
     Left Join CIDAD d on ((c.Cod_Estado = d.Cod_Estado) And (c.Cod_Cidade = d.Codigo)) 
     Left Join BAIRR b On ((c.Cod_Estado = b.Cod_Estado) and (c.Cod_Cidade = b.Cod_Cidade) and (b.Codigo = c.Cod_Bairro))
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [dbo].[V_PRODU] AS

Select  Cod_Produto = p.Codigo, 
       Linha = cl.Descricao,
    p.Descricao, 
    Fabricante = p.Cod_Fabricante, 
    Controlado = Case 
                   When (p.Ctrl_Venda = 'C') or (p.Ctrl_Venda = 'E') or (p.Ctrl_Venda = 'P') Then 1 
                   Else 0 
                 End,
    p.Cod_Classif, 
        p.Cod_GrpPrc,
    x.Cod_ClaTri,
    Des_Generica = IsNull(p.Des_NomGen,'') +' '+ IsNull(p.Des_FormaFarmac,'') +' '+ IsNull(Convert(VarChar,p.Qtd_UndVen),'') +' '+ IsNull(p.Des_UndVen,''),
    Des_Comercial = IsNull(p.Des_PrdRef,''), 
    
    Flg_DescGlobal = IsNull(p.Flg_PolComercMax,0), 
    Flg_PrzGlobal = Case
                          When IsNull(p.Flg_PolComercMax,0) = 1 Then IsNull(p.Flg_PrzComercMax,0) 
                          Else 0 
                        End, 
        Cod_Barra = IsNull(p.Cod_EAN,''),
        Caixa_Fechada = IsNull(p.Qtd_Embalagem,0),
    p.Unidade_Venda,
    Preco_Venda = x.Prc_Venda,    
    x.Cod_OriMer, --p.Ctrl_Origem,
    Cod_NCM = p.Cod_ClaFis,
    p.Tip_LisPis,
    p.Sta_AbcValFat,
    p.Sta_AbcUniVen,
    p.Cod_CEST,
        Principio = (Isnull(s1.Descricao, '') + Case 
                                              When Isnull(p.Cod_SubBas, 0) > 0 and Isnull(p.Cod_SubBas2, 0) > 0 Then '+' + Isnull(s2.Descricao, '') 
                          Else Isnull(s2.Descricao, '') 
                        end +
                                                Case 
                          When (Isnull(p.Cod_SubBas, 0) > 0 or Isnull(p.Cod_SubBas2, 0) > 0) and Isnull(p.Cod_SubBas3, 0) > 0 Then '+' + Isnull(s3.Descricao, '') 
                          Else Isnull(s3.Descricao, '') 
                        End),
        Dun14 = Isnull(p.Cod_EanEmbCmp, ''),
    p.Tipo,
    Prc_Fabric12, 
        Prc_MaxCon12, 
    Prc_Fabric17, 
    Prc_MaxCon17, 
    Prc_Fabric175, 
    Prc_MaxCon175, 
    Prc_Fabric18, 
    Prc_MaxCon18,
    Prc_Fabric19, 
    Prc_MaxCon19, 
    Prc_Fabric20,
    Prc_MaxCon20,
    Prc_Fabric21,
    Prc_MaxCon21,
    Prc_Fabric22,
    Prc_MaxCon22,
    Ctrl_Preco
  From  PRODU p
        Inner Join PRXES x On x.Cod_Estabe = (Select Min(Cod_Estabe) as CodEstabe From ESTAB) 
                              And x.Cod_Produt = p.Codigo
        Left Join SBBAS s1 on p.Cod_Subbas = s1.codigo
        Left Join SBBAS s2 on p.Cod_Subbas2 = s2.codigo
        Left Join SBBAS s3 on p.Cod_Subbas3 = s3.codigo
    Left Join CLASS cl ON cl.Codigo = SUBSTRING(p.Cod_Classif, 1, 2)
 Where  p.Flag_ImprClassif1 <> 'N' 

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_RegistraEmailXml]
@PCodEstabe int,
@PSerNot varchar(3),
@PNumNot int

AS

SET NOCOUNT ON

Begin Transaction

Declare @pm_FlgEnviaXml bit,
        @vr_DesEmailTo varchar(200),
        @vr_DesEmailTr varchar(200),
        @vr_DesAssunto varchar(100),
        @vr_DesNomArq  varchar(100),
        @vr_DesTexto   varchar(MAX),
        @vr_CodCli     int,
		@vr_IsnUsu     int

Select @pm_FlgEnviaXml = Case When Val_Param = 'SIM' then
						   Cast(1 as bit)
                         Else 			
                           Cast(0 as bit)
                         End						   
From FS_PARAM
Where Cod_Estabe = @PCodEstabe
And Cod_Param = 'NFE_XML_ATIVO'

if @@ROWCOUNT > 0 and @pm_FlgEnviaXml = 1 
  begin

	Select @vr_DesEmailTo = Case When LTrim(IsNull(a.Email,''))<>'' and LTrim(IsNull(b.Email,''))<>'' and a.Email<>b.Email then lower(a.Email+','+b.Email) 
								 When LTrim(IsNull(a.Email,''))<>'' then lower(LTrim(a.Email))
								 When LTrim(IsNull(b.Email,''))<>'' then lower(LTrim(b.Email))
								 Else ''
							End,
		  @vr_DesNomArq  = n.Chv_Acesso,
		  @vr_CodCli     = a.Codigo,
		  @vr_DesEmailTr = IsNull(t.EMail,'')
	From NFSCB n
	Inner Join CLIEN a On n.Cod_Cliente = a.Codigo
	Left Join CLIEN b On a.Cod_CliPag = b.Codigo
	Left Join TRANS t On n.Cod_Transportadora = t.Codigo
	Where n.Cod_Estabe = @PCodEstabe
    And n.Ser_Nota = @PSerNot
    And n.Num_Nota = @PNumNot	
	
	Select @vr_IsnUsu = ua.Isn 
	From NFSCB nf
	Inner Join USUAR ua On ua.Nome_Login = nf.Usuario 
	Where nf.Cod_Estabe = @PCodEstabe
    And nf.Ser_Nota = @PSerNot
    And nf.Num_Nota = @PNumNot
    
	-- Texto padrao configurado para Assunto e Corpo do email
	Select @vr_DesAssunto = Val_Param 
	From FS_PARAM Where Cod_Estabe = @PCodEstabe And Cod_Param = 'NFE_XML_ASSUNTO'

	Select @vr_DesTexto = Val_Param 
	From FS_PARAM Where Cod_Estabe = @PCodEstabe And Cod_Param = 'NFE_XML_TEXTO'

	-- Substituindo MACROS pelos valores no texto -- ASSUNTO
	Select Top 1 @vr_DesAssunto = Replace(@vr_DesAssunto,'[RAZAO_SOCIAL_EMPRESA]',Des_RazSoc)
	From ESTAB Where Cod_Estabe = @PCodEstabe

	Select Top 1 @vr_DesAssunto = Replace(@vr_DesAssunto,'[CNPJ_EMPRESA]',Num_Cnpj)
	From ESTAB Where Cod_Estabe = @PCodEstabe

	Select Top 1 @vr_DesAssunto = Replace(@vr_DesAssunto,'[CNPJ_CPF_CLIENTE]',Cgc_Cpf)
	From CLIEN Where Codigo = @vr_CodCli

	Select Top 1 @vr_DesAssunto = Replace(@vr_DesAssunto,'[RAZAO_SOCIAL_CLIENTE]',Razao_Social)
	From CLIEN Where Codigo = @vr_CodCli

	Select Top 1 @vr_DesAssunto = Replace(@vr_DesAssunto,'[SERIE_NUMERO_NOTA]',@PSerNot+'/'+Convert(varchar(10),@PNumNot))

	Select Top 1 @vr_DesAssunto = Replace(@vr_DesAssunto,'[CHAVE_NFE]',@vr_DesNomArq)

	-- Substituindo MACROS pelos valores no texto -- CORPO
	Select Top 1 @vr_DesTexto = Replace(@vr_DesTexto,'[RAZAO_SOCIAL_EMPRESA]',Des_RazSoc)
	From ESTAB Where Cod_Estabe = @PCodEstabe

	Select Top 1 @vr_DesTexto = Replace(@vr_DesTexto,'[CNPJ_EMPRESA]',Num_Cnpj)
	From ESTAB Where Cod_Estabe = @PCodEstabe

	Select Top 1 @vr_DesTexto = Replace(@vr_DesTexto,'[CNPJ_CPF_CLIENTE]',Cgc_Cpf)
	From CLIEN Where Codigo = @vr_CodCli

	Select Top 1 @vr_DesTexto = Replace(@vr_DesTexto,'[RAZAO_SOCIAL_CLIENTE]',Razao_Social)
	From CLIEN Where Codigo = @vr_CodCli

	Select Top 1 @vr_DesTexto = Replace(@vr_DesTexto,'[SERIE_NUMERO_NOTA]',@PSerNot+'/'+Convert(varchar(10),@PNumNot))

	Select Top 1 @vr_DesTexto = Replace(@vr_DesTexto,'[CHAVE_NFE]',@vr_DesNomArq)

	-----------------
	-- Caso não haja texto configurado

	if IsNull(@vr_DesAssunto,'')=''
	  Set @vr_DesAssunto = 'Envio XML NFe '+@PSerNot+'/'+Convert(varchar(10),@PNumNot)

	if IsNull(@vr_DesTexto,'')=''
	  Set @vr_DesTexto = 'XML NFe '+@PSerNot+'/'+Convert(varchar(10),@PNumNot)+' anexada - Chave Nfe ['+@vr_DesNomArq+']'

	Set @vr_DesNomArq = 'NFe'+@vr_DesNomArq+'.xml'

	While (CharIndex(',,',@vr_DesEmailTo) <> 0) or (CharIndex(' ',@vr_DesEmailTo) <> 0)
	  begin
		  Set @vr_DesEmailTo = Replace(@vr_DesEmailTo,' ','')
		  Set @vr_DesEmailTo = Replace(@vr_DesEmailTo,',,','')
	  end
	
	if IsNull(@vr_DesEmailTo,'') <> ''
		Insert Into FS_EMAIL(Cod_Estabe, Ser_Nota, Num_Nota, Tip_NF, 
							 Des_EmailTo, Des_Assunto, Des_Texto, Des_NomArq,
							 AnexoB64, Isn_Usuario )
		Select x.Cod_Estabe,
			   x.Ser_Nota,
			   x.Num_Nota,
			   'X' as Tipo,
			   Substring(e.Item,1,200) as Email,
			   @vr_DesAssunto as Assunto,
			   @vr_DesTexto   as Texto,
			   @vr_DesNomArq  as Nome,
			   dbo.FN_StrToBase64(x.Xml_Nfeproc) as Anexo, 
			   @vr_IsnUsu as IdUsuario 
		From FS_NFXML x
		Cross Join FN_Split(@vr_DesEmailTo,',') e
		Where Cod_Estabe = @PCodEstabe
		And Ser_Nota = @PSerNot
		And Num_Nota = @PNumNot	
		And Xml_Nfe is not null

	--Transportador separado devido ao tipo de remetente
	if IsNull(@vr_DesEmailTr,'') <> ''
		Insert Into FS_EMAIL(Cod_Estabe, Ser_Nota, Num_Nota, Tip_NF, 
							 Des_EmailTo, Des_Assunto, Des_Texto, Des_NomArq,
							 AnexoB64, Isn_Usuario, Tip_Rem )
		Select x.Cod_Estabe,
			   x.Ser_Nota,
			   x.Num_Nota,
			   'X' as Tipo,
			   @vr_DesEmailTr,
			   @vr_DesAssunto as Assunto,
			   @vr_DesTexto   as Texto,
			   @vr_DesNomArq  as Nome,
			   dbo.FN_StrToBase64(x.Xml_Nfeproc) as Anexo, 
			   @vr_IsnUsu as IdUsuario,
			   'TR' as Tip_Rem
		From FS_NFXML x
		Where Cod_Estabe = @PCodEstabe
		And Ser_Nota = @PSerNot
		And Num_Nota = @PNumNot	
		And Xml_Nfe is not null
  end

Commit Transaction
GO

